/****** Object:  UserDefinedFunction [Alls].[f_AppendWithParentheses]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create FUNCTION [Alls].[f_AppendWithParentheses]
(
    @v NVARCHAR(MAX),
    @NewValue NVARCHAR(MAX)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN

    SET @NewValue = RTRIM(LTRIM(@NewValue));

    IF @NewValue = ''
    BEGIN

        RETURN @v;

    END;
	
    RETURN @v + ' (' + @NewValue + ')';

END;




