CREATE FUNCTION [Alls].[f_GetAnyPaperRef] ( @ID UNIQUEIDENTIFIER )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @LinkType INT ,
    @RefF NVARCHAR(MAX) = '';

  SELECT TOP ( 1 ) @LinkType = s.LinkType
    FROM Transactions.t_Transaction AS s
    WHERE s.ID = @ID;

  IF @LinkType = 0
  BEGIN
	  
    RETURN Invoices.f_PurchasingGetPaperRef(@ID);

  END;

  IF @LinkType = 1
  BEGIN
	  
    RETURN Invoices.f_PurchasingReturnGetPaperRef(@ID);

  END;

  IF @LinkType = 2
  BEGIN

    RETURN Invoices.f_SoldGetPaperRef(@ID);

  END;

  IF @LinkType = 3
  BEGIN
		
    RETURN Invoices.f_SoldReturnGetPaperRef(@ID);

  END;
  
  IF @LinkType = 8
  BEGIN
		
    RETURN Company.f_ExpenseGetPaperRef(@ID);

  END;
  
  --IF @LinkType = 9
  --BEGIN
		
  --  RETURN Company.f_OpenBoxGetRefF(@ID);

  --END;
  
  --IF @LinkType = 11
  --BEGIN
		
  --  RETURN Company.f_PaySalaryGetRefF(@ID);

  --END;
  
  --IF @LinkType = 18
  --BEGIN
	
  --  RETURN Invoices.f_InternetSubscriptionGetRefF(@ID);

  --END;
  
  --IF @LinkType = 81
  --BEGIN
		
  --  RETURN Company.f_ChequeGetRefF(@ID);

  --END;
  
  --IF @LinkType = 112
  --BEGIN
		
  --  RETURN Company.f_BondGetRefF(@ID);

  --END;
  
  --IF @LinkType = 160
  --BEGIN
		
  --  RETURN Company.f_CloseBoxGetRefF(@ID);

  --END;
  
  IF @LinkType = 162
  BEGIN
						
    RETURN Invoices.f_DeliveryServiceGetPaperRef(@ID);

  END;
  
  IF @LinkType = 169
  BEGIN
	
    RETURN Customers.f_FrameJobOrderGetPaperRef(@ID);

  END;
  
  IF @LinkType = 174
  BEGIN
				
    RETURN Gym.f_GymSubscriptionGetPaperRef(@ID);			

  END;
  
  --IF @LinkType = 182
  --BEGIN
		
  --  RETURN Cars.f_CarExpenseGetRefF(@ID);

  --END;
  
  IF @LinkType = 185
  BEGIN
                      
    RETURN Cars.f_CarRentalGetPaperRef(@ID);

  END;

  RETURN COALESCE(@RefF, '');

END;








