/****** Object:  UserDefinedFunction [Alls].[f_GetDayTextBaseOnNumberAR]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Alls].[f_GetDayTextBaseOnNumberAR] ( @Days INT )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @DaysF NVARCHAR(MAX) = FORMAT(@Days, N'0') ,
    @Text NVARCHAR(MAX) = N'';

  SET @Text = CASE WHEN @Days = 1 THEN N'يوم'
                   WHEN @Days = 2 THEN N'يومين'
                   WHEN @Days <= 9 THEN @DaysF + N' أيام'
                   WHEN @Days >= 10 THEN @DaysF + N' يوماً'
                   ELSE @DaysF
              END;

  RETURN @Text;

END;




GO
/****** Object:  UserDefinedFunction [Alls].[f_GetDayTextBaseOnNumberEN]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Alls].[f_GetDayTextBaseOnNumberEN] ( @Days INT )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @Text NVARCHAR(MAX) = N'';

  SET @Text = CASE @Days
                WHEN 1 THEN N'1 Day'
                ELSE FORMAT(@Days, N'0') + N' Days'
              END;

  RETURN @Text;

END;



