  DECLARE @v FLOAT = 0;

  SELECT TOP ( 1 ) @v = Item
    FROM Alls.SplitToNumberTable(@text, '%[0-9.-]%')
    WHERE Matched = 1
    ORDER BY ItemNumber;    

  SET @v = ISNULL(@v, 0);

  RETURN @v;
   
END;




