/****** Object:  UserDefinedFunction [Alls].[f_GetValueContentPart]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Alls].[f_GetValueContentPart]
  (
    @Text NVARCHAR(MAX) ,
    @Part NVARCHAR(MAX) ,
    @SplitBy NVARCHAR(MAX)
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN
  
  DECLARE @v NVARCHAR(MAX) = '';
  
  WITH  o AS ( SELECT Split.a.value('.', 'VARCHAR(8000)') AS 'split_values'
                FROM ( SELECT CAST('<M>' + REPLACE(@Text, @SplitBy, '</M><M>') + '</M>' AS XML) AS xml_data
                     ) AS temp
                CROSS APPLY xml_data.nodes('/M') AS Split ( a )
             )
    SELECT TOP ( 1 ) @v = o.split_values
      FROM o
      WHERE o.split_values LIKE N'%' + @Part + N'%'
      ORDER BY o.split_values;

  RETURN ISNULL(@v, N'');

END;





