/****** Object:  UserDefinedFunction [Alls].[f_NotificationGetNewDateByPeriod]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Alls].[f_NotificationGetNewDateByPeriod]
  (
    @FromDate DATE ,
    @PeriodType TINYINT ,
    @PeriodNumber INT 
  )
RETURNS DATE
AS
BEGIN

  DECLARE @NewDate DATE = @FromDate;

  SET @NewDate = CASE @PeriodType
                   WHEN 0 THEN DATEADD(DAY, @PeriodNumber, @FromDate)
                   WHEN 1 THEN DATEADD(WEEK, @PeriodNumber, @FromDate)
                   WHEN 2 THEN DATEADD(MONTH, @PeriodNumber, @FromDate)
                   ELSE DATEADD(YEAR, @PeriodNumber, @FromDate)
                 END;

  RETURN ISNULL(@NewDate,@FromDate);

END;



