/****** Object:  UserDefinedFunction [Alls].[f_NotificationIsActive]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Alls].[f_NotificationIsActive]
(
    @StopNotification BIT,
    @ExpirationDate DATE
)
RETURNS BIT
AS
BEGIN

    RETURN CASE
               WHEN @StopNotification = 1 THEN
                   0
               ELSE
                   CASE
                       WHEN @ExpirationDate < CONVERT(DATE, GETDATE()) THEN
                           0
                       ELSE
                           1
                   END
           END;

END;







