CREATE FUNCTION [Cars].[f_CarGenerateFullName]
  (
    @Make NVARCHAR(MAX) ,
    @Model NVARCHAR(MAX) ,
    @YearIs DATE ,
    @Color NVARCHAR(MAX) ,
    @RegistrationNumber NVARCHAR(MAX)
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  RETURN  CONCAT(@Make ,N', ', @Model , N', ' , YEAR(@YearIs) , IIF(@Color = '', '', ', ' + @Color) , N', ' , @RegistrationNumber);

END;








