/****** Object:  UserDefinedFunction [Cars].[f_CarGetAvailabilityIsNow]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Cars].[f_CarGetAvailabilityIsNow] ( @ID UNIQUEIDENTIFIER )
RETURNS BIT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @CountIs INT = 0;

  END;

  BEGIN --Set

    SELECT  @CountIs = COUNT(*)
    FROM    Cars.t_CarRental AS t
    WHERE   t.CarID = @ID
            AND ( ( t.StatusIs = 0
                    AND t.FromDate >= CONVERT(DATE, GETDATE())
                  )
                  OR t.StatusIs = 1
                );

  END;

  RETURN IIF(@CountIs = 0, 0, 1);

END;

