CREATE FUNCTION [Cars].[f_CarRentalGetPaperRef] ( @ID UNIQUEIDENTIFIER )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @PaperRef NVARCHAR(MAX) = '';
 
  SELECT @PaperRef = t.PaperRef
    FROM Cars.t_CarRental AS t
    WHERE t.ID = @ID;

  IF @PaperRef = ''
  BEGIN
                              
    SELECT @PaperRef = t.PaperRef
      FROM Cars.t_CarRentalHistory AS t
      WHERE t.ID = @ID;     	    

  END;
		
  RETURN @PaperRef;

END;




