/****** Object:  UserDefinedFunction [Company].[f_AccountGetLastDateTheBalanceWasZero]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Company].[f_AccountGetLastDateTheBalanceWasZero] ( @ID UNIQUEIDENTIFIER )
RETURNS DATE
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @DateOnly DATE;

  END;

  BEGIN --Set

    SELECT TOP ( 1 ) @DateOnly = o.DateOnly
      FROM ( SELECT TOP 100 PERCENT t.DateOnly ,
                SUM(t.Balance) OVER ( PARTITION BY t.Account ORDER BY t.DateOnly, t.ID ) AS Balance
              FROM Transactions.t_TransactionDetail AS t
              WHERE t.AccountID = @ID
              ORDER BY t.DateOnly DESC
           ) AS o
      WHERE o.Balance = 0
      ORDER BY o.DateOnly DESC;

  END;

  RETURN COALESCE(DATEADD(DAY,1, @DateOnly), GETDATE());

END;







