SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Company].[f_AccountGetOtherIncomeBetweenDateTime]
  (
    @AccountID UNIQUEIDENTIFIER ,
    @CurrencyTypeIs INT ,
    @FromDate DATETIME ,
    @ToDate DATETIME
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v FLOAT = 0;

  END;

  BEGIN --Set

    SELECT @v = CASE @CurrencyTypeIs
                  WHEN 0 THEN SUM(t.BalanceD)
                  WHEN 1 THEN SUM(t.BalanceLL)
                  ELSE SUM(t.BalanceEuro)
                END
      FROM Transactions.t_TransactionDetail AS t
      INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
      WHERE t.AccountID = @AccountID AND t.DateIs BETWEEN @FromDate AND @ToDate AND t.Balance > 0 AND CASE WHEN t1.LinkType = 2 AND t1.LinkTypeSub <> 0 THEN 1
                                                                                                           WHEN t1.LinkType <> 2 THEN 1
                                                                                                           ELSE 0
                                                                                                      END = 1;

  END;

  RETURN ISNULL(@v, 0);

END;





