/****** Object:  UserDefinedFunction [Company].[f_CallsGetNewRef]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Company].[f_CallsGetNewRef] ( )
RETURNS BIGINT
AS
BEGIN

  DECLARE @Ref BIGINT = 0;
 
  SELECT @Ref = MAX(t.Ref)
    FROM ( SELECT MAX(s.Ref) AS Ref
            FROM Company.t_Calls AS s
           UNION ALL
           SELECT MAX(s.Ref) AS Ref
            FROM Company.t_CallsArchive AS s
         ) AS t;
		
  RETURN ISNULL( @Ref ,0) + 1;

END;




GO
/****** Object:  UserDefinedFunction [Company].[f_CallsGetTodayCount]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Company].[f_CallsGetTodayCount] ( )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT;
 
  SELECT TOP ( 1 ) @c = COUNT_BIG(t.ID)
    FROM Company.t_Calls AS t
    WHERE t.DateTimeIs >= DateTimes.f_GetToday() AND DateTimes.f_GetToday() <= t.DateTimeIs;
		
  RETURN ISNULL( @c , 0);

END;




