CREATE FUNCTION [Company].[f_DailyBoxAllGetRefF] ( @ID UNIQUEIDENTIFIER )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @RefF NVARCHAR(MAX) = '';
 
  SELECT @RefF = t.RefF
    FROM Company.t_DailyBox AS t
    WHERE t.ID = @ID;

  IF @RefF = ''
  BEGIN
                              
    SELECT @RefF = t.RefF
      FROM Company.t_ArchiveDailyBox AS t
      WHERE t.ID = @ID;     	    

  END;
		
  RETURN @RefF;

END;




