/****** Object:  UserDefinedFunction [Company].[f_MailSendingSchedulesGetMailRecipientsNamesLIVE]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Company].[f_MailSendingSchedulesGetMailRecipientsNamesLIVE]
  (
    @ID UNIQUEIDENTIFIER
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v NVARCHAR(MAX);

  END;

  BEGIN --Set

    SET @v = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                              FROM Company.t_MailSendingSchedulesRecipients AS t
                              LEFT JOIN Company.t_MailRecipients AS t1 ON t1.ID = t.MailRecipientsID
                              WHERE t.MailSendingSchedulesID = @ID
                           FOR
                             XML PATH('')
                           ));

  END;

  RETURN COALESCE(@v, N'');

END;

















GO
