/****** Object:  UserDefinedFunction [Company].[f_SubAccountsGetBalanceDX]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Company].[f_SubAccountsGetBalanceDX]
  (
    @MainAccountID UNIQUEIDENTIFIER
  )
RETURNS FLOAT
AS
BEGIN

  DECLARE @b FLOAT = 0;
 
  SELECT @b = SUM(t1.BalanceD)
    FROM Company.t_SubAccounts AS t
    INNER JOIN Company.t_Account AS t1 ON t1.ID = t.SubAccountID
    WHERE t.MainAccountID = @MainAccountID;

  RETURN COALESCE(@b , 0);

END;







