/****** Object:  UserDefinedFunction [Company].[f_SubAccountsGetBalanceX]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Company].[f_SubAccountsGetBalanceX]
  (
    @MainAccountID UNIQUEIDENTIFIER
  )
RETURNS FLOAT
AS
BEGIN

  DECLARE @b FLOAT = 0;
 
  SELECT @b = SUM(CASE t2.CurrencyTypeIs
                    WHEN 0 THEN t1.BalanceD
                    WHEN 1 THEN t1.BalanceLL
                    WHEN 2 THEN t1.BalanceEuro
                    ELSE 0
                  END)
    FROM Company.t_SubAccounts AS t
    INNER JOIN Company.t_Account AS t1 ON t1.ID = t.SubAccountID
    INNER JOIN Company.t_Account AS t2 ON t2.ID = t.MainAccountID
    WHERE t.MainAccountID = @MainAccountID;

  RETURN COALESCE(@b , 0);

END;







