/****** Object:  UserDefinedFunction [Currencys].[f_ChooseValue]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Currencys].[f_ChooseValue]
  (
    @ID UNIQUEIDENTIFIER ,
    @ValueD FLOAT ,
    @ValueLL FLOAT ,
    @ValueEuro FLOAT
  )
RETURNS FLOAT
AS
BEGIN
  BEGIN --DECLARE

    DECLARE @Value FLOAT = 0;

  END;

  BEGIN --Set

    SELECT TOP ( 1 ) @Value = CASE t.TypeIs
                                WHEN 0 THEN @ValueD
                                WHEN 1 THEN @ValueLL
                                ELSE @ValueEuro
                              END
      FROM Currencys.t_Currency AS t
      WHERE t.ID = @ID;

  END;

  RETURN ISNULL( @Value,0);

END;



GO
/****** Object:  UserDefinedFunction [Currencys].[f_CurrencyExchangeTo]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Currencys].[f_CurrencyExchangeTo]
  (
    @FromCurrencyID UNIQUEIDENTIFIER ,
    @ToCurrencyID UNIQUEIDENTIFIER ,
    @Value FLOAT
  )
RETURNS FLOAT
AS
BEGIN

  IF @FromCurrencyID = @ToCurrencyID
  BEGIN
                                       
    RETURN @Value;

  END;

  RETURN @Value / 
		Currencys.f_CurrencyGetExchangeRate(@FromCurrencyID) * 
		Currencys.f_CurrencyGetExchangeRate(@ToCurrencyID);

END;




GO
