/****** Object:  UserDefinedFunction [Currencys].[f_CurrencyRounding]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Currencys].[f_CurrencyRounding]
  (
    @Price DECIMAL ,
    @Start1 FLOAT ,
    @Start2 FLOAT ,
    @Unit1 DECIMAL ,
    @Unit2 DECIMAL ,
    @Unit3 DECIMAL ,
    @After1 FLOAT ,
    @After2 FLOAT ,
    @After3 FLOAT

  )
RETURNS FLOAT
AS
BEGIN
                                   
  RETURN CASE 
  WHEN @Price <= @Start1 THEN Currencys.f_CurrencyRoundingPart(@Price, @Unit1, @After1)
  WHEN @Price <= @Start2 THEN Currencys.f_CurrencyRoundingPart(@Price, @Unit2, @After2)
                 ELSE Currencys.f_CurrencyRoundingPart(@Price, @Unit3, @After3)END;

END;


GO
/****** Object:  UserDefinedFunction [Currencys].[f_CurrencyRoundingPart]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Currencys].[f_CurrencyRoundingPart]
  (
    @Price DECIMAL ,
    @Unit DECIMAL ,
    @After FLOAT 

  )
RETURNS FLOAT
AS
BEGIN
             
  IF @Unit <= 0
  BEGIN
			                   
    SET @Unit = 1;

  END; 
						                        
  RETURN IIF(@Price % @Unit >= @After, CEILING(@Price / @Unit) * @Unit, @Price - @Price % @Unit);

END;



