        DECLARE @ID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set

        SELECT TOP ( 1 )
                @ID = ID
        FROM    Customers.t_AgeRange AS t
        ORDER BY t.DateCreate;

    END;
	
    RETURN ISNULL(@ID, '00000000-0000-0000-0000-000000000000');

END;




