/****** Object:  UserDefinedFunction [Customers].[f_Customer_GetCount_NewBirthday]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Customers].[f_Customer_GetCount_NewBirthday] ( )
RETURNS INT
AS
BEGIN

  DECLARE @C INT = 0;

  SELECT @C = COUNT(t.ID)
    FROM Customers.t_Customer AS t
    INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
    WHERE t.StatusIs <> 2 AND t2.CustomerShowNotificationNewBirthday = 1 AND t.ShowNotificationNewBirthday = 1 AND t.DaysCloseToBirthday BETWEEN t2.CustomerDaysBeforeBirthday
                                                                                                                                         AND     t2.CustomerDaysAfterBirthday;

  RETURN ISNULL(@C , 0);

END;




