CREATE FUNCTION [Customers].[f_CustomersGetCountGymActiveSubscription] ( )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT = 0;
 
  SELECT @c = COUNT_BIG(DISTINCT t.AccountID)
    FROM Gym.t_GymSubscription AS t
    INNER JOIN Gym.t_SubscriptionType AS t1 ON t1.ID = t.SubscriptionTypeID
    WHERE t.IsActive = 1 AND t1.TypeIs <> 0;

  RETURN @c;

END;


