GO

CREATE FUNCTION [Customers].[f_CustomersGetCountGymUnsubscribed] ( @ActiveTo DATE )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT = 0;
 
  SELECT @c = COUNT_BIG(t.ID)
    FROM Customers.t_Customer AS t
    INNER  JOIN Company.t_Account AS t1 ON t1.LinkWithID = t.ID AND t1.IsMasterLink = 1 AND t1.SectionID = 15
    WHERE  t1.GymSubscriptionIsActive = 0 AND t1.GymSubscriptionC > 0 AND t1.GymSubscriptionLastType <> 0 AND t1.GymSubscriptionActiveTo >= @ActiveTo;

  RETURN @c;

END;







