/****** Object:  UserDefinedFunction [Customers].[f_CustomersGetCountSubscriptionsWillWxpireSoon]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Customers].[f_CustomersGetCountSubscriptionsWillWxpireSoon] ( @NextDays INT )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT = 0;
 
  SELECT @c = COUNT(*)
    FROM Gym.t_GymSubscription AS t
    WHERE t.DateIs <> t.ToDate AND t.IsActive = 1 AND ISNULL(DATEDIFF(DAY, DateTimes.f_GetToday(), t.ToDate), -1) BETWEEN 0 AND @NextDays;
 
  RETURN @c;

END;





