/****** Object:  UserDefinedFunction [Customers].[f_FrameJobOrderGetCountByCustomerID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Customers].[f_FrameJobOrderGetCountByCustomerID] ( @ID UNIQUEIDENTIFIER )
RETURNS BIGINT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @C BIGINT;

  END;

  BEGIN --Set

    SET @C = ( SELECT COUNT(t.ID)
                FROM Customers.t_FrameJobOrder AS t
                WHERE t.CustomerID = @ID AND t.StatusIs <> 4
             ) + ( SELECT COUNT(t.ID)
                    FROM Customers.t_FrameJobOrderHistory AS t
                    WHERE t.CustomerID = @ID AND t.StatusIs <> 4
                 );

  END;

  RETURN COALESCE(@C, 0);

END;



GO
/****** Object:  UserDefinedFunction [Customers].[f_FrameJobOrderGetLastDateByCustomerID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Customers].[f_FrameJobOrderGetLastDateByCustomerID] ( @ID UNIQUEIDENTIFIER )
RETURNS DATE
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @D DATE;

  END;

  BEGIN --Set

    SET @D = ( SELECT TOP ( 1 ) o.DateIs
                FROM ( SELECT t.DateIs
                        FROM Customers.t_FrameJobOrder AS t
                        WHERE t.CustomerID = @ID AND t.StatusIs <> 4
                       UNION ALL
                       SELECT t.DateIs
                        FROM Customers.t_FrameJobOrderHistory AS t
                        WHERE t.CustomerID = @ID AND t.StatusIs <> 4
                     ) AS o
                ORDER BY o.DateIs DESC
             );

  END;

  RETURN COALESCE(@D, DATEFROMPARTS(2000, 1, 1));

END;







