/****** Object:  UserDefinedFunction [dbo].[f_ToJSON]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [dbo].[f_ToJSON]
  (
    @IncludeHead INT ,
    @ToLowerCase INT ,
    @XML XML
  )
RETURNS VARCHAR(MAX)
AS
BEGIN
  DECLARE @Head VARCHAR(MAX) = '' ,
    @JSON VARCHAR(MAX) = '';
    WITH  cteEAV
            AS ( SELECT RowNr = ROW_NUMBER() OVER ( ORDER BY ( SELECT NULL
                                                             ) ) ,
                    Entity = xRow.value('@*[1]', 'varchar(100)') ,
                    Attribute = xAtt.value('local-name(.)', 'varchar(100)') ,
                    Value = xAtt.value('.', 'varchar(max)')
                  FROM @XML.nodes('/row') AS R ( xRow )
                  CROSS APPLY R.xRow.nodes('./@*') AS A ( xAtt )
               ),
          cteSum
            AS ( SELECT Records = COUNT(DISTINCT Entity) ,
                    Head = IIF(@IncludeHead = 0, IIF(COUNT(DISTINCT Entity) <= 1, '[getResults]', '[[getResults]]'), CONCAT('{"status":{"successful":"true","timestamp":"', FORMAT(GETUTCDATE(), 'yyyy-MM-dd hh:mm:ss '), 'GMT', '","rows":"', COUNT(DISTINCT Entity), '"},"results":[[getResults]]}'))
                  FROM cteEAV
               ),
          cteBld
            AS ( SELECT * ,
                    NewRow = IIF(LAG(Entity, 1) OVER ( PARTITION BY Entity ORDER BY ( SELECT NULL
                                                                                    ) ) = Entity, '', ',{') ,
                    EndRow = IIF(LEAD(Entity, 1) OVER ( PARTITION BY Entity ORDER BY ( SELECT NULL
                                                                                     ) ) = Entity, ',', '}') ,
                    JSON = CONCAT('"', IIF(@ToLowerCase = 1, LOWER(Attribute), Attribute), '":', '"', Value, '"')
                  FROM cteEAV
               )
    SELECT @JSON = @JSON + NewRow + JSON + EndRow ,
        @Head = Head
      FROM cteBld ,
        cteSum;
  RETURN REPLACE(@Head,'[getResults]',STUFF(@JSON,1,1,''));
END;

