/****** Object:  UserDefinedFunction [Employees].[f_BonusGetTotalByEmployee]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Employees].[f_BonusGetTotalByEmployee]
  (
    @EmployeeID UNIQUEIDENTIFIER ,
    @FromDate DATE ,
    @ToDate DATE
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @TotalIs FLOAT;

  END;

  BEGIN --Set

    SELECT @TotalIs = SUM(CASE t2.TypeIs
                            WHEN 0 THEN t.ValueIsD
                            WHEN 1 THEN t.ValueIsLL
                            ELSE t.ValueIsEuro
                          END)
      FROM Employees.t_Bonus AS t
      LEFT JOIN Employees.t_Employee AS t1 ON t1.ID = t.EmployeeID
      LEFT JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.FirstSalaryCurrencyID
      WHERE t.EmployeeID = @EmployeeID AND t.ImplementationIn BETWEEN @FromDate AND @ToDate;

  END;

  RETURN COALESCE(@TotalIs, 0);

END;



