CREATE FUNCTION [Employees].[f_EmployeeGetInWorkNow] ( @ID UNIQUEIDENTIFIER )
RETURNS BIT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @InWorkNow BIT = 0;

  END;

  BEGIN --Set info

    SELECT TOP ( 1 ) @InWorkNow = IIF(t.CheckoutTime IS NULL, 1, 0)
      FROM Employees.t_Shift AS t
      WHERE t.EmployeeID = @ID
