/****** Object:  UserDefinedFunction [Employees].[f_EmployeeGetTotalAttendancesHoursLastMonth]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Employees].[f_EmployeeGetTotalAttendancesHoursLastMonth] ( @ID UNIQUEIDENTIFIER )
RETURNS BIGINT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v1 FLOAT = 0 ,
      @v2 FLOAT = 0 ,
      @DateIs DATE = DATEADD(MONTH, -1, DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1));

  END;

  BEGIN --Set

    SELECT @v1 = SUM(t.FinalWorkHours)
      FROM Employees.t_Shift AS t
      WHERE t.EmployeeID = @ID AND DATEFROMPARTS(YEAR(t.CheckInTime), MONTH(t.CheckInTime), 1) = @DateIs AND t.StatusIs <> 2;
  
    SELECT @v2 = SUM(t.FinalWorkHours)
      FROM Employees.t_ShiftHistory AS t
      WHERE t.EmployeeID = @ID AND DATEFROMPARTS(YEAR(t.CheckInTime), MONTH(t.CheckInTime), 1) = @DateIs AND t.StatusIs <> 2;

  END;

  RETURN ISNULL(@v1,0) + ISNULL(@v2,0);

END;





