      FROM Employees.t_Shift AS t
      WHERE t.EmployeeID = @ID AND DATEFROMPARTS(YEAR(t.CheckInTime), MONTH(t.CheckInTime), 1) = @DateIs AND t.StatusIs <> 2;
   
    SELECT @v2 = SUM(t.FinalWorkHours)
      FROM Employees.t_ShiftHistory AS t
      WHERE t.EmployeeID = @ID AND DATEFROMPARTS(YEAR(t.CheckInTime), MONTH(t.CheckInTime), 1) = @DateIs AND t.StatusIs <> 2;

  END;

  RETURN ISNULL(@v1,0) + ISNULL(@v2,0);

