CREATE FUNCTION [Employees].[f_EmployeeGetTotalUnpaidInvoicesProfit]
  (
    @EmployeeID UNIQUEIDENTIFIER ,
    @CurrencyType INT ,
    @FromDate DATE ,
    @ToDate DATE
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v FLOAT = 0;

  END;

  BEGIN --Set

    SELECT @v = SUM(CASE @CurrencyType
                      WHEN 0 THEN t.ProfitD
                      WHEN 1 THEN t.ProfitLL
                      ELSE t.ProfitEuro
                    END)
      FROM Invoices.t_SoldDetailEmployeeProfit AS t
      INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
      WHERE t.EmployeeID = @EmployeeID AND t.Paid = 0 AND t1.DateOnly BETWEEN @FromDate AND @ToDate;

  END;

  RETURN COALESCE(@v, 0);

END;




