/****** Object:  UserDefinedFunction [Employees].[f_ShiftGetNewRef]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Employees].[f_ShiftGetNewRef] ( )
RETURNS BIGINT
AS
BEGIN

  DECLARE @Count BIGINT = 0 ,
    @Ref BIGINT = 0;

  SELECT @Count = COUNT_BIG(s.Ref)
    FROM Employees.t_Shift AS s;
    
  SELECT @Count += COUNT_BIG(s.Ref)
    FROM Employees.t_ShiftHistory AS s;

  IF @Count = 0
  BEGIN
                  
    RETURN 1;

  END;

  SELECT @Ref = COALESCE(MAX(o.Ref), 1)
    FROM ( SELECT MAX(s.Ref) AS Ref
            FROM Employees.t_Shift AS s
           UNION ALL
           SELECT MAX(s.Ref) AS Ref
            FROM Employees.t_ShiftHistory AS s
         ) AS o;

  RETURN @Ref + 1;

END;




