/****** Object:  UserDefinedFunction [Employees].[f_VacationGetDaysTransferAllowanceDiscount]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Employees].[f_VacationGetDaysTransferAllowanceDiscount]
  (
    @EmployeeID UNIQUEIDENTIFIER ,
    @FromDate DATE ,
    @ToDate DATE
  )
RETURNS INT
AS
BEGIN

  DECLARE @v INT = 0;
 
  SELECT @v = SUM(s.DaysIs)
    FROM Employees.t_Vacation AS s
    WHERE s.EmployeeID = @EmployeeID AND s.DateIs >= @FromDate AND s.DateIs <= @ToDate AND s.TransferAllowanceDiscount = 1 AND s.OperationType <> 0;

  RETURN ISNULL(@v , 0);

END;






