/****** Object:  UserDefinedFunction [Gym].[f_GymClassGetDaysNamesAR]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Gym].[f_GymClassGetDaysNamesAR]
  (
    @Day0 BIT ,
    @Day1 BIT ,
    @Day2 BIT ,
    @Day3 BIT ,
    @Day4 BIT ,
    @Day5 BIT ,
    @Day6 BIT
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @t AS TABLE
    (
      DayIsActive BIT ,
      SortIndex INT ,
      Name NVARCHAR(MAX)
    );
    
  INSERT @t
      ( DayIsActive, SortIndex, Name )
    VALUES  ( @Day0, 7, N'الاحد' ),
            ( @Day1, 1, N'الاثنين' ),
            ( @Day2, 2, N'الثلاثاء' ),
            ( @Day3, 3, N'الاربعاء' ),
            ( @Day4, 4, N'الخميس' ),
            ( @Day5, 5, N'الجمعة' ),
            ( @Day6, 6, N'السبت' );

  RETURN Alls.f_FixXML(( SELECT ', ' + t.Name AS [text()]
                                              FROM @t AS t
											  WHERE t.DayIsActive = 1
											  ORDER BY t.SortIndex
                                           FOR
                                             XML PATH('')
                                           ));

END;




