/****** Object:  UserDefinedFunction [Gym].[f_GymMemberAttendanceEnteredBefore]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Gym].[f_GymMemberAttendanceEnteredBefore]
  (
    @AccountID UNIQUEIDENTIFIER ,
    @Hours FLOAT
  )
RETURNS BIT
AS
BEGIN

  IF @Hours <= 0
  BEGIN
                   
    RETURN 0;

  END;

  BEGIN
    
    DECLARE @NowDate DATETIME = GETDATE();
    DECLARE @StartDate DATETIME = DATEADD(SECOND, 0 - ( @Hours * 60 * 60 ), @NowDate);

  END;

  IF EXISTS ( SELECT TOP ( 1 ) s.ID
                FROM Gym.t_GymMemberAttendance AS s
                WHERE s.AccountID = @AccountID AND s.DateIs BETWEEN @StartDate AND @NowDate )
  BEGIN
				    
    RETURN 1;

  END;

  RETURN 0; 

END;


GO
