/****** Object:  UserDefinedFunction [Gym].[f_GymSubscription_Check_IsActive]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Gym].[f_GymSubscription_Check_IsActive]
  (
    @ToDate DATE ,
    @RemainingDays INT ,
    @ActiveUntilUseDays BIT
  )
RETURNS DATE
AS
BEGIN

  DECLARE @d DATE = @ToDate;

  IF @ActiveUntilUseDays = 0
  BEGIN

    RETURN @ToDate;

  END;
  ELSE
  BEGIN

    SET @d = IIF(@RemainingDays > 0, GETDATE() + 1, @ToDate);

  END;

  RETURN @d;

END;




