/****** Object:  UserDefinedFunction [Gym].[f_GymSubscriptionGetActiveToByAccountID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Gym].[f_GymSubscriptionGetActiveToByAccountID] ( @ID UNIQUEIDENTIFIER )
RETURNS DATE
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @D DATE;

  END;

  BEGIN --Set

    SELECT TOP ( 1 ) @D = t.ToDate
      FROM Gym.t_GymSubscription AS t
      WHERE t.AccountID = @ID
      ORDER BY t.ToDate DESC;

    IF @D IS NULL
    BEGIN

      SELECT TOP ( 1 ) @D = t.ToDate
        FROM Gym.t_GymSubscriptionHistory AS t
        WHERE t.AccountID = @ID
        ORDER BY t.ToDate DESC;

    END;

  END;

  RETURN COALESCE(@D, DATEFROMPARTS(2000, 1, 1));

END;




