/****** Object:  UserDefinedFunction [Gym].[f_GymSubscriptionGetCount]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Gym].[f_GymSubscriptionGetCount] ( @WithDaily BIT )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT = 0;

  IF @WithDaily = 1
  BEGIN
                           
    SELECT @c = COUNT_BIG(s.ID)
      FROM Gym.t_GymSubscription AS s;

  END;
  ELSE
  BEGIN
    
    SELECT @c = COUNT_BIG(s.ID)
      FROM Gym.t_GymSubscription AS s
      INNER JOIN Gym.t_SubscriptionType AS s1 ON s1.ID = s.SubscriptionTypeID
      WHERE s1.TimePeriodDays > 1;

  END;

  RETURN ISNULL(@c,0);

END;



