  )
RETURNS BIGINT
AS
BEGIN

  DECLARE @c BIGINT = 0;

  IF @WithDaily = 1
  BEGIN
                           
    SELECT @c = COUNT_BIG(s.ID)
      FROM Gym.t_GymSubscription AS s
      WHERE CONVERT (DATE, s.DateCreate) = @DateCreate;

  END;
  ELSE
  BEGIN
    
    SELECT @c = COUNT_BIG(s.ID)
      FROM Gym.t_GymSubscription AS s
      INNER JOIN Gym.t_SubscriptionType AS s1 ON s1.ID = s.SubscriptionTypeID
      WHERE CONVERT (DATE, s.DateCreate) = @DateCreate AND s1.TimePeriodDays > 1;

  END;

  RETURN ISNULL(@c,0);

END;



