CREATE FUNCTION [Gym].[f_GymSubscriptionGetLastByAccountID] ( @ID UNIQUEIDENTIFIER )
RETURNS DATE
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @D DATE;

  END;

  BEGIN --Set

    SET @D = ( SELECT TOP ( 1 ) o.DateIs
                FROM ( SELECT t.DateIs
                        FROM Gym.t_GymSubscription AS t
                        WHERE t.AccountID = @ID
                       UNION ALL
                       SELECT t.DateIs
                        FROM Gym.t_GymSubscriptionHistory AS t
                        WHERE t.AccountID = @ID
                     ) AS o
                ORDER BY o.DateIs DESC
             );

  END;

  RETURN COALESCE(@D, DATEFROMPARTS(2000, 1, 1));

END;






