/****** Object:  UserDefinedFunction [Invoices].[f_ItemSerialMovementGetIsAvailable]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Invoices].[f_ItemSerialMovementGetIsAvailable]
  (
    @ItemID UNIQUEIDENTIFIER ,
    @SerialID UNIQUEIDENTIFIER
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @c INT = 0;

  SELECT @c = COUNT(*)
    FROM Invoices.t_PurchasingDetailSerial AS t
    INNER JOIN Invoices.t_PurchasingDetail AS t1 ON t1.ID = t.PurchasingDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c -= COUNT(*)
    FROM Invoices.t_PurchasingReturnDetailSerial AS t
    INNER JOIN Invoices.t_PurchasingReturnDetail AS t1 ON t1.ID = t.PurchasingReturnDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c -= COUNT(*)
    FROM Invoices.t_SoldDetailSerial AS t
    INNER JOIN Invoices.t_SoldDetail AS t1 ON t1.ID = t.SoldDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c += COUNT(*)
    FROM Invoices.t_SoldReturnDetailSerial AS t
    INNER JOIN Invoices.t_SoldReturnDetail AS t1 ON t1.ID = t.SoldReturnDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c += COUNT(*)
    FROM Items.t_BeginningInventoryQuantityDetailSerial AS t
    INNER JOIN Items.t_BeginningInventoryQuantityDetail AS t1 ON t1.ID = t.BeginningInventoryQuantityDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c += COUNT(*)
    FROM Items.t_ItemProductionSerial AS t
    INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c -= COUNT(*)
    FROM Items.t_ItemProductionMaterialSerial AS t
    INNER JOIN Items.t_ItemProductionMaterial AS t1 ON t1.ID = t.ItemProductionMaterialID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c -= COUNT(*)
    FROM Items.t_DeliveryPermissionDetailSerial AS t
    INNER JOIN Items.t_DeliveryPermissionDetail AS t1 ON t1.ID = t.DeliveryPermissionDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c -= COUNT(*)
    FROM Items.t_DeliveryPermissionHistoryDetailSerial AS t
    INNER JOIN Items.t_DeliveryPermissionHistoryDetail AS t1 ON t1.ID = t.DeliveryPermissionHistoryDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID;

  SELECT @c += COUNT(*)
    FROM Items.t_StockAdjustmentDetailSerial AS t
    INNER JOIN Items.t_StockAdjustmentDetail AS t1 ON t1.ID = t.StockAdjustmentDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID AND t1.Qty > 0;

  SELECT @c += COUNT(*)
    FROM Items.t_StockTakeDetailSerial AS t
    INNER JOIN Items.t_StockTakeDetail AS t1 ON t1.ID = t.StockTakeDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID AND t1.Qty > 0;

  SELECT @c -= COUNT(*)
    FROM Items.t_StockAdjustmentDetailSerial AS t
    INNER JOIN Items.t_StockAdjustmentDetail AS t1 ON t1.ID = t.StockAdjustmentDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID AND t1.Qty < 0;

  SELECT @c -= COUNT(*)
    FROM Items.t_StockTakeDetailSerial AS t
    INNER JOIN Items.t_StockTakeDetail AS t1 ON t1.ID = t.StockTakeDetailID
    WHERE t1.ItemID = @ItemID AND t.SerialID = @SerialID AND t1.Qty < 0;

  SELECT @c += COUNT(*)
    FROM Invoices.t_TransferAwaitedDetailSerial AS t
    INNER JOIN Invoices.t_TransferAwaitedDetail AS t1 ON t1.ID = t.TransferAwaitedDetailID
    INNER JOIN Invoices.t_TransferAwaited AS t2 ON t2.ID = t.TransferAwaitedID
    INNER JOIN Items.t_Item AS t3 ON t3.WareHouseID = t2.ToWarehouseID
    WHERE t3.ID = @ItemID AND t.SerialID = @SerialID; 

  SELECT @c -= COUNT(*)
    FROM Invoices.t_TransferAwaitedDetailSerial AS t
    INNER JOIN Invoices.t_TransferAwaitedDetail AS t1 ON t1.ID = t.TransferAwaitedDetailID
    INNER JOIN Invoices.t_TransferAwaited AS t2 ON t2.ID = t.TransferAwaitedID
    INNER JOIN Items.t_Item AS t3 ON t3.WareHouseID = t2.FromWarehouseID
    WHERE t3.ID = @ItemID AND t.SerialID = @SerialID; 

  SELECT @c += COUNT(*)
    FROM Invoices.t_TransferDetailSerial AS t
    INNER JOIN Invoices.t_TransferDetail AS t1 ON t1.ID = t.TransferDetailID
    INNER JOIN Invoices.t_Transfer AS t2 ON t2.ID = t.TransferID
    INNER JOIN Items.t_Item AS t3 ON t3.WareHouseID = t2.ToWarehouseID
    WHERE t3.ID = @ItemID AND t.SerialID = @SerialID; 

  SELECT @c -= COUNT(*)
    FROM Invoices.t_TransferDetailSerial AS t
    INNER JOIN Invoices.t_TransferDetail AS t1 ON t1.ID = t.TransferDetailID
    INNER JOIN Invoices.t_Transfer AS t2 ON t2.ID = t.TransferID
    INNER JOIN Items.t_Item AS t3 ON t3.WareHouseID = t2.FromWarehouseID
    WHERE t3.ID = @ItemID AND t.SerialID = @SerialID; 

  RETURN IIF(@c >= 1 ,1,0);

END;





GO
/****** Object:  UserDefinedFunction [Invoices].[f_PhoneCustomerGetCurrentBalance]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Invoices].[f_PhoneCustomerGetCurrentBalance] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @CurrentBalance FLOAT = 0;

  END;

  BEGIN --Set

    SELECT @CurrentBalance = ISNULL(SUM(t.Amount), 0)
      FROM Invoices.t_PhonePayment AS t
      WHERE t.CustomerID = @ID;

    SELECT @CurrentBalance -= ISNULL(SUM(t.MonthlyFees), 0)
      FROM Invoices.t_PhoneSubscription AS t
      WHERE t.CustomerID = @ID;
	  
  END;

  RETURN @CurrentBalance;

END;






