/****** Object:  UserDefinedFunction [Invoices].[f_PurchaseOrderGetDeadlineNotificationARX]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Invoices].[f_PurchaseOrderGetDeadlineNotificationARX] ( @DeadlineDate DATE )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @DeadlineNotification NVARCHAR(MAX) = N'' ,
    @Today DATE = DateTimes.f_GetToday();

  DECLARE @DaysLeft INT = DATEDIFF(DAY, @Today, @DeadlineDate) ,
    @DaysLate INT = DATEDIFF(DAY, @DeadlineDate, @Today);
	
  SET @DeadlineNotification = CASE WHEN @DeadlineDate > @Today THEN N'باقي ' + Alls.f_GetDayTextBaseOnNumberAR(@DaysLeft)
                                   WHEN @DeadlineDate = @Today THEN N'اليوم'
                                   ELSE N'متأخر ' + Alls.f_GetDayTextBaseOnNumberAR(@DaysLate)
                              END;

  RETURN COALESCE(@DeadlineNotification , N'');

END;










GO
/****** Object:  UserDefinedFunction [Invoices].[f_PurchaseOrderGetDeadlineNotificationENX]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Invoices].[f_PurchaseOrderGetDeadlineNotificationENX] ( @DeadlineDate DATE )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @DeadlineNotification NVARCHAR(MAX) = N'' ,
    @Today DATE = DateTimes.f_GetToday();
 
  DECLARE @DaysLeft INT = DATEDIFF(DAY, @Today, @DeadlineDate) ,
    @DaysLate INT = DATEDIFF(DAY, @DeadlineDate, @Today);

  SET @DeadlineNotification = CASE WHEN @DeadlineDate > @Today THEN Alls.f_GetDayTextBaseOnNumberEN(@DaysLeft) + N' left'
                                   WHEN @DeadlineDate = @Today THEN N'Today'
                                   ELSE Alls.f_GetDayTextBaseOnNumberEN(@DaysLate) + N' late'
                              END;

  RETURN COALESCE(@DeadlineNotification , N'');

END;










