CREATE FUNCTION [Invoices].[f_PurchasingGetExternalPayments] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  DECLARE @PaidUp FLOAT = 0;

  SELECT @PaidUp = ISNULL(SUM(s.Balance), 0)
    FROM Transactions.t_TransactionDetail AS s
    INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
    WHERE s.Balance > 0 AND s1.LinkType = 0 AND s1.LinkTypeSub = 16 AND s1.LinkID = @ID;

  RETURN @PaidUp;

END;






