CREATE FUNCTION [Invoices].[f_PurchasingGetPaidStatus]
  (
    @Total FLOAT ,
    @PaidUp FLOAT ,
    @Rest FLOAT
  )
RETURNS TINYINT
AS
BEGIN
		
