/****** Object:  UserDefinedFunction [Invoices].[f_PurchasingGetProfitByAccountVendorID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Invoices].[f_PurchasingGetProfitByAccountVendorID] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @V FLOAT;

  END;

  BEGIN --Set

    SET @V = ( SELECT COALESCE(SUM(CASE t1.CurrencyTypeIs
                                     WHEN 0 THEN t.ProfitD
                                     WHEN 1 THEN t.ProfitLL
                                     ELSE t.ProfitEuro
                                   END), 0)
                FROM Invoices.t_Purchasing AS t
                  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountVendorID
                WHERE t.AccountVendorID = @ID
             ); 
	 
  END;

  RETURN COALESCE(@V, 0);

END;













