/****** Object:  UserDefinedFunction [Invoices].[f_SoldDetail_CheckSoldBefore]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Invoices].[f_SoldDetail_CheckSoldBefore]
  (
    @ItemSharedID UNIQUEIDENTIFIER ,
    @AccountID UNIQUEIDENTIFIER
  )
RETURNS BIT
AS
BEGIN

  DECLARE @c BIGINT = 0;

  SELECT TOP ( 1 ) @c = COUNT_BIG(t.ID)
    FROM Invoices.t_SoldDetail AS t
    INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
    WHERE t.ItemSharedID = @ItemSharedID AND t1.AccountCustomerID = @AccountID;

  RETURN IIF(@c <= 0,0,1);

END;





