CREATE FUNCTION [Invoices].[f_SoldDetail_GetID_LastPrice]
  (
    @AccountID UNIQUEIDENTIFIER ,
    @ItemSharedID UNIQUEIDENTIFIER ,
    @ItemUnitID UNIQUEIDENTIFIER
  )
RETURNS UNIQUEIDENTIFIER
AS
BEGIN

  DECLARE @ID UNIQUEIDENTIFIER;

  SELECT TOP ( 1 ) @ID = t.ID
    FROM Invoices.t_SoldDetail AS t
    INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
    WHERE t1.AccountCustomerID = @AccountID AND t.ItemSharedID = @ItemSharedID AND t.ItemUnityID = @ItemUnitID
    ORDER BY t1.DateIs DESC;

  RETURN ISNULL(@ID ,Alls.f_GetEmptyGuid() );

END;






