GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Invoices].[f_SoldGetPaidStatus]
  (
    @Total FLOAT ,
    @PaidUp FLOAT ,
    @Rest FLOAT
  )
RETURNS TINYINT
AS
BEGIN
		
  RETURN IIF(ROUND(@Total, 4) - ROUND(@PaidUp, 4) = 0, 2, IIF(ROUND(@Rest, 4) < ROUND(@Total, 4), 1, 0));

END;




