/****** Object:  UserDefinedFunction [Items].[f_GetQtyCurrentByUnit]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Items].[f_GetQtyCurrentByUnit]
  (
    @ItemSharedID UNIQUEIDENTIFIER ,
    @QtyCurrent DECIMAL(18, 6)
  )
RETURNS NVARCHAR(MAX)
BEGIN
  	
  DECLARE @UnitCount INT = 0 ,
    @Unit NVARCHAR(MAX) = '' ,
    @UnitQty DECIMAL(18, 6) = 0 ,
    @QtyCurrentX DECIMAL(18, 6) ,
    @QtyCurrentByUnit NVARCHAR(MAX) = '';  

  SELECT @UnitCount = ISNULL(COUNT(s.ID), 0) ,
      @Unit = MIN(s.Unity)
    FROM Items.t_UnityItem AS s
    WHERE s.SharedID = @ItemSharedID;	
	
  IF @UnitCount = 1 AND @QtyCurrent <> 0
  BEGIN
                   
    RETURN FORMAT(@QtyCurrent ,N'#,###.######')  + N' ' + @Unit;

  END;

  WHILE @QtyCurrent <> 0
  BEGIN
   
    IF EXISTS ( SELECT TOP ( 1 ) s.ID
                  FROM Items.t_UnityItem AS s
                  WHERE s.SharedID = @ItemSharedID AND s.Qty <= @QtyCurrent )
    BEGIN
	    
      SELECT TOP ( 1 ) @Unit = s.Unity ,
          @UnitQty = s.Qty
        FROM Items.t_UnityItem AS s
        WHERE s.SharedID = @ItemSharedID AND s.Qty <= @QtyCurrent
        ORDER BY s.Qty DESC;

      SET @QtyCurrentX = IIF(( @QtyCurrent - @QtyCurrent % @UnitQty ) / @UnitQty <> 0, ( @QtyCurrent - @QtyCurrent % @UnitQty ) / @UnitQty, @QtyCurrent);

      SET @QtyCurrentByUnit += FORMAT(@QtyCurrentX, '#,##0.######') + ' ' + @Unit + ' & ';

      SET @QtyCurrent -= @QtyCurrentX * @UnitQty;

    END;
    ELSE
    BEGIN

      SELECT TOP ( 1 ) @Unit = s.Unity ,
          @UnitQty = s.Qty
        FROM Items.t_UnityItem AS s
        WHERE s.SharedID = @ItemSharedID
        ORDER BY s.Qty;

      SET @QtyCurrentX = IIF(( @QtyCurrent - @QtyCurrent % @UnitQty ) / @UnitQty <> 0, ( @QtyCurrent - @QtyCurrent % @UnitQty ) / @UnitQty, @QtyCurrent);

      SET @QtyCurrentByUnit += FORMAT(@QtyCurrentX, '#,##0.######') + ' ' + @Unit + ' & ';

      SET @QtyCurrent = 0;

    END;

  END;

  SET @QtyCurrentByUnit = SUBSTRING(@QtyCurrentByUnit, -1, LEN(@QtyCurrentByUnit));

  SET @QtyCurrentByUnit = IIF(@QtyCurrent >= 0, @QtyCurrentByUnit, '- ' + @QtyCurrentByUnit);

  SET @QtyCurrentByUnit = IIF(@QtyCurrentByUnit = '', '0', @QtyCurrentByUnit);
 
  RETURN @QtyCurrentByUnit;

END;




