                        INNER JOIN Items.t_StockTake AS t1 ON t1.ID = t.StockTakeID
                        WHERE t.ItemID = @ItemsID AND t1.DateIs <= @DateIs AND t1.ID <> @StockTakeID
                     );
	
  SET @QtyCurrent += ( SELECT COALESCE(SUM(Qtys), 0)
                        FROM Items.t_ItemProduction
                        WHERE ItemID = @ItemsID AND DateIs <= @DateIs
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_ItemProductionMaterial AS t
                        INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
                        WHERE t.ItemID = @ItemsID AND t1.DateIs <= @DateIs
                     );
	
