CREATE FUNCTION [Items].[f_ItemGetQtyByFromToDate]
  (
    @ItemsID UNIQUEIDENTIFIER ,
    @FromDate DATE ,
    @ToDate DATE
  )
RETURNS DECIMAL(18, 6)
AS
BEGIN

  DECLARE @QtyCurrent DECIMAL(18, 6) = 0.0;

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_PurchasingDetail AS t
                        INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_SoldDetail AS t
                        INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_PurchasingReturnDetail AS t
                        INNER JOIN Invoices.t_PurchasingReturn AS t1 ON t1.ID = t.PurchasingReturnID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_SoldReturnDetail AS t
                        INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_BeginningInventoryQuantityDetail AS t
                        INNER JOIN Items.t_BeginningInventoryQuantity AS t1 ON t1.ID = t.BeginningInventoryQuantityID
                        WHERE t.ItemID = @ItemsID AND t1.DateIs >= @FromDate AND t1.DateIs <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_TransferAwaitedDetail AS t
                        INNER JOIN Invoices.t_TransferAwaited AS t1 ON t1.ID = t.TransferAwaitedID
                        INNER JOIN Company.t_WareHouse AS s2 ON s2.ID = t1.FromWarehouseID
                        INNER JOIN Items.t_Item AS s3 ON s3.WareHouseID = s2.ID AND s3.SharedID = t.ItemSharedID
                        WHERE s3.ID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_TransferDetail AS t
                        INNER JOIN Invoices.t_Transfer AS t1 ON t1.ID = t.TransferID
                        INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t1.FromWarehouseID
                        INNER JOIN Items.t_Item AS s3 ON s3.WareHouseID = t2.ID AND s3.SharedID = t.ItemSharedID
                        WHERE s3.ID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Invoices.t_TransferDetail AS t
                        INNER JOIN Invoices.t_Transfer AS t1 ON t1.ID = t.TransferID
                        INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t1.ToWarehouseID
                        INNER JOIN Items.t_Item AS s3 ON s3.WareHouseID = t2.ID AND s3.SharedID = t.ItemSharedID
                        WHERE s3.ID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_StockAdjustmentDetail AS t
                        INNER JOIN Items.t_StockAdjustment AS t1 ON t1.ID = t.StockAdjustmentID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_StockTakeDetail AS t
                        INNER JOIN Items.t_StockTake AS t1 ON t1.ID = t.StockTakeID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );
	
  SET @QtyCurrent += ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_ItemProduction AS t
                        WHERE t.ItemID = @ItemsID AND t.DateOnly >= @FromDate AND t.DateOnly <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_ItemProductionMaterial AS t
                        INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
                        WHERE t.ItemID = @ItemsID AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );
	
  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_DeliveryPermissionDetail AS t
                        INNER JOIN Items.t_DeliveryPermission AS t1 ON t1.ID = t.DeliveryPermissionID
                        WHERE t.ItemID = @ItemsID AND t1.StatusNow <> 0 AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );
	
  SET @QtyCurrent -= ( SELECT COALESCE(SUM(t.Qtys), 0)
                        FROM Items.t_DeliveryPermissionHistoryDetail AS t
                        INNER JOIN Items.t_DeliveryPermissionHistory AS t1 ON t1.ID = t.DeliveryPermissionHistoryID
                        WHERE t.ItemID = @ItemsID AND t1.StatusNow <> 0 AND t1.DateOnly >= @FromDate AND t1.DateOnly <= @ToDate
                     );

  SET @QtyCurrent -= ( SELECT COUNT(t.ID)
                        FROM Invoices.t_DressesRental AS t
                        WHERE t.ItemID = @ItemsID AND t.DateOnly >= @FromDate AND t.DateOnly <= @ToDate
                     );

  RETURN ISNULL(@QtyCurrent, 0);

END;





