/****** Object:  UserDefinedFunction [Items].[f_ItemProductionGetLastItemUnitIDByItemShared]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Items].[f_ItemProductionGetLastItemUnitIDByItemShared] ( @ID UNIQUEIDENTIFIER )
RETURNS UNIQUEIDENTIFIER
AS
BEGIN

  DECLARE @v UNIQUEIDENTIFIER;

  SELECT TOP ( 1 ) @v = ItemUnityID
    FROM Items.t_ItemProduction
    WHERE ItemSharedID = @ID
    ORDER BY DateIs DESC;

  RETURN ISNULL(@v, N'00000000-0000-0000-0000-000000000000');

END;



