/****** Object:  UserDefinedFunction [Items].[f_ItemShared_Get_UnitsDetails_LIVE]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Items].[f_ItemShared_Get_UnitsDetails_LIVE] ( @ID UNIQUEIDENTIFIER )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  DECLARE @v NVARCHAR(MAX) = N'';

  SET @v = Alls.f_FixXML(( SELECT ', ' + t1.Name + N'_' + FORMAT(t.Qty, N'0.##') AS [text()]
                            FROM Items.t_UnityItem AS t
                            INNER JOIN Items.t_Unity AS t1 ON t1.ID = t.UnityID
                            WHERE t.SharedID = @ID AND t.PrimaryIs = 0
							ORDER BY t.Qty
                         FOR
                           XML PATH('')
                         ));

  RETURN COALESCE(@v , N'');

END;





