/****** Object:  UserDefinedFunction [Items].[f_ItemSharedGetAverageCost]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Items].[f_ItemSharedGetAverageCost]
  (
    @ID UNIQUEIDENTIFIER ,
    @CalculatingFreeQuantities BIT
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @CurrencyTypeIs INT ,
      @QtyCurrent BIGINT = 0 ,
      @OldCost FLOAT = 0 ,
      @NewCost FLOAT = 0;

  END;

  BEGIN --Set Info
    
    SELECT TOP ( 1 ) @CurrencyTypeIs = s1.TypeIs ,
        @OldCost = s.Purchase ,
        @QtyCurrent = s.QtyCurrent
      FROM Items.t_ItemShared AS s
      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
      WHERE s.ID = @ID;

    IF @QtyCurrent <= 0
    BEGIN
	                         
      SET @QtyCurrent = Items.f_ItemSharedGetLastQtysPurchase(@ID);

    END;

    IF @QtyCurrent <= 0
    BEGIN
	                         
      RETURN  Items.f_ItemSharedGetLastCost(@ID);

    END;
		
    --IF @CalculatingFreeQuantities = 1
    --BEGIN
                                      
    --  SELECT @NewCost = SUM(t.Total) / SUM(t.Qtys)
    --    FROM ( SELECT TOP ( @QtyCurrent ) s.DateIs ,
    --              1 AS Qtys ,
    --              CASE @CurrencyTypeIs
    --                WHEN 0 THEN s.TotalD
    --                WHEN 1 THEN s.TotalLL
    --                ELSE s.TotalEuro
    --              END / s.Qtys AS Total
    --            FROM Items.v_ItemSharedAllCostWithoutTax AS s
    --            INNER JOIN master.dbo.spt_values s1 ON s1.type = 'P' AND s1.number < s.Qtys
    --            WHERE s.ItemSharedID = @ID
    --            ORDER BY s.DateIs DESC ,
    --              s.SectionType ASC
    --         ) AS t;

    --END;
    --ELSE
    --BEGIN

    --  SELECT @NewCost = SUM(t.Total) / SUM(t.Qtys)
    --    FROM ( SELECT TOP ( @QtyCurrent ) s.DateIs ,
    --              1 AS Qtys ,
    --              CASE @CurrencyTypeIs
    --                WHEN 0 THEN s.TotalD
    --                WHEN 1 THEN s.TotalLL
    --                ELSE s.TotalEuro
    --              END / s.Qtys AS Total
    --            FROM Items.v_ItemSharedAllCostWithoutTaxWithoutFree AS s
    --            INNER JOIN master.dbo.spt_values s1 ON s1.type = 'P' AND s1.number < s.Qtys
    --            WHERE s.ItemSharedID = @ID
    --            ORDER BY s.DateIs DESC ,
    --              s.SectionType ASC
    --         ) AS t;

    --END;

  END;

  BEGIN
      
    BEGIN --DECLARE 2
    
      DECLARE @LoopID BIGINT;
      DECLARE @QtysFor BIGINT = 0;
      DECLARE @QtysRest BIGINT = @QtyCurrent;

      DECLARE @t AS TABLE
        (
          ID BIGINT NOT NULL ,
          DateIs DATETIME NOT NULL ,
          Qtys FLOAT NOT NULL ,
          Total FLOAT NOT NULL
        );

      DECLARE @NewCosts AS TABLE
        (
          Qtys FLOAT NOT NULL ,
          Total FLOAT NOT NULL
        );

    END;   

    BEGIN --Set 2
    
      IF @CalculatingFreeQuantities = 1
      BEGIN

        INSERT INTO @t
            ( ID ,
              DateIs ,
              Qtys ,
              Total
            )
          SELECT ROW_NUMBER() OVER ( ORDER BY s.DateIs DESC ) ,
              s.DateIs ,
              s.Qtys ,
              CASE @CurrencyTypeIs
                WHEN 0 THEN s.TotalD
                WHEN 1 THEN s.TotalLL
                ELSE s.TotalEuro
              END
            FROM Items.v_ItemSharedAllCostWithoutTax AS s
            WHERE s.ItemSharedID = @ID
            ORDER BY s.DateIs DESC;

      END;   
      ELSE
      BEGIN
    
        INSERT INTO @t
            ( ID ,
              DateIs ,
              Qtys ,
              Total
            )
          SELECT ROW_NUMBER() OVER ( ORDER BY s.DateIs DESC ) ,
              s.DateIs ,
              s.Qtys ,
              CASE @CurrencyTypeIs
                WHEN 0 THEN s.TotalD
                WHEN 1 THEN s.TotalLL
                ELSE s.TotalEuro
              END
            FROM Items.v_ItemSharedAllCostWithoutTaxWithoutFree AS s
            WHERE s.ItemSharedID = @ID
            ORDER BY s.DateIs DESC;
      END;

    END;   

    BEGIN --Loop
    
      DECLARE i CURSOR FORWARD_ONLY
      FOR
      SELECT s.ID
        FROM @t AS s
        ORDER BY s.DateIs DESC;

      OPEN i;
      FETCH NEXT FROM i
    INTO @LoopID;
      WHILE @@FETCH_STATUS = 0
      BEGIN
	
        SELECT @QtysFor = s.Qtys
          FROM @t AS s
          WHERE s.ID = @LoopID;

        SET @QtysFor = IIF(@QtysFor <= @QtysRest, @QtysFor, @QtysRest);
        SET @QtysRest -= @QtysFor;

        IF @QtysFor <= 0
        BEGIN

          BREAK;

        END;

        INSERT @NewCosts
            ( Qtys ,
              Total
            )
          SELECT 1 ,
              s.Total / s.Qtys
            FROM @t AS s
            JOIN
              ( SELECT ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                    ) ) AS rr
                  FROM master.dbo.spt_values AS s1 ,
                    master.dbo.spt_values AS s2
              ) AS ss ON ss.rr <= @QtysFor
            WHERE s.ID = @LoopID;
 
        FETCH NEXT FROM i
        INTO @LoopID;
      END;
      CLOSE i;
      DEALLOCATE i;

      SELECT @NewCost = SUM(t.Total) / SUM(t.Qtys)
        FROM @NewCosts AS t;

    END;

  END;

  SET @NewCost = ISNULL(@NewCost, 0);

  RETURN IIF( @NewCost <= 0 , @OldCost ,@NewCost);
  
END;

GO
/****** Object:  UserDefinedFunction [Items].[f_ItemSharedGetAverageCostProduction]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Items].[f_ItemSharedGetAverageCostProduction] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @CurrencyTypeIs INT ,
      @QtyCurrent BIGINT = 0 ,
      @OldCost FLOAT = 0 ,
      @NewCost FLOAT = 0;

  END;

  BEGIN --Set Info
    
    SELECT TOP ( 1 ) @CurrencyTypeIs = s1.TypeIs ,
        @OldCost = s.Purchase ,
        @QtyCurrent = s.QtyCurrent
      FROM Items.t_ItemShared AS s
      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
      WHERE s.ID = @ID;

    IF @QtyCurrent <= 0
    BEGIN
	                         
      SET @QtyCurrent = Items.f_ItemSharedGetLastQtysProduction(@ID);

    END;

    IF @QtyCurrent <= 0
    BEGIN
	                         
      RETURN -1;

    END;

  END;

  BEGIN
      
    BEGIN --DECLARE 2
    
      DECLARE @LoopID BIGINT;
      DECLARE @QtysFor BIGINT = 0;
      DECLARE @QtysRest BIGINT = @QtyCurrent;

      DECLARE @t AS TABLE
        (
          ID BIGINT NOT NULL ,
          DateIs DATETIME NOT NULL ,
          Qtys FLOAT NOT NULL ,
          Total FLOAT NOT NULL
        );

      DECLARE @NewCosts AS TABLE
        (
          Qtys FLOAT NOT NULL ,
          Total FLOAT NOT NULL
        );

    END;   

    BEGIN --Set 2

      INSERT INTO @t
          ( ID ,
            DateIs ,
            Qtys ,
            Total
          )
        SELECT ROW_NUMBER() OVER ( ORDER BY s.DateIs DESC ) ,
            s.DateIs ,
            s.Qtys ,
            CASE @CurrencyTypeIs
              WHEN 0 THEN s.TotalCostD
              WHEN 1 THEN s.TotalCostLL
              ELSE s.TotalCostEuro
            END
          FROM Items.t_ItemProduction AS s
          WHERE s.ItemSharedID = @ID
          ORDER BY s.DateIs DESC;  

    END;   

    BEGIN --Loop
    
      DECLARE i CURSOR FORWARD_ONLY
      FOR
      SELECT s.ID
        FROM @t AS s
        ORDER BY s.DateIs DESC;

      OPEN i;
      FETCH NEXT FROM i
    INTO @LoopID;
      WHILE @@FETCH_STATUS = 0
      BEGIN
	
        SELECT @QtysFor = s.Qtys
          FROM @t AS s
          WHERE s.ID = @LoopID;

        SET @QtysFor = IIF(@QtysFor <= @QtysRest, @QtysFor, @QtysRest);
        SET @QtysRest -= @QtysFor;

        IF @QtysFor <= 0
        BEGIN

          BREAK;

        END;

        INSERT @NewCosts
            ( Qtys ,
              Total
            )
          SELECT 1 ,
              s.Total / s.Qtys
            FROM @t AS s
            JOIN
              ( SELECT ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                    ) ) AS rr
                  FROM master.dbo.spt_values AS s1 ,
                    master.dbo.spt_values AS s2
              ) AS ss ON ss.rr <= @QtysFor
            WHERE s.ID = @LoopID;
 
        FETCH NEXT FROM i
        INTO @LoopID;
      END;
      CLOSE i;
      DEALLOCATE i;

      SELECT @NewCost = SUM(t.Total) / SUM(t.Qtys)
        FROM @NewCosts AS t;

    END;

  END;

  SET @NewCost = ISNULL(@NewCost, 0);

  RETURN IIF( @NewCost <= 0 , @OldCost ,@NewCost);
  
END;

