/****** Object:  UserDefinedFunction [Items].[f_ItemSharedGetHigherCost]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Items].[f_ItemSharedGetHigherCost]
  (
    @ID UNIQUEIDENTIFIER ,
    @FromDate DATE
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @CurrencyTypeIs INT ,
      @OldCost FLOAT = 0 ,
      @NewCost FLOAT = 0;

  END;

  BEGIN --Set Info
    
    SELECT TOP ( 1 ) @CurrencyTypeIs = s1.TypeIs ,
        @OldCost = s.Purchase
      FROM Items.t_ItemShared AS s
      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
      WHERE s.ID = @ID;

    SELECT @NewCost = CASE @CurrencyTypeIs
                        WHEN 0 THEN MAX(s.TotalD / s.Qtys)
                        WHEN 1 THEN MAX(s.TotalLL / s.Qtys)
                        ELSE MAX(s.TotalEuro / s.Qtys)
                      END
      FROM Items.v_ItemSharedAllCostWithoutTax AS s
      WHERE s.Qtys <> 0 and s.ItemSharedID = @ID AND s.DateIs >= @FromDate;

  END;

  SET @NewCost = ISNULL(@NewCost, 0);

  RETURN IIF( @NewCost <= 0 , @OldCost ,@NewCost);
  
END;







