CREATE FUNCTION [Items].[f_ItemSharedGetLastCost] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @CurrencyTypeIs INT ,
      @OldCost FLOAT = 0 ,
      @NewCost FLOAT = 0;

  END;
  
  BEGIN --Set Info
    
    SELECT TOP ( 1 ) @CurrencyTypeIs = s1.TypeIs ,
