/****** Object:  UserDefinedFunction [Items].[f_ItemSharedGetLastQtysPurchase]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Items].[f_ItemSharedGetLastQtysPurchase] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @PurchaseID UNIQUEIDENTIFIER ,
      @q FLOAT = 0;

  END;
  
  BEGIN --Set Info
    
    SELECT TOP ( 1 ) @PurchaseID = t.PurchasingID
      FROM Invoices.t_PurchasingDetail AS t
      INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
      WHERE t.ItemSharedID = @ID
      ORDER BY t1.DateOnly DESC;

    IF @PurchaseID IS NULL
    BEGIN
                           
      RETURN 0;

    END;

    SELECT @q = SUM(t.Qtys)
      FROM Invoices.t_PurchasingDetail AS t
      WHERE t.PurchasingID = @PurchaseID AND t.ItemSharedID = @ID;

  END;

  SET @q = ISNULL(@q, 0);

  RETURN IIF( @q <= 0 , 0 ,@q);
  
END;







