        @OldCost = s.Purchase
      FROM Items.t_ItemShared AS s
      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
      WHERE s.ID = @ID;

    SELECT @NewCost = CASE @CurrencyTypeIs
                        WHEN 0 THEN MIN(s.TotalD / s.Qtys)
