/****** Object:  UserDefinedFunction [Items].[f_ItemSharedMaterial_GetCost]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Items].[f_ItemSharedMaterial_GetCost]
  (
    @ItemSharedFatherID UNIQUEIDENTIFIER
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE
    
    DECLARE @Cost FLOAT = 0 ,
      @Cost2 FLOAT = 0;

  END;
  
  BEGIN --Set Info
    
    SELECT @Cost = SUM(CASE s3.TypeIs
                         WHEN 0 THEN s1.PurchaseWithTaxD * s.Qtys
                         WHEN 1 THEN s1.PurchaseWithTaxLL * s.Qtys
                         ELSE s1.PurchaseWithTaxEuro * s.Qtys
                       END)
      FROM Items.t_ItemSharedMaterial AS s
      INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
      INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.ItemSharedFatherID
      INNER JOIN Currencys.t_Currency AS s3 ON s3.ID = s2.CurrencyID
      WHERE s.ItemSharedFatherID = @ItemSharedFatherID;

  END;

  SET @Cost = COALESCE(@Cost, 0.0);
 
  IF Alls.f_Company_Get_Items_Production_SourceOfCost() = 1
  BEGIN
                                                               
    SET @Cost2 = COALESCE(Items.f_ItemSharedGetAverageCostProduction(@ItemSharedFatherID), 0);

  END; 

  RETURN  IIF(@Cost2 > 0 ,@Cost2 ,@Cost);
  
END;





GO
