/****** Object:  UserDefinedFunction [Quotations].[f_QuotationGetCountByAccountID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Quotations].[f_QuotationGetCountByAccountID] ( @ID UNIQUEIDENTIFIER )
RETURNS BIGINT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @C BIGINT;

  END;

  BEGIN --Set

    SET @C = ( SELECT COUNT(t.ID)
                FROM Quotations.t_Quotation AS t
                WHERE t.AccountID = @ID AND t.StatusIs <> 5
             ) + ( SELECT COUNT(t.ID)
                    FROM Quotations.t_QuotationHistory AS t
                    WHERE t.AccountID = @ID AND t.StatusIs <> 5
                 );

  END;

  RETURN COALESCE(@C, 0);

END;







GO
/****** Object:  UserDefinedFunction [Quotations].[f_QuotationGetLastDateByAccountID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Quotations].[f_QuotationGetLastDateByAccountID] ( @ID UNIQUEIDENTIFIER )
RETURNS DATE
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @D DATE;

  END;

  BEGIN --Set

    SET @D = ( SELECT TOP ( 1 ) o.DateIs
                FROM ( SELECT t.DateIs
                        FROM Quotations.t_Quotation AS t
                        WHERE t.AccountID = @ID AND t.StatusIs <> 5
                       UNION ALL
                       SELECT t.DateIs
                        FROM Quotations.t_QuotationHistory AS t
                        WHERE t.AccountID = @ID AND t.StatusIs <> 5
                     ) AS o
                ORDER BY o.DateIs DESC
             );

  END;

  RETURN COALESCE(@D, DATEFROMPARTS(2000, 1, 1));

END;






