/****** Object:  UserDefinedFunction [Quotations].[f_QuotationGetProfitByAccountID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Quotations].[f_QuotationGetProfitByAccountID] ( @ID UNIQUEIDENTIFIER )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @V FLOAT;

  END;

  BEGIN --Set

    SET @V = ( SELECT COALESCE(SUM(CASE t1.CurrencyTypeIs
                                     WHEN 0 THEN t.TotalProfitWithTaxD
                                     WHEN 1 THEN t.TotalProfitWithTaxLL
                                     ELSE t.TotalProfitWithTaxEuro
                                   END), 0)
                FROM Quotations.t_Quotation AS t
                INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
                WHERE t.AccountID = @ID AND t.StatusIs <> 5
             ); 
	 
    SET @V += ( SELECT COALESCE(SUM(CASE t1.CurrencyTypeIs
                                      WHEN 0 THEN t.TotalProfitWithTaxD
                                      WHEN 1 THEN t.TotalProfitWithTaxLL
                                      ELSE t.TotalProfitWithTaxEuro
                                    END), 0)
                  FROM Quotations.t_QuotationHistory AS t
                  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
                  WHERE t.AccountID = @ID AND t.StatusIs <> 5
              );  

  END;

  RETURN COALESCE(@V, 0);

END;















