/****** Object:  UserDefinedFunction [Transactions].[f_Transaction_HasAnyLegalAccount]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Transactions].[f_Transaction_HasAnyLegalAccount] ( @ID UNIQUEIDENTIFIER )
RETURNS BIT
AS
BEGIN

  DECLARE @c BIGINT = 0;
 
  SELECT @c = COUNT_BIG(t.ID)
    FROM Transactions.t_TransactionDetail AS t
    INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
    INNER JOIN Alls.v_Person AS t2 ON t2.ID = t1.LinkWithID
    WHERE t.TransactionID = @ID AND t2.NumberCurrency <> '';
				
  RETURN  IIF(@c <= 0, 0, 1);

END;






GO
/****** Object:  UserDefinedFunction [Transactions].[f_TransactionCheckHaveLinkTypeSub]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Transactions].[f_TransactionCheckHaveLinkTypeSub]
  (
    @LinkType INT ,
    @LinkID UNIQUEIDENTIFIER
  )
RETURNS BIT
AS
BEGIN
	
  IF EXISTS ( SELECT TOP ( 1 )
                      s.ID
              FROM    Transactions.t_Transaction AS s
              WHERE   s.LinkType = @LinkType
                      AND s.LinkTypeSub <> 0
                      AND s.LinkID = @LinkID )
  BEGIN
      
    RETURN 1;

  END;

  RETURN 0;

END;




