/****** Object:  UserDefinedFunction [Transactions].[f_TransactionDetailGetBestSellingCustomer]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Transactions].[f_TransactionDetailGetBestSellingCustomer]
  (
    @AccountID UNIQUEIDENTIFIER ,
    @FromDate DATE ,
    @ToDate DATE ,
    @CurrencyTypeIs INT
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v FLOAT;

  END;

  BEGIN --Set

    IF @CurrencyTypeIs = 0
    BEGIN

      SELECT  @v = ISNULL(SUM(t.DebitD), 0)
      FROM    Transactions.t_TransactionDetail AS t
      INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
      WHERE   t.AccountID = @AccountID
              AND t.Debit > 0
              AND t.DateOnly BETWEEN @FromDate AND @ToDate
              AND t1.LinkType IN ( 2, 18, 162, 169, 174, 185 )
              AND t1.LinkTypeSub = 0;                      

      RETURN @v;

    END;

    IF @CurrencyTypeIs = 1
    BEGIN
			
      SELECT  @v = ISNULL(SUM(t.DebitLL), 0)
      FROM    Transactions.t_TransactionDetail AS t
      INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
      WHERE   t.AccountID = @AccountID
              AND t.Debit > 0
              AND t.DateOnly BETWEEN @FromDate AND @ToDate
              AND t1.LinkType IN ( 2, 18, 162, 169, 174, 185 )
              AND t1.LinkTypeSub = 0;  
	
      RETURN @v;
  				       
    END;

    SELECT  @v = ISNULL(SUM(t.DebitEuro), 0)
    FROM    Transactions.t_TransactionDetail AS t
    INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
    WHERE   t.AccountID = @AccountID
            AND t.Debit > 0
            AND t.DateOnly BETWEEN @FromDate AND @ToDate
            AND t1.LinkType IN ( 2, 18, 162, 169, 174, 185 )
            AND t1.LinkTypeSub = 0;  

  END;

  RETURN @v;

END;




