GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Transactions].[f_TransactionDetailGetLastDateByAccount]
  (
    @AccountID UNIQUEIDENTIFIER
  )
RETURNS DATETIME
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @v DATETIME;

  END;

  BEGIN --Set

    SELECT @v = MAX(t.DateIs)
      FROM Transactions.t_TransactionDetail AS t
      WHERE t.AccountID = @AccountID;

  END;

  RETURN COALESCE(@v, DATEFROMPARTS(2000,1,1));

END;







