/****** Object:  UserDefinedFunction [Transactions].[f_TransactionGetBalanceLessDate]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Transactions].[f_TransactionGetBalanceLessDate]
    (
      @AccountID UNIQUEIDENTIFIER ,
      @DateIs DATETIME ,
      @CurrencyID UNIQUEIDENTIFIER
    )
RETURNS FLOAT
AS
    BEGIN

        BEGIN --DECLARE

            DECLARE @Balance FLOAT ,
                @CurrencyType TINYINT;

        END;

        BEGIN --Set

            SET @CurrencyType = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

        END;

        BEGIN --Get
		
            IF @CurrencyType = 0
                BEGIN

                    SELECT  @Balance = SUM(t.BalanceD)
                    FROM    Transactions.t_TransactionDetail AS t
                    WHERE   t.AccountID = @AccountID
                            AND t.DateIs <= @DateIs;
					             
                END;
            ELSE
                IF @CurrencyType = 1
                    BEGIN
					
                        SELECT  @Balance = SUM(t.BalanceLL)
                        FROM    Transactions.t_TransactionDetail AS t
                        WHERE   t.AccountID = @AccountID
                                AND t.DateIs <= @DateIs;
									                               
                    END;
                ELSE
                    IF @CurrencyType = 2
                        BEGIN

                            SELECT  @Balance = SUM(t.BalanceEuro)
                            FROM    Transactions.t_TransactionDetail AS t
                            WHERE   t.AccountID = @AccountID
                                    AND t.DateIs <= @DateIs;	
							                               
                        END;

        END;

        RETURN ISNULL(@Balance,0);

    END;



GO
