GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Transactions].[f_TransactionGetNewRef] ( @TypeIs NVARCHAR(225) )
RETURNS BIGINT
AS
BEGIN

  DECLARE @Ref BIGINT = 0;
 
  SELECT @Ref = ISNULL(MAX(s.Ref), 0)
    FROM Transactions.t_Transaction AS s
    WHERE s.TypeIs = @TypeIs;
				
  RETURN  @Ref  + 1;

END;





