CREATE FUNCTION [Transactions].[f_TransactionGetTotalCredit]
  (
    @AccountID UNIQUEIDENTIFIER
  )
RETURNS FLOAT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @CurrencyTypeIs INT;

  END;

  BEGIN --Set

    SELECT @CurrencyTypeIs = t.CurrencyTypeIs
      FROM Company.t_Account AS t
