    DECLARE @IDs AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

    DECLARE @v FLOAT;

  END;

  BEGIN --Set IDs

    INSERT INTO @IDs
        ( ID
        )
      SELECT @AccountID
      UNION ALL
      SELECT s.SubAccountID
        FROM Company.t_SubAccounts AS s
        WHERE s.MainAccountID = @AccountID;

