  BEGIN --Set

    SELECT @v = ISNULL(SUM(t.CreditD), 0)
      FROM Transactions.t_TransactionDetail AS t
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t.AccountID ) AND t.DateOnly < @DateIs;

  END;

  RETURN @v;

END;




