AS
BEGIN

  BEGIN --DECLARE

    DECLARE @CurrencyTypeIs INT;

  END;

  BEGIN --Set

    SELECT @CurrencyTypeIs = t.CurrencyTypeIs
      FROM Company.t_Account AS t
      WHERE t.ID = @AccountID;

    IF @CurrencyTypeIs = 0
    BEGIN
                           
      RETURN Transactions.f_TransactionGetTotalDebitD(@AccountID);

    END;

    IF @CurrencyTypeIs = 1
    BEGIN
                           
      RETURN Transactions.f_TransactionGetTotalDebitLL(@AccountID);

    END;

    IF @CurrencyTypeIs = 2
    BEGIN
                           
      RETURN Transactions.f_TransactionGetTotalDebitEuro(@AccountID);

    END;

  END;

  RETURN 0;

END;




