/****** Object:  UserDefinedFunction [Users].[f_PermissionAccountStatementUseAllowed]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Users].[f_PermissionAccountStatementUseAllowed]
  (
    @PermissionID UNIQUEIDENTIFIER ,
    @AccountNumber AS BIGINT
  )
RETURNS BIT
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @c INT = 0;

  END;

  BEGIN --Set

    SELECT @c = COUNT(t.ID)
      FROM Users.t_PermissionAccountStatement AS t
      WHERE t.PermissionID = @PermissionID AND t.RangeType = 1 AND @AccountNumber BETWEEN t.FromNumber AND t.ToNumber;

  END;
  
  IF @c > 0
  BEGIN
                
    RETURN 1;

  END;

  BEGIN --Set

    SET @c = 0;

    SELECT @c = COUNT(t.ID)
      FROM Users.t_PermissionAccountStatement AS t
      WHERE t.PermissionID = @PermissionID AND t.RangeType = 0 AND @AccountNumber BETWEEN t.FromNumber AND t.ToNumber;

  END;

  RETURN IIF(@c <= 0,1,0);

END;


GO
