/****** Object:  UserDefinedFunction [Users].[f_PermissionGetFirstID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Users].[f_PermissionGetFirstID] ()
RETURNS NVARCHAR(MAX)
AS
BEGIN

    BEGIN --DECLARE

        DECLARE @ID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set

        SELECT TOP (1)
               @ID = ID
        FROM Users.t_Permission AS t
        ORDER BY t.DateCreate;

    END;

    RETURN @ID;

END;
















