CREATE FUNCTION [Users].[f_PermissionGetFirstName] ()
RETURNS NVARCHAR(MAX)
AS
BEGIN

    BEGIN --DECLARE

        DECLARE @Name NVARCHAR(MAX);

    END;

    BEGIN --Set

        SELECT TOP (1)
               @Name = t.Name
        FROM Users.t_Permission AS t
        ORDER BY t.DateCreate;

    END;

    RETURN COALESCE(@Name, '');

END;









