/****** Object:  UserDefinedFunction [Users].[f_PermissionGetID]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE FUNCTION [Users].[f_PermissionGetID] ( @Name NVARCHAR(MAX) )
RETURNS UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @ID UNIQUEIDENTIFIER;

  END;

  BEGIN --Set

    SELECT @ID = t.ID
      FROM Users.t_Permission AS t
      WHERE t.Name = @Name;

  END;

  RETURN COALESCE(@ID, '00000000-0000-0000-0000-000000000000');

END;










