SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE FUNCTION [Users].[f_QuickActionsGetFirstID] ( )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @ID UNIQUEIDENTIFIER;

  END;

  BEGIN --Set

    SELECT TOP ( 1 ) @ID = ID
      FROM Users.t_QuickActions AS t
      ORDER BY t.DateCreated;

  END;

  RETURN ISNULL(@ID,N'00000000-0000-0000-0000-000000000000');

END;






