/****** Object:  UserDefinedFunction [Users].[f_UserGetOtherBoxesIDs]    Script Date: 28-03-2026 08:37:01 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Users].[f_UserGetOtherBoxesIDs]
  (
    @ID UNIQUEIDENTIFIER ,
    @FromDateTime DATETIME ,
    @ToDateTime DATETIME
  )
RETURNS NVARCHAR(MAX)
AS
BEGIN

  BEGIN --DECLARE

    DECLARE @IDs Alls.tt_Guid;

  END;

  BEGIN --Set

    INSERT INTO @IDs
        ( ID
        )
      SELECT AccountBoxID
        FROM Invoices.t_Sold
        WHERE UserID = @ID AND DateIs >= @FromDateTime AND DateIs <= @ToDateTime
      UNION
      SELECT SecondPaymentAccountBoxID
        FROM Invoices.t_Sold
        WHERE UserID = @ID AND DateIs >= @FromDateTime AND DateIs <= @ToDateTime
      EXCEPT
      SELECT AccountBoxID
        FROM Users.v_UserBoxes
        WHERE ID = @ID;

  END;

  RETURN Alls.f_GuidListToString(@IDs);

END;


