    '00000000-0000-0000-0000-000000000000' AS AccountBoxID ,
    '' AS AccountBox ,
    '' AS AccountBoxNumber ,
    -1 ,
    t.CurrencyID ,
    t.Currency ,
    t.ExchangeRate ,
    t.TotalF ,
    t.TotalD ,
    t.TaxRate ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.DiscountIsF ,
    t.DiscountIsD ,
    t.NetIsF ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    0 AS NetIsD1 ,
    0 AS NetIsLL1 ,
    0 AS NetIsEuro1 ,
    t.TotalProfitWithTaxF ,
    t.TotalProfitWithTaxD ,
    t.TotalProfitWithTaxLL ,
    t.TotalProfitWithTaxEuro ,
    t.Qtys ,
    t.DescriptionIs ,
    t.ItemsNames ,
    t.DateCreate
  FROM Quotations.v_QuotationHistoryList AS t
  WHERE CONVERT(DATE, t.DateCreate) = CONVERT(DATE, GETDATE());














