CREATE VIEW [Invoices].[v_ElectricitySubscriptionsArchivesList]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.RefPaper ,
    t.FromDate ,
    t.FromDateMonthly ,
    t.FromDateYearly ,
    t.ToDate ,
    t.IsActive ,
    t.AccountID ,
    t1.Name AS Account ,
    t1.NumberIs AS AccountNumberIs ,
    t1.NumberF AS AccountNumberF ,
    t1.CurrencyID AS AccountCurrencyID ,
    t1.Balance AS AccountBalance ,
    t1.BalanceF AS AccountBalanceF ,
    t1.BalanceD AS AccountBalanceD ,
    t1.BalanceLL AS AccountBalanceLL ,
    t1.BalanceEuro AS AccountBalanceEuro ,
    ISNULL(tt1.Phones, N'') AS Phones ,
    ISNULL(tt1.AddressIs, N'') AS AddressIs ,
    ISNULL(tt1.ClassificationID, N'00000000-0000-0000-0000-000000000000') AS ClassificationID ,
    ISNULL(tt1.Classification, N'') AS Classification ,
    t.SalesAccountID ,
    t2.Name AS SalesAccount ,
    t.ElectricitySubscriptionTypeID ,
    t3.Name AS ElectricitySubscriptionType ,
    t3.PeriodType ,
    t3.PeriodNumber ,
    t3.SubscriptionFeesF AS TypeSubscriptionFeesF,
    t.ElectricGeneratorID ,
    t4.Name AS ElectricGenerator ,
    t.ElectricalBoxID ,
    t5.Name AS ElectricalBox ,
    t5.PrintOrder ,
    t.TypeIs ,
    t.TotalAmperes ,
    t.PreviousConsumption ,
    t.CurrentConsumption ,
    t.TotalConsumption ,
    t.CurrencyID ,
    t6.Name AS Currency ,
    t.ExchangeRate ,
    t.ExchangeRateLL ,
    t.ExchangeRateEuro ,
    t.FixedFees ,
    t.FixedFeesF ,
    t.FixedFeesD ,
    t.FixedFeesLL ,
    t.FixedFeesEuro ,
    t.SubscriptionFees ,
    t.SubscriptionFeesF ,
    t.SubscriptionFeesD ,
    t.SubscriptionFeesLL ,
    t.SubscriptionFeesEuro ,
    t.AdditionalFees ,
    t.AdditionalFeesF ,
    t.AdditionalFeesD ,
    t.AdditionalFeesLL ,
    t.AdditionalFeesEuro ,
    t.Subtotal ,
    t.SubtotalF ,
    t.SubtotalD ,
    t.SubtotalLL ,
    t.SubtotalEuro ,
    t.Discount ,
    t.DiscountF ,
    t.DiscountD ,
    t.DiscountLL ,
    t.DiscountEuro ,
    t.Total ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.PaidUp ,
    t.PaidUpF ,
    t.PaidUpD ,
    t.PaidUpLL ,
    t.PaidUpEuro ,
    t.Rest ,
    t.RestF ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro ,
    t.Paid ,
    t.CollectionOfficerEmployeeID ,
    t7.Name AS CollectionOfficerEmployee ,
    t.Renewable ,
    t.PrivateNote ,
    t.PrintNote ,
    t.CreatedByUserID ,
    t8.Name AS CreatedByUser ,
    t.DateCreated ,
    t.LastModifiedDate
  FROM Invoices.t_ElectricitySubscriptionsArchives AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  LEFT JOIN Alls.v_Person1 AS tt1 ON tt1.ID = t1.LinkWithID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.SalesAccountID
  INNER JOIN Invoices.t_ElectricitySubscriptionTypes AS t3 ON t3.ID = t.ElectricitySubscriptionTypeID
  INNER JOIN Invoices.t_ElectricGenerators AS t4 ON t4.ID = t.ElectricGeneratorID
  INNER JOIN Invoices.t_ElectricalBoxes AS t5 ON t5.ID = t.ElectricalBoxID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t.CurrencyID
  INNER JOIN Employees.t_Employee AS t7 ON t7.ID = t.CollectionOfficerEmployeeID
  INNER JOIN Users.t_User AS t8 ON t8.ID = t.CreatedByUserID;
  














