CREATE VIEW [Items].[v_GoodsValueMovementSummaryReportStockTakeOut]
AS
SELECT s.ID ,
    s1.DateOnly ,
    s.TotalD ,
    s.TotalLL ,
    s.TotalEuro ,
    s2.Brand ,
    s2.MainCategory ,
    s3.WareHouse
  FROM Items.t_StockTakeDetail AS s
  INNER JOIN Items.t_StockTake AS s1 ON s1.ID = s.StockTakeID
  INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.ItemSharedID
  INNER JOIN Items.t_Item AS s3 ON s3.ID = s.ItemID
  WHERE s.Qtys < 0 AND s.Total <> 0;
    






