    0 - ( s2.PurchaseLL * s.Qtys ) AS TotalLL ,
    0 - ( s2.PurchaseEuro * s.Qtys ) AS TotalEuro ,
    s2.Brand ,
    s2.MainCategory ,
    s3.WareHouse
  FROM Items.t_DeliveryPermissionDetail AS s
  INNER JOIN Items.t_DeliveryPermission AS s1 ON s1.ID = s.DeliveryPermissionID
  INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.ItemSharedID
  INNER JOIN Items.t_Item AS s3 ON s3.ID = s.ItemID
  WHERE s1.StatusNow <> 0 AND s2.Purchase <> 0
UNION ALL
SELECT s.ID ,
    s1.DateOnly ,
    0 - ( s2.PurchaseD * s.Qtys ) AS TotalD ,
    0 - ( s2.PurchaseLL * s.Qtys ) AS TotalLL ,
    0 - ( s2.PurchaseEuro * s.Qtys ) AS TotalEuro ,
