/****** Object:  View [Items].[v_InventoryMovementSummaryReportStockAdjustmentIn]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Items].[v_InventoryMovementSummaryReportStockAdjustmentIn]
AS
SELECT s.ID ,
    s1.DateOnly ,
    s3.Name AS Warehouse ,
    s.ItemSharedID ,
    .0 AS InitialStock ,
    .0 AS Purchases ,
    .0 AS PurchasesReturns ,
    .0 AS Sales ,
    .0 AS SalesReturns ,
    .0 AS ItemsTransferOut ,
    .0 AS ItemsTransferIn ,
    .0 AS DeliveryPermission ,
    .0 AS ProductionOrder ,
    .0 AS ProductionMaterial ,
    .0 AS StockAdjustmentOut ,
    s.Qtys AS StockAdjustmentIn ,
    .0 AS StockTakeOut ,
    .0 AS StockTakeIn
  FROM Items.t_StockAdjustmentDetail AS s
  INNER JOIN Items.v_StockAdjustment AS s1 ON s1.ID = s.StockAdjustmentID
  INNER JOIN Items.t_Item AS s2 ON s2.ID = s.ItemID
  INNER JOIN Company.t_WareHouse AS s3 ON s3.ID = s2.WareHouseID
  WHERE s.Qtys > 0;
    







GO
/****** Object:  View [Items].[v_InventoryMovementSummaryReportStockAdjustmentOut]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Items].[v_InventoryMovementSummaryReportStockAdjustmentOut]
AS
SELECT s.ID ,
    s1.DateOnly ,
    s3.Name AS Warehouse ,
    s.ItemSharedID ,
    .0 AS InitialStock ,
    .0 AS Purchases ,
    .0 AS PurchasesReturns ,
    .0 AS Sales ,
    .0 AS SalesReturns ,
    .0 AS ItemsTransferOut ,
    .0 AS ItemsTransferIn ,
    .0 AS DeliveryPermission ,
    .0 AS ProductionOrder ,
    .0 AS ProductionMaterial ,
    0 - s.Qtys AS StockAdjustmentOut ,
    .0 AS StockAdjustmentIn ,
    .0 AS StockTakeOut ,
    .0 AS StockTakeIn
  FROM Items.t_StockAdjustmentDetail AS s
  INNER JOIN Items.v_StockAdjustment AS s1 ON s1.ID = s.StockAdjustmentID
  INNER JOIN Items.t_Item AS s2 ON s2.ID = s.ItemID
  INNER JOIN Company.t_WareHouse AS s3 ON s3.ID = s2.WareHouseID
  INNER JOIN Items.t_ItemShared AS s4 ON s4.ID = s.ItemSharedID
  INNER JOIN Items.t_Brand AS s5 ON s5.ID = s4.BrandID
  INNER JOIN Items.t_MainCategory AS s6 ON s6.ID = s4.MainCategoryID
  INNER JOIN Items.t_SubCategory AS s7 ON s7.ID = s4.SubCategoryID
  WHERE s.Qtys < 0;
    







