/****** Object:  View [Company].[v_AccountChoosePersonNotBlocked44]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_AccountChoosePersonNotBlocked44]
AS
SELECT t.ID ,
    t.Name ,
    t.NumberF ,
    t.ShowInGymClass ,
    t.ShowInPersonalTrainer ,
    t.ShowInAutoPurchase ,
    FORMAT(ISNULL(t1.IDDoor, 0), N'0') AS IDDoor ,
    ISNULL(t1.IDDoor, 0) AS IDDoorN ,
    ISNULL(t1.Phones, '') AS Phones ,
    ISNULL(t1.AddressIs, '') AS AddressIs ,
    ISNULL(t1.InternalNumber, '') AS InternalNumber ,
    ISNULL(t1.DescriptionIs, '') AS DescriptionIs,
    ISNULL(t1.SalesPersonID, '00000000-0000-0000-0000-000000000000') AS SalesPersonID 
  FROM ( SELECT s.ID ,
            s.Name ,
            s.NumberIs ,
            s.NumberF ,
            s.ShowInGymClass ,
            s.ShowInPersonalTrainer ,
            s.ShowInAutoPurchase ,
            s.LinkWithID ,
            s.SectionID
          FROM Company.t_Account AS s
          WHERE s.StatusIs <> 2
       ) AS t
  LEFT JOIN Alls.v_Person AS t1 ON t1.ID = t.LinkWithID AND t1.SectionID = t.SectionID
  WHERE t.NumberIs BETWEEN 4010100000 AND 4019999999 OR t.NumberIs BETWEEN 4110100000 AND 4119999999 OR t.NumberIs BETWEEN 4210100000 AND 4219999999 OR t.NumberIs BETWEEN 4410100000 AND 4499999999 OR t.NumberIs BETWEEN 1090100000 AND 1099999999 OR t.NumberIs BETWEEN 6210100000 AND 6299999999 OR t.NumberIs BETWEEN 6410100000 AND 6999999999;
  
  



