/****** Object:  View [Currencys].[v_SchedulePaymentsList]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Currencys].[v_SchedulePaymentsList]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.NumberFromTotal ,
    t.DateOnly ,
    t.PaymentDate ,
    t.AccountID ,
    t.CurrencyID ,
    t.Amount ,
    t.AmountF ,
    t.AmountD ,
    t.AmountLL ,
    t.AmountEuro ,
    t.DescriptionIs ,
    t.SourceType ,
    t.SourceID ,
    t.CreatedByUserID ,
    t.DateCreated ,
    t.StopNotification ,
    t.IsSync ,
    t1.Name AS Account ,
    t1.NumberF AS AccountNumber ,
    t1.BalanceF ,
    t1.BalanceD ,
    t1.BalanceLL ,
    t1.BalanceEuro ,
    ISNULL(t4.Phones, N'') AS Phones ,
    ISNULL(t4.AddressIs, N'') AS AddressIs ,
    ISNULL(t4.Classification, N'') AS Classification ,
    t2.Name AS Currency ,
    t2.TypeIs AS CurrencyTypeIs ,
    t2.ExchangeRate AS CurrencyExchangeRate ,
    t3.Name AS CreatedByUser ,
    ISNULL(t5.Ref, ISNULL(t6.Ref, 0)) AS SourceRef ,
    ISNULL(t5.RefF, ISNULL(t6.RefF, N'')) AS SourceRefF
  FROM Currencys.t_SchedulePayments AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID
  INNER JOIN Users.t_User AS t3 ON t3.ID = t.CreatedByUserID
  LEFT JOIN Alls.v_Person AS t4 ON t4.ID = t1.LinkWithID
  LEFT JOIN Invoices.t_Sold AS t5 ON t5.ID = t.SourceID AND t.SourceType = 1
  LEFT JOIN Invoices.t_Purchasing AS t6 ON t6.ID = t.SourceID AND t.SourceType = 2;
  





