/****** Object:  View [Invoices].[v_SoldDetailSoldItemsReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Invoices].[v_SoldDetailSoldItemsReport]
AS
SELECT 2 AS SectionType ,
    t.ID ,
    t1.Ref ,
    t1.DateOnly ,
    t1.AccountCustomerID ,
    t1.AccountCustomer ,
    ISNULL(t8.Phones, N'') AS Phones ,
    t1.SalespersonID ,
    t1.Salesperson ,
    t1.UserID ,
    t1.UserIs ,
    t1.Currency ,
    t6.TypeIs AS CurrencyType ,
    t.ItemSharedID ,
    t2.Barcode ,
    t2.Name ,
    t2.SellWithTaxF ,
    t2.WholesalePriceWithTaxF ,
    t2.DistributionPriceWithTaxF ,
    t2.GrossWeight ,
    t2.NetWeight ,
    t3.Name AS MainCategory ,
    t5.ID AS WarehouseID ,
    t5.Name AS Warehouse ,
    t.Qty ,
    t2.QtyCurrent ,
    t.QtyWithUnity ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.ProfitTotalF AS TotalProfitF ,
    t.ProfitTotalD AS TotalProfitD ,
    t.ProfitTotalLL AS TotalProfitLL ,
    t.ProfitTotalEuro AS TotalProfitEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t7 ON t7.ID = t1.AccountCustomerID
  LEFT JOIN Alls.v_Person AS t8 ON t8.ID = t7.LinkWithID
UNION ALL
SELECT 3 AS SectionType ,
    t.ID ,
    t1.Ref ,
    t1.DateOnly ,
    t1.AccountCustomerID ,
    t1.AccountCustomer ,
    ISNULL(t8.Phones, N'') AS Phones ,
    N'00000000-0000-0000-0000-000000000000' AS SalespersonID ,
    N'' AS Salesperson ,
    t1.UserID ,
    t1.UserIs ,
    t1.Currency ,
    t6.TypeIs AS CurrencyType ,
    t.ItemSharedID ,
    t2.Barcode ,
    t2.Name ,
    t2.SellWithTaxF ,
    t2.WholesalePriceWithTaxF ,
    t2.DistributionPriceWithTaxF ,
    t2.GrossWeight ,
    t2.NetWeight ,
    t3.Name AS MainCategory ,
    t5.ID AS WarehouseID ,
    t5.Name AS Warehouse ,
    0 - t.Qty AS Qty ,
    t2.QtyCurrent ,
    N'-' + t.QtyWithUnity AS QtyWithUnity ,
    N'-' + t.PriceF AS PriceF ,
    0 - t.PriceD AS PriceD ,
    0 - t.PriceLL AS PriceLL ,
    0 - t.PriceEuro AS PriceEuro ,
    N'-' + t.TotalF AS TotalF ,
    0 - t.TotalD AS TotalD ,
    0 - t.TotalLL AS TotalLL ,
    0 - t.TotalEuro AS TotalEuro ,
    N'-' + t.ProfitTotalF AS TotalProfitF ,
    0 - t.ProfitTotalD AS TotalProfitD ,
    0 - t.ProfitTotalLL AS TotalProfitLL ,
    0 - t.ProfitTotalEuro AS TotalProfitEuro
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t7 ON t7.ID = t1.AccountCustomerID
  LEFT JOIN Alls.v_Person AS t8 ON t8.ID = t7.LinkWithID;
    








GO
