/****** Object:  View [Transactions].[v_CashStatementReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Transactions].[v_CashStatementReport]
AS
SELECT t.ID ,
    t.TransactionID ,
    t.AccountID ,
    t.Account ,
    t.DateOnly ,
    t.CurrencyID ,
    t.Currency ,
    t.CurrencyTypeIs ,
    t.Credit ,
    t.CreditD ,
    t.CreditLL ,
    t.CreditEuro ,
    t.Debit ,
    t.DebitD ,
    t.DebitLL ,
    t.DebitEuro ,
    t.StatementIs ,
    t1.Ref ,
    t1.RefF ,
    t1.TypeIs AS TransactionTypeIs ,
    t1.UserID ,
    t1.UserIs ,
    t1.LinkType ,
    t1.LinkTypeSub ,
    t2.NumberIs ,
    t2.NumberF ,
    t2.Balance AS AccountBalance ,
    t2.BalanceF AS AccountBalanceF ,
    t2.BalanceD AS AccountBalanceD ,
    t2.BalanceLL AS AccountBalanceLL ,
    t2.BalanceEuro AS AccountBalanceEuro ,
    ISNULL(t3.Phones, N'') AS Phones ,
    ISNULL(COALESCE(t4.Ref, t5.Ref, t6.Ref, t7.Ref, 0), 0) AS InvoiceRef ,
    ISNULL(COALESCE(t4.RefF, t5.RefF, t6.RefF, t7.RefF, N''), N'') AS InvoiceRefF ,
    ISNULL(COALESCE(t4.CurrencyID, t5.CurrencyID, t6.CurrencyID, t7.CurrencyID, N'00000000-0000-0000-0000-000000000000'), N'00000000-0000-0000-0000-000000000000') AS InvoiceCurrencyID ,
    ISNULL(COALESCE(t4.NetIsF, t5.NetIsF, t6.NetIsF, t7.NetIsF, N''), N'') AS TotalInvoiceF ,
    ISNULL(COALESCE(t4.NetIsD, t5.NetIsD, t6.NetIsD, t7.NetIsD, 0), 0) AS TotalInvoiceD ,
    ISNULL(COALESCE(t4.NetIsLL, t5.NetIsLL, t6.NetIsLL, t7.NetIsLL, 0), 0) AS TotalInvoiceLL ,
    ISNULL(COALESCE(t4.NetIsEuro, t5.NetIsEuro, t6.NetIsEuro, t7.NetIsEuro, 0), 0) AS TotalInvoiceEuro ,
    ISNULL(COALESCE(t4.Rest, t5.NetIs - t5.FirstPayment, t6.Rest, t7.NetIs - t7.FirstPayment, 0), 0) AS InvoiceRest ,
    ISNULL(COALESCE(t4.RestD, t5.NetIsD - t5.FirstPaymentD, t6.RestD, t7.NetIsD - t7.FirstPaymentD, 0), 0) AS InvoiceRestD ,
    ISNULL(COALESCE(t4.RestLL, t5.NetIsLL - t5.FirstPaymentLL, t6.RestLL, t7.NetIsLL - t7.FirstPaymentLL, 0), 0) AS InvoiceRestLL ,
    ISNULL(COALESCE(t4.RestEuro, t5.NetIsEuro - t5.FirstPaymentEuro, t6.RestEuro, t7.NetIsEuro - t7.FirstPaymentEuro, 0), 0) AS InvoiceRestEuro
  FROM Transactions.t_TransactionDetail AS t
  INNER  JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER  JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Alls.v_Person AS t3 ON t3.ID = t2.LinkWithID AND t3.SectionID = t2.SectionID
  LEFT JOIN Invoices.t_Purchasing AS t4 ON t4.ID = t1.LinkID AND t1.LinkType = 0
  LEFT JOIN Invoices.t_PurchasingReturn AS t5 ON t5.ID = t1.LinkID AND t1.LinkType = 1
  LEFT JOIN Invoices.t_Sold AS t6 ON t6.ID = t1.LinkID AND t1.LinkType = 2
  LEFT JOIN Invoices.t_SoldReturn AS t7 ON t7.ID = t1.LinkID AND t1.LinkType = 3
  WHERE t.Balance <> 0 and t2.NumberIs BETWEEN 5310100000 AND 5310199999;
--UNION ALL
--SELECT t.ID ,
--    t.TransactionID ,
--    t.AccountID ,
--    t.Account ,
--    t.DateOnly ,
--    t.CurrencyID ,
--    t.Currency ,
--    t.CurrencyTypeIs ,
--    t.Debit ,
--    t.DebitD ,
--    t.DebitLL ,
--    t.DebitEuro ,
--    t.Credit ,
--    t.CreditD ,
--    t.CreditLL ,
--    t.CreditEuro ,
--    t.StatementIs ,
--    t1.Ref ,
--    t1.RefF ,
--    t1.TypeIs AS TransactionTypeIs ,
--    t1.UserID ,
--    t1.UserIs ,
--    t1.LinkType ,
--    t1.LinkTypeSub ,
--    t2.NumberIs ,
--    t2.NumberF ,
--    t2.Balance AS AccountBalance ,
--    t2.BalanceF AS AccountBalanceF ,
--    t2.BalanceD AS AccountBalanceD ,
--    t2.BalanceLL AS AccountBalanceLL ,
--    t2.BalanceEuro AS AccountBalanceEuro ,
--    N'' AS Phones ,
--    0 AS InvoiceRef ,
--    N'' AS InvoiceRefF ,
--    N'00000000-0000-0000-0000-000000000000' AS InvoiceCurrencyID ,
--    N'' AS TotalInvoiceF ,
--    0 AS TotalInvoiceD ,
--    0 AS TotalInvoiceLL ,
--    0 AS TotalInvoiceEuro ,
--    0 AS InvoiceRest ,
--    0 AS InvoiceRestD ,
--    0 AS InvoiceRestLL ,
--    0 AS InvoiceRestEuro
--  FROM Transactions.t_TransactionDetail AS t
--  INNER  JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
--  INNER  JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
--  WHERE t2.NumberIs BETWEEN 5310100000 AND 5310199999 AND t.Balance < 0;







