CREATE VIEW [Quotations].[v_QuotationReport]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.RefPaper ,
    t.DateIs ,
    t.AccountID ,
    t2.Name AS Account ,
    t1.NumberF AS AccountNumberF ,
    t1.BalanceF ,
    ISNULL(t2.ID, N'00000000-0000-0000-0000-000000000000') AS PersonID ,
    N' ' + ISNULL(t2.Phones, N'') AS Phones ,
    N' ' + ISNULL(t2.FullPhones, N'') AS FullPhones ,
    ISNULL(t2.SocialMedia, N'') AS SocialMedia ,
    ISNULL(t2.AddressIs, N'') AS AddressIs ,
    ISNULL(t2.Title, N'') AS Title ,
    ISNULL(t2.NumberCurrency, N'') AS NumberCurrency ,
    ISNULL(t2.DescriptionIs, N'') AS AccountDescription ,
    t3.Name + ' ' + t3.Phones AS Salesperson ,
    t.AttentionTo ,
    t.SubjectIs ,
    t.CurrencyID ,
    t4.Name AS Currency ,
    t.ExchangeRate ,
    t.ExchangeRateLL ,
    t.ExchangeRateEuro ,
    t4.ExchangeRateTax ,
    t.Total ,
    t.TotalF ,
    t.DiscountIs ,
    t.DiscountIsF ,
    t.TaxRate ,
    t.TaxRateF ,
    t.TaxValue ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.NetIs ,
    t.NetIsF ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    t.NetIsAR ,
    t.NetIsEN ,
    t.GhanaSystem ,
    t.GS_Covid19Rate ,
    t.GS_NHILRate ,
    t.GS_GetfundLevyRate ,
    t.GS_TaxRate ,
    t.GS_Reverse ,
    t.DescriptionIs ,
    t.Qtys ,
    t.ItemHaveDiscount ,
    t5.Name AS CreatedBy
  FROM Quotations.t_Quotation AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  LEFT JOIN Alls.v_Person AS t2 ON t1.SectionID = t2.SectionID AND t2.ID = t1.LinkWithID
  LEFT JOIN Employees.t_SalesPerson AS t3 ON t3.ID = t.SalespersonID
  INNER JOIN Currencys.t_Currency AS t4 ON t4.ID = t.CurrencyID
  INNER JOIN Users.t_User AS t5 ON t5.ID = t.CreatedByID;






GO
