CREATE VIEW [Quotations].[v_QuotationHistoryReport]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.RefPaper ,
    t.DateIs ,
    t2.Name AS Account ,
    t1.NumberF AS AccountNumberF ,
    t1.BalanceF ,
    N' ' + ISNULL(t2.Phones, N'') AS Phones ,
    N' ' + ISNULL(t2.FullPhones, N'') AS FullPhones ,
    ISNULL(t2.SocialMedia, N'') AS SocialMedia ,
    ISNULL(t2.AddressIs, N'') AS AddressIs ,
    ISNULL(t2.Title, N'') AS Title ,
    ISNULL(t2.NumberCurrency, N'') AS NumberCurrency ,
    ISNULL(t2.DescriptionIs, N'') AS AccountDescription ,
    t3.Name + ' ' + t3.Phones AS Salesperson ,
    t.AttentionTo ,
    t.SubjectIs ,
    t.CurrencyID ,
    t.ExchangeRate ,
    t.ExchangeRateLL ,
    t.ExchangeRateEuro ,
    t4.ExchangeRateTax ,
    t.Total ,
    t.TotalF ,
    t.DiscountIs ,
    t.DiscountIsF ,
    t.TaxRateF ,
    t.TaxValue ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.NetIs ,
    t.NetIsF ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    t.NetIsAR ,
    t.NetIsEN ,
    t.GhanaSystem ,
    t.GS_Covid19Rate ,
    t.GS_NHILRate ,
    t.GS_GetfundLevyRate ,
    t.GS_TaxRate ,
    t.GS_Reverse ,
    t.DescriptionIs ,
    t.ItemHaveDiscount
  FROM Quotations.t_QuotationHistory AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  LEFT JOIN Alls.v_Person AS t2 ON t1.SectionID = t2.SectionID AND t2.ID = t1.LinkWithID
  INNER JOIN Employees.t_SalesPerson AS t3 ON t3.ID = t.SalespersonID
  INNER JOIN Currencys.t_Currency AS t4 ON t4.ID = t.CurrencyID;

    








