GO


CREATE VIEW [Transactions].[v_PaymentsReport]
AS
SELECT t.ID ,
    t.AccountID ,
    t.Account ,
    t.DateIs ,
    t.DateOnly ,
    t.CurrencyID ,
    t.Currency ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.StatementIs ,
    t1.Ref ,
    t1.RefF ,
    t1.UserIs ,
    t2.Name ,
    ISNULL(t3.Phones, N'') AS Phones ,
    ISNULL(t3.AddressIs, N'') AS AddressIs ,
    ISNULL(t4.Ref, 0) AS InvoiceRef ,
    ISNULL(t4.RefF, N'0') AS InvoiceRefF
  FROM Transactions.t_TransactionDetail AS t
  INNER  JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER  JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Alls.v_Person AS t3 ON t3.ID = t2.LinkWithID
  LEFT JOIN Invoices.t_Purchasing AS t4 ON t4.ID = t1.LinkID
  WHERE t1.TypeIs = N'PV' AND t.Debit > 0;





