    t.PaidUpEuro ,
    t.Rest ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro ,
    1 AS NumberOfInvoices
  FROM Invoices.t_Sold AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountCustomerID
  LEFT JOIN Alls.v_Person AS t2 ON t2.ID = t1.LinkWithID
UNION ALL
SELECT t.ID ,
    1 AS RowIn ,
    t.DateOnly ,
    t.AccountCustomerID ,
    t.AccountCustomer ,
    ISNULL(t2.Phones, N'') AS Phones ,
    t.CurrencyID ,
    0 - t.NetIs ,
    0 - t.NetIsD ,
    0 - t.NetIsLL ,
    0 - t.NetIsEuro ,
    0 - t.PaidUp ,
    0 - t.PaidUpD ,
    0 - t.PaidUpLL ,
    0 - t.PaidUpEuro ,
    0 - t.Rest ,
    0 - t.RestD ,
    0 - t.RestLL ,
    0 - t.RestEuro ,
    -1 AS NumberOfInvoices
  FROM Invoices.t_SoldReturn AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountCustomerID
  LEFT JOIN Alls.v_Person AS t2 ON t2.ID = t1.LinkWithID;
  
  

