/****** Object:  View [Invoices].[v_PurchasedItemsReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_PurchasedItemsReport]
AS
SELECT 0 AS SectionType ,
    t.ID ,
    t1.RefF ,
    t1.DateIs ,
    t1.DateOnly ,
    t1.AccountVendor AS Account ,
    ISNULL(t8.Phones, N'') AS Phones ,
    t1.UserIs ,
    t1.Currency ,
    t6.TypeIs AS CurrencyType ,
    t2.Barcode ,
    t2.Name ,
    t2.QtyCurrentByUnit ,
    t3.Name AS MainCategory ,
    t5.Name AS Warehouse ,
    t.Qty ,
    t.QtyWithUnity ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.DiscountIs ,
    t.DiscountIsF ,
    t.DiscountIsValue / t.Qty AS UnitDiscount ,
    t.DiscountIsValueD / t.Qty AS UnitDiscountD ,
    t.DiscountIsValueLL / t.Qty AS UnitDiscountLL ,
    t.DiscountIsValueEuro / t.Qty AS UnitDiscountEuro ,
    t.DiscountIsValueF AS TotalDiscountF ,
    t.DiscountIsValueD AS TotalDiscountD ,
    t.DiscountIsValueLL AS TotalDiscountLL ,
    t.DiscountIsValueEuro AS TotalDiscountEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t7 ON t7.ID = t1.AccountVendorID
  LEFT JOIN Alls.v_Person AS t8 ON t8.ID = t7.LinkWithID
UNION ALL
SELECT 1 AS SectionType ,
    t.ID ,
    t1.RefF ,
    t1.DateIs ,
    t1.DateOnly ,
    t1.AccountVendor AS Account ,
    ISNULL(t8.Phones, N'') AS Phones ,
    t1.UserIs ,
    t1.Currency ,
    t6.TypeIs AS CurrencyType ,
    t2.Barcode ,
    t2.Name ,
    t2.QtyCurrentByUnit ,
    t3.Name AS MainCategory ,
    t5.Name AS Warehouse ,
    ISNULL(0 - t.Qty, 0.0) AS Qty ,
    N'-' + t.QtyWithUnity AS QtyWithUnity ,
    N'-' + t.PriceF AS PriceF ,
    0 - t.PriceD AS PriceD ,
    0 - t.PriceLL AS PriceLL ,
    0 - t.PriceEuro AS PriceEuro ,
    t.DiscountIs ,
    t.DiscountIsF ,
    t.DiscountIsValue / t.Qty AS UnitDiscount ,
    t.DiscountIsValueD / t.Qty AS UnitDiscountD ,
    t.DiscountIsValueLL / t.Qty AS UnitDiscountLL ,
    t.DiscountIsValueEuro / t.Qty AS UnitDiscountEuro ,
    t.DiscountIsValueF AS TotalDiscountF ,
    t.DiscountIsValueD AS TotalDiscountD ,
    t.DiscountIsValueLL AS TotalDiscountLL ,
    t.DiscountIsValueEuro AS TotalDiscountEuro ,
    N'-' + t.TotalF AS TotalF ,
    0 - t.TotalD AS TotalD ,
    0 - t.TotalLL AS TotalLL ,
    0 - t.TotalEuro AS TotalEuro
  FROM Invoices.t_PurchasingReturnDetail AS t
  INNER JOIN Invoices.t_PurchasingReturn AS t1 ON t1.ID = t.PurchasingReturnID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t7 ON t7.ID = t1.AccountVendorID
  LEFT JOIN Alls.v_Person AS t8 ON t8.ID = t7.LinkWithID;
    

	




GO
