    ISNULL(t4.InternalNumber, N'') AS Reference ,
    ISNULL(t4.ClassificationID, N'00000000-0000-0000-0000-000000000000') AS ClassificationID ,
    ISNULL(t4.Classification, N'') AS Classification ,
    FORMAT(ISNULL(t4.IDDoor, 0), N'#') AS IDDoor ,
    t5.Name AS DeliveryByEmployee
  FROM Invoices.t_Sold AS t
  LEFT JOIN Company.t_Account AS t1 ON t1.ID = t.NonTaxableAccountID
  LEFT JOIN Company.t_Account AS t2 ON t2.ID = t.TaxableAccountID
  INNER JOIN Company.t_Account AS t3 ON t3.ID = t.AccountCustomerID
  LEFT JOIN Alls.v_Person AS t4 ON t4.ID = t3.LinkWithID
  INNER JOIN Employees.t_Employee AS t5 ON t5.ID = t.DeliveryByEmployeeID;

  



