/****** Object:  View [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportSalary]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportSalary]
AS
SELECT t.ID ,
    t.DateOnly ,
    t.AccountID ,
    ISNULL(t4.Name, N'') AS Account ,
    t.CurrencyID ,
    t1.Name AS Currency ,
    t.DebitD - t.CreditD AS TotalD ,
    t.DebitLL - t.CreditLL AS TotalLL ,
    t.DebitEuro - t.CreditEuro AS TotalEuro
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Company.t_AccountLevel3 AS t3 ON t3.ID = t2.Level3ID
  LEFT JOIN Alls.v_Person AS t4 ON t4.ID = t2.LinkWithID
  WHERE t3.NumberIs BETWEEN 63101 AND 63199;
    




