/****** Object:  View [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportSaleItem]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportSaleItem]
AS
SELECT t.ID ,
    t1.DateOnly ,
    t5.Name AS Account ,
    t.ItemSharedID ,
    t4.Name ,
    t1.CurrencyID ,
    t2.Name AS Currency ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.ProfitTotalD AS ProfitD ,
    t.ProfitTotalLL AS ProfitLL ,
    t.ProfitTotalEuro AS ProfitEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t3 ON t3.ID = t1.AccountCustomerID
  INNER JOIN Items.t_ItemShared AS t4 ON t4.ID = t.ItemSharedID
  LEFT JOIN Alls.v_Person AS t5 ON t5.ID = t3.LinkWithID
UNION ALL
SELECT t.ID ,
    t1.DateOnly ,
    t5.Name AS Account ,
    t.ItemSharedID ,
    t4.Name ,
    t1.CurrencyID ,
    t2.Name AS Currency ,
    0 - t.TotalD AS TotalD ,
    0 - t.TotalLL AS TotalLL ,
    0 - t.TotalEuro AS TotalEuro ,
    0 - t.ProfitTotalD AS ProfitD ,
    0 - t.ProfitTotalLL AS ProfitLL ,
    0 - t.ProfitTotalEuro AS ProfitEuro
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t3 ON t3.ID = t1.AccountCustomerID
  INNER JOIN Items.t_ItemShared AS t4 ON t4.ID = t.ItemSharedID
  LEFT JOIN Alls.v_Person AS t5 ON t5.ID = t3.LinkWithID;
  







