/****** Object:  View [Items].[v_InventoryMovementSummaryReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_InventoryMovementSummaryReport]
AS
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
    SUM(t.ItemsTransferOut) AS ItemsTransferOut ,
    SUM(t.ItemsTransferIn) AS ItemsTransferIn ,
    SUM(t.DeliveryPermission) AS DeliveryPermission ,
    SUM(t.ProductionOrder) AS ProductionOrder ,
    SUM(t.ProductionMaterial) AS ProductionMaterial ,
    SUM(t.StockAdjustmentOut) AS StockAdjustmentOut ,
    SUM(t.StockAdjustmentIn) AS StockAdjustmentIn ,
    SUM(t.StockTakeOut) AS StockTakeOut ,
    SUM(t.StockTakeIn) AS StockTakeIn
  FROM Items.v_InventoryMovementSummaryReportInitialStock AS t
  GROUP BY t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID
UNION ALL
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
    SUM(t.ItemsTransferOut) AS ItemsTransferOut ,
    SUM(t.ItemsTransferIn) AS ItemsTransferIn ,
    SUM(t.DeliveryPermission) AS DeliveryPermission ,
    SUM(t.ProductionOrder) AS ProductionOrder ,
    SUM(t.ProductionMaterial) AS ProductionMaterial ,
    SUM(t.StockAdjustmentOut) AS StockAdjustmentOut ,
    SUM(t.StockAdjustmentIn) AS StockAdjustmentIn ,
    SUM(t.StockTakeOut) AS StockTakeOut ,
    SUM(t.StockTakeIn) AS StockTakeIn
  FROM Items.v_InventoryMovementSummaryReportPurchases AS t
  GROUP BY t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID
UNION ALL
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
    SUM(t.ItemsTransferOut) AS ItemsTransferOut ,
    SUM(t.ItemsTransferIn) AS ItemsTransferIn ,
    SUM(t.DeliveryPermission) AS DeliveryPermission ,
    SUM(t.ProductionOrder) AS ProductionOrder ,
    SUM(t.ProductionMaterial) AS ProductionMaterial ,
    SUM(t.StockAdjustmentOut) AS StockAdjustmentOut ,
    SUM(t.StockAdjustmentIn) AS StockAdjustmentIn ,
    SUM(t.StockTakeOut) AS StockTakeOut ,
    SUM(t.StockTakeIn) AS StockTakeIn
  FROM Items.v_InventoryMovementSummaryReportPurchasesReturns AS t
  GROUP BY t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID
UNION ALL
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
    SUM(t.ItemsTransferOut) AS ItemsTransferOut ,
    SUM(t.ItemsTransferIn) AS ItemsTransferIn ,
    SUM(t.DeliveryPermission) AS DeliveryPermission ,
    SUM(t.ProductionOrder) AS ProductionOrder ,
    SUM(t.ProductionMaterial) AS ProductionMaterial ,
    SUM(t.StockAdjustmentOut) AS StockAdjustmentOut ,
    SUM(t.StockAdjustmentIn) AS StockAdjustmentIn ,
    SUM(t.StockTakeOut) AS StockTakeOut ,
    SUM(t.StockTakeIn) AS StockTakeIn
  FROM Items.v_InventoryMovementSummaryReportSales AS t
  GROUP BY t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID
UNION ALL
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
    SUM(t.ItemsTransferOut) AS ItemsTransferOut ,
    SUM(t.ItemsTransferIn) AS ItemsTransferIn ,
    SUM(t.DeliveryPermission) AS DeliveryPermission ,
    SUM(t.ProductionOrder) AS ProductionOrder ,
    SUM(t.ProductionMaterial) AS ProductionMaterial ,
    SUM(t.StockAdjustmentOut) AS StockAdjustmentOut ,
    SUM(t.StockAdjustmentIn) AS StockAdjustmentIn ,
    SUM(t.StockTakeOut) AS StockTakeOut ,
    SUM(t.StockTakeIn) AS StockTakeIn
  FROM Items.v_InventoryMovementSummaryReportSalesReturns AS t
  GROUP BY t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID
UNION ALL
SELECT t.DateOnly ,
    t.Warehouse ,
    t.ItemSharedID ,
    SUM(t.InitialStock) AS InitialStock ,
    SUM(t.Purchases) AS Purchases ,
    SUM(t.PurchasesReturns) AS PurchasesReturns ,
    SUM(t.Sales) AS Sales ,
    SUM(t.SalesReturns) AS SalesReturns ,
