/****** Object:  View [Invoices].[v_SoldNotifications]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_SoldNotifications]
AS
SELECT 2 AS SectionID ,
    N'00000002-0001-0000-0000-' + FORMAT(t.Ref, N'000000000000') AS ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DeliveryDueDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'يجب توصيل هذه الفاتورة اليوم' AS TextAR ,
    N'This invoice must be delivered today' AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'1' AS MyNote ,
    CONVERT(IMAGE, NULL) AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Invoices.t_Sold AS t
  WHERE t.DeliveryStage BETWEEN 1 AND 2 AND t.DeliveryDueDate = DateTimes.f_GetToday()
UNION ALL
SELECT 2 AS SectionID ,
    N'00000002-0002-0000-0000-' + FORMAT(t.Ref, N'000000000000') AS ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DeliveryDueDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'لقد تأخرنا في توصيل توصيل هذه الفاتورة' AS TextAR ,
    N'We are late in delivering this invoice' AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'2' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Invoices.t_Sold AS t
  WHERE t.DeliveryStage BETWEEN 1 AND 2 AND t.DeliveryDueDate < DateTimes.f_GetToday()
UNION ALL
SELECT 2 AS SectionID ,
    N'00000002-0003-0000-0000-' + FORMAT(t.Ref, N'000000000000') AS ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DueDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'يجب على ' + t.AccountCustomer + N' أن يدفع ' + t.RestF AS TextAR ,
    t.AccountCustomer + N' must pay ' + t.RestF AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'3' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Invoices.t_Sold AS t
  WHERE t.Paid <> 2 AND t.Rest >= 0.01 AND t.DueDate <= DateTimes.f_GetToday();




GO
/****** Object:  View [Invoices].[v_DressesRentalNotificationWithImageThumbnail]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Invoices].[v_DressesRentalNotificationWithImageThumbnail]
AS
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.TakingMeasurementsDate ,
    N'خذ القياسات ثم اطبع (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Take Measurements then print (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 0 AND t.TakingMeasurementsDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.TailoringDate ,
    N'أرسل إلى الخياطة (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Send to the tailoring (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 1 AND t.TailoringDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DeliveryDate ,
    N'اتصل بالعميل للتسليم (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Call customer for delivery (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 2 AND t.DeliveryDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.ReceivedDate ,
    N'اتصل بالعميل للاستلام (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Call customer for receiving (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 3 AND t.ReceivedDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.CleaningDate ,
    N'أرسل إلى التنظيف (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Send to cleaning (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 4 AND t.CleaningDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.CompletionDate ,
    N'عرضه في صالة العرض (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Display in showroom stage (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageThumbnail AS ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 5 AND t.CompletionDate <= GETDATE();

 


