/****** Object:  View [Alls].[v_AllNotificationOnOnlyCustomerNewBirthday]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Alls].[v_AllNotificationOnOnlyCustomerNewBirthday]
AS
SELECT 15 AS Setion ,
    t.ID1 ,
    t.ID ,
    t.Name ,
    t.NewBirthday ,
    N'عيد ميلاد سعيد يا ' + t.Name AS TextAR ,
    N'Happy birthday to you ' + t.Name AS TextEN ,
    ~t.ShowNotificationNewBirthday AS IsStop ,
    N'NewBirthday' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Customers.t_Customer AS t
  INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
  WHERE t.StatusIs <> 2 AND t2.CustomerShowNotificationNewBirthday = 1 AND t.ShowNotificationNewBirthday = 1 AND t.DaysCloseToBirthday BETWEEN t2.CustomerDaysBeforeBirthday
                                                                                                                                       AND     t2.CustomerDaysAfterBirthday;


     






GO
/****** Object:  View [Company].[v_AccountExchangeRateDifferences]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Company].[v_AccountExchangeRateDifferences]
AS
SELECT t.ID ,
    t.NumberIs ,
    t.NumberF ,
    t.Name ,
    t.Balance ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro
  FROM Company.t_Account AS t
  INNER JOIN Company.t_AccountLevel3 AS t1 ON t1.ID = t.Level3ID AND t1.NumberIs <= 59999
  WHERE IIF(ROUND(t.Balance, 2) = 0, IIF(ROUND(t.BalanceD, 2) <> 0 OR ROUND(t.BalanceLL, 2) <> 0 OR ROUND(t.BalanceEuro, 2) <> 0, 1, 0), 0) = 1;
  




GO
/****** Object:  View [Alls].[v_AllNotificationWithImageThumbnail]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
