GO




CREATE VIEW [Alls].[v_AllNotificationWithImageThumbnail]
AS
SELECT t.SectionID ,
    t.ID ,
    t.FatherID ,
    t.RefF ,
    t.DateIs ,
    t.PeriodType ,
    t.PeriodNumber ,
    t.RepeatedInTheFuture ,
    t.Repeated ,
    t.TextAR ,
    t.TextEN ,
    t.IsStop ,
    t.MyNote ,
    t.ImageIs ,
    t.Barcode ,
    t.QtyCurrent ,
    t.QtyCurrentByUnit ,
    t.Brand ,
    t.MainCategory ,
    t.SubCategory ,
    t.VendorNames
  FROM Invoices.v_SoldNotifications AS t
UNION ALL
SELECT 4 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    t.NotificationTextAR AS TextAR ,
    t.NotificationTextEN AS TextEN ,
    t.NotificationStop AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Quotations.t_Quotation AS t
  WHERE t.NotificationDate <= DateTimes.f_GetToday() AND t.IsConfirm = 0
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.SharedID AS FatherID ,
    t1.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'نحتاج شراء ' + FORMAT(t.QtyToReorder - t.QtyCurrent, N'#,##0.##') + N' للمستودع (' + t.WareHouse + N')' AS TextAR ,
    N'We need to buy ' + FORMAT(t.QtyToReorder - t.QtyCurrent, N'#,##0.##') + N' for warehouse (' + t.WareHouse + N')' AS TextEN ,
    ~t.ShowNotificationReorder AS IsStop ,
    N'Reorder' AS MyNote ,
    t1.ImageThumbnail AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t.WareHouseID
  WHERE t1.StatusIs <> 2 AND t2.IsEnable = 1 AND t.QtyToReorder > 0 AND t.QtyToReorder > t.QtyCurrent
UNION ALL
SELECT 10 AS SectionID ,
    t.ID1 ,
    t.ID AS FatherID ,
    t1.Name AS RefF ,
    t.StockTakeEveryNotificationDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'حان الوقت لإجراء جرد (' + t1.Name + ') الموجود في (' + t.WareHouse + ') في (' + t.Place + N')' AS TextAR ,
    N'It is time to do stocktake for the (' + t1.Name + ') in the (' + t.WareHouse + ') in the (' + t.Place + N')' AS TextEN ,
    ~t.ShowNotificationInventoryTime AS IsStop ,
    N'InventoryTime' AS MyNote ,
    t1.ImageThumbnail AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
