    NULL AS ImageIs ,
    t.Barcode ,
    t.CurrentQuantity AS QtyCurrent ,
    Items.f_FormatQty(t.CurrentQuantity) AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Items.t_AlternativeItems AS t
  WHERE t.QuantityToReorder > 0 AND t.QuantityToReorder > t.CurrentQuantity;

  












