CREATE VIEW [Invoices].[v_DressesRentalNotification]
AS
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.TakingMeasurementsDate ,
    N'خذ القياسات ثم اطبع (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Take Measurements then print (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    t1.ImageIs
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 0 AND t.TakingMeasurementsDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
