  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 3 AND t.ReceivedDate <= GETDATE()
UNION ALL
SELECT 214 AS SectionID ,
