    t.RefF ,
    t.CleaningDate ,
    N'أرسل إلى التنظيف (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Send to cleaning (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
