    N'عرضه في صالة العرض (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'الزبونة: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'الفستان: ' + t1.Name + N' \ ' + t1.Barcode AS TextAR ,
    N'Display in showroom stage (' + t.RefF + N')' + CHAR(13) + CHAR(10) + N'Customer: ' + t.Account + N' \ ' + t3.Phones + CHAR(13) + CHAR(10) + N'Dress: ' + t1.Name + N' \ ' + t1.Barcode AS TextEN ,
