/****** Object:  View [Alls].[v_AllNotification]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Alls].[v_AllNotification]
AS
SELECT t.SectionID ,
    t.ID ,
    t.FatherID ,
    t.RefF ,
    t.DateIs ,
    t.PeriodType ,
    t.PeriodNumber ,
    t.RepeatedInTheFuture ,
    t.Repeated ,
    t.TextAR ,
    t.TextEN ,
    t.IsStop ,
    t.MyNote ,
    NULL AS ImageIs ,
    t.Barcode ,
    t.QtyCurrent ,
    t.QtyCurrentByUnit ,
    t.Brand ,
    t.MainCategory ,
    t.SubCategory ,
    t.VendorNames
  FROM Invoices.v_SoldNotifications AS t
UNION ALL
SELECT 4 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    t.NotificationTextAR AS TextAR ,
    t.NotificationTextEN AS TextEN ,
    t.NotificationStop AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Quotations.t_Quotation AS t
  WHERE t.NotificationDate <= DateTimes.f_GetToday() AND t.IsConfirm = 0
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.SharedID AS FatherID ,
    t1.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'نحتاج شراء ' + FORMAT(t.QtyToReorder - t.QtyCurrent, N'#,##0.##') + N' للمستودع (' + t.WareHouse + N')' AS TextAR ,
    N'We need to buy ' + FORMAT(t.QtyToReorder - t.QtyCurrent, N'#,##0.##') + N' for warehouse (' + t.WareHouse + N')' AS TextEN ,
    ~t.ShowNotificationReorder AS IsStop ,
    N'Reorder' AS MyNote ,
    NULL AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t.WareHouseID
  WHERE t1.StatusIs <> 2 AND t2.IsEnable = 1 AND t.QtyToReorder > 0 AND t.QtyToReorder > t.QtyCurrent
UNION ALL
SELECT 10 AS SectionID ,
    t.ID1 ,
    t.ID AS FatherID ,
    t1.Name AS RefF ,
    t.StockTakeEveryNotificationDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'حان الوقت لإجراء جرد (' + t1.Name + ') الموجود في (' + t.WareHouse + ') في (' + t.Place + N')' AS TextAR ,
    N'It is time to do stocktake for the (' + t1.Name + ') in the (' + t.WareHouse + ') in the (' + t.Place + N')' AS TextEN ,
    ~t.ShowNotificationInventoryTime AS IsStop ,
    N'InventoryTime' AS MyNote ,
    NULL AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  WHERE t1.StatusIs <> 2 AND t.StockTakeEveryNotificationDate <= DateTimes.f_GetToday() AND t.StockTakeEvery > 0
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'هذا الصنف غير نشط' TextAR ,
    N'This item is not active' TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'ItemShared' AS MyNote ,
    NULL AS ImageIs ,
    t.Barcode ,
    t.QtyCurrent ,
    t.QtyCurrentByUnit ,
    t.Brand ,
    t.MainCategory ,
    t.SubCategory ,
    t.VendorNames
  FROM Items.t_ItemShared AS t
  WHERE t.StatusIs = 1
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'لا توجد تكلفة للصنف' AS TextAR ,
    N'There is no cost for the item' AS TextEN ,
    ~t.ShowNotificationNoCost AS IsStop ,
    N'NoCost' AS MyNote ,
    NULL AS ImageIs ,
    t.Barcode ,
    t.QtyCurrent ,
    t.QtyCurrentByUnit ,
    t.Brand ,
    t.MainCategory ,
    t.SubCategory ,
    t.VendorNames
  FROM Items.t_ItemShared AS t
  INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
  WHERE t.StatusIs <> 2 AND t.Purchase = 0 AND t2.NotificationItemShowZeroCost = 1
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.SharedID AS FatherID ,
    t1.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'لا توجد سعر بيع لهذا الصنف' AS TextAR ,
    N'There is no sale price for this item' AS TextEN ,
    ~t.ShowNotificationNoSalePrice AS IsStop ,
    N'NoSalePrice' AS MyNote ,
    NULL AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_UnityItem AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
  WHERE t1.StatusIs <> 2 AND t1.Sell = 0 AND t1.Purchase <> 0 AND t2.NotificationItemShowZeroSale = 1
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.SharedID AS FatherID ,
    t1.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'لا يوجد ربح على ' + N' (' + t.Unity + N')' TextAR ,
    N'There is no profit on ' + N' (' + t.Unity + N')' TextEN ,
    ~t.ShowNotificationNoProfit AS IsStop ,
    N'NoProfit' AS MyNote ,
    NULL AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_UnityItem AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
  WHERE t1.StatusIs <> 2 AND t1.Purchase > 0 AND t1.Sell > 0 AND t.ProfitRatio <= 0 AND t1.TypeIs <> 1 AND t1.Rentable = 0
UNION ALL
SELECT 37 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'يوجد فروقات سعر الصرف بالحساب' AS TextAR ,
    N'There are exchange rate differences in the account' AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Company.v_AccountExchangeRateDifferences AS t
UNION ALL
SELECT 48 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.PaymentDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'يجب تحصيل دفعة بقيمة ' + t.AmountF + N' من ' + t1.Name + N'.' AS TextAR ,
    N'A payment of ' + t.AmountF + N' must be collected from ' + t1.Name + N'.' AS TextEN ,
    t.StopNotification AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Currencys.t_SchedulePayments AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  WHERE t.Amount > 0 AND t.PaymentDate <= DateTimes.f_GetToday()
UNION ALL
SELECT 48 AS SectionID ,
    t.ID ,
    t.ID AS FatherID ,
    t.RefF ,
    t.PaymentDate AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'يجب إرسال دفعة بقيمة ' + t.AmountF + N' إلى ' + t1.Name + N'.' AS TextAR ,
    N'A payment of ' + t.AmountF + N' must be sent to ' + t1.Name + N'.' AS TextEN ,
    t.StopNotification AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Currencys.t_SchedulePayments AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  WHERE t.Amount < 0 AND t.PaymentDate <= DateTimes.f_GetToday()
UNION ALL
SELECT 65 ,
    t.ID ,
    t.TransactionID ,
    t1.RefF ,
    t1.DateOnly ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    t.NotificationTextAR ,
    t.NotificationTextEN ,
    t.ChequeStopNotificationGet ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Transactions.t_TransactionDetail AS t
  LEFT JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  WHERE t.TypeIs = 1 AND t.ChequeDateGet <= DateTimes.f_GetToday() AND t1.TypeIs = 'JV'
UNION ALL
SELECT 168 ,
    t.ID ,
    t.ItemSharedID ,
    t.RefF ,
    t.NotificationDate ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    CASE WHEN t.ExpirationDate < DateTimes.f_GetToday() THEN N'إنتهت صلاحية ' + t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + ' في ' + FORMAT(t.ExpirationDate, 'dd-MM-yyyy')
         WHEN t.ExpirationDate = DateTimes.f_GetToday() THEN N'ستنتهي صلاحية ' + t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + ' اليوم'
         ELSE N'سوف تنتهي صلاحية ' + t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + ' في ' + FORMAT(t.ExpirationDate, 'dd-MM-yyyy')
    END AS NotificationTextAR ,
    CASE WHEN t.ExpirationDate < DateTimes.f_GetToday() THEN t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + N' has expired in ' + FORMAT(t.ExpirationDate, 'dd-MM-yyyy')
         WHEN t.ExpirationDate = DateTimes.f_GetToday() THEN t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + N' will expire today '
         ELSE t1.Name + FORMAT(t.Qtys, N' x#,##0.####') + N' will expire in ' + FORMAT(t.ExpirationDate, 'dd-MM-yyyy')
    END AS NotificationTextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
    NULL AS ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames
  FROM Items.t_ItemExpirationDate AS t
  LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  WHERE t.NotificationDate <= DateTimes.f_GetToday()
UNION ALL
SELECT 174 ,
    t.ID ,
    t.ID ,
    t.RefF ,
    t.DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'تجاوز عدد أيام الحضور ' + FORMAT(t.TotalDaysAttended, N'0') + N'\' + FORMAT(t.TotalSubscriptionDays, N'0') AS TextAR ,
    N'Exceeded number of attendance days ' + FORMAT(t.TotalDaysAttended, N'0') + N'\' + FORMAT(t.TotalSubscriptionDays, N'0') AS TextEN ,
    CONVERT(BIT, 0) AS IsStop ,
    N'' AS MyNote ,
