    N'' AS Barcode ,
    0.0 AS QtyCurrent ,
    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Gym.t_GymSubscription AS t
  WHERE t.TotalSubscriptionDays > 0 AND t.RemainingDays < 0
UNION ALL
SELECT 72 ,
    t.ID ,
    t.ID ,
    t.Name ,
    t.ExpirationDate ,
