    N'' AS QtyCurrentByUnit ,
    N'' AS Brand ,
    N'' AS MainCategory ,
    N'' AS SubCategory ,
    N'' AS VendorNames
  FROM Company.t_Cheque AS t
  WHERE t.NotificationDate <= DateTimes.f_GetToday()
UNION ALL
SELECT 96 ,
    t.ID ,
    t.TransactionID ,
    t1.RefF ,
    t1.DateOnly ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
