    N'It is time to do stocktake for the (' + t1.Name + ') in the (' + t.WareHouse + ') in the (' + t.Place + N')' AS TextEN ,
    ~t.ShowNotificationInventoryTime AS IsStop ,
    N'InventoryTime' AS MyNote ,
    t1.ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
    t1.MainCategory ,
