  FROM Items.t_UnityItem AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
  WHERE t1.StatusIs <> 2 AND t1.Sell = 0 AND t1.Purchase <> 0 AND t2.NotificationItemShowZeroSale = 1
UNION ALL
SELECT 10 AS SectionID ,
    t.ID ,
    t.SharedID AS FatherID ,
    t1.Name AS RefF ,
    DateTimes.f_GetToday() AS DateIs ,
    CONVERT(TINYINT, 255) AS PeriodType ,
    0 AS PeriodNumber ,
    CONVERT(BIT, 0) AS RepeatedInTheFuture ,
    CONVERT(BIT, 0) AS Repeated ,
    N'لا يوجد ربح على ' + N' (' + t.Unity + N')' TextAR ,
