    ~t.ShowNotificationNoProfit AS IsStop ,
    N'NoProfit' AS MyNote ,
    t1.ImageIs ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.Brand ,
