/****** Object:  View [Transactions].[v_TransactionDetailStatement]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Transactions].[v_TransactionDetailStatement]
AS
SELECT t.ID ,
    t.RowNumber ,
    t.TransactionID ,
    t1.Ref ,
    t1.RefF ,
    t1.LegalRef ,
    t1.LegalRefF ,
    t1.PaperRef ,
    ISNULL(t3.RefF, N'') AS LinkRefF ,
    t.DateIs ,
    t.DateOnly ,
    t1.TypeIs AS TransactionType ,
    t1.LinkType ,
    t1.LinkTypeSub ,
    t1.LinkID ,
    t.AccountID ,
    t2.Name AS Account ,
    t2.CurrencyID AS AccountCurrencyID ,
    t2.CurrencyTypeIs AS AccountCurrencyType ,
    t.CurrencyID ,
    t.CurrencyTypeIs ,
    t.BalanceF ,
    t.Balance ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.Credit ,
    t.CreditD ,
    t.CreditLL ,
    t.CreditEuro ,
    t.Debit ,
    t.DebitD ,
    t.DebitLL ,
    t.DebitEuro ,
    t.StatementIs ,
    t.TypeIs ,
    t.ChequeNumber ,
    t.ChequeDateGet ,
    t.ChequeStopNotificationGet
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Invoices.v_InvoiceAllShort AS t3 ON t3.SectionID = t1.LinkType AND t3.ID = t1.LinkID;















