CREATE VIEW [Transactions].[v_TransactionDetailStatementLinkSort]
AS
SELECT t.ID ,
    t.TransactionID ,
    t1.Ref ,
    t1.RefF ,
    t1.LegalRef ,
    t1.LegalRefF ,
    t1.PaperRef ,
    ISNULL(t3.RefF, N'') AS LinkRefF ,
    ISNULL(t3.DateIs, t.DateIs) AS DateIs ,
    ISNULL(ISNULL(t3.DateOnly, t.DateOnly), GETDATE()) AS DateOnly ,
    t1.TypeIs AS TransactionType ,
    t1.LinkType ,
    t1.LinkTypeSub ,
    t1.LinkID ,
    t.AccountID ,
    t2.CurrencyID AS AccountCurrencyID ,
    t2.CurrencyTypeIs AS AccountCurrencyType ,
    t.CurrencyID ,
    t.CurrencyTypeIs ,
    t.Balance ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.Credit ,
    t.CreditD ,
    t.CreditLL ,
    t.CreditEuro ,
    t.Debit ,
    t.DebitD ,
    t.DebitLL ,
    t.DebitEuro ,
    t.StatementIs ,
    t.TypeIs ,
    t.ChequeNumber ,
    t.ChequeDateGet ,
    t.ChequeStopNotificationGet
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Invoices.v_InvoiceAllShort AS t3 ON t3.SectionID = t1.LinkType AND t3.ID = t1.LinkID;
  








