CREATE VIEW [Company].[v_CallsAllList]
AS
SELECT t.ID ,
    0 AS RowStatus ,
    t.Ref ,
    t.RefF ,
    t.CallsTypesID ,
    t.DateTimeIs ,
    t.ReceivedFromNumber ,
    t.CallerNumber ,
    t.Notes ,
    t.SourceType ,
    t.IsSync ,
    t1.Name AS CallsTypes ,
    ISNULL(t2.OwnerID, N'00000000-0000-0000-0000-000000000000') AS OwnerID ,
    ISNULL(t2.Name, N'') AS Customer ,
    ISNULL(t2.AddressIs, N'') AS CustomerAddress ,
    ISNULL(t2.Phones, N'') AS CustomerPhones ,
    ISNULL(t2.SectionID, 69) AS SectionID ,
    ISNULL(t3.ID, N'00000000-0000-0000-0000-000000000000') AS InvoiceID ,
    ISNULL(t3.Ref, 0) AS InvoiceRef ,
    ISNULL(t3.RefF, N'') AS InvoiceRefF ,
    ISNULL(t3.NetIs, 0) AS InvoiceNetIs ,
    ISNULL(t3.NetIsF, N'') AS InvoiceNetIsF ,
    ISNULL(t3.NetIsD, 0) AS InvoiceNetIsD ,
    ISNULL(t3.NetIsLL, 0) AS InvoiceNetIsLL ,
    ISNULL(t3.NetIsEuro, 0) AS InvoiceNetIsEuro
  FROM Company.t_Calls AS t
  INNER JOIN Company.t_CallsTypes AS t1 ON t1.ID = t.CallsTypesID
  LEFT JOIN Company.v_BookPhone AS t2 ON t2.NumberIs = t.CallerNumber
  LEFT JOIN Invoices.t_Sold AS t3 ON t3.LinkID = t.ID AND t3.SaveFromSection = 7
UNION ALL
SELECT t.ID ,
    1 AS RowStatus ,
    t.Ref ,
    t.RefF ,
    t.CallsTypesID ,
    t.DateTimeIs ,
    t.ReceivedFromNumber ,
    t.CallerNumber ,
    t.Notes ,
    t.SourceType ,
    t.IsSync ,
    t1.Name AS CallsTypes ,
    ISNULL(t2.OwnerID, N'00000000-0000-0000-0000-000000000000') AS OwnerID ,
    ISNULL(t2.Name, N'') AS Customer ,
    ISNULL(t2.AddressIs, N'') AS CustomerAddress ,
    ISNULL(t2.Phones, N'') AS CustomerPhones ,
    ISNULL(t2.SectionID, 69) AS SectionID ,
    ISNULL(t3.ID, N'00000000-0000-0000-0000-000000000000') AS InvoiceID ,
    ISNULL(t3.Ref, 0) AS InvoiceRef ,
    ISNULL(t3.RefF, N'') AS InvoiceRefF ,
    ISNULL(t3.NetIs, 0) AS InvoiceNetIs ,
    ISNULL(t3.NetIsF, N'') AS InvoiceNetIsF ,
    ISNULL(t3.NetIsD, 0) AS InvoiceNetIsD ,
    ISNULL(t3.NetIsLL, 0) AS InvoiceNetIsLL ,
    ISNULL(t3.NetIsEuro, 0) AS InvoiceNetIsEuro
  FROM Company.t_CallsArchive AS t
  INNER JOIN Company.t_CallsTypes AS t1 ON t1.ID = t.CallsTypesID
  LEFT JOIN Company.v_BookPhone AS t2 ON t2.NumberIs = t.CallerNumber
  LEFT JOIN Invoices.t_Sold AS t3 ON t3.LinkID = t.ID AND t3.SaveFromSection = 7;
  
  





