/****** Object:  View [Invoices].[v_DeliveryServiceSumDeliveryChargeLast6DaysD]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_DeliveryServiceSumDeliveryChargeLast6DaysD]
AS
    SELECT  t.DateOnly ,
            SUM(t1.DeliveryChargeD) AS DeliveryCharge ,
            COUNT(*) AS CountIs
    FROM    ( SELECT DISTINCT TOP ( 6 )
                        s.DateOnly
              FROM      Invoices.v_DeliveryServiceAll AS s
              ORDER BY  s.DateOnly DESC
            ) AS t
            LEFT JOIN Invoices.v_DeliveryServiceAll AS t1 ON t1.DateOnly = t.DateOnly
    WHERE   t1.StatusIs <> 5
    GROUP BY t.DateOnly;



GO
