CREATE VIEW [Alls].[v_WhatsAppLogsArchivesList]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.SentDate ,
    t.SentDateOnly ,
    t.SentDateMonthly ,
    t.SentDateYearly ,
    t.SectionID ,
    t.PersonID ,
    t.Person ,
    t.ToPhone ,
    t.MessageText ,
    t.ReplyToUs ,
    t.ClassificationType ,
    t.CreatedByUserID ,
    t.DateCreated ,
    t.IsSync ,
    t1.Name AS CreatedByUser ,
    ISNULL(ISNULL(t2.Name, t.Person), N'') AS Name ,
    ISNULL(t2.Phones, t.ToPhone) AS Phones ,
    ISNULL(t2.AddressIs, '') AS AddressIs ,
    ISNULL(t2.TitleID, '00000000-0000-0000-0000-000000000000') AS TitleID ,
    ISNULL(t2.Title, '') AS Title ,
    ISNULL(t2.ClassificationID, '00000000-0000-0000-0000-000000000000') AS ClassificationID ,
    ISNULL(t2.Classification, '') AS Classification ,
    ISNULL(t2.StatesID, '00000000-0000-0000-0000-000000000000') AS StatesID ,
    ISNULL(t2.StatesIs, '') AS StatesIs ,
    ISNULL(t2.RegionID, '00000000-0000-0000-0000-000000000000') AS RegionID ,
    ISNULL(t2.RegionIs, '') AS RegionIs ,
    ISNULL(t2.StreetID, '00000000-0000-0000-0000-000000000000') AS StreetID ,
    ISNULL(t2.Street, '') AS Street ,
    ISNULL(t3.BalanceF, '0') AS BalanceF ,
    ISNULL(t3.BalanceD, 0) AS BalanceD ,
    ISNULL(t3.BalanceLL, 0) AS BalanceLL ,
    ISNULL(t3.BalanceEuro, 0) AS BalanceEuro
  FROM Alls.t_WhatsAppLogsArchives AS t
  INNER JOIN Users.t_User AS t1 ON t1.ID = t.CreatedByUserID
  LEFT JOIN Alls.v_Person1 AS t2 ON t2.ID = t.PersonID AND t2.SectionID = t.SectionID
  LEFT JOIN Company.t_Account AS t3 ON t3.LinkWithID = t.PersonID AND t3.SectionID = t.SectionID AND t3.IsMasterLink = 1;
  





GO
