SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_ItemSoldQuantityReport]
AS
SELECT t3.DateIs ,
    t.ItemSharedID ,
    t2.Name ,
    t2.Barcode ,
    t.Qtys ,
    t3.Currency ,
    t.CostD * t.Qty AS TotalCostD ,
    t.CostLL * t.Qty AS TotalCostLL ,
    t.CostEuro * t.Qty AS TotalCostEuro ,
    t.SubTotal2D ,
    t.SubTotal2LL ,
    t.SubTotal2Euro ,
    t.ProfitTotalD AS TotalProfitD ,
    t.ProfitTotalLL AS TotalProfitLL ,
    t.ProfitTotalEuro AS TotalProfitEuro ,
    t.SerialNames ,
    t.VendorName ,
    t2.Brand ,
    t2.VendorNames AS Vendors ,
    t3.UserIs ,
    t3.Salesperson ,
    t3.AccountCustomer ,
    t2.MainCategory ,
    t2.SubCategory ,
    t2.IsSerial ,
    t2.GrossWeight ,
    t2.NetWeight ,
    t2.AdditionalProperty1 ,
    t2.AdditionalProperty2 ,
    t2.AdditionalProperty3 ,
    t2.AdditionalProperty4 ,
    t2.AdditionalProperty5 ,
    t2.AdditionalProperty6 ,
    t2.AdditionalProperty7 ,
    t2.AdditionalProperty8 ,
    t2.AdditionalProperty9 ,
    t2.AdditionalProperty10 ,
    t1.WareHouse ,
    ISNULL(t6.StatesIs, N'') AS StatesIs ,
    ISNULL(t6.RegionIs, N'') AS RegionIs
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Invoices.t_Sold AS t3 ON t3.ID = t.SoldID
  INNER JOIN Company.t_Account AS t5 ON t5.ID = t3.AccountCustomerID
  LEFT JOIN Alls.v_Person1 AS t6 ON t6.ID = t5.LinkWithID
UNION ALL
SELECT t3.DateIs ,
    t.ItemSharedID ,
    t2.Name ,
    t2.Barcode ,
    0 AS Qtys ,
    t3.Currency ,
    0 AS TotalCostD ,
    0 AS TotalCostLL ,
    0 AS TotalCostEuro ,
    0 AS SubTotal2D ,
    0 AS SubTotal2LL ,
    0 AS SubTotal2Euro ,
    0 AS TotalProfitD ,
    0 AS TotalProfitLL ,
    0 AS TotalProfitEuro ,
    t.SerialNames ,
    N'' AS VendorName ,
    t2.Brand ,
    t2.VendorNames AS Vendors ,
    t3.UserIs ,
    t4.Name AS Salesperson ,
    t3.AccountCustomer ,
    t2.MainCategory ,
    t2.SubCategory ,
    t2.IsSerial ,
    0 AS GrossWeight ,
    0 AS NetWeight ,
    t2.AdditionalProperty1 ,
    t2.AdditionalProperty2 ,
    t2.AdditionalProperty3 ,
    t2.AdditionalProperty4 ,
    t2.AdditionalProperty5 ,
    t2.AdditionalProperty6 ,
    t2.AdditionalProperty7 ,
    t2.AdditionalProperty8 ,
    t2.AdditionalProperty9 ,
    t2.AdditionalProperty10 ,
    t1.WareHouse ,
    ISNULL(t6.StatesIs, N'') AS StatesIs ,
    ISNULL(t6.RegionIs, N'') AS RegionIs
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Invoices.t_SoldReturn AS t3 ON t3.ID = t.SoldReturnID
  INNER JOIN Employees.t_SalesPerson AS t4 ON t4.ID = t3.SalespersonID
  INNER JOIN Company.t_Account AS t5 ON t5.ID = t3.AccountCustomerID
  LEFT JOIN Alls.v_Person1 AS t6 ON t6.ID = t5.LinkWithID;
    












