/****** Object:  View [Invoices].[v_DressesRentalBaseNotification]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_DressesRentalBaseNotification]
AS
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'خذ القياسات ثم اطبع' AS TextAR ,
    N'Take Measurements then print' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 0 AND t.TakingMeasurementsDate <= GETDATE()
UNION ALL
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'أرسل إلى الخياطة' AS TextAR ,
    N'Send to the tailoring' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 1 AND t.TailoringDate <= GETDATE()
UNION ALL
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'اتصل بالعميل للتسليم' AS TextAR ,
    N'Call customer for delivery' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 2 AND t.DeliveryDate <= GETDATE()
UNION ALL
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'اتصل بالعميل للاستلام' AS TextAR ,
    N'Call customer for receiving' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 3 AND t.ReceivedDate <= GETDATE()
UNION ALL
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'أرسل إلى التنظيف' AS TextAR ,
    N'Send to cleaning' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 4 AND t.CleaningDate <= GETDATE()
UNION ALL
SELECT t.ID ,
    t3.Phones ,
    t3.AddressIs ,
    N'عرضه في صالة العرض' AS TextAR ,
    N'Display in showroom stage' AS TextEN
  FROM Invoices.t_DressesRental AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15
  WHERE t.StageIs = 5 AND t.CompletionDate <= GETDATE();

 


