    ISNULL(t6.Name, N'') AS PackUnit ,
    t.PackUnitQty ,
    t.PackQtys ,
    t.Qty ,
    t.Qtys ,
    t4.Unity AS Unit ,
    t.QtyWithUnity ,
    t.Qty - t.Qty AS Balance ,
    t1.CurrencyID ,
    t1.Currency ,
