/****** Object:  View [Items].[v_ItemMovementWithBalance]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Items].[v_ItemMovementWithBalance]
AS
WITH  t AS ( SELECT TOP ( 100 ) PERCENT s.ID ,
                s.SectionID ,
                s.SectionType ,
                s.Ref ,
                s.RefF ,
                s.DateIs ,
                s.AccountID ,
                s.Account ,
                s.AccountNumber ,
                s.ContactPerson ,
                s.ItemSharedID ,
                s.ItemID ,
                s.Name ,
                s.Barcode ,
                s.Barcodes ,
                s.BrandID ,
                s.Brand ,
                s.MainCategoryID ,
                s.MainCategory ,
                s.SubCategoryID ,
                s.SubCategory ,
                s.WareHouseID ,
                s.WareHouse ,
                s.PackUnit ,
                s.PackUnitQty ,
                s.PackQtys ,
                s.Qty ,
                s.Qtys ,
                s.Unit ,
                s.QtyWithUnity ,
                s.CurrencyID ,
                s.Currency ,
                s.Price ,
                s.PriceF ,
                s.PriceD ,
                s.PriceLL ,
                s.PriceEuro ,
                s.TaxRate ,
                s.TaxValue ,
                s.TaxValueF ,
                s.TaxValueD ,
                s.TaxValueLL ,
                s.TaxValueEuro ,
                s.DiscountIs ,
                s.DiscountIsValue ,
                s.DiscountIsValueF ,
                s.DiscountIsValueD ,
                s.DiscountIsValueLL ,
                s.DiscountIsValueEuro ,
                s.Total ,
                s.TotalF ,
                s.TotalD ,
                s.TotalLL ,
                s.TotalEuro ,
                s.ProfitTotal ,
                s.ProfitTotalF ,
                s.ProfitTotalD ,
                s.ProfitTotalLL ,
                s.ProfitTotalEuro ,
                s.DescriptionIs ,
                s.SerialNames ,
                s.SortAt ,
                s.DateCreate
              FROM Items.v_ItemMovement AS s
              ORDER BY s.ItemSharedID ,
                s.DateIs ,
                s.SectionID ,
                s.ItemID
           )
  SELECT TOP ( 100 ) PERCENT t.ID ,
      t.SectionID ,
      t.SectionType ,
      t.Ref ,
      t.RefF ,
      t.DateIs ,
      t.AccountID ,
      t.Account ,
      t.AccountNumber ,
      t.ContactPerson ,
      t.ItemSharedID ,
      t.ItemID ,
      t.Name ,
      t.Barcode ,
      t.Barcodes ,
      t.BrandID ,
      t.Brand ,
      t.MainCategoryID ,
      t.MainCategory ,
      t.SubCategoryID ,
      t.SubCategory ,
      t.WareHouseID ,
      t.WareHouse ,
      t.PackUnit ,
      t.PackUnitQty ,
      t.PackQtys ,
      t.Qty ,
      t.Qtys ,
      t.Unit ,
      t.QtyWithUnity ,
      Items.f_GetQtyCurrentByUnit(t.ItemSharedID, SUM(t.Qtys) OVER ( PARTITION BY t.ItemSharedID ORDER BY t.ItemSharedID , t.DateIs, t.SectionID, t.ItemID )) AS Balance ,
      t.CurrencyID ,
      t.Currency ,
      t.Price ,
      t.PriceF ,
      t.PriceD ,
      t.PriceLL ,
      t.PriceEuro ,
      t.TaxRate ,
      t.TaxValue ,
      t.TaxValueF ,
      t.TaxValueD ,
      t.TaxValueLL ,
      t.TaxValueEuro ,
      t.DiscountIs ,
      t.DiscountIsValue ,
      t.DiscountIsValueF ,
      t.DiscountIsValueD ,
      t.DiscountIsValueLL ,
      t.DiscountIsValueEuro ,
      t.Total ,
      t.TotalF ,
      t.TotalD ,
      t.TotalLL ,
      t.TotalEuro ,
      t.ProfitTotal ,
      t.ProfitTotalF ,
      t.ProfitTotalD ,
      t.ProfitTotalLL ,
      t.ProfitTotalEuro ,
      t.DescriptionIs ,
      t.SerialNames ,
      t.SortAt ,
      t.DateCreate
    FROM t
    ORDER BY t.DateIs DESC ,
      t.SectionID ,
      t.ItemID;

  






