/****** Object:  UserDefinedFunction [Alls].[f_SplitString]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- User Defined Function

CREATE FUNCTION [Alls].[f_SplitString]
  (
    @pString NVARCHAR(max) ,
    @pDelimiter CHAR(1)
  )
RETURNS TABLE
  WITH SCHEMABINDING
  AS
 RETURN
  --===== "Inline" CTE Driven "Tally Table" produces values from 0 up to 10,000...
     -- enough to cover NVARCHAR(4000)
  WITH  E1 ( N )
          AS ( SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
               UNION ALL
               SELECT 1
             ),                          --10E+1 or 10 rows
        E2 ( N )
          AS ( SELECT 1
                FROM E1 a ,
                  E1 b
             ), --10E+2 or 100 rows
        E4 ( N )
          AS ( SELECT 1
                FROM E2 a ,
                  E2 b
             ), --10E+4 or 10,000 rows max
        cteTally ( N )
          AS (--==== This provides the "base" CTE and limits the number of rows right up front
                     -- for both a performance gain and prevention of accidental "overruns"
               SELECT TOP ( ISNULL(DATALENGTH(@pString), 0) ) ROW_NUMBER() OVER ( ORDER BY ( SELECT NULL
                                                                                           ) )
                FROM E4
             ),
        cteStart ( N1 )
          AS (--==== This returns N+1 (starting position of each "element" just once for each delimiter)
               SELECT 1
               UNION ALL
               SELECT t.N + 1
                FROM cteTally t
                WHERE SUBSTRING(@pString, t.N, 1) = @pDelimiter
             ),
        cteLen ( N1, L1 )
          AS (--==== Return start and length (for use in substring)
               SELECT s.N1 ,
                  ISNULL(NULLIF(CHARINDEX(@pDelimiter, @pString, s.N1), 0) - s.N1, 8000)
                FROM cteStart s
             )
  --===== Do the actual split. The ISNULL/NULLIF combo handles the length for the final element when no delimiter is found.
 SELECT ItemNumber = ROW_NUMBER() OVER ( ORDER BY l.N1 ) ,
    Item = SUBSTRING(@pString, l.N1, l.L1)
  FROM cteLen l
  WHERE  SUBSTRING(@pString, l.N1, l.L1) <> N'';

GO
/****** Object:  UserDefinedFunction [Alls].[SplitToNumberTable]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE FUNCTION [Alls].[SplitToNumberTable]
  (
    @String VARCHAR(4000) ,
    @Pattern VARCHAR(5000)
  )
RETURNS @Results TABLE
  (
    ItemNumber FLOAT ,
    Item VARCHAR(4000) ,
    [Matched] INT
  )
  WITH SCHEMABINDING
AS
BEGIN;
-- DECLARE a couple of variables we'll need in our loop     
  DECLARE @ItemNumber INT = 0 ,
    @Remaining VARCHAR(400) = ISNULL(@String, '')         
-- Create the "not pattern" 
    ,
    @NotPattern VARCHAR(500) = REPLACE(REPLACE(@Pattern, '[', '[^'), '^^', '') ,
    @Matched INT;
  IF @String IS NULL OR @Pattern IS NULL
    INSERT INTO @Results
      SELECT NULL ,
          NULL ,
          NULL;
  WHILE DATALENGTH(@Remaining) > 0
  BEGIN
    SELECT @ItemNumber = @ItemNumber + 1 ,
        @String = CASE
            -- When a+b = 1, then either a=1 and b=0 (the pattern was found but not pattern                     
            -- was not found) or a=0 and b=1 (the not pattern was found but pattern was           
            -- not found).
            -- This means that no meaninful patterns are found in what remains so we’re done.   
                       WHEN a + b = 1 THEN @Remaining   
            -- This case returns the chunk up to the start of the next pattern/not pattern  
                       WHEN ( a = 1 AND b > 0
                            ) OR ( b = 1 AND a > 0
                                 ) THEN SUBSTRING(@Remaining, 1, CASE a
                                                                   WHEN 1 THEN b
                                                                   ELSE a
                                                                 END - 1)
                       ELSE @Remaining
                  END ,
        @Matched = CASE a
                     WHEN 1 THEN 1
                     ELSE 0
                   END
      FROM (
       -- Find the next occurrence of the Pattern and the NotPattern
             SELECT PATINDEX(@Pattern, @Remaining) ,
                PATINDEX(@NotPattern, @Remaining)
           ) a ( a, b );
       -- Now that we have our ItemNumber and Item (in @String) INSERT them into our results
    INSERT INTO @Results
      SELECT @ItemNumber ,
          @String ,
          @Matched;
        -- Find the remaining characters in the string         
    SELECT @Remaining = CASE WHEN DATALENGTH(@Remaining) = DATALENGTH(@String) THEN ''
                             ELSE SUBSTRING(@Remaining, DATALENGTH(@String) + 1, DATALENGTH(@Remaining))
                        END;
  END;
  RETURN;
END;

