CREATE VIEW [Cars].[v_CarRentalReport]
AS
SELECT t.ID ,
    t.RefF ,
    t.SponsorName ,
    t2.IDNumber ,
    t2.ID AS CustomerID ,
    t.Account ,
    t2.FatherName ,
    t2.MotherName ,
    t2.Phones ,
    t2.AddressIs ,
    t2.Birthday ,
    t2.BirthPlace ,
    t2.Nationality ,
    t2.DrivingLicense ,
    t2.DrivingLicenseIssuanceDate ,
    t2.DrivingLicenseStates ,
    t2.DrivingLicenseRegion ,
    t2.LicenseExpirationDate ,
    t2.SalesPerson ,
    t.CheckOutDate ,
    t.CheckOutOdometer ,
    t.CheckInDate ,
    t.CheckInOdometer ,
    t.StatusIs ,
    t.OdometerConsumed ,
    t.CarID ,
    t3.VehicleIdentificationNumber ,
    t3.RegistrationNumber ,
    t3.Make ,
    t3.Model ,
    t3.YearIs ,
    t3.ClassName ,
    t3.Color ,
    t3.Engine ,
    t.AgreementDate ,
    t.FromDate ,
    t.ToDate ,
    t.CurrencyID ,
    t.Subtotal ,
    t.SubtotalF ,
    t.Discount ,
    t.DailyTax ,
    t.DailyTaxF ,
    t.TotalTax ,
    t.TotalTaxF ,
	t.TaxRate,
