  FROM Cars.t_CarRental AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t2 ON t2.ID = t1.LinkWithID AND t1.IsMasterLink = 1
  INNER JOIN Cars.t_Car AS t3 ON t3.ID = t.CarID;

















