/****** Object:  View [Company].[v_AccountPurchase]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Company].[v_AccountPurchase]
AS
SELECT t.ID ,
    t.Name ,
    t.NumberIs ,
    t.NumberF ,
    t.CurrencyTypeIs
  FROM Company.t_Account AS t
  WHERE ( t.NumberIs BETWEEN 6010100000 AND 6019999999 ) AND ( t.NumberIs NOT BETWEEN 6050100000 AND 6050199999 ) AND ( t.NumberIs NOT BETWEEN 6050200000 AND 6050299999 )
UNION ALL
SELECT t.ID ,
    t.Name ,
    t.NumberIs ,
    t.NumberF ,
    t.CurrencyTypeIs
  FROM Company.t_Account AS t
  WHERE t.NumberIs BETWEEN 3710100000 AND 3799999999;

  




GO
