GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_AccountReevaluateBalances]
AS
SELECT t.ID ,
    t.NumberIs ,
    t.NumberF ,
    t.NumberNet ,
    t.Name ,
    t.Balance ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.CurrencyID ,
    t.Currency ,
    t.CurrencyTypeIs ,
    t2.ExchangeRate
  FROM Company.t_Account AS t
  INNER JOIN Company.t_AccountLevel3 AS t1 ON t1.ID = t.Level3ID AND t1.NumberIs <= 59999
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID
  WHERE ROUND(t.Balance, 2) <> 0;




