CREATE VIEW [Company].[v_AccountTopVendor]
AS
SELECT  t.ID ,
        t.Name ,
        t1.Phones ,
        t1.AddressIs ,
        t1.NumberCurrency
FROM    Company.t_Account AS t
INNER JOIN Vendors.t_Vendor AS t1 ON t1.ID = t.LinkWithID
                                        AND t.SectionID = 67
                                        AND t.IsMasterLink = 1
WHERE   t.NumberIs BETWEEN 4010100000 AND 4019999999
        AND t.StatusIs <> 2;






