CREATE VIEW [Company].[v_AccountTrialBalance]
AS
SELECT t.ID ,
    t.Level3ID ,
    t1.Level2ID ,
    t2.Level1ID ,
    t.NumberIs ,
    t.NumberF ,
    t.Name ,
    t.Balance ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.CurrencyID ,
    t.Currency ,
    t.CurrencyTypeIs ,
    t3.ExchangeRate
  FROM Company.t_Account AS t
  INNER JOIN Company.t_AccountLevel3 AS t1 ON t1.ID = t.Level3ID
  INNER JOIN Company.t_AccountLevel2 AS t2 ON t2.ID = t1.Level2ID
  INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t.CurrencyID;
	











