/****** Object:  View [Company].[v_ChequeDashBoardLast3MonthDAR]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_ChequeDashBoardLast3MonthDAR]
AS
SELECT SUM(t.AmountD) AS Amount,
       t.DateDueMonthly,
       t.TypeIsAR AS TypeIs
FROM Company.t_Cheque AS t
    INNER JOIN
    (
        SELECT DISTINCT TOP (3)
               s.DateDueMonthly
        FROM Company.t_Cheque AS s
        ORDER BY s.DateDueMonthly DESC
    ) AS t1
        ON t1.DateDueMonthly = t.DateDueMonthly
GROUP BY t.DateDueMonthly,
         t.TypeIsAR;





GO
/****** Object:  View [Company].[v_ChequeDashBoardLast3MonthDEN]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_ChequeDashBoardLast3MonthDEN]
AS
SELECT SUM(t.AmountD) AS Amount,
       t.DateDueMonthly,
       t.TypeIsEN AS TypeIs
FROM Company.t_Cheque AS t
    INNER JOIN
    (
        SELECT DISTINCT TOP (3)
               s.DateDueMonthly
        FROM Company.t_Cheque AS s
        ORDER BY s.DateDueMonthly DESC
    ) AS t1
