/****** Object:  View [Company].[v_CustomersDebtAgingReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [Company].[v_CustomersDebtAgingReport]
AS
WITH  o AS ( SELECT s.ID ,
                s.NumberIs ,
                s.Name ,
                ISNULL(s2.Phones, N'') AS Phones ,
                s.Balance ,
                s.BalanceD ,
                s.BalanceLL ,
                s.BalanceEuro ,
                s.CurrencyID ,
                s.Currency ,
                s.CurrencyTypeIs ,
                ISNULL(Transactions.f_TransactionGetTotalDebit(s.ID), 0) AS Debit ,
                ISNULL(Transactions.f_TransactionGetTotalCredit(s.ID), 0) AS Credit ,
                ISNULL(Transactions.f_TransactionGetTotalDebitToday(s.ID), 0) AS Days_0 ,
                ISNULL(Transactions.f_TransactionGetTotalDebitLessDate(s.ID, DateTimes.f_GetToday()), 0) AS Days_1_30 ,
                ISNULL(Transactions.f_TransactionGetTotalDebitLessDate(s.ID, DATEADD(DAY, -30, DateTimes.f_GetToday())), 0) AS Days_31_60 ,
                ISNULL(Transactions.f_TransactionGetTotalDebitLessDate(s.ID, DATEADD(DAY, -60, DateTimes.f_GetToday())), 0) AS Days_61_90 ,
                ISNULL(Transactions.f_TransactionGetTotalDebitLessDate(s.ID, DATEADD(DAY, -90, DateTimes.f_GetToday())), 0) AS Days_90 ,
                s1.ExchangeRate
              FROM Company.t_Account AS s
              INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
              LEFT JOIN Customers.t_Customer AS s2 ON s2.ID = s.LinkWithID AND s.IsMasterLink = 1
              WHERE s.SectionID = 15 AND ROUND(s.BalanceD, 2) > 0 AND s.StatusIs <> 2
           )
  SELECT o.ID ,
      o.NumberIs ,
      o.Name ,
      o.Phones ,
      o.Balance ,
      o.BalanceD ,
      o.BalanceLL ,
      o.BalanceEuro ,
      o.CurrencyID ,
      o.Currency ,
      o.CurrencyTypeIs ,
      o.Debit ,
      o.Credit ,
      o.Days_0 ,
      o.Days_1_30 - o.Days_31_60 AS Days_1_30 ,
      o.Days_31_60 - o.Days_61_90 AS Days_31_60 ,
      o.Days_61_90 - o.Days_90 AS Days_61_90 ,
      o.Days_90 ,
      ISNULL(o.Debit / o.ExchangeRate, 0) AS DebitD ,
      ISNULL(o.Credit / o.ExchangeRate, 0) AS CreditD ,
      ISNULL(o.Days_0 / o.ExchangeRate, 0) AS Days_0D ,
      ISNULL(( o.Days_1_30 - o.Days_31_60 ) / o.ExchangeRate, 0) AS Days_1_30D ,
      ISNULL(( o.Days_31_60 - o.Days_61_90 ) / o.ExchangeRate, 0) AS Days_31_60D ,
      ISNULL(( o.Days_61_90 - o.Days_90 ) / o.ExchangeRate, 0) AS Days_61_90D ,
      ISNULL(o.Days_90 / o.ExchangeRate, 0) AS Days_90D
    FROM o;
	







GO
