CREATE VIEW [Company].[v_CustomersDebtAgingReportEmpty]
AS
WITH  o AS ( SELECT s.ID ,
                s.NumberIs ,
                s.Name ,
                ISNULL(s2.Phones, N'') AS Phones ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Balance ,
                s.CurrencyID ,
                s.Currency ,
                s.CurrencyTypeIs ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Debit ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Credit ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Days_1_30 ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Days_31_60 ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Days_61_90 ,
                ISNULL(CONVERT(FLOAT, 0), 0) AS Days_90
              FROM Company.t_Account AS s
              LEFT JOIN Customers.t_Customer AS s2 ON s2.ID = s.LinkWithID AND s.IsMasterLink = 1
              WHERE s.SectionID = 15 AND s.BalanceD > 0 AND s.StatusIs <> 2
           )
  SELECT o.ID ,
      o.NumberIs ,
      o.Name ,
      o.Phones ,
      o.Balance ,
      o.CurrencyID ,
      o.Currency ,
      o.CurrencyTypeIs ,
      o.Debit ,
      o.Credit ,
      o.Debit - o.Days_1_30 AS Days_0 ,
      o.Days_1_30 - o.Days_31_60 AS Days_1_30 ,
      o.Days_31_60 - o.Days_61_90 AS Days_31_60 ,
      o.Days_61_90 - o.Days_90 AS Days_61_90 ,
      o.Days_90
    FROM o;
	









