/****** Object:  View [Company].[v_DailyBoxTransactionDetail]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_DailyBoxTransactionDetail]
AS
SELECT t.ID ,
    t.AccountID ,
    t.DateIs ,
    CASE t2.CurrencyTypeIs
      WHEN 0 THEN t.BalanceD
      WHEN 1 THEN t.BalanceLL
      ELSE t.BalanceEuro
    END AS Balance ,
    t1.TypeIs AS TransactionType ,
    t1.LinkType ,
    t1.LinkTypeSub
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID;

	  


GO
