CREATE VIEW [Company].[v_ExpenseBalanceSumDailyLast6DaysD]
AS
SELECT t.DateOnly,
       SUM(t1.NetIsD) AS Balance
FROM
(
    SELECT DISTINCT TOP (6)
           s.DateOnly
    FROM Company.t_Expense AS s
    ORDER BY s.DateOnly DESC
) AS t
    LEFT JOIN Company.t_Expense AS t1
        ON t1.DateOnly = t.DateOnly
GROUP BY t.DateOnly;






