/****** Object:  View [Company].[v_ExpenseReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Company].[v_ExpenseReport]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.PaperRef ,
    t.Legal ,
    t.LinkedType ,
    t.LinkRef ,
    t.DateOnly ,
    t.ExpenseTypeID ,
    t.UserID ,
    t.UserIs ,
    t.FromAccountID ,
    t.FromAccount ,
    t.ToAccountID ,
    t.ToAccount ,
    t.VendorAccountID ,
    t.VendorAccount ,
    t.PaymentMethod ,
    t.CurrencyID ,
    t.Currency ,
    t2.TypeIs AS CurrencyType ,
    t.ExchangeRate ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.TaxRate ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.TaxValueLL ,
    ISNULL(Calculation.Division(t.TaxValueLL, t.TaxExchangeRateLL) * t.ExchangeRateLL, 0) AS RealTaxValueLL ,
    t.TaxValueEuro ,
    t.NetIsF ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    t.DescriptionIs ,
    t1.Name AS ExpenseType
  FROM Company.t_Expense AS t
  INNER JOIN Company.t_ExpensesTypes AS t1 ON t1.ID = t.ExpenseTypeID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID;
  
  




