/****** Object:  View [Company].[v_MailSendingSchedulesNeedSend]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Company].[v_MailSendingSchedulesNeedSend]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.SubjectText ,
    t.MessageText ,
    t.MailSendersID ,
    t.StartsFrom ,
    t.RepeatEvery ,
    t.RepeatType ,
    t.NextAppointment ,
    t.EndsIn ,
    t.Endless ,
    t.StatusType ,
    t.LastDateSentSuccessfully ,
    t.MailRecipientsNames ,
    t.MailRecipientsCount ,
    t.DescriptionIs ,
    t.DateCreated ,
    t1.HostName ,
    t1.PortNumber ,
    t1.Name AS MailSenders ,
    t1.PasswordIs
  FROM Company.t_MailSendingSchedules AS t
  INNER JOIN Company.t_MailSenders AS t1 ON t1.ID = t.MailSendersID
  WHERE t.StatusType = 0 AND t.NextAppointment <= GETDATE() AND CASE WHEN Endless = 1 THEN 1
                                                                     WHEN EndsIn > GETDATE() THEN 1
                                                                     ELSE 0
                                                                END = 1;
  
  




GO
