/****** Object:  View [Company].[v_MoneyExchangeSummaryMonthlyList]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Company].[v_MoneyExchangeSummaryMonthlyList]
AS
SELECT ISNULL(MIN(t.ID), '00000000-0000-0000-0000-000000000000') AS ID ,
    t.DateMonth AS DateOnly ,
    ISNULL(SUM(t.TotalCount), 0) AS TotalCount ,
    ISNULL(SUM(t.TotalCountBuy), 0) AS TotalCountBuy ,
    ISNULL(SUM(t.TotalCountSell), 0) AS TotalCountSell ,
    ISNULL(SUM(t.TotalBuyD), 0) AS TotalBuyD ,
    ISNULL(SUM(t.TotalBuyLL), 0) AS TotalBuyLL ,
    ISNULL(SUM(t.TotalBuyLL), 0) / ISNULL(SUM(t.TotalBuyD), 0) AS AverageExchangeRateBuy ,
    ISNULL(SUM(t.TotalSellD), 0) AS TotalSellD ,
    ISNULL(SUM(t.TotalSellLL), 0) AS TotalSellLL ,
    ISNULL(SUM(t.TotalSellLL), 0) / ISNULL(SUM(t.TotalSellD), 0) AS AverageExchangeRateSell ,
    ISNULL(SUM(t.ProfitD), 0) AS ProfitD ,
    ISNULL(SUM(t.ProfitLL), 0) AS ProfitLL ,
    ISNULL(SUM(t.ProfitEuro), 0) AS ProfitEuro
  FROM Company.t_MoneyExchangeSummary AS t
  GROUP BY t.DateMonth;
  





GO
