/****** Object:  View [Employees].[v_EmployeesProfitSummaryReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Employees].[v_EmployeesProfitSummaryReport]
AS
SELECT t.ID ,
    t.SoldID ,
    t.EmployeeID ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.Paid ,
    t1.DateIs ,
    t1.DateOnly ,
    t1.Currency ,
    t1.PaidUpD * Calculation.Division(t2.TotalD, t1.NetIsD) AS PaidUpD ,
    t1.PaidUpLL * Calculation.Division(t2.TotalD, t1.NetIsD) AS PaidUpLL ,
    t1.PaidUpEuro * Calculation.Division(t2.TotalD, t1.NetIsD) AS PaidUpEuro ,
    t1.RestD * Calculation.Division(t2.TotalD, t1.NetIsD) AS RestD ,
    t1.RestLL * Calculation.Division(t2.TotalD, t1.NetIsD) AS RestLL ,
    t1.RestEuro * Calculation.Division(t2.TotalD, t1.NetIsD) AS RestEuro ,
    t2.Qty ,
    t2.QtyWithUnity ,
    t2.DiscountIsValue ,
    t2.DiscountInvoice ,
    t2.TotalD ,
    t2.TotalLL ,
    t2.TotalEuro ,
    t2.ProfitTotalD ,
    t2.ProfitTotalLL ,
    t2.ProfitTotalEuro ,
    t3.ID AS ItemSharedID ,
    t3.Name ,
    t3.Barcode ,
    t7.Name AS Employee
  FROM Invoices.t_SoldDetailEmployeeProfit AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Invoices.t_SoldDetail AS t2 ON t2.ID = t.SoldDetailID
  INNER JOIN Items.t_ItemShared AS t3 ON t3.ID = t2.ItemSharedID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t2.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Company.t_Place AS t6 ON t6.ID = t4.PlaceID
  INNER JOIN Employees.t_Employee AS t7 ON t7.ID = t.EmployeeID;
  
  






GO
