/****** Object:  View [Employees].[v_FingerPrint_CHECKINOUT]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO









CREATE VIEW [Employees].[v_FingerPrint_CHECKINOUT]
AS
--SELECT t.ID ,
--    t.USERID ,
--    t.CHECKTIME ,
--    t.CHECKTYPE ,
--    t.VERIFYCODE ,
--    t.IsDownloaded ,
--    ISNULL(t1.ID, '00000000-0000-0000-0000-000000000000') AS EmployeeID ,
--    t1.Name ,
--    t1.Phones ,
--    ISNULL(t1.TypeID, '00000000-0000-0000-0000-000000000000') AS TypeID ,
--    t1.TypeIs ,
--    ISNULL(t1.NationalityID, '00000000-0000-0000-0000-000000000000') AS NationalityID ,
--    t1.Nationality ,
--    ISNULL(t1.ProfessionID, '00000000-0000-0000-0000-000000000000') AS ProfessionID ,
--    t2.Name AS Profession
--  FROM FingerPrint.dbo.CHECKINOUT AS t
--  LEFT JOIN Employees.t_Employee AS t1 ON t.USERID = t1.IDFingerPrint
--  LEFT JOIN Employees.t_Professions AS t2 ON t2.ID = t1.ProfessionID;

  SELECT NEWID() AS ID ,
      -1 AS USERID ,
      GETDATE() AS CHECKTIME ,
      N'' AS CHECKTYPE ,
      NULL AS VERIFYCODE ,
      CONVERT(BIT, 0) AS IsDownloaded ,
      NEWID() AS EmployeeID ,
      N'NO FINGERPRINT' AS Name ,
      NULL AS Phones ,
      NEWID() AS TypeID ,
      NULL AS TypeIs ,
      NEWID() AS NationalityID ,
      NULL AS Nationality ,
      NEWID() AS ProfessionID ,
      NULL AS Profession;
	  







GO
