/****** Object:  View [Employees].[v_ShiftDuplicateAttendance]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Employees].[v_ShiftDuplicateAttendance]
AS
SELECT t.ID ,
    t.EmployeeID ,
    t.CheckInTime
  FROM Employees.t_Shift AS t
EXCEPT
SELECT DISTINCT FIRST_VALUE(t.ID) OVER ( PARTITION BY t.EmployeeID, t.CheckInTime ORDER BY t.FinalWorkMinutes DESC ) AS ID ,
    t.EmployeeID ,
    t.CheckInTime
  FROM Employees.t_Shift AS t;
  



