/****** Object:  View [Employees].[v_VacationTop10ByEmployee]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Employees].[v_VacationTop10ByEmployee]
AS
SELECT o.ID ,
    o.DateIs ,
    o.EmployeeID ,
    o.DaysIs ,
    o.OperationType ,
    o.DateCreate ,
    o.TypeIs
  FROM ( SELECT t.ID ,
            t.DateIs ,
            t.EmployeeID ,
            ROW_NUMBER() OVER ( PARTITION BY t.EmployeeID ORDER BY t.DateCreate DESC ) AS RowNumber ,
            t.DaysIs ,
            t.OperationType ,
            t.DateCreate ,
            t1.Name AS TypeIs
          FROM Employees.t_Vacation AS t
          INNER JOIN Employees.t_Employee AS t1 ON t1.ID = t.EmployeeID
       ) AS o
  WHERE o.RowNumber <= 10;


  

GO
