CREATE VIEW [Gym].[v_GymMemberAttendanceLastEntry]
AS
SELECT TOP ( 1 ) t.ID ,
    t.DateIs ,
    t.AccountID ,
    t.Account ,
    t.AccountNumber ,
    t1.Balance ,
    t1.BalanceF ,
    t2.IDDoor ,
    t2.ImageIs ,
    t1.GymSubscriptionIsActive ,
    t1.GymSubscriptionActiveTo
  FROM Gym.t_GymMemberAttendance AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t2 ON t2.ID = t1.LinkWithID AND t1.SectionID = 15
  ORDER BY t.DateIs DESC;
  



