    1 AS InHistory
  FROM Gym.t_GymSubscriptionHistoryClass AS t
  INNER JOIN Gym.t_GymSubscriptionHistory AS t1 ON t1.ID = t.SubscriptionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t1.AccountID
