    t.ActiveUntilUseDays ,
    t.PersonalTrainerID ,
    t.PersonalTrainer ,
    t.AccountEmployeeID ,
    t.AccountEmployee ,
    t.AccountEmployeeNumber ,
    t.NumberOfClasses ,
    t.ClassesNames ,
    t.ClassesEmployeesNames ,
    t.AccountBox ,
    t.AccountBoxNumber ,
    t.PaymentMethod ,
    t.Currency ,
    t.ExchangeRate ,
    t.ExchangeRateLL ,
    t.ExchangeRateEuro ,
    t.SubscriptionTypePriceF ,
    t.SubscriptionTypePriceD ,
    t.SubscriptionTypePriceLL ,
    t.SubscriptionTypePriceEuro ,
    t.PersonalTrainerPriceF ,
    t.PersonalTrainerPriceD ,
    t.PersonalTrainerPriceLL ,
    t.PersonalTrainerPriceEuro ,
    t.PersonalTrainerSalaryF ,
    t.PersonalTrainerSalaryD ,
    t.PersonalTrainerSalaryLL ,
    t.PersonalTrainerSalaryEuro ,
    t.ClassesPriceF ,
    t.ClassesPriceD ,
    t.ClassesPriceLL ,
    t.ClassesPriceEuro ,
    t.ClassesSalaryF ,
    t.ClassesSalaryD ,
    t.ClassesSalaryLL ,
    t.ClassesSalaryEuro ,
    t.SubtotalF ,
    t.SubtotalD ,
    t.SubtotalLL ,
    t.SubtotalEuro ,
    t.DiscountF ,
    t.DiscountD ,
    t.DiscountLL ,
    t.DiscountEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.FirstPaymentF ,
    t.FirstPaymentD ,
    t.FirstPaymentLL ,
    t.FirstPaymentEuro ,
    t.PaymentF ,
    t.PaymentD ,
    t.PaymentLL ,
    t.PaymentEuro ,
    t.RestF ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro ,
    t.IsPaid ,
    t.IsPaidSalary ,
    t.IsPaidSalary + 0 AS IsPaidSalary_ ,
    t.AreClassesSalariesPaid + 0 AS AreClassesSalariesPaid_ ,
    t.CostF ,
    t.CostD ,
    t.CostLL ,
    t.CostEuro ,
    t.ProfitF ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.UserIs ,
    t.DescriptionIs ,
    t.DateCreate ,
    t.IsSync ,
    0 AS InHistory ,
    ISNULL(DATEDIFF(DAY, DateTimes.f_GetToday(), t.ToDate), -1) AS NextDays ,
    t3.TypeIs AS SubscriptionTypeType
  FROM Gym.t_GymSubscription AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t2 ON t2.ID = t1.LinkWithID
  INNER JOIN Gym.t_SubscriptionType AS t3 ON t3.ID = t.SubscriptionTypeID;
 






