CREATE VIEW [Gym].[v_ReferralDiscountForGymCustomersList]
AS
SELECT t.ID ,
    t.ReferralDiscountForGymID ,
    t1.AccountID AS FatherAccountID ,
    t3.Name AS FatherAccount ,
    t.AccountID ,
    t4.GymSubscriptionIsActive ,
    t5.ID AS CustomerID ,
    t5.IDDoor ,
    t5.Name ,
    t5.Phones ,
    t5.AddressIs ,
    0x0 AS ImageIs ,
    t.DescriptionIs ,
    t.DateCreated ,
    t.CreatedByUserID ,
    t6.Name AS CreatedByUser ,
    t.WorkStationID
  FROM Gym.t_ReferralDiscountForGymCustomers AS t
  INNER JOIN Gym.t_ReferralDiscountForGym AS t1 ON t1.ID = t.ReferralDiscountForGymID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t1.AccountID
  INNER JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1
  INNER JOIN Company.t_Account AS t4 ON t4.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t5 ON t5.ID = t4.LinkWithID AND t4.IsMasterLink = 1
  INNER JOIN Users.t_User AS t6 ON t6.ID = t.CreatedByUserID;
  






