CREATE VIEW [Invoices].[v_DaysPackageDetailFull]
AS
SELECT t.ID ,
    t.DaysPackageID ,
    t.ItemSharedID ,
    t.ItemUnitID ,
    t.Qty ,
    t.Qtys ,
    Items.f_FormatQty(t.Qty) + N' ' + t3.Name AS QtyWithUnit,
    t.SalePrice ,
    t.SalePriceF ,
    t.SalePriceD ,
    t.SalePriceLL ,
    t.SalePriceEuro ,
    t.TotalSalePrice ,
    t.TotalSalePriceF ,
    t.TotalSalePriceD ,
    t.TotalSalePriceLL ,
    t.TotalSalePriceEuro ,
    t.UnitDollar ,
    t.TotalDollars ,
    t.SortAt ,
    t.IsSync ,
    t1.Name ,
    t1.Barcode ,
    t1.Barcodes ,
    t1.ImageThumbnail ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.AlfaMtcType ,
    t1.AlfaMtcIsPhoneNumber ,
    t1.AlfaMtcMaxQtyPhoneNumber ,
    t2.Qty AS UnitQty ,
    t2.CurrencyID ,
    t3.Name AS Unit
  FROM Invoices.t_DaysPackageDetail AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Items.t_UnityItem AS t2 ON t2.ID = t.ItemUnitID
  INNER JOIN Items.t_Unity AS t3 ON t3.ID = t2.UnityID;
    






