CREATE VIEW [Invoices].[v_DressesRentalArchiveReport]
AS
SELECT t.ID ,
    t.RefF ,
    t.DateOnly ,
    t.TakingMeasurementsDate ,
    t.TailoringDate ,
    t.DeliveryDate ,
    t.EventDate ,
    t.AccountID ,
    t.Account ,
    ISNULL(t3.AddressIs, '') AS AddressIs ,
    ISNULL(t3.StatesIs, '') AS StatesIs ,
    ISNULL(t3.RegionIs, '') AS RegionIs ,
    ISNULL(t3.Street, '') AS Street ,
    ISNULL(t3.AddressNote, '') AS AddressNote ,
    ISNULL(t3.Phones, '') AS Phones ,
    t1.Name ,
    t1.PurchaseWithTaxF ,
    t.AmountF ,
    t.AmountAR ,
    t.AmountEN ,
    t.PaidUpF ,
    t.RestF ,
    t.InsuranceAmountF ,
    t.InsuranceAmountPaidUpF ,
    t.InsuranceAmountRestF ,
    t.Bust ,
    t.Waist ,
    t.Hips ,
    t.HollowToFloor ,
    t.Shoulder ,
    t.SpecialAdjustments
  FROM Invoices.t_DressesRentalArchive AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID AND t2.IsMasterLink = 1 AND t2.SectionID = 15;
  
  







