/****** Object:  View [Invoices].[v_ElectricitySubscriptionsAllShort]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_ElectricitySubscriptionsAllShort]
AS
SELECT o.FromDateMonthly ,
    o.IsActive ,
    ISNULL(SUM(o.CountIs), 0) AS CountIs ,
    ISNULL(SUM(o.TotalAmperes), 0) AS TotalAmperes ,
    ISNULL(SUM(o.TotalD), 0) AS TotalD ,
    ISNULL(SUM(o.TotalLL), 0) AS TotalLL ,
    ISNULL(SUM(o.TotalEuro), 0) AS TotalEuro ,
    ISNULL(SUM(o.RestD), 0) AS RestD ,
    ISNULL(SUM(o.RestLL), 0) AS RestLL ,
    ISNULL(SUM(o.RestEuro), 0) AS RestEuro
  FROM ( SELECT t.FromDateMonthly ,
            t.IsActive ,
            COUNT_BIG(t.ID) AS CountIs ,
            SUM(t.TotalAmperes) AS TotalAmperes ,
            SUM(t.TotalD) AS TotalD ,
            SUM(t.TotalLL) AS TotalLL ,
            SUM(t.TotalEuro) AS TotalEuro ,
            SUM(t.RestD) AS RestD ,
            SUM(t.RestLL) AS RestLL ,
            SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_ElectricitySubscriptions AS t
          GROUP BY t.FromDateMonthly ,
            t.IsActive
         UNION ALL
         SELECT t.FromDateMonthly ,
            t.IsActive ,
            COUNT_BIG(t.ID) AS CountIs ,
            SUM(t.TotalAmperes) AS TotalAmperes ,
            SUM(t.TotalD) AS TotalD ,
            SUM(t.TotalLL) AS TotalLL ,
            SUM(t.TotalEuro) AS TotalEuro ,
            SUM(t.RestD) AS RestD ,
            SUM(t.RestLL) AS RestLL ,
            SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_ElectricitySubscriptionsArchives AS t
          GROUP BY t.FromDateMonthly ,
            t.IsActive
       ) AS o
  GROUP BY o.FromDateMonthly ,
    o.IsActive;
  




