CREATE VIEW [Invoices].[v_ElectricitySubscriptionsUpcomingRenewalList]
AS
SELECT t.ID ,
    t1.RefF ,
    t1.FromDateMonthly ,
    t1.CurrencyID ,
    t1.ExchangeRate ,
    t1.ExchangeRateLL ,
    t1.ExchangeRateEuro ,
    t1.Renewable ,
    t.ElectricitySubscriptionTypeID ,
    t2.Name AS ElectricitySubscriptionType ,
    t2.TypeIs  ,
    t2.PeriodType ,
    t2.PeriodNumber ,
    t2.TotalAmperes ,
    t2.CurrencyID AS TypeCurrencyID ,
    t2.FixedFees AS TypeFixedFees ,
    t2.FixedFeesF AS TypeFixedFeesF ,
    t2.FixedFeesD AS TypeFixedFeesD ,
    t2.FixedFeesLL AS TypeFixedFeesLL ,
    t2.FixedFeesEuro AS TypeFixedFeesEuro ,
    t2.SubscriptionFees AS TypeSubscriptionFees ,
    t2.SubscriptionFeesF AS TypeSubscriptionFeesF ,
    t2.SubscriptionFeesD AS TypeSubscriptionFeesD ,
    t2.SubscriptionFeesLL AS TypeSubscriptionFeesLL ,
    t2.SubscriptionFeesEuro AS TypeSubscriptionFeesEuro ,
    t.ElectricGeneratorID ,
    t3.Name AS ElectricGenerator ,
    t.ElectricalBoxID ,
    t4.Name AS ElectricalBox ,
    t4.PrintOrder ,
    t.AdditionalFees ,
    t.AdditionalFeesF ,
    t.AdditionalFeesD ,
    t.AdditionalFeesLL ,
    t.AdditionalFeesEuro ,
    t.Discount ,
    t.DiscountF ,
    t.DiscountD ,
    t.DiscountLL ,
    t.DiscountEuro ,
    t.CollectionOfficerEmployeeID ,
    t5.Name AS CollectionOfficerEmployee ,
    t.PrivateNote ,
    t.CreatedByUserID ,
    t6.Name AS CreatedByUser ,
    t.DateCreated ,
    t.LastModifiedDate
  FROM Invoices.t_ElectricitySubscriptionsUpcomingRenewal AS t
  INNER JOIN Invoices.t_ElectricitySubscriptions AS t1 ON t1.ID = t.ID
  INNER JOIN Invoices.t_ElectricitySubscriptionTypes AS t2 ON t2.ID = t.ElectricitySubscriptionTypeID
  INNER JOIN Invoices.t_ElectricGenerators AS t3 ON t3.ID = t.ElectricGeneratorID
  INNER JOIN Invoices.t_ElectricalBoxes AS t4 ON t4.ID = t.ElectricalBoxID
  INNER JOIN Employees.t_Employee AS t5 ON t5.ID = t.CollectionOfficerEmployeeID
  INNER JOIN Users.t_User AS t6 ON t6.ID = t.CreatedByUserID;
  

  






