/****** Object:  View [Invoices].[v_InternetSubscriptionsAllShort]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Invoices].[v_InternetSubscriptionsAllShort]
AS
SELECT o.FromDateMonthly ,
    o.IsActive ,
    ISNULL(SUM(o.CountIs), 0) AS CountIs ,
    ISNULL(SUM(o.PriceD), 0) AS PriceD ,
    ISNULL(SUM(o.PriceLL), 0) AS PriceLL ,
    ISNULL(SUM(o.PriceEuro), 0) AS PriceEuro ,
    ISNULL(SUM(o.RestD), 0) AS RestD ,
    ISNULL(SUM(o.RestLL), 0) AS RestLL ,
    ISNULL(SUM(o.RestEuro), 0) AS RestEuro
  FROM ( SELECT t.FromDateMonthly ,
            t.IsActive ,
            COUNT_BIG(t.ID) AS CountIs ,
            SUM(t.PriceD) AS PriceD ,
            SUM(t.PriceLL) AS PriceLL ,
            SUM(t.PriceEuro) AS PriceEuro ,
            SUM(t.RestD) AS RestD ,
            SUM(t.RestLL) AS RestLL ,
            SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_InternetSubscriptions AS t
          GROUP BY t.FromDateMonthly ,
            t.IsActive
         UNION ALL
         SELECT t.FromDateMonthly ,
            t.IsActive ,
            COUNT_BIG(t.ID) AS CountIs ,
            SUM(t.PriceD) AS PriceD ,
            SUM(t.PriceLL) AS PriceLL ,
            SUM(t.PriceEuro) AS PriceEuro ,
            SUM(t.RestD) AS RestD ,
            SUM(t.RestLL) AS RestLL ,
            SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_InternetSubscriptionsArchives AS t
          GROUP BY t.FromDateMonthly ,
            t.IsActive
       ) AS o
  GROUP BY o.FromDateMonthly ,
    o.IsActive;

	 




