/****** Object:  View [Invoices].[v_ItemsPurchaseCostsReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Invoices].[v_ItemsPurchaseCostsReport]
AS
WITH  t AS ( SELECT MIN(s.ID) AS ID ,
                s1.RefF ,
                s1.DateOnly ,
                s1.AccountVendor ,
                s.ItemSharedID ,
                ( SUM(s.TotalD) - SUM(s.TaxValueD) ) / SUM(s.Qtys) AS UnitCostD ,
                ( SUM(s.TotalLL) - SUM(s.TaxValueLL) ) / SUM(s.Qtys) AS UnitCostLL ,
                ( SUM(s.TotalEuro) - SUM(s.TaxValueEuro) ) / SUM(s.Qtys) AS UnitCostEuro ,
                SUM(s.TotalFinalCostD) / SUM(s.Qtys) UnitFinalCostD ,
                SUM(s.TotalFinalCostLL) / SUM(s.Qtys) UnitFinalCostLL ,
                SUM(s.TotalFinalCostEuro) / SUM(s.Qtys) UnitFinalCostEuro ,
                SUM(s.TaxValueD) / SUM(s.Qtys) AS UnitTaxD ,
                SUM(s.TaxValueLL) / SUM(s.Qtys) AS UnitTaxLL ,
                SUM(s.TaxValueEuro) / SUM(s.Qtys) AS UnitTaxEuro ,
                ROW_NUMBER() OVER ( PARTITION BY s.ItemSharedID ORDER BY s1.DateOnly DESC ) - 1 AS CostLevel
              FROM Invoices.t_PurchasingDetail AS s
              INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
              GROUP BY s.PurchasingID ,
                s1.RefF ,
                s1.DateOnly ,
                s1.AccountVendor ,
                s.ItemSharedID
           )
  SELECT t.ID ,
      t.RefF ,
      t.DateOnly ,
      t.AccountVendor ,
      t.ItemSharedID ,
      t1.Name ,
      t1.Barcode ,
      t2.Name AS Brand ,
      t3.Name AS MainCategory ,
      t4.Qty AS UnitQty ,
      t5.Name AS Unit ,
      t.UnitCostD ,
      t.UnitCostLL ,
      t.UnitCostEuro ,
      t.UnitFinalCostD ,
      t.UnitFinalCostLL ,
      t.UnitFinalCostEuro ,
      t.UnitTaxD ,
      t.UnitTaxLL ,
      t.UnitTaxEuro ,
      t.CostLevel
    FROM t
    INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
    INNER JOIN Items.t_Brand AS t2 ON t2.ID = t1.BrandID
    INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t1.MainCategoryID
    INNER JOIN Items.t_UnityItem AS t4 ON t4.SharedID = t1.ID AND t4.Purchasing = 1
    INNER JOIN Items.t_Unity AS t5 ON t5.ID = t4.UnityID
    WHERE t.CostLevel < 10;
	


GO
/****** Object:  View [Invoices].[v_ItemsPurchaseExpensesReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_ItemsPurchaseExpensesReport]
AS
SELECT t.ID ,
    t.PurchasingID ,
    t.Qty ,
    t.QtyWithUnity ,
    ( t.Total - t.TaxValue ) / t.Qty AS Price ,
    t.Total - t.TaxValue AS Total ,
    t.UnitExpenses ,
    t.InvoiceExpenses ,
    t.FinalUnitCost ,
    t.TotalFinalCost ,
    t1.RefF ,
    t1.DateOnly ,
    t1.AccountVendor ,
    t1.CurrencyID ,
    t1.Expenses ,
    t2.ID AS ItemSharedID ,
    t2.Barcode ,
    t2.Name ,
    t3.Name AS MainCategory ,
    t4.Name AS Brand ,
    t6.Name AS Warehouse ,
    t8.Name AS Unit
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Brand AS t4 ON t4.ID = t2.BrandID
  INNER JOIN Items.t_Item AS t5 ON t5.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t6 ON t6.ID = t5.WareHouseID
  INNER JOIN Items.t_UnityItem AS t7 ON t7.ID = t.ItemUnityID
  INNER JOIN Items.t_Unity AS t8 ON t8.ID = t7.UnityID
  WHERE t.UnitExpenses > 0;
    


GO
/****** Object:  View [Invoices].[v_MonthlyReceiptsSummaryReport259]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_MonthlyReceiptsSummaryReport259]
AS
SELECT t.DateFirstDayInMonth AS TransactionDate ,
    COALESCE(t2.FromDateMonthly, t3.FromDateMonthly, t.DateFirstDayInMonth) AS ElectricityDate ,
    t.DebitD AS TotalD ,
    t.DebitLL AS TotalLL ,
    t.DebitEuro AS TotalEuro
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  LEFT JOIN Invoices.t_ElectricitySubscriptions AS t2 ON t2.ID = t1.LinkID AND t1.LinkType = 259
  LEFT JOIN Invoices.t_ElectricitySubscriptionsArchives AS t3 ON t3.ID = t1.LinkID AND t1.LinkType = 259
  WHERE t1.TypeIs = N'RV' AND t.Debit > 0;


