CREATE VIEW [Invoices].[v_PhoneSubscriberActive]
AS
SELECT t.ID ,
    t.CustomerID ,
    t.Customer ,
    t1.CurrentBalance ,
    t.SerialNumber ,
    t.PrimaryPhoneNumberID ,
    t.PrimaryPhoneNumber ,
    t.SimCardNumber ,
    t.GBQuota ,
    t.MonthlyFeesD ,
    t.MonthlyFees ,
    t.ExtraChargeD ,
    t.ExtraCharge ,
    t.TotalD ,
    t.Total ,
    t.Deposit ,
    t.Notes ,
    t.NewSubscriptionDate ,
    t.DateCreated ,
    t.IsSync
  FROM Invoices.t_PhoneSubscriber AS t
  INNER JOIN Invoices.t_PhoneCustomer AS t1 ON t1.ID = t.CustomerID
  WHERE t.NewSubscriptionDate >= CONVERT(DATE, GETDATE());

















