/****** Object:  View [Invoices].[v_PurchasedQuantitySummaryReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_PurchasedQuantitySummaryReport]
AS
SELECT t.ID ,
    t.ItemSharedID ,
    t1.DateOnly ,
    t1.DateMonthly ,
    t1.DateYearly ,
    t2.Name ,
    t2.Barcode ,
    t3.Name AS Brand ,
    t4.Name AS MainCategory ,
    t6.Name AS Warehouse ,
    t.Qtys
  FROM Invoices.t_PurchasingDetail AS t
  INNER  JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Brand AS t3 ON t3.ID = t2.BrandID
  INNER JOIN Items.t_MainCategory AS t4 ON t4.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t5 ON t5.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t6 ON t6.ID = t5.WareHouseID;
 


GO
/****** Object:  View [Invoices].[v_PurchasedQuantitySummaryReportWithReturn]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_PurchasedQuantitySummaryReportWithReturn]
AS
SELECT t.ID ,
    t.ItemSharedID ,
    t1.DateOnly ,
    t1.DateMonthly ,
    t1.DateYearly ,
    t2.Name ,
    t2.Barcode ,
    t3.Name AS Brand ,
    t4.Name AS MainCategory ,
    t6.Name AS Warehouse ,
    t.Qtys
  FROM Invoices.t_PurchasingDetail AS t
  INNER  JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Brand AS t3 ON t3.ID = t2.BrandID
  INNER JOIN Items.t_MainCategory AS t4 ON t4.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t5 ON t5.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t6 ON t6.ID = t5.WareHouseID
UNION ALL
SELECT t.ID ,
    t.ItemSharedID ,
    t1.DateOnly ,
    t1.DateMonthly ,
    t1.DateYearly ,
    t2.Name ,
    t2.Barcode ,
    t3.Name AS Brand ,
    t4.Name AS MainCategory ,
    t6.Name AS Warehouse ,
    0 - t.Qtys AS Qtys
  FROM Invoices.t_PurchasingReturnDetail AS t
  INNER  JOIN Invoices.t_PurchasingReturn AS t1 ON t1.ID = t.PurchasingReturnID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Brand AS t3 ON t3.ID = t2.BrandID
  INNER JOIN Items.t_MainCategory AS t4 ON t4.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t5 ON t5.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t6 ON t6.ID = t5.WareHouseID;
 



GO
