    t.DescriptionIs ,
    t.SortAt ,
    t.DateCreate ,
    t1.Ref ,
    t1.RefF ,
    t1.DateIs ,
    t1.DateOnly ,
    t1.AccountID ,
    t1.Account ,
    t2.Name ,
    t2.Barcode ,
    t2.Barcodes ,
    t2.ImagePath ,
    t2.IsSerial ,
    t3.Place ,
    t3.QtyCurrent ,
    t4.CurrencyID AS UnitCurrencyID ,
    t4.Unity AS Unit ,
    t4.Qty AS UnitQty ,
    t5.Name AS WareHouse
  FROM Invoices.t_PurchaseOrderDetail AS t
  INNER JOIN Invoices.t_PurchaseOrder AS t1 ON t1.ID = t.PurchaseOrderID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t3 ON t3.ID = t.ItemID
  INNER JOIN Items.t_UnityItem AS t4 ON t4.ID = t.ItemUnitID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t.WarehouseID
  WHERE t.IsSync = 0;
















