/****** Object:  View [Invoices].[v_PurchasingDetailFillExpirationDateNew]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_PurchasingDetailFillExpirationDateNew]
AS
SELECT DISTINCT MIN(t.ID) OVER ( ) AS ID ,
    MIN(t.PurchasingID) OVER ( ) AS PurchasingID ,
    t.ItemSharedID ,
    t.ItemID ,
    t1.Barcode ,
    t1.Name ,
    t1.SellCurrencyID ,
    t1.SellCurrency ,
    t1.LifeSpanDays ,
    t1.NoticeDaysBeforeExpiryDate ,
    t2.WareHouseID ,
    t3.Name AS WareHouse ,
    t2.PlaceID ,
    t4.Name AS Place ,
    ISNULL(t2.QtyCurrent - Items.f_ItemExpirationDateGetQty(t.ItemID), 0) AS QtyCurrent
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t2 ON t2.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t3 ON t3.ID = t2.WareHouseID
  INNER JOIN Company.t_Place AS t4 ON t4.ID = t2.PlaceID
  WHERE t1.IsExpiryDate = 1 AND ISNULL(t2.QtyCurrent - Items.f_ItemExpirationDateGetQty(t.ItemID), 0) > 0;

  



GO
