CREATE VIEW [Invoices].[v_PurchasingDetailLatestCost]
AS
SELECT t1.ID ,
    t1.PurchasingID ,
    t1.ItemSharedID ,
    t1.ItemID ,
    t1.ItemUnityID ,
    t1.Qty ,
    t1.QtyWithUnity ,
    t1.Qtys ,
    t1.Price ,
    t1.PriceF ,
    t1.PriceD ,
    t1.PriceLL ,
    t1.PriceEuro ,
    t1.DiscountIs ,
    t1.DiscountIsF ,
    t1.DiscountIsValueF ,
    t1.DiscountIsValueD ,
    t1.DiscountIsValueLL ,
    t1.DiscountIsValueEuro ,
    t1.SubTotalF ,
    t1.SubTotalD ,
    t1.SubTotalLL ,
    t1.SubTotalEuro ,
    t1.DiscountInvoiceF ,
    t1.DiscountInvoiceD ,
    t1.DiscountInvoiceLL ,
    t1.DiscountInvoiceEuro ,
    t1.FutureDiscountRate ,
    t1.FutureDiscountRateF ,
    t1.FutureUnitDiscount ,
    t1.FutureUnitDiscountF ,
    t1.FutureUnitDiscountD ,
    t1.FutureUnitDiscountLL ,
    t1.FutureUnitDiscountEuro ,
    t1.FutureTotalDiscount ,
    t1.FutureTotalDiscountF ,
    t1.FutureTotalDiscountD ,
    t1.FutureTotalDiscountLL ,
    t1.FutureTotalDiscountEuro ,
    t1.TaxRate ,
    t1.TaxRateF ,
    t1.TaxValueF ,
    t1.TaxValueD ,
    t1.TaxValueLL ,
    t1.TaxValueEuro ,
    t1.TotalF ,
    t1.TotalD ,
    t1.TotalLL ,
    t1.TotalEuro ,
    t1.InvoiceExpensesF ,
    t1.InvoiceExpensesD ,
    t1.InvoiceExpensesLL ,
    t1.InvoiceExpensesEuro ,
    t1.DescriptionIs ,
    t1.DateCreate ,
    t1.IsSync ,
    t2.Ref ,
    t2.RefF ,
    t2.DateIs ,
    t2.AccountVendorID AS AccountID ,
    t2.AccountVendor AS Account ,
    t2.AccountVendorNumber AS AccountNumber ,
    t2.CurrencyID ,
    t2.Currency ,
    t2.ExchangeRate ,
    t2.ExchangeRateLL ,
    t2.ExchangeRateEuro ,
    t3.Name ,
    t3.Barcode ,
    t3.Barcodes ,
    t3.BrandID ,
    t3.Brand ,
    t3.MainCategoryID ,
    t3.MainCategory ,
    t3.SubCategoryID ,
    t3.SubCategory ,
    t4.WareHouseID ,
    t4.WareHouse ,
    t4.PlaceID ,
    t4.Place ,
    t5.UnityID AS UnitID ,
    t5.Qty AS UnitQty ,
    t6.Name AS Unit
  FROM ( SELECT MIN(s.ID) AS ID ,
            s1.AccountVendorID ,
            s.ItemUnityID ,
            s.Total
          FROM Invoices.t_PurchasingDetail AS s
          INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
          GROUP BY s1.AccountVendorID ,
            s.ItemUnityID ,
            s.Total
