SELECT t.ID,
       t.PurchasingID,
       t.PurchasingDetailID,
       t.SerialID,
       t1.SerialText,
       t.DateCreate
FROM Invoices.t_PurchasingDetailSerial AS t
    LEFT JOIN Items.t_ItemSerial AS t1
        ON t1.ID = t.SerialID;






