CREATE VIEW [Invoices].[v_PurchasingDetailWhatINeed]
AS
SELECT DISTINCT t1.AccountVendorID ,
    t.ItemID
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  INNER JOIN Items.t_Item AS t2 ON t2.ID = t.ItemID
  WHERE t2.QtyToReorder > 0 AND t2.QtyCurrent < t2.QtyToReorder;

	


