CREATE VIEW [Invoices].[v_PurchasingDistinctContactPerson]
AS
SELECT DISTINCT t.AccountVendorID ,
    t.ContactPerson
  FROM Invoices.t_Purchasing AS t
  WHERE t.ContactPerson <> ''
UNION
SELECT DISTINCT t.AccountVendorID ,
    t.ContactPerson
  FROM Invoices.t_PurchasingReturn AS t
  WHERE t.ContactPerson <> '';
  
  


