CREATE VIEW [Invoices].[v_PurchasingReturnDailyNumber]
AS

SELECT  t.ID ,
        t.RefF ,
        ROW_NUMBER() OVER ( PARTITION BY t.DateOnly ORDER BY t.Ref ) AS DailyNumber
FROM    Invoices.t_PurchasingReturn AS t;





