CREATE VIEW [Invoices].[v_PurchasingUnsavedDetailFillEdit]
AS
SELECT t.ID ,
    t.PurchasingUnsavedID ,
    t.ItemSharedID ,
    t.ItemID ,
    t1.Name ,
    t1.Barcode ,
    t1.ImageThumbnail ,
    t1.BrandID ,
    t1.Brand ,
    t.ItemUnityID ,
    t4.Name AS Unit ,
    t3.Qty AS UnitQty ,
    t.Qty ,
    t2.WareHouseID ,
    t2.WareHouse ,
    t.Price ,
    t.TaxRate ,
    t.DiscountIs ,
    t.Sell ,
    t3.CurrencyID ,
    t3.Price AS EditSellingPrice ,
    t.DescriptionIs ,
    t1.IsSerial ,
    t1.QtyCurrent ,
    t.SortAt
  FROM Invoices.t_PurchasingUnsavedDetail AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t2 ON t2.ID = t.ItemID
  INNER JOIN Items.t_UnityItem AS t3 ON t3.ID = t.ItemUnityID
  INNER JOIN Items.t_Unity AS t4 ON t4.ID = t3.UnityID;
    




