CREATE VIEW [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportGymSubscription]
AS
SELECT t.ID ,
    t.TransactionDate AS DateOnly ,
    t2.Name as Account ,
    t.CurrencyID ,
    t1.Name AS Currency ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.PaymentD AS PaidUpD ,
    t.PaymentLL AS PaidUpLL  ,
    t.PaymentEuro AS PaidUpEuro  ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro
  FROM Gym.t_GymSubscription AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID;
  






