/****** Object:  View [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportGymSubscriptionClassAndType]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Invoices].[v_SalesAndGymAndExpensesAndSalariesSummaryReportGymSubscriptionClassAndType]
AS
SELECT t.ID ,
    t1.TransactionDate AS DateOnly ,
    t3.Name AS Account ,
    t.ClassName AS ItemName ,
    t1.CurrencyID ,
    t2.Name AS Currency ,
    t.PriceD AS TotalD ,
    t.PriceLL AS TotalLL ,
    t.PriceEuro AS TotalEuro
  FROM Gym.t_GymSubscriptionClass AS t
  INNER JOIN Gym.t_GymSubscription AS t1 ON t1.ID = t.SubscriptionID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.CurrencyID
  INNER JOIN Company.t_Account AS t3 ON t3.ID = t1.AccountID
  WHERE PriceD > 0
UNION ALL
SELECT t.ID ,
    t.TransactionDate AS DateOnly ,
    t2.Name AS Account ,
    t3.Name AS ItemName ,
    t.CurrencyID ,
    t1.Name AS Currency ,
    t.SubscriptionTypePriceD - ( t.DiscountD / 2.0 ) AS TotalD ,
    t.SubscriptionTypePriceLL - ( t.DiscountLL / 2.0 ) AS TotalLL ,
    t.SubscriptionTypePriceEuro - ( t.DiscountEuro / 2.0 ) AS TotalEuro
  FROM Gym.t_GymSubscription AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Gym.t_SubscriptionType AS t3 ON t3.ID = t.SubscriptionTypeID
  WHERE t.SubscriptionTypePriceD - ( t.DiscountD / 2.0 ) > 0
UNION ALL
SELECT t.ID ,
    t.TransactionDate AS DateOnly ,
    t2.Name AS Account ,
    t3.Name AS ItemName ,
    t.CurrencyID ,
    t1.Name AS Currency ,
    t.PersonalTrainerPriceD - ( t.DiscountD / 2.0 ) AS TotalD ,
    t.PersonalTrainerPriceLL - ( t.DiscountLL / 2.0 ) AS TotalLL ,
    t.PersonalTrainerPriceEuro - ( t.DiscountEuro / 2.0 ) AS TotalEuro
  FROM Gym.t_GymSubscription AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Gym.t_PersonalTrainer AS t3 ON t3.ID = t.PersonalTrainerID
  WHERE t.PersonalTrainerPriceD - ( t.DiscountD / 2.0 ) > 0;
  
  







GO
