    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.PaidUpD ,
    t.PaidUpLL ,
    t.PaidUpEuro ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro
  FROM Invoices.t_Sold AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountCustomerID
UNION ALL
SELECT t.ID ,
    t.DateOnly ,
    t2.Name AS Account ,
    t.CurrencyID ,
    t1.Name AS Currency ,
    0 - t.NetIsD AS TotalD ,
    0 - t.NetIsLL AS TotalLL ,
    0 - t.NetIsEuro AS TotalEuro ,
    0 - t.ProfitD AS ProfitD ,
    0 - t.ProfitLL AS ProfitLL ,
    0 - t.ProfitEuro AS ProfitEuro ,
    0 - t.FirstPaymentD AS PaidUpD ,
    0 - t.FirstPaymentLL AS PaidUpLL ,
    0 - t.FirstPaymentEuro AS PaidUpEuro ,
    0 - (t.NetIsD - t.FirstPaymentD) AS RestD ,
    0 - (t.NetIsLL - t.FirstPaymentLL) AS RestLL ,
    0 - (t.NetIsEuro - t.FirstPaymentEuro) AS RestEuro
  FROM Invoices.t_SoldReturn AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountCustomerID;
  






GO
