CREATE VIEW [Invoices].[v_SalesLedgerReport]
AS
SELECT 2 AS SectionType ,
    1 AS NumberOfInvoice ,
    t.ID ,
    t.Ref ,
    t.RefF ,
    t.DateOnly ,
    t.AccountCustomer ,
    t.PaymentMethod ,
    t.CurrencyID ,
    t.Total AS Subtotal ,
    t.TotalF AS SubtotalF ,
    t.TotalD AS SubtotalD ,
    t.TotalLL AS SubtotalLL ,
    t.TotalEuro AS SubtotalEuro ,
    t.DiscountIs ,
    t.DiscountIsF ,
    t.DiscountIsD ,
    t.DiscountIsLL ,
    t.DiscountIsEuro ,
    t.DiscountIs AS Covid19 ,
    N'' AS Covid19F ,
    t.DiscountIsD AS Covid19D ,
    t.DiscountIsD AS Covid19LL ,
    t.DiscountIsD AS Covid19Euro ,
    t.DiscountIs AS GetFundLevy ,
    N'' AS GetFundLevyF ,
    t.DiscountIsD AS GetFundLevyD ,
    t.DiscountIsD AS GetFundLevyLL ,
    t.DiscountIsD AS GetFundLevyEuro ,
    t.DiscountIs AS NHIL ,
    N'' AS NHILF ,
    t.DiscountIsD AS NHILD ,
    t.DiscountIsD AS NHILLL ,
    t.DiscountIsD AS NHILEuro ,
    t.DiscountIs AS Tax ,
    N'' AS TaxF ,
    t.DiscountIsD AS TaxD ,
    t.DiscountIsD AS TaxLL ,
    t.DiscountIsD AS TaxEuro ,
    t.NetIs AS Total ,
    t.NetIsF AS TotalF ,
    t.NetIsD AS TotalD ,
    t.NetIsLL AS TotalLL ,
    t.NetIsEuro AS TotalEuro ,
    t.GhanaSystem ,
    t.GS_Covid19Rate ,
    t.GS_NHILRate ,
    t.GS_GetfundLevyRate ,
    t.GS_TaxRate ,
    t.GS_Reverse
  FROM Invoices.t_Sold AS t
UNION ALL
SELECT 3 AS SectionType ,
    -1 AS NumberOfInvoice ,
    t.ID ,
    t.Ref ,
    t.RefF ,
    t.DateOnly ,
    t.AccountCustomer ,
    t.PaymentMethod ,
    t.CurrencyID ,
    0 - t.Total AS Subtotal ,
    N'-' + t.TotalF AS SubtotalF ,
    0 - t.TotalD AS SubtotalD ,
    0 - t.TotalLL AS SubtotalLL ,
    0 - t.TotalEuro AS SubtotalEuro ,
    0 - t.DiscountIs ,
    N'-' + t.DiscountIsF ,
    0 - t.DiscountIsD ,
    0 - t.DiscountIsLL ,
    0 - t.DiscountIsEuro ,
    0 - t.DiscountIs AS Covid19 ,
    N'' AS Covid19F ,
    0 - t.DiscountIsD AS Covid19D ,
    0 - t.DiscountIsD AS Covid19LL ,
    0 - t.DiscountIsD AS Covid19Euro ,
    0 - t.DiscountIs AS GetFundLevy ,
    N'' AS GetFundLevyF ,
    0 - t.DiscountIsD AS GetFundLevyD ,
    0 - t.DiscountIsD AS GetFundLevyLL ,
    0 - t.DiscountIsD AS GetFundLevyEuro ,
    0 - t.DiscountIs AS NHIL ,
    N'' AS NHILF ,
    0 - t.DiscountIsD AS NHILD ,
    0 - t.DiscountIsD AS NHILLL ,
    0 - t.DiscountIsD AS NHILEuro ,
    0 - t.DiscountIs AS Tax ,
    N'' AS TaxF ,
    0 - t.DiscountIsD AS TaxD ,
    0 - t.DiscountIsD AS TaxLL ,
    0 - t.DiscountIsD AS TaxEuro ,
    0 - t.NetIs AS Total ,
    N'-' + t.NetIsF AS TotalF ,
    0 - t.NetIsD AS TotalD ,
    0 - t.NetIsLL AS TotalLL ,
    0 - t.NetIsEuro AS TotalEuro ,
    t.GhanaSystem ,
    t.GS_Covid19Rate ,
    t.GS_NHILRate ,
    t.GS_GetfundLevyRate ,
    t.GS_TaxRate ,
    t.GS_Reverse
  FROM Invoices.t_SoldReturn AS t;
 







