/****** Object:  View [Invoices].[v_SalesPaymentsReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_SalesPaymentsReport]
AS
SELECT t.ID ,
    0 AS RowIn ,
    1 NumberOfInvoices ,
    t.DateOnly ,
    t.AccountBoxID ,
    t.AccountBox ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    t.FirstPaymentD ,
    t.FirstPaymentLL ,
    t.FirstPaymentEuro ,
    t.SecondPaymentD ,
    t.SecondPaymentLL ,
    t.SecondPaymentEuro ,
    t.SecondPaymentAccountBoxID ,
    t.SecondPaymentAccountBox ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro ,
    t.UserID ,
    t1.Name AS UserIs
  FROM Invoices.t_Sold AS t
  INNER JOIN Users.t_User AS t1 ON t1.ID = t.UserID
UNION ALL
SELECT t.ID ,
    1 AS RowIn ,
    -1 NumberOfInvoices ,
    t.DateOnly ,
    t.AccountBoxID ,
    t.AccountBox ,
    0 - t.NetIsD ,
    0 - t.NetIsLL ,
    0 - t.NetIsEuro ,
    0 - t.FirstPaymentD ,
    0 - t.FirstPaymentLL ,
    0 - t.FirstPaymentEuro ,
    0 AS SecondPaymentD ,
    0 AS SecondPaymentLL ,
    0 AS SecondPaymentEuro ,
    N'00000000-0000-0000-0000-000000000000' AS SecondPaymentAccountBoxID ,
    N'' AS SecondPaymentAccountBox ,
    0 - t.RestD ,
    0 - t.RestLL ,
    0 - t.RestEuro ,
    t.UserID ,
    t1.Name AS UserIs
  FROM Invoices.t_SoldReturn AS t
  INNER JOIN Users.t_User AS t1 ON t1.ID = t.UserID
UNION ALL
SELECT t.ID ,
    2 AS RowIn ,
    0 NumberOfInvoices ,
    t.DateOnly ,
    t.AccountID ,
    t.Account ,
    0 AS NetIsD ,
    0 AS NetIsLL ,
    0 AS NetIsEuro ,
    BalanceD AS FirstPaymentD ,
    BalanceLL AS FirstPaymentLL ,
    BalanceEuro AS FirstPaymentEuro ,
    0 AS SecondPaymentD ,
    0 AS SecondPaymentLL ,
    0 AS SecondPaymentEuro ,
    N'00000000-0000-0000-0000-000000000000' AS SecondPaymentAccountBoxID ,
    N'' AS SecondPaymentAccountBox ,
    0 AS RestD ,
    0 AS RestLL ,
    0 AS RestEuro ,
    t1.UserID ,
    t1.UserIs
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  WHERE t1.TypeIs = N'RV' AND t.Balance > 0 AND ( t1.LinkTypeSub = 12 OR t1.LinkType <> 2
                                                );
  




GO
