CREATE VIEW [Invoices].[v_SalesProfitReportItems]
AS
SELECT 0 AS RowIn ,
    t1.DateOnly ,
    t.ItemSharedID ,
    t1.AccountCustomerID ,
    t2.Barcode ,
    t2.Name ,
    t2.Brand ,
    t2.MainCategory ,
    t2.AdditionalProperty1 ,
    t2.AdditionalProperty2 ,
    t2.AdditionalProperty3 ,
    t2.AdditionalProperty4 ,
    t2.AdditionalProperty5 ,
    t2.AdditionalProperty6 ,
    t2.AdditionalProperty7 ,
    t2.AdditionalProperty8 ,
    t2.AdditionalProperty9 ,
    t2.AdditionalProperty10 ,
    t2.QtyCurrentByUnit ,
    t.Qtys as PurchasedQty ,
    t.Qtys ,
    t.TotalD as SoldQtyRate ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.CostD ,
    t.CostLL ,
    t.CostEuro ,
    t.ProfitTotalD ,
    t.ProfitTotalLL ,
    t.ProfitTotalEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
UNION ALL
SELECT 1 AS RowIn ,
    t1.DateOnly ,
    t.ItemSharedID ,
    t1.AccountCustomerID ,
    t2.Barcode ,
    t2.Name ,
    t2.Brand ,
    t2.MainCategory ,
    t2.AdditionalProperty1 ,
    t2.AdditionalProperty2 ,
    t2.AdditionalProperty3 ,
    t2.AdditionalProperty4 ,
    t2.AdditionalProperty5 ,
    t2.AdditionalProperty6 ,
    t2.AdditionalProperty7 ,
    t2.AdditionalProperty8 ,
    t2.AdditionalProperty9 ,
    t2.AdditionalProperty10 ,
    t2.QtyCurrentByUnit ,
    0 - t.Qtys as PurchasedQty ,
    0 - t.Qtys ,
    0 - t.TotalD AS SoldQtyRate ,
    0 - t.TotalD ,
    0 - t.TotalLL ,
    0 - t.TotalEuro ,
    0 - t.CostD ,
    0 - t.CostLL ,
    0 - t.CostEuro ,
    0 - t.ProfitTotalD ,
    0 - t.ProfitTotalLL ,
    0 - t.ProfitTotalEuro
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID;
  




