GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_SalesProfitReportItemsPurchasedQty]
AS
SELECT 0 AS RowIn ,
    t.ItemSharedID ,
    t1.DateOnly ,
    ISNULL(SUM(t.Qtys), 0) AS Qtys
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
  GROUP BY t.ItemSharedID ,
    t1.DateOnly
UNION ALL
SELECT 1 AS RowIn ,
    t.ItemSharedID ,
    t1.DateOnly ,
    ISNULL(SUM(0 - t.Qtys), 0) AS Qtys
  FROM Invoices.t_PurchasingReturnDetail AS t
  INNER JOIN Invoices.t_PurchasingReturn AS t1 ON t1.ID = t.PurchasingReturnID
  GROUP BY t.ItemSharedID ,
    t1.DateOnly;
  




