SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Invoices].[v_SellOrderDetailsPrints]
AS
SELECT t.ID ,
    t.SellOrderID ,
    t.PackUnitID ,
    t.PackUnitQty ,
    t.PackQtys ,
    t.Qty ,
    t.QtyWithUnit ,
    t.SalePrice ,
    t.Discount ,
    t.SubTotal ,
    t.InvoiceDiscount ,
    t.SubTotal2 ,
    t.Taxes ,
    t.TaxesLL ,
    t.TaxesEuro ,
    t.Total ,
    t.OrderBy ,
    t.AdditionsNames ,
    t2.Name + CASE LEN(t.DescriptionIs) WHEN 0 THEN N'' ELSE N' \ ' + t.DescriptionIs END AS Name ,
    t2.Barcode ,
    t2.ImageThumbnail ,
    t2.Brand ,
    t3.Name AS Category ,
    t3.Printer ,
    t3.Printer1 ,
    t3.Printer2 ,
    t3.Printer3 ,
    t3.Printer4 ,
    t3.Printer5 ,
    t5.Name AS Warehouse ,
    t8.Name AS Unit
  FROM Invoices.t_SellOrderDetails AS t
  INNER JOIN Invoices.t_SellOrder AS t1 ON t1.ID = t.SellOrderID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t2.MainCategoryID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t.WarehouseID
  INNER JOIN Company.t_Place AS t6 ON t6.ID = t4.PlaceID
  INNER JOIN Items.t_UnityItem AS t7 ON t7.ID = t.ItemUnitID
  INNER JOIN Items.t_Unity AS t8 ON t8.ID = t7.UnityID;
  
  









