SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Invoices].[v_SoldDailyNumber]
AS

SELECT  t.ID ,
        t.RefF ,
        ROW_NUMBER() OVER ( PARTITION BY t.DateOnly ORDER BY t.Ref ) AS DailyNumber
FROM    Invoices.t_Sold AS t;





GO
/****** Object:  View [Invoices].[v_SoldDailyReportOfInvoiceTax]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Invoices].[v_SoldDailyReportOfInvoiceTax]
AS
SELECT t.DateOnly ,
    t.AccountCustomer ,
    ISNULL(COUNT(t.ID), 0) AS InvoicesCount ,
    ISNULL(SUM(t.NetIsD), 0) AS TotalD ,
    ISNULL(SUM(t.NetIsLL), 0) AS TotalLL ,
    ISNULL(SUM(t.NonTaxableTotalD), 0) AS NonTaxableTotalD ,
    ISNULL(SUM(t.NonTaxableTotalLL), 0) AS NonTaxableTotalLL ,
    ISNULL(SUM(t.TaxableTotalD), 0) AS TaxableTotalD ,
    ISNULL(SUM(t.TaxableTotalLL), 0) AS TaxableTotalLL ,
    ISNULL(SUM(t.TaxValueD), 0) AS TaxValueD ,
    ISNULL(SUM(t.TaxValueLL), 0) AS TaxValueLL
  FROM Invoices.t_Sold AS t
  GROUP BY t.DateOnly ,
    t.AccountCustomer;
  




GO
