CREATE VIEW [Invoices].[v_SoldDeletedDetailEmployeeProfitList]
AS
SELECT t.ID ,
    t.SoldDeletedID ,
    t.SoldDeletedDetailID ,
    t.EmployeeID ,
    t.ProfitRatio ,
    t.ProfitRatioF ,
    t.ProfitOn ,
    t.Profit ,
    t.ProfitF ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.Paid ,
    t.DateCreate ,
    t.IsSync ,
    t1.Ref ,
    t1.RefF ,
    t1.DateIs ,
    t1.DateOnly ,
    t1.AccountCustomerID ,
    t1.AccountCustomer ,
    t3.ID AS ItemSharedID ,
    t3.Name ,
    t3.Barcode ,
    t3.Barcodes ,
    t3.ImageThumbnail ,
    t3.BrandID ,
    t3.Brand ,
    t3.MainCategoryID ,
    t3.MainCategory ,
    t3.SubCategoryID ,
    t3.SubCategory ,
    t5.ID AS WarehouseID ,
    t5.Name AS Warehouse ,
    t6.ID AS PlaceID ,
    t6.Name AS Place ,
    t7.Name AS Employee
  FROM Invoices.t_SoldDeletedDetailEmployeeProfit AS t
  INNER JOIN Invoices.t_SoldDeleted AS t1 ON t1.ID = t.SoldDeletedID
  INNER JOIN Invoices.t_SoldDeletedDetail AS t2 ON t2.ID = t.SoldDeletedDetailID
  INNER JOIN Items.t_ItemShared AS t3 ON t3.ID = t2.ItemSharedID
  INNER JOIN Items.t_Item AS t4 ON t4.ID = t2.ItemID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t4.WareHouseID
  INNER JOIN Company.t_Place AS t6 ON t6.ID = t4.PlaceID
  INNER JOIN Employees.t_Employee AS t7 ON t7.ID = t.EmployeeID;
  









