    t1.DateIs ,
    t1.DateOnly ,
    t1.CurrencyID ,
    t1.AccountCustomerID ,
    t1.AccountCustomer ,
    t1.RowVersionID ,
    t3.ID AS ItemSharedID ,
    t3.Name ,
    t3.Barcode ,
    t3.Barcodes ,
    0x AS ImageIs ,
    t3.BrandID ,
    t3.Brand ,
    t3.MainCategoryID ,
    t3.MainCategory ,
    t3.SubCategoryID ,
    t3.SubCategory ,
    t5.ID AS WarehouseID ,
