    t6.ID AS PlaceID ,
    t6.Name AS Place ,
    t7.Name AS Employee ,
	t8.Profit AS EmployeeProfit
  FROM Invoices.t_SoldDetailEmployeeProfit AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Invoices.t_SoldDetail AS t2 ON t2.ID = t.SoldDetailID
  INNER JOIN Items.t_ItemShared AS t3 ON t3.ID = t2.ItemSharedID
