    ISNULL(Calculation.Rate(t.PriceD, t.TaxRate), 0) AS PriceWithTaxD ,
    ISNULL(Calculation.Rate(t.PriceLL, t.TaxRate), 0) AS PriceWithTaxLL ,
    ISNULL(Calculation.Rate(t.PriceEuro, t.TaxRate), 0) AS PriceWithTaxEuro ,
