/****** Object:  View [Invoices].[v_SoldDetailLatestFinalPrice]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [Invoices].[v_SoldDetailLatestFinalPrice]
AS
SELECT DISTINCT MIN(t.ID) OVER ( PARTITION BY t2.AccountCustomerID, t.ItemSharedID, t.Total / t.Qty ORDER BY ( SELECT 0
                                                                                                             ) ) AS ID ,
    t2.DateOnly ,
    t2.AccountCustomerID ,
    t.ItemSharedID ,
    t1.Unity ,
    Currencys.f_Format(t2.CurrencyID, t.Total / t.Qty) AS NetPriceF
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
  INNER JOIN Invoices.t_Sold AS t2 ON t2.ID = t.SoldID;


