CREATE VIEW [Invoices].[v_SoldDetailLatestPrice]
AS
SELECT DISTINCT MIN(t.ID) OVER ( PARTITION BY t1.AccountCustomerID, t.ItemSharedID, t.Total / t.Qty ORDER BY ( SELECT 0
                                                                                                                 ) ) AS ID ,
    t.SoldID ,
    t1.Ref ,
    t1.DateOnly ,
    t1.AccountCustomerID ,
    t.ItemSharedID ,
    t.Qty ,
    t.QtyWithUnity ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.DiscountIs ,
    t.DiscountIsValueF ,
    t.DiscountIsValueD ,
    t.DiscountIsValueLL ,
    t.DiscountIsValueEuro ,
    t.SubTotalF ,
    t.SubTotalD ,
    t.SubTotalLL ,
    t.SubTotalEuro ,
    t.DiscountInvoiceF ,
    t.DiscountInvoiceD ,
    t.DiscountInvoiceLL ,
    t.DiscountInvoiceEuro ,
    t.SubTotal2F ,
    t.SubTotal2D ,
    t.SubTotal2LL ,
    t.SubTotal2Euro ,
    t.TaxRate ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.TaxValueLL ,
    t.TaxValueEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.CostF ,
    t.CostD ,
    t.CostLL ,
    t.CostEuro ,
    t.ProfitF ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.ProfitTotalF ,
    t.ProfitTotalD ,
    t.ProfitTotalLL ,
    t.ProfitTotalEuro ,
    Currencys.f_Format(t1.CurrencyID, t.Total / t.Qty) AS NetPriceF ,
    t.TotalD / t.Qty AS NetPriceD ,
    t.TotalLL / t.Qty AS NetPriceLL ,
    t.TotalEuro / t.Qty AS NetPriceEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID;

	

