    t.SubTotalEuro ,
    t.Total ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.DescriptionIs ,
    t.SerialNames ,
    t.SortAt ,
    t4.Name AS WareHouse
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
  INNER JOIN Items.t_UnityItem AS t2 ON t2.ID = t.ItemUnityID
  INNER JOIN Items.t_Item AS t3 ON t3.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t4 ON t4.ID = t3.WareHouseID;

  




