/****** Object:  View [Invoices].[v_SoldSalespersonInvoicesReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Invoices].[v_SoldSalespersonInvoicesReport]
AS
SELECT t.ID ,
    t.RefF ,
    t.DateOnly ,
    t.SalespersonID ,
    t.Salesperson ,
    t1.Name AS Account ,
    t.CurrencyID ,
    t2.TypeIs AS CurrencyTypeIs ,
    t.NetIsF ,
    t.NetIsD ,
    t.NetIsLL ,
    t.NetIsEuro ,
    t.ProfitF ,
    t.ProfitD ,
    t.ProfitLL ,
    t.ProfitEuro ,
    t.PaidUpF ,
    t.PaidUpD ,
    t.PaidUpLL ,
    t.PaidUpEuro ,
    t.RestF ,
    t.RestD ,
    t.RestLL ,
    t.RestEuro ,
    t.CommissionValueF ,
    t.CommissionValueD ,
    t.CommissionValueLL ,
    t.CommissionValueEuro ,
    t.CommissionAvailableValueF ,
    t.CommissionAvailableValueD ,
    t.CommissionAvailableValueLL ,
    t.CommissionAvailableValueEuro ,
    t.CommissionRateOn ,
    t.CommissionRateF ,
    t.SalespersonTakeCommission ,
    t.TotalQuantity
  FROM Invoices.t_Sold AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountCustomerID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID
UNION ALL
SELECT t.ID ,
    t.RefF ,
    t.DateOnly ,
    t.SalespersonID ,
    t3.Name AS Salesperson ,
    t1.Name AS Account ,
    t.CurrencyID ,
    t2.TypeIs AS CurrencyTypeIs ,
    N'-' + t.NetIsF AS NetIsF ,
    0 - t.NetIsD AS NetIsD ,
    0 - t.NetIsLL AS NetIsLL ,
    0 - t.NetIsEuro AS NetIsEuro ,
    N'-' + t.ProfitF AS ProfitF ,
    0 - t.ProfitD AS ProfitD ,
    0 - t.ProfitLL AS ProfitLL ,
    0 - t.ProfitEuro AS ProfitEuro ,
    N'-' + t.PaidUpF ,
    0 - t.PaidUpD ,
    0 - t.PaidUpLL ,
    0 - t.PaidUpEuro ,
    N'-' + t.RestF ,
    0 - t.RestD AS RestD ,
    0 - t.RestLL AS RestLL ,
    0 - t.RestEuro AS RestEuro ,
    N'-' + t.CommissionValueF AS CommissionValueF ,
    0 - t.CommissionValueD AS CommissionValueD ,
    0 - t.CommissionValueLL AS CommissionValueLL ,
    0 - t.CommissionValueEuro AS CommissionValueEuro ,
    N'' AS CommissionAvailableValueF ,
    0 AS CommissionAvailableValueD ,
    0 AS CommissionAvailableValueLL ,
    0 AS CommissionAvailableValueEuro ,
    t.CommissionRateOn ,
    t.CommissionRateF ,
    CONVERT(BIT, 1) AS SalespersonTakeCommission ,
    0 - t.Qtys AS TotalQuantity
  FROM Invoices.t_SoldReturn AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountCustomerID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID
  INNER JOIN Employees.t_SalesPerson AS t3 ON t3.ID = t.SalespersonID;
  








