/****** Object:  View [Invoices].[v_TrackDeletedItemsFromInvoicesDaily]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Invoices].[v_TrackDeletedItemsFromInvoicesDaily]
AS
SELECT ISNULL(MIN(t.ID), '00000000-0000-0000-0000-000000000000') AS ID ,
    t.DateOnly ,
    t.UserID ,
    t.ItemSharedID ,
    SUM(t.Qtys) AS Qtys ,
    Items.f_GetQtyCurrentByUnit(t.ItemSharedID, Calculation.GetDecimal_18_6(SUM(t.Qtys))) AS QtyWithUnit ,
    SUM(t.TotalD) AS TotalD ,
    SUM(t.TotalLL) AS TotalLL ,
    SUM(t.TotalEuro) AS TotalEuro ,
    SUM(t.TotalCostD) AS TotalCostD ,
    SUM(t.TotalCostLL) AS TotalCostLL ,
    SUM(t.TotalCostEuro) AS TotalCostEuro ,
    SUM(t.TotalProfitD) AS TotalProfitD ,
    SUM(t.TotalProfitLL) AS TotalProfitLL ,
    SUM(t.TotalProfitEuro) AS TotalProfitEuro ,
    t1.Name AS UsernameIs ,
    t2.Name ,
    t2.Barcode
  FROM Invoices.t_TrackDeletedItemsFromInvoices AS t
  INNER JOIN Users.t_User AS t1 ON t1.ID = t.UserID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  GROUP BY t.DateOnly ,
    t.UserID ,
    t.ItemSharedID ,
    t1.Name ,
    t2.Name ,
    t2.Barcode;
	





GO
