  INNER JOIN Company.t_WareHouse AS t3 ON t3.ID = t.WarehouseID
  INNER JOIN Items.t_UnityItem AS t4 ON t4.ID = t.ItemUnitID
  INNER JOIN Items.t_Unity AS t5 ON t5.ID = t4.UnityID
  INNER JOIN Currencys.t_Currency AS t6 ON t6.ID = t.CurrencyID;





