/****** Object:  View [Invoices].[v_TransferAwaitedDetailExpirationDateList]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Invoices].[v_TransferAwaitedDetailExpirationDateList]
AS
SELECT t.ID ,
    t.TransferAwaitedID ,
    t1.Ref ,
    t1.RefF ,
    t1.DateIs ,
    t.TransferAwaitedDetailID ,
    t.ItemSharedID ,
    t2.Name ,
    t2.Barcode AS ItemBarcode ,
    t3.ID AS FromItemID ,
    t4.ID AS ToItemID ,
    t1.FromWarehouseID ,
    t5.Name AS FromWarehouse ,
    t1.ToWarehouseID ,
    t6.Name AS ToWarehouse ,
    t.Barcode ,
    t.Qtys ,
    t.ProductionDate ,
    t.ExpirationDate ,
    t.NotifyMeDaysBefore ,
    t.NotificationDate ,
    t.CurrencyID ,
    t7.Name AS Currency ,
    t.Price ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.BatchNumber ,
    t.DescriptionIs ,
    t.DateCreate ,
    t.IsSync ,
    t.WorkStationID
  FROM Invoices.t_TransferAwaitedDetailExpirationDate AS t
  INNER JOIN Invoices.t_TransferAwaited AS t1 ON t1.ID = t.TransferAwaitedID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t2.ID AND t3.WareHouseID = t1.FromWarehouseID
  INNER JOIN Items.t_Item AS t4 ON t4.SharedID = t2.ID AND t4.WareHouseID = t1.ToWarehouseID
  INNER JOIN Company.t_WareHouse AS t5 ON t5.ID = t1.FromWarehouseID
  INNER JOIN Company.t_WareHouse AS t6 ON t6.ID = t1.ToWarehouseID
  INNER JOIN Currencys.t_Currency AS t7 ON t7.ID = t.CurrencyID;
   



