/****** Object:  View [Invoices].[v_WeeklySalesReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [Invoices].[v_WeeklySalesReport]
AS
SELECT ISNULL(DATEPART(WEEK, t.DateOnly), 0) AS WeekNumber ,
    t.DateYearly ,
    COUNT(t.ID) AS NumberOfInvoices ,
    SUM(t.NetIsD) AS NetIsD ,
    SUM(t.NetIsLL) AS NetIsLL ,
    SUM(t.NetIsEuro) AS NetIsEuro ,
    SUM(t.PaidUpD) AS PaidupD ,
    SUM(t.PaidUpLL) AS PaidupLL ,
    SUM(t.PaidUpEuro) AS PaidupEuro ,
    SUM(t.RestD) AS RestD ,
    SUM(t.RestLL) AS RestLL ,
    SUM(t.RestEuro) AS RestEuro
  FROM Invoices.t_Sold AS t
  GROUP BY DATEPART(WEEK, t.DateOnly) ,
    t.DateYearly;
 






GO
/****** Object:  View [Invoices].[v_WeeklySalesReport_WithReturn]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE VIEW [Invoices].[v_WeeklySalesReport_WithReturn]
AS
SELECT ISNULL(o.WeekNumber, 0) AS WeekNumber ,
    o.DateYearly ,
    SUM(o.NumberOfInvoices) AS NumberOfInvoices ,
    SUM(o.NetIsD) AS NetIsD ,
    SUM(o.NetIsLL) AS NetIsLL ,
    SUM(o.NetIsEuro) AS NetIsEuro ,
    SUM(o.PaidupD) AS PaidupD ,
    SUM(o.PaidupLL) AS PaidupLL ,
    SUM(o.PaidupEuro) AS PaidupEuro ,
    SUM(o.RestD) AS RestD ,
    SUM(o.RestLL) AS RestLL ,
    SUM(o.RestEuro) AS RestEuro
  FROM ( SELECT DATEPART(WEEK, t.DateOnly) AS WeekNumber ,
            t.DateYearly ,
            COUNT(t.ID) AS NumberOfInvoices ,
            SUM(t.NetIsD) AS NetIsD ,
            SUM(t.NetIsLL) AS NetIsLL ,
            SUM(t.NetIsEuro) AS NetIsEuro ,
            SUM(t.PaidUpD) AS PaidupD ,
            SUM(t.PaidUpLL) AS PaidupLL ,
            SUM(t.PaidUpEuro) AS PaidupEuro ,
            SUM(t.RestD) AS RestD ,
            SUM(t.RestLL) AS RestLL ,
            SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_Sold AS t
          GROUP BY DATEPART(WEEK, t.DateOnly) ,
            t.DateYearly
         UNION ALL
         SELECT DATEPART(WEEK, t.DateOnly) AS WeekNumber ,
            t.DateYearly ,
            COUNT(t.ID) AS NumberOfInvoices ,
            0 - SUM(t.NetIsD) AS NetIsD ,
            0 - SUM(t.NetIsLL) AS NetIsLL ,
            0 - SUM(t.NetIsEuro) AS NetIsEuro ,
            0 - SUM(t.PaidUpD) AS PaidupD ,
            0 - SUM(t.PaidUpLL) AS PaidupLL ,
            0 - SUM(t.PaidUpEuro) AS PaidupEuro ,
            0 - SUM(t.RestD) AS RestD ,
            0 - SUM(t.RestLL) AS RestLL ,
            0 - SUM(t.RestEuro) AS RestEuro
          FROM Invoices.t_SoldReturn AS t
          GROUP BY DATEPART(WEEK, t.DateOnly) ,
            t.DateYearly
       ) AS o
  GROUP BY o.WeekNumber ,
    o.DateYearly;
 






