    0. AS DiscountIsValueLL ,
    0. AS DiscountIsValueEuro ,
    N'' AS SubTotalF ,
    0. AS SubTotalD ,
    0. AS SubTotalLL ,
    0. AS SubTotalEuro ,
    N'' AS DiscountInvoiceF ,
    0. AS DiscountInvoiceD ,
    0. AS DiscountInvoiceLL ,
    0. AS DiscountInvoiceEuro ,
    0 AS FutureDiscountRate ,
    N'' AS FutureDiscountRateF ,
    0 AS FutureUnitDiscount ,
    N'' AS FutureUnitDiscountF ,
    0 AS FutureUnitDiscountD ,
    0 AS FutureUnitDiscountLL ,
    0 AS FutureUnitDiscountEuro ,
    0 AS FutureTotalDiscount ,
    N'' AS FutureTotalDiscountF ,
    0 AS FutureTotalDiscountD ,
    0 AS FutureTotalDiscountLL ,
    0 AS FutureTotalDiscountEuro ,
    0. AS TaxRate ,
    N'' AS TaxRateF ,
    N'' AS TaxValueF ,
    0. AS TaxValueD ,
    0. AS TaxValueLL ,
    0. AS TaxValueEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    N'' AS UnitExpensesF ,
    0. AS UnitExpensesD ,
    0. AS UnitExpensesLL ,
    0. AS UnitExpensesEuro ,
    N'' AS InvoiceExpensesF ,
    0. AS InvoiceExpensesD ,
    0. AS InvoiceExpensesLL ,
    0. AS InvoiceExpensesEuro ,
    N'' AS FinalUnitCostF ,
    0. AS FinalUnitCostD ,
    0. AS FinalUnitCostLL ,
    0. AS FinalUnitCostEuro ,
    N'' AS TotalFinalCostF ,
    0. AS TotalFinalCostD ,
    0. AS TotalFinalCostLL ,
    0. AS TotalFinalCostEuro ,
    t.DescriptionIs ,
    t.DateCreate ,
    t.IsSync ,
    158 AS SectionIs ,
    t1.Ref ,
    t1.RefF ,
    t1.DateIs ,
    N'00000000-0000-0000-0000-000000000000' AS AccountID ,
    N'' AS Account ,
    N'' AS AccountNumber ,
    t2.Name ,
    t2.Barcode ,
    t2.Barcodes ,
    t2.BrandID ,
    t2.Brand ,
    t2.MainCategoryID ,
    t2.MainCategory ,
    t2.SubCategoryID ,
    t2.SubCategory ,
    t3.WareHouseID ,
    t3.WareHouse ,
    t3.PlaceID ,
    t3.Place ,
    t4.UnityID AS UnitID ,
    t5.Name AS Unit
  FROM Items.t_BeginningInventoryQuantityDetail AS t
  INNER JOIN Items.t_BeginningInventoryQuantity AS t1 ON t1.ID = t.BeginningInventoryQuantityID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t3 ON t3.ID = t.ItemID
  INNER JOIN Items.t_UnityItem AS t4 ON t4.ID = t.ItemUnityID
  INNER JOIN Items.t_Unity AS t5 ON t5.ID = t4.UnityID;
  







