    t1.MainCategory ,
    t1.SubCategory ,
    t1.ColorIs ,
    t1.SizeIs ,
    t1.AdditionalProperty1 ,
    t1.AdditionalProperty2 ,
    t1.AdditionalProperty3 ,
    t1.AdditionalProperty4 ,
    t1.AdditionalProperty5 ,
    t1.AdditionalProperty6 ,
    t1.AdditionalProperty7 ,
    t1.AdditionalProperty8 ,
    t1.AdditionalProperty9 ,
    t1.AdditionalProperty10 ,
    t1.NetWeight ,
    t.QtyCurrent ,
    t1.CurrencyID ,
    t2.TypeIs AS CurrencyType ,
    t1.Purchase ,
    t1.PurchaseD ,
    t1.PurchaseLL ,
    t1.PurchaseEuro ,
    t1.PurchaseTotal ,
    t1.PurchaseTotalD ,
    t1.PurchaseTotalLL ,
    t1.PurchaseTotalEuro ,
    t1.SellCurrencyID AS CurrencyIDSell ,
    t3.TypeIs AS CurrencyTypeSell ,
    t1.Sell ,
    t1.SellD ,
    t1.SellLL ,
    t1.SellEuro ,
    t1.SellTotal ,
    t1.SellTotalD ,
    t1.SellTotalLL ,
    t1.SellTotalEuro ,
    t1.LastCost ,
    t1.LastCostD ,
    t1.LastCostLL ,
    t1.LastCostEuro ,
    t1.AverageCost ,
    t1.AverageCostD ,
    t1.AverageCostLL ,
    t1.AverageCostEuro ,
    t1.HigherCost ,
    t1.HigherCostD ,
    t1.HigherCostLL ,
    t1.HigherCostEuro ,
    t1.LowerCost ,
    t1.LowerCostD ,
    t1.LowerCostLL ,
    t1.LowerCostEuro ,
    t.WareHouseID
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.CurrencyID
