/****** Object:  View [Items].[v_ItemGoodsValueReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Items].[v_ItemGoodsValueReport]
AS
SELECT t.ID ,
    t1.Brand ,
    t1.MainCategory ,
    t.QtyCurrent ,
    t2.TypeIs AS CurrencyType ,
    t1.PurchaseD ,
    t1.PurchaseLL ,
    t1.PurchaseEuro ,
    ISNULL(t1.PurchaseD * t.QtyCurrent, 0) AS PurchaseTotalD ,
    ISNULL(t1.PurchaseLL * t.QtyCurrent, 0) AS PurchaseTotalLL ,
    ISNULL(t1.PurchaseEuro * t.QtyCurrent, 0) AS PurchaseTotalEuro ,
    t3.TypeIs AS CurrencyTypeSell ,
    t4.DistributionPriceD ,
    t4.DistributionPriceLL ,
    t4.DistributionPriceEuro ,
    ISNULL(t4.DistributionPriceD * t.QtyCurrent, 0) AS TotalDistributionD ,
    ISNULL(t4.DistributionPriceLL * t.QtyCurrent, 0) AS TotalDistributionLL ,
    ISNULL(t4.DistributionPriceEuro * t.QtyCurrent, 0) AS TotalDistributionEuro ,
    t4.WholesalePriceD ,
    t4.WholesalePriceLL ,
    t4.WholesalePriceEuro ,
    ISNULL(t4.WholesalePriceD * t.QtyCurrent, 0) AS TotalWholesaleD ,
    ISNULL(t4.WholesalePriceLL * t.QtyCurrent, 0) AS TotalWholesaleLL ,
    ISNULL(t4.WholesalePriceEuro * t.QtyCurrent, 0) AS TotalWholesaleEuro ,
    t1.SellD ,
    t1.SellLL ,
    t1.SellEuro ,
    ISNULL(t1.SellD * t.QtyCurrent, 0) AS SellTotalD ,
    ISNULL(t1.SellLL * t.QtyCurrent, 0) AS SellTotalLL ,
    ISNULL(t1.SellEuro * t.QtyCurrent, 0) AS SellTotalEuro ,
    t.WareHouseID
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t1.CurrencyID
  INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t1.SellCurrencyID
  INNER JOIN Items.t_UnityItem AS t4 ON t4.SharedID = t1.ID AND t4.PrimaryIs = 1 AND t4.Qty = 1
  WHERE t1.StatusIs <> 2 AND t1.TypeIs <> 1;
   		









