/****** Object:  View [Items].[v_ItemMaterialsReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO





CREATE VIEW [Items].[v_ItemMaterialsReport]
AS
SELECT t.ID ,
    t.ItemSharedFatherID ,
    t.ItemSharedID ,
    t.ItemUnityID ,
    t.Qty ,
    t.Qtys ,
    t.OrderBy ,
    t.DescriptionIs ,
    t1.Name ,
    t1.Barcode ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t1.PurchaseF AS UnitCostF ,
    t1.PurchaseD AS UnitCostD ,
    t1.PurchaseLL AS UnitCostLL ,
    t1.PurchaseEuro AS UnitCostEuro ,
    Currencys.f_Format(t1.CurrencyID, t1.Purchase * t.Qtys) AS TotalF ,
    t1.PurchaseD * t.Qtys AS TotalD ,
    t1.PurchaseLL * t.Qtys AS TotalLL ,
    t1.PurchaseEuro * t.Qtys AS TotalEuro ,
    t2.Name AS Brand ,
    t3.Name AS MainCategory ,
    t4.Name AS SubCategory ,
    t5.Qty AS UnitQty ,
    t6.Name AS Unit
  FROM Items.t_ItemSharedMaterial AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t.ItemSharedID = t1.ID
  INNER JOIN Items.t_Brand AS t2 ON t2.ID = t1.BrandID
  INNER JOIN Items.t_MainCategory AS t3 ON t3.ID = t1.MainCategoryID
  INNER JOIN Items.t_SubCategory AS t4 ON t4.ID = t1.SubCategoryID
  INNER JOIN Items.t_UnityItem AS t5 ON t5.ID = t.ItemUnityID
  INNER JOIN Items.t_Unity AS t6 ON t6.ID = t5.UnityID;
   






