CREATE VIEW [Items].[v_ItemPurchasedQuantityReport]
AS
SELECT t3.DateOnly ,
    t3.AccountVendor AS Account ,
    t3.UserIs ,
    t.ItemSharedID ,
    t2.Name ,
    t2.Barcode ,
    t2.DescriptionIs ,
    SUM(t.Qtys) AS Qtys ,
    SUM(t.TotalD) AS TotalD ,
    SUM(t.TotalLL) AS TotalLL ,
    SUM(t.TotalEuro) AS TotalEuro ,
    t2.Brand ,
    t2.MainCategory ,
    t1.WareHouse
  FROM Invoices.t_PurchasingDetail AS t
  INNER JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Invoices.t_Purchasing AS t3 ON t3.ID = t.PurchasingID
  GROUP BY t3.DateOnly ,
    t3.AccountVendor ,
    t3.UserIs ,
    t.ItemSharedID ,
    t2.Name ,
    t2.Barcode ,
    t2.DescriptionIs ,
    t2.Brand ,
    t2.MainCategory ,
    t1.WareHouse;

  





