GO


CREATE VIEW [Items].[v_ItemSalesReport]
AS
SELECT t.ID ,
    t.SoldID ,
    t3.DateIs ,
    t3.DateOnly ,
    t3.Ref ,
    t3.AccountCustomerID AS AccountID ,
    t3.AccountCustomer AS Account ,
    t.ItemSharedID ,
    t.ItemID ,
    t2.Name AS Warehouse ,
    t.Qty ,
    t.Qtys ,
    t6.Name AS Unity ,
    t3.CurrencyID ,
    t4.TypeIs AS CurrencyTypeIs ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.DiscountIsValue ,
    t.DiscountIsValueD ,
    t.DiscountIsValueLL ,
    t.DiscountIsValueEuro ,
    t.DiscountInvoice ,
    t.DiscountInvoiceD ,
    t.DiscountInvoiceLL ,
    t.DiscountInvoiceEuro ,
    t.TaxValueF ,
    t.TaxValueD ,
    t.TaxValueLL ,
    t.TaxValueEuro ,
    t.TotalF ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro ,
    t.ProfitF AS UnitProfitF ,
    t.ProfitD AS UnitProfitD ,
    t.ProfitLL AS UnitProfitLL ,
    t.ProfitEuro AS UnitProfitEuro ,
    t.ProfitTotalF AS TotalProfitF ,
    t.ProfitTotalD AS TotalProfitD ,
    t.ProfitTotalLL AS TotalProfitLL ,
    t.ProfitTotalEuro AS TotalProfitEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t1.WareHouseID
  INNER JOIN Invoices.t_Sold AS t3 ON t3.ID = t.SoldID
  INNER JOIN Currencys.t_Currency AS t4 ON t4.ID = t3.CurrencyID
  INNER JOIN Items.t_UnityItem AS t5 ON t5.ID = t.ItemUnityID
  INNER JOIN Items.t_Unity AS t6 ON t6.ID = t5.UnityID;  




