/****** Object:  View [Items].[v_ItemSerialMovementList]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_ItemSerialMovementList]
AS
SELECT t.ID ,
    0 AS SectionType ,
    t.PurchasingID AS SectionID ,
    t1.RefF ,
    t1.AccountVendorID AS AccountID ,
    t1.AccountVendor AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_PurchasingDetailSerial AS t
  INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
UNION ALL
SELECT t.ID ,
    1 AS SectionType ,
    t.PurchasingReturnID AS SectionID ,
    t1.RefF ,
    t1.AccountVendorID AS AccountID ,
    t1.AccountVendor AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_PurchasingReturnDetailSerial AS t
  INNER JOIN Invoices.t_PurchasingReturn AS t1 ON t1.ID = t.PurchasingReturnID
UNION ALL
SELECT t.ID ,
    2 AS SectionType ,
    t.SoldID AS SectionID ,
    t1.RefF ,
    t1.AccountCustomerID AS AccountID ,
    t1.AccountCustomer AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_SoldDetailSerial AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
UNION ALL
SELECT t.ID ,
    3 AS SectionType ,
    t.SoldReturnID AS SectionID ,
    t1.RefF ,
    t1.AccountCustomerID AS AccountID ,
    t1.AccountCustomer AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_SoldReturnDetailSerial AS t
  INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
UNION ALL
SELECT t.ID ,
    158 AS SectionType ,
    t.BeginningInventoryQuantityID AS SectionID ,
    t1.RefF ,
    Alls.f_GetEmptyGuid() AS AccountID ,
    '' AS Account ,
    CONVERT(DATE, t1.DateIs) ,
    t.SerialID
  FROM Items.t_BeginningInventoryQuantityDetailSerial AS t
  INNER JOIN Items.t_BeginningInventoryQuantity AS t1 ON t1.ID = t.BeginningInventoryQuantityID
UNION ALL
SELECT t.ID ,
    155 AS SectionType ,
    t.ItemProductionID AS SectionID ,
    t1.RefF ,
    Alls.f_GetEmptyGuid() AS AccountID ,
    t1.Employee AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_ItemProductionSerial AS t
  INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
UNION ALL
SELECT t.ID ,
    155 AS SectionType ,
    t.ItemProductionID AS SectionID ,
    t1.RefF ,
    Alls.f_GetEmptyGuid() AS AccountID ,
    t1.Employee AS Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_ItemProductionMaterialSerial AS t
  INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
UNION ALL
SELECT t.ID ,
    197 AS SectionType ,
    t.DeliveryPermissionID AS SectionID ,
    t1.RefF ,
    t1.AccountID ,
    t1.Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_DeliveryPermissionDetailSerial AS t
  INNER JOIN Items.t_DeliveryPermission AS t1 ON t1.ID = t.DeliveryPermissionID
UNION ALL
SELECT t.ID ,
    200 AS SectionType ,
    t.DeliveryPermissionHistoryID AS SectionID ,
    t1.RefF ,
    t1.AccountID ,
    t1.Account ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_DeliveryPermissionHistoryDetailSerial AS t
  INNER JOIN Items.t_DeliveryPermissionHistory AS t1 ON t1.ID = t.DeliveryPermissionHistoryID
UNION ALL
SELECT t.ID ,
    7 AS SectionType ,
    t.StockAdjustmentID AS SectionID ,
    t1.RefF ,
    t1.UserID ,
    t1.UserIs ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_StockAdjustmentDetailSerial AS t
  INNER JOIN Items.t_StockAdjustment AS t1 ON t1.ID = t.StockAdjustmentID
UNION ALL
SELECT t.ID ,
    101 AS SectionType ,
    t.StockTakeID AS SectionID ,
    t1.RefF ,
    t1.UserID ,
    t1.UserIs ,
    t1.DateOnly ,
    t.SerialID
  FROM Items.t_StockTakeDetailSerial AS t
  INNER JOIN Items.t_StockTake AS t1 ON t1.ID = t.StockTakeID
UNION ALL
SELECT t.ID ,
    50 AS SectionType ,
    t.TransferAwaitedID AS SectionID ,
    t1.RefF ,
    t1.UserID ,
    t1.UserIs ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_TransferAwaitedDetailSerial AS t
  INNER JOIN Invoices.t_TransferAwaited AS t1 ON t1.ID = t.TransferAwaitedID
UNION ALL
SELECT t.ID ,
    50 AS SectionType ,
    t.TransferID AS SectionID ,
    t1.RefF ,
    t1.UserID ,
    t1.UserIs ,
    t1.DateOnly ,
    t.SerialID
  FROM Invoices.t_TransferDetailSerial AS t
  INNER JOIN Invoices.t_Transfer AS t1 ON t1.ID = t.TransferID;





