/****** Object:  View [Items].[v_ItemSharedAllCostWithoutTax]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_ItemSharedAllCostWithoutTax]
AS
SELECT 0 AS SectionType ,
    s.ItemSharedID ,
    SUM(s.Qtys) AS Qtys ,
    SUM(s.SubTotalD - s.DiscountInvoiceD + s.InvoiceExpensesD - s.FutureTotalDiscountD) AS TotalD ,
    SUM(s.SubTotalLL - s.DiscountInvoiceLL + s.InvoiceExpensesLL - s.FutureTotalDiscountLL) AS TotalLL ,
    SUM(s.SubTotalEuro - s.DiscountInvoiceEuro + s.InvoiceExpensesEuro - s.FutureTotalDiscountEuro) AS TotalEuro ,
    s1.DateIs
  FROM Invoices.t_PurchasingDetail AS s
  INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
  WHERE s.Qtys <> 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 1 AS SectionType ,
    s.ItemSharedID ,
    SUM(s.Qtys) AS Qtys ,
    SUM(s.TotalD) AS TotalD ,
    SUM(s.TotalLL) AS TotalLL ,
    SUM(s.TotalEuro) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_BeginningInventoryQuantityDetail AS s
  INNER JOIN Items.t_BeginningInventoryQuantity AS s1 ON s1.ID = s.BeginningInventoryQuantityID
  WHERE s.Qtys <> 0 and s.Total > 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 2 AS SectionType ,
    s.ItemSharedID ,
    ABS(SUM(s.Qtys)) AS Qtys ,
    ABS(SUM(s.TotalD)) AS TotalD ,
    ABS(SUM(s.TotalLL)) AS TotalLL ,
    ABS(SUM(s.TotalEuro)) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_StockTakeDetail AS s
  INNER JOIN Items.t_StockTake AS s1 ON s1.ID = s.StockTakeID
  WHERE s.Qtys <> 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 3 AS SectionType ,
    s.ItemSharedID ,
    ABS(SUM(s.Qtys)) AS Qtys ,
    ABS(SUM(s.TotalD)) AS TotalD ,
    ABS(SUM(s.TotalLL)) AS TotalLL ,
    ABS(SUM(s.TotalEuro)) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_StockAdjustmentDetail AS s
  INNER JOIN Items.t_StockAdjustment AS s1 ON s1.ID = s.StockAdjustmentID
  WHERE s.Qtys <> 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID; 
  












GO
/****** Object:  View [Items].[v_ItemSharedAllCostWithoutTaxWithoutFree]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Items].[v_ItemSharedAllCostWithoutTaxWithoutFree]
AS
SELECT 0 AS SectionType ,
    s.ItemSharedID ,
    SUM(s.Qtys) AS Qtys ,
    SUM(s.SubTotalD - s.DiscountInvoiceD + s.InvoiceExpensesD - s.FutureTotalDiscountD) AS TotalD ,
    SUM(s.SubTotalLL - s.DiscountInvoiceLL + s.InvoiceExpensesLL - s.FutureTotalDiscountLL) AS TotalLL ,
    SUM(s.SubTotalEuro - s.DiscountInvoiceEuro + s.InvoiceExpensesEuro - s.FutureTotalDiscountEuro) AS TotalEuro ,
    s1.DateIs
  FROM Invoices.t_PurchasingDetail AS s
  INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
  WHERE s.TotalFinalCostLL > 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 1 AS SectionType ,
    s.ItemSharedID ,
    SUM(s.Qtys) AS Qtys ,
    SUM(s.TotalD) AS TotalD ,
    SUM(s.TotalLL) AS TotalLL ,
    SUM(s.TotalEuro) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_BeginningInventoryQuantityDetail AS s
  INNER JOIN Items.t_BeginningInventoryQuantity AS s1 ON s1.ID = s.BeginningInventoryQuantityID
  WHERE s.Total > 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 2 AS SectionType ,
    s.ItemSharedID ,
    ABS(SUM(s.Qtys)) AS Qtys ,
    ABS(SUM(s.TotalD)) AS TotalD ,
    ABS(SUM(s.TotalLL)) AS TotalLL ,
    ABS(SUM(s.TotalEuro)) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_StockTakeDetail AS s
  INNER JOIN Items.t_StockTake AS s1 ON s1.ID = s.StockTakeID
  WHERE ABS(s.TotalD) <> 0 AND s.Qtys <> 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID
UNION ALL
SELECT 3 AS SectionType ,
    s.ItemSharedID ,
    ABS(SUM(s.Qtys)) AS Qtys ,
    ABS(SUM(s.TotalD)) AS TotalD ,
    ABS(SUM(s.TotalLL)) AS TotalLL ,
    ABS(SUM(s.TotalEuro)) AS TotalEuro ,
    s1.DateIs
  FROM Items.t_StockAdjustmentDetail AS s
  INNER JOIN Items.t_StockAdjustment AS s1 ON s1.ID = s.StockAdjustmentID
  WHERE ABS(s.TotalD) <> 0 AND s.Qtys <> 0
  GROUP BY s1.DateIs ,
    s.ItemSharedID; 
  


  



