CREATE VIEW [Items].[v_ItemSharedBarcodePrefixChoose]
AS
SELECT t.ID ,
    t.CountryCode ,
    t.ManufacturerCode ,
    t.TotalCount ,
    t.WithCheckDigit ,
    t.IsDefault ,
    CASE WHEN ROW_NUMBER() OVER ( ORDER BY t.CountryCode ) + 1 <= 12 THEN N'F' + FORMAT(ROW_NUMBER() OVER ( ORDER BY t.CountryCode ) + 1, N'0')
