SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_ItemSharedCompleteList]
AS
SELECT t.ID ,
    t.Name
  FROM Items.t_ItemShared AS t
  WHERE t.StatusIs <> 2
UNION
SELECT t.ID ,
    t.NameInvoice
  FROM Items.t_ItemShared AS t
  WHERE t.StatusIs <> 2 AND t.NameInvoice <> N''
UNION
SELECT t.ID ,
    t.BarCode
  FROM Items.t_ItemSharedBarCode AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  WHERE t1.StatusIs <> 2
UNION
SELECT t.ID ,
    t.Barcode
  FROM Items.t_ItemsPackage AS t
  WHERE t.Barcode <> N'';

  

