CREATE VIEW [Items].[v_ItemSharedMaterialEdit]
AS
SELECT t.ID ,
    t1.Name AS NameFather ,
    t.ItemSharedID ,
    t2.Name ,
    t2.IsSerial ,
    t.Qty ,
    t3.Unity ,
    t.QtyWithUnity ,
    t.DescriptionIs ,
	t.OrderBy
  FROM Items.t_ItemSharedMaterial AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedFatherID
  INNER JOIN Items.t_ItemShared AS t2 ON t.ItemSharedID = t2.ID
  INNER JOIN Items.t_UnityItem AS t3 ON t3.ID = t.ItemUnityID;
    



