    t2.PurchaseEuro AS UnitCostEuro ,
    Currencys.f_Format(t2.CurrencyID, t2.Purchase * t.Qtys) AS TotalCostF ,
    t2.PurchaseD * t.Qtys AS TotalCostD ,
    t2.PurchaseLL * t.Qtys AS TotalCostLL ,
    t2.PurchaseEuro * t.Qtys AS TotalCostEuro ,
    t2.PurchaseWithTaxF AS UnitCostWithTaxF ,
    t2.PurchaseWithTaxD AS UnitCostWithTaxD ,
    t2.PurchaseWithTaxLL AS UnitCostWithTaxLL ,
    t2.PurchaseWithTaxEuro AS UnitCostWithTaxEuro ,
    Currencys.f_Format(t2.CurrencyID, t2.PurchaseWithTax * t.Qtys) AS TotalCostWithTaxF ,
    t2.PurchaseWithTaxD * t.Qtys AS TotalCostWithTaxD ,
    t2.PurchaseWithTaxLL * t.Qtys AS TotalCostWithTaxLL ,
    t2.PurchaseWithTaxEuro * t.Qtys AS TotalCostWithTaxEuro
  FROM Items.t_ItemSharedMaterial AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedFatherID
  INNER JOIN Items.t_ItemShared AS t2 ON t.ItemSharedID = t2.ID;
   



