/****** Object:  View [Items].[v_ItemsProducedAndSoldReport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE VIEW [Items].[v_ItemsProducedAndSoldReport]
AS
SELECT t.ID ,
    0 AS RowID ,
    t.DateOnly ,
    t1.Name AS Warehouse ,
    t2.Name AS UserIs ,
    t.ItemSharedID ,
    t3.Barcode ,
    t3.Name ,
    t3.QtyCurrent ,
    t.Qtys ,
    0 AS TotalD ,
    0 AS TotalLL ,
    0 AS TotalEuro
  FROM Items.t_ItemProduction AS t
  INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WarehouseID
  INNER JOIN Users.t_User AS t2 ON t2.ID = t.CreateByID
  INNER JOIN Items.t_ItemShared AS t3 ON t3.ID = t.ItemSharedID
  WHERE t.StageType = 2 AND t3.StatusIs <> 2
UNION ALL
SELECT t.ID ,
    1 AS RowID ,
    t1.DateOnly ,
    t4.Name AS Warehouse ,
    t1.UserIs ,
    t.ItemSharedID ,
    t2.Barcode ,
    t2.Name ,
    t2.QtyCurrent ,
    t.Qtys ,
    t.TotalD ,
    t.TotalLL ,
    t.TotalEuro
  FROM Invoices.t_SoldDetail AS t
  INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t3 ON t3.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t4 ON t4.ID = t3.WareHouseID
  WHERE t2.StatusIs <> 2 AND t2.MaterialsCounts > 0
UNION ALL
SELECT t.ID ,
    2 AS RowID ,
    t1.DateOnly ,
    t4.Name AS Warehouse ,
    t1.UserIs ,
    t.ItemSharedID ,
    t2.Barcode ,
    t2.Name ,
    t2.QtyCurrent ,
    ISNULL(0 - t.Qtys, 0) AS Qtys ,
    ISNULL(0 - t.TotalD, 0) AS TotalD ,
    ISNULL(0 - t.TotalLL, 0) AS TotalLL ,
    ISNULL(0 - t.TotalEuro, 0) AS TotalEuro
  FROM Invoices.t_SoldReturnDetail AS t
  INNER JOIN Invoices.t_SoldReturn AS t1 ON t1.ID = t.SoldReturnID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
  INNER JOIN Items.t_Item AS t3 ON t3.ID = t.ItemID
  INNER JOIN Company.t_WareHouse AS t4 ON t4.ID = t3.WareHouseID
  WHERE t2.StatusIs <> 2 AND t2.MaterialsCounts > 0;





GO
