CREATE VIEW [Items].[v_ItemsToBeInventoried]
AS
SELECT t.ID ,
    t.SharedID ,
    t.WareHouseID ,
    t.QtyCurrent ,
    t.StockTakeEvery ,
    t.StockTakeEveryNotificationDate ,
    t.IsUsed ,
    t1.Name AS Warehouse ,
    t2.Name ,
    t2.Barcode ,
    t2.CurrencyID ,
    t2.Purchase ,
    t2.PurchaseD ,
    t2.IsSerial ,
    t2.IsExpiryDate ,
    t2.LifeSpanDays ,
    t2.NoticeDaysBeforeExpiryDate ,
    t2.SizeIs ,
    t2.ColorIs ,
    t2.ColorInt ,
    t2.AdditionalProperty1 ,
    t2.AdditionalProperty2 ,
    t2.AdditionalProperty3 ,
    t2.AdditionalProperty4 ,
    t2.AdditionalProperty5 ,
    t2.AdditionalProperty6 ,
    t2.AdditionalProperty7 ,
    t2.AdditionalProperty8 ,
    t2.AdditionalProperty9 ,
    t2.AdditionalProperty10 ,
    t2.VendorNames ,
    t2.UnitsDetails ,
    t3.Name AS Brand ,
    t4.Name AS MainCategory ,
    t5.Name AS SubCategory
  FROM Items.t_Item AS t
  INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WareHouseID
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.SharedID
  INNER JOIN Items.t_Brand AS t3 ON t3.ID = t2.BrandID
  INNER JOIN Items.t_MainCategory AS t4 ON t4.ID = t2.MainCategoryID
  INNER JOIN Items.t_SubCategory AS t5 ON t5.ID = t4.ID
  WHERE t2.StatusIs <> 2 AND t2.TypeIs = 0;

  








