    t1.Name ,
    t1.Barcode ,
    t1.ImageThumbnail ,
    t1.CurrencyID ,
    t1.Purchase ,
    t1.IsSerial ,
    t1.IsExpiryDate ,
    t1.LifeSpanDays ,
