    t.Unity ,
    t.Qty ,
    t.SharedID ,
    IIF(t.QtyCurrent >= t.Qty, 1, 0) AS AvailableQty ,
    t.PriceD ,
    Currencys.f_CurrencyRounding(t.PriceLL, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS PriceLL ,
    t.WholesalePriceD ,
    Currencys.f_CurrencyRounding(t.WholesalePriceLL, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS WholesalePriceLL ,
    t.DistributionPriceD ,
    Currencys.f_CurrencyRounding(t.DistributionPriceLL, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS DistributionPriceLL
  FROM Items.t_UnityItem AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.TypeIs = 1;
  

