/****** Object:  View [Items].[v_UnityItemPriceWithTaxFromCostChecker]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE VIEW [Items].[v_UnityItemPriceWithTaxFromCostChecker]
AS
SELECT t.ID ,
    t.Unity ,
    t.Qty ,
    t.SharedID ,
    IIF(t.QtyCurrent >= t.Qty, 1, 0) AS AvailableQty ,
    t.PriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS PriceD ,
    Currencys.f_CurrencyRounding(t.PriceLL + Calculation.GetTax(t.CostD, t2.TaxRate) * t1.ExchangeRateTax, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS PriceLL ,
    t.WholesalePriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS WholesalePriceD ,
    Currencys.f_CurrencyRounding(t.WholesalePriceLL + Calculation.GetTax(t.CostD, t2.TaxRate) * t1.ExchangeRateTax, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS WholesalePriceLL ,
    t.DistributionPriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS DistributionPriceD ,
    Currencys.f_CurrencyRounding(t.DistributionPriceLL + Calculation.GetTax(t.CostD, t2.TaxRate) * t1.ExchangeRateTax, t1.Level1RoundingStartFrom, t1.Level2RoundingStartFrom, t1.Level1RoundingMinimumUnit, t1.Level2RoundingMinimumUnit, t1.Level3RoundingMinimumUnit, t1.Level1RoundingAfter, t1.Level2RoundingAfter, t1.Level3RoundingAfter) AS DistributionPriceLL
  FROM Items.t_UnityItem AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.TypeIs = 1
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.SharedID;
  





