    t.Qty ,
    t.SharedID ,
    IIF(t.QtyCurrent >= t.Qty, 1, 0) AS AvailableQty ,
    t.PriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS PriceD ,
    t.WholesalePriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS WholesalePriceD ,
    t.DistributionPriceD + Calculation.GetTax(t.CostD, t2.TaxRate) AS DistributionPriceD
  FROM Items.t_UnityItem AS t
  INNER JOIN Currencys.t_Currency AS t1 ON t1.TypeIs = 1
  INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.SharedID;
  





