CREATE VIEW [Items].[v_UnityItemWithoutBase]
AS
SELECT t.ID ,
    t.UnityID ,
    t.Unity ,
    t.SharedID ,
    t1.Name ,
    t1.Barcodes ,
    t.Qty ,
    t1.QtyCurrent ,
    t1.QtyCurrentByUnit ,
    t.PrimaryIs ,
    t.Purchasing ,
    t.Sold ,
    t.Inventory ,
    t.UseInTransfer ,
    t.BarCode ,
    t.Currency ,
    t1.TaxRate ,
    t1.Brand ,
    t1.MainCategory ,
    t1.SubCategory ,
    t1.VendorNames ,
    t.PriceF ,
    t.PriceD ,
    t.PriceLL ,
    t.PriceEuro ,
    t.PriceWithTaxF ,
    t.PriceWithTaxD ,
    t.PriceWithTaxLL ,
    t.PriceWithTaxEuro ,
    t.DistributionPriceF ,
    t.DistributionPriceD ,
    t.DistributionPriceLL ,
    t.DistributionPriceEuro ,
    t.DistributionPriceWithTaxF ,
    t.DistributionPriceWithTaxD ,
    t.DistributionPriceWithTaxLL ,
    t.DistributionPriceWithTaxEuro ,
    t.DistributionPriceProfitRatio ,
    t.WholesalePriceF ,
    t.WholesalePriceD ,
    t.WholesalePriceLL ,
    t.WholesalePriceEuro ,
    t.WholesalePriceWithTaxF ,
    t.WholesalePriceWithTaxD ,
    t.WholesalePriceWithTaxLL ,
    t.WholesalePriceWithTaxEuro ,
    t.WholesalePriceProfitRatio ,
    t.LowestPriceF ,
    t.LowestPriceD ,
    t.Cost ,
    t.CostF ,
    t.CostD ,
    t.CostLL ,
    t.CostEuro ,
    t.CostWithTax ,
    t.CostWithTaxF ,
    t.CostWithTaxD ,
    t.CostWithTaxLL ,
    t.CostWithTaxEuro ,
    t.ProfitRatio ,
    t.ShowNotificationNoSalePrice ,
    t.ShowNotificationNoProfit ,
    t.DateCreate ,
    t.IsSync ,
    ROW_NUMBER() OVER ( PARTITION BY t.SharedID ORDER BY t.Qty ) AS UnitNumber
  FROM Items.t_UnityItem AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  WHERE t.Qty > 1 AND t.PrimaryIs = 0;
  
  



