CREATE VIEW [Items].[v_UnsoldItemsReportItem]
AS
SELECT t.ID ,
    t.SharedID ,
    t.WareHouseID ,
    t.WareHouse ,
    t.PlaceID ,
    t.Place ,
    t.QtyCurrent AS BaseCurrentQty ,
    .0 AS CurrentQty ,
    ISNULL( Alls.f_GetEmptyGuid(),'00000000-0000-0000-0000-000000000000') AS UnitID ,
    N'' AS Unit ,
    t1.Name ,
    t1.Barcode ,
    t1.MainCategoryID ,
    t1.MainCategory ,
    t1.BrandID ,
    t1.Brand ,
    t1.CurrencyID AS UnitCostCurrencyID ,
    t1.PurchaseWithTax AS UnitCost ,
    t1.PurchaseWithTaxD AS UnitCostD ,
    t1.PurchaseWithTaxLL AS UnitCostLL ,
    t1.PurchaseWithTaxEuro AS UnitCostEuro ,
    t1.SellCurrencyID AS SalePriceCurrencyID ,
    t1.SellWithTax AS SalePrice ,
    t1.SellWithTaxD AS SalePriceD ,
    t1.SellWithTaxLL AS SalePriceLL ,
    t1.SellWithTaxEuro AS SalePriceEuro ,
    t1.DateLastSale AS LastSaleDate ,
    t1.DaysLastSale AS DaysPastFromLastSale
  FROM Items.t_Item AS t
  INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
  WHERE t1.StatusIs <> 2;
    





