/****** Object:  View [Quotations].[v_QuotationAllDailyNumber]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Quotations].[v_QuotationAllDailyNumber]
AS
SELECT  t.ID ,
        t.RefF ,
        ROW_NUMBER() OVER ( PARTITION BY t.DateOnly ORDER BY t.Ref ) AS DailyNumber
FROM    ( SELECT  s.ID ,
                  s.Ref ,
                  s.RefF ,
                  s.DateOnly
          FROM    Quotations.t_Quotation AS s
          UNION ALL
          SELECT  s.ID ,
                  s.Ref ,
                  s.RefF ,
                  s.DateOnly
          FROM    Quotations.t_QuotationHistory AS s
        ) AS t;




