CREATE VIEW [Quotations].[v_QuotationHistorySumNetDailyD]
AS
SELECT t.DateOnly,
       SUM(t.NetIsD) AS NetIs,
       SUM(t.Qtys) AS Qtys
FROM Quotations.t_QuotationHistory AS t
GROUP BY t.DateOnly;





