    o1.DateIs ,
    o1.DateOnly ,
    o1.BalanceF
  FROM ( SELECT DISTINCT t.AccountID ,
            MAX(t.DateIs) OVER ( PARTITION BY t.AccountID ORDER BY t.DateIs DESC ) AS DateIs
          FROM Transactions.t_TransactionDetail AS t
          INNER  JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
          WHERE t1.TypeIs <> N'JV'
       ) AS o
  INNER  JOIN Transactions.t_TransactionDetail AS o1 ON o1.AccountID = o.AccountID AND o1.DateIs = o.DateIs
  INNER  JOIN Transactions.t_Transaction AS o2 ON o2.ID = o1.TransactionID
  WHERE o2.TypeIs <> N'JV';


	

