    t1.DateIs ,
    t1.DateOnly ,
    t1.DateFirstDayInMonth ,
    t.CurrencyID ,
    t.CurrencyTypeIs ,
    t.Balance ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t3.NumberIs
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Company.t_AccountLevel3 AS t3 ON t3.ID = t2.Level3ID
  WHERE t3.NumberIs BETWEEN 53100 AND 53999 AND t1.TypeIs = N'RV' AND t.Balance > 0;

  


