CREATE VIEW [Transactions].[v_TransactionDetailListOnlyExpenses]
AS
SELECT t.ID ,
    t.RowNumber ,
    t.TransactionID ,
    t1.Ref ,
    t1.RefF ,
    t1.TypeIs AS TransactionTypeIs ,
    t1.UserID ,
    t1.UserIs ,
    t1.LinkType ,
    t1.LinkTypeSub ,
    t.AccountID ,
    t.Account ,
    t2.NumberIs ,
    t2.NumberF ,
    t2.BalanceF AS AccountBalanceF ,
    t2.BalanceD AS AccountBalanceD ,
    t2.BalanceLL AS AccountBalanceLL ,
    t2.BalanceEuro AS AccountBalanceEuro ,
    t.DateOnly ,
    t.DateIs ,
    t.CurrencyID ,
    t.Currency ,
    t.ExchangeRate ,
    t.ExchangeRateLL ,
    t.ExchangeRateEuro ,
    t.BalanceType ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.StatementIs ,
    t.TypeIs ,
    t.ChequeNumber ,
    t.ChequeNote ,
    t.ChequeDateGet ,
    t.DateCreate ,
    t.IsSync ,
    t.IsSyncImage
  FROM Transactions.t_TransactionDetail AS t
  INNER  JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER  JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  LEFT JOIN Company.t_Expense AS t3 ON t3.ID = t1.LinkID
  WHERE ( t2.NumberIs BETWEEN 6200000000 AND 6999999999 ) AND ( t2.NumberIs NOT BETWEEN 6300000000 AND 6399999999 ) AND t1.LinkType <> 0 AND ISNULL(t3.LinkedType, 69) <> 0;

  





