/****** Object:  View [Transactions].[v_TransactionDetailSalespersonsMoneyStatement]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Transactions].[v_TransactionDetailSalespersonsMoneyStatement]
AS
SELECT t.ID ,
    t.CurrencyTypeIs ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.StatementIs ,
    t1.RefF ,
    t1.DateOnly ,
    t2.Name AS Account ,
    t3.Phones ,
    t3.AddressIs ,
    t5.Name AS SalesPerson ,
    t4.NetIsF ,
    t4.PaidUpF ,
    t4.RestF
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID
  INNER JOIN Invoices.t_Sold AS t4 ON t4.ID = t1.LinkID
  INNER JOIN Employees.t_SalesPerson AS t5 ON t5.ID = t4.SalespersonID
  WHERE t1.LinkType = 2 AND t1.TypeIs = N'RV'
UNION ALL
SELECT t.ID ,
    t.CurrencyTypeIs ,
    t.BalanceF ,
    t.BalanceD ,
    t.BalanceLL ,
    t.BalanceEuro ,
    t.StatementIs ,
    t1.RefF ,
    t1.DateOnly ,
    t2.Name AS Account ,
    t3.Phones ,
    t3.AddressIs ,
    t3.SalesPerson ,
    N'' AS NetIsF ,
    N'' AS PaidUpF ,
    N'' AS RestF
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Transactions.t_Transaction AS t1 ON t1.ID = t.TransactionID
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountID
  INNER JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID
  WHERE t1.LinkType <> 2 AND t1.TypeIs = N'RV'
UNION ALL
SELECT t.ID ,
    -1 AS CurrencyTypeIs ,
    '' AS BalanceF ,
    0 as BalanceD ,
    0 as BalanceLL ,
    0 as BalanceEuro ,
    '' AS StatementIs ,
    t.RefF ,
    t.DateOnly ,
    t2.Name AS Account ,
    t3.Phones ,
    t3.AddressIs ,
    t.SalesPerson ,
    t.NetIsF ,
    t.PaidUpF ,
    t.RestF
  FROM Invoices.t_Sold AS t
  INNER JOIN Company.t_Account AS t2 ON t2.ID = t.AccountCustomerID
  INNER JOIN Customers.t_Customer AS t3 ON t3.ID = t2.LinkWithID
  WHERE t.PaidUp = 0
  
  
  
  
  
  ;
  




GO
