CREATE VIEW [Transactions].[v_TransactionPV]
AS
SELECT t.ID ,
    t.Ref ,
    t.RefF ,
    t.PaperRef ,
    t.TypeIs ,
    t.BalanceType ,
    t.DateIs ,
    t.DateOnly ,
    t.DateFirstDayInMonth ,
    t.DateFirstDayInYear ,
    t.UserID ,
    t.UserIs ,
    t.DescriptionIs ,
    t.SourceType ,
    t.SourceID ,
    t.SourceRef ,
    t.SourceRefF ,
    t.LegalID ,
    t.LegalRef ,
    t.LegalRefF ,
    t.LinkType ,
    t.LinkTypeSub ,
    t.LinkID ,
    t.SubLinkID ,
    t.AccountsNames ,
    t.DateCreate ,
    t.DetailsCount ,
    t.IsSync
  FROM Transactions.t_Transaction AS t
  WHERE ( t.TypeIs LIKE N'PV' );

  




