/****** Object:  View [Transactions].[v_TransactionQuickStatementMoving]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Transactions].[v_TransactionQuickStatementMoving]
AS
SELECT t.ID,
       t.UserID,
       t2.Name AS UserIs,
       t.SectionID,
       t.DateIs,
       t.EventIs,
       t.EventType,
       t.ComputerIP,
       t.Computer,
       t.ComputerAccount,
       t1.Name
FROM Transactions.t_TransactionQuickStatementMoving AS t
    LEFT JOIN Transactions.t_TransactionQuickStatement AS t1
        ON t1.ID = t.SectionID
    LEFT OUTER JOIN Users.t_User AS t2
        ON t2.ID = t.UserID;



