CREATE VIEW [Users].[v_PermissionAccountStatement]
AS
SELECT t.ID ,
    t.PermissionID ,
    t.RangeType ,
    t.FromNumber ,
    t.ToNumber ,
    t.CreatedByUserID ,
    t.DateCreated ,
    t.LastModifiedDate ,
    t.WorkStationID
  FROM Users.t_PermissionAccountStatement AS t;

  

GO
/****** Object:  View [Users].[v_PermissionAccountStatementList]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE VIEW [Users].[v_PermissionAccountStatementList]
AS
SELECT t.ID ,
    t.PermissionID ,
    t.RangeType ,
    t.FromNumber ,
    t.ToNumber ,
    t.CreatedByUserID ,
    t.DateCreated ,
    t.LastModifiedDate ,
    t.WorkStationID ,
    t1.Name AS PermissionName ,
    t2.Name AS CreatedByUser
  FROM Users.t_PermissionAccountStatement AS t
  INNER JOIN Users.t_Permission AS t1 ON t1.ID = t.PermissionID
  INNER JOIN Users.t_User AS t2 ON t2.ID = t.CreatedByUserID;

  

