CREATE VIEW [Vendors].[v_BestSuppliersReport]
AS
SELECT t.AccountID ,
    t.DateOnly ,
    t.DebitD ,
    t.DebitLL ,
    t.DebitEuro ,
    t.CreditD ,
    t.CreditLL ,
    t.CreditEuro ,
    t1.LinkWithID
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  WHERE t1.NumberIs BETWEEN 4010100000 AND 4010199999;
   




