/****** Object:  View [Vendors].[v_BestSuppliersReportVendors]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [Vendors].[v_BestSuppliersReportVendors]
AS
SELECT DISTINCT t.AccountID ,
    t1.NumberF ,
    t1.Name ,
    t1.PurchasingC ,
    t1.PurchasingLast ,
    ISNULL(t2.ID, N'00000000-0000-0000-0000-000000000000') AS VendorID ,
    ISNULL(t2.Phones, N'') AS Phones ,
    ISNULL(t2.AddressIs, N'') AS AddressIs ,
    ISNULL(t2.NumberCurrency, N'') AS NumberCurrency
  FROM Transactions.t_TransactionDetail AS t
  INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
  LEFT JOIN Vendors.t_Vendor AS t2 ON t2.ID = t1.LinkWithID
  WHERE t1.NumberIs BETWEEN 4010100000 AND 4010199999;

  



