/****** Object:  StoredProcedure [Alls].[s_AAA_CheckConstraintAll]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_AAA_CheckConstraintAll]
AS
BEGIN 

  DECLARE @sql NVARCHAR(MAX) = N'';

  WITH  x AS ( SELECT DISTINCT obj = QUOTENAME(OBJECT_SCHEMA_NAME(parent_object_id)) + '.' + QUOTENAME(OBJECT_NAME(parent_object_id))
                FROM sys.foreign_keys
             )
    SELECT @sql += N'ALTER TABLE ' + obj + N' WITH CHECK CHECK CONSTRAINT ALL;
'
      FROM x;

  --SELECT @sql;

  --EXEC sys.sp_executesql @sql;

END;


GO
/****** Object:  StoredProcedure [Alls].[s_AAA_CopyAllTablesToAnotherDatabase]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_AAA_CopyAllTablesToAnotherDatabase]
AS
BEGIN 

  DECLARE @sql NVARCHAR(MAX) = N'';

  WITH  x AS ( SELECT DISTINCT obj = N'INSERT [' + TABLE_SCHEMA + N'].[' + TABLE_NAME + N'] SELECT * FROM [0009].[' + TABLE_SCHEMA + N'].[' + TABLE_NAME + N']'
                FROM INFORMATION_SCHEMA.TABLES
                WHERE TABLE_TYPE = 'BASE TABLE' AND TABLE_NAME NOT LIKE N'%Moving%' AND TABLE_NAME NOT IN ( N't_Teams', N't_UserNotifications' ) AND TABLE_SCHEMA NOT IN ( N'dbo', N'RedGateLocal' )
             )
    SELECT @sql += obj + '
'
      FROM x;

  --SELECT @sql;

  --EXEC sys.sp_executesql @sql;

END;


GO
