BEGIN --05-12-2024 x2 t_SoldReturn, t_SoldReturnDetail

  PRINT '05-12-2024 x2 t_SoldReturn, t_SoldReturnDetail';

  --DISABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;
  --DISABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;

  --UPDATE Invoices.t_SoldReturn
  --  SET NetIs = Total - DiscountIs + TaxValue ,
  --      NetIsF = Currencys.f_Format(CurrencyID, Total - DiscountIs + TaxValue) ,
  --      NetIsD = TotalD - DiscountIsD + TaxValueD ,
  --      NetIsLL = TotalLL - DiscountIsLL + TaxValueLL ,
  --      NetIsEuro = TotalEuro - DiscountIsEuro + TaxValueEuro ,
  --      NetIsAR = Currencys.f_ToWordAR(Total - DiscountIs + TaxValue, CurrencyID, 1) ,
  --      NetIsEN = Currencys.f_ToWordEN(Total - DiscountIs + TaxValue, CurrencyID, 1) ,
  --      Profit = Total - DiscountIs - Cost ,
  --      ProfitF = Currencys.f_Format(CurrencyID, Total - DiscountIs - Cost) ,
  --      ProfitD = TotalD - DiscountIsD - CostD ,
  --      ProfitLL = TotalLL - DiscountIsLL - CostLL ,
  --      ProfitEuro = TotalEuro - DiscountIsEuro - CostEuro;

  --UPDATE Invoices.t_SoldReturnDetail
  --  SET Total = SubTotal - DiscountInvoice + TaxValue ,
  --      TotalD = SubTotalD - DiscountInvoiceD + TaxValueD ,
  --      TotalLL = SubTotalLL - DiscountInvoiceLL + TaxValueLL ,
  --      TotalEuro = SubTotalEuro - DiscountInvoiceEuro + TaxValueEuro ,
