/****** Object:  StoredProcedure [Alls].[s_Backup]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Alls].[s_Backup] @Path1 NVARCHAR(MAX) ,
  @Path2 NVARCHAR(MAX) ,
  @DatabaseName sysname ,
  @TypeIs NVARCHAR(MAX) ,
  @PathNet1 AS NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY

    SET @PathNet1 = @Path1 + @DatabaseName + ' ' + FORMAT(GETDATE(), 'dd-MM-yyyy (hh-mm-ss tt)') + ' ' + @TypeIs + ' ' + Alls.f_CompanyGetNameApplicationVersionF() + '.bak';
    DECLARE @PathNet2 AS NVARCHAR(MAX) = @Path2 + @DatabaseName + ' ' + FORMAT(GETDATE(), 'dd-MM-yyyy (hh-mm-ss tt)') + ' ' + @TypeIs + ' ' + Alls.f_CompanyGetNameApplicationVersionF() + '.bak';

    IF @Path1 <> '' AND @Path2 <> ''
    BEGIN

      BACKUP DATABASE @DatabaseName TO DISK = @PathNet1 WITH FORMAT , INIT , COMPRESSION; 

      BACKUP DATABASE @DatabaseName TO DISK = @PathNet2 WITH FORMAT , INIT , COMPRESSION; 
	 
      RETURN 1;

    END;
  
    IF @Path1 <> ''
    BEGIN

      BACKUP DATABASE @DatabaseName TO DISK = @PathNet1 WITH FORMAT , INIT , COMPRESSION; 
          
    END;	
 
    IF @Path2 <> ''
    BEGIN

      BACKUP DATABASE @DatabaseName TO DISK = @PathNet2 WITH FORMAT , INIT , COMPRESSION; 
        
    END;
			
    RETURN 1;

  END TRY

  BEGIN CATCH

    RETURN 0;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Alls].[s_ClearOperationsBetween]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_ClearOperationsBetween]
AS
BEGIN

  DECLARE @FromDate DATE = DATEFROMPARTS(2024, 1, 1) ,
    @ToDate DATE = DATEFROMPARTS(2024, 12, 31);

  BEGIN --Delete
    
    EXECUTE Alls.s_ClearOperationsBetween_Cars @FromDate, @ToDate;

    EXECUTE Alls.s_ClearOperationsBetween_Company @FromDate, @ToDate;

    EXECUTE Alls.s_ClearOperationsBetween_Customers @FromDate, @ToDate;

    EXECUTE Alls.s_ClearOperationsBetween_Employees @FromDate, @ToDate;
	
    EXECUTE Alls.s_ClearOperationsBetween_Gym @FromDate, @ToDate;
	
    EXECUTE Alls.s_ClearOperationsBetween_Invoices @FromDate, @ToDate;
	
    EXECUTE Alls.s_ClearOperationsBetween_Items @FromDate, @ToDate;
 
    EXECUTE Alls.s_ClearOperationsBetween_Quotations @FromDate, @ToDate;
  
    EXECUTE Alls.s_ClearOperationsBetween_Transactions @FromDate, @ToDate;
  
    EXECUTE Alls.s_ClearOperationsBetween_Users @FromDate, @ToDate;
  
  END;

  EXECUTE Transactions.s_TransactionInsertDefaultData;

  EXECUTE Alls.s_RebuildAll;
  
END; 

GO
/****** Object:  StoredProcedure [Alls].[s_ClearOperationsBetween_Cars]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_ClearOperationsBetween_Cars] @FromDate AS DATE ,
  @ToDate AS DATE
AS
BEGIN
 
  BEGIN --Declare

    DECLARE @IDs AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

  END;

  BEGIN -- t_CarExpense

    DELETE FROM Cars.t_CarExpense
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;
  
    DELETE FROM Cars.t_CarExpenseMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
     
  BEGIN -- t_CarRentalDriver
    
    DELETE FROM @IDs;

    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Cars.t_CarRentalDriver AS s
        INNER JOIN Cars.t_CarRental AS s1 ON s1.ID = s.CarRentalID
        WHERE s1.AgreementDate BETWEEN @FromDate AND @ToDate;

    DELETE FROM Cars.t_CarRentalDriver
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_CarRentalDriver.ID );

  END;
 
  BEGIN -- t_CarRentalOwner

    DELETE FROM @IDs;

    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Cars.t_CarRentalOwner AS s
        INNER JOIN Cars.t_CarRental AS s1 ON s1.ID = s.CarRentalID
        WHERE s1.AgreementDate BETWEEN @FromDate AND @ToDate;

    DELETE FROM Cars.t_CarRentalOwner
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_CarRentalOwner.ID );

  END;

  BEGIN --t_CarRental
    
    DELETE FROM Cars.t_CarRental
      WHERE AgreementDate BETWEEN @FromDate AND @ToDate;

    DELETE FROM Cars.t_CarRentalMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;

  BEGIN -- t_CarRentalHistoryDriver

    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Cars.t_CarRentalHistoryDriver AS s
        INNER JOIN Cars.t_CarRentalHistory AS s1 ON s1.ID = s.CarRentalHistoryID
        WHERE s1.AgreementDate BETWEEN @FromDate AND @ToDate;

    DELETE FROM Cars.t_CarRentalHistoryDriver
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = Cars.t_CarRentalHistoryDriver.ID );

  END;
 
  BEGIN -- t_CarRentalHistoryOwner

    DELETE FROM @IDs;

    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Cars.t_CarRentalHistoryOwner AS s
        INNER JOIN Cars.t_CarRentalHistory AS s1 ON s1.ID = s.CarRentalHistoryID
        WHERE s1.AgreementDate BETWEEN @FromDate AND @ToDate;

    DELETE FROM Cars.t_CarRentalHistoryOwner
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = Cars.t_CarRentalHistoryOwner.ID );

  END;

  BEGIN -- t_CarRentalHistory

    DELETE FROM Cars.t_CarRentalHistory
      WHERE AgreementDate BETWEEN @FromDate AND @ToDate;

  END;

  BEGIN --t_CarRentalStatistics
      
    DELETE FROM Cars.t_CarRentalStatistics;

    DELETE FROM Cars.t_CarRentalStatisticsMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;

END; 


GO
