      WHERE DateCreate BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_Cheque
  	
    DELETE FROM Company.t_ChequeHistory
      WHERE DateIs BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_Cheque
      WHERE DateIs BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_ChequeMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_CloseBoxDetail

