    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Company.t_CloseBoxDetail AS s
        INNER JOIN Company.t_CloseBox AS s1 ON s1.ID = s.CloseBoxID
        WHERE s1.DateOnly BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_CloseBoxDetail
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_CloseBoxDetail.ID );

  END;
 
  BEGIN -- t_CloseBox

    DELETE FROM Company.t_CloseBox
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_CloseBoxMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_Expense
  	 
    DELETE FROM Company.t_Expense
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_ExpenseMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_MoneyExchange
  	    
    DELETE FROM Company.t_MoneyExchange
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;
  	    
    DELETE FROM Company.t_MoneyExchangeMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

    DELETE FROM Company.t_MoneyExchangeSummary
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_OpenBox
  	    
    DELETE FROM Company.t_OpenBox
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;
		 
    DELETE FROM Company.t_OpenBoxMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_PaySalary
  
    DELETE FROM Company.t_PaySalary
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;
  
    DELETE FROM Company.t_PaySalaryMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;

  END;
 
  BEGIN -- t_DailyBox

    DELETE FROM Company.t_DailyBox
      WHERE OpeningDate BETWEEN @FromDate AND @ToDate;
  
    DELETE FROM Company.t_DailyBoxMoving
      WHERE DateOnly BETWEEN @FromDate AND @ToDate;
  
    DELETE FROM Company.t_ArchiveDailyBox
      WHERE OpeningDate BETWEEN @FromDate AND @ToDate;

  END;

END; 





