  EXECUTE [Items].[s_ItemSharedExecuteJobStatusIs]; 

  EXECUTE [Items].[s_Items_StockTakeUnsaved_ExecuteJob]; 

  EXECUTE Invoices.s_PurchaseOrderExecuteJob; 
 
  EXECUTE Invoices.s_Invoices_PurchasingUnsaved_ExecuteJob; 
 
  EXECUTE Invoices.s_Invoices_SellOrderUnsaved_ExecuteJob; 
 
  EXECUTE Invoices.s_Invoices_SoldUnsaved_ExecuteJob; 

  TRUNCATE TABLE Alls.t_FireStoreRowsForDelete;

  RETURN 1;
  
END;



