/****** Object:  StoredProcedure [Alls].[s_FireStoreUpdateAllRowsVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_FireStoreUpdateAllRowsVersion]
  (
    @LiveSchema TINYINT ,
    @LiveTable INT ,
    @FullTableName NVARCHAR(MAX)
  )
AS
BEGIN
  BEGIN TRY

    DECLARE @NewRowVersionID NVARCHAR(max) = DateTimes.f_GetRowVersionID();

    DECLARE @t NVARCHAR(MAX) = N'UPDATE ' + @FullTableName + N' SET RowVersionID = ' + @NewRowVersionID + ';';

    EXEC sp_executesql @stmt = @t;

    SET @LiveSchema = FORMAT(@LiveSchema, N'0') + N'7';
    SET @LiveTable = FORMAT(@LiveTable, N'0') + N'7';
	 
    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, @LiveTable, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, @LiveSchema, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));
			
    RETURN 1;

  END TRY
  BEGIN CATCH

    RETURN 0;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Alls].[s_FireStoreUpdateRowVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_FireStoreUpdateRowVersion]
  (
    @IDs Alls.tt_Guid READONLY ,
    @LiveSchema TINYINT ,
    @LiveTable INT ,
    @FullTableName NVARCHAR(MAX) ,
    @ColumnName NVARCHAR(MAX)
  )
AS
BEGIN
  BEGIN TRY

    DECLARE @IDsTpye NVARCHAR(MAX) = N'@IDs Alls.tt_Guid READONLY';
  
    DECLARE @NewRowVersionID NVARCHAR(max) = DateTimes.f_GetRowVersionID();

    DECLARE @t NVARCHAR(MAX) = N'UPDATE ' + @FullTableName + N' SET ' + @ColumnName + ' = ' + @NewRowVersionID + ' WHERE EXISTS ( SELECT TOP ( 1 ) s.ID FROM @IDs AS s WHERE s.ID = ' + @FullTableName + '.ID );';

    EXEC sp_executesql @stmt = @t, @params = @IDsTpye, @IDs = @IDs;

    SET @LiveSchema = FORMAT(@LiveSchema, N'0') + N'7';
    SET @LiveTable = FORMAT(@LiveTable, N'0') + N'7';
	 
    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, @LiveTable, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, @LiveSchema, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));
			
    SELECT 1;

  END TRY
  BEGIN CATCH

    SELECT 0;

  END CATCH;

END;



