/****** Object:  StoredProcedure [Alls].[s_GetLastMoving]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_GetLastMoving]
    @tbl NVARCHAR(MAX) ,
    @Name NVARCHAR(MAX) OUTPUT
AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @SQL NVARCHAR(MAX);

        SET @SQL = 'SELECT TOP 1 @Name = UserName + N''|'' + MovingEvent FROM '
            + @tbl
            + ' WHERE MovingDate >= GETDATE() - 0.00002 ORDER BY MovingID DESC';

        EXECUTE sp_executesql @SQL, N'@Name NVARCHAR(MAX) OUTPUT',
            @Name OUTPUT;

    END; 





GO
/****** Object:  StoredProcedure [Alls].[s_GetLastMoving2]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_GetLastMoving2]
    @tbl NVARCHAR(MAX) ,
    @Name NVARCHAR(MAX) OUTPUT
AS
    BEGIN
        SET NOCOUNT ON;

        DECLARE @SQL NVARCHAR(MAX);

        SET @SQL = 'SELECT TOP 1 @Name = UserIs + N''|'' + EventIs FROM '
            + @tbl + ' WHERE DateIs >= GETDATE() - 0.00003 ORDER BY ID DESC';

        EXECUTE sp_executesql @SQL, N'@Name NVARCHAR(MAX) OUTPUT',
            @Name OUTPUT;

    END; 





