AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Insert event

            EXECUTE @Return = Alls.s_MovingInsert3 @ID,
                                                   @UserID,
                                                   @Event,
                                                   3,
                                                   @ComputerIP,
