/****** Object:  StoredProcedure [Alls].[s_MovingInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_MovingInserts]
    (
      @SectionID Alls.td_IDBigint READONLY ,
      @UserID INT ,
      @EventIs NVARCHAR(MAX) ,
      @EventType TINYINT ,
      @ComputerIP NVARCHAR(450) ,
      @Computer NVARCHAR(450) ,
      @ComputerAccount NVARCHAR(450) ,
      @Table NVARCHAR(MAX)
    )
AS
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;
			
            DECLARE @ID NVARCHAR(MAX);

            DECLARE Detail CURSOR FORWARD_ONLY
            FOR
                SELECT  CAST(t.ID AS NVARCHAR(MAX))
                FROM    @SectionID AS t; 

            OPEN Detail;

            FETCH NEXT FROM Detail INTO @ID;

            WHILE @@FETCH_STATUS = 0
                BEGIN
            
                    EXECUTE Alls.s_MovingInsert3 @ID, @UserID, @EventIs,
                        @EventType, @ComputerIP, @Computer, @ComputerAccount,
                        @Table;

                    FETCH NEXT FROM Detail INTO @ID;
                END;

            CLOSE Detail;
            DEALLOCATE Detail;

            COMMIT;
            RETURN 1;
        END TRY
        BEGIN CATCH
            ROLLBACK;
            RETURN 0;
        END CATCH;
    END;







GO
/****** Object:  StoredProcedure [Alls].[s_MovingTruncateTable]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_MovingTruncateTable]
    (
      @UserID INT ,
      @EventIs NVARCHAR(MAX) ,
      @ComputerIP NVARCHAR(MAX) ,
      @Computer NVARCHAR(MAX) ,
      @ComputerAccount NVARCHAR(MAX) ,
      @Table NVARCHAR(MAX) ,
      @IsGuid bit
    )
AS
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;
		
            EXECUTE(N'TRUNCATE TABLE ' + @Table);

            DECLARE @ScriptIs NVARCHAR(MAX);

            IF @IsGuid = 0
                BEGIN

                    SET @ScriptIs = N'INSERT INTO ' + @Table
                        + '(UserID, SectionID, EventIs , EventType , ComputerIP , Computer ,ComputerAccount) VALUES ('''
                        + CAST(@UserID AS NVARCHAR(MAX)) + ''', 0 , '''
                        + @EventIs + ''', 4 , ''' + @ComputerIP + ''', '''
                        + @Computer + ''', ''' + @ComputerAccount + ''');';

                    EXECUTE(@ScriptIs);

                END;

            ELSE
                BEGIN

                    SET @ScriptIs = N'INSERT INTO ' + @Table
                        + '(UserID, SectionID, EventIs , EventType , ComputerIP , Computer ,ComputerAccount) VALUES ('''
                        + CAST(@UserID AS NVARCHAR(MAX)) + ''', '''
                        + CAST(NEWID() AS NVARCHAR(MAX)) + ''', ''' + @EventIs
                        + ''', 4 , ''' + @ComputerIP + ''', ''' + @Computer
                        + ''', ''' + @ComputerAccount + ''');';

                    EXECUTE(@ScriptIs);

                END;
            
            COMMIT TRANSACTION;

            RETURN 1;

        END TRY

        BEGIN CATCH

            ROLLBACK;

            RETURN 0;

        END CATCH;

    END;











