/****** Object:  StoredProcedure [Alls].[s_NotificationExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_NotificationExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Alls_t_Notification < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Declare

      DECLARE @Ref BIGINT = Alls.f_NotificationGetNewRef() - 1;

      DECLARE @t Alls.tt_Notification;

    END;

    BEGIN --Set
    
      INSERT INTO @t
          ( ID ,
            Ref ,
            RefF ,
            TextIs ,
            DateIs ,
            PeriodType ,
            PeriodNumber ,
            RepeatedInTheFuture ,
            Repeated ,
            IsStop ,
            DateCreate ,
            WorkStationID
	      )
        SELECT t.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY t.Ref ) ,
            N'' ,
            t.TextIs ,
            Alls.f_NotificationGetNewDateByPeriod(t.DateIs, t.PeriodType, t.PeriodNumber) ,
            t.PeriodType ,
            t.PeriodNumber ,
            t.RepeatedInTheFuture ,
            t.Repeated ,
            t.IsStop ,
            t.DateCreate ,
            t.WorkStationID
          FROM Alls.t_Notification AS t
          WHERE t.DateIs <= DateTimes.f_GetToday() AND t.RepeatedInTheFuture = 1 AND t.Repeated = 0;

    END;

    BEGIN --Insert 

      INSERT INTO Alls.t_Notification
          ( Ref ,
            RefF ,
            TextIs ,
            DateIs ,
            PeriodType ,
            PeriodNumber ,
            RepeatedInTheFuture ,
            Repeated ,
            IsStop ,
            WorkStationID
          )
        SELECT t.Ref ,
            FORMAT(t.Ref, N'0') ,
            t.TextIs ,
            t.DateIs ,
            t.PeriodType ,
            t.PeriodNumber ,
            t.RepeatedInTheFuture ,
            t.Repeated ,
            t.IsStop ,
            t.WorkStationID
          FROM @t AS t;

    END;

    BEGIN --Update 
    
      UPDATE Alls.t_Notification
        SET RepeatedInTheFuture = 0 ,
            Repeated = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @t AS s
                        WHERE s.ID = t_Notification.ID );

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Alls_t_Notification = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Alls].[s_NotificationInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_NotificationInsert] @ID UNIQUEIDENTIFIER ,
  @TextIs NVARCHAR(450) ,
  @DateIs DATE ,
  @PeriodType TINYINT ,
  @PeriodNumber INT ,
  @RepeatedInTheFuture BIT ,
  @Repeated BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT = Alls.f_NotificationGetNewRef() ,
        @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_Notification
          ( ID ,
            Ref ,
            RefF ,
            TextIs ,
            DateIs ,
            PeriodType ,
            PeriodNumber ,
            RepeatedInTheFuture ,
            Repeated
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, N'#') ,
            @TextIs ,
            @DateIs ,
            @PeriodType ,
            @PeriodNumber ,
            @RepeatedInTheFuture ,
            @Repeated
          );

    END;

    BEGIN --Insert t_NotificationMoving

      SET @Return = -1;

      INSERT INTO Alls.t_NotificationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, N'#') ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








