/****** Object:  StoredProcedure [Alls].[s_NotificationUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_NotificationUpdate] @ID UNIQUEIDENTIFIER ,
  @TextIs NVARCHAR(450) ,
  @DateIs DATE ,
  @PeriodType TINYINT ,
  @PeriodNumber INT ,
  @RepeatedInTheFuture BIT ,
  @Repeated BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
	
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update

      UPDATE Alls.t_Notification
        SET TextIs = @TextIs ,
            DateIs = @DateIs ,
            PeriodType = @PeriodType ,
            PeriodNumber = @PeriodNumber ,
            RepeatedInTheFuture = @RepeatedInTheFuture ,
            Repeated = @Repeated
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_NotificationMoving

      SET @Return = -1;

      INSERT INTO Alls.t_NotificationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



