/****** Object:  StoredProcedure [Alls].[s_ReceiveDataCancelDeletion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Alls].[s_ReceiveDataCancelDeletion] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_ReceiveData
          ( ID ,
            Ref ,
            RefF ,
            SentDate ,
            FromUser ,
            SentText ,
            DataType ,
            DataIs ,
			Notes ,
            WorkStationID
	      )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.SentDate ,
            t.FromUser ,
            t.SentText ,
            t.DataType ,
            t.DataIs ,
            t.Notes ,
            t.WorkStationID
          FROM Alls.t_ReceiveDataDeleted AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Alls.t_ReceiveDataDeleted
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Alls.s_ReceiveDataMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_ReceiveDataLiveVersion;
    EXECUTE Alls.s_ReceiveDataDeletedLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Alls].[s_ReceiveDataCancelDeletions]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
