CREATE PROCEDURE [Alls].[s_ReceiveDataDeletes] @IDs Alls.tt_IDAndEvent READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete

      DELETE FROM Alls.t_ReceiveDataDeleted
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = Alls.t_ReceiveDataDeleted.ID );

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_ReceiveDataDeleted
          ( ID ,
            Ref ,
            RefF ,
            SentDate ,
            FromUser ,
            SentText ,
            DataType ,
            DataIs ,
            Notes ,
            WorkStationID
	      )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.SentDate ,
            t.FromUser ,
            t.SentText ,
            t.DataType ,
            t.DataIs ,
            t.Notes ,
            t.WorkStationID
          FROM Alls.t_ReceiveData AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Delete

      DELETE FROM Alls.t_ReceiveData
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ReceiveData.ID );

    END;

    SET @Return = -1;
    EXECUTE Alls.s_ReceiveDataMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_ReceiveDataLiveVersion;
    EXECUTE Alls.s_ReceiveDataDeletedLiveVersion;

    COMMIT TRANSACTION;

