CREATE PROCEDURE [Alls].[s_ReceiveDataInsert] @ID UNIQUEIDENTIFIER ,
  @FromUser NVARCHAR(MAX) ,
  @SentText NVARCHAR(MAX) ,
  @DataType TINYINT ,
  @DataIs NVARCHAR(MAX) ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Alls.f_ReceiveData_GetNew_Ref() ,
        @RefF NVARCHAR(MAX) ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SET @RefF = FORMAT(@Ref, N'0');

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_ReceiveData
          ( ID ,
            Ref ,
            RefF ,
            FromUser ,
            SentText ,
            DataType ,
            DataIs ,
			Notes
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @FromUser ,
            @SentText ,
            @DataType ,
            @DataIs ,
			@Notes
          );
	  
    END;

    SET @Return = -1;
    EXECUTE Alls.s_ReceiveDataMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_ReceiveDataLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





