/****** Object:  StoredProcedure [Alls].[s_RecentlyAndFrequentlyUsedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Alls].[s_RecentlyAndFrequentlyUsedMerge] @UserID UNIQUEIDENTIFIER ,
  @ActionType INT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @RecentlyAndFrequentlyUsed AS TABLE
        (
          ActionType INT NOT NULL
        );

    END;

    BEGIN --Set info

      INSERT @RecentlyAndFrequentlyUsed
          ( ActionType )
        VALUES ( @ActionType );

    END;

    BEGIN --Merge

      MERGE Alls.t_RecentlyAndFrequentlyUsed AS t
      USING @RecentlyAndFrequentlyUsed AS s
      ON s.ActionType = t.ActionType AND t.UserID = @UserID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( UserID ,
                 ActionType ,
                 ClicksCount
               )
        VALUES ( @UserID ,
                 s.ActionType ,
                 1
               )
      WHEN MATCHED THEN
        UPDATE SET t.ClicksCount += 1 ,
                    t.LastClick = GETDATE() ,
                    t.IsSync = 0;
 
    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;







GO
