    END;

    DISABLE TRIGGER  Alls.tr_RecentlyAndFrequentlyUsed ON Alls.t_RecentlyAndFrequentlyUsed;

    BEGIN --Insert

      UPDATE Alls.t_RecentlyAndFrequentlyUsed
        SET IsSync = 0
        WHERE ID = @ID;

    END;

    ENABLE TRIGGER Alls.tr_RecentlyAndFrequentlyUsed ON Alls.t_RecentlyAndFrequentlyUsed;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

