/****** Object:  StoredProcedure [Alls].[s_RefreshAllViews]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Alls].[s_RefreshAllViews]
AS
BEGIN

  SET NOCOUNT ON;

  DECLARE @ActualView VARCHAR(255);

  DECLARE viewlist CURSOR FAST_FORWARD
  FOR
  SELECT
DISTINCT s.name + '.' + o.name AS ViewName
    FROM sys.objects o
    JOIN
      sys.schemas s ON o.schema_id = s.schema_id
    WHERE o.[type] = 'V' AND OBJECTPROPERTY(o.[object_id], 'IsSchemaBound') <> 1 AND OBJECTPROPERTY(o.[object_id], 'IsMsShipped') <> 1;

  OPEN viewlist;

  FETCH NEXT FROM viewlist 
INTO @ActualView;

  WHILE @@FETCH_STATUS = 0
  BEGIN
    PRINT @ActualView;
    EXEC sp_refreshview @ActualView;

    FETCH NEXT FROM viewlist
INTO @ActualView;
  END;
  CLOSE viewlist;
  DEALLOCATE viewlist;
  
END;




GO
