CREATE PROCEDURE [Alls].[s_WhatsAppLogsInsert] @ID UNIQUEIDENTIFIER ,
  @SentDate DATETIME ,
  @SentDateOnly DATE ,
  @SentDateMonthly DATE ,
  @SentDateYearly DATE ,
  @SectionID INT ,
  @PersonID UNIQUEIDENTIFIER ,
  @Person NVARCHAR(MAX) ,
  @ToPhone NVARCHAR(MAX) ,
  @MessageText NVARCHAR(MAX) ,
  @CreatedByUserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @Return INT  = 0;

    END;

    BEGIN --Set
	    
      SET @Ref = Alls.f_WhatsAppLogsGetNewRef();
      SET @RefF = FORMAT(@Ref, '0');

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_WhatsAppLogs
          ( ID ,
            Ref ,
            RefF ,
            SentDate ,
            SentDateOnly ,
            SentDateMonthly ,
            SentDateYearly ,
            SectionID ,
            PersonID ,
            Person ,
            ToPhone ,
            MessageText ,
            CreatedByUserID
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @SentDate ,
            @SentDateOnly ,
            @SentDateMonthly ,
            @SentDateYearly ,
            @SectionID ,
            @PersonID ,
            @Person ,
            @ToPhone ,
            @MessageText ,
            @CreatedByUserID
          );

    END;
  
    SET @Return = -1;
    EXECUTE Alls.s_WhatsAppLogsMovingInsertPART @ID, @CreatedByUserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_WhatsAppLogsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








GO
/****** Object:  StoredProcedure [Alls].[s_WhatsAppLogsLiveVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Alls].[s_WhatsAppLogsLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, WhatsApp, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaAll, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;



