CREATE PROCEDURE [Alls].[s_WhatsAppMessagesTemplatesInsert] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @MessageText NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Alls.t_WhatsAppMessagesTemplates
          ( ID, Name, MessageText )
        VALUES ( @ID, @Name, @MessageText );
	  
    END;

    SET @return = -1;
    EXECUTE Alls.s_WhatsAppMessagesTemplatesMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_WhatsAppMessagesTemplatesLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;






