CREATE PROCEDURE [Alls].[s_WhatsAppMessagesTemplatesUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @MessageText NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;

    BEGIN --Update

      UPDATE Alls.t_WhatsAppMessagesTemplates
        SET Name = @Name ,
            MessageText = @MessageText
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Alls.s_WhatsAppMessagesTemplatesMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_WhatsAppMessagesTemplatesLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




