        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Cars.t_CarClassMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
