      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_CarDriver.ID );

    END;

    ENABLE TRIGGER Cars.tr_CarDriver ON Cars.t_CarDriver;
  
