/****** Object:  StoredProcedure [Cars].[s_CarExpenseInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Cars].[s_CarExpenseInsert] @CarID UNIQUEIDENTIFIER ,
  @DateIs DATE ,
  @BoxAccountID UNIQUEIDENTIFIER ,
  @CarExpenseAccountID UNIQUEIDENTIFIER ,
  @VendorAccountID UNIQUEIDENTIFIER ,
  @VendorTaxAccountID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @Balance FLOAT ,
  @TaxRate DECIMAL(4, 2) ,
  @TaxValue FLOAT ,
  @NetIs FLOAT ,
  @TransactionDetailTypeIs TINYINT ,
  @ChequeNumber NVARCHAR(MAX) ,
  @ChequeImage IMAGE ,
  @ChequeNote NVARCHAR(MAX) ,
  @ChequeDateGet DATE ,
  @ChequeStopNotificationGet BIT ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @DateOnly DATE = @DateIs ,
        @TransactionRef BIGINT ,
        @TransactionID UNIQUEIDENTIFIER ,
        @RowNumber INT ,
        @BoxAccount NVARCHAR(MAX) ,
        @BoxAccountNumberF NVARCHAR(MAX) ,
        @CarExpenseAccount NVARCHAR(MAX) ,
        @CarExpenseAccountNumberF NVARCHAR(MAX) ,
        @VendorTaxAccount NVARCHAR(MAX) ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @LinkType INT = 182 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @StatementIs_ NVARCHAR(MAX) ,
        @BalanceD FLOAT ,
        @TaxValueD FLOAT ,
        @NetIsD FLOAT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(s.Ref), 0) + 1
        FROM Cars.t_CarExpense AS s;

      SET @BoxAccount = Company.f_AccountGetName(@BoxAccountID);
      SET @BoxAccountNumberF = Company.f_AccountGetNumberF(@BoxAccountID);

      SET @CarExpenseAccount = Company.f_AccountGetName(@CarExpenseAccountID);
      SET @CarExpenseAccountNumberF = Company.f_AccountGetNumberF(@CarExpenseAccountID);

      SET @VendorTaxAccount = Company.f_AccountGetName(@VendorTaxAccountID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);

      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);
      IF @CurrencyTypeIs <> 0
      BEGIN
	                              
        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      SET @BalanceD = @Balance / @ExchangeRate;

      SET @TaxValueD = @TaxValue / @ExchangeRate;

      SET @NetIsD = @NetIs / @ExchangeRate;

    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Cars.t_CarExpense
          ( ID ,
            CarID ,
            Car ,
            Ref ,
            RefF ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            ByUserID ,
            ByUser ,
            FromAccountID ,
            FromAccount ,
            FromAccountNumberF ,
            ToAccountID ,
            ToAccount ,
            ToAccountNumberF ,
            VendorAccountID ,
            VendorAccount ,
            VendorAccountNumberF ,
            PaymentMethod ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Balance ,
            BalanceF ,
            BalanceD ,
            BalanceLL ,
            BalanceEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @CarID ,
            Cars.f_CarGetName(@CarID) ,
            @Ref ,
            FORMAT(@Ref, '#') ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @BoxAccountID ,
            @BoxAccount ,
            @BoxAccountNumberF ,
            @CarExpenseAccountID ,
            @CarExpenseAccount ,
            @CarExpenseAccountNumberF ,
            @VendorAccountID ,
            Company.f_AccountGetName(@VendorAccountID) ,
            Company.f_AccountGetNumberF(@VendorAccountID) ,
            @PaymentMethod ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @TaxExchangeRateLL ,
            @TaxExchangeRateEuro ,
            @Balance ,
            Currencys.f_Format(@CurrencyID, @Balance) ,
            @BalanceD ,
            @BalanceD * @ExchangeRateLL ,
            @BalanceD * @ExchangeRateEuro ,
            @TaxRate ,
            Currencys.f_FormatRate(@TaxRate) ,
            @TaxValue ,
            Currencys.f_Format(@CurrencyID, @TaxValue) ,
            @TaxValueD ,
            @TaxValueD * @TaxExchangeRateLL ,
            @TaxValueD * @TaxExchangeRateEuro ,
            @NetIs ,
            Currencys.f_Format(@CurrencyID, @NetIs) ,
            @NetIsD ,
            @NetIsD * @ExchangeRateLL ,
            @NetIsD * @ExchangeRateEuro ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            Currencys.f_ToWordEN(@NetIs, @CurrencyID, 1) ,
            @DescriptionIs
          );

    END;

    BEGIN --Fix t_Car

      UPDATE Cars.t_Car
        SET ExpensesCount += 1 ,
            TotalExpensesD += @NetIsD ,
            TotalExpensesLL += @NetIsD * @ExchangeRateLL ,
            TotalExpensesEuro += @NetIsD * @ExchangeRateEuro
        WHERE ID = @CarID;

      UPDATE Cars.t_Car
        SET ProfitD = ProfitCarRentsD - TotalExpensesD ,
            ProfitLL = ProfitCarRentsLL - TotalExpensesLL ,
            ProfitEuro = ProfitCarRentsEuro - TotalExpensesEuro
        WHERE ID = @CarID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Cars.t_CarExpenseMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

      END;
	  
      BEGIN --Insert detail

        IF @PaymentMethod = 1
        BEGIN
	                            
          SET @BoxAccountID = @VendorAccountID;

        END;

        SET @V = @Balance;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @BoxAccount;
        EXECUTE Transactions.s_TransactionDetailInsertDebitFull @RowNumber, @TransactionID, @CarExpenseAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_, @TransactionDetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN;
	
        SET @RowNumber = 2;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @CarExpenseAccount;
        EXECUTE Transactions.s_TransactionDetailInsertCreditFull @RowNumber, @TransactionID, @BoxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_, @TransactionDetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN;
		
        IF @TaxValue > 0
        BEGIN --Insert detail tax

          SET @V = @TaxValue;
          SET @RowNumber = 3;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @BoxAccount + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertDebitTax @RowNumber, @TransactionID, @VendorTaxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TaxValue, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

          SET @RowNumber = 3;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @VendorTaxAccount + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @BoxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TaxValue, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
		
        END;

      END;

      BEGIN --Insert event

        SET @return = -1;

        INSERT INTO Transactions.t_TransactionMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          VALUES
            ( @UserID ,
              @TransactionID ,
              @Event + CONVERT(NVARCHAR(MAX), @TransactionRef) ,
              0 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            );

      END;

    END;
	
    BEGIN --Fix t_Transaction

      EXECUTE Transactions.s_TransactionFixPart @TransactionID;

    END;

    BEGIN --Update t_CarRentalStatistics

      UPDATE Cars.t_CarRentalStatistics
        SET Expenses += 1 ,
            ExpensesSubTotalD += @BalanceD ,
            ExpensesSubTotalLL += @BalanceD * @ExchangeRateLL ,
            ExpensesSubTotalEuro += @BalanceD * @ExchangeRateEuro ,
            ExpensesTaxValueD += @TaxValueD ,
            ExpensesTaxValueLL += @TaxValueD * @TaxExchangeRateLL ,
            ExpensesTaxValueEuro += @TaxValueD * @TaxExchangeRateEuro ,
            ExpensesTotalD += @NetIsD ,
            ExpensesTotalLL += @NetIsD * @ExchangeRateLL ,
            ExpensesTotalEuro += @NetIsD * @ExchangeRateEuro;
  
      UPDATE Cars.t_CarRentalStatistics
        SET ProfitD = RentalsProfitD - ExpensesTotalD ,
            ProfitLL = RentalsProfitLL - ExpensesTotalLL ,
            ProfitEuro = RentalsProfitEuro - ExpensesTotalEuro;

    END;

    EXECUTE Invoices.s_ProfitDaily_Expenses_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;



GO
