      DECLARE @Return INT;

    END;
	
    BEGIN --Insert

      INSERT  INTO Cars.t_CarOwners
              ( ID ,
                CarID ,
                Car ,
                OwnerProfileID ,
                OwnerProfile ,
                ProfitRatio 
	          )
      VALUES  ( @ID ,
                @CarID ,
                Cars.f_CarGetName(@CarID) ,
                @OwnerProfileID ,
                Cars.f_CarOwnersProfileGetName(@OwnerProfileID) ,
                @ProfitRatio
              );

    END;

