/****** Object:  StoredProcedure [Cars].[s_CarRentalDeletePaidTax]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Cars].[s_CarRentalDeletePaidTax]
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @TrnLinkType INT = 185 ,
        @TrnLinkTypeSub TINYINT = 10 ,
        @return INT = 0;

    END;

    BEGIN --Update

      UPDATE  Cars.t_CarRental
      SET     PaidTax = 0
      WHERE   ID = @ID;  
	  
    END;
	
    BEGIN --Insert t_CarRentalMoving

      SET @return = -1;

      INSERT  INTO Cars.t_CarRentalMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;
 
    BEGIN --Delete t_Transaction

      INSERT  INTO @TrnIDs
              ( ID ,
                RefF
              )
      SELECT  s.ID ,
              s.RefF
      FROM    Transactions.t_Transaction AS s
      WHERE   s.LinkType = @TrnLinkType
              AND s.LinkTypeSub = @TrnLinkTypeSub
              AND s.LinkID = @ID;

      DELETE  FROM Transactions.t_Transaction
      WHERE   LinkType = @TrnLinkType
              AND LinkTypeSub = @TrnLinkTypeSub
              AND LinkID = @ID;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT  INTO Transactions.t_TransactionMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      SELECT  @UserID ,
              s.ID ,
              @EventBase + N': ' + s.RefF ,
              @EventType ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
      FROM    @TrnIDs AS s;

    END;
	
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;



