GO


CREATE PROCEDURE [Cars].[s_CarRentalDriverUpdateIsSync]
    @IsSync BIT,
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Cars.tr_CarRentalDriver ON Cars.t_CarRentalDriver;

        BEGIN --Insert

            UPDATE Cars.t_CarRentalDriver
            SET IsSync = @IsSync
            WHERE ID = @ID;

        END;

        ENABLE TRIGGER Cars.tr_CarRentalDriver ON Cars.t_CarRentalDriver;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;






