CREATE PROCEDURE [Cars].[s_CarRentalHistoryInsert] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @CarID_Old UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Set info
	    
      SELECT TOP ( 1 ) @CarID_Old = s.CarID
        FROM Cars.t_CarRental AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert
    
      INSERT INTO Cars.t_CarRentalHistory
          ( ID ,
            Ref ,
            RefF ,
            PaperRef ,
            SponsorName ,
            FlightReference ,
            FlightTime ,
            AccountID ,
            Account ,
            AccountNumberF ,
            AccountBoxID ,
            AccountBox ,
            AccountBoxNumberF ,
            CarID ,
            Car ,
            AgreementDate ,
            FromDate ,
            ToDate ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            DayPrice ,
            DayPriceF ,
            DayPriceD ,
            DayPriceLL ,
            DayPriceEuro ,
            DayQty ,
            DayTotalPrice ,
