          FROM Cars.t_CarRental
          WHERE ID = @ID;

      INSERT INTO Cars.t_CarRentalHistoryDriver
          ( ID ,
            CarRentalHistoryID ,
            CarDriverID ,
            CarDriver ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT ID ,
            CarRentalID ,
            CarDriverID ,
            CarDriver ,
            DateCreate ,
            IsSync ,
            WorkStationID
          FROM Cars.t_CarRentalDriver
          WHERE CarRentalID = @ID;
   
      INSERT INTO Cars.t_CarRentalHistoryOwner
          ( ID ,
            CarRentalHistoryID ,
            OwnerProfileID ,
            OwnerProfile ,
            ProfitRatio ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
