/****** Object:  StoredProcedure [Cars].[s_CarRentalNewPaidUp]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Cars].[s_CarRentalNewPaidUp] @DateIs DATE ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @PaidUp FLOAT ,
  @StatementIs NVARCHAR(MAX) ,
  @TransactionID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @EventTypeTransaction TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @RefF NVARCHAR(MAX) ,
        @AccountID UNIQUEIDENTIFIER ,
        @Account NVARCHAR(MAX) ,
        @AccountBox NVARCHAR(MAX) ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @TrnRef BIGINT ,
        @TrnRN INT ,
        @TrnStatementBase NVARCHAR(MAX) ,
        @TrnStatement NVARCHAR(MAX) ,
        @TrnLinkType INT = 185 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @return INT;
		

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @RefF = s.RefF ,
          @AccountID = s.AccountID ,
          @Account = s.Account ,
          @CID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro
        FROM Cars.t_CarRental AS s
        WHERE s.ID = @ID;
  
      SET @AccountBox = Company.f_AccountGetName(@AccountBoxID);
    
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
       
      SET @TrnStatementBase = N'CR:' + @RefF + N' ' + @StatementIs;
		      
    END;

    BEGIN --Insert

      SET @return = 0;

      UPDATE Cars.t_CarRental
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(@CID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpD * @ELL ,
            PaidUpEuro += @PaidUpD * @EEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(@CID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpD * @ELL ,
            RestEuro -= @PaidUpD * @EEuro ,
            Paid = IIF(( Rest - @PaidUp ) = 0, 2, 1)
        WHERE ID = @ID;
		
    END;

    BEGIN --Insert Event

      SET @return = -1;

      INSERT INTO Cars.t_CarRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Transaction

      BEGIN --Set info
      
        SET @return = 0;

        SELECT @TrnRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert transaction

        INSERT INTO Transactions.t_Transaction
            ( ID ,
              Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionID ,
              @TrnRef ,
              N'RV' ,
              @DateIs ,
              @TrnStatementBase ,
              @TrnLinkType ,
              9 ,
              @ID ,
              @UserID
            );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              FORMAT(@TrnRef, '#')
            );

      END;

      BEGIN --t_TransactionDetail

        SET @V = @PaidUp;
        SET @TrnRN = 1;
        SET @TrnStatement = @TrnStatementBase + ' \ ' + @Account;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @TrnRN, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TrnStatement;
		
        SET @TrnRN += 1;
        SET @TrnStatement = @TrnStatementBase;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @TrnRN, @TransactionID, @AccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TrnStatement;

      END;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            @TransactionID ,
            @Event + s.RefF ,
            @EventTypeTransaction ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @AccountID, @AccountBoxID ) AND StatusIs = 1;
               
      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;
     
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;






