GO

CREATE PROCEDURE [Company].[s_AccountInsert] @ID UNIQUEIDENTIFIER ,
  @Level3ID UNIQUEIDENTIFIER ,
  @Level3 NVARCHAR(MAX) ,
  @SectionID INT ,
  @LinkWithID UNIQUEIDENTIFIER ,
  @LinkWith NVARCHAR(MAX) ,
  @IsMasterLink BIT ,
  @NumberIs BIGINT ,
  @NumberF NVARCHAR(MAX) ,
  @NumberNet NVARCHAR(MAX) ,
  @Name NVARCHAR(225) ,
  @BalanceF NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyTypeIs INT ,
  @Limit FLOAT ,
  @LimitF NVARCHAR(MAX) ,
  @LimitD FLOAT ,
  @ProfitOrDepreciationRate FLOAT ,
  @IsStatic BIT ,
  @ShowInGymClass BIT ,
  @ShowInPersonalTrainer BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;
	
    BEGIN --Insert

      INSERT INTO Company.t_Account
          ( ID ,
            Level3ID ,
            Level3 ,
            SectionID ,
            LinkWithID ,
            LinkWith ,
            IsMasterLink ,
            NumberIs ,
            NumberF ,
            NumberNet ,
            Name ,
            BalanceF ,
            CurrencyID ,
            Currency ,
            CurrencyTypeIs ,
            Limit ,
            LimitF ,
            LimitD ,
            ProfitOrDepreciationRate ,
            IsStatic ,
            ShowInGymClass ,
            ShowInPersonalTrainer ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Level3ID ,
            @Level3 ,
            @SectionID ,
            @LinkWithID ,
            @LinkWith ,
            @IsMasterLink ,
            @NumberIs ,
            @NumberF ,
            @NumberNet ,
            @Name ,
            @BalanceF ,
            @CurrencyID ,
            @Currency ,
            @CurrencyTypeIs ,
            @Limit ,
            @LimitF ,
            @LimitD ,
            @ProfitOrDepreciationRate ,
            @IsStatic ,
            @ShowInGymClass ,
            @ShowInPersonalTrainer ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert t_AccountMoving

      SET @Return = -1;

      INSERT INTO Company.t_AccountMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










