/****** Object:  StoredProcedure [Company].[s_AccountRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_AccountRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Company.tr_Account ON Company.t_Account;
    DISABLE TRIGGER Company.tr_AccountLevel1 ON Company.t_AccountLevel1;
    DISABLE TRIGGER Company.tr_AccountLevel2 ON Company.t_AccountLevel2;
    DISABLE TRIGGER Company.tr_AccountLevel3 ON Company.t_AccountLevel3;

    BEGIN --Rebuilding statistics

      SET @Return = 0;

      UPDATE Company.t_Account
        SET Level3 = Company.f_AccountLevel3GetName(Level3ID) ,
            NumberNet = SUBSTRING(NumberF, 6, 5) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
            BalanceD = COALESCE(( SELECT SUM(t.BalanceD)
                                    FROM Transactions.t_TransactionDetail AS t
                                    WHERE t.AccountID = t_Account.ID
                                ), 0) ,
            BalanceLL = COALESCE(( SELECT SUM(t.BalanceLL)
                                    FROM Transactions.t_TransactionDetail AS t
                                    WHERE t.AccountID = t_Account.ID
                                 ), 0) ,
            BalanceEuro = COALESCE(( SELECT SUM(t.BalanceEuro)
                                      FROM Transactions.t_TransactionDetail AS t
                                      WHERE t.AccountID = t_Account.ID
                                   ), 0) ,
            SubaccountsBalance = Company.f_SubAccountsGetBalanceX(ID) ,
            SubaccountsBalanceD = Company.f_SubAccountsGetBalanceDX(ID) ,
            SubaccountsBalanceLL = Company.f_SubAccountsGetBalanceLLX(ID) ,
            SubaccountsBalanceEuro = Company.f_SubAccountsGetBalanceEuroX(ID) ,
            LimitF = Currencys.f_Format(CurrencyID, Limit) ,
            LimitD = Currencys.f_ExchangeToDollarBy(CurrencyID, Limit) ,
            UserBlockedC = ( SELECT COUNT(*)
                              FROM Company.t_AccountUserBlocked AS s
                              WHERE s.AccountID = t_Account.ID
                           ) ,
            UsersNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                          FROM Company.t_AccountUserBlocked AS t
                                          LEFT JOIN Users.t_User AS t1 ON t1.ID = t.UserID
                                          WHERE t.AccountID = t_Account.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            SubAccountsCount = Company.f_SubAccountsGetSubAccountsCountX(ID) ,
            SubAccountsNames = Company.f_SubAccountsGetSubAccountsNamesX(ID) ,
            DeliveryServicesC = [Invoices].f_DeliveryServiceGetCountByAccountCustomerID(ID) ,
            DeliveryServicesTotal = [Invoices].[f_DeliveryServiceGetTotalByAccountCustomerID](ID) ,
            DeliveryServicesProfit = [Invoices].[f_DeliveryServiceGetProfitByAccountCustomerID](ID) ,
            DeliveryServicesLastDate = [Invoices].f_DeliveryServiceGetLastDateByAccountCustomerID(ID) ,
            PurchasingC = [Invoices].[f_PurchasingGetCountByAccountVendorID](ID) ,
            PurchasingTotal = [Invoices].[f_PurchasingGetTotalByAccountVendorID](ID) ,
            PurchasingProfit = [Invoices].[f_PurchasingGetProfitByAccountVendorID](ID) ,
            PurchasingLast = [Invoices].[f_PurchasingGetLastDateByAccountVendorID](ID) ,
            PurchasingReturnC = [Invoices].[f_PurchasingReturnGetCountByAccountVendorID](ID) ,
            PurchasingReturnTotal = [Invoices].[f_PurchasingReturnGetTotalByAccountVendorID](ID) ,
            PurchasingReturnProfit = [Invoices].[f_PurchasingReturnGetProfitByAccountVendorID](ID) ,
            PurchasingReturnLast = [Invoices].[f_PurchasingReturnGetLastDateByAccountVendorID](ID) ,
            SoldC = [Invoices].[f_SoldGetCountByAccountCustomerID](ID) ,
            SoldTotal = [Invoices].[f_SoldGetTotalByAccountCustomerID](ID) ,
            SoldProfit = [Invoices].[f_SoldGetProfitByAccountCustomerID](ID) ,
            SoldLast = [Invoices].[f_SoldGetLastDateByAccountCustomerID](ID) ,
            SoldReturnC = [Invoices].[f_SoldReturnGetCountByAccountCustomerID](ID) ,
            SoldReturnTotal = [Invoices].[f_SoldReturnGetTotalByAccountCustomerID](ID) ,
            SoldReturnProfit = [Invoices].[f_SoldReturnGetProfitByAccountCustomerID](ID) ,
            SoldReturnLast = [Invoices].[f_SoldReturnGetLastDateByAccountCustomerID](ID) ,
            QuotationC = Quotations.[f_QuotationGetCountByAccountID](ID) ,
            QuotationTotal = Quotations.[f_QuotationGetTotalByAccountID](ID) ,
            QuotationProfit = Quotations.[f_QuotationGetProfitByAccountID](ID) ,
            QuotationLast = Quotations.[f_QuotationGetLastDateByAccountID](ID) ,
            GymSubscriptionC = [Gym].f_GymSubscriptionGetCountByAccountID(ID) ,
            GymSubscriptionLast = [Gym].f_GymSubscriptionGetLastByAccountID(ID) ,
            GymSubscriptionLastType = [Gym].f_GymSubscriptionGetLastTypeByAccountID(ID) ,
            GymSubscriptionTotal = [Gym].[f_GymSubscriptionGetTotalByAccountID](ID) ,
            GymSubscriptionProfit = [Gym].[f_GymSubscriptionGetProfitByAccountID](ID) ,
            GymSubscriptionActiveTo = [Gym].f_GymSubscriptionGetActiveToByAccountID(ID);

      UPDATE Company.t_Account
        SET SubaccountsBalanceF = Currencys.f_Format(CurrencyID, SubaccountsBalance) ,
            TotalBalance = Balance + SubaccountsBalance ,
            TotalBalanceF = Currencys.f_Format(CurrencyID, Balance + SubaccountsBalance) ,
            TotalBalanceD = BalanceD + SubaccountsBalanceD ,
            TotalBalanceLL = BalanceLL + SubaccountsBalanceLL ,
            TotalBalanceEuro = BalanceEuro + SubaccountsBalanceEuro ,
            DeliveryServicesTotalF = Currencys.f_Format(CurrencyID, DeliveryServicesTotal) ,
            DeliveryServicesProfitF = Currencys.f_Format(CurrencyID, DeliveryServicesProfit) ,
            PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
            PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit) ,
            PurchasingReturnTotalF = Currencys.f_Format(CurrencyID, PurchasingReturnTotal) ,
            PurchasingReturnProfitF = Currencys.f_Format(CurrencyID, PurchasingReturnProfit) ,
            SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
            SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit) ,
            SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
            SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit) ,
            QuotationTotalF = Currencys.f_Format(CurrencyID, QuotationTotal) ,
            QuotationProfitF = Currencys.f_Format(CurrencyID, QuotationProfit) ,
            GymSubscriptionTotalF = Currencys.f_Format(CurrencyID, GymSubscriptionTotal) ,
            GymSubscriptionProfitF = Currencys.f_Format(CurrencyID, GymSubscriptionProfit) ,
            GymSubscriptionIsActive = IIF(GymSubscriptionActiveTo >= DateTimes.f_GetToday(), 1, 0);

      UPDATE Company.t_AccountLevel3
        SET Level2 = Company.f_AccountLevel2GetName(Level2ID) ,
            BalanceD = COALESCE(( SELECT SUM(t.BalanceD)
                                    FROM Company.t_Account AS t
                                    WHERE t.Level3ID = t_AccountLevel3.ID
                                ), 0) ,
            BalanceLL = COALESCE(( SELECT SUM(t.BalanceLL)
                                    FROM Company.t_Account AS t
                                    WHERE t.Level3ID = t_AccountLevel3.ID
                                 ), 0) ,
            BalanceEuro = COALESCE(( SELECT SUM(t.BalanceEuro)
                                      FROM Company.t_Account AS t
                                      WHERE t.Level3ID = t_AccountLevel3.ID
                                   ), 0);

      UPDATE Company.t_AccountLevel2
        SET Level1 = Company.f_AccountLevel2GetName(Level1ID) ,
            BalanceD = COALESCE(( SELECT SUM(t.BalanceD)
                                    FROM Company.t_AccountLevel3 AS t
                                    WHERE t.Level2ID = t_AccountLevel2.ID
                                ), 0) ,
            BalanceLL = COALESCE(( SELECT SUM(t.BalanceLL)
                                    FROM Company.t_AccountLevel3 AS t
                                    WHERE t.Level2ID = t_AccountLevel2.ID
                                 ), 0) ,
            BalanceEuro = COALESCE(( SELECT SUM(t.BalanceEuro)
                                      FROM Company.t_AccountLevel3 AS t
                                      WHERE t.Level2ID = t_AccountLevel2.ID
                                   ), 0);

      UPDATE Company.t_AccountLevel1
        SET BalanceD = COALESCE(( SELECT SUM(t.BalanceD)
                                    FROM Company.t_AccountLevel2 AS t
                                    WHERE t.Level1ID = t_AccountLevel1.ID
                                ), 0) ,
            BalanceLL = COALESCE(( SELECT SUM(t.BalanceLL)
                                    FROM Company.t_AccountLevel2 AS t
                                    WHERE t.Level1ID = t_AccountLevel1.ID
                                 ), 0) ,
            BalanceEuro = COALESCE(( SELECT SUM(t.BalanceEuro)
                                      FROM Company.t_AccountLevel2 AS t
                                      WHERE t.Level1ID = t_AccountLevel1.ID
                                   ), 0);

    END;

    BEGIN --levels

      UPDATE Company.t_AccountLevel2
        SET Level1 = Company.f_AccountLevel1GetName(Level1ID) ,
            NumberNet = SUBSTRING(NumberF, 3, 1);

      UPDATE Company.t_AccountLevel3
        SET Level2 = Company.f_AccountLevel2GetName(Level2ID) ,
            NumberNet = SUBSTRING(NumberF, 4, 2);

    END;

    ENABLE TRIGGER Company.tr_Account ON Company.t_Account;
    ENABLE TRIGGER Company.tr_AccountLevel1 ON Company.t_AccountLevel1;
    ENABLE TRIGGER Company.tr_AccountLevel2 ON Company.t_AccountLevel2;
    ENABLE TRIGGER Company.tr_AccountLevel3 ON Company.t_AccountLevel3;

    BEGIN --Account Blocked

      UPDATE Company.t_AccountUserBlocked
        SET Account = Company.f_AccountGetName(AccountID);

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_AccountMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;
END;











GO
/****** Object:  StoredProcedure [Company].[s_AccountRebuildSubaccounts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_AccountRebuildSubaccounts] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    DISABLE TRIGGER Company.tr_Account ON Company.t_Account;

    BEGIN --Update

      UPDATE Company.t_Account
        SET SubAccountsCount = Company.f_SubAccountsGetSubAccountsCountX(ID) ,
            SubAccountsNames = Company.f_SubAccountsGetSubAccountsNamesX(ID) ,
            SubaccountsBalance = 0 ,
            SubaccountsBalanceD = 0 ,
            SubaccountsBalanceLL = 0 ,
            SubaccountsBalanceEuro = 0 ,
            TotalBalance = 0 ,
            TotalBalanceD = 0 ,
            TotalBalanceLL = 0 ,
            TotalBalanceEuro = 0;

      UPDATE Company.t_Account
        SET SubaccountsBalance = Company.f_SubAccountsGetBalanceX(ID) ,
            SubaccountsBalanceD = Company.f_SubAccountsGetBalanceDX(ID) ,
            SubaccountsBalanceLL = Company.f_SubAccountsGetBalanceLLX(ID) ,
            SubaccountsBalanceEuro = Company.f_SubAccountsGetBalanceEuroX(ID)
        WHERE SubAccountsCount > 0;

      UPDATE Company.t_Account
        SET SubaccountsBalanceF = Currencys.f_Format(CurrencyID, SubaccountsBalance) ,
            TotalBalance = Balance + SubaccountsBalance ,
            TotalBalanceF = Currencys.f_Format(CurrencyID, Balance + SubaccountsBalance) ,
            TotalBalanceD = BalanceD + SubaccountsBalanceD ,
            TotalBalanceLL = BalanceLL + SubaccountsBalanceLL ,
            TotalBalanceEuro = BalanceEuro + SubaccountsBalanceEuro;

    END;

    ENABLE TRIGGER Company.tr_Account ON Company.t_Account;
	
    SET @Return = -1;
    EXECUTE Company.s_AccountMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;
END;




GO
/****** Object:  StoredProcedure [Company].[s_AccountUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_AccountUpdate] @Name NVARCHAR(450) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Limit FLOAT ,
  @ProfitOrDepreciationRate FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450) ,
        @CurrencyIDOld UNIQUEIDENTIFIER ,
        @ExchangeRate FLOAT;

    END;

    BEGIN --Set Info

      SELECT @CurrencyIDOld = CurrencyID
        FROM Company.t_Account
        WHERE ID = @ID;

      SELECT @ExchangeRate = ExchangeRate
        FROM Currencys.t_Currency
        WHERE ID = @CurrencyID;

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Company.t_Account AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update 

      SET @Return = 0;

      UPDATE Company.t_Account
        SET Name = @Name ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID) ,
            Limit = @Limit ,
            LimitF = Currencys.f_Format(@CurrencyID, @Limit) ,
            LimitD = @Limit / @ExchangeRate ,
            ProfitOrDepreciationRate = @ProfitOrDepreciationRate ,
            DescriptionIs = @DescriptionIs ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN; --Fix t_Account

      DISABLE TRIGGER Company.tr_Account ON Company.t_Account;
      DISABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;
      DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
      DISABLE TRIGGER Invoices.tr_PurchasingReturn ON Invoices.t_PurchasingReturn;
      DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

      BEGIN --t_PurchaseOrder

        UPDATE Invoices.t_PurchaseOrder
          SET Account = @Name ,
              IsSync = 0
          WHERE AccountID = @ID;

        UPDATE Invoices.t_PurchaseOrderArchive
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --t_DressesRental

        UPDATE Invoices.t_DressesRental
          SET Account = @Name ,
              IsSync = 0
          WHERE AccountID = @ID;

        UPDATE Invoices.t_DressesRentalArchive
          SET Account = @Name ,
              IsSync = 0
          WHERE AccountID = @ID;

      END;

      BEGIN --Account Blocked

        UPDATE Company.t_AccountUserBlocked
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN; --t_Purchasing

        UPDATE Invoices.t_Purchasing
          SET AccountVendor = @Name
          WHERE AccountVendorID = @ID;
				
        UPDATE Invoices.t_Purchasing
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

        UPDATE Invoices.t_Purchasing
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @ID;

      END;

      BEGIN; --t_PurchasingDeleted

        UPDATE Invoices.t_PurchasingDeleted
          SET AccountVendor = @Name
          WHERE AccountVendorID = @ID;
				
        UPDATE Invoices.t_PurchasingDeleted
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

        UPDATE Invoices.t_PurchasingDeleted
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @ID;

      END;

      BEGIN; --t_PurchasingReturn

        UPDATE Invoices.t_PurchasingReturn
          SET AccountVendor = @Name
          WHERE AccountVendorID = @ID;

        UPDATE Invoices.t_PurchasingReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

      END;

      BEGIN; --t_Sold

        UPDATE Invoices.t_Sold
          SET AccountCustomer = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountCustomerID = @ID;

        UPDATE Invoices.t_Sold
          SET AccountBox = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountBoxID = @ID;

        UPDATE Invoices.t_Sold
          SET SecondPaymentAccountBox = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE SecondPaymentAccountBoxID = @ID;

      END;
  
      BEGIN; --t_SoldDeleted

        UPDATE Invoices.t_SoldDeleted
          SET AccountCustomer = @Name
          WHERE AccountCustomerID = @ID;

        UPDATE Invoices.t_SoldDeleted
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

        UPDATE Invoices.t_SoldDeleted
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @ID;

      END;

      BEGIN; --t_SoldReturn

        UPDATE Invoices.t_SoldReturn
          SET AccountCustomer = @Name
          WHERE AccountCustomerID = @ID;

        UPDATE Invoices.t_SoldReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

      END;

      BEGIN; --Transaction Detail

        UPDATE Transactions.t_TransactionDetail
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --Transaction Detail By Day

        UPDATE Transactions.t_TransactionDetailByDay
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --Transaction Detail By Month

        UPDATE Transactions.t_TransactionDetailByMonth
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --Transaction Detail By Year

        UPDATE Transactions.t_TransactionDetailByYear
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --Account Group Account

        UPDATE Company.t_AccountGroupAccount
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

      BEGIN --t_User

        UPDATE Users.t_User
          SET AccountBoxName = @Name
          WHERE AccountBoxID = @ID;
    
        UPDATE Users.t_User
          SET AccountBoxLLName = @Name
          WHERE AccountBoxLLID = @ID;
	
        UPDATE Users.t_User
          SET AccountBoxEuroName = @Name
          WHERE AccountBoxEuroID = @ID;

      END;

      BEGIN --Fix t_CloseBox

        UPDATE Company.t_CloseBox
          SET FromAccount = @Name
          WHERE FromAccountID = @ID;

        UPDATE Company.t_CloseBox
          SET ToAccount = @Name
          WHERE ToAccountID = @ID;

      END;

      BEGIN --Fix t_Expense

        UPDATE Company.t_Expense
          SET FromAccount = @Name ,
              RowVersionID = DateTimes.f_GetRowVersionID()
          WHERE FromAccountID = @ID;

        UPDATE Company.t_Expense
          SET ToAccount = @Name ,
              RowVersionID = DateTimes.f_GetRowVersionID()
          WHERE ToAccountID = @ID;

        UPDATE Company.t_Expense
          SET VendorAccount = @Name ,
              RowVersionID = DateTimes.f_GetRowVersionID()
          WHERE VendorAccountID = @ID;

      END;

      BEGIN --Fix t_OpenBox

        UPDATE Company.t_OpenBox
          SET FromAccount = @Name
          WHERE FromAccountID = @ID;

        UPDATE Company.t_OpenBox
          SET ToAccount = @Name
          WHERE ToAccountID = @ID;

      END;

      BEGIN --Fix t_GymClass
	  
        UPDATE Gym.t_GymClass
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

      END;

      BEGIN --Fix t_PersonalTrainer
	  
        UPDATE Gym.t_PersonalTrainer
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

      END;

      BEGIN --Fix t_GymSubscription

        UPDATE Gym.t_GymSubscription
          SET Account = @Name
          WHERE AccountID = @ID;

        UPDATE Gym.t_GymSubscription
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

        UPDATE Gym.t_GymSubscription
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;
		  
        UPDATE Gym.t_GymSubscriptionClass
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

      END;

      BEGIN --Fix t_GymSubscriptionHistory

        UPDATE Gym.t_GymSubscriptionHistory
          SET Account = @Name
          WHERE AccountID = @ID;

        UPDATE Gym.t_GymSubscriptionHistory
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

        UPDATE Gym.t_GymSubscriptionHistory
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;
		  
        UPDATE Gym.t_GymSubscriptionHistoryClass
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

      END;

      BEGIN --Fix t_GymSubscriptionDeleted

        UPDATE Gym.t_GymSubscriptionDeleted
          SET Account = @Name
          WHERE AccountID = @ID;

        UPDATE Gym.t_GymSubscriptionDeleted
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

        UPDATE Gym.t_GymSubscriptionDeleted
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

        UPDATE Gym.t_GymSubscriptionDeletedClass
          SET AccountEmployee = @Name
          WHERE AccountEmployeeID = @ID;

      END;

      BEGIN --Fix t_GymMemberAttendance

        UPDATE Gym.t_GymMemberAttendance
          SET Account = @Name
          WHERE AccountID = @ID;

      END;
	  
      BEGIN --Fix t_CarExpense

        UPDATE Cars.t_CarExpense
          SET FromAccount = @Name
          WHERE FromAccountID = @ID;

        UPDATE Cars.t_CarExpense
          SET ToAccount = @Name
          WHERE ToAccountID = @ID;

        UPDATE Cars.t_CarExpense
          SET VendorAccount = @Name
          WHERE VendorAccountID = @ID;

      END;
    
      BEGIN --Fix t_CarRental

        UPDATE Cars.t_CarRental
          SET Account = @Name
          WHERE AccountID = @ID;

        UPDATE Cars.t_CarRentalHistory
          SET Account = @Name
          WHERE AccountID = @ID;
    
        UPDATE Cars.t_CarRental
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

        UPDATE Cars.t_CarRentalHistory
          SET AccountBox = @Name
          WHERE AccountBoxID = @ID;

      END;

      ENABLE TRIGGER Company.tr_Account ON Company.t_Account;
      ENABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;
      ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
      ENABLE TRIGGER Invoices.tr_PurchasingReturn ON Invoices.t_PurchasingReturn;
      ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

      BEGIN --Fix t_DeliveryPermission

        UPDATE Items.t_DeliveryPermission
          SET Account = @Name
          WHERE AccountID = @ID;

        UPDATE Items.t_DeliveryPermissionHistory
          SET Account = @Name
          WHERE AccountID = @ID;

      END;

    END;

    IF @CurrencyIDOld <> @CurrencyID
    BEGIN; --Fix Balance

      UPDATE Company.t_Account
        SET Balance = COALESCE(( SELECT CASE t_Account.CurrencyTypeIs
                                          WHEN 0 THEN SUM(t.BalanceD)
                                          WHEN 1 THEN SUM(t.BalanceLL)
                                          ELSE SUM(t.BalanceEuro)
                                        END
                                  FROM Transactions.t_TransactionDetail AS t
                                  WHERE t.AccountID = t_Account.ID
                               ), 0) ,
            DeliveryServicesTotal = [Invoices].[f_DeliveryServiceGetTotalByAccountCustomerID](ID) ,
            DeliveryServicesProfit = [Invoices].[f_DeliveryServiceGetProfitByAccountCustomerID](ID) ,
            PurchasingTotal = [Invoices].[f_PurchasingGetTotalByAccountVendorID](ID) ,
            PurchasingProfit = [Invoices].[f_PurchasingGetProfitByAccountVendorID](ID) ,
            PurchasingReturnTotal = [Invoices].[f_PurchasingReturnGetTotalByAccountVendorID](ID) ,
            PurchasingReturnProfit = [Invoices].[f_PurchasingReturnGetProfitByAccountVendorID](ID) ,
            SoldTotal = [Invoices].[f_SoldGetTotalByAccountCustomerID](ID) ,
            SoldProfit = [Invoices].[f_SoldGetProfitByAccountCustomerID](ID) ,
            SoldReturnTotal = [Invoices].[f_SoldReturnGetTotalByAccountCustomerID](ID) ,
            SoldReturnProfit = [Invoices].[f_SoldReturnGetProfitByAccountCustomerID](ID) ,
            QuotationTotal = Quotations.[f_QuotationGetTotalByAccountID](ID) ,
            QuotationProfit = Quotations.[f_QuotationGetProfitByAccountID](ID) ,
            GymSubscriptionTotal = [Gym].[f_GymSubscriptionGetTotalByAccountID](ID) ,
            GymSubscriptionProfit = [Gym].[f_GymSubscriptionGetProfitByAccountID](ID)
        WHERE ID = @ID;

      UPDATE Company.t_Account
        SET BalanceF = Currencys.f_Format(@CurrencyID, Balance) ,
            DeliveryServicesTotalF = Currencys.f_Format(CurrencyID, DeliveryServicesTotal) ,
            DeliveryServicesProfitF = Currencys.f_Format(CurrencyID, DeliveryServicesProfit) ,
            PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
            PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit) ,
            PurchasingReturnTotalF = Currencys.f_Format(CurrencyID, PurchasingReturnTotal) ,
            PurchasingReturnProfitF = Currencys.f_Format(CurrencyID, PurchasingReturnProfit) ,
            SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
            SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit) ,
            SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
            SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit) ,
            QuotationTotalF = Currencys.f_Format(CurrencyID, QuotationTotal) ,
            QuotationProfitF = Currencys.f_Format(CurrencyID, QuotationProfit) ,
            GymSubscriptionTotalF = Currencys.f_Format(CurrencyID, GymSubscriptionTotal) ,
            GymSubscriptionProfitF = Currencys.f_Format(CurrencyID, GymSubscriptionProfit)
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_AccountMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





