            t.FinalBalanceLL ,
            t.FinalBalanceEuro ,
            t.SafeAmount ,
            t.SafeAmountF ,
            t.SafeAmountD ,
            t.SafeAmountLL ,
            t.SafeAmountEuro ,
            t.WorkmateAmount ,
            t.WorkmateAmountF ,
            t.WorkmateAmountD ,
            t.WorkmateAmountLL ,
            t.WorkmateAmountEuro ,
            t.KeepWithMe ,
            t.KeepWithMeF ,
            t.KeepWithMeD ,
            t.KeepWithMeLL ,
            t.KeepWithMeEuro ,
            t.DifferenceBalance ,
            t.DifferenceBalanceF ,
            t.DifferenceBalanceD ,
            t.DifferenceBalanceLL ,
            t.DifferenceBalanceEuro ,
            t.BanknotesLLQtys1000 ,
            t.BanknotesLLQtys5000 ,
            t.BanknotesLLQtys10000 ,
            t.BanknotesLLQtys20000 ,
            t.BanknotesLLQtys50000 ,
            t.BanknotesLLQtys100000 ,
            t.BanknotesLLTotal1000 ,
            t.BanknotesLLTotal5000 ,
            t.BanknotesLLTotal10000 ,
            t.BanknotesLLTotal20000 ,
            t.BanknotesLLTotal50000 ,
            t.BanknotesLLTotal100000 ,
            t.BanknotesLLTotal ,
            t.BanknotesLLNumbers1000 ,
            t.BanknotesLLNumbers5000 ,
            t.BanknotesLLNumbers10000 ,
            t.BanknotesLLNumbers20000 ,
            t.BanknotesLLNumbers50000 ,
            t.BanknotesLLNumbers100000 ,
            t.BanknotesDollarQtys1 ,
            t.BanknotesDollarQtys5 ,
            t.BanknotesDollarQtys10 ,
            t.BanknotesDollarQtys20 ,
            t.BanknotesDollarQtys50 ,
            t.BanknotesDollarQtys100 ,
            t.BanknotesDollarTotal1 ,
            t.BanknotesDollarTotal5 ,
            t.BanknotesDollarTotal10 ,
            t.BanknotesDollarTotal20 ,
            t.BanknotesDollarTotal50 ,
            t.BanknotesDollarTotal100 ,
            t.BanknotesDollarTotal ,
            t.BanknotesDollarNumbers1 ,
            t.BanknotesDollarNumbers5 ,
            t.BanknotesDollarNumbers10 ,
            t.BanknotesDollarNumbers20 ,
            t.BanknotesDollarNumbers50 ,
            t.BanknotesDollarNumbers100 ,
            t.Notes ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Company.t_DailyBox AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Delete t_DailyBox

      DELETE FROM Company.t_DailyBox
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DailyBoxMoving

      SET @return = -1;

      INSERT INTO Company.t_DailyBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @EventUserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
  
    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'dailyBox' );
  
    END;

    EXECUTE Company.s_DailyBoxLiveVersion;
    EXECUTE Company.s_ArchiveDailyBoxLiveVersion;
	
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;





