/****** Object:  StoredProcedure [Company].[s_ArchiveDailyBoxRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_ArchiveDailyBoxRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Company.t_ArchiveDailyBox
        SET OpeningBalanceF = Currencys.f_Format(CurrencyID, OpeningBalance) ,
            SalesF = Currencys.f_Format(CurrencyID, Sales) ,
            CashSalesF = Currencys.f_Format(CurrencyID, CashSales) ,
            OtherIncomeF = Currencys.f_Format(CurrencyID, OtherIncome) ,
            SalesReturnsF = Currencys.f_Format(CurrencyID, SalesReturns) ,
            ExpensesF = Currencys.f_Format(CurrencyID, Expenses) ,
            OtherOutcomeF = Currencys.f_Format(CurrencyID, OtherOutcome) ,
            FinalBalanceF = Currencys.f_Format(CurrencyID, FinalBalance) ,
            SafeAmountF = Currencys.f_Format(CurrencyID, SafeAmount) ,
            WorkmateAmountF = Currencys.f_Format(CurrencyID, WorkmateAmount) ,
            KeepWithMeF = Currencys.f_Format(CurrencyID, KeepWithMe) ,
            DifferenceBalanceF = Currencys.f_Format(CurrencyID, DifferenceBalance) ,
            IsSync = 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_DailyBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    EXECUTE Company.s_ArchiveDailyBoxLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




