/****** Object:  StoredProcedure [Company].[s_BankUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_BankUpdate] @Name NVARCHAR(450) ,
  @StatesID UNIQUEIDENTIFIER ,
  @RegionID UNIQUEIDENTIFIER ,
  @StreetID UNIQUEIDENTIFIER ,
  @BuildingID UNIQUEIDENTIFIER ,
  @FloorID UNIQUEIDENTIFIER ,
  @PostalCodeID UNIQUEIDENTIFIER ,
  @AddressNote NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450) ,
        @AccountID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Company.t_Bank AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;
      UPDATE Company.t_Bank
        SET Name = @Name ,
            StatesID = @StatesID ,
            RegionID = @RegionID ,
            StreetID = @StreetID ,
            BuildingID = @BuildingID ,
            FloorID = @FloorID ,
            PostalCodeID = @PostalCodeID ,
            AddressNote = @AddressNote ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Format

      EXECUTE Company.s_BankFormat @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_BankMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --t_Account

        UPDATE Company.t_Account
          SET LinkWith = @Name ,
              Name = @Name
          WHERE SectionID = 38 AND LinkWithID = @ID;

      END;

      BEGIN --Set info

        SELECT TOP ( 1 ) @AccountID = s.ID
          FROM Company.t_Account AS s
          WHERE SectionID = 38 AND LinkWithID = @ID
          ORDER BY s.ID;

      END;

      BEGIN; --t_Purchasing

        UPDATE Invoices.t_Purchasing
          SET AccountVendor = @Name
          WHERE AccountVendorID = @AccountID;
				
        UPDATE Invoices.t_Purchasing
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;

      END;

      BEGIN; --t_PurchasingReturn

        UPDATE Invoices.t_PurchasingReturn
          SET AccountVendor = @Name
          WHERE AccountVendorID = @AccountID;

        UPDATE Invoices.t_PurchasingReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;

      END;

      BEGIN; --t_Sold

        UPDATE Invoices.t_Sold
          SET AccountCustomer = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountCustomerID = @AccountID;

        UPDATE Invoices.t_Sold
          SET AccountBox = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountBoxID = @AccountID;

      END;

      BEGIN; --t_SoldReturn

        UPDATE Invoices.t_SoldReturn
          SET AccountCustomer = @Name
          WHERE AccountCustomerID = @AccountID;

        UPDATE Invoices.t_SoldReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









