/****** Object:  StoredProcedure [Company].[s_BookPhoneDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_BookPhoneDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --DECLARE

      DECLARE @OwnerID UNIQUEIDENTIFIER ,
        @SectionID INT ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OwnerID = s.OwnerID ,
          @SectionID = s.SectionID
        FROM Company.t_BookPhone AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = -2;

      DELETE FROM Company.t_BookPhone
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      IF @SectionID = 15
      BEGIN

        EXECUTE Customers.s_CustomerMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @OwnerID;

      END;
      ELSE
        IF @SectionID = 33
        BEGIN

          INSERT INTO Employees.t_EmployeeMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
            VALUES
              ( @UserID ,
                @OwnerID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

        END;
        ELSE
          IF @SectionID = 38
          BEGIN

            INSERT INTO Company.t_BankMoving
                ( UserID ,
                  SectionID ,
