/****** Object:  StoredProcedure [Company].[s_CallsArchiveInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_CallsArchiveInserts] @IDs Alls.tt_IDAndEvent READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Company.t_CallsArchive
          ( ID ,
            Ref ,
            RefF ,
            CallsTypesID ,
            DateTimeIs ,
            ReceivedFromNumber ,
            CallerNumber ,
            Notes ,
            SourceType ,
            IsSync
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.CallsTypesID ,
            t.DateTimeIs ,
            t.ReceivedFromNumber ,
            t.CallerNumber ,
            t.Notes ,
            t.SourceType ,
            t.IsSync
          FROM Company.t_Calls AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Delete

      DELETE FROM Company.t_Calls
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Calls.ID );

    END;

    SET @Return = -1;
    EXECUTE Company.s_CallsMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
		
    EXECUTE Company.s_CallsLiveVersion;
    EXECUTE Company.s_CallsArchiveLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;













