CREATE PROCEDURE [Company].[s_CallsEngineInsert] @ReceivedFromNumber NVARCHAR(MAX) ,
  @CallerNumber NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @CallsTypesID UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Set
	    
      SET @Ref = Company.f_CallsGetNewRef();
      SET @RefF = FORMAT(@Ref, '#');
      SET @CallsTypesID = Company.f_CallsTypesGetFirstID();

    END;

    BEGIN --Insert

      INSERT INTO Company.t_Calls
          ( Ref ,
            RefF ,
            CallsTypesID ,
            ReceivedFromNumber ,
            CallerNumber
          )
        VALUES
          ( @Ref ,
            @RefF ,
            @CallsTypesID ,
            @ReceivedFromNumber ,
            @CallerNumber
          );
	  
    END;

    EXECUTE Company.s_CallsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








