/****** Object:  StoredProcedure [Company].[s_CallsExecuteJobArchiveInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_CallsExecuteJobArchiveInsert]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Company_Calls < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Insert

      INSERT INTO Company.t_CallsArchive
          ( Ref ,
            RefF ,
            CallsTypesID ,
            DateTimeIs ,
            ReceivedFromNumber ,
            CallerNumber ,
            Notes ,
            SourceType ,
            IsSync
          )
        SELECT t.Ref ,
            t.RefF ,
            t.CallsTypesID ,
            t.DateTimeIs ,
            t.ReceivedFromNumber ,
            t.CallerNumber ,
            t.Notes ,
            t.SourceType ,
            t.IsSync
          FROM Company.t_Calls AS t
          WHERE CONVERT(DATE, t.DateTimeIs) < DateTimes.f_GetToday();

    END;

    BEGIN --Delete

      DELETE FROM Company.t_Calls
        WHERE CONVERT(DATE, DateTimeIs) < DateTimes.f_GetToday();

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Company_Calls = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;













