GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_CallsInsert] @ID UNIQUEIDENTIFIER ,
  @CallsTypesID UNIQUEIDENTIFIER ,
  @ReceivedFromNumber NVARCHAR(MAX) ,
  @CallerNumber NVARCHAR(MAX) ,
  @Notes NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @Return INT = 0;

    END;

    BEGIN --Set
	    
      SET @Ref = Company.f_CallsGetNewRef();
      SET @RefF = FORMAT(@Ref, '#');

    END;

    BEGIN --Insert

      INSERT INTO Company.t_Calls
          ( ID ,
            Ref ,
            RefF ,
            CallsTypesID ,
            ReceivedFromNumber ,
            CallerNumber ,
            Notes ,
            SourceType
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @CallsTypesID ,
            @ReceivedFromNumber ,
            @CallerNumber ,
            @Notes ,
            @SourceType
          );
	  
    END;

    UPDATE Alls.t_CompanyInfo
      SET LastCallID = @ID;

    SET @Return = -1;
    EXECUTE Company.s_CallsMovingInsert @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID; 

    EXECUTE Company.s_CallsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







