/****** Object:  StoredProcedure [Company].[s_CloseBoxFixPart]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_CloseBoxFixPart] @ID UNIQUEIDENTIFIER
AS
BEGIN

  DECLARE @ExchangeRate FLOAT;

  SELECT TOP ( 1 ) @ExchangeRate = s.ExchangeRate
    FROM Company.t_CloseBox AS s
    WHERE s.ID = @ID
    ORDER BY s.ID;

  UPDATE Company.t_CloseBoxDetail
    SET Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
        CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(CurrencyID) ,
        PriceF = Currencys.f_Format(CurrencyID, Price) ,
        PriceD = Price / @ExchangeRate ,
        Total = Price * Qty ,
        TotalF = Currencys.f_Format(CurrencyID, Price * Qty)
    WHERE CloseBoxID = @ID;

  UPDATE Company.t_CloseBox
    SET RefF = FORMAT(Ref, '#') ,
        DateOnly = DateIs ,
        FromUser = Users.f_UserGetName(FromUserID) ,
        ToUser = Users.f_UserGetName(ToUserID) ,
        FromAccount = Company.f_AccountGetName(FromAccountID) ,
        FromAccountNumberF = Company.f_AccountGetNumberF(FromAccountID) ,
        ToAccount = Company.f_AccountGetName(ToAccountID) ,
        ToAccountNumberF = Company.f_AccountGetNumberF(ToAccountID) ,
        Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
        BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
        BalanceD = Balance / ExchangeRate ,
        BalanceLL = ( Balance / ExchangeRate ) * ExchangeRateLL ,
        BalanceEuro = ( Balance / ExchangeRate ) * ExchangeRateEuro ,
        BalanceAR = Currencys.f_ToWordAR(Balance, CurrencyID, 1) ,
        BalanceEN = Currencys.f_ToWordEN(Balance, CurrencyID, 1) ,
        BalanceDifferenceF = Currencys.f_Format(CurrencyID, BalanceDifference) ,
        BalanceDifferenceD = BalanceDifference / ExchangeRate ,
        BalanceDifferenceLL = ( BalanceDifference / ExchangeRate ) * ExchangeRateLL ,
        BalanceDifferenceEuro = ( BalanceDifference / ExchangeRate ) * ExchangeRateEuro ,
        TotalD = ( SELECT COALESCE(SUM(s.Total), 0)
                    FROM Company.t_CloseBoxDetail AS s
                    WHERE s.CloseBoxID = t_CloseBox.ID AND s.CurrencyTypeIs = 0
                 ) ,
        TotalLL = ( SELECT COALESCE(SUM(s.Total), 0)
                      FROM Company.t_CloseBoxDetail AS s
                      WHERE s.CloseBoxID = t_CloseBox.ID AND s.CurrencyTypeIs = 1
                  ) ,
        TotalEuro = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM Company.t_CloseBoxDetail AS s
                        WHERE s.CloseBoxID = t_CloseBox.ID AND s.CurrencyTypeIs = 2
                    )
    WHERE ID = @ID;

  UPDATE Company.t_CloseBox
    SET TotalDF = Currencys.f_FormatD(TotalD) ,
        TotalLLF = Currencys.f_FormatLL(TotalLL) ,
        TotalEuroF = Currencys.f_FormatEuro(TotalEuro)
    WHERE ID = @ID;

  RETURN 1;

END;




