/****** Object:  StoredProcedure [Company].[s_CloseBoxInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Company].[s_CloseBoxInsert] @DateIs DATE ,
  @TransactionDate DATE ,
  @FromUserID UNIQUEIDENTIFIER ,
  @ToUserID UNIQUEIDENTIFIER ,
  @FromAccountID UNIQUEIDENTIFIER ,
  @ToAccountID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Balance FLOAT ,
  @BalanceDifference FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @CloseBoxDetail [Company].[tt_CloseBoxDetail] READONLY ,
  @TransactionID UNIQUEIDENTIFIER ,
  @TransactionDetail Transactions.dt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(s.Ref), 0) + 1
        FROM Company.t_CloseBox AS s;

    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Company.t_CloseBox
          ( ID ,
            Ref ,
            DateIs ,
            FromUserID ,
            ToUserID ,
            FromAccountID ,
            ToAccountID ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Balance ,
            BalanceDifference ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            @DateIs ,
            @FromUserID ,
            @UserID ,
            @FromAccountID ,
            @ToAccountID ,
            @CurrencyID ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Balance ,
            @BalanceDifference ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert t_CloseBoxDetail

      INSERT INTO Company.t_CloseBoxDetail
          ( CloseBoxID ,
            CurrencyID ,
            Price ,
            Qty ,
            DescriptionIs
          )
        SELECT @ID ,
            s.CurrencyID ,
            s.Price ,
            s.Qty ,
            s.DescriptionIs
          FROM @CloseBoxDetail AS s;

    END;

    BEGIN --Insert t_CloseBoxMoving

      SET @return = -1;

      INSERT INTO Company.t_CloseBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, '#') ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Company.s_CloseBoxFixPart @ID;

    SET @DescriptionIs += N' {0}';

    EXECUTE Transactions.s_TransactionInsertPart @TransactionID, 'JV', 0, @TransactionDate, @UserID, @DescriptionIs, 160, 0, @ID, @ID, @TransactionDetail, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;











