/****** Object:  StoredProcedure [Company].[s_CloseBoxUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_CloseBoxUpdate] @DescriptionIs NVARCHAR(MAX) ,
  @Detail [Company].[tt_CloseBoxDetail] READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ExchangeRate FLOAT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ExchangeRate = s.ExchangeRate
        FROM Company.t_CloseBox AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Insert

      UPDATE Company.t_CloseBox
        SET DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Insert detail

      MERGE Company.t_CloseBoxDetail AS t
      USING @Detail AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( CloseBoxID ,
                 CurrencyID ,
                 Price ,
                 Qty ,
                 DescriptionIs
               )
        VALUES ( @ID ,
                 s.CurrencyID ,
                 s.Price ,
                 s.Qty ,
                 s.DescriptionIs
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Price = s.Price ,
                    t.Qty = s.Qty ,
                    t.DescriptionIs = s.DescriptionIs
      WHEN NOT MATCHED BY SOURCE THEN
        DELETE;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Company.t_CloseBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Company.s_CloseBoxFixPart @ID;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;









