/****** Object:  StoredProcedure [Company].[s_ContactDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_ContactDelete]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Delete phones 

            DELETE FROM Company.t_BookPhone
            WHERE SectionID = 153
                  AND OwnerID = @ID;

        END;

        BEGIN --Delete SocialMedia 

            DELETE FROM Company.t_SocialMedia
            WHERE SectionID = 153
                  AND OwnerID = @ID;

        END;

        BEGIN --Delete

            SET @Return = 0;

            DELETE FROM Company.t_Contact
            WHERE ID = @ID;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Company.t_ContactMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, @ID, @Event, 2, @ComputerIP, @Computer, @ComputerAccount);

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK TRANSACTION;

        RETURN @Return;

    END CATCH;

END;














