/****** Object:  StoredProcedure [Company].[s_DailyBoxDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_DailyBoxDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete

      DELETE FROM Company.t_DailyBox
        WHERE ID = @ID;

      DELETE FROM Company.t_ArchiveDailyBox
        WHERE ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 220 AND LinkID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_DailyBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'dailyBox' );
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'archiveDailyBox' );

    END;

    EXECUTE Company.s_DailyBoxLiveVersion;
    EXECUTE Company.s_ArchiveDailyBoxLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









