/****** Object:  StoredProcedure [Company].[s_DailyBoxInsertShort]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_DailyBoxInsertShort] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @BoxAccountID UNIQUEIDENTIFIER ,
  @SafeAccountID UNIQUEIDENTIFIER ,
  @WorkmateBoxAccountID UNIQUEIDENTIFIER ,
  @OpeningDate DATETIME ,
  @ClosingDate DATETIME ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @EventUserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @PriceF NVARCHAR(MAX) = Currencys.f_Format(@CurrencyID, 0) ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(t.Ref), 0) + 1
        FROM ( SELECT MAX(s.Ref) AS Ref
                FROM Company.t_DailyBox AS s
               UNION ALL
               SELECT MAX(s.Ref) AS Ref
                FROM Company.t_ArchiveDailyBox AS s
             ) AS t;

      SET @RefF = FORMAT(@Ref, '0');

    END;

    BEGIN --Insert t_DailyBox

      INSERT INTO Company.t_DailyBox
          ( ID ,
            Ref ,
            RefF ,
            UserID ,
            BoxAccountID ,
            SafeAccountID ,
            WorkmateBoxAccountID ,
            OpeningDate ,
            ClosingDate ,
            CurrencyID ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            OpeningBalanceF ,
            SalesF ,
            CashSalesF ,
            OtherIncomeF ,
            SalesReturnsF ,
            ExpensesF ,
            OtherOutcomeF ,
            FinalBalanceF ,
            SafeAmountF ,
            WorkmateAmountF ,
            KeepWithMeF ,
            DifferenceBalanceF
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @UserID ,
            @BoxAccountID ,
            @SafeAccountID ,
            @WorkmateBoxAccountID ,
            @OpeningDate ,
            @ClosingDate ,
            @CurrencyID ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF ,
            @PriceF
          );

    END;

    BEGIN --Insert t_DailyBoxMoving

      SET @return = -1;

      INSERT INTO Company.t_DailyBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @EventUserID ,
            @ID ,
            @Event + N': ' + @RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
 
    EXECUTE Company.s_DailyBoxLiveVersion;
	
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;



