  @TransactionDetail Transactions.dt_TransactionDetail READONLY ,
  @TransactionDescription NVARCHAR(MAX) ,
  @EventUserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @TransactionLinkType INT = 220 ,
        @return INT = 0;

    END;

    BEGIN --Update t_DailyBox

      UPDATE Company.t_DailyBox
        SET UserID = @UserID ,
            BoxAccountID = @BoxAccountID ,
            SafeAccountID = @SafeAccountID ,
            WorkmateBoxAccountID = @WorkmateBoxAccountID ,
            OpeningDate = @OpeningDate ,
            ClosingDate = @ClosingDate ,
            StatusNow = 1 ,
            CurrencyID = @CurrencyID ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            OpeningBalance = @OpeningBalance ,
            OpeningBalanceF = @OpeningBalanceF ,
            OpeningBalanceD = @OpeningBalanceD ,
            OpeningBalanceLL = @OpeningBalanceLL ,
            OpeningBalanceEuro = @OpeningBalanceEuro ,
