            SalesF = @SalesF ,
            SalesD = @SalesD ,
            SalesLL = @SalesLL ,
            SalesEuro = @SalesEuro ,
            CashSales = @CashSales ,
            CashSalesF = @CashSalesF ,
            CashSalesD = @CashSalesD ,
            CashSalesLL = @CashSalesLL ,
            CashSalesEuro = @CashSalesEuro ,
            OtherIncome = @OtherIncome ,
            OtherIncomeF = @OtherIncomeF ,
            OtherIncomeD = @OtherIncomeD ,
            OtherIncomeLL = @OtherIncomeLL ,
            OtherIncomeEuro = @OtherIncomeEuro ,
            SalesReturns = @SalesReturns ,
            SalesReturnsF = @SalesReturnsF ,
            SalesReturnsD = @SalesReturnsD ,
            SalesReturnsLL = @SalesReturnsLL ,
            SalesReturnsEuro = @SalesReturnsEuro ,
            Expenses = @Expenses ,
            ExpensesF = @ExpensesF ,
            ExpensesD = @ExpensesD ,
            ExpensesLL = @ExpensesLL ,
            ExpensesEuro = @ExpensesEuro ,
            OtherOutcome = @OtherOutcome ,
            OtherOutcomeF = @OtherOutcomeF ,
            OtherOutcomeD = @OtherOutcomeD ,
            OtherOutcomeLL = @OtherOutcomeLL ,
            OtherOutcomeEuro = @OtherOutcomeEuro ,
            FinalBalance = @FinalBalance ,
            FinalBalanceF = @FinalBalanceF ,
            FinalBalanceD = @FinalBalanceD ,
            FinalBalanceLL = @FinalBalanceLL ,
            FinalBalanceEuro = @FinalBalanceEuro ,
            SafeAmount = @SafeAmount ,
            SafeAmountF = @SafeAmountF ,
            SafeAmountD = @SafeAmountD ,
            SafeAmountLL = @SafeAmountLL ,
            SafeAmountEuro = @SafeAmountEuro ,
            WorkmateAmount = @WorkmateAmount ,
            WorkmateAmountF = @WorkmateAmountF ,
            WorkmateAmountD = @WorkmateAmountD ,
            WorkmateAmountLL = @WorkmateAmountLL ,
            WorkmateAmountEuro = @WorkmateAmountEuro ,
            KeepWithMe = @KeepWithMe ,
            KeepWithMeF = @KeepWithMeF ,
            KeepWithMeD = @KeepWithMeD ,
            KeepWithMeLL = @KeepWithMeLL ,
            KeepWithMeEuro = @KeepWithMeEuro ,
            DifferenceBalance = @DifferenceBalance ,
            DifferenceBalanceF = @DifferenceBalanceF ,
            DifferenceBalanceD = @DifferenceBalanceD ,
            DifferenceBalanceLL = @DifferenceBalanceLL ,
            DifferenceBalanceEuro = @DifferenceBalanceEuro ,
            BanknotesLLQtys1000 = @BanknotesLLQtys1000 ,
            BanknotesLLQtys5000 = @BanknotesLLQtys5000 ,
            BanknotesLLQtys10000 = @BanknotesLLQtys10000 ,
            BanknotesLLQtys20000 = @BanknotesLLQtys20000 ,
            BanknotesLLQtys50000 = @BanknotesLLQtys50000 ,
            BanknotesLLQtys100000 = @BanknotesLLQtys100000 ,
            BanknotesLLTotal1000 = @BanknotesLLTotal1000 ,
            BanknotesLLTotal5000 = @BanknotesLLTotal5000 ,
            BanknotesLLTotal10000 = @BanknotesLLTotal10000 ,
            BanknotesLLTotal20000 = @BanknotesLLTotal20000 ,
            BanknotesLLTotal50000 = @BanknotesLLTotal50000 ,
            BanknotesLLTotal100000 = @BanknotesLLTotal100000 ,
            BanknotesLLTotal = @BanknotesLLTotal ,
            BanknotesLLNumbers1000 = @BanknotesLLNumbers1000 ,
            BanknotesLLNumbers5000 = @BanknotesLLNumbers5000 ,
            BanknotesLLNumbers10000 = @BanknotesLLNumbers10000 ,
            BanknotesLLNumbers20000 = @BanknotesLLNumbers20000 ,
            BanknotesLLNumbers50000 = @BanknotesLLNumbers50000 ,
            BanknotesLLNumbers100000 = @BanknotesLLNumbers100000 ,
            BanknotesDollarQtys1 = @BanknotesDollarQtys1 ,
            BanknotesDollarQtys5 = @BanknotesDollarQtys5 ,
            BanknotesDollarQtys10 = @BanknotesDollarQtys10 ,
            BanknotesDollarQtys20 = @BanknotesDollarQtys20 ,
            BanknotesDollarQtys50 = @BanknotesDollarQtys50 ,
            BanknotesDollarQtys100 = @BanknotesDollarQtys100 ,
            BanknotesDollarTotal1 = @BanknotesDollarTotal1 ,
            BanknotesDollarTotal5 = @BanknotesDollarTotal5 ,
            BanknotesDollarTotal10 = @BanknotesDollarTotal10 ,
            BanknotesDollarTotal20 = @BanknotesDollarTotal20 ,
            BanknotesDollarTotal50 = @BanknotesDollarTotal50 ,
            BanknotesDollarTotal100 = @BanknotesDollarTotal100 ,
            BanknotesDollarTotal = @BanknotesDollarTotal ,
            BanknotesDollarNumbers1 = @BanknotesDollarNumbers1 ,
            BanknotesDollarNumbers5 = @BanknotesDollarNumbers5 ,
            BanknotesDollarNumbers10 = @BanknotesDollarNumbers10 ,
            BanknotesDollarNumbers20 = @BanknotesDollarNumbers20 ,
            BanknotesDollarNumbers50 = @BanknotesDollarNumbers50 ,
            BanknotesDollarNumbers100 = @BanknotesDollarNumbers100 ,
            Notes = @Notes ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DailyBoxMoving

      SET @return = -1;

      INSERT INTO Company.t_DailyBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @EventUserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN--Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkID = @ID AND LinkType = @TransactionLinkType;

    END;

    IF EXISTS ( SELECT TOP ( 1 ) s.ID
                  FROM @TransactionDetail AS s )
    BEGIN--Insert t_Transaction
	     
      SET @ClosingDate = DATEADD(SECOND, 1, @ClosingDate);
 
      EXECUTE Transactions.s_TransactionInsertPart @TransactionID, 'JV', 0, @ClosingDate, @EventUserID, @TransactionDescription, @TransactionLinkType, 0, @ID, @ID, @TransactionDetail, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    END;

    EXECUTE Company.s_DailyBoxLiveVersion;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;




