/****** Object:  StoredProcedure [Company].[s_DoctorDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_DoctorDelete]
    @UserID UNIQUEIDENTIFIER ,
    @Event NVARCHAR(MAX) ,
    @EventType TINYINT,
    @ComputerIP NVARCHAR(MAX) ,
    @Computer NVARCHAR(MAX) ,
    @ComputerAccount NVARCHAR(MAX) ,
    @ID UNIQUEIDENTIFIER
AS
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;

            BEGIN --Declare

                DECLARE @Return INT;

            END;

            BEGIN --Delete phones 

                DELETE  FROM Company.t_BookPhone
                WHERE   SectionID = 163
                        AND OwnerID = @ID;

            END;

            BEGIN --Delete SocialMedia 

                DELETE  FROM Company.t_SocialMedia
                WHERE   SectionID = 163
                        AND OwnerID = @ID;

            END;

            BEGIN --Delete

                SET @Return = 0;

                DELETE  FROM Company.t_Doctor
                WHERE   ID = @ID;

            END;

            BEGIN --Insert event

                SET @Return = -1;

                INSERT  INTO Company.t_DoctorMoving
                        ( UserID ,
                          SectionID ,
                          EventIs ,
                          EventType ,
                          ComputerIP ,
                          Computer ,
                          ComputerAccount
                        )
                VALUES  ( @UserID ,
                          @ID ,
                          @Event ,
                          @EventType ,
                          @ComputerIP ,
                          @Computer ,
                          @ComputerAccount
                        );

            END;

            COMMIT TRANSACTION;

            RETURN 1;

        END TRY
        BEGIN CATCH

            ROLLBACK TRANSACTION;

            RETURN @Return;

        END CATCH;

    END;














GO
/****** Object:  StoredProcedure [Company].[s_DoctorExecuteJobAgeIs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_DoctorExecuteJobAgeIs]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 )
                              s.ID
                      FROM    Alls.t_LastExecuteJob AS s
                      WHERE   s.Company_Doctor_AgeIs < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Update 

      UPDATE  Company.t_Doctor
      SET     AgeIs = DateTimes.f_GetAge(Birthday) ,
              IsSync = 0;

    END;

    BEGIN --Execute is done

      UPDATE  Alls.t_LastExecuteJob
      SET     Company_Doctor_AgeIs = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;












