/****** Object:  StoredProcedure [Company].[s_ExpenseInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_ExpenseInsertPART] @PaperRef NVARCHAR(MAX) ,
  @Legal BIT ,
  @LinkedType INT ,
  @LinkID UNIQUEIDENTIFIER ,
  @LinkRef NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @RecurringExpense BIT ,
  @ExpenseTypeID UNIQUEIDENTIFIER ,
  @BoxAccountID UNIQUEIDENTIFIER ,
  @ExpenseAccountID UNIQUEIDENTIFIER ,
  @VendorAccountID UNIQUEIDENTIFIER ,
  @VendorTaxAccountID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @Balance FLOAT ,
  @TaxRate DECIMAL(4, 2) ,
  @TaxValue FLOAT ,
  @NetIs FLOAT ,
  @TransactionDetailTypeIs TINYINT ,
  @ChequeNumber NVARCHAR(MAX) ,
  @ChequeImage IMAGE ,
  @ChequeNote NVARCHAR(MAX) ,
  @ChequeDateGet DATE ,
  @ChequeStopNotificationGet BIT ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER OUTPUT
AS
BEGIN

  BEGIN --Declare

    DECLARE @IDs TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

    DECLARE @Ref BIGINT ,
      @TransactionRef BIGINT ,
      @TransactionID UNIQUEIDENTIFIER ,
      @RowNumber INT ,
      @BoxAccount NVARCHAR(MAX) ,
      @BoxAccountNumberF NVARCHAR(MAX) ,
      @ExpenseAccount NVARCHAR(MAX) ,
      @ExpenseAccountNumberF NVARCHAR(MAX) ,
      @VendorTaxAccount NVARCHAR(MAX) ,
      @Currency NVARCHAR(MAX) ,
      @CurrencyTypeIs INT ,
      @LinkType INT = 8 ,
      @CID UNIQUEIDENTIFIER ,
      @E FLOAT ,
      @ELL FLOAT ,
      @EEuro FLOAT ,
      @V FLOAT ,
      @StatementIs_ NVARCHAR(MAX) ,
      @BalanceD FLOAT ,
      @TaxValueD FLOAT ,
      @NetIsD FLOAT ,
      @return INT;

  END;

  BEGIN --Set info

    SELECT @Ref = COALESCE(MAX(s.Ref), 0) + 1
      FROM Company.t_Expense AS s;

    SET @BoxAccount = Company.f_AccountGetName(@BoxAccountID);

    SET @BoxAccountNumberF = Company.f_AccountGetNumberF(@BoxAccountID);

    SET @ExpenseAccount = Company.f_AccountGetName(@ExpenseAccountID);

    SET @ExpenseAccountNumberF = Company.f_AccountGetNumberF(@ExpenseAccountID);

    SET @VendorTaxAccount = Company.f_AccountGetName(@VendorTaxAccountID);

    SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);

    SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);
    IF @CurrencyTypeIs <> 0
    BEGIN
	                              
      SET @TaxExchangeRateLL = @ExchangeRateLL;
      SET @TaxExchangeRateEuro = @ExchangeRateEuro;

    END;

    SET @CID = @CurrencyID;
    SET @E = @ExchangeRate;
    SET @ELL = @ExchangeRateLL;
    SET @EEuro = @ExchangeRateEuro;

    SET @BalanceD = @Balance / @ExchangeRate;

    SET @TaxValueD = @TaxValue / @ExchangeRate;

    SET @NetIsD = @NetIs / @ExchangeRate;

  END;

  BEGIN --Insert

    SET @return = 0;

    INSERT INTO Company.t_Expense
        ( Ref ,
          RefF ,
          PaperRef ,
          Legal ,
          LinkedType ,
          LinkID ,
          LinkRef ,
          DateIs ,
          DateOnly ,
          DateMonthly ,
          DateYearly ,
          RecurringExpense ,
          ExpenseTypeID ,
          UserID ,
          UserIs ,
          FromAccountID ,
          FromAccount ,
          FromAccountNumberF ,
          ToAccountID ,
          ToAccount ,
          ToAccountNumberF ,
          VendorAccountID ,
          VendorAccount ,
          VendorAccountNumberF ,
          PaymentMethod ,
          CurrencyID ,
          Currency ,
          ExchangeRate ,
          ExchangeRateLL ,
          ExchangeRateEuro ,
          TaxExchangeRateLL ,
          TaxExchangeRateEuro ,
          Balance ,
          BalanceF ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro ,
          TaxRate ,
          TaxRateF ,
          TaxValue ,
          TaxValueF ,
          TaxValueD ,
          TaxValueLL ,
          TaxValueEuro ,
          NetIs ,
          NetIsF ,
          NetIsD ,
          NetIsLL ,
          NetIsEuro ,
          NetIsAR ,
          NetIsEN ,
          DescriptionIs ,
          TypeIs ,
          ChequeNumber ,
          ChequeImage ,
          ChequeImagePath ,
          ChequeNote ,
          ChequeDateGet ,
          ChequeStopNotificationGet
        )
      OUTPUT Inserted.ID
        INTO @IDs ( ID )
      VALUES
        ( @Ref ,
          FORMAT(@Ref, '#') ,
          @PaperRef ,
          @Legal ,
          @LinkedType ,
          @LinkID ,
          @LinkRef ,
          @DateIs ,
          @DateIs ,
          DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
          DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
          @RecurringExpense ,
          @ExpenseTypeID ,
          @UserID ,
          Users.f_UserGetName(@UserID) ,
          @BoxAccountID ,
          @BoxAccount ,
          @BoxAccountNumberF ,
          @ExpenseAccountID ,
          @ExpenseAccount ,
          @ExpenseAccountNumberF ,
          @VendorAccountID ,
          Company.f_AccountGetName(@VendorAccountID) ,
          Company.f_AccountGetNumberF(@VendorAccountID) ,
          @PaymentMethod ,
          @CurrencyID ,
          @Currency ,
          @ExchangeRate ,
          @ExchangeRateLL ,
          @ExchangeRateEuro ,
          @TaxExchangeRateLL ,
          @TaxExchangeRateEuro ,
          @Balance ,
          Currencys.f_Format(@CurrencyID, @Balance) ,
          @BalanceD ,
          @BalanceD * @ExchangeRateLL ,
          @BalanceD * @ExchangeRateEuro ,
          @TaxRate ,
          Currencys.f_FormatRate(@TaxRate) ,
          @TaxValue ,
          Currencys.f_Format(@CurrencyID, @TaxValue) ,
          @TaxValueD ,
          @TaxValueD * @TaxExchangeRateLL ,
          @TaxValueD * @TaxExchangeRateEuro ,
          @NetIs ,
          Currencys.f_Format(@CurrencyID, @NetIs) ,
          @NetIsD ,
          @NetIsD * @ExchangeRateLL ,
          @NetIsD * @ExchangeRateEuro ,
          Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
          Currencys.f_ToWordEN(@NetIs, @CurrencyID, 1) ,
          @DescriptionIs ,
          @TransactionDetailTypeIs ,
          @ChequeNumber ,
          @ChequeImage ,
          '' ,
          @ChequeNote ,
          @ChequeDateGet ,
          @ChequeStopNotificationGet
        );

    SET @ID = ( SELECT TOP ( 1 ) s.ID
                  FROM @IDs AS s
                  ORDER BY s.ID
              );

  END;

  BEGIN --Transaction

    BEGIN --Set info

      SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
        FROM Transactions.t_Transaction AS s
        WHERE s.TypeIs = N'JV';

    END;

    BEGIN --Insert transaction

      SET @return = 0;

      DELETE FROM @IDs;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            TypeIs ,
            DateIs ,
            DescriptionIs ,
            LinkType ,
            LinkID ,
            UserID
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @TransactionRef ,
            N'JV' ,
            @DateIs ,
            REPLACE(@StatementIs, N'{0}', @Ref) ,
            @LinkType ,
            @ID ,
            @UserID
          );

      SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                              FROM @IDs AS s
                              ORDER BY s.ID
                           );

    END;
	  
    BEGIN --Insert detail

      IF @PaymentMethod = 1
      BEGIN
	                            
        SET @BoxAccountID = @VendorAccountID;

      END;

      SET @V = @Balance;
      SET @RowNumber = 1;
      SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @BoxAccount;
      EXECUTE Transactions.s_TransactionDetailInsertDebitFull @RowNumber, @TransactionID, @ExpenseAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_, @TransactionDetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN;
	
      SET @RowNumber = 2;
      SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @ExpenseAccount;
      EXECUTE Transactions.s_TransactionDetailInsertCreditFull @RowNumber, @TransactionID, @BoxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_, @TransactionDetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN;
		
      IF @TaxValue > 0
      BEGIN --Insert detail tax

        SET @V = @TaxValue;
        SET @RowNumber = 3;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @BoxAccount + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
        EXECUTE Transactions.s_TransactionDetailInsertDebitTax @RowNumber, @TransactionID, @VendorTaxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TaxValue, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        SET @RowNumber = 3;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @VendorTaxAccount + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
        EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @BoxAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TaxValue, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
		
      END;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @TransactionID ,
            @Event + CONVERT(NVARCHAR(MAX), @TransactionRef) ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

  END;
	
  BEGIN --Fix t_Transaction

    EXECUTE Transactions.s_TransactionFixPart @TransactionID;

  END;

  SET @return = -1;
  DECLARE @EventFull NVARCHAR(MAX) = @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref);
  EXECUTE Company.s_ExpenseMovingInsertPART @ID, @UserID, @EventFull, 0, @ComputerIP, @Computer, @ComputerAccount;

  EXECUTE Company.s_ExpenseLiveVersion;

END;







GO
/****** Object:  StoredProcedure [Company].[s_ExpenseInsertsPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_ExpenseInsertsPART] @LinkedType INT ,
  @LinkID UNIQUEIDENTIFIER ,
  @LinkRef NVARCHAR(MAX) ,
  @Expenses Company.tt_Expenses READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  IF NOT EXISTS ( SELECT s.ID
                    FROM @Expenses AS s )
  BEGIN

    RETURN;

  END;
                  
  BEGIN --Declare

    DECLARE @DateOnly DateTimes.tt_DateOnly;
 
    DECLARE @ID UNIQUEIDENTIFIER ,
      @PaperRef NVARCHAR(MAX) ,
      @Legal BIT ,
      @DateIs DATETIME ,
      @RecurringExpense BIT ,
      @ExpenseTypeID UNIQUEIDENTIFIER ,
      @BoxAccountID UNIQUEIDENTIFIER ,
      @ExpenseAccountID UNIQUEIDENTIFIER ,
      @VendorAccountID UNIQUEIDENTIFIER ,
      @VendorTaxAccountID UNIQUEIDENTIFIER ,
      @PaymentMethod TINYINT ,
      @CurrencyID UNIQUEIDENTIFIER ,
      @ExchangeRate FLOAT ,
      @ExchangeRateLL FLOAT ,
      @ExchangeRateEuro FLOAT ,
      @TaxExchangeRateLL FLOAT ,
      @TaxExchangeRateEuro FLOAT ,
      @TaxExchangeRateEvent NVARCHAR(MAX) ,
      @Balance FLOAT ,
      @TaxRate DECIMAL(4, 2) ,
      @TaxValue FLOAT ,
      @NetIs FLOAT ,
      @TransactionDetailTypeIs TINYINT ,
      @ChequeNumber NVARCHAR(MAX) ,
      @ChequeImage VARBINARY(MAX) ,
      @ChequeNote NVARCHAR(MAX) ,
      @ChequeDateGet DATE ,
      @ChequeStopNotificationGet BIT ,
      @NotificationTextAR NVARCHAR(MAX) ,
      @NotificationTextEN NVARCHAR(MAX) ,
      @DescriptionIs NVARCHAR(MAX) ,
      @StatementIs NVARCHAR(MAX); 

  END;

  INSERT INTO @DateOnly
      ( DateOnly
      )
    SELECT DISTINCT s.DateIs
      FROM @Expenses AS s;

  DECLARE i CURSOR FORWARD_ONLY
  FOR
  SELECT s.ID
    FROM @Expenses AS s;

  OPEN i;
  FETCH NEXT FROM i
    INTO @ID;
  WHILE @@FETCH_STATUS = 0
  BEGIN
	
    BEGIN --Set info

      SELECT TOP ( 1 ) @PaperRef = s.PaperRef ,
          @Legal = s.Legal ,
          @DateIs = s.DateIs ,
          @RecurringExpense = s.RecurringExpense ,
          @ExpenseTypeID = s.ExpenseTypeID ,
          @BoxAccountID = s.BoxAccountID ,
          @ExpenseAccountID = s.ExpenseAccountID ,
          @VendorAccountID = s.VendorAccountID ,
          @VendorTaxAccountID = s.VendorTaxAccountID ,
          @PaymentMethod = s.PaymentMethod ,
          @CurrencyID = s.CurrencyID ,
          @ExchangeRate = s.ExchangeRate ,
          @ExchangeRateLL = s.ExchangeRateLL ,
          @ExchangeRateEuro = s.ExchangeRateEuro ,
          @TaxExchangeRateLL = s.TaxExchangeRateLL ,
          @TaxExchangeRateEuro = s.TaxExchangeRateEuro ,
          @TaxExchangeRateEvent = s.TaxExchangeRateEvent ,
          @Balance = s.Balance ,
          @TaxRate = s.TaxRate ,
          @TaxValue = s.TaxValue ,
          @NetIs = s.NetIs ,
          @TransactionDetailTypeIs = s.TransactionDetailTypeIs ,
          @ChequeNumber = s.ChequeNumber ,
          @ChequeImage = s.ChequeImage ,
          @ChequeNote = s.ChequeNote ,
          @ChequeDateGet = s.ChequeDateGet ,
          @ChequeStopNotificationGet = s.ChequeStopNotificationGet ,
          @NotificationTextAR = s.NotificationTextAR ,
          @NotificationTextEN = s.NotificationTextEN ,
          @DescriptionIs = s.DescriptionIs ,
          @StatementIs = s.StatementIs
        FROM @Expenses AS s
        WHERE s.ID = @ID;

    END;

    EXECUTE Company.s_ExpenseInsertPART @PaperRef, @Legal, @LinkedType, @LinkID, @LinkRef, @DateIs, @RecurringExpense, @ExpenseTypeID, @BoxAccountID, @ExpenseAccountID, @VendorAccountID, @VendorTaxAccountID, @PaymentMethod, @CurrencyID, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @TaxExchangeRateLL, @TaxExchangeRateEuro, @TaxExchangeRateEvent, @Balance, @TaxRate, @TaxValue, @NetIs, @TransactionDetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN, @DescriptionIs, @StatementIs, @UserID, @Event, @ComputerIP, @Computer, @ComputerAccount, @ID; 
	
    FETCH NEXT FROM i
        INTO @ID;
  END;
  CLOSE i;
  DEALLOCATE i;
  
  EXECUTE Invoices.s_ProfitDaily_Expenses_Updates_PART @DateOnly;

  EXECUTE Company.s_ExpenseLiveVersion;

  RETURN 1;

END;








GO
