/****** Object:  StoredProcedure [Company].[s_ExpenseRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_ExpenseRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Company.t_Expense
        SET UserIs = Users.f_UserGetName(UserID) ,
            FromAccount = Company.f_AccountGetName(FromAccountID) ,
            ToAccount = Company.f_AccountGetName(ToAccountID) ,
            VendorAccount = Company.f_AccountGetName(VendorAccountID) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
            TaxRateF = Currencys.f_FormatRate(TaxRate) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            RowVersionID = DateTimes.f_GetRowVersionID();

    END;

    SET @Return = -1;
    EXECUTE Company.s_ExpenseMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Company.s_ExpenseLiveVersion;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









