    SET @Return = -1;
    EXECUTE Company.s_ExpensesTypesMovingInsert @UserID, @EventIs, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID; 

    EXECUTE Alls.s_FireStoreRowsForDeleteInsertPART @ID, 1, 'expensesTypes'; 

    EXECUTE Company.s_ExpensesTypesLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










