SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_ExpensesTypesMovingTruncate] @UserID UNIQUEIDENTIFIER ,
  @EventIs NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete

      TRUNCATE TABLE Company.t_ExpensesTypesMoving;

    END;

    SET @Return = -1;
    EXECUTE Company.s_ExpensesTypesMovingInsert @UserID, @EventIs, 4, @ComputerIP, @Computer, @ComputerAccount, '00000000-0000-0000-0000-000000000000'; 

    EXECUTE Company.s_ExpensesTypesLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

