/****** Object:  StoredProcedure [Company].[s_ExpenseUpdatesLinkedType]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_ExpenseUpdatesLinkedType] @IDs Alls.tt_Guid READONLY ,
  @LinkedType TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @LinkRef BIGINT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    BEGIN --Update

      UPDATE Company.t_Expense
        SET LinkedType = @LinkedType ,
            LinkID = @LinkID ,
            LinkRef = @LinkRef ,
            RowVersionID = DateTimes.f_GetRowVersionID()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Expense.ID );

    END;

    SET @return = -1;
    EXECUTE Company.s_ExpenseMovingInsertsPART @IDs, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Company.s_ExpenseLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;


