/****** Object:  StoredProcedure [Company].[s_FileStorageLinkedDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_FileStorageLinkedDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --DECLARE

      DECLARE @OwnerID UNIQUEIDENTIFIER ,
        @SectionID INT ,
        @FileStorageID UNIQUEIDENTIFIER ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OwnerID = s.OwnerID ,
          @SectionID = s.SectionID ,
          @FileStorageID = s.FileStorageID
        FROM Company.t_FileStorageLinked AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;


    END;

    BEGIN --Update

      SET @Return = -6;

      DELETE FROM Company.t_FileStorageLinked
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      IF @SectionID = 33
      BEGIN

        UPDATE Company.t_FileStorage
          SET LinkEmployeeC -= 1
          WHERE ID = @FileStorageID;

        UPDATE Employees.t_Employee
          SET FileStorageC -= 1
          WHERE ID = @OwnerID;

        INSERT INTO Employees.t_EmployeeMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          VALUES
            ( @UserID ,
              @OwnerID ,
              @Event ,
              1 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            );

      END;
      ELSE
        IF @SectionID = 149
        BEGIN

          UPDATE Company.t_FileStorage
            SET LinkSalesPersonC -= 1
            WHERE ID = @FileStorageID;

          UPDATE Employees.t_SalesPerson
            SET FileStorageC -= 1
            WHERE ID = @OwnerID;

          INSERT INTO Employees.t_SalesPersonMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
            VALUES
              ( @UserID ,
                @OwnerID ,
                @Event ,
                1 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

        END;
        ELSE
          IF @SectionID = 15
          BEGIN

            UPDATE Company.t_FileStorage
              SET LinkCustomerC -= 1
              WHERE ID = @FileStorageID;

            UPDATE Customers.t_Customer
              SET FileStorageC -= 1
              WHERE ID = @OwnerID;

            SET @Return = -1;
            EXECUTE Customers.s_CustomerMovingInsertPART @UserID, @Event, 1, @ComputerIP, @Computer, @ComputerAccount, @OwnerID;

          END;
          ELSE
            IF @SectionID = 10
            BEGIN

              UPDATE Company.t_FileStorage
                SET LinkItemC -= 1
                WHERE ID = @FileStorageID;

              UPDATE Items.t_ItemShared
                SET FileStorageC -= 1
                WHERE ID = @OwnerID;

              INSERT INTO Items.t_ItemSharedMoving
                  ( UserID ,
                    SectionID ,
                    EventIs ,
                    EventType ,
                    ComputerIP ,
                    Computer ,
                    ComputerAccount
                  )
                VALUES
                  ( @UserID ,
                    @OwnerID ,
                    @Event ,
                    1 ,
                    @ComputerIP ,
                    @Computer ,
                    @ComputerAccount
                  );

            END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











