/****** Object:  StoredProcedure [Company].[s_ItemSharedCostCalculationByMaterial]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_ItemSharedCostCalculationByMaterial] @ItemSharedID UNIQUEIDENTIFIER
AS
BEGIN
   	
  DECLARE @ItemSharedIDs AS Alls.tt_Guid;
	  	
  INSERT INTO @ItemSharedIDs
      ( ID )
    VALUES ( @ItemSharedID );

  EXECUTE Company.s_ItemSharedCostCalculationByMaterials @ItemSharedIDs; 
		
END;





GO
/****** Object:  StoredProcedure [Company].[s_ItemSharedCostCalculationByMaterials]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_ItemSharedCostCalculationByMaterials] @ItemSharedIDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY

    IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM Items.t_ItemSharedMaterial AS s
                      WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                      FROM @ItemSharedIDs AS ss
                                      WHERE ss.ID = s.ItemSharedID ) )
    BEGIN
				      
      RETURN;

    END;

    BEGIN --DECLARE
      	  
      DECLARE @ID UNIQUEIDENTIFIER;

      DECLARE @ItemSharedIDs_ AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );
	  	  
      DECLARE @ItemSharedFatherIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

    END;

    BEGIN --Set Info
      
      INSERT @ItemSharedIDs_
          ( ID
          )
        SELECT s.ID
          FROM @ItemSharedIDs AS s;

      INSERT @ItemSharedFatherIDs
          ( ID
          )
        SELECT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                          FROM @ItemSharedIDs_ AS ss
                          WHERE ss.ID = s.ItemSharedID );

    END;

    BEGIN
  
      WHILE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @ItemSharedFatherIDs AS s )
      BEGIN
                                             
        UPDATE Items.t_ItemShared
          SET Purchase = Items.f_ItemSharedMaterial_GetCost(ID)
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ItemSharedFatherIDs AS s
                          WHERE s.ID = t_ItemShared.ID );

        UPDATE Items.t_ItemShared
          SET PurchaseF = Currencys.f_Format(CurrencyID, Purchase) ,
              PurchaseD = Purchase / Currencys.f_CurrencyGetExchangeRate(CurrencyID) ,
              PurchaseLL = Currencys.f_ExchangeToLL(CurrencyID, Purchase, Purchase / Currencys.f_CurrencyGetExchangeRate(CurrencyID)) ,
              PurchaseEuro = Currencys.f_ExchangeToEuro(CurrencyID, Purchase, Purchase / Currencys.f_CurrencyGetExchangeRate(CurrencyID)) ,
              PurchaseWithTax = Calculation.Rate(Purchase, TaxRate)
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ItemSharedFatherIDs AS s
                          WHERE s.ID = t_ItemShared.ID );

        UPDATE Items.t_ItemShared
          SET PurchaseWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax) ,
              PurchaseWithTaxD = PurchaseWithTax / Currencys.f_CurrencyGetExchangeRate(CurrencyID) ,
              PurchaseWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, PurchaseWithTax, PurchaseWithTax / Currencys.f_CurrencyGetExchangeRate(CurrencyID)) ,
              PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, PurchaseWithTax, PurchaseWithTax / Currencys.f_CurrencyGetExchangeRate(CurrencyID)) ,
              @ID = ID
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ItemSharedFatherIDs AS s
                          WHERE s.ID = t_ItemShared.ID );
  
        BEGIN --Delete ID
		
          DELETE FROM @ItemSharedFatherIDs
            WHERE ID = @ID;

        END;
                          
      END;

    END;
  
  END TRY
  BEGIN CATCH
  
  END CATCH;

END;






GO
