CREATE PROCEDURE [Company].[s_MailRecipientsUpdates_SalesInvoiceReceiver] @IDs Alls.tt_IDAndEvent READONLY ,
  @SalesInvoiceReceiver BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;
	
    BEGIN --Insert

      MERGE Company.t_MailRecipients AS t
      USING @IDs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.SalesInvoiceReceiver = @SalesInvoiceReceiver;

    END;

    SET @Return = -1;
    EXECUTE Company.s_MailRecipientsMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Company.s_MailRecipientsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;




