    WHERE FunctionName = N'Live_Tick' AND DateCreated <= GETDATE() - 1;
 
  DELETE FROM Company.t_MailReportsServiceLogs
    WHERE FunctionName = N'InitializedData' AND DateCreated <= GETDATE() - 2;	

