/****** Object:  StoredProcedure [Company].[s_MailSendingSchedulesEndlessJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Company].[s_MailSendingSchedulesEndlessJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Company_MailSendingSchedules_Endless < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    EXECUTE Company.s_MailSendingSchedulesCheckEndlessPART;
    EXECUTE Company.s_MailReportsServiceLogsJobPART;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Company_MailSendingSchedules_Endless = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;










GO
