GO



CREATE PROCEDURE [Company].[s_MailSendingSchedulesInsert] @ID UNIQUEIDENTIFIER ,
  @SubjectText NVARCHAR(MAX) ,
  @MessageText NVARCHAR(MAX) ,
  @MailSendersID UNIQUEIDENTIFIER ,
  @StartsFrom DATETIME ,
  @RepeatEvery INT ,
  @RepeatType TINYINT ,
  @NextAppointment DATETIME ,
  @EndsIn DATETIME ,
  @Endless BIT ,
  @MailRecipientsNames NVARCHAR(MAX) ,
  @MailRecipientsCount INT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @MailSendingSchedulesRecipients Company.tt_MailSendingSchedulesRecipients READONLY ,
  @MailSendingSchedulesReports Company.tt_MailSendingSchedulesReports READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT = Company.f_MailSendingSchedulesGetNewRef() ,
        @RefF NVARCHAR(MAX) ,
        @Return INT  = 0;

    END;

    BEGIN --Set
 
      SET @RefF = FORMAT(@Ref, '#');   

    END;	

    BEGIN --Insert

      INSERT INTO Company.t_MailSendingSchedules
          ( ID ,
            Ref ,
            RefF ,
            SubjectText ,
            MessageText ,
            MailSendersID ,
            StartsFrom ,
            RepeatEvery ,
            RepeatType ,
            NextAppointment ,
            EndsIn ,
            Endless ,
            MailRecipientsNames ,
            MailRecipientsCount ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @SubjectText ,
            @MessageText ,
            @MailSendersID ,
            @StartsFrom ,
            @RepeatEvery ,
            @RepeatType ,
            @NextAppointment ,
            @EndsIn ,
            @Endless ,
            @MailRecipientsNames ,
            @MailRecipientsCount ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert t_MailSendingSchedulesRecipients

      INSERT INTO Company.t_MailSendingSchedulesRecipients
          ( ID ,
            MailSendingSchedulesID ,
            MailRecipientsID 
          )
        SELECT s.ID ,
            s.MailSendingSchedulesID ,
            s.MailRecipientsID
          FROM @MailSendingSchedulesRecipients AS s;

    END;
 
    BEGIN --Insert t_MailSendingSchedulesReports

      INSERT INTO Company.t_MailSendingSchedulesReports
          ( ID ,
            MailSendingSchedulesID ,
            ReportType ,
            ReportSettings 
          )
        SELECT s.ID ,
            s.MailSendingSchedulesID ,
            s.ReportType ,
            s.ReportSettings
          FROM @MailSendingSchedulesReports AS s;

    END;

    SET @Return = -1;
    EXECUTE Company.s_MailSendingSchedulesMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Company.s_MailSendingSchedulesLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;





GO
