CREATE PROCEDURE [Company].[s_MailSendingSchedulesTransmissionLogsInsert] @ID UNIQUEIDENTIFIER ,
  @MailSendingSchedulesID UNIQUEIDENTIFIER ,
  @TransmissionType TINYINT ,
  @StatusType TINYINT ,
  @DateIs DATETIME ,
  @FailureReason NVARCHAR(MAX) ,
  @NextAppointment DATETIME ,
