    END;

    BEGIN --Insert

      INSERT INTO Company.t_MailSendingSchedulesTransmissionLogs
          ( ID ,
            MailSendingSchedulesID ,
            TransmissionType ,
            StatusType ,
            DateIs ,
            FailureReason
          )
        VALUES
          ( @ID ,
            @MailSendingSchedulesID ,
            @TransmissionType ,
            @StatusType ,
            @DateIs ,
            @FailureReason
          );

    END;

    IF @TransmissionType = 1 AND @StatusType = 0
    BEGIN --Update t_MailSendingSchedules

      UPDATE Company.t_MailSendingSchedules
        SET NextAppointment = @NextAppointment
        WHERE ID = @MailSendingSchedulesID;
   
      EXECUTE Company.s_MailSendingSchedulesCheckEndlessPART;

    END;

    SET @Return = -1;
    EXECUTE Company.s_MailSendingSchedulesMovingInsertPART @MailSendingSchedulesID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

