  @Endless BIT ,
  @MailRecipientsNames NVARCHAR(MAX) ,
  @MailRecipientsCount INT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @MailSendingSchedulesRecipients Company.tt_MailSendingSchedulesRecipients READONLY ,
  @MailSendingSchedulesReports Company.tt_MailSendingSchedulesReports READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;

    BEGIN --Update

      UPDATE Company.t_MailSendingSchedules
        SET SubjectText = @SubjectText ,
            MessageText = @MessageText ,
            MailSendersID = @MailSendersID ,
            StartsFrom = @StartsFrom ,
            RepeatEvery = @RepeatEvery ,
            RepeatType = @RepeatType ,
            NextAppointment = @NextAppointment ,
            EndsIn = @EndsIn ,
            Endless = @Endless ,
            StatusType = 0 ,
            MailRecipientsNames = @MailRecipientsNames ,
            MailRecipientsCount = @MailRecipientsCount ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_MailSendingSchedulesRecipients

      DELETE FROM Company.t_MailSendingSchedulesRecipients
        WHERE MailSendingSchedulesID = @ID;

    END;

    BEGIN --Insert t_MailSendingSchedulesRecipients

      INSERT INTO Company.t_MailSendingSchedulesRecipients
          ( ID ,
            MailSendingSchedulesID ,
            MailRecipientsID 
          )
        SELECT s.ID ,
            s.MailSendingSchedulesID ,
            s.MailRecipientsID
          FROM @MailSendingSchedulesRecipients AS s;

    END;
  
    BEGIN --Merge t_MailSendingSchedulesReports

      MERGE Company.t_MailSendingSchedulesReports AS t
      USING @MailSendingSchedulesReports AS s
      ON s.ID = t.ID AND t.MailSendingSchedulesID = @ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 MailSendingSchedulesID ,
                 ReportType ,
                 ReportSettings 
               )
        VALUES ( s.ID ,
                 s.MailSendingSchedulesID ,
                 s.ReportType ,
                 s.ReportSettings
               )
      WHEN MATCHED THEN
        UPDATE SET t.ReportSettings = s.ReportSettings
      WHEN NOT MATCHED BY SOURCE AND t.MailSendingSchedulesID = @ID THEN
        DELETE;

    END;

    EXECUTE Company.s_MailSendingSchedulesCheckEndlessPART;

    SET @Return = -1;
    EXECUTE Company.s_MailSendingSchedulesMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Company.s_MailSendingSchedulesLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;






