SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_MoneyExchangeDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly DATE ,
        @Return INT = 0;

    END;

    BEGIN
    
      SELECT TOP ( 1 ) @DateOnly = s.DateOnly
        FROM Company.t_MoneyExchange AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Company.t_MoneyExchange
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 213 AND LinkID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_MoneyExchangeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'moneyExchange' );

    END;

    EXECUTE [Company].s_MoneyExchangeSummaryRebuildingStatisticsPART @DateOnly;
   
    EXECUTE [Company].[s_MoneyExchangeLiveVersion];
  
    EXECUTE Invoices.s_ProfitDaily_MoneyExchang_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




