/****** Object:  StoredProcedure [Company].[s_MoneyExchangeInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_MoneyExchangeInsert] @OriginSection TINYINT ,
  @OriginID UNIQUEIDENTIFIER ,
  @OriginRef BIGINT ,
  @DateIs DATETIME ,
  @TypeIs TINYINT ,
  @FromAccountID UNIQUEIDENTIFIER ,
  @FromAccount NVARCHAR(MAX) ,
  @FromAccountNumberF NVARCHAR(MAX) ,
  @ToAccountID UNIQUEIDENTIFIER ,
  @ToAccount NVARCHAR(MAX) ,
  @ToAccountNumberF NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Balance FLOAT ,
  @BalanceF NVARCHAR(MAX) ,
  @BalanceD FLOAT ,
  @BalanceLL FLOAT ,
  @BalanceEuro FLOAT ,
  @ExpectedProfit FLOAT ,
  @ExpectedProfitF NVARCHAR(MAX) ,
  @ExpectedProfitD FLOAT ,
  @ExpectedProfitLL FLOAT ,
  @ExpectedProfitEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @CreateByUserID UNIQUEIDENTIFIER ,
  @CreateByUser NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @TransactionRef BIGINT ,
        @Ref BIGINT ,
        @DateOnly DATE = @DateIs ,
        @BalanceAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Balance, @CurrencyID, 1) ,
        @BalanceEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Balance, @CurrencyID, 1) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

    END;

    BEGIN --Set Info

      SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
        FROM Transactions.t_Transaction AS s
        WHERE s.TypeIs = 'JV';

      SELECT @Ref = COALESCE(MAX(s.Ref), 0) + 1
        FROM Company.t_MoneyExchange AS s;

      SET @BaseStatement = N'M.Ex: ' + FORMAT(@Ref, '#') + N' ' + @DescriptionIs;

    END;

    BEGIN --Insert

      INSERT INTO Company.t_MoneyExchange
          ( ID ,
            TransactionID ,
            TransactionRef ,
            Ref ,
            RefF ,
            OriginSection ,
            OriginID ,
            OriginRef ,
            DateIs ,
            DateOnly ,
            TypeIs ,
            FromAccountID ,
            FromAccount ,
            FromAccountNumberF ,
            ToAccountID ,
            ToAccount ,
            ToAccountNumberF ,
            CurrencyID ,
            Currency ,
            CurrencyType ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Balance ,
            BalanceF ,
            BalanceD ,
            BalanceLL ,
            BalanceEuro ,
            BalanceAR ,
            BalanceEN ,
            ExpectedProfit ,
            ExpectedProfitF ,
            ExpectedProfitD ,
            ExpectedProfitLL ,
            ExpectedProfitEuro ,
            DescriptionIs ,
            CreateByUserID ,
            CreateByUser
          )
        VALUES
          ( @ID ,
            @TransactionID ,
            @TransactionRef ,
            @Ref ,
            FORMAT(@Ref, '0') ,
            @OriginSection ,
            @OriginID ,
            @OriginRef ,
            @DateIs ,
            @DateIs ,
            @TypeIs ,
            @FromAccountID ,
            @FromAccount ,
            @FromAccountNumberF ,
            @ToAccountID ,
            @ToAccount ,
            @ToAccountNumberF ,
            @CurrencyID ,
            @Currency ,
            @CurrencyType ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Balance ,
            @BalanceF ,
            @BalanceD ,
            @BalanceLL ,
            @BalanceEuro ,
            @BalanceAR ,
            @BalanceEN ,
            @ExpectedProfit ,
            @ExpectedProfitF ,
            @ExpectedProfitD ,
            @ExpectedProfitLL ,
            @ExpectedProfitEuro ,
            @DescriptionIs ,
            @CreateByUserID ,
            @CreateByUser
          );

    END;

    BEGIN --Insert t_MoneyExchangeMoving

      SET @return = -1;

      INSERT INTO Company.t_MoneyExchangeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @CreateByUserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, '#') ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    BEGIN --Insert t_Transaction
  
      INSERT INTO Transactions.t_Transaction
          ( ID ,
            Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        VALUES
          ( @TransactionID ,
            @TransactionRef ,
            FORMAT(@TransactionRef, '0') ,
            'JV' ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @CreateByUserID ,
            @CreateByUser ,
            @BaseStatement ,
            213 ,
            @ID ,
            @FromAccount + ', ' + @ToAccount ,
            2
          );

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @ToAccountID, @ToAccount, @DateIs, @DateIs, DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1), DATEFROMPARTS(YEAR(@DateIs), 1, 1), @CurrencyID, @Currency, @CurrencyType, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @Balance, @BalanceF, @BalanceD, @BalanceLL, @BalanceEuro, @BalanceAR, @BalanceEN, 0, 0, 0, 0, @Balance, @BalanceD, @BalanceLL, @BalanceEuro, @BaseStatement + ' \ ' + @FromAccount ),
                ( 2, @TransactionID, @FromAccountID, @FromAccount, @DateIs, @DateIs, DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1), DATEFROMPARTS(YEAR(@DateIs), 1, 1), @CurrencyID, @Currency, @CurrencyType, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, 0 - @Balance, @BalanceF, 0 - @BalanceD, 0 - @BalanceLL, 0 - @BalanceEuro, @BalanceAR, @BalanceEN, @Balance, @BalanceD, @BalanceLL, @BalanceEuro, 0, 0, 0, 0, @BaseStatement + ' \ ' + @ToAccount );

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @FromAccountID, @ToAccountID ) AND StatusIs = 1;

    END;

    EXECUTE [Company].s_MoneyExchangeSummaryRebuildingStatisticsPART @DateIs;
 
    EXECUTE [Company].[s_MoneyExchangeLiveVersion];

    EXECUTE Invoices.s_ProfitDaily_MoneyExchang_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;













