GO

CREATE PROCEDURE [Company].[s_MoneyExchangeRebuildingStatistics] @RebuildColumn NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding statistics

      IF @RebuildColumn = 'All'
      BEGIN

        UPDATE Company.t_MoneyExchange
          SET FromAccount = Company.f_AccountGetName(FromAccountID) ,
              ToAccount = Company.f_AccountGetName(ToAccountID) ,
              Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
              BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
              BalanceAR = Currencys.f_ToWordAR(Balance, CurrencyID, 1) ,
              BalanceEN = Currencys.f_ToWordEN(Balance, CurrencyID, 1) ,
              ExpectedProfitF = Currencys.f_Format(CurrencyID, ExpectedProfit) ,
              CreateByUser = Users.f_UserGetName(CreateByUserID) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_MoneyExchange.ID );

      END;
      ELSE
        IF @RebuildColumn = 'From Account'
        BEGIN

          UPDATE Company.t_MoneyExchange
            SET FromAccount = Company.f_AccountGetName(FromAccountID) ,
                IsSync = 0
            WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                            FROM @IDs AS s
                            WHERE s.ID = t_MoneyExchange.ID );

        END;
        ELSE
          IF @RebuildColumn = 'To Account'
          BEGIN

            UPDATE Company.t_MoneyExchange
              SET ToAccount = Company.f_AccountGetName(ToAccountID) ,
                  IsSync = 0
              WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                              FROM @IDs AS s
                              WHERE s.ID = t_MoneyExchange.ID );

          END;
          ELSE
            IF @RebuildColumn = 'Currency and Balance'
            BEGIN

              UPDATE Company.t_MoneyExchange
                SET Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
                    BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
                    BalanceAR = Currencys.f_ToWordAR(Balance, CurrencyID, 1) ,
                    BalanceEN = Currencys.f_ToWordEN(Balance, CurrencyID, 1) ,
                    ExpectedProfitF = Currencys.f_Format(CurrencyID, ExpectedProfit) ,
                    IsSync = 0
                WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                WHERE s.ID = t_MoneyExchange.ID );

            END;
            ELSE
              IF @RebuildColumn = 'Create by User'
              BEGIN

                UPDATE Company.t_MoneyExchange
                  SET CreateByUser = Users.f_UserGetName(CreateByUserID) ,
                      IsSync = 0
                  WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  WHERE s.ID = t_MoneyExchange.ID );

              END;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_MoneyExchangeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;
 
    EXECUTE [Company].[s_MoneyExchangeLiveVersion];

    COMMIT TRAN;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









