/****** Object:  StoredProcedure [Company].[s_MoneyExchangeSummaryRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Company].[s_MoneyExchangeSummaryRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Summary AS TABLE
        (
          DateOnly DATE NOT NULL ,
          TotalCount INT NOT NULL ,
          TotalCountBuy INT NOT NULL ,
          TotalCountSell INT NOT NULL ,
          TotalBuyD FLOAT NOT NULL ,
          TotalBuyLL FLOAT NOT NULL ,
          AverageExchangeRateBuy FLOAT NOT NULL ,
          TotalSellD FLOAT NOT NULL ,
          TotalSellLL FLOAT NOT NULL ,
          AverageExchangeRateSell FLOAT NOT NULL
        );
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Set
    	 	
      INSERT INTO @Summary
          ( DateOnly ,
            TotalCount ,
            TotalCountBuy ,
            TotalCountSell ,
            TotalBuyD ,
            TotalBuyLL ,
            AverageExchangeRateBuy ,
            TotalSellD ,
            TotalSellLL ,
            AverageExchangeRateSell
          )
        SELECT t.DateOnly ,
            COUNT(*) ,
            Company.f_MoneyExchangeGetTotalCountBuy(t.DateOnly) ,
            Company.f_MoneyExchangeGetTotalCountSell(t.DateOnly) ,
            Company.f_MoneyExchangeGetTotalBuyD(t.DateOnly) ,
            Company.f_MoneyExchangeGetTotalBuyLL(t.DateOnly) ,
            Company.f_MoneyExchangeGetAverageExchangeRateBuy(t.DateOnly) ,
            Company.f_MoneyExchangeGetTotalSellD(t.DateOnly) ,
            Company.f_MoneyExchangeGetTotalSellLL(t.DateOnly) ,
            Company.f_MoneyExchangeGetAverageExchangeRateSell(t.DateOnly)
          FROM Company.t_MoneyExchange AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID )
          GROUP BY t.DateOnly;

    END;

    BEGIN --Update

      UPDATE Company.t_MoneyExchangeSummary
        SET TotalCount = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_MoneyExchangeSummary.ID );

    END;

    BEGIN --Rebuilding statistics

      MERGE Company.t_MoneyExchangeSummary AS t
      USING @Summary AS s
      ON s.DateOnly = t.DateOnly
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 DateOnly ,
                 DateMonth ,
                 DateYear ,
                 TotalCount ,
                 TotalCountBuy ,
                 TotalCountSell ,
                 TotalBuyD ,
                 TotalBuyLL ,
                 AverageExchangeRateBuy ,
                 TotalSellD ,
                 TotalSellLL ,
                 AverageExchangeRateSell
               )
        VALUES ( FORMAT(s.DateOnly, N'yyyyMMdd-0000-0000-0000-000000000000') ,
                 s.DateOnly ,
                 DATEFROMPARTS(YEAR(s.DateOnly), MONTH(s.DateOnly), 1) ,
                 DATEFROMPARTS(YEAR(s.DateOnly), 1, 1) ,
                 s.TotalCount ,
                 s.TotalCountBuy ,
                 s.TotalCountSell ,
                 s.TotalBuyD ,
                 s.TotalBuyLL ,
                 s.AverageExchangeRateBuy ,
                 s.TotalSellD ,
                 s.TotalSellLL ,
                 s.AverageExchangeRateSell
               )
      WHEN MATCHED THEN
        UPDATE SET t.TotalCount = s.TotalCount ,
                    t.TotalCountBuy = s.TotalCountBuy ,
                    t.TotalCountSell = s.TotalCountSell ,
                    t.TotalBuyD = s.TotalBuyD ,
                    t.TotalBuyLL = s.TotalBuyLL ,
                    t.AverageExchangeRateBuy = s.AverageExchangeRateBuy ,
                    t.TotalSellD = s.TotalSellD ,
                    t.TotalSellLL = s.TotalSellLL ,
                    t.AverageExchangeRateSell = s.AverageExchangeRateSell ,
                    t.IsSync = 0;

      UPDATE Company.t_MoneyExchangeSummary
        SET ProfitD = IIF(TotalBuyD > TotalSellD, TotalSellD - ( TotalSellD * AverageExchangeRateBuy / IIF(AverageExchangeRateSell > 0, AverageExchangeRateSell, 1)), TotalBuyD - ( TotalBuyD * AverageExchangeRateBuy / IIF(AverageExchangeRateSell > 0, AverageExchangeRateSell, 1)))
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_MoneyExchangeSummary.ID );
   
      UPDATE Company.t_MoneyExchangeSummary
        SET ProfitLL = ProfitD * AverageExchangeRateSell ,
            ProfitEuro = ProfitD * Currencys.f_CurrencyGetExchangeRateEuro()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_MoneyExchangeSummary.ID );
   
      UPDATE Company.t_MoneyExchangeSummary
        SET TotalBuyDF = Currencys.f_FormatD(TotalBuyD) ,
            TotalBuyLLF = Currencys.f_FormatLL(TotalBuyLL) ,
            TotalSellDF = Currencys.f_FormatD(TotalSellD) ,
            TotalSellLLF = Currencys.f_FormatLL(TotalSellLL) ,
            ProfitDF = Currencys.f_FormatD(ProfitD) ,
            ProfitLLF = Currencys.f_FormatLL(ProfitLL) ,
            ProfitEuroF = Currencys.f_FormatEuro(ProfitEuro)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_MoneyExchangeSummary.ID );

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Company.t_MoneyExchangeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;
 
    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            0 ,
            'moneyExchangeSummary'
          FROM Company.t_MoneyExchangeSummary AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = s.ID ) AND t.TotalCount <= 0;

    END;

    BEGIN
     
      DELETE FROM Company.t_MoneyExchangeSummary
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_MoneyExchangeSummary.ID ) AND TotalCount <= 0;

    END;

    EXEC Invoices.s_ProfitDaily_MoneyExchange_UpdateAll_PART; 

    EXECUTE [Company].[s_MoneyExchangeLiveVersion];

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










GO
