/****** Object:  StoredProcedure [Company].[s_MoneyExchangeUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_MoneyExchangeUpdate] @DateIs DATETIME ,
  @TypeIs TINYINT ,
  @FromAccountID UNIQUEIDENTIFIER ,
  @FromAccount NVARCHAR(MAX) ,
  @FromAccountNumberF NVARCHAR(MAX) ,
  @ToAccountID UNIQUEIDENTIFIER ,
  @ToAccount NVARCHAR(MAX) ,
  @ToAccountNumberF NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Balance FLOAT ,
  @BalanceF NVARCHAR(MAX) ,
  @BalanceD FLOAT ,
  @BalanceLL FLOAT ,
  @BalanceEuro FLOAT ,
  @ExpectedProfit FLOAT ,
  @ExpectedProfitF NVARCHAR(MAX) ,
  @ExpectedProfitD FLOAT ,
  @ExpectedProfitLL FLOAT ,
  @ExpectedProfitEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @CreateByUserID UNIQUEIDENTIFIER ,
  @CreateByUser NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @RefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @DateOnly_OLD DATE ,
        @BalanceAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Balance, @CurrencyID, 1) ,
        @BalanceEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Balance, @CurrencyID, 1) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

    END;

    BEGIN --Set Info

      SELECT TOP ( 1 ) @RefF = s.RefF ,
          @DateOnly_OLD = s.DateOnly
        FROM Company.t_MoneyExchange AS s
        WHERE s.ID = @ID;

      SET @BaseStatement = N'M.Ex: ' + @RefF + N' ' + @DescriptionIs;

    END;

    BEGIN --Update

      UPDATE Company.t_MoneyExchange
        SET DateIs = @DateIs ,
            DateOnly = @DateIs ,
            TypeIs = @TypeIs ,
            FromAccountID = @FromAccountID ,
            FromAccount = @FromAccount ,
            FromAccountNumberF = @FromAccountNumberF ,
            ToAccountID = @ToAccountID ,
            ToAccount = @ToAccount ,
            ToAccountNumberF = @ToAccountNumberF ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            CurrencyType = @CurrencyType ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Balance = @Balance ,
            BalanceF = @BalanceF ,
            BalanceD = @BalanceD ,
            BalanceLL = @BalanceLL ,
            BalanceEuro = @BalanceEuro ,
            BalanceAR = @BalanceAR ,
            BalanceEN = @BalanceEN ,
            ExpectedProfit = @ExpectedProfit ,
            ExpectedProfitF = @ExpectedProfitF ,
            ExpectedProfitD = @ExpectedProfitD ,
            ExpectedProfitLL = @ExpectedProfitLL ,
            ExpectedProfitEuro = @ExpectedProfitEuro ,
            DescriptionIs = @DescriptionIs ,
            CreateByUserID = @CreateByUserID ,
            CreateByUser = @CreateByUser ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_MoneyExchangeMoving

      SET @return = -1;

      INSERT INTO Company.t_MoneyExchangeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @CreateByUserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    BEGIN --t_Transaction
  
      UPDATE Transactions.t_Transaction
        SET DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateFirstDayInMonth = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateFirstDayInYear = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            UserID = @CreateByUserID ,
            UserIs = @CreateByUser ,
            DescriptionIs = @BaseStatement ,
            AccountsNames = @FromAccount + ', ' + @ToAccount ,
            IsSync = 0
        WHERE ID = @TransactionID;

      DELETE FROM Transactions.t_TransactionDetail
        WHERE TransactionID = @TransactionID;
   
      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @ToAccountID, @ToAccount, @DateIs, @DateIs, DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1), DATEFROMPARTS(YEAR(@DateIs), 1, 1), @CurrencyID, @Currency, @CurrencyType, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @Balance, @BalanceF, @BalanceD, @BalanceLL, @BalanceEuro, @BalanceAR, @BalanceEN, 0, 0, 0, 0, @Balance, @BalanceD, @BalanceLL, @BalanceEuro, @BaseStatement + ' \ ' + @FromAccount ),
                ( 2, @TransactionID, @FromAccountID, @FromAccount, @DateIs, @DateIs, DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1), DATEFROMPARTS(YEAR(@DateIs), 1, 1), @CurrencyID, @Currency, @CurrencyType, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, 0 - @Balance, @BalanceF, 0 - @BalanceD, 0 - @BalanceLL, 0 - @BalanceEuro, @BalanceAR, @BalanceEN, @Balance, @BalanceD, @BalanceLL, @BalanceEuro, 0, 0, 0, 0, @BaseStatement + ' \ ' + @ToAccount );

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @FromAccountID, @ToAccountID ) AND StatusIs = 1;

    END;
 
    EXECUTE [Company].s_MoneyExchangeSummaryRebuildingStatisticsPART @DateOnly_OLD;
    EXECUTE [Company].s_MoneyExchangeSummaryRebuildingStatisticsPART @DateIs;
    EXECUTE [Company].[s_MoneyExchangeLiveVersion];

    IF @DateOnly_OLD = @DateOnly
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_MoneyExchang_Update_PART @DateOnly;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_MoneyExchang_Update_PART @DateOnly_OLD;
      EXECUTE Invoices.s_ProfitDaily_MoneyExchang_Update_PART @DateOnly;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;














GO
