/****** Object:  StoredProcedure [Company].[s_OpenBoxUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_OpenBoxUpdate] @DateIs DATETIME ,
  @FromAccountID UNIQUEIDENTIFIER ,
  @ToAccountID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @Balance FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @TransactionJV Transactions.dt_TransactionDetailShort READONLY ,
  @TransactionJVDescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventInsert NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @RefJV BIGINT ,
        @TransactionID UNIQUEIDENTIFIER ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @return INT;

    END;

    BEGIN --Set info

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);

      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

      SELECT TOP ( 1 ) @Ref = s.Ref
        FROM Company.t_OpenBox AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      SELECT TOP ( 1 ) @RefJV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = 8 AND s.LinkID = @ID AND s.TypeIs = N'JV'
        ORDER BY s.ID;

    END;

    BEGIN --Insert

      SET @return = 0;

      UPDATE Company.t_OpenBox
        SET DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            UserID = @UserID ,
            UserIs = Users.f_UserGetName(@UserID) ,
            FromAccountID = @FromAccountID ,
            FromAccount = Company.f_AccountGetName(@FromAccountID) ,
            FromAccountNumberF = Company.f_AccountGetNumberF(@FromAccountID) ,
            ToAccountID = @ToAccountID ,
            ToAccount = Company.f_AccountGetName(@ToAccountID) ,
            ToAccountNumberF = Company.f_AccountGetNumberF(@ToAccountID) ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            ExchangeRate = @ExchangeRate ,
            Balance = @Balance ,
            BalanceF = Currencys.f_Format(@CurrencyID, @Balance) ,
            BalanceD = @Balance / @ExchangeRate ,
            BalanceLL = Currencys.f_ExchangeToLL(@CurrencyID, @Balance, @Balance / @ExchangeRate) ,
            BalanceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @Balance, @Balance / @ExchangeRate) ,
            BalanceAR = Currencys.f_ToWordAR(@Balance, @CurrencyID, 1) ,
            BalanceEN = Currencys.f_ToWordEN(@Balance, @CurrencyID, 1) ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Company.t_OpenBoxMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Delete old transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 9 AND LinkID = @ID;

    END;

    BEGIN --Transaction

      IF @RefJV IS NULL
      BEGIN --Set info

        SELECT @RefJV = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              AccountsNames ,
              LinkType ,
              LinkID ,
              UserID ,
              UserIs
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @RefJV ,
              FORMAT(@RefJV, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@TransactionJVDescriptionIs, N'{0}', @Ref) ,
              Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                FROM @TransactionJV AS t
                                LEFT JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
                            FOR
                              XML PATH('')
                            )) ,
              9 ,
              @ID ,
              @UserID ,
              Users.f_UserGetName(@UserID)
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

      END;

      BEGIN --Insert detail

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber ,
              TransactionID ,
              AccountID ,
              Account ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              Balance ,
              BalanceF ,
              BalanceD ,
              BalanceLL ,
              BalanceEuro ,
              BalanceAR ,
              BalanceEN ,
              Credit ,
              CreditD ,
              CreditLL ,
              CreditEuro ,
              Debit ,
              DebitD ,
              DebitLL ,
              DebitEuro ,
              StatementIs ,
              CurrencyID ,
              Currency ,
              CurrencyTypeIs ,
              ExchangeRate ,
              ExchangeRateLL ,
              ExchangeRateEuro ,
              TypeIs
            )
          SELECT o.RowNumber ,
              @TransactionID ,
              o.AccountID ,
              o.Account ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              o.Balance ,
              o.BalanceF ,
              o.BalanceD ,
              o.BalanceLL ,
              o.BalanceEuro ,
              o.BalanceAR ,
              o.BalanceEN ,
              ABS(o.Credit) ,
              ABS(IIF(o.BalanceD < 0, o.BalanceD, 0)) ,
              ABS(IIF(o.BalanceLL < 0, o.BalanceLL, 0)) ,
              ABS(IIF(o.BalanceEuro < 0, o.BalanceEuro, 0)) ,
              o.Debit ,
              IIF(o.BalanceD > 0, o.BalanceD, 0) ,
              IIF(o.BalanceLL > 0, o.BalanceLL, 0) ,
              IIF(o.BalanceEuro > 0, o.BalanceEuro, 0) ,
              o.StatementIs ,
              @CurrencyID ,
              @Currency ,
              @CurrencyTypeIs ,
              @ExchangeRate ,
			  Currencys.f_CurrencyGetExchangeRateLL(),
			  Currencys.f_CurrencyGetExchangeRateEuro(),
              0
            FROM ( SELECT t.RowNumber ,
                      t.AccountID ,
                      Company.f_AccountGetName(t.AccountID) AS Account ,
                      t.Balance ,
                      Currencys.f_Format(@CurrencyID, t.Balance) AS BalanceF ,
                      t.Balance / @ExchangeRate AS BalanceD ,
                      Currencys.f_ExchangeToLL(@CurrencyID, t.Balance, t.Balance / @ExchangeRate) AS BalanceLL ,
                      Currencys.f_ExchangeToEuro(@CurrencyID, t.Balance, t.Balance / @ExchangeRate) AS BalanceEuro ,
                      Currencys.f_ToWordAR(Balance, @CurrencyID, 1) AS BalanceAR ,
                      Currencys.f_ToWordEN(Balance, @CurrencyID, 1) AS BalanceEN ,
                      IIF(Balance < 0, Balance, 0) AS Credit ,
                      IIF(Balance > 0, Balance, 0) AS Debit ,
                      REPLACE(t.StatementIs, N'{0}', @Ref) AS StatementIs
                    FROM @TransactionJV AS t
                 ) AS o
            ORDER BY o.RowNumber;

      END;

      BEGIN --Fix data

        UPDATE Company.t_Account
          SET StatusIs = 0 ,
              LastAction = GETDATE()
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @TransactionJV AS s
                          WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

      END;
	
      BEGIN --Fix t_Transaction

        EXECUTE Transactions.s_TransactionFixPart @TransactionID;

      END;

      BEGIN --Insert event

        SET @return = -1;

        INSERT INTO Transactions.t_TransactionMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          VALUES
            ( @UserID ,
              @TransactionID ,
              @EventInsert + CONVERT(NVARCHAR(MAX), @RefJV) ,
              0 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            );

      END;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Company].[s_PaySalaryDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_PaySalaryDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_OLD DATE ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly
        FROM Company.t_PaySalary AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Company.t_PaySalary
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 11 AND LinkID = @ID;

    END;

    BEGIN --Insert t_PaySalaryMoving

      SET @Return = -1;

      INSERT INTO Company.t_PaySalaryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 1, 'paySalary' );

    END;

    EXECUTE Company.s_PaySalaryLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Salaries_Update_PART @DateOnly_OLD;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;
















