CREATE PROCEDURE [Company].[s_PaySalaryInsert] @ID UNIQUEIDENTIFIER ,
  @Legal BIT ,
  @ItIsADraft BIT ,
  @DateIs DATETIME ,
  @FromDate DATETIME ,
  @ToDate DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @FirstBoxAccountID UNIQUEIDENTIFIER ,
  @SecondBoxAccountID UNIQUEIDENTIFIER ,
  @EmployeeAccountID UNIQUEIDENTIFIER ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @FirstCurrencyID UNIQUEIDENTIFIER ,
  @FirstExchangeRate FLOAT ,
  @FirstExchangeRateLL FLOAT ,
  @FirstExchangeRateEuro FLOAT ,
  @FirstAmount FLOAT ,
  @FirstAmountF NVARCHAR(MAX) ,
  @FirstAmountD FLOAT ,
  @FirstAmountLL FLOAT ,
  @FirstAmountEuro FLOAT ,
  @Wage FLOAT ,
  @WageF NVARCHAR(MAX) ,
  @WageD FLOAT ,
  @WageLL FLOAT ,
  @WageEuro FLOAT ,
  @Bonus FLOAT ,
  @BonusF NVARCHAR(MAX) ,
  @BonusD FLOAT ,
  @BonusLL FLOAT ,
  @BonusEuro FLOAT ,
  @Overtime FLOAT ,
  @OvertimeF NVARCHAR(MAX) ,
  @OvertimeD FLOAT ,
  @OvertimeLL FLOAT ,
  @OvertimeEuro FLOAT ,
  @RentAllowance FLOAT ,
  @RentAllowanceF NVARCHAR(MAX) ,
  @RentAllowanceD FLOAT ,
  @RentAllowanceLL FLOAT ,
  @RentAllowanceEuro FLOAT ,
  @TransferAllowance FLOAT ,
  @TransferAllowanceF NVARCHAR(MAX) ,
  @TransferAllowanceD FLOAT ,
  @TransferAllowanceLL FLOAT ,
  @TransferAllowanceEuro FLOAT ,
  @InvoicesProfit FLOAT ,
  @InvoicesProfitF NVARCHAR(MAX) ,
  @InvoicesProfitD FLOAT ,
  @InvoicesProfitLL FLOAT ,
  @InvoicesProfitEuro FLOAT ,
  @Discount FLOAT ,
  @DiscountF NVARCHAR(MAX) ,
  @DiscountD FLOAT ,
  @DiscountLL FLOAT ,
  @DiscountEuro FLOAT ,
  @Discount2 FLOAT ,
  @Discount2F NVARCHAR(MAX) ,
  @Discount2D FLOAT ,
  @Discount2LL FLOAT ,
  @Discount2Euro FLOAT ,
  @NSSFAmount FLOAT ,
  @NSSFAmountF NVARCHAR(MAX) ,
  @NSSFAmountD FLOAT ,
  @NSSFAmountLL FLOAT ,
  @NSSFAmountEuro FLOAT ,
  @SecondCurrencyID UNIQUEIDENTIFIER ,
  @SecondExchangeRate FLOAT ,
  @SecondExchangeRateLL FLOAT ,
  @SecondExchangeRateEuro FLOAT ,
  @SecondAmount FLOAT ,
  @SecondAmountF NVARCHAR(MAX) ,
  @SecondAmountD FLOAT ,
  @SecondAmountLL FLOAT ,
  @SecondAmountEuro FLOAT ,
  @TotalAmountD FLOAT ,
  @TotalAmountLL FLOAT ,
  @TotalAmountEuro FLOAT ,
  @NSSF BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @SoldDetailEmployeeProfitIDs Alls.tt_Guid READONLY ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(s.Ref), 0) + 1
        FROM Company.t_PaySalary AS s;

      SET @RefF = FORMAT(@Ref, '#');

    END;

    BEGIN --Insert t_PaySalary
	
      INSERT INTO Company.t_PaySalary
          ( ID ,
            Ref ,
            RefF ,
            Legal ,
            ItIsADraft ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            FromDate ,
            ToDate ,
            UserID ,
            FirstBoxAccountID ,
            SecondBoxAccountID ,
            EmployeeAccountID ,
            FirstCurrencyID ,
            FirstExchangeRate ,
            FirstExchangeRateLL ,
            FirstExchangeRateEuro ,
            FirstAmount ,
            FirstAmountF ,
            FirstAmountD ,
            FirstAmountLL ,
            FirstAmountEuro ,
            Wage ,
            WageF ,
            WageD ,
            WageLL ,
            WageEuro ,
            Bonus ,
            BonusF ,
            BonusD ,
            BonusLL ,
            BonusEuro ,
            Overtime ,
            OvertimeF ,
            OvertimeD ,
            OvertimeLL ,
            OvertimeEuro ,
            RentAllowance ,
            RentAllowanceF ,
            RentAllowanceD ,
            RentAllowanceLL ,
            RentAllowanceEuro ,
            TransferAllowance ,
            TransferAllowanceF ,
            TransferAllowanceD ,
            TransferAllowanceLL ,
            TransferAllowanceEuro ,
            InvoicesProfit ,
            InvoicesProfitF ,
            InvoicesProfitD ,
            InvoicesProfitLL ,
            InvoicesProfitEuro ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            Discount2 ,
            Discount2F ,
            Discount2D ,
            Discount2LL ,
            Discount2Euro ,
            NSSFAmount ,
            NSSFAmountF ,
            NSSFAmountD ,
            NSSFAmountLL ,
            NSSFAmountEuro ,
            SecondCurrencyID ,
            SecondExchangeRate ,
            SecondExchangeRateLL ,
            SecondExchangeRateEuro ,
            SecondAmount ,
            SecondAmountF ,
            SecondAmountD ,
            SecondAmountLL ,
            SecondAmountEuro ,
            TotalAmountD ,
            TotalAmountLL ,
            TotalAmountEuro ,
            NSSF ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @Legal ,
            @ItIsADraft ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @FromDate ,
            @ToDate ,
            @UserID ,
            @FirstBoxAccountID ,
            @SecondBoxAccountID ,
            @EmployeeAccountID ,
            @FirstCurrencyID ,
            @FirstExchangeRate ,
            @FirstExchangeRateLL ,
            @FirstExchangeRateEuro ,
            @FirstAmount ,
            @FirstAmountF ,
            @FirstAmountD ,
            @FirstAmountLL ,
            @FirstAmountEuro ,
            @Wage ,
            @WageF ,
            @WageD ,
            @WageLL ,
            @WageEuro ,
            @Bonus ,
            @BonusF ,
            @BonusD ,
            @BonusLL ,
            @BonusEuro ,
            @Overtime ,
            @OvertimeF ,
            @OvertimeD ,
            @OvertimeLL ,
            @OvertimeEuro ,
            @RentAllowance ,
            @RentAllowanceF ,
            @RentAllowanceD ,
            @RentAllowanceLL ,
            @RentAllowanceEuro ,
            @TransferAllowance ,
            @TransferAllowanceF ,
            @TransferAllowanceD ,
            @TransferAllowanceLL ,
            @TransferAllowanceEuro ,
            @InvoicesProfit ,
            @InvoicesProfitF ,
            @InvoicesProfitD ,
            @InvoicesProfitLL ,
            @InvoicesProfitEuro ,
            @Discount ,
            @DiscountF ,
            @DiscountD ,
            @DiscountLL ,
            @DiscountEuro ,
            @Discount2 ,
            @Discount2F ,
            @Discount2D ,
            @Discount2LL ,
            @Discount2Euro ,
            @NSSFAmount ,
            @NSSFAmountF ,
            @NSSFAmountD ,
            @NSSFAmountLL ,
            @NSSFAmountEuro ,
            @SecondCurrencyID ,
            @SecondExchangeRate ,
            @SecondExchangeRateLL ,
            @SecondExchangeRateEuro ,
            @SecondAmount ,
            @SecondAmountF ,
            @SecondAmountD ,
            @SecondAmountLL ,
            @SecondAmountEuro ,
            @TotalAmountD ,
            @TotalAmountLL ,
            @TotalAmountEuro ,
            @NSSF ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert t_PaySalaryMoving

      SET @return = -1;

      INSERT INTO Company.t_PaySalaryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + @RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @ItIsADraft = 0
    BEGIN

      EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
 
      BEGIN --Update t_SoldDetailEmployeeProfit

        UPDATE Invoices.t_SoldDetailEmployeeProfit
          SET Paid = 1
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @SoldDetailEmployeeProfitIDs AS s
                          WHERE s.ID = t_SoldDetailEmployeeProfit.ID );

        WITH  o AS ( SELECT 
                        t1.RowVersionID
                      FROM Invoices.t_SoldDetailEmployeeProfit AS t
                      INNER JOIN Invoices.t_Sold AS t1 ON t1.ID = t.SoldID
                      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                      FROM @SoldDetailEmployeeProfitIDs AS s
                                      WHERE s.ID = t.ID )
                   )
          UPDATE o
            SET o.RowVersionID = [DateTimes].[f_GetRowVersionID]();

      END;

      UPDATE Employees.t_Shift
        SET StatusIs = 1
        WHERE EmployeeID = @EmployeeID AND StatusIs <> 2 AND ISNULL(CheckInTime, RequiredCheckInTime) >= @FromDate AND ISNULL(CheckoutTime, RequiredCheckoutTime) <= @ToDate;
  
      UPDATE Employees.t_ShiftHistory
        SET StatusIs = 1
        WHERE EmployeeID = @EmployeeID AND StatusIs <> 2 AND ISNULL(CheckInTime, RequiredCheckInTime) >= @FromDate AND ISNULL(CheckoutTime, RequiredCheckoutTime) <= @ToDate;
      
      EXECUTE Invoices.s_SoldLiveVersion;
		           
    END;

    EXECUTE Company.s_PaySalaryLiveVersion;
 
    EXECUTE Invoices.s_ProfitDaily_Salaries_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;














