SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Company].[s_PaySalaryUpdate] @ID UNIQUEIDENTIFIER ,
  @Legal BIT ,
  @ItIsADraft BIT ,
  @DateIs DATETIME ,
  @FromDate DATETIME ,
  @ToDate DATETIME ,
  @FirstBoxAccountID UNIQUEIDENTIFIER ,
  @SecondBoxAccountID UNIQUEIDENTIFIER ,
  @EmployeeAccountID UNIQUEIDENTIFIER ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @FirstCurrencyID UNIQUEIDENTIFIER ,
  @FirstExchangeRate FLOAT ,
  @FirstExchangeRateLL FLOAT ,
  @FirstExchangeRateEuro FLOAT ,
  @FirstAmount FLOAT ,
  @FirstAmountF NVARCHAR(MAX) ,
  @FirstAmountD FLOAT ,
  @FirstAmountLL FLOAT ,
  @FirstAmountEuro FLOAT ,
  @Wage FLOAT ,
  @WageF NVARCHAR(MAX) ,
  @WageD FLOAT ,
  @WageLL FLOAT ,
  @WageEuro FLOAT ,
  @Bonus FLOAT ,
  @BonusF NVARCHAR(MAX) ,
  @BonusD FLOAT ,
  @BonusLL FLOAT ,
  @BonusEuro FLOAT ,
  @Overtime FLOAT ,
  @OvertimeF NVARCHAR(MAX) ,
  @OvertimeD FLOAT ,
  @OvertimeLL FLOAT ,
  @OvertimeEuro FLOAT ,
  @RentAllowance FLOAT ,
  @RentAllowanceF NVARCHAR(MAX) ,
  @RentAllowanceD FLOAT ,
  @RentAllowanceLL FLOAT ,
  @RentAllowanceEuro FLOAT ,
  @TransferAllowance FLOAT ,
  @TransferAllowanceF NVARCHAR(MAX) ,
  @TransferAllowanceD FLOAT ,
  @TransferAllowanceLL FLOAT ,
  @TransferAllowanceEuro FLOAT ,
  @InvoicesProfit FLOAT ,
  @InvoicesProfitF NVARCHAR(MAX) ,
  @InvoicesProfitD FLOAT ,
  @InvoicesProfitLL FLOAT ,
  @InvoicesProfitEuro FLOAT ,
  @Discount FLOAT ,
  @DiscountF NVARCHAR(MAX) ,
  @DiscountD FLOAT ,
  @DiscountLL FLOAT ,
  @DiscountEuro FLOAT ,
  @Discount2 FLOAT ,
  @Discount2F NVARCHAR(MAX) ,
  @Discount2D FLOAT ,
  @Discount2LL FLOAT ,
  @Discount2Euro FLOAT ,
  @NSSFAmount FLOAT ,
  @NSSFAmountF NVARCHAR(MAX) ,
  @NSSFAmountD FLOAT ,
  @NSSFAmountLL FLOAT ,
  @NSSFAmountEuro FLOAT ,
  @SecondCurrencyID UNIQUEIDENTIFIER ,
  @SecondExchangeRate FLOAT ,
  @SecondExchangeRateLL FLOAT ,
  @SecondExchangeRateEuro FLOAT ,
  @SecondAmount FLOAT ,
  @SecondAmountF NVARCHAR(MAX) ,
  @SecondAmountD FLOAT ,
  @SecondAmountLL FLOAT ,
  @SecondAmountEuro FLOAT ,
  @TotalAmountD FLOAT ,
  @TotalAmountLL FLOAT ,
  @TotalAmountEuro FLOAT ,
  @NSSF BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_OLD DATE ,
        @DateOnly DATE = @DateIs ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly
        FROM Company.t_PaySalary AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Company.t_PaySalary
        SET Legal = @Legal ,
            ItIsADraft = @ItIsADraft ,
            DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            FromDate = @FromDate ,
            ToDate = @ToDate ,
            FirstBoxAccountID = @FirstBoxAccountID ,
            SecondBoxAccountID = @SecondBoxAccountID ,
            EmployeeAccountID = @EmployeeAccountID ,
            FirstCurrencyID = @FirstCurrencyID ,
            FirstExchangeRate = @FirstExchangeRate ,
            FirstExchangeRateLL = @FirstExchangeRateLL ,
            FirstExchangeRateEuro = @FirstExchangeRateEuro ,
            FirstAmount = @FirstAmount ,
            FirstAmountF = @FirstAmountF ,
            FirstAmountD = @FirstAmountD ,
            FirstAmountLL = @FirstAmountLL ,
            FirstAmountEuro = @FirstAmountEuro ,
            Wage = @Wage ,
            WageF = @WageF ,
            WageD = @WageD ,
            WageLL = @WageLL ,
            WageEuro = @WageEuro ,
            Bonus = @Bonus ,
            BonusF = @BonusF ,
            BonusD = @BonusD ,
            BonusLL = @BonusLL ,
            BonusEuro = @BonusEuro ,
            Overtime = @Overtime ,
            OvertimeF = @OvertimeF ,
            OvertimeD = @OvertimeD ,
            OvertimeLL = @OvertimeLL ,
            OvertimeEuro = @OvertimeEuro ,
            RentAllowance = @RentAllowance ,
            RentAllowanceF = @RentAllowanceF ,
            RentAllowanceD = @RentAllowanceD ,
            RentAllowanceLL = @RentAllowanceLL ,
            RentAllowanceEuro = @RentAllowanceEuro ,
            TransferAllowance = @TransferAllowance ,
            TransferAllowanceF = @TransferAllowanceF ,
            TransferAllowanceD = @TransferAllowanceD ,
            TransferAllowanceLL = @TransferAllowanceLL ,
            TransferAllowanceEuro = @TransferAllowanceEuro ,
            InvoicesProfit = @InvoicesProfit ,
            InvoicesProfitF = @InvoicesProfitF ,
            InvoicesProfitD = @InvoicesProfitD ,
            InvoicesProfitLL = @InvoicesProfitLL ,
            InvoicesProfitEuro = @InvoicesProfitEuro ,
            Discount = @Discount ,
            DiscountF = @DiscountF ,
            DiscountD = @DiscountD ,
            DiscountLL = @DiscountLL ,
            DiscountEuro = @DiscountEuro ,
            Discount2 = @Discount2 ,
            Discount2F = @Discount2F ,
            Discount2D = @Discount2D ,
            Discount2LL = @Discount2LL ,
            Discount2Euro = @Discount2Euro ,
            NSSFAmount = @NSSFAmount ,
            NSSFAmountF = @NSSFAmountF ,
            NSSFAmountD = @NSSFAmountD ,
            NSSFAmountLL = @NSSFAmountLL ,
            NSSFAmountEuro = @NSSFAmountEuro ,
            SecondCurrencyID = @SecondCurrencyID ,
            SecondExchangeRate = @SecondExchangeRate ,
            SecondExchangeRateLL = @SecondExchangeRateLL ,
            SecondExchangeRateEuro = @SecondExchangeRateEuro ,
            SecondAmount = @SecondAmount ,
            SecondAmountF = @SecondAmountF ,
            SecondAmountD = @SecondAmountD ,
            SecondAmountLL = @SecondAmountLL ,
            SecondAmountEuro = @SecondAmountEuro ,
            TotalAmountD = @TotalAmountD ,
            TotalAmountLL = @TotalAmountLL ,
            TotalAmountEuro = @TotalAmountEuro ,
            NSSF = @NSSF ,
            DescriptionIs = @DescriptionIs ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_PaySalaryMoving

      SET @Return = -1;

      INSERT INTO Company.t_PaySalaryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 11 AND LinkID = @ID;

    END;

    IF @ItIsADraft = 0
    BEGIN
	    
      EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

      UPDATE Employees.t_Shift
        SET StatusIs = 1
        WHERE EmployeeID = @EmployeeID AND StatusIs <> 2 AND ISNULL(CheckInTime, RequiredCheckInTime) >= @FromDate AND ISNULL(CheckoutTime, RequiredCheckoutTime) <= @ToDate;
  
      UPDATE Employees.t_ShiftHistory
        SET StatusIs = 1
        WHERE EmployeeID = @EmployeeID AND StatusIs <> 2 AND ISNULL(CheckInTime, RequiredCheckInTime) >= @FromDate AND ISNULL(CheckoutTime, RequiredCheckoutTime) <= @ToDate;
	
    END;

    EXECUTE Company.s_PaySalaryLiveVersion;

    IF @DateOnly_OLD = @DateOnly
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_Salaries_Update_PART @DateOnly;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_Salaries_Update_PART @DateOnly_OLD;
      EXECUTE Invoices.s_ProfitDaily_Salaries_Update_PART @DateOnly;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;












GO
