    END;

    DISABLE TRIGGER Company.tr_Place ON Company.t_Place;

    BEGIN --Insert

      UPDATE  Company.t_Place
      SET     IsSync = @IsSync
      WHERE   ID = @ID;

    END;

    ENABLE TRIGGER Company.tr_Place ON Company.t_Place;

    BEGIN --Insert event

