    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Company.tr_Place ON Company.t_Place;

    RETURN @Return;

  END CATCH;

END;





