CREATE PROCEDURE [Company].[s_SocialMediaDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --DECLARE

      DECLARE @OwnerID UNIQUEIDENTIFIER ,
        @SectionID INT ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OwnerID = s.OwnerID ,
          @SectionID = s.SectionID
        FROM Company.t_SocialMedia AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;


    END;

    BEGIN --Update

      SET @Return = -2;

      DELETE FROM Company.t_SocialMedia
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      IF @SectionID = 15
      BEGIN

        EXECUTE Customers.s_CustomerMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @OwnerID;

      END;
      ELSE
        IF @SectionID = 33
        BEGIN

          INSERT INTO Employees.t_EmployeeMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
            VALUES
              ( @UserID ,
                @OwnerID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

        END;
        ELSE
          IF @SectionID = 38
          BEGIN

            INSERT INTO Company.t_BankMoving
                ( UserID ,
                  SectionID ,
                  EventIs ,
                  EventType ,
                  ComputerIP ,
                  Computer ,
                  ComputerAccount
                )
              VALUES
                ( @UserID ,
                  @OwnerID ,
                  @Event ,
                  @EventType ,
                  @ComputerIP ,
                  @Computer ,
                  @ComputerAccount
                );

          END;
          ELSE
            IF @SectionID = 42
            BEGIN

              INSERT INTO Company.t_WarehouseMoving
                  ( UserID ,
