                    EventIs ,
                    EventType ,
                    ComputerIP ,
                    Computer ,
                    ComputerAccount
                  )
                VALUES
                  ( @UserID ,
                    @OwnerID ,
                    @Event ,
                    @EventType ,
                    @ComputerIP ,
                    @Computer ,
                    @ComputerAccount
                  );

            END;
            ELSE
              IF @SectionID = 67
              BEGIN

                INSERT INTO Vendors.t_VendorMoving
                    ( UserID ,
                      SectionID ,
                      EventIs ,
                      EventType ,
                      ComputerIP ,
                      Computer ,
                      ComputerAccount
                    )
                  VALUES
                    ( @UserID ,
                      @OwnerID ,
                      @Event ,
                      @EventType ,
                      @ComputerIP ,
                      @Computer ,
                      @ComputerAccount
                    );

              END;
              ELSE
                IF @SectionID = 149
                BEGIN

                  INSERT INTO Employees.t_SalesPersonMoving
                      ( UserID ,
                        SectionID ,
                        EventIs ,
                        EventType ,
                        ComputerIP ,
                        Computer ,
                        ComputerAccount
                      )
                    VALUES
                      ( @UserID ,
                        @OwnerID ,
                        @Event ,
                        @EventType ,
                        @ComputerIP ,
                        @Computer ,
                        @ComputerAccount
                      );

                END;
                ELSE
                  IF @SectionID = 153
                  BEGIN

                    INSERT INTO Company.t_ContactMoving
                        ( UserID ,
                          SectionID ,
                          EventIs ,
                          EventType ,
                          ComputerIP ,
                          Computer ,
                          ComputerAccount
                        )
                      VALUES
                        ( @UserID ,
