                          @Event ,
                          @EventType ,
                          @ComputerIP ,
                          @Computer ,
                          @ComputerAccount
                        );

                  END;
                  ELSE
                    IF @SectionID = 163
                    BEGIN

                      INSERT INTO Company.t_DoctorMoving
