        WHERE ID = @MainAccountID;

    END;

    SET @Return = -1;
    EXECUTE Company.s_AccountMovingInsertPART @MainAccountID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;


