    END;

    BEGIN --Insert 

      INSERT INTO Company.t_SubAccounts
          ( ID ,
            MainAccountID ,
            SubAccountID 
          )
        SELECT s.ID ,
            s.MainAccountID ,
            s.SubAccountID
          FROM @SubAccounts AS s;

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET SubAccountsCount = Company.f_SubAccountsGetSubAccountsCountX(ID) ,
            SubAccountsNames = Company.f_SubAccountsGetSubAccountsNamesX(ID)
        WHERE ID = @MainAccountID;

    END;

    SET @Return = -1;
    EXECUTE Company.s_AccountMovingInsertPART @MainAccountID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;



