/****** Object:  StoredProcedure [Company].[s_WareHouseUpdatesIsEnable]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Company].[s_WareHouseUpdatesIsEnable] @Warehouses Company.tt_WareHouseUpdatesIsEnable READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Company.t_WareHouse AS t
      USING @Warehouses AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.IsEnable = s.IsEnable ,
                    t.IsSync = 0;

    END;

    BEGIN --Insert t_WarehouseMoving

      INSERT INTO Company.t_WarehouseMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Warehouses AS s;

    END;
    
    EXECUTE Company.s_WareHouseLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










