        BEGIN --Delete

            SET @Return = 0;

            TRUNCATE TABLE Currencys.t_CurrencyMoving;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Currencys.t_CurrencyMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, '00000000-0000-0000-0000-000000000000', @Event, 4, @ComputerIP, @Computer, @ComputerAccount);

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, Currency, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaCurrency, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;










GO
/****** Object:  StoredProcedure [Currencys].[s_CurrencyRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Currencys].[s_CurrencyRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Currencys.t_Currency
        SET DisplayFormat = DisplayFormat ,
            AccountC = ( SELECT COUNT(*)
                          FROM Company.t_Account AS s
                          WHERE ( s.CurrencyID = t_Currency.ID )
                       ) ,
            EmployeeC = ( SELECT COUNT(*)
                            FROM Employees.t_Employee AS s
                            WHERE ( s.FirstSalaryCurrencyID = t_Currency.ID )
                        ) ,
            EmployeeDiscountC = ( SELECT COUNT(*)
                                    FROM Employees.t_Discount AS s
                                    WHERE ( s.CurrencyID = t_Currency.ID )
                                ) + ( SELECT COUNT(*)
                                        FROM Employees.t_DiscountHistory AS s
                                        WHERE ( s.CurrencyID = t_Currency.ID )
                                    ) ,
            ItemC = ( SELECT COUNT(*)
                        FROM Items.t_ItemShared AS s
                        WHERE ( s.CurrencyID = t_Currency.ID )
                    ) ,
            PurchaseC = ( SELECT COUNT(*)
                            FROM Invoices.t_Purchasing AS s
                            WHERE ( s.CurrencyID = t_Currency.ID )
                        ) ,
            PurchaseReturnC = ( SELECT COUNT(*)
                                  FROM Invoices.t_PurchasingReturn AS s
                                  WHERE ( s.CurrencyID = t_Currency.ID )
                              ) ,
            SellC = ( SELECT COUNT(*)
                        FROM Invoices.t_Sold AS s
                        WHERE ( s.CurrencyID = t_Currency.ID )
                    ) ,
            SellReturnC = ( SELECT COUNT(*)
                              FROM Invoices.t_SoldReturn AS s
                              WHERE ( s.CurrencyID = t_Currency.ID )
                          ) ,
            InventoryAdjustmentC = ( SELECT COUNT(*)
                                      FROM Items.t_StockTake AS s
                                      WHERE ( s.CurrencyID = t_Currency.ID )
                                   ) ,
            QuotationC = ( SELECT COUNT(*)
                            FROM Quotations.t_Quotation AS s
                            WHERE ( s.CurrencyID = t_Currency.ID )
                         ) + ( SELECT COUNT(*)
                                FROM Quotations.t_QuotationHistory AS s
                                WHERE ( s.CurrencyID = t_Currency.ID )
                             ) ,
            ChequeC = ( SELECT COUNT(*)
                          FROM Company.t_Cheque AS s
                          WHERE ( s.CurrencyID = t_Currency.ID )
                      ) + ( SELECT COUNT(*)
                              FROM Company.t_ChequeHistory AS s
                              WHERE ( s.CurrencyID = t_Currency.ID )
                          ) ,
            TransactionC = ( SELECT COUNT(*)
                              FROM Transactions.t_TransactionDetail AS s
                              WHERE ( s.CurrencyID = t_Currency.ID )
                           );

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Currencys.t_CurrencyMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













GO
/****** Object:  StoredProcedure [Currencys].[s_CurrencyUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Currencys].[s_CurrencyUpdate] @Name NVARCHAR(450) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateTax FLOAT ,
  @ExchangeRateMoneyBack FLOAT ,
  @DecimalNumber TINYINT ,
  @PositivePattern TINYINT ,
  @PrintFormat NVARCHAR(MAX) ,
  @PrintFormatDetails NVARCHAR(MAX) ,
  @DescriptionAR NVARCHAR(MAX) ,
  @DescriptionEN NVARCHAR(MAX) ,
  @DescriptionDecimalAR NVARCHAR(MAX) ,
  @DescriptionDecimalEN NVARCHAR(MAX) ,
  @RewardPointsInsteadOf FLOAT ,
  @Level1RoundingStartFrom FLOAT ,
  @Level1RoundingMinimumUnit FLOAT ,
  @Level1RoundingAfter FLOAT ,
  @Level2RoundingStartFrom FLOAT ,
  @Level2RoundingMinimumUnit FLOAT ,
  @Level2RoundingAfter FLOAT ,
  @Level3RoundingStartFrom FLOAT ,
  @Level3RoundingMinimumUnit FLOAT ,
  @Level3RoundingAfter FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0 ,
        @NameOld NVARCHAR(450) ,
        @ExchangeRateOld FLOAT ,
        @TypeIs INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name ,
          @ExchangeRateOld = s.ExchangeRate ,
          @TypeIs = s.TypeIs
        FROM Currencys.t_Currency AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      UPDATE Currencys.t_Currency
        SET Name = @Name ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateTax = @ExchangeRateTax ,
            ExchangeRateMoneyBack = @ExchangeRateMoneyBack ,
            DecimalNumber = @DecimalNumber ,
            PositivePattern = @PositivePattern ,
            PrintFormat = @PrintFormat ,
            PrintFormatDetails = @PrintFormatDetails ,
            DescriptionAR = @DescriptionAR ,
            DescriptionEN = @DescriptionEN ,
            DescriptionDecimalAR = @DescriptionDecimalAR ,
            DescriptionDecimalEN = @DescriptionDecimalEN ,
            RewardPointsInsteadOf = @RewardPointsInsteadOf ,
            Level1RoundingStartFrom = @Level1RoundingStartFrom ,
            Level1RoundingMinimumUnit = @Level1RoundingMinimumUnit ,
            Level1RoundingAfter = @Level1RoundingAfter ,
            Level2RoundingStartFrom = @Level2RoundingStartFrom ,
            Level2RoundingMinimumUnit = @Level2RoundingMinimumUnit ,
            Level2RoundingAfter = @Level2RoundingAfter ,
            Level3RoundingStartFrom = @Level3RoundingStartFrom ,
            Level3RoundingMinimumUnit = @Level3RoundingMinimumUnit ,
            Level3RoundingAfter = @Level3RoundingAfter
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_CurrencyMoving

      SET @Return = -1;

      INSERT INTO Currencys.t_CurrencyMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      UPDATE Currencys.t_CurrencyExchangeRateHistory
        SET Currency = @Name
        WHERE CurrencyID = @ID;

      BEGIN --Invoices

        --t_SeparateDeliveryFees
        UPDATE Invoices.t_SeparateDeliveryFees
          SET FeeAmountF = Currencys.f_Format(CurrencyID, FeeAmount)
          WHERE CurrencyID = @ID;

        --t_PurchaseOrder
        UPDATE Invoices.t_PurchaseOrder
          SET Currency = @Name ,
              IsSync = 0
          WHERE CurrencyID = @ID;

        UPDATE Invoices.t_PurchaseOrderArchive
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		--t_DressesRental
        UPDATE Invoices.t_DressesRental
          SET Currency = @Name ,
              IsSync = 0
          WHERE CurrencyID = @ID;

        UPDATE Invoices.t_DressesRentalArchive
          SET Currency = @Name ,
              IsSync = 0
          WHERE CurrencyID = @ID;

		--t_TransferAwaited
        UPDATE Invoices.t_TransferAwaited
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Invoices.t_Transfer
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_Purchasing
        DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;

        UPDATE Invoices.t_Purchasing
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Invoices.t_Purchasing
          SET SecondPaymentCurrency = @Name
          WHERE SecondPaymentCurrencyID = @ID;

        ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
 
		  --t_PurchasingDeleted
        UPDATE Invoices.t_PurchasingDeleted
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Invoices.t_PurchasingDeleted
          SET SecondPaymentCurrency = @Name
          WHERE SecondPaymentCurrencyID = @ID;

        BEGIN; --t_PurchasingReturn

          DISABLE TRIGGER Invoices.tr_PurchasingReturn ON Invoices.t_PurchasingReturn;

          UPDATE Invoices.t_PurchasingReturn
            SET Currency = @Name
            WHERE CurrencyID = @ID;

          ENABLE TRIGGER Invoices.tr_PurchasingReturn ON Invoices.t_PurchasingReturn;

        END;

		  --t_Sold
        UPDATE Invoices.t_Sold
          SET Currency = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE CurrencyID = @ID;
  
        UPDATE Invoices.t_Sold
          SET SecondPaymentCurrency = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE SecondPaymentCurrencyID = @ID;

		  --t_SoldDeleted
        UPDATE Invoices.t_SoldDeleted
          SET Currency = @Name
          WHERE CurrencyID = @ID;
  
        UPDATE Invoices.t_SoldDeleted
          SET SecondPaymentCurrency = @Name
          WHERE SecondPaymentCurrencyID = @ID;

		  --t_SoldReturn
        DISABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;

        UPDATE Invoices.t_SoldReturn
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        ENABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;
	    
		  --t_DeliveryService
        UPDATE Invoices.t_DeliveryService
          SET CostCurrency = @Name
          WHERE CostCurrencyID = @ID;

        UPDATE Invoices.t_DeliveryServiceHistory
          SET CostCurrency = @Name
          WHERE CostCurrencyID = @ID;

        UPDATE Invoices.t_DeliveryServiceDeleted
          SET CostCurrency = @Name
          WHERE CostCurrencyID = @ID;

        UPDATE Invoices.t_DeliveryService
          SET DeliveryChargeCurrency = @Name
          WHERE DeliveryChargeCurrencyID = @ID;

        UPDATE Invoices.t_DeliveryServiceHistory
          SET DeliveryChargeCurrency = @Name
          WHERE DeliveryChargeCurrencyID = @ID;

        UPDATE Invoices.t_DeliveryServiceDeleted
          SET DeliveryChargeCurrency = @Name
          WHERE DeliveryChargeCurrencyID = @ID;

      END;

      BEGIN --Items
    
		  --t_ItemShared
        UPDATE Items.t_ItemShared
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_UnityItem
        UPDATE Items.t_UnityItem
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Items.t_UnityItem
          SET CurrencyCost = @Name
          WHERE CurrencyIDCost = @ID;

		  --t_BeginningInventoryQuantity
        UPDATE Items.t_BeginningInventoryQuantity
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_StockAdjustment
        UPDATE Items.t_StockAdjustment
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_StockTake
        UPDATE Items.t_StockTake
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_ItemExpirationDate
        UPDATE Items.t_ItemExpirationDate
          SET Currency = @Name ,
              PriceF = Currencys.f_Format(@ID, Price)
          WHERE CurrencyID = @ID;

      END;

      BEGIN --Company
    
		  --t_Account
        UPDATE Company.t_Account
          SET Currency = @Name ,
              DeliveryServicesTotalF = Currencys.f_Format(CurrencyID, DeliveryServicesTotal) ,
              DeliveryServicesProfitF = Currencys.f_Format(CurrencyID, DeliveryServicesProfit) ,
              PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
              PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit) ,
              PurchasingReturnTotalF = Currencys.f_Format(CurrencyID, PurchasingReturnTotal) ,
              PurchasingReturnProfitF = Currencys.f_Format(CurrencyID, PurchasingReturnProfit) ,
              SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
              SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit) ,
              SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
              SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit) ,
              QuotationTotalF = Currencys.f_Format(CurrencyID, QuotationTotal) ,
              QuotationProfitF = Currencys.f_Format(CurrencyID, QuotationProfit)
          WHERE CurrencyID = @ID;

		  --t_AccountGroup
        UPDATE Company.t_AccountGroup
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_Cheque
        UPDATE Company.t_Cheque
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Company.t_ChequeHistory
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_AccountItemPrice
        UPDATE Company.t_AccountItemPrice
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_CloseBox
        UPDATE Company.t_CloseBox
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Company.t_CloseBoxDetail
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_Expense
        UPDATE Company.t_Expense
          SET Currency = @Name ,
              RowVersionID = DateTimes.f_GetRowVersionID()
          WHERE CurrencyID = @ID;

		  --t_OpenBox
        UPDATE Company.t_OpenBox
          SET Currency = @Name
          WHERE CurrencyID = @ID;

      END;

      BEGIN --Transactions
     
	    --t_TransactionDetail
        UPDATE Transactions.t_TransactionDetail
          SET Currency = @Name
          WHERE CurrencyID = @ID;

      END;

      BEGIN --Employees
    
		  --t_Discount
        UPDATE Employees.t_Discount
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Employees.t_DiscountHistory
          SET Currency = @Name
          WHERE CurrencyID = @ID;

		  --t_Bonus
        UPDATE Employees.t_Bonus
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Employees.t_BonusHistory
          SET Currency = @Name
          WHERE CurrencyID = @ID;

      END;

      BEGIN --Customers
  
		  --t_Customer
        UPDATE Customers.t_Customer
          SET MaximumDebtInvoiceCurrency = @Name
          WHERE MaximumDebtInvoiceCurrencyID = @ID;

        WITH  o AS ( SELECT s1.CurrencyID ,
                        s.FrameJobOrderTotal ,
                        s.FrameJobOrderTotalF ,
                        s.FrameJobOrderProfit ,
                        s.FrameJobOrderProfitF
                      FROM Customers.t_Customer AS s
                      INNER JOIN Company.t_Account AS s1 ON s1.LinkWithID = s.ID AND s1.IsMasterLink = 1 AND s1.SectionID = 15
                      WHERE s1.CurrencyID = @ID
                   )
          UPDATE o
            SET o.FrameJobOrderTotalF = Currencys.f_Format(o.CurrencyID, o.FrameJobOrderTotal) ,
                o.FrameJobOrderProfitF = Currencys.f_Format(o.CurrencyID, o.FrameJobOrderProfit);

		  --t_FrameJobOrder
        UPDATE Customers.t_FrameJobOrder
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Customers.t_FrameJobOrderHistory
          SET Currency = @Name
          WHERE CurrencyID = @ID;
       
      END;
 
      BEGIN --Gym
    
        UPDATE Gym.t_SubscriptionType
          SET Currency = @Name
          WHERE CurrencyID = @ID;
  
        UPDATE Gym.t_PersonalTrainer
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Gym.t_GymClass
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Gym.t_GymSubscription
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Gym.t_GymSubscriptionHistory
          SET Currency = @Name
          WHERE CurrencyID = @ID;

        UPDATE Gym.t_GymSubscriptionDeleted
          SET Currency = @Name
          WHERE CurrencyID = @ID;

      END;  

      BEGIN --Cars

        UPDATE Cars.t_Car
          SET Currency = @Name ,
              PurchasePriceF = Currencys.f_Format(CurrencyID, PurchasePrice) ,
              SalePriceF = Currencys.f_Format(CurrencyID, SalePrice) ,
              DayPriceF = Currencys.f_Format(CurrencyID, DayPrice) ,
              WeekPriceF = Currencys.f_Format(CurrencyID, WeekPrice) ,
              MonthPriceF = Currencys.f_Format(CurrencyID, MonthPrice)
          WHERE CurrencyID = @ID;
    
        UPDATE Cars.t_CarExpense
          SET Currency = @Name ,
              BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
              TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
              NetIsF = Currencys.f_Format(CurrencyID, NetIs)
          WHERE CurrencyID = @ID;
	
        UPDATE Cars.t_CarRental
          SET Currency = @Name ,
              DayPriceF = Currencys.f_Format(CurrencyID, DayPrice) ,
              DayTotalPriceF = Currencys.f_Format(CurrencyID, DayTotalPrice) ,
              WeekPriceF = Currencys.f_Format(CurrencyID, WeekPrice) ,
              WeekTotalPriceF = Currencys.f_Format(CurrencyID, WeekTotalPrice) ,
              MonthPriceF = Currencys.f_Format(CurrencyID, MonthPrice) ,
              MonthTotalPriceF = Currencys.f_Format(CurrencyID, MonthTotalPrice) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
              PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
              RestF = Currencys.f_Format(CurrencyID, Rest) ,
              DailyTaxF = Currencys.f_Format(CurrencyID, DailyTax) ,
              TotalTaxF = Currencys.f_Format(CurrencyID, TotalTax) ,
              ProfitF = Currencys.f_Format(CurrencyID, Profit)
          WHERE CurrencyID = @ID;
	
        UPDATE Cars.t_CarRentalHistory
          SET Currency = @Name ,
              DayPriceF = Currencys.f_Format(CurrencyID, DayPrice) ,
              DayTotalPriceF = Currencys.f_Format(CurrencyID, DayTotalPrice) ,
              WeekPriceF = Currencys.f_Format(CurrencyID, WeekPrice) ,
              WeekTotalPriceF = Currencys.f_Format(CurrencyID, WeekTotalPrice) ,
              MonthPriceF = Currencys.f_Format(CurrencyID, MonthPrice) ,
              MonthTotalPriceF = Currencys.f_Format(CurrencyID, MonthTotalPrice) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
              PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
              RestF = Currencys.f_Format(CurrencyID, Rest) ,
              DailyTaxF = Currencys.f_Format(CurrencyID, DailyTax) ,
              TotalTaxF = Currencys.f_Format(CurrencyID, TotalTax) ,
              ProfitF = Currencys.f_Format(CurrencyID, Profit)
          WHERE CurrencyID = @ID;

      END;

    END;

    IF @ExchangeRateOld <> @ExchangeRate
    BEGIN; --Fix
	
      DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
      DISABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;
      DISABLE TRIGGER Employees.tr_Employee ON Employees.t_Employee;

      BEGIN --Invoices
    
	        --t_SeparateDeliveryFees
        WITH  o AS ( SELECT s.FeeAmount ,
                        s.FeeAmountD ,
                        s.FeeAmount / s1.ExchangeRate AS FeeAmountD_ ,
                        s.FeeAmountLL ,
                        s.FeeAmountEuro ,
                        s.CurrencyID ,
                        s1.ExchangeRate
                      FROM Invoices.t_SeparateDeliveryFees AS s
                      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                   )
          UPDATE o
            SET o.FeeAmountD = o.FeeAmountD_ ,
                o.FeeAmountLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.FeeAmount, o.FeeAmountD_) ,
                o.FeeAmountEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.FeeAmount, o.FeeAmountD_);

      END;

      BEGIN; --t_AlfaBundle
			
        WITH  o AS ( SELECT s.UnitSalePrice ,
                        s.UnitSalePriceD ,
                        s.UnitSalePrice / s1.ExchangeRate AS UnitSalePriceD_ ,
                        s.UnitSalePriceLL ,
                        s.UnitSalePriceEuro ,
                        s.CurrencyID ,
                        s1.ExchangeRate
                      FROM Invoices.t_AlfaBundle AS s
                      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                   )
          UPDATE o
            SET o.UnitSalePriceD = o.UnitSalePriceD_ ,
                o.UnitSalePriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.UnitSalePrice, o.UnitSalePriceD_) ,
                o.UnitSalePriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.UnitSalePrice, o.UnitSalePriceD_);

      END;

      IF @TypeIs = 1
      BEGIN; --t_PhoneSubscriber

        UPDATE Invoices.t_PhoneSubscriber
          SET MonthlyFees = MonthlyFeesD * @ExchangeRate ,
              ExtraCharge = ExtraChargeD * @ExchangeRate;
	
        UPDATE Invoices.t_PhoneSubscriber
          SET MonthlyFees = CEILING(MonthlyFees / 1000.0) * 1000.0 ,
              ExtraCharge = CEILING(ExtraCharge / 1000.0) * 1000.0;
  
        UPDATE Invoices.t_PhoneSubscriber
          SET Total = MonthlyFees + ExtraCharge;

      END;
 
      BEGIN --Customers
     
        BEGIN; --t_SubscriptionType
			
          WITH  o AS ( SELECT s.Internet_GeneralSubscriptionFee ,
                          s.Internet_GeneralSubscriptionFeeD ,
                          s.Internet_GeneralSubscriptionFee / s2.ExchangeRate AS Internet_GeneralSubscriptionFeeD_ ,
                          s.Internet_GeneralSubscriptionFeeLL ,
                          s.Internet_GeneralSubscriptionFeeEuro ,
                          s1.CurrencyID ,
                          s2.ExchangeRate
                        FROM Customers.t_Customer AS s
                        INNER JOIN Company.t_Account AS s1 ON s1.LinkWithID = s.ID AND s1.IsMasterLink = 1
                        INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
                     )
            UPDATE o
              SET o.Internet_GeneralSubscriptionFeeD = o.Internet_GeneralSubscriptionFeeD_ ,
                  o.Internet_GeneralSubscriptionFeeLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Internet_GeneralSubscriptionFee, o.Internet_GeneralSubscriptionFeeD_) ,
                  o.Internet_GeneralSubscriptionFeeEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Internet_GeneralSubscriptionFee, o.Internet_GeneralSubscriptionFeeD_);

        END;

      END;  

      BEGIN -- t_CurrencyExchangeRateHistory
	    
        INSERT INTO Currencys.t_CurrencyExchangeRateHistory
            ( CurrencyID ,
              Currency ,
              ExchangeRate ,
              ByUserID ,
              ByUser 
	        )
          VALUES
            ( @ID ,
              @Name ,
              @ExchangeRate ,
              @UserID ,
              Users.f_UserGetName(@UserID)
            );

      END;

      BEGIN; --t_ItemShared

        WITH  o AS ( SELECT s.CurrencyID ,
                        s.Purchase ,
                        s.PurchaseD ,
                        s.PurchaseLL ,
                        s.PurchaseEuro ,
                        s.PurchaseWithTax ,
                        s.PurchaseWithTaxD ,
                        s.PurchaseWithTaxLL ,
                        s.PurchaseWithTaxEuro ,
                        s.SellCurrencyID ,
                        s1.ExchangeRate ,
                        s2.ExchangeRate AS ExchangeRateSell ,
                        IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.WholesalePrice, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.WholesalePriceProfitRatio))) AS WholesalePrice_ ,
                        s.WholesalePrice ,
                        s.WholesalePriceF ,
                        s.WholesalePriceD ,
                        s.WholesalePriceLL ,
                        s.WholesalePriceEuro ,
                        Calculation.Rate(IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.WholesalePrice, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.WholesalePriceProfitRatio))), s.TaxRate) AS WholesalePriceWithTax_ ,
                        s.WholesalePriceWithTax ,
                        s.WholesalePriceWithTaxF ,
                        s.WholesalePriceWithTaxD ,
                        s.WholesalePriceWithTaxLL ,
                        s.WholesalePriceWithTaxEuro ,
                        IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.DistributionPrice, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.DistributionPriceProfitRatio))) AS DistributionPrice_ ,
                        s.DistributionPrice ,
                        s.DistributionPriceF ,
                        s.DistributionPriceD ,
                        s.DistributionPriceLL ,
                        s.DistributionPriceEuro ,
                        Calculation.Rate(IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.DistributionPrice, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.DistributionPriceProfitRatio))), s.TaxRate) AS DistributionPriceWithTax_ ,
                        s.DistributionPriceWithTax ,
                        s.DistributionPriceWithTaxF ,
                        s.DistributionPriceWithTaxD ,
                        s.DistributionPriceWithTaxLL ,
                        s.DistributionPriceWithTaxEuro ,
                        IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.Sell, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.ProfitRatio))) AS Sell_ ,
                        s.Sell ,
                        s.SellF ,
                        s.SellD ,
                        s.SellLL ,
                        s.SellEuro ,
                        Calculation.Rate(IIF(s.KeepProfitRatio = 0 OR s.Purchase = 0, s.Sell, Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.ProfitRatio))), s.TaxRate) AS SellWithTax_ ,
                        s.SellWithTax ,
                        s.SellWithTaxF ,
                        s.SellWithTaxD ,
                        s.SellWithTaxLL ,
                        s.SellWithTaxEuro
                      FROM Items.t_ItemShared AS s
                      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                      INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s.SellCurrencyID
                   )
          UPDATE o
            SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
                o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
                o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
                o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
                o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
                o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
                o.WholesalePrice = o.WholesalePrice_ ,
                o.WholesalePriceF = Currencys.f_Format(o.SellCurrencyID, o.WholesalePrice_) ,
                o.WholesalePriceD = o.WholesalePrice_ / o.ExchangeRateSell ,
                o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.ExchangeRateSell) ,
                o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.ExchangeRateSell) ,
                o.WholesalePriceWithTax = o.WholesalePriceWithTax_ ,
                o.WholesalePriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.WholesalePriceWithTax_) ,
                o.WholesalePriceWithTaxD = o.WholesalePriceWithTax_ / o.ExchangeRateSell ,
                o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.ExchangeRateSell) ,
                o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.ExchangeRateSell) ,
                o.DistributionPrice = o.DistributionPrice_ ,
                o.DistributionPriceF = Currencys.f_Format(o.SellCurrencyID, o.DistributionPrice_) ,
                o.DistributionPriceD = o.DistributionPrice_ / o.ExchangeRateSell ,
                o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.ExchangeRateSell) ,
                o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.ExchangeRateSell) ,
                o.DistributionPriceWithTax = o.DistributionPriceWithTax_ ,
                o.DistributionPriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.DistributionPriceWithTax_) ,
                o.DistributionPriceWithTaxD = o.DistributionPriceWithTax_ / o.ExchangeRateSell ,
                o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.ExchangeRateSell) ,
                o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.ExchangeRateSell) ,
                o.Sell = o.Sell_ ,
                o.SellF = Currencys.f_Format(o.SellCurrencyID, o.Sell_) ,
                o.SellD = o.Sell_ / o.ExchangeRateSell ,
                o.SellLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.Sell_, o.Sell_ / o.ExchangeRateSell) ,
                o.SellEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.Sell_, o.Sell_ / o.ExchangeRateSell) ,
                o.SellWithTax = o.SellWithTax_ ,
                o.SellWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.SellWithTax_) ,
                o.SellWithTaxD = o.SellWithTax_ / o.ExchangeRateSell ,
                o.SellWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.SellWithTax_, o.SellWithTax_ / o.ExchangeRateSell) ,
                o.SellWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.SellWithTax_, o.SellWithTax_ / o.ExchangeRateSell);

        UPDATE Items.t_ItemShared
          SET FinalPrice = Calculation.Discount(Sell, Discount) ,
              FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
              FinalPriceD = Calculation.Discount(SellD, Discount) ,
              FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
              FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
              PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
              PurchaseTotalD = PurchaseD * QtyCurrent ,
              PurchaseTotalLL = PurchaseLL * QtyCurrent ,
              PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
              PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
              PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
              PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
              PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
              TotalWholesalePrice = WholesalePrice * QtyCurrent ,
              TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
              TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
              TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
              TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
              TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
              TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
              TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
              TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
              TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
              TotalDistributionPrice = DistributionPrice * QtyCurrent ,
              TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
              TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
              TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
              TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
              TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
              TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
              TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
              TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
              TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
              SellTotal = Sell * QtyCurrent ,
              SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
              SellTotalD = SellD * QtyCurrent ,
              SellTotalLL = SellLL * QtyCurrent ,
              SellTotalEuro = SellEuro * QtyCurrent ,
              SellTotalWithTax = SellWithTax * QtyCurrent ,
              SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
              SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
              SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
              SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent;

      END;

      BEGIN; --t_UnityItem

        WITH  o AS ( SELECT s.CurrencyIDCost ,
                        s.Cost ,
                        s.CostD ,
                        s.CostLL ,
                        s.CostEuro ,
                        s.CostWithTax ,
                        s.CostWithTaxD ,
                        s.CostWithTaxLL ,
                        s.CostWithTaxEuro ,
                        s.CurrencyID ,
                        IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.Price, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.ProfitRatio))) AS Price_ ,
                        s.Price ,
                        s.PriceF ,
                        s.PriceD ,
                        s.PriceLL ,
                        s.PriceEuro ,
                        Calculation.Rate(IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.Price, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.ProfitRatio))), s3.TaxRate) AS PriceWithTax_ ,
                        s.PriceWithTax ,
                        s.PriceWithTaxF ,
                        s.PriceWithTaxD ,
                        s.PriceWithTaxLL ,
                        s.PriceWithTaxEuro ,
                        IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.DistributionPrice, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.DistributionPriceProfitRatio))) AS DistributionPrice_ ,
                        s.DistributionPrice ,
                        s.DistributionPriceF ,
                        s.DistributionPriceD ,
                        s.DistributionPriceLL ,
                        s.DistributionPriceEuro ,
                        Calculation.Rate(IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.DistributionPrice, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.DistributionPriceProfitRatio))), s3.TaxRate) AS DistributionPriceWithTax_ ,
                        s.DistributionPriceWithTax ,
                        s.DistributionPriceWithTaxF ,
                        s.DistributionPriceWithTaxD ,
                        s.DistributionPriceWithTaxLL ,
                        s.DistributionPriceWithTaxEuro ,
                        IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.WholesalePrice, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.WholesalePriceProfitRatio))) AS WholesalePrice_ ,
                        s.WholesalePrice ,
                        s.WholesalePriceF ,
                        s.WholesalePriceD ,
                        s.WholesalePriceLL ,
                        s.WholesalePriceEuro ,
                        Calculation.Rate(IIF(s3.KeepProfitRatio = 0 OR s.Cost = 0, s.WholesalePrice, Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.WholesalePriceProfitRatio))), s3.TaxRate) AS WholesalePriceWithTax_ ,
                        s.WholesalePriceWithTax ,
                        s.WholesalePriceWithTaxF ,
                        s.WholesalePriceWithTaxD ,
                        s.WholesalePriceWithTaxLL ,
                        s.WholesalePriceWithTaxEuro ,
                        s1.ExchangeRate AS EXCost ,
                        s2.ExchangeRate AS EXSell
                      FROM Items.t_UnityItem AS s
                      INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyIDCost
                      INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s.CurrencyID
                      INNER JOIN Items.t_ItemShared AS s3 ON s3.ID = s.SharedID
                   )
          UPDATE o
            SET o.CostD = o.Cost / o.EXCost ,
                o.CostLL = Currencys.f_ExchangeToLL(o.CurrencyIDCost, o.Cost, o.Cost / o.EXCost) ,
                o.CostEuro = Currencys.f_ExchangeToEuro(o.CurrencyIDCost, o.Cost, o.Cost / o.EXCost) ,
                o.CostWithTaxD = o.CostWithTax / o.EXCost ,
                o.CostWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyIDCost, o.CostWithTax, o.CostWithTax / o.EXCost) ,
                o.CostWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyIDCost, o.CostWithTax, o.CostWithTax / o.EXCost) ,
                o.Price = o.Price_ ,
                o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price_) ,
                o.PriceD = o.Price_ / o.EXSell ,
                o.PriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Price_, o.Price_ / o.EXSell) ,
                o.PriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Price_, o.Price_ / o.EXSell) ,
                o.PriceWithTax = o.PriceWithTax_ ,
                o.PriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.PriceWithTax_) ,
                o.PriceWithTaxD = o.PriceWithTax_ / o.EXSell ,
                o.PriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PriceWithTax_, o.PriceWithTax_ / o.EXSell) ,
                o.PriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PriceWithTax_, o.PriceWithTax_ / o.EXSell) ,
                o.DistributionPrice = o.DistributionPrice_ ,
                o.DistributionPriceF = Currencys.f_Format(o.CurrencyID, o.DistributionPrice_) ,
                o.DistributionPriceD = o.DistributionPrice_ / o.EXSell ,
                o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.EXSell) ,
                o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.EXSell) ,
                o.DistributionPriceWithTax = o.DistributionPriceWithTax_ ,
                o.DistributionPriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.DistributionPriceWithTax_) ,
                o.DistributionPriceWithTaxD = o.DistributionPriceWithTax_ / o.EXSell ,
                o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.EXSell) ,
                o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.EXSell) ,
                o.WholesalePrice = o.WholesalePrice_ ,
                o.WholesalePriceF = Currencys.f_Format(o.CurrencyID, o.WholesalePrice_) ,
                o.WholesalePriceD = o.WholesalePrice_ / o.EXSell ,
                o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.EXSell) ,
                o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.EXSell) ,
                o.WholesalePriceWithTax = o.WholesalePriceWithTax_ ,
                o.WholesalePriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.WholesalePriceWithTax_) ,
                o.WholesalePriceWithTaxD = o.WholesalePriceWithTax_ / o.EXSell ,
                o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.EXSell) ,
                o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.EXSell);

      END;
   
      BEGIN; --t_Employee
       
        UPDATE Employees.t_Employee
          SET FinalSalary = FirstSalary + Wage + Bonus + RentAllowance + TransferAllowance + Currencys.f_CurrencyExchangeTo(SecondSalaryCurrencyID, FirstSalaryCurrencyID, SecondSalary);

        UPDATE Employees.t_Employee
          SET FinalSalaryF = Currencys.f_Format(FirstSalaryCurrencyID, FinalSalary);

      END; 
       
      BEGIN; --t_ItemSharedEmployeeProfit
			
        WITH  o AS ( SELECT s.Profit ,
                        s.ProfitD ,
                        s.ProfitLL ,
                        s.ProfitEuro ,
                        s1.CurrencyID ,
                        s2.ExchangeRate
                      FROM Items.t_ItemSharedEmployeeProfit AS s
                      INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
                      LEFT JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.SellCurrencyID
                   )
          UPDATE o
            SET o.ProfitD = o.Profit / o.ExchangeRate ,
                o.ProfitLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Profit, o.Profit / o.ExchangeRate) ,
                o.ProfitEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Profit, o.Profit / o.ExchangeRate);

      END;

