      BEGIN; --t_GymClass
			
        WITH  o AS ( SELECT s.PriceDaily ,
                        s.PriceDailyD ,
                        s.PriceDailyLL ,
                        s.PriceDailyEuro ,
                        s.PriceWeekly ,
                        s.PriceWeeklyD ,
                        s.PriceWeeklyLL ,
                        s.PriceWeeklyEuro ,
                        s.PriceMonthly ,
                        s.PriceMonthlyD ,
                        s.PriceMonthlyLL ,
                        s.PriceMonthlyEuro ,
                        s.SalaryDaily ,
                        s.SalaryDailyD ,
                        s.SalaryDailyLL ,
                        s.SalaryDailyEuro ,
                        s.SalaryWeekly ,
                        s.SalaryWeeklyD ,
                        s.SalaryWeeklyLL ,
                        s.SalaryWeeklyEuro ,
                        s.SalaryMonthly ,
                        s.SalaryMonthlyD ,
                        s.SalaryMonthlyLL ,
                        s.SalaryMonthlyEuro ,
                        s.CurrencyID ,
                        s1.ExchangeRate
                      FROM Gym.t_GymClass AS s
                      LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                   )
          UPDATE o
            SET o.PriceDailyD = o.PriceDaily / o.ExchangeRate ,
                o.PriceDailyLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PriceDaily, o.PriceDaily / o.ExchangeRate) ,
                o.PriceDailyEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PriceDaily, o.PriceDaily / o.ExchangeRate) ,
                o.PriceWeeklyD = o.PriceWeekly / o.ExchangeRate ,
