/****** Object:  StoredProcedure [Currencys].[s_SchedulePaymentsInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Currencys].[s_SchedulePaymentsInsert] @ID UNIQUEIDENTIFIER ,
  @DateOnly DATE ,
  @PaymentDate DATE ,
  @AccountID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Amount FLOAT ,
  @AmountF NVARCHAR(MAX) ,
  @AmountD FLOAT ,
  @AmountLL FLOAT ,
  @AmountEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @SourceType INT ,
  @SourceID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @NewRef BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SELECT @NewRef = ISNULL(MAX(s.Ref), 0) + 1
        FROM Currencys.t_SchedulePayments AS s;

    END;

    BEGIN --Insert

      INSERT INTO Currencys.t_SchedulePayments
          ( ID ,
            Ref ,
            RefF ,
            DateOnly ,
            PaymentDate ,
            AccountID ,
            CurrencyID ,
            Amount ,
            AmountF ,
            AmountD ,
            AmountLL ,
            AmountEuro ,
            DescriptionIs ,
            SourceType ,
            SourceID ,
            CreatedByUserID
          )
        VALUES
          ( @ID ,
            @NewRef ,
            FORMAT(@NewRef, N'0') ,
            @DateOnly ,
            @PaymentDate ,
            @AccountID ,
            @CurrencyID ,
            @Amount ,
            @AmountF ,
            @AmountD ,
            @AmountLL ,
            @AmountEuro ,
            @DescriptionIs ,
            @SourceType ,
            @SourceID ,
			@UserID
          );
	  
    END;

    SET @Return = -1;
    EXECUTE Currencys.s_SchedulePaymentsMovingInsert @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID; 

    EXECUTE Currencys.s_SchedulePaymentsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Currencys].[s_SchedulePaymentsInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Currencys].[s_SchedulePaymentsInserts] @SchedulePayments Currencys.tt_SchedulePayments READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @IDs Alls.tt_Guid ,
        @LastRef BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID
          )
        SELECT s.ID
          FROM @SchedulePayments AS s;

      SELECT @LastRef = ISNULL(MAX(s.Ref), 0)
        FROM Currencys.t_SchedulePayments AS s;

    END;

    BEGIN --Insert

      INSERT INTO Currencys.t_SchedulePayments
          ( ID ,
            Ref ,
            RefF ,
            NumberFromTotal ,
            DateOnly ,
            PaymentDate ,
            AccountID ,
            CurrencyID ,
            Amount ,
            AmountF ,
            AmountD ,
            AmountLL ,
            AmountEuro ,
            DescriptionIs ,
            SourceType ,
            SourceID ,
            CreatedByUserID
          )
        SELECT s.ID ,
            @LastRef + ROW_NUMBER() OVER ( PARTITION BY 1 ORDER BY s.PaymentDate ) ,
            s.RefF ,
            s.NumberFromTotal ,
            s.DateOnly ,
            s.PaymentDate ,
            s.AccountID ,
            s.CurrencyID ,
            s.Amount ,
            s.AmountF ,
            s.AmountD ,
            s.AmountLL ,
            s.AmountEuro ,
            s.DescriptionIs ,
            s.SourceType ,
            s.SourceID ,
            s.UserID
          FROM @SchedulePayments AS s;
	  
    END;

    BEGIN --Update

      UPDATE Currencys.t_SchedulePayments
        SET RefF = FORMAT(Ref, N'0')
        WHERE Ref > @LastRef;

    END;

    EXECUTE Currencys.s_SchedulePaymentsNumberFromTotalRebuildPART @IDs;
	
    SET @Return = -1;
    EXECUTE Currencys.s_SchedulePaymentsMovingInserts @SchedulePayments;

    EXECUTE Currencys.s_SchedulePaymentsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;



GO
