/****** Object:  StoredProcedure [Currencys].[s_SchedulePaymentsNumberFromTotalRebuildPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Currencys].[s_SchedulePaymentsNumberFromTotalRebuildPART] @IDs Alls.tt_Guid READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @t AS TABLE
      (
        ID UNIQUEIDENTIFIER ,
        NumberFromTotal NVARCHAR(MAX)
      );

  END;

  BEGIN --Set
    	
    INSERT INTO @t
        ( ID ,
          NumberFromTotal
        )
      SELECT MIN(t.ID) OVER ( PARTITION BY t.ID ORDER BY t.PaymentDate ) ,
          FORMAT(ROW_NUMBER() OVER ( PARTITION BY t.SourceID ORDER BY t.PaymentDate ), N'0') + N' - ' + FORMAT(COUNT(t.ID) OVER ( PARTITION BY t.SourceID ), N'0')
        FROM Currencys.t_SchedulePayments AS t
        WHERE t.SourceType <> 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @IDs AS s
                                              WHERE s.ID = t.ID )
        ORDER BY t.PaymentDate;

  END;

  BEGIN; --NumberFromTotal
			
    WITH  o AS ( SELECT s.NumberFromTotal ,
                    s1.NumberFromTotal AS NumberFromTotal_
                  FROM Currencys.t_SchedulePayments AS s
                  INNER JOIN @t AS s1 ON s1.ID = s.ID
               )
      UPDATE o
        SET o.NumberFromTotal = o.NumberFromTotal_;

  END;
	
END;




GO
/****** Object:  StoredProcedure [Currencys].[s_SchedulePaymentsRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Currencys].[s_SchedulePaymentsRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @EventIs NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @t AS TABLE
        (
          ID UNIQUEIDENTIFIER ,
          NumberFromTotal NVARCHAR(MAX)
        );

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set
    	
      INSERT INTO @t
          ( ID ,
            NumberFromTotal
          )
        SELECT MIN(t.ID) OVER ( PARTITION BY t.ID ORDER BY t.PaymentDate ) ,
            FORMAT(ROW_NUMBER() OVER ( PARTITION BY t.SourceID ORDER BY t.PaymentDate ), N'0') + N' - ' + FORMAT(COUNT(t.ID) OVER ( PARTITION BY t.SourceID ), N'0')
          FROM Currencys.t_SchedulePayments AS t
          WHERE t.SourceType <> 0
          ORDER BY t.PaymentDate;

    END;

    BEGIN --Rebuild statistics

      UPDATE Currencys.t_SchedulePayments
        SET AmountF = Currencys.f_Format(CurrencyID, Amount) ,
            NumberFromTotal = N'';

    END;

    BEGIN; --ExchangeRate
			
      WITH  o AS ( SELECT s.Amount ,
                      s.AmountD ,
                      s.AmountLL ,
                      s.AmountEuro ,
                      s.CurrencyID ,
                      s1.ExchangeRate
                    FROM Currencys.t_SchedulePayments AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                 )
        UPDATE o
          SET o.AmountD = o.Amount / o.ExchangeRate ,
              o.AmountLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Amount, o.Amount / o.ExchangeRate) ,
              o.AmountEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Amount, o.Amount / o.ExchangeRate);

    END;

    BEGIN; --NumberFromTotal
			
      WITH  o AS ( SELECT s.NumberFromTotal ,
                      s1.NumberFromTotal AS NumberFromTotal_
                    FROM Currencys.t_SchedulePayments AS s
                    INNER JOIN @t AS s1 ON s1.ID = s.ID
                 )
        UPDATE o
          SET o.NumberFromTotal = o.NumberFromTotal_;

    END;

    SET @Return = -1;
    EXECUTE Currencys.s_SchedulePaymentsMovingInsert @UserID, @EventIs, 6, @ComputerIP, @Computer, @ComputerAccount, '00000000-0000-0000-0000-000000000000'; 
	
    EXECUTE Currencys.s_SchedulePaymentsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





