/****** Object:  StoredProcedure [Customers].[s_ClassificationUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_ClassificationUpdate] @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @MaximumInvoices FLOAT ,
  @MaximumInvoicesF NVARCHAR(MAX) ,
  @DuringThePeriod TINYINT ,
  @WithTax TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0 ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Customers.t_Classification AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      UPDATE Customers.t_Classification
        SET Name = @Name ,
            DescriptionIs = @DescriptionIs ,
            CurrencyID = @CurrencyID ,
            MaximumInvoices = @MaximumInvoices ,
            MaximumInvoicesF = @MaximumInvoicesF ,
            DuringThePeriod = @DuringThePeriod ,
            WithTax = @WithTax
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_ClassificationMoving

      SET @Return = -1;

      INSERT INTO Customers.t_ClassificationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Customer

        UPDATE Customers.t_Customer
          SET Classification = @Name
          WHERE ClassificationID = @ID;

      END;

      BEGIN --Vendor

        UPDATE Vendors.t_Vendor
          SET Classification = @Name
          WHERE ClassificationID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








GO
