/****** Object:  StoredProcedure [Customers].[s_CRMInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CRMInsert] @SaleID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @t AS TABLE
        (
          [CustomerID] [UNIQUEIDENTIFIER] NOT NULL ,
          [CustomerName] [NVARCHAR](MAX) NOT NULL ,
          [TypeIs] [TINYINT] NOT NULL ,
          [SalesID] [UNIQUEIDENTIFIER] NOT NULL ,
          [SalesRef] [NVARCHAR](MAX) NOT NULL ,
          [SalesDate] [DATETIME] NOT NULL ,
          [SalesEmployees] [NVARCHAR](MAX) NOT NULL ,
          [SalesDetailsID] [UNIQUEIDENTIFIER] NOT NULL ,
          [ItemSharedID] [UNIQUEIDENTIFIER] NOT NULL ,
          [ItemName] [NVARCHAR](MAX) NOT NULL ,
          [ReviewIs] [NVARCHAR](MAX) NOT NULL ,
          [TimeIs] [TINYINT] NOT NULL ,
          [Duedate1] [DATETIME] NOT NULL ,
          [Duedate2] [DATETIME] NOT NULL ,
          [Duedate3] [DATETIME] NOT NULL
        );

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete t_CRM
    
      DELETE FROM Customers.t_CRM
        WHERE SalesID = @SaleID;

    END;

    BEGIN --Set
				
      INSERT INTO @t
          ( CustomerID ,
            CustomerName ,
            TypeIs ,
            SalesID ,
            SalesRef ,
            SalesDate ,
            SalesEmployees ,
            SalesDetailsID ,
            ItemSharedID ,
            ItemName ,
            ReviewIs ,
            TimeIs ,
            Duedate1 ,
            Duedate2 ,
            Duedate3 
          )
        SELECT t3.AccountCustomerID ,
            t3.AccountCustomer ,
            0 ,
            t3.ID ,
            t3.Ref ,
            t3.DateIs ,
            t3.DescriptionIs ,
            t.ID ,
            t1.ID ,
            t1.Name ,
            '' ,
            0 ,
            DATEADD(DAY, t2.CRMFirstDatePeriod, t3.DateIs) ,
            DATEADD(DAY, t2.CRMSecondDatePeriod, t3.DateIs) ,
            DATEADD(DAY, t2.CRMThirdDatePeriod, t3.DateIs)
          FROM Invoices.t_SoldDetail AS t
          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
          INNER JOIN Items.t_MainCategory AS t2 ON t2.ID = t1.MainCategoryID
          INNER JOIN Invoices.t_Sold AS t3 ON t3.ID = t.SoldID
          WHERE t.SoldID = @SaleID;

    END;

    BEGIN --Insert t_CRM
				
      INSERT INTO Customers.t_CRM
          ( CustomerID ,
            CustomerName ,
            TypeIs ,
            SalesID ,
            SalesRef ,
            SalesDate ,
            SalesEmployees ,
            SalesDetailsID ,
            ItemSharedID ,
            ItemName ,
            ReviewIs ,
            TimeIs ,
            Duedate 
          )
        SELECT t.CustomerID ,
            t.CustomerName ,
            t.TypeIs ,
            t.SalesID ,
            t.SalesRef ,
            t.SalesDate ,
            t.SalesEmployees ,
            t.SalesDetailsID ,
            t.ItemSharedID ,
            t.ItemName ,
            t.ReviewIs ,
            1 ,
            t.Duedate1
          FROM @t AS t
        UNION ALL
        SELECT t.CustomerID ,
            t.CustomerName ,
            t.TypeIs ,
            t.SalesID ,
            t.SalesRef ,
            t.SalesDate ,
            t.SalesEmployees ,
            t.SalesDetailsID ,
            t.ItemSharedID ,
            t.ItemName ,
            t.ReviewIs ,
            2 ,
            t.Duedate2
          FROM @t AS t
        UNION ALL
        SELECT t.CustomerID ,
            t.CustomerName ,
            t.TypeIs ,
            t.SalesID ,
            t.SalesRef ,
            t.SalesDate ,
            t.SalesEmployees ,
            t.SalesDetailsID ,
            t.ItemSharedID ,
            t.ItemName ,
            t.ReviewIs ,
            3 ,
            t.Duedate3
          FROM @t AS t;

    END;
 
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






GO
