/****** Object:  StoredProcedure [Customers].[s_Customer_Update_InternetSubscriptionsInfo_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_Customer_Update_InternetSubscriptionsInfo_PART] @dt Customers.tt_CustomerInternetSubscriptionsInfo READONLY
AS
BEGIN

  MERGE Customers.t_Customer AS t
  USING @dt AS s
  ON s.ID = t.ID
  WHEN MATCHED THEN
    UPDATE SET t.InternetPackageID = s.InternetPackageID ,
                t.InternetPackage = s.InternetPackage ,
                t.EmployeeIDInternet = s.EmployeeID ,
                t.EmployeeInternet = s.Employee;

END;



