/****** Object:  StoredProcedure [Customers].[s_CustomerDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION customerDelete;

    BEGIN --Declare

      DECLARE @AccountID UNIQUEIDENTIFIER ,
        @AgeRangeID UNIQUEIDENTIFIER ,
        @Return INT;

    END;

    BEGIN --Set Info

      SELECT TOP ( 1 ) @AgeRangeID = s.AgeRangeID
        FROM Customers.t_Customer AS s
        WHERE s.ID = @ID;

      SELECT TOP ( 1 ) @AccountID = s.ID
        FROM Company.t_Account AS s
        WHERE s.SectionID = 15 AND s.LinkWithID = @ID AND s.IsMasterLink = 1;

    END;

    EXECUTE Transactions.s_TransactionDetailByDaysReinsertPART;

    BEGIN --Delete account

      SET @Return = -3;

      DELETE FROM Company.t_AccountItemPrice
        WHERE AccountID = @AccountID;

      DELETE FROM Company.t_Account
        WHERE SectionID = 15 AND LinkWithID = @ID;

    END;

    BEGIN --Delete phones 

      DELETE FROM Company.t_BookPhone
        WHERE SectionID = 15 AND OwnerID = @ID;

    END;

    BEGIN --Delete SocialMedia 

      DELETE FROM Company.t_SocialMedia
        WHERE SectionID = 15 AND OwnerID = @ID;

    END;

    BEGIN --Delete File Storage Linked 

      DELETE FROM Company.t_FileStorageLinked
        WHERE SectionID = 15 AND OwnerID = @ID;

    END;

    BEGIN --Delete

      SET @Return = 0;

      DELETE FROM Customers.t_Customer
        WHERE ID = @ID;

    END;

    BEGIN --Fix t_AgeRange

      UPDATE Customers.t_AgeRange
        SET CustomerC -= 1
        WHERE ID = @AgeRangeID;

    END;

    BEGIN --Fix t_CustomerGroup
		
      UPDATE Customers.t_CustomerGroup
        SET CustomerNames = Alls.f_FixXML(( SELECT N', ' + t.Customer AS [text()]
                                              FROM Customers.t_CustomerGroupDetail AS t
                                              WHERE t.CustomerGroupID = t_CustomerGroup.ID
                                          FOR
                                            XML PATH('')
                                          )) ,
            CustomerCount = ( SELECT COUNT(t.ID)
                                FROM Customers.t_CustomerGroupDetail AS t
                                WHERE t.CustomerGroupID = t_CustomerGroup.ID
                            )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Customers.t_CustomerGroupDetail AS s
                        WHERE s.CustomerID = @ID AND s.CustomerGroupID = t_CustomerGroup.ID );

    END;

    SET @Return = -1;
    EXECUTE Customers.s_CustomerMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID;

    COMMIT TRANSACTION customerDelete;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK TRANSACTION customerDelete;

    RETURN @Return;

  END CATCH;

END;














GO
/****** Object:  StoredProcedure [Customers].[s_CustomerExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Customers_t_Customer < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN; --Update 
  
      UPDATE Customers.t_Customer
        SET NewBirthday = DateTimes.f_GetNewBirthday(Birthday) ,
            AgeIs = DateTimes.f_GetAge(Birthday) ,
            ValidDriverLicense = IIF(YEAR(LicenseExpirationDate) <> 2000 AND LicenseExpirationDate >= CONVERT(DATE, GETDATE()), 1, 0);

      UPDATE Customers.t_Customer
        SET DaysCloseToBirthday = DateTimes.f_GetDaysCloseToBirthday(NewBirthday);

      WITH  o AS ( SELECT t.ShowNotificationNewBirthday
                    FROM Customers.t_Customer AS t
                    INNER JOIN Alls.t_CompanyInfo AS t2 ON 1 = 1
                    WHERE t.ShowNotificationNewBirthday = 0 AND t.DaysCloseToBirthday not BETWEEN t2.CustomerDaysBeforeBirthday
                                                                                      AND     t2.CustomerDaysAfterBirthday
                 )
        UPDATE o
          SET o.ShowNotificationNewBirthday = 1;

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Customers_t_Customer = GETDATE();

    END;

    EXECUTE Customers.s_CustomerLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Customers].[s_CustomerFormat]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerFormat] @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Rebuilding statistics

      UPDATE Customers.t_Customer
        SET Phones = Alls.f_FixXML(( SELECT N', ' + t.NumberIs + CASE t.ExtensionIs
                                                                   WHEN N'' THEN N''
                                                                   ELSE N': ' + t.ExtensionIs
                                                                 END AS [text()]
                                      FROM Company.t_BookPhone AS t
                                      WHERE t.OwnerID = t_Customer.ID AND t.SectionID = 15
                                   FOR
                                     XML PATH('')
                                   )) ,
            FullPhones = Alls.f_FixXML(( SELECT N', ' + t.NumberNetPlus + CASE t.ExtensionIs
                                                                            WHEN N'' THEN N''
                                                                            ELSE N': ' + t.ExtensionIs
                                                                          END AS [text()]
                                          FROM Company.t_BookPhone AS t
                                          WHERE t.OwnerID = t_Customer.ID AND t.SectionID = 15
                                       FOR
                                         XML PATH('')
                                       )) ,
            PhonesC = ( SELECT COUNT(t.ID)
                          FROM Company.t_BookPhone AS t
                          WHERE t.OwnerID = t_Customer.ID AND t.SectionID = 15
                      ) ,
            SocialMedia = Alls.f_FixXML(( SELECT N', ' + t.AccountIs AS [text()]
                                            FROM Company.t_SocialMedia AS t
                                            WHERE t.OwnerID = t_Customer.ID AND t.SectionID = 15
                                        FOR
                                          XML PATH('')
                                        )) ,
            SocialMediaC = ( SELECT COUNT(t.ID)
                              FROM Company.t_SocialMedia AS t
                              WHERE t.OwnerID = t_Customer.ID AND t.SectionID = 15
                           ) ,
            Title = Customers.f_TitleGetName(TitleID) ,
            Classification = Customers.f_ClassificationGetName(ClassificationID) ,
            SalesPerson = Employees.f_SalesPersonGetName(SalesPersonID) ,
            Nationality = Employees.f_NationalityGetName(NationalityID) ,
            StatesIs = Location.f_StatesGetName(StatesID) ,
            RegionIs = Location.f_RegionGetName(RegionID) ,
            Street = Location.f_StreetGetName(StreetID) ,
            Building = Location.f_BuildingGetName(BuildingID) ,
            FloorIs = Location.f_FloorGetName(FloorID) ,
            BirthPlaceStates = Location.f_StatesGetName(BirthPlaceStatesID) ,
            BirthPlaceRegion = Location.f_RegionGetName(BirthPlaceRegionID) ,
            BirthPlaceStreet = Location.f_StreetGetName(BirthPlaceStreetID) ,
            PostalCode = Location.f_PostalCodeGetName(PostalCodeID) ,
            CallAfterF = FORMAT(CallAfter, 't') ,
            ValidDriverLicense = IIF(YEAR(LicenseExpirationDate) <> 2000 AND LicenseExpirationDate >= CONVERT(DATE, GETDATE()), 1, 0)
        WHERE ID = @ID;

      UPDATE Customers.t_Customer
        SET AddressIs = Location.f_ConcetFullAddress(StatesIs, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-') ,
            BirthPlace = Location.f_ConcetFullAddress(BirthPlaceStates, BirthPlaceRegion, BirthPlaceStreet, '-', '-', '-', '-', ' - ', '-')
        WHERE ID = @ID;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;










