/****** Object:  StoredProcedure [Customers].[s_CustomerGenerate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerGenerate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @ClassificationID UNIQUEIDENTIFIER ,
  @AccountCurrencyID UNIQUEIDENTIFIER ,
  @LicenseInternet BIT ,
  @NotificationBeforeDaysInternet TINYINT ,
  @EventBase NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @AgeRangeID UNIQUEIDENTIFIER = Customers.f_AgeRangeGetFirstID() ,
        @InternetPackageID UNIQUEIDENTIFIER = Customers.f_InternetPackageGetFirstID() ,
        @AccountID UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Customers.t_Customer
          ( ID ,
            Name ,
            NewBirthday ,
            DaysCloseToBirthday ,
            AgeIs ,
            ClassificationID ,
            LicenseInternet ,
            MaximumDebtInvoiceCurrencyID ,
            MaximumDebtInvoiceCurrency ,
            MaximumDebtInvoiceF
          )
        VALUES
          ( @ID ,
            @Name ,
            DateTimes.f_GetNewBirthday(GETDATE()) ,
            DateTimes.f_GetDaysCloseToBirthday(DateTimes.f_GetNewBirthday(GETDATE())) ,
            DateTimes.f_GetAge(GETDATE()) ,
            @ClassificationID ,
            @LicenseInternet ,
            @AccountCurrencyID ,
            Currencys.f_CurrencyGetName(@AccountCurrencyID) ,
            Currencys.f_Format(@AccountCurrencyID, 0)
          );

    END;

    BEGIN --Insert t_Account Normal

      SET @Return = -5;

      BEGIN --DECLARE

        DECLARE @Level3ID UNIQUEIDENTIFIER ,
          @NumberIs BIGINT ,
          @NumberF NVARCHAR(MAX);

      END;

      BEGIN --Set info

        SET @Level3ID = Company.f_AccountLevel3GetIDByNumber(41101);

        SELECT @NumberIs = COALESCE(MAX(t.NumberIs), 4110100000) + 1
          FROM Company.t_Account AS t
          WHERE t.Level3ID = @Level3ID;

        SET @NumberF = @NumberIs;

      END;

      DELETE FROM @IDs;

      INSERT INTO Company.t_Account
          ( Level3ID ,
            Level3 ,
            SectionID ,
            LinkWithID ,
            LinkWith ,
            IsMasterLink ,
            NumberIs ,
            NumberF ,
            NumberNet ,
            Name ,
            CurrencyID ,
            Currency ,
            CurrencyTypeIs ,
            Limit ,
            LimitF ,
            LimitD ,
            DescriptionIs
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Level3ID ,
            Company.f_AccountLevel3GetName(@Level3ID) ,
            15 ,
            @ID ,
            @Name ,
            1 ,
            @NumberIs ,
            @NumberF ,
            SUBSTRING(@NumberF, 6, 5) ,
            @Name ,
            @AccountCurrencyID ,
            Currencys.f_CurrencyGetName(@AccountCurrencyID) ,
            Currencys.f_CurrencyGetTypeIs(@AccountCurrencyID) ,
            0 ,
            Currencys.f_Format(@AccountCurrencyID, 0) ,
            0 ,
            N''
          );

      SET @AccountID = ( SELECT TOP ( 1 ) ID
                          FROM @IDs
                          ORDER BY ID
                       );

    END;

    BEGIN --Insert t_Account Tax

      BEGIN --Set info

        DECLARE @Level3IDTax UNIQUEIDENTIFIER = Company.f_AccountLevel3GetIDByNumber(44270);

        DECLARE @AccountIDTax UNIQUEIDENTIFIER;

        SELECT @NumberIs = COALESCE(MAX(t.NumberIs), 4427000000) + 1
          FROM Company.t_Account AS t
          WHERE t.Level3ID = @Level3IDTax;

        SET @NumberF = @NumberIs;

      END;

      DELETE FROM @IDs;

      INSERT INTO Company.t_Account
          ( Level3ID ,
            Level3 ,
            SectionID ,
            LinkWithID ,
            LinkWith ,
            IsMasterLink ,
            NumberIs ,
            NumberF ,
            NumberNet ,
            Name ,
            CurrencyID ,
            Currency ,
            CurrencyTypeIs ,
            Limit ,
            LimitF ,
            LimitD ,
            DescriptionIs ,
            ShowInStatement
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Level3IDTax ,
            Company.f_AccountLevel3GetName(@Level3IDTax) ,
            15 ,
            @ID ,
            @Name ,
            0 ,
            @NumberIs ,
            @NumberF ,
            SUBSTRING(@NumberF, 6, 5) ,
            @Name + ' | الضريبة' ,
            @AccountCurrencyID ,
            Currencys.f_CurrencyGetName(@AccountCurrencyID) ,
            Currencys.f_CurrencyGetTypeIs(@AccountCurrencyID) ,
            0 ,
            Currencys.f_Format(@AccountCurrencyID, 0) ,
            0 ,
            N'' ,
            0
          );

      SET @AccountIDTax = ( SELECT TOP ( 1 ) ID
                              FROM @IDs
                              ORDER BY ID
                          );

    END;

    BEGIN --Update t_Customer

      UPDATE Customers.t_Customer
        SET Classification = Customers.f_ClassificationGetName(ClassificationID) ,
            CallAfterF = FORMAT(CallAfter, 't')
        WHERE ID = @ID;

    END;

    BEGIN --Update t_InternetPackage

      UPDATE Customers.t_InternetPackage
        SET TotalCustomers += 1
        WHERE ID = @InternetPackageID;

    END;
      
    BEGIN --Update t_AgeRange

      UPDATE Customers.t_AgeRange
        SET CustomerC += 1
        WHERE ID = @AgeRangeID;

    END;

    SET @Return = -1;
    EXECUTE Customers.s_CustomerMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID;

    BEGIN --Insert t_AccountMoving

      SET @Return = -1;

      SET @EventBase += Company.f_AccountGetName(@AccountID);

      INSERT INTO Company.t_AccountMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @AccountID ,
            @EventBase ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Insert t_AccountMoving Tax

      SET @Return = -1;

      DECLARE @AccountEvent NVARCHAR(MAX) = @EventBase + Company.f_AccountGetName(@AccountIDTax);

      INSERT INTO Company.t_AccountMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @AccountIDTax ,
            @AccountEvent ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;


GO
/****** Object:  StoredProcedure [Customers].[s_CustomerGroupDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerGroupDelete]
    @UserID UNIQUEIDENTIFIER ,
    @Event NVARCHAR(MAX) ,
    @EventType TINYINT ,
    @ComputerIP NVARCHAR(MAX) ,
    @Computer NVARCHAR(MAX) ,
    @ComputerAccount NVARCHAR(MAX) ,
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

            DECLARE @CustomerIDs AS TABLE ( ID UNIQUEIDENTIFIER );

        END;

        BEGIN --Set Info

            INSERT  INTO @CustomerIDs
                    ( ID
                    )
                    SELECT  s.CustomerID
                    FROM    Customers.t_CustomerGroupDetail AS s
                    WHERE   s.CustomerGroupID = @ID;

        END;

        BEGIN --Delete

            SET @Return = 0;

            DELETE  FROM Customers.t_CustomerGroupDetail
            WHERE   CustomerGroupID = @ID;

            DELETE  FROM Customers.t_CustomerGroup
            WHERE   ID = @ID;

        END;

        BEGIN --Fix t_Customer

            UPDATE  Customers.t_Customer
            SET     GroupNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                                 FROM   Customers.t_CustomerGroupDetail AS t
                                                        LEFT JOIN Customers.t_CustomerGroup AS t1 ON t1.ID = t.CustomerGroupID
                                                 WHERE  t.CustomerID = t_Customer.ID
                                               FOR
                                                 XML PATH('')
                                               )) ,
                    GroupCounts = ( SELECT  COUNT(t.ID)
                                    FROM    Customers.t_CustomerGroupDetail AS t
                                    WHERE   t.CustomerID = t_Customer.ID
                                  )
            WHERE   EXISTS ( SELECT TOP ( 1 )
                                    s.ID
                             FROM   @CustomerIDs AS s
                             WHERE  s.ID = t_Customer.ID );

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT  INTO Customers.t_CustomerGroupMoving
                    ( UserID ,
                      SectionID ,
                      EventIs ,
                      EventType ,
                      ComputerIP ,
                      Computer ,
                      ComputerAccount
                    )
            VALUES  ( @UserID ,
                      @ID ,
                      @Event ,
                      @EventType ,
                      @ComputerIP ,
                      @Computer ,
                      @ComputerAccount
                    );
	
        END;
		
        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;


GO
