/****** Object:  StoredProcedure [Customers].[s_CustomerGroupRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CustomerGroupRebuildingStatistics]
    @UserID UNIQUEIDENTIFIER ,
    @Event NVARCHAR(MAX) ,
    @ComputerIP NVARCHAR(MAX) ,
    @Computer NVARCHAR(MAX) ,
    @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Rebuilding statistics

            SET @Return = 0;

            UPDATE  Customers.t_CustomerGroupDetail
            SET     Customer = Customers.f_CustomerGetName(CustomerID);

            UPDATE  Customers.t_CustomerGroup
            SET     CustomerNames = Alls.f_FixXML(( SELECT  N', ' + s.Customer AS [text()]
                                                    FROM    Customers.t_CustomerGroupDetail AS s
                                                    WHERE   s.CustomerGroupID = t_CustomerGroup.ID
                                                  FOR
                                                    XML PATH('')
                                                  )) ,
                    CustomerCount = ( SELECT    COUNT(*)
                                      FROM      Customers.t_CustomerGroupDetail AS s
                                      WHERE     s.CustomerGroupID = t_CustomerGroup.ID
                                    );

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT  INTO Customers.t_CustomerGroupMoving
                    ( UserID ,
                      SectionID ,
                      EventIs ,
                      EventType ,
                      ComputerIP ,
                      Computer ,
                      ComputerAccount
                    )
            VALUES  ( @UserID ,
                      '00000000-0000-0000-0000-000000000000' ,
                      @Event ,
                      6 ,
                      @ComputerIP ,
                      @Computer ,
                      @ComputerAccount
                    );

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;












GO
/****** Object:  StoredProcedure [Customers].[s_CustomerGroupUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CustomerGroupUpdate]
  @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 )
              @NameOld = s.Name
      FROM    Customers.t_CustomerGroup AS s
      WHERE   s.ID = @ID
      ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE  Customers.t_CustomerGroup
      SET     Name = @Name ,
              DescriptionIs = @DescriptionIs
      WHERE   ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Customers.t_CustomerGroupMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Customer

        DECLARE @CustomerIDs AS TABLE ( ID UNIQUEIDENTIFIER );

        INSERT  INTO @CustomerIDs
                ( ID
                )
        SELECT DISTINCT
                s.CustomerID
        FROM    Customers.t_CustomerGroupDetail AS s
        WHERE   s.CustomerGroupID = @ID;

        UPDATE  Customers.t_Customer
        SET     GroupNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                             FROM   Customers.t_CustomerGroupDetail AS t
                                             LEFT JOIN Customers.t_CustomerGroup AS t1 ON t1.ID = t.CustomerGroupID
                                             WHERE  t.CustomerID = t_Customer.ID
                                           FOR
                                             XML PATH('')
                                           ))
        WHERE   EXISTS ( SELECT TOP ( 1 )
                                s.ID
                         FROM   @CustomerIDs AS s
                         WHERE  s.ID = t_Customer.ID );

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Customers].[s_CustomerGroupUpdateIsSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CustomerGroupUpdateIsSync]
    @IsSync BIT,
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY

    SET ANSI_WARNINGS OFF;

        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Customers.tr_CustomerGroup ON Customers.t_CustomerGroup;

        BEGIN --Insert

            UPDATE Customers.t_CustomerGroup
            SET IsSync = @IsSync
            WHERE ID = @ID;

        END;

        ENABLE TRIGGER Customers.tr_CustomerGroup ON Customers.t_CustomerGroup;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Customers.t_CustomerGroupMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, @ID, @Event, 7, @ComputerIP, @Computer, @ComputerAccount);

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;






GO
/****** Object:  StoredProcedure [Customers].[s_CustomerGroupUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Customers].[s_CustomerGroupUpdateNotSync] @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Customers.tr_CustomerGroup ON Customers.t_CustomerGroup;
    DISABLE TRIGGER Customers.tr_CustomerGroupDetail ON Customers.t_CustomerGroupDetail;

    BEGIN --Update

      UPDATE Customers.t_CustomerGroup
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_CustomerGroup.ID );
         
      UPDATE Customers.t_CustomerGroupDetail
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_CustomerGroupDetail.CustomerGroupID );

    END;

    ENABLE TRIGGER Customers.tr_CustomerGroup ON Customers.t_CustomerGroup;
    ENABLE TRIGGER Customers.tr_CustomerGroupDetail ON Customers.t_CustomerGroupDetail;
		   
    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, CustomerGroup, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaCustomer, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;







GO
