/****** Object:  StoredProcedure [Customers].[s_CustomerInsertDefaultData]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CustomerInsertDefaultData]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check

      IF EXISTS ( SELECT TOP ( 1 ) ID
                    FROM Customers.t_Customer )
      BEGIN
			
        COMMIT TRAN;

        RETURN 1;

      END;

    END;

    BEGIN --Insert
		
      INSERT INTO Customers.t_CustomerOption
          DEFAULT VALUES;

      INSERT INTO Customers.t_Customer
          DEFAULT VALUES;

      UPDATE Customers.t_Customer
        SET NewBirthday = DateTimes.f_GetNewBirthday(Birthday);
 
      UPDATE Customers.t_Customer
        SET DaysCloseToBirthday = DateTimes.f_GetDaysCloseToBirthday(NewBirthday);

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;










