/****** Object:  StoredProcedure [Customers].[s_CustomersInvoicesPointsReinsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Customers].[s_CustomersInvoicesPointsReinsertPART] @CustomerID UNIQUEIDENTIFIER ,
  @DateOnly DATE ,
  @TypeIs TINYINT ,
  @LinkedWithID UNIQUEIDENTIFIER ,
  @PointsIs FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  IF EXISTS ( SELECT TOP ( 1 ) s.ID
                FROM Customers.t_CustomersInvoicesPoints AS s
                WHERE s.LinkedWithID = @LinkedWithID )
  BEGIN
	      
    BEGIN --DECLARE
    
      DECLARE @OldCustomerID UNIQUEIDENTIFIER ,
        @OldPointsIs FLOAT;

    END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @OldCustomerID = s.CustomerID ,
          @OldPointsIs = s.PointsIs
        FROM Customers.t_CustomersInvoicesPoints AS s
        WHERE s.LinkedWithID = @LinkedWithID;

    END;

    EXECUTE Customers.s_CustomerUpdatePointsAddPART @OldCustomerID, @OldPointsIs, 0;

    DELETE FROM Customers.t_CustomersInvoicesPoints
      WHERE LinkedWithID = @LinkedWithID;

  END;
  
  --Insert t_CustomersInvoicesPoints
  EXECUTE Customers.s_CustomersInvoicesPointsInsertPART @CustomerID, @DateOnly, 0, @LinkedWithID, @PointsIs, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
	
END;





