CREATE PROCEDURE [Customers].[s_CustomersInvoicesPointsUpdate] @ID UNIQUEIDENTIFIER ,
  @CustomerID UNIQUEIDENTIFIER ,
  @DateOnly DATE ,
  @TypeIs TINYINT ,
  @PointsIs FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @OldCustomerID UNIQUEIDENTIFIER ,
        @OldPoints FLOAT ,
        @Return INT = 0;

    END;

    BEGIN --Set

      SELECT @OldCustomerID = s.CustomerID ,
          @OldPoints = s.PointsIs
        FROM Customers.t_CustomersInvoicesPoints AS s
        WHERE s.ID = @ID;
 
    END;

    BEGIN --Update

      UPDATE Customers.t_CustomersInvoicesPoints
        SET CustomerID = @CustomerID ,
            DateOnly = @DateOnly ,
            TypeIs = @TypeIs ,
            PointsIs = @PointsIs ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;
	  
    END;

    EXECUTE Customers.s_CustomerUpdatePointsAddPART @OldCustomerID, @OldPoints, 0;
    EXECUTE Customers.s_CustomerUpdatePointsAddPART @CustomerID, 0, @PointsIs;

    SET @Return = -1;
    EXECUTE Customers.[s_CustomersInvoicesPointsMovingInsertPART] @UserID, @ID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Customers.s_CustomersInvoicesPointsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






