/****** Object:  StoredProcedure [Customers].[s_CustomerUpdateAddress]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_CustomerUpdateAddress]
  @StatesID UNIQUEIDENTIFIER ,
  @RegionID UNIQUEIDENTIFIER ,
  @StreetID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Update 

      SET @Return = 0;

      UPDATE  Customers.t_Customer
      SET     StatesID = @StatesID ,
              StatesIs = Location.f_StatesGetName(@StatesID) ,
              RegionID = @RegionID ,
              RegionIs = Location.f_RegionGetName(@RegionID) ,
              StreetID = @StreetID ,
              Street = Location.f_StreetGetName(@StreetID)
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDAndEvent AS s
                       WHERE  s.ID = t_Customer.ID );

      UPDATE  Customers.t_Customer
      SET     AddressIs = Location.f_ConcetFullAddress(StatesIs, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDAndEvent AS s
                       WHERE  s.ID = t_Customer.ID );
	  
    END;

    SET @Return = -1;
    EXECUTE Customers.s_CustomerMovingInsertsPART2 @IDAndEvent, @UserID, 1, @ComputerIP, @Computer, @ComputerAccount;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  @Return;

  END CATCH;

END;










