/****** Object:  StoredProcedure [Customers].[s_FrameJobOrderRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Customers].[s_FrameJobOrderRebuildingStatistics]
    @UserID UNIQUEIDENTIFIER ,
    @Event NVARCHAR(MAX) ,
    @ComputerIP NVARCHAR(MAX) ,
    @Computer NVARCHAR(MAX) ,
    @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Customers.tr_FrameJobOrder ON Customers.t_FrameJobOrder;
        DISABLE TRIGGER Customers.tr_FrameJobOrderDetail ON Customers.t_FrameJobOrderDetail;

        BEGIN --Rebuild statistics

            SET @Return = 0;

            UPDATE  Customers.t_FrameJobOrder
            SET     RefF = FORMAT(Ref, '#') ,
                    Customer = Customers.f_CustomerGetName(CustomerID) ,
                    Doctor = Company.f_DoctorGetName(DoctorID) ,
                    Salesperson = Employees.f_SalesPersonGetName(SalespersonID) ,
                    StatesIs = Location.f_StatesGetName(StatesID) ,
                    RegionIs = Location.f_RegionGetName(RegionID) ,
                    Street = Location.f_StreetGetName(StreetID) ,
                    Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
                    SubTotalF = Currencys.f_Format(CurrencyID, SubTotal) ,
                    DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
                    TaxRateF = Currencys.f_FormatRate(0) ,
                    TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
                    TotalF = Currencys.f_Format(CurrencyID, Total) ,
                    PaymentF = Currencys.f_Format(CurrencyID, Payment) ,
                    RestF = Currencys.f_Format(CurrencyID, Rest) ,
                    CostF = Currencys.f_Format(CurrencyID, Cost) ,
                    ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
                    ItemsNames = Alls.f_FixXML(( SELECT DISTINCT
                                                        ', ' + t1.Name AS [text()]
                                                 FROM   Customers.t_FrameJobOrderDetail AS t
                                                        LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                                 WHERE  t.FrameJobOrderID = t_FrameJobOrder.ID
                                               FOR
                                                 XML PATH('')
                                               ));

            UPDATE  Customers.t_FrameJobOrder
            SET     AddressIs = Location.f_ConcetFullAddress(StatesIs, RegionIs, Street, N'', N'', N'', N'', ' - ', ' - ');

            UPDATE  Customers.t_FrameJobOrder
            SET     TaxRateF = Currencys.f_FormatRate(( TaxValue / ( Total - TaxValue ) ) * 100.0)
            WHERE   Total > 0;

            WITH    o AS ( SELECT   s.Sale ,
                                    s.SaleF ,
                                    s.DiscountIs ,
                                    s.DiscountIsF ,
                                    s.DiscountIsValue ,
                                    s.DiscountIsValueF ,
                                    s.SubTotal ,
                                    s.SubTotalF ,
                                    s.DiscountOrder ,
                                    s.DiscountOrderF ,
                                    s.TaxRate ,
                                    s.TaxRateF ,
                                    s.TaxValue ,
                                    s.Total ,
                                    s.TotalF ,
                                    s.Cost ,
                                    s.CostF ,
                                    s.TotalCost ,
                                    s.TotalCostF ,
                                    s.Profit ,
                                    s.ProfitF ,
                                    s.ProfitTotal ,
                                    s.ProfitTotalF ,
                                    s1.CurrencyID ,
                                    s.Qty ,
                                    s.Qtys ,
                                    s.QtyWithUnity ,
                                    s3.Name AS Unity
                           FROM     Customers.t_FrameJobOrderDetail AS s
                                    LEFT JOIN Customers.t_FrameJobOrder AS s1 ON s1.ID = s.FrameJobOrderID
                                    LEFT JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                                    LEFT JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                         )
                UPDATE  o
                SET     o.SaleF = Currencys.f_Format(o.CurrencyID, o.Sale) ,
                        o.DiscountIsF = Currencys.f_FormatRate(o.DiscountIs) ,
                        o.DiscountIsValueF = Currencys.f_Format(o.CurrencyID, o.DiscountIsValue) ,
                        o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
                        o.DiscountOrderF = Currencys.f_Format(o.CurrencyID, o.DiscountOrder) ,
                        o.TaxRateF = Currencys.f_FormatRate(o.TaxRate) ,
                        o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
                        o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost) ,
                        o.TotalCostF = Currencys.f_Format(o.CurrencyID, o.TotalCost) ,
                        o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
                        o.ProfitTotalF = Currencys.f_Format(o.CurrencyID, o.ProfitTotal) ,
                        o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT  INTO Customers.t_FrameJobOrderMoving
                    ( UserID ,
                      SectionID ,
                      EventIs ,
                      EventType ,
                      ComputerIP ,
                      Computer ,
                      ComputerAccount
                    )
            VALUES  ( @UserID ,
                      '00000000-0000-0000-0000-000000000000' ,
                      @Event ,
                      6 ,
                      @ComputerIP ,
                      @Computer ,
                      @ComputerAccount
                    );

        END;

        BEGIN --Live

            UPDATE  Alls.t_LiveVersion
            SET     VersionLive = STUFF(VersionLive, FrameJobOrder, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
                    SchemasIs = STUFF(SchemasIs, SchemaCustomer, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        ENABLE TRIGGER Customers.tr_FrameJobOrder ON Customers.t_FrameJobOrder;
        ENABLE TRIGGER Customers.tr_FrameJobOrderDetail ON Customers.t_FrameJobOrderDetail;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;







GO
/****** Object:  StoredProcedure [Customers].[s_FrameJobOrderUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Customers].[s_FrameJobOrderUpdate] @RefPaper NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @DateDelivery DATETIME ,
  @PriorityLevel TINYINT ,
  @CustomerID UNIQUEIDENTIFIER ,
  @DoctorID UNIQUEIDENTIFIER ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @StatesID UNIQUEIDENTIFIER ,
  @RegionID UNIQUEIDENTIFIER ,
  @StreetID UNIQUEIDENTIFIER ,
  @Focal NVARCHAR(MAX) ,
  @WithRight BIT ,
  @WithLeft BIT ,
  @SphereRight DECIMAL(18, 2) ,
  @SphereLeft DECIMAL(18, 2) ,
  @CylinderRight DECIMAL(18, 2) ,
  @CylinderLeft DECIMAL(18, 2) ,
  @AxisRight INT ,
  @AxisLeft INT ,
  @PrismRight INT ,
  @PrismLeft INT ,
  @BaseRight NVARCHAR(MAX) ,
  @BaseLeft NVARCHAR(MAX) ,
  @Addition DECIMAL(18, 2) ,
  @HeightRight INT ,
  @HeightLeft INT ,
  @PDRight DECIMAL(18, 2) ,
  @PDLeft DECIMAL(18, 2) ,
  @PD DECIMAL(18, 2) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DiscountIs FLOAT ,
  @CustomerAccountID UNIQUEIDENTIFIER ,
  @BoxID UNIQUEIDENTIFIER ,
  @Payment FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Customers.tt_FrameJobOrderDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventInsert NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @RefF NVARCHAR(MAX) ,
        @CustomerIDOld UNIQUEIDENTIFIER ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @LinkType INT = 169 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @SubTotal FLOAT ,
        @SubTotalD FLOAT ,
        @DiscountIsD FLOAT ,
        @TaxValue FLOAT ,
        @TaxValueD FLOAT ,
        @Total FLOAT ,
        @TotalD FLOAT ,
        @PaymentD FLOAT ,
        @Rest FLOAT ,
        @RestD FLOAT ,
        @CustomerAccount NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Cost FLOAT ,
        @CostD FLOAT ,
        @Profit FLOAT ,
        @ProfitD FLOAT ,
        @Qtys DECIMAL(18, 6) ,
        @ItemsNames NVARCHAR(MAX) ,
        @StatesIs NVARCHAR(MAX) ,
        @RegionIs NVARCHAR(MAX) ,
        @Street NVARCHAR(MAX) ,
        @AddressIs NVARCHAR(MAX) ,
        @User NVARCHAR(MAX) ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @RefF = s.RefF ,
          @CustomerIDOld = s.CustomerID
        FROM Customers.t_FrameJobOrder AS s
        WHERE s.ID = @ID;

      SELECT @SubTotal = COALESCE(SUM(s.SubTotal), 0) ,
          @TaxValue = COALESCE(SUM(s.TaxValue), 0) ,
          @Total = COALESCE(SUM(s.Total), 0) ,
          @Cost = COALESCE(SUM(s.Cost), 0) ,
          @Profit = COALESCE(SUM(s.Profit), 0) ,
          @Qtys = COALESCE(SUM(s.Qtys), 0)
        FROM @DetailIs AS s;
			 
      SET @CustomerAccount = Company.f_AccountGetName(@CustomerAccountID);
      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @SubTotalD = @SubTotal / @ExchangeRate;
      SET @DiscountIsD = @DiscountIs / @ExchangeRate;
      SET @TaxValueD = @TaxValue / @ExchangeRate;
      SET @TotalD = @Total / @ExchangeRate;
      SET @PaymentD = @Payment / @ExchangeRate;
      SET @Rest = @Total - @Payment;
      SET @RestD = @Rest / @ExchangeRate;
      SET @CostD = @Cost / @ExchangeRate;
      SET @ProfitD = @Profit / @ExchangeRate;
			
      SET @StatesIs = Location.f_StatesGetName(@StatesID); 
      SET @RegionIs = Location.f_RegionGetName(@RegionID); 
      SET @Street = Location.f_StreetGetName(@StreetID); 
      SET @AddressIs = Location.f_ConcetFullAddress(@StatesIs, @RegionIs, @Street, N'', N'', N'', N'', ' - ', '-');
           
      SET @User = Users.f_UserGetName(@UserID);

      SET @ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM @DetailIs AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                      FOR
                                        XML PATH('')
                                      ));
      
    END;

    BEGIN --Insert

      SET @return = 0;

      UPDATE Customers.t_FrameJobOrder
        SET RefPaper = @RefPaper ,
            DateIs = @DateIs ,
            DateDelivery = @DateDelivery ,
            PriorityLevel = @PriorityLevel ,
            CustomerID = @CustomerID ,
            Customer = Customers.f_CustomerGetName(@CustomerID) ,
            DoctorID = @DoctorID ,
            Doctor = Company.f_DoctorGetName(@DoctorID) ,
            SalespersonID = @SalespersonID ,
            Salesperson = Employees.f_SalesPersonGetName(@SalespersonID) ,
            StatesID = @StatesID ,
            StatesIs = @StatesIs ,
            RegionID = @RegionID ,
            RegionIs = @RegionIs ,
            StreetID = @StreetID ,
            Street = @Street ,
            AddressIs = @AddressIs ,
            Focal = @Focal ,
            WithRight = @WithRight ,
            WithLeft = @WithLeft ,
            SphereRight = @SphereRight ,
            SphereLeft = @SphereLeft ,
            CylinderRight = @CylinderRight ,
            CylinderLeft = @CylinderLeft ,
            AxisRight = @AxisRight ,
            AxisLeft = @AxisLeft ,
            PrismRight = @PrismRight ,
            PrismLeft = @PrismLeft ,
            BaseRight = @BaseRight ,
            BaseLeft = @BaseLeft ,
            Addition = @Addition ,
            HeightRight = @HeightRight ,
            HeightLeft = @HeightLeft ,
            PDRight = @PDRight ,
            PDLeft = @PDLeft ,
            PD = @PD ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            SubTotal = @SubTotal ,
            SubTotalF = Currencys.f_Format(@CurrencyID, @SubTotal) ,
            SubTotalD = @SubTotalD ,
            SubTotalLL = @SubTotalD * @ExchangeRateLL ,
            SubTotalEuro = @SubTotalD * @ExchangeRateEuro ,
            DiscountIs = @DiscountIs ,
            DiscountIsF = Currencys.f_Format(@CurrencyID, @DiscountIs) ,
            DiscountIsD = @DiscountIsD ,
            DiscountIsLL = @DiscountIsD * @ExchangeRateLL ,
            DiscountIsEuro = @DiscountIsD * @ExchangeRateEuro ,
            TaxValue = @TaxValue ,
            TaxValueF = Currencys.f_Format(@CurrencyID, @TaxValue) ,
            TaxValueD = @TaxValueD ,
            TaxValueLL = @TaxValueD * @ExchangeRateLL ,
            TaxValueEuro = @TaxValueD * @ExchangeRateEuro ,
            Total = @Total ,
            TotalF = Currencys.f_Format(@CurrencyID, @Total) ,
            TotalD = @TotalD ,
            TotalLL = @TotalD * @ExchangeRateLL ,
            TotalEuro = @TotalD * @ExchangeRateEuro ,
            Payment = @Payment ,
            PaymentF = Currencys.f_Format(@CurrencyID, @Payment) ,
            PaymentD = @PaymentD ,
            PaymentLL = @PaymentD * @ExchangeRateLL ,
            PaymentEuro = @PaymentD * @ExchangeRateEuro ,
            Rest = @Rest ,
            RestF = Currencys.f_Format(@CurrencyID, @Rest) ,
            RestD = @RestD ,
            RestLL = @RestD * @ExchangeRateLL ,
            RestEuro = @RestD * @ExchangeRateEuro ,
            Cost = @Cost ,
            CostF = Currencys.f_Format(@CurrencyID, @Cost) ,
            CostD = @CostD ,
            CostLL = @CostD * @ExchangeRateLL ,
            CostEuro = @CostD * @ExchangeRateEuro ,
            Profit = @Profit ,
            ProfitF = Currencys.f_Format(@CurrencyID, @Profit) ,
            ProfitD = @ProfitD ,
            ProfitLL = @ProfitD * @ExchangeRateLL ,
            ProfitEuro = @ProfitD * @ExchangeRateEuro ,
            Qtys = @Qtys ,
            ItemsNames = @ItemsNames ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Fix t_Customer

      UPDATE Customers.t_Customer
        SET FrameJobOrderC = Customers.f_FrameJobOrderGetCountByCustomerID(ID) ,
            FrameJobOrderTotal = Customers.[f_FrameJobOrderGetTotalByCustomerID](ID) ,
            FrameJobOrderProfit = Customers.[f_FrameJobOrderGetProfitByCustomerID](ID) ,
            FrameJobOrderLast = Customers.f_FrameJobOrderGetLastDateByCustomerID(ID)
        WHERE ID IN ( @CustomerID, @CustomerIDOld );

      WITH  o AS ( SELECT s1.CurrencyID ,
                      s.FrameJobOrderTotal ,
                      s.FrameJobOrderTotalF ,
                      s.FrameJobOrderProfit ,
                      s.FrameJobOrderProfitF
                    FROM Customers.t_Customer AS s
                    INNER JOIN Company.t_Account AS s1 ON s1.LinkWithID = s.ID AND s1.IsMasterLink = 1 AND s1.SectionID = 15
                    WHERE s.ID IN ( @CustomerID, @CustomerIDOld )
                 )
        UPDATE o
          SET o.FrameJobOrderTotalF = Currencys.f_Format(o.CurrencyID, o.FrameJobOrderTotal) ,
              o.FrameJobOrderProfitF = Currencys.f_Format(o.CurrencyID, o.FrameJobOrderProfit);

    END;

    BEGIN --Insert detail

      DELETE FROM Customers.t_FrameJobOrderDetail
        WHERE FrameJobOrderID = @ID;

      INSERT INTO Customers.t_FrameJobOrderDetail
          ( ID ,
            FrameJobOrderID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            ItemType ,
            Sale ,
            SaleF ,
            SaleD ,
            SaleLL ,
            SaleEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            DiscountOrder ,
            DiscountOrderF ,
            DiscountOrderD ,
            DiscountOrderLL ,
            DiscountOrderEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitTotal ,
            ProfitTotalF ,
            ProfitTotalD ,
            ProfitTotalLL ,
            ProfitTotalEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qtys ,
            s.ItemType ,
            s.Sale ,
            Currencys.f_Format(@CurrencyID, s.Sale) ,
            s.Sale / @ExchangeRate ,
            ( s.Sale / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Sale / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountIs ,
            Currencys.f_FormatRate(s.DiscountIs) ,
            s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
            s.DiscountIsValue / @ExchangeRate ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.SubTotal ,
            Currencys.f_Format(@CurrencyID, s.SubTotal) ,
            s.SubTotal / @ExchangeRate ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountOrder ,
            Currencys.f_Format(@CurrencyID, s.DiscountOrder) ,
            s.DiscountOrder / @ExchangeRate ,
            ( s.DiscountOrder / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountOrder / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TaxRate ,
            Currencys.f_FormatRate(s.TaxRate) ,
            s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.TaxValue) ,
            s.TaxValue / @ExchangeRate ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Cost ,
            Currencys.f_Format(@CurrencyID, s.Cost) ,
            s.Cost / @ExchangeRate ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TotalCost ,
            Currencys.f_Format(@CurrencyID, s.TotalCost) ,
            s.TotalCost / @ExchangeRate ,
            ( s.TotalCost / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.TotalCost / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Profit ,
            Currencys.f_Format(@CurrencyID, s.Profit) ,
            s.Profit / @ExchangeRate ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
            s.ProfitTotal ,
            Currencys.f_Format(@CurrencyID, s.ProfitTotal) ,
            s.ProfitTotal / @ExchangeRate ,
            ( s.ProfitTotal / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.ProfitTotal / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Rebuild statistics

      UPDATE Customers.t_FrameJobOrder
        SET TaxRate = ( TaxValue / ( Total - TaxValue ) ) * 100.0 ,
            TaxRateF = Currencys.f_FormatRate(( TaxValue / ( Total - TaxValue ) ) * 100.0)
        WHERE ID = @ID AND Total > 0;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Customers.t_FrameJobOrderMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Delete old Transaction
  							           
      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = @LinkType AND LinkID = @ID;

    END;

    IF @Payment > 0
    BEGIN --Transaction
		
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID 
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'RV' ,
              @DateIs ,
              N'FJB:' + @RefF ,
              @LinkType ,
              0 ,
              @ID ,
              @UserID 
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @CID = @CurrencyID;
        SET @E = @ExchangeRate;
        SET @ELL = @ExchangeRateLL;
        SET @EEuro = @ExchangeRateEuro;
        SET @V = @Payment;
        SET @VD = @PaymentD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL , ExchangeRateEuro  )
          VALUES  ( 1, @TransactionID, @BoxID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'FJB:' + @RefF + ' \ ' + @CustomerAccount, @CID, @E, @ELL, @EEuro ),
                  ( 2, @TransactionID, @CustomerAccountID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'FJB:' + @RefF, @CID, @E, @ELL, @EEuro  );

      END;

      BEGIN --Insert t_TransactionMoving

        SET @return = -1;

        INSERT INTO Transactions.t_TransactionMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          SELECT @UserID ,
              @TransactionID ,
              @EventInsert + s.RefF ,
              0 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            FROM @TrnIDs AS s;

      END;

      BEGIN --Fix data

        UPDATE Company.t_Account
          SET StatusIs = 0 ,
              LastAction = GETDATE()
          WHERE ID IN ( @BoxID, @CustomerID ) AND StatusIs = 1;
  
        DECLARE @TrnIDsFix AS Alls.tt_Guid;
        INSERT INTO @TrnIDsFix
            ( ID )
          SELECT s.ID
            FROM @TrnIDs AS s;

        EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

      END;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;






GO
