GO
CREATE PROCEDURE [Customers].[s_InternetPackageDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete

      DELETE FROM Customers.t_InternetPackage
        WHERE ID = @ID;

    END;

    EXECUTE Alls.s_FireStoreRowsForDeleteInsertPART @ID, 0, 'internetPackage'; 

    SET @Return = -1;
    EXECUTE Customers.s_InternetPackageMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Customers.s_InternetPackageLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;


