/****** Object:  StoredProcedure [Customers].[s_InternetPackageInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_InternetPackageInsert] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @PeriodType TINYINT ,
  @PeriodNumber INT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Cost FLOAT ,
  @CostF NVARCHAR(MAX) ,
  @CostD FLOAT ,
  @CostLL FLOAT ,
  @CostEuro FLOAT ,
  @Price FLOAT ,
  @PriceF NVARCHAR(MAX) ,
  @PriceD FLOAT ,
  @PriceLL FLOAT ,
  @PriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;
					
    END;

    BEGIN --Insert

      INSERT INTO Customers.t_InternetPackage
          ( ID ,
            Name ,
            PeriodType ,
            PeriodNumber ,
            CurrencyID ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            DescriptionIs ,
            CreatedByUserID
          )
        VALUES
          ( @ID ,
            @Name ,
            @PeriodType ,
            @PeriodNumber ,
            @CurrencyID ,
            @Cost ,
            @CostF ,
            @CostD ,
            @CostLL ,
            @CostEuro ,
            @Price ,
            @PriceF ,
            @PriceD ,
            @PriceLL ,
            @PriceEuro ,
            @Profit ,
            @ProfitF ,
            @ProfitD ,
            @ProfitLL ,
            @ProfitEuro ,
            @DescriptionIs ,
            @UserID
          );

    END;

    SET @Return = -1;
    EXECUTE Customers.s_InternetPackageMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Customers.s_InternetPackageLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





