/****** Object:  StoredProcedure [Customers].[s_InternetPackageUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_InternetPackageUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @PeriodType TINYINT ,
  @PeriodNumber INT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Cost FLOAT ,
  @CostF NVARCHAR(MAX) ,
  @CostD FLOAT ,
  @CostLL FLOAT ,
  @CostEuro FLOAT ,
  @Price FLOAT ,
  @PriceF NVARCHAR(MAX) ,
  @PriceD FLOAT ,
  @PriceLL FLOAT ,
  @PriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0 ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Customers.t_InternetPackage AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Customers.t_InternetPackage
        SET Name = @Name ,
            PeriodType = @PeriodType ,
            PeriodNumber = @PeriodNumber ,
            CurrencyID = @CurrencyID ,
            Cost = @Cost ,
            CostF = @CostF ,
            CostD = @CostD ,
            CostLL = @CostLL ,
            CostEuro = @CostEuro ,
            Price = @Price ,
            PriceF = @PriceF ,
            PriceD = @PriceD ,
            PriceLL = @PriceLL ,
            PriceEuro = @PriceEuro ,
            Profit = @Profit ,
            ProfitF = @ProfitF ,
            ProfitD = @ProfitD ,
            ProfitLL = @ProfitLL ,
            ProfitEuro = @ProfitEuro ,
            DescriptionIs = @DescriptionIs ,
            LastModifiedDate = GETDATE() ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Customers.s_InternetPackageMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Customers.s_InternetPackageLiveVersion;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --t_Customer

        UPDATE Customers.t_Customer
          SET InternetPackage = @Name
          WHERE InternetPackageID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



