/****** Object:  StoredProcedure [Customers].[s_TitleInsertDefaultData]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Customers].[s_TitleInsertDefaultData]
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Check

            IF EXISTS (SELECT TOP (1) ID FROM Customers.t_Title)
            BEGIN
			
                COMMIT TRAN;

                RETURN 1;

