      SET @Return = 0;

      UPDATE  Customers.t_Title
      SET     CustomerC = ( SELECT  COUNT(*)
                            FROM    Customers.t_Customer AS s
                            WHERE   s.TitleID = t_Title.ID
                          ) ,
