            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            2 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;
















