/****** Object:  StoredProcedure [Employees].[s_BonusRestoreFromArchive]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_BonusRestoreFromArchive] @IDs Alls.tt_IDAndEvent READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert t_Bonus

      INSERT INTO Employees.t_Bonus
          ( ID ,
            Ref ,
            RefF ,
            DateIs ,
            EmployeeID ,
            Employee ,
            TypeID ,
            TypeIs ,
            FromEmployeeID ,
            FromEmployee ,
            ImplementationIn ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ValueIs ,
            ValueIsF ,
            ValueIsD ,
            ValueIsLL ,
            ValueIsEuro ,
            ValueIsAR ,
            ValueIsEN ,
            Why ,
            StatusIs ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.DateIs ,
            t.EmployeeID ,
            t.Employee ,
            t.TypeID ,
            t.TypeIs ,
            t.FromEmployeeID ,
            t.FromEmployee ,
            t.ImplementationIn ,
            t.CurrencyID ,
            t.Currency ,
            t.ExchangeRate ,
            t.ValueIs ,
            t.ValueIsF ,
            t.ValueIsD ,
            t.ValueIsLL ,
            t.ValueIsEuro ,
            t.ValueIsAR ,
            t.ValueIsEN ,
            t.Why ,
            0 ,
            t.DateCreate ,
            t.WorkStationID
          FROM Employees.t_BonusHistory AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Delete t_BonusHistory

      DELETE FROM Employees.t_BonusHistory
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_BonusHistory.ID );

    END;
	
    BEGIN --Insert t_BonusMoving

      SET @Return = -1;

      INSERT INTO Employees.t_BonusMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            2 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

















