            );

            DECLARE @Return INT;

        END;

        BEGIN --Insert

            SET @Return = 0;

            INSERT INTO Employees.t_BonusType
            (
                Name,
                DescriptionIs
            )
            OUTPUT Inserted.ID
            INTO @IDs
            (
