/****** Object:  StoredProcedure [Employees].[s_EmployeeAddVacationPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_EmployeeAddVacationPART] @ID UNIQUEIDENTIFIER ,
  @NewDays INT
AS
BEGIN

  BEGIN --Declare

    DECLARE @Return INT = 0;

  END;
  
  BEGIN --Update t_Employee

    UPDATE Employees.t_Employee
      SET VacationAvailableC += @NewDays ,
          IsSync = 0
      WHERE ID = @ID;

  END;

END;




GO
/****** Object:  StoredProcedure [Employees].[s_EmployeeAddVacationsPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_EmployeeAddVacationsPART] @Vacations Employees.tt_Vacation READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @t AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        VacationNet BIGINT NOT NULL
      );

    DECLARE @Return INT = 0;

  END;
  
  BEGIN --Set
    
    INSERT INTO @t
        ( ID ,
          VacationNet
	    )
      SELECT o.EmployeeID ,
          COALESCE(SUM(o.VacationAddC), 0) - COALESCE(SUM(o.VacationUseC), 0)
        FROM ( SELECT s.EmployeeID ,
                  IIF(s.OperationType = 0, s.DaysIs, 0) AS VacationAddC ,
                  IIF(s.OperationType = 1, s.DaysIs, 0) AS VacationUseC
                FROM @Vacations AS s
             ) AS o
        GROUP BY o.EmployeeID;

  END;

  BEGIN --Rebuild t_Employee

    MERGE Employees.t_Employee AS t
    USING @t AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.VacationAvailableC += s.VacationNet ,
                  t.IsSync = 0;

  END;

END;





