/****** Object:  StoredProcedure [Employees].[s_EmployeeDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_EmployeeDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION employeeDelete;

    BEGIN --Declare

      DECLARE @TypeID UNIQUEIDENTIFIER ,
        @ProfessionID UNIQUEIDENTIFIER ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @TypeID = s.TypeID ,
          @ProfessionID = s.ProfessionID
        FROM Employees.t_Employee AS s
        WHERE s.ID = @ID;

    END;

    EXECUTE Transactions.s_TransactionDetailByDaysReinsertPART;

    BEGIN --Delete account

      SET @Return = -3;

      DELETE FROM Company.t_Account
        WHERE SectionID = 33 AND LinkWithID = @ID;

    END;

    BEGIN --Delete phones 

      DELETE FROM Company.t_BookPhone
        WHERE SectionID = 33 AND OwnerID = @ID;

    END;

    BEGIN --Delete SocialMedia 

      DELETE FROM Company.t_SocialMedia
        WHERE SectionID = 33 AND OwnerID = @ID;

    END;

    BEGIN --Delete File Storage Linked 

      DELETE FROM Company.t_FileStorageLinked
        WHERE SectionID = 33 AND OwnerID = @ID;

    END;

    BEGIN --Delete

      SET @Return = 0;

      DELETE FROM Employees.t_Employee
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Employees.t_EmployeeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Employees.s_EmployeeTypeEmployeesCountRebuildPART @TypeID;
    EXECUTE Employees.s_ProfessionsEmployeesCountRebuildPART @ProfessionID;

    COMMIT TRANSACTION employeeDelete;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK TRANSACTION employeeDelete;

    RETURN @Return;

  END CATCH;

END;













GO
/****** Object:  StoredProcedure [Employees].[s_EmployeeExecuteJobAgeIs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_EmployeeExecuteJobAgeIs]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Employees_Employee_AgeIs < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    DISABLE TRIGGER Employees.tr_Employee ON Employees.t_Employee;

    BEGIN --Update 

      UPDATE Employees.t_Employee
        SET AgeIs = DateTimes.f_GetAge(Birthday) ,
            TotalAttendancesHoursLastMonth = Employees.f_EmployeeGetTotalAttendancesHoursLastMonth(ID) ,
            TotalAttendancesHoursThisMonth = Employees.f_EmployeeGetTotalAttendancesHoursThisMonth(ID);

      UPDATE Employees.t_Employee
        SET TotalRemainingAttendanceHoursLastMonth = TotalAttendancesHoursLastMonth - TotalHoursMustWork ,
            TotalRemainingAttendanceHoursThisMonth = TotalAttendancesHoursThisMonth - TotalHoursMustWork;
   
    END;

    ENABLE TRIGGER Employees.tr_Employee ON Employees.t_Employee;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Employees_Employee_AgeIs = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Employees].[s_EmployeeFormat]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_EmployeeFormat] @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Rebuilding statistics

      UPDATE Employees.t_Employee
        SET AgeIs = DateTimes.f_GetAge(Birthday) ,
            TypeIs = Employees.f_EmployeeTypeGetName(TypeID) ,
            Nationality = Employees.f_NationalityGetName(NationalityID) ,
            StatesIs = Location.f_StatesGetName(StatesID) ,
            RegionIs = Location.f_RegionGetName(RegionID) ,
            Street = Location.f_StreetGetName(StreetID) ,
            Building = Location.f_BuildingGetName(BuildingID) ,
            FloorIs = Location.f_FloorGetName(FloorID) ,
            PostalCode = Location.f_PostalCodeGetName(PostalCodeID) ,
            FirstSalaryF = Currencys.f_Format(FirstSalaryCurrencyID, FirstSalary) ,
            WageF = Currencys.f_Format(FirstSalaryCurrencyID, Wage) ,
            BonusF = Currencys.f_Format(FirstSalaryCurrencyID, Bonus) ,
            RentAllowanceF = Currencys.f_Format(FirstSalaryCurrencyID, RentAllowance) ,
            TransferAllowanceF = Currencys.f_Format(FirstSalaryCurrencyID, TransferAllowance) ,
            NSSFAmountF = Currencys.f_Format(FirstSalaryCurrencyID, NSSFAmount) ,
            SecondSalaryF = Currencys.f_Format(SecondSalaryCurrencyID, SecondSalary) ,
            FinalSalary = FirstSalary + Wage + Bonus + RentAllowance + TransferAllowance - NSSFAmount + Currencys.f_CurrencyExchangeTo(SecondSalaryCurrencyID, FirstSalaryCurrencyID, SecondSalary) ,
            SalaryDeliveryServiceF = Currencys.f_Format(FirstSalaryCurrencyID, SalaryDeliveryService) ,
            SalaryHoursF = Currencys.f_Format(FirstSalaryCurrencyID, SalaryHours) ,
            Phones = Alls.f_FixXML(( SELECT N', ' + t.NumberIs + CASE t.ExtensionIs
                                                                   WHEN N'' THEN N''
                                                                   ELSE N': ' + t.ExtensionIs
                                                                 END AS [text()]
                                      FROM Company.t_BookPhone AS t
                                      WHERE t.OwnerID = t_Employee.ID AND t.SectionID = 33
                                   FOR
                                     XML PATH('')
                                   )) ,
            PhonesC = ( SELECT COUNT(t.ID)
                          FROM Company.t_BookPhone AS t
                          WHERE t.OwnerID = t_Employee.ID AND t.SectionID = 33
                      ) ,
            SocialMedia = Alls.f_FixXML(( SELECT N', ' + t.AccountIs AS [text()]
                                            FROM Company.t_SocialMedia AS t
                                            WHERE t.OwnerID = t_Employee.ID AND t.SectionID = 33
                                        FOR
                                          XML PATH('')
                                        )) ,
            SocialMediaC = ( SELECT COUNT(t.ID)
                              FROM Company.t_SocialMedia AS t
                              WHERE t.OwnerID = t_Employee.ID AND t.SectionID = 33
                           )
        WHERE ID = @ID;

      UPDATE Employees.t_Employee
        SET FinalSalaryF = Currencys.f_Format(FirstSalaryCurrencyID, FinalSalary) ,
            AddressIs = Location.f_ConcetFullAddress(StatesIs, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
        WHERE ID = @ID;

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;






