/****** Object:  StoredProcedure [Employees].[s_EmployeeRebuild_AttendancesHours_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_EmployeeRebuild_AttendancesHours_PART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  UPDATE Employees.t_Employee
    SET TotalAttendancesHoursLastMonth = Employees.f_EmployeeGetTotalAttendancesHoursLastMonth(ID) ,
        TotalAttendancesHoursThisMonth = Employees.f_EmployeeGetTotalAttendancesHoursThisMonth(ID)
    WHERE ID = @ID;

  UPDATE Employees.t_Employee
    SET TotalRemainingAttendanceHoursLastMonth = TotalAttendancesHoursLastMonth - TotalHoursMustWork ,
        TotalRemainingAttendanceHoursThisMonth = TotalAttendancesHoursThisMonth - TotalHoursMustWork
    WHERE ID = @ID;

END;



GO
