/****** Object:  StoredProcedure [Employees].[s_EmployeeUpdateSalaryAndShift]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_EmployeeUpdateSalaryAndShift] @DateWork DATE ,
  @IDFingerPrint INT ,
  @FirstSalaryCurrencyID UNIQUEIDENTIFIER ,
  @FirstSalary FLOAT ,
  @FirstSalaryF NVARCHAR(MAX) ,
  @Wage FLOAT ,
  @WageF NVARCHAR(MAX) ,
  @Bonus FLOAT ,
  @BonusF NVARCHAR(MAX) ,
  @RentAllowance FLOAT ,
  @RentAllowanceF NVARCHAR(MAX) ,
  @TransferAllowance FLOAT ,
  @TransferAllowanceF NVARCHAR(MAX) ,
  @NSSFAmount FLOAT ,
  @NSSFAmountF NVARCHAR(MAX) ,
  @SecondSalaryCurrencyID UNIQUEIDENTIFIER ,
  @SecondSalary FLOAT ,
  @SecondSalaryF NVARCHAR(MAX) ,
  @FinalSalary FLOAT ,
  @FinalSalaryF NVARCHAR(MAX) ,
  @SalaryDeliveryService FLOAT ,
  @NSSF BIT ,
  @NSSFDate DATE ,
  @FamilyMembersCount INT ,
  @FamilyMembersNames NVARCHAR(MAX) ,
  @DaysWork INT ,
  @DaysWorkHours FLOAT ,
  @TotalHoursFree INT ,
  @SalaryHours FLOAT ,
  @SalaryHoursF NVARCHAR(MAX) ,
  @VacationDay TINYINT ,
  @HoursLateX DECIMAL(4, 2) ,
  @HoursOverX DECIMAL(4, 2) ,
  @CalculationEarly BIT ,
  @CalculationOverTime BIT ,
  @ShiftFrom TIME(7) ,
  @ShiftTo TIME(7) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0 ,
        @FirstSalaryCurrencyIDOld UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FirstSalaryCurrencyIDOld = s.FirstSalaryCurrencyID
        FROM Employees.t_Employee AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update 

      UPDATE Employees.t_Employee
        SET DateWork = @DateWork ,
            IDFingerPrint = @IDFingerPrint ,
            FirstSalaryCurrencyID = @FirstSalaryCurrencyID ,
            FirstSalary = @FirstSalary ,
            FirstSalaryF = @FirstSalaryF ,
            Wage = @Wage ,
            WageF = @WageF ,
            Bonus = @Bonus ,
            BonusF = @BonusF ,
            RentAllowance = @RentAllowance ,
            RentAllowanceF = @RentAllowanceF ,
            TransferAllowance = @TransferAllowance ,
            TransferAllowanceF = @TransferAllowanceF ,
            NSSFAmount = @NSSFAmount ,
            NSSFAmountF = @NSSFAmountF ,
            SecondSalaryCurrencyID = @SecondSalaryCurrencyID ,
            SecondSalary = @SecondSalary ,
            SecondSalaryF = @SecondSalaryF ,
            FinalSalary = @FinalSalary ,
            FinalSalaryF = @FinalSalaryF ,
            SalaryDeliveryService = @SalaryDeliveryService ,
            SalaryDeliveryServiceF = Currencys.f_Format(@FirstSalaryCurrencyID, @SalaryDeliveryService) ,
            NSSF = @NSSF ,
            NSSFDate = @NSSFDate ,
            FamilyMembersCount = @FamilyMembersCount ,
            FamilyMembersNames = @FamilyMembersNames ,
            DaysWork = @DaysWork ,
            DaysWorkHours = @DaysWorkHours ,
            TotalHoursMustWork = ( @DaysWorkHours * @DaysWork ) - @TotalHoursFree ,
            TotalHoursFree = @TotalHoursFree ,
            SalaryHours = @SalaryHours ,
            SalaryHoursF = @SalaryHoursF ,
            VacationDay = @VacationDay ,
            HoursLateX = @HoursLateX ,
            HoursOverX = @HoursOverX ,
            CalculationEarly = @CalculationEarly ,
            CalculationOverTime = @CalculationOverTime ,
            ShiftFrom = @ShiftFrom ,
            ShiftTo = @ShiftTo
        WHERE ID = @ID;

    END;

    IF @FirstSalaryCurrencyIDOld <> @FirstSalaryCurrencyID
    BEGIN --Update DiscountAvailable and BonusAvailable

      UPDATE Employees.t_Employee
        SET DiscountAvailable = ( SELECT COALESCE(SUM(CASE s1.TypeIs
                                                        WHEN 0 THEN s.ValueIsD
                                                        WHEN 1 THEN s.ValueIsLL
                                                        ELSE s.ValueIsEuro
                                                      END), 0) AS DiscountAvailable
                                    FROM Employees.t_Discount AS s
                                    LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = t_Employee.FirstSalaryCurrencyID
                                    WHERE s.EmployeeID = t_Employee.ID
                                ) ,
            BonusAvailable = ( SELECT COALESCE(SUM(CASE s1.TypeIs
                                                     WHEN 0 THEN s.ValueIsD
                                                     WHEN 1 THEN s.ValueIsLL
                                                     ELSE s.ValueIsEuro
                                                   END), 0) AS BonusAvailable
                                FROM Employees.t_Bonus AS s
                                LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = t_Employee.FirstSalaryCurrencyID
                                WHERE s.EmployeeID = t_Employee.ID
                             )
        WHERE ID = @ID;

      UPDATE Employees.t_Employee
        SET DiscountAvailableF = Currencys.f_Format(FirstSalaryCurrencyID, DiscountAvailable) ,
            BonusAvailableF = Currencys.f_Format(FirstSalaryCurrencyID, BonusAvailable)
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_EmployeeMoving

      SET @Return = -1;

      INSERT INTO Employees.t_EmployeeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









GO
