GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_FingerPrint_CHECKINOUT_Updates_IsDownloaded] @FingerPrintIDs Alls.td_IDBigint READONLY ,
  @FromDate DATE
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Update

      UPDATE Employees.v_FingerPrint_CHECKINOUT
        SET IsDownloaded = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @FingerPrintIDs AS s
                        WHERE s.ID = v_FingerPrint_CHECKINOUT.USERID ) AND CONVERT(DATE, CHECKTIME) >= @FromDate AND IsDownloaded = 1;
   
    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;



