/****** Object:  StoredProcedure [Employees].[s_SalesPerson_Increment_CommissionAvailable_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_SalesPerson_Increment_CommissionAvailable_PART] @ID UNIQUEIDENTIFIER ,
  @CommissionAvailableValueD FLOAT ,
  @CommissionAvailableValueLL FLOAT ,
  @CommissionAvailableValueEuro FLOAT
AS
BEGIN

  UPDATE Employees.t_SalesPerson
    SET CommissionAvailableValueD += @CommissionAvailableValueD ,
        CommissionAvailableValueDF = Currencys.f_FormatD(CommissionAvailableValueD + @CommissionAvailableValueD) ,
        CommissionAvailableValueLL += @CommissionAvailableValueLL ,
        CommissionAvailableValueLLF = Currencys.f_FormatLL(CommissionAvailableValueLL + @CommissionAvailableValueLL) ,
        CommissionAvailableValueEuro += @CommissionAvailableValueEuro ,
        CommissionAvailableValueEuroF = Currencys.f_FormatEuro(CommissionAvailableValueEuro + @CommissionAvailableValueEuro)
    WHERE ID = @ID;

END;



GO
/****** Object:  StoredProcedure [Employees].[s_SalesPerson_Increments_CommissionAvailable_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_SalesPerson_Increments_CommissionAvailable_PART] @drs Employees.tt_SalesPerson_Increment_CommissionAvailable READONLY
AS
BEGIN
 
  DECLARE @drs1 Employees.tt_SalesPerson_Increment_CommissionAvailable;

  INSERT INTO @drs1
      ( ID ,
        ValueD ,
        ValueLL ,
        ValueEuro
      )
    SELECT ID ,
        COALESCE(SUM(ValueD), 0) ,
        COALESCE(SUM(ValueLL), 0) ,
        COALESCE(SUM(ValueEuro), 0)
      FROM @drs
      GROUP BY ID;

  MERGE Employees.t_SalesPerson AS t
  USING @drs1 AS s
  ON s.ID = t.ID
  WHEN MATCHED THEN
    UPDATE SET t.CommissionAvailableValueD += s.ValueD ,
                t.CommissionAvailableValueDF = Currencys.f_FormatD(t.CommissionAvailableValueD + s.ValueD) ,
                t.CommissionAvailableValueLL += s.ValueLL ,
                t.CommissionAvailableValueLLF = Currencys.f_FormatLL(t.CommissionAvailableValueLL + s.ValueLL) ,
                t.CommissionAvailableValueEuro += s.ValueEuro ,
                t.CommissionAvailableValueEuroF = Currencys.f_FormatEuro(t.CommissionAvailableValueEuro + s.ValueEuro);

END;





GO
