/****** Object:  StoredProcedure [Employees].[s_SalesPersonUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_SalesPersonUpdate] @Name NVARCHAR(450) ,
  @StatesID UNIQUEIDENTIFIER ,
  @RegionID UNIQUEIDENTIFIER ,
  @StreetID UNIQUEIDENTIFIER ,
  @BuildingID UNIQUEIDENTIFIER ,
  @FloorID UNIQUEIDENTIFIER ,
  @PostalCodeID UNIQUEIDENTIFIER ,
  @AddressNote NVARCHAR(MAX) ,
  @CommissionRate DECIMAL(4, 2) ,
  @CommissionRateType TINYINT ,
  @CommissionRateOn TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450) ,
        @AccountID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Employees.t_SalesPerson AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;
      UPDATE Employees.t_SalesPerson
        SET Name = @Name ,
            StatesID = @StatesID ,
            RegionID = @RegionID ,
            StreetID = @StreetID ,
            BuildingID = @BuildingID ,
            FloorID = @FloorID ,
            PostalCodeID = @PostalCodeID ,
            AddressNote = @AddressNote ,
            CommissionRate = @CommissionRate ,
            CommissionRateType = @CommissionRateType ,
            CommissionRateOn = @CommissionRateOn ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Format

      EXECUTE [Employees].s_SalesPersonFormat @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Employees.t_SalesPersonMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --t_Account

        UPDATE Company.t_Account
          SET LinkWith = @Name ,
              Name = @Name
          WHERE SectionID = 149 AND LinkWithID = @ID;

      END;

      BEGIN --t_Account

        UPDATE Company.t_Account
          SET LinkWith = @Name ,
              Name = @Name + ' (عمولات البيع)'
          WHERE SectionID = 149 AND LinkWithID = @ID AND NumberIs BETWEEN 7010800000 AND 7010899999;

      END;

      BEGIN --t_Customer

        UPDATE Customers.t_Customer
          SET SalesPerson = @Name
          WHERE SalesPersonID = @ID;

      END;

      BEGIN; --t_FrameJobOrder

        UPDATE Customers.t_FrameJobOrder
          SET Salesperson = @Name
          WHERE SalespersonID = @ID;

      END;
     
      BEGIN; --t_FrameJobOrderHistory

        UPDATE Customers.t_FrameJobOrderHistory
          SET Salesperson = @Name
          WHERE SalespersonID = @ID;

      END;

      BEGIN --Set info

        SELECT TOP ( 1 ) @AccountID = s.ID
          FROM Company.t_Account AS s
          WHERE SectionID = 149 AND LinkWithID = @ID
          ORDER BY s.ID;

      END;

      BEGIN; --t_Purchasing

        UPDATE Invoices.t_Purchasing
          SET AccountVendor = @Name
          WHERE AccountVendorID = @AccountID;
				
        UPDATE Invoices.t_Purchasing
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;
				
        UPDATE Invoices.t_Purchasing
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @AccountID;

      END;

      BEGIN; --t_PurchasingDeleted

        UPDATE Invoices.t_PurchasingDeleted
          SET AccountVendor = @Name
          WHERE AccountVendorID = @AccountID;
				
        UPDATE Invoices.t_PurchasingDeleted
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;
				
        UPDATE Invoices.t_PurchasingDeleted
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @AccountID;

      END;

      BEGIN; --t_PurchasingReturn

        UPDATE Invoices.t_PurchasingReturn
          SET AccountVendor = @Name
          WHERE AccountVendorID = @AccountID;

        UPDATE Invoices.t_PurchasingReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;

      END;

      BEGIN; --t_Sold

        UPDATE Invoices.t_Sold
          SET AccountCustomer = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountCustomerID = @AccountID;

        UPDATE Invoices.t_Sold
          SET AccountBox = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE AccountBoxID = @AccountID;
				
        UPDATE Invoices.t_Sold
          SET SecondPaymentAccountBox = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE SecondPaymentAccountBoxID = @AccountID;

        UPDATE Invoices.t_Sold
          SET Salesperson = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE SalespersonID = @ID;

      END;

      BEGIN; --t_SoldDeleted

        UPDATE Invoices.t_SoldDeleted
          SET AccountCustomer = @Name
          WHERE AccountCustomerID = @AccountID;
				
        UPDATE Invoices.t_SoldDeleted
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;
				
        UPDATE Invoices.t_SoldDeleted
          SET SecondPaymentAccountBox = @Name
          WHERE SecondPaymentAccountBoxID = @AccountID;

        UPDATE Invoices.t_SoldDeleted
          SET Salesperson = @Name
          WHERE SalespersonID = @ID;

      END;

      BEGIN; --t_SoldReturn

        UPDATE Invoices.t_SoldReturn
          SET AccountCustomer = @Name
          WHERE AccountCustomerID = @AccountID;

        UPDATE Invoices.t_SoldReturn
          SET AccountBox = @Name
          WHERE AccountBoxID = @AccountID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









GO
/****** Object:  StoredProcedure [Employees].[s_SalesPersonUpdateAddress]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_SalesPersonUpdateAddress]
    @StatesID UNIQUEIDENTIFIER,
    @RegionID UNIQUEIDENTIFIER,
    @StreetID UNIQUEIDENTIFIER,
    @UserID UNIQUEIDENTIFIER,
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
    BEGIN TRY

    SET ANSI_WARNINGS OFF;

        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Update 

            SET @Return = 0;

            UPDATE Employees.t_SalesPerson
            SET StatesID = @StatesID,
                StatesIs = Location.f_StatesGetName(@StatesID),
                RegionID = @RegionID,
                RegionIs = Location.f_RegionGetName(@RegionID),
                StreetID = @StreetID,
                Street = Location.f_StreetGetName(@StreetID)
            WHERE EXISTS
            (
                SELECT TOP (1) s.ID FROM @IDAndEvent AS s WHERE s.ID = t_SalesPerson.ID
            );

            UPDATE Employees.t_SalesPerson
            SET AddressIs = Location.f_ConcetFullAddress(
                                                            StatesIs,
                                                            RegionIs,
                                                            Street,
                                                            Building,
                                                            FloorIs,
                                                            PostalCode,
                                                            AddressNote,
                                                            ' - ',
                                                            '-'
                                                        )
            WHERE EXISTS
            (
                SELECT TOP (1) s.ID FROM @IDAndEvent AS s WHERE s.ID = t_SalesPerson.ID
            );

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Employees.t_SalesPersonMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            SELECT @UserID,
                   s.ID,
                   s.EventIs,
                   1,
                   @ComputerIP,
                   @Computer,
                   @ComputerAccount
            FROM @IDAndEvent AS s;

        END;

        COMMIT TRANSACTION;

        SELECT 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        SELECT @Return;

    END CATCH;

END;









