CREATE PROCEDURE [Employees].[s_ShiftDownloadData] @ForceDownloaded BIT ,
  @FromDateTime DATETIME ,
  @ToDateTime DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN --Declare
	
      DECLARE @DownloadType TINYINT;

    END;

    --BEGIN --Delete
    
    --  WITH  o AS ( SELECT ID ,
    --                  USERID ,
    --                  CHECKTIME ,
    --                  ROW_NUMBER() OVER ( PARTITION BY USERID, CHECKTIME ORDER BY USERID, CHECKTIME ) AS RowNumber
    --                FROM FingerPrint.dbo.CHECKINOUT
    --             )
    --    DELETE FROM o
    --      WHERE o.RowNumber <> 1;

    --END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @DownloadType = s.Employees_Shift_DownloadDataType
        FROM Alls.t_CompanyInfo AS s;

    END;
	
    IF @DownloadType = 0
    BEGIN
	                         
      EXECUTE Employees.s_ShiftDownloadDataDaily @ForceDownloaded, @FromDateTime, @ToDateTime, @UserID, @EventBase, @ComputerIP, @Computer, @ComputerAccount; 
							  
    END;

    IF @DownloadType = 1
    BEGIN 
	                         
      EXECUTE Employees.s_ShiftDownloadDataOpen @ForceDownloaded, @FromDateTime, @ToDateTime, @UserID, @EventBase, @ComputerIP, @Computer, @ComputerAccount; 
							  
    END;
    
    IF @DownloadType = 2
    BEGIN 
	                         
      EXECUTE Employees.s_ShiftDownloadDataInOut @ForceDownloaded, @FromDateTime, @ToDateTime, @UserID, @EventBase, @ComputerIP, @Computer, @ComputerAccount; 
							  
    END;

    RETURN 1;

  END TRY
  BEGIN CATCH

    RETURN 0;

  END CATCH;

END;


