/****** Object:  StoredProcedure [Employees].[s_ShiftDownloadDataDaily]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_ShiftDownloadDataDaily] @ForceDownloaded BIT ,
  @FromDateTime DATETIME ,
  @ToDateTime DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @dt_CHECKINOUT TABLE
        (
          USERID INT NOT NULL ,
          CHECKTIME DATETIME NOT NULL ,
          IsDownloaded BIT NOT NULL
        );

      DECLARE @IDsAndRef TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          EmployeeID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Shifts AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NOT NULL
        );

      DECLARE @Ref BIGINT  = Employees.f_ShiftGetNewRef() - 1 ,
        @EmployeeIDs Alls.tt_Guid ,
        @return INT = 0;

    END;

    BEGIN --Set

      INSERT INTO @dt_CHECKINOUT
          ( USERID ,
            CHECKTIME ,
            IsDownloaded
          )
        SELECT s.USERID ,
            s.CHECKTIME ,
            s.IsDownloaded
          FROM Employees.v_FingerPrint_CHECKINOUT AS s
          WHERE IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime;

    END;   

    BEGIN --Check
	    
      IF NOT EXISTS ( SELECT TOP ( 1 ) s.USERID
                        FROM @dt_CHECKINOUT AS s )
      BEGIN
                                                         
        RETURN 1;
	
      END;

    END;    

    BEGIN --Set
    
      WITH  o AS ( SELECT NEWID() AS ID ,
                      ROW_NUMBER() OVER ( PARTITION BY USERID, CONVERT(DATE, CHECKTIME) ORDER BY USERID, CHECKTIME ) AS RowN ,
                      USERID ,
                      CHECKTIME AS FromIs ,
                      CASE WHEN LEAD(USERID, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) = USERID AND CONVERT(DATE, LEAD(CHECKTIME, 1, '') OVER ( ORDER BY USERID, CHECKTIME )) = CONVERT(DATE, CHECKTIME) THEN LEAD(CHECKTIME, 1, '') OVER ( ORDER BY USERID, CHECKTIME )
                           ELSE CHECKTIME
                      END AS ToIs
                    FROM @dt_CHECKINOUT
                 )
        INSERT INTO @Shifts
            ( ID ,
              USERID ,
              FromDate ,
              ToDate
            )
          SELECT o.ID ,
              o.USERID ,
              o.FromIs ,
              o.ToIs
            FROM o
            WHERE o.RowN % 2 = 1;

    END;

    BEGIN --Insert t_Shift

      INSERT INTO Employees.t_Shift
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            RequiredCheckInTime ,
            CheckInTime ,
            EarlyAttendanceIsCalculated ,
            DelayDoubled ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            OvertimeIsCalculated ,
            DoubleOvertime
          )
        OUTPUT Inserted.ID ,
          Inserted.RefF ,
          Inserted.EmployeeID
          INTO @IDsAndRef ( ID, RefF, EmployeeID )
        SELECT s.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ), '0') ,
            s1.ID ,
            s1.Name ,
            DateTimes.f_AddTimeToDate1_Or_2(s.FromDate, s.ToDate, s1.ShiftFrom) ,
            s.FromDate ,
            s1.CalculationEarly ,
            s1.HoursLateX ,
            DateTimes.f_AddTimeToDate1_Or_2(s.ToDate, s.FromDate, s1.ShiftTo) ,
            s.ToDate ,
            s1.CalculationOverTime ,
            s1.HoursOverX
          FROM @Shifts AS s
          INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID;

    END;

    BEGIN --Set 2

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT t.EmployeeID
          FROM @IDsAndRef AS t;

    END;

    BEGIN --Update CHECKINOUT

      WITH  o AS ( SELECT s.IsDownloaded
                    FROM Employees.v_FingerPrint_CHECKINOUT AS s
                    INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID
                    WHERE  IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime
                 )
        UPDATE o
          SET o.IsDownloaded = 1;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @EventBase + s.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDsAndRef AS s;

    END;

    EXECUTE Employees.s_ShiftRebuildFromRefPART @Ref;
 
    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;

GO
/****** Object:  StoredProcedure [Employees].[s_ShiftDownloadDataInOut]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_ShiftDownloadDataInOut] @ForceDownloaded BIT ,
  @FromDateTime DATETIME ,
  @ToDateTime DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

	      DECLARE @dt_CHECKINOUT TABLE
        (
          USERID INT NOT NULL ,
          CHECKTIME DATETIME NOT NULL ,
          CHECKTYPE VARCHAR(1) NOT NULL ,
          IsDownloaded BIT NOT NULL
        );

      DECLARE @AllRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          CHECKTYPE NVARCHAR(MAX) NOT NULL ,
          FromDate DATETIME NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL ,
          IsLast BIT NOT NULL
        );

      DECLARE @VaildRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL
        );

      DECLARE @NoVaildRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL
        );

      DECLARE @FinalRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL
        );

      DECLARE @CanceledRows AS TABLE
        (
          USERID INT NOT NULL ,
          DateIs DATETIME NOT NULL
        );

      DECLARE @IDsAndRef TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          EmployeeID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT = Employees.f_ShiftGetNewRef() - 1 ,
        @DeleteAttendanceMinutes BIGINT = 5 ,
        @MaxAttendanceMinutes BIGINT = 1080 ,
        @EmployeeIDs Alls.tt_Guid ,
        @return INT = 0;

    END;

    BEGIN --Set

      INSERT INTO @dt_CHECKINOUT
          ( USERID ,
            CHECKTIME ,
            CHECKTYPE ,
            IsDownloaded
          )
        SELECT s.USERID ,
            s.CHECKTIME ,
            s.CHECKTYPE ,
            s.IsDownloaded
          FROM Employees.v_FingerPrint_CHECKINOUT AS s
          WHERE IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime;

    END;   
		
    BEGIN --Check
	    
      IF NOT EXISTS ( SELECT TOP ( 1 ) s.USERID
                        FROM @dt_CHECKINOUT AS s )
      BEGIN
                                                         
        RETURN 1;
	
      END;

    END;    

    BEGIN --Set
    
      SELECT TOP ( 1 ) @MaxAttendanceMinutes = s.Shift_MaxAttendanceMinutes
        FROM Alls.t_CompanyInfo AS s;

    END;

    BEGIN --Set All
    
      INSERT INTO @AllRows
          ( ID ,
            USERID ,
            CHECKTYPE ,
            FromDate ,
            ToDate ,
            Mintues ,
            IsLast
          )
        SELECT NEWID() ,
            USERID ,
            CHECKTYPE ,
            CASE WHEN LAG(CHECKTYPE, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) = 'O' AND CHECKTYPE = 'O' THEN NULL
                 ELSE CHECKTIME
            END AS FromIs ,
            CASE WHEN LAG(CHECKTYPE, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) LIKE N'O' AND CHECKTYPE = 'O' THEN CHECKTIME
                 WHEN LEAD(CHECKTYPE, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) LIKE N'O' THEN LEAD(CHECKTIME, 1, '') OVER ( ORDER BY USERID, CHECKTIME )
                 WHEN CHECKTYPE = 'O' THEN CHECKTIME
                 ELSE NULL
            END AS ToIs ,
            0 ,
            CASE WHEN LEAD(USERID, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) <> USERID AND CHECKTYPE = N'I' THEN 1
                 ELSE 0
            END AS IsLast
          FROM @dt_CHECKINOUT
          WHERE IIF(@ForceDownloaded = 1, 0, IsDownloaded) = 0 AND CHECKTIME BETWEEN @FromDateTime AND @ToDateTime;

      DELETE FROM @AllRows
        WHERE FromDate IS NULL;

      INSERT INTO @CanceledRows
          ( USERID ,
            DateIs
          )
        SELECT s.USERID ,
            s.FromDate
          FROM @AllRows AS s
          WHERE s.IsLast = 1;

      DELETE FROM @AllRows
        WHERE CHECKTYPE = N'O' OR IsLast = 1;

      UPDATE @AllRows
        SET Mintues = DATEDIFF(MINUTE, FromDate, ToDate);

      DELETE FROM @AllRows
        WHERE Mintues <= @DeleteAttendanceMinutes;
   
      UPDATE @AllRows
        SET ToDate = FromDate ,
            Mintues = 0
        WHERE ToDate IS NULL;

    END;

    BEGIN --Set Vaild
    
      INSERT INTO @VaildRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          FROM @AllRows
          WHERE Mintues <= @MaxAttendanceMinutes;
    
    END;

    BEGIN --Set NoVaild
    
      INSERT INTO @NoVaildRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          FROM @AllRows
          WHERE Mintues > @MaxAttendanceMinutes;

    END;

    BEGIN --Set Final
    	
      INSERT INTO @FinalRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues
          FROM @VaildRows
        UNION ALL
        SELECT ID ,
            USERID ,
            FromDate ,
            FromDate ,
            Mintues
          FROM @NoVaildRows
        UNION ALL
        SELECT NEWID() ,
            USERID ,
            ToDate ,
            ToDate ,
            Mintues
          FROM @NoVaildRows;
  
      UPDATE @FinalRows
        SET Mintues = DATEDIFF(MINUTE, FromDate, ToDate);

    END;

    BEGIN --Insert t_Shift

      INSERT INTO Employees.t_Shift
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            RequiredCheckInTime ,
            CheckInTime ,
            EarlyAttendanceIsCalculated ,
            DelayDoubled ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            OvertimeIsCalculated ,
            DoubleOvertime
          )
        OUTPUT Inserted.ID ,
          Inserted.RefF ,
          Inserted.EmployeeID
          INTO @IDsAndRef ( ID, RefF, EmployeeID )
        SELECT s.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ), '0') ,
            s1.ID ,
            s1.Name ,
            s.FromDate ,
            s.FromDate ,
            s1.CalculationEarly ,
            s1.HoursLateX ,
            s.ToDate ,
            s.ToDate ,
            s1.CalculationOverTime ,
            s1.HoursOverX
          FROM @FinalRows AS s
          INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID;

    END;

    BEGIN --Set 2

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT t.EmployeeID
          FROM @IDsAndRef AS t;

    END;

    BEGIN --Update CHECKINOUT

      WITH  o AS ( SELECT s.IsDownloaded
                    FROM Employees.v_FingerPrint_CHECKINOUT AS s
                    INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID
                    WHERE  IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime
                 )
        UPDATE o
          SET o.IsDownloaded = 1;

      MERGE Employees.v_FingerPrint_CHECKINOUT AS t
      USING @CanceledRows AS s
      ON s.USERID = t.USERID AND s.DateIs = t.CHECKTIME
      WHEN MATCHED THEN
        UPDATE SET t.IsDownloaded = 0;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @EventBase + s.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDsAndRef AS s;

    END;

    EXECUTE Employees.s_ShiftRebuildFromRefPART @Ref;
  
    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;

GO
/****** Object:  StoredProcedure [Employees].[s_ShiftDownloadDataOpen]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_ShiftDownloadDataOpen] @ForceDownloaded BIT ,
  @FromDateTime DATETIME ,
  @ToDateTime DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @dt_CHECKINOUT TABLE
        (
          USERID INT NOT NULL ,
          CHECKTIME DATETIME NOT NULL ,
          IsDownloaded BIT NOT NULL
        );

      DECLARE @AllRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL ,
          RowN BIGINT NOT NULL
        );

      DECLARE @VaildRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL ,
          RowN BIGINT NOT NULL
        );

      DECLARE @NoVaildRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL ,
          RowN BIGINT NOT NULL
        );

      DECLARE @FinalRows AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          USERID INT NOT NULL ,
          FromDate DATETIME NOT NULL ,
          ToDate DATETIME NULL ,
          Mintues BIGINT NULL ,
          RowN BIGINT NOT NULL
        );

      DECLARE @CanceledRows AS TABLE
        (
          USERID INT NOT NULL ,
          DateIs DATETIME NOT NULL
        );

      DECLARE @IDsAndRef TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          EmployeeID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT = Employees.f_ShiftGetNewRef() - 1 ,
        @DeleteAttendanceMinutes BIGINT = 5 ,
        @MaxAttendanceMinutes BIGINT = 1080 ,
        @EmployeeIDs Alls.tt_Guid ,
        @return INT = 0;

    END;

    BEGIN --Set

      INSERT INTO @dt_CHECKINOUT
          ( USERID ,
            CHECKTIME ,
            IsDownloaded
          )
        SELECT s.USERID ,
            s.CHECKTIME ,
            s.IsDownloaded
          FROM Employees.v_FingerPrint_CHECKINOUT AS s
          WHERE IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime;

    END;   
		
    BEGIN --Check
	    
      IF NOT EXISTS ( SELECT TOP ( 1 ) s.USERID
                        FROM @dt_CHECKINOUT AS s )
      BEGIN
                                                         
        RETURN 1;
	
      END;

    END;    

    BEGIN --Set
    
      SELECT TOP ( 1 ) @MaxAttendanceMinutes = s.Shift_MaxAttendanceMinutes
        FROM Alls.t_CompanyInfo AS s;

    END;

    BEGIN --Set All
    
      INSERT INTO @AllRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          )
        SELECT NEWID() ,
            USERID ,
            CHECKTIME AS FromIs ,
            CASE WHEN LEAD(USERID, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) = USERID THEN LEAD(CHECKTIME, 1, '') OVER ( ORDER BY USERID, CHECKTIME )
                 ELSE NULL
            END AS ToIs ,
            DATEDIFF(MINUTE, CHECKTIME, CASE WHEN LEAD(USERID, 1, '') OVER ( ORDER BY USERID, CHECKTIME ) = USERID THEN LEAD(CHECKTIME, 1, '') OVER ( ORDER BY USERID, CHECKTIME )
                                             ELSE NULL
                                        END) ,
            ROW_NUMBER() OVER ( PARTITION BY USERID ORDER BY USERID, CHECKTIME ) AS RowN
          FROM @dt_CHECKINOUT
          WHERE IIF(@ForceDownloaded = 1, 0, IsDownloaded) = 0 AND CHECKTIME BETWEEN @FromDateTime AND @ToDateTime;

      UPDATE @AllRows
        SET Mintues = DATEDIFF(MINUTE, FromDate, ToDate);

      DELETE FROM @AllRows
        WHERE Mintues <= @DeleteAttendanceMinutes;

    END;

    BEGIN --Set Vaild
    
      INSERT INTO @VaildRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          FROM @AllRows
          WHERE Mintues <= @MaxAttendanceMinutes;
  
      DELETE @VaildRows
        WHERE RowN % 2 = 0;
  
    END;

    BEGIN --Set NoVaild
    
      INSERT INTO @NoVaildRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          FROM @AllRows
          WHERE Mintues > @MaxAttendanceMinutes;

      UPDATE @NoVaildRows
        SET ToDate = FromDate;

    END;

    BEGIN --Set Final
    	
      INSERT INTO @FinalRows
          ( ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          )
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          FROM @VaildRows
        UNION ALL
        SELECT ID ,
            USERID ,
            FromDate ,
            ToDate ,
            Mintues ,
            RowN
          FROM @NoVaildRows;
  
      UPDATE @FinalRows
        SET Mintues = DATEDIFF(MINUTE, FromDate, ToDate);

    END;

    BEGIN --Set Canceled
    
      INSERT INTO @CanceledRows
          ( USERID ,
            DateIs 
          )
        SELECT USERID ,
            FromDate
          FROM @AllRows
          WHERE ToDate IS NULL;

    END;

    BEGIN --Insert t_Shift

      INSERT INTO Employees.t_Shift
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            RequiredCheckInTime ,
            CheckInTime ,
            EarlyAttendanceIsCalculated ,
            DelayDoubled ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            OvertimeIsCalculated ,
            DoubleOvertime
          )
        OUTPUT Inserted.ID ,
          Inserted.RefF ,
          Inserted.EmployeeID
          INTO @IDsAndRef ( ID, RefF, EmployeeID )
        SELECT s.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY s.ID ), '0') ,
            s1.ID ,
            s1.Name ,
            s.FromDate ,
            s.FromDate ,
            s1.CalculationEarly ,
            s1.HoursLateX ,
            s.ToDate ,
            s.ToDate ,
            s1.CalculationOverTime ,
            s1.HoursOverX
          FROM @FinalRows AS s
          INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID;

    END;

    BEGIN --Set 2

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT t.EmployeeID
          FROM @IDsAndRef AS t;

    END;

    BEGIN --Update CHECKINOUT

      WITH  o AS ( SELECT s.IsDownloaded
                    FROM Employees.v_FingerPrint_CHECKINOUT AS s
                    INNER JOIN Employees.t_Employee AS s1 ON s1.IDFingerPrint = s.USERID
                    WHERE  IIF(@ForceDownloaded = 1, 0, s.IsDownloaded) = 0 AND s.CHECKTIME BETWEEN @FromDateTime AND @ToDateTime
                 )
        UPDATE o
          SET o.IsDownloaded = 1;

      MERGE Employees.v_FingerPrint_CHECKINOUT AS t
      USING @CanceledRows AS s
      ON s.USERID = t.USERID AND s.DateIs = t.CHECKTIME
      WHEN MATCHED THEN
        UPDATE SET t.IsDownloaded = 0;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @EventBase + s.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDsAndRef AS s;

    END;

    EXECUTE Employees.s_ShiftRebuildFromRefPART @Ref;
  
    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;

GO
