/****** Object:  StoredProcedure [Employees].[s_ShiftHistoryDeletes]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_ShiftHistoryDeletes] @IDs Alls.tt_IDAndEvent READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @EmployeeIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT t.EmployeeID
          FROM Employees.t_ShiftHistory AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Delete t_Shift

      DELETE FROM Employees.t_ShiftHistory
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ShiftHistory.ID );

    END;
	
    BEGIN --Insert t_ShiftMoving

      SET @Return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            2 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;
	
    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;














