/****** Object:  StoredProcedure [Employees].[s_ShiftHistoryRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_ShiftHistoryRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding statistics

      BEGIN --Calculation

        UPDATE Employees.t_Shift
          SET RequiredMinutes = DATEDIFF(SECOND, RequiredCheckInTime, RequiredCheckoutTime) / 60.0 ,
              EarlyAttendanceMinutes = COALESCE(DATEDIFF(SECOND, CheckInTime, RequiredCheckInTime), 0) / 60.0 ,
              DelayMinutes = COALESCE(DATEDIFF(SECOND, RequiredCheckInTime, CheckInTime), 0) / 60.0 ,
              WorkMinutes = COALESCE(DATEDIFF(SECOND, CheckInTime, CheckoutTime), 0) / 60.0 ,
              DateIs = COALESCE(CheckInTime, RequiredCheckInTime);

      END;

      BEGIN --Fix

        UPDATE Employees.t_Shift
          SET RequiredHours = RequiredMinutes / 60.0 ,
              WorkHours = WorkMinutes / 60.0 ,
              OvertimeMinutes = WorkMinutes - RequiredMinutes;

        BEGIN --EarlyAttendanceMinutes

          UPDATE Employees.t_Shift
            SET EarlyAttendanceMinutes = 0
            WHERE EarlyAttendanceMinutes < 0;

        END;

        BEGIN --DelayMinutes

          UPDATE Employees.t_Shift
            SET DelayMinutes = 0
            WHERE DelayMinutes < 0;

          UPDATE Employees.t_Shift
            SET FinalDelayMinutes = DelayMinutes * DelayDoubled;

          UPDATE Employees.t_Shift
            SET DoubleDelayMinutes = FinalDelayMinutes - DelayMinutes;

        END;

        BEGIN --OvertimeMinutes

          UPDATE Employees.t_Shift
            SET OvertimeMinutes -= IIF(EarlyAttendanceIsCalculated = 0, EarlyAttendanceMinutes, 0);
          UPDATE Employees.t_Shift
            SET OvertimeMinutes -= DoubleDelayMinutes;

          UPDATE Employees.t_Shift
            SET OvertimeMinutes = 0
            WHERE OvertimeMinutes < 0;

          UPDATE Employees.t_Shift
            SET FinalOvertimeMinutes = OvertimeMinutes * DoubleOvertime;

          UPDATE Employees.t_Shift
            SET AddedOvertimeMinutes = FinalOvertimeMinutes - OvertimeMinutes;

        END;

        BEGIN --TimeIncompleteMinute

          UPDATE Employees.t_Shift
            SET IncompleteWorkMinutes = IIF(CheckInTime IS NULL OR CheckoutTime IS NULL, RequiredMinutes, RequiredMinutes - FinalWorkMinutes);
          UPDATE Employees.t_Shift
            SET IncompleteWorkMinutes = 0
            WHERE IncompleteWorkMinutes < 0;

        END;

        BEGIN --ShiftMinuteNet

          UPDATE Employees.t_Shift
            SET FinalWorkMinutes = WorkMinutes;

          UPDATE Employees.t_Shift
            SET FinalWorkMinutes -= IIF(EarlyAttendanceIsCalculated = 0, EarlyAttendanceMinutes, 0);
          UPDATE Employees.t_Shift
            SET FinalWorkMinutes -= DoubleDelayMinutes;

          UPDATE Employees.t_Shift
            SET FinalWorkMinutes += IIF(OvertimeIsCalculated = 0, 0 - OvertimeMinutes, AddedOvertimeMinutes);
          UPDATE Employees.t_Shift
            SET FinalWorkHours = FinalWorkMinutes / 60.0;

        END;

      END;

      BEGIN --Format

        UPDATE Employees.t_Shift
          SET RequiredTime = DateTimes.[f_FormatHHMMSS](RequiredMinutes, 'm') ,
              EarlyAttendance = DateTimes.[f_FormatHHMMSS](EarlyAttendanceMinutes, 'm') ,
              DelayTime = DateTimes.[f_FormatHHMMSS](DelayMinutes, 'm') ,
              FinalDelayTime = DateTimes.[f_FormatHHMMSS](FinalDelayMinutes, 'm') ,
              DoubleDelayTime = DateTimes.[f_FormatHHMMSS](DoubleDelayMinutes, 'm') ,
              WorkTime = DateTimes.[f_FormatHHMMSS](WorkMinutes, 'm') ,
              Overtime = DateTimes.[f_FormatHHMMSS](OvertimeMinutes, 'm') ,
              FinalOvertime = DateTimes.[f_FormatHHMMSS](FinalOvertimeMinutes, 'm') ,
              AddedOvertimeTime = DateTimes.[f_FormatHHMMSS](AddedOvertimeMinutes, 'm') ,
              FinalWorkTime = DateTimes.[f_FormatHHMMSS](FinalWorkMinutes, 'm') ,
              IncompleteWorkTime = DateTimes.[f_FormatHHMMSS](IncompleteWorkMinutes, 'm');

      END;

    END;

    SET @Return = -1;
    EXECUTE Employees.s_ShiftMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Employees].[s_ShiftHistoryUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_ShiftHistoryUpdate] @ShiftHistory Employees.tt_Shift READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @EmployeeIDs Alls.tt_Guid ,
       @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT s.EmployeeID
          FROM @ShiftHistory AS s;

    END;

    BEGIN --Merge t_ShiftHistory

      MERGE Employees.t_ShiftHistory AS t
      USING @ShiftHistory AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.DateIs = s.DateIs ,
                    t.RequiredCheckInTime = s.RequiredCheckInTime ,
                    t.CheckInTime = s.CheckInTime ,
                    t.RequiredMinutes = s.RequiredMinutes ,
                    t.RequiredHours = s.RequiredHours ,
                    t.RequiredTime = s.RequiredTime ,
                    t.EarlyAttendanceMinutes = s.EarlyAttendanceMinutes ,
                    t.EarlyAttendance = s.EarlyAttendance ,
                    t.EarlyAttendanceIsCalculated = s.EarlyAttendanceIsCalculated ,
                    t.DelayMinutes = s.DelayMinutes ,
                    t.DelayTime = s.DelayTime ,
                    t.DelayDoubled = s.DelayDoubled ,
                    t.FinalDelayMinutes = s.FinalDelayMinutes ,
                    t.FinalDelayTime = s.FinalDelayTime ,
                    t.DoubleDelayMinutes = s.DoubleDelayMinutes ,
                    t.DoubleDelayTime = s.DoubleDelayTime ,
                    t.RequiredCheckoutTime = s.RequiredCheckoutTime ,
                    t.CheckoutTime = s.CheckoutTime ,
                    t.WorkMinutes = s.WorkMinutes ,
                    t.WorkHours = s.WorkHours ,
                    t.WorkTime = s.WorkTime ,
                    t.OvertimeMinutes = s.OvertimeMinutes ,
                    t.Overtime = s.Overtime ,
                    t.OvertimeIsCalculated = s.OvertimeIsCalculated ,
                    t.DoubleOvertime = s.DoubleOvertime ,
                    t.FinalOvertimeMinutes = s.FinalOvertimeMinutes ,
                    t.FinalOvertime = s.FinalOvertime ,
                    t.AddedOvertimeMinutes = s.AddedOvertimeMinutes ,
                    t.AddedOvertimeTime = s.AddedOvertimeTime ,
                    t.FinalWorkMinutes = s.FinalWorkMinutes ,
                    t.FinalWorkHours = s.FinalWorkHours ,
                    t.FinalWorkTime = s.FinalWorkTime ,
                    t.IncompleteWorkMinutes = s.IncompleteWorkMinutes ,
                    t.IncompleteWorkTime = s.IncompleteWorkTime ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.StatusIs = s.StatusIs;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @Return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            t.ID ,
            t.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @ShiftHistory AS t;

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;
	
    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









