GO

CREATE PROCEDURE [Employees].[s_ShiftInsert] @Shift Employees.tt_Shift READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY 
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Shift_ Employees.tt_Shift;

      DECLARE @Ref BIGINT= 0 ,
        @EmployeeIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(o.Ref), 0)
        FROM ( SELECT MAX(s.Ref) AS Ref
                FROM Employees.t_Shift AS s
               UNION ALL
               SELECT MAX(s.Ref) AS Ref
                FROM Employees.t_ShiftHistory AS s
             ) AS o;

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT s.EmployeeID
          FROM @Shift AS s;

      INSERT @Shift_
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            DateIs ,
            RequiredCheckInTime ,
            CheckInTime ,
            RequiredMinutes ,
            RequiredHours ,
            RequiredTime ,
            EarlyAttendanceMinutes ,
            EarlyAttendance ,
            EarlyAttendanceIsCalculated ,
            DelayMinutes ,
            DelayTime ,
            DelayDoubled ,
            FinalDelayMinutes ,
            FinalDelayTime ,
            DoubleDelayMinutes ,
            DoubleDelayTime ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            WorkMinutes ,
            WorkHours ,
            WorkTime ,
            OvertimeMinutes ,
            Overtime ,
            OvertimeIsCalculated ,
            DoubleOvertime ,
            FinalOvertimeMinutes ,
            FinalOvertime ,
            AddedOvertimeMinutes ,
            AddedOvertimeTime ,
            FinalWorkMinutes ,
            FinalWorkHours ,
            FinalWorkTime ,
            IncompleteWorkMinutes ,
            IncompleteWorkTime ,
            DescriptionIs ,
            StatusIs ,
            EventIs
          )
        SELECT ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY ID ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY ID ), '0') ,
            EmployeeID ,
            Employee ,
            DateIs ,
            RequiredCheckInTime ,
            CheckInTime ,
            RequiredMinutes ,
            RequiredHours ,
            RequiredTime ,
            EarlyAttendanceMinutes ,
            EarlyAttendance ,
            EarlyAttendanceIsCalculated ,
            DelayMinutes ,
            DelayTime ,
            DelayDoubled ,
            FinalDelayMinutes ,
            FinalDelayTime ,
            DoubleDelayMinutes ,
            DoubleDelayTime ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            WorkMinutes ,
            WorkHours ,
            WorkTime ,
            OvertimeMinutes ,
            Overtime ,
            OvertimeIsCalculated ,
            DoubleOvertime ,
            FinalOvertimeMinutes ,
            FinalOvertime ,
            AddedOvertimeMinutes ,
            AddedOvertimeTime ,
            FinalWorkMinutes ,
            FinalWorkHours ,
            FinalWorkTime ,
            IncompleteWorkMinutes ,
            IncompleteWorkTime ,
            DescriptionIs ,
            StatusIs ,
            EventIs
          FROM @Shift;

    END;

    BEGIN --Insert t_Shift

      INSERT INTO Employees.t_Shift
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            DateIs ,
            RequiredCheckInTime ,
            CheckInTime ,
            RequiredMinutes ,
            RequiredHours ,
            RequiredTime ,
            EarlyAttendanceMinutes ,
            EarlyAttendance ,
            EarlyAttendanceIsCalculated ,
            DelayMinutes ,
            DelayTime ,
            DelayDoubled ,
            FinalDelayMinutes ,
            FinalDelayTime ,
            DoubleDelayMinutes ,
            DoubleDelayTime ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            WorkMinutes ,
            WorkHours ,
            WorkTime ,
            OvertimeMinutes ,
            Overtime ,
            OvertimeIsCalculated ,
            DoubleOvertime ,
            FinalOvertimeMinutes ,
            FinalOvertime ,
            AddedOvertimeMinutes ,
            AddedOvertimeTime ,
            FinalWorkMinutes ,
            FinalWorkHours ,
            FinalWorkTime ,
            IncompleteWorkMinutes ,
            IncompleteWorkTime ,
            DescriptionIs ,
            StatusIs
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.EmployeeID ,
            t.Employee ,
            t.DateIs ,
            t.RequiredCheckInTime ,
            t.CheckInTime ,
            t.RequiredMinutes ,
            t.RequiredHours ,
            t.RequiredTime ,
            t.EarlyAttendanceMinutes ,
            t.EarlyAttendance ,
            t.EarlyAttendanceIsCalculated ,
            t.DelayMinutes ,
            t.DelayTime ,
            t.DelayDoubled ,
            t.FinalDelayMinutes ,
            t.FinalDelayTime ,
            t.DoubleDelayMinutes ,
            t.DoubleDelayTime ,
            t.RequiredCheckoutTime ,
            t.CheckoutTime ,
            t.WorkMinutes ,
            t.WorkHours ,
            t.WorkTime ,
            t.OvertimeMinutes ,
            t.Overtime ,
            t.OvertimeIsCalculated ,
            t.DoubleOvertime ,
            t.FinalOvertimeMinutes ,
            t.FinalOvertime ,
            t.AddedOvertimeMinutes ,
            t.AddedOvertimeTime ,
            t.FinalWorkMinutes ,
            t.FinalWorkHours ,
            t.FinalWorkTime ,
            t.IncompleteWorkMinutes ,
            t.IncompleteWorkTime ,
            t.DescriptionIs ,
            t.StatusIs
          FROM @Shift_ AS t;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @Return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            t.ID ,
            t.EventIs + t.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Shift_ AS t;

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








