CREATE PROCEDURE [Employees].[s_ShiftInsertShort] @EmployeeID UNIQUEIDENTIFIER ,
  @Employee NVARCHAR(MAX) ,
  @CheckInTime DATETIME
AS
BEGIN
  BEGIN TRY 
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(o.Ref), 0) + 1
        FROM ( SELECT MAX(s.Ref) AS Ref
                FROM Employees.t_Shift AS s
               UNION ALL
               SELECT MAX(s.Ref) AS Ref
                FROM Employees.t_ShiftHistory AS s
             ) AS o;

    END;

    BEGIN --Insert t_Shift

      INSERT INTO Employees.t_Shift
          ( Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            DateIs ,
            RequiredCheckInTime ,
            CheckInTime
          )
        VALUES
          ( @Ref ,
            FORMAT(@Ref, '0') ,
            @EmployeeID ,
            @Employee ,
            @CheckInTime ,
            @CheckInTime ,
            @CheckInTime 
          );

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PART @EmployeeID;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;








