CREATE PROCEDURE [Employees].[s_ShiftMigrateToArchive] @IDs Alls.tt_IDAndEvent READONLY ,
  @StatusIs TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @EmployeeIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT t.EmployeeID
          FROM Employees.t_Shift AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Insert t_ShiftHistory

      INSERT INTO Employees.t_ShiftHistory
          ( ID ,
            Ref ,
            RefF ,
            EmployeeID ,
            Employee ,
            DateIs ,
            RequiredCheckInTime ,
            CheckInTime ,
            RequiredMinutes ,
            RequiredHours ,
            RequiredTime ,
            EarlyAttendanceMinutes ,
            EarlyAttendance ,
            EarlyAttendanceIsCalculated ,
            DelayMinutes ,
            DelayTime ,
            DelayDoubled ,
            FinalDelayMinutes ,
            FinalDelayTime ,
            DoubleDelayMinutes ,
            DoubleDelayTime ,
            RequiredCheckoutTime ,
            CheckoutTime ,
            WorkMinutes ,
            WorkHours ,
            WorkTime ,
            OvertimeMinutes ,
            Overtime ,
            OvertimeIsCalculated ,
            DoubleOvertime ,
            FinalOvertimeMinutes ,
            FinalOvertime ,
            AddedOvertimeMinutes ,
            AddedOvertimeTime ,
            FinalWorkMinutes ,
            FinalWorkHours ,
            FinalWorkTime ,
            IncompleteWorkMinutes ,
            IncompleteWorkTime ,
            DescriptionIs ,
            StatusIs ,
            DateCreate 
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.EmployeeID ,
            t.Employee ,
            t.DateIs ,
            t.RequiredCheckInTime ,
            t.CheckInTime ,
            t.RequiredMinutes ,
            t.RequiredHours ,
            t.RequiredTime ,
            t.EarlyAttendanceMinutes ,
            t.EarlyAttendance ,
            t.EarlyAttendanceIsCalculated ,
            t.DelayMinutes ,
            t.DelayTime ,
            t.DelayDoubled ,
            t.FinalDelayMinutes ,
            t.FinalDelayTime ,
            t.DoubleDelayMinutes ,
            t.DoubleDelayTime ,
            t.RequiredCheckoutTime ,
            t.CheckoutTime ,
            t.WorkMinutes ,
            t.WorkHours ,
            t.WorkTime ,
            t.OvertimeMinutes ,
            t.Overtime ,
            t.OvertimeIsCalculated ,
            t.DoubleOvertime ,
            t.FinalOvertimeMinutes ,
            t.FinalOvertime ,
            t.AddedOvertimeMinutes ,
            t.AddedOvertimeTime ,
            t.FinalWorkMinutes ,
            t.FinalWorkHours ,
            t.FinalWorkTime ,
            t.IncompleteWorkMinutes ,
            t.IncompleteWorkTime ,
            t.DescriptionIs ,
            @StatusIs ,
            t.DateCreate
          FROM Employees.t_Shift AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Delete t_Shift

      DELETE FROM Employees.t_Shift
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Shift.ID );

    END;
	
    BEGIN --Insert t_ShiftMoving

      SET @Return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            2 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;
	
    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;














