/****** Object:  StoredProcedure [Employees].[s_ShiftUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Employees].[s_ShiftUpdate] @Shift Employees.tt_Shift READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @EmployeeIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @EmployeeIDs
          ( ID
          )
        SELECT DISTINCT s.EmployeeID
          FROM @Shift AS s;

    END;
	
    BEGIN --Merge t_Shift

      MERGE Employees.t_Shift AS t
      USING @Shift AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.DateIs = s.DateIs ,
                    t.RequiredCheckInTime = s.RequiredCheckInTime ,
                    t.CheckInTime = s.CheckInTime ,
                    t.RequiredMinutes = s.RequiredMinutes ,
                    t.RequiredHours = s.RequiredHours ,
                    t.RequiredTime = s.RequiredTime ,
                    t.EarlyAttendanceMinutes = s.EarlyAttendanceMinutes ,
                    t.EarlyAttendance = s.EarlyAttendance ,
                    t.EarlyAttendanceIsCalculated = s.EarlyAttendanceIsCalculated ,
                    t.DelayMinutes = s.DelayMinutes ,
                    t.DelayTime = s.DelayTime ,
                    t.DelayDoubled = s.DelayDoubled ,
                    t.FinalDelayMinutes = s.FinalDelayMinutes ,
                    t.FinalDelayTime = s.FinalDelayTime ,
                    t.DoubleDelayMinutes = s.DoubleDelayMinutes ,
                    t.DoubleDelayTime = s.DoubleDelayTime ,
                    t.RequiredCheckoutTime = s.RequiredCheckoutTime ,
                    t.CheckoutTime = s.CheckoutTime ,
                    t.WorkMinutes = s.WorkMinutes ,
                    t.WorkHours = s.WorkHours ,
                    t.WorkTime = s.WorkTime ,
                    t.OvertimeMinutes = s.OvertimeMinutes ,
                    t.Overtime = s.Overtime ,
                    t.OvertimeIsCalculated = s.OvertimeIsCalculated ,
                    t.DoubleOvertime = s.DoubleOvertime ,
                    t.FinalOvertimeMinutes = s.FinalOvertimeMinutes ,
                    t.FinalOvertime = s.FinalOvertime ,
                    t.AddedOvertimeMinutes = s.AddedOvertimeMinutes ,
                    t.AddedOvertimeTime = s.AddedOvertimeTime ,
                    t.FinalWorkMinutes = s.FinalWorkMinutes ,
                    t.FinalWorkHours = s.FinalWorkHours ,
                    t.FinalWorkTime = s.FinalWorkTime ,
                    t.IncompleteWorkMinutes = s.IncompleteWorkMinutes ,
                    t.IncompleteWorkTime = s.IncompleteWorkTime ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.StatusIs = s.StatusIs;

    END;

    BEGIN --Insert t_ShiftMoving

      SET @Return = -1;

      INSERT INTO Employees.t_ShiftMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            t.ID ,
            t.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Shift AS t;

    END;

    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PARTS @EmployeeIDs;
	
    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








