/****** Object:  StoredProcedure [Employees].[s_ShiftUpdateShort]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_ShiftUpdateShort] @ID UNIQUEIDENTIFIER ,
  @RequiredMinutes FLOAT ,
  @RequiredHours FLOAT ,
  @RequiredTime NVARCHAR(MAX) ,
  @CheckoutTime DATETIME ,
  @WorkMinutes FLOAT ,
  @WorkHours FLOAT ,
  @WorkTime NVARCHAR(MAX) ,
  @FinalWorkMinutes FLOAT ,
  @FinalWorkHours FLOAT ,
  @FinalWorkTime NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY 
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @EmployeeID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @EmployeeID = s.EmployeeID
        FROM Employees.t_Shift AS s
        WHERE ID = @ID;

    END;

    BEGIN --Update t_Shift

      UPDATE Employees.t_Shift
        SET RequiredMinutes = @RequiredMinutes ,
            RequiredHours = @RequiredHours ,
            RequiredTime = @RequiredTime ,
            RequiredCheckoutTime = @CheckoutTime ,
            CheckoutTime = @CheckoutTime ,
            WorkMinutes = @WorkMinutes ,
            WorkHours = @WorkHours ,
            WorkTime = @WorkTime ,
            FinalWorkMinutes = @FinalWorkMinutes ,
            FinalWorkHours = @FinalWorkHours ,
            FinalWorkTime = @FinalWorkTime
        WHERE ID = @ID;

      UPDATE Employees.t_Shift
        SET RequiredTime = DateTimes.[f_FormatHHMMSS](RequiredMinutes, 'm') ,
            EarlyAttendance = DateTimes.[f_FormatHHMMSS](EarlyAttendanceMinutes, 'm') ,
            DelayTime = DateTimes.[f_FormatHHMMSS](DelayMinutes, 'm') ,
            FinalDelayTime = DateTimes.[f_FormatHHMMSS](FinalDelayMinutes, 'm') ,
            DoubleDelayTime = DateTimes.[f_FormatHHMMSS](DoubleDelayMinutes, 'm') ,
            WorkTime = DateTimes.[f_FormatHHMMSS](WorkMinutes, 'm') ,
            Overtime = DateTimes.[f_FormatHHMMSS](OvertimeMinutes, 'm') ,
            FinalOvertime = DateTimes.[f_FormatHHMMSS](FinalOvertimeMinutes, 'm') ,
            AddedOvertimeTime = DateTimes.[f_FormatHHMMSS](AddedOvertimeMinutes, 'm') ,
            FinalWorkTime = DateTimes.[f_FormatHHMMSS](FinalWorkMinutes, 'm') ,
            IncompleteWorkTime = DateTimes.[f_FormatHHMMSS](IncompleteWorkMinutes, 'm')
        WHERE ID = @ID;

    END;
	
    EXECUTE Employees.s_EmployeeRebuild_AttendancesHours_PART @EmployeeID;

    EXECUTE Employees.s_ShiftLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;









