/****** Object:  StoredProcedure [Employees].[s_VacationDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_VacationDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Old_EmployeeID UNIQUEIDENTIFIER ,
        @Old_TypeID UNIQUEIDENTIFIER ,
        @Old_VacationAddC BIGINT ,
        @Old_VacationUseC BIGINT ,
        @Old_VacationNet BIGINT ,
        @Old_VacationDiscountedC BIGINT ,
        @Old_VacationC BIGINT = -1 ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @Old_EmployeeID = s.EmployeeID ,
          @Old_TypeID = s.TypeID ,
          @Old_VacationAddC = IIF(s.OperationType = 0, 0 - s.DaysIs, 0) ,
          @Old_VacationUseC = IIF(s.OperationType = 1, 0 - s.DaysIs, 0) ,
          @Old_VacationDiscountedC = IIF(s.OperationType = 2, 0 - s.DaysIs, 0)
        FROM Employees.t_Vacation AS s
        WHERE s.ID = @ID;

      SET @Old_VacationNet = @Old_VacationAddC - @Old_VacationUseC;

    END;

    BEGIN --Delete

      DELETE FROM Employees.t_Vacation
        WHERE ID = @ID;

    END;

    EXECUTE Employees.s_EmployeeAddVacationPART @Old_EmployeeID, @Old_VacationNet;
    EXECUTE Employees.s_VacationTypeAddVacationPART @Old_TypeID, @Old_VacationAddC, @Old_VacationUseC, @Old_VacationNet, @Old_VacationDiscountedC, @Old_VacationC;

    SET @Return = -1;
    EXECUTE Employees.s_VacationMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Alls.s_FireStoreRowsForDeleteInsertPART @ID, 0, 'vacation'; 

    EXECUTE Employees.s_VacationLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Employees].[s_VacationInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_VacationInserts] @Vacations Employees.tt_Vacation READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs AS Alls.tt_IDAndEvent;

      DECLARE @Return INT = 0 ,
        @Ref BIGINT = Employees.f_VacationGetNewRef() - 1;

    END;

    BEGIN --Insert t_Vacation

      INSERT INTO Employees.t_Vacation
          ( Ref ,
            RefF ,
            DateIs ,
            EmployeeID ,
            TypeID ,
            DaysIs ,
            OperationType ,
            TransferAllowanceDiscount ,
            DescriptionIs
          )
        OUTPUT Inserted.ID ,
          @Event + Inserted.RefF
          INTO @IDs ( ID, EventIs )
        SELECT @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                   ) ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                       ) ), '#') ,
            s.DateIs ,
            s.EmployeeID ,
            s.TypeID ,
            s.DaysIs ,
            s.OperationType ,
            s.TransferAllowanceDiscount ,
            s.DescriptionIs
          FROM @Vacations AS s;

    END;

    EXECUTE Employees.s_VacationTypeAddVacationsPART @Vacations;
	EXECUTE Employees.s_EmployeeAddVacationsPART @Vacations;

    SET @Return = -1;
    EXECUTE Employees.s_VacationMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;
    
    EXECUTE Employees.s_VacationLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;



GO
