CREATE PROCEDURE [Employees].[s_VacationTypeAddVacationPART] @ID UNIQUEIDENTIFIER ,
  @VacationAddC BIGINT ,
  @VacationUseC BIGINT ,
  @VacationNet BIGINT ,
  @VacationDiscountedC BIGINT ,
  @VacationC BIGINT
AS
BEGIN

  BEGIN --Declare

    DECLARE @Return INT = 0;

  END;
  
  BEGIN --Update t_VacationType

    UPDATE Employees.t_VacationType
      SET VacationAddC += @VacationAddC ,
          VacationUseC += @VacationUseC ,
          VacationNet += @VacationNet ,
          VacationDiscountedC += @VacationDiscountedC ,
          VacationC += @VacationC
      WHERE ID = @ID;

  END;

END;






