/****** Object:  StoredProcedure [Employees].[s_VacationTypeAddVacationsPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_VacationTypeAddVacationsPART] @Vacations Employees.tt_Vacation READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @t AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        VacationC BIGINT NOT NULL ,
        VacationAddC BIGINT NOT NULL ,
        VacationUseC BIGINT NOT NULL ,
        VacationDiscountedC BIGINT NOT NULL ,
        VacationNet BIGINT NOT NULL
      );

    DECLARE @Return INT = 0;

  END;
  
  BEGIN --Set
    
    INSERT INTO @t
        ( ID ,
          VacationC ,
          VacationAddC ,
          VacationUseC ,
          VacationDiscountedC ,
          VacationNet
	    )
      SELECT o.TypeID ,
          COALESCE(SUM(o.VacationC), 0) ,
          COALESCE(SUM(o.VacationAddC), 0) ,
          COALESCE(SUM(o.VacationUseC), 0) ,
          COALESCE(SUM(o.VacationDiscountedC), 0) ,
          0
        FROM ( SELECT s.TypeID ,
                  1 AS VacationC ,
                  IIF(s.OperationType = 0, s.DaysIs, 0) AS VacationAddC ,
                  IIF(s.OperationType = 1, s.DaysIs, 0) AS VacationUseC ,
                  IIF(s.OperationType = 2, s.DaysIs, 0) AS VacationDiscountedC
                FROM @Vacations AS s
             ) AS o
        GROUP BY o.TypeID;

  END;

  BEGIN --Rebuild t_VacationType

    MERGE Employees.t_VacationType AS t
    USING @t AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.VacationC += s.VacationC ,
                  t.VacationAddC += s.VacationAddC ,
                  t.VacationUseC += s.VacationUseC ,
                  t.VacationDiscountedC += s.VacationDiscountedC ,
                  t.VacationNet += ( s.VacationAddC - s.VacationUseC );

  END;

END;



