/****** Object:  StoredProcedure [Employees].[s_VacationUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Employees].[s_VacationUpdate] @ID UNIQUEIDENTIFIER ,
  @DateIs DATE ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @TypeID UNIQUEIDENTIFIER ,
  @TransferAllowanceDiscount BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Old_EmployeeID UNIQUEIDENTIFIER ,
        @Old_Days INT ,
        @New_Days INT ,
        @Old_TypeID UNIQUEIDENTIFIER ,
        @Old_VacationAddC BIGINT ,
        @Old_VacationUseC BIGINT ,
        @Old_VacationNet BIGINT ,
        @Old_VacationDiscountedC BIGINT ,
        @Old_VacationC BIGINT = -1 ,
        @New_VacationAddC BIGINT ,
        @New_VacationUseC BIGINT ,
        @New_VacationNet BIGINT ,
        @New_VacationDiscountedC BIGINT ,
        @New_VacationC BIGINT = 1 ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      SELECT TOP ( 1 ) @Old_EmployeeID = s.EmployeeID ,
          @Old_Days = IIF(s.OperationType <= 1, 0 - s.DaysIs, 0) ,
          @New_Days = IIF(s.OperationType <= 1, s.DaysIs, 0) ,
          @Old_TypeID = s.TypeID ,
          @Old_VacationAddC = IIF(s.OperationType = 0, 0 - s.DaysIs, 0) ,
          @Old_VacationUseC = IIF(s.OperationType = 1, 0 - s.DaysIs, 0) ,
          @Old_VacationDiscountedC = IIF(s.OperationType = 2, 0 - s.DaysIs, 0) ,
          @New_VacationAddC = IIF(s.OperationType = 0, s.DaysIs, 0) ,
          @New_VacationUseC = IIF(s.OperationType = 1, s.DaysIs, 0) ,
          @New_VacationDiscountedC = IIF(s.OperationType = 2, s.DaysIs, 0)
        FROM Employees.t_Vacation AS s
        WHERE s.ID = @ID;

      SET @Old_VacationNet = @Old_VacationAddC - @Old_VacationUseC;
      SET @New_VacationNet = @New_VacationAddC - @New_VacationUseC;

    END;

    BEGIN --Insert t_Vacation

      UPDATE Employees.t_Vacation
        SET DateIs = @DateIs ,
            EmployeeID = @EmployeeID ,
            TypeID = @TypeID ,
            TransferAllowanceDiscount = @TransferAllowanceDiscount ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    IF @Old_EmployeeID <> @EmployeeID
    BEGIN
                                      
      EXECUTE Employees.s_EmployeeAddVacationPART @Old_EmployeeID, @Old_Days;
      EXECUTE Employees.s_EmployeeAddVacationPART @EmployeeID, @New_Days;

    END;

    IF @Old_TypeID <> @TypeID
    BEGIN
                                      
      EXECUTE Employees.s_VacationTypeAddVacationPART @Old_TypeID, @Old_VacationAddC, @Old_VacationUseC, @Old_VacationNet, @Old_VacationDiscountedC, @Old_VacationC;
      EXECUTE Employees.s_VacationTypeAddVacationPART @TypeID, @New_VacationAddC, @New_VacationUseC, @New_VacationNet, @New_VacationDiscountedC, @New_VacationC;

    END;
 
    SET @Return = -1;
    EXECUTE Employees.s_VacationMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Employees.s_VacationLiveVersion;
		
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Gym].[s_GymActiveVSAttendanceMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Gym].[s_GymActiveVSAttendanceMerge] @FromDate DATE ,
  @ToDate DATE ,
  @ActiveOrAttendance BIT ,
  @Addition BIT
AS
BEGIN
  
  BEGIN --Declare
	
    DECLARE @DateList AS TABLE ( DateIs DATE );
    DECLARE @Days BIGINT ,
      @Index BIGINT ,
      @NumberIs INT;
	  	
  END;

  BEGIN --Set info
	    
    SET @Days = DATEDIFF(DAY, @FromDate, @ToDate);

    SET @Index = 0;

    WHILE ( @Index <= @Days )
    BEGIN
		    
      INSERT INTO @DateList
          ( DateIs )
        VALUES ( DATEADD(DAY, @Index, @FromDate) );

      SET @Index += 1;

    END;
	 
    SET @NumberIs = IIF(@Addition = 1, 1, -1);

  END;
	
  BEGIN --Insert
	
    MERGE Gym.t_GymActiveVSAttendance AS t
    USING @DateList AS s
    ON s.DateIs = t.DateIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( DateIs ,
               DateMonthly ,
               DateYearly ,
               ActiveNumber ,
               AttendanceNumber
             )
      VALUES ( s.DateIs ,
               DATEFROMPARTS(YEAR(s.DateIs), MONTH(s.DateIs), 1) ,
               DATEFROMPARTS(YEAR(s.DateIs), 1, 1) ,
               IIF(@ActiveOrAttendance = 1, @NumberIs, 0) ,
               IIF(@ActiveOrAttendance = 1, 0, @NumberIs)
             )
    WHEN MATCHED THEN
      UPDATE SET t.ActiveNumber += IIF(@ActiveOrAttendance = 1, @NumberIs, 0) ,
                  t.AttendanceNumber += IIF(@ActiveOrAttendance = 1, 0, @NumberIs);

  END;

  BEGIN --Delete empty row

    DELETE FROM Gym.t_GymActiveVSAttendance
      WHERE ActiveNumber <= 0 AND AttendanceNumber <= 0;

  END;
 
  RETURN 1;

END;



GO
/****** Object:  StoredProcedure [Gym].[s_GymActiveVSAttendanceRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Gym].[s_GymActiveVSAttendanceRebuildingStatistics]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateList AS TABLE
        (
          DateIs DATE ,
          CountIs BIGINT
        );

      DECLARE @FromDate DATE ,
        @ToDate DATE ,
        @Days BIGINT ,
        @Index BIGINT ,
        @Return INT;

    END;

    BEGIN --Set info
	  
      SELECT  @FromDate = MIN(o.DateIs) ,
              @ToDate = MAX(o.ToDate)
      FROM    ( SELECT DISTINCT
                        s.DateIs ,
                        s.ToDate
                FROM    Gym.t_GymSubscription AS s
                UNION ALL
                SELECT DISTINCT
                        s.DateIs ,
                        s.ToDate
                FROM    Gym.t_GymSubscriptionHistory AS s
              ) AS o;
    
      SET @Days = DATEDIFF(DAY, @FromDate, @ToDate);

      SET @Index = 0;

      WHILE ( @Index <= @Days )
      BEGIN
		    
        INSERT  INTO @DateList
                ( DateIs )
        VALUES  ( DATEADD(DAY, @Index, @FromDate) );

        SET @Index += 1;

      END;
	 
    END;
	 
    BEGIN --Delete t_GymActiveVSAttendance

      SET @Return = 0;

      TRUNCATE TABLE Gym.t_GymActiveVSAttendance;
	  
    END;
   
    BEGIN --Insert t_GymActiveVSAttendance from t_GymSubscription

      INSERT  INTO Gym.t_GymActiveVSAttendance
              ( DateIs ,
                DateMonthly ,
                DateYearly ,
                ActiveNumber 
	          )
      SELECT  t.DateIs ,
              DATEFROMPARTS(YEAR(t.DateIs), MONTH(t.DateIs), 1) ,
              DATEFROMPARTS(YEAR(t.DateIs), 1, 1) ,
              ( SELECT  COUNT_BIG(*)
                FROM    Gym.t_GymSubscription AS s
                WHERE   s.DateIs <= t.DateIs
                        AND s.ToDate >= t.DateIs
              ) + ( SELECT  COUNT_BIG(*)
                    FROM    Gym.t_GymSubscriptionHistory AS s
                    WHERE   s.DateIs <= t.DateIs
                            AND s.ToDate >= t.DateIs
                  )
      FROM    @DateList AS t;
             
    END;
	   
    BEGIN --Insert t_GymActiveVSAttendance from t_GymMemberAttendance
	
      DELETE  FROM @DateList;

      INSERT  INTO @DateList
              ( DateIs ,
                CountIs
              )
      SELECT  s.DateOnly ,
              COUNT_BIG(*)
      FROM    Gym.t_GymMemberAttendance AS s
      GROUP BY s.DateOnly;

      MERGE Gym.t_GymActiveVSAttendance AS t
      USING @DateList AS s
      ON s.DateIs = t.DateIs
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( DateIs ,
                 DateMonthly ,
                 DateYearly ,
                 AttendanceNumber
               )
        VALUES ( s.DateIs ,
                 DATEFROMPARTS(YEAR(s.DateIs), MONTH(s.DateIs), 1) ,
                 DATEFROMPARTS(YEAR(s.DateIs), 1, 1) ,
                 s.CountIs
               )
      WHEN MATCHED THEN
        UPDATE SET
               t.AttendanceNumber += s.CountIs;
             
    END;

    BEGIN --Delete empty row

      DELETE  FROM Gym.t_GymActiveVSAttendance
      WHERE   ActiveNumber <= 0
              AND AttendanceNumber <= 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Gym.t_GymSubscriptionMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                '00000000-0000-0000-0000-000000000000' ,
                @Event ,
                6 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







