/****** Object:  StoredProcedure [Gym].[s_GymMemberAttendanceDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Gym].[s_GymMemberAttendanceDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateIs DATE ,
        @ToDate DATE ,
        @AccountID UNIQUEIDENTIFIER ,
        @Return INT;
 
    END;

    BEGIN --Set info
	    
      SELECT TOP ( 1 ) @DateIs = s.DateIs ,
          @ToDate = s.DateIs ,
          @AccountID = s.AccountID
        FROM Gym.t_GymMemberAttendance AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Gym.t_GymMemberAttendance
        WHERE ID = @ID;

    END;

    BEGIN --Fix t_GymActiveVSAttendance

      EXECUTE Gym.s_GymActiveVSAttendanceMerge @DateIs, @ToDate, 0, 0; 
	  
    END;
			
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Gym.t_GymMemberAttendanceMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Fix t_Account GymMemberAttendance

      UPDATE Company.t_Account
        SET GymMemberAttendanceC = [Gym].f_GymMemberAttendanceGetCountByAccountID(ID) ,
            GymMemberAttendanceLast = [Gym].f_GymMemberAttendanceGetLastByAccountID(ID)
        WHERE ID = @AccountID;
		  
    END;

    EXECUTE Gym.s_GymSubscriptionIncreasedTotalDaysAttendedPART @AccountID, @DateIs, -1;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;
	



GO
/****** Object:  StoredProcedure [Gym].[s_GymMemberAttendanceInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Gym].[s_GymMemberAttendanceInsert] @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @TypeIs TINYINT ,
  @IntegrationAccessLastIDSaved BIGINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER OUTPUT
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    IF @TypeIs = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                  FROM Gym.t_GymMemberAttendance AS s
                                  WHERE s.AccountID = @AccountID AND s.DateOnly = CONVERT(DATE, @DateIs) )
    BEGIN

      IF @TypeIs = 1 AND @IntegrationAccessLastIDSaved >= 1
      BEGIN --Update t_SettingPC

        UPDATE Users.t_SettingPC
          SET GymSubscriptionSettingUIIntegrationAccessLastIDSaved = @IntegrationAccessLastIDSaved;

      END;

      SET @ID = '00000000-0000-0000-0000-000000000000';

      COMMIT TRANSACTION;

      RETURN 1;

    END;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Account NVARCHAR(MAX) ,
        @AccountNumber NVARCHAR(MAX) ,
        @UserIs NVARCHAR(MAX) ,
        @return INT;

    END;

    BEGIN --Set info
	
      SET @Account = Company.f_AccountGetName(@AccountID);
      SET @AccountNumber = Company.f_AccountGetNumberF(@AccountID);
 
      SET @UserIs = Users.f_UserGetName(@UserID);
		      
    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Gym.t_GymMemberAttendance
          ( DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            AccountID ,
            Account ,
            AccountNumber ,
            TypeIs ,
            TypeIsAR ,
            TypeIsEN ,
            DescriptionIs
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @AccountID ,
            @Account ,
            @AccountNumber ,
            @TypeIs ,
            Gym.f_GymMemberAttendanceTypeIsARConvert(@TypeIs) ,
            Gym.f_GymMemberAttendanceTypeIsENConvert(@TypeIs) ,
            @DescriptionIs
          );

      SET @ID = ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s
                    ORDER BY s.ID
                );

    END;

    BEGIN --Insert Event

      SET @return = -1;

      INSERT INTO Gym.t_GymMemberAttendanceMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
  
    BEGIN --Fix t_Account GymMemberAttendance

      UPDATE Company.t_Account
        SET GymMemberAttendanceC += 1 ,
            GymMemberAttendanceLast = [Gym].f_GymMemberAttendanceGetLastByAccountID(ID)
        WHERE ID = @AccountID;

    END;

    BEGIN --Fix t_GymActiveVSAttendance

      EXECUTE Gym.s_GymActiveVSAttendanceMerge @DateIs, @DateIs, 0, 1; 
	  
    END;

    IF @TypeIs = 1 AND @IntegrationAccessLastIDSaved >= 1
    BEGIN --Update t_SettingPC

      UPDATE Users.t_SettingPC
        SET GymSubscriptionSettingUIIntegrationAccessLastIDSaved = @IntegrationAccessLastIDSaved;

    END;
   
    EXECUTE Gym.s_GymSubscriptionIncreasedTotalDaysAttendedPART @AccountID, @DateIs, 1;
    
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;


GO
