            t.SubtotalLL ,
            t.SubtotalEuro ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.TotalAR ,
            t.TotalEN ,
            t.FirstPayment ,
            t.FirstPaymentF ,
            t.FirstPaymentD ,
            t.FirstPaymentLL ,
            t.FirstPaymentEuro ,
            t.Payment ,
            t.PaymentF ,
            t.PaymentD ,
            t.PaymentLL ,
            t.PaymentEuro ,
            t.Rest ,
            t.RestF ,
            t.RestD ,
            t.RestLL ,
            t.RestEuro ,
            t.IsPaid ,
            t.IsPaidSalary ,
            t.AreClassesSalariesPaid ,
            t.Cost ,
            t.CostF ,
            t.CostD ,
            t.CostLL ,
            t.CostEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.UserID ,
            t.UserIs ,
            t.DescriptionIs ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Gym.t_GymSubscription AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Insert t_GymSubscriptionDeletedClass
	 
      INSERT INTO Gym.t_GymSubscriptionDeletedClass
          ( ID ,
            SubscriptionID ,
            ClassID ,
            ClassName ,
            AccountEmployeeID ,
            AccountEmployee ,
            AccountEmployeeNumber ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            SalaryPercent ,
            Salary ,
            SalaryF ,
            SalaryD ,
            SalaryLL ,
            SalaryEuro ,
            IsSalaryPaid ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.SubscriptionID ,
            t.ClassID ,
            t.ClassName ,
            t.AccountEmployeeID ,
            t.AccountEmployee ,
            t.AccountEmployeeNumber ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.SalaryPercent ,
            t.Salary ,
            t.SalaryF ,
            t.SalaryD ,
            t.SalaryLL ,
            t.SalaryEuro ,
            t.IsSalaryPaid ,
            t.DescriptionIs ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Gym.t_GymSubscriptionClass AS t
          WHERE t.SubscriptionID = @ID;

    END;

    BEGIN --Delete
				
      DELETE FROM Gym.t_GymSubscriptionClass
        WHERE SubscriptionID = @ID;

      DELETE FROM Gym.t_GymSubscription
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 174 AND LinkID = @ID;

    END;

    BEGIN --Fix t_GymActiveVSAttendance

      EXECUTE Gym.s_GymActiveVSAttendanceMerge @DateOnly_OLD, @ToDate, 1, 0; 
	  
    END;
			
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Gym.t_GymSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Fix t_Account GymSubscription

      UPDATE Company.t_Account
        SET GymSubscriptionC = [Gym].f_GymSubscriptionGetCountByAccountID(ID) ,
            GymSubscriptionLast = [Gym].f_GymSubscriptionGetLastByAccountID(ID) ,
            GymSubscriptionLastType = [Gym].f_GymSubscriptionGetLastTypeByAccountID(ID) ,
            GymSubscriptionTotal = [Gym].[f_GymSubscriptionGetTotalByAccountID](ID) ,
            GymSubscriptionProfit = [Gym].[f_GymSubscriptionGetProfitByAccountID](ID) ,
            GymSubscriptionActiveTo = [Gym].f_GymSubscriptionGetActiveToByAccountID(ID)
        WHERE ID = @AccountID;

      UPDATE Company.t_Account
        SET GymSubscriptionTotalF = Currencys.f_Format(CurrencyID, GymSubscriptionTotal) ,
            GymSubscriptionProfitF = Currencys.f_Format(CurrencyID, GymSubscriptionProfit) ,
            GymSubscriptionIsActive = IIF(GymSubscriptionActiveTo >= DateTimes.f_GetToday(), 1, 0)
        WHERE ID = @AccountID;
		  
    END;

    BEGIN --Fix t_SubscriptionType

      UPDATE Gym.t_SubscriptionType
        SET NumberOfSubscriptions -= 1
        WHERE ID = @SubscriptionTypeID;

    END;

    BEGIN --Fix t_PersonalTrainer

      UPDATE Gym.t_PersonalTrainer
        SET NumberOfSubscriptions -= 1
        WHERE ID = @PersonalTrainerID;

    END;

    BEGIN --Fix t_GymClass

      UPDATE Gym.t_GymClass
        SET NumberOfSubscriptions -= ( SELECT COUNT(*)
                                        FROM Gym.t_GymSubscriptionDeletedClass AS s
                                        WHERE s.ClassID = t_GymClass.ID AND s.SubscriptionID = @ID
                                     ) ,
            NumberOfActiveAccounts = Gym.f_GymClassGetNumberOfActiveAccounts(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Gym.t_GymSubscriptionDeletedClass AS s
                        WHERE s.ClassID = t_GymClass.ID AND s.SubscriptionID = @ID );

    END;
		  
    EXECUTE Invoices.s_ProfitDaily_Gym_Update_PART @DateOnly_OLD;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;
	


