/****** Object:  StoredProcedure [Gym].[s_GymSubscriptionIncreasedTotalDaysAttendedPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Gym].[s_GymSubscriptionIncreasedTotalDaysAttendedPART] @AccountID UNIQUEIDENTIFIER ,
  @DateIs DATE ,
  @TotalDaysAttended INT
AS
BEGIN;

  DISABLE TRIGGER Gym.tr_GymSubscription ON Gym.t_GymSubscription;
  
  DECLARE @LastID UNIQUEIDENTIFIER;

  SELECT TOP ( 1 ) @LastID = s.ID
    FROM Gym.t_GymSubscription AS s
    WHERE s.AccountID = @AccountID
    ORDER BY s.ToDate DESC;

  UPDATE Gym.t_GymSubscription
    SET TotalDaysAttended += @TotalDaysAttended ,
        IsSync = 0
    WHERE ID = @LastID;
 
  UPDATE Gym.t_GymSubscription
    SET RemainingDays = TotalSubscriptionDays - TotalDaysAttended
    WHERE ID = @LastID;

  UPDATE Gym.t_GymSubscription
    SET ToDate = Gym.f_GymSubscription_Check_IsActive(ToDate, RemainingDays, ActiveUntilUseDays) ,
        IsSync = 0
    WHERE ID = @LastID;

  UPDATE Gym.t_GymSubscription
    SET IsActive = IIF(ToDate >= DateTimes.f_GetToday(), 1, 0)
    WHERE ID = @LastID;

  ENABLE TRIGGER Gym.tr_GymSubscription ON Gym.t_GymSubscription;

END;











