    BEGIN --Delete
				
      DELETE FROM Gym.t_GymSubscriptionClass
        WHERE SubscriptionID = @ID;

      DELETE FROM Gym.t_GymSubscription
        WHERE ID = @ID;

    END;
	
    BEGIN --Fix t_GymClass

      UPDATE Gym.t_GymClass
