/****** Object:  StoredProcedure [Gym].[s_GymSubscriptionNewPayment]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Gym].[s_GymSubscriptionNewPayment] @DateIs DATE ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @NewPayment FLOAT ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @RefF NVARCHAR(MAX) ,
        @DateOnly_OLD DATE ,
        @AccountID UNIQUEIDENTIFIER ,
        @Account NVARCHAR(MAX) ,
        @DoorID NVARCHAR(MAX) ,
        @SubscriptionType NVARCHAR(MAX) ,
        @AccountBox NVARCHAR(MAX) ,
        @NewPaymentD FLOAT ,
        @UserIs NVARCHAR(MAX) ,
        @TrnID UNIQUEIDENTIFIER ,
        @TrnRef BIGINT ,
        @TrnStatementBase NVARCHAR(MAX) ,
        @TrnStatement NVARCHAR(MAX) ,
        @TrnRN INT ,
        @TrnLinkType INT = 174 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @RefF = s.RefF ,
          @DateOnly_OLD = s.DateIs ,
          @AccountID = s.AccountID ,
          @Account = s.Account ,
          @SubscriptionType = s.SubscriptionType ,
          @CID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro
        FROM Gym.t_GymSubscription AS s
        WHERE s.ID = @ID;

      SET @DoorID = FORMAT(Customers.f_CustomerGetIDDoorByAccount(@AccountID), '#');
	  
      SET @AccountBox = Company.f_AccountGetName(@AccountBoxID);
	 
      SET @NewPaymentD = @NewPayment / @E;

      SET @UserIs = Users.f_UserGetName(@UserID);
       
      SET @TrnStatementBase = N'GS:' + @RefF + N' ' + @StatementIs;
		      
    END;

    BEGIN --Insert

      SET @return = 0;

      UPDATE Gym.t_GymSubscription
        SET Payment += @NewPayment ,
            PaymentF = Currencys.f_Format(@CID, Payment + @NewPayment) ,
            PaymentD += @NewPaymentD ,
            PaymentLL += @NewPaymentD * @ELL ,
            PaymentEuro += @NewPaymentD * @EEuro ,
            Rest -= @NewPayment ,
            RestF = Currencys.f_Format(@CID, Rest - @NewPayment) ,
            RestD -= @NewPaymentD ,
            RestLL -= @NewPaymentD * @ELL ,
            RestEuro -= @NewPaymentD * @EEuro ,
            IsPaid = IIF(( Rest - @NewPayment ) = 0, 1, 0)
        WHERE ID = @ID;
		
    END;

    BEGIN --Insert Event

      SET @return = -1;

      INSERT INTO Gym.t_GymSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TrnRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TrnRef ,
              N'RV' ,
              @DateIs ,
              @TrnStatementBase ,
              @TrnLinkType ,
              @ID ,
              @UserID
            );

        SET @TrnID = ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        ORDER BY s.ID
                     );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TrnID ,
              CONVERT(NVARCHAR(MAX), @TrnRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @NewPayment;
        SET @TrnRN = 1;
        SET @TrnStatement = @DoorID + N' \ ' + @Account + N' \ ' + @SubscriptionType + N' \ ' + @TrnStatementBase;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @TrnRN, @TrnID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TrnStatement;
       
        SET @TrnRN += 1;
        SET @TrnStatement = @SubscriptionType + N' \ ' + @TrnStatementBase;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @TrnRN, @TrnID, @AccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @TrnStatement;

      END;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            @TrnID ,
            @Event + s.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @AccountID, @AccountBoxID ) AND StatusIs = 1;
  
      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;
  
    EXECUTE Invoices.s_ProfitDaily_Gym_Update_PART @DateOnly_OLD;
   
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;




GO
