/****** Object:  StoredProcedure [Gym].[s_GymSubscriptionRebuildTotalDaysAttended]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Gym].[s_GymSubscriptionRebuildTotalDaysAttended] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN;

  DISABLE TRIGGER Gym.tr_GymSubscription ON Gym.t_GymSubscription;

  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild
   
      UPDATE Gym.t_GymSubscription
        SET TotalDaysAttended = Gym.f_GymMemberAttendanceGetTotalDaysAttended(AccountID, DateIs, ToDate) ,
            IsSync = 0;
 
      UPDATE Gym.t_GymSubscription
        SET RemainingDays = TotalSubscriptionDays - TotalDaysAttended;
 
      UPDATE Gym.t_GymSubscription
        SET ToDate = Gym.f_GymSubscription_Check_IsActive(ToDate, RemainingDays, ActiveUntilUseDays);
 
      UPDATE Gym.t_GymSubscription
        SET IsActive = IIF(ToDate >= DateTimes.f_GetToday(), 1, 0);

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Gym.t_GymSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, GymSubscription, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaGym, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;
	
    ENABLE TRIGGER Gym.tr_GymSubscription ON Gym.t_GymSubscription;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Gym.tr_GymSubscription ON Gym.t_GymSubscription;

    RETURN @Return;

  END CATCH;

END;







