/****** Object:  StoredProcedure [Gym].[s_ReferralDiscountForGymUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Gym].[s_ReferralDiscountForGymUpdate] @ID UNIQUEIDENTIFIER ,
  @DescriptionIs NVARCHAR(MAX) ,
  @NumberOfCustomers INT ,
  @Customers Gym.tt_ReferralDiscountForGymCustomers READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;
					
    END;

    BEGIN --Insert

      UPDATE Gym.t_ReferralDiscountForGym
        SET DescriptionIs = @DescriptionIs ,
            NumberOfCustomers = @NumberOfCustomers
        WHERE ID = @ID;

    END;

    BEGIN --Merge t_ReferralDiscountForGymCustomers

      MERGE Gym.t_ReferralDiscountForGymCustomers AS t
      USING @Customers AS s
      ON t.ID = s.ID AND t.ReferralDiscountForGymID = @ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 ReferralDiscountForGymID ,
                 AccountID ,
                 DescriptionIs ,
                 CreatedByUserID 
               )
        VALUES ( s.ID ,
                 s.ReferralDiscountForGymID ,
                 s.AccountID ,
                 s.DescriptionIs ,
                 @UserID
               )
      WHEN MATCHED THEN
        UPDATE SET t.DescriptionIs = s.DescriptionIs
      WHEN NOT MATCHED BY SOURCE AND t.ReferralDiscountForGymID = @ID THEN
        DELETE;

    END;

    SET @Return = -1;
    EXECUTE Gym.s_ReferralDiscountForGymMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;     

    EXECUTE Gym.s_ReferralDiscountForGymLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    SELECT @Return;

  END CATCH;

END;




