/****** Object:  StoredProcedure [Gym].[s_SubscriptionTypeInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Gym].[s_SubscriptionTypeInsert] @Name NVARCHAR(MAX) ,
  @TypeIs TINYINT ,
  @NumberIs INT ,
  @TotalSubscriptionDays INT ,
  @ActiveUntilUseDays BIT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Price FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER OUTPUT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Return INT ,
        @ExchangeRate FLOAT ,
        @PriceF NVARCHAR(MAX) ,
        @PriceD FLOAT;
					
    END;

    BEGIN --Set info
		
      SET @ExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyID);
      SET @PriceD = @Price / @ExchangeRate;
      SET @PriceF = Currencys.f_Format(@CurrencyID, @Price);

    END;

    BEGIN --Insert

      SET @Return = 0;

      INSERT INTO Gym.t_SubscriptionType
          ( Name ,
            NameF ,
            TypeIs ,
            NumberIs ,
            TimePeriodDays ,
            TimePeriodARF ,
            TimePeriodENF ,
            TotalSubscriptionDays ,
            ActiveUntilUseDays ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DescriptionIs
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Name ,
            Gym.f_SubscriptionTypeNameFFix(@Name, @TypeIs, @PriceF) ,
            @TypeIs ,
            @NumberIs ,
            Gym.f_SubscriptionTypeTimePeriodDaysFix(@TypeIs, @NumberIs) ,
            Gym.f_SubscriptionTypeTimePeriodARFFix(@TypeIs, @NumberIs) ,
            Gym.f_SubscriptionTypeTimePeriodENFFix(@TypeIs, @NumberIs) ,
            @TotalSubscriptionDays ,
            @ActiveUntilUseDays ,
            @CurrencyID ,
            Currencys.f_CurrencyGetName(@CurrencyID) ,
            @Price ,
            @PriceF ,
            @PriceD ,
            Currencys.f_ExchangeToLL(@CurrencyID, @Price, @PriceD) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @PriceD) ,
            @DescriptionIs
          );

      SET @ID = ( SELECT TOP ( 1 ) ID
                    FROM @IDs
                    ORDER BY ID
                );

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Gym.t_SubscriptionTypeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
