/****** Object:  StoredProcedure [Invoices].[s_DaysPackageRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_DaysPackageRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild statistics

      UPDATE Invoices.t_DaysPackage
        SET TotalF = Currencys.f_Format(CurrencyID, Total) ,
            IsSync = 0;

    END;
  
    BEGIN --Rebuild statistics t_DaysPackageDetail

      WITH  o AS ( SELECT s.SalePrice ,
                      s.SalePriceF ,
                      s.TotalSalePrice ,
                      s.TotalSalePriceF ,
                      s.IsSync ,
                      s1.CurrencyID
                    FROM Invoices.t_DaysPackageDetail AS s
                    INNER JOIN Invoices.t_DaysPackage AS s1 ON s1.ID = s.DaysPackageID
                 )
        UPDATE o
          SET SalePriceF = Currencys.f_Format(CurrencyID, SalePrice) ,
              TotalSalePriceF = Currencys.f_Format(CurrencyID, TotalSalePrice) ,
              IsSync = 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_DaysPackageMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    EXECUTE Invoices.s_DaysPackageLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






