/****** Object:  StoredProcedure [Invoices].[s_DeliveryServiceDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_DeliveryServiceDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @CustomerID UNIQUEIDENTIFIER ,
        @Return INT;
 
    END;

    BEGIN --Set info
	    
      SELECT TOP ( 1 ) @CustomerID = s.AccountCustomerID
        FROM Invoices.t_DeliveryService AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert t_DeliveryServiceDeleted

      SET @Return = 0;

      INSERT INTO Invoices.t_DeliveryServiceDeleted
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            DateIs ,
            DateOnly ,
            TimeOnly ,
            DateMonthly ,
            DateYearly ,
            TypeIs ,
            StatusIs ,
            DescriptionIs ,
            UserID ,
            UserIs ,
            AccountVendorID ,
            AccountVendor ,
            AccountVendorNumber ,
            FromAddress ,
            ItemsNames ,
            CostCurrencyID ,
            CostCurrency ,
            CostExchangeRate ,
            CostExchangeRateLL ,
            CostExchangeRateEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Payment ,
            PaymentF ,
            PaymentD ,
            PaymentLL ,
            PaymentEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            AccountCustomerID ,
            AccountCustomer ,
            AccountCustomerNumber ,
            AccountCustomerIsVendor ,
            ToAddress ,
            DeliveryDate ,
            DeliveryChargeCurrencyID ,
            DeliveryChargeCurrency ,
            DeliveryChargeExchangeRate ,
            DeliveryChargeExchangeRateLL ,
            DeliveryChargeExchangeRateEuro ,
            DeliveryCharge ,
            DeliveryChargeF ,
            DeliveryChargeD ,
            DeliveryChargeLL ,
            DeliveryChargeEuro ,
            DeliveryChargeStatus ,
            AccountEmployeeID ,
            AccountEmployee ,
            AccountEmployeeNumber ,
            AssignDate ,
            Expense ,
            ExpenseF ,
            ExpenseD ,
            ExpenseLL ,
            ExpenseEuro ,
            ExpenseStatus ,
            ExpensePaymentDate ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
          SELECT t.ID ,
              t.Ref ,
              t.RefF ,
              t.RefPaper ,
              t.DateIs ,
              t.DateOnly ,
              t.TimeOnly ,
              t.DateMonthly ,
              t.DateYearly ,
              t.TypeIs ,
              t.StatusIs ,
              t.DescriptionIs ,
              t.UserID ,
              t.UserIs ,
              t.AccountVendorID ,
              t.AccountVendor ,
              t.AccountVendorNumber ,
              t.FromAddress ,
              t.ItemsNames ,
              t.CostCurrencyID ,
              t.CostCurrency ,
              t.CostExchangeRate ,
              t.CostExchangeRateLL ,
              t.CostExchangeRateEuro ,
              t.Cost ,
              t.CostF ,
              t.CostD ,
              t.CostLL ,
              t.CostEuro ,
              t.Payment ,
              t.PaymentF ,
              t.PaymentD ,
              t.PaymentLL ,
              t.PaymentEuro ,
              t.Rest ,
              t.RestF ,
              t.RestD ,
              t.RestLL ,
              t.RestEuro ,
              t.AccountCustomerID ,
              t.AccountCustomer ,
              t.AccountCustomerNumber ,
              t.AccountCustomerIsVendor ,
              t.ToAddress ,
              t.DeliveryDate ,
              t.DeliveryChargeCurrencyID ,
              t.DeliveryChargeCurrency ,
              t.DeliveryChargeExchangeRate ,
              t.DeliveryChargeExchangeRateLL ,
              t.DeliveryChargeExchangeRateEuro ,
              t.DeliveryCharge ,
              t.DeliveryChargeF ,
              t.DeliveryChargeD ,
              t.DeliveryChargeLL ,
              t.DeliveryChargeEuro ,
              t.DeliveryChargeStatus ,
              t.AccountEmployeeID ,
              t.AccountEmployee ,
              t.AccountEmployeeNumber ,
              t.AssignDate ,
              t.Expense ,
              t.ExpenseF ,
              t.ExpenseD ,
              t.ExpenseLL ,
              t.ExpenseEuro ,
              t.ExpenseStatus ,
              t.ExpensePaymentDate ,
              t.DateCreate ,
              t.IsSync ,
              t.WorkStationID
            FROM Invoices.t_DeliveryService AS t
            WHERE t.ID = @ID;

    END;

    BEGIN --Delete
		
      DELETE FROM Invoices.t_DeliveryService
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 162 AND LinkID = @ID;

    END;
			
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_DeliveryServiceMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Fix t_Account DeliveryServices

      UPDATE Company.t_Account
        SET DeliveryServicesC = [Invoices].f_DeliveryServiceGetCountByAccountCustomerID(ID) ,
            DeliveryServicesLastDate = [Invoices].f_DeliveryServiceGetLastDateByAccountCustomerID(ID) ,
            DeliveryServicesTotal = [Invoices].[f_DeliveryServiceGetTotalByAccountCustomerID](ID) ,
            DeliveryServicesProfit = [Invoices].[f_DeliveryServiceGetProfitByAccountCustomerID](ID)
        WHERE ID = @CustomerID;

      UPDATE Company.t_Account
        SET DeliveryServicesTotalF = Currencys.f_Format(CurrencyID, DeliveryServicesTotal) ,
            DeliveryServicesProfitF = Currencys.f_Format(CurrencyID, DeliveryServicesProfit)
        WHERE ID = @CustomerID;
		  
    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;
	

GO
/****** Object:  StoredProcedure [Invoices].[s_DeliveryServiceDeletedRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_DeliveryServiceDeletedRebuildingStatistics]
    @UserID UNIQUEIDENTIFIER ,
    @Event NVARCHAR(MAX) ,
    @ComputerIP NVARCHAR(MAX) ,
    @Computer NVARCHAR(MAX) ,
    @ComputerAccount NVARCHAR(MAX)
AS
    BEGIN
        BEGIN TRY
            BEGIN TRANSACTION;

            BEGIN --Declare

                DECLARE @Return INT;

            END;

            DISABLE TRIGGER Invoices.tr_DeliveryServiceDeleted ON Invoices.t_DeliveryServiceDeleted;

            BEGIN --Rebuild statistics

                SET @Return = 0;

                UPDATE  Invoices.t_DeliveryServiceDeleted
                SET     RefF = FORMAT(Ref, '#') ,
                        TypeIsAR = Invoices.f_DeliveryServiceGetTypeIsAR(TypeIs) ,
                        TypeIsEN = Invoices.f_DeliveryServiceGetTypeIsEN(TypeIs) ,
                        StatusIsAR = Invoices.f_DeliveryServiceGetStatusIsAR(StatusIs) ,
                        StatusIsEN = Invoices.f_DeliveryServiceGetStatusIsEN(StatusIs) ,
                        UserIs = Users.f_UserGetName(UserID) ,
                        AccountVendor = Company.f_AccountGetName(AccountVendorID) ,
                        CostCurrency = Currencys.f_CurrencyGetName(CostCurrencyID) ,
                        CostF = Currencys.f_Format(CostCurrencyID, Cost) ,
                        PaymentF = Currencys.f_Format(CostCurrencyID, Payment) ,
                        RestF = Currencys.f_Format(CostCurrencyID, Rest) ,
                        AccountCustomer = Company.f_AccountGetName(AccountCustomerID) ,
                        DeliveryChargeCurrency = Currencys.f_CurrencyGetName(DeliveryChargeCurrencyID) ,
                        DeliveryChargeF = Currencys.f_Format(DeliveryChargeCurrencyID, DeliveryCharge) ,
                        DeliveryChargeStatusAR = Invoices.f_DeliveryServiceGetDeliveryChargeStatusAR(DeliveryChargeStatus) ,
                        DeliveryChargeStatusEN = Invoices.f_DeliveryServiceGetDeliveryChargeStatusEN(DeliveryChargeStatus) ,
                        AccountEmployee = Company.f_AccountGetName(AccountEmployeeID) ,
                        ExpenseF = Currencys.f_Format(DeliveryChargeCurrencyID, Expense) ,
                        ExpenseStatusAR = Invoices.f_DeliveryServiceGetExpenseStatusAR(ExpenseStatus) ,
                        ExpenseStatusEN = Invoices.f_DeliveryServiceGetExpenseStatusEN(ExpenseStatus) ,
                        ProcessIn = CASE WHEN Rest > 0 THEN 0
                                         WHEN DeliveryCharge > 0
                                              AND DeliveryChargeStatus = 0 THEN 0
                                         WHEN Expense > 0
                                              AND ExpenseStatus = 0 THEN 0
                                         ELSE 1
                                    END;

            END;

            BEGIN --Insert event

                SET @Return = -1;

                INSERT  INTO Invoices.t_DeliveryServiceMoving
                        ( UserID ,
                          SectionID ,
                          EventIs ,
                          EventType ,
                          ComputerIP ,
                          Computer ,
                          ComputerAccount
                        )
                VALUES  ( @UserID ,
                          '00000000-0000-0000-0000-000000000000' ,
                          @Event ,
                          6 ,
                          @ComputerIP ,
                          @Computer ,
                          @ComputerAccount
                        );

            END;

            BEGIN --Live

                UPDATE  Alls.t_LiveVersion
                SET     VersionLive = STUFF(VersionLive, DeliveryService, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
                        SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

            END;

            ENABLE TRIGGER Invoices.tr_DeliveryServiceDeleted ON Invoices.t_DeliveryServiceDeleted;

            COMMIT TRANSACTION;

            RETURN 1;

        END TRY
        BEGIN CATCH

            ROLLBACK;

            RETURN @Return;

        END CATCH;

    END;





GO
