/****** Object:  StoredProcedure [Invoices].[s_DeliveryServiceInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_DeliveryServiceInsert] @RefPaper NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @TypeIs TINYINT ,
  @StatusIs TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @VendorID UNIQUEIDENTIFIER ,
  @FromAddress NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @CostCurrencyID UNIQUEIDENTIFIER ,
  @CostExchangeRate FLOAT ,
  @CostExchangeRateLL FLOAT ,
  @CostExchangeRateEuro FLOAT ,
  @Cost FLOAT ,
  @Payment FLOAT ,
  @CustomerID UNIQUEIDENTIFIER ,
  @ToAddress NVARCHAR(MAX) ,
  @DeliveryDate DATETIME ,
  @DeliveryChargeCurrencyID UNIQUEIDENTIFIER ,
  @DeliveryChargeExchangeRate FLOAT ,
  @DeliveryChargeExchangeRateLL FLOAT ,
  @DeliveryChargeExchangeRateEuro FLOAT ,
  @DeliveryCharge FLOAT ,
  @DeliveryChargeStatus TINYINT ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @EmployeeSalaryID UNIQUEIDENTIFIER ,
  @AssignDate DATETIME ,
  @Expense FLOAT ,
  @ExpenseStatus TINYINT ,
  @ExpensePaymentDate DATETIME ,
  @PurchaseID UNIQUEIDENTIFIER ,
  @BoxID UNIQUEIDENTIFIER ,
  @SaleID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER OUTPUT
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @Vendor NVARCHAR(MAX) ,
        @CostCurrency NVARCHAR(MAX) ,
        @Customer NVARCHAR(MAX) ,
        @DeliveryChargeCurrency NVARCHAR(MAX) ,
        @Employee NVARCHAR(MAX) ,
        @EmployeeSalary NVARCHAR(MAX) ,
        @Purchase NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Sale NVARCHAR(MAX) ,
        @CostD FLOAT ,
        @PaymentD FLOAT ,
        @Rest FLOAT ,
        @RestD FLOAT ,
        @DeliveryChargeD FLOAT ,
        @ExpenseD FLOAT ,
        @User NVARCHAR(MAX) ,
        @return INT ,
        @LinkType INT = 162 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(o.Ref), 0) + 1
        FROM ( SELECT s.Ref
                FROM Invoices.t_DeliveryService AS s
               UNION ALL
               SELECT s1.Ref
                FROM Invoices.t_DeliveryServiceHistory AS s1
             ) AS o;

      SET @RefF = FORMAT(@Ref, '#');

      SET @Vendor = Company.f_AccountGetName(@VendorID);

      SET @CostCurrency = Currencys.f_CurrencyGetName(@CostCurrencyID);

      SET @Customer = Company.f_AccountGetName(@CustomerID);
	          
      SET @DeliveryChargeCurrency = Currencys.f_CurrencyGetName(@DeliveryChargeCurrencyID);
         
      SET @Employee = Company.f_AccountGetName(@EmployeeID);

      SET @EmployeeSalary = Company.f_AccountGetName(@EmployeeSalaryID);

      SET @Purchase = Company.f_AccountGetName(@PurchaseID);

      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @Sale = Company.f_AccountGetName(@SaleID);
	          	
      SET @CostD = @Cost / @CostExchangeRate;

      SET @PaymentD = @Payment / @CostExchangeRate;

      SET @Rest = @Cost - @Payment;

      SET @RestD = @Rest / @CostExchangeRate;

      SET @DeliveryChargeD = @DeliveryCharge / @DeliveryChargeExchangeRate;

      SET @ExpenseD = @Expense / @DeliveryChargeExchangeRate;

      SET @User = Users.f_UserGetName(@UserID);
               
      IF @EmployeeID = '00000000-0000-0000-0000-000000000000'
      BEGIN
			                                                               
        SET @AssignDate = DATETIMEFROMPARTS(2000, 1, 1, 0, 0, 0, 0);

      END;

      IF @ExpenseStatus = 0
      BEGIN
						                          
        SET @ExpensePaymentDate = DATETIMEFROMPARTS(2000, 1, 1, 0, 0, 0, 0);

      END;

    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Invoices.t_DeliveryService
          ( Ref ,
            RefF ,
            RefPaper ,
            DateIs ,
            DateOnly ,
            TimeOnly ,
            DateMonthly ,
            DateYearly ,
            TypeIs ,
            TypeIsAR ,
            TypeIsEN ,
            StatusIs ,
            StatusIsAR ,
            StatusIsEN ,
            DescriptionIs ,
            UserID ,
            UserIs ,
            AccountVendorID ,
            AccountVendor ,
            AccountVendorNumber ,
            FromAddress ,
            ItemsNames ,
            CostCurrencyID ,
            CostCurrency ,
            CostExchangeRate ,
            CostExchangeRateLL ,
            CostExchangeRateEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Payment ,
            PaymentF ,
            PaymentD ,
            PaymentLL ,
            PaymentEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            AccountCustomerID ,
            AccountCustomer ,
            AccountCustomerNumber ,
            ToAddress ,
            DeliveryDate ,
            DeliveryChargeCurrencyID ,
            DeliveryChargeCurrency ,
            DeliveryChargeExchangeRate ,
            DeliveryChargeExchangeRateLL ,
            DeliveryChargeExchangeRateEuro ,
            DeliveryCharge ,
            DeliveryChargeF ,
            DeliveryChargeD ,
            DeliveryChargeLL ,
            DeliveryChargeEuro ,
            DeliveryChargeStatus ,
            DeliveryChargeStatusAR ,
            DeliveryChargeStatusEN ,
            AccountEmployeeID ,
            AccountEmployee ,
            AccountEmployeeNumber ,
            AssignDate ,
            Expense ,
            ExpenseF ,
            ExpenseD ,
            ExpenseLL ,
            ExpenseEuro ,
            ExpenseStatus ,
            ExpenseStatusAR ,
            ExpenseStatusEN ,
            ExpensePaymentDate
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Ref ,
            @RefF ,
            @RefPaper ,
            @DateIs ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @TypeIs ,
            Invoices.f_DeliveryServiceGetTypeIsAR(@TypeIs) ,
            Invoices.f_DeliveryServiceGetTypeIsEN(@TypeIs) ,
            @StatusIs ,
            Invoices.f_DeliveryServiceGetStatusIsAR(@StatusIs) ,
            Invoices.f_DeliveryServiceGetStatusIsEN(@StatusIs) ,
            @DescriptionIs ,
            @UserID ,
            @User ,
            @VendorID ,
            @Vendor ,
            Company.f_AccountGetNumberF(@VendorID) ,
            @FromAddress ,
            @ItemsNames ,
            @CostCurrencyID ,
            @CostCurrency ,
            @CostExchangeRate ,
            @CostExchangeRateLL ,
            @CostExchangeRateEuro ,
            @Cost ,
            Currencys.f_Format(@CostCurrencyID, @Cost) ,
            @CostD ,
            @CostD * @CostExchangeRateLL ,
            @CostD * @CostExchangeRateEuro ,
            @Payment ,
            Currencys.f_Format(@CostCurrencyID, @Payment) ,
            @PaymentD ,
            @PaymentD * @CostExchangeRateLL ,
            @PaymentD * @CostExchangeRateEuro ,
            @Rest ,
            Currencys.f_Format(@CostCurrencyID, @Rest) ,
            @RestD ,
            @RestD * @CostExchangeRateLL ,
            @RestD * @CostExchangeRateEuro ,
            @CustomerID ,
            @Customer ,
            Company.f_AccountGetNumberF(@CustomerID) ,
            @ToAddress ,
            @DeliveryDate ,
            @DeliveryChargeCurrencyID ,
            @DeliveryChargeCurrency ,
            @DeliveryChargeExchangeRate ,
            @DeliveryChargeExchangeRateLL ,
            @DeliveryChargeExchangeRateEuro ,
            @DeliveryCharge ,
            Currencys.f_Format(@DeliveryChargeCurrencyID, @DeliveryCharge) ,
            @DeliveryChargeD ,
            @DeliveryChargeD * @DeliveryChargeExchangeRateLL ,
            @DeliveryChargeD * @DeliveryChargeExchangeRateEuro ,
            @DeliveryChargeStatus ,
            Invoices.f_DeliveryServiceGetDeliveryChargeStatusAR(@DeliveryChargeStatus) ,
            Invoices.f_DeliveryServiceGetDeliveryChargeStatusEN(@DeliveryChargeStatus) ,
            @EmployeeID ,
            @Employee ,
            Company.f_AccountGetNumberF(@EmployeeID) ,
            @AssignDate ,
            @Expense ,
            Currencys.f_Format(@DeliveryChargeCurrencyID, @Expense) ,
            @ExpenseD ,
            @ExpenseD * @DeliveryChargeExchangeRateLL ,
            @ExpenseD * @DeliveryChargeExchangeRateEuro ,
            @ExpenseStatus ,
            Invoices.f_DeliveryServiceGetExpenseStatusAR(@ExpenseStatus) ,
            Invoices.f_DeliveryServiceGetExpenseStatusEN(@ExpenseStatus) ,
            IIF(@ExpenseStatus = 0, DATETIMEFROMPARTS(2000, 1, 1, 0, 0, 0, 0), @ExpensePaymentDate)
          );

      SET @ID = ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s
                    ORDER BY s.ID
                );

    END;

    BEGIN --Fix data t_DeliveryService

      UPDATE Invoices.t_DeliveryService
        SET ProcessIn = CASE WHEN Rest > 0 THEN 0
                             WHEN DeliveryCharge > 0 AND DeliveryChargeStatus = 0 THEN 0
                             WHEN Expense > 0 AND ExpenseStatus = 0 THEN 0
                             ELSE 1
                        END ,
            AccountCustomerIsVendor = IIF(AccountCustomerID = AccountVendorID, 1, 0)
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_DeliveryServiceMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + @RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @EmployeeID <> '00000000-0000-0000-0000-000000000000' AND @Expense > 0
    BEGIN
						
      WITH  o AS ( SELECT s1.SalaryDeliveryService ,
                      Currencys.f_ExchangeToAccountCurrency(@DeliveryChargeCurrencyID, @DeliveryChargeExchangeRate, @Expense, s1.FirstSalaryCurrencyID) AS SalaryDeliveryService_ ,
                      s1.SalaryDeliveryServiceF ,
                      s1.FirstSalaryCurrencyID
                    FROM Company.t_Account AS s
                      INNER JOIN Employees.t_Employee AS s1 ON s.LinkWithID = s1.ID
                    WHERE s.ID = @EmployeeID
                 )
        UPDATE o
          SET o.SalaryDeliveryService = o.SalaryDeliveryService_ ,
              o.SalaryDeliveryServiceF = Currencys.f_Format(o.FirstSalaryCurrencyID, o.SalaryDeliveryService_);

    END;

    IF @Cost > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              N'DS:' + @RefF ,
              @LinkType ,
              1 ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @CID = @CostCurrencyID;
        SET @E = @CostExchangeRate;
        SET @ELL = @CostExchangeRateLL;
        SET @EEuro = @CostExchangeRateEuro;
        SET @V = @Cost;
        SET @VD = @CostD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro )
          VALUES  ( 1, @TransactionID, @PurchaseID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF + ' \ ' + @Vendor, @CID, @E , @ELL , @EEuro ),
                  ( 2, @TransactionID, @VendorID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF, @CID, @E  , @ELL , @EEuro);
	  
      END;

    END;

    IF @Payment > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              N'DS:' + @RefF ,
              @LinkType ,
              2 ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );


        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @CID = @CostCurrencyID;
        SET @E = @CostExchangeRate;
        SET @ELL = @CostExchangeRateLL;
        SET @EEuro = @CostExchangeRateEuro;
        SET @V = @Payment;
        SET @VD = @PaymentD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro )
          VALUES  ( 1, @TransactionID, @VendorID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF, @CID, @E  , @ELL , @EEuro),
                  ( 2, @TransactionID, @PurchaseID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF + ' \ ' + @Vendor, @CID, @E  , @ELL , @EEuro);

      END;

    END;

    IF @DeliveryCharge > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              N'DS:' + @RefF ,
              @LinkType ,
              3 ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @CID = @DeliveryChargeCurrencyID;
        SET @E = @DeliveryChargeExchangeRate;
        SET @ELL = @DeliveryChargeExchangeRateLL;
        SET @EEuro = @DeliveryChargeExchangeRateEuro;
        SET @V = @DeliveryCharge;
        SET @VD = @DeliveryChargeD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro  )
          VALUES  ( 1, @TransactionID, @CustomerID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF, @CID, @E  , @ELL , @EEuro ),
                  ( 2, @TransactionID, @SaleID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF + ' \ ' + @Customer, @CID, @E  , @ELL , @EEuro );

      END;

    END;

    IF @DeliveryCharge > 0 AND @DeliveryChargeStatus = 1
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'RV' ,
              @DateIs ,
              N'DS:' + @RefF ,
              @LinkType ,
              4 ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @CID = @DeliveryChargeCurrencyID;
        SET @E = @DeliveryChargeExchangeRate;
        SET @ELL = @DeliveryChargeExchangeRateLL;
        SET @EEuro = @DeliveryChargeExchangeRateEuro;
        SET @V = @DeliveryCharge;
        SET @VD = @DeliveryChargeD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate , ExchangeRateLL, ExchangeRateEuro )
          VALUES  ( 1, @TransactionID, @BoxID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF + ' \ ' + @Customer, @CID, @E , @ELL , @EEuro  ),
                  ( 2, @TransactionID, @CustomerID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF, @CID, @E , @ELL , @EEuro  );

      END;

    END;

    IF @EmployeeID <> '00000000-0000-0000-0000-000000000000'
    BEGIN
               
      IF @Expense > 0
      BEGIN --Transaction

        BEGIN --Set info

          SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
            FROM Transactions.t_Transaction AS s
            WHERE s.TypeIs = N'JV';

        END;

        BEGIN --Insert transaction

          SET @return = 0;

          DELETE FROM @IDs;

          INSERT INTO Transactions.t_Transaction
              ( Ref ,
                TypeIs ,
                DateIs ,
                DescriptionIs ,
                LinkType ,
                LinkTypeSub ,
                LinkID ,
                UserID
              )
            OUTPUT Inserted.ID
              INTO @IDs ( ID )
            VALUES
              ( @TransactionRef ,
                N'JV' ,
                @DateIs ,
                N'DS:' + @RefF ,
                @LinkType ,
                5 ,
                @ID ,
                @UserID
              );

          SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  ORDER BY s.ID
                               );

          INSERT @TrnIDs
              ( ID ,
                RefF
              )
            VALUES
              ( @TransactionID ,
                CONVERT(NVARCHAR(MAX), @TransactionRef)
              );

        END;

        BEGIN --Insert detail
					
          SET @CID = @DeliveryChargeCurrencyID;
          SET @E = @DeliveryChargeExchangeRate;
          SET @ELL = @DeliveryChargeExchangeRateLL;
          SET @EEuro = @DeliveryChargeExchangeRateEuro;
          SET @V = @Expense;
          SET @VD = @ExpenseD;

          INSERT INTO Transactions.t_TransactionDetail
              ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate , ExchangeRateLL, ExchangeRateEuro )
            VALUES  ( 1, @TransactionID, @EmployeeSalaryID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF, @CID, @E , @ELL , @EEuro  ),
                    ( 2, @TransactionID, @EmployeeID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF, @CID, @E , @ELL , @EEuro  );

        END;

      END;
 
      IF @ExpenseStatus = 1 AND @Expense > 0
      BEGIN --Transaction

        BEGIN --Set info

          SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
            FROM Transactions.t_Transaction AS s
            WHERE s.TypeIs = N'JV';

        END;

        BEGIN --Insert transaction

          SET @return = 0;

          DELETE FROM @IDs;

          INSERT INTO Transactions.t_Transaction
              ( Ref ,
                TypeIs ,
                DateIs ,
                DescriptionIs ,
                LinkType ,
                LinkTypeSub ,
                LinkID ,
                UserID
              )
            OUTPUT Inserted.ID
              INTO @IDs ( ID )
            VALUES
              ( @TransactionRef ,
                N'JV' ,
                @DateIs ,
                N'DS:' + @RefF ,
                @LinkType ,
                6 ,
                @ID ,
                @UserID
              );

          SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  ORDER BY s.ID
                               );

          INSERT @TrnIDs
              ( ID ,
                RefF
              )
            VALUES
              ( @TransactionID ,
                CONVERT(NVARCHAR(MAX), @TransactionRef)
              );

        END;

        BEGIN --Insert detail
					
          SET @CID = @DeliveryChargeCurrencyID;
          SET @E = @DeliveryChargeExchangeRate;
          SET @ELL = @DeliveryChargeExchangeRateLL;
          SET @EEuro = @DeliveryChargeExchangeRateEuro;
          SET @V = @Expense;
          SET @VD = @ExpenseD;

          INSERT INTO Transactions.t_TransactionDetail
              ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro  )
            VALUES  ( 1, @TransactionID, @EmployeeID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF, @CID, @E , @ELL , @EEuro  ),
                    ( 2, @TransactionID, @BoxID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF + ' \ ' + @Employee, @CID, @E , @ELL , @EEuro  );

        END;

      END;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
          SELECT @UserID ,
              @TransactionID ,
              @Event + s.RefF ,
              0 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            FROM @TrnIDs AS s;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @BoxID, @CustomerID, @EmployeeID, @EmployeeSalaryID, @PurchaseID, @SaleID, @VendorID ) AND StatusIs = 1;
  
      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;
     
    BEGIN --Fix t_Account DeliveryServices

      UPDATE Company.t_Account
        SET DeliveryServicesC += 1 ,
            DeliveryServicesLastDate = [Invoices].f_DeliveryServiceGetLastDateByAccountCustomerID(ID) ,
            DeliveryServicesTotal += CASE CurrencyTypeIs
                                       WHEN 0 THEN @DeliveryChargeD
                                       WHEN 1 THEN @DeliveryChargeD * @DeliveryChargeExchangeRateLL
                                       ELSE @DeliveryChargeD * @DeliveryChargeExchangeRateEuro
                                     END ,
            DeliveryServicesProfit += CASE CurrencyTypeIs
                                        WHEN 0 THEN @DeliveryChargeD - @ExpenseD
                                        WHEN 1 THEN ( @DeliveryChargeD * @DeliveryChargeExchangeRateLL ) - ( @ExpenseD * @DeliveryChargeExchangeRateLL )
                                        ELSE ( @DeliveryChargeD * @DeliveryChargeExchangeRateEuro ) - ( @ExpenseD * @DeliveryChargeExchangeRateEuro )
                                      END
        WHERE ID = @CustomerID;

      UPDATE Company.t_Account
        SET DeliveryServicesTotalF = Currencys.f_Format(CurrencyID, DeliveryServicesTotal) ,
            DeliveryServicesProfitF = Currencys.f_Format(CurrencyID, DeliveryServicesProfit)
        WHERE ID = @CustomerID;

    END;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;



