        @PaymentOld FLOAT ,
        @PaymentOldD FLOAT ,
        @PaymentNewD FLOAT ,
        @RestNew FLOAT ,
        @RestNewD FLOAT ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @return INT ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @RefF = s.RefF ,
          @VendorID = s.AccountVendorID ,
          @Vendor = s.AccountVendor ,
          @CurrencyID = s.CostCurrencyID ,
          @Currency = s.CostCurrency ,
          @ExchangeRate = s.CostExchangeRate ,
          @ExchangeRateLL = s.CostExchangeRateLL ,
          @ExchangeRateEuro = s.CostExchangeRateEuro ,
          @Cost = s.Cost ,
          @PaymentOld = s.Payment ,
          @PaymentOldD = s.PaymentD
        FROM Invoices.t_DeliveryService AS s
        WHERE s.ID = @ID;
        	
      SET @DateIs = GETDATE();

      SET @PaymentNewD = @PaymentNew / @ExchangeRate;

      SET @RestNew = @Cost - ( @PaymentOld + @PaymentNew );

      SET @RestNewD = @RestNew / @ExchangeRate;

    END;

    BEGIN --Update

      SET @return = 0;

      UPDATE Invoices.t_DeliveryService
        SET Payment += @PaymentNew ,
            PaymentF = Currencys.f_Format(@CurrencyID, @PaymentOld + @PaymentNew) ,
            PaymentD += @PaymentNewD ,
            PaymentLL += @PaymentNewD * @ExchangeRateLL ,
            PaymentEuro += @PaymentNewD * @ExchangeRateEuro ,
            Rest = @RestNew ,
            RestF = Currencys.f_Format(@CurrencyID, @RestNew) ,
            RestD = @RestNewD ,
            RestLL = @RestNewD * @ExchangeRateLL ,
            RestEuro = @RestNewD * @ExchangeRateEuro
        WHERE ID = @ID;

    END;

    BEGIN --Fix data t_DeliveryService

      UPDATE Invoices.t_DeliveryService
        SET ProcessIn = CASE WHEN Rest > 0 THEN 0
                             WHEN DeliveryCharge > 0 AND DeliveryChargeStatus = 0 THEN 0
                             WHEN Expense > 0 AND ExpenseStatus = 0 THEN 0
                             ELSE 1
                        END
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_DeliveryServiceMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkTypeSub ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              N'DS:' + @RefF ,
              162 ,
              2 ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );


        INSERT @TrnIDs
            ( ID )
          VALUES ( @TransactionID );

      END;

      BEGIN --Insert detail

        SET @CID = @CurrencyID;
        SET @E = @ExchangeRate;
        SET @ELL = @ExchangeRateLL;
        SET @EEuro = @ExchangeRateEuro;
        SET @V = @PaymentNew;
        SET @VD = @PaymentNewD;

        INSERT INTO Transactions.t_TransactionDetail
            ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro )
          VALUES  ( 1, @TransactionID, @VendorID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'DS:' + @RefF, @CID, @E  , @ELL , @EEuro ),
                  ( 2, @TransactionID, @PurchaseID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'DS:' + @RefF + ' \ ' + @Vendor, @CID, @E  , @ELL , @EEuro );

      END;

      BEGIN --Insert event

        SET @return = -1;

        INSERT INTO Transactions.t_TransactionMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          VALUES
            ( @UserID ,
              @TransactionID ,
              @EventInsert + CONVERT(NVARCHAR(MAX), @TransactionRef) ,
              0 ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            );

      END;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @PurchaseID, @VendorID ) AND StatusIs = 1;
  
      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;


GO
