/****** Object:  StoredProcedure [Invoices].[s_DressesRentalArchiveInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_DressesRentalArchiveInsert] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @return INT = 0;

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

    END;

    BEGIN --Set
	    
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT t.ItemID ,
            t.ItemSharedID ,
            1
          FROM Invoices.t_DressesRental AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_DressesRentalArchive
          ( ID ,
            Ref ,
            RefF ,
            DateOnly ,
            TakingMeasurementsDate ,
            TailoringDate ,
            DeliveryDate ,
            EventDate ,
            ReceivedDate ,
            CleaningDate ,
            CompletionDate ,
            AccountID ,
            Account ,
            AccountNumberF ,
            StageIs ,
            ItemSharedID ,
            ItemID ,
            CurrencyID ,
            Currency ,
            CurrencyType ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Amount ,
            AmountF ,
            AmountD ,
            AmountLL ,
            AmountEuro ,
            AmountAR ,
            AmountEN ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            InsuranceAmount ,
            InsuranceAmountF ,
            InsuranceAmountD ,
            InsuranceAmountLL ,
            InsuranceAmountEuro ,
            InsuranceAmountPaidUp ,
            InsuranceAmountPaidUpF ,
            InsuranceAmountPaidUpD ,
            InsuranceAmountPaidUpLL ,
            InsuranceAmountPaidUpEuro ,
            InsuranceAmountRest ,
            InsuranceAmountRestF ,
            InsuranceAmountRestD ,
            InsuranceAmountRestLL ,
            InsuranceAmountRestEuro ,
            Bust ,
            Waist ,
            Hips ,
            HollowToFloor ,
            Shoulder ,
            SpecialAdjustments ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID
	      )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.DateOnly ,
            t.TakingMeasurementsDate ,
            t.TailoringDate ,
            t.DeliveryDate ,
            t.EventDate ,
            t.ReceivedDate ,
            t.CleaningDate ,
            t.CompletionDate ,
            t.AccountID ,
            t.Account ,
            t.AccountNumberF ,
            6 ,
            t.ItemSharedID ,
            t.ItemID ,
            t.CurrencyID ,
            t.Currency ,
            t.CurrencyType ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            t.Amount ,
            t.AmountF ,
            t.AmountD ,
            t.AmountLL ,
            t.AmountEuro ,
            t.AmountAR ,
            t.AmountEN ,
            t.PaidUp ,
            t.PaidUpF ,
            t.PaidUpD ,
            t.PaidUpLL ,
            t.PaidUpEuro ,
            t.Rest ,
            t.RestF ,
            t.RestD ,
            t.RestLL ,
            t.RestEuro ,
            t.InsuranceAmount ,
            t.InsuranceAmountF ,
            t.InsuranceAmountD ,
            t.InsuranceAmountLL ,
            t.InsuranceAmountEuro ,
            t.InsuranceAmountPaidUp ,
            t.InsuranceAmountPaidUpF ,
            t.InsuranceAmountPaidUpD ,
            t.InsuranceAmountPaidUpLL ,
            t.InsuranceAmountPaidUpEuro ,
            t.InsuranceAmountRest ,
            t.InsuranceAmountRestF ,
            t.InsuranceAmountRestD ,
            t.InsuranceAmountRestLL ,
            t.InsuranceAmountRestEuro ,
            t.Bust ,
            t.Waist ,
            t.Hips ,
            t.HollowToFloor ,
            t.Shoulder ,
            t.SpecialAdjustments ,
            t.DescriptionIs ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Invoices.t_DressesRental AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Delete t_DressesRental

      DELETE FROM Invoices.t_DressesRental
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DressesRentalMoving

      SET @return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
 
    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'dressesRental' );

    END;
		
	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE [Invoices].[s_DressesRentalLiveVersion];
    EXECUTE [Invoices].[s_DressesRentalArchiveLiveVersion];

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;















