GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [Invoices].[s_DressesRentalArchiveLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, DressesRentalArchive, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;






