/****** Object:  StoredProcedure [Invoices].[s_DressesRentalArchiveRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_DressesRentalArchiveRebuildingStatistics] @RebuildColumn NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding statistics

      IF @RebuildColumn = 'All'
      BEGIN

        UPDATE Invoices.t_DressesRentalArchive
          SET Account = Company.f_AccountGetName(AccountID) ,
              Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
              AmountF = Currencys.f_Format(CurrencyID, Amount) ,
              AmountAR = Currencys.f_ToWordAR(Amount, CurrencyID, 1) ,
              AmountEN = Currencys.f_ToWordEN(Amount, CurrencyID, 1) ,
              PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
              RestF = Currencys.f_Format(CurrencyID, Rest) ,
              InsuranceAmountF = Currencys.f_Format(CurrencyID, InsuranceAmount) ,
              InsuranceAmountPaidUpF = Currencys.f_Format(CurrencyID, InsuranceAmountPaidUp) ,
              InsuranceAmountRestF = Currencys.f_Format(CurrencyID, InsuranceAmountRest) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_DressesRentalArchive.ID );

      END;
      ELSE
        IF @RebuildColumn = 'Account'
        BEGIN

          UPDATE Invoices.t_DressesRentalArchive
            SET Account = Company.f_AccountGetName(AccountID) ,
                IsSync = 0
            WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                            FROM @IDs AS s
                            WHERE s.ID = t_DressesRentalArchive.ID );

        END;
        ELSE
          IF @RebuildColumn = 'Currency and Amount'
          BEGIN

            UPDATE Invoices.t_DressesRentalArchive
              SET Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
                  AmountF = Currencys.f_Format(CurrencyID, Amount) ,
                  AmountAR = Currencys.f_ToWordAR(Amount, CurrencyID, 1) ,
                  AmountEN = Currencys.f_ToWordEN(Amount, CurrencyID, 1) ,
                  PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
                  RestF = Currencys.f_Format(CurrencyID, Rest) ,
                  InsuranceAmountF = Currencys.f_Format(CurrencyID, InsuranceAmount) ,
                  InsuranceAmountPaidUpF = Currencys.f_Format(CurrencyID, InsuranceAmountPaidUp) ,
                  InsuranceAmountRestF = Currencys.f_Format(CurrencyID, InsuranceAmountRest) ,
                  IsSync = 0
              WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                              FROM @IDs AS s
                              WHERE s.ID = t_DressesRentalArchive.ID );

          END;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
 
    EXECUTE [Invoices].[s_DressesRentalArchiveLiveVersion];

    COMMIT TRAN;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;











