/****** Object:  StoredProcedure [Invoices].[s_DressesRentalArchiveRestore]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_DressesRentalArchiveRestore] @ID UNIQUEIDENTIFIER ,
  @AccountSalesID UNIQUEIDENTIFIER ,
  @AccountSales NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @RefF NVARCHAR(MAX) ,
        @D DATE ,
        @DM DATE ,
        @DY DATE ,
        @AccountID UNIQUEIDENTIFIER ,
        @Account NVARCHAR(MAX) ,
        @AccountNumberF NVARCHAR(MAX) ,
        @StageIs TINYINT ,
        @ItemSharedID UNIQUEIDENTIFIER ,
        @ItemID UNIQUEIDENTIFIER ,
        @CurrencyID UNIQUEIDENTIFIER ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyType TINYINT ,
        @DescriptionIs NVARCHAR(MAX) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @EX FLOAT ,
        @EXLL FLOAT ,
        @EXEuro FLOAT ,
        @V FLOAT ,
        @VF NVARCHAR(MAX) ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @VAR NVARCHAR(MAX) ,
        @VEN NVARCHAR(MAX) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

      DECLARE @TransactionsIDs AS TABLE ( ID UNIQUEIDENTIFIER );
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;
	  
    END;

    BEGIN --Set Info

      SELECT TOP ( 1 ) @RefF = t.RefF ,
          @D = t.DateOnly ,
          @DM = DATEFROMPARTS(YEAR(t.DateOnly), MONTH(t.DateOnly), 1) ,
          @DY = DATEFROMPARTS(YEAR(t.DateOnly), 1, 1) ,
          @AccountID = t.AccountID ,
          @Account = t.Account ,
          @AccountNumberF = t.AccountNumberF ,
          @StageIs = t.StageIs ,
          @ItemSharedID = t.ItemSharedID ,
          @ItemID = t.ItemID ,
          @CurrencyID = t.CurrencyID ,
          @Currency = t.Currency ,
          @CurrencyType = t.CurrencyType ,
          @EX = CASE t.CurrencyType
                  WHEN 0 THEN 1
                  WHEN 1 THEN t.ExchangeRateLL
                  ELSE t.ExchangeRateEuro
                END ,
          @EXLL = t.ExchangeRateLL ,
          @EXEuro = t.ExchangeRateEuro ,
          @V = t.Amount ,
          @VF = t.AmountF ,
          @VD = t.AmountD ,
          @VLL = t.AmountLL ,
          @VEuro = t.AmountEuro ,
          @VAR = t.AmountAR ,
          @VEN = t.AmountEN ,
          @DescriptionIs = t.DescriptionIs
        FROM Invoices.t_DressesRentalArchive AS t
        WHERE t.ID = @ID;

      SET @BaseStatement = N'D.R: ' + @RefF;
    
      INSERT INTO @ItemQtys
          ( ID, SharedID, Qty )
        VALUES ( @ItemID, @ItemSharedID, -1 );

    END;

    IF @StageIs = 7
    BEGIN --Insert t_DressesRental

      INSERT INTO Invoices.t_DressesRental
          ( ID ,
            Ref ,
            RefF ,
            DateOnly ,
            TakingMeasurementsDate ,
            TailoringDate ,
            DeliveryDate ,
            EventDate ,
            ReceivedDate ,
            CleaningDate ,
            CompletionDate ,
            AccountID ,
            Account ,
            AccountNumberF ,
            StageIs ,
            ItemSharedID ,
            ItemID ,
            CurrencyID ,
            Currency ,
            CurrencyType ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Amount ,
            AmountF ,
            AmountD ,
            AmountLL ,
            AmountEuro ,
            AmountAR ,
            AmountEN ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            InsuranceAmount ,
            InsuranceAmountF ,
            InsuranceAmountD ,
            InsuranceAmountLL ,
            InsuranceAmountEuro ,
            InsuranceAmountPaidUp ,
            InsuranceAmountPaidUpF ,
            InsuranceAmountPaidUpD ,
            InsuranceAmountPaidUpLL ,
            InsuranceAmountPaidUpEuro ,
            InsuranceAmountRest ,
            InsuranceAmountRestF ,
            InsuranceAmountRestD ,
            InsuranceAmountRestLL ,
            InsuranceAmountRestEuro ,
