            t.WorkStationID
          FROM Invoices.t_DressesRentalArchive AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Invoices.t_DressesRentalArchive
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DressesRentalMoving

      SET @return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    SET @return = -5;

    IF @StageIs = 7 AND @V > 0 --Insert t_Transaction
    BEGIN
  
      BEGIN --Set
      
        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = 'JV';

      END;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        OUTPUT Inserted.ID
          INTO @TransactionsIDs
        VALUES
          ( @TransactionRef ,
            FORMAT(@TransactionRef, '0') ,
            'JV' ,
            @D ,
            @D ,
            @DM ,
            @DY ,
            @UserID ,
            @UserIs ,
            @BaseStatement ,
            214 ,
            @ID ,
            @Account + ', ' + @AccountSales ,
            2
          );

      SELECT TOP ( 1 ) @TransactionID = s.ID
        FROM @TransactionsIDs AS s;

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @AccountID, @Account, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, @V, @VF, @VD, @VLL, @VEuro, @VAR, @VEN, 0, 0, 0, 0, @V, @VD, @VLL, @VEuro, @BaseStatement ),
                ( 2, @TransactionID, @AccountSalesID, @AccountSales, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, 0 - @V, '-' + @VF, 0 - @VD, 0 - @VLL, 0 - @VEuro, @VAR, @VEN, @V, @VD, @VLL, @VEuro, 0, 0, 0, 0, @BaseStatement + ' \ ' + @Account );

    END;

    IF @StageIs = 7
    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @AccountID, @AccountSalesID ) AND StatusIs = 1;

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'dressesRentalArchive' );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE [Invoices].[s_DressesRentalLiveVersion];
    EXECUTE [Invoices].[s_DressesRentalArchiveLiveVersion];

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;















