/****** Object:  StoredProcedure [Invoices].[s_DressesRentalInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Invoices].[s_DressesRentalInsert] @ID UNIQUEIDENTIFIER ,
  @DateOnly DATETIME ,
  @TakingMeasurementsDate DATE ,
  @TailoringDate DATE ,
  @DeliveryDate DATE ,
  @EventDate DATE ,
  @ReceivedDate DATE ,
  @CleaningDate DATE ,
  @CompletionDate DATE ,
  @AccountID UNIQUEIDENTIFIER ,
  @Account NVARCHAR(MAX) ,
  @AccountNumberF NVARCHAR(MAX) ,
  @StageIs TINYINT ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Amount FLOAT ,
  @AmountF NVARCHAR(MAX) ,
  @AmountD FLOAT ,
  @AmountLL FLOAT ,
  @AmountEuro FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @InsuranceAmount FLOAT ,
  @InsuranceAmountF NVARCHAR(MAX) ,
  @InsuranceAmountD FLOAT ,
  @InsuranceAmountLL FLOAT ,
  @InsuranceAmountEuro FLOAT ,
  @InsuranceAmountPaidUp FLOAT ,
  @InsuranceAmountPaidUpF NVARCHAR(MAX) ,
  @InsuranceAmountPaidUpD FLOAT ,
  @InsuranceAmountPaidUpLL FLOAT ,
  @InsuranceAmountPaidUpEuro FLOAT ,
  @InsuranceAmountRest FLOAT ,
  @InsuranceAmountRestF NVARCHAR(MAX) ,
  @InsuranceAmountRestD FLOAT ,
  @InsuranceAmountRestLL FLOAT ,
  @InsuranceAmountRestEuro FLOAT ,
  @Bust NVARCHAR(MAX) ,
  @Waist NVARCHAR(MAX) ,
  @Hips NVARCHAR(MAX) ,
  @HollowToFloor NVARCHAR(MAX) ,
  @Shoulder NVARCHAR(MAX) ,
  @SpecialAdjustments NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @AccountSalesID UNIQUEIDENTIFIER ,
  @AccountSales NVARCHAR(MAX) ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @AccountBox NVARCHAR(MAX) ,
  @AccountBoxInsuranceID UNIQUEIDENTIFIER ,
  @AccountBoxInsurance NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @D DATE = @DateOnly ,
        @DM DATE = DATEFROMPARTS(YEAR(@DateOnly), MONTH(@DateOnly), 1) ,
        @DY DATE = DATEFROMPARTS(YEAR(@DateOnly), 1, 1) ,
        @AmountAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Amount, @CurrencyID, 1) ,
        @AmountEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Amount, @CurrencyID, 1) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @EX FLOAT = @ExchangeRate ,
        @EXLL FLOAT  = @ExchangeRateLL ,
        @EXEuro FLOAT  = @ExchangeRateEuro ,
        @V FLOAT ,
        @VF NVARCHAR(MAX) ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @VAR NVARCHAR(MAX) ,
        @VEN NVARCHAR(MAX) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

      DECLARE @TransactionsIDs AS TABLE ( ID UNIQUEIDENTIFIER );
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

    END;

    BEGIN --Set Info

      SELECT @Ref = COALESCE(MAX(t.Ref), 0) + 1
        FROM ( SELECT s.Ref
                FROM Invoices.t_DressesRental AS s
               UNION ALL
               SELECT s1.Ref
                FROM Invoices.t_DressesRentalArchive AS s1
             ) AS t;

      SET @RefF = FORMAT(@Ref, '#');
   
      INSERT INTO @ItemQtys
          ( ID, SharedID, Qty )
        VALUES ( @ItemID, @ItemSharedID, -1 );
  
      SET @BaseStatement = N'D.R: ' + @RefF + N' ' + @DescriptionIs;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_DressesRental
          ( ID ,
            Ref ,
            RefF ,
            DateOnly ,
            TakingMeasurementsDate ,
            TailoringDate ,
            DeliveryDate ,
            EventDate ,
            ReceivedDate ,
            CleaningDate ,
            CompletionDate ,
            AccountID ,
            Account ,
            AccountNumberF ,
            StageIs ,
            ItemSharedID ,
            ItemID ,
            CurrencyID ,
            Currency ,
            CurrencyType ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Amount ,
            AmountF ,
            AmountD ,
            AmountLL ,
            AmountEuro ,
            AmountAR ,
            AmountEN ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            InsuranceAmount ,
            InsuranceAmountF ,
            InsuranceAmountD ,
            InsuranceAmountLL ,
            InsuranceAmountEuro ,
            InsuranceAmountPaidUp ,
            InsuranceAmountPaidUpF ,
            InsuranceAmountPaidUpD ,
            InsuranceAmountPaidUpLL ,
            InsuranceAmountPaidUpEuro ,
            InsuranceAmountRest ,
            InsuranceAmountRestF ,
            InsuranceAmountRestD ,
            InsuranceAmountRestLL ,
            InsuranceAmountRestEuro ,
            Bust ,
            Waist ,
            Hips ,
            HollowToFloor ,
            Shoulder ,
            SpecialAdjustments ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @DateOnly ,
            @TakingMeasurementsDate ,
            @TailoringDate ,
            @DeliveryDate ,
            @EventDate ,
            @ReceivedDate ,
            @CleaningDate ,
            @CompletionDate ,
            @AccountID ,
            @Account ,
            @AccountNumberF ,
            @StageIs ,
            @ItemSharedID ,
            @ItemID ,
            @CurrencyID ,
            @Currency ,
            @CurrencyType ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Amount ,
            @AmountF ,
            @AmountD ,
            @AmountLL ,
            @AmountEuro ,
            @AmountAR ,
            @AmountEN ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @InsuranceAmount ,
            @InsuranceAmountF ,
            @InsuranceAmountD ,
            @InsuranceAmountLL ,
            @InsuranceAmountEuro ,
            @InsuranceAmountPaidUp ,
            @InsuranceAmountPaidUpF ,
            @InsuranceAmountPaidUpD ,
            @InsuranceAmountPaidUpLL ,
            @InsuranceAmountPaidUpEuro ,
            @InsuranceAmountRest ,
            @InsuranceAmountRestF ,
            @InsuranceAmountRestD ,
            @InsuranceAmountRestLL ,
            @InsuranceAmountRestEuro ,
            @Bust ,
            @Waist ,
            @Hips ,
            @HollowToFloor ,
            @Shoulder ,
            @SpecialAdjustments ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert t_DressesRentalMoving

      SET @return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + @RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    SET @return = -5;

    IF @Amount > 0 --Insert t_Transaction
    BEGIN
  
      BEGIN --Set
      
        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = 'JV';

      END;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        OUTPUT Inserted.ID
          INTO @TransactionsIDs
        VALUES
          ( @TransactionRef ,
            FORMAT(@TransactionRef, '#') ,
            'JV' ,
            @D ,
            @D ,
            @DM ,
            @DY ,
            @UserID ,
            @UserIs ,
            @BaseStatement ,
            214 ,
            @ID ,
            @Account + ', ' + @AccountSales ,
            2
          );

      SELECT TOP ( 1 ) @TransactionID = s.ID
        FROM @TransactionsIDs AS s;

      SET @V = @Amount; 
      SET @VF = @AmountF; 
      SET @VD = @AmountD;
      SET @VLL = @AmountLL;
      SET @VEuro = @AmountEuro;

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @AccountID, @Account, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, @V, @VF, @VD, @VLL, @VEuro, @AmountAR, @AmountEN, 0, 0, 0, 0, @V, @VD, @VLL, @VEuro, @BaseStatement ),
                ( 2, @TransactionID, @AccountSalesID, @AccountSales, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, 0 - @V, '-' + @VF, 0 - @VD, 0 - @VLL, 0 - @VEuro, @AmountAR, @AmountEN, @V, @VD, @VLL, @VEuro, 0, 0, 0, 0, @BaseStatement + ' \ ' + @Account );

    END;

    IF @PaidUp > 0 --Insert t_Transaction
    BEGIN

      DELETE FROM @TransactionsIDs;

      BEGIN --Set
      
        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = 'RV';

      END;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkTypeSub ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        OUTPUT Inserted.ID
          INTO @TransactionsIDs
        VALUES
          ( @TransactionRef ,
            FORMAT(@TransactionRef, '#') ,
            'RV' ,
            @D ,
            @D ,
            @DM ,
            @DY ,
            @UserID ,
            @UserIs ,
            @BaseStatement ,
            214 ,
            13 ,
            @ID ,
            @Account + ', ' + @AccountBox ,
            2
          );

      SELECT TOP ( 1 ) @TransactionID = s.ID
        FROM @TransactionsIDs AS s;

      SET @V = @PaidUp; 
      SET @VF = @PaidUpF; 
      SET @VD = @PaidUpD;
      SET @VLL = @PaidUpLL;
      SET @VEuro = @PaidUpEuro;
	  
      SET @VAR = Currencys.f_ToWordAR(@V, @CurrencyID, 1);
      SET @VEN = Currencys.f_ToWordEN(@V, @CurrencyID, 1);

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @AccountBoxID, @AccountBox, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, @V, @VF, @VD, @VLL, @VEuro, @VAR, @VEN, 0, 0, 0, 0, @V, @VD, @VLL, @VEuro, @BaseStatement + ' \ ' + @Account ),
                ( 2, @TransactionID, @AccountID, @Account, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, 0 - @V, '-' + @VF, 0 - @VD, 0 - @VLL, 0 - @VEuro, @VAR, @VEN, @V, @VD, @VLL, @VEuro, 0, 0, 0, 0, @BaseStatement );

    END;

    IF @InsuranceAmountPaidUp > 0 --Insert t_Transaction
    BEGIN

      DELETE FROM @TransactionsIDs;

      BEGIN --Set
      
        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = 'JV';

      END;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkTypeSub ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        OUTPUT Inserted.ID
          INTO @TransactionsIDs
        VALUES
          ( @TransactionRef ,
            FORMAT(@TransactionRef, '#') ,
            'JV' ,
            @D ,
            @D ,
            @DM ,
            @DY ,
            @UserID ,
            @UserIs ,
            @BaseStatement ,
            214 ,
            14 ,
            @ID ,
            @Account + ', ' + @AccountBoxInsurance ,
            2
          );

      SELECT TOP ( 1 ) @TransactionID = s.ID
        FROM @TransactionsIDs AS s;

      SET @V = @InsuranceAmountPaidUp; 
      SET @VF = @InsuranceAmountPaidUpF; 
      SET @VD = @InsuranceAmountPaidUpD;
      SET @VLL = @InsuranceAmountPaidUpLL;
      SET @VEuro = @InsuranceAmountPaidUpEuro;
	  
      SET @VAR = Currencys.f_ToWordAR(@V, @CurrencyID, 1);
      SET @VEN = Currencys.f_ToWordEN(@V, @CurrencyID, 1);

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @AccountBoxInsuranceID, @AccountBoxInsurance, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, @V, @VF, @VD, @VLL, @VEuro, @VAR, @VEN, 0, 0, 0, 0, @V, @VD, @VLL, @VEuro, @BaseStatement + ' \ ' + @Account ),
                ( 2, @TransactionID, @AccountID, @Account, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, 0 - @V, '-' + @VF, 0 - @VD, 0 - @VLL, 0 - @VEuro, @VAR, @VEN, @V, @VD, @VLL, @VEuro, 0, 0, 0, 0, @BaseStatement );

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @AccountID, @AccountSalesID, @AccountBoxID, @AccountBoxInsuranceID ) AND StatusIs = 1;

    END;
	
	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE [Invoices].[s_DressesRentalLiveVersion];

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;














