GO

CREATE PROCEDURE [Invoices].[s_DressesRentalNewInsurancePayment] @ID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @Account NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @NewPayment FLOAT ,
  @NewPaymentF NVARCHAR(MAX) ,
  @NewPaymentD FLOAT ,
  @NewPaymentLL FLOAT ,
  @NewPaymentEuro FLOAT ,
  @InsuranceAmountPaidUp FLOAT ,
  @InsuranceAmountPaidUpF NVARCHAR(MAX) ,
  @InsuranceAmountPaidUpD FLOAT ,
  @InsuranceAmountPaidUpLL FLOAT ,
  @InsuranceAmountPaidUpEuro FLOAT ,
  @InsuranceAmountRest FLOAT ,
  @InsuranceAmountRestF NVARCHAR(MAX) ,
  @InsuranceAmountRestD FLOAT ,
  @InsuranceAmountRestLL FLOAT ,
  @InsuranceAmountRestEuro FLOAT ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @AccountBox NVARCHAR(MAX) ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @RefF NVARCHAR(MAX) ,
        @D DATE = @DateIs ,
        @DM DATE = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
        @DY DATE = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @EX FLOAT = @ExchangeRate ,
        @EXLL FLOAT  = @ExchangeRateLL ,
        @EXEuro FLOAT  = @ExchangeRateEuro ,
        @V FLOAT = @NewPayment ,
        @VF NVARCHAR(MAX) = @NewPaymentF ,
        @VD FLOAT = @NewPaymentD ,
        @VLL FLOAT = @NewPaymentLL ,
        @VEuro FLOAT = @NewPaymentEuro ,
        @VAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@NewPayment, @CurrencyID, 1) ,
        @VEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@NewPayment, @CurrencyID, 1) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

      DECLARE @TransactionsIDs AS TABLE ( ID UNIQUEIDENTIFIER );

    END;

    BEGIN --Set Info
	
      SELECT TOP ( 1 ) @RefF = s.RefF
        FROM Invoices.t_DressesRental AS s
        WHERE s.ID = @ID;

      SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
        FROM Transactions.t_Transaction AS s
        WHERE s.TypeIs = 'JV';

      SET @BaseStatement = N'D.R: ' + @RefF + N' ' + @StatementIs;

    END;

    BEGIN --Update

      UPDATE Invoices.t_DressesRental
        SET InsuranceAmountPaidUp = @InsuranceAmountPaidUp ,
            InsuranceAmountPaidUpF = @InsuranceAmountPaidUpF ,
            InsuranceAmountPaidUpD = @InsuranceAmountPaidUpD ,
            InsuranceAmountPaidUpLL = @InsuranceAmountPaidUpLL ,
            InsuranceAmountPaidUpEuro = @InsuranceAmountPaidUpEuro ,
            InsuranceAmountRest = @InsuranceAmountRest ,
            InsuranceAmountRestF = @InsuranceAmountRestF ,
            InsuranceAmountRestD = @InsuranceAmountRestD ,
            InsuranceAmountRestLL = @InsuranceAmountRestLL ,
            InsuranceAmountRestEuro = @InsuranceAmountRestEuro ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DressesRentalMoving

      SET @return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    SET @return = -5;

    BEGIN--Insert t_Transaction

