  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @RefF NVARCHAR(MAX) ,
        @D DATE = @DateOnly ,
        @DM DATE = DATEFROMPARTS(YEAR(@DateOnly), MONTH(@DateOnly), 1) ,
        @DY DATE = DATEFROMPARTS(YEAR(@DateOnly), 1, 1) ,
        @AmountAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Amount, @CurrencyID, 1) ,
        @AmountEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Amount, @CurrencyID, 1) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionJVRef BIGINT ,
        @EX FLOAT = @ExchangeRate ,
        @EXLL FLOAT  = @ExchangeRateLL ,
        @EXEuro FLOAT  = @ExchangeRateEuro ,
        @V FLOAT ,
        @VF NVARCHAR(MAX) ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @VAR NVARCHAR(MAX) ,
        @VEN NVARCHAR(MAX) ,
        @BaseStatement NVARCHAR(MAX) ,
        @return INT = 0;

      DECLARE @TransactionsIDs AS TABLE ( ID UNIQUEIDENTIFIER );
	
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

    END;

    BEGIN --Set Info

      SELECT TOP ( 1 ) @RefF = s.RefF
        FROM Invoices.t_DressesRental AS s
        WHERE s.ID = @ID;

      SELECT TOP ( 1 ) @TransactionJVRef = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = 214 AND s.LinkTypeSub = 0 AND s.LinkID = @ID AND s.SubLinkID = '00000000-0000-0000-0000-000000000000' AND s.TypeIs = 'JV';
  
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT t.ItemID ,
            t.ItemSharedID ,
            1
          FROM Invoices.t_DressesRental AS t
          WHERE t.ID = @ID
        UNION ALL
        SELECT @ItemID ,
            @ItemSharedID ,
            -1;

      SET @BaseStatement = N'D.R: ' + @RefF + N' ' + @DescriptionIs;

    END;

    BEGIN --Update

      UPDATE Invoices.t_DressesRental
        SET DateOnly = @DateOnly ,
            TakingMeasurementsDate = @TakingMeasurementsDate ,
            TailoringDate = @TailoringDate ,
            DeliveryDate = @DeliveryDate ,
            EventDate = @EventDate ,
            ReceivedDate = @ReceivedDate ,
            CleaningDate = @CleaningDate ,
            CompletionDate = @CompletionDate ,
            AccountID = @AccountID ,
            Account = @Account ,
            AccountNumberF = @AccountNumberF ,
            StageIs = @StageIs ,
            ItemSharedID = @ItemSharedID ,
            ItemID = @ItemID ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            CurrencyType = @CurrencyType ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Amount = @Amount ,
            AmountF = @AmountF ,
            AmountD = @AmountD ,
            AmountLL = @AmountLL ,
            AmountEuro = @AmountEuro ,
            AmountAR = @AmountAR ,
            AmountEN = @AmountEN ,
            PaidUp = @PaidUp ,
            PaidUpF = @PaidUpF ,
            PaidUpD = @PaidUpD ,
            PaidUpLL = @PaidUpLL ,
            PaidUpEuro = @PaidUpEuro ,
            Rest = @Rest ,
            RestF = @RestF ,
            RestD = @RestD ,
            RestLL = @RestLL ,
            RestEuro = @RestEuro ,
            InsuranceAmount = @InsuranceAmount ,
            InsuranceAmountF = @InsuranceAmountF ,
            InsuranceAmountD = @InsuranceAmountD ,
            InsuranceAmountLL = @InsuranceAmountLL ,
            InsuranceAmountEuro = @InsuranceAmountEuro ,
            InsuranceAmountPaidUp = @InsuranceAmountPaidUp ,
            InsuranceAmountPaidUpF = @InsuranceAmountPaidUpF ,
            InsuranceAmountPaidUpD = @InsuranceAmountPaidUpD ,
            InsuranceAmountPaidUpLL = @InsuranceAmountPaidUpLL ,
            InsuranceAmountPaidUpEuro = @InsuranceAmountPaidUpEuro ,
            InsuranceAmountRest = @InsuranceAmountRest ,
            InsuranceAmountRestF = @InsuranceAmountRestF ,
            InsuranceAmountRestD = @InsuranceAmountRestD ,
            InsuranceAmountRestLL = @InsuranceAmountRestLL ,
            InsuranceAmountRestEuro = @InsuranceAmountRestEuro ,
            Bust = @Bust ,
            Waist = @Waist ,
            Hips = @Hips ,
            HollowToFloor = @HollowToFloor ,
            Shoulder = @Shoulder ,
            SpecialAdjustments = @SpecialAdjustments ,
            DescriptionIs = @DescriptionIs ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DressesRentalMoving

      SET @return = -1;

      INSERT INTO Invoices.t_DressesRentalMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    SET @return = -5;

    BEGIN --Delete t_Transaction
    
      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 214 AND LinkTypeSub = 0 AND LinkID = @ID;

    END;

    IF @Amount > 0 --Insert t_Transaction
    BEGIN
  
      IF @TransactionJVRef IS NULL
      BEGIN --Set
      
        SELECT @TransactionJVRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = 'JV';

      END;

      INSERT INTO Transactions.t_Transaction
          ( Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            LinkType ,
            LinkID ,
            AccountsNames ,
            DetailsCount 
          )
        OUTPUT Inserted.ID
          INTO @TransactionsIDs
        VALUES
          ( @TransactionJVRef ,
            FORMAT(@TransactionJVRef, '0') ,
            'JV' ,
            @D ,
            @D ,
            @DM ,
            @DY ,
            @UserID ,
            @UserIs ,
            @BaseStatement ,
            214 ,
            @ID ,
            @Account + ', ' + @AccountSales ,
            2
          );

      SELECT TOP ( 1 ) @TransactionID = s.ID
        FROM @TransactionsIDs AS s;

      SET @V = @Amount; 
      SET @VF = @AmountF; 
      SET @VD = @AmountD;
      SET @VLL = @AmountLL;
      SET @VEuro = @AmountEuro;

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, Account, DateIs, DateOnly, DateFirstDayInMonth, DateFirstDayInYear, CurrencyID, Currency, CurrencyTypeIs, ExchangeRate, ExchangeRateLL, ExchangeRateEuro, Balance, BalanceF, BalanceD, BalanceLL, BalanceEuro, BalanceAR, BalanceEN, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs )
        VALUES  ( 1, @TransactionID, @AccountID, @Account, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, @V, @VF, @VD, @VLL, @VEuro, @AmountAR, @AmountEN, 0, 0, 0, 0, @V, @VD, @VLL, @VEuro, @BaseStatement ),
                ( 2, @TransactionID, @AccountSalesID, @AccountSales, @D, @D, @DM, @DY, @CurrencyID, @Currency, @CurrencyType, @EX, @EXLL, @EXEuro, 0 - @V, '-' + @VF, 0 - @VD, 0 - @VLL, 0 - @VEuro, @AmountAR, @AmountEN, @V, @VD, @VLL, @VEuro, 0, 0, 0, 0, @BaseStatement + ' \ ' + @Account );

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @AccountID, @AccountSalesID ) AND StatusIs = 1;

    END;
		
	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE [Invoices].[s_DressesRentalLiveVersion];

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;















GO
