GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_ElectricalBoxes_Addition_ActiveSubscriptions_PARTS] @t Invoices.tt_ElectricalBoxesAddition READONLY
AS
BEGIN

  MERGE Invoices.t_ElectricalBoxes AS t
  USING @t AS s
  ON s.ID = t.ID
  WHEN MATCHED THEN
    UPDATE SET t.ActiveSubscriptions += s.ActiveSubscriptions;

END;





