/****** Object:  StoredProcedure [Invoices].[s_ElectricGenerators_Addition_AmperesUsed_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_ElectricGenerators_Addition_AmperesUsed_PART] @ID UNIQUEIDENTIFIER ,
  @AmperesUsed FLOAT
AS
BEGIN

  UPDATE Invoices.t_ElectricGenerators
    SET AmperesUsed += @AmperesUsed ,
        RemainingAmperes = AmperageCapacity - ( AmperesUsed + @AmperesUsed )
    WHERE ID = @ID;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_ElectricGenerators_Addition_AmperesUsed_PARTS]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ElectricGenerators_Addition_AmperesUsed_PARTS] @t Invoices.tt_ElectricGeneratorsAddition READONLY
AS
BEGIN

  MERGE Invoices.t_ElectricGenerators AS t
  USING @t AS s
  ON s.ID = t.ID
  WHEN MATCHED THEN
    UPDATE SET t.AmperesUsed += s.AmperesUsed ,
                t.RemainingAmperes = t.AmperageCapacity - ( t.AmperesUsed + s.AmperesUsed );

END;




GO
