/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsArchivesRebuild]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsArchivesRebuild] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild

      UPDATE Invoices.t_ElectricitySubscriptionsArchives
        SET FixedFeesF = Currencys.f_Format(CurrencyID, FixedFees) ,
            SubscriptionFeesF = Currencys.f_Format(CurrencyID, SubscriptionFees) ,
            AdditionalFeesF = Currencys.f_Format(CurrencyID, AdditionalFees) ,
            SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
            DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            RestF = Currencys.f_Format(CurrencyID, Rest) ,
            LastModifiedDate = GETDATE();

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





