/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @FromDate DATE ,
        @ElectricGeneratorID UNIQUEIDENTIFIER ,
        @ElectricalBoxID UNIQUEIDENTIFIER ,
		@ActiveSubscriptions BIGINT,
        @TotalAmperes FLOAT ,
        @IsActive BIT ,
        @LinkType INT = 259 ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate = s.FromDate ,
          @ElectricGeneratorID = s.ElectricGeneratorID ,
          @ElectricalBoxID = s.ElectricalBoxID ,
          @TotalAmperes = s.TotalAmperes ,
          @IsActive = s.IsActive
        FROM Invoices.t_ElectricitySubscriptions AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Invoices.t_ElectricitySubscriptions
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = @LinkType AND LinkID = @ID;

    END;

	--ElectricGenerators
    SET @TotalAmperes = IIF(@IsActive = 1, 0 - @TotalAmperes, 0);
    EXECUTE Invoices.s_ElectricGenerators_Addition_AmperesUsed_PART @ElectricGeneratorID, @TotalAmperes;

	--ElectricalBoxes
    SET @ActiveSubscriptions = IIF(@IsActive = 1, 0 - 1, 0);
    EXECUTE Invoices.s_ElectricalBoxes_Addition_ActiveSubscriptions_PART @ElectricalBoxID, @ActiveSubscriptions;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Invoices_ElectricitySubscriptions < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Declare
	
      DECLARE @IDs Alls.tt_Guid;

    END;

    BEGIN --Set

      INSERT INTO @IDs
          ( ID 
          )
        SELECT DISTINCT s.ElectricGeneratorID
          FROM Invoices.t_ElectricitySubscriptions AS s
          WHERE s.IsActive = 1;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_ElectricitySubscriptions
        SET IsActive = IIF(ToDate >= DateTimes.f_GetToday(), 0, 1)
        WHERE IsActive = 1;

    END;

    BEGIN --Rebuild

      UPDATE Invoices.t_ElectricGenerators
        SET AmperesUsed = Invoices.f_ElectricGeneratorsGetTotalAmperes_LIVE(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ElectricGenerators.ID );

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Invoices_ElectricitySubscriptions = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;














GO
