  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @CollectionOfficerEmployeeID UNIQUEIDENTIFIER ,
  @PrivateNote NVARCHAR(MAX) ,
  @PrintNote NVARCHAR(MAX) ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Invoices.f_ElectricitySubscriptionsGetNewRef() ,
		@ActiveSubscriptions BIGINT,
        @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_ElectricitySubscriptions
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            FromDate ,
            FromDateMonthly ,
            FromDateYearly ,
            ToDate ,
            IsActive ,
            AccountID ,
            SalesAccountID ,
            ElectricitySubscriptionTypeID ,
            ElectricGeneratorID ,
            ElectricalBoxID ,
            TypeIs ,
            TotalAmperes ,
            PreviousConsumption ,
            CurrentConsumption ,
            TotalConsumption ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            FixedFees ,
            FixedFeesF ,
            FixedFeesD ,
            FixedFeesLL ,
            FixedFeesEuro ,
            SubscriptionFees ,
            SubscriptionFeesF ,
            SubscriptionFeesD ,
            SubscriptionFeesLL ,
            SubscriptionFeesEuro ,
            AdditionalFees ,
            AdditionalFeesF ,
            AdditionalFeesD ,
            AdditionalFeesLL ,
            AdditionalFeesEuro ,
            Subtotal ,
            SubtotalF ,
            SubtotalD ,
            SubtotalLL ,
            SubtotalEuro ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid ,
            CollectionOfficerEmployeeID ,
            PrivateNote ,
            PrintNote ,
            CreatedByUserID
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, N'0') ,
            @RefPaper ,
            @FromDate ,
            @FromDateMonthly ,
            @FromDateYearly ,
            @ToDate ,
            @IsActive ,
            @AccountID ,
            @SalesAccountID ,
            @ElectricitySubscriptionTypeID ,
            @ElectricGeneratorID ,
            @ElectricalBoxID ,
            @TypeIs ,
            @TotalAmperes ,
            @PreviousConsumption ,
            @CurrentConsumption ,
            @TotalConsumption ,
            @CurrencyID ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @FixedFees ,
            @FixedFeesF ,
            @FixedFeesD ,
            @FixedFeesLL ,
            @FixedFeesEuro ,
            @SubscriptionFees ,
            @SubscriptionFeesF ,
            @SubscriptionFeesD ,
            @SubscriptionFeesLL ,
            @SubscriptionFeesEuro ,
            @AdditionalFees ,
            @AdditionalFeesF ,
            @AdditionalFeesD ,
            @AdditionalFeesLL ,
            @AdditionalFeesEuro ,
            @Subtotal ,
            @SubtotalF ,
            @SubtotalD ,
            @SubtotalLL ,
            @SubtotalEuro ,
            @Discount ,
            @DiscountF ,
            @DiscountD ,
            @DiscountLL ,
            @DiscountEuro ,
            @Total ,
            @TotalF ,
            @TotalD ,
            @TotalLL ,
            @TotalEuro ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @Paid ,
            @CollectionOfficerEmployeeID ,
            @PrivateNote ,
            @PrintNote ,
            @UserID
          );	  

    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
	
	--ElectricGenerators
    SET @TotalAmperes = IIF(@IsActive = 1, @TotalAmperes, 0);
    EXECUTE Invoices.s_ElectricGenerators_Addition_AmperesUsed_PART @ElectricGeneratorID, @TotalAmperes;

	--ElectricalBoxes
    SET @ActiveSubscriptions = IIF(@IsActive = 1, 1, 0);
    EXECUTE Invoices.s_ElectricalBoxes_Addition_ActiveSubscriptions_PART @ElectricalBoxID, @ActiveSubscriptions;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;
 
    EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

