CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsInserts] @ElectricitySubscriptions Invoices.tt_ElectricitySubscriptions READONLY ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Invoices.f_ElectricitySubscriptionsGetNewRef() - 1 ,
        @IDs Alls.tt_IDAndEvent ,
        @ElectricalBoxesAddition Invoices.tt_ElectricalBoxesAddition ,
        @ElectricGeneratorsAddition Invoices.tt_ElectricGeneratorsAddition;

      DECLARE @DateOnly DateTimes.tt_DateOnly;

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID ,
            EventIs
          )
        SELECT s.ID ,
            @Event
          FROM @ElectricitySubscriptions AS s;

      INSERT INTO @ElectricalBoxesAddition
          ( ID ,
            ActiveSubscriptions
          )
        SELECT s.ElectricalBoxID ,
            COUNT(s.ID)
          FROM @ElectricitySubscriptions AS s
          WHERE s.IsActive = 1
          GROUP BY s.ElectricalBoxID;

      INSERT INTO @ElectricGeneratorsAddition
          ( ID ,
            AmperesUsed
          )
        SELECT s.ElectricGeneratorID ,
            SUM(IIF(s.IsActive = 1, s.TotalAmperes, 0))
          FROM @ElectricitySubscriptions AS s
          GROUP BY s.ElectricGeneratorID;

      INSERT INTO @DateOnly
          ( DateOnly
          )
        SELECT DISTINCT s.FromDate
          FROM @ElectricitySubscriptions AS s;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_ElectricitySubscriptions
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            FromDate ,
            FromDateMonthly ,
            FromDateYearly ,
            ToDate ,
            IsActive ,
            AccountID ,
            SalesAccountID ,
            ElectricitySubscriptionTypeID ,
            ElectricGeneratorID ,
            ElectricalBoxID ,
            TypeIs ,
            TotalAmperes ,
            PreviousConsumption ,
            CurrentConsumption ,
            TotalConsumption ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            FixedFees ,
            FixedFeesF ,
            FixedFeesD ,
            FixedFeesLL ,
            FixedFeesEuro ,
            SubscriptionFees ,
            SubscriptionFeesF ,
            SubscriptionFeesD ,
            SubscriptionFeesLL ,
            SubscriptionFeesEuro ,
            AdditionalFees ,
            AdditionalFeesF ,
            AdditionalFeesD ,
            AdditionalFeesLL ,
            AdditionalFeesEuro ,
            Subtotal ,
            SubtotalF ,
            SubtotalD ,
            SubtotalLL ,
            SubtotalEuro ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid ,
            CollectionOfficerEmployeeID ,
            PrivateNote ,
            PrintNote ,
            CreatedByUserID
          )
        SELECT s.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                ) ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                       ) ), N'0') ,
            s.RefPaper ,
            s.FromDate ,
            s.FromDateMonthly ,
            s.FromDateYearly ,
            s.ToDate ,
            s.IsActive ,
            s.AccountID ,
            s.SalesAccountID ,
            s.ElectricitySubscriptionTypeID ,
            s.ElectricGeneratorID ,
            s.ElectricalBoxID ,
            s.TypeIs ,
            s.TotalAmperes ,
            s.PreviousConsumption ,
            s.CurrentConsumption ,
            s.TotalConsumption ,
            s.CurrencyID ,
            s.ExchangeRate ,
            s.ExchangeRateLL ,
            s.ExchangeRateEuro ,
            s.FixedFees ,
            s.FixedFeesF ,
            s.FixedFeesD ,
            s.FixedFeesLL ,
            s.FixedFeesEuro ,
            s.SubscriptionFees ,
            s.SubscriptionFeesF ,
            s.SubscriptionFeesD ,
            s.SubscriptionFeesLL ,
            s.SubscriptionFeesEuro ,
            s.AdditionalFees ,
            s.AdditionalFeesF ,
            s.AdditionalFeesD ,
            s.AdditionalFeesLL ,
            s.AdditionalFeesEuro ,
            s.Subtotal ,
            s.SubtotalF ,
            s.SubtotalD ,
            s.SubtotalLL ,
            s.SubtotalEuro ,
            s.Discount ,
            s.DiscountF ,
            s.DiscountD ,
            s.DiscountLL ,
            s.DiscountEuro ,
            s.Total ,
            s.TotalF ,
            s.TotalD ,
            s.TotalLL ,
            s.TotalEuro ,
            s.PaidUp ,
            s.PaidUpF ,
            s.PaidUpD ,
            s.PaidUpLL ,
            s.PaidUpEuro ,
            s.Rest ,
            s.RestF ,
            s.RestD ,
            s.RestLL ,
            s.RestEuro ,
            s.Paid ,
            s.CollectionOfficerEmployeeID ,
            s.PrivateNote ,
            s.PrintNote ,
            @UserID
          FROM @ElectricitySubscriptions AS s;	  

    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    EXECUTE Invoices.s_ElectricalBoxes_Addition_ActiveSubscriptions_PARTS @ElectricalBoxesAddition;

    EXECUTE Invoices.s_ElectricGenerators_Addition_AmperesUsed_PARTS @ElectricGeneratorsAddition;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Electricity_Updates_PART @DateOnly;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

GO
