CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, ElectricitySubscriptions, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;






