/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsPaidUpDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsPaidUpDelete] @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventTransaction NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @FromDate DATE ,
        @CurrencyID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @PaidUp FLOAT ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate = s.FromDate ,
          @CurrencyID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_ElectricitySubscriptions AS s
        WHERE s.ID = @ID;
	    
      SELECT @PaidUpD = ISNULL(SUM(s.BalanceD), 0) ,
          @PaidUpLL = ISNULL(SUM(s.BalanceLL), 0) ,
          @PaidUpEuro = ISNULL(SUM(s.BalanceEuro), 0)
        FROM Transactions.t_TransactionDetail AS s
        WHERE s.TransactionID = @TransactionID AND s.Balance > 0;

      SET @PaidUp = Currencys.f_ChooseValue(@CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro);
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;

    END;

    BEGIN --Update t_ElectricitySubscriptions

      UPDATE Invoices.t_ElectricitySubscriptions
        SET PaidUp -= @PaidUp ,
            PaidUpD -= @PaidUpD ,
            PaidUpLL -= @PaidUpLL ,
            PaidUpEuro -= @PaidUpEuro
        WHERE ID = @ID;
	    
      UPDATE Invoices.t_ElectricitySubscriptions
        SET PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            Rest = Total - PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Total - PaidUp) ,
            RestD = TotalD - PaidUpD ,
            RestLL = TotalLL - PaidUpLL ,
            RestEuro = TotalEuro - PaidUpEuro
        WHERE ID = @ID;  

      UPDATE Invoices.t_ElectricitySubscriptions
        SET Paid = Invoices.f_ElectricitySubscriptionsGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;  
	    
    END;
 
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE ID = @TransactionID;

    END;
	
    SET @return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
    EXECUTE Transactions. s_TransactionMovingInsertPART @TransactionID, @UserID, @EventTransaction, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
	EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsPaidUpNew]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsPaidUpNew] @ID UNIQUEIDENTIFIER ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @FromDate_OLD DATE ,
        @PaidUp FLOAT ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @return INT = 0;
		
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate_OLD = s.FromDate ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_ElectricitySubscriptions AS s
        WHERE s.ID = @ID;
   
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
      
    END;

    BEGIN --Update t_ElectricitySubscriptions

      UPDATE Invoices.t_ElectricitySubscriptions
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpLL ,
            PaidUpEuro += @PaidUpEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpLL ,
            RestEuro -= @PaidUpEuro ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;

      UPDATE Invoices.t_ElectricitySubscriptions
        SET Rest = IIF(Rest < 0, 0, Rest) ,
            RestF = Currencys.f_Format(CurrencyID, IIF(Rest < 0, 0, Rest)) ,
            RestD = IIF(RestD < 0, 0, RestD) ,
            RestLL = IIF(RestLL < 0, 0, RestLL) ,
            RestEuro = IIF(RestEuro < 0, 0, RestEuro)
        WHERE ID = @ID;

      UPDATE Invoices.t_ElectricitySubscriptions
        SET Paid = Invoices.f_ElectricitySubscriptionsGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;
		
    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
	
    SET @return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
	
    EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate_OLD;
   
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;








