/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsUpdate] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @FromDate DATE ,
  @FromDateMonthly DATE ,
  @FromDateYearly DATE ,
  @ToDate DATE ,
  @IsActive BIT ,
  @AccountID UNIQUEIDENTIFIER ,
  @SalesAccountID UNIQUEIDENTIFIER ,
  @ElectricitySubscriptionTypeID UNIQUEIDENTIFIER ,
  @ElectricGeneratorID UNIQUEIDENTIFIER ,
  @ElectricalBoxID UNIQUEIDENTIFIER ,
  @TypeIs TINYINT ,
  @TotalAmperes FLOAT ,
  @PreviousConsumption FLOAT ,
  @CurrentConsumption FLOAT ,
  @TotalConsumption FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @FixedFees FLOAT ,
  @FixedFeesF NVARCHAR(MAX) ,
  @FixedFeesD FLOAT ,
  @FixedFeesLL FLOAT ,
  @FixedFeesEuro FLOAT ,
  @SubscriptionFees FLOAT ,
  @SubscriptionFeesF NVARCHAR(MAX) ,
  @SubscriptionFeesD FLOAT ,
  @SubscriptionFeesLL FLOAT ,
  @SubscriptionFeesEuro FLOAT ,
  @AdditionalFees FLOAT ,
  @AdditionalFeesF NVARCHAR(MAX) ,
  @AdditionalFeesD FLOAT ,
  @AdditionalFeesLL FLOAT ,
  @AdditionalFeesEuro FLOAT ,
  @Subtotal FLOAT ,
  @SubtotalF NVARCHAR(MAX) ,
  @SubtotalD FLOAT ,
  @SubtotalLL FLOAT ,
  @SubtotalEuro FLOAT ,
  @Discount FLOAT ,
  @DiscountF NVARCHAR(MAX) ,
  @DiscountD FLOAT ,
  @DiscountLL FLOAT ,
  @DiscountEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @CollectionOfficerEmployeeID UNIQUEIDENTIFIER ,
  @PrivateNote NVARCHAR(MAX) ,
  @PrintNote NVARCHAR(MAX) ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @ResetTransactions BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @FromDate_OLD DATE ,
        @AccountID_Old UNIQUEIDENTIFIER ,
        @ElectricGeneratorID_Old UNIQUEIDENTIFIER ,
        @ElectricalBoxID_Old UNIQUEIDENTIFIER ,
        @TotalAmperes_Old FLOAT ,
        @ActiveSubscriptions BIGINT ,
        @IsActive_Old BIT ,
        @LinkType INT = 259 ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate_OLD = s.FromDate ,
          @AccountID_Old = s.AccountID ,
          @ElectricGeneratorID_Old = s.ElectricGeneratorID ,
          @ElectricalBoxID_Old = s.ElectricalBoxID ,
          @TotalAmperes_Old = s.TotalAmperes ,
          @IsActive_Old = s.IsActive
        FROM Invoices.t_ElectricitySubscriptions AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Invoices.t_ElectricitySubscriptions
        SET RefPaper = @RefPaper ,
            FromDate = @FromDate ,
            FromDateMonthly = @FromDateMonthly ,
            FromDateYearly = @FromDateYearly ,
            ToDate = @ToDate ,
            IsActive = @IsActive ,
            AccountID = @AccountID ,
            SalesAccountID = @SalesAccountID ,
            ElectricitySubscriptionTypeID = @ElectricitySubscriptionTypeID ,
            ElectricGeneratorID = @ElectricGeneratorID ,
            ElectricalBoxID = @ElectricalBoxID ,
            TypeIs = @TypeIs ,
            TotalAmperes = @TotalAmperes ,
            PreviousConsumption = @PreviousConsumption ,
            CurrentConsumption = @CurrentConsumption ,
            TotalConsumption = @TotalConsumption ,
            CurrencyID = @CurrencyID ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            FixedFees = @FixedFees ,
            FixedFeesF = @FixedFeesF ,
            FixedFeesD = @FixedFeesD ,
            FixedFeesLL = @FixedFeesLL ,
            FixedFeesEuro = @FixedFeesEuro ,
            SubscriptionFees = @SubscriptionFees ,
            SubscriptionFeesF = @SubscriptionFeesF ,
            SubscriptionFeesD = @SubscriptionFeesD ,
            SubscriptionFeesLL = @SubscriptionFeesLL ,
            SubscriptionFeesEuro = @SubscriptionFeesEuro ,
            AdditionalFees = @AdditionalFees ,
            AdditionalFeesF = @AdditionalFeesF ,
            AdditionalFeesD = @AdditionalFeesD ,
            AdditionalFeesLL = @AdditionalFeesLL ,
            AdditionalFeesEuro = @AdditionalFeesEuro ,
            Subtotal = @Subtotal ,
            SubtotalF = @SubtotalF ,
            SubtotalD = @SubtotalD ,
            SubtotalLL = @SubtotalLL ,
            SubtotalEuro = @SubtotalEuro ,
            Discount = @Discount ,
            DiscountF = @DiscountF ,
            DiscountD = @DiscountD ,
            DiscountLL = @DiscountLL ,
            DiscountEuro = @DiscountEuro ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            PaidUp = @PaidUp ,
            PaidUpF = @PaidUpF ,
            PaidUpD = @PaidUpD ,
            PaidUpLL = @PaidUpLL ,
            PaidUpEuro = @PaidUpEuro ,
            Rest = @Rest ,
            RestF = @RestF ,
            RestD = @RestD ,
            RestLL = @RestLL ,
            RestEuro = @RestEuro ,
            Paid = @Paid ,
            CollectionOfficerEmployeeID = @CollectionOfficerEmployeeID ,
            PrivateNote = @PrivateNote ,
            PrintNote = @PrintNote ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;

    END;

     --Delete t_Transaction
    DELETE FROM Transactions.t_Transaction
      WHERE LinkType = @LinkType AND LinkID = @ID AND IIF(@ResetTransactions = 1, 0, LinkTypeSub) = 0;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

	--ElectricGenerators
    SET @TotalAmperes = IIF(@IsActive = 1, @TotalAmperes, 0);
    EXECUTE Invoices.s_ElectricGenerators_Addition_AmperesUsed_PART @ElectricGeneratorID, @TotalAmperes;
   
    SET @TotalAmperes_Old = IIF(@IsActive_Old = 1, 0 - @TotalAmperes_Old, 0);
    EXECUTE Invoices.s_ElectricGenerators_Addition_AmperesUsed_PART @ElectricGeneratorID_Old, @TotalAmperes_Old;

	--ElectricalBoxes
    SET @ActiveSubscriptions = IIF(@IsActive = 1, 1, 0);
    EXECUTE Invoices.s_ElectricalBoxes_Addition_ActiveSubscriptions_PART @ElectricalBoxID, @ActiveSubscriptions;
   
    SET @ActiveSubscriptions = IIF(@IsActive_Old = 1, -1, 0);
    EXECUTE Invoices.s_ElectricalBoxes_Addition_ActiveSubscriptions_PART @ElectricalBoxID_Old, @ActiveSubscriptions;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    IF @FromDate = @FromDate_OLD
    BEGIN
                                 
      EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate_OLD;
      EXECUTE Invoices.s_ProfitDaily_Electricity_Update_PART @FromDate;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Invoices].[s_ElectricitySubscriptionsUpdateRef]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionsUpdateRef] @ID UNIQUEIDENTIFIER ,
  @Ref BIGINT ,
  @RefF NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

	--Check
    IF EXISTS ( SELECT TOP ( 1 ) s.ID
                  FROM Invoices.t_ElectricitySubscriptionsArchives AS s
                  WHERE s.Ref = @Ref )
    BEGIN

      RETURN @Return;

    END;

    BEGIN --Update

      UPDATE Invoices.t_ElectricitySubscriptions
        SET Ref = @Ref ,
            RefF = @RefF ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_ElectricitySubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_ElectricitySubscriptionsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







