CREATE PROCEDURE [Invoices].[s_ElectricitySubscriptionTypesInsert] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @TypeIs TINYINT ,
  @PeriodType TINYINT ,
  @PeriodNumber INT ,
  @ElectricGeneratorID UNIQUEIDENTIFIER ,
  @TotalAmperes FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @FixedFees FLOAT ,
  @FixedFeesF NVARCHAR(MAX) ,
  @FixedFeesD FLOAT ,
  @FixedFeesLL FLOAT ,
  @FixedFeesEuro FLOAT ,
  @SubscriptionFees FLOAT ,
  @SubscriptionFeesF NVARCHAR(MAX) ,
  @SubscriptionFeesD FLOAT ,
  @SubscriptionFeesLL FLOAT ,
  @SubscriptionFeesEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @OrderNumber BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set Info
    
      SELECT @OrderNumber = ISNULL(MAX(s.OrderNumber), 0) + 1
        FROM Invoices.t_ElectricitySubscriptionTypes AS s;

    END;

