CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsArchivesRebuild] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild

      UPDATE Invoices.t_InternetSubscriptionsArchives
        SET CostF = Currencys.f_Format(CurrencyID, Cost) ,
            PriceF = Currencys.f_Format(CurrencyID, Price) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            RestF = Currencys.f_Format(CurrencyID, Rest) ,
            LastModifiedDate = GETDATE();

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






