GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @FromDate DATE ,
        @LinkType INT = 18 ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate = s.FromDate
        FROM Invoices.t_InternetSubscriptions AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Invoices.t_InternetSubscriptions
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = @LinkType AND LinkID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Invoices_InternetSubscriptions < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_InternetSubscriptions
        SET IsActive = IIF(ToDate >= DateTimes.f_GetToday(), 0, 1)
        WHERE IsActive = 1;

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Invoices_InternetSubscriptions = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;





GO
