CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsInsert] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @FromDate DATE ,
  @FromDateMonthly DATE ,
  @FromDateYearly DATE ,
  @ToDate DATE ,
  @IsActive BIT ,
  @AccountID UNIQUEIDENTIFIER ,
  @SalesAccountID UNIQUEIDENTIFIER ,
  @InternetPackageID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Cost FLOAT ,
  @CostF NVARCHAR(MAX) ,
  @CostD FLOAT ,
  @CostLL FLOAT ,
  @CostEuro FLOAT ,
  @Price FLOAT ,
  @PriceF NVARCHAR(MAX) ,
  @PriceD FLOAT ,
  @PriceLL FLOAT ,
  @PriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @PrivateNote NVARCHAR(MAX) ,
  @PrintNote NVARCHAR(MAX) ,
  @CustomerInternetSubscriptionsInfo Customers.tt_CustomerInternetSubscriptionsInfo READONLY ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Invoices.f_InternetSubscriptionsGetNewRef() ,
        @PriceAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Price, @CurrencyID, 1) ,
        @PriceEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Price, @CurrencyID, 1) ,
        @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_InternetSubscriptions
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            FromDate ,
            FromDateMonthly ,
            FromDateYearly ,
            ToDate ,
            IsActive ,
            AccountID ,
            SalesAccountID ,
            InternetPackageID ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            PriceAR ,
            PriceEN ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid ,
            EmployeeID ,
            PrivateNote ,
            PrintNote ,
            CreatedByUserID
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, N'0') ,
            @RefPaper ,
            @FromDate ,
            @FromDateMonthly ,
            @FromDateYearly ,
            @ToDate ,
            @IsActive ,
            @AccountID ,
            @SalesAccountID ,
            @InternetPackageID ,
            @CurrencyID ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Cost ,
            @CostF ,
            @CostD ,
            @CostLL ,
            @CostEuro ,
            @Price ,
            @PriceF ,
            @PriceD ,
            @PriceLL ,
            @PriceEuro ,
            @PriceAR ,
            @PriceEN ,
            @Profit ,
            @ProfitF ,
            @ProfitD ,
            @ProfitLL ,
            @ProfitEuro ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @Paid ,
            @EmployeeID ,
            @PrivateNote ,
            @PrintNote ,
            @UserID
          );	  

    END;

    EXECUTE Customers.s_Customer_Update_InternetSubscriptionsInfo_PART @CustomerInternetSubscriptionsInfo;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
	
    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;
 
    EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;


