/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsInserts] @InternetSubscriptions Invoices.tt_InternetSubscriptions READONLY ,
  @CustomerInternetSubscriptionsInfo Customers.tt_CustomerInternetSubscriptionsInfo READONLY ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Invoices.f_InternetSubscriptionsGetNewRef() - 1 ,
        @IDs Alls.tt_IDAndEvent;

      DECLARE @DateOnly DateTimes.tt_DateOnly;

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID ,
            EventIs
          )
        SELECT s.ID ,
            @Event
          FROM @InternetSubscriptions AS s;

      INSERT INTO @DateOnly
          ( DateOnly
          )
        SELECT DISTINCT s.FromDate
          FROM @InternetSubscriptions AS s;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_InternetSubscriptions
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            FromDate ,
            FromDateMonthly ,
            FromDateYearly ,
            ToDate ,
            IsActive ,
            AccountID ,
            SalesAccountID ,
            InternetPackageID ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            PriceAR ,
            PriceEN ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid ,
            EmployeeID ,
            PrivateNote ,
            PrintNote ,
            CreatedByUserID
          )
        SELECT s.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                ) ) ,
            FORMAT(@Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                       ) ), N'0') ,
            s.RefPaper ,
            s.FromDate ,
            s.FromDateMonthly ,
            s.FromDateYearly ,
            s.ToDate ,
            s.IsActive ,
            s.AccountID ,
            s.SalesAccountID ,
            s.InternetPackageID ,
            s.CurrencyID ,
            s.ExchangeRate ,
            s.ExchangeRateLL ,
            s.ExchangeRateEuro ,
            s.Cost ,
            s.CostF ,
            s.CostD ,
            s.CostLL ,
            s.CostEuro ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            Currencys.f_ToWordAR(s.Price, s.CurrencyID, 1) ,
            Currencys.f_ToWordAR(s.Price, s.CurrencyID, 1) ,
            s.Profit ,
            s.ProfitF ,
            s.ProfitD ,
            s.ProfitLL ,
            s.ProfitEuro ,
            s.PaidUp ,
            s.PaidUpF ,
            s.PaidUpD ,
            s.PaidUpLL ,
            s.PaidUpEuro ,
            s.Rest ,
            s.RestF ,
            s.RestD ,
            s.RestLL ,
            s.RestEuro ,
            s.Paid ,
            s.EmployeeID ,
            s.PrivateNote ,
            s.PrintNote ,
            @UserID
          FROM @InternetSubscriptions AS s;	  

    END;

    EXECUTE Customers.s_Customer_Update_InternetSubscriptionsInfo_PART @CustomerInternetSubscriptionsInfo;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Internet_Updates_PART @DateOnly;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;



GO
