/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsPaidUpDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsPaidUpDelete] @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventTransaction NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @FromDate DATE ,
        @CurrencyID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @PaidUp FLOAT ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate = s.FromDate ,
          @CurrencyID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_InternetSubscriptions AS s
        WHERE s.ID = @ID;
	    
      SELECT @PaidUpD = ISNULL(SUM(s.BalanceD), 0) ,
          @PaidUpLL = ISNULL(SUM(s.BalanceLL), 0) ,
          @PaidUpEuro = ISNULL(SUM(s.BalanceEuro), 0)
        FROM Transactions.t_TransactionDetail AS s
        WHERE s.TransactionID = @TransactionID AND s.Balance > 0;

      SET @PaidUp = Currencys.f_ChooseValue(@CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro);
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;

    END;

    BEGIN --Update t_InternetSubscriptions

      UPDATE Invoices.t_InternetSubscriptions
        SET PaidUp -= @PaidUp ,
            PaidUpD -= @PaidUpD ,
            PaidUpLL -= @PaidUpLL ,
            PaidUpEuro -= @PaidUpEuro
        WHERE ID = @ID;
	    
      UPDATE Invoices.t_InternetSubscriptions
        SET PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            Rest = Price - PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Price - PaidUp) ,
            RestD = PriceD - PaidUpD ,
            RestLL = PriceLL - PaidUpLL ,
            RestEuro = PriceEuro - PaidUpEuro
        WHERE ID = @ID;  

      UPDATE Invoices.t_InternetSubscriptions
        SET Paid = IIF(Rest = Price AND Price > 0, 0, IIF(Rest > 0, 1, 2))
        WHERE ID = @ID;  
	    
    END;
 
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE ID = @TransactionID;

    END;
	
    SET @return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
    EXECUTE Transactions.s_TransactionMovingInsertPART @TransactionID, @UserID, @EventTransaction, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsPaidUpNew]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsPaidUpNew] @ID UNIQUEIDENTIFIER ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @FromDate_OLD DATE ,
        @PaidUp FLOAT ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @return INT = 0;
		
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate_OLD = s.FromDate ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_InternetSubscriptions AS s
        WHERE s.ID = @ID;
   
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
      
    END;

    BEGIN --Update t_InternetSubscriptions

      UPDATE Invoices.t_InternetSubscriptions
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpLL ,
            PaidUpEuro += @PaidUpEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpLL ,
            RestEuro -= @PaidUpEuro ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;

      UPDATE Invoices.t_InternetSubscriptions
        SET Rest = IIF(Rest < 0, 0, Rest) ,
            RestF = Currencys.f_Format(CurrencyID, IIF(Rest < 0, 0, Rest)) ,
            RestD = IIF(RestD < 0, 0, RestD) ,
            RestLL = IIF(RestLL < 0, 0, RestLL) ,
            RestEuro = IIF(RestEuro < 0, 0, RestEuro)
        WHERE ID = @ID;

      UPDATE Invoices.t_InternetSubscriptions
        SET Paid = IIF(Rest = Price AND Price > 0, 0, IIF(Rest > 0, 1, 2))
        WHERE ID = @ID;
		
    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
	
    SET @return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
	
	EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate_OLD;
   
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;









GO
/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsRebuild]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsRebuild] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild

      UPDATE Invoices.t_InternetSubscriptions
        SET IsActive = IIF(DateTimes.f_GetToday() > ToDate, 0, 1) ,
            CostF = Currencys.f_Format(CurrencyID, Cost) ,
            PriceF = Currencys.f_Format(CurrencyID, Price) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            RestF = Currencys.f_Format(CurrencyID, Rest) ,
            LastModifiedDate = GETDATE();

      UPDATE Invoices.t_InternetSubscriptions
        SET Paid = IIF(Rest = Price AND Price > 0, 0, IIF(Rest > 0, 1, 2));

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





