/****** Object:  StoredProcedure [Invoices].[s_InternetSubscriptionsUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_InternetSubscriptionsUpdate] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @FromDate DATE ,
  @FromDateMonthly DATE ,
  @FromDateYearly DATE ,
  @ToDate DATE ,
  @IsActive BIT ,
  @AccountID UNIQUEIDENTIFIER ,
  @SalesAccountID UNIQUEIDENTIFIER ,
  @InternetPackageID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Cost FLOAT ,
  @CostF NVARCHAR(MAX) ,
  @CostD FLOAT ,
  @CostLL FLOAT ,
  @CostEuro FLOAT ,
  @Price FLOAT ,
  @PriceF NVARCHAR(MAX) ,
  @PriceD FLOAT ,
  @PriceLL FLOAT ,
  @PriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @PrivateNote NVARCHAR(MAX) ,
  @PrintNote NVARCHAR(MAX) ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @ResetTransactions BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @FromDate_OLD DATE ,
        @PriceAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Price, @CurrencyID, 1) ,
        @PriceEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Price, @CurrencyID, 1) ,
        @LinkType INT = 18 ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromDate_OLD = s.FromDate
        FROM Invoices.t_InternetSubscriptions AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Invoices.t_InternetSubscriptions
        SET RefPaper = @RefPaper ,
            FromDate = @FromDate ,
            FromDateMonthly = @FromDateMonthly ,
            FromDateYearly = @FromDateYearly ,
            ToDate = @ToDate ,
            IsActive = @IsActive ,
            AccountID = @AccountID ,
            SalesAccountID = @SalesAccountID ,
            InternetPackageID = @InternetPackageID ,
            CurrencyID = @CurrencyID ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Cost = @Cost ,
            CostF = @CostF ,
            CostD = @CostD ,
            CostLL = @CostLL ,
            CostEuro = @CostEuro ,
            Price = @Price ,
            PriceF = @PriceF ,
            PriceD = @PriceD ,
            PriceLL = @PriceLL ,
            PriceEuro = @PriceEuro ,
            PriceAR = @PriceAR ,
            PriceEN = @PriceEN ,
            Profit = @Profit ,
            ProfitF = @ProfitF ,
            ProfitD = @ProfitD ,
            ProfitLL = @ProfitLL ,
            ProfitEuro = @ProfitEuro ,
            PaidUp = @PaidUp ,
            PaidUpF = @PaidUpF ,
            PaidUpD = @PaidUpD ,
            PaidUpLL = @PaidUpLL ,
            PaidUpEuro = @PaidUpEuro ,
            Rest = @Rest ,
            RestF = @RestF ,
            RestD = @RestD ,
            RestLL = @RestLL ,
            RestEuro = @RestEuro ,
            Paid = @Paid ,
            EmployeeID = @EmployeeID ,
            PrivateNote = @PrivateNote ,
            PrintNote = @PrintNote ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;

    END;

     --Delete t_Transaction
    DELETE FROM Transactions.t_Transaction
      WHERE LinkType = @LinkType AND LinkID = @ID AND IIF(@ResetTransactions = 1, 0, LinkTypeSub) = 0;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    SET @Return = -1;
    EXECUTE Invoices.s_InternetSubscriptionsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_InternetSubscriptionsLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    IF @FromDate = @FromDate_OLD
    BEGIN
                                 
      EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate_OLD;
      EXECUTE Invoices.s_ProfitDaily_Internet_Update_PART @FromDate;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








GO
