CREATE PROCEDURE [Invoices].[s_Invoices_PurchasingUnsaved_ExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Invoices_PurchasingUnsaved < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN--
    
      DECLARE @IDs Alls.tt_Guid;

    END;


    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID
          )
        SELECT ID
          FROM Invoices.t_PurchasingUnsaved
          WHERE DATEDIFF(WEEK, DateIs, GETDATE()) >= 1;

    END;

    BEGIN --Delete 

      DELETE FROM Invoices.t_PurchasingUnsavedDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_PurchasingUnsavedDetail.PurchasingUnsavedID );
  
      DELETE FROM Invoices.t_PurchasingUnsaved
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_PurchasingUnsaved.ID );

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Invoices_PurchasingUnsaved = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;














