/****** Object:  StoredProcedure [Invoices].[s_InvoiceTitleUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_InvoiceTitleUpdate] @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Invoices.t_InvoiceTitle AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Invoices.t_InvoiceTitle
        SET Name = @Name ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_InvoiceTitleMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --t_PurchaseOrder

        UPDATE Invoices.t_PurchaseOrder
          SET InvoiceTitle = @Name
          WHERE InvoiceTitleID = @ID;

        UPDATE Invoices.t_PurchaseOrderArchive
          SET InvoiceTitle = @Name
          WHERE InvoiceTitleID = @ID;

      END;

      BEGIN --Fix Invoices

        UPDATE Invoices.t_Sold
          SET InvoiceTitle = @Name ,
              RowVersionID = [DateTimes].[f_GetRowVersionID]()
          WHERE InvoiceTitleID = @ID;

        UPDATE Invoices.t_SoldReturn
          SET InvoiceTitle = @Name
          WHERE InvoiceTitleID = @ID;

        UPDATE Invoices.t_Purchasing
          SET InvoiceTitle = @Name
          WHERE InvoiceTitleID = @ID;

        UPDATE Invoices.t_PurchasingReturn
          SET InvoiceTitle = @Name
          WHERE InvoiceTitleID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
