/****** Object:  StoredProcedure [Invoices].[s_PhoneCustomerInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneCustomerInsert] @Name NVARCHAR(MAX) ,
  @CurrentBalance FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @PhonePaymentID UNIQUEIDENTIFIER = NEWID() ,
        @Return INT = 0;
					
    END;

    BEGIN --Set
	
      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_PhonePayment AS s;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_PhoneCustomer
          ( ID, Name, CurrentBalance, Notes )
        VALUES ( @ID, @Name, @CurrentBalance, @Notes );

    END;

    IF @CurrentBalance <> 0
    BEGIN --Insert t_PhonePayment

      INSERT INTO Invoices.t_PhonePayment
          ( ID ,
            Ref ,
            CustomerID ,
            Amount
          )
        VALUES
          ( @PhonePaymentID ,
            @Ref ,
            @ID ,
            @CurrentBalance
          );

      EXECUTE Invoices.s_PhonePaymentFixPART @PhonePaymentID; 

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneCustomerMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



