/****** Object:  StoredProcedure [Invoices].[s_PhoneCustomerUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneCustomerUpdate] @Name NVARCHAR(MAX) ,
  @CurrentBalance FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @NameOld NVARCHAR(450) ,
        @Return INT = 0;
					
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Invoices.t_PhoneCustomer AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert

      UPDATE Invoices.t_PhoneCustomer
        SET Name = @Name ,
            Notes = @Notes
        WHERE ID = @ID;

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN
    
      UPDATE Invoices.t_PhonePayment
        SET Customer = @Name
        WHERE CustomerID = @ID;
    
      UPDATE Invoices.t_PhoneSubscriber
        SET Customer = @Name
        WHERE CustomerID = @ID;
    
      UPDATE Invoices.t_PhoneSubscription
        SET Customer = @Name
        WHERE CustomerID = @ID;

    END;

    IF @CurrentBalance <> 0
    BEGIN --Insert t_PhonePayment
                            
      DECLARE @PhonePaymentID UNIQUEIDENTIFIER = NEWID() ,
        @Ref BIGINT;

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_PhonePayment AS s;

      INSERT INTO Invoices.t_PhonePayment
          ( ID ,
            Ref ,
            CustomerID ,
            Amount
          )
        VALUES
          ( @PhonePaymentID ,
            @Ref ,
            @ID ,
            @CurrentBalance
          );


      EXECUTE Invoices.s_PhonePaymentFixPART @PhonePaymentID; 

      EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @CurrentBalance, @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneCustomerMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








GO
