CREATE PROCEDURE [Invoices].[s_PhonePaymentInsert] @DateIs DATE ,
  @CustomerID UNIQUEIDENTIFIER ,
  @Amount FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @Return INT = 0;
					
    END;

    BEGIN --Set
	
      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_PhonePayment AS s;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_PhonePayment
          ( ID ,
            Ref ,
            DateIs ,
            CustomerID ,
            Amount ,
            Notes
          )
        VALUES
          ( @ID ,
            @Ref ,
            @DateIs ,
            @CustomerID ,
            @Amount ,
            @Notes
          );

    END;

    EXECUTE Invoices.s_PhonePaymentFixPART @ID; 

	EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @Amount, @CustomerID;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhonePaymentMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, '#') ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








