CREATE PROCEDURE [Invoices].[s_PhonePaymentUpdate] @DateIs DATE ,
  @CustomerID UNIQUEIDENTIFIER ,
  @Amount FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @CustomerIDOld UNIQUEIDENTIFIER ,
        @AmountOld FLOAT ,
        @Return INT = 0;
							
    END;

    BEGIN --Set

      SELECT TOP ( 1 ) @CustomerIDOld = t.CustomerID ,
          @AmountOld = 0 - t.Amount
        FROM Invoices.t_PhonePayment AS t
        WHERE t.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Invoices.t_PhonePayment
        SET DateIs = @DateIs ,
            CustomerID = @CustomerID ,
            Amount = @Amount ,
            Notes = @Notes
        WHERE ID = @ID;

    END;

    EXECUTE Invoices.s_PhonePaymentFixPART @ID; 

    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @AmountOld, @CustomerIDOld;
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @Amount, @CustomerID;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhonePaymentMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








