/****** Object:  StoredProcedure [Invoices].[s_PhoneSubscriberFixPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PhoneSubscriberFixPART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Update

    UPDATE Invoices.t_PhoneSubscriber
      SET Customer = Invoices.f_PhoneCustomerGetName(CustomerID) ,
          PrimaryPhoneNumber = Invoices.f_PrimaryPhoneNumberGetPhoneNumber(PrimaryPhoneNumberID) ,
          MonthlyFees = CEILING(MonthlyFees / 1000.0) * 1000.0 ,
          ExtraCharge = CEILING(ExtraCharge / 1000.0) * 1000.0
      WHERE ID = @ID;

    UPDATE Invoices.t_PhoneSubscriber
      SET Total = MonthlyFees + ExtraCharge
      WHERE ID = @ID;

  END;

END;





