GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriberInsert] @CustomerID UNIQUEIDENTIFIER ,
  @SerialNumber NVARCHAR(MAX) ,
  @PrimaryPhoneNumberID UNIQUEIDENTIFIER ,
  @SimCardNumber NVARCHAR(MAX) ,
  @GBQuota INT ,
  @MonthlyFeesD FLOAT ,
  @ExtraChargeD FLOAT ,
  @Deposit FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @MonthlyFees FLOAT = @MonthlyFeesD * Currencys.f_CurrencyGetExchangeRateLL() ,
        @ExtraCharge FLOAT = @ExtraChargeD * Currencys.f_CurrencyGetExchangeRateLL() ,
        @Return INT = 0;
					
    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_PhoneSubscriber
          ( ID ,
            CustomerID ,
            SerialNumber ,
            PrimaryPhoneNumberID ,
            SimCardNumber ,
            GBQuota ,
            MonthlyFeesD ,
            MonthlyFees ,
            ExtraChargeD ,
            ExtraCharge ,
            TotalD ,
            Total ,
            Deposit ,
            Notes
          )
        VALUES
          ( @ID ,
            @CustomerID ,
            @SerialNumber ,
            @PrimaryPhoneNumberID ,
            @SimCardNumber ,
            @GBQuota ,
            @MonthlyFeesD ,
            @MonthlyFees ,
            @ExtraChargeD ,
            @ExtraCharge ,
            @MonthlyFeesD + @ExtraChargeD ,
            @MonthlyFees + @ExtraCharge ,
            @Deposit ,
            @Notes
          );

    END;

    EXECUTE Invoices.s_PhoneSubscriberFixPART @ID;
  
    EXECUTE Invoices.s_PrimaryPhoneNumberRebuildingStatisticsPART @PrimaryPhoneNumberID;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriberMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






