GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriberRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild statistics

      UPDATE Invoices.t_PhoneSubscriber
        SET Customer = Invoices.f_PhoneCustomerGetName(CustomerID) ,
            PrimaryPhoneNumber = Invoices.f_PrimaryPhoneNumberGetPhoneNumber(PrimaryPhoneNumberID) ,
            MonthlyFees = CEILING(( MonthlyFeesD * Currencys.f_CurrencyGetExchangeRateLL() ) / 1000.0) * 1000.0 ,
            ExtraCharge = CEILING(( ExtraChargeD * Currencys.f_CurrencyGetExchangeRateLL() ) / 1000.0) * 1000.0;
 
      UPDATE Invoices.t_PhoneSubscriber
        SET Total = MonthlyFees + ExtraCharge;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriberMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





