/****** Object:  StoredProcedure [Invoices].[s_PhoneSubscriberUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriberUpdate] @CustomerID UNIQUEIDENTIFIER ,
  @SerialNumber NVARCHAR(MAX) ,
  @PrimaryPhoneNumberID UNIQUEIDENTIFIER ,
  @SimCardNumber NVARCHAR(MAX) ,
  @GBQuota INT ,
  @MonthlyFeesD FLOAT ,
  @ExtraChargeD FLOAT ,
  @Deposit FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @PrimaryPhoneNumberIDOld UNIQUEIDENTIFIER ,
        @MonthlyFees FLOAT = @MonthlyFeesD * Currencys.f_CurrencyGetExchangeRateLL() ,
        @ExtraCharge FLOAT = @ExtraChargeD * Currencys.f_CurrencyGetExchangeRateLL() ,
        @Return INT = 0;
					
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @PrimaryPhoneNumberIDOld = s.PrimaryPhoneNumberID
        FROM Invoices.t_PhoneSubscriber AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert

      UPDATE Invoices.t_PhoneSubscriber
        SET CustomerID = @CustomerID ,
            SerialNumber = @SerialNumber ,
            PrimaryPhoneNumberID = @PrimaryPhoneNumberID ,
            SimCardNumber = @SimCardNumber ,
            GBQuota = @GBQuota ,
            MonthlyFeesD = @MonthlyFeesD ,
            MonthlyFees = @MonthlyFees ,
            ExtraChargeD = @ExtraChargeD ,
            ExtraCharge = @ExtraCharge ,
            TotalD = @MonthlyFeesD + @ExtraChargeD ,
            Total = @MonthlyFees + @ExtraCharge ,
            Deposit = @Deposit ,
            Notes = @Notes
        WHERE ID = @ID;

    END;

    EXECUTE Invoices.s_PhoneSubscriberFixPART @ID;
  
    EXECUTE Invoices.s_PrimaryPhoneNumberRebuildingStatisticsPART @PrimaryPhoneNumberID;

    IF @PrimaryPhoneNumberIDOld <> @PrimaryPhoneNumberID
    BEGIN
                                                           
      EXECUTE Invoices.s_PrimaryPhoneNumberRebuildingStatisticsPART @PrimaryPhoneNumberIDOld;

    END;  

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriberMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






