GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriptionDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @PhoneSubscriberID UNIQUEIDENTIFIER ,
        @CustomerIDOld UNIQUEIDENTIFIER ,
        @MonthlyFeesOld FLOAT ,
        @ExtraChargeOld FLOAT ,
        @OldBalance FLOAT ,
        @Return INT = 0;
					
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @PhoneSubscriberID = s.PhoneSubscriberID ,
          @CustomerIDOld = s.CustomerID ,
          @MonthlyFeesOld = ISNULL(s.MonthlyFees, 0) ,
          @ExtraChargeOld = ISNULL(s.ExtraCharge, 0)
        FROM Invoices.t_PhoneSubscription AS s
        WHERE s.ID = @ID;
	
      SET @OldBalance = @MonthlyFeesOld + @ExtraChargeOld;
	      
    END;

    BEGIN --Delete

      DELETE FROM Invoices.t_PhoneSubscription
        WHERE ID = @ID;

    END;

    EXECUTE Invoices.s_PhoneSubscriptionFixPART @ID;

    EXECUTE Invoices.s_PhoneSubscriberNewSubscriptionDateFixPART @PhoneSubscriberID;
	
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @OldBalance, @CustomerIDOld;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








