/****** Object:  StoredProcedure [Invoices].[s_PhoneSubscriptionInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriptionInsert] @PhoneSubscriberID UNIQUEIDENTIFIER ,
  @SerialNumber NVARCHAR(MAX) ,
  @PrimaryPhoneNumberID UNIQUEIDENTIFIER ,
  @SimCardNumber NVARCHAR(MAX) ,
  @GBQuota INT ,
  @MonthlyFees FLOAT ,
  @ExtraCharge FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @CustomerID UNIQUEIDENTIFIER ,
        @DateIs DATE ,
        @DateToday DATE = GETDATE() ,
        @Total FLOAT = 0 - ( @MonthlyFees + @ExtraCharge ) ,
        @Return INT = 0;
					
    END;

    BEGIN --Set
	
      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_PhoneSubscription AS s;
		      
      SELECT @DateIs = MAX(s.DateIs)
        FROM Invoices.t_PhoneSubscription AS s
        WHERE s.PhoneSubscriberID = @PhoneSubscriberID;
   
      SET @DateIs = IIF(@DateIs IS NULL, DATEFROMPARTS(YEAR(@DateToday), IIF(DAY(@DateToday) >= 15 OR MONTH(@DateToday) = 1, MONTH(@DateToday), MONTH(@DateToday) - 1), 15), DATEADD(MONTH, 1, @DateIs));
	
      SELECT TOP ( 1 ) @CustomerID = t.CustomerID
        FROM Invoices.t_PhoneSubscriber AS t
        WHERE t.ID = @PhoneSubscriberID;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_PhoneSubscription
          ( ID ,
            PhoneSubscriberID ,
            Ref ,
            DateIs ,
            CustomerID ,
            Customer ,
            SerialNumber ,
            PrimaryPhoneNumberID ,
            SimCardNumber ,
            GBQuota ,
            MonthlyFees ,
            ExtraCharge ,
            Notes 
          )
        SELECT @ID ,
            t.ID ,
            @Ref ,
            @DateIs ,
            t.CustomerID ,
            t.Customer ,
            @SerialNumber ,
            @PrimaryPhoneNumberID ,
            @SimCardNumber ,
            @GBQuota ,
            @MonthlyFees ,
            @ExtraCharge ,
            @Notes
          FROM Invoices.t_PhoneSubscriber AS t
          WHERE t.ID = @PhoneSubscriberID;
          
    END;
	
    BEGIN --Update t_PhoneSubscriber

      UPDATE Invoices.t_PhoneSubscriber
        SET ExtraChargeD = 0 ,
            ExtraCharge = 0 ,
            TotalD = MonthlyFeesD ,
            Total = MonthlyFees
        WHERE ID = @PhoneSubscriberID;
          
    END;

    EXECUTE Invoices.s_PhoneSubscriptionFixPART @ID;

    EXECUTE Invoices.s_PhoneSubscriberNewSubscriptionDateFixPART @PhoneSubscriberID;
		
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @Total, @CustomerID;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, '#') ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











