GO
CREATE PROCEDURE [Invoices].[s_PhoneSubscriptionInsertShort] @PhoneSubscriberID UNIQUEIDENTIFIER ,
  @PreviousMonth BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT ,
        @DateIs DATE ,
        @DateToday DATE = GETDATE() ,
        @CustomerID UNIQUEIDENTIFIER ,
        @MonthlyFees FLOAT ,
        @ExtraCharge FLOAT ,
        @Total FLOAT ,
        @Return INT = 0;
					
    END;

    BEGIN --Set
	
      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_PhoneSubscription AS s;
		      
      SELECT @DateIs = MAX(s.DateIs)
        FROM Invoices.t_PhoneSubscription AS s
        WHERE s.PhoneSubscriberID = @PhoneSubscriberID;
   
      SET @DateIs = IIF(@DateIs IS NULL, DATEFROMPARTS(YEAR(@DateToday), IIF(DAY(@DateToday) >= 15 OR MONTH(@DateToday) = 1, MONTH(@DateToday), MONTH(@DateToday) - 1), 15), DATEADD(MONTH, 1, @DateIs));
    
      SET @DateIs = IIF(@PreviousMonth = 0, @DateIs, DATEADD(MONTH, -1, @DateIs));

      SELECT TOP ( 1 ) @CustomerID = t.CustomerID ,
          @Total = 0 - ( ISNULL(t.MonthlyFees, 0) + ISNULL(t.ExtraCharge, 0) )
        FROM Invoices.t_PhoneSubscriber AS t
        WHERE t.ID = @PhoneSubscriberID;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_PhoneSubscription
          ( ID ,
            PhoneSubscriberID ,
            Ref ,
            DateIs ,
            CustomerID ,
            Customer ,
            SerialNumber ,
            PrimaryPhoneNumberID ,
            PrimaryPhoneNumber ,
            SimCardNumber ,
            GBQuota ,
            MonthlyFees ,
            ExtraCharge ,
            Notes 
          )
        SELECT @ID ,
            t.ID ,
            @Ref ,
            @DateIs ,
            t.CustomerID ,
            t.Customer ,
            t.SerialNumber ,
            t.PrimaryPhoneNumberID ,
            t.PrimaryPhoneNumber ,
            t.SimCardNumber ,
            t.GBQuota ,
            t.MonthlyFees ,
            t.ExtraCharge ,
            t.Notes
          FROM Invoices.t_PhoneSubscriber AS t
          WHERE t.ID = @PhoneSubscriberID;
          
    END;
	
    BEGIN --Update t_PhoneSubscriber

      UPDATE Invoices.t_PhoneSubscriber
        SET ExtraChargeD = 0 ,
            ExtraCharge = 0 ,
            TotalD = MonthlyFeesD ,
            Total = MonthlyFees
        WHERE ID = @PhoneSubscriberID;
          
    END;
	
    EXECUTE Invoices.s_PhoneSubscriptionFixPART @ID;

    EXECUTE Invoices.s_PhoneSubscriberNewSubscriptionDateFixPART @PhoneSubscriberID;
		
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @Total, @CustomerID;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
