/****** Object:  StoredProcedure [Invoices].[s_PhoneSubscriptionUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PhoneSubscriptionUpdate] @CustomerID UNIQUEIDENTIFIER ,
  @SerialNumber NVARCHAR(MAX) ,
  @PrimaryPhoneNumberID UNIQUEIDENTIFIER ,
  @SimCardNumber NVARCHAR(MAX) ,
  @GBQuota INT ,
  @MonthlyFees FLOAT ,
  @ExtraCharge FLOAT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @PhoneSubscriberID UNIQUEIDENTIFIER ,
        @CustomerIDOld UNIQUEIDENTIFIER ,
        @MonthlyFeesOld FLOAT ,
        @ExtraChargeOld FLOAT ,
        @OldBalance FLOAT ,
        @Return INT = 0;
					
    END;

    BEGIN --Set

      SELECT TOP ( 1 ) @PhoneSubscriberID = s.PhoneSubscriberID ,
          @CustomerIDOld = s.CustomerID ,
          @MonthlyFeesOld = ISNULL(s.MonthlyFees, 0) ,
          @ExtraChargeOld = ISNULL(s.ExtraCharge, 0)
        FROM Invoices.t_PhoneSubscription AS s
        WHERE s.ID = @ID;
	
      SET @OldBalance = @MonthlyFeesOld + @ExtraChargeOld;
	      
    END;

    BEGIN --Update

      UPDATE Invoices.t_PhoneSubscription
        SET CustomerID = @CustomerID ,
            SerialNumber = @SerialNumber ,
            PrimaryPhoneNumberID = @PrimaryPhoneNumberID ,
            SimCardNumber = @SimCardNumber ,
            GBQuota = @GBQuota ,
            MonthlyFees = @MonthlyFees ,
            ExtraCharge = @ExtraCharge ,
            Notes = @Notes
        WHERE ID = @ID;
          
    END;

    EXECUTE Invoices.s_PhoneSubscriptionFixPART @ID;

    EXECUTE Invoices.s_PhoneSubscriberNewSubscriptionDateFixPART @PhoneSubscriberID;
	
    SET @MonthlyFees = 0 - ( @MonthlyFees + @ExtraCharge );		
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @MonthlyFees, @CustomerID;
    EXECUTE Invoices.s_PhoneCustomerIncreaseAmountPART @OldBalance, @CustomerIDOld;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PhoneSubscriptionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









GO
