CREATE PROCEDURE [Invoices].[s_PrimaryPhoneNumberUpdate] @PhoneNumber NVARCHAR(MAX) ,
  @SerialNumber NVARCHAR(MAX) ,
  @GB INT ,
  @Notes NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @PhoneNumberOld NVARCHAR(450) ,
        @Return INT = 0;
					
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @PhoneNumberOld = s.PhoneNumber
        FROM Invoices.t_PrimaryPhoneNumber AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert

      UPDATE Invoices.t_PrimaryPhoneNumber
        SET PhoneNumber = @PhoneNumber ,
            SerialNumber = @SerialNumber ,
            GB = @GB ,
            GBAvailable = @GB - GBUsed ,
            Notes = @Notes
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PrimaryPhoneNumberMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    IF @PhoneNumberOld COLLATE Arabic_CS_AS <> @PhoneNumber COLLATE Arabic_CS_AS
    BEGIN --Fix

      UPDATE Invoices.t_PhoneSubscriber
        SET PrimaryPhoneNumber = @PhoneNumber
        WHERE PrimaryPhoneNumberID = @ID;

      UPDATE Invoices.t_PhoneSubscription
        SET PrimaryPhoneNumber = @PhoneNumber
        WHERE PrimaryPhoneNumberID = @ID;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







