GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Invoices].[s_PrimaryPhoneNumberUpdateNotSync] @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_PrimaryPhoneNumber ON Invoices.t_PrimaryPhoneNumber;

    BEGIN --Update

      UPDATE Invoices.t_PrimaryPhoneNumber
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_PrimaryPhoneNumber.ID );

    END;

    ENABLE TRIGGER Invoices.tr_PrimaryPhoneNumber ON Invoices.t_PrimaryPhoneNumber;
   
    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, PrimaryPhoneNumber, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;













