                  t.Electricity_RealProfitD = s.TotalD - s.DebtsD ,
                  t.Electricity_RealProfitLL = s.TotalLL - s.DebtsLL ,
                  t.Electricity_RealProfitEuro = s.TotalEuro - s.DebtsEuro ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]()
    WHEN NOT MATCHED BY SOURCE THEN
      UPDATE SET t.Electricity_Count = 0 ,
