/****** Object:  StoredProcedure [Invoices].[s_ProfitDaily_Expenses_Update_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ProfitDaily_Expenses_Update_PART] @DateOnly DATE
AS
BEGIN
  
  BEGIN --Declare
	
    DECLARE @Profit AS TABLE
      (
        DateIs DATE NOT NULL ,
        TotalD FLOAT NULL ,
        TotalLL FLOAT NULL ,
        TotalEuro FLOAT NULL
      );
	  	
  END;

  BEGIN --Set info
	
    INSERT INTO @Profit
        ( DateIs ,
          TotalD ,
          TotalLL ,
          TotalEuro
        )
      SELECT t.DateOnly ,
          COALESCE(SUM(t.DebitD), 0) ,
          COALESCE(SUM(t.DebitLL), 0) ,
          COALESCE(SUM(t.DebitEuro), 0)
        FROM Transactions.t_TransactionDetail AS t
        INNER JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
        INNER JOIN Transactions.t_Transaction AS t2 ON t2.ID = t.TransactionID
		LEFT JOIN Company.t_Expense AS t3 ON t3.ID = t2.LinkID
        WHERE @DateOnly = t.DateOnly AND t.Debit > 0 AND ( t1.NumberIs BETWEEN 6200000000 AND 6999999999 ) AND ( t1.NumberIs NOT BETWEEN 6300000000 AND 6399999999 ) AND t2.LinkType IN ( 8, 69, 182 ) AND ISNULL(t3.LinkedType, 69) <> 0
        GROUP BY t.DateOnly;
   
  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.DateIs
                    FROM @Profit AS s )
  BEGIN
     
    INSERT INTO @Profit
        ( DateIs, TotalD, TotalLL, TotalEuro )
      VALUES ( @DateOnly, 0, 0, 0 );

  END;	

  BEGIN --Insert
	
    MERGE Invoices.t_ProfitDaily AS t
    USING @Profit AS s
    ON s.DateIs = t.DateIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( ID ,
               DateIs ,
               Expenses_TotalD ,
               Expenses_TotalLL ,
               Expenses_TotalEuro 
             )
      VALUES ( FORMAT(s.DateIs, N'yyyyMMdd-0000-0000-0000-000000000000') ,
               s.DateIs ,
               s.TotalD ,
               s.TotalLL ,
               s.TotalEuro
             )
    WHEN MATCHED THEN
      UPDATE SET t.Expenses_TotalD = s.TotalD ,
                  t.Expenses_TotalLL = s.TotalLL ,
                  t.Expenses_TotalEuro = s.TotalEuro ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]();

  END;
  
  EXECUTE Invoices.s_ProfitDaily_Recalculation_PART @DateOnly;  

END;





