        WHERE t.Debit > 0 AND ( t1.NumberIs BETWEEN 6200000000 AND 6999999999 ) AND ( t1.NumberIs NOT BETWEEN 6300000000 AND 6399999999 ) AND t2.LinkType IN ( 8, 69, 182 ) AND ISNULL(t3.LinkedType, 69) <> 0
        GROUP BY t.DateOnly;
   
  END;
  	
  BEGIN --Insert
	
    MERGE Invoices.t_ProfitDaily AS t
    USING @Profit AS s
    ON s.DateIs = t.DateIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( ID ,
               DateIs ,
               Expenses_TotalD ,
               Expenses_TotalLL ,
               Expenses_TotalEuro 
             )
      VALUES ( FORMAT(s.DateIs, N'yyyyMMdd-0000-0000-0000-000000000000') ,
               s.DateIs ,
               s.TotalD ,
               s.TotalLL ,
               s.TotalEuro
             )
    WHEN MATCHED THEN
      UPDATE SET t.Expenses_TotalD = s.TotalD ,
                  t.Expenses_TotalLL = s.TotalLL ,
                  t.Expenses_TotalEuro = s.TotalEuro ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]()
    WHEN NOT MATCHED BY SOURCE THEN
      UPDATE SET t.Expenses_TotalD = 0 ,
                  t.Expenses_TotalLL = 0 ,
                  t.Expenses_TotalEuro = 0 ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]();

  END;
  

END;




