        WHERE EXISTS ( SELECT TOP ( 1 ) s.DateOnly
                        FROM @DateOnly AS s
                        WHERE s.DateOnly = t.DateOnly ) AND t.Debit > 0 AND ( t1.NumberIs BETWEEN 6200000000 AND 6999999999 ) AND ( t1.NumberIs NOT BETWEEN 6300000000 AND 6399999999 ) AND t2.LinkType IN ( 8, 69, 182 ) AND ISNULL(t3.LinkedType, 69) <> 0
        GROUP BY t.DateOnly;
   
  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.DateIs
                    FROM @Profit AS s )
  BEGIN
     
    INSERT INTO @Profit
        ( DateIs ,
          TotalD ,
          TotalLL ,
          TotalEuro
        )
      SELECT DateOnly ,
          0 ,
          0 ,
          0
        FROM @DateOnly
		GROUP BY DateOnly;

  END;	

  BEGIN --Insert
	
