BEGIN
  
  BEGIN --Declare
	
    DECLARE @Profit AS TABLE
      (
        DateIs DATE NOT NULL ,
        CountIs BIGINT NULL ,
        TotalD FLOAT NULL ,
        TotalLL FLOAT NULL ,
        TotalEuro FLOAT NULL ,
        DebtsD FLOAT NULL ,
        DebtsLL FLOAT NULL ,
        DebtsEuro FLOAT NULL
      );
	  	
  END;

  BEGIN --Set info
	
    INSERT INTO @Profit
        ( DateIs ,
          CountIs ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          DebtsD ,
          DebtsLL ,
          DebtsEuro
        )
      SELECT t.DateOnly ,
          COALESCE(SUM(t.CountIs), 0) ,
          COALESCE(SUM(t.TotalD), 0) ,
          COALESCE(SUM(t.TotalLL), 0) ,
          COALESCE(SUM(t.TotalEuro), 0) ,
          COALESCE(SUM(t.RestD), 0) ,
          COALESCE(SUM(t.RestLL), 0) ,
          COALESCE(SUM(t.RestEuro), 0)
        FROM ( SELECT s.DateIs AS DateOnly ,
                  COUNT_BIG(s.ID) AS CountIs ,
                  COALESCE(SUM(s.TotalD), 0) AS TotalD ,
                  COALESCE(SUM(s.TotalLL), 0) AS TotalLL ,
                  COALESCE(SUM(s.TotalEuro), 0) AS TotalEuro ,
                  COALESCE(SUM(s.RestD), 0) AS RestD ,
                  COALESCE(SUM(s.RestLL), 0) AS RestLL ,
                  COALESCE(SUM(s.RestEuro), 0) AS RestEuro
                FROM Gym.t_GymSubscription AS s
                WHERE s.DateIs = @DateOnly
                GROUP BY s.DateIs
               UNION ALL
               SELECT s.DateIs AS DateOnly ,
                  COUNT_BIG(s.ID) AS CountIs ,
                  COALESCE(SUM(s.TotalD), 0) AS TotalD ,
                  COALESCE(SUM(s.TotalLL), 0) AS TotalLL ,
                  COALESCE(SUM(s.TotalEuro), 0) AS TotalEuro ,
                  COALESCE(SUM(s.RestD), 0) AS RestD ,
                  COALESCE(SUM(s.RestLL), 0) AS RestLL ,
                  COALESCE(SUM(s.RestEuro), 0) AS RestEuro
                FROM Gym.t_GymSubscriptionHistory AS s
                WHERE s.DateIs = @DateOnly
                GROUP BY s.DateIs
             ) AS t
        GROUP BY t.DateOnly;
   
  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.DateIs
                    FROM @Profit AS s )
  BEGIN
     
    INSERT INTO @Profit
        ( DateIs ,
          CountIs ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          DebtsD ,
          DebtsLL ,
          DebtsEuro
        )
      VALUES
        ( @DateOnly ,
          0 ,
          0 ,
          0 ,
          0 ,
          0 ,
          0 ,
          0
        );

  END;	

  BEGIN --Insert
	
    MERGE Invoices.t_ProfitDaily AS t
    USING @Profit AS s
    ON s.DateIs = t.DateIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( ID ,
               DateIs ,
               Gym_Count ,
               Gym_TotalD ,
               Gym_TotalLL ,
               Gym_TotalEuro ,
               Gym_DebtsD ,
               Gym_DebtsLL ,
               Gym_DebtsEuro ,
               Gym_RealProfitD ,
               Gym_RealProfitLL ,
               Gym_RealProfitEuro 
             )
      VALUES ( FORMAT(s.DateIs, N'yyyyMMdd-0000-0000-0000-000000000000') ,
               s.DateIs ,
               s.CountIs ,
               s.TotalD ,
               s.TotalLL ,
               s.TotalEuro ,
               s.DebtsD ,
               s.DebtsLL ,
               s.DebtsEuro ,
               s.TotalD - s.DebtsD ,
               s.TotalLL - s.DebtsLL ,
               s.TotalEuro - s.DebtsEuro 
             )
    WHEN MATCHED THEN
      UPDATE SET t.Gym_Count = s.CountIs ,
                  t.Gym_TotalD = s.TotalD ,
                  t.Gym_TotalLL = s.TotalLL ,
                  t.Gym_TotalEuro = s.TotalEuro ,
                  t.Gym_DebtsD = s.DebtsD ,
                  t.Gym_DebtsLL = s.DebtsLL ,
                  t.Gym_DebtsEuro = s.DebtsEuro ,
                  t.Gym_RealProfitD = s.TotalD - s.DebtsD ,
                  t.Gym_RealProfitLL = s.TotalLL - s.DebtsLL ,
                  t.Gym_RealProfitEuro = s.TotalEuro - s.DebtsEuro ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]();

  END;
  
  EXECUTE Invoices.s_ProfitDaily_Recalculation_PART @DateOnly;  
  
END;




