GO

CREATE PROCEDURE [Invoices].[s_ProfitDaily_Recalculation_PART] @DateOnly DATE
AS
BEGIN
   
  UPDATE Invoices.t_ProfitDaily
    SET DateMonthly = DATEFROMPARTS(YEAR(DateIs), MONTH(DateIs), 1) ,
        DateYearly = DATEFROMPARTS(YEAR(DateIs), 1, 1) ,
        Summary_TotalD = SalesSummary_TotalD + Gym_TotalD + Internet_TotalD + Electricity_TotalD + CarRental_TotalD + MoneyExchange_TotalD + License_ProfitD ,
        Summary_TotalLL = SalesSummary_TotalLL + Gym_TotalLL + Internet_TotalLL + Electricity_TotalLL + CarRental_TotalLL + MoneyExchange_TotalLL + License_ProfitLL ,
        Summary_TotalEuro = SalesSummary_TotalEuro + Gym_TotalEuro + Internet_TotalEuro + Electricity_TotalEuro + CarRental_TotalEuro + MoneyExchange_TotalEuro + License_ProfitEuro ,
        Summary_CostD = SalesSummary_CostD + Internet_CostD + CarRental_CostD + Expenses_TotalD + Salaries_TotalD ,
        Summary_CostLL = SalesSummary_CostLL + Internet_CostLL + CarRental_CostLL + Expenses_TotalLL + Salaries_TotalLL ,
        Summary_CostEuro = SalesSummary_CostEuro + Internet_CostEuro + CarRental_CostEuro + Expenses_TotalEuro + Salaries_TotalEuro ,
        Summary_DebtsD = SalesSummary_DebtsD + Gym_DebtsD + Internet_DebtsD + Electricity_DebtsD + CarRental_DebtsD ,
        Summary_DebtsLL = SalesSummary_DebtsLL + Gym_DebtsLL + Internet_DebtsLL + Electricity_DebtsLL + CarRental_DebtsLL ,
        Summary_DebtsEuro = SalesSummary_DebtsEuro + Gym_DebtsEuro + Internet_DebtsEuro + Electricity_DebtsEuro + CarRental_DebtsEuro
    WHERE DateIs = @DateOnly;

  UPDATE Invoices.t_ProfitDaily
    SET Summary_ProfitD = Summary_TotalD - Summary_CostD ,
        Summary_ProfitLL = Summary_TotalLL - Summary_CostLL ,
        Summary_ProfitEuro = Summary_TotalEuro - Summary_CostEuro ,
        Summary_RealProfitD = Summary_TotalD - Summary_CostD - Summary_DebtsD ,
        Summary_RealProfitLL = Summary_TotalLL - Summary_CostLL - Summary_DebtsLL ,
        Summary_RealProfitEuro = Summary_TotalEuro - Summary_CostEuro - Summary_DebtsEuro
    WHERE DateIs = @DateOnly;

  UPDATE Invoices.t_ProfitDaily
    SET SalesSummary_ProfitRate = Calculation.GetRate(SalesSummary_ProfitD, SalesSummary_TotalD) ,
        SalesSummary_ProfitRate_Cost = Calculation.GetRate(SalesSummary_ProfitD, SalesSummary_CostD) ,
        SalesSummary_RealProfitRate = Calculation.GetRate(SalesSummary_RealProfitD, SalesSummary_TotalD) ,
        SalesSummary_RealProfitRate_Cost = Calculation.GetRate(SalesSummary_RealProfitD, SalesSummary_CostD) ,
        Summary_ProfitRate = Calculation.GetRate(Summary_ProfitD, Summary_TotalD) ,
        Summary_ProfitRate_Cost = Calculation.GetRate(Summary_ProfitD, Summary_CostD) ,
        Summary_RealProfitRate = Calculation.GetRate(Summary_RealProfitD, Summary_TotalD) ,
        Summary_RealProfitRate_Cost = Calculation.GetRate(Summary_RealProfitD, Summary_CostD)
    WHERE DateIs = @DateOnly;
	
  EXECUTE Invoices.s_ProfitDaily_Clean_One_PART @DateOnly;
		  
  EXECUTE Invoices.s_ProfitDailyLiveVersion;

END;








