          DebtsD ,
          DebtsLL ,
          DebtsEuro
        )
      SELECT t.DateOnly ,
          COALESCE(SUM(t.TotalQuantity), 0) ,
          COUNT_BIG(t.ID) ,
          COALESCE(SUM(t.NetIsD - t.TaxValueD), 0) ,
          COALESCE(SUM(t.NetIsLL - t.TaxValueLL), 0) ,
