                  t.SaleInvoices_TotalLL = s.TotalLL ,
                  t.SaleInvoices_TotalEuro = s.TotalEuro ,
                  t.SaleInvoices_CostD = s.CostD ,
                  t.SaleInvoices_CostLL = s.CostLL ,
                  t.SaleInvoices_CostEuro = s.CostEuro ,
                  t.SaleInvoices_CommissionD = s.CommissionD ,
