SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_ProfitDaily_SalesReturnsInvoices_UpdateAll_PART]
AS
BEGIN
  
  BEGIN --Declare
	
    DECLARE @Profit AS TABLE
      (
        DateIs DATE NOT NULL ,
        Qtys FLOAT NULL ,
        CountIs BIGINT NULL ,
        TotalD FLOAT NULL ,
        TotalLL FLOAT NULL ,
        TotalEuro FLOAT NULL ,
        CostD FLOAT NULL ,
        CostLL FLOAT NULL ,
        CostEuro FLOAT NULL ,
        ProfitD FLOAT NULL ,
        ProfitLL FLOAT NULL ,
        ProfitEuro FLOAT NULL ,
        DebtsD FLOAT NULL ,
        DebtsLL FLOAT NULL ,
        DebtsEuro FLOAT NULL
      );
	  	
  END;

  BEGIN --Set info
	
    INSERT INTO @Profit
        ( DateIs ,
          Qtys ,
          CountIs ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          CostD ,
          CostLL ,
          CostEuro ,
          ProfitD ,
          ProfitLL ,
          ProfitEuro ,
          DebtsD ,
          DebtsLL ,
          DebtsEuro
        )
      SELECT t.DateOnly ,
          COALESCE(SUM(t.Qtys), 0) ,
          COUNT_BIG(t.ID) ,
          COALESCE(SUM(t.NetIsD - t.TaxValueD), 0) ,
          COALESCE(SUM(t.NetIsLL - t.TaxValueLL), 0) ,
          COALESCE(SUM(t.NetIsEuro - t.TaxValueEuro), 0) ,
          COALESCE(SUM(t.CostD), 0) ,
          COALESCE(SUM(t.CostLL), 0) ,
          COALESCE(SUM(t.CostEuro), 0) ,
          COALESCE(SUM(t.ProfitD), 0) ,
          COALESCE(SUM(t.ProfitLL), 0) ,
          COALESCE(SUM(t.ProfitEuro), 0) ,
          COALESCE(SUM(t.RestD), 0) ,
          COALESCE(SUM(t.RestLL), 0) ,
          COALESCE(SUM(t.RestEuro), 0)
        FROM Invoices.t_SoldReturn AS t
        GROUP BY t.DateOnly;
   
  END;
 
  BEGIN --Insert
	
    MERGE Invoices.t_ProfitDaily AS t
    USING @Profit AS s
    ON s.DateIs = t.DateIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( ID ,
               DateIs ,
               SalesReturnsInvoices_Qtys ,
               SalesReturnsInvoices_Count ,
               SalesReturnsInvoices_TotalD ,
               SalesReturnsInvoices_TotalLL ,
               SalesReturnsInvoices_TotalEuro ,
               SalesReturnsInvoices_CostD ,
               SalesReturnsInvoices_CostLL ,
               SalesReturnsInvoices_CostEuro ,
               SalesReturnsInvoices_ProfitD ,
               SalesReturnsInvoices_ProfitLL ,
               SalesReturnsInvoices_ProfitEuro ,
               SalesReturnsInvoices_DebtsD ,
               SalesReturnsInvoices_DebtsLL ,
               SalesReturnsInvoices_DebtsEuro ,
               SalesReturnsInvoices_RealProfitD ,
               SalesReturnsInvoices_RealProfitLL ,
               SalesReturnsInvoices_RealProfitEuro 
             )
      VALUES ( FORMAT(s.DateIs, N'yyyyMMdd-0000-0000-0000-000000000000') ,
               s.DateIs ,
               s.Qtys ,
               s.CountIs ,
               s.TotalD ,
               s.TotalLL ,
               s.TotalEuro ,
               s.CostD ,
               s.CostLL ,
               s.CostEuro ,
               s.ProfitD ,
               s.ProfitLL ,
               s.ProfitEuro ,
               s.DebtsD ,
               s.DebtsLL ,
               s.DebtsEuro ,
               s.ProfitD - s.DebtsD ,
               s.ProfitLL - s.DebtsLL ,
               s.ProfitEuro - s.DebtsEuro 
             )
    WHEN MATCHED THEN
      UPDATE SET t.SalesReturnsInvoices_Qtys = s.Qtys ,
                  t.SalesReturnsInvoices_Count = s.CountIs ,
                  t.SalesReturnsInvoices_TotalD = s.TotalD ,
                  t.SalesReturnsInvoices_TotalLL = s.TotalLL ,
                  t.SalesReturnsInvoices_TotalEuro = s.TotalEuro ,
                  t.SalesReturnsInvoices_CostD = s.CostD ,
                  t.SalesReturnsInvoices_CostLL = s.CostLL ,
                  t.SalesReturnsInvoices_CostEuro = s.CostEuro ,
                  t.SalesReturnsInvoices_ProfitD = s.ProfitD ,
                  t.SalesReturnsInvoices_ProfitLL = s.ProfitLL ,
                  t.SalesReturnsInvoices_ProfitEuro = s.ProfitEuro ,
                  t.SalesReturnsInvoices_DebtsD = s.DebtsD ,
                  t.SalesReturnsInvoices_DebtsLL = s.DebtsLL ,
                  t.SalesReturnsInvoices_DebtsEuro = s.DebtsEuro ,
                  t.SalesReturnsInvoices_RealProfitD = s.ProfitD - s.DebtsD ,
                  t.SalesReturnsInvoices_RealProfitLL = s.ProfitLL - s.DebtsLL ,
                  t.SalesReturnsInvoices_RealProfitEuro = s.ProfitEuro - s.DebtsEuro ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]()
    WHEN NOT MATCHED BY SOURCE THEN
      UPDATE SET t.SalesReturnsInvoices_Qtys = 0 ,
                  t.SalesReturnsInvoices_Count = 0 ,
                  t.SalesReturnsInvoices_TotalD = 0 ,
                  t.SalesReturnsInvoices_TotalLL = 0 ,
                  t.SalesReturnsInvoices_TotalEuro = 0 ,
                  t.SalesReturnsInvoices_CostD = 0 ,
                  t.SalesReturnsInvoices_CostLL = 0 ,
                  t.SalesReturnsInvoices_CostEuro = 0 ,
                  t.SalesReturnsInvoices_ProfitD = 0 ,
                  t.SalesReturnsInvoices_ProfitLL = 0 ,
                  t.SalesReturnsInvoices_ProfitEuro = 0 ,
                  t.SalesReturnsInvoices_DebtsD = 0 ,
                  t.SalesReturnsInvoices_DebtsLL = 0 ,
                  t.SalesReturnsInvoices_DebtsEuro = 0 ,
                  t.SalesReturnsInvoices_RealProfitD = 0 ,
                  t.SalesReturnsInvoices_RealProfitLL = 0 ,
                  t.SalesReturnsInvoices_RealProfitEuro = 0 ,
                  t.RowVersionID = [DateTimes].[f_GetRowVersionID]();

  END;
    
END;










