               s.DateIs ,
               s.Qtys ,
               s.CountIs ,
               s.TotalD ,
               s.TotalLL ,
               s.TotalEuro ,
               s.CostD ,
               s.CostLL ,
               s.CostEuro ,
               s.ProfitD ,
               s.ProfitLL ,
               s.ProfitEuro ,
               s.DebtsD ,
               s.DebtsLL ,
