/****** Object:  StoredProcedure [Invoices].[s_ProfitDaily_SalesSummary_Recalculation_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_ProfitDaily_SalesSummary_Recalculation_PART] @DateOnly DATE
AS
BEGIN
    
  UPDATE Invoices.t_ProfitDaily
    SET SalesSummary_Qtys = SaleInvoices_Qtys - SalesReturnsInvoices_Qtys ,
        SalesSummary_Count = SaleInvoices_Count - SalesReturnsInvoices_Count ,
        SalesSummary_TotalD = SaleInvoices_TotalD - SalesReturnsInvoices_TotalD ,
        SalesSummary_TotalLL = SaleInvoices_TotalLL - SalesReturnsInvoices_TotalLL ,
        SalesSummary_TotalEuro = SaleInvoices_TotalEuro - SalesReturnsInvoices_TotalEuro ,
        SalesSummary_CostD = SaleInvoices_CostD - SalesReturnsInvoices_CostD ,
        SalesSummary_CostLL = SaleInvoices_CostLL - SalesReturnsInvoices_CostLL ,
        SalesSummary_CostEuro = SaleInvoices_CostEuro - SalesReturnsInvoices_CostEuro ,
        SalesSummary_ProfitD = SaleInvoices_ProfitD - SaleInvoices_CommissionD - SalesReturnsInvoices_ProfitD ,
        SalesSummary_ProfitLL = SaleInvoices_ProfitLL - SaleInvoices_CommissionLL - SalesReturnsInvoices_ProfitLL ,
        SalesSummary_ProfitEuro = SaleInvoices_ProfitEuro - SaleInvoices_CommissionEuro - SalesReturnsInvoices_ProfitEuro ,
        SalesSummary_DebtsD = SaleInvoices_DebtsD - SalesReturnsInvoices_DebtsD ,
        SalesSummary_DebtsLL = SaleInvoices_DebtsLL - SalesReturnsInvoices_DebtsLL ,
        SalesSummary_DebtsEuro = SaleInvoices_DebtsEuro - SalesReturnsInvoices_DebtsEuro ,
        RowVersionID = [DateTimes].[f_GetRowVersionID]()
    WHERE DateIs = @DateOnly;

  UPDATE Invoices.t_ProfitDaily
    SET SalesSummary_RealProfitD = SalesSummary_ProfitD - SalesSummary_DebtsD ,
        SalesSummary_RealProfitLL = SalesSummary_ProfitLL - SalesSummary_DebtsLL ,
        SalesSummary_RealProfitEuro = SalesSummary_ProfitEuro - SalesSummary_DebtsEuro
    WHERE DateIs = @DateOnly; 

  EXECUTE Invoices.s_ProfitDaily_Recalculation_PART @DateOnly;  

END;




