    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

	TRUNCATE TABLE Invoices.t_ProfitDaily;

	EXECUTE Invoices.s_ProfitDaily_SaleInvoices_UpdateAll_PART;
	EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_UpdateAll_PART;
    EXECUTE Invoices.s_ProfitDaily_SalesSummary_RecalculationAll_PART;

	EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_UpdateAll_PART;
	EXECUTE Invoices.s_ProfitDaily_PurchaseReturnInvoices_UpdateAll_PART;
	EXECUTE Invoices.s_ProfitDaily_PurchasesSummary_RecalculationAll_PART;
	
	EXECUTE Invoices.s_ProfitDaily_Expenses_UpdateAll_PART;
	
	EXECUTE Invoices.s_ProfitDaily_LicenseProfit_UpdateAll_PART;

  	EXECUTE Invoices.s_ProfitDaily_Salaries_UpdateAll_PART;
  
  	EXECUTE Invoices.s_ProfitDaily_MoneyExchange_UpdateAll_PART;
  
  	EXECUTE Invoices.s_ProfitDaily_CarRental_UpdateAll_PART;
  
  	EXECUTE Invoices.s_ProfitDaily_Gym_UpdateAll_PART;
  
  	EXECUTE Invoices.s_ProfitDaily_Electricity_UpdateAll_PART;

  	EXECUTE Invoices.s_ProfitDaily_Internet_UpdateAll_PART;

    EXECUTE Invoices.s_ProfitDaily_RecalculationAll_PART; 
	 
    EXECUTE Invoices.s_ProfitDaily_Clean_All_PART;  
		
    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








