              ItemsCount = Invoices.f_PurchaseOrderArchiveGetItemsCountX(ID) ,
              ItemsNames = Invoices.f_PurchaseOrderArchiveGetItemsNamesX(ID) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_PurchaseOrderArchive.ID );

      END;

