GO

CREATE PROCEDURE [Invoices].[s_PurchaseOrderDelete] @ID UNIQUEIDENTIFIER ,
  @StageIs TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @PurchaseID UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Set
	    
      SELECT TOP ( 1 ) @PurchaseID = s.PurchaseID
        FROM Invoices.t_PurchaseOrder AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert t_PurchaseOrderArchive
	
      INSERT Invoices.t_PurchaseOrderArchive
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            PurchaseID ,
            PurchaseRef ,
            PurchaseRefF ,
            InvoiceTitleID ,
            InvoiceTitle ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            DeadlineDate ,
            DeadlineNotificationAR ,
            DeadlineNotificationEN ,
            ReceivingDate ,
            StageIs ,
            UserID ,
            UserIs ,
            AccountID ,
            Account ,
            AccountNumber ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Subtotal ,
            SubtotalF ,
            SubtotalD ,
            SubtotalLL ,
            SubtotalEuro ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            NontaxableAmount ,
            NontaxableAmountF ,
            NontaxableAmountD ,
            NontaxableAmountLL ,
            NontaxableAmountEuro ,
            TaxableAmount ,
            TaxableAmountF ,
            TaxableAmountD ,
            TaxableAmountLL ,
            TaxableAmountEuro ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            TaxesRate ,
            TaxesRateF ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TotalAR ,
            TotalEN ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            DescriptionIs ,
            ItemsQtys ,
            ItemsCount ,
            ItemsNames ,
            AnyItemHasDiscount ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.RefPaper ,
            IIF(@StageIs < 4, PurchaseID, N'00000000-0000-0000-0000-000000000000') ,
            IIF(@StageIs < 4, PurchaseRef, 0) ,
            IIF(@StageIs < 4, PurchaseRefF, N'0') ,
            t.InvoiceTitleID ,
            t.InvoiceTitle ,
            t.DateIs ,
            t.DateOnly ,
            t.DateMonthly ,
            t.DateYearly ,
            t.DeadlineDate ,
            t.DeadlineNotificationAR ,
            t.DeadlineNotificationEN ,
            t.ReceivingDate ,
            @StageIs ,
            t.UserID ,
            t.UserIs ,
            t.AccountID ,
            t.Account ,
            t.AccountNumber ,
            t.CurrencyID ,
            t.Currency ,
            t.ExchangeRate ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            t.TaxExchangeRateLL ,
            t.TaxExchangeRateEuro ,
            t.Subtotal ,
            t.SubtotalF ,
            t.SubtotalD ,
            t.SubtotalLL ,
            t.SubtotalEuro ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.NontaxableAmount ,
            t.NontaxableAmountF ,
            t.NontaxableAmountD ,
            t.NontaxableAmountLL ,
            t.NontaxableAmountEuro ,
            t.TaxableAmount ,
            t.TaxableAmountF ,
            t.TaxableAmountD ,
            t.TaxableAmountLL ,
            t.TaxableAmountEuro ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.TotalAR ,
            t.TotalEN ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.DescriptionIs ,
            t.ItemsQtys ,
            t.ItemsCount ,
            t.ItemsNames ,
            t.AnyItemHasDiscount ,
            t.DateCreate ,
            t.WorkStationID
          FROM Invoices.t_PurchaseOrder AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Insert t_PurchaseOrderArchiveDetail
	
      INSERT Invoices.t_PurchaseOrderArchiveDetail
          ( ID ,
            PurchaseOrderArchiveID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnit ,
            Qtys ,
            UnitCost ,
            UnitCostF ,
            UnitCostD ,
            UnitCostLL ,
            UnitCostEuro ,
            DiscountRate ,
            DiscountRateF ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            InvoiceDiscount ,
            InvoiceDiscountF ,
            InvoiceDiscountD ,
            InvoiceDiscountLL ,
            InvoiceDiscountEuro ,
            SubTotal2 ,
            SubTotal2F ,
            SubTotal2D ,
            SubTotal2LL ,
            SubTotal2Euro ,
            TaxesRate ,
            TaxesRateF ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            TotalSalePrice ,
            TotalSalePriceF ,
            TotalSalePriceD ,
            TotalSalePriceLL ,
            TotalSalePriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            DescriptionIs ,
            SortAt ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.PurchaseOrderID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.PackUnitID ,
            t.PackUnitQty ,
            t.PackQtys ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.InvoiceDiscount ,
            t.InvoiceDiscountF ,
            t.InvoiceDiscountD ,
            t.InvoiceDiscountLL ,
            t.InvoiceDiscountEuro ,
            t.SubTotal2 ,
            t.SubTotal2F ,
            t.SubTotal2D ,
            t.SubTotal2LL ,
            t.SubTotal2Euro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.TotalSalePrice ,
            t.TotalSalePriceF ,
            t.TotalSalePriceD ,
            t.TotalSalePriceLL ,
            t.TotalSalePriceEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.DescriptionIs ,
            t.SortAt ,
            t.DateCreate ,
            t.WorkStationID
          FROM Invoices.t_PurchaseOrderDetail AS t
          WHERE t.PurchaseOrderID = @ID;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'purchaseOrder' );
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            0 ,
            'purchaseOrderDetail'
          FROM Invoices.t_PurchaseOrderDetail AS t
          WHERE t.PurchaseOrderID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Invoices.t_PurchaseOrderDetail
        WHERE PurchaseOrderID = @ID;

      DELETE FROM Invoices.t_PurchaseOrder
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_PurchaseOrderMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchaseOrderMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @StageIs >= 4
    BEGIN
               
      UPDATE Invoices.t_Purchasing
        SET LinkType = 0 ,
            LinkID = Alls.f_GetEmptyGuid() ,
            LinkRef = 0 ,
            LinkRefF = N'0'
        WHERE ID = @PurchaseID;      

    END;

    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    EXECUTE Items.s_ItemSharedRebuildPurchaseOrderQuantityPART;
    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    EXECUTE Invoices.s_PurchaseOrderLiveVersion;
    EXECUTE Invoices.s_PurchaseOrderArchiveLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    ROLLBACK;

