/****** Object:  StoredProcedure [Invoices].[s_PurchaseOrderExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchaseOrderExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Invoices_PurchaseOrder < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_PurchaseOrder
        SET DeadlineNotificationAR = Invoices.f_PurchaseOrderGetDeadlineNotificationARX(DeadlineDate) ,
            DeadlineNotificationEN = Invoices.f_PurchaseOrderGetDeadlineNotificationENX(DeadlineDate);

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Invoices_PurchaseOrder = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;













