  @SalePriceD FLOAT ,
  @SalePriceLL FLOAT ,
  @SalePriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @ProfitRate FLOAT ,
  @ProfitRateF NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsQtys FLOAT ,
  @ItemsCount FLOAT ,
  @ItemsNames NVARCHAR(MAX) ,
  @AnyItemHasDiscount BIT ,
  @PurchaseOrderDetail Invoices.tt_PurchaseOrderDetail READONLY ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Invoices.f_PurchaseOrderGetNewRef() ,
        @RefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @DateMonthly DATE = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
        @DateYearly DATE = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
        @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @return INT = 0;

    END;

    BEGIN --Set info
	
      SET @RefF = FORMAT(@Ref, '#');
	  
    END;

    BEGIN --Insert t_PurchaseOrder

      INSERT INTO Invoices.t_PurchaseOrder
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            InvoiceTitleID ,
            InvoiceTitle ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            DeadlineDate ,
            DeadlineNotificationAR ,
            DeadlineNotificationEN ,
            ReceivingDate ,
            StageIs ,
            UserID ,
            UserIs ,
            AccountID ,
            Account ,
            AccountNumber ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Subtotal ,
            SubtotalF ,
            SubtotalD ,
            SubtotalLL ,
            SubtotalEuro ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            NontaxableAmount ,
            NontaxableAmountF ,
            NontaxableAmountD ,
            NontaxableAmountLL ,
            NontaxableAmountEuro ,
            TaxableAmount ,
            TaxableAmountF ,
            TaxableAmountD ,
            TaxableAmountLL ,
            TaxableAmountEuro ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            TaxesRate ,
            TaxesRateF ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TotalAR ,
            TotalEN ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            DescriptionIs ,
            ItemsQtys ,
            ItemsCount ,
            ItemsNames ,
            AnyItemHasDiscount
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @RefPaper ,
            @InvoiceTitleID ,
            @InvoiceTitle ,
            @DateIs ,
            @DateOnly ,
            @DateMonthly ,
            @DateYearly ,
            @DeadlineDate ,
            @DeadlineNotificationAR ,
            @DeadlineNotificationEN ,
            @ReceivingDate ,
            @StageIs ,
            @UserID ,
            @UserIs ,
            @AccountID ,
            @Account ,
            @AccountNumber ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @TaxExchangeRateLL ,
            @TaxExchangeRateEuro ,
            @Subtotal ,
            @SubtotalF ,
            @SubtotalD ,
            @SubtotalLL ,
            @SubtotalEuro ,
            @Discount ,
            @DiscountF ,
            @DiscountD ,
            @DiscountLL ,
            @DiscountEuro ,
            @NontaxableAmount ,
            @NontaxableAmountF ,
            @NontaxableAmountD ,
            @NontaxableAmountLL ,
            @NontaxableAmountEuro ,
            @TaxableAmount ,
            @TaxableAmountF ,
            @TaxableAmountD ,
            @TaxableAmountLL ,
            @TaxableAmountEuro ,
            @Taxes ,
            @TaxesF ,
            @TaxesD ,
            @TaxesLL ,
            @TaxesEuro ,
            @TaxesRate ,
            @TaxesRateF ,
            @Total ,
            @TotalF ,
            @TotalD ,
            @TotalLL ,
            @TotalEuro ,
            @TotalAR ,
            @TotalEN ,
            @SalePrice ,
            @SalePriceF ,
            @SalePriceD ,
            @SalePriceLL ,
            @SalePriceEuro ,
            @Profit ,
            @ProfitF ,
            @ProfitD ,
            @ProfitLL ,
            @ProfitEuro ,
            @ProfitRate ,
            @ProfitRateF ,
            @DescriptionIs ,
            @ItemsQtys ,
            @ItemsCount ,
            @ItemsNames ,
            @AnyItemHasDiscount
          );

    END;

    BEGIN --Insert t_PurchaseOrderDetail

      INSERT INTO Invoices.t_PurchaseOrderDetail
          ( ID ,
            PurchaseOrderID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnit ,
            Qtys ,
            UnitCost ,
            UnitCostF ,
            UnitCostD ,
            UnitCostLL ,
            UnitCostEuro ,
            DiscountRate ,
            DiscountRateF ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            InvoiceDiscount ,
            InvoiceDiscountF ,
            InvoiceDiscountD ,
            InvoiceDiscountLL ,
            InvoiceDiscountEuro ,
            SubTotal2 ,
            SubTotal2F ,
            SubTotal2D ,
            SubTotal2LL ,
            SubTotal2Euro ,
            TaxesRate ,
            TaxesRateF ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            TotalSalePrice ,
            TotalSalePriceF ,
            TotalSalePriceD ,
            TotalSalePriceLL ,
            TotalSalePriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            DescriptionIs ,
            SortAt 
          )
        SELECT t.ID ,
            t.PurchaseOrderID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.PackUnitID ,
            t.PackUnitQty ,
            t.PackQtys ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.InvoiceDiscount ,
            t.InvoiceDiscountF ,
            t.InvoiceDiscountD ,
            t.InvoiceDiscountLL ,
            t.InvoiceDiscountEuro ,
            t.SubTotal2 ,
            t.SubTotal2F ,
            t.SubTotal2D ,
            t.SubTotal2LL ,
            t.SubTotal2Euro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.TotalSalePrice ,
            t.TotalSalePriceF ,
            t.TotalSalePriceD ,
            t.TotalSalePriceLL ,
            t.TotalSalePriceEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.DescriptionIs ,
            t.SortAt
          FROM @PurchaseOrderDetail AS t;

    END;

    BEGIN --Insert t_PurchaseOrderMoving

      SET @return = -1;

      INSERT INTO Invoices.t_PurchaseOrderMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + @RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    EXECUTE Items.s_ItemSharedRebuildPurchaseOrderQuantityPART;
    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    EXECUTE Invoices.s_PurchaseOrderLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;




