BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding Statistics

      IF @RebuildColumn = 'All'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET RefF = FORMAT(Ref, '#') ,
              InvoiceTitle = Invoices.f_InvoiceTitleGetName(InvoiceTitleID) ,
              UserIs = Users.f_UserGetName(UserID) ,
              DeadlineNotificationAR = Invoices.f_PurchaseOrderGetDeadlineNotificationARX(DeadlineDate) ,
              DeadlineNotificationEN = Invoices.f_PurchaseOrderGetDeadlineNotificationENX(DeadlineDate) ,
              Account = Company.f_AccountGetName(AccountID) ,
              Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalAR = Currencys.f_ToWordAR(Total, CurrencyID, 1) ,
              TotalEN = Currencys.f_ToWordEN(Total, CurrencyID, 1) ,
              SalePriceF = Currencys.f_Format(CurrencyID, SalePrice) ,
              ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              ItemsQtys = Invoices.f_PurchaseOrderGetItemsQtysX(ID) ,
              ItemsCount = Invoices.f_PurchaseOrderGetItemsCountX(ID) ,
              ItemsNames = Invoices.f_PurchaseOrderGetItemsNamesX(ID) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'Ref'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET RefF = FORMAT(Ref, '#') ,
              DeadlineNotificationAR = Invoices.f_PurchaseOrderGetDeadlineNotificationARX(DeadlineDate) ,
              DeadlineNotificationEN = Invoices.f_PurchaseOrderGetDeadlineNotificationENX(DeadlineDate) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'Invoice Title'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET InvoiceTitle = Invoices.f_InvoiceTitleGetName(InvoiceTitleID) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'User'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET UserIs = Users.f_UserGetName(UserID) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'Account'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET Account = Company.f_AccountGetName(AccountID) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'Currency'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalAR = Currencys.f_ToWordAR(Total, CurrencyID, 1) ,
              TotalEN = Currencys.f_ToWordEN(Total, CurrencyID, 1) ,
              SalePriceF = Currencys.f_Format(CurrencyID, SalePrice) ,
              ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              IsSync = 0;

      END;

      IF @RebuildColumn = 'Items'
      BEGIN

        UPDATE Invoices.t_PurchaseOrder
          SET ItemsQtys = Invoices.f_PurchaseOrderGetItemsQtysX(ID) ,
              ItemsCount = Invoices.f_PurchaseOrderGetItemsCountX(ID) ,
              ItemsNames = Invoices.f_PurchaseOrderGetItemsNamesX(ID) ,
              IsSync = 0;

      END;

    END;

    BEGIN --Insert t_PurchaseOrderMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchaseOrderMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
 
    EXECUTE Invoices.[s_PurchaseOrderLiveVersion];

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








