/****** Object:  StoredProcedure [Invoices].[s_PurchaseOrderUnsavedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PurchaseOrderUnsavedMerge] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @PCName NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @Discount FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @PurchaseOrderUnsavedDetail Invoices.tt_PurchaseOrderUnsavedDetail READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Merge t_PurchaseOrderUnsaved

      MERGE Invoices.t_PurchaseOrderUnsaved AS t
      USING
        ( SELECT @ID AS ID
        ) AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 UserID ,
                 PCName ,
                 CurrencyID ,
                 ExchangeRate ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 TaxExchangeRateLL ,
                 TaxExchangeRateEuro ,
                 Discount ,
                 TotalF ,
                 ItemsCount
               )
        VALUES ( @ID ,
                 @UserID ,
                 @PCName ,
                 @CurrencyID ,
                 @ExchangeRate ,
                 @ExchangeRateLL ,
                 @ExchangeRateEuro ,
                 @TaxExchangeRateLL ,
                 @TaxExchangeRateEuro ,
                 @Discount ,
                 @TotalF ,
                 @ItemsCount
          
               )
      WHEN MATCHED THEN
        UPDATE SET t.DateIs = GETDATE() ,
                    t.UserID = @UserID ,
                    t.PCName = @PCName ,
                    t.CurrencyID = @CurrencyID ,
                    t.ExchangeRateLL = @ExchangeRateLL ,
                    t.ExchangeRateEuro = @ExchangeRateEuro ,
                    t.TaxExchangeRateLL = @TaxExchangeRateLL ,
                    t.TaxExchangeRateEuro = @TaxExchangeRateEuro ,
                    t.Discount = @Discount ,
                    t.TotalF = @TotalF ,
                    t.ItemsCount = @ItemsCount;

    END;

    BEGIN --Reinsert t_PurchaseOrderUnsavedDetail
	
      DELETE FROM Invoices.t_PurchaseOrderUnsavedDetail
        WHERE PurchaseOrderUnsavedID = @ID;

      INSERT Invoices.t_PurchaseOrderUnsavedDetail
          ( ID ,
            PurchaseOrderUnsavedID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            Qty ,
            UnitCost ,
            UnitCostF ,
            DiscountRate ,
            Discount ,
            InvoiceDiscount ,
            TaxesRate ,
            Taxes ,
            TotalF ,
            SalePrice ,
            DescriptionIs ,
            SortAt 
	      )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.WarehouseID ,
            s.ItemUnitID ,
            s.Qty ,
            s.UnitCost ,
            s.UnitCostF ,
            s.DiscountRate ,
            s.Discount ,
            s.InvoiceDiscount ,
            s.TaxesRate ,
            s.Taxes ,
            s.TotalF ,
            s.SalePrice ,
            s.DescriptionIs ,
            s.SortAt
          FROM @PurchaseOrderUnsavedDetail AS s;

    END;

    EXECUTE Invoices.s_PurchaseOrderUnsavedLiveVersion;
    EXECUTE Invoices.s_PurchaseOrderUnsavedDetailLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;






GO
