CREATE PROCEDURE [Invoices].[s_PurchaseOrderUpdate] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @InvoiceTitleID UNIQUEIDENTIFIER ,
  @InvoiceTitle NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @DeadlineDate DATE ,
  @DeadlineNotificationAR NVARCHAR(MAX) ,
  @DeadlineNotificationEN NVARCHAR(MAX) ,
  @ReceivingDate DATE ,
  @StageIs TINYINT ,
  @AccountID UNIQUEIDENTIFIER ,
  @Account NVARCHAR(MAX) ,
  @AccountNumber NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @Subtotal FLOAT ,
  @SubtotalF NVARCHAR(MAX) ,
  @SubtotalD FLOAT ,
  @SubtotalLL FLOAT ,
  @SubtotalEuro FLOAT ,
  @Discount FLOAT ,
  @DiscountF NVARCHAR(MAX) ,
  @DiscountD FLOAT ,
  @DiscountLL FLOAT ,
  @DiscountEuro FLOAT ,
  @NontaxableAmount FLOAT ,
  @NontaxableAmountF NVARCHAR(MAX) ,
  @NontaxableAmountD FLOAT ,
  @NontaxableAmountLL FLOAT ,
  @NontaxableAmountEuro FLOAT ,
  @TaxableAmount FLOAT ,
  @TaxableAmountF NVARCHAR(MAX) ,
  @TaxableAmountD FLOAT ,
  @TaxableAmountLL FLOAT ,
  @TaxableAmountEuro FLOAT ,
  @Taxes FLOAT ,
  @TaxesF NVARCHAR(MAX) ,
  @TaxesD FLOAT ,
  @TaxesLL FLOAT ,
  @TaxesEuro FLOAT ,
  @TaxesRate FLOAT ,
  @TaxesRateF NVARCHAR(MAX) ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @SalePrice FLOAT ,
  @SalePriceF NVARCHAR(MAX) ,
  @SalePriceD FLOAT ,
  @SalePriceLL FLOAT ,
  @SalePriceEuro FLOAT ,
  @Profit FLOAT ,
  @ProfitF NVARCHAR(MAX) ,
  @ProfitD FLOAT ,
  @ProfitLL FLOAT ,
  @ProfitEuro FLOAT ,
  @ProfitRate FLOAT ,
  @ProfitRateF NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsQtys FLOAT ,
  @ItemsCount FLOAT ,
  @ItemsNames NVARCHAR(MAX) ,
  @AnyItemHasDiscount BIT ,
  @PurchaseOrderDetail Invoices.tt_PurchaseOrderDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @DateOnly DATE = @DateIs ,
        @DateMonthly DATE = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
        @DateYearly DATE = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
        @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @Return INT = 0;

    END;

    BEGIN --Update t_PurchaseOrder

      UPDATE Invoices.t_PurchaseOrder
        SET RefPaper = @RefPaper ,
            InvoiceTitleID = @InvoiceTitleID ,
            InvoiceTitle = @InvoiceTitle ,
            DateIs = @DateIs ,
            DateOnly = @DateOnly ,
            DateMonthly = @DateMonthly ,
            DateYearly = @DateYearly ,
            DeadlineDate = @DeadlineDate ,
            DeadlineNotificationAR = @DeadlineNotificationAR ,
            DeadlineNotificationEN = @DeadlineNotificationEN ,
            ReceivingDate = @ReceivingDate ,
            StageIs = @StageIs ,
            AccountID = @AccountID ,
            Account = @Account ,
            AccountNumber = @AccountNumber ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            TaxExchangeRateLL = @TaxExchangeRateLL ,
            TaxExchangeRateEuro = @TaxExchangeRateEuro ,
            Subtotal = @Subtotal ,
            SubtotalF = @SubtotalF ,
            SubtotalD = @SubtotalD ,
            SubtotalLL = @SubtotalLL ,
            SubtotalEuro = @SubtotalEuro ,
            Discount = @Discount ,
            DiscountF = @DiscountF ,
            DiscountD = @DiscountD ,
            DiscountLL = @DiscountLL ,
            DiscountEuro = @DiscountEuro ,
            NontaxableAmount = @NontaxableAmount ,
            NontaxableAmountF = @NontaxableAmountF ,
            NontaxableAmountD = @NontaxableAmountD ,
            NontaxableAmountLL = @NontaxableAmountLL ,
            NontaxableAmountEuro = @NontaxableAmountEuro ,
            TaxableAmount = @TaxableAmount ,
            TaxableAmountF = @TaxableAmountF ,
            TaxableAmountD = @TaxableAmountD ,
            TaxableAmountLL = @TaxableAmountLL ,
            TaxableAmountEuro = @TaxableAmountEuro ,
            Taxes = @Taxes ,
            TaxesF = @TaxesF ,
            TaxesD = @TaxesD ,
            TaxesLL = @TaxesLL ,
            TaxesEuro = @TaxesEuro ,
            TaxesRate = @TaxesRate ,
            TaxesRateF = @TaxesRateF ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            TotalAR = @TotalAR ,
            TotalEN = @TotalEN ,
            SalePrice = @SalePrice ,
            SalePriceF = @SalePriceF ,
            SalePriceD = @SalePriceD ,
            SalePriceLL = @SalePriceLL ,
            SalePriceEuro = @SalePriceEuro ,
            Profit = @Profit ,
            ProfitF = @ProfitF ,
            ProfitD = @ProfitD ,
            ProfitLL = @ProfitLL ,
            ProfitEuro = @ProfitEuro ,
            ProfitRate = @ProfitRate ,
            ProfitRateF = @ProfitRateF ,
            DescriptionIs = @DescriptionIs ,
            ItemsQtys = @ItemsQtys ,
            ItemsCount = @ItemsCount ,
            ItemsNames = @ItemsNames ,
            AnyItemHasDiscount = @AnyItemHasDiscount ,
            IsSync = 0
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            0 ,
            'purchaseOrderDetail'
          FROM Invoices.t_PurchaseOrderDetail AS t
          WHERE t.PurchaseOrderID = @ID
        EXCEPT
        SELECT t.ID ,
            0 ,
            'purchaseOrderDetail'
          FROM @PurchaseOrderDetail AS t;

    END;
  
    BEGIN --Delete t_PurchaseOrderDetail

      DELETE FROM Invoices.t_PurchaseOrderDetail
        WHERE PurchaseOrderID = @ID;

    END;
    
    BEGIN --Insert t_PurchaseOrderDetail
		
      INSERT INTO Invoices.t_PurchaseOrderDetail
          ( ID ,
            PurchaseOrderID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnit ,
            Qtys ,
            UnitCost ,
            UnitCostF ,
            UnitCostD ,
            UnitCostLL ,
            UnitCostEuro ,
            DiscountRate ,
            DiscountRateF ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            InvoiceDiscount ,
            InvoiceDiscountF ,
            InvoiceDiscountD ,
            InvoiceDiscountLL ,
            InvoiceDiscountEuro ,
            SubTotal2 ,
            SubTotal2F ,
            SubTotal2D ,
            SubTotal2LL ,
            SubTotal2Euro ,
            TaxesRate ,
            TaxesRateF ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            TotalSalePrice ,
            TotalSalePriceF ,
            TotalSalePriceD ,
            TotalSalePriceLL ,
            TotalSalePriceEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            DescriptionIs ,
            SortAt 
          )
        SELECT t.ID ,
            t.PurchaseOrderID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.PackUnitID ,
            t.PackUnitQty ,
            t.PackQtys ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.InvoiceDiscount ,
            t.InvoiceDiscountF ,
            t.InvoiceDiscountD ,
            t.InvoiceDiscountLL ,
            t.InvoiceDiscountEuro ,
            t.SubTotal2 ,
            t.SubTotal2F ,
            t.SubTotal2D ,
            t.SubTotal2LL ,
            t.SubTotal2Euro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.TotalSalePrice ,
            t.TotalSalePriceF ,
            t.TotalSalePriceD ,
            t.TotalSalePriceLL ,
            t.TotalSalePriceEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.DescriptionIs ,
            t.SortAt
          FROM @PurchaseOrderDetail AS t;

    END;

    BEGIN --Insert t_PurchaseOrderMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchaseOrderMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    EXECUTE Items.s_ItemSharedRebuildPurchaseOrderQuantityPART;
    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    EXECUTE Invoices.s_PurchaseOrderLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;




