/****** Object:  StoredProcedure [Invoices].[s_PurchasingDebtRedistribution]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingDebtRedistribution] @IDs AS Alls.tt_Guid READONLY ,
  @drs AS Invoices.tt_FixPaidUp READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    BEGIN --Update t_Purchasing
  
      UPDATE Invoices.t_Purchasing
        SET PaidUp = NetIs ,
            PaidUpF = NetIsF ,
            PaidUpD = NetIsD ,
            PaidUpLL = NetIsLL ,
            PaidUpEuro = NetIsEuro ,
            Rest = 0 ,
            RestF = Currencys.f_Format(CurrencyID, 0) ,
            RestD = 0 ,
            RestLL = 0 ,
            RestEuro = 0 ,
            Paid = 2 
        WHERE EXISTS ( SELECT TOP(1) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Purchasing.AccountVendorID );

    END;
 
    BEGIN --Merge t_Purchasing

      MERGE Invoices.t_Purchasing AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUp = s.PaidUp ,
                    t.PaidUpF = Currencys.f_Format(t.CurrencyID, s.PaidUp) ,
                    t.PaidUpD = s.PaidUp / t.ExchangeRate ,
                    t.Rest = t.NetIs - s.PaidUp ,
                    t.RestF = Currencys.f_Format(t.CurrencyID, t.NetIs - s.PaidUp) ,
                    t.RestD = ( t.NetIs - s.PaidUp ) / t.ExchangeRate;

      MERGE Invoices.t_Purchasing AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUpLL = t.PaidUpD * t.ExchangeRateLL ,
                    t.PaidUpEuro = t.PaidUpD * t.ExchangeRateEuro ,
                    t.RestLL = t.RestD * t.ExchangeRateLL ,
                    t.RestEuro = t.RestD * t.ExchangeRateEuro ,
                    t.Paid = IIF(t.PaidUp = 0 AND t.NetIs > 0, 0, IIF(t.Rest > 0, 1, 2));
 
    END;

    BEGIN --Insert t_PurchasingMoving

      SET @return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventText ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @drs AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



