          )
        SELECT t.ID ,
            t.PurchasingID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.DiscountIs ,
            t.DiscountIsF ,
            t.DiscountIsValue ,
            t.DiscountIsValueF ,
            t.DiscountIsValueD ,
            t.DiscountIsValueLL ,
            t.DiscountIsValueEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.DiscountInvoice ,
            t.DiscountInvoiceF ,
            t.DiscountInvoiceD ,
            t.DiscountInvoiceLL ,
            t.DiscountInvoiceEuro ,
            t.FutureDiscountRate ,
            t.FutureDiscountRateF ,
            t.FutureUnitDiscount ,
            t.FutureUnitDiscountF ,
            t.FutureUnitDiscountD ,
