            t.FutureTotalDiscount ,
            t.FutureTotalDiscountF ,
            t.FutureTotalDiscountD ,
            t.FutureTotalDiscountLL ,
            t.FutureTotalDiscountEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Sell ,
            t.SellF ,
            t.SellD ,
            t.SellLL ,
            t.SellEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.ProfitTotal ,
            t.ProfitTotalF ,
            t.ProfitTotalD ,
            t.ProfitTotalLL ,
            t.ProfitTotalEuro ,
            t.UnitExpenses ,
            t.UnitExpensesF ,
            t.UnitExpensesD ,
            t.UnitExpensesLL ,
            t.UnitExpensesEuro ,
            t.InvoiceExpenses ,
            t.InvoiceExpensesF ,
            t.InvoiceExpensesD ,
            t.InvoiceExpensesLL ,
            t.InvoiceExpensesEuro ,
            t.FinalUnitCost ,
            t.FinalUnitCostF ,
            t.FinalUnitCostD ,
            t.FinalUnitCostLL ,
            t.FinalUnitCostEuro ,
            t.TotalFinalCost ,
            t.TotalFinalCostF ,
            t.TotalFinalCostD ,
            t.TotalFinalCostLL ,
            t.TotalFinalCostEuro ,
            t.DescriptionIs ,
            t.SortAt ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Invoices.t_PurchasingDetail AS t
          WHERE t.PurchasingID = @ID;

    END;

    EXECUTE Invoices.s_PurchasingDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      DELETE FROM Invoices.t_PurchasingDetailSerial
        WHERE PurchasingID = @ID;

      DELETE FROM Items.t_ItemSerial
        WHERE SectionType = 0 AND LinkID = @ID;

      DELETE FROM Invoices.t_PurchasingDetail
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          0 - Deleted.Qtys
          INTO @ItemQtys
        WHERE PurchasingID = @ID;

      DELETE FROM Invoices.t_Purchasing
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 0 AND LinkID = @ID;

    END;

    BEGIN--Item Qtys

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET PurchasingC -= 1 ,
            PurchasingTotal = [Invoices].[f_PurchasingGetTotalByAccountVendorID](ID) ,
            PurchasingProfit = [Invoices].[f_PurchasingGetProfitByAccountVendorID](ID) ,
            PurchasingLast = [Invoices].f_PurchasingGetLastDateByAccountVendorID(ID)
        WHERE ID = @VendorID;

      UPDATE Company.t_Account
        SET PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
            PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit)
        WHERE ID = @VendorID;
		  
    END;

    BEGIN --Insert t_PurchasingMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Delete t_Expense
    EXECUTE Invoices.s_PurchasingDeleteExpensePART @ID;
	
    IF @LinkType = 1
    BEGIN
	          
      EXECUTE Invoices.s_PurchaseOrderUpdatePurchasedPART @LinkID, 0, N'00000000-0000-0000-0000-000000000000', 0, N'0';
		              
    END;
	
    EXECUTE Currencys.s_SchedulePaymentsDeleteBySourcePART @ID, 2;
   
    EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateIs;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













