/****** Object:  StoredProcedure [Invoices].[s_PurchasingDeleteExpensePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingDeleteExpensePART] @PurchasingID UNIQUEIDENTIFIER
AS
BEGIN
    
  BEGIN --Declare
	  
    DECLARE @IDs AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );  

  END;

  BEGIN --Set Info
	    
    INSERT INTO @IDs
        ( ID
        )
      SELECT s.ID
        FROM Company.t_Expense AS s
        WHERE LinkID = @PurchasingID AND LinkedType = 0;

  END;

  BEGIN --Delete t_Expense

    DELETE FROM Company.t_Expense
      WHERE LinkID = @PurchasingID AND LinkedType = 0;

  END;

  BEGIN --Delete t_Transaction
    
    DELETE FROM Transactions.t_Transaction
      WHERE LinkType = 8 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                        FROM @IDs AS s
                                        WHERE s.ID = t_Transaction.LinkID );

  END;

END;

