/****** Object:  StoredProcedure [Invoices].[s_PurchasingFixPaidUp]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingFixPaidUp] @drs AS Invoices.tt_FixPaidUp READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateIs_OLD DateTimes.tt_DateOnly;

      DECLARE @return INT = 0;

    END;

    BEGIN --Set
     
      INSERT INTO @DateIs_OLD
          ( DateOnly
          )
        SELECT DISTINCT s1.DateOnly
          FROM @drs AS s
          INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.ID;

    END;

    BEGIN --Merge

      MERGE Invoices.t_Purchasing AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUp = s.PaidUp ,
                    t.PaidUpF = Currencys.f_Format(t.CurrencyID, s.PaidUp) ,
                    t.PaidUpD = s.PaidUp / t.ExchangeRate ,
                    t.Rest = t.NetIs - s.PaidUp ,
                    t.RestF = Currencys.f_Format(t.CurrencyID, t.NetIs - s.PaidUp) ,
                    t.RestD = ( t.NetIs - s.PaidUp ) / t.ExchangeRate ,
                    t.IsSync = 0;

      MERGE Invoices.t_Purchasing AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUpLL = t.PaidUpD * t.ExchangeRateLL ,
                    t.PaidUpEuro = t.PaidUpD * t.ExchangeRateEuro ,
                    t.RestLL = t.RestD * t.ExchangeRateLL ,
                    t.RestEuro = t.RestD * t.ExchangeRateEuro ,
                    t.Paid = IIF(t.PaidUp = 0 AND t.NetIs > 0, 0, IIF(t.Rest > 0, 1, 2));

    END;
 
    BEGIN --Insert t_PurchasingMoving

      SET @return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventText ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @drs AS s;

    END;

    EXECUTE Items.s_PurchasingLiveVersion;
  
    EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Updates_PART @DateIs_OLD;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;














GO
