  @Paid TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Invoices.tt_PurchasingDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @StatementIs NVARCHAR(MAX) ,
  @ExpensesTable Company.tt_Expenses READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @LegalRef BIGINT = 0 ,
        @LegalRefF NVARCHAR(MAX)= N'' ,
        @AnyRef BIGINT ,
        @AnyRefF NVARCHAR(MAX) ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @RowNumber INT ,
        @Vendor NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @TransactionLinkType INT = 0 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @StatementIs_ NVARCHAR(MAX) ,
        @NetD FLOAT ,
        @Profit FLOAT ,
        @ProfitD FLOAT ,
        @SecondPaymentExchangeRate FLOAT = Currencys.f_ChooseValue(@SecondPaymentCurrencyID, 1, @ExchangeRateLL, @ExchangeRateEuro) ,
        @return INT;

    END;

    BEGIN --Set Info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_Purchasing AS s;
      SET @RefF = FORMAT(@Ref, '#');

      SET @AnyRef = @Ref;
      SET @AnyRefF = @RefF;

      IF @Legal = 1
      BEGIN

        SELECT @LegalRef = ISNULL(MAX(s.LegalRef), 0) + 1
          FROM Invoices.t_Purchasing AS s
          WHERE s.Legal = 1;
        SET @LegalRefF = FORMAT(@LegalRef, '#');	  

        SET @AnyRef = @LegalRef;
        SET @AnyRefF = N'|' + @LegalRefF;

      END;

      SET @Vendor = Company.f_AccountGetName(@VendorID);
      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);
      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

      IF @CurrencyTypeIs <> 0
      BEGIN

        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      SET @NetD = @NetIs / @ExchangeRate;
      SELECT @Profit = COALESCE(SUM(s.ProfitTotal), 0)
        FROM @DetailIs AS s;
      SET @ProfitD = @Profit / @ExchangeRate;

    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Invoices.t_Purchasing
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            LinkType ,
            LinkID ,
            LinkRef ,
            LinkRefF ,
            Legal ,
            LegalRef ,
            LegalRefF ,
            InvoiceTitleID ,
            InvoiceTitle ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            UserID ,
            UserIs ,
            AccountVendorID ,
            AccountVendor ,
            AccountVendorNumber ,
            ContactPerson ,
            AccountBoxID ,
            AccountBox ,
            AccountBoxNumber ,
            PaymentMethod ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Total ,
            DiscountIs ,
            TaxValue ,
            NetIs ,
            Profit ,
            Expenses ,
            ExpensesF ,
            ExpensesD ,
            ExpensesLL ,
            ExpensesEuro ,
            ExpensesTaxRate ,
            ExpensesTaxRateF ,
            ExpensesTax ,
            ExpensesTaxF ,
            ExpensesTaxD ,
            ExpensesTaxLL ,
            ExpensesTaxEuro ,
            ExpensesWithTax ,
            ExpensesWithTaxF ,
            ExpensesWithTaxD ,
            ExpensesWithTaxLL ,
            ExpensesWithTaxEuro ,
            Sell ,
            Qtys ,
            DescriptionIs ,
            FirstPayment ,
            SecondPaymentCurrencyID ,
            SecondPaymentCurrency ,
            SecondPayment ,
            SecondPaymentF ,
            SecondPaymentD ,
            SecondPaymentLL ,
            SecondPaymentEuro ,
            SecondPaymentAccountBoxID ,
            SecondPaymentAccountBox ,
            SecondPaymentAccountBoxNumber ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            WePaidD ,
            WePaidLL ,
            WePaidEuro ,
            WeReceivedD ,
            WeReceivedLL ,
            WeReceivedEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @RefPaper ,
            @LinkType ,
            @LinkID ,
            @LinkRef ,
            @LinkRefF ,
            @Legal ,
            @LegalRef ,
            @LegalRefF ,
            @InvoiceTitleID ,
            Invoices.f_InvoiceTitleGetName(@InvoiceTitleID) ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @VendorID ,
            @Vendor ,
            Company.f_AccountGetNumberF(@VendorID) ,
            @ContactPerson ,
            @BoxID ,
            Company.f_AccountGetName(@BoxID) ,
            Company.f_AccountGetNumberF(@BoxID) ,
            @PaymentMethod ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @TaxExchangeRateLL ,
            @TaxExchangeRateEuro ,
            ( SELECT COALESCE(SUM(s.SubTotal), 0)
                FROM @DetailIs AS s
            ) ,
            @DiscountIs ,
            @Tax ,
            ( SELECT COALESCE(SUM(s.Total), 0)
                FROM @DetailIs AS s
            ) ,
            @Profit ,
            @Expenses ,
            @ExpensesF ,
            @ExpensesD ,
            @ExpensesLL ,
            @ExpensesEuro ,
            @ExpensesTaxRate ,
            @ExpensesTaxRateF ,
            @ExpensesTax ,
            @ExpensesTaxF ,
            @ExpensesTaxD ,
            @ExpensesTaxLL ,
            @ExpensesTaxEuro ,
            @ExpensesWithTax ,
            @ExpensesWithTaxF ,
            @ExpensesWithTaxD ,
            @ExpensesWithTaxLL ,
            @ExpensesWithTaxEuro ,
            ( SELECT COALESCE(SUM(s.Sell * s.Qtys), 0)
                FROM @DetailIs AS s
            ) ,
            ( SELECT COALESCE(SUM(s.Qtys), 0)
                FROM @DetailIs AS s
            ) ,
            @DescriptionIs ,
            @FirstPayment ,
            @SecondPaymentCurrencyID ,
            @SecondPaymentCurrency ,
            @SecondPayment ,
            @SecondPaymentF ,
            @SecondPaymentD ,
            @SecondPaymentLL ,
            @SecondPaymentEuro ,
            @SecondPaymentAccountBoxID ,
            @SecondPaymentAccountBox ,
            @SecondPaymentAccountBoxNumber ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @WePaidD ,
            @WePaidLL ,
            @WePaidEuro ,
            @WeReceivedD ,
            @WeReceivedLL ,
            @WeReceivedEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @Paid
          );

    END;

    BEGIN --Insert t_PurchasingDetail

      INSERT INTO Invoices.t_PurchasingDetail
          ( ID ,
            PurchasingID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            DiscountInvoice ,
            DiscountInvoiceF ,
            DiscountInvoiceD ,
            DiscountInvoiceLL ,
            DiscountInvoiceEuro ,
            FutureDiscountRate ,
            FutureDiscountRateF ,
            FutureUnitDiscount ,
            FutureUnitDiscountF ,
            FutureUnitDiscountD ,
            FutureUnitDiscountLL ,
            FutureUnitDiscountEuro ,
            FutureTotalDiscount ,
            FutureTotalDiscountF ,
            FutureTotalDiscountD ,
            FutureTotalDiscountLL ,
            FutureTotalDiscountEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Sell ,
            SellF ,
            SellD ,
            SellLL ,
            SellEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitTotal ,
            ProfitTotalF ,
            ProfitTotalD ,
            ProfitTotalLL ,
            ProfitTotalEuro ,
            ExpenseCalculated ,
            FixedExpense ,
            UnitExpenses ,
            UnitExpensesF ,
            UnitExpensesD ,
            UnitExpensesLL ,
            UnitExpensesEuro ,
            InvoiceExpenses ,
            InvoiceExpensesF ,
            InvoiceExpensesD ,
            InvoiceExpensesLL ,
            InvoiceExpensesEuro ,
            FinalUnitCost ,
            FinalUnitCostF ,
            FinalUnitCostD ,
            FinalUnitCostLL ,
            FinalUnitCostEuro ,
            TotalFinalCost ,
            TotalFinalCostF ,
            TotalFinalCostD ,
            TotalFinalCostLL ,
            TotalFinalCostEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.PackUnitID ,
            s.PackUnitQty ,
            s.PackQtys ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qty * s1.Qty ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountIs ,
            Currencys.f_FormatRate(s.DiscountIs) ,
            s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
            s.DiscountIsValue / @ExchangeRate ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
            ( s.Price * s.Qty ) - s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, ( s.Price * s.Qty ) - s.DiscountIsValue) ,
            ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ,
            ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateLL ,
            ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountInvoice ,
            Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
            s.DiscountInvoice / @ExchangeRate ,
            ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
            s.FutureDiscountRate ,
            s.FutureDiscountRateF ,
            s.FutureUnitDiscount ,
            s.FutureUnitDiscountF ,
            s.FutureUnitDiscountD ,
            s.FutureUnitDiscountLL ,
            s.FutureUnitDiscountEuro ,
            s.FutureTotalDiscount ,
            s.FutureTotalDiscountF ,
            s.FutureTotalDiscountD ,
            s.FutureTotalDiscountLL ,
            s.FutureTotalDiscountEuro ,
            s.TaxRate ,
            Currencys.f_FormatRate(s.TaxRate) ,
            s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.TaxValue) ,
            s.TaxValue / @ExchangeRate ,
            ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Sell ,
            Currencys.f_Format(@CurrencyID, s.Sell) ,
            s.Sell / @ExchangeRate ,
            ( s.Sell / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Sell / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Profit ,
            Currencys.f_Format(@CurrencyID, s.Profit) ,
            s.Profit / @ExchangeRate ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Profit * s.Qty ,
            Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
            ( s.Profit * s.Qty ) / @ExchangeRate ,
            ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateLL ,
            ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.ExpenseCalculated ,
            s.FixedExpense ,
            Calculation.Division(s.InvoiceExpenses, s.Qty) ,
            Currencys.f_Format(@CurrencyID, Calculation.Division(s.InvoiceExpenses, s.Qty)) ,
            Calculation.Division(s.InvoiceExpensesD, s.Qty) ,
            Calculation.Division(s.InvoiceExpensesLL, s.Qty) ,
            Calculation.Division(s.InvoiceExpensesEuro, s.Qty) ,
            s.InvoiceExpenses ,
            s.InvoiceExpensesF ,
            s.InvoiceExpensesD ,
            s.InvoiceExpensesLL ,
            s.InvoiceExpensesEuro ,
            Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) ,
            Currencys.f_Format(@CurrencyID, Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty)) ,
            Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ,
            ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateLL ,
            ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total + s.InvoiceExpenses - s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.Total + s.InvoiceExpenses - s.TaxValue) ,
            ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ,
            ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateLL ,
            ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            0 ,
            @ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_PurchasingDetailSerial

      INSERT INTO Invoices.t_PurchasingDetailSerial
          ( PurchasingID ,
            PurchasingDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    EXECUTE Invoices.s_PurchasingDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_PurchasingDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Update t_Purchasing

      SET @return = 0;

      UPDATE Invoices.t_Purchasing
        SET TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalD = Total / ExchangeRate ,
            TotalLL = ( Total / ExchangeRate ) * @ExchangeRateLL ,
            TotalEuro = ( Total / ExchangeRate ) * @ExchangeRateEuro ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            DiscountIsD = DiscountIs / ExchangeRate ,
            DiscountIsLL = ( DiscountIs / ExchangeRate ) * @ExchangeRateLL ,
            DiscountIsEuro = ( DiscountIs / ExchangeRate ) * @ExchangeRateEuro ,
            TaxRate = Calculation.GetRate(TaxValue, NetIs - TaxValue) ,
            TaxRateF = Calculation.GetRateF(TaxValue, NetIs - TaxValue) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            TaxValueD = TaxValue / ExchangeRate ,
            TaxValueLL = ( TaxValue / ExchangeRate ) * @TaxExchangeRateLL ,
            TaxValueEuro = ( TaxValue / ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsD = NetIs / ExchangeRate ,
            NetIsLL = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateLL ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            NetIsEuro = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateEuro ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            ProfitD = Profit / ExchangeRate ,
            ProfitLL = ( Profit / ExchangeRate ) * @ExchangeRateLL ,
            ProfitEuro = ( Profit / ExchangeRate ) * @ExchangeRateEuro ,
            SellF = Currencys.f_Format(CurrencyID, Sell) ,
            SellD = Sell / ExchangeRate ,
            SellLL = ( Sell / ExchangeRate ) * @ExchangeRateLL ,
            SellEuro = ( Sell / ExchangeRate ) * @ExchangeRateEuro ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            FirstPaymentD = FirstPayment / ExchangeRate ,
            FirstPaymentLL = ( FirstPayment / ExchangeRate ) * @ExchangeRateLL ,
            FirstPaymentEuro = ( FirstPayment / ExchangeRate ) * @ExchangeRateEuro ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM @DetailIs AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM @DetailIs AS s
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END
        WHERE ID = @ID;

    END;
      	
    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    DECLARE @NumberIs BIGINT = Company.f_AccountGetNumber(@VendorID);
    IF @NumberIs <> 4010100001 AND @NumberIs <> 4110100001
    BEGIN --Insert last price

      DECLARE @DetailIsDistinct AS TABLE
        (
          ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
          ItemUnityID UNIQUEIDENTIFIER NOT NULL ,
          Price FLOAT NOT NULL ,
          DiscountIs DECIMAL(5, 2) NOT NULL
        );

      DECLARE @DistinctIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      INSERT INTO @DistinctIDs
          ( ID
          )
        SELECT MIN(s.ID)
          FROM @DetailIs AS s
          WHERE s.Price <> 0
          GROUP BY s.ItemUnityID;

      INSERT INTO @DetailIsDistinct
          ( ItemSharedID ,
            ItemUnityID ,
            Price ,
            DiscountIs
          )
        SELECT o1.ItemSharedID ,
            o1.ItemUnityID ,
            o1.Price ,
            o1.DiscountIs
          FROM @DistinctIDs AS o
          INNER JOIN @DetailIs AS o1 ON o1.ID = o.ID;

      MERGE Company.t_AccountItemPrice AS t
      USING @DetailIsDistinct AS s
      ON s.ItemUnityID = t.ItemUnityID AND t.AccountID = @VendorID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( AccountID ,
                 ItemSharedID ,
                 ItemUnityID ,
                 Unity ,
                 CurrencyID ,
                 Currency ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 DiscountIs ,
                 DiscountIsF
               )
        VALUES ( @VendorID ,
                 s.ItemSharedID ,
                 s.ItemUnityID ,
                 Items.f_UnityItemGetName(s.ItemUnityID) ,
                 @CurrencyID ,
                 @Currency ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs)
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = @CurrencyID ,
                    t.Currency = @Currency ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs);

    END;

    BEGIN --Insert t_PurchasingMoving

      SET @return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + @AnyRefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    --IF @Net > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @TransactionLinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @NetIs;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @Tax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        IF @NetNonTaxable > 0
        BEGIN --Insert detail 

          SET @V = @NetNonTaxable;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountIDPurchaseNonTaxable, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;

        IF @Tax > 0
        BEGIN --Insert detail tax

          SET @V = @NetTaxableWithoutTax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountIDPurchaseTaxable, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Tax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;

      END;

    END;

    IF @PaidUp <> 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'PV';

      END;

      BEGIN --Insert t_Transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'PV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @TransactionLinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert t_TransactionDetail

        IF ( @PaidUp >= @NetIs AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @PaidUp <= @NetIs - @Tax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          IF @FirstPayment <> 0
          BEGIN

            SET @V = @FirstPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          END;

          IF @SecondPayment <> 0
          BEGIN

            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @VendorID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;
        ELSE
        BEGIN

          IF @FirstPayment <> 0
          BEGIN

            SET @V = @FirstPayment - @Tax;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @V = @FirstPayment - @V;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

          END;

          IF @SecondPayment <> 0
          BEGIN

            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 5, @TransactionID, @VendorID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 6, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;

      END;

    END;

	--Expenses
    EXECUTE Company.s_ExpenseInsertsPART 0, @ID, @RefF, @ExpensesTable, @UserID, @Event, @ComputerIP, @Computer, @ComputerAccount;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix t_Transaction

      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET PurchasingC += 1 ,
            PurchasingTotal = CASE CurrencyTypeIs
                                WHEN 0 THEN @NetD
                                WHEN 1 THEN @NetD * @ExchangeRateLL
                                ELSE @NetD * @ExchangeRateEuro
                              END ,
            PurchasingProfit = CASE CurrencyTypeIs
                                 WHEN 0 THEN @ProfitD
                                 WHEN 1 THEN @ProfitD * @ExchangeRateLL
                                 ELSE @ProfitD * @ExchangeRateEuro
                               END ,
            PurchasingLast = [Invoices].f_PurchasingGetLastDateByAccountVendorID(ID)
        WHERE ID = @VendorID;

      UPDATE Company.t_Account
        SET PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
            PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit)
        WHERE ID = @VendorID;

    END;

    IF @LinkType = 1
    BEGIN

      EXECUTE Invoices.s_PurchaseOrderUpdatePurchasedPART @LinkID, 3, @ID, @Ref, @RefF;
      EXECUTE Invoices.s_PurchaseOrderUpdatesPurchasedPART @LinkIDs, 3, @ID, @Ref, @RefF;

    END;

    EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateIs;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










