/****** Object:  StoredProcedure [Invoices].[s_PurchasingPaidUpDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingPaidUpDelete] @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventTransaction NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @DateOnly_OLD DATE ,
        @CurrencyID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @PaidUp FLOAT ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly ,
          @CurrencyID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_Purchasing AS s
        WHERE s.ID = @ID;
	    
      SELECT @PaidUpD = ISNULL(SUM(s.BalanceD), 0) ,
          @PaidUpLL = ISNULL(SUM(s.BalanceLL), 0) ,
          @PaidUpEuro = ISNULL(SUM(s.BalanceEuro), 0)
        FROM Transactions.t_TransactionDetail AS s
        WHERE s.TransactionID = @TransactionID AND s.Balance > 0;

      SET @PaidUp = Currencys.f_ChooseValue(@CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro);
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;

    END;

    BEGIN --Update t_Purchasing

      UPDATE Invoices.t_Purchasing
        SET PaidUp -= @PaidUp ,
            PaidUpD -= @PaidUpD ,
            PaidUpLL -= @PaidUpLL ,
            PaidUpEuro -= @PaidUpEuro
        WHERE ID = @ID;
	    
      UPDATE Invoices.t_Purchasing
        SET PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            Rest = Total - PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Total - PaidUp) ,
            RestD = TotalD - PaidUpD ,
            RestLL = TotalLL - PaidUpLL ,
            RestEuro = TotalEuro - PaidUpEuro
        WHERE ID = @ID;  

      UPDATE Invoices.t_Purchasing
        SET Paid = Invoices.f_PurchasingGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;  
	    
    END;
 
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE ID = @TransactionID;

    END;
	
    SET @return = -1;
    EXECUTE Invoices.s_PurchasingMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
    EXECUTE Transactions. s_TransactionMovingInsertPART @TransactionID, @UserID, @EventTransaction, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_PurchasingLiveVersion;
	EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateOnly_OLD;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingPaidUpNew]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingPaidUpNew] @ID UNIQUEIDENTIFIER ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @SchedulePaymentsID UNIQUEIDENTIFIER ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_OLD DATE ,
        @PaidUp FLOAT ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @return INT = 0;
		
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_Purchasing AS s
        WHERE s.ID = @ID;
   
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
      
    END;

    BEGIN --Update t_Purchasing

      UPDATE Invoices.t_Purchasing
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpLL ,
            PaidUpEuro += @PaidUpEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpLL ,
            RestEuro -= @PaidUpEuro
        WHERE ID = @ID;

      UPDATE Invoices.t_Purchasing
        SET Rest = IIF(Rest < 0, 0, Rest) ,
            RestF = Currencys.f_Format(CurrencyID, IIF(Rest < 0, 0, Rest)) ,
            RestD = IIF(RestD < 0, 0, RestD) ,
            RestLL = IIF(RestLL < 0, 0, RestLL) ,
            RestEuro = IIF(RestEuro < 0, 0, RestEuro)
        WHERE ID = @ID;

      UPDATE Invoices.t_Purchasing
        SET Paid = Invoices.f_PurchasingGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;
		
    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;
	
    SET @return = -1;
    EXECUTE Invoices.s_PurchasingMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_PurchasingLiveVersion;
	
    EXECUTE Currencys.s_SchedulePaymentsDeletePART @SchedulePaymentsID;
 
    EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateOnly_OLD;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingRebuildExpenses]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingRebuildExpenses]
AS
BEGIN;
  BEGIN TRY
    BEGIN TRANSACTION;
 
    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    DISABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

    BEGIN --Update t_Purchasing
  
      UPDATE Invoices.t_Purchasing
        SET ExpensesD = ( SELECT ISNULL(SUM(s.BalanceD), 0)
                            FROM Company.t_Expense AS s
                            WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                        ) ,
            ExpensesLL = ( SELECT ISNULL(SUM(s.BalanceLL), 0)
                            FROM Company.t_Expense AS s
                            WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                         ) ,
            ExpensesEuro = ( SELECT ISNULL(SUM(s.BalanceEuro), 0)
                              FROM Company.t_Expense AS s
                              WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                           ) ,
            ExpensesTaxD = ( SELECT ISNULL(SUM(s.TaxValueD), 0)
                              FROM Company.t_Expense AS s
                              WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                           ) ,
            ExpensesTaxLL = ( SELECT ISNULL(SUM(s.TaxValueLL), 0)
                                FROM Company.t_Expense AS s
                                WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                            ) ,
            ExpensesTaxEuro = ( SELECT ISNULL(SUM(s.TaxValueEuro), 0)
                                  FROM Company.t_Expense AS s
                                  WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                              ) ,
            ExpensesWithTaxD = ( SELECT ISNULL(SUM(s.NetIsD), 0)
                                  FROM Company.t_Expense AS s
                                  WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                               ) ,
            ExpensesWithTaxLL = ( SELECT ISNULL(SUM(s.NetIsLL), 0)
                                    FROM Company.t_Expense AS s
                                    WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                                ) ,
            ExpensesWithTaxEuro = ( SELECT ISNULL(SUM(s.NetIsEuro), 0)
                                      FROM Company.t_Expense AS s
                                      WHERE s.LinkedType = 0 AND s.LinkID = t_Purchasing.ID
                                  );

      UPDATE Invoices.t_Purchasing
        SET Expenses = Currencys.f_ChooseValue(CurrencyID, ExpensesD, ExpensesLL, ExpensesEuro) ,
            ExpensesTax = Currencys.f_ChooseValue(CurrencyID, ExpensesTaxD, ExpensesTaxLL, ExpensesTaxEuro) ,
            ExpensesWithTax = Currencys.f_ChooseValue(CurrencyID, ExpensesWithTaxD, ExpensesWithTaxLL, ExpensesWithTaxEuro);

      UPDATE Invoices.t_Purchasing
        SET ExpensesF = Currencys.f_Format(CurrencyID, Expenses) ,
            ExpensesTaxRate = Calculation.GetRate(ExpensesTax, Expenses) ,
            ExpensesTaxRateF = Currencys.f_FormatRate(Calculation.GetRate(ExpensesTax, Expenses)) ,
            ExpensesTaxF = Currencys.f_Format(CurrencyID, ExpensesTax) ,
            ExpensesWithTaxF = Currencys.f_Format(CurrencyID, ExpensesWithTax);
 
    END;
 
    BEGIN --Update t_PurchasingDetail
  
      WITH  o AS ( SELECT s.InvoiceExpenses ,
                      s.InvoiceExpensesF ,
                      s.InvoiceExpensesD ,
                      s.InvoiceExpensesLL ,
                      s.InvoiceExpensesEuro ,
                      Calculation.Division(s1.Expenses, 100.0) * Calculation.Division(s.SubTotal - s.DiscountInvoice, s1.Total - s1.DiscountIs) * 100.0 AS InvoiceExpenses_ ,
                      Calculation.Division(s1.ExpensesD, 100.0) * Calculation.Division(s.SubTotalD - s.DiscountInvoiceD, s1.TotalD - s1.DiscountIsD) * 100.0 AS InvoiceExpensesD_ ,
                      Calculation.Division(s1.ExpensesLL, 100.0) * Calculation.Division(s.SubTotalLL - s.DiscountInvoiceLL, s1.TotalLL - s1.DiscountIsLL) * 100.0 AS InvoiceExpensesLL_ ,
                      Calculation.Division(s1.ExpensesEuro, 100.0) * Calculation.Division(s.SubTotalEuro - s.DiscountInvoiceEuro, s1.TotalEuro - s1.DiscountIsEuro) * 100.0 AS InvoiceExpensesEuro_
                    FROM Invoices.t_PurchasingDetail AS s
                    INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
                 )
        UPDATE o
          SET o.InvoiceExpenses = o.InvoiceExpenses_ ,
              o.InvoiceExpensesD = o.InvoiceExpensesD_ ,
              o.InvoiceExpensesLL = o.InvoiceExpensesLL_ ,
              o.InvoiceExpensesEuro = o.InvoiceExpensesEuro_;
   
      UPDATE Invoices.t_PurchasingDetail
        SET UnitExpenses = Calculation.Division(InvoiceExpenses, Qty) ,
            UnitExpensesD = Calculation.Division(InvoiceExpensesD, Qty) ,
            UnitExpensesLL = Calculation.Division(InvoiceExpensesLL, Qty) ,
            UnitExpensesEuro = Calculation.Division(InvoiceExpensesEuro, Qty) ,
            FinalUnitCost = Calculation.Division(Total + InvoiceExpenses, Qty) ,
            FinalUnitCostD = Calculation.Division(TotalD + InvoiceExpensesD, Qty) ,
            FinalUnitCostLL = Calculation.Division(TotalLL + InvoiceExpensesLL, Qty) ,
            FinalUnitCostEuro = Calculation.Division(TotalEuro + InvoiceExpensesEuro, Qty) ,
            TotalFinalCost = Total + InvoiceExpenses ,
            TotalFinalCostD = TotalD + InvoiceExpensesD ,
            TotalFinalCostLL = TotalLL + InvoiceExpensesLL ,
            TotalFinalCostEuro = TotalEuro + InvoiceExpensesEuro;
  
      WITH  o AS ( SELECT s.UnitExpenses ,
                      s.UnitExpensesF ,
                      s.InvoiceExpenses ,
                      s.InvoiceExpensesF ,
                      s.FinalUnitCost ,
                      s.FinalUnitCostF ,
                      s.TotalFinalCost ,
                      s.TotalFinalCostF ,
                      s1.CurrencyID
                    FROM Invoices.t_PurchasingDetail AS s
                    INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
                 )
        UPDATE o
          SET o.UnitExpensesF = Currencys.f_Format(o.CurrencyID, o.UnitExpenses) ,
              o.InvoiceExpensesF = Currencys.f_Format(o.CurrencyID, o.InvoiceExpenses) ,
              o.FinalUnitCostF = Currencys.f_Format(o.CurrencyID, o.FinalUnitCost) ,
              o.TotalFinalCostF = Currencys.f_Format(o.CurrencyID, o.TotalFinalCost);

    END;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Purchase, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
  
    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

    RETURN 0;

  END CATCH;

END;



