/****** Object:  StoredProcedure [Invoices].[s_PurchasingRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    DISABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Invoices.t_Purchasing
        SET RefF = FORMAT(Ref, '#') ,
            UserIs = Users.f_UserGetName(UserID) ,
            AccountVendor = Company.f_AccountGetName(AccountVendorID) ,
            AccountBox = Company.f_AccountGetName(AccountBoxID) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            ExpensesF = Currencys.f_Format(CurrencyID, Expenses) ,
            ExpensesTaxRateF = Currencys.f_FormatRate(ExpensesTaxRate) ,
            ExpensesTaxF = Currencys.f_Format(CurrencyID, ExpensesTax) ,
            ExpensesWithTaxF = Currencys.f_Format(CurrencyID, ExpensesWithTax) ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            RestF = Currencys.f_Format(CurrencyID, Rest) ,
            SellF = Currencys.f_Format(CurrencyID, Sell) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_PurchasingDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.PurchasingID = t_Purchasing.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM Invoices.t_PurchasingDetail AS s
                                        WHERE s.PurchasingID = t_Purchasing.ID
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END;

      UPDATE Invoices.t_Purchasing
        SET TaxRateF = Currencys.f_FormatRate(( TaxValue / ( NetIs - TaxValue ) ) * 100.0)
        WHERE NetIs > 0;

      WITH  o AS ( SELECT s.Price ,
                      s.PriceF ,
                      s.DiscountIs ,
                      s.DiscountIsF ,
                      s.DiscountIsValue ,
                      s.DiscountIsValueF ,
                      s.SubTotal ,
                      s.SubTotalF ,
                      s.DiscountInvoice ,
                      s.DiscountInvoiceF ,
                      s.FutureDiscountRate ,
                      s.FutureDiscountRateF ,
                      s.FutureUnitDiscount ,
                      s.FutureUnitDiscountF ,
                      s.FutureTotalDiscount ,
                      s.FutureTotalDiscountF ,
                      s.TaxRate ,
                      s.TaxRateF ,
                      s.TaxValue ,
                      s.Total ,
                      s.TotalF ,
                      s.Sell ,
                      s.SellF ,
                      s.Profit ,
                      s.ProfitF ,
                      s.ProfitTotal ,
                      s.ProfitTotalF ,
                      s.UnitExpenses ,
                      s.UnitExpensesF ,
                      s.InvoiceExpenses ,
                      s.InvoiceExpensesF ,
                      s.FinalUnitCost ,
                      s.FinalUnitCostF ,
                      s.TotalFinalCost ,
                      s.TotalFinalCostF ,
                      s1.CurrencyID ,
                      s.Qty ,
                      s.Qtys ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Invoices.t_PurchasingDetail AS s
                    LEFT JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.PurchasingID
                    LEFT JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    LEFT JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE o
          SET o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
              o.DiscountIsF = Currencys.f_FormatRate(o.DiscountIs) ,
              o.DiscountIsValueF = Currencys.f_Format(o.CurrencyID, o.DiscountIsValue) ,
              o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
              o.DiscountInvoiceF = Currencys.f_Format(o.CurrencyID, o.DiscountInvoice) ,
              o.FutureDiscountRateF = Currencys.f_FormatRate(o.FutureDiscountRate) ,
              o.FutureUnitDiscountF = Currencys.f_Format(o.CurrencyID, o.FutureUnitDiscount) ,
              o.FutureTotalDiscountF = Currencys.f_Format(o.CurrencyID, o.FutureTotalDiscount) ,
              o.TaxRateF = Currencys.f_FormatRate(o.TaxRate) ,
              o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
              o.SellF = Currencys.f_Format(o.CurrencyID, o.Sell) ,
              o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
              o.ProfitTotalF = Currencys.f_Format(o.CurrencyID, o.ProfitTotal) ,
              o.UnitExpensesF = Currencys.f_Format(o.CurrencyID, o.UnitExpenses) ,
              o.InvoiceExpensesF = Currencys.f_Format(o.CurrencyID, o.InvoiceExpenses) ,
              o.FinalUnitCostF = Currencys.f_Format(o.CurrencyID, o.FinalUnitCost) ,
              o.TotalFinalCostF = Currencys.f_Format(o.CurrencyID, o.TotalFinalCost) ,
              o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;
 
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Purchase, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingRecalculateExpensesPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingRecalculateExpensesPART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @CurrencyID UNIQUEIDENTIFIER ,
      @Subtotal FLOAT ,
      @SubtotalD FLOAT ,
      @SubtotalLL FLOAT ,
      @SubtotalEuro FLOAT ,
      @Expenses FLOAT ,
      @ExpensesD FLOAT ,
      @ExpensesLL FLOAT ,
      @ExpensesEuro FLOAT ,
      @ExpensesTax FLOAT ,
      @ExpensesTaxRate FLOAT ,
      @ExpensesTaxD FLOAT ,
      @ExpensesTaxLL FLOAT ,
      @ExpensesTaxEuro FLOAT ,
      @ExpensesWithTax FLOAT ,
      @ExpensesWithTaxD FLOAT ,
      @ExpensesWithTaxLL FLOAT ,
      @ExpensesWithTaxEuro FLOAT;

  END;

  BEGIN --Set Info

    SELECT @CurrencyID = s.CurrencyID ,
        @Subtotal = s.Total - s.DiscountIs ,
        @SubtotalD = s.TotalD - s.DiscountIsD ,
        @SubtotalLL = s.TotalLL - s.DiscountIsLL ,
        @SubtotalEuro = s.TotalEuro - s.DiscountIsEuro
      FROM Invoices.t_Purchasing AS s
      WHERE s.ID = @ID;

    SELECT @Expenses = ISNULL(SUM(Currencys.f_ChooseValue(@CurrencyID, s.BalanceD, s.BalanceLL, s.BalanceEuro)), 0) ,
        @ExpensesD = ISNULL(SUM(s.BalanceD), 0) ,
        @ExpensesLL = ISNULL(SUM(s.BalanceLL), 0) ,
        @ExpensesEuro = ISNULL(SUM(s.BalanceEuro), 0) ,
        @ExpensesTax = ISNULL(SUM(Currencys.f_ChooseValue(@CurrencyID, s.TaxValueD, s.TaxValueLL, s.TaxValueEuro)), 0) ,
        @ExpensesTaxD = ISNULL(SUM(s.TaxValueD), 0) ,
        @ExpensesTaxLL = ISNULL(SUM(s.TaxValueLL), 0) ,
        @ExpensesTaxEuro = ISNULL(SUM(s.TaxValueEuro), 0) ,
        @ExpensesWithTax = ISNULL(SUM(Currencys.f_ChooseValue(@CurrencyID, s.NetIsD, s.NetIsLL, s.NetIsEuro)), 0) ,
        @ExpensesWithTaxD = ISNULL(SUM(s.NetIsD), 0) ,
        @ExpensesWithTaxLL = ISNULL(SUM(s.NetIsLL), 0) ,
        @ExpensesWithTaxEuro = ISNULL(SUM(s.NetIsEuro), 0)
      FROM Company.t_Expense AS s
      WHERE s.LinkedType = 0 AND s.LinkID = @ID;

    SET @ExpensesTaxRate = Calculation.GetRate(@ExpensesTax, @Expenses);

  END;
  
  DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
  DISABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

  BEGIN --Update t_Purchasing
  
    UPDATE Invoices.t_Purchasing
      SET Expenses = @Expenses ,
          ExpensesF = Currencys.f_Format(CurrencyID, @Expenses) ,
          ExpensesD = @ExpensesD ,
          ExpensesLL = @ExpensesLL ,
          ExpensesEuro = @ExpensesEuro ,
          ExpensesTaxRate = @ExpensesTaxRate ,
          ExpensesTaxRateF = Currencys.f_FormatRate(@ExpensesTaxRate) ,
          ExpensesTax = @ExpensesTax ,
          ExpensesTaxF = Currencys.f_Format(CurrencyID, @ExpensesTax) ,
          ExpensesTaxD = @ExpensesTaxD ,
          ExpensesTaxLL = @ExpensesTaxLL ,
          ExpensesTaxEuro = @ExpensesTaxEuro ,
          ExpensesWithTax = @ExpensesWithTax ,
          ExpensesWithTaxF = Currencys.f_Format(CurrencyID, @ExpensesWithTax) ,
          ExpensesWithTaxD = @ExpensesWithTaxD ,
          ExpensesWithTaxLL = @ExpensesWithTaxLL ,
          ExpensesWithTaxEuro = @ExpensesWithTaxEuro
      WHERE ID = @ID;
 
  END;
 
  BEGIN --Update t_PurchasingDetail
  
    UPDATE Invoices.t_PurchasingDetail
      SET InvoiceExpenses = Calculation.Division(@Expenses, 100.0) * Calculation.Division(SubTotal - DiscountInvoice, @Subtotal) * 100.0 ,
          InvoiceExpensesD = Calculation.Division(@ExpensesD, 100.0) * Calculation.Division(SubTotalD - DiscountInvoiceD, @SubtotalD) * 100.0 ,
          InvoiceExpensesLL = Calculation.Division(@ExpensesLL, 100.0) * Calculation.Division(SubTotalLL - DiscountInvoiceLL, @SubtotalLL) * 100.0 ,
          InvoiceExpensesEuro = Calculation.Division(@ExpensesEuro, 100.0) * Calculation.Division(SubTotalEuro - DiscountInvoiceEuro, @SubtotalEuro) * 100.0
      WHERE PurchasingID = @ID;
   
    UPDATE Invoices.t_PurchasingDetail
      SET UnitExpenses = Calculation.Division(InvoiceExpenses, Qty) ,
          UnitExpensesD = Calculation.Division(InvoiceExpensesD, Qty) ,
          UnitExpensesLL = Calculation.Division(InvoiceExpensesLL, Qty) ,
          UnitExpensesEuro = Calculation.Division(InvoiceExpensesEuro, Qty) ,
          FinalUnitCost = Calculation.Division(Total + InvoiceExpenses, Qty) ,
          FinalUnitCostD = Calculation.Division(TotalD + InvoiceExpensesD, Qty) ,
          FinalUnitCostLL = Calculation.Division(TotalLL + InvoiceExpensesLL, Qty) ,
          FinalUnitCostEuro = Calculation.Division(TotalEuro + InvoiceExpensesEuro, Qty) ,
          TotalFinalCost = Total + InvoiceExpenses ,
          TotalFinalCostD = TotalD + InvoiceExpensesD ,
          TotalFinalCostLL = TotalLL + InvoiceExpensesLL ,
          TotalFinalCostEuro = TotalEuro + InvoiceExpensesEuro
      WHERE PurchasingID = @ID;
  
    UPDATE Invoices.t_PurchasingDetail
      SET UnitExpensesF = Currencys.f_Format(@CurrencyID, UnitExpenses) ,
          InvoiceExpensesF = Currencys.f_Format(@CurrencyID, InvoiceExpenses) ,
          FinalUnitCostF = Currencys.f_Format(@CurrencyID, FinalUnitCost) ,
          TotalFinalCostF = Currencys.f_Format(@CurrencyID, TotalFinalCost)
      WHERE PurchasingID = @ID;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, Purchase, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

  ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
  ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;

  RETURN 1;

END;



GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingReturnDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingReturnDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @DateIs_OLD DATE ,
        @VendorID UNIQUEIDENTIFIER ,
        @Return INT;

    END;
		
    BEGIN --Set info
	    
      SELECT TOP ( 1 ) @DateIs_OLD = s.DateOnly ,
          @VendorID = s.AccountVendorID
        FROM Invoices.t_PurchasingReturn AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert

      SET @Return = 0;

      INSERT INTO Invoices.t_PurchasingReturnDeleted
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            InvoiceTitleID ,
            InvoiceTitle ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            UserID ,
            UserIs ,
            AccountVendorID ,
            AccountVendor ,
            AccountVendorNumber ,
            ContactPerson ,
            AccountBoxID ,
            AccountBox ,
            AccountBoxNumber ,
            PaymentMethod ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsD ,
            DiscountIsLL ,
            DiscountIsEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            FirstPayment ,
            FirstPaymentF ,
            FirstPaymentD ,
            FirstPaymentLL ,
            FirstPaymentEuro ,
            Sell ,
            SellF ,
            SellD ,
            SellLL ,
            SellEuro ,
            Qtys ,
            DescriptionIs ,
            ItemsNames ,
            ItemHaveDiscount ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.RefPaper ,
            t.InvoiceTitleID ,
            t.InvoiceTitle ,
            t.DateIs ,
            t.DateOnly ,
            t.DateMonthly ,
            t.DateYearly ,
            t.UserID ,
            t.UserIs ,
            t.AccountVendorID ,
            t.AccountVendor ,
            t.AccountVendorNumber ,
            t.ContactPerson ,
            t.AccountBoxID ,
            t.AccountBox ,
            t.AccountBoxNumber ,
            t.PaymentMethod ,
            t.CurrencyID ,
            t.Currency ,
            t.ExchangeRate ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            t.TaxExchangeRateLL ,
            t.TaxExchangeRateEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.DiscountIs ,
            t.DiscountIsF ,
            t.DiscountIsD ,
            t.DiscountIsLL ,
            t.DiscountIsEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.NetIs ,
            t.NetIsF ,
            t.NetIsD ,
            t.NetIsLL ,
            t.NetIsEuro ,
            t.NetIsAR ,
            t.NetIsEN ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.FirstPayment ,
            t.FirstPaymentF ,
            t.FirstPaymentD ,
            t.FirstPaymentLL ,
            t.FirstPaymentEuro ,
            t.Sell ,
            t.SellF ,
            t.SellD ,
            t.SellLL ,
            t.SellEuro ,
            t.Qtys ,
            t.DescriptionIs ,
            t.ItemsNames ,
            t.ItemHaveDiscount ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Invoices.t_PurchasingReturn AS t
          WHERE t.ID = @ID;

      INSERT INTO Invoices.t_PurchasingReturnDeletedDetail
          ( ID ,
            PurchasingReturnDeletedID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            DiscountInvoice ,
            DiscountInvoiceF ,
            DiscountInvoiceD ,
            DiscountInvoiceLL ,
            DiscountInvoiceEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Sell ,
            SellF ,
            SellD ,
            SellLL ,
            SellEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitTotal ,
            ProfitTotalF ,
            ProfitTotalD ,
            ProfitTotalLL ,
            ProfitTotalEuro ,
            DescriptionIs ,
            SortAt ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.PurchasingReturnID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.DiscountIs ,
            t.DiscountIsF ,
            t.DiscountIsValue ,
            t.DiscountIsValueF ,
            t.DiscountIsValueD ,
            t.DiscountIsValueLL ,
            t.DiscountIsValueEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.DiscountInvoice ,
            t.DiscountInvoiceF ,
            t.DiscountInvoiceD ,
            t.DiscountInvoiceLL ,
            t.DiscountInvoiceEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Sell ,
            t.SellF ,
            t.SellD ,
            t.SellLL ,
            t.SellEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.ProfitTotal ,
            t.ProfitTotalF ,
            t.ProfitTotalD ,
            t.ProfitTotalLL ,
            t.ProfitTotalEuro ,
            t.DescriptionIs ,
            t.SortAt ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Invoices.t_PurchasingReturnDetail AS t
          WHERE t.PurchasingReturnID = @ID;

    END;

    EXECUTE Invoices.s_PurchasingReturnDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      DELETE FROM Invoices.t_PurchasingReturnDetail
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          Deleted.Qtys
          INTO @ItemQtys
        WHERE PurchasingReturnID = @ID;

      DELETE FROM Invoices.t_PurchasingReturn
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 1 AND LinkID = @ID;

    END;

    BEGIN--Item Qtys

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET PurchasingReturnC -= 1 ,
            PurchasingReturnTotal = [Invoices].[f_PurchasingReturnGetTotalByAccountVendorID](ID) ,
            PurchasingReturnProfit = [Invoices].[f_PurchasingReturnGetProfitByAccountVendorID](ID) ,
            PurchasingReturnLast = [Invoices].f_PurchasingReturnGetLastDateByAccountVendorID(ID)
        WHERE ID = @VendorID;

      UPDATE Company.t_Account
        SET PurchasingReturnTotalF = Currencys.f_Format(CurrencyID, PurchasingReturnTotal) ,
            PurchasingReturnProfitF = Currencys.f_Format(CurrencyID, PurchasingReturnProfit)
        WHERE ID = @VendorID;
		  
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_PurchasingReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Invoices.s_ProfitDaily_PurchaseReturnInvoices_Update_PART @DateIs_OLD;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingReturnDetailExpirationDateDeletePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingReturnDetailExpirationDateDeletePART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @t Items.tt_ItemExpirationDate ,
      @Ref BIGINT = Items.f_ItemExpirationDateGetNewRef() - 1;

  END;

  BEGIN --Set info

    INSERT INTO @t
        ( ID ,
          Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          WareHouse ,
          PlaceID ,
          Place ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Currency ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          IsSync ,
          WorkStationID ,
          OriginalID ,
          FatherID1 ,
          FatherID2 ,
          EventIs
        )
      SELECT t.OriginalID ,
          @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                              ) ) ,
          N'0' ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t1.Name AS WareHouse ,
          t.PlaceID ,
          t2.Name AS Place ,
          t.SectionIs ,
          t.SectionID ,
          t.Barcode ,
          t.Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t3.Name AS Currency ,
          t.Price ,
          t.PriceF ,
          t.PriceD ,
          t.PriceLL ,
          t.PriceEuro ,
          t.BatchNumber ,
          t.DescriptionIs ,
          t.DateCreate ,
          0 ,
          1 ,
          t.OriginalID ,
          t.PurchasingReturnID ,
          t.PurchasingReturnDetailID ,
          N''
        FROM Invoices.t_PurchasingReturnDetailExpirationDate AS t
        INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WareHouseID
        INNER JOIN Company.t_Place AS t2 ON t2.ID = t.PlaceID
        INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t.CurrencyID
        WHERE t.PurchasingReturnID = @ID;

    UPDATE @t
      SET RefF = FORMAT(Ref, '#');

  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @t AS s )
  BEGIN
   
    RETURN;

  END;

  BEGIN --Merge
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( s.Ref ,
               s.RefF ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               s.WareHouse ,
               s.PlaceID ,
               s.Place ,
               s.SectionIs ,
               s.SectionID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               s.Currency ,
               s.Price ,
               s.PriceF ,
               s.PriceD ,
               s.PriceLL ,
               s.PriceEuro ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;
    
  BEGIN --Delete t_PurchasingReturnDetailExpirationDate

    DELETE FROM Invoices.t_PurchasingReturnDetailExpirationDate
      WHERE PurchasingReturnID = @ID;
 
  END;
  
END;








GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingReturnDetailExpirationDateInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingReturnDetailExpirationDateInsertPART] @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @ItemExpirationDate AS s )
  BEGIN
   
    RETURN;

  END;
  
  BEGIN --Declare

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;
  
  BEGIN --Insert t_PurchasingReturnDetailExpirationDate

    INSERT INTO Invoices.t_PurchasingReturnDetailExpirationDate
        ( OriginalID ,
          PurchasingReturnID ,
          PurchasingReturnDetailID ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT s.OriginalID ,
          @ID ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.PlaceID ,
          s.SectionIs ,
          s.SectionID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate AS s;

  END;
  
  BEGIN --Set
   
    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @ItemExpirationDate AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

  END;  

  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys -= s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	

END;



