/****** Object:  StoredProcedure [Invoices].[s_PurchasingReturnDetailExpirationDateUpdatePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingReturnDetailExpirationDateUpdatePART] @ItemExpirationDate_Old [Items].tt_ItemExpirationDate READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  
  BEGIN --Declare

    DECLARE @All [Items].tt_ItemExpirationDate;

    DECLARE @t AS  TABLE
      (
        Ref BIGINT NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );
 
    DECLARE @Ref BIGINT = Items.f_ItemExpirationDateGetNewRef() - 1;

  END;

  BEGIN --Set
   
    INSERT INTO @All
        ( ID ,
          Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          WareHouse ,
          PlaceID ,
          Place ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Currency ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          IsSync ,
          WorkStationID ,
          OriginalID ,
          FatherID1 ,
          FatherID2 ,
          EventIs
        )
      SELECT t.ID ,
          t.Ref ,
          t.RefF ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.WareHouse ,
          t.PlaceID ,
          t.Place ,
          t.SectionIs ,
          t.SectionID ,
          t.Barcode ,
          t.Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Currency ,
          t.Price ,
          t.PriceF ,
          t.PriceD ,
          t.PriceLL ,
          t.PriceEuro ,
          t.BatchNumber ,
          t.DescriptionIs ,
          t.DateCreate ,
          t.IsSync ,
          t.WorkStationID ,
          t.OriginalID ,
          t.FatherID1 ,
          t.FatherID2 ,
          t.EventIs
        FROM @ItemExpirationDate_Old AS t
      UNION ALL
      SELECT t.ID ,
          t.Ref ,
          t.RefF ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.WareHouse ,
          t.PlaceID ,
          t.Place ,
          t.SectionIs ,
          t.SectionID ,
          t.Barcode ,
          0 - t.Qtys AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Currency ,
          t.Price ,
          t.PriceF ,
          t.PriceD ,
          t.PriceLL ,
          t.PriceEuro ,
          t.BatchNumber ,
          t.DescriptionIs ,
          t.DateCreate ,
          t.IsSync ,
          t.WorkStationID ,
          t.OriginalID ,
          t.FatherID1 ,
          t.FatherID2 ,
          t.EventIs
        FROM @ItemExpirationDate AS t;

    INSERT INTO @t
        ( Ref ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT 0 ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          SUM(t.Qtys) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @All AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    DELETE FROM @t
      WHERE Qtys = 0;

    WITH  o AS ( SELECT s.Ref ,
                    @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                        ) ) AS Ref_
                  FROM @t AS s
                  WHERE s.Qtys > 0
               )
      UPDATE o
        SET o.Ref = o.Ref_;

  END;  
 
  BEGIN --Delete t_PurchasingReturnDetailExpirationDate

    DELETE FROM Invoices.t_PurchasingReturnDetailExpirationDate
      WHERE PurchasingReturnID = @ID;
 
  END;

  BEGIN --Insert t_PurchasingReturnDetailExpirationDate

    INSERT INTO Invoices.t_PurchasingReturnDetailExpirationDate
        ( OriginalID ,
          PurchasingReturnID ,
          PurchasingReturnDetailID ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          SectionIs ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT s.OriginalID ,
          @ID ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.PlaceID ,
          10 ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate AS s;

  END;
  
  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ItemSharedID
                    FROM @t AS s )
  BEGIN
   
    RETURN;

  END;

  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET AND s.Qtys > 0 THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( s.Ref ,
               FORMAT(s.Ref, '#') ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               Company.f_WareHouseGetName(s.WareHouseID) ,
               s.PlaceID ,
               Company.f_PlaceGetName(s.PlaceID) ,
               10 ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               Currencys.f_CurrencyGetName(s.CurrencyID) ,
               s.Price ,
               Currencys.f_Format(s.CurrencyID, s.Price) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateLL() ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateEuro() ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	

END;





