/****** Object:  StoredProcedure [Invoices].[s_PurchasingUnsavedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingUnsavedMerge] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @PCName NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @DiscountIs FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @Detail Invoices.tt_PurchasingUnsavedDetail READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Merge

      MERGE Invoices.t_PurchasingUnsaved AS t
      USING
        ( SELECT @ID AS ID
        ) AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 UserID ,
                 PCName ,
                 CurrencyID ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 TaxExchangeRateLL ,
                 TaxExchangeRateEuro ,
                 DiscountIs ,
                 TotalF ,
                 ItemsCount
               )
        VALUES ( @ID ,
                 @UserID ,
                 @PCName ,
                 @CurrencyID ,
                 @ExchangeRateLL ,
                 @ExchangeRateEuro ,
                 @TaxExchangeRateLL ,
                 @TaxExchangeRateEuro ,
                 @DiscountIs ,
                 @TotalF ,
                 @ItemsCount
          
               )
      WHEN MATCHED THEN
        UPDATE SET t.DateIs = GETDATE() ,
                    t.UserID = @UserID ,
                    t.PCName = @PCName ,
                    t.CurrencyID = @CurrencyID ,
                    t.ExchangeRateLL = @ExchangeRateLL ,
                    t.ExchangeRateEuro = @ExchangeRateEuro ,
                    t.TaxExchangeRateLL = @TaxExchangeRateLL ,
                    t.TaxExchangeRateEuro = @TaxExchangeRateEuro ,
                    t.DiscountIs = @DiscountIs ,
                    t.TotalF = @TotalF ,
                    t.ItemsCount = @ItemsCount;

    END;

    BEGIN --Reinsert t_PurchasingUnsavedDetail
	
      DELETE FROM Invoices.t_PurchasingUnsavedDetail
        WHERE PurchasingUnsavedID = @ID;

      INSERT Invoices.t_PurchasingUnsavedDetail
          ( ID ,
            PurchasingUnsavedID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            Price ,
            PriceF ,
            DiscountIs ,
            TaxRate ,
            TotalF ,
            Sell ,
            DescriptionIs ,
            SortAt 
	      )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            s.Price ,
            s.PriceF ,
            s.DiscountIs ,
            s.TaxRate ,
            s.TotalF ,
            s.Sell ,
            s.DescriptionIs ,
            s.SortAt
          FROM @Detail AS s;

    END;

    EXECUTE Invoices.s_PurchasingUnsavedLiveVersion;
    EXECUTE Invoices.s_PurchasingUnsavedDetailLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_PurchasingUpdate] @RefPaper NVARCHAR(MAX) ,
  @Legal BIT ,
  @InvoiceTitleID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @VendorID UNIQUEIDENTIFIER ,
  @ContactPerson NVARCHAR(MAX) ,
  @AccountTaxID UNIQUEIDENTIFIER ,
  @AccountIDPurchaseNonTaxable UNIQUEIDENTIFIER ,
  @AccountIDPurchaseTaxable UNIQUEIDENTIFIER ,
  @BoxID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @ResetTransactions BIT ,
  @NetIs FLOAT ,
  @NetNonTaxable FLOAT ,
  @NetTaxableWithoutTax FLOAT ,
  @Tax FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @DiscountIs FLOAT ,
  @Expenses FLOAT ,
  @ExpensesF NVARCHAR(MAX) ,
  @ExpensesD FLOAT ,
  @ExpensesLL FLOAT ,
  @ExpensesEuro FLOAT ,
  @ExpensesTaxRate FLOAT ,
  @ExpensesTaxRateF NVARCHAR(MAX) ,
  @ExpensesTax FLOAT ,
  @ExpensesTaxF NVARCHAR(MAX) ,
  @ExpensesTaxD FLOAT ,
  @ExpensesTaxLL FLOAT ,
  @ExpensesTaxEuro FLOAT ,
  @ExpensesWithTax FLOAT ,
  @ExpensesWithTaxF NVARCHAR(MAX) ,
  @ExpensesWithTaxD FLOAT ,
  @ExpensesWithTaxLL FLOAT ,
  @ExpensesWithTaxEuro FLOAT ,
  @FirstPayment FLOAT ,
  @SecondPaymentCurrencyID UNIQUEIDENTIFIER ,
  @SecondPaymentCurrency NVARCHAR(MAX) ,
  @SecondPayment FLOAT ,
  @SecondPaymentF NVARCHAR(MAX) ,
  @SecondPaymentD FLOAT ,
  @SecondPaymentLL FLOAT ,
  @SecondPaymentEuro FLOAT ,
  @SecondPaymentAccountBoxID UNIQUEIDENTIFIER ,
  @SecondPaymentAccountBox NVARCHAR(MAX) ,
  @SecondPaymentAccountBoxNumber NVARCHAR(MAX) ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @WePaidD FLOAT ,
  @WePaidLL FLOAT ,
  @WePaidEuro FLOAT ,
  @WeReceivedD FLOAT ,
  @WeReceivedLL FLOAT ,
  @WeReceivedEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Invoices.tt_PurchasingDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @StatementIs NVARCHAR(MAX) ,
  @ExpensesTable Company.tt_Expenses READONLY ,
  @ResetExpenses BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventInsert NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @LegalRef BIGINT ,
        @LegalRefF NVARCHAR(MAX) ,
        @DateOnly_OLD DATE ,
        @DateOnly DATE = @DateIs,
        @AnyRef BIGINT ,
        @AnyRefF NVARCHAR(MAX) ,
        @VendorIDOld UNIQUEIDENTIFIER ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @TrnRefJV BIGINT ,
        @TrnRefPV BIGINT ,
        @RowNumber INT ,
        @Vendor NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @return INT = 0 ,
        @LinkType INT = 0 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @StatementIs_ NVARCHAR(MAX) ,
        @AllFirstPayment FLOAT = @FirstPayment + Currencys.f_ChooseValue(@CurrencyID, @SecondPaymentD, @SecondPaymentLL, @SecondPaymentEuro) ,
        @SecondPaymentExchangeRate FLOAT = Currencys.f_ChooseValue(@SecondPaymentCurrencyID, 1, @ExchangeRateLL, @ExchangeRateEuro);

    END;

    BEGIN --Declare and Set ItemExpirationDate

      DECLARE @ItemExpirationDate_Old [Items].[tt_ItemExpirationDate];
    
      INSERT INTO @ItemExpirationDate_Old
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID ,
            OriginalID ,
            FatherID1 ,
            FatherID2 ,
            EventIs
		  )
        SELECT s.ID ,
            0 ,
            N'' ,
            s.ItemSharedID ,
            s.ItemID ,
            s.WareHouseID ,
            N'' ,
            s.PlaceID ,
            N'' ,
            s.SectionIs ,
            s.SectionID ,
            N'' ,
            s.Qtys ,
            s.ProductionDate ,
            s.ExpirationDate ,
            s.NotifyMeDaysBefore ,
            s.NotificationDate ,
            s.CurrencyID ,
            N'' ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            s.BatchNumber ,
            s.DescriptionIs ,
            s.DateCreate ,
            s.IsSync ,
            s.WorkStationID ,
            s.OriginalID ,
            s.PurchasingID ,
            s.PurchasingDetailID ,
            N''
          FROM Invoices.t_PurchasingDetailExpirationDate AS s
          WHERE s.PurchasingID = @ID;

    END;

    BEGIN --Set Info

      SELECT TOP ( 1 ) @TrnRefJV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'JV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;

      SELECT TOP ( 1 ) @TrnRefPV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'PV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;

      SET @Vendor = Company.f_AccountGetName(@VendorID);
      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);
      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

      IF @CurrencyTypeIs <> 0
      BEGIN

        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Invoices.t_PurchasingDetail AS s
          WHERE s.PurchasingID = @ID;

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @RefF = s.RefF ,
          @LegalRef = s.LegalRef ,
          @LegalRefF = s.LegalRefF ,
          @AnyRef = s.Ref ,
          @AnyRefF = s.RefF ,
          @DateOnly_OLD = s.DateOnly ,
          @VendorIDOld = s.AccountVendorID
        FROM Invoices.t_Purchasing AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;
   
      IF @Legal = 1
      BEGIN

        IF @LegalRef <= 0
        BEGIN
	                        
          SELECT @LegalRef = ISNULL(MAX(s.LegalRef), 0) + 1
            FROM Invoices.t_Purchasing AS s
            WHERE s.Legal = 1;
          SET @LegalRefF = FORMAT(@LegalRef, '#');	  

        END;

        SET @AnyRef = @LegalRef;
        SET @AnyRefF = N'|' + @LegalRefF;

      END;
      ELSE
      BEGIN

        SET @LegalRef = 0;
        SET @LegalRefF = N'';
  
      END;

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      IF @VendorID = @VendorIDOld AND @ResetTransactions = 0
      BEGIN
                                       
        SET @PaidUp += ( SELECT ISNULL(SUM(s.Balance), 0)
                          FROM Transactions.t_TransactionDetail AS s
                          INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                          WHERE s.Balance > 0 AND s1.LinkType = @LinkType AND s1.LinkTypeSub = 16 AND s1.LinkID = @ID
                       );

        SET @PaidUpF = Currencys.f_Format(@CID, @PaidUp);
        SET @PaidUpD = @PaidUp / @E;
        SET @PaidUpLL = @PaidUpD * @ELL;
        SET @PaidUpEuro = @PaidUpD * @EEuro;

        SET @Rest = @NetIs - @PaidUp;
        SET @RestF = Currencys.f_Format(@CID, @Rest);
        SET @RestD = @Rest / @E;
        SET @RestLL = @RestD * @ELL;
        SET @RestEuro = @RestD * @EEuro;

      END;

    END;

    BEGIN --Update

      UPDATE Invoices.t_Purchasing
        SET RefPaper = @RefPaper ,
            Legal = @Legal ,
            LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF ,
            InvoiceTitleID = @InvoiceTitleID ,
            InvoiceTitle = Invoices.f_InvoiceTitleGetName(@InvoiceTitleID) ,
            DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            AccountVendorID = @VendorID ,
            AccountVendor = Company.f_AccountGetName(@VendorID) ,
            AccountVendorNumber = Company.f_AccountGetNumberF(@VendorID) ,
            ContactPerson = @ContactPerson ,
            AccountBoxID = @BoxID ,
            AccountBox = Company.f_AccountGetName(@BoxID) ,
            AccountBoxNumber = Company.f_AccountGetNumberF(@BoxID) ,
            PaymentMethod = @PaymentMethod ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            TaxExchangeRateLL = @TaxExchangeRateLL ,
            TaxExchangeRateEuro = @TaxExchangeRateEuro ,
            Total = ( SELECT COALESCE(SUM(s.SubTotal), 0)
                        FROM @DetailIs AS s
                    ) ,
            DiscountIs = @DiscountIs ,
            Expenses = @Expenses ,
            ExpensesF = @ExpensesF ,
            ExpensesD = @ExpensesD ,
            ExpensesLL = @ExpensesLL ,
            ExpensesEuro = @ExpensesEuro ,
            ExpensesTaxRate = @ExpensesTaxRate ,
            ExpensesTaxRateF = @ExpensesTaxRateF ,
            ExpensesTax = @ExpensesTax ,
            ExpensesTaxF = @ExpensesTaxF ,
            ExpensesTaxD = @ExpensesTaxD ,
            ExpensesTaxLL = @ExpensesTaxLL ,
            ExpensesTaxEuro = @ExpensesTaxEuro ,
            ExpensesWithTax = @ExpensesWithTax ,
            ExpensesWithTaxF = @ExpensesWithTaxF ,
            ExpensesWithTaxD = @ExpensesWithTaxD ,
            ExpensesWithTaxLL = @ExpensesWithTaxLL ,
            ExpensesWithTaxEuro = @ExpensesWithTaxEuro ,
            TaxValue = @Tax ,
            NetIs = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM @DetailIs AS s
                    ) ,
            Profit = ( SELECT COALESCE(SUM(s.ProfitTotal), 0)
                        FROM @DetailIs AS s
                     ) ,
            Sell = ( SELECT COALESCE(SUM(s.Sell * s.Qtys), 0)
                      FROM @DetailIs AS s
                   ) ,
            Qtys = ( SELECT COALESCE(SUM(s.Qtys), 0)
                      FROM @DetailIs AS s
                   ) ,
            DescriptionIs = @DescriptionIs ,
            FirstPayment = @FirstPayment ,
            SecondPaymentCurrencyID = @SecondPaymentCurrencyID ,
            SecondPaymentCurrency = @SecondPaymentCurrency ,
            SecondPayment = @SecondPayment ,
            SecondPaymentF = @SecondPaymentF ,
            SecondPaymentD = @SecondPaymentD ,
            SecondPaymentLL = @SecondPaymentLL ,
            SecondPaymentEuro = @SecondPaymentEuro ,
            SecondPaymentAccountBoxID = @SecondPaymentAccountBoxID ,
            SecondPaymentAccountBox = @SecondPaymentAccountBox ,
            SecondPaymentAccountBoxNumber = @SecondPaymentAccountBoxNumber ,
            PaidUp = @PaidUp ,
            PaidUpF = @PaidUpF ,
            PaidUpD = @PaidUpD ,
            PaidUpLL = @PaidUpLL ,
            PaidUpEuro = @PaidUpEuro ,
            WePaidD = @WePaidD ,
            WePaidLL = @WePaidLL ,
            WePaidEuro = @WePaidEuro ,
            WeReceivedD = @WeReceivedD ,
            WeReceivedLL = @WeReceivedLL ,
            WeReceivedEuro = @WeReceivedEuro ,
            Rest = @Rest ,
            RestF = @RestF ,
            RestD = @RestD ,
            RestLL = @RestLL ,
            RestEuro = @RestEuro ,
            Paid = @Paid
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_PurchasingDetail

      MERGE Invoices.t_PurchasingDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 PurchasingID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 PackUnitID ,
                 PackUnitQty ,
                 PackQtys ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 PriceLL ,
                 PriceEuro ,
                 DiscountIs ,
                 DiscountIsF ,
                 DiscountIsValue ,
                 DiscountIsValueF ,
                 DiscountIsValueD ,
                 DiscountIsValueLL ,
                 DiscountIsValueEuro ,
                 SubTotal ,
                 SubTotalF ,
                 SubTotalD ,
                 SubTotalLL ,
                 SubTotalEuro ,
                 DiscountInvoice ,
                 DiscountInvoiceF ,
                 DiscountInvoiceD ,
                 DiscountInvoiceLL ,
                 DiscountInvoiceEuro ,
                 FutureDiscountRate ,
                 FutureDiscountRateF ,
                 FutureUnitDiscount ,
                 FutureUnitDiscountF ,
                 FutureUnitDiscountD ,
                 FutureUnitDiscountLL ,
                 FutureUnitDiscountEuro ,
                 FutureTotalDiscount ,
                 FutureTotalDiscountF ,
                 FutureTotalDiscountD ,
                 FutureTotalDiscountLL ,
                 FutureTotalDiscountEuro ,
                 TaxRate ,
                 TaxRateF ,
                 TaxValue ,
                 TaxValueF ,
                 TaxValueD ,
                 TaxValueLL ,
                 TaxValueEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 Sell ,
                 SellF ,
                 SellD ,
                 SellLL ,
                 SellEuro ,
                 Profit ,
                 ProfitF ,
                 ProfitD ,
                 ProfitLL ,
                 ProfitEuro ,
                 ProfitTotal ,
                 ProfitTotalF ,
                 ProfitTotalD ,
                 ProfitTotalLL ,
                 ProfitTotalEuro ,
                 ExpenseCalculated ,
                 FixedExpense ,
                 UnitExpenses ,
                 UnitExpensesF ,
                 UnitExpensesD ,
                 UnitExpensesLL ,
                 UnitExpensesEuro ,
                 InvoiceExpenses ,
                 InvoiceExpensesF ,
                 InvoiceExpensesD ,
                 InvoiceExpensesLL ,
                 InvoiceExpensesEuro ,
                 FinalUnitCost ,
                 FinalUnitCostF ,
                 FinalUnitCostD ,
                 FinalUnitCostLL ,
                 FinalUnitCostEuro ,
                 TotalFinalCost ,
                 TotalFinalCostF ,
                 TotalFinalCostD ,
                 TotalFinalCostLL ,
                 TotalFinalCostEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.PackUnitID ,
                 s.PackUnitQty ,
                 s.PackQtys ,
                 s.Qty ,
                 Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                 s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs) ,
                 s.DiscountIsValue ,
                 Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                 s.DiscountIsValue / @ExchangeRate ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                 ( s.Price * s.Qty ) - s.DiscountIsValue ,
                 Currencys.f_Format(@CurrencyID, ( s.Price * s.Qty ) - s.DiscountIsValue) ,
                 ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ,
                 ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DiscountInvoice ,
                 Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
                 s.DiscountInvoice / @ExchangeRate ,
                 ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.FutureDiscountRate ,
                 s.FutureDiscountRateF ,
                 s.FutureUnitDiscount ,
                 s.FutureUnitDiscountF ,
                 s.FutureUnitDiscountD ,
                 s.FutureUnitDiscountLL ,
                 s.FutureUnitDiscountEuro ,
                 s.FutureTotalDiscount ,
                 s.FutureTotalDiscountF ,
                 s.FutureTotalDiscountD ,
                 s.FutureTotalDiscountLL ,
                 s.FutureTotalDiscountEuro ,
                 s.TaxRate ,
                 Currencys.f_FormatRate(s.TaxRate) ,
                 s.TaxValue ,
                 Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                 s.TaxValue / @ExchangeRate ,
                 ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
                 ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
                 s.Total ,
                 Currencys.f_Format(@CurrencyID, s.Total) ,
                 s.Total / @ExchangeRate ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Sell ,
                 Currencys.f_Format(@CurrencyID, s.Sell) ,
                 s.Sell / @ExchangeRate ,
                 ( s.Sell / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Sell / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Profit ,
                 Currencys.f_Format(@CurrencyID, s.Profit) ,
                 s.Profit / @ExchangeRate ,
                 ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Profit * s.Qty ,
                 Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
                 ( s.Profit * s.Qty ) / @ExchangeRate ,
                 ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.ExpenseCalculated ,
                 s.FixedExpense ,
                 Calculation.Division(s.InvoiceExpenses, s.Qty) ,
                 Currencys.f_Format(@CurrencyID, Calculation.Division(s.InvoiceExpenses, s.Qty)) ,
                 Calculation.Division(s.InvoiceExpensesD, s.Qty) ,
                 Calculation.Division(s.InvoiceExpensesLL, s.Qty) ,
                 Calculation.Division(s.InvoiceExpensesEuro, s.Qty) ,
                 s.InvoiceExpenses ,
                 s.InvoiceExpensesF ,
                 s.InvoiceExpensesD ,
                 s.InvoiceExpensesLL ,
                 s.InvoiceExpensesEuro ,
                 Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) ,
                 Currencys.f_Format(@CurrencyID, Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty)) ,
                 Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ,
                 ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Total + s.InvoiceExpenses - s.TaxValue ,
                 Currencys.f_Format(@CurrencyID, s.Total + s.InvoiceExpenses - s.TaxValue) ,
                 ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ,
                 ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemID = s.ItemID ,
                    t.ItemUnityID = s.ItemUnityID ,
                    t.PackUnitID = s.PackUnitID ,
                    t.PackUnitQty = s.PackUnitQty ,
                    t.PackQtys = s.PackQtys ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                    t.Qtys = s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.PriceLL = ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs) ,
                    t.DiscountIsValue = s.DiscountIsValue ,
                    t.DiscountIsValueF = Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                    t.DiscountIsValueD = s.DiscountIsValue / @ExchangeRate ,
                    t.DiscountIsValueLL = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                    t.DiscountIsValueEuro = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.SubTotal = s.SubTotal ,
                    t.SubTotalF = Currencys.f_Format(@CurrencyID, s.SubTotal) ,
                    t.SubTotalD = s.SubTotal / @ExchangeRate ,
                    t.SubTotalLL = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
                    t.SubTotalEuro = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DiscountInvoice = s.DiscountInvoice ,
                    t.DiscountInvoiceF = Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
                    t.DiscountInvoiceD = s.DiscountInvoice / @ExchangeRate ,
                    t.DiscountInvoiceLL = ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateLL ,
                    t.DiscountInvoiceEuro = ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.FutureDiscountRate = s.FutureDiscountRate ,
                    t.FutureDiscountRateF = s.FutureDiscountRateF ,
                    t.FutureUnitDiscount = s.FutureUnitDiscount ,
                    t.FutureUnitDiscountF = s.FutureUnitDiscountF ,
                    t.FutureUnitDiscountD = s.FutureUnitDiscountD ,
                    t.FutureUnitDiscountLL = s.FutureUnitDiscountLL ,
                    t.FutureUnitDiscountEuro = s.FutureUnitDiscountEuro ,
                    t.FutureTotalDiscount = s.FutureTotalDiscount ,
                    t.FutureTotalDiscountF = s.FutureTotalDiscountF ,
                    t.FutureTotalDiscountD = s.FutureTotalDiscountD ,
                    t.FutureTotalDiscountLL = s.FutureTotalDiscountLL ,
                    t.FutureTotalDiscountEuro = s.FutureTotalDiscountEuro ,
                    t.TaxRate = s.TaxRate ,
                    t.TaxRateF = Currencys.f_FormatRate(s.TaxRate) ,
                    t.TaxValue = s.TaxValue ,
                    t.TaxValueF = Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                    t.TaxValueD = s.TaxValue / @ExchangeRate ,
                    t.TaxValueLL = ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
                    t.TaxValueEuro = ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
                    t.Total = s.Total ,
                    t.TotalF = Currencys.f_Format(@CurrencyID, s.Total) ,
                    t.TotalD = s.Total / @ExchangeRate ,
                    t.TotalLL = ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TotalEuro = ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Sell = s.Sell ,
                    t.SellF = Currencys.f_Format(@CurrencyID, s.Sell) ,
                    SellD = s.Sell / @ExchangeRate ,
                    t.SellLL = ( s.Sell / @ExchangeRate ) * @ExchangeRateLL ,
                    t.SellEuro = ( s.Sell / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Profit = s.Profit ,
                    t.ProfitF = Currencys.f_Format(@CurrencyID, s.Profit) ,
                    t.ProfitD = s.Profit / @ExchangeRate ,
                    t.ProfitLL = ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
                    t.ProfitEuro = ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.ProfitTotal = s.Profit * s.Qty ,
                    t.ProfitTotalF = Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
                    t.ProfitTotalD = s.Profit * s.Qty / @ExchangeRate ,
                    t.ProfitTotalLL = ( s.Profit * s.Qty / @ExchangeRate ) * @ExchangeRateLL ,
                    t.ProfitTotalEuro = ( s.Profit * s.Qty / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.ExpenseCalculated = s.ExpenseCalculated ,
                    t.FixedExpense = s.FixedExpense ,
                    t.UnitExpenses = Calculation.Division(s.InvoiceExpenses, s.Qty) ,
                    t.UnitExpensesF = Currencys.f_Format(@CurrencyID, Calculation.Division(s.InvoiceExpenses, s.Qty)) ,
                    t.UnitExpensesD = Calculation.Division(s.InvoiceExpensesD, s.Qty) ,
                    t.UnitExpensesLL = Calculation.Division(s.InvoiceExpensesLL, s.Qty) ,
                    t.UnitExpensesEuro = Calculation.Division(s.InvoiceExpensesEuro, s.Qty) ,
                    t.InvoiceExpenses = s.InvoiceExpenses ,
                    t.InvoiceExpensesF = s.InvoiceExpensesF ,
                    t.InvoiceExpensesD = s.InvoiceExpensesD ,
                    t.InvoiceExpensesLL = s.InvoiceExpensesLL ,
                    t.InvoiceExpensesEuro = s.InvoiceExpensesEuro ,
                    t.FinalUnitCost = Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) ,
                    t.FinalUnitCostF = Currencys.f_Format(@CurrencyID, Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty)) ,
                    t.FinalUnitCostD = Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ,
                    t.FinalUnitCostLL = ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateLL ,
                    t.FinalUnitCostEuro = ( Calculation.Division(s.Total + s.InvoiceExpenses - s.TaxValue, s.Qty) / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.TotalFinalCost = s.Total + s.InvoiceExpenses - s.TaxValue ,
                    t.TotalFinalCostF = Currencys.f_Format(@CurrencyID, s.Total + s.InvoiceExpenses - s.TaxValue) ,
                    t.TotalFinalCostD = ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ,
                    t.TotalFinalCostLL = ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TotalFinalCostEuro = ( ( s.Total + s.InvoiceExpenses - s.TaxValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.PurchasingID = @ID THEN
        DELETE;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            0 ,
            @ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_PurchasingDetailSerial

      INSERT INTO Invoices.t_PurchasingDetailSerial
          ( PurchasingID ,
            PurchasingDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;
  
    EXECUTE Invoices.s_PurchasingDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_PurchasingDetailExpirationDateUpdatePART @ItemExpirationDate_Old, @ItemExpirationDate, @ID;  

    BEGIN --Update t_Purchasing

      UPDATE Invoices.t_Purchasing
        SET TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalD = Total / ExchangeRate ,
            TotalLL = ( Total / ExchangeRate ) * @ExchangeRateLL ,
            TotalEuro = ( Total / ExchangeRate ) * @ExchangeRateEuro ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            DiscountIsD = DiscountIs / ExchangeRate ,
            DiscountIsLL = ( DiscountIs / ExchangeRate ) * @ExchangeRateLL ,
            DiscountIsEuro = ( DiscountIs / ExchangeRate ) * @ExchangeRateEuro ,
            TaxRate = Calculation.GetRate(TaxValue, NetIs - TaxValue) ,
            TaxRateF = Calculation.GetRateF(TaxValue, NetIs - TaxValue) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            TaxValueD = TaxValue / ExchangeRate ,
            TaxValueLL = ( TaxValue / ExchangeRate ) * @TaxExchangeRateLL ,
            TaxValueEuro = ( TaxValue / ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsD = NetIs / ExchangeRate ,
            NetIsLL = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateLL ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            NetIsEuro = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateEuro ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            ProfitD = Profit / ExchangeRate ,
            ProfitLL = ( Profit / ExchangeRate ) * @ExchangeRateLL ,
            ProfitEuro = ( Profit / ExchangeRate ) * @ExchangeRateEuro ,
            SellF = Currencys.f_Format(CurrencyID, Sell) ,
            SellD = Sell / ExchangeRate ,
            SellLL = ( Sell / ExchangeRate ) * @ExchangeRateLL ,
            SellEuro = ( Sell / ExchangeRate ) * @ExchangeRateEuro ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            FirstPaymentD = FirstPayment / ExchangeRate ,
            FirstPaymentLL = ( FirstPayment / ExchangeRate ) * @ExchangeRateLL ,
            FirstPaymentEuro = ( FirstPayment / ExchangeRate ) * @ExchangeRateEuro ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM @DetailIs AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM @DetailIs AS s
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    DECLARE @NumberIs BIGINT = Company.f_AccountGetNumber(@VendorID);
    IF @NumberIs <> 4010100001 AND @NumberIs <> 4110100001
    BEGIN --Insert last price

      DECLARE @DetailIsDistinct AS TABLE
        (
          ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
          ItemUnityID UNIQUEIDENTIFIER NOT NULL ,
          Price FLOAT NOT NULL ,
          DiscountIs DECIMAL(5, 2) NOT NULL
        );

      DECLARE @DistinctIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      INSERT INTO @DistinctIDs
          ( ID
          )
        SELECT MIN(s.ID)
          FROM @DetailIs AS s
          WHERE s.Price <> 0
          GROUP BY s.ItemUnityID;

      INSERT INTO @DetailIsDistinct
          ( ItemSharedID ,
            ItemUnityID ,
            Price ,
            DiscountIs
          )
        SELECT o1.ItemSharedID ,
            o1.ItemUnityID ,
            o1.Price ,
            o1.DiscountIs
          FROM @DistinctIDs AS o
          INNER JOIN @DetailIs AS o1 ON o1.ID = o.ID;

      MERGE Company.t_AccountItemPrice AS t
      USING @DetailIsDistinct AS s
      ON s.ItemUnityID = t.ItemUnityID AND t.AccountID = @VendorID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( AccountID ,
                 ItemSharedID ,
                 ItemUnityID ,
                 Unity ,
                 CurrencyID ,
                 Currency ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 DiscountIs ,
                 DiscountIsF
               )
        VALUES ( @VendorID ,
                 s.ItemSharedID ,
                 s.ItemUnityID ,
                 Items.f_UnityItemGetName(s.ItemUnityID) ,
                 @CurrencyID ,
                 @Currency ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs)
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = @CurrencyID ,
                    t.Currency = @Currency ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs);

    END;

    BEGIN --Insert t_PurchasingMoving

      SET @return = -1;

      INSERT INTO Invoices.t_PurchasingMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Delete t_Transaction

      IF @ResetTransactions = 1
      BEGIN
	                              
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkID = @ID;

      END;
      ELSE
      BEGIN
          
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkTypeSub = 0 AND LinkID = @ID;
  
        IF @VendorID <> @VendorIDOld
        BEGIN
    
          DELETE FROM Transactions.t_Transaction
            WHERE LinkType = @LinkType AND LinkTypeSub = 16 AND LinkID = @ID;

        END;
  
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkTypeSub = 18 AND LinkID = @ID;

      END;

    END;

    --IF @Net > 0
    BEGIN --Insert t_Transaction

      SET @TransactionRef = @TrnRefJV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert t_Transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert t_TransactionDetail

        SET @V = @NetIs;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @Tax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        IF @NetNonTaxable > 0
        BEGIN --Insert detail 

          SET @V = @NetNonTaxable;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountIDPurchaseNonTaxable, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;

        IF @Tax > 0
        BEGIN --Insert detail tax

          SET @V = @NetTaxableWithoutTax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountIDPurchaseTaxable, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Tax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;

      END;

    END;

    IF @AllFirstPayment <> 0
    BEGIN --Insert t_Transaction

      SET @TransactionRef = @TrnRefPV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'PV';

      END;

      BEGIN --Insert t_Transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'PV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert t_TransactionDetail

        IF ( @AllFirstPayment >= @NetIs AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @AllFirstPayment <= @NetIs - @Tax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          IF @FirstPayment <> 0
          BEGIN

            SET @V = @FirstPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
      
          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @VendorID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;
        ELSE
        BEGIN

          IF @FirstPayment <> 0
          BEGIN

            SET @V = @FirstPayment - @Tax;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @V = @FirstPayment - @V;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Box + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @VendorID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
   
          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 5, @TransactionID, @VendorID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @Vendor;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 6, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;

      END;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Update t_Transaction

      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET PurchasingTotal = Invoices.f_PurchasingGetTotalByAccountVendorID(ID) ,
            PurchasingProfit = Invoices.f_PurchasingGetProfitByAccountVendorID(ID) ,
            PurchasingLast = Invoices.f_PurchasingGetLastDateByAccountVendorID(ID)
        WHERE ID = @VendorID OR ID = @VendorIDOld;

      UPDATE Company.t_Account
        SET PurchasingTotalF = Currencys.f_Format(CurrencyID, PurchasingTotal) ,
            PurchasingProfitF = Currencys.f_Format(CurrencyID, PurchasingProfit)
        WHERE ID = @VendorID OR ID = @VendorIDOld;

    END;

    IF @ResetExpenses = 1
    BEGIN
	                          
	--Delete Expenses
      EXECUTE Invoices.s_PurchasinDeleteExpensesPART @ID;
	
	--Insert Expenses
      EXECUTE Company.s_ExpenseInsertsPART 0, @ID, @RefF, @ExpensesTable, @UserID, @Event, @ComputerIP, @Computer, @ComputerAccount;

    END;
  
    IF @DateOnly_OLD = @DateOnly
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateOnly;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateOnly_OLD;
      EXECUTE Invoices.s_ProfitDaily_PurchaseInvoices_Update_PART @DateOnly;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



















GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateIsSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_PurchasingUpdateIsSync]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;

    BEGIN --Insert

      UPDATE  Invoices.t_Purchasing
      SET     IsSync = 1
      WHERE   ID = @ID;

    END;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Invoices.t_PurchasingMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                7 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







