GO

CREATE PROCEDURE [Invoices].[s_PurchasingUpdateLegal] @ID UNIQUEIDENTIFIER ,
  @LegalID UNIQUEIDENTIFIER ,
  @LegalRef BIGINT ,
  @LegalRefF NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Update 

      UPDATE Invoices.t_Purchasing
        SET Legal = IIF(@LegalID = Alls.f_GetEmptyGuid(), 0, 1) ,
            LegalID = @LegalID ,
            LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF
        WHERE ID = @ID;

    END;
 		
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;














