/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateLegalRef]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingUpdateLegalRef] @LegalRef BIGINT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @LinkType INT = 0 ,
        @StatementIsFirstPart NVARCHAR(MAX) = N'P:Inv' ,
        @LegalRefOld BIGINT ,
        @LegalRefFOld NVARCHAR(MAX) ,
        @LegalRefNumberOld NVARCHAR(MAX) ,
        @LegalRefF NVARCHAR(MAX) = FORMAT(@LegalRef, '#') ,
        @LegalRefNumber NVARCHAR(MAX) = CONVERT(NVARCHAR(MAX), @LegalRef) ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      SELECT TOP ( 1 ) @LegalRefOld = s.LegalRef ,
          @LegalRefFOld = FORMAT(s.LegalRef, '#') ,
          @LegalRefNumberOld = CONVERT(NVARCHAR(MAX), s.LegalRef)
        FROM Invoices.t_Purchasing AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_Purchasing
        SET LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF
        WHERE ID = @ID;

    END;
 
    BEGIN --Update t_PurchasingMoving 

--EN  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Insert: ' + @LegalRefNumberOld, N'Insert: ' + @LegalRefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Edit: ' + @LegalRefNumberOld, N'Edit: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Delete: ' + @LegalRefNumberOld, N'Delete: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

--AR  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'إضافة: ' + @LegalRefNumberOld, N'إضافة: ' + @LegalRefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'تعديل: ' + @LegalRefNumberOld, N'تعديل: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'حذف: ' + @LegalRefNumberOld, N'حذف: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

    END;

    BEGIN --Update t_Transaction 

      UPDATE Transactions.t_Transaction
        SET DescriptionIs = REPLACE(DescriptionIs, @StatementIsFirstPart + @LegalRefNumberOld, @StatementIsFirstPart + @LegalRefNumber)
        WHERE LinkType = @LinkType AND LinkID = @ID;
 
      UPDATE Transactions.t_TransactionDetail
        SET StatementIs = REPLACE(StatementIs, @StatementIsFirstPart + @LegalRefNumberOld, @StatementIsFirstPart + @LegalRefNumber)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Transactions.t_Transaction AS s
                        WHERE s.LinkType = @LinkType AND s.LinkID = @ID );

    END;
			
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @Return;

  END CATCH;

END;














GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingUpdateNotSync] @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    DISABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    DISABLE TRIGGER Invoices.tr_PurchasingDetailSerial ON Invoices.t_PurchasingDetailSerial;

    BEGIN --Update

      UPDATE Invoices.t_Purchasing
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Purchasing.ID );

      UPDATE Invoices.t_PurchasingDetail
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_PurchasingDetail.PurchasingID );

      UPDATE Invoices.t_PurchasingDetailSerial
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_PurchasingDetailSerial.PurchasingID );

    END;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    ENABLE TRIGGER Invoices.tr_PurchasingDetailSerial ON Invoices.t_PurchasingDetailSerial;
		  
    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Purchase, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;







GO
