/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateRef]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingUpdateRef] @Ref BIGINT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @LinkType INT = 0 ,
        @StatementIsFirstPart NVARCHAR(MAX) = N'P:Inv' ,
        @RefOld BIGINT ,
        @RefFOld NVARCHAR(MAX) ,
        @RefNumberOld NVARCHAR(MAX) ,
        @RefF NVARCHAR(MAX) = FORMAT(@Ref, '#') ,
        @RefNumber NVARCHAR(MAX) = CONVERT(NVARCHAR(MAX), @Ref) ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      SELECT TOP ( 1 ) @RefOld = s.Ref ,
          @RefFOld = FORMAT(s.Ref, '#') ,
          @RefNumberOld = CONVERT(NVARCHAR(MAX), s.Ref)
        FROM Invoices.t_Purchasing AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_Purchasing
        SET Ref = @Ref ,
            RefF = @RefF
        WHERE ID = @ID;

    END;
 
    BEGIN --Update t_PurchasingMoving 

--EN  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Insert: ' + @RefNumberOld, N'Insert: ' + @RefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Edit: ' + @RefNumberOld, N'Edit: ' + @RefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'Delete: ' + @RefNumberOld, N'Delete: ' + @RefNumber)
        WHERE SectionID = @ID;

--AR  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'إضافة: ' + @RefNumberOld, N'إضافة: ' + @RefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'تعديل: ' + @RefNumberOld, N'تعديل: ' + @RefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_PurchasingMoving
        SET EventIs = REPLACE(EventIs, N'حذف: ' + @RefNumberOld, N'حذف: ' + @RefNumber)
        WHERE SectionID = @ID;

    END;

    BEGIN --Update t_Transaction 

      UPDATE Transactions.t_Transaction
        SET DescriptionIs = REPLACE(DescriptionIs, @StatementIsFirstPart + @RefNumberOld, @StatementIsFirstPart + @RefNumber)
        WHERE LinkType = @LinkType AND LinkID = @ID;
 
      UPDATE Transactions.t_TransactionDetail
        SET StatementIs = REPLACE(StatementIs, @StatementIsFirstPart + @RefNumberOld, @StatementIsFirstPart + @RefNumber)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Transactions.t_Transaction AS s
                        WHERE s.LinkType = @LinkType AND s.LinkID = @ID );

    END;
			
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @Return;

  END CATCH;

END;













