/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateResetLegalRefs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingUpdateResetLegalRefs] @StartRefFrom BIGINT
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

    BEGIN --DECLARE
	    
      DECLARE @LinkType INT = 0 ,
        @StatementIs NVARCHAR(MAX) = N'P:Inv|';

    END;

    IF @StartRefFrom >= 1
    BEGIN
                         
      SET @StartRefFrom -= 1;

    END;

    BEGIN --Update
 
      WITH  o AS ( SELECT t.LegalRef ,
                      t.LegalRefF ,
                      t.DateIs ,
                      t.DateCreate ,
                      ROW_NUMBER() OVER ( ORDER BY t.DateIs ) + @StartRefFrom AS LegalRef_
                    FROM Invoices.t_Purchasing AS t
                    WHERE t.Legal = 1
                 )
        UPDATE o
          SET o.LegalRef = o.LegalRef_ ,
              o.LegalRefF = FORMAT(o.LegalRef_, '#') ,
              o.DateCreate = o.DateIs;

      UPDATE Invoices.t_Purchasing
        SET LegalID = Alls.f_GetEmptyGuid() ,
            LegalRef = 0 ,
            LegalRefF = ''
        WHERE Legal = 0;

    END;
		
    BEGIN --Delete t_PurchasingMoving 
	
      TRUNCATE TABLE Invoices.t_PurchasingMoving;

    END;
	
    BEGIN --Update t_Transaction 

      WITH  o AS ( SELECT s.DescriptionIs ,
                      s1.LegalRefF
                    FROM Transactions.t_Transaction AS s
                    INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.LinkID
                    WHERE s.LinkType = @LinkType AND s1.Legal = 1
                 )
        UPDATE o
          SET DescriptionIs = @StatementIs + o.LegalRefF;

      WITH  o AS ( SELECT s.StatementIs ,
                      s2.LegalRefF
                    FROM Transactions.t_TransactionDetail AS s
                    INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                    INNER JOIN Invoices.t_Purchasing AS s2 ON s2.ID = s1.LinkID
                    WHERE s1.LinkType = @LinkType AND s2.Legal = 1
                 )
        UPDATE o
          SET StatementIs = @StatementIs + o.LegalRefF;

    END;
	
    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
	
    EXECUTE Invoices.s_PurchasingLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Invoices].[s_PurchasingUpdateResetRefs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_PurchasingUpdateResetRefs] @StartRef BIGINT
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

    BEGIN --DECLARE
	    
      DECLARE @LinkType INT = 0 ,
        @StatementIs NVARCHAR(MAX) = N'P:Inv';

    END;

    BEGIN --Update
 
      WITH  o AS ( SELECT t.Ref ,
                      t.RefF ,
                      t.DateIs ,
                      t.DateCreate ,
                      ROW_NUMBER() OVER ( ORDER BY t.DateIs ) + @StartRef AS Ref_
                    FROM Invoices.t_Purchasing AS t
                 )
        UPDATE o
          SET o.Ref = o.Ref_ ,
              o.RefF = FORMAT(o.Ref_, '#') ,
              o.DateCreate = o.DateIs;

    END;
		
    BEGIN --Delete t_PurchasingMoving 
	
      TRUNCATE TABLE Invoices.t_PurchasingMoving;

    END;
	
    BEGIN --Update t_Transaction 

      WITH  o AS ( SELECT s.DescriptionIs ,
                      s1.RefF
                    FROM Transactions.t_Transaction AS s
                    INNER JOIN Invoices.t_Purchasing AS s1 ON s1.ID = s.LinkID
                    WHERE s.LinkType = @LinkType
                 )
        UPDATE o
          SET DescriptionIs = @StatementIs + o.RefF;

      WITH  o AS ( SELECT s.StatementIs ,
                      s2.RefF
                    FROM Transactions.t_TransactionDetail AS s
                    INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                    INNER JOIN Invoices.t_Purchasing AS s2 ON s2.ID = s1.LinkID
                    WHERE s1.LinkType = @LinkType
                 )
        UPDATE o
          SET StatementIs = @StatementIs + o.RefF;

    END;

    ENABLE TRIGGER Invoices.tr_Purchasing ON Invoices.t_Purchasing;
    ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
	
    EXECUTE Invoices.s_PurchasingLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;


