CREATE PROCEDURE [Invoices].[s_SellOrderDeletedRebuildingStatisticsAll] @RebuildColumn NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding Statistics

      IF @RebuildColumn = 'All'
      BEGIN

        UPDATE Invoices.t_SellOrderDeleted
          SET TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              PrepaymentF = Currencys.f_Format(CurrencyID, Prepayment) ,
              ItemsQtys = Invoices.f_SellOrderDeletedGetItemsQtysX(ID) ,
              ItemsCount = Invoices.f_SellOrderDeletedGetItemsCountX(ID) ,
              ItemsNames = Invoices.f_SellOrderDeletedGetItemsNamesX(ID);

        WITH  o AS ( SELECT s.UnitCost ,
                        s.UnitCostF ,
                        s.TotalCost ,
                        s.TotalCostF ,
                        s.SalePrice ,
                        s.SalePriceF ,
                        s.Discount ,
                        s.DiscountF ,
                        s.SubTotal ,
                        s.SubTotalF ,
                        s.InvoiceDiscount ,
                        s.InvoiceDiscountF ,
                        s.SubTotal2 ,
                        s.SubTotal2F ,
                        s.Taxes ,
                        s.TaxesF ,
                        s.Total ,
                        s.TotalF ,
                        s.Profit ,
                        s.ProfitF ,
                        s.TotalProfit ,
                        s.TotalProfitF ,
                        s1.CurrencyID
                      FROM Invoices.t_SellOrderDeletedDetails AS s
                      INNER JOIN Invoices.t_SellOrderDeleted AS s1 ON s1.ID = s.SellOrderDeletedID
                   )
          UPDATE o
            SET o.UnitCostF = Currencys.f_Format(o.CurrencyID, o.UnitCost) ,
                o.TotalCostF = Currencys.f_Format(o.CurrencyID, o.TotalCost) ,
                o.SalePriceF = Currencys.f_Format(o.CurrencyID, o.SalePrice) ,
                o.DiscountF = Currencys.f_Format(o.CurrencyID, o.Discount) ,
                o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
                o.InvoiceDiscountF = Currencys.f_Format(o.CurrencyID, o.InvoiceDiscount) ,
                o.SubTotal2F = Currencys.f_Format(o.CurrencyID, o.SubTotal2) ,
                o.TaxesF = Currencys.f_Format(o.CurrencyID, o.Taxes) ,
                o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
                o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
                o.TotalProfitF = Currencys.f_Format(o.CurrencyID, o.TotalProfit);

      END;

      IF @RebuildColumn = 'Currency'
      BEGIN

        UPDATE Invoices.t_SellOrderDeleted
          SET TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              DiscountF = Currencys.f_Format(CurrencyID, Discount) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              PrepaymentF = Currencys.f_Format(CurrencyID, Prepayment);

        WITH  o AS ( SELECT s.UnitCost ,
                        s.UnitCostF ,
                        s.TotalCost ,
                        s.TotalCostF ,
                        s.SalePrice ,
                        s.SalePriceF ,
                        s.Discount ,
                        s.DiscountF ,
                        s.SubTotal ,
                        s.SubTotalF ,
                        s.InvoiceDiscount ,
                        s.InvoiceDiscountF ,
                        s.SubTotal2 ,
                        s.SubTotal2F ,
                        s.Taxes ,
                        s.TaxesF ,
                        s.Total ,
                        s.TotalF ,
                        s.Profit ,
                        s.ProfitF ,
                        s.TotalProfit ,
                        s.TotalProfitF ,
                        s1.CurrencyID
                      FROM Invoices.t_SellOrderDeletedDetails AS s
                      INNER JOIN Invoices.t_SellOrderDeleted AS s1 ON s1.ID = s.SellOrderDeletedID
                   )
          UPDATE o
            SET o.UnitCostF = Currencys.f_Format(o.CurrencyID, o.UnitCost) ,
                o.TotalCostF = Currencys.f_Format(o.CurrencyID, o.TotalCost) ,
                o.SalePriceF = Currencys.f_Format(o.CurrencyID, o.SalePrice) ,
                o.DiscountF = Currencys.f_Format(o.CurrencyID, o.Discount) ,
                o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
                o.InvoiceDiscountF = Currencys.f_Format(o.CurrencyID, o.InvoiceDiscount) ,
                o.SubTotal2F = Currencys.f_Format(o.CurrencyID, o.SubTotal2) ,
                o.TaxesF = Currencys.f_Format(o.CurrencyID, o.Taxes) ,
                o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
                o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
                o.TotalProfitF = Currencys.f_Format(o.CurrencyID, o.TotalProfit);

      END;

      IF @RebuildColumn = 'Invoices Informations'
      BEGIN

        UPDATE Invoices.t_SellOrderDeleted
          SET ItemsQtys = Invoices.f_SellOrderDeletedGetItemsQtysX(ID) ,
              ItemsCount = Invoices.f_SellOrderDeletedGetItemsCountX(ID) ,
              ItemsNames = Invoices.f_SellOrderDeletedGetItemsNamesX(ID);

      END;

    END;

    SET @Return = -1;
    EXEC Invoices.s_SellOrderMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount;
   
    EXECUTE Invoices.[s_SellOrderDeletedLiveVersion];

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;












