            SubTotalLL ,
            SubTotalEuro ,
            InvoiceDiscount ,
            InvoiceDiscountF ,
            InvoiceDiscountD ,
            InvoiceDiscountLL ,
            InvoiceDiscountEuro ,
            SubTotal2 ,
            SubTotal2F ,
            SubTotal2D ,
            SubTotal2LL ,
            SubTotal2Euro ,
            TaxesRate ,
            TaxesRateF ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            Total ,
