            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.OrderBy ,
            t.DescriptionIs ,
            t.AdditionsNames
          FROM @SellOrderDetails AS t;

    END;
  
    BEGIN --Insert t_SellOrderDetailsAdditions

      INSERT INTO Invoices.t_SellOrderDetailsAdditions
          ( ID ,
            SellOrderID ,
            SellOrderDetailsID ,
            AdditionsOnItemsID ,
