            t.SalePriceEuro
          FROM @Additions AS t;

    END;
    
	EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    SET @Return = -1;
    EXECUTE Invoices.s_SellOrderMovingInsertPART @ID, @CreatedByUserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_SellOrderLiveVersion;
    EXECUTE Invoices.s_SellOrderDetailsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








