AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;

    BEGIN --Update

      UPDATE Invoices.t_SellOrder
        SET TotalCost = @TotalCost ,
            TotalCostF = @TotalCostF ,
            TotalCostD = @TotalCostD ,
            TotalCostLL = @TotalCostLL ,
            TotalCostEuro = @TotalCostEuro ,
            Subtotal = @Subtotal ,
            SubtotalF = @SubtotalF ,
