            AnyItemHasDiscount = @AnyItemHasDiscount
        WHERE ID = @ID;

    END;
  
    BEGIN --Delete t_SellOrderDetailsAdditions

      DELETE FROM Invoices.t_SellOrderDetailsAdditions
        WHERE SellOrderID = @ID OR EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @MergeIDs AS s
                                              WHERE s.ID = t_SellOrderDetailsAdditions.SellOrderID );

    END;

    BEGIN --Delete t_SellOrderDetails

      DELETE FROM Invoices.t_SellOrderDetails
        WHERE SellOrderID = @ID OR EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @MergeIDs AS s
                                              WHERE s.ID = t_SellOrderDetails.SellOrderID );

    END;
   
    BEGIN --Delete t_SellOrder

      DELETE FROM Invoices.t_SellOrder
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @MergeIDs AS s
                        WHERE s.ID = t_SellOrder.ID );

    END;

    BEGIN --Insert t_SellOrderDetail

      INSERT INTO Invoices.t_SellOrderDetails
          ( ID ,
