            OrderBy ,
            DescriptionIs ,
            AdditionsNames 
          )
        SELECT t.ID ,
            t.SellOrderID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.PackUnitID ,
            t.PackUnitQty ,
            t.PackQtys ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.TotalCost ,
            t.TotalCostF ,
            t.TotalCostD ,
            t.TotalCostLL ,
            t.TotalCostEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.InvoiceDiscount ,
            t.InvoiceDiscountF ,
            t.InvoiceDiscountD ,
            t.InvoiceDiscountLL ,
            t.InvoiceDiscountEuro ,
            t.SubTotal2 ,
            t.SubTotal2F ,
            t.SubTotal2D ,
            t.SubTotal2LL ,
            t.SubTotal2Euro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.OrderBy ,
            t.DescriptionIs ,
            t.AdditionsNames
          FROM @SellOrderDetails AS t;

    END;
   
    BEGIN --Insert t_SellOrderDetailsAdditions

      INSERT INTO Invoices.t_SellOrderDetailsAdditions
          ( ID ,
            SellOrderID ,
            SellOrderDetailsID ,
            AdditionsOnItemsID ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro
          )
        SELECT t.ID ,
            t.SellOrderID ,
            t.SellOrderDetailsID ,
            t.AdditionsOnItemsID ,
            t.Cost ,
            t.CostF ,
            t.CostD ,
            t.CostLL ,
