            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro
          FROM @Additions AS t;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SellOrderMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
    EXECUTE Invoices.s_SellOrderMovingInsertsPART @MergeIDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Invoices.s_SellOrderLiveVersion;
    EXECUTE Invoices.s_SellOrderDetailsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









