/****** Object:  StoredProcedure [Invoices].[s_SellOrderUnsavedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SellOrderUnsavedMerge] @ID UNIQUEIDENTIFIER ,
  @PCName NVARCHAR(MAX) ,
  @PricingType TINYINT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @Discount FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @CreatedByUserID UNIQUEIDENTIFIER ,
  @Detail Invoices.tt_SellOrderUnsavedDetails READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Merge

      MERGE Invoices.t_SellOrderUnsaved AS t
      USING
        ( SELECT @ID AS ID
        ) AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 PCName ,
                 CurrencyID ,
                 ExchangeRate ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 TaxExchangeRateLL ,
                 TaxExchangeRateEuro ,
                 Discount ,
                 TotalF ,
                 DescriptionIs
               )
        VALUES ( @ID ,
                 @PCName ,
                 @CurrencyID ,
                 @ExchangeRate ,
                 @ExchangeRateLL ,
                 @ExchangeRateEuro ,
                 @TaxExchangeRateLL ,
                 @TaxExchangeRateEuro ,
                 @Discount ,
                 @TotalF ,
                 @DescriptionIs
          
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = @CurrencyID ,
                    t.ExchangeRate = @ExchangeRate ,
                    t.ExchangeRateLL = @ExchangeRateLL ,
                    t.ExchangeRateEuro = @ExchangeRateEuro ,
                    t.TaxExchangeRateLL = @TaxExchangeRateLL ,
                    t.TaxExchangeRateEuro = @TaxExchangeRateEuro ,
                    t.Discount = @Discount ,
                    t.TotalF = @TotalF ,
                    t.DescriptionIs = @DescriptionIs,
					t.DateCreated = GETDATE();

    END;

    BEGIN --Reinsert t_SellOrderUnsavedDetails
	
      DELETE FROM Invoices.t_SellOrderUnsavedDetails
        WHERE SellOrderUnsavedID = @ID;

      INSERT Invoices.t_SellOrderUnsavedDetails
          ( ID ,
            SellOrderUnsavedID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            Qty ,
            UnitCost ,
            SalePrice ,
            DiscountRate ,
            Discount ,
            TaxesRate ,
            Taxes ,
            OrderBy ,
            DescriptionIs
          )
        SELECT s.ID ,
            s.SellOrderUnsavedID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.WarehouseID ,
            s.ItemUnitID ,
            s.Qty ,
            s.UnitCost ,
            s.SalePrice ,
            s.DiscountRate ,
            s.Discount ,
            s.TaxesRate ,
            s.Taxes ,
            s.OrderBy ,
            s.DescriptionIs
          FROM @Detail AS s;

    END;

    EXECUTE Invoices.s_SellOrderUnsavedLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;






GO
