            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            OrderBy ,
            DescriptionIs ,
            AdditionsNames 
          )
        SELECT t.ID ,
            t.SellOrderID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.PackUnitID ,
            t.PackUnitQty ,
            t.PackQtys ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.TotalCost ,
            t.TotalCostF ,
            t.TotalCostD ,
            t.TotalCostLL ,
            t.TotalCostEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
