            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.OrderBy ,
            t.DescriptionIs ,
            t.AdditionsNames
          FROM @SellOrderDetails AS t;

    END;
   
    BEGIN --Insert t_SellOrderDetailsAdditions

      INSERT INTO Invoices.t_SellOrderDetailsAdditions
          ( ID ,
            SellOrderID ,
            SellOrderDetailsID ,
            AdditionsOnItemsID ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro
          )
        SELECT t.ID ,
            t.SellOrderID ,
            t.SellOrderDetailsID ,
            t.AdditionsOnItemsID ,
            t.Cost ,
            t.CostF ,
            t.CostD ,
            t.CostLL ,
            t.CostEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro
          FROM @Additions AS t;

    END;

    IF @TransactionNeedRest = 1
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 238 AND LinkID = @ID;
    
      EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SellOrderMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_SellOrderLiveVersion;
    EXECUTE Invoices.s_SellOrderDetailsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








