/****** Object:  StoredProcedure [Invoices].[s_SoldDebtRedistribution]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldDebtRedistribution] @IDs AS Alls.tt_Guid READONLY ,
  @drs AS Invoices.tt_FixPaidUp READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @drsCommission Employees.tt_SalesPerson_Increment_CommissionAvailable ,
        @return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT SalespersonID ,
            0 - COALESCE(SUM(CommissionAvailableValueD), 0) ,
            0 - COALESCE(SUM(CommissionAvailableValueLL), 0) ,
            0 - COALESCE(SUM(CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold
          WHERE CommissionAvailableValueD > 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                            FROM @IDs AS s
                                                            WHERE s.ID = t_Sold.AccountCustomerID )
          GROUP BY SalespersonID;

    END;

    BEGIN --Update t_Sold
  
      UPDATE Invoices.t_Sold
        SET PaidUp = NetIs ,
            PaidUpF = NetIsF ,
            PaidUpD = NetIsD ,
            PaidUpLL = NetIsLL ,
            PaidUpEuro = NetIsEuro ,
            Rest = 0 ,
            RestF = Currencys.f_Format(CurrencyID, 0) ,
            RestD = 0 ,
            RestLL = 0 ,
            RestEuro = 0 ,
            Paid = 2 ,
            CommissionAvailableValue = IIF(SalespersonTakeCommission = 1, 0, CommissionValue) ,
            CommissionAvailableValueF = Currencys.f_Format(CurrencyID, IIF(SalespersonTakeCommission = 1, 0, CommissionValue)) ,
            CommissionAvailableValueD = IIF(SalespersonTakeCommission = 1, 0, CommissionValue) / ExchangeRate ,
            CommissionAvailableValueLL = ( IIF(SalespersonTakeCommission = 1, 0, CommissionValue) / ExchangeRate ) * ExchangeRateLL ,
            CommissionAvailableValueEuro = ( IIF(SalespersonTakeCommission = 1, 0, CommissionValue) / ExchangeRate ) * ExchangeRateEuro ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Sold.AccountCustomerID );

    END;
 
    BEGIN --Merge t_Sold

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUp = s.PaidUp ,
                    t.PaidUpF = Currencys.f_Format(t.CurrencyID, s.PaidUp) ,
                    t.PaidUpD = s.PaidUp / t.ExchangeRate ,
                    t.Rest = t.NetIs - s.PaidUp ,
                    t.RestF = Currencys.f_Format(t.CurrencyID, t.NetIs - s.PaidUp) ,
                    t.RestD = ( t.NetIs - s.PaidUp ) / t.ExchangeRate ,
                    t.RowVersionID = [DateTimes].[f_GetRowVersionID]();

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUpLL = t.PaidUpD * t.ExchangeRateLL ,
                    t.PaidUpEuro = t.PaidUpD * t.ExchangeRateEuro ,
                    t.RestLL = t.RestD * t.ExchangeRateLL ,
                    t.RestEuro = t.RestD * t.ExchangeRateEuro ,
                    t.Paid = IIF(t.PaidUp = 0 AND t.NetIs > 0, 0, IIF(t.Rest > 0, 1, 2));

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.CommissionAvailableValue = IIF(t.SalespersonTakeCommission = 1, 0, IIF(t.CommissionRateType = 0, t.CommissionValue, IIF(t.Paid <> 2, 0, t.CommissionValue)));

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.CommissionAvailableValueF = Currencys.f_Format(t.CurrencyID, t.CommissionAvailableValue) ,
                    t.CommissionAvailableValueD = t.CommissionAvailableValue / t.ExchangeRate ,
                    t.CommissionAvailableValueLL = ( t.CommissionAvailableValue / t.ExchangeRate ) * t.ExchangeRateLL ,
                    t.CommissionAvailableValueEuro = ( t.CommissionAvailableValue / t.ExchangeRate ) * t.ExchangeRateEuro;
 
    END;

    BEGIN --Set2
    
      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT SalespersonID ,
            COALESCE(SUM(CommissionAvailableValueD), 0) ,
            COALESCE(SUM(CommissionAvailableValueLL), 0) ,
            COALESCE(SUM(CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold
          WHERE CommissionAvailableValueD > 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                            FROM @IDs AS s
                                                            WHERE s.ID = t_Sold.AccountCustomerID )
          GROUP BY SalespersonID;

    END;

    EXECUTE Employees.s_SalesPerson_Increments_CommissionAvailable_PART @drsCommission;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART1 @drs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;
 
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;


GO
