/****** Object:  StoredProcedure [Invoices].[s_SoldDeletedDeletes]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldDeletedDeletes] @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DELETE FROM Invoices.t_SoldDeletedEmployeeProfit
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_SoldDeletedEmployeeProfit.SoldDeletedID );

    DELETE FROM Invoices.t_SoldDeletedDetailEmployeeProfit
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_SoldDeletedDetailEmployeeProfit.SoldDeletedID );

    DELETE FROM Invoices.t_SoldDeletedDetail
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_SoldDeletedDetail.SoldDeletedID );

    DELETE FROM Invoices.t_SoldDeleted
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_SoldDeleted.ID );

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;




