GO
CREATE PROCEDURE [Invoices].[s_SoldDeletes] @SendThemToTheTrash BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_IDAndEvent READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_OLD DateTimes.tt_DateOnly;

      DECLARE @ItemQtys AS Items.ItemAppendQtys;
    
      DECLARE @AccountCustomerIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Serials AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @drsCommission Employees.tt_SalesPerson_Increment_CommissionAvailable ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @DateOnly_OLD
          ( DateOnly
          )
        SELECT DISTINCT s1.DateOnly
          FROM @IDs AS s
          INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.ID;
  
      INSERT INTO @AccountCustomerIDs
          ( ID
          )
        SELECT DISTINCT t.AccountCustomerID
          FROM Invoices.t_Sold AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT t.ItemID ,
            t.ItemSharedID ,
            t.Qtys
          FROM Invoices.t_SoldDetail AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.SoldID )
        UNION ALL
        SELECT t.ItemID ,
            t.ItemSharedID ,
            0 - t.Qtys
          FROM Items.t_ItemProduction AS t
          WHERE t.OriginSection = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                  FROM @IDs AS s
                                                  WHERE s.ID = t.OriginID )
        UNION ALL
        SELECT t.ItemID ,
            t.ItemSharedID ,
            t.Qtys
          FROM Items.t_ItemProductionMaterial AS t
          INNER JOIN Items.t_ItemProduction AS t1 ON t1.ID = t.ItemProductionID
          WHERE t1.OriginSection = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                    FROM @IDs AS s
                                                    WHERE s.ID = t1.OriginID )
        UNION ALL
        SELECT t.ItemID ,
            t.ItemSharedID ,
            0 - t.Qtys
          FROM Items.t_StockAdjustmentDetail AS t
          INNER JOIN Items.t_StockAdjustment AS t1 ON t1.ID = t.StockAdjustmentID
          WHERE t1.LinkType = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @IDs AS s
                                              WHERE s.ID = t1.LinkID );

      INSERT INTO @Serials
          ( ID
          )
        SELECT t.SerialID
          FROM Invoices.t_SoldDetailSerial AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.SoldID );

      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT t.SalespersonID ,
            0 - COALESCE(SUM(t.CommissionAvailableValueD), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueLL), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID )
          GROUP BY t.SalespersonID;

    END;

