      BEGIN --Insert t_SoldDeletedEmployeeProfit
    
        INSERT Invoices.t_SoldDeletedEmployeeProfit
            ( ID ,
              SoldDeletedID ,
              EmployeeID ,
              ProfitRatio ,
              ProfitRatioF ,
