              t.ProfitD ,
              t.ProfitLL ,
              t.ProfitEuro ,
              t.DateCreate ,
              t.WorkStationID
            FROM Invoices.t_SoldEmployeeProfit AS t
            WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                            FROM @IDs AS s
                            WHERE s.ID = t.SoldID );

      END;

      BEGIN --Insert t_SoldDeletedDetailEmployeeProfit

        INSERT Invoices.t_SoldDeletedDetailEmployeeProfit
            ( ID ,
              SoldDeletedID ,
              SoldDeletedDetailID ,
