                        FROM @IDs AS s
                        WHERE s.ID = t_SoldDetailAdditions.SoldID );
   
    END;

    BEGIN --Delete t_SoldDetailEmployeeProfit

      DELETE FROM Invoices.t_SoldDetailEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_SoldDetailEmployeeProfit.SoldID );
   
    END;

    BEGIN --Delete t_SoldEmployeeProfit

      DELETE FROM Invoices.t_SoldEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_SoldEmployeeProfit.SoldID );

    END;

    BEGIN --Update t_ItemSerial
    
      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Serials AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;

    BEGIN --Delete t_SoldDetailSerial

      DELETE FROM Invoices.t_SoldDetailSerial
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_SoldDetailSerial.SoldID );
 
    END;

    EXECUTE Invoices.s_SoldDetailExpirationDateDeletesPART @IDs;

    BEGIN --Delete t_SoldDetail

      DELETE FROM Invoices.t_SoldDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_SoldDetail.SoldID );
 
    END;

    BEGIN --Delete t_Sold

      DELETE FROM Invoices.t_Sold
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_Sold.ID );

    END;
	
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 2 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                          FROM @IDs AS s
                                          WHERE s.ID = t_Transaction.LinkID );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET SoldC = [Invoices].[f_SoldGetCountByAccountCustomerID](ID) ,
            SoldTotal = [Invoices].[f_SoldGetTotalByAccountCustomerID](ID) ,
            SoldProfit = [Invoices].[f_SoldGetProfitByAccountCustomerID](ID) ,
            SoldLast = [Invoices].f_SoldGetLastDateByAccountCustomerID(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @AccountCustomerIDs AS s
                        WHERE s.ID = t_Account.ID );

      UPDATE Company.t_Account
        SET SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
            SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @AccountCustomerIDs AS s
                        WHERE s.ID = t_Account.ID );
		  
    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    BEGIN-- Delete t_ItemProduction

      DELETE FROM Items.t_ItemProductionMaterial
        WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                        FROM Items.t_ItemProduction AS t
                        WHERE t.OriginSection = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                                FROM @IDs AS s
                                                                WHERE s.ID = t.OriginID ) AND t.ID = t_ItemProductionMaterial.ItemProductionID );

      DELETE FROM Items.t_ItemProduction
        WHERE OriginSection = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @IDs AS s
                                              WHERE s.ID = t_ItemProduction.OriginID );

    END;
   
    BEGIN-- Delete t_StockAdjustment

      DELETE FROM Items.t_StockAdjustmentDetailSerial
        WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                        FROM Items.t_StockAdjustment AS t
                        WHERE t.LinkType = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                            FROM @IDs AS s
                                                            WHERE s.ID = t.LinkID ) AND t.ID = t_StockAdjustmentDetailSerial.StockAdjustmentID );
   
      DELETE FROM Items.t_StockAdjustmentDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                        FROM Items.t_StockAdjustment AS t
                        WHERE t.LinkType = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                            FROM @IDs AS s
                                                            WHERE s.ID = t.LinkID ) AND t.ID = t_StockAdjustmentDetail.StockAdjustmentID );

      DELETE FROM Items.t_StockAdjustment
        WHERE LinkType = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                          FROM @IDs AS s
                                          WHERE s.ID = t_StockAdjustment.LinkID );

    END;

    BEGIN --Delete t_SoldDetailEmployeeProfit

      DELETE FROM Invoices.t_SoldDetailEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_SoldDetailEmployeeProfit.SoldID );
   
    END;

	--Delete t_CustomersInvoicesPoints
    EXECUTE Customers.s_CustomersInvoicesPointsDeletesPART @IDs;
	
    EXECUTE Currencys.s_SchedulePaymentsDeletesBySourcePART @IDs, 1;
  
    EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Updates_PART @DateOnly_OLD;

    EXECUTE Employees.s_SalesPerson_Increments_CommissionAvailable_PART @drsCommission;
	  
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;





