CREATE PROCEDURE [Invoices].[s_SoldDetailAdditions_Inserts_PART] @dt Invoices.tt_SoldDetailAdditions READONLY
AS
BEGIN

  INSERT INTO Invoices.t_SoldDetailAdditions
      ( ID ,
        SoldID ,
        SoldDetailID ,
        AdditionsOnItemsID
      )
    SELECT s.ID ,
        s.SoldID ,
        s.SoldDetailID ,
        s.AdditionsOnItemsID
      FROM @dt AS s;

END;

