/****** Object:  StoredProcedure [Invoices].[s_SoldDetailEmployeeProfitUpdatePaid]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldDetailEmployeeProfitUpdatePaid] @ID UNIQUEIDENTIFIER ,
  @SoldID UNIQUEIDENTIFIER ,
  @Paid BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update

      UPDATE Invoices.t_SoldDetailEmployeeProfit
        SET Paid = @Paid
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
 		
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













