CREATE PROCEDURE [Invoices].[s_SoldDetailExpirationDateDeletesPART] @IDs Alls.tt_IDAndEvent READONLY
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s )
  BEGIN
   
    RETURN;

  END;

  BEGIN --Declare

    DECLARE @t Items.tt_ItemExpirationDate ,
      @Ref BIGINT = Items.f_ItemExpirationDateGetNewRef() - 1;

  END;

  BEGIN --Set info

    INSERT INTO @t
        ( ID ,
          Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          WareHouse ,
          PlaceID ,
          Place ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Currency ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          IsSync ,
          WorkStationID ,
          OriginalID ,
          FatherID1 ,
          FatherID2 ,
          EventIs
        )
      SELECT t.OriginalID ,
          @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                              ) ) ,
          N'0' ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t1.Name AS WareHouse ,
          t.PlaceID ,
          t2.Name AS Place ,
          t.SectionIs ,
          t.SectionID ,
          t.Barcode ,
          t.Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t3.Name AS Currency ,
          t.Price ,
          t.PriceF ,
          t.PriceD ,
          t.PriceLL ,
          t.PriceEuro ,
          t.BatchNumber ,
          t.DescriptionIs ,
          t.DateCreate ,
          0 ,
          1 ,
          t.OriginalID ,
          t.SoldID ,
          t.SoldDetailID ,
          N''
        FROM Invoices.t_SoldDetailExpirationDate AS t
        INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WareHouseID
        INNER JOIN Company.t_Place AS t2 ON t2.ID = t.PlaceID
        INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t.CurrencyID
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t.SoldID );

    UPDATE @t
      SET RefF = FORMAT(Ref, '#');

  END;

  BEGIN --Merge
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( s.Ref ,
               s.RefF ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               s.WareHouse ,
               s.PlaceID ,
               s.Place ,
               s.SectionIs ,
               s.SectionID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               s.Currency ,
               s.Price ,
               s.PriceF ,
               s.PriceD ,
               s.PriceLL ,
               s.PriceEuro ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;
    
  BEGIN --Delete t_SoldDetailExpirationDate

    DELETE FROM Invoices.t_SoldDetailExpirationDate
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_SoldDetailExpirationDate.SoldID );
 
  END;
  
END;







GO
/****** Object:  StoredProcedure [Invoices].[s_SoldDetailExpirationDateInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_SoldDetailExpirationDateInsertPART] @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @ItemExpirationDate AS s )
  BEGIN
   
    RETURN;

  END;
  
  BEGIN --Declare

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;
  
  BEGIN --Insert t_SoldDetailExpirationDate

    INSERT INTO Invoices.t_SoldDetailExpirationDate
        ( OriginalID ,
          SoldID ,
          SoldDetailID ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT s.OriginalID ,
          @ID ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.PlaceID ,
          s.SectionIs ,
          s.SectionID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate AS s;

  END;
  
  BEGIN --Set
   
    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @ItemExpirationDate AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

  END;  

  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys -= s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	

END;






GO
