CREATE PROCEDURE [Invoices].[s_SoldDetailUpdateAllIsLegal] @IsLegal BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    DISABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;

    BEGIN --Update

      UPDATE Invoices.t_SoldDetail
        SET IsLegal = @IsLegal;

    END;

    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART N'', @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
	
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;




GO
