/****** Object:  StoredProcedure [Invoices].[s_SoldEmployeeProfitDeletes]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldEmployeeProfitDeletes] @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @SoldIDs Alls.tt_IDAndEvent READONLY
AS
BEGIN;

  BEGIN TRY
    BEGIN TRANSACTION;


    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete t_SoldDetailEmployeeProfit

      DELETE FROM Invoices.t_SoldDetailEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SoldIDs AS s
                        WHERE s.ID = t_SoldDetailEmployeeProfit.SoldID );
   
    END;

    BEGIN --Delete t_SoldEmployeeProfit

      DELETE FROM Invoices.t_SoldEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SoldIDs AS s
                        WHERE s.ID = t_SoldEmployeeProfit.SoldID );

    END;
	
    BEGIN --Update t_Sold

      UPDATE Invoices.t_Sold
        SET EmployeesWhoHaveProfit = N'' ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SoldIDs AS s
                        WHERE s.ID = t_Sold.ID );

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART @SoldIDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Invoices.s_SoldLiveVersion;
  	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;





