        ( ID ,
          SoldID ,
          SoldDetailID ,
          EmployeeID ,
          ProfitRatio ,
          ProfitRatioF ,
          ProfitOn ,
          Profit ,
          ProfitF ,
          ProfitD ,
          ProfitLL ,
          ProfitEuro ,
          Paid
        )
      SELECT s.ID ,
          @SoldID ,
          s.SoldDetailID ,
          s.EmployeeID ,
          s.ProfitRatio ,
          s.ProfitRatioF ,
          s.ProfitOn ,
          s.Profit ,
          s.ProfitF ,
          s.ProfitD ,
          s.ProfitLL ,
          s.ProfitEuro ,
          s.Paid
        FROM @SoldDetailEmployeeProfit AS s;

  END;
    
END;









