/****** Object:  StoredProcedure [Invoices].[s_SoldFixPaidUp]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldFixPaidUp] @drs AS Invoices.tt_FixPaidUp READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_Old DateTimes.tt_DateOnly;

      DECLARE @drsCommission Employees.tt_SalesPerson_Increment_CommissionAvailable ,
        @return INT = 0;

    END;

    BEGIN --Set
	    
      INSERT INTO @DateOnly_Old
          ( DateOnly
          )
        SELECT DISTINCT s1.DateOnly
          FROM @drs AS s
          INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.ID;

      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT t.SalespersonID ,
            0 - COALESCE(SUM(t.CommissionAvailableValueD), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueLL), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @drs AS s
                          WHERE s.ID = t.ID )
          GROUP BY t.SalespersonID;

    END;

    BEGIN --Merge

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUp = s.PaidUp ,
                    t.PaidUpF = Currencys.f_Format(t.CurrencyID, s.PaidUp) ,
                    t.PaidUpD = s.PaidUp / t.ExchangeRate ,
                    t.Rest = t.NetIs - s.PaidUp ,
                    t.RestF = Currencys.f_Format(t.CurrencyID, t.NetIs - s.PaidUp) ,
                    t.RestD = ( t.NetIs - s.PaidUp ) / t.ExchangeRate;

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUpLL = t.PaidUpD * t.ExchangeRateLL ,
                    t.PaidUpEuro = t.PaidUpD * t.ExchangeRateEuro ,
                    t.RestLL = t.RestD * t.ExchangeRateLL ,
                    t.RestEuro = t.RestD * t.ExchangeRateEuro ,
                    t.Paid = IIF(t.PaidUp = 0 AND t.NetIs > 0, 0, IIF(t.Rest > 0, 1, 2));

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.CommissionAvailableValue = IIF(t.SalespersonTakeCommission = 1, 0, IIF(t.CommissionRateType = 0, t.CommissionValue, IIF(t.Paid <> 2, 0, t.CommissionValue)));

      MERGE Invoices.t_Sold AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.CommissionAvailableValueF = Currencys.f_Format(t.CurrencyID, t.CommissionAvailableValue) ,
                    t.CommissionAvailableValueD = t.CommissionAvailableValue / t.ExchangeRate ,
                    t.CommissionAvailableValueLL = ( t.CommissionAvailableValue / t.ExchangeRate ) * t.ExchangeRateLL ,
                    t.CommissionAvailableValueEuro = ( t.CommissionAvailableValue / t.ExchangeRate ) * t.ExchangeRateEuro;
 
    END;
 
    BEGIN --Set2

      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT t.SalespersonID ,
            COALESCE(SUM(t.CommissionAvailableValueD), 0) ,
            COALESCE(SUM(t.CommissionAvailableValueLL), 0) ,
            COALESCE(SUM(t.CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @drs AS s
                          WHERE s.ID = t.ID )
          GROUP BY t.SalespersonID;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART1 @drs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Employees.s_SalesPerson_Increments_CommissionAvailable_PART @drsCommission;

    EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Updates_PART @DateOnly_Old;
  
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;













GO
