AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT = Invoices.f_SoldGetNewRef() ,
        @LegalRef BIGINT = 0 ,
        @LegalRefF NVARCHAR(MAX)= N'' ,
        @AnyRef BIGINT ,
        @AnyRefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @RowNumber INT ,
        @LinkType INT = 2 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @AccountsNames NVARCHAR(MAX) ,
        @StatementIs_ NVARCHAR(MAX) ,
        @RefF NVARCHAR(MAX) ,
        @NonTaxableTotal FLOAT = @NetIsNonTaxable ,
        @NonTaxableTotalF NVARCHAR(MAX) ,
        @NonTaxableTotalD FLOAT ,
        @NonTaxableTotalLL FLOAT ,
        @NonTaxableTotalEuro FLOAT ,
        @TaxableTotal FLOAT = @NetIsTaxableWithoutTax ,
        @TaxableTotalF NVARCHAR(MAX) ,
        @TaxableTotalD FLOAT ,
        @TaxableTotalLL FLOAT ,
        @TaxableTotalEuro FLOAT ,
        @AllFirstPayment FLOAT = @FirstPayment - @PointsPayment + Currencys.f_ChooseValue(@CurrencyID, @SecondPaymentD, @SecondPaymentLL, @SecondPaymentEuro) ,
        @SecondPaymentExchangeRate FLOAT = Currencys.f_ChooseValue(@SecondPaymentCurrencyID, 1, @ExchangeRateLL, @ExchangeRateEuro) ,
        @WFPShopID NVARCHAR(MAX) ,
        @WFPBranchID NVARCHAR(MAX) ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SET @RefF = FORMAT(@Ref, '#');

      SET @AnyRef = @Ref;
      SET @AnyRefF = @RefF;

      IF @Legal = 1
      BEGIN
            
        SET @LegalRef = Invoices.f_SoldGetNewLegalRef();
        SET @LegalRefF = FORMAT(@LegalRef, '#');	  

        SET @AnyRef = @LegalRef;
        SET @AnyRefF = N'|' + @LegalRefF;

      END;
	      
	  --TaxCompressed>
      IF @CurrencyTypeIs <> 0
      BEGIN
	                              
        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;
	  --TaxCompressed<
	  	
      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      SET @NonTaxableTotalF = Currencys.f_Format(@CID, @NonTaxableTotal);
      SET @NonTaxableTotalD = @NonTaxableTotal / @E;
      SET @NonTaxableTotalLL = @NonTaxableTotalD * @ELL;
      SET @NonTaxableTotalEuro = @NonTaxableTotalD * @EEuro;

      SET @TaxableTotalF = Currencys.f_Format(@CID, @TaxableTotal);
      SET @TaxableTotalD = @TaxableTotal / @E;
      SET @TaxableTotalLL = @TaxableTotalD * @ELL;
      SET @TaxableTotalEuro = @TaxableTotalD * @EEuro;
    
      SELECT TOP ( 1 ) @WFPShopID = s.ShopID ,
          @WFPBranchID = s.BranchID
        FROM Options.t_WorldFoodProgramme AS s
        ORDER BY s.ID;

    END;

    BEGIN --Insert

