            @CommissionValueLL ,
            @CommissionValueEuro ,
            0 ,
            @CommissionAvailableValue ,
            @CommissionAvailableValueF ,
            @CommissionAvailableValueD ,
            @CommissionAvailableValueLL ,
            @CommissionAvailableValueEuro ,
            @AccountSellNonTaxableID ,
            @AccountSellTaxableID ,
            @AccountCustomerID ,
            @AccountCustomer ,
            @AccountCustomerNumber ,
            @ContactPerson ,
            @AccountBoxID ,
            @AccountBox ,
            @AccountBoxNumber ,
            @PaymentMethod ,
            @PricingType ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ELL ,
            @EEuro ,
            @TaxExchangeRateLL ,
            @TaxExchangeRateEuro ,
            @Total ,
            @TotalF ,
            @TotalD ,
            @TotalLL ,
            @TotalEuro ,
            @DiscountIs ,
            @DiscountIsF ,
            @DiscountIsD ,
            @DiscountIsLL ,
            @DiscountIsEuro ,
            @TaxRate ,
            @TaxRateF ,
            @TaxValue ,
            @TaxValueF ,
            @TaxValueD ,
            @TaxValueLL ,
            @TaxValueEuro ,
            @TaxOnTaxRate ,
            @TaxOnTaxRateF ,
            @TaxOnTax ,
            @TaxOnTaxF ,
            @TaxOnTaxD ,
            @TaxOnTaxLL ,
            @TaxOnTaxEuro ,
            @NetIs ,
            @NetIsF ,
            @NetIsD ,
            @NetIsLL ,
            @NetIsEuro ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            Currencys.f_ToWordEN(@NetIs, @CurrencyID, 1) ,
            @NonTaxableTotal ,
            @NonTaxableTotalF ,
            @NonTaxableTotalD ,
            @NonTaxableTotalLL ,
            @NonTaxableTotalEuro ,
            @TaxableTotal ,
            @TaxableTotalF ,
            @TaxableTotalD ,
            @TaxableTotalLL ,
            @TaxableTotalEuro ,
            @Rounding ,
            @RoundingF ,
            @RoundingD ,
            @RoundingLL ,
            @RoundingEuro ,
            @ProfitRatio ,
            @ProfitRatioF ,
            @ProfitMarginRatio ,
            @ProfitMarginRatioF ,
            @Profit ,
            @ProfitF ,
            @ProfitD ,
            @ProfitLL ,
            @ProfitEuro ,
            @FirstPayment ,
            @FirstPaymentF ,
            @FirstPaymentD ,
            @FirstPaymentLL ,
            @FirstPaymentEuro ,
            @SecondPaymentCurrencyID ,
            @SecondPaymentCurrency ,
            @SecondPayment ,
            @SecondPaymentF ,
            @SecondPaymentD ,
            @SecondPaymentLL ,
            @SecondPaymentEuro ,
            @SecondPaymentAccountBoxID ,
            @SecondPaymentAccountBox ,
            @SecondPaymentAccountBoxNumber ,
            @PointsPayment ,
            @PointsPaymentF ,
            @PointsPaymentD ,
            @PointsPaymentLL ,
            @PointsPaymentEuro ,
            @TotalPoints ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @Paid ,
            @Cost ,
            @CostF ,
            @CostD ,
            @CostLL ,
            @CostEuro ,
            @WeReceiveD ,
            @WeReceiveLL ,
            @WeReceiveEuro ,
            @WeReturnedD ,
            @WeReturnedLL ,
            @WeReturnedEuro ,
            @SeparateDeliveryFees ,
            @SeparateDeliveryFeesF ,
            @SeparateDeliveryFeesD ,
            @SeparateDeliveryFeesLL ,
            @SeparateDeliveryFeesEuro ,
            @GhanaSystem ,
            @GS_Covid19Rate ,
            @GS_NHILRate ,
            @GS_GetfundLevyRate ,
            @GS_TaxRate ,
            @GS_Reverse ,
            @DeliveryStage ,
            @DeliveryStageUndelivered ,
            @DeliveryDueDate ,
            @DeliveryByEmployeeID ,
            @DeliveryDate ,
            @DeliveryDelayedDays ,
            @DeliveryNote ,
            @DescriptionIs ,
            @WFPFrom ,
            @WFPShopID ,
            @WFPBranchID ,
            0 ,
            @ItemsCount ,
            @ItemsNames ,
            @WarehousesNames ,
            @ItemHaveDiscount ,
            @TotalQuantity ,
            @PointsIs ,
            @HasSerial ,
            @EmployeesWhoHaveProfit
          );

    END;

    BEGIN --Insert t_SoldDetail

      INSERT INTO Invoices.t_SoldDetail
          ( ID ,
            SoldID ,
            ItemSharedID ,
            UsedBarcode ,
            ItemID ,
            ItemUnityID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
