    EXECUTE Invoices.s_SoldDetailAdditions_Inserts_PART @SoldDetailAdditions;
  
    IF @HasSerial = 1
    BEGIN --Insert t_SoldDetailSerial

      INSERT INTO Invoices.t_SoldDetailSerial
          ( SoldID ,
            SoldDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
  
    EXECUTE Invoices.s_SoldDetailUpdateSerialNamesPART @SerialIs;

	--Reinsert t_SoldEmployeeProfit, t_SoldDetailEmployeeProfit
    EXECUTE Invoices.s_SoldEmployeeProfitInsertPART @ID, @SoldEmployeeProfit, @SoldDetailEmployeeProfit; 
  
	--Rebuild statistics
    --EXECUTE Invoices.s_SoldFixPART @ID, @CurrencyID, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @TaxExchangeRateLL, @TaxExchangeRateEuro;
      	
    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

	--Insert Last Price
    IF @SaveLastPrice = 1
    BEGIN

      EXECUTE Invoices.s_SoldInsertLastPricePART @ID, @CurrencyID, @ExchangeRate, @AccountCustomerID, @DetailIs;

    END; 

    EXECUTE Invoices.s_SoldDetailExpirationDateInsertPART @ItemExpirationDate, @ID;
 	
    --IF @NetIs > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        SET @AccountsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t.Name AS [text()]
                                              FROM Company.t_Account AS t
                                              WHERE t.ID = @AccountCustomerID OR t.ID = IIF(@NetIsNonTaxable > 0, @AccountSellNonTaxableID, '00000000-0000-0000-0000-000000000000') OR t.ID = IIF(@AllTax > 0, @AccountSellTaxableID, '00000000-0000-0000-0000-000000000000') OR t.ID = IIF(@AllTax > 0, @AccountCustomerTaxID, '00000000-0000-0000-0000-000000000000') OR t.ID = IIF(@PointsPayment > 0, @AccountCustomerPointsID, '00000000-0000-0000-0000-000000000000') OR t.ID = @BalanceDifferenceAccountID
                                           FOR
                                             XML PATH('')
                                           ));

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID ,
              @UserIs ,
              @AccountsNames
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail
			
        SET @V = @NetIs;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertDebitTax @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @AllTax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
        --TaxCompressed 
		--EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;

      IF @NetIsNonTaxable > 0
      BEGIN --Insert detail 
	   
        SET @V = @NetIsNonTaxable + @Rounding;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountSellNonTaxableID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
										
      END;

      IF @AllTax > 0
      BEGIN --Insert detail tax

        SET @V = @NetIsTaxableWithoutTax + IIF(@NetIsNonTaxable > 0, 0, @Rounding);
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountSellTaxableID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        SET @V = @AllTax;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
        --TaxCompressed
		--EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
					
      END;

      IF @PointsPayment > 0 AND @CustomerID <> Alls.f_GetEmptyGuid()
      BEGIN --Insert detail points

        SET @V = @PointsPayment;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountCustomerPointsID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomerPoints;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
			
        SET @V = 0 - @TotalPoints;
        EXECUTE Customers.s_CustomersInvoicesPointsUseBySoldPART @CustomerID, @DateIs, @ID, @V;
						
      END;

      IF @TransactionBetweenGoodsAndPurchase = 1 AND @CostNonTaxable > 0
      BEGIN --Insert detail 
	   
        SET @V = @CostNonTaxable;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @PurchaseNonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @GoodsNonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;
   
      IF @TransactionBetweenGoodsAndPurchase = 1 AND @CostTaxableWithoutTax > 0
      BEGIN --Insert detail 
	   
        SET @V = @CostTaxableWithoutTax;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @PurchaseTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @GoodsTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;

      IF @BalanceDifference <> 0
      BEGIN --Insert Detail Balance Difference

        SET @V = ABS(@BalanceDifference);
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + IIF(@BalanceDifference < 0, N'', ' \ ' + @AccountCustomer);
        DECLARE @AccountID UNIQUEIDENTIFIER = IIF(@BalanceDifference < 0, @AccountCustomerID, @BalanceDifferenceAccountID);
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        SET @RowNumber += 1;
        SET @StatementIs_ += IIF(@BalanceDifference > 0, N'', ' \ ' + @AccountCustomer);
        SET @AccountID = IIF(@BalanceDifference > 0, @AccountCustomerID, @BalanceDifferenceAccountID);
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
					
      END;

    END;
	
    IF @AllFirstPayment <> 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert t_Transaction

        SET @return = 0;

        DELETE FROM @IDs;

        SET @AccountsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t.Name AS [text()]
                                              FROM Company.t_Account AS t
                                              WHERE t.ID = @AccountBoxID OR t.ID = @AccountCustomerID
                                           FOR
                                             XML PATH('')
                                           ));

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'RV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID ,
              @UserIs ,
              @AccountsNames
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail
		
        IF ( @AllFirstPayment >= @NetIs AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @AllFirstPayment <= @NetIs - @AllTax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          IF @FirstPayment <> 0
          BEGIN
	    
            SET @V = @FirstPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @AccountCustomerID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;
        ELSE
        BEGIN

          IF @FirstPayment <> 0
          BEGIN
	 
            SET @V = @FirstPayment - @AllTax;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @V = @FirstPayment - @V;
            IF @V <> 0
            BEGIN

              SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
              EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
        
              SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
              EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
           

            END;
          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 5, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 6, @TransactionID, @AccountCustomerID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;

		--TaxCompressed>
        --SET @V = @FirstPayment;
        --SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @AccountCustomer;
        --EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        
        --SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @AccountBox;
        --EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
		--TaxCompressed<

      END;

    END;
 
    IF @CommissionAvailableValue > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        SET @AccountsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t.Name AS [text()]
                                              FROM Company.t_Account AS t
                                              WHERE t.ID = @AccountSalespersonSellID OR t.ID = @AccountSalespersonID
                                           FOR
                                             XML PATH('')
                                           ));

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              LinkTypeSub ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              7 ,
              @UserID ,
              @UserIs ,
              @AccountsNames 
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @CommissionAvailableValue;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + N' (' + @NetIsF + N' | ' + @CommissionRateF + N' ' + Currencys.f_Format(@CID, @V) + N' EX: ' + FORMAT(@ExchangeRateLL, N'#,##0.##') + ') \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountSalespersonSellID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountSalespersonID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;

      EXECUTE Employees.s_SalesPerson_Increment_CommissionAvailable_PART @SalespersonID, @CommissionAvailableValueD, @CommissionAvailableValueLL, @CommissionAvailableValueEuro;
	         
    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET SoldC += 1 ,
            SoldTotal = CASE CurrencyTypeIs
                          WHEN 0 THEN @NetIsD
                          WHEN 1 THEN @NetIsLL
                          ELSE @NetIsEuro
                        END ,
            SoldProfit = CASE CurrencyTypeIs
                           WHEN 0 THEN @ProfitD
                           WHEN 1 THEN @ProfitLL
                           ELSE @ProfitEuro
                         END ,
            SoldLast = @DateIs ,
            LastSeparateDeliveryFeesD = @SeparateDeliveryFeesD ,
            LastSeparateDeliveryFeesLL = @SeparateDeliveryFeesLL ,
            LastSeparateDeliveryFeesEuro = @SeparateDeliveryFeesEuro
        WHERE ID = @AccountCustomerID;

      UPDATE Company.t_Account
        SET SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
            SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit)
        WHERE ID = @AccountCustomerID;

    END;

		--Close FrameJobOrder
    IF @SaveFromSection = 2
    BEGIN
    
      BEGIN --Insert t_FrameJobOrderHistory

        SET @return = -169;

        INSERT INTO Customers.t_FrameJobOrderHistory
            ( ID ,
              Ref ,
              RefF ,
              RefPaper ,
              DateIs ,
              DateDelivery ,
              DateInProcess ,
              DateInProcessNotification ,
              DateReady ,
              DateReadyNotification ,
              StatusIs ,
              PriorityLevel ,
              CustomerID ,
              Customer ,
              DoctorID ,
              Doctor ,
              SalespersonID ,
              Salesperson ,
              StatesID ,
              StatesIs ,
              RegionID ,
              RegionIs ,
              StreetID ,
              Street ,
              AddressIs ,
              Focal ,
              WithRight ,
              WithLeft ,
              SphereRight ,
              SphereLeft ,
              CylinderRight ,
              CylinderLeft ,
              AxisRight ,
              AxisLeft ,
              PrismRight ,
              PrismLeft ,
              BaseRight ,
              BaseLeft ,
              Addition ,
              HeightRight ,
              HeightLeft ,
              PDRight ,
              PDLeft ,
              PD ,
              CurrencyID ,
              Currency ,
              ExchangeRate ,
              ExchangeRateLL ,
              ExchangeRateEuro ,
              SubTotal ,
              SubTotalF ,
              SubTotalD ,
              SubTotalLL ,
              SubTotalEuro ,
              DiscountIs ,
              DiscountIsF ,
              DiscountIsD ,
              DiscountIsLL ,
              DiscountIsEuro ,
              TaxRate ,
              TaxRateF ,
              TaxValue ,
              TaxValueF ,
              TaxValueD ,
              TaxValueLL ,
              TaxValueEuro ,
              Total ,
              TotalF ,
