              t.SortAt ,
              t.DateCreate ,
              0 ,
              t.WorkStationID
            FROM Customers.t_FrameJobOrderDetail AS t
            WHERE t.FrameJobOrderID = @LinkID;

      END;

      BEGIN --Delete

        DELETE FROM Customers.t_FrameJobOrderDetail
          WHERE FrameJobOrderID = @LinkID;

        DELETE FROM Customers.t_FrameJobOrder
          WHERE ID = @LinkID;

      END;

      BEGIN --Insert event

        INSERT INTO Customers.t_FrameJobOrderMoving
            ( UserID ,
              SectionID ,
              EventIs ,
              EventType ,
              ComputerIP ,
              Computer ,
              ComputerAccount
            )
          VALUES
            ( @UserID ,
              @LinkID ,
              REPLACE(@LinkEvent, N'{0}', FORMAT(@LinkRef, '#')) ,
              IIF(@EventType = 0, 2, 11) ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
            );

      END;

    END;
	
    EXECUTE [Items].[s_ItemProductionInsertBySold] @ProductionWhenSale, @ID, @Ref, @DateIs, @StageType, @CurrencyID, @Currency, @CurrencyTypeIs, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @DetailIs, @UserID, @EventInsert, @EventInsertBySold, @ComputerIP, @Computer, @ComputerAccount; 

    IF @SaveFromSection = 1
    BEGIN

      UPDATE Quotations.t_Quotation
        SET TransmissionType = 2 ,
            TransmissionID = @ID ,
            TransmissionRef = @Ref ,
            TransmissionRefF = @RefF
        WHERE ID = @LinkID;

    END;

    IF @SaveFromSection = 4
    BEGIN

      EXECUTE Items.s_StockAdjustmentInsertPART @StockAdjustmentID, -- @ID
        1, -- @LinkType
        @ID, -- @LinkID
        @Ref, -- @LinkRef
        @RefF, -- @LinkRefF
        @DateIs, -- 
        @StockAdjustmentReasonID, --
        @StockAdjustmentReason, --
        @UserID, -- 
        @UserIs, -- 
        @CurrencyID, --
        @Currency, --
        @CurrencyTypeIs, -- 
        @ExchangeRateLL, -- 
        @ExchangeRateEuro, -- 
        @StockAdjustmentTotal, -- @Total
        @StockAdjustmentTotalF, -- @TotalF
        @StockAdjustmentTotalD, -- @TotalD
        @StockAdjustmentTotalLL, -- @TotalLL
        @StockAdjustmentTotalEuro, -- @TotalEuro
        @StockAdjustmentTotalQtys, -- @TotalQtys
        N'', -- @DescriptionIs
        @StockAdjustmentWarehouses, -- @Warehouses
        @StockAdjustmentItemsNames, -- @ItemsNames
        @StockAdjustmentDetailIs, -- @DetailIs tt_StockAdjustmentDetail
        @Event, -- @Event
        @EventType, --
        @ComputerIP, -- 
        @Computer, -- 
        @ComputerAccount; 

      SET @LinkRef = Items.f_StockAdjustmentGetRef(@StockAdjustmentID);

      UPDATE Invoices.t_Sold
        SET LinkID = @StockAdjustmentID ,
            LinkRef = @LinkRef ,
            LinkRefF = FORMAT(@LinkRef, N'0')
        WHERE ID = @ID;

    END;
  
    IF @SaveFromSection = 6
    BEGIN

      UPDATE Invoices.t_SellOrder
        SET TransmissionType = 2 ,
            TransmissionID = @ID ,
            TransmissionRef = @Ref ,
            TransmissionRefF = @RefF ,
            Scheduled = 0 ,
            TurnOffSchedulingNotification = 1
        WHERE ID = @LinkID OR EXISTS ( SELECT TOP ( 1 ) s.ID
                                        FROM @LinkIDs AS s
                                        WHERE s.ID = t_SellOrder.ID );

      EXECUTE Invoices.s_SellOrderLiveVersion;

    END;

    --Edit Item Sale Price
    EXECUTE Items.s_ItemEditSalePriceByInvoicePART @ItemSharedEditSalePrice, @UnityItemEditSalePrice;

	--Insert t_CustomersInvoicesPoints
    EXECUTE Customers.s_CustomersInvoicesPointsInsertPART @CustomerID, @DateIs, 0, @ID, @PointsIs, @UserID, @PointsEvent, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
	
    IF @SaveCRM = 1
    BEGIN

      EXECUTE Customers.s_CRMInsert @ID;

    END;

    EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly;
 
    SET @return = -1;
    DECLARE @EventFull NVARCHAR(MAX) = @Event + @AnyRefF;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @EventFull, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;

