/****** Object:  StoredProcedure [Invoices].[s_SoldPaidUpDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldPaidUpDelete] @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventTransaction NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @DateOnly_OLD DATE ,
        @CurrencyID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @PaidUp FLOAT ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly ,
          @CurrencyID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro)
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID;
	    
      SELECT @PaidUpD = ISNULL(SUM(s.BalanceD), 0) ,
          @PaidUpLL = ISNULL(SUM(s.BalanceLL), 0) ,
          @PaidUpEuro = ISNULL(SUM(s.BalanceEuro), 0)
        FROM Transactions.t_TransactionDetail AS s
        WHERE s.TransactionID = @TransactionID AND s.Balance > 0;

      SET @PaidUp = Currencys.f_ChooseValue(@CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro);
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;

    END;

    BEGIN --Update t_Sold

      UPDATE Invoices.t_Sold
        SET PaidUp -= @PaidUp ,
            PaidUpD -= @PaidUpD ,
            PaidUpLL -= @PaidUpLL ,
            PaidUpEuro -= @PaidUpEuro ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;
	    
      UPDATE Invoices.t_Sold
        SET PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            Rest = Total - PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Total - PaidUp) ,
            RestD = TotalD - PaidUpD ,
            RestLL = TotalLL - PaidUpLL ,
            RestEuro = TotalEuro - PaidUpEuro
        WHERE ID = @ID;  

      UPDATE Invoices.t_Sold
        SET Paid = Invoices.f_SoldGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;  
	    
    END;
 
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE ID = @TransactionID;

    END;
	
    SET @return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
    EXECUTE Transactions.s_TransactionMovingInsertPART @TransactionID, @UserID, @EventTransaction, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_SoldLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly_OLD;
  
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;






GO
