CREATE PROCEDURE [Invoices].[s_SoldPaidUpNew] @ID UNIQUEIDENTIFIER ,
  @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY ,
  @SchedulePaymentsID UNIQUEIDENTIFIER ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_OLD DATE ,
        @PaidUp FLOAT ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @SalesPersonID UNIQUEIDENTIFIER ,
        @return INT = 0;
		
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @DateOnly_OLD = s.DateOnly ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro ,
          @PaidUp = Currencys.f_ChooseValue(s.CurrencyID, @PaidUpD, @PaidUpLL, @PaidUpEuro) ,
          @SalesPersonID = s.SalespersonID
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID;
   
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
      
    END;

    BEGIN --Update t_Sold

      UPDATE Invoices.t_Sold
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpLL ,
            PaidUpEuro += @PaidUpEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpLL ,
            RestEuro -= @PaidUpEuro ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;

      UPDATE Invoices.t_Sold
        SET Rest = IIF(Rest < 0, 0, Rest) ,
            RestF = Currencys.f_Format(CurrencyID, IIF(Rest < 0, 0, Rest)) ,
            RestD = IIF(RestD < 0, 0, RestD) ,
            RestLL = IIF(RestLL < 0, 0, RestLL) ,
            RestEuro = IIF(RestEuro < 0, 0, RestEuro)
        WHERE ID = @ID;

      UPDATE Invoices.t_Sold
        SET Paid = Invoices.f_SoldGetPaidStatus(Total, PaidUp, Rest)
        WHERE ID = @ID;
	
      UPDATE Invoices.t_Sold
        SET CommissionAvailableValue = IIF(SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValue, IIF(Paid <> 2, 0, CommissionValue))) ,
            CommissionAvailableValueD = IIF(SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueD, IIF(Paid <> 2, 0, CommissionValueD))) ,
            CommissionAvailableValueLL = IIF(SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueLL, IIF(Paid <> 2, 0, CommissionValueLL))) ,
            CommissionAvailableValueEuro = IIF(SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueEuro, IIF(Paid <> 2, 0, CommissionValueEuro)))
        WHERE ID = @ID;

      UPDATE Invoices.t_Sold
        SET CommissionAvailableValueF = Currencys.f_Format(CurrencyID, CommissionAvailableValue)
        WHERE ID = @ID;
	
    END;

    EXECUTE Transactions.s_TransactionInsertsPART @Transaction, @TransactionDetail;

    EXECUTE Employees.s_SalesPerson_UpdateLive_CommissionAvailable_PART @SalesPersonID;
	
    SET @return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Invoices.s_SoldLiveVersion;
	
    EXECUTE Currencys.s_SchedulePaymentsDeletePART @SchedulePaymentsID;
 
    EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly_OLD;
    
    EXECUTE Invoices.s_SoldLiveVersion;
 
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_SoldRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    DISABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;

    BEGIN --Rebuild statistics
	
      UPDATE Invoices.t_Sold
        SET InvoiceTitle = Invoices.f_InvoiceTitleGetName(InvoiceTitleID) ,
            UserIs = Users.f_UserGetName(UserID) ,
            Salesperson = Employees.f_SalesPersonGetName(SalespersonID) ,
            CommissionValueF = Currencys.f_Format(CurrencyID, CommissionValue) ,
            CommissionAvailableValue = IIF(SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValue, IIF(Paid <> 2, 0, CommissionValue))) ,
            AccountCustomer = Company.f_AccountGetName(AccountCustomerID) ,
            AccountBox = Company.f_AccountGetName(AccountBoxID) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            TaxRate = Calculation.GetRate(TaxValue, NetIs - TaxValue) ,
            TaxRateF = Calculation.GetRateF(TaxValue, NetIs - TaxValue) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            RestF = Currencys.f_Format(CurrencyID, Rest) ,
            CostF = Currencys.f_Format(CurrencyID, Cost) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_SoldDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.SoldID = t_Sold.ID
                                       FOR
                                         XML PATH('')
                                       ));
 
      UPDATE Invoices.t_Sold
        SET CommissionAvailableValueF = Currencys.f_Format(CurrencyID, CommissionAvailableValue);

      WITH  o AS ( SELECT s.Price ,
                      s.PriceF ,
                      s.DiscountIs ,
                      s.DiscountIsF ,
                      s.DiscountIsValue ,
                      s.DiscountIsValueF ,
                      s.SubTotal ,
                      s.SubTotalF ,
                      s.DiscountInvoice ,
                      s.DiscountInvoiceF ,
                      s.SubTotal2 ,
                      s.SubTotal2F ,
                      s.TaxRate ,
                      s.TaxRateF ,
                      s.TaxValue ,
                      s.Total ,
                      s.TotalF ,
                      s.Cost ,
                      s.CostF ,
                      s.Profit ,
                      s.ProfitF ,
                      s.ProfitTotal ,
                      s.ProfitTotalF ,
                      s1.CurrencyID ,
                      s.Qty ,
                      s.Qtys ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Invoices.t_SoldDetail AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SoldID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE o
          SET o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
              o.DiscountIsF = Currencys.f_FormatRate(o.DiscountIs) ,
              o.DiscountIsValueF = Currencys.f_Format(o.CurrencyID, o.DiscountIsValue) ,
              o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
              o.DiscountInvoiceF = Currencys.f_Format(o.CurrencyID, o.DiscountInvoice) ,
              o.SubTotal2F = Currencys.f_Format(o.CurrencyID, o.SubTotal2) ,
              o.TaxRateF = Currencys.f_FormatRate(o.TaxRate) ,
              o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
              o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost) ,
              o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
              o.ProfitTotalF = Currencys.f_Format(o.CurrencyID, o.ProfitTotal) ,
              o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;
 
    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART N'00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Invoices.s_SoldLiveVersion;

    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
