            t.NetIsEN ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.FirstPayment ,
            t.FirstPaymentF ,
            t.FirstPaymentD ,
