            DiscountInvoiceF ,
            DiscountInvoiceD ,
            DiscountInvoiceLL ,
            DiscountInvoiceEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitTotal ,
            ProfitTotalF ,
            ProfitTotalD ,
            ProfitTotalLL ,
            ProfitTotalEuro ,
            DescriptionIs ,
            SortAt ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.SoldReturnID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.DiscountIs ,
            t.DiscountIsF ,
            t.DiscountIsValue ,
            t.DiscountIsValueF ,
            t.DiscountIsValueD ,
            t.DiscountIsValueLL ,
            t.DiscountIsValueEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.DiscountInvoice ,
            t.DiscountInvoiceF ,
            t.DiscountInvoiceD ,
            t.DiscountInvoiceLL ,
            t.DiscountInvoiceEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Cost ,
            t.CostF ,
            t.CostD ,
            t.CostLL ,
            t.CostEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.ProfitTotal ,
            t.ProfitTotalF ,
            t.ProfitTotalD ,
            t.ProfitTotalLL ,
            t.ProfitTotalEuro ,
