            t.SortAt ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID
          FROM Invoices.t_SoldReturnDetail AS t
          WHERE t.SoldReturnID = @ID;

    END;

    EXECUTE Invoices.s_SoldReturnDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      DELETE FROM Invoices.t_SoldReturnDetailSerial
        WHERE SoldReturnID = @ID;

      DELETE FROM Invoices.t_SoldReturnDetail
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          0 - Deleted.Qtys
          INTO @ItemQtys
        WHERE SoldReturnID = @ID;

      DELETE FROM Invoices.t_SoldReturn
        WHERE ID = @ID;

    END;

    BEGIN --Update item serial

      MERGE Items.t_ItemSerial AS t
      USING @SerialIs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET IsAvailable = 0;

    END;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 3 AND LinkID = @ID;

    END;

    BEGIN--Item Qtys

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET SoldReturnC -= 1 ,
            SoldReturnTotal = [Invoices].[f_SoldReturnGetTotalByAccountCustomerID](ID) ,
            SoldReturnProfit = [Invoices].[f_SoldReturnGetProfitByAccountCustomerID](ID) ,
            SoldReturnLast = [Invoices].f_SoldReturnGetLastDateByAccountCustomerID(ID)
        WHERE ID = @CustomerID;

      UPDATE Company.t_Account
        SET SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
            SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit)
        WHERE ID = @CustomerID;
		  
    END;
  
    BEGIN --Insert t_SoldReturnMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Delete t_CustomersInvoicesPoints
    EXECUTE Customers.s_CustomersInvoicesPointsDeletePART @ID;
  
    EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly_Old;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;















