/****** Object:  StoredProcedure [Invoices].[s_SoldReturnDetailExpirationDateDeletePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnDetailExpirationDateDeletePART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;

  BEGIN --Set
   
    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          0 - ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Invoices.t_SoldReturnDetailExpirationDate AS t
		WHERE t.SoldReturnID = @ID
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

  END;  

  BEGIN --Delete t_SoldReturnDetailExpirationDate

    DELETE FROM Invoices.t_SoldReturnDetailExpirationDate
      WHERE SoldReturnID = @ID;

  END;
  
  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;


GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnDetailExpirationDateInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnDetailExpirationDateInsertPART] @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Delete Old
    
    DELETE FROM Invoices.t_SoldReturnDetailExpirationDate
      WHERE SoldReturnID = @ID;

  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @ItemExpirationDate AS s )
  BEGIN
   
    RETURN;

  END;

  BEGIN --Declare

    DECLARE @t AS  TABLE
      (
        Ref BIGINT NOT NULL ,
        RefF NVARCHAR(MAX) NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );
    
    DECLARE @t_Delete AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(450) NOT NULL
      ); 	

    DECLARE @Ref BIGINT = Items.f_ItemExpirationDateGetNewRef() - 1;

  END;
  
  BEGIN --Insert t_SoldReturnDetailExpirationDate

    INSERT INTO Invoices.t_SoldReturnDetailExpirationDate
        ( ID ,
          OriginalID ,
          SoldReturnID ,
          SoldReturnDetailID ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT s.ID ,
          s.ID ,
          s.FatherID1 ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.PlaceID ,
          0 ,
          @ID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate AS s;

  END;
  
  BEGIN --Set
   
    INSERT INTO @t
        ( Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                 ) ) ,
          N'' ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @ItemExpirationDate AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    UPDATE @t
      SET RefF = FORMAT(Ref, '#');

  END;  

  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET AND s.Qtys > 0 THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( s.Ref ,
               s.RefF ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               Company.f_WareHouseGetName(s.WareHouseID) ,
               s.PlaceID ,
               Company.f_PlaceGetName(s.PlaceID) ,
               3 ,
               @ID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               Currencys.f_CurrencyGetName(s.CurrencyID) ,
               s.Price ,
               Currencys.f_Format(s.CurrencyID, s.Price) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateLL() ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateEuro() ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;
	
END;




