/****** Object:  StoredProcedure [Invoices].[s_SoldReturnFixPaidUp]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnFixPaidUp] @drs AS Invoices.tt_FixPaidUp READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

	      DECLARE @DateOnly_Old DateTimes.tt_DateOnly;

      DECLARE @return INT = 0;

    END;

    BEGIN --Set
	    
      INSERT INTO @DateOnly_Old
          ( DateOnly
          )
        SELECT DISTINCT s1.DateOnly
          FROM @drs AS s
          INNER JOIN Invoices.t_SoldReturn AS s1 ON s1.ID = s.ID;

    END;

    BEGIN --Merge

      MERGE Invoices.t_SoldReturn AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUp = s.PaidUp ,
                    t.PaidUpF = Currencys.f_Format(t.CurrencyID, s.PaidUp) ,
                    t.PaidUpD = s.PaidUp / t.ExchangeRate ,
                    t.Rest = t.NetIs - s.PaidUp ,
                    t.RestF = Currencys.f_Format(t.CurrencyID, t.NetIs - s.PaidUp) ,
                    t.RestD = ( t.NetIs - s.PaidUp ) / t.ExchangeRate;

      MERGE Invoices.t_SoldReturn AS t
      USING @drs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.PaidUpLL = t.PaidUpD * t.ExchangeRateLL ,
                    t.PaidUpEuro = t.PaidUpD * t.ExchangeRateEuro ,
                    t.RestLL = t.RestD * t.ExchangeRateLL ,
                    t.RestEuro = t.RestD * t.ExchangeRateEuro ,
                    t.Paid = IIF(t.PaidUp = 0 AND t.NetIs > 0, 0, IIF(t.Rest > 0, 1, 2));

    END;
 
    BEGIN --Insert t_SoldReturnMoving

      SET @return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventText ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @drs AS s;

    END;

    EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Updates_PART @DateOnly_Old;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;














GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnInsert] @RefPaper NVARCHAR(MAX) ,
  @SaveFromSection TINYINT,
  @LinkID UNIQUEIDENTIFIER,
  @LinkRef BIGINT,
  @LinkRefF NVARCHAR(max),
  @LinkDate DATETIME,
  @InvoiceTitleID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @AccountSalespersonID UNIQUEIDENTIFIER ,
  @AccountSalespersonSellID UNIQUEIDENTIFIER ,
  @CommissionRate DECIMAL(4, 2) ,
  @CommissionRateF NVARCHAR(MAX) ,
  @CommissionRateOn TINYINT ,
  @CommissionValue FLOAT ,
  @CommissionValueF NVARCHAR(MAX) ,
  @CommissionValueD FLOAT ,
  @CommissionValueLL FLOAT ,
  @CommissionValueEuro FLOAT ,
  @AccountCustomerID UNIQUEIDENTIFIER ,
  @ContactPerson NVARCHAR(MAX) ,
  @AccountCustomerTaxID UNIQUEIDENTIFIER ,
  @CustomerID UNIQUEIDENTIFIER ,
  @NonTaxableAccountID UNIQUEIDENTIFIER ,
  @TaxableAccountID UNIQUEIDENTIFIER ,
  @BoxID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @Payment FLOAT ,
  @Net FLOAT ,
  @NetNonTaxable FLOAT ,
  @NetTaxableWithoutTax FLOAT ,
  @Tax FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @DiscountIs FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @GhanaSystem BIT ,
  @GS_Covid19Rate FLOAT ,
  @GS_NHILRate FLOAT ,
  @GS_GetfundLevyRate FLOAT ,
  @GS_TaxRate FLOAT ,
  @GS_Reverse FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @PointsIs FLOAT ,
  @PointsEvent NVARCHAR(MAX) ,
  @DetailIs Invoices.tt_SoldReturnDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate Items.tt_ItemExpirationDate READONLY ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @DateOnly DATE  = @DateIs ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @RowNumber INT ,
        @Customer NVARCHAR(MAX) ,
        @AccountTax NVARCHAR(MAX) ,
        @Sell NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @AccountIsVendor BIT ,
        @LinkType INT = 3 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @StatementIs_ NVARCHAR(MAX) ,
        @NetD FLOAT ,
        @Profit FLOAT ,
        @ProfitD FLOAT ,
        @return INT = 0;;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Invoices.t_SoldReturn AS s;

      SET @Customer = Company.f_AccountGetName(@AccountCustomerID);
      SET @AccountTax = Company.f_AccountGetName(@AccountCustomerTaxID);
      SET @Sell = Company.f_AccountGetName(@NonTaxableAccountID);
      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);
      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

      IF @CurrencyTypeIs <> 0
      BEGIN

        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      SET @NetD = @Net / @ExchangeRate;
      SELECT @Profit = COALESCE(SUM(s.ProfitTotal), 0)
        FROM @DetailIs AS s;
      SET @ProfitD = @Profit / @ExchangeRate;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_SoldReturn
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            SaveFromSection ,
            LinkID ,
            LinkRef ,
            LinkRefF ,
            LinkDate ,
            InvoiceTitleID ,
            InvoiceTitle ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            UserID ,
            UserIs ,
            SalespersonID ,
            CommissionRate ,
            CommissionRateF ,
            CommissionRateOn ,
            CommissionValue ,
            CommissionValueF ,
            CommissionValueD ,
            CommissionValueLL ,
            CommissionValueEuro ,
            NonTaxableAccountID ,
            TaxableAccountID ,
            AccountCustomerID ,
            AccountCustomer ,
            AccountCustomerNumber ,
            ContactPerson ,
            AccountBoxID ,
            AccountBox ,
            AccountBoxNumber ,
            PaymentMethod ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            TaxExchangeRateLL ,
            TaxExchangeRateEuro ,
            Total ,
            DiscountIs ,
            TaxValue ,
            NetIs ,
            Profit ,
            PaidUp ,
            PaidUpF ,
            PaidUpD ,
            PaidUpLL ,
            PaidUpEuro ,
            Rest ,
            RestF ,
            RestD ,
            RestLL ,
            RestEuro ,
            Paid ,
            Cost ,
            GhanaSystem ,
            GS_Covid19Rate ,
            GS_NHILRate ,
            GS_GetfundLevyRate ,
            GS_TaxRate ,
            GS_Reverse ,
            Qtys ,
            DescriptionIs ,
            FirstPayment ,
            PointsIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, '#') ,
            @RefPaper ,
            @SaveFromSection ,
            @LinkID ,
            @LinkRef ,
            @LinkRefF ,
            @LinkDate ,
            @InvoiceTitleID ,
            Invoices.f_InvoiceTitleGetName(@InvoiceTitleID) ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @SalespersonID ,
            @CommissionRate ,
            @CommissionRateF ,
            @CommissionRateOn ,
            @CommissionValue ,
            @CommissionValueF ,
            @CommissionValueD ,
            @CommissionValueLL ,
            @CommissionValueEuro ,
            @NonTaxableAccountID ,
            @TaxableAccountID ,
            @AccountCustomerID ,
            Company.f_AccountGetName(@AccountCustomerID) ,
            Company.f_AccountGetNumberF(@AccountCustomerID) ,
            @ContactPerson ,
            @BoxID ,
            Company.f_AccountGetName(@BoxID) ,
            Company.f_AccountGetNumberF(@BoxID) ,
            @PaymentMethod ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @TaxExchangeRateLL ,
            @TaxExchangeRateEuro ,
            ( SELECT COALESCE(SUM(s.SubTotal), 0)
                FROM @DetailIs AS s
            ) ,
            @DiscountIs ,
            @Tax ,
            ( SELECT COALESCE(SUM(s.Total), 0)
                FROM @DetailIs AS s
            ) ,
            ( SELECT COALESCE(SUM(s.ProfitTotal), 0)
                FROM @DetailIs AS s
            ) ,
            @PaidUp ,
            @PaidUpF ,
            @PaidUpD ,
            @PaidUpLL ,
            @PaidUpEuro ,
            @Rest ,
            @RestF ,
            @RestD ,
            @RestLL ,
            @RestEuro ,
            @Paid ,
            ( SELECT COALESCE(SUM(s.Cost), 0)
                FROM @DetailIs AS s
            ) ,
            @GhanaSystem ,
            @GS_Covid19Rate ,
            @GS_NHILRate ,
            @GS_GetfundLevyRate ,
            @GS_TaxRate ,
            @GS_Reverse ,
            ( SELECT COALESCE(SUM(s.Qtys), 0)
                FROM @DetailIs AS s
            ) ,
            @DescriptionIs ,
            @Payment ,
            @PointsIs
          );

    END;

    BEGIN --Insert detail

      INSERT INTO Invoices.t_SoldReturnDetail
          ( ID ,
            SoldReturnID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            DiscountInvoice ,
            DiscountInvoiceF ,
            DiscountInvoiceD ,
            DiscountInvoiceLL ,
            DiscountInvoiceEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            ProfitTotal ,
            ProfitTotalF ,
            ProfitTotalD ,
            ProfitTotalLL ,
            ProfitTotalEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.PackUnitID ,
            s.PackUnitQty ,
            s.PackQtys ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qtys ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountIs ,
            Currencys.f_FormatRate(s.DiscountIs) ,
            s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
            s.DiscountIsValue / @ExchangeRate ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
            ( s.Price * s.Qty ) - s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, ( s.Price * s.Qty ) - s.DiscountIsValue) ,
            ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ,
            ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateLL ,
            ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountInvoice ,
            Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
            s.DiscountInvoice / @ExchangeRate ,
            ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TaxRate ,
            Currencys.f_FormatRate(s.TaxRate) ,
            s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.TaxValue) ,
            s.TaxValue / @ExchangeRate ,
            ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Cost ,
            Currencys.f_Format(@CurrencyID, s.Cost) ,
            s.Cost / @ExchangeRate ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Profit ,
            Currencys.f_Format(@CurrencyID, s.Profit) ,
            s.Profit / @ExchangeRate ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Profit * s.Qty ,
            Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
            ( s.Profit * s.Qty ) / @ExchangeRate ,
            ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateLL ,
            ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Insert detial serial

      INSERT INTO Invoices.t_SoldReturnDetailSerial
          ( SoldReturnID ,
            SoldReturnDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update item serial

      MERGE Items.t_ItemSerial AS t
      USING @SerialIs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET IsAvailable = 1 ,
                    t.ItemID = s.ItemID;

    END;

    EXECUTE Invoices.s_SoldReturnDetailUpdateSerialNamesPART @SerialIs;
   
    EXECUTE Invoices.s_SoldReturnDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Rebuild statistics

      UPDATE Invoices.t_SoldReturn
        SET TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalD = Total / ExchangeRate ,
            TotalLL = ( Total / ExchangeRate ) * @ExchangeRateLL ,
            TotalEuro = ( Total / ExchangeRate ) * @ExchangeRateEuro ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            DiscountIsD = DiscountIs / ExchangeRate ,
            DiscountIsLL = ( DiscountIs / ExchangeRate ) * @ExchangeRateLL ,
            DiscountIsEuro = ( DiscountIs / ExchangeRate ) * @ExchangeRateEuro ,
            TaxRate = Calculation.GetRate(TaxValue, NetIs - TaxValue) ,
            TaxRateF = Calculation.GetRateF(TaxValue, NetIs - TaxValue) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            TaxValueD = TaxValue / ExchangeRate ,
            TaxValueLL = ( TaxValue / ExchangeRate ) * @TaxExchangeRateLL ,
            TaxValueEuro = ( TaxValue / ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsD = NetIs / ExchangeRate ,
            NetIsLL = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateLL ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            NetIsEuro = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateEuro ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            ProfitD = Profit / ExchangeRate ,
            ProfitLL = ( Profit / ExchangeRate ) * @ExchangeRateLL ,
            ProfitEuro = ( Profit / ExchangeRate ) * @ExchangeRateEuro ,
            CostF = Currencys.f_Format(CurrencyID, Cost) ,
            CostD = Cost / ExchangeRate ,
            CostLL = ( Cost / ExchangeRate ) * @ExchangeRateLL ,
            CostEuro = ( Cost / ExchangeRate ) * @ExchangeRateEuro ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            FirstPaymentD = FirstPayment / ExchangeRate ,
            FirstPaymentLL = ( FirstPayment / ExchangeRate ) * @ExchangeRateLL ,
            FirstPaymentEuro = ( FirstPayment / ExchangeRate ) * @ExchangeRateEuro ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM @DetailIs AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM @DetailIs AS s
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END
        WHERE ID = @ID;

    END;
	      	
    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @Net > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @Net;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Sell;
        EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @Tax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        IF @NetNonTaxable > 0
        BEGIN --Insert detail 

          SET @V = @NetNonTaxable;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @NonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;

        IF @Tax > 0
        BEGIN --Insert detail tax

          SET @V = @NetTaxableWithoutTax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @TaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Tax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref);
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;

      END;

    END;

    IF @Payment > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'PV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'PV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        IF ( @Payment = @Net AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @Payment <= @Net - @Tax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          SET @V = @Payment;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box;
          EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;
        ELSE
        BEGIN

          SET @V = @Payment - @Tax;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box;
          EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Payment - @V;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;



      END;

    END;
 
    IF @CommissionValue > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              LinkTypeSub ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              7 ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @CommissionValue;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + N' (' + Currencys.f_Format(@CID, @Net) + N' | ' + Currencys.f_FormatRate(@CommissionRate) + N' ' + Currencys.f_Format(@CID, @V) + ') \ ' + Company.f_AccountGetName(@AccountCustomerID);
        EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountSalespersonID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountSalespersonSellID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;
	         
    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix t_Transaction

      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET SoldReturnC += 1 ,
            SoldReturnTotal = CASE CurrencyTypeIs
                                WHEN 0 THEN @NetD
                                WHEN 1 THEN @NetD * Currencys.f_CurrencyGetExchangeRateLL()
                                ELSE @NetD * Currencys.f_CurrencyGetExchangeRateEuro()
                              END ,
            SoldReturnProfit = CASE CurrencyTypeIs
                                 WHEN 0 THEN @ProfitD
                                 WHEN 1 THEN @ProfitD * Currencys.f_CurrencyGetExchangeRateLL()
                                 ELSE @ProfitD * Currencys.f_CurrencyGetExchangeRateEuro()
                               END ,
            SoldReturnLast = [Invoices].f_SoldReturnGetLastDateByAccountCustomerID(ID)
        WHERE ID = @AccountCustomerID;

      UPDATE Company.t_Account
        SET SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
            SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit)
        WHERE ID = @AccountCustomerID;

    END;

	--Insert t_CustomersInvoicesPoints
    SET @PointsIs = 0 - @PointsIs;
    EXECUTE Customers.s_CustomersInvoicesPointsInsertPART @CustomerID, @DateIs, 1, @ID, @PointsIs, @UserID, @PointsEvent, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnMovingInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnMovingInsert]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Invoices.t_SoldReturnMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, @ID, @Event, 3, @ComputerIP, @Computer, @ComputerAccount);

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, ReturnSold, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;
















GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnMovingInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnMovingInserts]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @IDs Alls.tt_Guid READONLY
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Invoices.t_SoldReturnMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            SELECT @UserID,
                   s.ID,
                   @Event,
                   3,
                   @ComputerIP,
                   @Computer,
                   @ComputerAccount
            FROM @IDs AS s;

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, ReturnSold, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        SELECT 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        SELECT @Return;

    END CATCH;

END;
















