/****** Object:  StoredProcedure [Invoices].[s_SoldReturnPaidUpDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnPaidUpDelete] @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @TransactionID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	   
      DECLARE @TrnRefF NVARCHAR(MAX) ,
        @DateOnly_Old DATE ,
        @PaidUp FLOAT ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @TrnLinkType INT = 3 ,
        @TrnLinkTypeSub TINYINT = 19 ,
        @return INT = 0;

    END;

    BEGIN --Set info
	   
      SELECT TOP ( 1 ) @DateOnly_Old = s.DateOnly
        FROM Invoices.t_SoldReturn AS s
        WHERE s.ID = @ID;

      SELECT @TrnRefF = MIN(s1.RefF) ,
          @PaidUp = ISNULL(SUM(s.Balance), 0) ,
          @PaidUpD = ISNULL(SUM(s.BalanceD), 0) ,
          @PaidUpLL = ISNULL(SUM(s.BalanceLL), 0) ,
          @PaidUpEuro = ISNULL(SUM(s.BalanceEuro), 0)
        FROM Transactions.t_TransactionDetail AS s
        INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
        WHERE s1.ID = @TransactionID AND s.Balance > 0 AND s1.LinkType = @TrnLinkType AND s1.LinkTypeSub = @TrnLinkTypeSub AND s1.LinkID = @ID;

    END;

    BEGIN --Update

      UPDATE Invoices.t_SoldReturn
        SET PaidUp -= @PaidUp ,
            PaidUpD -= @PaidUpD ,
            PaidUpLL -= @PaidUpLL ,
            PaidUpEuro -= @PaidUpEuro
        WHERE ID = @ID;
	    
      UPDATE Invoices.t_SoldReturn
        SET PaidUpF = Currencys.f_Format(CurrencyID, PaidUp) ,
            Rest = NetIs - PaidUp ,
            RestF = Currencys.f_Format(CurrencyID, NetIsD - PaidUpD) ,
            RestD = NetIsD - PaidUpD ,
            RestLL = NetIsLL - PaidUpLL ,
            RestEuro = NetIsEuro - PaidUpEuro
        WHERE ID = @ID;  

      UPDATE Invoices.t_SoldReturn
        SET Paid = IIF(Rest = NetIs AND NetIs > 0, 0, IIF(Rest > 0, 1, 2))
        WHERE ID = @ID;  
	    
    END;
	
    BEGIN --Insert t_SoldReturnMoving

      SET @return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
 
    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE ID = @TransactionID;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @TransactionID ,
            @EventBase + N': ' + @TrnRefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly_Old;
	
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnPaidUpNew]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnPaidUpNew] @AccountBoxID UNIQUEIDENTIFIER ,
  @PaidUp FLOAT ,
  @DateIs DATETIME ,
  @DescriptionIs NVARCHAR(MAX) ,
  @TransactionID UNIQUEIDENTIFIER ,
  @TransactionDetail Transactions.dt_TransactionDetail READONLY ,
  @SchedulePaymentsID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @EventTypeTransaction TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateOnly_Old DATE ,
        @PaidUpD FLOAT ,
        @PaidUpLL FLOAT ,
        @PaidUpEuro FLOAT ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @return INT = 0;
		
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @DateOnly_Old = s.DateOnly ,
          @CID = s.CurrencyID ,
          @E = s.ExchangeRate ,
          @ELL = s.ExchangeRateLL ,
          @EEuro = s.ExchangeRateEuro
        FROM Invoices.t_SoldReturn AS s
        WHERE s.ID = @ID;
   
      SET @PaidUpD = @PaidUp / @E;
      SET @PaidUpLL = @PaidUpD * @ELL;
      SET @PaidUpEuro = @PaidUpD * @EEuro;
	      
    END;

    BEGIN --Update t_SoldReturn

      UPDATE Invoices.t_SoldReturn
        SET PaidUp += @PaidUp ,
            PaidUpF = Currencys.f_Format(@CID, PaidUp + @PaidUp) ,
            PaidUpD += @PaidUpD ,
            PaidUpLL += @PaidUpLL ,
            PaidUpEuro += @PaidUpEuro ,
            Rest -= @PaidUp ,
            RestF = Currencys.f_Format(@CID, Rest - @PaidUp) ,
            RestD -= @PaidUpD ,
            RestLL -= @PaidUpLL ,
            RestEuro -= @PaidUpEuro ,
            Paid = IIF(( Rest - @PaidUp ) = 0, 2, 1)
        WHERE ID = @ID;
	
    END;

    BEGIN --Insert t_SoldReturnMoving

      SET @return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    EXECUTE Transactions.s_TransactionInsertPart @TransactionID, 'PV', 0, @DateIs, @UserID, @DescriptionIs, 3, 19, @ID, @ID, @TransactionDetail, @Event, @EventTypeTransaction, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Currencys.s_SchedulePaymentsDeletePART @SchedulePaymentsID;

    EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly_Old;
	   
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldReturnRebuildingStatistics]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;

        DISABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;

        BEGIN --Rebuild statistics

            SET @Return = 0;

            UPDATE Invoices.t_SoldReturn
            SET RefF = FORMAT(Ref, '#'),
                UserIs = Users.f_UserGetName(UserID),
                CommissionRateF = Currencys.f_FormatRate(CommissionRate),
                CommissionValueF = Currencys.f_Format(CurrencyID, CommissionValue),
                AccountCustomer = Company.f_AccountGetName(AccountCustomerID),
                AccountBox = Company.f_AccountGetName(AccountBoxID),
                Currency = Currencys.f_CurrencyGetName(CurrencyID),
                TotalF = Currencys.f_Format(CurrencyID, Total),
                DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs),
                TaxValueF = Currencys.f_Format(CurrencyID, TaxValue),
                NetIsF = Currencys.f_Format(CurrencyID, NetIs),
                NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1),
                NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1),
                ProfitF = Currencys.f_Format(CurrencyID, Profit),
                FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment),
                PaidUpF = Currencys.f_Format(CurrencyID, PaidUp),
                RestF = Currencys.f_Format(CurrencyID, Rest),
                ItemsNames = Alls.f_FixXML(
                             (
                                 SELECT DISTINCT
                                        ', ' + t1.Name AS [text()]
                                 FROM Invoices.t_SoldReturnDetail AS t
                                     LEFT JOIN Items.t_ItemShared AS t1
                                         ON t1.ID = t.ItemSharedID
                                 WHERE t.SoldReturnID = t_SoldReturn.ID
                                 FOR XML PATH('')
                             )
                                          ),
                ItemHaveDiscount = CASE
                                   (
                                       SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                       FROM Invoices.t_SoldReturnDetail AS s
                                       WHERE s.SoldReturnID = t_SoldReturn.ID
                                   )
                                       WHEN 0 THEN
                                           0
                                       ELSE
                                           1
                                   END;

            UPDATE Invoices.t_SoldReturn
            SET TaxRateF = FORMAT((TaxValue / (NetIs - TaxValue)) * 100.0, '0.##') + N' %'
            WHERE NetIs > 0;

            WITH o
            AS (SELECT s.Price,
                       s.PriceF,
                       s.DiscountIs,
                       s.DiscountIsF,
                       s.DiscountIsValue,
                       s.DiscountIsValueF,
                       s.SubTotal,
                       s.SubTotalF,
                       s.DiscountInvoice,
                       s.DiscountInvoiceF,
                       s.TaxRate,
                       s.TaxRateF,
                       s.TaxValue,
                       s.Total,
                       s.TotalF,
                       s.Cost,
                       s.CostF,
                       s.Profit,
                       s.ProfitF,
                       s.ProfitTotal,
                       s.ProfitTotalF,
                       s1.CurrencyID,
                       s.Qty,
                       s.Qtys,
                       s.QtyWithUnity,
                       s3.Name AS Unity
                FROM Invoices.t_SoldDetail AS s
                    LEFT JOIN Invoices.t_Sold AS s1
                        ON s1.ID = s.SoldID
                    LEFT JOIN Items.t_UnityItem AS s2
                        ON s2.ID = s.ItemUnityID
                    LEFT JOIN Items.t_Unity AS s3
                        ON s3.ID = s2.UnityID)
            UPDATE o
            SET o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price),
                o.DiscountIsF = Currencys.f_FormatRate(o.DiscountIs) ,
                o.DiscountIsValueF = Currencys.f_Format(o.CurrencyID, o.DiscountIsValue),
                o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal),
                o.DiscountInvoiceF = Currencys.f_Format(o.CurrencyID, o.DiscountInvoice),
                o.TaxRateF = Currencys.f_FormatRate(o.TaxRate) ,
                o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total),
                o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost),
                o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit),
                o.ProfitTotalF = Currencys.f_Format(o.CurrencyID, o.ProfitTotal),
                o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Invoices.t_SoldReturnMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, '00000000-0000-0000-0000-000000000000', @Event, 6, @ComputerIP, @Computer, @ComputerAccount);

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, ReturnSold, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        ENABLE TRIGGER Invoices.tr_SoldReturn ON Invoices.t_SoldReturn;

        ENABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;







GO
/****** Object:  StoredProcedure [Invoices].[s_SoldReturnUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldReturnUpdate] @RefPaper NVARCHAR(MAX) ,
  @InvoiceTitleID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @AccountSalespersonID UNIQUEIDENTIFIER ,
  @AccountSalespersonSellID UNIQUEIDENTIFIER ,
  @CommissionRate DECIMAL(4, 2) ,
  @CommissionRateF NVARCHAR(MAX) ,
  @CommissionRateOn TINYINT ,
  @CommissionValue FLOAT ,
  @CommissionValueF NVARCHAR(MAX) ,
  @CommissionValueD FLOAT ,
  @CommissionValueLL FLOAT ,
  @CommissionValueEuro FLOAT ,
  @AccountCustomerID UNIQUEIDENTIFIER ,
  @ContactPerson NVARCHAR(MAX) ,
  @AccountCustomerTaxID UNIQUEIDENTIFIER ,
  @CustomerID UNIQUEIDENTIFIER ,
  @NonTaxableAccountID UNIQUEIDENTIFIER ,
  @TaxableAccountID UNIQUEIDENTIFIER ,
  @BoxID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @Payment FLOAT ,
  @Net FLOAT ,
  @NetNonTaxable FLOAT ,
  @NetTaxableWithoutTax FLOAT ,
  @Tax FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @DiscountIs FLOAT ,
  @PaidUp FLOAT ,
  @PaidUpF NVARCHAR(MAX) ,
  @PaidUpD FLOAT ,
  @PaidUpLL FLOAT ,
  @PaidUpEuro FLOAT ,
  @Rest FLOAT ,
  @RestF NVARCHAR(MAX) ,
  @RestD FLOAT ,
  @RestLL FLOAT ,
  @RestEuro FLOAT ,
  @Paid TINYINT ,
  @GhanaSystem BIT ,
  @GS_Covid19Rate FLOAT ,
  @GS_NHILRate FLOAT ,
  @GS_GetfundLevyRate FLOAT ,
  @GS_TaxRate FLOAT ,
  @GS_Reverse FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @PointsIs FLOAT ,
  @PointsEvent NVARCHAR(MAX) ,
  @DetailIs Invoices.tt_SoldReturnDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate Items.tt_ItemExpirationDate READONLY ,
  @StatementIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventInsert NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Ref BIGINT ,
        @DateOnly DATE = @DateIs ,
        @DateOnly_Old DATE ,
        @CustomerIDOld UNIQUEIDENTIFIER ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @TransactionRefJV BIGINT ,
        @TransactionRefPV BIGINT ,
        @RowNumber INT ,
        @Customer NVARCHAR(MAX) ,
        @AccountTax NVARCHAR(MAX) ,
        @Sell NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @return INT = 0 ,
        @LinkType INT = 3 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @VLL FLOAT ,
        @VEuro FLOAT ,
        @StatementIs_ NVARCHAR(MAX);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @TransactionRefJV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'JV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;

      SELECT TOP ( 1 ) @TransactionRefPV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'PV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;

      SET @Customer = Company.f_AccountGetName(@AccountCustomerID);

      SET @AccountTax = Company.f_AccountGetName(@AccountCustomerTaxID);

      SET @Sell = Company.f_AccountGetName(@NonTaxableAccountID);

      SET @Box = Company.f_AccountGetName(@BoxID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);
      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);

      IF @CurrencyTypeIs <> 0
      BEGIN

        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Invoices.t_SoldReturnDetail AS s
          WHERE s.SoldReturnID = @ID;

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @DateOnly_Old = s.DateOnly ,
          @CustomerIDOld = s.AccountCustomerID
        FROM Invoices.t_SoldReturn AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

    END;

    BEGIN --Declare and Set ItemExpirationDate

      DECLARE @ItemExpirationDate_Old [Items].[tt_ItemExpirationDate];
    
      INSERT INTO @ItemExpirationDate_Old
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID ,
            OriginalID ,
            FatherID1 ,
            FatherID2 ,
            EventIs
		  )
        SELECT t.ID ,
            0 ,
            N'' ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WareHouseID ,
            t1.Name ,
            t.PlaceID ,
            t2.Name ,
            t.SectionIs ,
            t.SectionID ,
            t.Barcode ,
            t.Qtys ,
            t.ProductionDate ,
            t.ExpirationDate ,
            t.NotifyMeDaysBefore ,
            t.NotificationDate ,
            t.CurrencyID ,
            t3.Name ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.BatchNumber ,
            t.DescriptionIs ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID ,
            t.OriginalID ,
            t.SoldReturnID ,
            t.SoldReturnDetailID ,
            N''
          FROM Invoices.t_SoldReturnDetailExpirationDate AS t
          INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WareHouseID
          INNER JOIN Company.t_Place AS t2 ON t2.ID = t.PlaceID
          INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t.CurrencyID
          WHERE t.SoldReturnID = @ID;

    END;

    BEGIN --Update

      UPDATE Invoices.t_SoldReturn
        SET RefPaper = @RefPaper ,
            InvoiceTitleID = @InvoiceTitleID ,
            InvoiceTitle = Invoices.f_InvoiceTitleGetName(@InvoiceTitleID) ,
            DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            SalespersonID = @SalespersonID ,
            CommissionRate = @CommissionRate ,
            CommissionRateF = @CommissionRateF ,
            CommissionRateOn = @CommissionRateOn ,
            CommissionValue = @CommissionValue ,
            CommissionValueF = @CommissionValueF ,
            CommissionValueD = @CommissionValueD ,
            CommissionValueLL = @CommissionValueLL ,
            CommissionValueEuro = @CommissionValueEuro ,
			NonTaxableAccountID = @NonTaxableAccountID ,
			TaxableAccountID = @TaxableAccountID ,
            AccountCustomerID = @AccountCustomerID ,
            AccountCustomer = Company.f_AccountGetName(@AccountCustomerID) ,
            AccountCustomerNumber = Company.f_AccountGetNumberF(@AccountCustomerID) ,
            ContactPerson = @ContactPerson ,
            AccountBoxID = @BoxID ,
            AccountBox = Company.f_AccountGetName(@BoxID) ,
            AccountBoxNumber = Company.f_AccountGetNumberF(@BoxID) ,
            PaymentMethod = @PaymentMethod ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            TaxExchangeRateLL = @TaxExchangeRateLL ,
            TaxExchangeRateEuro = @TaxExchangeRateEuro ,
            Total = ( SELECT COALESCE(SUM(s.SubTotal), 0)
                        FROM @DetailIs AS s
                    ) ,
            DiscountIs = @DiscountIs ,
            TaxValue = @Tax ,
            NetIs = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM @DetailIs AS s
                    ) ,
            Profit = ( SELECT COALESCE(SUM(s.ProfitTotal), 0)
                        FROM @DetailIs AS s
                     ) ,
            PaidUp = @PaidUp ,
            PaidUpF = @PaidUpF ,
            PaidUpD = @PaidUpD ,
            PaidUpLL = @PaidUpLL ,
            PaidUpEuro = @PaidUpEuro ,
            Rest = @Rest ,
            RestF = @RestF ,
            RestD = @RestD ,
            RestLL = @RestLL ,
            RestEuro = @RestEuro ,
            Paid = @Paid ,
            Cost = ( SELECT COALESCE(SUM(s.Cost), 0)
                      FROM @DetailIs AS s
                   ) ,
            GhanaSystem = @GhanaSystem ,
            GS_Covid19Rate = @GS_Covid19Rate ,
            GS_NHILRate = @GS_NHILRate ,
            GS_GetfundLevyRate = @GS_GetfundLevyRate ,
            GS_TaxRate = @GS_TaxRate ,
            GS_Reverse = @GS_Reverse ,
            Qtys = ( SELECT COALESCE(SUM(s.Qtys), 0)
                      FROM @DetailIs AS s
                   ) ,
            DescriptionIs = @DescriptionIs ,
            FirstPayment = @Payment
        WHERE ID = @ID;

    END;

    BEGIN --Insert detail

      MERGE Invoices.t_SoldReturnDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 SoldReturnID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 PackUnitID ,
                 PackUnitQty ,
                 PackQtys ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 PriceLL ,
                 PriceEuro ,
                 DiscountIs ,
                 DiscountIsF ,
                 DiscountIsValue ,
                 DiscountIsValueF ,
                 DiscountIsValueD ,
                 DiscountIsValueLL ,
                 DiscountIsValueEuro ,
                 SubTotal ,
                 SubTotalF ,
                 SubTotalD ,
                 SubTotalLL ,
                 SubTotalEuro ,
                 DiscountInvoice ,
                 DiscountInvoiceF ,
                 DiscountInvoiceD ,
                 DiscountInvoiceLL ,
                 DiscountInvoiceEuro ,
                 TaxRate ,
                 TaxRateF ,
                 TaxValue ,
                 TaxValueF ,
                 TaxValueD ,
                 TaxValueLL ,
                 TaxValueEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 Cost ,
                 CostF ,
                 CostD ,
                 CostLL ,
                 CostEuro ,
                 Profit ,
                 ProfitF ,
                 ProfitD ,
                 ProfitLL ,
                 ProfitEuro ,
                 ProfitTotal ,
                 ProfitTotalF ,
                 ProfitTotalD ,
                 ProfitTotalLL ,
                 ProfitTotalEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.PackUnitID ,
                 s.PackUnitQty ,
                 s.PackQtys ,
                 s.Qty ,
                 Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                 s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs) ,
                 s.DiscountIsValue ,
                 Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                 s.DiscountIsValue / @ExchangeRate ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                 ( s.Price * s.Qty ) - s.DiscountIsValue ,
                 Currencys.f_Format(@CurrencyID, ( s.Price * s.Qty ) - s.DiscountIsValue) ,
                 ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ,
                 ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( ( ( s.Price * s.Qty ) - s.DiscountIsValue ) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DiscountInvoice ,
                 Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
                 s.DiscountInvoice / @ExchangeRate ,
                 ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRate ,
                 ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.TaxRate ,
                 Currencys.f_FormatRate(s.TaxRate) ,
                 s.TaxValue ,
                 Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                 s.TaxValue / @ExchangeRate ,
                 ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
                 ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
                 s.Total ,
                 Currencys.f_Format(@CurrencyID, s.Total) ,
                 s.Total / @ExchangeRate ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Cost ,
                 Currencys.f_Format(@CurrencyID, s.Cost) ,
                 s.Cost / @ExchangeRate ,
                 ( s.Cost / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Cost / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Profit ,
                 Currencys.f_Format(@CurrencyID, s.Profit) ,
                 s.Profit / @ExchangeRate ,
                 ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Profit * s.Qty ,
                 Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
                 ( s.Profit * s.Qty ) / @ExchangeRate ,
                 ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateLL ,
                 ( ( s.Profit * s.Qty ) / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemID = s.ItemID ,
                    t.ItemUnityID = s.ItemUnityID ,
                    t.PackUnitID = s.PackUnitID ,
                    t.PackUnitQty = s.PackUnitQty ,
                    t.PackQtys = s.PackQtys ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                    t.Qtys = s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.PriceLL = ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs) ,
                    t.DiscountIsValue = s.DiscountIsValue ,
                    t.DiscountIsValueF = Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                    t.DiscountIsValueD = s.DiscountIsValue / @ExchangeRate ,
                    t.DiscountIsValueLL = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                    t.DiscountIsValueEuro = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.SubTotal = s.SubTotal ,
                    t.SubTotalF = Currencys.f_Format(@CurrencyID, s.SubTotal) ,
                    t.SubTotalD = s.SubTotal / @ExchangeRate ,
                    t.SubTotalLL = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
                    t.SubTotalEuro = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DiscountInvoice = s.DiscountInvoice ,
                    t.DiscountInvoiceF = Currencys.f_Format(@CurrencyID, s.DiscountInvoice) ,
                    t.DiscountInvoiceD = s.DiscountInvoice / @ExchangeRate ,
                    t.DiscountInvoiceLL = ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateLL ,
                    t.DiscountInvoiceEuro = ( s.DiscountInvoice / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.TaxRate = s.TaxRate ,
                    t.TaxRateF = Currencys.f_FormatRate(s.TaxRate) ,
                    t.TaxValue = s.TaxValue ,
                    t.TaxValueF = Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                    t.TaxValueD = s.TaxValue / @ExchangeRate ,
                    t.TaxValueLL = ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
                    t.TaxValueEuro = ( s.TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
                    t.Total = s.Total ,
                    t.TotalF = Currencys.f_Format(@CurrencyID, s.Total) ,
                    t.TotalD = s.Total / @ExchangeRate ,
                    t.TotalLL = ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TotalEuro = ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Cost = s.Cost ,
                    t.CostF = Currencys.f_Format(@CurrencyID, s.Cost) ,
                    t.CostD = s.Cost / @ExchangeRate ,
                    t.CostLL = ( s.Cost / @ExchangeRate ) * @ExchangeRateLL ,
                    t.CostEuro = ( s.Cost / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Profit = s.Profit ,
                    t.ProfitF = Currencys.f_Format(@CurrencyID, s.Profit) ,
                    t.ProfitD = s.Profit / @ExchangeRate ,
                    t.ProfitLL = ( s.Profit / @ExchangeRate ) * @ExchangeRateLL ,
                    t.ProfitEuro = ( s.Profit / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.ProfitTotal = s.Profit * s.Qty ,
                    t.ProfitTotalF = Currencys.f_Format(@CurrencyID, s.Profit * s.Qty) ,
                    t.ProfitTotalD = s.Profit * s.Qty / @ExchangeRate ,
                    t.ProfitTotalLL = ( s.Profit * s.Qty / @ExchangeRate ) * @ExchangeRateLL ,
                    t.ProfitTotalEuro = ( s.Profit * s.Qty / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.SoldReturnID = @ID THEN
        DELETE;
		
    END;

    BEGIN --Insert detial serial

      INSERT INTO Invoices.t_SoldReturnDetailSerial
          ( SoldReturnID ,
            SoldReturnDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update item serial

      MERGE Items.t_ItemSerial AS t
      USING @SerialIs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET IsAvailable = 1 ,
                    t.ItemID = s.ItemID;

    END;

    EXECUTE Invoices.s_SoldReturnDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_SoldReturnDetailExpirationDateUpdatePART @ItemExpirationDate_Old, @ItemExpirationDate, @ID;

    BEGIN --Rebuild statistics

      UPDATE Invoices.t_SoldReturn
        SET TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalD = Total / ExchangeRate ,
            TotalLL = ( Total / ExchangeRate ) * @ExchangeRateLL ,
            TotalEuro = ( Total / ExchangeRate ) * @ExchangeRateEuro ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            DiscountIsD = DiscountIs / ExchangeRate ,
            DiscountIsLL = ( DiscountIs / ExchangeRate ) * @ExchangeRateLL ,
            DiscountIsEuro = ( DiscountIs / ExchangeRate ) * @ExchangeRateEuro ,
            TaxRate = Calculation.GetRate(TaxValue, NetIs - TaxValue) ,
            TaxRateF = Calculation.GetRateF(TaxValue, NetIs - TaxValue) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            TaxValueD = TaxValue / ExchangeRate ,
            TaxValueLL = ( TaxValue / ExchangeRate ) * @TaxExchangeRateLL ,
            TaxValueEuro = ( TaxValue / ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsD = NetIs / ExchangeRate ,
            NetIsLL = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateLL ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateLL ,
            NetIsEuro = ( ( ( NetIs - TaxValue ) / ExchangeRate ) * @ExchangeRateEuro ) + ( TaxValue / @ExchangeRate ) * @TaxExchangeRateEuro ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            ProfitF = Currencys.f_Format(CurrencyID, Profit) ,
            ProfitD = Profit / ExchangeRate ,
            ProfitLL = ( Profit / ExchangeRate ) * @ExchangeRateLL ,
            ProfitEuro = ( Profit / ExchangeRate ) * @ExchangeRateEuro ,
            CostF = Currencys.f_Format(CurrencyID, Cost) ,
            CostD = Cost / ExchangeRate ,
            CostLL = ( Cost / ExchangeRate ) * @ExchangeRateLL ,
            CostEuro = ( Cost / ExchangeRate ) * @ExchangeRateEuro ,
            FirstPaymentF = Currencys.f_Format(CurrencyID, FirstPayment) ,
            FirstPaymentD = FirstPayment / ExchangeRate ,
            FirstPaymentLL = ( FirstPayment / ExchangeRate ) * @ExchangeRateLL ,
            FirstPaymentEuro = ( FirstPayment / ExchangeRate ) * @ExchangeRateEuro ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM @DetailIs AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM @DetailIs AS s
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END
        WHERE ID = @ID;

    END;
    
	BEGIN--Item Qtys
   
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_SoldReturnMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Delete old transaction

      DELETE FROM Transactions.t_Transaction
        WHERE LinkType = 3 AND LinkID = @ID;

    END;

    IF @Net > 0
    BEGIN --Transaction

      SET @TransactionRef = @TransactionRefJV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'JV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @Net;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Sell;
        EXECUTE Transactions.s_TransactionDetailInsertCreditTax @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @Tax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        IF @NetNonTaxable > 0
        BEGIN --Insert detail 

          SET @V = @NetNonTaxable;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @NonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;

        IF @Tax > 0
        BEGIN --Insert detail tax

          SET @V = @NetTaxableWithoutTax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @TaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Tax;
          SET @RowNumber += 1;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref);
          EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;

      END;

    END;

    IF @Payment > 0
    BEGIN --Transaction

      SET @TransactionRef = @TransactionRefPV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'PV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              TypeIs ,
              DateIs ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              N'PV' ,
              @DateIs ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        IF ( @Payment = @Net AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @Payment <= @Net - @Tax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          SET @V = @Payment;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box;
          EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        END;
        ELSE
        BEGIN

          SET @V = @Payment - @Tax;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box;
          EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer;
          EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          SET @V = @Payment - @V;
          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Box + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

          SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @Customer + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
          EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @BoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

        END;



      END;

    END;

    IF @CommissionValue > 0
    BEGIN --Transaction

      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              LinkTypeSub ,
              UserID
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @Ref) ,
              @LinkType ,
              @ID ,
              7 ,
              @UserID
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail

        SET @V = @CommissionValue;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + N' (' + Currencys.f_Format(@CID, @Net) + N' | ' + Currencys.f_FormatRate(@CommissionRate) + N' ' + Currencys.f_Format(@CID, @V) + ') \ ' + Company.f_AccountGetName(@AccountCustomerID);
        EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountSalespersonID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountSalespersonSellID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;
	         
    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix t_Transaction

      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET SoldReturnTotal = Invoices.f_SoldReturnGetTotalByAccountCustomerID(ID) ,
            SoldReturnProfit = Invoices.f_SoldReturnGetProfitByAccountCustomerID(ID) ,
            SoldReturnLast = Invoices.f_SoldReturnGetLastDateByAccountCustomerID(ID)
        WHERE ID = @AccountCustomerID OR ID = @CustomerIDOld;

      UPDATE Company.t_Account
        SET SoldReturnTotalF = Currencys.f_Format(CurrencyID, SoldReturnTotal) ,
            SoldReturnProfitF = Currencys.f_Format(CurrencyID, SoldReturnProfit)
        WHERE ID = @AccountCustomerID OR ID = @CustomerIDOld;

    END;

	--Insert t_CustomersInvoicesPoints
    SET @PointsIs = 0 - @PointsIs;
    EXECUTE Customers.s_CustomersInvoicesPointsReinsertPART @CustomerID, @DateIs, 0, @ID, @PointsIs, @UserID, @PointsEvent, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    IF @DateOnly_OLD = @DateOnly
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly_OLD;
      EXECUTE Invoices.s_ProfitDaily_SalesReturnsInvoices_Update_PART @DateOnly;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;













