/****** Object:  StoredProcedure [Invoices].[s_SoldUnsavedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldUnsavedMerge] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @PCName NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @DiscountIs FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @Detail Invoices.tt_SoldUnsavedDetail READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Merge

      MERGE Invoices.t_SoldUnsaved AS t
      USING
        ( SELECT @ID AS ID
        ) AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 UserID ,
                 PCName ,
                 CurrencyID ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 TaxExchangeRateLL ,
                 TaxExchangeRateEuro ,
                 DiscountIs ,
                 TotalF ,
                 ItemsCount
               )
        VALUES ( @ID ,
                 @UserID ,
                 @PCName ,
                 @CurrencyID ,
                 @ExchangeRateLL ,
                 @ExchangeRateEuro ,
                 @TaxExchangeRateLL ,
                 @TaxExchangeRateEuro ,
                 @DiscountIs ,
                 @TotalF ,
                 @ItemsCount
          
               )
      WHEN MATCHED THEN
        UPDATE SET t.DateIs = GETDATE() ,
                    t.UserID = @UserID ,
                    t.PCName = @PCName ,
                    t.CurrencyID = @CurrencyID ,
                    t.ExchangeRateLL = @ExchangeRateLL ,
                    t.ExchangeRateEuro = @ExchangeRateEuro ,
                    t.TaxExchangeRateLL = @TaxExchangeRateLL ,
                    t.TaxExchangeRateEuro = @TaxExchangeRateEuro ,
                    t.DiscountIs = @DiscountIs ,
                    t.TotalF = @TotalF ,
                    t.ItemsCount = @ItemsCount;

    END;

    BEGIN --Reinsert t_SoldUnsavedDetail
	
      DELETE FROM Invoices.t_SoldUnsavedDetail
        WHERE SoldUnsavedID = @ID;

      INSERT Invoices.t_SoldUnsavedDetail
          ( SoldUnsavedID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            UnitSalePrice ,
            UnitSalePriceF ,
            DiscountIs ,
            TaxRate ,
            TotalF ,
            UnitCost ,
            TotalCost ,
            DescriptionIs ,
            SortAt 
	      )
        SELECT @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            s.UnitSalePrice ,
            s.UnitSalePriceF ,
            s.DiscountIs ,
            s.TaxRate ,
            s.TotalF ,
            s.UnitCost ,
            s.TotalCost ,
            s.DescriptionIs ,
            s.SortAt
          FROM @Detail AS s;

    END;

    EXECUTE Invoices.s_SoldUnsavedLiveVersion;
    EXECUTE Invoices.s_SoldUnsavedDetailLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;




GO
