CREATE PROCEDURE [Invoices].[s_SoldUpdate] @RefPaper NVARCHAR(MAX) ,
  @RefPurchaseOrder NVARCHAR(MAX) ,
  @Legal BIT ,
  @InvoiceTitleID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @DueDate DATE ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @CommissionRate DECIMAL(18, 2) ,
  @CommissionRateType TINYINT ,
  @CommissionRateOn TINYINT ,
  @AccountCustomerID UNIQUEIDENTIFIER ,
  @ContactPerson NVARCHAR(MAX) ,
  @AccountCustomerTaxID UNIQUEIDENTIFIER ,
  @CustomerID UNIQUEIDENTIFIER ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @AccountSellNonTaxableID UNIQUEIDENTIFIER ,
  @AccountSellTaxableID UNIQUEIDENTIFIER ,
  @PaymentMethod TINYINT ,
  @PricingType TINYINT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TaxExchangeRateLL FLOAT ,
  @TaxExchangeRateEuro FLOAT ,
  @TaxExchangeRateEvent NVARCHAR(MAX) ,
  @Total FLOAT ,
  @DiscountIs FLOAT ,
  @TaxValue FLOAT ,
  @TaxOnTaxRate FLOAT ,
  @TaxOnTaxRateF NVARCHAR(MAX) ,
  @TaxOnTax FLOAT ,
  @TaxOnTaxF NVARCHAR(MAX) ,
  @TaxOnTaxD FLOAT ,
  @TaxOnTaxLL FLOAT ,
  @TaxOnTaxEuro FLOAT ,
  @AllTax FLOAT ,
  @NetIs FLOAT ,
  @Rounding FLOAT ,
  @NetIsNonTaxable FLOAT ,
  @NetIsTaxableWithoutTax FLOAT ,
  @Profit FLOAT ,
  @FirstPayment FLOAT ,
  @SecondPaymentCurrencyID UNIQUEIDENTIFIER ,
  @SecondPaymentCurrency NVARCHAR(MAX) ,
  @SecondPayment FLOAT ,
  @SecondPaymentF NVARCHAR(MAX) ,
  @SecondPaymentD FLOAT ,
  @SecondPaymentLL FLOAT ,
  @SecondPaymentEuro FLOAT ,
  @SecondPaymentAccountBoxID UNIQUEIDENTIFIER ,
  @SecondPaymentAccountBox NVARCHAR(MAX) ,
  @SecondPaymentAccountBoxNumber NVARCHAR(MAX) ,
  @PaidUp FLOAT ,
  @Rest FLOAT ,
  @Paid TINYINT ,
  @Cost FLOAT ,
  @CostF NVARCHAR(MAX) ,
  @CostD FLOAT ,
  @CostLL FLOAT ,
  @CostEuro FLOAT ,
  @CostNonTaxable FLOAT ,
  @CostTaxableWithoutTax FLOAT ,
  @TransactionBetweenGoodsAndPurchase BIT ,
  @GoodsNonTaxableAccountID UNIQUEIDENTIFIER ,
  @GoodsTaxableAccountID UNIQUEIDENTIFIER ,
  @PurchaseNonTaxableAccountID UNIQUEIDENTIFIER ,
  @PurchaseTaxableAccountID UNIQUEIDENTIFIER ,
  @WeReceiveD FLOAT ,
  @WeReceiveLL FLOAT ,
  @WeReceiveEuro FLOAT ,
  @WeReturnedD FLOAT ,
  @WeReturnedLL FLOAT ,
  @WeReturnedEuro FLOAT ,
  @SeparateDeliveryFees FLOAT ,
  @SeparateDeliveryFeesF NVARCHAR(MAX) ,
  @SeparateDeliveryFeesD FLOAT ,
  @SeparateDeliveryFeesLL FLOAT ,
  @SeparateDeliveryFeesEuro FLOAT ,
  @BalanceDifferenceAccountID UNIQUEIDENTIFIER ,
  @BalanceDifference FLOAT ,
  @GhanaSystem BIT ,
  @GS_Covid19Rate FLOAT ,
  @GS_NHILRate FLOAT ,
  @GS_GetfundLevyRate FLOAT ,
  @GS_TaxRate FLOAT ,
  @GS_Reverse FLOAT ,
  @DeliveryStage TINYINT ,
  @DeliveryStageUndelivered TINYINT ,
  @DeliveryDueDate DATE ,
  @DeliveryByEmployeeID UNIQUEIDENTIFIER ,
  @DeliveryDate DATE ,
  @DeliveryDelayedDays INT ,
  @DeliveryNote NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @WFPFrom BIT ,
  @ItemsCount INT ,
  @ItemsNames NVARCHAR(MAX) ,
  @WarehousesNames NVARCHAR(MAX) ,
  @ItemHaveDiscount BIT ,
  @TotalQuantity FLOAT ,
  @PointsIs FLOAT ,
  @PointsEvent NVARCHAR(MAX) ,
  @HasSerial BIT ,
  @DetailIs Invoices.tt_SoldDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate Items.tt_ItemExpirationDate READONLY ,
  @EmployeesWhoHaveProfit NVARCHAR(MAX) ,
  @SoldEmployeeProfit Invoices.tt_SoldEmployeeProfit READONLY ,
  @SoldDetailEmployeeProfit Invoices.tt_SoldDetailEmployeeProfit READONLY ,
  @ProductionWhenSale TINYINT ,
  @StageType TINYINT ,
  @SaveCRM BIT ,
  @StatementIs NVARCHAR(MAX) ,
  @ResetTransactions BIT ,
  @SoldDetailAdditions Invoices.tt_SoldDetailAdditions READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventInsert NVARCHAR(MAX) ,
  @EventInsertBySold NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL
        );

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Ref BIGINT ,
        @LegalRef BIGINT ,
        @LegalRefF NVARCHAR(MAX) ,
        @AnyRef BIGINT ,
        @AnyRefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @DateOnly_OLD DATE ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @RowNumber INT ,
        @AccountSalespersonID UNIQUEIDENTIFIER ,
        @AccountSalespersonSellID UNIQUEIDENTIFIER ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @LinkType INT = 2 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @AccountsNames NVARCHAR(MAX) ,
        @StatementIs_ NVARCHAR(MAX) ,
        @RefF NVARCHAR(MAX) ,
        @InvoiceTitle NVARCHAR(MAX) = Invoices.f_InvoiceTitleGetName(@InvoiceTitleID) ,
        @UserIs NVARCHAR(MAX) = Users.f_UserGetName(@UserID) ,
        @SalesPersonID_OLD UNIQUEIDENTIFIER ,
        @Salesperson NVARCHAR(MAX) = Employees.f_SalesPersonGetName(@SalespersonID) ,
        @AccountCustomer NVARCHAR(MAX) = Company.f_AccountGetName(@AccountCustomerID) ,
        @AccountCustomerNumber NVARCHAR(MAX)  = Company.f_AccountGetNumberF(@AccountCustomerID) ,
        @AccountBox NVARCHAR(MAX)  = Company.f_AccountGetName(@AccountBoxID) ,
        @AccountBoxNumber NVARCHAR(MAX)  = Company.f_AccountGetNumberF(@AccountBoxID) ,
        @CommissionValue FLOAT ,
        @CommissionValueD FLOAT ,
        @CommissionAvailableValue FLOAT ,
        @CommissionAvailableValueD FLOAT ,
        @TotalD FLOAT ,
        @DiscountIsD FLOAT ,
        @TaxValueD FLOAT ,
        @NetIsD FLOAT ,
        @NetIsLL FLOAT ,
        @NetIsEuro FLOAT ,
        @NonTaxableTotal FLOAT = @NetIsNonTaxable ,
        @NonTaxableTotalF NVARCHAR(MAX) ,
        @NonTaxableTotalD FLOAT ,
        @NonTaxableTotalLL FLOAT ,
        @NonTaxableTotalEuro FLOAT ,
        @TaxableTotal FLOAT = @NetIsTaxableWithoutTax ,
        @TaxableTotalF NVARCHAR(MAX) ,
        @TaxableTotalD FLOAT ,
        @TaxableTotalLL FLOAT ,
        @TaxableTotalEuro FLOAT ,
        @RoundingD FLOAT ,
        @RoundingLL FLOAT ,
        @RoundingEuro FLOAT ,
        @ProfitD FLOAT ,
        @ProfitLL FLOAT ,
        @ProfitEuro FLOAT ,
        @FirstPaymentD FLOAT ,
        @AllFirstPayment FLOAT = @FirstPayment + Currencys.f_ChooseValue(@CurrencyID, @SecondPaymentD, @SecondPaymentLL, @SecondPaymentEuro) ,
        @SecondPaymentExchangeRate FLOAT = Currencys.f_ChooseValue(@SecondPaymentCurrencyID, 1, @ExchangeRateLL, @ExchangeRateEuro) ,
        @PaidUpD FLOAT ,
        @RestD FLOAT ,
        @WFPShopID NVARCHAR(MAX) ,
        @WFPBranchID NVARCHAR(MAX) ,
        @TrnRefJV BIGINT ,
        @TrnRefJVSalesperson BIGINT ,
        @TrnRefRV BIGINT ,
        @AccountCustomerIDOld UNIQUEIDENTIFIER ,
        @return INT;

    END;

    BEGIN --Declare and Set ItemExpirationDate

      DECLARE @ItemExpirationDate_Old [Items].[tt_ItemExpirationDate];
    
      INSERT INTO @ItemExpirationDate_Old
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID ,
            OriginalID ,
            FatherID1 ,
            FatherID2 ,
            EventIs
		  )
        SELECT t.ID ,
            0 ,
            N'' ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WareHouseID ,
            t1.Name ,
            t.PlaceID ,
            t2.Name ,
            t.SectionIs ,
            t.SectionID ,
            t.Barcode ,
            t.Qtys ,
            t.ProductionDate ,
            t.ExpirationDate ,
            t.NotifyMeDaysBefore ,
            t.NotificationDate ,
            t.CurrencyID ,
            t3.Name ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.BatchNumber ,
            t.DescriptionIs ,
            t.DateCreate ,
            0 ,
            t.WorkStationID ,
            t.OriginalID ,
            t.SoldID ,
            t.SoldDetailID ,
            N''
          FROM Invoices.t_SoldDetailExpirationDate AS t
          INNER JOIN Company.t_WareHouse AS t1 ON t1.ID = t.WareHouseID
          INNER JOIN Company.t_Place AS t2 ON t2.ID = t.PlaceID
          INNER JOIN Currencys.t_Currency AS t3 ON t3.ID = t.CurrencyID
          WHERE t.SoldID = @ID;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @TrnRefJV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'JV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;
	 
      SELECT TOP ( 1 ) @TrnRefRV = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'RV' AND s.LinkTypeSub = 0
        ORDER BY s.ID;

      SELECT TOP ( 1 ) @TrnRefJVSalesperson = s.Ref
        FROM Transactions.t_Transaction AS s
        WHERE s.LinkType = @LinkType AND s.LinkID = @ID AND s.TypeIs = N'JV' AND s.LinkTypeSub = 7
        ORDER BY s.ID;

      SET @AccountBox = Company.f_AccountGetName(@AccountBoxID);

      SET @AccountSalespersonID = [Company].[f_AccountSalespersonGetID](@SalespersonID);
      SET @AccountSalespersonSellID = [Company].[f_AccountSalespersonSellGetID](@SalespersonID);

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);
      SET @CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(@CurrencyID);
     
	  --TaxCompressed>
      IF @CurrencyTypeIs <> 0
      BEGIN

        SET @TaxExchangeRateLL = @ExchangeRateLL;
        SET @TaxExchangeRateEuro = @ExchangeRateEuro;

      END;
	  --TaxCompressed<

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s
        UNION ALL
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_SoldDetail AS s
          WHERE s.SoldID = @ID;

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @LegalRef = s.LegalRef ,
          @LegalRefF = s.LegalRefF ,
          @AnyRef = s.Ref ,
          @AnyRefF = s.RefF ,
          @DateOnly_OLD = s.DateOnly ,
          @AccountCustomerIDOld = s.AccountCustomerID ,
          @SalespersonID = s.SalespersonID
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      IF @Legal = 1
      BEGIN

        IF @LegalRef <= 0
        BEGIN
	                        
          SELECT @LegalRef = ISNULL(MAX(s.LegalRef), 0) + 1
            FROM Invoices.t_Sold AS s
            WHERE s.Legal = 1;
          SET @LegalRefF = FORMAT(@LegalRef, '#');	  

        END;

        SET @AnyRef = @LegalRef;
        SET @AnyRefF = N'|' + @LegalRefF;

      END;
      ELSE
      BEGIN

        SET @LegalRef = 0;
        SET @LegalRefF = N'';
  
      END;
 
      IF @AccountCustomerID = @AccountCustomerIDOld AND @ResetTransactions = 0
      BEGIN
                                       
        SET @PaidUp += ( SELECT ISNULL(SUM(s.Balance), 0)
                          FROM Transactions.t_TransactionDetail AS s
                          INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                          WHERE s.Balance > 0 AND s1.LinkType = @LinkType AND s1.LinkTypeSub = 12 AND s1.LinkID = @ID
                       );

        SET @Rest = @NetIs - @PaidUp;

      END;
   
      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;

      SET @NetIsD = @NetIs / @E;
      SET @NetIsLL = @NetIsD * @ELL;
      SET @NetIsEuro = @NetIsD * @EEuro;

      SET @NonTaxableTotalF = Currencys.f_Format(@CID, @NonTaxableTotal);
      SET @NonTaxableTotalD = @NonTaxableTotal / @E;
      SET @NonTaxableTotalLL = @NonTaxableTotalD * @ELL;
      SET @NonTaxableTotalEuro = @NonTaxableTotalD * @EEuro;

      SET @TaxableTotalF = Currencys.f_Format(@CID, @TaxableTotal);
      SET @TaxableTotalD = @TaxableTotal / @E;
      SET @TaxableTotalLL = @TaxableTotalD * @ELL;
      SET @TaxableTotalEuro = @TaxableTotalD * @EEuro;

      SET @RoundingD = @Rounding / @E;
      SET @RoundingLL = @RoundingD * @ELL;
      SET @RoundingEuro = @RoundingD * @EEuro;

      SET @CommissionValue = ROUND(CASE @CommissionRateOn
                                     WHEN 0 THEN IIF(@NetIs > 0, @NetIs / 100, 0)
                                     WHEN 1 THEN IIF(@Profit > 0, @Profit / 100, 0)
                                     ELSE IIF(( @NetIs - @AllTax ) > 0, ( @NetIs - @AllTax ) / 100, 0)
                                   END * @CommissionRate, 2);
      SET @CommissionValueD = @CommissionValue / @E;

      SET @CommissionAvailableValue = IIF(@CommissionRateType = 0, @CommissionValue, IIF(@Paid <> 2, 0, @CommissionValue));
      SET @CommissionAvailableValueD = @CommissionAvailableValue / @E;
    
      SET @TotalD = @Total / @E;
      SET @DiscountIsD = @DiscountIs / @E;
      SET @TaxValueD = @TaxValue / @E;
      SET @ProfitD = @Profit / @E;
      SET @ProfitLL = @ProfitD * @ELL;
      SET @ProfitEuro = @ProfitD * @EEuro;
      SET @FirstPaymentD = @FirstPayment / @E;
      SET @PaidUpD = @PaidUp / @E;
      SET @RestD = @Rest / @E;

      SELECT TOP ( 1 ) @WFPShopID = s.ShopID ,
          @WFPBranchID = s.BranchID
        FROM Options.t_WorldFoodProgramme AS s
        ORDER BY s.ID;

    END;

