    --BEGIN --Insert t_SoldDetailAdditions

    --  INSERT INTO Invoices.t_SoldDetailAdditions
    --      ( ID ,
    --        SoldID ,
    --        SoldDetailID ,
    --        AdditionsOnItemsID
    --      )
    --    SELECT s.ID ,
    --        s.SoldID ,
    --        s.SoldDetailID ,
    --        s.AdditionsOnItemsID
    --      FROM @SoldDetailAdditions AS s;

