    IF @HasSerial = 1
    BEGIN --Insert t_SoldDetailSerial

      INSERT INTO Invoices.t_SoldDetailSerial
          ( SoldID ,
            SoldDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
  
    EXECUTE Invoices.s_SoldDetailUpdateSerialNamesPART @SerialIs;
	
	--Reinsert t_SoldEmployeeProfit, t_SoldDetailEmployeeProfit
    EXECUTE Invoices.s_SoldEmployeeProfitInsertPART @ID, @SoldEmployeeProfit, @SoldDetailEmployeeProfit; 

	--Rebuild statistics
    --EXECUTE Invoices.s_SoldFixPART @ID, @CurrencyID, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @TaxExchangeRateLL, @TaxExchangeRateEuro;

	--Insert Last price
    EXECUTE Invoices.s_SoldInsertLastPricePART @ID, @CurrencyID, @ExchangeRate, @AccountCustomerID, @DetailIs;

    EXECUTE Invoices.s_SoldDetailExpirationDateUpdatePART @ItemExpirationDate_Old, @ItemExpirationDate, @ID;
 
    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
	
    BEGIN --Delete t_Transaction

      IF @ResetTransactions = 1
      BEGIN
	                              
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkID = @ID;

      END;
      ELSE
      BEGIN
          
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkTypeSub = 0 AND LinkID = @ID;
  
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkTypeSub = 7 AND LinkID = @ID;

        IF @AccountCustomerID <> @AccountCustomerIDOld
        BEGIN
    
          DELETE FROM Transactions.t_Transaction
            WHERE LinkType = @LinkType AND LinkTypeSub = 12 AND LinkID = @ID;

        END;
  
        DELETE FROM Transactions.t_Transaction
          WHERE LinkType = @LinkType AND LinkTypeSub = 17 AND LinkID = @ID;

      END;

    END;

    --IF @NetIs > 0
    BEGIN --Transaction
	
      SET @TransactionRef = @TrnRefJV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        SET @AccountsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t.Name AS [text()]
                                              FROM Company.t_Account AS t
                                              WHERE t.ID = @AccountCustomerID OR t.ID = IIF(@NetIsNonTaxable > 0, @AccountSellNonTaxableID, '00000000-0000-0000-0000-000000000000') OR t.ID = IIF(@AllTax > 0, @AccountSellTaxableID, '00000000-0000-0000-0000-000000000000') OR t.ID = IIF(@AllTax > 0, @AccountCustomerTaxID, '00000000-0000-0000-0000-000000000000') OR t.ID = @BalanceDifferenceAccountID
                                           FOR
                                             XML PATH('')
                                           ));

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID ,
              @UserIs ,
              @AccountsNames
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail
			
        SET @V = @NetIs;
        SET @RowNumber = 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertDebitTax @RowNumber, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @AllTax, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;

      END;

      IF @NetIsNonTaxable > 0
      BEGIN --Insert detail 
	   
        SET @V = @NetIsNonTaxable + @Rounding;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountSellNonTaxableID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
										
      END;

      IF @AllTax > 0
      BEGIN --Insert detail tax

        SET @V = @NetIsTaxableWithoutTax + IIF(@NetIsNonTaxable > 0, 0, @Rounding);
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountSellTaxableID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        SET @V = @AllTax;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF);
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
        --TaxCompressed
		--EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountCustomerTaxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
					
      END;

      IF @TransactionBetweenGoodsAndPurchase = 1 AND @CostNonTaxable > 0
      BEGIN --Insert detail 
	   
        SET @V = @CostNonTaxable;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @PurchaseNonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @GoodsNonTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;
   
      IF @TransactionBetweenGoodsAndPurchase = 1 AND @CostTaxableWithoutTax > 0
      BEGIN --Insert detail 
	   
        SET @V = @CostTaxableWithoutTax;
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @PurchaseTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @GoodsTaxableAccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;

      IF @BalanceDifference <> 0
      BEGIN --Insert Detail Balance Difference

        SET @V = ABS(@BalanceDifference);
        SET @RowNumber += 1;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + IIF(@BalanceDifference < 0, N'', ' \ ' + @AccountCustomer);
        DECLARE @AccountID UNIQUEIDENTIFIER = IIF(@BalanceDifference < 0, @AccountCustomerID, @BalanceDifferenceAccountID);
        EXECUTE Transactions.s_TransactionDetailInsertDebit @RowNumber, @TransactionID, @AccountID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

        SET @RowNumber += 1;
        SET @StatementIs_ += IIF(@BalanceDifference > 0, N'', ' \ ' + @AccountCustomer);
        SET @AccountID = IIF(@BalanceDifference > 0, @AccountCustomerID, @BalanceDifferenceAccountID);
        EXECUTE Transactions.s_TransactionDetailInsertCredit @RowNumber, @TransactionID, @AccountID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
					
      END;

    END;

    IF @AllFirstPayment <> 0
    BEGIN --Transaction
   
      SET @TransactionRef = @TrnRefRV;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'RV';

      END;

      BEGIN --Insert t_Transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'RV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              @UserID ,
              @UserIs ,
              @AccountsNames
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert t_TransactionDetail
		 
        IF ( @AllFirstPayment >= @NetIs AND @ExchangeRateLL = @TaxExchangeRateLL AND @ExchangeRateEuro = @TaxExchangeRateEuro
           ) OR ( @AllFirstPayment <= @NetIs - @AllTax ) OR ( @CurrencyTypeIs <> 0 )
        BEGIN

          IF @FirstPayment <> 0
          BEGIN
	    
            SET @V = @FirstPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @AccountCustomerID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;
        ELSE
        BEGIN
		 
          IF @FirstPayment <> 0
          BEGIN
	 
            SET @V = @FirstPayment - @AllTax;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

            SET @V = @FirstPayment - @V;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertDebit 3, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountBox + N' (' + @TaxExchangeRateEvent + N': ' + FORMAT(@TaxExchangeRateLL, N'#,##0.##') + N')';
            EXECUTE Transactions.s_TransactionDetailInsertCredit 4, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @TaxExchangeRateLL, @TaxExchangeRateEuro, @StatementIs_;
	
          END;

          IF @SecondPayment <> 0
          BEGIN
	    
            SET @V = @SecondPayment;
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @AccountCustomer;
            EXECUTE Transactions.s_TransactionDetailInsertDebit 5, @TransactionID, @SecondPaymentAccountBoxID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;
        
            SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + ' \ ' + @SecondPaymentAccountBox;
            EXECUTE Transactions.s_TransactionDetailInsertCredit 6, @TransactionID, @AccountCustomerID, @DateIs, @SecondPaymentCurrencyID, @V, @SecondPaymentExchangeRate, @ELL, @EEuro, @StatementIs_;

          END;

        END;

		--TaxCompressed>
        --SET @V = @FirstPayment;
        --SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @AccountCustomer;
        --EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountBoxID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        
        --SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @Ref) + ' \ ' + @AccountBox;
        --EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountCustomerID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
		--TaxCompressed<

      END;
 
    END;
	
    IF @CommissionAvailableValue > 0
    BEGIN --Transaction
   
      SET @TransactionRef = @TrnRefJVSalesperson;
      IF @TransactionRef IS NULL
      BEGIN --Set info

        SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = N'JV';

      END;

      BEGIN --Insert transaction

        SET @return = 0;

        DELETE FROM @IDs;

        INSERT INTO Transactions.t_Transaction
            ( Ref ,
              RefF ,
              TypeIs ,
              DateIs ,
              DateOnly ,
              DateFirstDayInMonth ,
              DateFirstDayInYear ,
              DescriptionIs ,
              LinkType ,
              LinkID ,
              LinkTypeSub ,
              UserID ,
              UserIs ,
              AccountsNames
            )
          OUTPUT Inserted.ID
            INTO @IDs ( ID )
          VALUES
            ( @TransactionRef ,
              FORMAT(@TransactionRef, '#') ,
              N'JV' ,
              @DateIs ,
              @DateIs ,
              DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
              DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
              REPLACE(@StatementIs, N'{0}', @AnyRefF) ,
              @LinkType ,
              @ID ,
              7 ,
              @UserID ,
              @UserIs ,
              @AccountsNames 
            );

        SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                ORDER BY s.ID
                             );

        INSERT @TrnIDs
            ( ID ,
              RefF
            )
          VALUES
            ( @TransactionID ,
              CONVERT(NVARCHAR(MAX), @TransactionRef)
            );

      END;

      BEGIN --Insert detail
		
        SET @V = @CommissionAvailableValue;
        SET @StatementIs_ = REPLACE(@StatementIs, N'{0}', @AnyRefF) + N' (' + Currencys.f_Format(@CID, @NetIs) + N' | ' + Currencys.f_FormatRate(@CommissionRate) + N' ' + Currencys.f_Format(@CID, @V) + N' EX: ' + FORMAT(@ExchangeRateLL, N'#,##0.##') + ') \ ' + @AccountCustomer;
        EXECUTE Transactions.s_TransactionDetailInsertDebit 1, @TransactionID, @AccountSalespersonSellID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;
        EXECUTE Transactions.s_TransactionDetailInsertCredit 2, @TransactionID, @AccountSalespersonID, @DateIs, @CID, @V, @E, @ELL, @EEuro, @StatementIs_;

      END;
	         
    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event + s.RefF ,
            IIF(@EventType = 1, 0, 9) ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;
	
    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET SoldTotal = Invoices.f_SoldGetTotalByAccountCustomerID(ID) ,
            SoldProfit = Invoices.f_SoldGetProfitByAccountCustomerID(ID)
        WHERE ID = @AccountCustomerID OR ID = @AccountCustomerIDOld;

      UPDATE Company.t_Account
        SET SoldTotalF = Currencys.f_Format(CurrencyID, SoldTotal) ,
            SoldProfitF = Currencys.f_Format(CurrencyID, SoldProfit)
        WHERE ID = @AccountCustomerID OR ID = @AccountCustomerIDOld;
		  
    END;

    IF @ProductionWhenSale <> 0
    BEGIN-- Delete t_ItemProduction
	
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_ItemProduction AS s
          WHERE s.OriginSection = 1 AND s.OriginID = @ID
        UNION ALL
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Items.t_ItemProductionMaterial AS s
          INNER JOIN Items.t_ItemProduction AS s1 ON s1.ID = s.ItemProductionID
          WHERE s1.OriginSection = 1 AND s1.OriginID = @ID;

      BEGIN --Delete

        SET @return = 0;

        DELETE FROM Items.t_ItemProductionMaterial
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM Items.t_ItemProduction AS s
                          WHERE s.OriginSection = 1 AND s.OriginID = @ID AND s.ID = t_ItemProductionMaterial.ItemProductionID );

        DELETE FROM Items.t_ItemProduction
          WHERE OriginSection = 1 AND OriginID = @ID;

      END;

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;
	
    EXECUTE [Items].[s_ItemProductionInsertBySold] @ProductionWhenSale, @ID, @Ref, @DateIs, @StageType, @CurrencyID, @Currency, @CurrencyTypeIs, @ExchangeRate, @ExchangeRateLL, @ExchangeRateEuro, @DetailIs, @UserID, @EventInsert, @EventInsertBySold, @ComputerIP, @Computer, @ComputerAccount; 

	--Insert t_CustomersInvoicesPoints
    EXECUTE Customers.s_CustomersInvoicesPointsReinsertPART @CustomerID, @DateIs, 0, @ID, @PointsIs, @UserID, @PointsEvent, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Employees.s_SalesPerson_UpdateLive_CommissionAvailable_PART2 @SalespersonID, @SalesPersonID_OLD;
	
    IF @SaveCRM = 1
    BEGIN

      EXECUTE Customers.s_CRMInsert @ID;

    END;

    IF @DateOnly_OLD = @DateOnly
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly_OLD;
      EXECUTE Invoices.s_ProfitDaily_SaleInvoices_Update_PART @DateOnly;

    END;
  
    EXECUTE Invoices.s_SoldLiveVersion;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateDeliveryInfo]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldUpdateDeliveryInfo] @ID UNIQUEIDENTIFIER ,
  @DeliveryStage TINYINT ,
  @DeliveryStageUndelivered TINYINT ,
  @DeliveryDueDate DATE ,
  @DeliveryByEmployeeID UNIQUEIDENTIFIER ,
  @DeliveryDate DATE ,
  @DeliveryDelayedDays INT ,
  @DeliveryNote NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update

      UPDATE Invoices.t_Sold
        SET DeliveryStage = @DeliveryStage ,
            DeliveryStageUndelivered = @DeliveryStageUndelivered ,
            DeliveryDueDate = @DeliveryDueDate ,
            DeliveryByEmployeeID = @DeliveryByEmployeeID ,
            DeliveryDate = @DeliveryDate ,
            DeliveryDelayedDays = @DeliveryDelayedDays ,
            DeliveryNote = @DeliveryNote ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;

    END;
 
    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Invoices.s_SoldLiveVersion;
	
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




