      UPDATE Invoices.t_Sold
        SET Legal = IIF(@LegalID = Alls.f_GetEmptyGuid(), 0, 1) ,
            LegalID = @LegalID ,
            LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;

    END;
 		
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;













