/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateLegalRef]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdateLegalRef] @LegalRef BIGINT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @LegalRefOld BIGINT ,
        @LegalRefFOld NVARCHAR(MAX) ,
        @LegalRefNumberOld NVARCHAR(MAX) ,
        @LegalRefF NVARCHAR(MAX) = FORMAT(@LegalRef, '#') ,
        @LegalRefNumber NVARCHAR(MAX) = CONVERT(NVARCHAR(MAX), @LegalRef) ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      SELECT TOP ( 1 ) @LegalRefOld = s.LegalRef ,
          @LegalRefFOld = FORMAT(s.LegalRef, '#') ,
          @LegalRefNumberOld = CONVERT(NVARCHAR(MAX), s.LegalRef)
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_Sold
        SET LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;

    END;
 
    BEGIN --Update t_SoldMoving 

--EN  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Insert: ' + @LegalRefNumberOld, N'Insert: ' + @LegalRefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Edit: ' + @LegalRefNumberOld, N'Edit: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Delete: ' + @LegalRefNumberOld, N'Delete: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

--AR  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'إضافة: ' + @LegalRefNumberOld, N'إضافة: ' + @LegalRefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'تعديل: ' + @LegalRefNumberOld, N'تعديل: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'حذف: ' + @LegalRefNumberOld, N'حذف: ' + @LegalRefNumber)
        WHERE SectionID = @ID;

    END;

    BEGIN --Update t_Transaction 

      UPDATE Transactions.t_Transaction
        SET DescriptionIs = REPLACE(DescriptionIs, N'S:Inv' + @LegalRefNumberOld, N'S:Inv' + @LegalRefNumber)
        WHERE LinkType = 2 AND LinkID = @ID;
 
      UPDATE Transactions.t_TransactionDetail
        SET StatementIs = REPLACE(StatementIs, N'S:Inv' + @LegalRefNumberOld, N'S:Inv' + @LegalRefNumber)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Transactions.t_Transaction AS s
                        WHERE s.LinkType = 2 AND s.LinkID = @ID );

    END;
	  
    EXECUTE Invoices.s_SoldLiveVersion;
		
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @Return;

  END CATCH;

END;













