/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateLegalSwitch]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldUpdateLegalSwitch] @ID UNIQUEIDENTIFIER ,
  @Legal BIT
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @LegalRef BIGINT ,
        @LegalRefF NVARCHAR(MAX);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @LegalRef = s.LegalRef ,
          @LegalRefF = s.LegalRefF
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID;

      IF @Legal = 1
      BEGIN

        IF @LegalRef <= 0
        BEGIN
	                        
          SELECT @LegalRef = ISNULL(MAX(s.LegalRef), 0) + 1
            FROM Invoices.t_Sold AS s
            WHERE s.Legal = 1;

          SET @LegalRefF = FORMAT(@LegalRef, '#');	  

        END;

      END;
      ELSE
      BEGIN

        SET @LegalRef = 0;
        SET @LegalRefF = N'';
  
      END;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_Sold
        SET Legal = @Legal ,
            LegalRef = @LegalRef ,
            LegalRefF = @LegalRefF ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;
    
      UPDATE Invoices.t_SoldDetail
        SET IsLegal = @Legal
        WHERE SoldID = @ID;

    END;
  
    EXECUTE Invoices.s_SoldLiveVersion;
 		
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;



