/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateRef]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdateRef] @Ref BIGINT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @RefOld BIGINT ,
        @RefFOld NVARCHAR(MAX) ,
        @RefNumberOld NVARCHAR(MAX) ,
        @RefF NVARCHAR(MAX) = FORMAT(@Ref, '#') ,
        @RefNumber NVARCHAR(MAX) = CONVERT(NVARCHAR(MAX), @Ref) ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      SELECT TOP ( 1 ) @RefOld = s.Ref ,
          @RefFOld = FORMAT(s.Ref, '#') ,
          @RefNumberOld = CONVERT(NVARCHAR(MAX), s.Ref)
        FROM Invoices.t_Sold AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update 

      UPDATE Invoices.t_Sold
        SET Ref = @Ref ,
            RefF = @RefF ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE ID = @ID;

    END;
 
    BEGIN --Update t_SoldMoving 

--EN  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Insert: ' + @RefNumberOld, N'Insert: ' + @RefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Edit: ' + @RefNumberOld, N'Edit: ' + @RefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'Delete: ' + @RefNumberOld, N'Delete: ' + @RefNumber)
        WHERE SectionID = @ID;

--AR  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'إضافة: ' + @RefNumberOld, N'إضافة: ' + @RefNumber)
        WHERE SectionID = @ID;
  
      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'تعديل: ' + @RefNumberOld, N'تعديل: ' + @RefNumber)
        WHERE SectionID = @ID;

      UPDATE Invoices.t_SoldMoving
        SET EventIs = REPLACE(EventIs, N'حذف: ' + @RefNumberOld, N'حذف: ' + @RefNumber)
        WHERE SectionID = @ID;

    END;

    BEGIN --Update t_Transaction 

      UPDATE Transactions.t_Transaction
        SET DescriptionIs = REPLACE(DescriptionIs, N'S:Inv' + @RefNumberOld, N'S:Inv' + @RefNumber)
        WHERE LinkType = 2 AND LinkID = @ID;
 
      UPDATE Transactions.t_TransactionDetail
        SET StatementIs = REPLACE(StatementIs, N'S:Inv' + @RefNumberOld, N'S:Inv' + @RefNumber)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Transactions.t_Transaction AS s
                        WHERE s.LinkType = 2 AND s.LinkID = @ID );

    END;

    BEGIN --Update t_FrameJobOrder 

      UPDATE Customers.t_FrameJobOrder
        SET SoldRefF = @RefF
        WHERE SoldID = @ID;
 
      UPDATE Customers.t_FrameJobOrderHistory
        SET SoldRefF = @RefF
        WHERE SoldID = @ID;
 
    END;

    BEGIN --Update t_FrameJobOrderMoving 
 
      UPDATE Customers.t_FrameJobOrderMoving
        SET EventIs = N'Converted to Sales Invoice Number: ' + @RefNumber
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Customers.t_FrameJobOrder AS s
                        WHERE s.SoldID = @ID
                       UNION ALL
                       SELECT TOP ( 1 ) s.ID
                        FROM Customers.t_FrameJobOrderHistory AS s
                        WHERE s.SoldID = @ID ) AND EventIs LIKE N'Converted%';

      UPDATE Customers.t_FrameJobOrderMoving
        SET EventIs = N'تحويلها إلى فاتورة بيع رقم: ' + @RefNumber
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Customers.t_FrameJobOrder AS s
                        WHERE s.SoldID = @ID
                       UNION ALL
                       SELECT TOP ( 1 ) s.ID
                        FROM Customers.t_FrameJobOrderHistory AS s
                        WHERE s.SoldID = @ID ) AND EventIs LIKE N'تحويلها%';

    END;

    BEGIN --Update t_Quotation 

      UPDATE Quotations.t_Quotation
        SET SourceRef = @Ref ,
            SourceRefF = @RefF
        WHERE SourceID = @ID;
 
      UPDATE Quotations.t_QuotationHistory
        SET SourceRef = @Ref ,
            SourceRefF = @RefF
        WHERE SourceID = @ID;
  
    END;

    BEGIN --Update t_ItemProduction 
	 
      UPDATE Items.t_ItemProduction
        SET OriginRef = @Ref
        WHERE OriginSection = 1 AND OriginID = @ID;

      UPDATE Items.t_ItemProductionMoving
        SET EventIs = REPLACE(EventIs, N': ' + @RefNumberOld + N')', N': ' + @RefNumber + N')')
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Items.t_ItemProduction AS s
                        WHERE s.OriginSection = 1 AND s.OriginID = @ID );

    END;
  
    EXECUTE Invoices.s_SoldLiveVersion;
		
    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  @Return;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateResetLegalRefs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdateResetLegalRefs] @StartRefFrom BIGINT
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

    BEGIN --DECLARE
	    
      DECLARE @LinkType INT = 2 ,
        @StatementIs NVARCHAR(MAX) = N'S:Inv|';

    END;

    IF @StartRefFrom >= 1
    BEGIN
                         
      SET @StartRefFrom -= 1;

    END;

    BEGIN --Update
 
      WITH  o AS ( SELECT t.LegalRef ,
                      t.LegalRefF ,
                      t.DateIs ,
                      t.DateCreate ,
                      ROW_NUMBER() OVER ( ORDER BY t.DateIs ) + @StartRefFrom AS LegalRef_
                    FROM Invoices.t_Sold AS t
                    WHERE t.Legal = 1
                 )
        UPDATE o
          SET o.LegalRef = o.LegalRef_ ,
              o.LegalRefF = FORMAT(o.LegalRef_, '#') ,
              o.DateCreate = o.DateIs;

      UPDATE Invoices.t_Sold
        SET LegalID = Alls.f_GetEmptyGuid() ,
            LegalRef = 0 ,
            LegalRefF = '' ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE Legal = 0;

    END;
		
    BEGIN --Delete t_SoldMoving 
	
      TRUNCATE TABLE Invoices.t_SoldMoving;

    END;
	
    BEGIN --Update t_Transaction 

      WITH  o AS ( SELECT s.DescriptionIs ,
                      s1.LegalRefF
                    FROM Transactions.t_Transaction AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.LinkID
                    WHERE s.LinkType = @LinkType AND s1.Legal = 1
                 )
        UPDATE o
          SET DescriptionIs = @StatementIs + o.LegalRefF;

      WITH  o AS ( SELECT s.StatementIs ,
                      s2.LegalRefF
                    FROM Transactions.t_TransactionDetail AS s
                    INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                    INNER JOIN Invoices.t_Sold AS s2 ON s2.ID = s1.LinkID
                    WHERE s1.LinkType = @LinkType AND s2.Legal = 1
                 )
        UPDATE o
          SET StatementIs = @StatementIs + o.LegalRefF;

    END;
	
    ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
	
    EXECUTE Invoices.s_SoldLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateResetRefs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdateResetRefs] @StartRef BIGINT
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
    DISABLE TRIGGER Customers.tr_FrameJobOrder ON Customers.t_FrameJobOrder;
    DISABLE TRIGGER Customers.tr_FrameJobOrderHistory ON Customers.t_FrameJobOrderHistory;
    DISABLE TRIGGER Quotations.tr_Quotation ON Quotations.t_Quotation;
    DISABLE TRIGGER Quotations.tr_QuotationHistory ON Quotations.t_QuotationHistory;
    DISABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;

    BEGIN --DECLARE
	    
      DECLARE @LinkType INT = 2 ,
        @StatementIs NVARCHAR(MAX) = N'S:Inv';

    END;

    BEGIN --Update
 
      WITH  o AS ( SELECT t.Ref ,
                      t.RefF ,
                      t.DateIs ,
                      t.DateCreate ,
                      ROW_NUMBER() OVER ( ORDER BY t.DateIs ) + @StartRef AS Ref_
                    FROM Invoices.t_Sold AS t
                 )
        UPDATE o
          SET o.Ref = o.Ref_ ,
              o.RefF = FORMAT(o.Ref_, '#') ,
              o.DateCreate = o.DateIs;

    END;
		
    BEGIN --Delete t_SoldMoving 
	
      TRUNCATE TABLE Invoices.t_SoldMoving;

    END;
	
    BEGIN --Update t_Transaction 

      WITH  o AS ( SELECT s.DescriptionIs ,
                      s1.RefF
                    FROM Transactions.t_Transaction AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.LinkID
                    WHERE s.LinkType = @LinkType AND s1.Legal = 0
                 )
        UPDATE o
          SET DescriptionIs = @StatementIs + o.RefF;

      WITH  o AS ( SELECT s.StatementIs ,
                      s2.RefF
                    FROM Transactions.t_TransactionDetail AS s
                    INNER JOIN Transactions.t_Transaction AS s1 ON s1.ID = s.TransactionID
                    INNER JOIN Invoices.t_Sold AS s2 ON s2.ID = s1.LinkID
                    WHERE s1.LinkType = @LinkType AND s2.Legal = 0
                 )
        UPDATE o
          SET StatementIs = @StatementIs + o.RefF;

    END;
	
    BEGIN --Update t_FrameJobOrder 
	 
      WITH  o AS ( SELECT s.SoldRefF ,
                      s1.RefF AS SoldRefF_
                    FROM Customers.t_FrameJobOrder AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SoldID
                    WHERE s1.Legal = 0
                 )
        UPDATE o
          SET o.SoldRefF = o.SoldRefF_;
  
    END;
  
    BEGIN --Update t_FrameJobOrderHistory 
	 
      WITH  o AS ( SELECT s.SoldRefF ,
                      s1.RefF AS SoldRefF_
                    FROM Customers.t_FrameJobOrderHistory AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SoldID
                    WHERE s1.Legal = 0
                 )
        UPDATE o
          SET o.SoldRefF = o.SoldRefF_;
  
    END;
   
    BEGIN --Update t_Quotation 
	 
      WITH  o AS ( SELECT s.SourceRef ,
                      s.SourceRefF ,
                      s1.Ref AS SourceRef_ ,
                      s1.RefF AS SourceRefF_
                    FROM Quotations.t_Quotation AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SourceID AND s.SourceType = 3
                    WHERE s1.Legal = 0
                 )
        UPDATE o
          SET o.SourceRef = o.SourceRef_ ,
              o.SourceRefF = o.SourceRefF_;
  
    END;

    BEGIN --Update t_QuotationHistory
	 
      WITH  o AS ( SELECT s.SourceRef ,
                      s.SourceRefF ,
                      s1.Ref AS SourceRef_ ,
                      s1.RefF AS SourceRefF_
                    FROM Quotations.t_QuotationHistory AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SourceID AND s.SourceType = 3
                    WHERE s1.Legal = 0
                 )
        UPDATE o
          SET o.SourceRef = o.SourceRef_ ,
              o.SourceRefF = o.SourceRefF_;
  
    END;

    BEGIN --Update t_ItemProduction 

      WITH  o AS ( SELECT s.OriginRef ,
                      s1.RefF AS SoldRefF_
                    FROM Items.t_ItemProduction AS s
                    INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.OriginID
                    WHERE s.OriginSection = 1 AND s1.Legal = 0
                 )
        UPDATE o
          SET o.OriginRef = o.SoldRefF_;

    END;

    ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
    ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
    ENABLE TRIGGER Customers.tr_FrameJobOrder ON Customers.t_FrameJobOrder;
    ENABLE TRIGGER Customers.tr_FrameJobOrderHistory ON Customers.t_FrameJobOrderHistory;
    ENABLE TRIGGER Quotations.tr_Quotation ON Quotations.t_Quotation;
    ENABLE TRIGGER Quotations.tr_QuotationHistory ON Quotations.t_QuotationHistory;
    ENABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
	
    EXECUTE Invoices.s_SoldLiveVersion;
    EXECUTE Transactions.s_TransactionLiveVersion;
    EXECUTE Customers.s_FrameJobOrderLiveVersion;
    EXECUTE Quotations.s_QuotationLiveVersion;
    EXECUTE Items.s_ItemProductionLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN  0;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateSalespersonTakeCommission]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_SoldUpdateSalespersonTakeCommission] @SalespersonTakeCommission BIT ,
  @DateIs DATETIME ,
  @BoxID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @EventTransactionBase NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @TrnIDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          RefF NVARCHAR(MAX) NOT NULL ,
          AccountSalespersonID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @ID UNIQUEIDENTIFIER ,
        @RefF NVARCHAR(MAX) ,
        @AccountSalespersonID UNIQUEIDENTIFIER ,
        @Salesperson NVARCHAR(MAX) ,
        @Box NVARCHAR(MAX) ,
        @CommissionValue FLOAT ,
        @TransactionID UNIQUEIDENTIFIER ,
        @TransactionRef BIGINT ,
        @LinkType INT = 2 ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @drsCommission Employees.tt_SalesPerson_Increment_CommissionAvailable ,
        @return INT;

    END;

    BEGIN --Set info

      SET @Box = Company.f_AccountGetName(@BoxID);
   
      INSERT INTO @drsCommission
          ( ID ,
            ValueD ,
            ValueLL ,
            ValueEuro
          )
        SELECT t.SalespersonID ,
            0 - COALESCE(SUM(t.CommissionAvailableValueD), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueLL), 0) ,
            0 - COALESCE(SUM(t.CommissionAvailableValueEuro), 0)
          FROM Invoices.t_Sold AS t
          WHERE t.CommissionAvailableValue > 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                                              FROM @IDAndEvent AS s
                                                              WHERE s.ID = t.ID )
          GROUP BY t.SalespersonID;

    END;

    BEGIN --Update 

      SET @return = 0;

      UPDATE Invoices.t_Sold
        SET SalespersonTakeCommission = @SalespersonTakeCommission ,
            CommissionAvailableValue = IIF(@SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValue, IIF(Paid <> 2, 0, CommissionValue))) ,
            CommissionAvailableValueD = IIF(@SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueD, IIF(Paid <> 2, 0, CommissionValueD))) ,
            CommissionAvailableValueLL = IIF(@SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueLL, IIF(Paid <> 2, 0, CommissionValueLL))) ,
            CommissionAvailableValueEuro = IIF(@SalespersonTakeCommission = 1, 0, IIF(CommissionRateType = 0, CommissionValueEuro, IIF(Paid <> 2, 0, CommissionValueEuro))) ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID );

      UPDATE Invoices.t_Sold
        SET CommissionAvailableValueF = Currencys.f_Format(CurrencyID, CommissionAvailableValue)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID );

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART @IDAndEvent, @UserID, 1, @ComputerIP, @Computer, @ComputerAccount;

    BEGIN --Delete t_Transaction

      DELETE FROM Transactions.t_Transaction
        WHERE TypeIs = N'JV' AND LinkTypeSub = 8 AND LinkType = 2 AND EXISTS ( SELECT s.ID
                                                                                FROM @IDAndEvent AS s
                                                                                WHERE s.ID = t_Transaction.LinkID );
		
    END;

    IF @SalespersonTakeCommission = 1
    BEGIN --Insert t_Transaction

      DECLARE i CURSOR FORWARD_ONLY
      FOR
      SELECT s.ID
        FROM @IDAndEvent AS s
        LEFT JOIN Invoices.t_Sold AS s1 ON s1.ID = s.ID
        WHERE s1.CommissionValue > 0;

      OPEN i;
      FETCH NEXT FROM i
    INTO @ID;
      WHILE @@FETCH_STATUS = 0
      BEGIN
	
        BEGIN --Get Info

          SELECT @RefF = s.RefF ,
              @Salesperson = s.Salesperson ,
              @AccountSalespersonID = Company.f_AccountSalespersonGetID(s.SalespersonID) ,
              @CommissionValue = s.CommissionValue ,
              @CID = s.CurrencyID ,
              @E = s.ExchangeRate ,
              @ELL = s.ExchangeRateLL ,
              @EEuro = s.ExchangeRateEuro
            FROM Invoices.t_Sold AS s
            WHERE s.ID = @ID;
   
        END;

        BEGIN --Set info

          SELECT @TransactionRef = ISNULL(MAX(s.Ref), 0) + 1
            FROM Transactions.t_Transaction AS s
            WHERE s.TypeIs = N'JV';
   
        END;

        BEGIN --Insert t_Transaction

          DELETE FROM @IDs;

          INSERT INTO Transactions.t_Transaction
              ( Ref ,
                TypeIs ,
                DateIs ,
                DescriptionIs ,
                LinkType ,
                LinkTypeSub ,
                LinkID ,
                UserID
              )
            OUTPUT Inserted.ID
              INTO @IDs ( ID )
            VALUES
              ( @TransactionRef ,
                N'JV' ,
                @DateIs ,
                N'S:Inv' + @RefF ,
                @LinkType ,
                8 ,
                @ID ,
                @UserID
              );
   
          SET @TransactionID = ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  ORDER BY s.ID
                               );

          INSERT @TrnIDs
              ( ID ,
                RefF ,
                AccountSalespersonID
              )
            VALUES
              ( @TransactionID ,
                FORMAT(@TransactionRef, '#') ,
                @AccountSalespersonID
              );

        END;

        BEGIN --Insert detail
		
          SET @V = @CommissionValue;
          SET @VD = @CommissionValue / @E;

          INSERT INTO Transactions.t_TransactionDetail
              ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro )
            VALUES  ( 1, @TransactionID, @AccountSalespersonID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, N'S:Inv' + @RefF + N' \ ' + @Box, @CID, @E, @ELL, @EEuro ),
                    ( 2, @TransactionID, @BoxID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, N'S:Inv' + @RefF + N' \ ' + @Salesperson, @CID, @E, @ELL, @EEuro );

        END;

        FETCH NEXT FROM i
        INTO @ID;
      END;
      CLOSE i;
      DEALLOCATE i;

    END;

    BEGIN --Insert t_TransactionMoving

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @EventTransactionBase + s.RefF ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @TrnIDs AS s;

    END;

    BEGIN --Fix data
	
      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @BoxID ) AND StatusIs = 1;
    
      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @TrnIDs AS s
                        WHERE s.AccountSalespersonID = t_Account.ID ) AND StatusIs = 1;
  
      DECLARE @TrnIDsFix AS Alls.tt_Guid;
      INSERT INTO @TrnIDsFix
          ( ID )
        SELECT s.ID
          FROM @TrnIDs AS s;

      EXECUTE Transactions.s_TransactionFixesPart @TrnIDsFix;

    END;

    EXECUTE Employees.s_SalesPerson_Increments_CommissionAvailable_PART @drsCommission;
  
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdatesDeliveryStage]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdatesDeliveryStage] @IDAndEvent Alls.tt_IDAndEvent READONLY ,
  @DeliveryStage TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    BEGIN --Update

      SET @return = 0;

      UPDATE Invoices.t_Sold
        SET DeliveryStage = @DeliveryStage ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID );

    END;

    IF @DeliveryStage = 3
    BEGIN
                          
      UPDATE Invoices.t_Sold
        SET DeliveryDate = GETDATE() ,
            DeliveryDelayedDays = DATEDIFF(DAY, DeliveryDueDate, GETDATE())
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID );
    
      UPDATE Invoices.t_Sold
        SET DeliveryDate = DeliveryDueDate ,
            DeliveryDelayedDays = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID ) AND DeliveryDate < DeliveryDueDate;

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART @IDAndEvent, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Invoices.s_SoldLiveVersion;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Invoices].[s_SoldUpdateWFPFrom]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_SoldUpdateWFPFrom] @WFPFrom BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @WFPShopID NVARCHAR(MAX) = '' ,
        @WFPBranchID NVARCHAR(MAX) = '' ,
        @Return INT;

    END;

    BEGIN --Set info

      IF @WFPFrom = 1
      BEGIN

        SELECT TOP ( 1 ) @WFPShopID = s.ShopID ,
            @WFPBranchID = s.BranchID
          FROM Options.t_WorldFoodProgramme AS s
          ORDER BY s.ID;

      END;

    END;

    BEGIN --Update 

      SET @Return = 0;

      UPDATE Invoices.t_Sold
        SET WFPShopID = @WFPShopID ,
            WFPBranchID = @WFPBranchID ,
            WFPFrom = @WFPFrom ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_Sold.ID );

    END;

    SET @Return = -1;
    EXECUTE Invoices.s_SoldMovingInsertsPART @IDAndEvent, @UserID, 1, @ComputerIP, @Computer, @ComputerAccount;
  
    EXECUTE Invoices.s_SoldLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









