/****** Object:  StoredProcedure [Invoices].[s_TrackDeletedItemsFromInvoicesRebuild]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_TrackDeletedItemsFromInvoicesRebuild]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    UPDATE Invoices.t_TrackDeletedItemsFromInvoices
      SET UnitSellingPriceF = Currencys.f_Format(CurrencyID, UnitSellingPrice) ,
          TotalDiscountF = Currencys.f_Format(CurrencyID, TotalDiscount) ,
          SubTotalF = Currencys.f_Format(CurrencyID, SubTotal) ,
          InvoiceDiscountF = Currencys.f_Format(CurrencyID, InvoiceDiscount) ,
          SubTotal2F = Currencys.f_Format(CurrencyID, SubTotal2) ,
          TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
          TotalF = Currencys.f_Format(CurrencyID, Total) ,
          UnitCostF = Currencys.f_Format(CurrencyID, UnitCost) ,
          TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
          UnitProfitF = Currencys.f_Format(CurrencyID, UnitProfit) ,
          TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit);

    WITH  o AS ( SELECT t.Qty ,
                    t.QtyWithUnit ,
                    t2.Name
                  FROM Invoices.t_TrackDeletedItemsFromInvoices AS t
                  INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnitID
                  INNER JOIN Items.t_Unity AS t2 ON t2.ID = t1.UnityID
               )
      UPDATE o
        SET o.QtyWithUnit = FORMAT(o.Qty, N'0.#### ') + o.Name;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Invoices].[s_TransferAwaitedCommit]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_TransferAwaitedCommit] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Return INT = 0 ,
        @Ref NVARCHAR(MAX) ,
        @FromWarehouseID UNIQUEIDENTIFIER ,
        @ToWarehouseID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @Ref = s.RefF ,
          @FromWarehouseID = s.FromWarehouseID ,
          @ToWarehouseID = s.ToWarehouseID
        FROM Invoices.t_TransferAwaited AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_TransferAwaitedDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @ToWarehouseID
          WHERE s.TransferAwaitedID = @ID;

    END;

    BEGIN --Insert Transfer

      INSERT INTO Invoices.t_Transfer
          ( ID ,
            Ref ,
            RefF ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            FromWarehouseID ,
            FromWarehouse ,
            ToWarehouseID ,
            ToWarehouse ,
            UserID ,
            UserIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            DescriptionIs ,
            ItemsNames ,
            Qtys ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.DateIs ,
            t.DateOnly ,
            t.DateMonthly ,
            t.DateYearly ,
            t.FromWarehouseID ,
            t.FromWarehouse ,
            t.ToWarehouseID ,
            t.ToWarehouse ,
            t.UserID ,
            t.UserIs ,
            t.CurrencyID ,
            t.Currency ,
            t.ExchangeRate ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.NetIs ,
            t.NetIsF ,
            t.NetIsD ,
            t.NetIsLL ,
            t.NetIsEuro ,
            t.NetIsAR ,
            t.NetIsEN ,
            t.DescriptionIs ,
            t.ItemsNames ,
            t.Qtys ,
            t.DateCreate ,
            t.WorkStationID
          FROM Invoices.t_TransferAwaited AS t
          WHERE t.ID = @ID;

    END;

    BEGIN --Insert Detail

      SET @Return = -2;

      INSERT INTO Invoices.t_TransferDetail
          ( ID ,
            TransferID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DescriptionIs ,
            SerialNames ,
            SortAt ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.TransferAwaitedID ,
            t.ItemSharedID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.DiscountIs ,
            t.DiscountIsF ,
            t.DiscountIsValue ,
            t.DiscountIsValueF ,
            t.DiscountIsValueD ,
            t.DiscountIsValueLL ,
            t.DiscountIsValueEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.TaxRate ,
            t.TaxRateF ,
            t.TaxValue ,
            t.TaxValueF ,
            t.TaxValueD ,
            t.TaxValueLL ,
            t.TaxValueEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.DescriptionIs ,
            t.SerialNames ,
            t.SortAt ,
            t.DateCreate ,
            t.WorkStationID
          FROM Invoices.t_TransferAwaitedDetail AS t
          WHERE t.TransferAwaitedID = @ID;

      INSERT INTO Invoices.t_TransferDetailSerial
          ( ID ,
            TransferID ,
            TransferDetailID ,
            SerialID ,
            DateCreate ,
            WorkStationID
          )
        SELECT t.ID ,
            t.TransferAwaitedID ,
            t.TransferAwaitedDetailID ,
            t.SerialID ,
            t.DateCreate ,
            t.WorkStationID
          FROM Invoices.t_TransferAwaitedDetailSerial AS t;

    END;

    BEGIN --Update t_ItemSerial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1 ,
            ItemID = Items.f_ItemGetID(ItemSharedID, @ToWarehouseID) ,
            LastSectionID = '00000000-0000-0000-0000-000000000000'
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Invoices.t_TransferAwaitedDetailSerial AS s
                        WHERE s.SerialID = t_ItemSerial.ID );

    END;

    EXECUTE Invoices.s_TransferDetailExpirationDateInsertByCommitPART @ID, @FromWarehouseID, @ToWarehouseID; 

    BEGIN --Delete Transfer Awaited

      DELETE FROM Invoices.t_TransferAwaitedDetailSerial
        WHERE TransferAwaitedID = @ID;

      DELETE FROM Invoices.t_TransferAwaitedDetail
        WHERE TransferAwaitedID = @ID;

      DELETE FROM Invoices.t_TransferAwaitedDetailExpirationDate
        WHERE TransferAwaitedID = @ID;

      DELETE FROM Invoices.t_TransferAwaited
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + @Ref ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;












GO
