CREATE PROCEDURE [Invoices].[s_TransferAwaitedDetailUpdateSerialNamesPART] @SerialIs Items.tt_ItemSerial READONLY
AS
BEGIN
  
  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @SerialIs AS s )
  BEGIN

    RETURN;
			    
  END;

  UPDATE Invoices.t_TransferAwaitedDetail
    SET SerialNames = Invoices.f_TransferAwaitedDetailGetSerialNames(ID)
    WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @SerialIs AS s
                    WHERE s.FatherID = t_TransferAwaitedDetail.ID );

END;



