/****** Object:  StoredProcedure [Invoices].[s_TransferAwaitedInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_TransferAwaitedInsert] @DateIs DATETIME ,
  @FromWarehouseID UNIQUEIDENTIFIER ,
  @ToWarehouseID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Invoices.[tt_TransferDetail] READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @Total FLOAT ,
        @TaxRate DECIMAL(4, 2) = 0 ,
        @TaxValue FLOAT ,
        @NetIs FLOAT ,
        @Qtys DECIMAL(18, 6) ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM ( SELECT MAX(s.Ref) AS Ref
                FROM Invoices.t_TransferAwaited AS s
               UNION
               SELECT MAX(s.Ref)
                FROM Invoices.t_Transfer AS s
             ) AS s;

      SELECT @Total = COALESCE(SUM(s.SubTotal), 0) ,
          @TaxValue = COALESCE(SUM(s.TaxValue), 0) ,
          @NetIs = COALESCE(SUM(s.Total), 0) ,
          @Qtys = COALESCE(SUM(s.Qtys), 0)
        FROM @DetailIs AS s;

      IF @Total > 0 AND @TaxValue > 0
      BEGIN

        SET @TaxRate = ( @TaxValue / @Total ) * 100;

      END;

    END;

    BEGIN --Insert

      INSERT INTO Invoices.t_TransferAwaited
          ( ID ,
            Ref ,
            RefF ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            FromWarehouseID ,
            FromWarehouse ,
            ToWarehouseID ,
            ToWarehouse ,
            UserID ,
            UserIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            DescriptionIs ,
            Qtys
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, '#') ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @FromWarehouseID ,
            Company.f_WareHouseGetName(@FromWarehouseID) ,
            @ToWarehouseID ,
            Company.f_WareHouseGetName(@ToWarehouseID) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @CurrencyID ,
            Currencys.f_CurrencyGetName(@CurrencyID) ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Total ,
            Currencys.f_Format(@CurrencyID, @Total) ,
            @Total / @ExchangeRate ,
            ( @Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( @Total / @ExchangeRate ) * @ExchangeRateEuro ,
            @TaxRate ,
            Currencys.f_FormatRate(@TaxRate) ,
            @TaxValue ,
            Currencys.f_Format(@CurrencyID, @TaxValue) ,
            @TaxValue / @ExchangeRate ,
            ( @TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( @TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            @NetIs ,
            Currencys.f_Format(@CurrencyID, @NetIs) ,
            @NetIs / @ExchangeRate ,
            ( @NetIs / @ExchangeRate ) * @ExchangeRateLL ,
            ( @NetIs / @ExchangeRate ) * @ExchangeRateEuro ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            @DescriptionIs ,
            @Qtys
          );

    END;

    BEGIN --Insert detail

      INSERT INTO Invoices.t_TransferAwaitedDetail
          ( ID ,
            TransferAwaitedID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemUnityID ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qtys ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountIs ,
            Currencys.f_FormatRate(s.DiscountIs) ,
            s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
            s.DiscountIsValue / @ExchangeRate ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.SubTotal ,
            Currencys.f_Format(@CurrencyID, s.SubTotal) ,
            s.SubTotal / @ExchangeRate ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TaxRate ,
            Currencys.f_FormatRate(s.TaxRate) ,
            s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.TaxValue) ,
            s.TaxValue / @ExchangeRate ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Insert detial serial

      INSERT INTO Invoices.t_TransferAwaitedDetailSerial
          ( TransferAwaitedID ,
            TransferAwaitedDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update item serial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 2 ,
            LastSectionID = @ID
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
  
    EXECUTE Invoices.s_TransferAwaitedDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_TransferAwaitedDetailExpirationDateInsertPART @ID, @ItemExpirationDate;
	
    BEGIN --Rebuild statistics

      UPDATE Invoices.t_TransferAwaited
        SET ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_TransferAwaitedDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.TransferAwaitedID = t_TransferAwaited.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @FromWarehouseID;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Invoices].[s_TransferAwaitedRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_TransferAwaitedRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Invoices.t_TransferAwaited
        SET FromWarehouse = Company.f_WareHouseGetName(FromWarehouseID) ,
            ToWarehouse = Company.f_WareHouseGetName(ToWarehouseID) ,
            UserIs = Users.f_UserGetName(UserID) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_TransferAwaitedDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.TransferAwaitedID = t_TransferAwaited.ID
                                       FOR
                                         XML PATH('')
                                       ));


      WITH  o AS ( SELECT s.Qty ,
                      s.QtyWithUnity ,
                      s2.Name AS Unity
                    FROM Invoices.t_TransferAwaitedDetail AS s
                    LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
                    LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID
                 )
        UPDATE o
          SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Invoices].[s_TransferAwaitedUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_TransferAwaitedUpdate] @DateIs DATETIME ,
  @FromWarehouseID UNIQUEIDENTIFIER ,
  @ToWarehouseID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Invoices.[tt_TransferDetail] READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @return INT ,
        @Total FLOAT ,
        @TaxRate DECIMAL(4, 2) = 0 ,
        @TaxValue FLOAT ,
        @NetIs FLOAT ,
        @Qtys DECIMAL(18, 6) ,
        @FromWarehouseIDOld UNIQUEIDENTIFIER;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @FromWarehouseIDOld = s.FromWarehouseID
        FROM Invoices.t_TransferAwaited AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_TransferAwaitedDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @FromWarehouseIDOld
          WHERE s.TransferAwaitedID = @ID;

      SELECT @Total = COALESCE(SUM(s.SubTotal), 0) ,
          @TaxValue = COALESCE(SUM(s.TaxValue), 0) ,
          @NetIs = COALESCE(SUM(s.Total), 0) ,
          @Qtys = COALESCE(SUM(s.Qtys), 0)
        FROM @DetailIs AS s;

      IF @Total > 0
      BEGIN

        SET @TaxRate = ( @TaxValue / @Total ) * 100;

      END;

    END;

    BEGIN --Update

      SET @return = 0;

      UPDATE Invoices.t_TransferAwaited
        SET DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            FromWarehouseID = @FromWarehouseID ,
            FromWarehouse = Company.f_WareHouseGetName(@FromWarehouseID) ,
            ToWarehouseID = @ToWarehouseID ,
            ToWarehouse = Company.f_WareHouseGetName(@ToWarehouseID) ,
            UserID = @UserID ,
            UserIs = Users.f_UserGetName(@UserID) ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Total = @Total ,
            TotalF = Currencys.f_Format(@CurrencyID, @Total) ,
            TotalD = @Total / @ExchangeRate ,
            TotalLL = ( @Total / @ExchangeRate ) * @ExchangeRateLL ,
            TotalEuro = ( @Total / @ExchangeRate ) * @ExchangeRateEuro ,
            TaxRate = @TaxRate ,
            TaxRateF = FORMAT(@TaxRate, '0.##') + N' %' ,
            TaxValue = @TaxValue ,
            TaxValueF = Currencys.f_Format(@CurrencyID, @TaxValue) ,
            TaxValueD = @TaxValue / @ExchangeRate ,
            TaxValueLL = ( @TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            TaxValueEuro = ( @TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            NetIs = @NetIs ,
            NetIsF = Currencys.f_Format(@CurrencyID, @NetIs) ,
            NetIsD = @NetIs / @ExchangeRate ,
            NetIsLL = ( @NetIs / @ExchangeRate ) * @ExchangeRateLL ,
            NetIsEuro = ( @NetIs / @ExchangeRate ) * @ExchangeRateEuro ,
            NetIsAR = Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            DescriptionIs = @DescriptionIs ,
            Qtys = @Qtys
        WHERE ID = @ID;

    END;

    BEGIN --Delete detial serial

      DELETE FROM Invoices.t_TransferAwaitedDetailSerial
        WHERE TransferAwaitedID = @ID;

    END;

    BEGIN --Insert detail

      MERGE Invoices.t_TransferAwaitedDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 TransferAwaitedID ,
                 ItemSharedID ,
                 ItemUnityID ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 PriceLL ,
                 PriceEuro ,
                 DiscountIs ,
                 DiscountIsF ,
                 DiscountIsValue ,
                 DiscountIsValueF ,
                 DiscountIsValueD ,
                 DiscountIsValueLL ,
                 DiscountIsValueEuro ,
                 SubTotal ,
                 SubTotalF ,
                 SubTotalD ,
                 SubTotalLL ,
                 SubTotalEuro ,
                 TaxRate ,
                 TaxRateF ,
                 TaxValue ,
                 TaxValueF ,
                 TaxValueD ,
                 TaxValueLL ,
                 TaxValueEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemUnityID ,
                 s.Qty ,
                 Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                 s.Qtys ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs) ,
                 s.DiscountIsValue ,
                 Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                 s.DiscountIsValue / @ExchangeRate ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.SubTotal ,
                 Currencys.f_Format(@CurrencyID, s.SubTotal) ,
                 s.SubTotal / @ExchangeRate ,
                 ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.TaxRate ,
                 Currencys.f_FormatRate(s.TaxRate) ,
                 s.TaxValue ,
                 Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                 s.TaxValue / @ExchangeRate ,
                 ( s.TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Total ,
                 Currencys.f_Format(@CurrencyID, s.Total) ,
                 s.Total / @ExchangeRate ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemUnityID = s.ItemUnityID ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                    t.Qtys = s.Qtys ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.PriceLL = ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs) ,
                    t.DiscountIsValue = s.DiscountIsValue ,
                    t.DiscountIsValueF = Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
                    t.DiscountIsValueD = s.DiscountIsValue / @ExchangeRate ,
                    t.DiscountIsValueLL = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
                    t.DiscountIsValueEuro = ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.SubTotal = s.SubTotal ,
                    t.SubTotalF = Currencys.f_Format(@CurrencyID, s.SubTotal) ,
                    t.SubTotalD = s.SubTotal / @ExchangeRate ,
                    t.SubTotalLL = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
                    t.SubTotalEuro = ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.TaxRate = s.TaxRate ,
                    t.TaxRateF = Currencys.f_FormatRate(s.TaxRate) ,
                    t.TaxValue = s.TaxValue ,
                    t.TaxValueF = Currencys.f_Format(@CurrencyID, s.TaxValue) ,
                    t.TaxValueD = s.TaxValue / @ExchangeRate ,
                    t.TaxValueLL = ( s.TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TaxValueEuro = ( s.TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Total = s.Total ,
                    t.TotalF = Currencys.f_Format(@CurrencyID, s.Total) ,
                    t.TotalD = s.Total / @ExchangeRate ,
                    t.TotalLL = ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TotalEuro = ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.TransferAwaitedID = @ID THEN
        DELETE;

    END;

    BEGIN --Insert detial serial

      INSERT INTO Invoices.t_TransferAwaitedDetailSerial
          ( TransferAwaitedID ,
            TransferAwaitedDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update item serial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1 ,
            LastSectionID = '00000000-0000-0000-0000-000000000000'
        WHERE LastSectionID = @ID;

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 2 ,
            LastSectionID = @ID
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
  
    EXECUTE Invoices.s_TransferAwaitedDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_TransferAwaitedDetailExpirationDateInsertPART @ID, @ItemExpirationDate;

    BEGIN --Rebuild statistics

      UPDATE Invoices.t_TransferAwaited
        SET ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_TransferAwaitedDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.TransferAwaitedID = t_TransferAwaited.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @ID;
    
    END;

    BEGIN--Item Qtys

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @FromWarehouseID;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
