/****** Object:  StoredProcedure [Invoices].[s_TransferAwaitedUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Invoices].[s_TransferAwaitedUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_TransferAwaited ON Invoices.t_TransferAwaited;
    DISABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    DISABLE TRIGGER Invoices.tr_TransferAwaitedDetailSerial ON Invoices.t_TransferAwaitedDetailSerial;

    BEGIN --Update

      UPDATE  Invoices.t_TransferAwaited
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_TransferAwaited.ID );

      UPDATE  Invoices.t_TransferAwaitedDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_TransferAwaitedDetail.TransferAwaitedID );

      UPDATE  Invoices.t_TransferAwaitedDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_TransferAwaitedDetailSerial.TransferAwaitedID );
  
    END;

    ENABLE TRIGGER Invoices.tr_TransferAwaited ON Invoices.t_TransferAwaited;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetailSerial ON Invoices.t_TransferAwaitedDetailSerial;

    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, TransferIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));
   
    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;










GO
