/****** Object:  StoredProcedure [Invoices].[s_TransferDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_TransferDelete] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Return INT = 0 ,
        @FromWarehouseID UNIQUEIDENTIFIER ,
        @ToWarehouseID UNIQUEIDENTIFIER;

    END;

    BEGIN --Set

      SELECT TOP ( 1 ) @FromWarehouseID = s.FromWarehouseID ,
          @ToWarehouseID = s.ToWarehouseID
        FROM Invoices.t_Transfer AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_TransferDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @FromWarehouseID
          WHERE s.TransferID = @ID
        UNION ALL
        SELECT s1.ID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Invoices.t_TransferDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @ToWarehouseID
          WHERE s.TransferID = @ID;

    END;

    EXECUTE Invoices.s_TransferDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      DELETE FROM Invoices.t_TransferDetail
        WHERE TransferID = @ID;

      DELETE FROM Invoices.t_Transfer
        WHERE ID = @ID;

    END;
	
    BEGIN --Insert t_TransferMoving

      SET @Return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Invoices].[s_TransferDetailExpirationDateDeletePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_TransferDetailExpirationDateDeletePART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @All AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;

  BEGIN --Set
   
    INSERT INTO @All
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Invoices.t_TransferDetailExpirationDate AS t
        INNER JOIN Invoices.t_Transfer AS t1 ON t1.ID = t.TransferID
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = t1.FromWarehouseID
        WHERE t.TransferID = @ID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
      UNION ALL
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          0 - ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Invoices.t_TransferDetailExpirationDate AS t
        INNER JOIN Invoices.t_Transfer AS t1 ON t1.ID = t.TransferID
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = t1.ToWarehouseID
        WHERE t.TransferID = @ID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @All AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs;

  END;  

  BEGIN --Delete t_TransferDetailExpirationDate

    DELETE FROM Invoices.t_TransferDetailExpirationDate
      WHERE TransferID = @ID;

  END;
  
  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;



GO
/****** Object:  StoredProcedure [Invoices].[s_TransferDetailExpirationDateInsertByCommitPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_TransferDetailExpirationDateInsertByCommitPART] @ID UNIQUEIDENTIFIER ,
  @FromWarehouseID UNIQUEIDENTIFIER ,
  @ToWarehouseID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @All AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;

  BEGIN --Set
   
    INSERT INTO @All
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          0 - ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Invoices.t_TransferAwaitedDetailExpirationDate AS t
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = @FromWarehouseID
        WHERE t.TransferAwaitedID = @ID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
      UNION ALL
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Invoices.t_TransferAwaitedDetailExpirationDate AS t
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = @ToWarehouseID
        WHERE t.TransferAwaitedID = @ID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @All AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs;

  END;  

  BEGIN --Insert t_TransferDetailExpirationDate

    INSERT INTO Invoices.t_TransferDetailExpirationDate
        ( ID ,
          TransferID ,
          TransferDetailID ,
          ItemSharedID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          WorkStationID
        )
      SELECT s.ID ,
          s.TransferAwaitedID ,
          s.TransferAwaitedDetailID ,
          s.ItemSharedID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs ,
          s.DateCreate ,
          s.WorkStationID
        FROM Invoices.t_TransferAwaitedDetailExpirationDate AS s
        WHERE s.TransferAwaitedID = @ID;

  END;
  
  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( Items.f_ItemExpirationDateGetNewRef() ,
               N'-' ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               Company.f_WareHouseGetName(s.WareHouseID) ,
               s.PlaceID ,
               Company.f_PlaceGetName(s.PlaceID) ,
               158 ,
               @ID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               Currencys.f_CurrencyGetName(s.CurrencyID) ,
               s.Price ,
               Currencys.f_Format(s.CurrencyID, s.Price) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateLL() ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateEuro() ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

    UPDATE Items.t_ItemExpirationDate
      SET RefF = FORMAT(Ref, N'0')
      WHERE RefF = N'-';

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;




