CREATE PROCEDURE [Invoices].[s_TransferDetailExpirationDateInsertPART] @ID UNIQUEIDENTIFIER ,
  @FromWarehouseID UNIQUEIDENTIFIER ,
  @ToWarehouseID UNIQUEIDENTIFIER ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @All AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;

  BEGIN --Set
   
    INSERT INTO @All
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          0 - ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @ItemExpirationDate AS t
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = @FromWarehouseID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
      UNION ALL
      SELECT t.ItemSharedID ,
          t3.ID AS ItemID ,
          t3.WareHouseID ,
          Company.f_PlaceGetFirstID1(t3.WareHouseID) AS PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @ItemExpirationDate AS t
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t.ItemSharedID AND t3.WareHouseID = @ToWarehouseID
        GROUP BY t.ItemSharedID ,
          t3.ID ,
          t3.WareHouseID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM @All AS t
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs;

  END;  

  BEGIN --Insert t_TransferDetailExpirationDate

    INSERT INTO Invoices.t_TransferDetailExpirationDate
        ( ID ,
          TransferID ,
          TransferDetailID ,
          ItemSharedID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          WorkStationID
        )
      SELECT s.ID ,
          @ID ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.NotificationDate ,
          s.CurrencyID ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs ,
          s.DateCreate ,
          s.WorkStationID
        FROM @ItemExpirationDate AS s;

  END;
  
  BEGIN --Merge t_ItemExpirationDate In
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( Items.f_ItemExpirationDateGetNewRef() ,
               N'-' ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               Company.f_WareHouseGetName(s.WareHouseID) ,
               s.PlaceID ,
               Company.f_PlaceGetName(s.PlaceID) ,
               158 ,
               @ID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               Currencys.f_CurrencyGetName(s.CurrencyID) ,
               s.Price ,
               Currencys.f_Format(s.CurrencyID, s.Price) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateLL() ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateEuro() ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

    UPDATE Items.t_ItemExpirationDate
      SET RefF = FORMAT(Ref, N'0')
      WHERE RefF = N'-';

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;




GO
