CREATE PROCEDURE [Invoices].[s_TransferDetailUpdateSerialNamesPART] @SerialIs Items.tt_ItemSerial READONLY
AS
BEGIN
  
  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @SerialIs AS s )
  BEGIN

    RETURN;
			    
  END;

  UPDATE Invoices.t_TransferDetail
    SET SerialNames = Invoices.f_TransferDetailGetSerialNames(ID)
