/****** Object:  StoredProcedure [Invoices].[s_TransferInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_TransferInsert] @DateIs DATETIME ,
  @FromWarehouseID UNIQUEIDENTIFIER ,
  @ToWarehouseID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Invoices.[tt_TransferDetail] READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemOut AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          SharedID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL
        );

      DECLARE @ItemIn AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          SharedID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL
        );

      DECLARE @ItemQtyNet AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @Total FLOAT ,
        @TaxRate DECIMAL(4, 2) = 0 ,
        @TaxValue FLOAT ,
        @NetIs FLOAT ,
        @Qtys DECIMAL(18, 6) ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM ( SELECT MAX(s.Ref) AS Ref
                FROM Invoices.t_Transfer AS s
               UNION
               SELECT MAX(s.Ref)
                FROM Invoices.t_Transfer AS s
             ) AS s;

      SELECT @Total = COALESCE(SUM(s.SubTotal), 0) ,
          @TaxValue = COALESCE(SUM(s.TaxValue), 0) ,
          @NetIs = COALESCE(SUM(s.Total), 0) ,
          @Qtys = COALESCE(SUM(s.Qtys), 0)
        FROM @DetailIs AS s;

      IF @Total > 0 AND @TaxValue > 0
      BEGIN

        SET @TaxRate = ( @TaxValue / @Total ) * 100;

      END;

    END;

    BEGIN --Insert

      SET @return = 0;

      INSERT INTO Invoices.t_Transfer
          ( ID ,
            Ref ,
            RefF ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            FromWarehouseID ,
            FromWarehouse ,
            ToWarehouseID ,
            ToWarehouse ,
            UserID ,
            UserIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            DescriptionIs ,
            Qtys
          )
        VALUES
          ( @ID ,
            @Ref ,
            FORMAT(@Ref, '#') ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @FromWarehouseID ,
            Company.f_WareHouseGetName(@FromWarehouseID) ,
            @ToWarehouseID ,
            Company.f_WareHouseGetName(@ToWarehouseID) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @CurrencyID ,
            Currencys.f_CurrencyGetName(@CurrencyID) ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Total ,
            Currencys.f_Format(@CurrencyID, @Total) ,
            @Total / @ExchangeRate ,
            ( @Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( @Total / @ExchangeRate ) * @ExchangeRateEuro ,
            @TaxRate ,
            Currencys.f_FormatRate(@TaxRate) ,
            @TaxValue ,
            Currencys.f_Format(@CurrencyID, @TaxValue) ,
            @TaxValue / @ExchangeRate ,
            ( @TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( @TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            @NetIs ,
            Currencys.f_Format(@CurrencyID, @NetIs) ,
            @NetIs / @ExchangeRate ,
            ( @NetIs / @ExchangeRate ) * @ExchangeRateLL ,
            ( @NetIs / @ExchangeRate ) * @ExchangeRateEuro ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
            @DescriptionIs ,
            @Qtys
          );

    END;

    BEGIN --Insert detail

      INSERT INTO Invoices.t_TransferDetail
          ( ID ,
            TransferID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemUnityID ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qtys ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DiscountIs ,
            Currencys.f_FormatRate(s.DiscountIs) ,
            s.DiscountIsValue ,
            Currencys.f_Format(@CurrencyID, s.DiscountIsValue) ,
            s.DiscountIsValue / @ExchangeRate ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.DiscountIsValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.SubTotal ,
            Currencys.f_Format(@CurrencyID, s.SubTotal) ,
            s.SubTotal / @ExchangeRate ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.SubTotal / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TaxRate ,
            Currencys.f_FormatRate(s.TaxRate) ,
            s.TaxValue ,
            Currencys.f_Format(@CurrencyID, s.TaxValue) ,
            s.TaxValue / @ExchangeRate ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.TaxValue / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

      INSERT INTO @ItemOut
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_TransferDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @FromWarehouseID
          WHERE s.TransferID = @ID;

      INSERT INTO @ItemIn
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s1.ID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Invoices.t_TransferDetail AS s
          LEFT JOIN Items.t_Item AS s1 ON s1.SharedID = s.ItemSharedID AND s1.WareHouseID = @ToWarehouseID
          WHERE s.TransferID = @ID;

    END;

    BEGIN --Insert detial serial

      INSERT INTO Invoices.t_TransferDetailSerial
          ( TransferID ,
            TransferDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update item serial

      UPDATE Items.t_ItemSerial
        SET ItemID = Items.f_ItemGetID(ItemSharedID, @ToWarehouseID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
  
    EXECUTE Invoices.s_TransferDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Invoices.s_TransferDetailExpirationDateInsertPART @ID, @FromWarehouseID, @ToWarehouseID, @ItemExpirationDate;
	
    BEGIN --Rebuild statistics

      UPDATE Invoices.t_Transfer
        SET ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Invoices.t_TransferDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.TransferID = t_Transfer.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @ID;

    END;

    BEGIN --Fix item qty

      INSERT INTO @ItemQtyNet
          ( ID ,
            Qty
          )
        SELECT o.ID ,
            COALESCE(SUM(o.Qty), 0)
          FROM ( SELECT s.ID ,
                    s.Qty
                  FROM @ItemIn AS s
                 UNION ALL
                 SELECT s.ID ,
                    0 - s.Qty
                  FROM @ItemOut AS s
               ) AS o
          GROUP BY o.ID;

      MERGE Items.t_Item AS t
      USING @ItemQtyNet AS s
      ON s.ID = t.ID AND t.TypeIs = 0
      WHEN MATCHED THEN
        UPDATE SET t.QtyCurrent += s.Qty;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Invoices.t_TransferMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Invoices].[s_TransferMovingInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Invoices].[s_TransferMovingInsert]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Invoices.t_TransferMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, @ID, @Event, 3, @ComputerIP, @Computer, @ComputerAccount);

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, TransferIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;
















GO
/****** Object:  StoredProcedure [Invoices].[s_TransferMovingTruncate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Invoices].[s_TransferMovingTruncate]
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Delete

            SET @Return = 0;

            TRUNCATE TABLE Invoices.t_TransferMoving;

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Invoices.t_TransferMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, '00000000-0000-0000-0000-000000000000', @Event, 4, @ComputerIP, @Computer, @ComputerAccount);

        END;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, TransferIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;















