/****** Object:  StoredProcedure [Invoices].[s_TransferUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Invoices].[s_TransferUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Invoices.tr_Transfer ON Invoices.t_Transfer;
    DISABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;
    DISABLE TRIGGER Invoices.tr_TransferDetailSerial ON Invoices.t_TransferDetailSerial;

    BEGIN --Update

      UPDATE  Invoices.t_Transfer
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_Transfer.ID );

      UPDATE  Invoices.t_TransferDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_TransferDetail.TransferID );

      UPDATE  Invoices.t_TransferDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_TransferDetailSerial.TransferID );
  
    END;

    ENABLE TRIGGER Invoices.tr_Transfer ON Invoices.t_Transfer;
    ENABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;
    ENABLE TRIGGER Invoices.tr_TransferDetailSerial ON Invoices.t_TransferDetailSerial;

    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, TransferIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaInvoice, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));
   
    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;









GO
