/****** Object:  StoredProcedure [Items].[s_AdditionsOnItemsImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_AdditionsOnItemsImport] @drs Items.tt_AdditionsOnItems READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Items.t_AdditionsOnItems AS t
      USING @drs AS s
      ON s.Name = t.Name
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( Name ,
                 CurrencyID ,
                 Cost ,
                 CostF ,
                 CostD ,
                 CostLL ,
                 CostEuro ,
                 SalePrice ,
                 SalePriceF ,
                 SalePriceD ,
                 SalePriceLL ,
                 SalePriceEuro ,
                 ColorIs ,
                 ColorInt
               )
        VALUES ( Name ,
                 CurrencyID ,
                 Cost ,
                 CostF ,
                 CostD ,
                 CostLL ,
                 CostEuro ,
                 SalePrice ,
                 SalePriceF ,
                 SalePriceD ,
                 SalePriceLL ,
                 SalePriceEuro ,
                 ColorIs ,
                 ColorInt
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Cost = s.Cost ,
                    t.CostF = s.CostF ,
                    t.CostD = s.CostD ,
                    t.CostLL = s.CostLL ,
                    t.CostEuro = s.CostEuro ,
                    t.SalePrice = s.SalePrice ,
                    t.SalePriceF = s.SalePriceF ,
                    t.SalePriceD = s.SalePriceD ,
                    t.SalePriceLL = s.SalePriceLL ,
                    t.SalePriceEuro = s.SalePriceEuro ,
                    t.ColorIs = s.ColorIs ,
                    t.ColorInt = s.ColorInt;

    END;

    SET @Return = -1;
    EXECUTE Items.s_AdditionsOnItemsMovingInsertPART N'00000000-0000-0000-0000-000000000000', @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    EXECUTE Items.s_AdditionsOnItemsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;




