GO


CREATE PROCEDURE [Items].[s_AlternativeItems_FixsByItemShared_CurrentQuantity_PART] @IDs Alls.tt_Guid READONLY
AS
BEGIN

  DECLARE @AlternativeItemsIDs Alls.tt_Guid;

  INSERT INTO @AlternativeItemsIDs
      ( ID
      )
    SELECT DISTINCT t.AlternativeItemsID
      FROM Items.t_AlternativeItemsDetails AS t
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t.ItemSharedID );

  IF EXISTS ( SELECT TOP ( 1 ) s.ID
                FROM @AlternativeItemsIDs AS s )
  BEGIN
    
    UPDATE Items.t_AlternativeItems
      SET CurrentQuantity = Items.f_AlternativeItemsGetCurrentQuantityNow(ID)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @AlternativeItemsIDs AS s
                      WHERE s.ID = t_AlternativeItems.ID );

    EXECUTE Items.s_AlternativeItemsLiveVersion;

  END;


END;




