/****** Object:  StoredProcedure [Items].[s_AlternativeItemsUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_AlternativeItemsUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @Barcode NVARCHAR(450) ,
  @BarcodeNumber BIGINT ,
  @QuantityToReorder FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @Details Items.tt_AlternativeItemsDetails READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Update

      UPDATE Items.t_AlternativeItems
        SET Name = @Name ,
            Barcode = @Barcode ,
            BarcodeNumber = @BarcodeNumber ,
            QuantityToReorder = @QuantityToReorder ,
            DescriptionIs = @DescriptionIs ,
            LastModifiedDate = GETDATE() ,
            ItemsCount = @ItemsCount
        WHERE ID = @ID;
	  
    END;

    BEGIN --Merge t_AlternativeItemsDetails

      MERGE Items.t_AlternativeItemsDetails AS t
      USING @Details AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 AlternativeItemsID ,
                 ItemSharedID ,
                 OrderBy ,
                 CreatedByUserID ,
                 DescriptionIs
               )
        VALUES ( s.ID ,
                 s.AlternativeItemsID ,
                 s.ItemSharedID ,
                 s.OrderBy ,
                 @UserID ,
                 s.DescriptionIs
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemSharedID = s.ItemSharedID ,
                    t.OrderBy = s.OrderBy ,
                    t.LastModifiedDate = GETDATE() ,
                    t.DescriptionIs = s.DescriptionIs
      WHEN NOT MATCHED BY SOURCE AND t.AlternativeItemsID = @ID THEN
        DELETE;
	  
    END;

    EXECUTE Items.s_AlternativeItems_Fix_CurrentQuantity_PART @ID;
    
    SET @Return = -1;
    EXECUTE Items.s_AlternativeItemsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Items.s_AlternativeItemsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;







GO
