/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @DateOnly DATE ,
        @ItemQtys AS Items.ItemAppendQtys ,
        @Return INT;

    END;

    BEGIN -- Set Info
    
      SELECT TOP ( 1 ) @DateOnly = s.DateIs
        FROM Items.t_BeginningInventoryQuantity AS s
        WHERE s.ID = @ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_BeginningInventoryQuantityDetail AS s
          WHERE s.BeginningInventoryQuantityID = @ID;

    END;

    EXECUTE Items.s_BeginningInventoryQuantityDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      SET @Return = 0;

      DELETE FROM Items.t_BeginningInventoryQuantityDetailSerial
        WHERE BeginningInventoryQuantityID = @ID;

      DELETE FROM Items.t_ItemSerial
        WHERE SectionType = 158 AND LinkID = @ID;

      DELETE FROM Items.t_BeginningInventoryQuantityDetail
        WHERE BeginningInventoryQuantityID = @ID;

      DELETE FROM Items.t_BeginningInventoryQuantity
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_BeginningInventoryQuantityMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE Invoices.s_ProfitDaily_LicenseProfit_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityDetailExpirationDateDeletePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityDetailExpirationDateDeletePART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @t AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );

  END;

  BEGIN --Set
   
    INSERT INTO @t
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          0 - ISNULL(SUM(t.Qtys), 0) AS Qtys ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Items.t_BeginningInventoryQuantityDetailExpirationDate AS t
		WHERE t.BeginningInventoryQuantityID = @ID
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

  END;  

  BEGIN --Delete t_BeginningInventoryQuantityDetailExpirationDate

    DELETE FROM Items.t_BeginningInventoryQuantityDetailExpirationDate
      WHERE BeginningInventoryQuantityID = @ID;

  END;
  
  BEGIN --Merge t_ItemExpirationDate
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;


GO
/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityDetailExpirationDateInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
