CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityInsert] @ID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @TotalLicenseCost FLOAT ,
  @TotalLicenseCostF NVARCHAR(MAX) ,
  @TotalLicenseCostD FLOAT ,
  @TotalLicenseCostLL FLOAT ,
  @TotalLicenseCostEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @TotalProfit FLOAT ,
  @TotalProfitF NVARCHAR(MAX) ,
  @TotalProfitD FLOAT ,
  @TotalProfitLL FLOAT ,
  @TotalProfitEuro FLOAT ,
  @Qtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @DetailIs Items.tt_BeginningInventoryQuantityDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @AutomaticallyUpdateCostAfterSave TINYINT ,
  @UpdateCostEventBase NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @DateOnly DATE = @DateIs ,
        @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @ItemQtys AS Items.ItemAppendQtys ,
        @ExchangeRateLL FLOAT = Currencys.f_CurrencyGetExchangeRateLL() ,
        @ExchangeRateEuro FLOAT = Currencys.f_CurrencyGetExchangeRateEuro() ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Items.t_BeginningInventoryQuantity AS s;
    
      SET @RefF = FORMAT(@Ref, '#');

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_BeginningInventoryQuantity
          ( ID ,
            Ref ,
            RefF ,
            DateIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            TotalLicenseCost ,
            TotalLicenseCostF ,
            TotalLicenseCostD ,
            TotalLicenseCostLL ,
            TotalLicenseCostEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            Qtys ,
            DescriptionIs ,
            ItemsNames
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @DateIs ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @TotalLicenseCost ,
            @TotalLicenseCostF ,
            @TotalLicenseCostD ,
            @TotalLicenseCostLL ,
            @TotalLicenseCostEuro ,
            @Total ,
            @TotalF ,
            @TotalD ,
            @TotalLL ,
            @TotalEuro ,
            @TotalProfit ,
            @TotalProfitF ,
            @TotalProfitD ,
            @TotalProfitLL ,
            @TotalProfitEuro ,
            @Qtys ,
            @DescriptionIs ,
            @ItemsNames
          );

    END;

    BEGIN --Insert t_BeginningInventoryQuantityDetail

      INSERT INTO Items.t_BeginningInventoryQuantityDetail
          ( ID ,
            BeginningInventoryQuantityID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            LicenseCost ,
            LicenseCostF ,
            LicenseCostD ,
            LicenseCostLL ,
            LicenseCostEuro ,
            TotalLicenseCost ,
            TotalLicenseCostF ,
            TotalLicenseCostD ,
            TotalLicenseCostLL ,
            TotalLicenseCostEuro ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            s.QtyWithUnity ,
            s.Qtys ,
            s.LicenseCost ,
            s.LicenseCostF ,
            s.LicenseCostD ,
            s.LicenseCostLL ,
            s.LicenseCostEuro ,
            s.TotalLicenseCost ,
            s.TotalLicenseCostF ,
            s.TotalLicenseCostD ,
            s.TotalLicenseCostLL ,
            s.TotalLicenseCostEuro ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            s.Total ,
            s.TotalF ,
            s.TotalD ,
            s.TotalLL ,
            s.TotalEuro ,
            s.Profit ,
            s.ProfitF ,
            s.ProfitD ,
            s.ProfitLL ,
            s.ProfitEuro ,
            s.TotalProfit ,
            s.TotalProfitF ,
            s.TotalProfitD ,
            s.TotalProfitLL ,
            s.TotalProfitEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            158 ,
            @ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_BeginningInventoryQuantityDetailSerial

      INSERT INTO Items.t_BeginningInventoryQuantityDetailSerial
          ( BeginningInventoryQuantityID ,
            BeginningInventoryQuantityDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;
	
    EXECUTE Items.s_BeginningInventoryQuantityDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Items.s_BeginningInventoryQuantityDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Insert t_BeginningInventoryQuantityMoving

      SET @return = -1;

      INSERT INTO Items.t_BeginningInventoryQuantityMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    IF @AutomaticallyUpdateCostAfterSave > 0 --Update t_ItemShared (Items Cost)
    BEGIN 

      BEGIN --Declare

        DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;
    
      END;

      BEGIN --Set Info

        INSERT INTO @ItemShared
            ( ID ,
              CurrencyID ,
              OldCost ,
              Cost ,
              EventIs
            )
          SELECT s.ItemSharedID ,
              s1.CurrencyID ,
              s1.Purchase ,
              CASE s2.TypeIs
                WHEN 0 THEN ( s.Price / s3.Qty ) / @ExchangeRate
                WHEN 1 THEN ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateLL
                ELSE ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateEuro
              END ,
              @UpdateCostEventBase + s1.PurchaseF
            FROM @DetailIs AS s
            INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
            INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
            INNER JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
            WHERE s.Price > 0;

        DELETE FROM @ItemShared
          WHERE OldCost = Cost;
  
        DELETE FROM @ItemShared
          WHERE OldCost > 0 AND @AutomaticallyUpdateCostAfterSave = 1;

        UPDATE @ItemShared
          SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

      END;
  
      EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @UpdateCostEventBase, @ComputerIP, @Computer, @ComputerAccount;

    END;

    EXECUTE Invoices.s_ProfitDaily_LicenseProfit_Update_PART @DateOnly;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
