AS
BEGIN

  BEGIN --Declare
	
    DECLARE @BeginningInventoryQuantity_ AS Items.tt_BeginningInventoryQuantity ,
      @Ref BIGINT ,
      @ItemQtys AS Items.ItemAppendQtys;

  END;

  BEGIN --Set info

    SELECT @Ref = ISNULL(MAX(s.Ref), 0)
      FROM Items.t_BeginningInventoryQuantity AS s;
    
    INSERT INTO @BeginningInventoryQuantity_
        ( ID ,
          Ref ,
          RefF ,
          DateIs ,
          CurrencyID ,
          Currency ,
          ExchangeRate ,
          TotalLicenseCost ,
          TotalLicenseCostF ,
          TotalLicenseCostD ,
          TotalLicenseCostLL ,
          TotalLicenseCostEuro ,
          Total ,
