          TotalProfitD ,
          TotalProfitLL ,
          TotalProfitEuro ,
          Qtys ,
          DescriptionIs ,
          ItemsNames ,
          UserID ,
          Event ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      SELECT t.ID ,
          @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 0
                                              ) ) ,
          t.RefF ,
          t.DateIs ,
          t.CurrencyID ,
          t.Currency ,
          t.ExchangeRate ,
          t.TotalLicenseCost ,
          t.TotalLicenseCostF ,
