          t.TotalProfitF ,
          t.TotalProfitD ,
          t.TotalProfitLL ,
          t.TotalProfitEuro ,
          t.Qtys ,
          t.DescriptionIs ,
          t.ItemsNames ,
          t.UserID ,
          t.Event ,
          t.EventType ,
          t.ComputerIP ,
          t.Computer ,
          t.ComputerAccount
        FROM @BeginningInventoryQuantity AS t;

    UPDATE @BeginningInventoryQuantity_
      SET RefF = FORMAT(Ref, N'#');

    INSERT INTO @ItemQtys
        ( ID ,
          SharedID ,
          Qty
        )
      SELECT s.ItemID ,
