          t.CurrencyID ,
          t.Currency ,
          t.ExchangeRate ,
          t.TotalLicenseCost ,
          t.TotalLicenseCostF ,
          t.TotalLicenseCostD ,
          t.TotalLicenseCostLL ,
          t.TotalLicenseCostEuro ,
          t.Total ,
          t.TotalF ,
          t.TotalD ,
          t.TotalLL ,
          t.TotalEuro ,
          t.TotalProfit ,
          t.TotalProfitF ,
          t.TotalProfitD ,
          t.TotalProfitLL ,
          t.TotalProfitEuro ,
          t.Qtys ,
          t.DescriptionIs ,
          t.ItemsNames
        FROM @BeginningInventoryQuantity_ AS t;

  END;

  BEGIN --Insert t_BeginningInventoryQuantityDetail

    INSERT INTO Items.t_BeginningInventoryQuantityDetail
        ( ID ,
          BeginningInventoryQuantityID ,
          ItemSharedID ,
          ItemID ,
          ItemUnityID ,
          Qty ,
          QtyWithUnity ,
          Qtys ,
          LicenseCost ,
          LicenseCostF ,
          LicenseCostD ,
          LicenseCostLL ,
          LicenseCostEuro ,
          TotalLicenseCost ,
          TotalLicenseCostF ,
          TotalLicenseCostD ,
          TotalLicenseCostLL ,
          TotalLicenseCostEuro ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          Total ,
          TotalF ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          Profit ,
          ProfitF ,
          ProfitD ,
          ProfitLL ,
          ProfitEuro ,
          TotalProfit ,
          TotalProfitF ,
          TotalProfitD ,
          TotalProfitLL ,
          TotalProfitEuro ,
          DescriptionIs ,
          SortAt
        )
      SELECT s.ID ,
          s.BeginningInventoryQuantityID ,
          s.ItemSharedID ,
          s.ItemID ,
          s.ItemUnityID ,
          s.Qty ,
          s.QtyWithUnity ,
          s.Qtys ,
          s.LicenseCost ,
          s.LicenseCostF ,
          s.LicenseCostD ,
          s.LicenseCostLL ,
          s.LicenseCostEuro ,
          s.TotalLicenseCost ,
          s.TotalLicenseCostF ,
          s.TotalLicenseCostD ,
          s.TotalLicenseCostLL ,
          s.TotalLicenseCostEuro ,
          s.Price ,
          s.PriceF ,
          s.PriceD ,
          s.PriceLL ,
          s.PriceEuro ,
          s.Total ,
          s.TotalF ,
          s.TotalD ,
          s.TotalLL ,
          s.TotalEuro ,
          s.Profit ,
          s.ProfitF ,
          s.ProfitD ,
          s.ProfitLL ,
          s.ProfitEuro ,
          s.TotalProfit ,
          s.TotalProfitF ,
          s.TotalProfitD ,
          s.TotalProfitLL ,
          s.TotalProfitEuro ,
