/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild Statistics

      UPDATE Items.t_BeginningInventoryQuantity
        SET RefF = FORMAT(Ref, '#') ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            TotalLicenseCostF = Currencys.f_Format(CurrencyID, TotalLicenseCost) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_BeginningInventoryQuantityDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.BeginningInventoryQuantityID = t_BeginningInventoryQuantity.ID
                                       FOR
                                         XML PATH('')
                                       ));

      WITH  o AS ( SELECT s.LicenseCost ,
                      s.LicenseCostF ,
                      s.TotalLicenseCost ,
                      s.TotalLicenseCostF ,
                      s.Price ,
                      s.PriceF ,
                      s.Total ,
                      s.TotalF ,
                      s.Profit ,
                      s.ProfitF ,
                      s.TotalProfit ,
                      s.TotalProfitF ,
                      s1.CurrencyID ,
                      s.Qty ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Items.t_BeginningInventoryQuantityDetail AS s
                    INNER JOIN Items.t_BeginningInventoryQuantity AS s1 ON s1.ID = s.BeginningInventoryQuantityID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE o
          SET o.LicenseCostF = Currencys.f_Format(o.CurrencyID, o.LicenseCost) ,
              o.TotalLicenseCostF = Currencys.f_Format(o.CurrencyID, o.TotalLicenseCost) ,
              o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
              o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
              o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit) ,
              o.TotalProfitF = Currencys.f_Format(o.CurrencyID, o.TotalProfit) ,
              o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    BEGIN --Insert t_BeginningInventoryQuantityMoving

      SET @Return = -1;

      INSERT INTO Items.t_BeginningInventoryQuantityMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityUpdate] @ID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @TotalLicenseCost FLOAT ,
  @TotalLicenseCostF NVARCHAR(MAX) ,
  @TotalLicenseCostD FLOAT ,
  @TotalLicenseCostLL FLOAT ,
  @TotalLicenseCostEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @TotalProfit FLOAT ,
  @TotalProfitF NVARCHAR(MAX) ,
  @TotalProfitD FLOAT ,
  @TotalProfitLL FLOAT ,
  @TotalProfitEuro FLOAT ,
  @Qtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @DetailIs Items.tt_BeginningInventoryQuantityDetail READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @AutomaticallyUpdateCostAfterSave TINYINT ,
  @UpdateCostEventBase NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @DateIs_OLD DATE ,
        @DateOnly DATE = @DateIs ,
        @ItemQtys AS Items.ItemAppendQtys ,
        @ExchangeRateLL FLOAT = Currencys.f_CurrencyGetExchangeRateLL() ,
        @ExchangeRateEuro FLOAT = Currencys.f_CurrencyGetExchangeRateEuro() ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @DateIs_OLD = s.DateIs
        FROM Items.t_BeginningInventoryQuantity AS s
        WHERE s.ID = @ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s
        UNION ALL
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_BeginningInventoryQuantityDetail AS s
          WHERE s.BeginningInventoryQuantityID = @ID;

    END;

    BEGIN --Declare and Set ItemExpirationDate

      DECLARE @ItemExpirationDate_Old [Items].[tt_ItemExpirationDate];
    
      INSERT INTO @ItemExpirationDate_Old
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID ,
            OriginalID ,
            FatherID1 ,
            FatherID2 ,
            EventIs
		  )
        SELECT s.ID ,
            0 ,
            N'' ,
            s.ItemSharedID ,
            s.ItemID ,
            s.WareHouseID ,
            N'' ,
            s.PlaceID ,
            N'' ,
            s.SectionIs ,
            s.SectionID ,
            N'' ,
            s.Qtys ,
            s.ProductionDate ,
            s.ExpirationDate ,
            s.NotifyMeDaysBefore ,
            s.NotificationDate ,
            s.CurrencyID ,
            N'' ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            s.BatchNumber ,
            s.DescriptionIs ,
            s.DateCreate ,
            s.IsSync ,
            s.WorkStationID ,
            s.OriginalID ,
            s.BeginningInventoryQuantityID ,
            s.BeginningInventoryQuantityDetailID ,
            N''
          FROM Items.t_BeginningInventoryQuantityDetailExpirationDate AS s
          WHERE s.BeginningInventoryQuantityID = @ID;

    END;

    BEGIN --Update

      UPDATE Items.t_BeginningInventoryQuantity
        SET DateIs = @DateIs ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            ExchangeRate = @ExchangeRate ,
            TotalLicenseCost = @TotalLicenseCost ,
            TotalLicenseCostF = @TotalLicenseCostF ,
            TotalLicenseCostD = @TotalLicenseCostD ,
            TotalLicenseCostLL = @TotalLicenseCostLL ,
            TotalLicenseCostEuro = @TotalLicenseCostEuro ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            TotalProfit = @TotalProfit ,
            TotalProfitF = @TotalProfitF ,
            TotalProfitD = @TotalProfitD ,
            TotalProfitLL = @TotalProfitLL ,
            TotalProfitEuro = @TotalProfitEuro ,
            Qtys = @Qtys ,
            DescriptionIs = @DescriptionIs ,
            ItemsNames = @ItemsNames
        WHERE ID = @ID;

    END;

    BEGIN --Merge t_BeginningInventoryQuantityDetail

      MERGE Items.t_BeginningInventoryQuantityDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 BeginningInventoryQuantityID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 LicenseCost ,
                 LicenseCostF ,
                 LicenseCostD ,
                 LicenseCostLL ,
                 LicenseCostEuro ,
                 TotalLicenseCost ,
                 TotalLicenseCostF ,
                 TotalLicenseCostD ,
                 TotalLicenseCostLL ,
                 TotalLicenseCostEuro ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 PriceLL ,
                 PriceEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 Profit ,
                 ProfitF ,
                 ProfitD ,
                 ProfitLL ,
                 ProfitEuro ,
                 TotalProfit ,
                 TotalProfitF ,
                 TotalProfitD ,
                 TotalProfitLL ,
                 TotalProfitEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.Qty ,
                 s.QtyWithUnity ,
                 s.Qtys ,
                 s.LicenseCost ,
                 s.LicenseCostF ,
                 s.LicenseCostD ,
                 s.LicenseCostLL ,
                 s.LicenseCostEuro ,
                 s.TotalLicenseCost ,
                 s.TotalLicenseCostF ,
                 s.TotalLicenseCostD ,
                 s.TotalLicenseCostLL ,
                 s.TotalLicenseCostEuro ,
                 s.Price ,
                 s.PriceF ,
                 s.PriceD ,
                 s.PriceLL ,
                 s.PriceEuro ,
                 s.Total ,
                 s.TotalF ,
                 s.TotalD ,
                 s.TotalLL ,
                 s.TotalEuro ,
                 s.Profit ,
                 s.ProfitF ,
                 s.ProfitD ,
                 s.ProfitLL ,
                 s.ProfitEuro ,
                 s.TotalProfit ,
                 s.TotalProfitF ,
                 s.TotalProfitD ,
                 s.TotalProfitLL ,
                 s.TotalProfitEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemID = s.ItemID ,
                    t.ItemUnityID = s.ItemUnityID ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = s.QtyWithUnity ,
                    t.Qtys = s.Qtys ,
                    t.LicenseCost = s.LicenseCost ,
                    t.LicenseCostF = s.LicenseCostF ,
                    t.LicenseCostD = s.LicenseCostD ,
                    t.LicenseCostLL = s.LicenseCostLL ,
                    t.LicenseCostEuro = s.LicenseCostEuro ,
                    t.TotalLicenseCost = s.TotalLicenseCost ,
                    t.TotalLicenseCostF = s.TotalLicenseCostF ,
                    t.TotalLicenseCostD = s.TotalLicenseCostD ,
                    t.TotalLicenseCostLL = s.TotalLicenseCostLL ,
                    t.TotalLicenseCostEuro = s.TotalLicenseCostEuro ,
                    t.Price = s.Price ,
                    t.PriceF = s.PriceF ,
                    t.PriceD = s.PriceD ,
                    t.PriceLL = s.PriceLL ,
                    t.PriceEuro = s.PriceEuro ,
                    t.Total = s.Total ,
                    t.TotalF = s.TotalF ,
                    t.TotalD = s.TotalD ,
                    t.TotalLL = s.TotalLL ,
                    t.TotalEuro = s.TotalEuro ,
                    t.Profit = s.Profit ,
                    t.ProfitF = s.ProfitF ,
                    t.ProfitD = s.ProfitD ,
                    t.ProfitLL = s.ProfitLL ,
                    t.ProfitEuro = s.ProfitEuro ,
                    t.TotalProfit = s.TotalProfit ,
                    t.TotalProfitF = s.TotalProfitF ,
                    t.TotalProfitD = s.TotalProfitD ,
                    t.TotalProfitLL = s.TotalProfitLL ,
                    t.TotalProfitEuro = s.TotalProfitEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.BeginningInventoryQuantityID = @ID THEN
        DELETE;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            158 ,
            @ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_BeginningInventoryQuantityDetailSerial

      INSERT INTO Items.t_BeginningInventoryQuantityDetailSerial
          ( BeginningInventoryQuantityID ,
            BeginningInventoryQuantityDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;
	
    EXECUTE Items.s_BeginningInventoryQuantityDetailUpdateSerialNamesPART @SerialIs;

    EXECUTE Items.s_BeginningInventoryQuantityDetailExpirationDateUpdatePART @ItemExpirationDate_Old, @ItemExpirationDate, @ID;  

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_BeginningInventoryQuantityMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    IF @AutomaticallyUpdateCostAfterSave > 0 --Update t_ItemShared (Items Cost)
    BEGIN 

      BEGIN --Declare

        DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;
    
      END;

      BEGIN --Set Info

        INSERT INTO @ItemShared
            ( ID ,
              CurrencyID ,
              OldCost ,
              Cost ,
              EventIs
            )
          SELECT s.ItemSharedID ,
              s1.CurrencyID ,
              s1.Purchase ,
              CASE s2.TypeIs
                WHEN 0 THEN ( s.Price / s3.Qty ) / @ExchangeRate
                WHEN 1 THEN ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateLL
                ELSE ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateEuro
              END ,
              @UpdateCostEventBase + s1.PurchaseF
            FROM @DetailIs AS s
            INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
            INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
            INNER JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
            WHERE s.Price > 0;

        DELETE FROM @ItemShared
          WHERE OldCost = Cost;
  
        DELETE FROM @ItemShared
          WHERE OldCost > 0 AND @AutomaticallyUpdateCostAfterSave = 1;

        UPDATE @ItemShared
          SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

      END;
  
      EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @UpdateCostEventBase, @ComputerIP, @Computer, @ComputerAccount;

    END;

    IF @DateIs_OLD = @DateIs
    BEGIN
                               
      EXECUTE Invoices.s_ProfitDaily_LicenseProfit_Update_PART @DateIs;

    END;
    ELSE
    BEGIN
    
      EXECUTE Invoices.s_ProfitDaily_LicenseProfit_Update_PART @DateIs_OLD;
      EXECUTE Invoices.s_ProfitDaily_LicenseProfit_Update_PART @DateIs;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;











GO
