/****** Object:  StoredProcedure [Items].[s_BeginningInventoryQuantityUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_BeginningInventoryQuantityUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Items.tr_BeginningInventoryQuantity ON Items.t_BeginningInventoryQuantity;
    DISABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    DISABLE TRIGGER Items.tr_BeginningInventoryQuantityDetailSerial ON Items.t_BeginningInventoryQuantityDetailSerial;

    BEGIN --Update

      UPDATE  Items.t_BeginningInventoryQuantity
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_BeginningInventoryQuantity.ID );
 
      UPDATE  Items.t_BeginningInventoryQuantityDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_BeginningInventoryQuantityDetail.BeginningInventoryQuantityID );
 
      UPDATE  Items.t_BeginningInventoryQuantityDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_BeginningInventoryQuantityDetailSerial.BeginningInventoryQuantityID );

    END;

    ENABLE TRIGGER Items.tr_BeginningInventoryQuantity ON Items.t_BeginningInventoryQuantity;
	ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetailSerial ON Items.t_BeginningInventoryQuantityDetailSerial;
	  
    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, BeginningInventoryQuantity, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;




