/****** Object:  StoredProcedure [Items].[s_BrandsImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_BrandsImport] @WithImage BIT ,
  @drs Items.tt_Brand READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Items.t_Brand AS t
      USING @drs AS s
      ON s.Name = t.Name
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( Name ,
                 ArabicName ,
                 DescriptionIs
               )
        VALUES ( Name ,
                 ArabicName ,
                 DescriptionIs
               )
      WHEN MATCHED THEN
        UPDATE SET t.ArabicName = s.ArabicName ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.RowVersionID = DateTimes.f_GetRowVersionID();

    END;

    IF @WithImage = 1 --Merge Images
    BEGIN
                   
      MERGE Items.t_Brand AS t
      USING @drs AS s
      ON s.Name = t.Name
      WHEN MATCHED THEN
        UPDATE SET t.ImageIs = s.ImageIs ,
                    t.ImageVersionID = DateTimes.f_GetRowVersionID();

    END;

    BEGIN --Rebuild

      WITH  o AS ( SELECT s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY OrderBy , Name ) AS NewOrderBy
                    FROM Items.t_Brand AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy;

    END;

    SET @Return = -1;
    EXECUTE Items.s_BrandsMovingInsertPART N'00000000-0000-0000-0000-000000000000', @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Items].[s_BrandsInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_BrandsInsert] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @ArabicName NVARCHAR(MAX) ,
  @ImageIs IMAGE ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @OrderBy INT ,
        @Return INT = 0;

    END;

    BEGIN --Set Info
    
      SELECT @OrderBy = ISNULL(MAX(s.OrderBy), 0) + 1
        FROM Items.t_Brand AS s;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_Brand
          ( ID ,
            Name ,
            ArabicName ,
            ImageIs ,
            DescriptionIs ,
            OrderBy
          )
        VALUES
          ( @ID ,
            @Name ,
            @ArabicName ,
            @ImageIs ,
            @DescriptionIs ,
            @OrderBy
          );
	  
    END;

    SET @Return = -1;
    EXECUTE Items.s_BrandsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Items.s_BrandsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




