/****** Object:  StoredProcedure [Items].[s_BrandsRebuild]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_BrandsRebuild] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild statistics

      UPDATE Items.t_Brand
        SET ItemC = ( SELECT COUNT(*) AS Total
                        FROM Items.t_ItemShared AS s
                        WHERE ( BrandID = t_Brand.ID )
                    ) ,
            SellC = ( SELECT COUNT(*) AS Total
                        FROM Invoices.t_SoldDetail AS t
                        LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                        LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                        WHERE ( t2.BrandID = t_Brand.ID )
                    ) ,
            SellQty = ( SELECT COALESCE(SUM(t.Qtys), 0) AS Total
                          FROM Invoices.t_SoldDetail AS t
                          LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                          LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                          WHERE ( t2.BrandID = t_Brand.ID )
                      ) ,
            SellReturnC = ( SELECT COUNT(*) AS Total
                              FROM Invoices.t_SoldReturnDetail AS t
                              LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                              LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                              WHERE ( t2.BrandID = t_Brand.ID )
                          ) ,
            SellReturnQty = ( SELECT COALESCE(SUM(t.Qtys), 0) AS Total
                                FROM Invoices.t_SoldReturnDetail AS t
                                LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                                WHERE ( t2.BrandID = t_Brand.ID )
                            ) ,
            PurchaseC = ( SELECT COUNT(*) AS Total
                            FROM Invoices.t_PurchasingDetail AS t
                            LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                            LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                            WHERE ( t2.BrandID = t_Brand.ID )
                        ) ,
            PurchaseQty = ( SELECT COALESCE(SUM(t.Qtys), 0) AS Total
                              FROM Invoices.t_PurchasingDetail AS t
                              LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                              LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                              WHERE ( t2.BrandID = t_Brand.ID )
                          ) ,
            PurchaseReturnC = ( SELECT COUNT(*) AS Total
                                  FROM Invoices.t_PurchasingReturnDetail AS s
                                  LEFT JOIN Items.t_Item AS t ON t.ID = s.ItemID
                                  LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.SharedID
                                  WHERE ( t1.BrandID = t_Brand.ID )
                              ) ,
            PurchaseReturnQty = ( SELECT COALESCE(SUM(t.Qtys), 0) AS Total
                                    FROM Invoices.t_PurchasingReturnDetail AS t
                                    LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                    LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                                    WHERE ( t2.BrandID = t_Brand.ID )
                                ) ,
            RowVersionID = DateTimes.f_GetRowVersionID();

    END;

    BEGIN --Reorder
    
      WITH  o AS ( SELECT s.Name ,
                      s.ArabicName ,
                      s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY Name ) AS NewOrderBy
                    FROM Items.t_Brand AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy;

    END;

    SET @Return = -1;
    EXECUTE Items.s_BrandsMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 6, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Items.s_BrandsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;


GO
/****** Object:  StoredProcedure [Items].[s_BrandsUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_BrandsUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @ArabicName NVARCHAR(MAX) ,
  @ImageIs IMAGE ,
  @ImageEdited BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0 ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Items.t_Brand AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      UPDATE Items.t_Brand
        SET Name = @Name ,
            ArabicName = @ArabicName ,
            ImageIs = @ImageIs ,
            DescriptionIs = @DescriptionIs ,
            RowVersionID = DateTimes.f_GetRowVersionID() ,
            ImageVersionID = IIF(@ImageEdited = 1, DateTimes.f_GetRowVersionID(), ImageVersionID)
        WHERE ID = @ID;

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Fix Item Shared

        UPDATE Items.t_ItemShared
          SET Brand = @Name
          WHERE BrandID = @ID;

      END;

      BEGIN --t_Customer

        UPDATE Customers.t_Customer
          SET PrescriptionBrand = @Name
          WHERE PrescriptionBrandID = @ID;

      END;

      BEGIN --t_Prescription

        UPDATE Customers.t_Prescription
          SET Brand = @Name
          WHERE BrandID = @ID;

      END;

    END;

    SET @Return = -1;
    EXECUTE Items.s_BrandsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Items.s_BrandsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;









