/****** Object:  StoredProcedure [Items].[s_BrandsUpdateOrderBy]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_BrandsUpdateOrderBy] @IDAndEvent Alls.tt_IDOrderByEvent READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update 

      MERGE Items.t_Brand AS t
      USING @IDAndEvent AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.OrderBy = s.OrderBy ,
                    t.RowVersionID = DateTimes.f_GetRowVersionID();

      WITH  o AS ( SELECT s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy ,
                      s.RowVersionID
                    FROM Items.t_Brand AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy ,
              o.RowVersionID = DateTimes.f_GetRowVersionID();

    END;
	
    SET @Return = -1;
    EXECUTE Items.s_BrandsMovingInsertsPART @IDAndEvent, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
	
    EXECUTE Items.s_BrandsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;












