CREATE PROCEDURE [Items].[s_BrandsUpdateOrderByDown] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDOld UNIQUEIDENTIFIER ,
        @OrderByOld BIGINT ,
        @OrderByNew BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OrderByOld = s.OrderBy
        FROM Items.t_Brand AS s
        WHERE s.ID = @ID;

      SELECT TOP ( 1 ) @IDOld = s.ID ,
          @OrderByNew = s.OrderBy
        FROM Items.t_Brand AS s
        WHERE s.OrderBy > @OrderByOld
        ORDER BY s.OrderBy;

      IF @OrderByNew IS NULL
      BEGIN
                             
        RETURN 1;

      END;

    END;

    BEGIN --Update

      UPDATE Items.t_Brand
        SET OrderBy = @OrderByNew ,
            RowVersionID = DateTimes.f_GetRowVersionID()
        WHERE ID = @ID;
 
      UPDATE Items.t_Brand
        SET OrderBy = @OrderByOld ,
            RowVersionID = DateTimes.f_GetRowVersionID()
        WHERE ID = @IDOld;

      WITH  o AS ( SELECT s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy ,
                      s.RowVersionID
                    FROM Items.t_Brand AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy ,
              o.RowVersionID = DateTimes.f_GetRowVersionID();

    END;

    BEGIN --Insert event

      SET @Return = -1;

      DECLARE @Event2 NVARCHAR(MAX) = @Event;

      SET @Event = REPLACE(@Event, @OrderByOld, @OrderByNew);
      SET @Event2 = REPLACE(@Event2, @OrderByNew, @OrderByOld);

      EXECUTE Items.s_BrandsMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
      EXECUTE Items.s_BrandsMovingInsertPART @IDOld, @UserID, @Event2, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
 
    END;

    EXECUTE Items.s_BrandsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



