SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_DeletedAlternativeItemsLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, DeletedAlternativeItems, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;




