/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_DeliveryPermissionDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @StatusNow TINYINT ,
        @Return INT = 0;

    END;

    BEGIN --Set Info
    
      SELECT TOP ( 1 ) @StatusNow = s.StatusNow
        FROM Items.t_DeliveryPermission AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_DeliveryPermissionDelete
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            SaveFromSection ,
            LinkID ,
            LinkRef ,
            LinkRefF ,
            DateIs ,
            DateOnly ,
            TimeOnly ,
            DateMonthly ,
            DateYearly ,
            AccountID ,
            Account ,
            AccountNumber ,
            WarehouseID ,
            Warehouse ,
            StatusNow ,
            DescriptionIs ,
            CreateByUserID ,
            CreateByUser ,
			DeliveryDeadline ,
            DeliveredByUserID ,
            DeliveredByUser ,
            DeliveredDate ,
            ConsumedPeriodMinutes ,
            ConsumedPeriodF ,
            ItemsCount ,
            ItemsNames ,
            TotalQuantity ,
            HasSerial ,
            DateCreate ,
            IsSync ,
            WorkStationID
	      )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.RefPaper ,
            t.SaveFromSection ,
            t.LinkID ,
            t.LinkRef ,
            t.LinkRefF ,
            t.DateIs ,
            t.DateOnly ,
            t.TimeOnly ,
            t.DateMonthly ,
            t.DateYearly ,
            t.AccountID ,
            t.Account ,
            t.AccountNumber ,
            t.WarehouseID ,
            t.Warehouse ,
            t.StatusNow ,
            t.DescriptionIs ,
            t.CreateByUserID ,
            t.CreateByUser ,
            t.DeliveryDeadline ,
            t.DeliveredByUserID ,
            t.DeliveredByUser ,
            t.DeliveredDate ,
            t.ConsumedPeriodMinutes ,
            t.ConsumedPeriodF ,
            t.ItemsCount ,
            t.ItemsNames ,
            t.TotalQuantity ,
            t.HasSerial ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermission AS t
          WHERE t.ID = @ID;

      INSERT INTO Items.t_DeliveryPermissionDeleteDetail
          ( ID ,
            DeliveryPermissionDeleteID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            SortAt ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.DeliveryPermissionID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.DescriptionIs ,
            t.SortAt ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermissionDetail AS t
          WHERE t.DeliveryPermissionID = @ID;

    END;

    BEGIN --Delete
	
      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Items.t_DeliveryPermissionDetailSerial AS s
                        WHERE s.SerialID = t_ItemSerial.ID );

      DELETE FROM Items.t_DeliveryPermissionDetailSerial
        WHERE DeliveryPermissionID = @ID;

      DELETE FROM Items.t_DeliveryPermissionDetail
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          Deleted.Qtys
          INTO @ItemQtys
        WHERE DeliveryPermissionID = @ID;

      DELETE FROM Items.t_DeliveryPermission
        WHERE ID = @ID;

    END;

    IF @StatusNow <> 0
    BEGIN 
  
      --Fix Item Qty
      EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;
	
    END;

    BEGIN --Insert Event

      SET @Return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





