/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionDeleteRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionDeleteRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @RebuildingStatistics NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @NetIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      INSERT INTO @NetIDs
          ( ID )
        SELECT s.ID
          FROM @IDs AS s;

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s )
      BEGIN
    
        INSERT INTO @NetIDs
            ( ID
            )
          SELECT s.ID
            FROM Items.t_DeliveryPermissionDelete AS s;

      END;

    END;

    IF @RebuildingStatistics = 'All'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET RefF = FORMAT(Ref, '#') ,
            Account = Company.f_AccountGetName(AccountID) ,
            AccountNumber = Company.f_AccountGetNumberF(AccountID) ,
            Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
            CreateByUser = Users.f_UserGetName(CreateByUserID) ,
            DeliveredByUser = Users.f_UserGetName(DeliveredByUserID) ,
            ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
            ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '') ,
            ItemsCount = ( SELECT COUNT(t.ID)
                            FROM Items.t_DeliveryPermissionDeleteDetail AS t
                            INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                            WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                         ) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_DeliveryPermissionDeleteDetail AS t
                                          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            TotalQuantity = ( SELECT ISNULL(SUM(t.Qtys), 0)
                                FROM Items.t_DeliveryPermissionDeleteDetail AS t
                                INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                            )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

      WITH  o AS ( SELECT s.Qty ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Items.t_DeliveryPermissionDeleteDetail AS s
                    INNER JOIN Items.t_DeliveryPermissionDelete AS s1 ON s1.ID = s.DeliveryPermissionDeleteID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                    WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                    FROM @NetIDs AS ss
                                    WHERE ss.ID = s.DeliveryPermissionDeleteID )
                 )
        UPDATE o
          SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    IF @RebuildingStatistics = 'Ref'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET RefF = FORMAT(Ref, '#')
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

    END;

    IF @RebuildingStatistics = 'Account'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET Account = Company.f_AccountGetName(AccountID) ,
            AccountNumber = Company.f_AccountGetNumberF(AccountID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

    END;

    IF @RebuildingStatistics = 'Warehouse'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET Warehouse = Company.f_WareHouseGetName(WarehouseID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

    END;

    IF @RebuildingStatistics = 'Users'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET CreateByUser = Users.f_UserGetName(CreateByUserID) ,
            DeliveredByUser = Users.f_UserGetName(DeliveredByUserID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

    END;

    IF @RebuildingStatistics = 'Consumed Period'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
            ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '')
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

    END;

    IF @RebuildingStatistics = 'Items'
    BEGIN

      UPDATE Items.t_DeliveryPermissionDelete
        SET ItemsCount = ( SELECT COUNT(t.ID)
                            FROM Items.t_DeliveryPermissionDeleteDetail AS t
                            INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                            WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                         ) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_DeliveryPermissionDeleteDetail AS t
                                          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            TotalQuantity = ( SELECT ISNULL(SUM(t.Qtys), 0)
                                FROM Items.t_DeliveryPermissionDeleteDetail AS t
                                INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                WHERE t.DeliveryPermissionDeleteID = t_DeliveryPermissionDelete.ID
                            )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDelete.ID );

      WITH  o AS ( SELECT s.Qty ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Items.t_DeliveryPermissionDeleteDetail AS s
                    INNER JOIN Items.t_DeliveryPermissionDelete AS s1 ON s1.ID = s.DeliveryPermissionDeleteID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                    WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                    FROM @NetIDs AS ss
                                    WHERE ss.ID = s.DeliveryPermissionDeleteID )
                 )
        UPDATE o
          SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










