CREATE PROCEDURE [Items].[s_DeliveryPermissionDeleteUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Items.tr_DeliveryPermissionDelete ON Items.t_DeliveryPermissionDelete;
    DISABLE TRIGGER Items.tr_DeliveryPermissionDeleteDetail ON Items.t_DeliveryPermissionDeleteDetail;

    BEGIN --Update

      UPDATE  Items.t_DeliveryPermissionDelete
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_DeliveryPermissionDelete.ID );
 
      UPDATE  Items.t_DeliveryPermissionDeleteDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_DeliveryPermissionDeleteDetail.DeliveryPermissionDeleteID );
 
    END;

    ENABLE TRIGGER Items.tr_DeliveryPermissionDelete ON Items.t_DeliveryPermissionDelete;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDeleteDetail ON Items.t_DeliveryPermissionDeleteDetail;
	  
    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, DeliveryPermissionDelete, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;









