/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionFixPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionFixPART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  UPDATE Items.t_DeliveryPermission
    SET RefF = FORMAT(Ref, '#') ,
        LinkRefF = FORMAT(LinkRef, '#') ,
        DateOnly = DateIs ,
        TimeOnly = DateIs ,
        DateMonthly = DATEFROMPARTS(YEAR(DateIs), MONTH(DateIs), 1) ,
        DateYearly = DATEFROMPARTS(YEAR(DateIs), 1, 1) ,
        Account = Company.f_AccountGetName(AccountID) ,
        AccountNumber = Company.f_AccountGetNumberF(AccountID) ,
        Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
        CreateByUser = Users.f_UserGetName(CreateByUserID) ,
        DeliveredByUser = Users.f_UserGetName(DeliveredByUserID) ,
        ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
        ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '') ,
        ItemsCount = ( SELECT COUNT(t.ID)
                        FROM Items.t_DeliveryPermissionDetail AS t
                        INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                        WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                     ) ,
        ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                      FROM Items.t_DeliveryPermissionDetail AS t
                                      INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                      WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                                   FOR
                                     XML PATH('')
                                   )) ,
        TotalQuantity = ( SELECT ISNULL(SUM(t.Qtys), 0)
                            FROM Items.t_DeliveryPermissionDetail AS t
                            INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                            WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                        ) ,
        HasSerial = ( SELECT IIF(COUNT(t.ID) = 0, 0, 1)
                        FROM Items.t_DeliveryPermissionDetailSerial AS t
                        WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                    )
    WHERE t_DeliveryPermission.ID = @ID;

  WITH  o AS ( SELECT s.Qty ,
                  s.QtyWithUnity ,
                  s3.Name AS Unity
                FROM Items.t_DeliveryPermissionDetail AS s
                INNER JOIN Items.t_DeliveryPermission AS s1 ON s1.ID = s.DeliveryPermissionID
                INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                WHERE s.DeliveryPermissionID = @ID
             )
    UPDATE o
      SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

END;




