/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionHistoryUpdateNotSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [Items].[s_DeliveryPermissionHistoryUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Items.tr_DeliveryPermissionHistory ON Items.t_DeliveryPermissionHistory;
    DISABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    DISABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetailSerial ON Items.t_DeliveryPermissionHistoryDetailSerial;

    BEGIN --Update

      UPDATE  Items.t_DeliveryPermissionHistory
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_DeliveryPermissionHistory.ID );
 
      UPDATE  Items.t_DeliveryPermissionHistoryDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_DeliveryPermissionHistoryDetail.DeliveryPermissionHistoryID );
 
      UPDATE  Items.t_DeliveryPermissionHistoryDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_DeliveryPermissionHistoryDetailSerial.DeliveryPermissionHistoryID );

    END;

    ENABLE TRIGGER Items.tr_DeliveryPermissionHistory ON Items.t_DeliveryPermissionHistory;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetailSerial ON Items.t_DeliveryPermissionHistoryDetailSerial;
	  
    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, DeliveryPermissionHistory, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;








