/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionInsert] @RefPaper NVARCHAR(MAX) ,
  @SaveFromSection TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @LinkRef BIGINT ,
  @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @StatusNow TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DeliveryDeadline DATE ,
  @DetailIs Items.[tt_DeliveryPermissionDetail] READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate Items.tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @DraftID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Ref BIGINT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(o.Ref), 0) + 1
        FROM ( SELECT s.Ref
                FROM Items.t_DeliveryPermission AS s
               UNION ALL
               SELECT s.Ref
                FROM Items.t_DeliveryPermissionHistory AS s
             ) AS o;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s;

    END;

    IF @DraftID <> '00000000-0000-0000-0000-000000000000'
    BEGIN
   
      SELECT TOP ( 1 ) @Ref = s.Ref
        FROM Items.t_DeliveryPermission AS s
        WHERE s.ID = @DraftID;
                                             
      DELETE FROM Items.t_DeliveryPermissionDetail
        WHERE DeliveryPermissionID = @DraftID;   
		   
      DELETE FROM Items.t_DeliveryPermission
        WHERE ID = @DraftID;      

    END;

    BEGIN --Insert

      INSERT INTO Items.t_DeliveryPermission
          ( ID ,
            Ref ,
            RefPaper ,
            SaveFromSection ,
            LinkID ,
            LinkRef ,
            DateIs ,
            AccountID ,
            WarehouseID ,
            StatusNow ,
            DescriptionIs ,
            CreateByUserID ,
            DeliveryDeadline ,
            DeliveredByUserID ,
            DeliveredDate
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefPaper ,
            @SaveFromSection ,
            @LinkID ,
            @LinkRef ,
            @DateIs ,
            @AccountID ,
            @WarehouseID ,
            @StatusNow ,
            @DescriptionIs ,
            @UserID ,
            @DeliveryDeadline ,
            IIF(@StatusNow = 2, @UserID, '00000000-0000-0000-0000-000000000000') ,
            IIF(@StatusNow = 2, @DateIs, DATEFROMPARTS(2000, 1, 1))
          );

    END;

    BEGIN --Insert t_DeliveryPermissionDetail

      INSERT INTO Items.t_DeliveryPermissionDetail
          ( ID ,
            DeliveryPermissionID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            Qtys ,
            DescriptionIs ,
            SortAt 
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            s.Qtys ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s;

    END;

    BEGIN --Insert t_DeliveryPermissionDetailSerial

      INSERT INTO Items.t_DeliveryPermissionDetailSerial
          ( DeliveryPermissionID ,
            DeliveryPermissionDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update t_ItemSerial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
	
    EXECUTE Items.s_DeliveryPermissionDetailUpdateSerialNamesPART @SerialIs;

	--Fix t_DeliveryPermission
    EXECUTE Items.s_DeliveryPermissionFixPART @ID;
	
    IF @StatusNow <> 0
    BEGIN
	                       
	--Fix t_ItemExpirationDate
      EXECUTE [Items].[s_ItemExpirationDateReduceQtysPART] @ItemExpirationDate;

	--Fix Item Qty
      EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + FORMAT(@Ref, '#') ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionMoveFromHistory]    Script Date: 28-03-2026 08:37:02 PM ******/
