CREATE PROCEDURE [Items].[s_DeliveryPermissionMoveFromHistory] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    BEGIN --Insert t_DeliveryPermission

      INSERT INTO Items.t_DeliveryPermission
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            SaveFromSection ,
            LinkID ,
            LinkRef ,
            LinkRefF ,
            DateIs ,
            DateOnly ,
            TimeOnly ,
            DateMonthly ,
            DateYearly ,
            AccountID ,
            Account ,
            AccountNumber ,
            WarehouseID ,
            Warehouse ,
            StatusNow ,
            DescriptionIs ,
            CreateByUserID ,
            CreateByUser ,
			DeliveryDeadline ,
            DeliveredByUserID ,
            DeliveredByUser ,
            DeliveredDate ,
            ConsumedPeriodMinutes ,
            ConsumedPeriodF ,
            ItemsCount ,
            ItemsNames ,
            TotalQuantity ,
            HasSerial ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.RefPaper ,
            t.SaveFromSection ,
            t.LinkID ,
            t.LinkRef ,
            t.LinkRefF ,
            t.DateIs ,
            t.DateOnly ,
            t.TimeOnly ,
            t.DateMonthly ,
            t.DateYearly ,
            t.AccountID ,
            t.Account ,
            t.AccountNumber ,
            t.WarehouseID ,
            t.Warehouse ,
            t.StatusNow ,
            t.DescriptionIs ,
            t.CreateByUserID ,
            t.CreateByUser ,
            t.DeliveryDeadline ,
            t.DeliveredByUserID ,
            t.DeliveredByUser ,
            t.DeliveredDate ,
            t.ConsumedPeriodMinutes ,
            t.ConsumedPeriodF ,
            t.ItemsCount ,
            t.ItemsNames ,
            t.TotalQuantity ,
            t.HasSerial ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermissionHistory AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

    END;

    BEGIN --Insert t_DeliveryPermissionDetail

      INSERT INTO Items.t_DeliveryPermissionDetail
          ( ID ,
            DeliveryPermissionID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            SerialNames ,
            SortAt ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.DeliveryPermissionHistoryID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.ItemUnityID ,
            t.Qty ,
            t.QtyWithUnity ,
            t.Qtys ,
            t.DescriptionIs ,
            t.SerialNames ,
            t.SortAt ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermissionHistoryDetail AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.DeliveryPermissionHistoryID );

    END;

    BEGIN --Insert t_DeliveryPermissionDetailSerial

      INSERT INTO Items.t_DeliveryPermissionDetailSerial
          ( ID ,
            DeliveryPermissionID ,
            DeliveryPermissionDetailID ,
            SerialID ,
            DateCreate ,
            IsSync ,
            WorkStationID
          )
        SELECT t.ID ,
            t.DeliveryPermissionHistoryID ,
            t.DeliveryPermissionHistoryDetailID ,
            t.SerialID ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermissionHistoryDetailSerial AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.DeliveryPermissionHistoryID );

    END;

    BEGIN --Delete

      DELETE FROM Items.t_DeliveryPermissionHistoryDetailSerial
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_DeliveryPermissionHistoryDetailSerial.DeliveryPermissionHistoryID );
 
      DELETE FROM Items.t_DeliveryPermissionHistoryDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_DeliveryPermissionHistoryDetail.DeliveryPermissionHistoryID );

      DELETE FROM Items.t_DeliveryPermissionHistory
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_DeliveryPermissionHistory.ID );

    END;
	
    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;




