            WorkStationID
          )
        SELECT t.ID ,
            t.DeliveryPermissionID ,
            t.DeliveryPermissionDetailID ,
            t.SerialID ,
            t.DateCreate ,
            0 ,
            t.WorkStationID
          FROM Items.t_DeliveryPermissionDetailSerial AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @NetIDs AS s
                          WHERE s.ID = t.DeliveryPermissionID );

    END;

    BEGIN --Delete

      DELETE FROM Items.t_DeliveryPermissionDetailSerial
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDetailSerial.DeliveryPermissionID );
 
      DELETE FROM Items.t_DeliveryPermissionDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermissionDetail.DeliveryPermissionID );

      DELETE FROM Items.t_DeliveryPermission
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;
	
    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @NetIDs AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



