/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @RebuildingStatistics NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @NetIDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set info
    
      INSERT INTO @NetIDs
          ( ID )
        SELECT s.ID
          FROM @IDs AS s;

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s )
      BEGIN
    
        INSERT INTO @NetIDs
            ( ID
            )
          SELECT s.ID
            FROM Items.t_DeliveryPermission AS s;

      END;

    END;

    IF @RebuildingStatistics = 'All'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET RefF = FORMAT(Ref, '#') ,
            Account = Company.f_AccountGetName(AccountID) ,
            AccountNumber = Company.f_AccountGetNumberF(AccountID) ,
            Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
            CreateByUser = Users.f_UserGetName(CreateByUserID) ,
            DeliveredByUser = Users.f_UserGetName(DeliveredByUserID) ,
            ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
            ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '') ,
            ItemsCount = ( SELECT COUNT(t.ID)
                            FROM Items.t_DeliveryPermissionDetail AS t
                            INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                            WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                         ) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_DeliveryPermissionDetail AS t
                                          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            TotalQuantity = ( SELECT ISNULL(SUM(t.Qtys), 0)
                                FROM Items.t_DeliveryPermissionDetail AS t
                                INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                            )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

      WITH  o AS ( SELECT s.Qty ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Items.t_DeliveryPermissionDetail AS s
                    INNER JOIN Items.t_DeliveryPermission AS s1 ON s1.ID = s.DeliveryPermissionID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                    WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                    FROM @NetIDs AS ss
                                    WHERE ss.ID = s.DeliveryPermissionID )
                 )
        UPDATE o
          SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    IF @RebuildingStatistics = 'Ref'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET RefF = FORMAT(Ref, '#')
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;

    IF @RebuildingStatistics = 'Account'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET Account = Company.f_AccountGetName(AccountID) ,
            AccountNumber = Company.f_AccountGetNumberF(AccountID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;

    IF @RebuildingStatistics = 'Warehouse'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET Warehouse = Company.f_WareHouseGetName(WarehouseID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;

    IF @RebuildingStatistics = 'Users'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET CreateByUser = Users.f_UserGetName(CreateByUserID) ,
            DeliveredByUser = Users.f_UserGetName(DeliveredByUserID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;

    IF @RebuildingStatistics = 'Consumed Period'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
            ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '')
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

    END;

    IF @RebuildingStatistics = 'Items'
    BEGIN

      UPDATE Items.t_DeliveryPermission
        SET ItemsCount = ( SELECT COUNT(t.ID)
                            FROM Items.t_DeliveryPermissionDetail AS t
                            INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                            WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                         ) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_DeliveryPermissionDetail AS t
                                          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            TotalQuantity = ( SELECT ISNULL(SUM(t.Qtys), 0)
                                FROM Items.t_DeliveryPermissionDetail AS t
                                INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                WHERE t.DeliveryPermissionID = t_DeliveryPermission.ID
                            )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @NetIDs AS s
                        WHERE s.ID = t_DeliveryPermission.ID );

      WITH  o AS ( SELECT s.Qty ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Items.t_DeliveryPermissionDetail AS s
                    INNER JOIN Items.t_DeliveryPermission AS s1 ON s1.ID = s.DeliveryPermissionID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                    WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                    FROM @NetIDs AS ss
                                    WHERE ss.ID = s.DeliveryPermissionID )
                 )
        UPDATE o
          SET o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









GO
/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionUpdate] @RefPaper NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @StatusNow TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DeliveryDeadline DATE ,
  @DetailIs Items.[tt_DeliveryPermissionDetail] READONLY ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @StatusNowOld TINYINT ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @StatusNowOld = s.StatusNow
        FROM Items.t_DeliveryPermission AS s
        WHERE s.ID = @ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM Items.t_DeliveryPermissionDetail AS s
          WHERE s.DeliveryPermissionID = @ID;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @DetailIs AS s;

    END;

    BEGIN --Insert

      UPDATE Items.t_DeliveryPermission
        SET RefPaper = @RefPaper ,
            DateIs = @DateIs ,
            AccountID = @AccountID ,
            WarehouseID = @WarehouseID ,
            StatusNow = @StatusNow ,
            DeliveryDeadline = @DeliveryDeadline ,
            DeliveredByUserID = IIF(@StatusNow = 2, IIF(@StatusNowOld = 2, DeliveredByUserID, @UserID), '00000000-0000-0000-0000-000000000000') ,
            DeliveredDate = IIF(@StatusNow = 2, IIF(@StatusNowOld = 2, DeliveredDate, @DateIs), DATEFROMPARTS(2000, 1, 1)) ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_DeliveryPermissionDetail

      MERGE Items.t_DeliveryPermissionDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 DeliveryPermissionID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 Qty ,
                 Qtys ,
                 DescriptionIs ,
                 SortAt 
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.Qty ,
                 s.Qtys ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemUnityID = s.ItemUnityID ,
                    t.Qty = s.Qty ,
                    t.Qtys = s.Qtys ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.DeliveryPermissionID = @ID THEN
        DELETE;

    END;

    BEGIN --Insert t_DeliveryPermissionDetailSerial

      INSERT INTO Items.t_DeliveryPermissionDetailSerial
          ( DeliveryPermissionID ,
            DeliveryPermissionDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Update t_ItemSerial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIs AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
	
    EXECUTE Items.s_DeliveryPermissionDetailUpdateSerialNamesPART @SerialIs;

	--Fix t_DeliveryPermission
    EXECUTE Items.s_DeliveryPermissionFixPART @ID;--Fix t_DeliveryPermissionz
	
	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;

GO
/****** Object:  StoredProcedure [Items].[s_DeliveryPermissionUpdateDelivered]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_DeliveryPermissionUpdateDelivered] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @NetIDs Alls.tt_Guid ,
        @return INT = 0;

    END;

    BEGIN --Set info
	    
      INSERT INTO @NetIDs
          ( ID
          )
        SELECT t.ID
          FROM Items.t_DeliveryPermission AS t
          WHERE t.StatusNow = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                              FROM @IDs AS s
                                              WHERE s.ID = t.ID );
    END;

    BEGIN --Insert

      UPDATE Items.t_DeliveryPermission
        SET StatusNow = 2 ,
            DeliveredByUserID = @UserID ,
            DeliveredByUser = Users.f_UserGetName(@UserID) ,
            DeliveredDate = GETDATE()
        WHERE StatusNow = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                          FROM @NetIDs AS s
                                          WHERE s.ID = t_DeliveryPermission.ID );
  
      UPDATE Items.t_DeliveryPermission
        SET ConsumedPeriodMinutes = DATEDIFF(MINUTE, DateIs, DeliveredDate) ,
            ConsumedPeriodF = DateTimes.f_DateTimeDiff(DateIs, DeliveredDate, 'd', 1, '', '')
        WHERE StatusNow = 1 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                          FROM @NetIDs AS s
                                          WHERE s.ID = t_DeliveryPermission.ID );

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_DeliveryPermissionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @NetIDs AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



GO
