CREATE PROCEDURE [Items].[s_DeliveryPermissionUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Items.tr_DeliveryPermission ON Items.t_DeliveryPermission;
    DISABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    DISABLE TRIGGER Items.tr_DeliveryPermissionDetailSerial ON Items.t_DeliveryPermissionDetailSerial;

    BEGIN --Update

      UPDATE  Items.t_DeliveryPermission
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_DeliveryPermission.ID );
 
      UPDATE  Items.t_DeliveryPermissionDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_DeliveryPermissionDetail.DeliveryPermissionID );
 
      UPDATE  Items.t_DeliveryPermissionDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_DeliveryPermissionDetailSerial.DeliveryPermissionID );

    END;

    ENABLE TRIGGER Items.tr_DeliveryPermission ON Items.t_DeliveryPermission;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetailSerial ON Items.t_DeliveryPermissionDetailSerial;
	  
    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, DeliveryPermission, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;







