/****** Object:  StoredProcedure [Items].[s_FoodMenusIncreasePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_FoodMenusIncreasePART]
AS
BEGIN

  BEGIN --Declare

    DECLARE @FreeCount INT = 0 ,
      @MaxCount INT;

  END;

  BEGIN --Set
    
    SELECT @FreeCount = COUNT(s.ID)
      FROM Items.t_FoodMenus AS s
      WHERE s.ItemSharedID = Alls.f_GetEmptyGuid();
  
    SELECT @MaxCount = COUNT(s.ID)
      FROM Items.t_FoodMenus AS s;
	
  END;

  IF @FreeCount > 3 --Check
  BEGIN 
    
    RETURN 0;

  END;

  BEGIN --Insert t_FoodMenus

    INSERT Items.t_FoodMenus
        ( ItemNumber )
      VALUES  ( @MaxCount + 1 ),
              ( @MaxCount + 2 ),
              ( @MaxCount + 3 ),
              ( @MaxCount + 4 ),
              ( @MaxCount + 5 ),
              ( @MaxCount + 6 ),
              ( @MaxCount + 7 ),
              ( @MaxCount + 8 ),
              ( @MaxCount + 9 ),
              ( @MaxCount + 10 );

  END;


END;



