/****** Object:  StoredProcedure [Items].[s_ItemAppendQtysPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemAppendQtysPART] @ItemQtys Items.ItemAppendQtys READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @NetQtys AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        Qty DECIMAL(18, 6) NOT NULL
      );

    DECLARE @IDs Alls.tt_Guid ,
      @Return INT = 0;

  END;

  BEGIN --Append Item

    INSERT INTO @NetQtys
        ( ID ,
          Qty
        )
      SELECT s.ID ,
          COALESCE(SUM(s.Qty), 0)
        FROM @ItemQtys AS s
        GROUP BY s.ID;

    MERGE Items.t_Item AS t
    USING @NetQtys AS s
    ON s.ID = t.ID AND t.TypeIs = 0
    WHEN MATCHED THEN
      UPDATE SET t.QtyCurrent += s.Qty;

    INSERT @IDs
        ( ID )
      SELECT s.ID
        FROM @NetQtys AS s;

    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotal @IDs;
    
  END;

  BEGIN --Append ItemShared

    DELETE FROM @NetQtys;

    INSERT INTO @NetQtys
        ( ID ,
          Qty
        )
      SELECT s.SharedID ,
          COALESCE(SUM(s.Qty), 0)
        FROM @ItemQtys AS s
        GROUP BY s.SharedID;

    MERGE Items.t_ItemShared AS t
    USING @NetQtys AS s
    ON s.ID = t.ID AND t.TypeIs = 0
    WHEN MATCHED THEN
      UPDATE SET t.QtyCurrent += s.Qty ,
                  t.PurchaseTotal = t.Purchase * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalF = Currencys.f_Format(t.CurrencyID, t.Purchase * ( t.QtyCurrent + s.Qty )) ,
                  t.PurchaseTotalD = t.PurchaseD * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalLL = t.PurchaseLL * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalEuro = t.PurchaseEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalWithTax = t.PurchaseWithTax * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalWithTaxF = Currencys.f_Format(t.CurrencyID, t.PurchaseWithTax * ( t.QtyCurrent + s.Qty )) ,
                  t.PurchaseTotalWithTaxD = t.PurchaseWithTaxD * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalWithTaxLL = t.PurchaseWithTaxLL * ( t.QtyCurrent + s.Qty ) ,
                  t.PurchaseTotalWithTaxEuro = t.PurchaseWithTaxEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePrice = t.WholesalePrice * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, t.WholesalePrice * ( t.QtyCurrent + s.Qty )) ,
                  t.TotalWholesalePriceD = t.WholesalePriceD * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceLL = t.WholesalePriceLL * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceEuro = t.WholesalePriceEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceWithTax = t.WholesalePriceWithTax * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceWithTaxF = Currencys.f_Format(t.SellCurrencyID, t.WholesalePriceWithTax * ( t.QtyCurrent + s.Qty )) ,
                  t.TotalWholesalePriceWithTaxD = t.WholesalePriceWithTaxD * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceWithTaxLL = t.WholesalePriceWithTaxLL * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalWholesalePriceWithTaxEuro = t.WholesalePriceWithTaxEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPrice = t.DistributionPrice * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, t.DistributionPrice * ( t.QtyCurrent + s.Qty )) ,
                  t.TotalDistributionPriceD = t.DistributionPriceD * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceLL = t.DistributionPriceLL * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceEuro = t.DistributionPriceEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceWithTax = t.DistributionPriceWithTax * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceWithTaxF = Currencys.f_Format(t.SellCurrencyID, t.DistributionPriceWithTax * ( t.QtyCurrent + s.Qty )) ,
                  t.TotalDistributionPriceWithTaxD = t.DistributionPriceWithTaxD * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceWithTaxLL = t.DistributionPriceWithTaxLL * ( t.QtyCurrent + s.Qty ) ,
                  t.TotalDistributionPriceWithTaxEuro = t.DistributionPriceWithTaxEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotal = t.Sell * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalF = Currencys.f_Format(SellCurrencyID, t.Sell * ( t.QtyCurrent + s.Qty )) ,
                  t.SellTotalD = t.SellD * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalLL = t.SellLL * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalEuro = t.SellEuro * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalWithTax = t.SellWithTax * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalWithTaxF = Currencys.f_Format(t.SellCurrencyID, t.SellWithTax * ( t.QtyCurrent + s.Qty )) ,
                  t.SellTotalWithTaxD = t.SellWithTaxD * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalWithTaxLL = t.SellWithTaxLL * ( t.QtyCurrent + s.Qty ) ,
                  t.SellTotalWithTaxEuro = t.SellWithTaxEuro * ( t.QtyCurrent + s.Qty );

  END;

END;





