CREATE PROCEDURE [Items].[s_ItemAppendQtysPART3] @Qtys Items.ItemAppendQtys READONLY
AS
BEGIN

  BEGIN --Declare

    DECLARE @ItemQtys Items.tt_ItemQtys ,
      @ItemSharedQtys Items.tt_ItemSharedQtys;

  END;

  BEGIN --Set

    INSERT INTO @ItemQtys
        ( ID ,
          Qtys
        )
      SELECT s.ID ,
          COALESCE(SUM(s.Qty), 0)
        FROM @Qtys AS s
        GROUP BY s.ID;
   
    INSERT INTO @ItemSharedQtys
        ( ID ,
          Qtys
        )
      SELECT s.SharedID ,
          COALESCE(SUM(s.Qty), 0)
        FROM @Qtys AS s
        GROUP BY s.SharedID;

  END;

  BEGIN --t_Item
	
    WITH  o AS ( SELECT s1.ID ,
                    s1.SharedID ,
                    s1.QtyCurrent ,
                    s1.QtyCurrent + s.Qtys AS QtyCurrent_ ,
                    s1.PurchaseTotal ,
                    s1.PurchaseTotalF ,
                    s1.PurchaseTotalD ,
                    s1.PurchaseTotalLL ,
                    s1.PurchaseTotalEuro ,
                    s1.PurchaseTotalWithTax ,
                    s1.PurchaseTotalWithTaxF ,
                    s1.PurchaseTotalWithTaxD ,
                    s1.PurchaseTotalWithTaxLL ,
                    s1.PurchaseTotalWithTaxEuro ,
                    s1.SellTotal ,
                    s1.SellTotalF ,
                    s1.SellTotalD ,
                    s1.SellTotalLL ,
                    s1.SellTotalEuro ,
                    s1.SellTotalWithTax ,
                    s1.SellTotalWithTaxF ,
                    s1.SellTotalWithTaxD ,
                    s1.SellTotalWithTaxLL ,
                    s1.SellTotalWithTaxEuro ,
                    s1.StockTakeEvery ,
                    s1.StockTakeEveryType ,
                    s1.StockTakeEveryARF ,
                    s1.StockTakeEveryENF ,
                    s1.StockTakeEveryNotificationDate ,
                    s2.CurrencyID ,
                    s2.Purchase ,
                    s2.PurchaseD ,
                    s2.PurchaseLL ,
                    s2.PurchaseEuro ,
                    s2.PurchaseWithTax ,
                    s2.PurchaseWithTaxD ,
                    s2.PurchaseWithTaxLL ,
                    s2.PurchaseWithTaxEuro ,
                    s2.SellCurrencyID ,
                    s2.Sell ,
                    s2.SellD ,
                    s2.SellLL ,
                    s2.SellEuro ,
                    s2.SellWithTax ,
                    s2.SellWithTaxD ,
                    s2.SellWithTaxLL ,
                    s2.SellWithTaxEuro ,
                    s1.RowVersionID
                  FROM @ItemQtys AS s
                  LEFT JOIN Items.t_Item AS s1 ON s1.ID = s.ID
                  LEFT JOIN Items.t_ItemShared AS s2 ON s2.ID = s1.SharedID
                  WHERE s1.TypeIs = 0
               )
      UPDATE o
        SET o.QtyCurrent = o.QtyCurrent_ ,
            o.PurchaseTotal = o.Purchase * o.QtyCurrent_ ,
            o.PurchaseTotalF = Currencys.f_Format(o.CurrencyID, o.Purchase * o.QtyCurrent_) ,
            o.PurchaseTotalD = o.PurchaseD * o.QtyCurrent_ ,
            o.PurchaseTotalLL = o.PurchaseLL * o.QtyCurrent_ ,
            o.PurchaseTotalEuro = o.PurchaseEuro * o.QtyCurrent_ ,
            o.PurchaseTotalWithTax = o.PurchaseWithTax * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax * o.QtyCurrent_) ,
            o.PurchaseTotalWithTaxD = o.PurchaseWithTaxD * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxLL = o.PurchaseWithTaxLL * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxEuro = o.PurchaseWithTaxEuro * o.QtyCurrent_ ,
            o.SellTotal = o.Sell * o.QtyCurrent_ ,
            o.SellTotalF = Currencys.f_Format(o.SellCurrencyID, o.Sell * o.QtyCurrent_) ,
            o.SellTotalD = o.SellD * o.QtyCurrent_ ,
            o.SellTotalLL = o.SellLL * o.QtyCurrent_ ,
            o.SellTotalEuro = o.SellEuro * o.QtyCurrent_ ,
            o.SellTotalWithTax = o.SellWithTax * o.QtyCurrent_ ,
            o.SellTotalWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.SellWithTax * o.QtyCurrent_) ,
            o.SellTotalWithTaxD = o.SellWithTaxD * o.QtyCurrent_ ,
            o.SellTotalWithTaxLL = o.SellWithTaxLL * o.QtyCurrent_ ,
            o.SellTotalWithTaxEuro = o.SellWithTaxEuro * o.QtyCurrent_ ,
            o.RowVersionID = [DateTimes].[f_GetRowVersionID]();

  END;

  BEGIN --t_ItemShared

    WITH  o AS ( SELECT s1.ID ,
                    s1.QtyCurrent ,
                    s1.QtyCurrent + s.Qtys AS QtyCurrent_ ,
                    s1.QtyCurrentByUnit ,
                    s1.WholesalePrice ,
                    s1.WholesalePriceD ,
                    s1.WholesalePriceLL ,
                    s1.WholesalePriceEuro ,
                    s1.TotalWholesalePrice ,
                    s1.TotalWholesalePriceF ,
                    s1.TotalWholesalePriceD ,
                    s1.TotalWholesalePriceLL ,
                    s1.TotalWholesalePriceEuro ,
                    s1.WholesalePriceWithTax ,
                    s1.WholesalePriceWithTaxD ,
                    s1.WholesalePriceWithTaxLL ,
                    s1.WholesalePriceWithTaxEuro ,
                    s1.TotalWholesalePriceWithTax ,
                    s1.TotalWholesalePriceWithTaxF ,
                    s1.TotalWholesalePriceWithTaxD ,
                    s1.TotalWholesalePriceWithTaxLL ,
                    s1.TotalWholesalePriceWithTaxEuro ,
                    s1.DistributionPrice ,
                    s1.DistributionPriceD ,
                    s1.DistributionPriceLL ,
                    s1.DistributionPriceEuro ,
                    s1.TotalDistributionPrice ,
                    s1.TotalDistributionPriceF ,
                    s1.TotalDistributionPriceD ,
                    s1.TotalDistributionPriceLL ,
                    s1.TotalDistributionPriceEuro ,
                    s1.DistributionPriceWithTax ,
                    s1.DistributionPriceWithTaxD ,
                    s1.DistributionPriceWithTaxLL ,
                    s1.DistributionPriceWithTaxEuro ,
                    s1.TotalDistributionPriceWithTax ,
                    s1.TotalDistributionPriceWithTaxF ,
                    s1.TotalDistributionPriceWithTaxD ,
                    s1.TotalDistributionPriceWithTaxLL ,
                    s1.TotalDistributionPriceWithTaxEuro ,
                    s1.CurrencyID ,
                    s1.Purchase ,
                    s1.PurchaseD ,
                    s1.PurchaseLL ,
                    s1.PurchaseEuro ,
                    s1.PurchaseTotal ,
                    s1.PurchaseTotalF ,
                    s1.PurchaseTotalD ,
                    s1.PurchaseTotalLL ,
                    s1.PurchaseTotalEuro ,
                    s1.PurchaseWithTax ,
                    s1.PurchaseWithTaxD ,
                    s1.PurchaseWithTaxLL ,
                    s1.PurchaseWithTaxEuro ,
                    s1.PurchaseTotalWithTax ,
                    s1.PurchaseTotalWithTaxF ,
                    s1.PurchaseTotalWithTaxD ,
                    s1.PurchaseTotalWithTaxLL ,
                    s1.PurchaseTotalWithTaxEuro ,
                    s1.SellCurrencyID ,
                    s1.Sell ,
                    s1.SellD ,
                    s1.SellLL ,
                    s1.SellEuro ,
                    s1.SellTotal ,
                    s1.SellTotalF ,
                    s1.SellTotalD ,
                    s1.SellTotalLL ,
                    s1.SellTotalEuro ,
                    s1.SellWithTax ,
                    s1.SellWithTaxD ,
                    s1.SellWithTaxLL ,
                    s1.SellWithTaxEuro ,
                    s1.SellTotalWithTax ,
                    s1.SellTotalWithTaxF ,
                    s1.SellTotalWithTaxD ,
                    s1.SellTotalWithTaxLL ,
                    s1.SellTotalWithTaxEuro ,
                    s1.RowVersionID
                  FROM @ItemSharedQtys AS s
                  LEFT JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ID
                  WHERE s1.TypeIs = 0
               )
      UPDATE o
        SET o.QtyCurrent = o.QtyCurrent_ ,
            o.QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(o.ID, o.QtyCurrent_) ,
            o.PurchaseTotal = o.Purchase * o.QtyCurrent_ ,
            o.PurchaseTotalF = Currencys.f_Format(o.CurrencyID, o.Purchase * o.QtyCurrent_) ,
            o.PurchaseTotalD = o.PurchaseD * o.QtyCurrent_ ,
            o.PurchaseTotalLL = o.PurchaseLL * o.QtyCurrent_ ,
            o.PurchaseTotalEuro = o.PurchaseEuro * o.QtyCurrent_ ,
            o.PurchaseTotalWithTax = o.PurchaseWithTax * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax * o.QtyCurrent_) ,
            o.PurchaseTotalWithTaxD = o.PurchaseWithTaxD * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxLL = o.PurchaseWithTaxLL * o.QtyCurrent_ ,
            o.PurchaseTotalWithTaxEuro = o.PurchaseWithTaxEuro * o.QtyCurrent_ ,
            o.TotalWholesalePrice = o.WholesalePrice * o.QtyCurrent_ ,
            o.TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, o.WholesalePrice * o.QtyCurrent_) ,
            o.TotalWholesalePriceD = o.WholesalePriceD * o.QtyCurrent_ ,
            o.TotalWholesalePriceLL = o.WholesalePriceLL * o.QtyCurrent_ ,
            o.TotalWholesalePriceEuro = o.WholesalePriceEuro * o.QtyCurrent_ ,
            o.TotalWholesalePriceWithTax = o.WholesalePriceWithTax * o.QtyCurrent_ ,
            o.TotalWholesalePriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.WholesalePriceWithTax * o.QtyCurrent_) ,
            o.TotalWholesalePriceWithTaxD = o.WholesalePriceWithTaxD * o.QtyCurrent_ ,
            o.TotalWholesalePriceWithTaxLL = o.WholesalePriceWithTaxLL * o.QtyCurrent_ ,
            o.TotalWholesalePriceWithTaxEuro = o.WholesalePriceWithTaxEuro * o.QtyCurrent_ ,
            o.TotalDistributionPrice = o.DistributionPrice * o.QtyCurrent_ ,
            o.TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, o.DistributionPrice * o.QtyCurrent_) ,
            o.TotalDistributionPriceD = o.DistributionPriceD * o.QtyCurrent_ ,
            o.TotalDistributionPriceLL = o.DistributionPriceLL * o.QtyCurrent_ ,
            o.TotalDistributionPriceEuro = o.DistributionPriceEuro * o.QtyCurrent_ ,
            o.TotalDistributionPriceWithTax = o.DistributionPriceWithTax * o.QtyCurrent_ ,
            o.TotalDistributionPriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.DistributionPriceWithTax * o.QtyCurrent_) ,
            o.TotalDistributionPriceWithTaxD = o.DistributionPriceWithTaxD * o.QtyCurrent_ ,
            o.TotalDistributionPriceWithTaxLL = o.DistributionPriceWithTaxLL * o.QtyCurrent_ ,
            o.TotalDistributionPriceWithTaxEuro = o.DistributionPriceWithTaxEuro * o.QtyCurrent_ ,
            o.SellTotal = o.Sell * o.QtyCurrent_ ,
            o.SellTotalF = Currencys.f_Format(SellCurrencyID, o.Sell * o.QtyCurrent_) ,
            o.SellTotalD = o.SellD * o.QtyCurrent_ ,
            o.SellTotalLL = o.SellLL * o.QtyCurrent_ ,
            o.SellTotalEuro = o.SellEuro * o.QtyCurrent_ ,
