/****** Object:  StoredProcedure [Items].[s_ItemEditSalePriceByInvoicePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemEditSalePriceByInvoicePART] @ItemSharedEditSalePrice Items.tt_ItemSharedEditSalePrice READONLY ,
  @UnityItemEditSalePrice Items.tt_UnityItemEditSalePrice READONLY
AS
BEGIN
   
  BEGIN --Declare

    DECLARE @ItemSharedEditSalePriceIDs Alls.tt_Guid;

  END;

  BEGIN --Set
	      
    INSERT @ItemSharedEditSalePriceIDs
        ( ID
        )
      SELECT s.ID
        FROM @ItemSharedEditSalePrice AS s;

  END;

  BEGIN --Update t_ItemShared

    MERGE Items.t_ItemShared AS t
    USING @ItemSharedEditSalePrice AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.Sell = s.Sell ,
                  t.SellF = s.SellF ,
                  t.SellD = s.SellD ,
                  t.SellLL = s.SellLL ,
                  t.SellEuro = s.SellEuro ,
                  t.SellTotal = s.Sell * t.QtyCurrent ,
                  t.SellTotalF = Currencys.f_Format(t.SellCurrencyID, s.Sell * t.QtyCurrent) ,
                  t.SellTotalD = s.SellD * t.QtyCurrent ,
                  t.SellTotalLL = s.SellLL * t.QtyCurrent ,
                  t.SellTotalEuro = s.SellEuro * t.QtyCurrent ,
                  t.SellWithTax = s.SellWithTax ,
                  t.SellWithTaxF = s.SellWithTaxF ,
                  t.SellWithTaxD = s.SellWithTaxD ,
                  t.SellWithTaxLL = s.SellWithTaxLL ,
                  t.SellWithTaxEuro = s.SellWithTaxEuro ,
                  t.SellTotalWithTax = s.SellWithTax * t.QtyCurrent ,
                  t.SellTotalWithTaxF = Currencys.f_Format(t.SellCurrencyID, s.SellWithTax * t.QtyCurrent) ,
                  t.SellTotalWithTaxD = s.SellWithTaxD * t.QtyCurrent ,
                  t.SellTotalWithTaxLL = s.SellWithTaxLL * t.QtyCurrent ,
                  t.SellTotalWithTaxEuro = s.SellWithTaxEuro * t.QtyCurrent ,
                  t.ProfitRatio = Calculation.GetRate(s.SellLL - t.PurchaseLL, t.PurchaseLL) ,
                  t.TaxRate = s.TaxRate ,
                  t.FinalPrice = Calculation.Discount(s.Sell, Discount) ,
                  t.FinalPriceF = Currencys.f_Format(t.SellCurrencyID, Calculation.Discount(s.Sell, t.Discount)) ,
                  t.FinalPriceD = Calculation.Discount(s.SellD, t.Discount) ,
                  t.FinalPriceLL = Calculation.Discount(s.SellLL, t.Discount) ,
                  t.FinalPriceEuro = Calculation.Discount(s.SellEuro, t.Discount);

  END;
    
  BEGIN --Update t_UnityItem

    MERGE Items.t_UnityItem AS t
    USING @UnityItemEditSalePrice AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.Price = s.Price ,
                  t.PriceF = s.PriceF ,
                  t.PriceD = s.PriceD ,
                  t.PriceLL = s.PriceLL ,
                  t.PriceEuro = s.PriceEuro ,
                  t.PriceWithTax = s.PriceWithTax ,
                  t.PriceWithTaxF = s.PriceWithTaxF ,
                  t.PriceWithTaxD = s.PriceWithTaxD ,
                  t.PriceWithTaxLL = s.PriceWithTaxLL ,
                  t.PriceWithTaxEuro = s.PriceWithTaxEuro ,
                  t.ProfitRatio = Calculation.GetRate(s.PriceLL - t.CostLL, t.CostLL);

  END;
  
  EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @ItemSharedEditSalePriceIDs;
 
END;




GO
/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateCleanPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemExpirationDateCleanPART]
AS
BEGIN

  BEGIN --Declare
     
    DECLARE @t_Delete AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(450) NOT NULL
      ); 	

  END;

  BEGIN --Delete Empty Qtys
    
    DELETE FROM Items.t_ItemExpirationDate
      OUTPUT Deleted.ID ,
        Deleted.ItemSharedID ,
        Deleted.Barcode
        INTO @t_Delete
      WHERE Qtys < 1;

    DELETE FROM @t_Delete
      WHERE Barcode = N'';

  END;

  BEGIN --Delete t_ItemSharedBarCode

    DELETE FROM Items.t_ItemSharedBarCode
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @t_Delete AS s
                      WHERE s.ItemSharedID = t_ItemSharedBarCode.SharedID AND t_ItemSharedBarCode.TypeIs = 3 AND s.Barcode = t_ItemSharedBarCode.BarCode );
	
    BEGIN --Update Barcodes t_ItemShared

      DECLARE @IDs Alls.tt_Guid;
      INSERT INTO @IDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedID
          FROM @t_Delete AS s;

      EXECUTE Items.s_ItemShared_UpdatesLive_Barcodes_PART @IDs;

    END;

  END;
  	
END;



