/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemExpirationDateDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemSharedID UNIQUEIDENTIFIER ,
        @Barcode NVARCHAR(450) ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ItemSharedID = s.ItemSharedID ,
          @Barcode = s.Barcode
        FROM Items.t_ItemExpirationDate AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      SET @Return = 0;

      DELETE FROM Items.t_ItemExpirationDate
        WHERE ID = @ID;

    END;

    IF @Barcode <> N''
    BEGIN --Delete barcodes

      SET @Return = -3;

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ItemSharedID AND TypeIs = 3 AND BarCode = @Barcode;
	
      EXECUTE Items.s_ItemShared_UpdateLive_Barcodes_PART @ItemSharedID;
      
      EXECUTE Items.s_ItemSharedUpdateSearchIndexPART @ItemSharedID;
	
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemExpirationDateMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










