/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemExpirationDateInsert]
  @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemID UNIQUEIDENTIFIER ,
  @WareHouseID UNIQUEIDENTIFIER ,
  @PlaceID UNIQUEIDENTIFIER ,
  @Barcode NVARCHAR(450) ,
  @Qtys DECIMAL(18, 6) ,
  @ProductionDate DATE ,
  @ExpirationDate DATE ,
  @NotifyMeDaysBefore INT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Price FLOAT ,
  @BatchNumber NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @PriceD FLOAT ,
        @ExchangeRate FLOAT ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT  @Ref = ISNULL(MAX(s.Ref), 0) + 1
      FROM    Items.t_ItemExpirationDate AS s;

      SET @ExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyID);

      SET @PriceD = @Price / @ExchangeRate;

    END;

    BEGIN --Insert

      SET @Return = 0;

      INSERT  INTO Items.t_ItemExpirationDate
              ( ID ,
                Ref ,
                RefF ,
                ItemSharedID ,
                ItemID ,
                WareHouseID ,
                WareHouse ,
                PlaceID ,
                Place ,
                SectionIs ,
                SectionID ,
                Barcode ,
                Qtys ,
                ProductionDate ,
                ExpirationDate ,
                NotifyMeDaysBefore ,
                NotificationDate ,
                CurrencyID ,
                Currency ,
                Price ,
                PriceF ,
                PriceD ,
                PriceLL ,
                PriceEuro ,
                BatchNumber ,
                DescriptionIs
              )
      VALUES  ( @ID ,
                @Ref ,
                FORMAT(@Ref, '#') ,
                @ItemSharedID ,
                @ItemID ,
                @WareHouseID ,
                Company.f_WareHouseGetName(@WareHouseID) ,
                @PlaceID ,
                Company.f_PlaceGetName(@PlaceID) ,
                10 ,
                @ItemSharedID ,
                @Barcode ,
                @Qtys ,
                @ProductionDate ,
                @ExpirationDate ,
                @NotifyMeDaysBefore ,
                DATEADD(DAY, 0 - @NotifyMeDaysBefore, @ExpirationDate) ,
                @CurrencyID ,
                Currencys.f_CurrencyGetName(@CurrencyID) ,
                @Price ,
                Currencys.f_Format(@CurrencyID, @Price) ,
                @PriceD ,
                Currencys.f_ExchangeToLL(@CurrencyID, @Price, @PriceD) ,
                Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @PriceD) ,
                @BatchNumber ,
                @DescriptionIs
              );

    END;

    IF @Barcode <> N''
    BEGIN --Insert barcodes

      SET @Return = -3;

      INSERT  INTO Items.t_ItemSharedBarCode
              ( SharedID ,
                BarCode ,
                BarcodeNumber ,
                TypeIs
              )
      VALUES  ( @ItemSharedID ,
                @Barcode ,
                Alls.f_ToBigint(@Barcode) ,
                3
              );
		
      EXECUTE Items.s_ItemShared_UpdateLive_Barcodes_PART @ItemSharedID;

      EXECUTE Items.s_ItemSharedUpdateSearchIndexPART @ItemSharedID;
		
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Items.t_ItemExpirationDateMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemExpirationDateInsertPART] @SectionIs INT ,
  @SectionID UNIQUEIDENTIFIER ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  BEGIN --Declare

    DECLARE @ItemExpirationDate_ [Items].[tt_ItemExpirationDate] ,
      @ItemExpirationDateRef BIGINT;

  END;

  BEGIN --Set info

    SELECT @ItemExpirationDateRef = ISNULL(MAX(s.Ref), 0)
      FROM Items.t_ItemExpirationDate AS s;

    INSERT INTO @ItemExpirationDate_
        ( ID ,
          Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          WareHouse ,
          PlaceID ,
          Place ,
          SectionIs ,
          SectionID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Currency ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs ,
          DateCreate ,
          IsSync ,
          WorkStationID ,
          OriginalID ,
          FatherID1 ,
          FatherID2 ,
          EventIs
        )
      SELECT MIN(s.ID) AS ID ,
          0 ,
          N'' ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          N'' ,
          Alls.f_GetEmptyGuid() ,
          N'' ,
          0 ,
          Alls.f_GetEmptyGuid() ,
          N'' ,
          SUM(s.Qtys) AS Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          GETDATE() ,
          s.CurrencyID ,
          N'' ,
          s.Price ,
          N'' ,
          0 ,
          0 ,
          0 ,
          s.BatchNumber ,
          s.DescriptionIs ,
          GETDATE() ,
          0 ,
          1 ,
          Alls.f_GetEmptyGuid() ,
          Alls.f_GetEmptyGuid() ,
          Alls.f_GetEmptyGuid() ,
          N''
        FROM @ItemExpirationDate AS s
        GROUP BY s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          s.CurrencyID ,
          s.Price ,
          s.BatchNumber ,
          s.DescriptionIs;

  END;

  BEGIN --Insert

    INSERT INTO Items.t_ItemExpirationDate
        ( ID ,
          Ref ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          WareHouse ,
          PlaceID ,
          Place ,
          SectionIs ,
          SectionID ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Currency ,
          Price ,
          PriceF ,
          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs 
        )
      SELECT s.ID ,
          @ItemExpirationDateRef + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                                ) ) ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          Company.f_WareHouseGetName(s.WareHouseID) ,
          Company.f_PlaceGetFirstID1(s.WareHouseID) ,
          Company.f_PlaceGetFirstName1(s.WareHouseID) ,
          @SectionIs ,
          @SectionID ,
          s.Qtys ,
          s.ProductionDate ,
          s.ExpirationDate ,
          s.NotifyMeDaysBefore ,
          DATEADD(DAY, 0 - s.NotifyMeDaysBefore, s.ExpirationDate) ,
          s.CurrencyID ,
          Currencys.f_CurrencyGetName(s.CurrencyID) ,
          s.Price ,
          Currencys.f_Format(s.CurrencyID, s.Price) ,
          s.Price / s1.ExchangeRate ,
          Currencys.f_ExchangeToLL(s.CurrencyID, s.Price, s.Price / s1.ExchangeRate) ,
          Currencys.f_ExchangeToEuro(s.CurrencyID, s.Price, s.Price / s1.ExchangeRate) ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate_ AS s
        LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID;

  END;

  BEGIN --Fix Ref

    UPDATE Items.t_ItemExpirationDate
      SET RefF = FORMAT(Ref, '#')
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @ItemExpirationDate_ AS s
                      WHERE s.ID = t_ItemExpirationDate.ID );

  END;

  BEGIN --Insert t_ItemExpirationDateMoving

    INSERT INTO Items.t_ItemExpirationDateMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      SELECT @UserID ,
          s.ID ,
          @Event + N': ' + s1.RefF ,
          @EventType ,
          @ComputerIP ,
          @Computer ,
          @ComputerAccount
        FROM @ItemExpirationDate_ AS s
        LEFT JOIN Items.t_ItemExpirationDate AS s1 ON s1.ID = s.ID;

  END;

END;





