/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateInserts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemExpirationDateInserts] @ItemExpirationDate Items.tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemExpirationDate_ Items.tt_ItemExpirationDate ,
        @Ref BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0)
        FROM Items.t_ItemExpirationDate AS s;

      INSERT INTO @ItemExpirationDate_
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs ,
            DateCreate ,
            IsSync ,
            WorkStationID ,
            OriginalID ,
            FatherID1 ,
            FatherID2 ,
            EventIs
          )
        SELECT t.ID ,
            @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 0
                                                ) ) ,
            t.RefF ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WareHouseID ,
            t.WareHouse ,
            t.PlaceID ,
            t.Place ,
            t.SectionIs ,
            t.SectionID ,
            t.Barcode ,
            t.Qtys ,
            t.ProductionDate ,
            t.ExpirationDate ,
            t.NotifyMeDaysBefore ,
            t.NotificationDate ,
            t.CurrencyID ,
            t.Currency ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.BatchNumber ,
            t.DescriptionIs ,
            t.DateCreate ,
            t.IsSync ,
            t.WorkStationID ,
            t.OriginalID ,
            t.FatherID1 ,
            t.FatherID2 ,
            t.EventIs
          FROM @ItemExpirationDate AS t;

      UPDATE @ItemExpirationDate_
        SET RefF = FORMAT(Ref, '#');

    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemExpirationDate
          ( ID ,
            Ref ,
            RefF ,
            ItemSharedID ,
            ItemID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
            SectionIs ,
            SectionID ,
            Barcode ,
            Qtys ,
            ProductionDate ,
            ExpirationDate ,
            NotifyMeDaysBefore ,
            NotificationDate ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            BatchNumber ,
            DescriptionIs
          )
        SELECT t.ID ,
            t.Ref ,
            t.RefF ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WareHouseID ,
            t.WareHouse ,
            t.PlaceID ,
            t.Place ,
            t.SectionIs ,
            t.SectionID ,
            t.Barcode ,
            t.Qtys ,
            t.ProductionDate ,
            t.ExpirationDate ,
            t.NotifyMeDaysBefore ,
            t.NotificationDate ,
            t.CurrencyID ,
            t.Currency ,
            t.Price ,
            t.PriceF ,
            t.PriceD ,
            t.PriceLL ,
            t.PriceEuro ,
            t.BatchNumber ,
            t.DescriptionIs
          FROM @ItemExpirationDate_ AS t;

    END;

    BEGIN --Insert barcodes

      SET @Return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        SELECT t.ItemSharedID ,
            t.Barcode ,
            Alls.f_ToBigint(t.Barcode) ,
            3
          FROM @ItemExpirationDate_ AS t
          WHERE t.Barcode <> N'';
	
    END;

    BEGIN --Update Barcodes t_ItemShared

      DECLARE @BarcodesIDs Alls.tt_Guid;
      INSERT INTO @BarcodesIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedID
          FROM @ItemExpirationDate_ AS s;

      EXECUTE Items.s_ItemShared_UpdatesLive_Barcodes_PART @BarcodesIDs;

    END;	

    BEGIN --UpdateSearchIndex
   
      DECLARE @ID UNIQUEIDENTIFIER;
      DECLARE @IDs AS TABLE ( ID UNIQUEIDENTIFIER );

      INSERT INTO @IDs
          ( ID
          )
        SELECT s.ItemSharedID
          FROM @ItemExpirationDate_ AS s
          WHERE s.Barcode <> N'';

      DECLARE i CURSOR FAST_FORWARD READ_ONLY
      FOR
      SELECT ID
        FROM @IDs;

      OPEN i;
      FETCH NEXT FROM i INTO @ID;

      WHILE @@FETCH_STATUS = 0
      BEGIN
    
        EXECUTE Items.s_ItemSharedUpdateSearchIndexPART @ID;

        FETCH NEXT FROM i INTO @ID;

      END;

      CLOSE i;
      DEALLOCATE i;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemExpirationDateMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            REPLACE(s.EventIs, N'{0}', s.RefF) ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @ItemExpirationDate_ AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;







GO
