/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateReduceQtysPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemExpirationDateReduceQtysPART] @tt Items.tt_ItemExpirationDate READONLY
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @tt AS s )
  BEGIN

    RETURN 1;
	 
  END;

  BEGIN --DECLARE
	  
    DECLARE @ItemExpirationDateSum AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        Qtys FLOAT NOT NULL
      );

    DECLARE @ItemExpirationDateDelete AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(450) NOT NULL
      ); 
	    
  END;

  BEGIN --Set Info
	  
    INSERT INTO @ItemExpirationDateSum
        ( ID ,
          Qtys
        )
      SELECT s.ID ,
          COALESCE(SUM(s.Qtys), 0)
        FROM @tt AS s
        GROUP BY s.ID;

  END;

  BEGIN --Update
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @ItemExpirationDateSum AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.Qtys -= s.Qtys;

  END;

  BEGIN --Delete Empty Qtys
    
    DELETE FROM Items.t_ItemExpirationDate
      OUTPUT Deleted.ID ,
        Deleted.ItemSharedID ,
        Deleted.Barcode
        INTO @ItemExpirationDateDelete
      WHERE Qtys < 1;

    DELETE FROM @ItemExpirationDateDelete
      WHERE Barcode = N'';

  END;

  BEGIN --Delete t_ItemSharedBarCode

    DELETE FROM Items.t_ItemSharedBarCode
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @ItemExpirationDateDelete AS s
                      WHERE s.ItemSharedID = t_ItemSharedBarCode.SharedID AND t_ItemSharedBarCode.TypeIs = 3 AND s.Barcode = t_ItemSharedBarCode.BarCode );

    BEGIN --Update Barcodes t_ItemShared

      DECLARE @BarcodesIDs Alls.tt_Guid;
      INSERT INTO @BarcodesIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedID
          FROM @ItemExpirationDateDelete AS s;

      EXECUTE Items.s_ItemShared_UpdatesLive_Barcodes_PART @BarcodesIDs;

    END;	

  END;

END;





GO
/****** Object:  StoredProcedure [Items].[s_ItemExpirationDateUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemExpirationDateUpdate] @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemID UNIQUEIDENTIFIER ,
  @WareHouseID UNIQUEIDENTIFIER ,
  @PlaceID UNIQUEIDENTIFIER ,
  @Barcode NVARCHAR(450) ,
  @Qtys DECIMAL(18, 6) ,
  @ProductionDate DATE ,
  @ExpirationDate DATE ,
  @NotifyMeDaysBefore INT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Price FLOAT ,
  @BatchNumber NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType INT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
		
      DECLARE @PriceD FLOAT ,
        @ExchangeRate FLOAT ,
        @ItemSharedIDOld UNIQUEIDENTIFIER ,
        @BarcodeOld NVARCHAR(450) ,
        @Return INT;

    END;

    BEGIN --Set info

      SET @ExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyID);

      SET @PriceD = @Price / @ExchangeRate;

      SELECT TOP ( 1 ) @ItemSharedIDOld = s.ItemSharedID ,
          @BarcodeOld = s.Barcode
        FROM Items.t_ItemExpirationDate AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Items.t_ItemExpirationDate
        SET ItemSharedID = @ItemSharedID ,
            ItemID = @ItemID ,
            WareHouseID = @WareHouseID ,
            WareHouse = Company.f_WareHouseGetName(@WareHouseID) ,
            PlaceID = @PlaceID ,
            Place = Company.f_PlaceGetName(@PlaceID) ,
            Barcode = @Barcode ,
            Qtys = @Qtys ,
            ProductionDate = @ProductionDate ,
            ExpirationDate = @ExpirationDate ,
            NotifyMeDaysBefore = @NotifyMeDaysBefore ,
            NotificationDate = DATEADD(DAY, 0 - @NotifyMeDaysBefore, @ExpirationDate) ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            Price = @Price ,
            PriceF = Currencys.f_Format(@CurrencyID, @Price) ,
            PriceD = @PriceD ,
            PriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @Price, @PriceD) ,
            PriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @PriceD) ,
            BatchNumber = @BatchNumber ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;
		
    BEGIN --Delete old barcode

      SET @Return = -3;

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ItemSharedID AND TypeIs = 3 AND BarCode = @BarcodeOld;

    END;

    IF @Barcode <> N''
    BEGIN --Insert barcodes

      SET @Return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        VALUES
          ( @ItemSharedID ,
            @Barcode ,
            Alls.f_ToBigint(@Barcode) ,
            3
          );
	
    END;

    BEGIN --Fix t_ItemShared

      EXECUTE Items.s_ItemShared_UpdateLive_Barcodes_PART @ItemSharedID;

      EXECUTE Items.s_ItemSharedUpdateSearchIndexPART @ItemSharedID;
		
      IF @ItemSharedIDOld <> @ItemSharedID
      BEGIN

        EXECUTE Items.s_ItemShared_UpdateLive_Barcodes_PART @ItemSharedIDOld;

        EXECUTE Items.s_ItemSharedUpdateSearchIndexPART @ItemSharedIDOld;
		
      END;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemExpirationDateMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
