/****** Object:  StoredProcedure [Items].[s_ItemFixAllPurchaseAndSaleTotal]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemFixAllPurchaseAndSaleTotal]
AS
BEGIN

  WITH  o AS ( SELECT s.ID ,
                  s.SharedID ,
                  s.QtyCurrent ,
                  s.PurchaseTotal ,
                  s.PurchaseTotalF ,
                  s.PurchaseTotalD ,
                  s.PurchaseTotalLL ,
                  s.PurchaseTotalEuro ,
                  s.PurchaseTotalWithTax ,
                  s.PurchaseTotalWithTaxF ,
                  s.PurchaseTotalWithTaxD ,
                  s.PurchaseTotalWithTaxLL ,
                  s.PurchaseTotalWithTaxEuro ,
                  s.SellTotal ,
                  s.SellTotalF ,
                  s.SellTotalD ,
                  s.SellTotalLL ,
                  s.SellTotalEuro ,
                  s.SellTotalWithTax ,
                  s.SellTotalWithTaxF ,
                  s.SellTotalWithTaxD ,
                  s.SellTotalWithTaxLL ,
                  s.SellTotalWithTaxEuro ,
                  s.StockTakeEvery ,
                  s.StockTakeEveryType ,
                  s.StockTakeEveryARF ,
                  s.StockTakeEveryENF ,
                  s.StockTakeEveryNotificationDate ,
                  s1.CurrencyID ,
                  s1.Purchase ,
                  s1.PurchaseD ,
                  s1.PurchaseLL ,
                  s1.PurchaseEuro ,
                  s1.PurchaseWithTax ,
                  s1.PurchaseWithTaxD ,
                  s1.PurchaseWithTaxLL ,
                  s1.PurchaseWithTaxEuro ,
                  s1.SellCurrencyID ,
                  s1.Sell ,
                  s1.SellD ,
                  s1.SellLL ,
                  s1.SellEuro ,
                  s1.SellWithTax ,
                  s1.SellWithTaxD ,
                  s1.SellWithTaxLL ,
                  s1.SellWithTaxEuro
                FROM Items.t_Item AS s
                INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
             )
    UPDATE o
      SET o.PurchaseTotal = o.Purchase * o.QtyCurrent ,
          o.PurchaseTotalF = Currencys.f_Format(o.CurrencyID, o.Purchase * o.QtyCurrent) ,
          o.PurchaseTotalD = o.PurchaseD * o.QtyCurrent ,
          o.PurchaseTotalLL = o.PurchaseLL * o.QtyCurrent ,
          o.PurchaseTotalEuro = o.PurchaseEuro * o.QtyCurrent ,
          o.PurchaseTotalWithTax = o.PurchaseWithTax * o.QtyCurrent ,
          o.PurchaseTotalWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax * o.QtyCurrent) ,
