          o.PurchaseTotalWithTaxEuro = o.PurchaseWithTaxEuro * o.QtyCurrent ,
          o.SellTotal = o.Sell * o.QtyCurrent ,
          o.SellTotalF = Currencys.f_Format(o.SellCurrencyID, o.Sell * o.QtyCurrent) ,
          o.SellTotalD = o.SellD * o.QtyCurrent ,
          o.SellTotalLL = o.SellLL * o.QtyCurrent ,
          o.SellTotalEuro = o.SellEuro * o.QtyCurrent ,
