/****** Object:  StoredProcedure [Items].[s_ItemProductionDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemProductionDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @ItemID UNIQUEIDENTIFIER ,
        @ItemSharedID UNIQUEIDENTIFIER ,
        @Qtys FLOAT ,
        @Return INT = 0;

      DECLARE @ItemSerial AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @ItemSerialMaterial AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );
    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ItemID = s.ItemID ,
          @ItemSharedID = s.ItemSharedID ,
          @Qtys = s.Qtys
        FROM Items.t_ItemProduction AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemSerial
          ( ID
          )
        SELECT s.SerialID
          FROM Items.t_ItemProductionSerial AS s
          WHERE s.ItemProductionID = @ID;
    
      INSERT INTO @ItemSerialMaterial
          ( ID
          )
        SELECT s.SerialID
          FROM Items.t_ItemProductionMaterialSerial AS s
          WHERE s.ItemProductionID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Items.t_ItemProductionSerial
        WHERE ItemProductionID = @ID;
   
      DELETE FROM Items.t_ItemProductionMaterialSerial
        WHERE ItemProductionID = @ID;

      DELETE FROM Items.t_ItemSerial
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemSerial AS s
                        WHERE s.ID = t_ItemSerial.ID );
    
      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemSerialMaterial AS s
                        WHERE s.ID = t_ItemSerial.ID );
  
      DELETE FROM Items.t_ItemProductionMaterial
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          Deleted.Qtys
          INTO @ItemQtys
        WHERE ItemProductionID = @ID;

      DELETE FROM Items.t_ItemProduction
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT @ItemID ,
            @ItemSharedID ,
            0 - @Qtys;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;


    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemProductionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Items].[s_ItemProductionInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Items].[s_ItemProductionInsert] @RefPaper NVARCHAR(MAX) ,
  @OriginSection INT ,
  @OriginID UNIQUEIDENTIFIER ,
  @OriginRef BIGINT ,
  @OriginDetailID UNIQUEIDENTIFIER ,
  @DateIs DATETIME ,
  @StartDate DATETIME ,
  @EndDate DATETIME ,
  @MachineName NVARCHAR(MAX) ,
  @StageType TINYINT ,
  @EmployeeID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemID UNIQUEIDENTIFIER ,
  @ItemUnityID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 6) ,
  @Qtys DECIMAL(18, 6) ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TotalCost FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @AdditionalProperty1 NVARCHAR(MAX) ,
  @AdditionalProperty2 NVARCHAR(MAX) ,
  @AdditionalProperty3 NVARCHAR(MAX) ,
  @AdditionalProperty4 NVARCHAR(MAX) ,
  @AdditionalProperty5 NVARCHAR(MAX) ,
  @SerialIs Items.tt_ItemSerial READONLY ,
  @Material Items.tt_ItemProductionMaterial READONLY ,
  @MaterialSerial Items.tt_ItemSerial READONLY ,
  @HaveSerial BIT ,
  @UpdateItemMaterials BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER OUTPUT
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @Currency NVARCHAR(MAX) ,
        @ItemsNames NVARCHAR(MAX) ,
        @ItemsCounts INT ,
        @Cost FLOAT ,
        @UnitQty DECIMAL(18, 6) = @Qtys / @Qty ,
        @return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Items.t_ItemProduction AS s;

      SET @Currency = Currencys.f_CurrencyGetName(@CurrencyID);

      SELECT @ItemsCounts = ( SELECT COUNT(*)
                                FROM @Material
                            );

      SELECT @ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                            FROM @Material AS t
                                            LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                         FOR
                                           XML PATH('')
                                         ));

      SET @Cost = ( @TotalCost / @Qty ) / @UnitQty;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemProduction
          ( Ref ,
            RefF ,
            RefPaper ,
            OriginSection ,
            OriginID ,
            OriginRef ,
            OriginDetailID ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            StartDate ,
            EndDate ,
            TotalRunningHours ,
            MachineName ,
            StageType ,
            EmployeeID ,
            Employee ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            WarehouseID ,
            Warehouse ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            ItemsNames ,
            ItemsCounts ,
            DescriptionIs ,
            AdditionalProperty1 ,
            AdditionalProperty2 ,
            AdditionalProperty3 ,
            AdditionalProperty4 ,
            AdditionalProperty5 ,
            CreateByID ,
            CreateBy ,
            HaveSerial
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Ref ,
            FORMAT(@Ref, '#') ,
            @RefPaper ,
            @OriginSection ,
            @OriginID ,
            @OriginRef ,
            @OriginDetailID ,
            @DateIs ,
            @DateIs ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @StartDate ,
            @EndDate ,
            DateTimes.f_DateTimeDiff(@StartDate, @EndDate, N'H', 1, N'', N'') ,
            @MachineName ,
            @StageType ,
            @EmployeeID ,
            Employees.f_EmployeeGetName(@EmployeeID) ,
            @ItemSharedID ,
            @ItemID ,
            @ItemUnityID ,
            @Qty ,
            Items.f_FormatQty(@Qty) + ' ' + Items.f_UnityItemGetName(@ItemUnityID) ,
            @Qtys ,
            @WarehouseID ,
            Company.f_WareHouseGetName(@WarehouseID) ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Cost ,
            Currencys.f_Format(@CurrencyID, @Cost) ,
            @Cost / @ExchangeRate ,
            ( @Cost / @ExchangeRate ) * @ExchangeRateLL ,
            ( @Cost / @ExchangeRate ) * @ExchangeRateEuro ,
            @TotalCost ,
            Currencys.f_Format(@CurrencyID, @TotalCost) ,
            @TotalCost / @ExchangeRate ,
            ( @TotalCost / @ExchangeRate ) * @ExchangeRateLL ,
            ( @TotalCost / @ExchangeRate ) * @ExchangeRateEuro ,
            @ItemsNames ,
            @ItemsCounts ,
            @DescriptionIs ,
            @AdditionalProperty1 ,
            @AdditionalProperty2 ,
            @AdditionalProperty3 ,
            @AdditionalProperty4 ,
            @AdditionalProperty5 ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @HaveSerial
          );

      SET @ID = ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s
                    ORDER BY s.ID
                );

    END;

    BEGIN --Insert t_ItemProductionMaterial

      INSERT INTO Items.t_ItemProductionMaterial
          ( ID ,
            ItemProductionID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            WarehouseID ,
            Warehouse ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qtys ,
            s.WarehouseID ,
            Company.f_WareHouseGetName(s.WarehouseID) ,
            s.Cost ,
            Currencys.f_Format(@CurrencyID, s.Cost) ,
            s.Cost / @ExchangeRate ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Cost / @ExchangeRate ) * @ExchangeRateEuro ,
            s.TotalCost ,
            Currencys.f_Format(@CurrencyID, s.TotalCost) ,
            s.TotalCost / @ExchangeRate ,
            ( s.TotalCost / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.TotalCost / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @Material AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            155 ,
            @ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_ItemProductionSerial

      INSERT INTO Items.t_ItemProductionSerial
          ( ItemProductionID, SerialID )
        SELECT @ID ,
            s.ID
          FROM @SerialIs AS s;

    END;

    BEGIN --Insert t_ItemProductionMaterialSerial

      INSERT INTO Items.t_ItemProductionMaterialSerial
          ( ItemProductionID ,
            ItemProductionMaterialID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @MaterialSerial AS s;

    END;

    BEGIN --Update t_ItemSerial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @MaterialSerial AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
	
    EXECUTE Items.s_ItemProductionUpdateSerialNamesPART @ID, @SerialIs;
	
    EXECUTE Items.s_ItemProductionMaterialUpdateSerialNamesPART @MaterialSerial;

    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT @ItemID ,
            @ItemSharedID ,
            @Qtys
        UNION ALL
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM @Material AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert t_ItemProductionMoving

      SET @return = -1;

      INSERT INTO Items.t_ItemProductionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event + N': ' + CONVERT(NVARCHAR(MAX), @Ref) ,
            0 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @UpdateItemMaterials = 1
    BEGIN --Update Item Materials
    
      BEGIN --Declare

        DECLARE @IDs2 Alls.tt_Guid;

      END;
	
      BEGIN --Set
	    
        INSERT @IDs2
            ( ID )
          VALUES ( @ItemSharedID );

      END;

      BEGIN --Reinsert t_ItemSharedMaterial

        DELETE FROM Items.t_ItemSharedMaterial
          WHERE ItemSharedFatherID = @ItemSharedID;

        INSERT INTO Items.t_ItemSharedMaterial
            ( ItemSharedFatherID ,
              ItemSharedID ,
              ItemUnityID ,
              Qty ,
              QtyWithUnity ,
              Qtys ,
              DescriptionIs ,
              CreateByID ,
              CreateBy
	        )
          SELECT @ItemSharedID ,
              s.ItemSharedID ,
              s.ItemUnityID ,
              ( s.Qty / s2.Qty ) / @UnitQty ,
              Items.f_FormatQty(( s.Qty / s2.Qty ) / @UnitQty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
              ( s.Qtys / s2.Qtys ) / @UnitQty ,
              s.DescriptionIs ,
              @UserID ,
              s1.Name
            FROM Items.t_ItemProductionMaterial AS s
            INNER JOIN Users.t_User AS s1 ON s1.ID = @UserID
            INNER JOIN Items.t_ItemProduction AS s2 ON s2.ID = s.ItemProductionID
            WHERE s.ItemProductionID = @ID;

      END;

      BEGIN --Reinsert t_ItemShared
	
        SET @Cost = Items.f_ItemSharedMaterial_GetCost(@ItemSharedID);

        UPDATE Items.t_ItemShared
          SET CurrencyID = @CurrencyID ,
              Currency = @Currency ,
              Purchase = @Cost ,
              PurchaseF = Currencys.f_Format(CurrencyID, @Cost) ,
              PurchaseD = @Cost / @ExchangeRate ,
              PurchaseLL = ( @Cost / @ExchangeRate ) * @ExchangeRateLL ,
              PurchaseEuro = ( @Cost / @ExchangeRate ) * @ExchangeRateEuro
          WHERE ID = @ItemSharedID;
	 
        UPDATE Items.t_ItemShared
          SET PurchaseWithTax = Calculation.Rate(Purchase, TaxRate) ,
              PurchaseWithTaxF = Currencys.f_Format(CurrencyID, Calculation.Rate(Purchase, TaxRate)) ,
              PurchaseWithTaxD = Calculation.Rate(PurchaseD, TaxRate) ,
              PurchaseWithTaxLL = Calculation.Rate(PurchaseLL, TaxRate) ,
              PurchaseWithTaxEuro = Calculation.Rate(PurchaseEuro, TaxRate) ,
              PurchaseTotal = Purchase * QtyCurrent ,
              PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
              PurchaseTotalD = PurchaseD * QtyCurrent ,
              PurchaseTotalLL = PurchaseLL * QtyCurrent ,
              PurchaseTotalEuro = PurchaseEuro * QtyCurrent
          WHERE ID = @ItemSharedID;
	
        UPDATE Items.t_ItemShared
          SET PurchaseTotalWithTax = PurchaseWithTax * QtyCurrent ,
              PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
              PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
              PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
              PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent
          WHERE ID = @ItemSharedID;

      END;

      EXECUTE Items.s_ItemSharedKeepProfitRatioFixPART @IDs2;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Items].[s_ItemProductionInsertBySold]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemProductionInsertBySold] @ProductionWhenSale TINYINT ,
  @SoldID UNIQUEIDENTIFIER ,
  @SoldRef BIGINT ,
  @DateIs DATETIME ,
  @StageType TINYINT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyTypeIs INT ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DetailIs Invoices.tt_SoldDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventInsert NVARCHAR(MAX) ,
  @EventInsertBySold NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  BEGIN --Check

    IF @ProductionWhenSale = 0
    BEGIN

      RETURN 0;

    END;

    IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @DetailIs AS s
                      INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
                      INNER JOIN Items.t_MainCategory AS s2 ON s2.ID = s1.MainCategoryID
                      INNER JOIN Items.t_Item AS s3 ON s3.ID = s.ItemID
                      WHERE s1.IsSerial = 0 AND s1.MaterialsCounts > 0 AND CASE @ProductionWhenSale
                                                                             WHEN 2 THEN s2.ProductionWhenSale
                                                                             WHEN 4 THEN IIF(s3.QtyCurrent < 0, 1, 0)
                                                                             ELSE 1
                                                                           END = 1 )
    BEGIN

      RETURN 0;

    END;
    
  END;
                  
  BEGIN --Declare

    DECLARE @DetailIs2 AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        ItemUnityID UNIQUEIDENTIFIER NOT NULL ,
        Qty FLOAT NOT NULL ,
        Qtys FLOAT NOT NULL ,
        Cost FLOAT NOT NULL ,
        AdditionalProperty1 NVARCHAR(MAX) NOT NULL ,
        AdditionalProperty2 NVARCHAR(MAX) NOT NULL ,
        AdditionalProperty3 NVARCHAR(MAX) NOT NULL ,
        AdditionalProperty4 NVARCHAR(MAX) NOT NULL ,
        AdditionalProperty5 NVARCHAR(MAX) NOT NULL
      );

    DECLARE @IDs TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

    DECLARE @SavedIDs TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        RefF NVARCHAR(MAX) NOT NULL
      );

    DECLARE @ID UNIQUEIDENTIFIER ,
      @DetailID UNIQUEIDENTIFIER ,
      @Ref BIGINT ,
      @EmployeeID UNIQUEIDENTIFIER ,
      @Employee NVARCHAR(MAX) ,
      @User NVARCHAR(MAX) ,
      @ItemSharedID UNIQUEIDENTIFIER ,
      @ItemID UNIQUEIDENTIFIER ,
      @ItemUnityID UNIQUEIDENTIFIER ,
      @Qty DECIMAL(18, 6) ,
      @Qtys DECIMAL(18, 6) ,
      @WarehouseID UNIQUEIDENTIFIER ,
      @Cost FLOAT ,
      @CostD FLOAT ,
      @CostTotal FLOAT ,
      @CostTotalD FLOAT ,
      @AdditionalProperty1 NVARCHAR(MAX) ,
      @AdditionalProperty2 NVARCHAR(MAX) ,
      @AdditionalProperty3 NVARCHAR(MAX) ,
      @AdditionalProperty4 NVARCHAR(MAX) ,
      @AdditionalProperty5 NVARCHAR(MAX);
   
    DECLARE @ItemQtys AS Items.ItemAppendQtys;

  END;

  BEGIN --Set info

    INSERT INTO @DetailIs2
        ( ID ,
          ItemSharedID ,
          ItemID ,
          ItemUnityID ,
          Qty ,
          Qtys ,
          Cost ,
          AdditionalProperty1 ,
          AdditionalProperty2 ,
          AdditionalProperty3 ,
          AdditionalProperty4 ,
          AdditionalProperty5
        )
      OUTPUT Inserted.ID
        INTO @IDs ( ID )
      SELECT s.ID ,
          s.ItemSharedID ,
          s.ItemID ,
          s.ItemUnityID ,
          s.Qty ,
          s.Qtys ,
          s.Cost ,
          s.AdditionalProperty1 ,
          s.AdditionalProperty2 ,
          s.AdditionalProperty3 ,
          s.AdditionalProperty4 ,
          s.AdditionalProperty5
        FROM @DetailIs AS s
        INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
        INNER JOIN Items.t_MainCategory AS s2 ON s2.ID = s1.MainCategoryID
        INNER JOIN Items.t_Item AS s3 ON s3.ID = s.ItemID
        WHERE s1.IsSerial = 0 AND s1.MaterialsCounts > 0 AND CASE @ProductionWhenSale
                                                               WHEN 2 THEN s2.ProductionWhenSale
                                                               WHEN 4 THEN IIF(s3.QtyCurrent < 0, 1, 0)
                                                               ELSE 1
                                                             END = 1;

    INSERT INTO @DetailIs2
        ( ID ,
          ItemSharedID ,
          ItemID ,
          ItemUnityID ,
          Qty ,
          Qtys ,
          Cost ,
          AdditionalProperty1 ,
          AdditionalProperty2 ,
          AdditionalProperty3 ,
          AdditionalProperty4 ,
          AdditionalProperty5
        )
      SELECT NEWID() ,
          t1.ItemSharedID ,
          t3.ID ,
          t1.ItemUnityID ,
          t.Qtys * t1.Qty AS Qty ,
          t.Qtys * t1.Qtys AS Qtys ,
          CASE @CurrencyTypeIs
            WHEN 0 THEN t2.PurchaseD
            WHEN 1 THEN t2.PurchaseLL
            ELSE t2.PurchaseEuro
          END AS Cost ,
          t2.AdditionalProperty1 ,
          t2.AdditionalProperty2 ,
          t2.AdditionalProperty3 ,
          t2.AdditionalProperty4 ,
          t2.AdditionalProperty5
        FROM @DetailIs AS t
        INNER JOIN Items.t_ItemSharedMaterial AS t1 ON t1.ItemSharedFatherID = t.ItemSharedID
        INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.ItemSharedID
        INNER JOIN Items.t_Item AS t3 ON t3.SharedID = t2.ID
        INNER JOIN Items.t_MainCategory AS t4 ON t4.ID = t2.MainCategoryID
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t.ID ) AND t2.IsSerial = 0 AND t2.MaterialsCounts > 0 AND CASE @ProductionWhenSale
                                                                                                 WHEN 2 THEN t4.ProductionWhenSale
                                                                                                 WHEN 4 THEN IIF(t3.QtyCurrent < 0, 1, 0)
                                                                                                 ELSE 1
                                                                                               END = 1;

    SELECT @EmployeeID = Employees.f_EmployeeGetFirstID();
    SELECT @Employee = Employees.f_EmployeeGetName(@EmployeeID);
    SELECT @User = Users.f_UserGetName(@UserID);
	  
  END;

  DECLARE i CURSOR FORWARD_ONLY
  FOR
  SELECT s.ID
    FROM @DetailIs2 AS s;

  OPEN i;
  FETCH NEXT FROM i
    INTO @DetailID;
  WHILE @@FETCH_STATUS = 0
  BEGIN
	
    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Items.t_ItemProduction AS s;
  
      SELECT TOP ( 1 ) @ItemSharedID = s.ItemSharedID ,
          @ItemID = s.ItemID ,
          @ItemUnityID = s.ItemUnityID ,
          @Qty = s.Qty ,
          @Qtys = s.Qtys ,
          @WarehouseID = s1.WareHouseID ,
          @Cost = s.Cost ,
          @AdditionalProperty1 = s.AdditionalProperty1 ,
          @AdditionalProperty2 = s.AdditionalProperty2 ,
          @AdditionalProperty3 = s.AdditionalProperty3 ,
          @AdditionalProperty4 = s.AdditionalProperty4 ,
          @AdditionalProperty5 = s.AdditionalProperty5
        FROM @DetailIs2 AS s
        INNER JOIN Items.t_Item AS s1 ON s1.ID = s.ItemID
        WHERE s.ID = @DetailID;
		
      SET @CostD = @Cost / @ExchangeRate;
      SET @CostTotal = @Cost * @Qty;
      SET @CostTotalD = @CostTotal / @ExchangeRate;

    END;

    BEGIN --Insert t_ItemProduction

      DELETE FROM @IDs;

      INSERT INTO Items.t_ItemProduction
          ( Ref ,
            OriginSection ,
            OriginID ,
            OriginRef ,
            OriginDetailID ,
            DateIs ,
            StartDate ,
            EndDate ,
            StageType ,
            EmployeeID ,
            Employee ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            Qtys ,
            WarehouseID ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Cost ,
            CostD ,
            CostLL ,
            CostEuro ,
            TotalCost ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            AdditionalProperty1 ,
            AdditionalProperty2 ,
            AdditionalProperty3 ,
            AdditionalProperty4 ,
            AdditionalProperty5 ,
            CreateByID ,
            CreateBy ,
            HaveSerial
          )
        OUTPUT Inserted.ID
          INTO @IDs ( ID )
        VALUES
          ( @Ref ,
            1 ,
            @SoldID ,
            @SoldRef ,
            @DetailID ,
            @DateIs ,
            @DateIs ,
            @DateIs ,
            @StageType ,
            @EmployeeID ,
            @Employee ,
            @ItemSharedID ,
            @ItemID ,
            @ItemUnityID ,
            @Qty ,
            @Qtys ,
            @WarehouseID ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Cost ,
            @CostD ,
            @CostD * @ExchangeRateLL ,
            @CostD * @ExchangeRateEuro ,
            @CostTotal ,
            @CostTotalD ,
            @CostTotalD * @ExchangeRateLL ,
            @CostTotalD * @ExchangeRateEuro ,
            @AdditionalProperty1 ,
            @AdditionalProperty2 ,
            @AdditionalProperty3 ,
            @AdditionalProperty4 ,
            @AdditionalProperty5 ,
            @UserID ,
            @User ,
            0
          );

      SET @ID = ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s
                    ORDER BY s.ID
                );

      INSERT INTO @SavedIDs
          ( ID, RefF )
        VALUES ( @ID, FORMAT(@Ref, '#') );
   
    END;
	
    BEGIN --Item Qtys +
    
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT @ItemID ,
            @ItemSharedID ,
            @Qtys;

    END; 
   
    BEGIN --Insert t_ItemProductionMaterial

      INSERT INTO Items.t_ItemProductionMaterial
          ( ItemProductionID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            Qty ,
            Qtys ,
            WarehouseID ,
            Cost ,
            TotalCost ,
            SortAt
          )
        OUTPUT Inserted.ItemID ,
          Inserted.ItemSharedID ,
          0 - Inserted.Qtys
          INTO @ItemQtys
        SELECT @ID ,
            s.ItemSharedID ,
            s2.ID ,
            s.ItemUnityID ,
            s.Qty * @Qtys ,
            s.Qtys * @Qtys ,
            @WarehouseID ,
            CASE @CurrencyTypeIs
              WHEN 0 THEN s1.PurchaseD
              WHEN 1 THEN s1.PurchaseLL
              ELSE s1.PurchaseEuro
            END * s3.Qty ,
            ( CASE @CurrencyTypeIs
                WHEN 0 THEN s1.PurchaseD
                WHEN 1 THEN s1.PurchaseLL
                ELSE s1.PurchaseEuro
              END * s3.Qty ) * ( s.Qty * @Qtys ) ,
            ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                         ) )
          FROM Items.t_ItemSharedMaterial AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
          INNER JOIN Items.t_Item AS s2 ON s2.SharedID = s1.ID AND s2.WareHouseID = @WarehouseID
          LEFT JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
          WHERE s.ItemSharedFatherID = @ItemSharedID;

    END;
	
    FETCH NEXT FROM i
        INTO @DetailID;
  END;
  CLOSE i;
  DEALLOCATE i;

  BEGIN--Item Qtys

    EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

  END;

  BEGIN --Fix t_ItemProduction, t_ItemProductionMaterial
	     
    UPDATE Items.t_ItemProduction
      SET RefF = FORMAT(Ref, '#') ,
          DateOnly = DateIs ,
          DateMonthly = DATEFROMPARTS(YEAR(DateIs), MONTH(DateIs), 1) ,
          DateYearly = DATEFROMPARTS(YEAR(DateIs), 1, 1) ,
          QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + Items.f_UnityItemGetName(ItemUnityID) ,
          Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
          CostF = Currencys.f_Format(CurrencyID, Cost) ,
          TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
          ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                        FROM Items.t_ItemProductionMaterial AS t
                                        LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                        WHERE t.ItemProductionID = t_ItemProduction.ID
                                     FOR
                                       XML PATH('')
                                     )) ,
          ItemsCounts = ( SELECT COUNT(*)
                            FROM Items.t_ItemProductionMaterial AS t
                            WHERE t.ItemProductionID = t_ItemProduction.ID
                        )
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @SavedIDs AS s
                      WHERE s.ID = t_ItemProduction.ID );
   
    UPDATE Items.t_ItemProductionMaterial
      SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + Items.f_UnityItemGetName(ItemUnityID) ,
          Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
          CostF = Currencys.f_Format(@CurrencyID, Cost) ,
          CostD = Cost / @ExchangeRate ,
          TotalCostF = Currencys.f_Format(@CurrencyID, TotalCost) ,
          TotalCostD = TotalCost / @ExchangeRate
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @SavedIDs AS s
                      WHERE s.ID = Items.t_ItemProductionMaterial.ItemProductionID );
     
    UPDATE Items.t_ItemProductionMaterial
      SET CostLL = CostD * @ExchangeRateLL ,
          CostEuro = CostD * @ExchangeRateEuro ,
          TotalCostLL = TotalCostD * @ExchangeRateLL ,
          TotalCostEuro = TotalCostD * @ExchangeRateEuro
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @SavedIDs AS s
                      WHERE s.ID = Items.t_ItemProductionMaterial.ItemProductionID );

  END;
	 
  BEGIN --Insert t_ItemProductionMoving

    INSERT INTO Items.t_ItemProductionMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      SELECT @UserID ,
          s.ID ,
          @EventInsert + N': ' + s.RefF + N' (' + @EventInsertBySold + N': ' + FORMAT(@SoldRef, N'#') + N')' ,
          0 ,
          @ComputerIP ,
          @Computer ,
          @ComputerAccount
        FROM @SavedIDs AS s;

  END;
  
  RETURN 1;

END;

GO
