/****** Object:  StoredProcedure [Items].[s_ItemProductionUpdateSerialNamesPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemProductionUpdateSerialNamesPART] @ID UNIQUEIDENTIFIER ,
  @SerialIs Items.tt_ItemSerial READONLY
AS
BEGIN
  
  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @SerialIs AS s )
  BEGIN

    RETURN;
			    
  END;

  UPDATE Items.t_ItemProduction
    SET SerialNames = Items.f_ItemProductionGetSerialNames(ID)
    WHERE ID = @ID;

END;





