/****** Object:  StoredProcedure [Items].[s_ItemReclassificationOfUsedItemsInWarehouses]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemReclassificationOfUsedItemsInWarehouses] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @IDs
          ( ID 
          )
        SELECT DISTINCT t.ItemID
          FROM Items.v_ItemMovement AS t;

    END;

    DISABLE TRIGGER Items.tr_Item ON Items.t_Item;

    BEGIN --Merge

      MERGE Items.t_Item AS t
      USING @IDs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.IsUsed = 1
      WHEN NOT MATCHED BY SOURCE THEN
        UPDATE SET t.IsUsed = 0;

    END;
	
    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, N'00000000-0000-0000-0000-000000000000';

    EXECUTE Items.s_ItemSharedLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

    RETURN @Return;

  END CATCH;

END;












