/****** Object:  StoredProcedure [Items].[s_Items_StockTakeUnsaved_ExecuteJob]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_Items_StockTakeUnsaved_ExecuteJob]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check i need execute

      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Alls.t_LastExecuteJob AS s
                        WHERE s.Items_StockTakeUnsaved < CONVERT(DATE, GETDATE()) )
      BEGIN

        COMMIT TRANSACTION;

        RETURN 1;

      END;

    END;

    BEGIN--
    
      DECLARE @IDs Alls.tt_Guid;

    END;


    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID
          )
        SELECT ID
          FROM Items.t_StockTakeUnsaved
          WHERE DATEDIFF(WEEK, DateIs, GETDATE()) >= 1;

    END;

    BEGIN --Delete 

      DELETE FROM Items.t_StockTakeUnsavedDetail
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_StockTakeUnsavedDetail.StockTakeUnsavedID );
  
      DELETE FROM Items.t_StockTakeUnsaved
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_StockTakeUnsaved.ID );

    END;

    BEGIN --Execute is done

      UPDATE Alls.t_LastExecuteJob
        SET Items_StockTakeUnsaved = GETDATE();

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;















