CREATE PROCEDURE [Items].[s_ItemSerialUpdate] @ID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @SerialText NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    DISABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    DISABLE TRIGGER Invoices.tr_PurchasingReturnDetail ON Invoices.t_PurchasingReturnDetail;
    DISABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;
    DISABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;
    DISABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    DISABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;
    DISABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    DISABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    DISABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    DISABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
    DISABLE TRIGGER Items.tr_ItemProductionMaterial ON Items.t_ItemProductionMaterial;
    DISABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update

      UPDATE Items.t_ItemSerial
        SET SerialText = @SerialText
        WHERE ID = @ID;

    END;

    BEGIN --Update t_PurchasingDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_PurchasingDetailSerial AS s
                    INNER JOIN Invoices.t_PurchasingDetail AS s1 ON s1.ID = s.PurchasingDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_PurchasingDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_PurchasingReturnDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_PurchasingReturnDetailSerial AS s
                    INNER JOIN Invoices.t_PurchasingReturnDetail AS s1 ON s1.ID = s.PurchasingReturnDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_PurchasingReturnDetailGetSerialNames(o.ID);

    END;

    BEGIN --Update t_SoldDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_SoldDetailSerial AS s
                    INNER JOIN Invoices.t_SoldDetail AS s1 ON s1.ID = s.SoldDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_SoldDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_SoldReturnDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_SoldReturnDetailSerial AS s
                    INNER JOIN Invoices.t_SoldReturnDetail AS s1 ON s1.ID = s.SoldReturnDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_SoldReturnDetailGetSerialNames(o.ID);

    END;

    BEGIN --Update t_TransferAwaitedDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_TransferAwaitedDetailSerial AS s
                    INNER JOIN Invoices.t_TransferAwaitedDetail AS s1 ON s1.ID = s.TransferAwaitedDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_TransferAwaitedDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_TransferDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Invoices.t_TransferDetailSerial AS s
                    INNER JOIN Invoices.t_TransferDetail AS s1 ON s1.ID = s.TransferDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Invoices.f_TransferDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_BeginningInventoryQuantityDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_BeginningInventoryQuantityDetailSerial AS s
                    INNER JOIN Items.t_BeginningInventoryQuantityDetail AS s1 ON s1.ID = s.BeginningInventoryQuantityDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_BeginningInventoryQuantityDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_DeliveryPermissionDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_DeliveryPermissionDetailSerial AS s
                    INNER JOIN Items.t_DeliveryPermissionDetail AS s1 ON s1.ID = s.DeliveryPermissionDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_DeliveryPermissionDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_DeliveryPermissionHistoryDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_DeliveryPermissionHistoryDetailSerial AS s
                    INNER JOIN Items.t_DeliveryPermissionHistoryDetail AS s1 ON s1.ID = s.DeliveryPermissionHistoryDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_DeliveryPermissionHistoryDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_ItemProduction

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_ItemProductionSerial AS s
                    INNER JOIN Items.t_ItemProduction AS s1 ON s1.ID = s.ItemProductionID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_ItemProductionGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_ItemProductionMaterial

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_ItemProductionMaterialSerial AS s
                    INNER JOIN Items.t_ItemProductionMaterial AS s1 ON s1.ID = s.ItemProductionMaterialID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_ItemProductionMaterialGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_StockAdjustmentDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_StockAdjustmentDetailSerial AS s
                    INNER JOIN Items.t_StockAdjustmentDetail AS s1 ON s1.ID = s.StockAdjustmentDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_StockAdjustmentDetailGetSerialNames(o.ID);

    END;
 
    BEGIN --Update t_StockTakeDetail

      WITH  o AS ( SELECT s1.ID ,
                      s1.SerialNames
                    FROM Items.t_StockTakeDetailSerial AS s
                    INNER JOIN Items.t_StockTakeDetail AS s1 ON s1.ID = s.StockTakeDetailID
                    WHERE s.SerialID = @ID
                 )
        UPDATE o
          SET o.SerialNames = Items.f_StockTakeDetailGetSerialNames(o.ID);

    END;

    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Items.s_ItemSerialLiveVersion;

    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    ENABLE TRIGGER Invoices.tr_PurchasingReturnDetail ON Invoices.t_PurchasingReturnDetail;
    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;
    ENABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    ENABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;
    ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    ENABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
    ENABLE TRIGGER Items.tr_ItemProductionMaterial ON Items.t_ItemProductionMaterial;
    ENABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    ENABLE TRIGGER Invoices.tr_PurchasingReturnDetail ON Invoices.t_PurchasingReturnDetail;
    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;
    ENABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    ENABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;
    ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    ENABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
    ENABLE TRIGGER Items.tr_ItemProductionMaterial ON Items.t_ItemProductionMaterial;
    ENABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;

    RETURN @Return;

  END CATCH;

END;






