/****** Object:  StoredProcedure [Items].[s_ItemSharedAdditionsDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedAdditionsDelete] @ID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;
	
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;
	  
    BEGIN --Insert t_ItemSharedAdditions

      DELETE FROM Items.t_ItemSharedAdditions
        WHERE ID = @ID;

    END;	

    EXECUTE Items.s_ItemSharedAdditionsReorderPART @ItemSharedID;

    SET @return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ItemSharedID;
  
    EXECUTE Alls.s_FireStoreRowsForDeleteInsertPART @ID, 0, 'itemSharedAdditions'; 

    EXECUTE Items.s_ItemSharedLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;



