/****** Object:  StoredProcedure [Items].[s_ItemSharedAdditionsImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedAdditionsImport] @ItemSharedAdditions Items.tt_ItemSharedAdditions2 READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @drs Items.tt_ItemSharedAdditions ,
        @IDs2 Alls.tt_IDAndEvent ,
        @ids Alls.tt_Guid;

    END;

    BEGIN --Set
    
      INSERT INTO @drs
          ( ID ,
            ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
	      )
        SELECT NEWID() ,
            s1.ID ,
            s2.ID ,
            s.OrderBy
          FROM @ItemSharedAdditions AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.Barcode = s.Barcode
          INNER JOIN Items.t_AdditionsOnItems AS s2 ON s2.Name = s.AdditionName;

      INSERT INTO @ids
          ( ID
          )
        SELECT DISTINCT s.ItemSharedID
          FROM @drs AS s;

      INSERT INTO @IDs2
          ( ID ,
            EventIs
          )
        SELECT ID ,
            N''
          FROM Items.t_ItemSharedAdditions
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ids AS s
                          WHERE s.ID = t_ItemSharedAdditions.ItemSharedID );

    END;

    BEGIN --Delete t_ItemSharedAdditions

      DELETE FROM Items.t_ItemSharedAdditions
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ids AS s
                        WHERE s.ID = t_ItemSharedAdditions.ItemSharedID );

    END;	

    BEGIN --Insert t_ItemSharedAdditions

      INSERT INTO Items.t_ItemSharedAdditions
          ( ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
          )
        SELECT s.ItemSharedID ,
            s.AdditionsOnItemsID ,
            s.OrderBy
          FROM @drs AS s;

    END;	

    EXECUTE Items.s_ItemSharedAdditionsReorderALLPART;

    EXECUTE Alls.s_FireStoreRowsForDeleteInsertsPART @IDs2, 0, 'itemSharedAdditions'; 

    EXECUTE Items.s_ItemSharedLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;



