/****** Object:  StoredProcedure [Items].[s_ItemSharedAdditionsInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedAdditionsInsert] @ItemSharedID UNIQUEIDENTIFIER ,
  @AdditionsOnItemsID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;
	
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @OrderBy BIGINT ,
        @return INT = 0;

    END;

    BEGIN --Set

      SELECT @OrderBy = ISNULL(MAX(s.OrderBy), 0) + 1
        FROM Items.t_ItemSharedAdditions AS s
        WHERE s.ItemSharedID = @ItemSharedID;

    END;
  
    BEGIN --Insert t_ItemSharedAdditions

      INSERT INTO Items.t_ItemSharedAdditions
          ( ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
          )
        VALUES
          ( @ItemSharedID ,
            @AdditionsOnItemsID ,
            @OrderBy
		  );

    END;	
	
    EXECUTE Items.s_ItemSharedAdditionsReorderPART @ItemSharedID;

    SET @return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ItemSharedID;

    EXECUTE Items.s_ItemSharedLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;



