/****** Object:  StoredProcedure [Items].[s_ItemSharedAdditionsReorderALLPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedAdditionsReorderALLPART]
AS
BEGIN

  WITH  o AS ( SELECT s.OrderBy ,
                  s.RowVersionID ,
                  ROW_NUMBER() OVER ( PARTITION BY s.ItemSharedID ORDER BY s.OrderBy ) AS OrderBy_
                FROM Items.t_ItemSharedAdditions AS s
             )
    UPDATE o
      SET o.OrderBy = o.OrderBy_ ,
          o.RowVersionID = [DateTimes].[f_GetRowVersionID]();


END;

