SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedAdditionsUpdates] @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemSharedAdditions Items.tt_ItemSharedAdditions READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;
	
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs Alls.tt_IDAndEvent ,
        @return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @IDs
          ( ID ,
            EventIs
          )
        SELECT ID ,
            N''
          FROM Items.t_ItemSharedAdditions
          WHERE ItemSharedID = @ItemSharedID;

    END;	

    BEGIN --Delete t_ItemSharedAdditions
   
      DELETE FROM Items.t_ItemSharedAdditions
        WHERE ItemSharedID = @ItemSharedID;

    END;	
  
    BEGIN --Insert t_ItemSharedAdditions

      INSERT INTO Items.t_ItemSharedAdditions
          ( ID ,
            ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.AdditionsOnItemsID ,
            s.OrderBy
          FROM @ItemSharedAdditions AS s;

    END;	
	
    EXECUTE Items.s_ItemSharedAdditionsReorderPART @ItemSharedID;

    SET @return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ItemSharedID;

    EXECUTE Alls.s_FireStoreRowsForDeleteInsertsPART @IDs, 0, 'itemSharedAdditions'; 
	
    EXECUTE Items.s_ItemSharedLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



