      DECLARE @Return INT = 0;

    END;
	
    BEGIN --Delete

      DELETE FROM Items.t_ItemSharedBarcodePrefix
        WHERE ID = @ID;

    END;
	
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            @EventType ,
