/****** Object:  StoredProcedure [Items].[s_ItemSharedBarCodeUpdates]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedBarCodeUpdates] @ItemSharedBarCode Items.tt_ItemSharedBarCodeMultiEdit READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemShared Items.tt_ItemSharedBarCodeMultiEdit ,
        @ItemUnit Items.tt_ItemSharedBarCodeMultiEdit ,
        @ItemExpirationDate Items.tt_ItemSharedBarCodeMultiEdit;

    END;

    BEGIN --Set
  
      INSERT INTO @ItemShared
          ( ID ,
            SharedID ,
            BarCode ,
            TypeIs ,
            ItemUnitID ,
            ItemExpirationDateID
          )
        SELECT s.ID ,
            s.SharedID ,
            s.BarCode ,
            s.TypeIs ,
            s.ItemUnitID ,
            s.ItemExpirationDateID
          FROM @ItemSharedBarCode AS s
          WHERE s.TypeIs = 0; 

      INSERT INTO @ItemUnit
          ( ID ,
            SharedID ,
            BarCode ,
            TypeIs ,
            ItemUnitID ,
            ItemExpirationDateID
          )
        SELECT s.ID ,
            s.SharedID ,
            s.BarCode ,
            s.TypeIs ,
            s.ItemUnitID ,
            s.ItemExpirationDateID
          FROM @ItemSharedBarCode AS s
          WHERE s.TypeIs = 2; 
   
      INSERT INTO @ItemExpirationDate
          ( ID ,
            SharedID ,
            BarCode ,
            TypeIs ,
            ItemUnitID ,
            ItemExpirationDateID
          )
        SELECT s.ID ,
            s.SharedID ,
            s.BarCode ,
            s.TypeIs ,
            s.ItemUnitID ,
            s.ItemExpirationDateID
          FROM @ItemSharedBarCode AS s
          WHERE s.TypeIs = 3; 

    END;	

    BEGIN --Merge t_ItemSharedBarCode

      MERGE Items.t_ItemSharedBarCode AS t
      USING @ItemSharedBarCode AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.BarCode = s.BarCode ,
                    t.BarcodeNumber = Alls.f_ToBigint(s.BarCode);

    END;

    BEGIN --Merge t_ItemShared

      MERGE Items.t_ItemShared AS t
      USING @ItemShared AS s
      ON s.SharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Barcode = s.BarCode ,
                    t.Barcodes = Items.f_ItemShared_GetLive_Barcodes(t.ID);

    END;

    BEGIN --Merge t_UnityItem

      MERGE Items.t_UnityItem AS t
      USING @ItemUnit AS s
      ON s.ItemUnitID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.BarCode = s.BarCode;

    END;

    BEGIN --Merge t_ItemExpirationDate

      MERGE Items.t_ItemExpirationDate AS t
      USING @ItemExpirationDate AS s
      ON s.ItemExpirationDateID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Barcode = s.BarCode;

    END;
		
    EXECUTE Items.s_ItemSharedLiveVersion;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;
	
    SELECT 0;

  END CATCH;

END;

GO
