CREATE PROCEDURE [Items].[s_ItemSharedCostCalculationByFather_PART] @ID UNIQUEIDENTIFIER
AS
BEGIN
   	
  DECLARE @IDs AS Alls.tt_Guid;
	  	
  INSERT INTO @IDs
      ( ID )
    VALUES ( @ID );

  EXECUTE Items.[s_ItemSharedCostCalculationByFathers_PART] @IDs;
		
