/****** Object:  StoredProcedure [Items].[s_ItemSharedCostCalculationByFathers_PART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemSharedCostCalculationByFathers_PART] @IDs Alls.tt_Guid READONLY
AS
BEGIN

  UPDATE Items.t_ItemShared
    SET Purchase = Items.f_ItemSharedMaterial_GetCost(ID)
    WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @IDs AS s
                    WHERE s.ID = t_ItemShared.ID );

  WITH  o AS ( SELECT t.ID ,
                  t.CurrencyID ,
                  t.Purchase ,
                  t.PurchaseF ,
                  t.PurchaseD ,
                  t.PurchaseLL ,
                  t.PurchaseEuro ,
                  t.PurchaseWithTax ,
                  t.TaxRate ,
                  t1.ExchangeRate
                FROM Items.t_ItemShared AS t
                INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
                WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                WHERE s.ID = t.ID )
             )
    UPDATE o
      SET o.PurchaseF = Currencys.f_Format(o.CurrencyID, o.Purchase) ,
          o.PurchaseD = o.Purchase / o.ExchangeRate ,
          o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
          o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
          o.PurchaseWithTax = Calculation.Rate(o.Purchase, o.TaxRate)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = o.ID );

  WITH  o AS ( SELECT t.ID ,
                  t.CurrencyID ,
                  t.QtyCurrent ,
                  t.Purchase ,
                  t.PurchaseF ,
                  t.PurchaseD ,
                  t.PurchaseLL ,
                  t.PurchaseEuro ,
                  t.PurchaseTotal ,
                  t.PurchaseTotalF ,
                  t.PurchaseTotalD ,
                  t.PurchaseTotalLL ,
                  t.PurchaseTotalEuro ,
                  t.PurchaseWithTax ,
                  t.PurchaseWithTaxF ,
                  t.PurchaseWithTaxD ,
                  t.PurchaseWithTaxLL ,
                  t.PurchaseWithTaxEuro ,
                  t.PurchaseTotalWithTax ,
                  t.PurchaseTotalWithTaxF ,
                  t.PurchaseTotalWithTaxD ,
                  t.PurchaseTotalWithTaxLL ,
                  t.PurchaseTotalWithTaxEuro ,
                  t.MaterialsCounts ,
                  t.MaterialsNames ,
                  t1.ExchangeRate
                FROM Items.t_ItemShared AS t
                INNER JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID
                WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                FROM @IDs AS s
                                WHERE s.ID = t.ID )
             )
    UPDATE o
      SET o.PurchaseWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax) ,
          o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
          o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
          o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
          o.PurchaseTotal = o.Purchase * o.QtyCurrent ,
          o.PurchaseTotalF = Currencys.f_Format(o.CurrencyID, o.Purchase * o.QtyCurrent) ,
          o.PurchaseTotalD = o.PurchaseD * o.QtyCurrent ,
          o.PurchaseTotalLL = o.PurchaseLL * o.QtyCurrent ,
          o.PurchaseTotalEuro = o.PurchaseEuro * o.QtyCurrent ,
          o.PurchaseTotalWithTax = o.PurchaseWithTax * o.QtyCurrent ,
          o.PurchaseTotalWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax * o.QtyCurrent) ,
          o.PurchaseTotalWithTaxD = o.PurchaseWithTaxD * o.QtyCurrent ,
          o.PurchaseTotalWithTaxLL = o.PurchaseWithTaxLL * o.QtyCurrent ,
          o.PurchaseTotalWithTaxEuro = o.PurchaseWithTaxEuro * o.QtyCurrent ,
          o.MaterialsNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                              FROM Items.t_ItemSharedMaterial AS t
                                              LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                              WHERE t.ItemSharedFatherID = o.ID
                                           FOR
                                             XML PATH('')
                                           )) ,
          MaterialsCounts = ( SELECT COUNT(t.ID)
                                FROM Items.t_ItemSharedMaterial AS t
                                WHERE t.ItemSharedFatherID = o.ID
                            )
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = o.ID );

END;





GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @MainCategoryID UNIQUEIDENTIFIER ,
        @BrandID UNIQUEIDENTIFIER ,
        @RowsDelete Alls.tt_FireStoreRowsForDelete ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @MainCategoryID = s.MainCategoryID ,
          @BrandID = s.BrandID
        FROM Items.t_ItemShared AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Set RowsDelete

      INSERT INTO @RowsDelete
          ( ID ,
            DocumentID ,
            HasImage ,
            TableName ,
            RowVersionID
          )
        SELECT ID ,
            ID ,
            0 ,
            N'itemSharedAdditions' ,
            0
          FROM Items.t_ItemSharedAdditions
          WHERE ItemSharedID = @ID
        UNION ALL
        SELECT @ID ,
            @ID ,
            1 ,
            'itemShared' ,
            0
        UNION ALL
        SELECT s.ID ,
            s.ID ,
            0 ,
            'item' ,
            0
          FROM Items.t_Item AS s
          WHERE s.SharedID = @ID;
		  
    END;

    DISABLE TRIGGER Items.tr_Item ON Items.t_Item;
    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
   
    BEGIN --Delete t_TrackDeletedItemsFromInvoices

      DELETE FROM Invoices.t_TrackDeletedItemsFromInvoices
        WHERE ItemSharedID = @ID;

    END;

    BEGIN --Delete t_ItemSharedAdditions

      DELETE FROM Items.t_ItemSharedAdditions
        WHERE ItemSharedID = @ID;

    END;
    
    BEGIN --Delete t_ItemSubtabDetail

      DELETE FROM Items.t_ItemSubtabDetail
        WHERE ItemSharedID = @ID;

    END;

    BEGIN --Delete t_ItemDiscountLimit

      DELETE FROM Items.t_ItemDiscountLimit
        WHERE ItemSharedID = @ID;

    END;

    BEGIN --Delete t_ItemSharedBarCode

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ID;

    END;

    BEGIN --Delete t_AccountItemPrice

      DELETE FROM Company.t_AccountItemPrice
        WHERE ItemSharedID = @ID;

    END;

    BEGIN --Delete t_UnityItem

      DELETE FROM Items.t_UnityItem
        WHERE SharedID = @ID;

    END;
	
    BEGIN --Delete t_Item

      DELETE FROM Items.t_Item
        WHERE SharedID = @ID;

    END;

    BEGIN --Delete File Storage Linked 

      DELETE FROM Company.t_FileStorageLinked
        WHERE SectionID = 10 AND OwnerID = @ID;

    END;

    BEGIN --Delete t_ItemSharedMaterial 

      DELETE FROM Items.t_ItemSharedMaterial
        WHERE ItemSharedFatherID = @ID;

    END;
   
    EXECUTE Items.s_ItemTabDeleteItemPART @ID;

    EXECUTE Items.s_ItemSharedEmployeeProfitDeletePART @ID;
	
    BEGIN --Delete

      DELETE FROM Items.t_ItemShared
        WHERE ID = @ID;

    END;

    BEGIN --Update t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemC -= 1 ,
            ItemInListCount = ( SELECT COUNT(*) AS Total
                                  FROM Items.t_ItemShared AS t
                                  WHERE t.MainCategoryID = t_MainCategory.ID AND t.InList = 1
                              )
        WHERE ID = @MainCategoryID;

    END;

    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID;
  
    EXECUTE Alls.s_FireStoreRowsForDeleteInsertsPART2 @RowsDelete; 

    EXECUTE Items.s_ItemSharedLiveVersion;

    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;
    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
  
    EXECUTE Items.s_Brands_ItemsCount_RebuildPART @BrandID;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN @Return;

  END CATCH;

END;


