/****** Object:  StoredProcedure [Items].[s_ItemSharedEmployeeProfitImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedEmployeeProfitImport] @dt Items.tt_ItemSharedEmployeeProfit2 READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @drs Items.tt_ItemSharedEmployeeProfit ,
        @ids Alls.tt_Guid ,
        @idsEmployee Alls.tt_Guid;

    END;

    BEGIN --Set
    
      INSERT INTO @drs
          ( ID ,
            ItemSharedID ,
            EmployeeID ,
            ProfitRatio ,
            ProfitRatioF ,
            ProfitOn ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            IfUserID ,
            DescriptionIs
          )
        SELECT NEWID() ,
            s1.ID ,
            s2.ID ,
            s.ProfitRatio ,
            s.ProfitRatioF ,
            s.ProfitOn ,
            s.Profit ,
            s.ProfitF ,
            s.ProfitD ,
            s.ProfitLL ,
            s.ProfitEuro ,
            ISNULL(s3.ID, Alls.f_GetEmptyGuid()) ,
            s.DescriptionIs
          FROM @dt AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.Barcode = s.Barcode
          INNER JOIN Employees.t_Employee AS s2 ON s2.Name = s.Employee
          LEFT JOIN Users.t_User AS s3 ON s3.Name = s.IfUser;

      INSERT INTO @ids
          ( ID
          )
        SELECT DISTINCT s.ItemSharedID
          FROM @drs AS s;

      INSERT INTO @idsEmployee
          ( ID
          )
        SELECT DISTINCT s.EmployeeID
          FROM @drs AS s;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            0 ,
            'itemSharedEmployeeProfit'
          FROM Items.t_ItemSharedEmployeeProfit AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ids AS s
                          WHERE s.ID = t.ItemSharedID );

    END;

    BEGIN --Delete t_ItemSharedEmployeeProfit

      DELETE FROM Items.t_ItemSharedEmployeeProfit
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ids AS s
                        WHERE s.ID = t_ItemSharedEmployeeProfit.ItemSharedID );

    END;	

    BEGIN --Insert t_ItemSharedEmployeeProfit

      INSERT INTO Items.t_ItemSharedEmployeeProfit
          ( ItemSharedID ,
            EmployeeID ,
            ProfitRatio ,
            ProfitRatioF ,
            ProfitOn ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            IfUserID ,
            DescriptionIs
          )
        SELECT s.ItemSharedID ,
            s.EmployeeID ,
            s.ProfitRatio ,
            s.ProfitRatioF ,
            s.ProfitOn ,
            s.Profit ,
            s.ProfitF ,
            s.ProfitD ,
            s.ProfitLL ,
            s.ProfitEuro ,
            s.IfUserID ,
            s.DescriptionIs
          FROM @drs AS s;

    END;	
  
    BEGIN --Update t_Employee
    
      UPDATE Employees.t_Employee
        SET ItemSharedProfitCount = Employees.f_EmployeeGetItemSharedProfitCountLIVE(ID) ,
            ItemSharedProfitNames = Employees.f_EmployeeGetItemSharedProfitNamesLIVE(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @idsEmployee AS s
                        WHERE s.ID = t_Employee.ID );

    END;
 
    BEGIN --Update t_ItemShared
    
      UPDATE Items.t_ItemShared
        SET EmployeesProfitCount = Items.f_ItemSharedGetEmployeesProfitCountLIVE(ID) ,
            EmployeesProfitNames = Items.f_ItemSharedGetEmployeesProfitNamesLIVE(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ids AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

    EXECUTE Items.s_ItemSharedLiveVersion;
    EXECUTE Employees.s_EmployeeLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;



GO
