/****** Object:  StoredProcedure [Items].[s_ItemSharedEmployeeProfitMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedEmployeeProfitMerge] @EmployeeID UNIQUEIDENTIFIER ,
  @ItemSharedEmployeeProfit Items.tt_ItemSharedEmployeeProfit READONLY ,
  @Moving Alls.tt_Moving READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --DECLARE

      DECLARE @Return INT  = 0;

      DECLARE @ItemSharedIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

    END;

    BEGIN --Set
    
      INSERT INTO @ItemSharedIDs
          ( ID
          )
        SELECT t.ItemSharedID
          FROM Items.t_ItemSharedEmployeeProfit AS t
          WHERE t.EmployeeID = @EmployeeID
        UNION
        SELECT s.ItemSharedID
          FROM @ItemSharedEmployeeProfit AS s;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            0 ,
            'itemSharedEmployeeProfit'
          FROM Items.t_ItemSharedEmployeeProfit AS t
          WHERE t.EmployeeID = @EmployeeID
        EXCEPT
        SELECT t.ID ,
            0 ,
            'itemSharedEmployeeProfit'
          FROM @ItemSharedEmployeeProfit AS t;

    END;

    BEGIN --Merge t_ItemSharedEmployeeProfit
    
      MERGE Items.t_ItemSharedEmployeeProfit AS t
      USING @ItemSharedEmployeeProfit AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 ItemSharedID ,
                 EmployeeID ,
                 ProfitRatio ,
                 ProfitRatioF ,
                 ProfitOn ,
                 Profit ,
                 ProfitF ,
                 ProfitD ,
                 ProfitLL ,
                 ProfitEuro ,
                 IfUserID ,
                 DescriptionIs
               )
        VALUES ( s.ID ,
                 s.ItemSharedID ,
                 s.EmployeeID ,
                 s.ProfitRatio ,
                 s.ProfitRatioF ,
                 s.ProfitOn ,
                 s.Profit ,
                 s.ProfitF ,
                 s.ProfitD ,
                 s.ProfitLL ,
                 s.ProfitEuro ,
                 s.IfUserID ,
                 s.DescriptionIs
               )
      WHEN MATCHED AND t.EmployeeID = @EmployeeID THEN
        UPDATE SET t.ProfitRatio = s.ProfitRatio ,
                    t.ProfitRatioF = s.ProfitRatioF ,
                    t.ProfitOn = s.ProfitOn ,
                    t.Profit = s.Profit ,
                    t.ProfitF = s.ProfitF ,
                    t.ProfitD = s.ProfitD ,
                    t.ProfitLL = s.ProfitLL ,
                    t.ProfitEuro = s.ProfitEuro ,
                    t.IfUserID = s.IfUserID ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.IsSync = 0
      WHEN NOT MATCHED BY SOURCE AND t.EmployeeID = @EmployeeID THEN
        DELETE;

    END;
  
    BEGIN --Update t_Employee
    
      UPDATE Employees.t_Employee
        SET ItemSharedProfitCount = Employees.f_EmployeeGetItemSharedProfitCountLIVE(ID) ,
            ItemSharedProfitNames = Employees.f_EmployeeGetItemSharedProfitNamesLIVE(ID)
        WHERE ID = @EmployeeID;

    END;
 
    BEGIN --Update t_ItemShared
    
      UPDATE Items.t_ItemShared
        SET EmployeesProfitCount = Items.f_ItemSharedGetEmployeesProfitCountLIVE(ID) ,
            EmployeesProfitNames = Items.f_ItemSharedGetEmployeesProfitNamesLIVE(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemSharedIDs AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

	--Insert t_ItemSharedMoving
    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertsPART @Moving;

    EXECUTE Items.s_ItemSharedLiveVersion;
    EXECUTE Employees.s_EmployeeLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;








GO
