            @EmployeesProfitNames ,
            Alls.f_ToSearchIndex(@SearchIndex)
          );

    END;

    BEGIN --Insert barcodes

      SET @Return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        SELECT DISTINCT @ID ,
            t.Barcode ,
            Alls.f_ToBigint(t.Barcode) ,
            t.TypeIs
          FROM @Barcodes AS t;

    END;

    BEGIN --Insert items

      INSERT INTO Items.t_Item
          ( SharedID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place ,
