            DistributionPriceLL ,
            DistributionPriceEuro ,
            DistributionPriceWithTax ,
            DistributionPriceWithTaxF ,
            DistributionPriceWithTaxD ,
            DistributionPriceWithTaxLL ,
            DistributionPriceWithTaxEuro ,
            LowestPrice ,
            LowestPriceF ,
            LowestPriceD
          )
        SELECT t.ID ,
            t.UnityID ,
            Items.f_UnityGetName(t.UnityID) ,
            @ID ,
            t.Qty ,
            t.IsPrimary ,
            t.Purchasing ,
            t.Sold ,
            t.Inventory ,
            t.UseInTransfer ,
            t.BarCode ,
            t.CurrencyID ,
            t1.Name ,
            t.Price ,
            Currencys.f_Format(t.CurrencyID, t.Price) ,
            t.Price / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.Price, t.Price / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.Price, t.Price / t1.ExchangeRate) ,
            Calculation.Rate(t.Price, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate)) ,
            Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate), Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate), Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate) ,
            t.WholesalePrice ,
            Currencys.f_Format(t.CurrencyID, t.WholesalePrice) ,
            t.WholesalePrice / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.WholesalePrice, t.WholesalePrice / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.WholesalePrice, t.WholesalePrice / t1.ExchangeRate) ,
            Calculation.Rate(t.WholesalePrice, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate)) ,
            Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate), Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate), Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate) ,
            t.DistributionPrice ,
            Currencys.f_Format(t.CurrencyID, t.DistributionPrice) ,
            t.DistributionPrice / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.DistributionPrice, t.DistributionPrice / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.DistributionPrice, t.DistributionPrice / t1.ExchangeRate) ,
            Calculation.Rate(t.DistributionPrice, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate)) ,
            Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate), Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate), Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate) ,
            t.LowestPrice ,
            Currencys.f_Format(t.CurrencyID, t.LowestPrice) ,
            t.LowestPrice / t1.ExchangeRate
          FROM @Unities AS t
          LEFT JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID;

    END;

    BEGIN --Insert t_ItemSharedMaterial

      INSERT INTO Items.t_ItemSharedMaterial
          ( ID ,
            ItemSharedFatherID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            CreateByID ,
            CreateBy ,
            OrderBy
          )
        SELECT t.ID ,
            @ID ,
            t.ItemSharedID ,
            t.ItemUnityID ,
            t.Qty ,
            Items.f_FormatQty(t.Qty) + ' ' + t2.Name ,
            t.Qtys ,
            t.DescriptionIs ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            t.OrderBy
          FROM @Material AS t
          INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
          INNER JOIN Items.t_Unity AS t2 ON t2.ID = t1.UnityID;

    END;

	-- Insert t_ItemSharedEmployeeProfit
    EXECUTE Items.s_ItemSharedEmployeeProfitMergePART @ID, @ItemSharedEmployeeProfit;

    BEGIN --Insert t_ItemSharedAdditions
   
      INSERT INTO Items.t_ItemSharedAdditions
          ( ID ,
            ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.AdditionsOnItemsID ,
            s.OrderBy
          FROM @ItemSharedAdditions AS s;

    END;	

    EXECUTE Items.s_ItemSharedAdditionsReorderPART @ID;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            UnityC = ( SELECT COUNT(t.ID)
                        FROM Items.t_UnityItem AS t
                        WHERE t.SharedID = t_ItemShared.ID
                     ) ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID) ,
            MaterialsNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                              FROM @Material AS t
                                              LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                           FOR
                                             XML PATH('')
                                           )) ,
            MaterialsCounts = ( SELECT COUNT(t.ID)
                                  FROM @Material AS t
                              ) ,
            PlacesNames = Alls.f_FixXML(( SELECT N', ' + t.Place AS [text()]
                                            FROM Items.t_Item AS t
                                            WHERE t.SharedID = t_ItemShared.ID
                                        FOR
                                          XML PATH('')
                                        )) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL)
        WHERE ID = @ID;
     
      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE SharedID = @ID;

    END;

    BEGIN --Rebuilding statistics t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemC += 1 ,
            ItemInListCount += IIF(@InList = 1, 1, 0)
        WHERE ID = @MainCategoryID;

    END;

	--BeginningInventoryQuantity   	                                                                        
    EXECUTE Items.s_BeginningInventoryQuantityInsertByItemSharedPART @BeginningInventoryQuantity, @BeginningInventoryQuantityDetail;

    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Items.s_Brands_ItemsCount_AddPART @BrandID, 1;	

    EXECUTE Items.s_ItemTabOrSubAddItemPART @ItemTabOrSubID, @TabType, @ID, @ItemUnitID, @UserID;  

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

















GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedInsertShort]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedInsertShort] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @Barcode NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Purchase FLOAT ,
  @AdditionalProperty1 NVARCHAR(MAX) ,
  @AdditionalProperty2 NVARCHAR(MAX) ,
  @AdditionalProperty3 NVARCHAR(MAX) ,
  @AdditionalProperty4 NVARCHAR(MAX) ,
  @AdditionalProperty5 NVARCHAR(MAX) ,
  @AdditionalProperty6 NVARCHAR(MAX) ,
  @AdditionalProperty7 NVARCHAR(MAX) ,
  @AdditionalProperty8 NVARCHAR(MAX) ,
  @AdditionalProperty9 NVARCHAR(MAX) ,
  @AdditionalProperty10 NVARCHAR(MAX) ,
  @Unities Items.td_Unity READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0 ,
        @WholesalePrice FLOAT ,
        @DistributionPrice FLOAT ,
        @Sell FLOAT ,
        @ExchangeRate FLOAT ,
        @SellCurrencyID UNIQUEIDENTIFIER ,
        @SellExchangeRate FLOAT ,
        @TaxRate DECIMAL(4, 2) = 0 ,
        @BrandID UNIQUEIDENTIFIER = Items.f_BrandGetFirstID() ,
        @SearchIndex Alls.td_String;

    END;

    BEGIN --Set info

      SET @ExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyID);
      SET @SellExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@SellCurrencyID);
 
      SELECT TOP ( 1 ) @SellCurrencyID = s.CurrencyID ,
          @WholesalePrice = s.WholesalePrice ,
          @DistributionPrice = s.DistributionPrice ,
          @Sell = s.Price
        FROM @Unities AS s
        WHERE s.IsPrimary = 1
        ORDER BY s.IsPrimary;

      INSERT INTO @SearchIndex
          ( Name )
        VALUES ( @Name );

    END;

    BEGIN --Insert t_ItemShared

      INSERT INTO Items.t_ItemShared
          ( ID ,
            Name ,
            Barcode ,
            Barcodes ,
            CurrencyID ,
            Currency ,
            Purchase ,
            PurchaseF ,
            PurchaseD ,
            PurchaseLL ,
            PurchaseEuro ,
            PurchaseTotalF ,
            PurchaseWithTax ,
            PurchaseWithTaxF ,
            PurchaseWithTaxD ,
            PurchaseWithTaxLL ,
            PurchaseWithTaxEuro ,
            PurchaseTotalWithTaxF ,
            SellCurrencyID ,
            SellCurrency ,
            WholesalePrice ,
            WholesalePriceF ,
            WholesalePriceD ,
            WholesalePriceLL ,
            WholesalePriceEuro ,
            TotalWholesalePriceF ,
            WholesalePriceWithTax ,
            WholesalePriceWithTaxF ,
            WholesalePriceWithTaxD ,
            WholesalePriceWithTaxLL ,
            WholesalePriceWithTaxEuro ,
            TotalWholesalePriceWithTaxF ,
            DistributionPrice ,
            DistributionPriceF ,
            DistributionPriceD ,
            DistributionPriceLL ,
            DistributionPriceEuro ,
            TotalDistributionPriceF ,
            DistributionPriceWithTax ,
            DistributionPriceWithTaxF ,
            DistributionPriceWithTaxD ,
            DistributionPriceWithTaxLL ,
            DistributionPriceWithTaxEuro ,
            TotalDistributionPriceWithTaxF ,
            Sell ,
            SellF ,
            SellD ,
            SellLL ,
            SellEuro ,
            SellTotalF ,
            SellWithTax ,
            SellWithTaxF ,
            SellWithTaxD ,
            SellWithTaxLL ,
            SellWithTaxEuro ,
            SellTotalWithTaxF ,
            AdditionalProperty1 ,
            AdditionalProperty2 ,
            AdditionalProperty3 ,
            AdditionalProperty4 ,
            AdditionalProperty5 ,
            AdditionalProperty6 ,
            AdditionalProperty7 ,
            AdditionalProperty8 ,
            AdditionalProperty9 ,
            AdditionalProperty10 ,
            SearchIndex
          )
        VALUES
          ( @ID ,
            @Name ,
            @Barcode ,
            @Barcode ,
            @CurrencyID ,
            Currencys.f_CurrencyGetName(@CurrencyID) ,
            @Purchase ,
            Currencys.f_Format(@CurrencyID, @Purchase) ,
            @Purchase / @ExchangeRate ,
            Currencys.f_ExchangeToLL(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            Currencys.f_Format(@CurrencyID, 0) ,
            @Purchase ,
            Currencys.f_Format(@CurrencyID, @Purchase) ,
            @Purchase / @ExchangeRate ,
            Currencys.f_ExchangeToLL(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            Currencys.f_Format(@CurrencyID, 0) ,
            @SellCurrencyID ,
            Currencys.f_CurrencyGetName(@SellCurrencyID) ,
            @WholesalePrice ,
            Currencys.f_Format(@SellCurrencyID, @WholesalePrice) ,
            @WholesalePrice / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @WholesalePrice, @WholesalePrice / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @WholesalePrice, @WholesalePrice / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @WholesalePrice ,
            Currencys.f_Format(@SellCurrencyID, @WholesalePrice) ,
            @WholesalePrice / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @WholesalePrice, @WholesalePrice / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @WholesalePrice, @WholesalePrice / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @DistributionPrice ,
            Currencys.f_Format(@SellCurrencyID, @DistributionPrice) ,
            @DistributionPrice / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @DistributionPrice, @DistributionPrice / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @DistributionPrice, @DistributionPrice / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @DistributionPrice ,
            Currencys.f_Format(@SellCurrencyID, @DistributionPrice) ,
            @DistributionPrice / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @DistributionPrice, @DistributionPrice / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @DistributionPrice, @DistributionPrice / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @Sell ,
            Currencys.f_Format(@SellCurrencyID, @Sell) ,
            @Sell / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @Sell, @Sell / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @Sell, @Sell / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @Sell ,
            Currencys.f_Format(@SellCurrencyID, @Sell) ,
            @Sell / @SellExchangeRate ,
            Currencys.f_ExchangeToLL(@SellCurrencyID, @Sell, @Sell / @SellExchangeRate) ,
            Currencys.f_ExchangeToEuro(@SellCurrencyID, @Sell, @Sell / @SellExchangeRate) ,
            Currencys.f_Format(@SellCurrencyID, 0) ,
            @AdditionalProperty1 ,
            @AdditionalProperty2 ,
            @AdditionalProperty3 ,
            @AdditionalProperty4 ,
            @AdditionalProperty5 ,
            @AdditionalProperty6 ,
            @AdditionalProperty7 ,
            @AdditionalProperty8 ,
            @AdditionalProperty9 ,
            @AdditionalProperty10 ,
            Alls.f_ToSearchIndex(@SearchIndex)
          );

    END;

    BEGIN --Insert t_ItemSharedBarCode

      SET @Return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        VALUES
          ( @ID ,
            @Barcode ,
            Alls.f_ToBigint(@Barcode) ,
            0
          );

    END;

    BEGIN --Insert t_Item

      INSERT INTO Items.t_Item
          ( SharedID ,
            WareHouseID ,
            WareHouse ,
            PlaceID ,
            Place 
          )
        SELECT @ID ,
            t.ID ,
            t.Name ,
            Company.f_PlaceGetFirstID1(t.ID) ,
            Company.f_PlaceGetFirstName1(t.ID)
          FROM Company.t_WareHouse AS t;

    END;

    BEGIN --Insert t_UnityItem

      INSERT INTO Items.t_UnityItem
          ( UnityID ,
            Unity ,
            SharedID ,
            Qty ,
            PrimaryIs ,
            Purchasing ,
            Sold ,
            Inventory ,
            UseInTransfer ,
            BarCode ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            PriceWithTax ,
            PriceWithTaxF ,
            PriceWithTaxD ,
            PriceWithTaxLL ,
            PriceWithTaxEuro ,
            WholesalePrice ,
            WholesalePriceF ,
            WholesalePriceD ,
            WholesalePriceLL ,
            WholesalePriceEuro ,
            WholesalePriceWithTax ,
            WholesalePriceWithTaxF ,
            WholesalePriceWithTaxD ,
            WholesalePriceWithTaxLL ,
            WholesalePriceWithTaxEuro ,
            DistributionPrice ,
            DistributionPriceF ,
            DistributionPriceD ,
            DistributionPriceLL ,
            DistributionPriceEuro ,
            DistributionPriceWithTax ,
            DistributionPriceWithTaxF ,
            DistributionPriceWithTaxD ,
            DistributionPriceWithTaxLL ,
            DistributionPriceWithTaxEuro ,
            LowestPrice ,
            LowestPriceF ,
            LowestPriceD
          )
        SELECT t.UnityID ,
            Items.f_UnityGetName(t.UnityID) ,
            @ID ,
            t.Qty ,
            t.IsPrimary ,
            t.Purchasing ,
            t.Sold ,
            t.Inventory ,
            t.UseInTransfer ,
            t.BarCode ,
            t.CurrencyID ,
            t1.Name ,
            t.Price ,
            Currencys.f_Format(t.CurrencyID, t.Price) ,
            t.Price / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.Price, t.Price / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.Price, t.Price / t1.ExchangeRate) ,
            Calculation.Rate(t.Price, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate)) ,
            Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate), Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.Price, @TaxRate), Calculation.Rate(t.Price, @TaxRate) / t1.ExchangeRate) ,
            t.WholesalePrice ,
            Currencys.f_Format(t.CurrencyID, t.WholesalePrice) ,
            t.WholesalePrice / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.WholesalePrice, t.WholesalePrice / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.WholesalePrice, t.WholesalePrice / t1.ExchangeRate) ,
            Calculation.Rate(t.WholesalePrice, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate)) ,
            Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate), Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.WholesalePrice, @TaxRate), Calculation.Rate(t.WholesalePrice, @TaxRate) / t1.ExchangeRate) ,
            t.DistributionPrice ,
            Currencys.f_Format(t.CurrencyID, t.DistributionPrice) ,
            t.DistributionPrice / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, t.DistributionPrice, t.DistributionPrice / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, t.DistributionPrice, t.DistributionPrice / t1.ExchangeRate) ,
            Calculation.Rate(t.DistributionPrice, @TaxRate) ,
            Currencys.f_Format(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate)) ,
            Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate ,
            Currencys.f_ExchangeToLL(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate), Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(t.CurrencyID, Calculation.Rate(t.DistributionPrice, @TaxRate), Calculation.Rate(t.DistributionPrice, @TaxRate) / t1.ExchangeRate) ,
            t.LowestPrice ,
            Currencys.f_Format(t.CurrencyID, t.LowestPrice) ,
            t.LowestPrice / t1.ExchangeRate
          FROM @Unities AS t
          LEFT JOIN Currencys.t_Currency AS t1 ON t1.ID = t.CurrencyID;

    END;

    BEGIN --Rebuild t_ItemShared

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            UnityC = ( SELECT COUNT(t.ID)
                        FROM Items.t_UnityItem AS t
                        WHERE t.SharedID = t_ItemShared.ID
                     ) ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID) ,
            PlacesNames = Alls.f_FixXML(( SELECT N', ' + t.Place AS [text()]
                                            FROM Items.t_Item AS t
                                            WHERE t.SharedID = t_ItemShared.ID
                                        FOR
                                          XML PATH('')
                                        )) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL)
        WHERE ID = @ID;
     
      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE SharedID = @ID;

    END;

    BEGIN --Rebuild t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemC += 1
        WHERE ID = [Items].[f_MainCategoryGetFirstID]();

    END;

    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
  
    EXECUTE Items.s_Brands_ItemsCount_AddPART @BrandID, 1;	

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;
















GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedKeepProfitRatioFixPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedKeepProfitRatioFixPART] @IDs Alls.tt_Guid READONLY
AS
BEGIN

  BEGIN; --t_ItemShared KeepProfitRatio

    WITH  o AS ( SELECT s.SellCurrencyID ,
                    s2.ExchangeRate AS ExchangeRateSell ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.WholesalePriceProfitRatio)) AS WholesalePrice_ ,
                    s.WholesalePrice ,
                    s.WholesalePriceF ,
                    s.WholesalePriceD ,
                    s.WholesalePriceLL ,
                    s.WholesalePriceEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.WholesalePriceProfitRatio)), s.TaxRate) AS WholesalePriceWithTax_ ,
                    s.WholesalePriceWithTax ,
                    s.WholesalePriceWithTaxF ,
                    s.WholesalePriceWithTaxD ,
                    s.WholesalePriceWithTaxLL ,
                    s.WholesalePriceWithTaxEuro ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.DistributionPriceProfitRatio)) AS DistributionPrice_ ,
                    s.DistributionPrice ,
                    s.DistributionPriceF ,
                    s.DistributionPriceD ,
                    s.DistributionPriceLL ,
                    s.DistributionPriceEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.DistributionPriceProfitRatio)), s.TaxRate) AS DistributionPriceWithTax_ ,
                    s.DistributionPriceWithTax ,
                    s.DistributionPriceWithTaxF ,
                    s.DistributionPriceWithTaxD ,
                    s.DistributionPriceWithTaxLL ,
                    s.DistributionPriceWithTaxEuro ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.ProfitRatio)) AS Sell_ ,
                    s.Sell ,
                    s.SellF ,
                    s.SellD ,
                    s.SellLL ,
                    s.SellEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyID, s.SellCurrencyID, Calculation.Rate(s.Purchase, s.ProfitRatio)), s.TaxRate) AS SellWithTax_ ,
                    s.SellWithTax ,
                    s.SellWithTaxF ,
                    s.SellWithTaxD ,
                    s.SellWithTaxLL ,
                    s.SellWithTaxEuro
                  FROM Items.t_ItemShared AS s
                  INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s.SellCurrencyID
                  WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  WHERE s.ID = s.ID ) AND s.KeepProfitRatio = 1
               )
      UPDATE o
        SET o.WholesalePrice = o.WholesalePrice_ ,
            o.WholesalePriceF = Currencys.f_Format(o.SellCurrencyID, o.WholesalePrice_) ,
            o.WholesalePriceD = o.WholesalePrice_ / o.ExchangeRateSell ,
            o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.ExchangeRateSell) ,
            o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.ExchangeRateSell) ,
            o.WholesalePriceWithTax = o.WholesalePriceWithTax_ ,
            o.WholesalePriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.WholesalePriceWithTax_) ,
            o.WholesalePriceWithTaxD = o.WholesalePriceWithTax_ / o.ExchangeRateSell ,
            o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.ExchangeRateSell) ,
            o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.ExchangeRateSell) ,
            o.DistributionPrice = o.DistributionPrice_ ,
            o.DistributionPriceF = Currencys.f_Format(o.SellCurrencyID, o.DistributionPrice_) ,
            o.DistributionPriceD = o.DistributionPrice_ / o.ExchangeRateSell ,
            o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.ExchangeRateSell) ,
            o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.ExchangeRateSell) ,
            o.DistributionPriceWithTax = o.DistributionPriceWithTax_ ,
            o.DistributionPriceWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.DistributionPriceWithTax_) ,
            o.DistributionPriceWithTaxD = o.DistributionPriceWithTax_ / o.ExchangeRateSell ,
            o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.ExchangeRateSell) ,
            o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.ExchangeRateSell) ,
            o.Sell = o.Sell_ ,
            o.SellF = Currencys.f_Format(o.SellCurrencyID, o.Sell_) ,
            o.SellD = o.Sell_ / o.ExchangeRateSell ,
            o.SellLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.Sell_, o.Sell_ / o.ExchangeRateSell) ,
            o.SellEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.Sell_, o.Sell_ / o.ExchangeRateSell) ,
            o.SellWithTax = o.SellWithTax_ ,
            o.SellWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.SellWithTax_) ,
            o.SellWithTaxD = o.SellWithTax_ / o.ExchangeRateSell ,
            o.SellWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.SellWithTax_, o.SellWithTax_ / o.ExchangeRateSell) ,
            o.SellWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.SellWithTax_, o.SellWithTax_ / o.ExchangeRateSell);

    UPDATE Items.t_ItemShared
      SET FinalPrice = Calculation.Discount(Sell, Discount) ,
          FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
          FinalPriceD = Calculation.Discount(SellD, Discount) ,
          FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
          FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
          TotalWholesalePrice = WholesalePrice * QtyCurrent ,
          TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
          TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
          TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
          TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
          TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
          TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
          TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
          TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
          TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
          TotalDistributionPrice = DistributionPrice * QtyCurrent ,
          TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
          TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
          TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
          TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
          TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
          TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
          TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
          TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
          TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
          SellTotal = Sell * QtyCurrent ,
          SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
          SellTotalD = SellD * QtyCurrent ,
          SellTotalLL = SellLL * QtyCurrent ,
          SellTotalEuro = SellEuro * QtyCurrent ,
          SellTotalWithTax = SellWithTax * QtyCurrent ,
          SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
          SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
          SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
          SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_ItemShared.ID ) AND KeepProfitRatio = 1;

  END;

  BEGIN; --t_UnityItem KeepProfitRatio

    WITH  o AS ( SELECT s.CurrencyID ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.ProfitRatio)) AS Price_ ,
                    s.Price ,
                    s.PriceF ,
                    s.PriceD ,
                    s.PriceLL ,
                    s.PriceEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.ProfitRatio)), s3.TaxRate) AS PriceWithTax_ ,
                    s.PriceWithTax ,
                    s.PriceWithTaxF ,
                    s.PriceWithTaxD ,
                    s.PriceWithTaxLL ,
                    s.PriceWithTaxEuro ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.DistributionPriceProfitRatio)) AS DistributionPrice_ ,
                    s.DistributionPrice ,
                    s.DistributionPriceF ,
                    s.DistributionPriceD ,
                    s.DistributionPriceLL ,
                    s.DistributionPriceEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.DistributionPriceProfitRatio)), s3.TaxRate) AS DistributionPriceWithTax_ ,
                    s.DistributionPriceWithTax ,
                    s.DistributionPriceWithTaxF ,
                    s.DistributionPriceWithTaxD ,
                    s.DistributionPriceWithTaxLL ,
                    s.DistributionPriceWithTaxEuro ,
                    Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.WholesalePriceProfitRatio)) AS WholesalePrice_ ,
                    s.WholesalePrice ,
                    s.WholesalePriceF ,
                    s.WholesalePriceD ,
                    s.WholesalePriceLL ,
                    s.WholesalePriceEuro ,
                    Calculation.Rate(Currencys.f_CurrencyExchangeTo(s.CurrencyIDCost, s.CurrencyID, Calculation.Rate(s.Cost, s.WholesalePriceProfitRatio)), s3.TaxRate) AS WholesalePriceWithTax_ ,
                    s.WholesalePriceWithTax ,
                    s.WholesalePriceWithTaxF ,
                    s.WholesalePriceWithTaxD ,
                    s.WholesalePriceWithTaxLL ,
                    s.WholesalePriceWithTaxEuro ,
                    s2.ExchangeRate AS EXSell
                  FROM Items.t_UnityItem AS s
                  INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s.CurrencyID
                  INNER JOIN Items.t_ItemShared AS s3 ON s3.ID = s.SharedID
                  WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                                  FROM @IDs AS s
                                  WHERE s.ID = s3.ID ) AND s3.KeepProfitRatio = 1
               )
      UPDATE o
        SET o.Price = o.Price_ ,
            o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price_) ,
            o.PriceD = o.Price_ / o.EXSell ,
            o.PriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Price_, o.Price_ / o.EXSell) ,
            o.PriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Price_, o.Price_ / o.EXSell) ,
            o.PriceWithTax = o.PriceWithTax_ ,
            o.PriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.PriceWithTax_) ,
            o.PriceWithTaxD = o.PriceWithTax_ / o.EXSell ,
            o.PriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PriceWithTax_, o.PriceWithTax_ / o.EXSell) ,
            o.PriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PriceWithTax_, o.PriceWithTax_ / o.EXSell) ,
            o.DistributionPrice = o.DistributionPrice_ ,
            o.DistributionPriceF = Currencys.f_Format(o.CurrencyID, o.DistributionPrice_) ,
            o.DistributionPriceD = o.DistributionPrice_ / o.EXSell ,
            o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.EXSell) ,
            o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPrice_, o.DistributionPrice_ / o.EXSell) ,
            o.DistributionPriceWithTax = o.DistributionPriceWithTax_ ,
            o.DistributionPriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.DistributionPriceWithTax_) ,
            o.DistributionPriceWithTaxD = o.DistributionPriceWithTax_ / o.EXSell ,
            o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.EXSell) ,
            o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPriceWithTax_, o.DistributionPriceWithTax_ / o.EXSell) ,
            o.WholesalePrice = o.WholesalePrice_ ,
            o.WholesalePriceF = Currencys.f_Format(o.CurrencyID, o.WholesalePrice_) ,
            o.WholesalePriceD = o.WholesalePrice_ / o.EXSell ,
            o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.EXSell) ,
            o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePrice_, o.WholesalePrice_ / o.EXSell) ,
            o.WholesalePriceWithTax = o.WholesalePriceWithTax_ ,
            o.WholesalePriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.WholesalePriceWithTax_) ,
            o.WholesalePriceWithTaxD = o.WholesalePriceWithTax_ / o.EXSell ,
            o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.EXSell) ,
            o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePriceWithTax_, o.WholesalePriceWithTax_ / o.EXSell);

  END;
	
  BEGIN --Rebuilding statistics

    UPDATE Items.t_ItemShared
      SET WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
          DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
          ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_ItemShared.ID );

    UPDATE Items.t_UnityItem
      SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
          DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
          WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_UnityItem.SharedID );

  END;

END;




