/****** Object:  StoredProcedure [Items].[s_ItemSharedMaterialDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedMaterialDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemSharedFatherIDs Alls.tt_Guid;

      DECLARE @ItemSharedFatherID UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ItemSharedFatherID = s.ItemSharedFatherID
        FROM Items.t_ItemSharedMaterial AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemSharedFatherIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE s.ItemSharedID = @ItemSharedFatherID; 

    END;

    BEGIN --Delete
	
      DELETE FROM Items.t_ItemSharedMaterial
        WHERE ID = @ID;

    END;

    EXECUTE Items.s_ItemSharedCostCalculationByFather_PART @ItemSharedFatherID;
    EXECUTE Items.s_ItemSharedCostCalculationByFathers_PART @ItemSharedFatherIDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ItemSharedFatherID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;












GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedMaterialInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedMaterialInsert] @ItemSharedFatherID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemUnityID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 6) ,
  @Qtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemSharedFatherIDs Alls.tt_Guid;

      DECLARE @OrderBy BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info
	
      INSERT INTO @ItemSharedFatherIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE s.ItemSharedID = @ItemSharedFatherID; 

      SELECT @OrderBy = ISNULL(MAX(s.OrderBy), 1)
        FROM Items.t_ItemSharedMaterial AS s
        WHERE s.ItemSharedFatherID = @ItemSharedFatherID;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemSharedMaterial
          ( ItemSharedFatherID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            CreateByID ,
            CreateBy ,
            OrderBy
          )
        VALUES
          ( @ItemSharedFatherID ,
            @ItemSharedID ,
            @ItemUnityID ,
            @Qty ,
            Items.f_FormatQty(@Qty) + ' ' + Items.f_UnityItemGetName(@ItemUnityID) ,
            @Qtys ,
            @DescriptionIs ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @OrderBy
          );

    END;
	
    EXECUTE Items.s_ItemSharedCostCalculationByFather_PART @ItemSharedFatherID;
    EXECUTE Items.s_ItemSharedCostCalculationByFathers_PART @ItemSharedFatherIDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ItemSharedID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













