GO

CREATE PROCEDURE [Items].[s_ItemSharedMaterialUpdate] @ItemUnityID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 6) ,
  @Qtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

