    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ItemSharedFatherID = s.ItemSharedFatherID
        FROM Items.t_ItemSharedMaterial AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      INSERT INTO @ItemSharedFatherIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE s.ItemSharedID = @ItemSharedFatherID; 

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Items.t_ItemSharedMaterial
        SET ItemUnityID = @ItemUnityID ,
            Qty = @Qty ,
            QtyWithUnity = Items.f_FormatQty(@Qty) + ' ' + Items.f_UnityItemGetName(@ItemUnityID) ,
            Qtys = @Qtys ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    EXECUTE Items.s_ItemSharedCostCalculationByFather_PART @ItemSharedFatherID;
    EXECUTE Items.s_ItemSharedCostCalculationByFathers_PART @ItemSharedFatherIDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ItemSharedFatherID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













