/****** Object:  StoredProcedure [Items].[s_ItemSharedMaterialUpdates]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemSharedMaterialUpdates] @ItemSharedFatherID UNIQUEIDENTIFIER ,
  @Material Items.tt_ItemSharedMaterial READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemSharedFatherIDs Alls.tt_Guid;

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT INTO @ItemSharedFatherIDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE s.ItemSharedID = @ItemSharedFatherID; 

    END;

    BEGIN --Reinsert t_ItemSharedMaterial
     
      DELETE FROM Items.t_ItemSharedMaterial
        WHERE ItemSharedFatherID = @ItemSharedFatherID;

      INSERT INTO Items.t_ItemSharedMaterial
          ( ID ,
            ItemSharedFatherID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            CreateByID ,
            CreateBy ,
            OrderBy
          )
        SELECT t.ID ,
            @ItemSharedFatherID ,
            t.ItemSharedID ,
            t.ItemUnityID ,
            t.Qty ,
            Items.f_FormatQty(t.Qty) + ' ' + t2.Name ,
            t.Qtys ,
            t.DescriptionIs ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            t.OrderBy
          FROM @Material AS t
          LEFT JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
          LEFT JOIN Items.t_Unity AS t2 ON t2.ID = t1.UnityID;

    END;

	--t_ItemShared Cost
    EXECUTE Company.s_ItemSharedCostCalculationByMaterial @ItemSharedFatherID;

    EXECUTE Items.s_ItemSharedCostCalculationByFather_PART @ItemSharedFatherID;
    EXECUTE Items.s_ItemSharedCostCalculationByFathers_PART @ItemSharedFatherIDs;

    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
             
          )
        VALUES
          ( @UserID ,
            @ItemSharedFatherID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









