/****** Object:  StoredProcedure [Items].[s_ItemSharedMaterialUpdatesFull]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedMaterialUpdatesFull] @Material Items.tt_ItemSharedMaterial READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set
   
      INSERT INTO @IDs
          ( ID
          )
        SELECT DISTINCT s.ItemSharedFatherID
          FROM @Material AS s;

    END;

    BEGIN --Reinsert t_ItemSharedMaterial
     
      DELETE FROM Items.t_ItemSharedMaterial
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemSharedMaterial.ItemSharedFatherID );

      INSERT INTO Items.t_ItemSharedMaterial
          ( ID ,
            ItemSharedFatherID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            CreateByID ,
            CreateBy ,
            OrderBy
          )
        SELECT t.ID ,
            t.ItemSharedFatherID ,
            t.ItemSharedID ,
            t.ItemUnityID ,
            t.Qty ,
            Items.f_FormatQty(t.Qty) + ' ' + t2.Name ,
            t.Qtys ,
            t.DescriptionIs ,
            t.CreateByID ,
            Users.f_UserGetName(t.CreateByID) ,
            t.OrderBy
          FROM @Material AS t
          INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
          INNER JOIN Items.t_Unity AS t2 ON t2.ID = t1.UnityID;

    END;

    BEGIN --Fix Cost
		  
      UPDATE Items.t_ItemShared
        SET Purchase = Items.f_ItemSharedMaterial_GetCost(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

      WITH  o AS ( SELECT s.CurrencyID ,
                      s1.ExchangeRate ,
                      s.Purchase ,
                      s.PurchaseF ,
                      s.PurchaseD ,
                      s.PurchaseLL ,
                      s.PurchaseEuro ,
                      s.TaxRate ,
                      s.PurchaseWithTax ,
                      Calculation.Rate(s.Purchase, s.TaxRate) AS PurchaseWithTax_ ,
                      s.PurchaseWithTaxF ,
                      s.PurchaseWithTaxD ,
                      s.PurchaseWithTaxLL ,
                      s.PurchaseWithTaxEuro
                    FROM Items.t_ItemShared AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                    FROM @IDs AS ss
                                    WHERE s.ID = ss.ID )
                 )
        UPDATE o
          SET o.PurchaseF = Currencys.f_Format(o.CurrencyID, o.Purchase) ,
              o.PurchaseD = o.Purchase / o.ExchangeRate ,
              o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseWithTax = o.PurchaseWithTax_ ,
              o.PurchaseWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax_) ,
              o.PurchaseWithTaxD = o.PurchaseWithTax_ / o.ExchangeRate ,
              o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax_, o.PurchaseWithTax_ / o.ExchangeRate) ,
              o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax_, o.PurchaseWithTax_ / o.ExchangeRate);

    END;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET PurchaseTotal = Purchase * QtyCurrent ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
            PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTax = PurchaseWithTax * QtyCurrent ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            MaterialsNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                              FROM Items.t_ItemSharedMaterial AS t
                                              LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                              WHERE t.ItemSharedFatherID = t_ItemShared.ID
                                           FOR
                                             XML PATH('')
                                           )) ,
            MaterialsCounts = ( SELECT COUNT(t.ID)
                                  FROM Items.t_ItemSharedMaterial AS t
                                  WHERE t.ItemSharedFatherID = t_ItemShared.ID
                              )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

	--t_ItemShared Cost
    EXECUTE Company.s_ItemSharedCostCalculationByMaterials @IDs;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

