CREATE PROCEDURE [Items].[s_ItemSharedPriceCheckerViewInsert] @ItemSharedID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemSharedPriceCheckerView
          ( ItemSharedID )
        VALUES ( @ItemSharedID );
	  
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
