/****** Object:  StoredProcedure [Items].[s_ItemSharedRebuildElseCosts]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedRebuildElseCosts] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ExLL FLOAT = Currencys.f_CurrencyGetExchangeRateLL() ,
        @ExEuro FLOAT = Currencys.f_CurrencyGetExchangeRateEuro() ,
        @Return INT = 0;

    END;

    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    BEGIN --Rebuild

      UPDATE Items.t_ItemShared
        SET LastCost = Items.f_ItemSharedGetLastCost(ID) ,
            AverageCost = Items.f_ItemSharedGetAverageCost(ID, 0) ,
            HigherCost = Items.f_ItemSharedGetHigherCost(ID, DateCreate) ,
            LowerCost = Items.f_ItemSharedGetLowerCost(ID, DateCreate);

      WITH  o AS ( SELECT s.CurrencyID ,
                      s.LastCost ,
                      s.LastCostF ,
                      s.LastCostD ,
                      s.LastCost / s1.ExchangeRate AS LastCostD_ ,
                      s.LastCostLL ,
                      s.LastCostEuro ,
                      s.AverageCost ,
                      s.AverageCostF ,
                      s.AverageCostD ,
                      s.AverageCost / s1.ExchangeRate AS AverageCostD_ ,
                      s.AverageCostLL ,
                      s.AverageCostEuro ,
                      s.HigherCost ,
                      s.HigherCostF ,
                      s.HigherCostD ,
                      s.HigherCost / s1.ExchangeRate AS HigherCostD_ ,
                      s.HigherCostLL ,
                      s.HigherCostEuro ,
                      s.LowerCost ,
                      s.LowerCostF ,
                      s.LowerCostD ,
                      s.LowerCost / s1.ExchangeRate AS LowerCostD_ ,
                      s.LowerCostLL ,
                      s.LowerCostEuro
                    FROM Items.t_ItemShared AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                 )
        UPDATE o
          SET o.LastCostF = Currencys.f_Format(o.CurrencyID,  o.LastCost) ,
              o.LastCostD = o.LastCostD_ ,
              o.LastCostLL = o.LastCostD_ * @ExLL ,
              o.LastCostEuro = o.LastCostD_ * @ExEuro ,
              o.AverageCostF = Currencys.f_Format(o.CurrencyID, o.AverageCost) ,
              o.AverageCostD = o.AverageCostD_ ,
              o.AverageCostLL = o.AverageCostD_ * @ExLL ,
              o.AverageCostEuro = o.AverageCostD_ * @ExEuro ,
              o.HigherCostF = Currencys.f_Format(o.CurrencyID, o.HigherCost) ,
              o.HigherCostD = o.HigherCostD_ ,
              o.HigherCostLL = o.HigherCostD_ * @ExLL ,
              o.HigherCostEuro = o.HigherCostD_ * @ExEuro ,
              o.LowerCostF = Currencys.f_Format(o.CurrencyID, o.LowerCost) ,
              o.LowerCostD = o.LowerCostD_ ,
              o.LowerCostLL = o.LowerCostD_ * @ExLL ,
              o.LowerCostEuro = o.LowerCostD_ * @ExEuro;

      UPDATE Items.t_ItemShared
        SET TotalLastCost = LastCost * QtyCurrent ,
            TotalLastCostF = Currencys.f_Format(CurrencyID, LastCost * QtyCurrent) ,
            TotalLastCostD = LastCostD * QtyCurrent ,
            TotalLastCostLL = LastCostLL * QtyCurrent ,
            TotalLastCostEuro = LastCostEuro * QtyCurrent ,
            TotalAverageCost = AverageCost * QtyCurrent ,
            TotalAverageCostF = Currencys.f_Format(CurrencyID, AverageCost * QtyCurrent) ,
            TotalAverageCostD = AverageCostD * QtyCurrent ,
            TotalAverageCostLL = AverageCostLL * QtyCurrent ,
            TotalAverageCostEuro = AverageCostEuro * QtyCurrent ,
            TotalHigherCost = HigherCost * QtyCurrent ,
            TotalHigherCostF = Currencys.f_Format(CurrencyID, HigherCost * QtyCurrent) ,
            TotalHigherCostD = HigherCostD * QtyCurrent ,
            TotalHigherCostLL = HigherCostLL * QtyCurrent ,
            TotalHigherCostEuro = HigherCostEuro * QtyCurrent ,
            TotalLowerCost = LowerCost * QtyCurrent ,
            TotalLowerCostF = Currencys.f_Format(CurrencyID, LowerCost * QtyCurrent) ,
            TotalLowerCostD = LowerCostD * QtyCurrent ,
            TotalLowerCostLL = LowerCostLL * QtyCurrent ,
            TotalLowerCostEuro = LowerCostEuro * QtyCurrent;

    END;

    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Item, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN @Return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    DISABLE TRIGGER Items.tr_Item ON Items.t_Item;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Items.t_Item
        SET QtyCurrent = Items.f_ItemGetQty(ID)
        WHERE TypeIs = 0;

      UPDATE Items.t_Item
        SET QtyCurrent = 0
        WHERE TypeIs = 1;

      WITH  o AS ( SELECT s.ID ,
                      s.SharedID ,
                      s.WareHouse ,
                      s2.Name AS WareHouse_ ,
                      s.Place ,
                      s3.Name AS Place_ ,
                      s.QtyCurrent ,
                      s.QtyCurrentByUnit ,
                      s.LastStockTakeDate ,
                      s.StockTakeEvery ,
                      s.StockTakeEveryType ,
                      s.StockTakeEveryARF ,
                      s.StockTakeEveryENF ,
                      s.StockTakeEveryNotificationDate
                    FROM Items.t_Item AS s
                    INNER JOIN Company.t_WareHouse AS s2 ON s2.ID = s.WareHouseID
                    INNER JOIN Company.t_Place AS s3 ON s3.ID = s.PlaceID
                 )
        UPDATE o
          SET o.QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(o.SharedID, o.QtyCurrent) ,
              o.WareHouse = o.WareHouse_ ,
              o.Place = o.Place_ ,
              o.StockTakeEveryARF = FORMAT(o.StockTakeEvery, '0') + CASE o.StockTakeEveryType
                                                                      WHEN 2 THEN N' أيام'
                                                                      WHEN 1 THEN N' شهور'
                                                                      ELSE N' سنوات'
                                                                    END ,
              o.StockTakeEveryENF = FORMAT(o.StockTakeEvery, '0') + CASE o.StockTakeEveryType
                                                                      WHEN 2 THEN N' Days'
                                                                      WHEN 1 THEN N' Months'
                                                                      ELSE N' Years'
                                                                    END ,
              o.StockTakeEveryNotificationDate = CASE o.StockTakeEveryType
                                                   WHEN 2 THEN DATEADD(DAY, o.StockTakeEvery, o.LastStockTakeDate)
                                                   WHEN 1 THEN DATEADD(MONTH, o.StockTakeEvery, o.LastStockTakeDate)
                                                   ELSE DATEADD(YEAR, o.StockTakeEvery, o.LastStockTakeDate)
                                                 END;

      EXECUTE Items.s_ItemFixAllPurchaseAndSaleTotal;

      UPDATE Items.t_ItemShared
        SET QtyCurrent = ( SELECT COALESCE(SUM(s.QtyCurrent), 0)
                            FROM Items.t_Item AS s
                            WHERE s.SharedID = t_ItemShared.ID
                         ) ,
            Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            MainCategory = Items.f_MainCategoryGetName(MainCategoryID) ,
            SubCategory = Items.f_SubCategoryGetName(SubCategoryID) ,
            Brand = Items.f_BrandGetName(BrandID) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            PurchaseF = Currencys.f_Format(CurrencyID, Purchase) ,
            PurchaseWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax) ,
            SellCurrency = Currencys.f_CurrencyGetName(SellCurrencyID) ,
            WholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice) ,
            WholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax) ,
            DistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice) ,
            DistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax) ,
            SellF = Currencys.f_Format(SellCurrencyID, Sell) ,
            SellWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax) ,
            DiscountF = FORMAT(Discount, 'n') + ' %' ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, FinalPrice) ,
            UnityC = ( SELECT COUNT(t.ID)
                        FROM Items.t_UnityItem AS t
                        WHERE t.SharedID = t_ItemShared.ID
                     ) ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID) ,
            VendorC = ( SELECT DISTINCT COUNT(t1.AccountVendorID)
                          FROM Invoices.t_PurchasingDetail AS t
                          INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
                          WHERE t.ItemSharedID = t_ItemShared.ID
                      ) ,
            VendorNames = Alls.f_FixXML(( SELECT DISTINCT N', ' + t1.AccountVendor AS [text()]
                                            FROM Invoices.t_PurchasingDetail AS t
                                            INNER JOIN Invoices.t_Purchasing AS t1 ON t1.ID = t.PurchasingID
                                            WHERE t.ItemSharedID = t_ItemShared.ID
                                        FOR
                                          XML PATH('')
                                        )) ,
            PlacesNames = Alls.f_FixXML(( SELECT N', ' + t.Place AS [text()]
                                            FROM Items.t_Item AS t
                                            WHERE t.SharedID = t_ItemShared.ID
                                        FOR
                                          XML PATH('')
                                        )) ,
            FileStorageC = ( SELECT COUNT(t.ID)
                              FROM Company.t_FileStorageLinked AS t
                              WHERE t.SectionID = 10 AND t.OwnerID = t_ItemShared.ID
                           ) ,
            DaysLastSale = DATEDIFF(DAY, DateLastSale, GETDATE()) ,
            MaterialsNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                              FROM Items.t_ItemSharedMaterial AS t
                                              LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                              WHERE t.ItemSharedFatherID = t_ItemShared.ID
                                           FOR
                                             XML PATH('')
                                           )) ,
            MaterialsCounts = ( SELECT COUNT(t.ID)
                                  FROM Items.t_ItemSharedMaterial AS t
                                  WHERE t.ItemSharedFatherID = t_ItemShared.ID
                              ) ,
            EmployeesProfitCount = Items.f_ItemSharedGetEmployeesProfitCountLIVE(ID) ,
            EmployeesProfitNames = Items.f_ItemSharedGetEmployeesProfitNamesLIVE(ID) ,
            PriceCheckerViews = ( SELECT COUNT(s.ID)
                                    FROM Items.t_ItemSharedPriceCheckerView AS s
                                    WHERE s.ItemSharedID = t_ItemShared.ID
                                );

      UPDATE Items.t_ItemShared
        SET StatusIs = 1
        WHERE StatusIs = 0 AND MakeInactiveAfter <> 0 AND CASE MakeInactiveAfterType
                                                            WHEN 2 THEN DATEADD(DAY, MakeInactiveAfter, DateLastSale)
                                                            WHEN 1 THEN DATEADD(MONTH, MakeInactiveAfter, DateLastSale)
                                                            ELSE DATEADD(YEAR, MakeInactiveAfter, DateLastSale)
                                                          END < GETDATE();

      UPDATE Items.t_ItemShared
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent);

      WITH  o AS ( SELECT s.CurrencyID ,
                      s1.ExchangeRate ,
                      s2.ExchangeRate AS ExchangeRateSell ,
                      s.Purchase ,
                      s.PurchaseD ,
                      s.PurchaseLL ,
                      s.PurchaseEuro ,
                      s.PurchaseWithTax ,
                      s.PurchaseWithTaxD ,
                      s.PurchaseWithTaxLL ,
                      s.PurchaseWithTaxEuro ,
                      s.SellCurrencyID ,
                      s.WholesalePrice ,
                      s.WholesalePriceD ,
                      s.WholesalePriceLL ,
                      s.WholesalePriceEuro ,
                      s.WholesalePriceWithTax ,
                      s.WholesalePriceWithTaxD ,
                      s.WholesalePriceWithTaxLL ,
                      s.WholesalePriceWithTaxEuro ,
                      s.DistributionPrice ,
                      s.DistributionPriceD ,
                      s.DistributionPriceLL ,
                      s.DistributionPriceEuro ,
                      s.DistributionPriceWithTax ,
                      s.DistributionPriceWithTaxD ,
                      s.DistributionPriceWithTaxLL ,
                      s.DistributionPriceWithTaxEuro ,
                      s.Sell ,
                      s.SellD ,
                      s.SellLL ,
                      s.SellEuro ,
                      s.SellWithTax ,
                      s.SellWithTaxD ,
                      s.SellWithTaxLL ,
                      s.SellWithTaxEuro
                    FROM Items.t_ItemShared AS s
                    LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    LEFT JOIN Currencys.t_Currency AS s2 ON s2.ID = s.SellCurrencyID
                 )
        UPDATE o
          SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
              o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
              o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
              o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
              o.WholesalePriceD = o.WholesalePrice / o.ExchangeRateSell ,
              o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePrice, o.WholesalePrice / o.ExchangeRateSell) ,
              o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePrice, o.WholesalePrice / o.ExchangeRateSell) ,
              o.WholesalePriceWithTaxD = o.WholesalePriceWithTax / o.ExchangeRateSell ,
              o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRateSell) ,
              o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRateSell) ,
              o.DistributionPriceD = o.DistributionPrice / o.ExchangeRateSell ,
              o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPrice, o.DistributionPrice / o.ExchangeRateSell) ,
              o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPrice, o.DistributionPrice / o.ExchangeRateSell) ,
              o.DistributionPriceWithTaxD = o.DistributionPriceWithTax / o.ExchangeRateSell ,
              o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRateSell) ,
              o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRateSell) ,
              o.SellD = o.Sell / o.ExchangeRateSell ,
              o.SellLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.Sell, o.Sell / o.ExchangeRateSell) ,
              o.SellEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.Sell, o.Sell / o.ExchangeRateSell) ,
              o.SellWithTaxD = o.SellWithTax / o.ExchangeRateSell ,
              o.SellWithTaxLL = Currencys.f_ExchangeToLL(o.SellCurrencyID, o.SellWithTax, o.SellWithTax / o.ExchangeRateSell) ,
              o.SellWithTaxEuro = Currencys.f_ExchangeToEuro(o.SellCurrencyID, o.SellWithTax, o.SellWithTax / o.ExchangeRateSell);

      WITH  o AS ( SELECT s.Qty ,
                      s.CurrencyID ,
                      s.Price ,
                      s.PriceF ,
                      s.PriceD ,
                      s.PriceLL ,
                      s.PriceEuro ,
                      s.PriceWithTax ,
                      s.PriceWithTaxF ,
                      s.PriceWithTaxD ,
                      s.PriceWithTaxLL ,
                      s.PriceWithTaxEuro ,
                      s.DistributionPrice ,
                      s.DistributionPriceF ,
                      s.DistributionPriceD ,
                      s.DistributionPriceLL ,
                      s.DistributionPriceEuro ,
                      s.DistributionPriceWithTax ,
                      s.DistributionPriceWithTaxF ,
                      s.DistributionPriceWithTaxD ,
                      s.DistributionPriceWithTaxLL ,
                      s.DistributionPriceWithTaxEuro ,
                      s.WholesalePrice ,
                      s.WholesalePriceF ,
                      s.WholesalePriceD ,
                      s.WholesalePriceLL ,
                      s.WholesalePriceEuro ,
                      s.WholesalePriceWithTax ,
                      s.WholesalePriceWithTaxF ,
                      s.WholesalePriceWithTaxD ,
                      s.WholesalePriceWithTaxLL ,
                      s.WholesalePriceWithTaxEuro ,
                      s1.ExchangeRate ,
                      s.CurrencyIDCost ,
                      s.CurrencyCost ,
                      s.Cost ,
                      s.CostF ,
                      s.CostD ,
                      s.CostLL ,
                      s.CostEuro ,
                      s.CostWithTax ,
                      s.CostWithTaxF ,
                      s.CostWithTaxD ,
                      s.CostWithTaxLL ,
                      s.CostWithTaxEuro ,
                      s2.CurrencyID AS CurrencyIDCost_ ,
                      s2.Currency AS CurrencyCost_ ,
                      s2.Purchase AS Cost_ ,
                      s2.PurchaseD AS CostD_ ,
                      s2.PurchaseLL AS CostLL_ ,
                      s2.PurchaseEuro AS CostEuro_ ,
                      s2.PurchaseWithTax AS CostWithTax_ ,
                      s2.PurchaseWithTaxD AS CostWithTaxD_ ,
                      s2.PurchaseWithTaxLL AS CostWithTaxLL_ ,
                      s2.PurchaseWithTaxEuro AS CostWithTaxEuro_ ,
                      s.QtyCurrent ,
                      s2.QtyCurrent AS QtyCurrent_
                    FROM Items.t_UnityItem AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.SharedID
                 )
        UPDATE o
          SET o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
              o.PriceD = o.Price / o.ExchangeRate ,
              o.PriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Price, o.Price / o.ExchangeRate) ,
              o.PriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Price, o.Price / o.ExchangeRate) ,
              o.PriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.PriceWithTax) ,
              o.PriceWithTaxD = o.PriceWithTax / o.ExchangeRate ,
              o.PriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PriceWithTax, o.PriceWithTax / o.ExchangeRate) ,
              o.PriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PriceWithTax, o.PriceWithTax / o.ExchangeRate) ,
              o.DistributionPriceF = Currencys.f_Format(o.CurrencyID, o.DistributionPrice) ,
              o.DistributionPriceD = o.DistributionPrice / o.ExchangeRate ,
              o.DistributionPriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPrice, o.DistributionPrice / o.ExchangeRate) ,
              o.DistributionPriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPrice, o.DistributionPrice / o.ExchangeRate) ,
              o.DistributionPriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.DistributionPriceWithTax) ,
              o.DistributionPriceWithTaxD = o.DistributionPriceWithTax / o.ExchangeRate ,
              o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRate) ,
              o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRate) ,
              o.WholesalePriceF = Currencys.f_Format(o.CurrencyID, o.WholesalePrice) ,
              o.WholesalePriceD = o.WholesalePrice / o.ExchangeRate ,
              o.WholesalePriceLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePrice, o.WholesalePrice / o.ExchangeRate) ,
              o.WholesalePriceEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePrice, o.WholesalePrice / o.ExchangeRate) ,
              o.WholesalePriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.WholesalePriceWithTax) ,
              o.WholesalePriceWithTaxD = o.WholesalePriceWithTax / o.ExchangeRate ,
              o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRate) ,
              o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRate) ,
              o.CurrencyIDCost = o.CurrencyIDCost_ ,
              o.CurrencyCost = o.CurrencyCost_ ,
              o.Cost = o.Cost_ * o.Qty ,
              o.CostF = Currencys.f_Format(o.CurrencyIDCost_, o.Cost_ * o.Qty) ,
              o.CostD = o.CostD_ * o.Qty ,
              o.CostLL = o.CostLL_ * o.Qty ,
              o.CostEuro = o.CostEuro_ * o.Qty ,
              o.CostWithTax = o.CostWithTax_ * o.Qty ,
              o.CostWithTaxF = Currencys.f_Format(o.CurrencyIDCost_, o.CostWithTax_ * o.Qty) ,
              o.CostWithTaxD = o.CostWithTaxD_ * o.Qty ,
              o.CostWithTaxLL = o.CostWithTaxLL_ * o.Qty ,
              o.CostWithTaxEuro = o.CostWithTaxEuro_ * o.Qty ,
              o.QtyCurrent = o.QtyCurrent_ / o.Qty;

      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL);

      UPDATE Items.t_ItemShared
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            PurchaseTotal = Purchase * QtyCurrent ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
            PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTax = PurchaseWithTax * QtyCurrent ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            TotalWholesalePrice = WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
            TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            TotalDistributionPrice = DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            SellTotal = Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL);

      UPDATE Items.t_ItemSharedMaterial
        SET CreateBy = Users.f_UserGetName(CreateByID);

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Item, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

            --BEGIN --GoldenClick

            --    MERGE GoldenClick.dbo.t_ItemQtyFlexiBills AS t
            --    USING Items.t_ItemShared AS s
            --    ON s.ID = t.ID
            --    WHEN NOT MATCHED BY TARGET THEN
            --        INSERT ( ID, Barcode, Qty )
            --        VALUES ( s.ID ,
            --                 s.Barcode ,
            --                 s.QtyCurrent
            --               )
            --    WHEN MATCHED THEN
            --        UPDATE SET t.Barcode = s.Barcode ,
            --                  t.Qty = s.QtyCurrent;

            --    UPDATE  GoldenClick.dbo.t_liveVersion
            --    SET     ItemQtyFlexiBills = NEWID();

            --END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

    RETURN @Return;

  END CATCH;

END;

