/****** Object:  StoredProcedure [Items].[s_ItemSharedRebuildLastSaleDate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedRebuildLastSaleDate] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN;

  DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @t AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          DateLastSale DATETIME NOT NULL
        );

    END;

    BEGIN --Set

      INSERT INTO @t
          ( ID ,
            DateLastSale
          )
        SELECT DISTINCT s.ItemSharedID ,
            MAX(s1.DateIs) OVER ( PARTITION BY s.ItemSharedID ORDER BY s1.DateIs DESC ) AS DateLastSale
          FROM Invoices.t_SoldDetail AS s
          INNER JOIN Invoices.t_Sold AS s1 ON s1.ID = s.SoldID;
      
    END;
  
    BEGIN --Merge t_ItemShared

      MERGE Items.t_ItemShared AS t
      USING @t AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY SOURCE THEN
        UPDATE SET t.DateLastSale = DATEFROMPARTS(2000, 1, 1) ,
                    t.DaysLastSale = DATEDIFF(DAY, DATEFROMPARTS(2000, 1, 1), GETDATE())
      WHEN MATCHED THEN
        UPDATE SET t.DateLastSale = s.DateLastSale ,
                    t.DaysLastSale = DATEDIFF(DAY, s.DateLastSale, GETDATE());

    END;

    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, '00000000-0000-0000-0000-000000000000'; 

    COMMIT TRANSACTION;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN 1;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedRebuildProductionCost]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedRebuildProductionCost] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN;

  DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs AS Alls.tt_Guid;

    END;

    BEGIN --Set

      INSERT @IDs
          ( ID
          )
        SELECT DISTINCT t.ID
          FROM Items.t_ItemShared AS t
          INNER JOIN Items.t_ItemSharedMaterial AS t1 ON t1.ItemSharedID = t.ID
          INNER JOIN Items.t_ItemSharedMaterial AS t2 ON t2.ItemSharedFatherID = t1.ItemSharedID;
      
    END;
  
    --1
    EXECUTE Items.s_ItemSharedFixProductionCostPARTs @IDs;
	
    BEGIN --Set 2

      DELETE FROM @IDs;

      INSERT @IDs
          ( ID
          )
        SELECT DISTINCT t.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS t;      
    END;

	--2
    EXECUTE Items.s_ItemSharedFixProductionCostPARTs @IDs;

    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, '00000000-0000-0000-0000-000000000000'; 

    COMMIT TRANSACTION;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

    RETURN 1;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedRebuildPurchaseOrderQuantityPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedRebuildPurchaseOrderQuantityPART]
AS
BEGIN

  UPDATE Items.t_ItemShared
    SET PurchaseOrderQuantity = 0 ,
        PurchaseOrderQuantityF = N''
    WHERE PurchaseOrderQuantity <> 0;

  DECLARE @ItemsQtys TABLE
    (
      ID UNIQUEIDENTIFIER ,
      Qtys FLOAT
    );

  INSERT INTO @ItemsQtys
      ( ID ,
        Qtys
      )
    SELECT s.ItemSharedID ,
        SUM(s.Qtys)
      FROM Invoices.t_PurchaseOrderDetail AS s
      GROUP BY s.ItemSharedID;

  MERGE Items.t_ItemShared AS t
  USING @ItemsQtys AS s
  ON s.ID = t.ID
  WHEN MATCHED THEN
    UPDATE SET t.PurchaseOrderQuantity = s.Qtys ,
                t.PurchaseOrderQuantityF = Items.f_GetQtyCurrentByUnit(t.ID, s.Qtys);

  EXECUTE Items.s_ItemSharedLiveVersion;

END;


GO
