CREATE PROCEDURE [Items].[s_ItemSharedUpdate] @Name NVARCHAR(MAX) ,
  @NameInvoice NVARCHAR(MAX) ,
  @Barcode NVARCHAR(MAX) ,
  @Barcodes Items.td_Barcode READONLY ,
  @MainCategoryID UNIQUEIDENTIFIER ,
  @SubCategoryID UNIQUEIDENTIFIER ,
