  @LifeSpanDays INT ,
  @NoticeDaysBeforeExpiryDate INT ,
  @NetWeight DECIMAL(18, 2) ,
  @GrossWeight DECIMAL(18, 2) ,
  @SizeIs NVARCHAR(MAX) ,
  @ColorIs NVARCHAR(MAX) ,
  @ColorInt INT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Purchase FLOAT ,
  @CurrencyIDSell UNIQUEIDENTIFIER ,
  @Sell FLOAT ,
  @WholesalePrice FLOAT ,
  @DistributionPrice FLOAT ,
  @KeepProfitRatio BIT ,
  @StandardSalePrice BIT ,
  @Discount DECIMAL(4, 2) ,
  @TaxRate DECIMAL(4, 2) ,
  @LegalWithTax BIT ,
  @ScaleType TINYINT ,
  @PLUNumber NVARCHAR(MAX) ,
  @ScaleBarcodeWeightDividedBy INT ,
  @ScaleShelfDateData INT ,
