  @ImageThumbnail IMAGE ,
  @IsSyncImage BIT ,
  @DescriptionAR NVARCHAR(MAX) ,
  @DescriptionEN NVARCHAR(MAX) ,
  @DescriptionSearch NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @AdditionalProperty1 NVARCHAR(MAX) ,
  @AdditionalProperty2 NVARCHAR(MAX) ,
  @AdditionalProperty3 NVARCHAR(MAX) ,
  @AdditionalProperty4 NVARCHAR(MAX) ,
  @AdditionalProperty5 NVARCHAR(MAX) ,
  @AdditionalProperty6 NVARCHAR(MAX) ,
  @AdditionalProperty7 NVARCHAR(MAX) ,
  @AdditionalProperty8 NVARCHAR(MAX) ,
  @AdditionalProperty9 NVARCHAR(MAX) ,
  @AdditionalProperty10 NVARCHAR(MAX) ,
  @OpticType TINYINT ,
  @SpectacleLensesFocal NVARCHAR(MAX) ,
  @SpectacleLensesMaterial NVARCHAR(MAX) ,
  @SpectacleLensesUncoated BIT ,
  @SpectacleLensesSuperHardCoat BIT ,
  @SpectacleLensesAntiReflection BIT ,
  @SpectacleLensesUVProtection BIT ,
  @SpectacleLensesBlueFilterBlueControl BIT ,
  @SpectacleLensesPhotochromic BIT ,
  @SpectacleLensesBCPhotochromic BIT ,
  @SpectacleLensesPolariod BIT ,
  @SpectacleLensesTintedSolid NVARCHAR(MAX) ,
  @SpectacleLensesTintedGradient NVARCHAR(MAX) ,
  @SpectacleLensesTintedMirror NVARCHAR(MAX) ,
  @SpectacleLensesIndex NVARCHAR(MAX) ,
  @SpectacleLensesDiameter INT ,
  @SpectacleLensesBase INT ,
  @SpectacleLensesSphere DECIMAL(18, 2) ,
  @SpectacleLensesCylinder DECIMAL(18, 2) ,
  @SpectacleLensesAxis INT ,
  @ContactLensesBC DECIMAL(18, 2) ,
  @ContactLensesDIA DECIMAL(18, 2) ,
  @ContactLensesTransparency NVARCHAR(MAX) ,
  @ContactLensesColor NVARCHAR(MAX) ,
  @ContactLensesType NVARCHAR(MAX) ,
  @ContactLensesPeriod NVARCHAR(MAX) ,
  @ContactLensesSphere DECIMAL(18, 2) ,
  @ContactLensesCylinder DECIMAL(18, 2) ,
  @ContactLensesAxis INT ,
  @ItemSharedEmployeeProfit Items.tt_ItemSharedEmployeeProfit READONLY ,
  @EmployeesProfitCount INT ,
  @EmployeesProfitNames NVARCHAR(MAX) ,
  @EmployeesProfitReset BIT ,
  @Material Items.tt_ItemSharedMaterial READONLY ,
  @ItemSharedAdditions Items.tt_ItemSharedAdditions READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;
	
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0 ,
        @CurrencyType TINYINT ,
        @ExchangeRate FLOAT ,
        @ExchangeRateSell FLOAT ,
        @MainCategoryIDOld UNIQUEIDENTIFIER ,
        @Old_BrandID UNIQUEIDENTIFIER ,
        @InListOld BIT ,
        @QtyToReorderOld INT ,
        @WarehouseCount INT ,
        @PurchaseWithTax FLOAT ,
        @SearchIndex Alls.td_String;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @MainCategoryIDOld = s.MainCategoryID ,
          @Old_BrandID = s.BrandID ,
          @QtyToReorderOld = s.QtyToReorder ,
          @InListOld = s.InList
        FROM Items.t_ItemShared AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

      SET @CurrencyType = [Currencys].[f_CurrencyGetTypeIs](@CurrencyID);
      SET @ExchangeRate = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyID);
      SET @ExchangeRateSell = [Currencys].[f_CurrencyGetExchangeRate](@CurrencyIDSell);

      SELECT @WarehouseCount = COUNT(*)
        FROM Company.t_WareHouse AS s;

      SET @PurchaseWithTax = Calculation.Rate(@Purchase, @TaxRate);
    
      INSERT INTO @SearchIndex
          ( Name )
        VALUES ( @Name );

      INSERT INTO @SearchIndex
          ( Name
          )
        SELECT s.Barcode
          FROM @Barcodes AS s;

    END;

    BEGIN --Update item shared

      UPDATE Items.t_ItemShared
        SET Name = @Name ,
            NameInvoice = @NameInvoice ,
            Barcode = @Barcode ,
            MainCategoryID = @MainCategoryID ,
            MainCategory = Items.f_MainCategoryGetName(@MainCategoryID) ,
            SubCategoryID = @SubCategoryID ,
            SubCategory = Items.f_SubCategoryGetName(@SubCategoryID) ,
            BrandID = @BrandID ,
            Brand = Items.f_BrandGetName(@BrandID) ,
            InList = @InList ,
            QtyToReorder = @QtyToReorder ,
            QtySalesAlert = @QtySalesAlert ,
            IsExpiryDate = @IsExpiryDate ,
            LifeSpanDays = @LifeSpanDays ,
            NoticeDaysBeforeExpiryDate = @NoticeDaysBeforeExpiryDate ,
            NetWeight = @NetWeight ,
            GrossWeight = @GrossWeight ,
            SizeIs = @SizeIs ,
            ColorIs = @ColorIs ,
            ColorInt = @ColorInt ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            Purchase = @Purchase ,
            PurchaseF = Currencys.f_Format(@CurrencyID, @Purchase) ,
            PurchaseD = @Purchase / @ExchangeRate ,
            PurchaseLL = Currencys.f_ExchangeToLL(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            PurchaseEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @Purchase, @Purchase / @ExchangeRate) ,
            PurchaseWithTax = @PurchaseWithTax ,
            PurchaseWithTaxF = Currencys.f_Format(@CurrencyID, @PurchaseWithTax) ,
            PurchaseWithTaxD = @PurchaseWithTax / @ExchangeRate ,
            PurchaseWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyID, @PurchaseWithTax, @PurchaseWithTax / @ExchangeRate) ,
            PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @PurchaseWithTax, @PurchaseWithTax / @ExchangeRate) ,
            SellCurrencyID = @CurrencyIDSell ,
            SellCurrency = Currencys.f_CurrencyGetName(@CurrencyIDSell) ,
            WholesalePrice = @WholesalePrice ,
            WholesalePriceF = Currencys.f_Format(@CurrencyIDSell, @WholesalePrice) ,
            WholesalePriceD = @WholesalePrice / @ExchangeRateSell ,
            WholesalePriceLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @WholesalePrice, @WholesalePrice / @ExchangeRateSell) ,
            WholesalePriceEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @WholesalePrice, @WholesalePrice / @ExchangeRateSell) ,
            WholesalePriceWithTax = Calculation.Rate(@WholesalePrice, @TaxRate) ,
            DistributionPrice = @DistributionPrice ,
            DistributionPriceF = Currencys.f_Format(@CurrencyIDSell, @DistributionPrice) ,
            DistributionPriceD = @DistributionPrice / @ExchangeRateSell ,
            DistributionPriceLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @DistributionPrice, @DistributionPrice / @ExchangeRateSell) ,
            DistributionPriceEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @DistributionPrice, @DistributionPrice / @ExchangeRateSell) ,
            DistributionPriceWithTax = Calculation.Rate(@DistributionPrice, @TaxRate) ,
            Sell = @Sell ,
            SellF = Currencys.f_Format(@CurrencyIDSell, @Sell) ,
            SellD = @Sell / @ExchangeRateSell ,
            SellLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @Sell, @Sell / @ExchangeRateSell) ,
            SellEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @Sell, @Sell / @ExchangeRateSell) ,
            SellWithTax = Calculation.Rate(@Sell, @TaxRate) ,
            KeepProfitRatio = @KeepProfitRatio ,
            StandardSalePrice = @StandardSalePrice ,
            Discount = @Discount ,
            TaxRate = @TaxRate ,
            LegalWithTax = @LegalWithTax ,
            ScaleType = @ScaleType ,
            PLUNumber = @PLUNumber ,
            ScaleBarcodeWeightDividedBy = @ScaleBarcodeWeightDividedBy ,
			ScaleShelfDateData = @ScaleShelfDateData ,
            TypeIs = @TypeIs ,
            ReplenishmentSystem = @ReplenishmentSystem ,
            Rentable = @Rentable ,
            HasAWarranty = @HasAWarranty ,
            PointsAreCalculated = @PointsAreCalculated ,
            AlfaMtcType = @AlfaMtcType ,
            AlfaMtcShowOnSaleBoard = @AlfaMtcShowOnSaleBoard ,
            ImageIs = @ImageIs ,
            ImageThumbnail = @ImageThumbnail ,
            ImageThumbnailFixed = 1 ,
            DescriptionAR = @DescriptionAR ,
            DescriptionEN = @DescriptionEN ,
            DescriptionSearch = @DescriptionSearch ,
            DescriptionIs = @DescriptionIs ,
            AdditionalProperty1 = @AdditionalProperty1 ,
            AdditionalProperty2 = @AdditionalProperty2 ,
            AdditionalProperty3 = @AdditionalProperty3 ,
            AdditionalProperty4 = @AdditionalProperty4 ,
            AdditionalProperty5 = @AdditionalProperty5 ,
            AdditionalProperty6 = @AdditionalProperty6 ,
            AdditionalProperty7 = @AdditionalProperty7 ,
            AdditionalProperty8 = @AdditionalProperty8 ,
            AdditionalProperty9 = @AdditionalProperty9 ,
            AdditionalProperty10 = @AdditionalProperty10 ,
            OpticType = @OpticType ,
            SpectacleLensesFocal = @SpectacleLensesFocal ,
            SpectacleLensesMaterial = @SpectacleLensesMaterial ,
            SpectacleLensesUncoated = @SpectacleLensesUncoated ,
            SpectacleLensesSuperHardCoat = @SpectacleLensesSuperHardCoat ,
            SpectacleLensesAntiReflection = @SpectacleLensesAntiReflection ,
            SpectacleLensesUVProtection = @SpectacleLensesUVProtection ,
            SpectacleLensesBlueFilterBlueControl = @SpectacleLensesBlueFilterBlueControl ,
            SpectacleLensesPhotochromic = @SpectacleLensesPhotochromic ,
            SpectacleLensesBCPhotochromic = @SpectacleLensesBCPhotochromic ,
            SpectacleLensesPolariod = @SpectacleLensesPolariod ,
            SpectacleLensesTintedSolid = @SpectacleLensesTintedSolid ,
            SpectacleLensesTintedGradient = @SpectacleLensesTintedGradient ,
            SpectacleLensesTintedMirror = @SpectacleLensesTintedMirror ,
            SpectacleLensesIndex = @SpectacleLensesIndex ,
            SpectacleLensesDiameter = @SpectacleLensesDiameter ,
            SpectacleLensesBase = @SpectacleLensesBase ,
            SpectacleLensesSphere = @SpectacleLensesSphere ,
            SpectacleLensesCylinder = @SpectacleLensesCylinder ,
            SpectacleLensesAxis = @SpectacleLensesAxis ,
            ContactLensesBC = @ContactLensesBC ,
            ContactLensesDIA = @ContactLensesDIA ,
            ContactLensesTransparency = @ContactLensesTransparency ,
            ContactLensesColor = @ContactLensesColor ,
            ContactLensesType = @ContactLensesType ,
            ContactLensesPeriod = @ContactLensesPeriod ,
            ContactLensesSphere = @ContactLensesSphere ,
            ContactLensesCylinder = @ContactLensesCylinder ,
            ContactLensesAxis = @ContactLensesAxis ,
            EmployeesProfitCount = IIF(@EmployeesProfitReset = 1, @EmployeesProfitCount, EmployeesProfitCount) ,
            EmployeesProfitNames = IIF(@EmployeesProfitReset = 1, @EmployeesProfitNames, EmployeesProfitNames) ,
            SearchIndex = Alls.f_ToSearchIndex(@SearchIndex) ,
			LastModifiedDate = GETDATE()
        WHERE ID = @ID;
  
      UPDATE Items.t_Item
        SET TypeIs = @TypeIs
        WHERE SharedID = @ID;

    END;

    BEGIN --Update Base Unit

      UPDATE Items.t_UnityItem
        SET CurrencyID = @CurrencyIDSell ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyIDSell) ,
            Price = @Sell ,
            PriceF = Currencys.f_Format(@CurrencyIDSell, @Sell) ,
            PriceD = @Sell / @ExchangeRateSell ,
            PriceLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @Sell, @Sell / @ExchangeRateSell) ,
            PriceEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @Sell, @Sell / @ExchangeRateSell) ,
            WholesalePrice = @WholesalePrice ,
            WholesalePriceF = Currencys.f_Format(@CurrencyIDSell, @WholesalePrice) ,
            WholesalePriceD = @WholesalePrice / @ExchangeRateSell ,
            WholesalePriceLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @WholesalePrice, @WholesalePrice / @ExchangeRateSell) ,
            WholesalePriceEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @WholesalePrice, @WholesalePrice / @ExchangeRateSell) ,
            DistributionPrice = @DistributionPrice ,
            DistributionPriceF = Currencys.f_Format(@CurrencyIDSell, @DistributionPrice) ,
            DistributionPriceD = @DistributionPrice / @ExchangeRateSell ,
            DistributionPriceLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, @DistributionPrice, @DistributionPrice / @ExchangeRateSell) ,
            DistributionPriceEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, @DistributionPrice, @DistributionPrice / @ExchangeRateSell)
        WHERE SharedID = @ID AND PrimaryIs = 1 AND Qty = 1;
   
      UPDATE Items.t_UnityItem
        SET PriceWithTax = Calculation.Rate(Price, @TaxRate) ,
            DistributionPriceWithTax = Calculation.Rate(DistributionPrice, @TaxRate) ,
            WholesalePriceWithTax = Calculation.Rate(WholesalePrice, @TaxRate) ,
            ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE SharedID = @ID;

      WITH  o AS ( SELECT s.CurrencyID ,
                      s.PriceWithTax ,
                      s.PriceWithTaxF ,
                      s.PriceWithTaxD ,
                      s.PriceWithTaxLL ,
                      s.PriceWithTaxEuro ,
                      s.DistributionPriceWithTax ,
                      s.DistributionPriceWithTaxF ,
                      s.DistributionPriceWithTaxD ,
                      s.DistributionPriceWithTaxLL ,
                      s.DistributionPriceWithTaxEuro ,
                      s.WholesalePriceWithTax ,
                      s.WholesalePriceWithTaxF ,
                      s.WholesalePriceWithTaxD ,
                      s.WholesalePriceWithTaxLL ,
                      s.WholesalePriceWithTaxEuro ,
                      s1.ExchangeRate
                    FROM Items.t_UnityItem AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.SharedID
                    WHERE s.SharedID = @ID
                 )
        UPDATE o
          SET o.PriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.PriceWithTax) ,
              o.PriceWithTaxD = o.PriceWithTax / o.ExchangeRate ,
              o.PriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PriceWithTax, o.PriceWithTax / o.ExchangeRate) ,
              o.PriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PriceWithTax, o.PriceWithTax / o.ExchangeRate) ,
              o.DistributionPriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.DistributionPriceWithTax) ,
              o.DistributionPriceWithTaxD = o.DistributionPriceWithTax / o.ExchangeRate ,
              o.DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRate) ,
              o.DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.DistributionPriceWithTax, o.DistributionPriceWithTax / o.ExchangeRate) ,
              o.WholesalePriceWithTaxF = Currencys.f_Format(o.CurrencyID, o.WholesalePriceWithTax) ,
              o.WholesalePriceWithTaxD = o.WholesalePriceWithTax / o.ExchangeRate ,
              o.WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRate) ,
              o.WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.WholesalePriceWithTax, o.WholesalePriceWithTax / o.ExchangeRate);
			
      UPDATE Items.t_ItemShared
        SET TotalWholesalePrice = @WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(@CurrencyIDSell, @WholesalePrice * QtyCurrent) ,
            WholesalePriceWithTaxF = Currencys.f_Format(@CurrencyIDSell, WholesalePriceWithTax) ,
            WholesalePriceWithTaxD = WholesalePriceWithTax / @ExchangeRateSell ,
            WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRateSell) ,
            WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRateSell) ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(@CurrencyIDSell, WholesalePriceWithTax * QtyCurrent) ,
            TotalDistributionPrice = @DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(@CurrencyIDSell, @DistributionPrice * QtyCurrent) ,
            DistributionPriceWithTaxF = Currencys.f_Format(@CurrencyIDSell, DistributionPriceWithTax) ,
            DistributionPriceWithTaxD = DistributionPriceWithTax / @ExchangeRateSell ,
            DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRateSell) ,
            DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRateSell) ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(@CurrencyIDSell, DistributionPriceWithTax * QtyCurrent) ,
            SellTotal = @Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(@CurrencyIDSell, @Sell * QtyCurrent) ,
            SellWithTaxF = Currencys.f_Format(@CurrencyIDSell, SellWithTax) ,
            SellWithTaxD = SellWithTax / @ExchangeRateSell ,
            SellWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyIDSell, SellWithTax, SellWithTax / @ExchangeRateSell) ,
            SellWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyIDSell, SellWithTax, SellWithTax / @ExchangeRateSell) ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(@CurrencyIDSell, SellWithTax * QtyCurrent)
        WHERE ID = @ID;

      UPDATE Items.t_ItemShared
        SET TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent
        WHERE ID = @ID;

    END;

    IF @QtyToReorder <> @QtyToReorderOld
    BEGIN --Update items

      SET @QtyToReorder = @QtyToReorder / @WarehouseCount;

      UPDATE Items.t_Item
        SET QtyToReorder = @QtyToReorder
        WHERE SharedID = @ID;

    END;

    BEGIN --Reinsert barcodes

      SET @return = -3;

      DECLARE @OldBarcodes AS TABLE
        (
          SharedID UNIQUEIDENTIFIER ,
          BarCode NVARCHAR(450) ,
          UnitItemID UNIQUEIDENTIFIER
        );

      INSERT INTO @OldBarcodes
          ( SharedID ,
            BarCode ,
            UnitItemID
          )
        SELECT SharedID ,
            BarCode ,
            UnitItemID
          FROM Items.t_ItemSharedBarCode AS s
          WHERE s.SharedID = @ID AND s.UnitItemID <> Alls.f_GetEmptyGuid();

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ID;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        SELECT @ID ,
            t.Barcode ,
            Alls.f_ToBigint(t.Barcode) ,
            t.TypeIs
          FROM @Barcodes AS t;

      MERGE Items.t_ItemSharedBarCode AS t
      USING @OldBarcodes AS s
      ON t.SharedID = s.SharedID AND t.BarCode = s.BarCode
      WHEN MATCHED THEN
        UPDATE SET t.UnitItemID = s.UnitItemID;

    END;

    BEGIN --Insert t_ItemSharedMaterial
	
      DELETE FROM Items.t_ItemSharedMaterial
        WHERE ItemSharedFatherID = @ID;

      INSERT INTO Items.t_ItemSharedMaterial
          ( ID ,
            ItemSharedFatherID ,
            ItemSharedID ,
            ItemUnityID ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            DescriptionIs ,
            CreateByID ,
            CreateBy ,
            OrderBy
          )
        SELECT t.ID ,
            @ID ,
            t.ItemSharedID ,
            t.ItemUnityID ,
            t.Qty ,
            Items.f_FormatQty(t.Qty) + ' ' + t2.Name ,
            t.Qtys ,
            t.DescriptionIs ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            t.OrderBy
          FROM @Material AS t
          INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
          INNER JOIN Items.t_Unity AS t2 ON t2.ID = t1.UnityID;

    END;
	
	--t_ItemShared Cost
    EXECUTE Company.s_ItemSharedCostCalculationByMaterial @ID;
	
    IF @EmployeesProfitReset = 1
    BEGIN
	                                 
	-- Insert t_ItemSharedEmployeeProfit
      EXECUTE Items.s_ItemSharedEmployeeProfitMergePART @ID, @ItemSharedEmployeeProfit;

    END;

    BEGIN --Delete t_ItemSharedAdditions

      DECLARE @IDsAdditions Alls.tt_IDAndEvent;

      INSERT INTO @IDsAdditions
          ( ID ,
            EventIs
          )
        SELECT ID ,
            N''
          FROM Items.t_ItemSharedAdditions
          WHERE ItemSharedID = @ID;

      DELETE FROM Items.t_ItemSharedAdditions
        WHERE ItemSharedID = @ID;

      EXECUTE Alls.s_FireStoreRowsForDeleteInsertsPART @IDsAdditions, 0, 'itemSharedAdditions'; 

    END;
  
    BEGIN --Insert t_ItemSharedAdditions

      INSERT INTO Items.t_ItemSharedAdditions
          ( ID ,
            ItemSharedID ,
            AdditionsOnItemsID ,
            OrderBy
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.AdditionsOnItemsID ,
            s.OrderBy
          FROM @ItemSharedAdditions AS s;

    END;	

    EXECUTE Items.s_ItemSharedAdditionsReorderPART @ID;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            PurchaseTotal = Purchase * QtyCurrent ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
            PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTax = PurchaseWithTax * QtyCurrent ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL) ,
            MaterialsNames = Alls.f_FixXML(( SELECT N', ' + t1.Name AS [text()]
                                              FROM Items.t_ItemSharedMaterial AS t
                                              LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                              WHERE t.ItemSharedFatherID = t_ItemShared.ID
                                           FOR
                                             XML PATH('')
                                           )) ,
            MaterialsCounts = ( SELECT COUNT(t.ID)
                                  FROM Items.t_ItemSharedMaterial AS t
                                  WHERE t.ItemSharedFatherID = t_ItemShared.ID
                              )
        WHERE ID = @ID;

      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE SharedID = @ID;

      EXECUTE Items.s_ItemFixPurchaseAndSaleTotal @ID;

    END;

    IF @MainCategoryIDOld <> @MainCategoryID
    BEGIN --Rebuilding statistics t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemC += 1 ,
            ItemInListCount = ( SELECT COUNT(*) AS Total
                                  FROM Items.t_ItemShared AS t
                                  WHERE t.MainCategoryID = t_MainCategory.ID AND t.InList = 1
                              )
        WHERE ID = @MainCategoryID;

      UPDATE Items.t_MainCategory
        SET ItemC -= 1 ,
            ItemInListCount = ( SELECT COUNT(*) AS Total
                                  FROM Items.t_ItemShared AS t
                                  WHERE t.MainCategoryID = t_MainCategory.ID AND t.InList = 1
                              )
        WHERE ID = @MainCategoryIDOld;

    END;

    IF @InListOld <> @InList
    BEGIN --Rebuilding statistics t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemInListCount = ( SELECT COUNT(*) AS Total
                                  FROM Items.t_ItemShared AS t
                                  WHERE t.MainCategoryID = t_MainCategory.ID AND t.InList = 1
                              )
        WHERE ID IN ( @MainCategoryID, @MainCategoryIDOld );


    END;

    IF @Old_BrandID <> @BrandID
    BEGIN

      EXECUTE Items.s_Brands_ItemsCount_AddPART @Old_BrandID, -1;	
      EXECUTE Items.s_Brands_ItemsCount_AddPART @BrandID, 1;	

    END;

    SET @return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID;  
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;















GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateAddBarcode]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdateAddBarcode] @ID UNIQUEIDENTIFIER ,
  @Barcode NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
  
    SET ANSI_WARNINGS OFF;
	
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0 ,
        @SearchIndex Alls.td_String;

    END;

    BEGIN --Set info
    
      INSERT INTO @SearchIndex
          ( Name )
        VALUES ( @Barcode );

      INSERT INTO @SearchIndex
          ( Name
          )
        SELECT s.BarCode
          FROM Items.t_ItemSharedBarCode AS s
          WHERE s.SharedID = @ID;

    END;

    BEGIN --Insert t_ItemSharedBarCode

      SET @return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        VALUES
          ( @ID ,
            @Barcode ,
            Alls.f_ToBigint(@Barcode) ,
            1
          );

    END;

    BEGIN --Update t_ItemShared

      UPDATE Items.t_ItemShared
        SET Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            SearchIndex = Alls.f_ToSearchIndex(@SearchIndex) ,
			LastModifiedDate = GETDATE()
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
