        UPDATE Invoices.t_SoldReturnDeletedDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_SoldReturnDetail
    
        UPDATE Invoices.t_SoldReturnDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_SoldUnsavedDetail
    
        UPDATE Invoices.t_SoldUnsavedDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_StockAdjustmentDetail
    
        UPDATE Items.t_StockAdjustmentDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_StockTakeDetail
    
        UPDATE Items.t_StockTakeDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_StockTakeUnsavedDetail
    
        UPDATE Items.t_StockTakeUnsavedDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_TransferAwaitedDetail
    
        UPDATE Invoices.t_TransferAwaitedDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

      BEGIN --t_TransferDetail
    
        UPDATE Invoices.t_TransferDetail
          SET ItemSharedID = @ToItemSharedID
          WHERE ItemSharedID = @FromItemSharedID; 

      END;

    END;

    BEGIN --Rebuild statistics

      UPDATE Items.t_Item
        SET QtyCurrent = Items.f_ItemGetQty(ID)
        WHERE TypeIs = 0 AND SharedID IN ( @FromItemSharedID, @ToItemSharedID );

      UPDATE Items.t_Item
        SET QtyCurrent = 0
        WHERE TypeIs = 1 AND SharedID IN ( @FromItemSharedID, @ToItemSharedID );

      UPDATE Items.t_Item
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent)
        WHERE SharedID IN ( @FromItemSharedID, @ToItemSharedID );

      UPDATE Items.t_ItemShared
        SET QtyCurrent = ( SELECT COALESCE(SUM(s.QtyCurrent), 0)
                            FROM Items.t_Item AS s
                            WHERE s.SharedID = t_ItemShared.ID
                         ) ,
            LastModifiedDate = GETDATE()
        WHERE ID IN ( @FromItemSharedID, @ToItemSharedID );

      WITH  o AS ( SELECT s.Qty ,
                      s.QtyCurrent ,
                      s1.QtyCurrent AS QtyCurrent_
                    FROM Items.t_UnityItem AS s
                    INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
                    WHERE s.SharedID IN ( @FromItemSharedID, @ToItemSharedID )
                 )
        UPDATE o
          SET o.QtyCurrent = o.QtyCurrent_ / o.Qty;

      UPDATE Items.t_ItemShared
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            LastModifiedDate = GETDATE()
        WHERE ID IN ( @FromItemSharedID, @ToItemSharedID );

      WITH  o AS ( SELECT s.ID ,
                      s.SharedID ,
                      s.QtyCurrent ,
                      s.PurchaseTotal ,
                      s.PurchaseTotalF ,
                      s.PurchaseTotalD ,
                      s.PurchaseTotalLL ,
                      s.PurchaseTotalEuro ,
                      s.PurchaseTotalWithTax ,
                      s.PurchaseTotalWithTaxF ,
                      s.PurchaseTotalWithTaxD ,
                      s.PurchaseTotalWithTaxLL ,
                      s.PurchaseTotalWithTaxEuro ,
                      s.SellTotal ,
                      s.SellTotalF ,
                      s.SellTotalD ,
                      s.SellTotalLL ,
                      s.SellTotalEuro ,
                      s.SellTotalWithTax ,
                      s.SellTotalWithTaxF ,
                      s.SellTotalWithTaxD ,
                      s.SellTotalWithTaxLL ,
                      s.SellTotalWithTaxEuro ,
                      s.StockTakeEvery ,
                      s.StockTakeEveryType ,
                      s.StockTakeEveryARF ,
                      s.StockTakeEveryENF ,
                      s.StockTakeEveryNotificationDate ,
                      s1.CurrencyID ,
                      s1.Purchase ,
                      s1.PurchaseD ,
                      s1.PurchaseLL ,
                      s1.PurchaseEuro ,
                      s1.PurchaseWithTax ,
                      s1.PurchaseWithTaxD ,
                      s1.PurchaseWithTaxLL ,
                      s1.PurchaseWithTaxEuro ,
                      s1.SellCurrencyID ,
                      s1.Sell ,
                      s1.SellD ,
                      s1.SellLL ,
                      s1.SellEuro ,
                      s1.SellWithTax ,
                      s1.SellWithTaxD ,
                      s1.SellWithTaxLL ,
                      s1.SellWithTaxEuro
                    FROM Items.t_Item AS s
                    INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
                    WHERE s.SharedID IN ( @FromItemSharedID, @ToItemSharedID )
                 )
        UPDATE o
          SET o.PurchaseTotal = o.Purchase * o.QtyCurrent ,
              o.PurchaseTotalF = Currencys.f_Format(o.CurrencyID, o.Purchase * o.QtyCurrent) ,
              o.PurchaseTotalD = o.PurchaseD * o.QtyCurrent ,
              o.PurchaseTotalLL = o.PurchaseLL * o.QtyCurrent ,
              o.PurchaseTotalEuro = o.PurchaseEuro * o.QtyCurrent ,
              o.PurchaseTotalWithTax = o.PurchaseWithTax * o.QtyCurrent ,
              o.PurchaseTotalWithTaxF = Currencys.f_Format(o.CurrencyID, o.PurchaseWithTax * o.QtyCurrent) ,
              o.PurchaseTotalWithTaxD = o.PurchaseWithTaxD * o.QtyCurrent ,
              o.PurchaseTotalWithTaxLL = o.PurchaseWithTaxLL * o.QtyCurrent ,
              o.PurchaseTotalWithTaxEuro = o.PurchaseWithTaxEuro * o.QtyCurrent ,
              o.SellTotal = o.Sell * o.QtyCurrent ,
              o.SellTotalF = Currencys.f_Format(o.SellCurrencyID, o.Sell * o.QtyCurrent) ,
              o.SellTotalD = o.SellD * o.QtyCurrent ,
              o.SellTotalLL = o.SellLL * o.QtyCurrent ,
              o.SellTotalEuro = o.SellEuro * o.QtyCurrent ,
              o.SellTotalWithTax = o.SellWithTax * o.QtyCurrent ,
              o.SellTotalWithTaxF = Currencys.f_Format(o.SellCurrencyID, o.SellWithTax * o.QtyCurrent) ,
              o.SellTotalWithTaxD = o.SellWithTaxD * o.QtyCurrent ,
              o.SellTotalWithTaxLL = o.SellWithTaxLL * o.QtyCurrent ,
              o.SellTotalWithTaxEuro = o.SellWithTaxEuro * o.QtyCurrent;

    END;

    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @FromItemSharedID;  
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ToItemSharedID;  
		
    COMMIT TRANSACTION;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;
    ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDeleteDetail ON Items.t_DeliveryPermissionDeleteDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    ENABLE TRIGGER Customers.tr_FrameJobOrderDetail ON Customers.t_FrameJobOrderDetail;
    ENABLE TRIGGER Customers.tr_FrameJobOrderHistoryDetail ON Customers.t_FrameJobOrderHistoryDetail;
    ENABLE TRIGGER Items.tr_ItemExpirationDate ON Items.t_ItemExpirationDate;
    ENABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
    ENABLE TRIGGER Items.tr_ItemProductionMaterial ON Items.t_ItemProductionMaterial;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    ENABLE TRIGGER Invoices.tr_PurchasingReturnDetail ON Invoices.t_PurchasingReturnDetail;
    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;
    ENABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;
    ENABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    ENABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
    ENABLE TRIGGER Items.tr_Item ON Items.t_Item;
    ENABLE TRIGGER Items.tr_BeginningInventoryQuantityDetail ON Items.t_BeginningInventoryQuantityDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDeleteDetail ON Items.t_DeliveryPermissionDeleteDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionDetail ON Items.t_DeliveryPermissionDetail;
    ENABLE TRIGGER Items.tr_DeliveryPermissionHistoryDetail ON Items.t_DeliveryPermissionHistoryDetail;
    ENABLE TRIGGER Customers.tr_FrameJobOrderDetail ON Customers.t_FrameJobOrderDetail;
    ENABLE TRIGGER Customers.tr_FrameJobOrderHistoryDetail ON Customers.t_FrameJobOrderHistoryDetail;
    ENABLE TRIGGER Items.tr_ItemExpirationDate ON Items.t_ItemExpirationDate;
    ENABLE TRIGGER Items.tr_ItemProduction ON Items.t_ItemProduction;
    ENABLE TRIGGER Items.tr_ItemProductionMaterial ON Items.t_ItemProductionMaterial;
    ENABLE TRIGGER Invoices.tr_PurchasingDetail ON Invoices.t_PurchasingDetail;
    ENABLE TRIGGER Invoices.tr_PurchasingReturnDetail ON Invoices.t_PurchasingReturnDetail;
    ENABLE TRIGGER Invoices.tr_SoldDetail ON Invoices.t_SoldDetail;
    ENABLE TRIGGER Invoices.tr_SoldReturnDetail ON Invoices.t_SoldReturnDetail;
    ENABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;
    ENABLE TRIGGER Invoices.tr_TransferAwaitedDetail ON Invoices.t_TransferAwaitedDetail;
    ENABLE TRIGGER Invoices.tr_TransferDetail ON Invoices.t_TransferDetail;

    SELECT @Return;

  END CATCH;

END;



