/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateCost]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdateCost] @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @Detail Items.[tt_ItemCost] READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs Alls.tt_Guid ,
        @Return INT = 0;

    END;

    BEGIN --Set Info
	    
      INSERT INTO @IDs
          ( ID )
        SELECT s.ID
          FROM @Detail AS s;

    END;

    BEGIN --Update 

      MERGE Items.t_ItemShared AS t
      USING @Detail AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Purchase = s.Purchase ,
                    t.PurchaseF = Currencys.f_Format(t.CurrencyID, s.Purchase) ,
                    t.PurchaseTotal = t.QtyCurrent * s.Purchase ,
                    t.PurchaseTotalF = Currencys.f_Format(t.CurrencyID, t.QtyCurrent * s.Purchase) ,
                    t.PurchaseWithTax = Calculation.Rate(s.Purchase, t.TaxRate) ,
                    t.PurchaseWithTaxF = Currencys.f_Format(t.CurrencyID, Calculation.Rate(s.Purchase, t.TaxRate)) ,
                    t.PurchaseTotalWithTax = t.QtyCurrent * Calculation.Rate(s.Purchase, t.TaxRate) ,
                    t.PurchaseTotalWithTaxF = Currencys.f_Format(t.CurrencyID, t.QtyCurrent * Calculation.Rate(s.Purchase, t.TaxRate));

      WITH  o AS ( SELECT s.CurrencyID ,
                      s.Purchase ,
                      s.PurchaseD ,
                      s.PurchaseLL ,
                      s.PurchaseEuro ,
                      s.PurchaseWithTax ,
                      s.PurchaseWithTaxD ,
                      s.PurchaseWithTaxLL ,
                      s.PurchaseWithTaxEuro ,
                      s1.ExchangeRate
                    FROM Items.t_ItemShared AS s
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    WHERE EXISTS ( SELECT TOP ( 1 ) s2.ID
                                    FROM @Detail AS s2
                                    WHERE s2.ID = s.ID )
                 )
        UPDATE o
          SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
              o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
              o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
              o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate);

      UPDATE Items.t_ItemShared
        SET PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
			LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Detail AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;
		
	BEGIN--t_ItemShared Cost
	  
    EXECUTE Company.s_ItemSharedCostCalculationByMaterials @IDs;

	END
	
    EXECUTE Items.s_ItemSharedKeepProfitRatioFixPART @IDs;
	
    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @IDs;
	
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Detail AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateCostByRate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdateCostByRate] @IncreaseRate DECIMAL(5, 2) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update 

      UPDATE Items.t_ItemShared
        SET Purchase = Calculation.Rate(PurchaseWithTax, @IncreaseRate) - ( ( Calculation.Rate(PurchaseWithTax, @IncreaseRate) / ( 100.0 + TaxRate ) ) * TaxRate ) ,
            PurchaseWithTax = Calculation.Rate(PurchaseWithTax, @IncreaseRate)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

      WITH  o AS ( SELECT s.CurrencyID ,
                      s.Purchase ,
                      s.PurchaseD ,
                      s.PurchaseLL ,
                      s.PurchaseEuro ,
                      s.PurchaseWithTax ,
                      s.PurchaseWithTaxD ,
                      s.PurchaseWithTaxLL ,
                      s.PurchaseWithTaxEuro ,
                      s1.ExchangeRate
                    FROM Items.t_ItemShared AS s
                    LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                    WHERE EXISTS ( SELECT TOP ( 1 ) s2.ID
                                    FROM @IDs AS s2
                                    WHERE s2.ID = s.ID )
                 )
        UPDATE o
          SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
              o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
              o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
              o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate);

      UPDATE Items.t_ItemShared
        SET PurchaseF = Currencys.f_Format(CurrencyID, Purchase) ,
            PurchaseTotal = QtyCurrent * Purchase ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, QtyCurrent * Purchase) ,
            PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax) ,
            PurchaseTotalWithTax = QtyCurrent * PurchaseWithTax ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, QtyCurrent * PurchaseWithTax) ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

    IF EXISTS ( SELECT TOP ( 1 ) --t_ItemSharedMaterial
                    s.ID
                  FROM Items.t_ItemSharedMaterial AS s
                  WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                  FROM @IDs AS ss
                                  WHERE ss.ID = s.ItemSharedID ) )
    BEGIN
		  
      DECLARE @MaterialItemSharedFatherIDs AS Alls.tt_Guid;

      INSERT @MaterialItemSharedFatherIDs
          ( ID
          )
        SELECT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                          FROM @IDs AS ss
                          WHERE ss.ID = s.ItemSharedID );

      EXECUTE Items.s_ItemSharedFixProductionCostPARTs @MaterialItemSharedFatherIDs;

    END;

    EXECUTE Items.s_ItemSharedKeepProfitRatioFixPART @IDs;
		
    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @IDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            REPLACE(@Event, '{0}', s1.Name) ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s
          LEFT JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ID;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
