/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateMakeInactiveAfter]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdateMakeInactiveAfter]
    @MakeInactiveAfter INT,
    @MakeInactiveAfterType TINYINT,
    @UserID UNIQUEIDENTIFIER,
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
    BEGIN TRY

    SET ANSI_WARNINGS OFF;

        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

        BEGIN --Update 

            SET @Return = 0;

            UPDATE Items.t_ItemShared
            SET MakeInactiveAfter = @MakeInactiveAfter,
                MakeInactiveAfterType = @MakeInactiveAfterType
            WHERE EXISTS
            (
                SELECT TOP (1) s.ID FROM @IDAndEvent AS s WHERE s.ID = t_ItemShared.ID
            );

            UPDATE Items.t_ItemShared
            SET StatusIs = 1
            WHERE EXISTS
            (
                SELECT TOP (1) s.ID FROM @IDAndEvent AS s WHERE s.ID = t_ItemShared.ID
            )
                  AND StatusIs = 0
                  AND MakeInactiveAfter <> 0
                  AND CASE MakeInactiveAfterType
                          WHEN 2 THEN
                              DATEADD(DAY, MakeInactiveAfter, DateLastSale)
                          WHEN 1 THEN
                              DATEADD(MONTH, MakeInactiveAfter, DateLastSale)
                          ELSE
                              DATEADD(YEAR, MakeInactiveAfter, DateLastSale)
                      END < GETDATE();

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Items.t_ItemSharedMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            SELECT @UserID,
                   s.ID,
                   s.EventIs,
                   1,
                   @ComputerIP,
                   @Computer,
                   @ComputerAccount
            FROM @IDAndEvent AS s;

        END;

        ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

        BEGIN --Live

            UPDATE Alls.t_LiveVersion
            SET VersionLive = STUFF(VersionLive, Item, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')),
                SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

        END;

        COMMIT TRANSACTION;

        SELECT 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        SELECT @Return;

    END CATCH;

END;








GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateMergeItemsIntoOneItem]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdateMergeItemsIntoOneItem] @ID UNIQUEIDENTIFIER ,
  @ItemsIDs Alls.tt_Guid READONLY ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyTypeIs INT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @StockAdjustmentID UNIQUEIDENTIFIER ,
  @StockAdjustmentReasonID UNIQUEIDENTIFIER ,
  @StockAdjustmentReason NVARCHAR(MAX) ,
  @StockAdjustmentTotal FLOAT ,
  @StockAdjustmentTotalF NVARCHAR(MAX) ,
  @StockAdjustmentTotalD FLOAT ,
  @StockAdjustmentTotalLL FLOAT ,
  @StockAdjustmentTotalEuro FLOAT ,
  @StockAdjustmentTotalQtys FLOAT ,
  @StockAdjustmentWarehouses NVARCHAR(MAX) ,
  @StockAdjustmentItemsNames NVARCHAR(MAX) ,
  @StockAdjustmentDetailIs Items.[tt_StockAdjustmentDetail] READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @MasterBarcodes AS TABLE ( Barcode NVARCHAR(MAX) ); 
      DECLARE @DateIs DATETIME = GETDATE() ,
        @return INT = 0;

    END;

    BEGIN --Set
	   
      INSERT INTO @MasterBarcodes
          ( Barcode
          )
        SELECT t.BarCode
          FROM Items.t_ItemSharedBarCode AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @ItemsIDs AS s
                          WHERE s.ID = t.SharedID AND t.TypeIs = 0 );

    END;

    SET @return = -3;

    BEGIN --Update t_ItemSharedBarCode

      UPDATE Items.t_ItemSharedBarCode
        SET BarCode += N' ' + CONVERT(NVARCHAR(MAX), NEWID())
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemsIDs AS s
                        WHERE s.ID = t_ItemSharedBarCode.SharedID );

    END;

    BEGIN --Insert t_ItemSharedBarCode
    
      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        SELECT @ID ,
            t.Barcode ,
            Alls.f_ToBigint(t.Barcode) ,
            1
          FROM @MasterBarcodes AS t;

    END;

    BEGIN --Update t_ItemShared

      UPDATE Items.t_ItemShared
        SET Name += N' ' + CONVERT(NVARCHAR(MAX), NEWID()) ,
            Barcode = Items.f_ItemSharedBarCodeGetMasterBarcode(ID) ,
            Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemsIDs AS s
                        WHERE s.ID = t_ItemShared.ID );

      EXECUTE Items.s_ItemShared_UpdateLive_Barcodes_PART @ID;

    END;

    BEGIN --Delete t_ItemExpirationDate
    
      DELETE FROM Items.t_ItemExpirationDate
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @ItemsIDs AS s
                        WHERE s.ID = t_ItemExpirationDate.ItemSharedID ); 


    END;

    EXECUTE Items.s_StockAdjustmentInsertPART @StockAdjustmentID, -- @ID
      0, -- @LinkType
      '00000000-0000-0000-0000-000000000000', -- @LinkID
      0, N'', -- @LinkRefF
      @DateIs, --
      @StockAdjustmentReasonID, @StockAdjustmentReason, --
      @UserID, @UserIs, --
      @CurrencyID, @Currency, @CurrencyTypeIs, @ExchangeRateLL, @ExchangeRateEuro, --
      @StockAdjustmentTotal, -- @Total
      @StockAdjustmentTotalF, -- @TotalF
      @StockAdjustmentTotalD, -- @TotalD
      @StockAdjustmentTotalLL, -- @TotalLL
      @StockAdjustmentTotalEuro, -- @TotalEuro
      @StockAdjustmentTotalQtys, -- @TotalQtys
      N'', -- @DescriptionIs
      @StockAdjustmentWarehouses, -- @Warehouses
      @StockAdjustmentItemsNames, -- @ItemsNames
      @StockAdjustmentDetailIs, -- @DetailIs tt_StockAdjustmentDetail
      @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
	
    SET @return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ID;  
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;



GO
