/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatePricesSystemElectric2]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdatePricesSystemElectric2] @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @Items Items.tt_ItemSharedEditSell READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Items_ AS TABLE
        (
          [ID] [UNIQUEIDENTIFIER] NOT NULL ,
          [ItemSharedID] [UNIQUEIDENTIFIER] NOT NULL ,
          PrimaryIs BIT NOT NULL ,
          Price [FLOAT] NOT NULL ,
          Discount DECIMAL(4, 2) NOT NULL ,
          [CurrencyID] [UNIQUEIDENTIFIER] NOT NULL ,
          [Currency] NVARCHAR(MAX) NOT NULL ,
          ExchangeRate FLOAT NOT NULL ,
          TaxRate DECIMAL(4, 2) NOT NULL
        );

      DECLARE @Return INT = 0 ,
        @ExchangeRateLL FLOAT ,
        @ExchangeRateEuro FLOAT;

    END;

    BEGIN --Set info

      INSERT INTO @Items_
          ( ID ,
            ItemSharedID ,
            PrimaryIs ,
            Price ,
            Discount ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            TaxRate
          )
        SELECT t.ID ,
            t.ItemSharedID ,
            t.PrimaryIs ,
            t.Price ,
            t.Discount ,
            t.CurrencyID ,
            t2.Name ,
            t2.ExchangeRate ,
            t1.TaxRate
          FROM @Items AS t
          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
          INNER JOIN Currencys.t_Currency AS t2 ON t2.ID = t.CurrencyID;

      SET @ExchangeRateLL = Currencys.f_CurrencyGetExchangeRateLL();
      SET @ExchangeRateEuro = Currencys.f_CurrencyGetExchangeRateEuro();

    END;

    BEGIN --Update t_UnityItem

      MERGE Items.t_UnityItem AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Price = s.Price * t.Qty ,
                    t.PriceWithTax = Calculation.Rate(s.Price * t.Qty, s.TaxRate);

      MERGE Items.t_UnityItem AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.PriceF = Currencys.f_Format(s.CurrencyID, t.Price) ,
                    t.PriceD = t.Price / s.ExchangeRate ,
                    t.PriceLL = ( t.Price / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( t.Price / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.PriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.PriceWithTax) ,
                    t.PriceWithTaxD = t.PriceWithTax / s.ExchangeRate ,
                    t.PriceWithTaxLL = ( t.PriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceWithTaxEuro = ( t.PriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

    END;

    BEGIN --Update t_ItemShared

      DELETE FROM @Items_
        WHERE PrimaryIs = 0;

      WITH  o AS ( SELECT ROW_NUMBER() OVER ( PARTITION BY s.ItemSharedID ORDER BY ( SELECT 0
                                                                                   ) ) AS RowCountIs
                    FROM @Items_ AS s
                 )
        DELETE FROM o
          WHERE o.RowCountIs > 1;

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Sell = s.Price,
                    t.SellWithTax = Calculation.Rate(s.Price, s.TaxRate) ,
                    t.Discount = s.Discount ,
                    t.DiscountF = Currencys.f_FormatRate(s.Discount);

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.SellF = Currencys.f_Format(t.CurrencyID, t.Sell) ,
                    t.SellD = t.Sell / s.ExchangeRate ,
                    t.SellLL = ( t.Sell / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellEuro = ( t.Sell / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.SellWithTaxF = Currencys.f_Format(t.CurrencyID, t.SellWithTax) ,
                    t.SellWithTaxD = t.SellWithTax / s.ExchangeRate ,
                    t.SellWithTaxLL = ( t.SellWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellWithTaxEuro = ( t.SellWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            SellTotal = Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent  ,
			LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

    END;

    BEGIN --Cost
    
      UPDATE Items.t_ItemShared
        SET Purchase = Currencys.f_CurrencyExchangeTo(SellCurrencyID, CurrencyID, Calculation.Discount(Sell, Discount))
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );
  
      UPDATE Items.t_ItemShared
        SET PurchaseF = Currencys.f_Format(CurrencyID, Purchase) ,
            PurchaseTotal = QtyCurrent * Purchase ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, QtyCurrent * Purchase) ,
            PurchaseWithTax = Calculation.Rate(Purchase, TaxRate) ,
            PurchaseWithTaxF = Currencys.f_Format(CurrencyID, Calculation.Rate(Purchase, TaxRate)) ,
            PurchaseTotalWithTax = QtyCurrent * Calculation.Rate(Purchase, TaxRate) ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, QtyCurrent * Calculation.Rate(Purchase, TaxRate))
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

      WITH  o AS ( SELECT t.CurrencyID ,
                      t.Purchase ,
                      t.PurchaseD ,
                      t.PurchaseLL ,
                      t.PurchaseEuro ,
                      t.PurchaseWithTax ,
                      t.PurchaseWithTaxD ,
                      t.PurchaseWithTaxLL ,
                      t.PurchaseWithTaxEuro ,
                      s1.ExchangeRate
                    FROM Items.t_ItemShared AS t
                    INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = t.CurrencyID
                    WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                                    FROM @Items_ AS s
                                    WHERE s.ItemSharedID = t.ID )
                 )
        UPDATE o
          SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
              o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
              o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
              o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
              o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate);

      UPDATE Items.t_ItemShared
        SET PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

    END;

    BEGIN --Update t_UnityItem
    
      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items AS s
                        WHERE s.ID = t_UnityItem.ID );

    END;	

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ItemSharedID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Items AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatePurchase]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdatePurchase] @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @Items Items.[tt_ItemSharedEditCost] READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Items_ AS TABLE
        (
          [ID] [UNIQUEIDENTIFIER] NOT NULL ,
          [Cost] [FLOAT] NOT NULL ,
          [CurrencyID] [UNIQUEIDENTIFIER] NOT NULL ,
          [Currency] NVARCHAR(MAX) NOT NULL ,
          ExchangeRate FLOAT NOT NULL ,
          [Discount] [DECIMAL](4, 2) NOT NULL ,
          TaxRate [DECIMAL](4, 2) NOT NULL
        );

      DECLARE @IDs Alls.tt_Guid ,
        @Return INT = 0 ,
        @ExchangeRateLL FLOAT ,
        @ExchangeRateEuro FLOAT;

    END;

    BEGIN --Set info

      INSERT INTO @Items_
          ( ID ,
            Cost ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            TaxRate ,
            Discount
          )
        SELECT s.ID ,
            s.Cost ,
            s.CurrencyID ,
            s1.Name ,
            s1.ExchangeRate ,
            s.TaxRate ,
            s.Discount
          FROM @Items AS s
          LEFT JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID;

      SET @ExchangeRateLL = Currencys.f_CurrencyGetExchangeRateLL();

      SET @ExchangeRateEuro = Currencys.f_CurrencyGetExchangeRateEuro();
	
      INSERT INTO @IDs
          ( ID )
        SELECT s.ID
          FROM @Items AS s;

    END;

    BEGIN --Update 

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Currency = s.Currency ,
                    t.Purchase = s.Cost ,
                    t.PurchaseWithTax = Calculation.Rate(s.Cost, s.TaxRate) ,
                    t.Discount = s.Discount ,
                    t.DiscountF = Currencys.f_FormatRate(s.Discount) ,
                    t.TaxRate = s.TaxRate;

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.PurchaseF = Currencys.f_Format(s.CurrencyID, t.Purchase) ,
                    t.PurchaseD = t.Purchase / s.ExchangeRate ,
                    t.PurchaseLL = ( t.Purchase / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PurchaseEuro = ( t.Purchase / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.PurchaseWithTaxF = Currencys.f_Format(s.CurrencyID, t.PurchaseWithTax) ,
                    t.PurchaseWithTaxD = t.PurchaseWithTax / s.ExchangeRate ,
                    t.PurchaseWithTaxLL = ( t.PurchaseWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PurchaseWithTaxEuro = ( t.PurchaseWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET PurchaseTotal = Purchase * QtyCurrent ,
            PurchaseTotalF = Currencys.f_Format(CurrencyID, Purchase * QtyCurrent) ,
            PurchaseTotalD = PurchaseD * QtyCurrent ,
            PurchaseTotalLL = PurchaseLL * QtyCurrent ,
            PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
            PurchaseTotalWithTax = PurchaseWithTax * QtyCurrent ,
            PurchaseTotalWithTaxF = Currencys.f_Format(CurrencyID, PurchaseWithTax * QtyCurrent) ,
            PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
            PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
            PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
            LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

    IF EXISTS ( SELECT TOP ( 1 ) --t_ItemSharedMaterial
                    s.ID
                  FROM Items.t_ItemSharedMaterial AS s
                  WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                  FROM @Items AS ss
                                  WHERE ss.ID = s.ItemSharedID ) )
    BEGIN
		  
      DECLARE @MaterialItemSharedFatherIDs AS Alls.tt_Guid;

      INSERT @MaterialItemSharedFatherIDs
          ( ID
          )
        SELECT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                          FROM @Items AS ss
                          WHERE ss.ID = s.ItemSharedID );

      EXECUTE Items.s_ItemSharedFixProductionCostPARTs @MaterialItemSharedFatherIDs;

    END;

    EXECUTE Items.s_ItemSharedKeepProfitRatioFixPART @IDs;
	
    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Items AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
