/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateSale]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdateSale] @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @Items Items.tt_ItemSharedEditAllSalePrice READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Items_ AS TABLE
        (
          [ID] [UNIQUEIDENTIFIER] NOT NULL ,
          [ItemSharedID] [UNIQUEIDENTIFIER] NOT NULL ,
          PrimaryIs BIT NOT NULL ,
          Price [FLOAT] NOT NULL ,
          PriceWithTax [FLOAT] NOT NULL ,
          WholesalePrice [FLOAT] NOT NULL ,
          WholesalePriceWithTax [FLOAT] NOT NULL ,
          DistributionPrice [FLOAT] NOT NULL ,
          DistributionPriceWithTax [FLOAT] NOT NULL ,
          [CurrencyID] [UNIQUEIDENTIFIER] NOT NULL ,
          [Currency] NVARCHAR(MAX) NOT NULL ,
          ExchangeRate FLOAT NOT NULL ,
          LowestPrice [FLOAT] NOT NULL
        );

      DECLARE @ItemSharedIDs Alls.tt_Guid ,
        @Return INT ,
        @ExchangeRateLL FLOAT ,
        @ExchangeRateEuro FLOAT;

    END;

    BEGIN --Set info

      INSERT INTO @Items_
          ( ID ,
            ItemSharedID ,
            PrimaryIs ,
            Price ,
            PriceWithTax ,
            WholesalePrice ,
            WholesalePriceWithTax ,
            DistributionPrice ,
            DistributionPriceWithTax ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            LowestPrice
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.PrimaryIs ,
            s.Price ,
            Calculation.Rate(s.Price, s2.TaxRate) ,
            s.WholesalePrice ,
            Calculation.Rate(s.WholesalePrice, s2.TaxRate) ,
            s.DistributionPrice ,
            Calculation.Rate(s.DistributionPrice, s2.TaxRate) ,
            s.CurrencyID ,
            s1.Name ,
            s1.ExchangeRate ,
            s.LowestPrice
          FROM @Items AS s
          INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
          INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.ItemSharedID;

      SET @ExchangeRateLL = Currencys.f_CurrencyGetExchangeRateLL();
      SET @ExchangeRateEuro = Currencys.f_CurrencyGetExchangeRateEuro();
    
      INSERT INTO @ItemSharedIDs
          ( ID
          )
        SELECT s.ItemSharedID
          FROM @Items AS s;

    END;

    BEGIN --Update t_UnityItem

      SET @Return = 0;

      MERGE Items.t_UnityItem AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Currency = s.Currency ,
                    t.Price = s.Price ,
                    t.PriceWithTax = s.PriceWithTax ,
                    t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.LowestPrice = s.LowestPrice ,
                    t.LowestPriceF = Currencys.f_Format(s.CurrencyID, s.LowestPrice) ,
                    t.LowestPriceD = s.LowestPrice / s.ExchangeRate;

      MERGE Items.t_UnityItem AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.PriceF = Currencys.f_Format(s.CurrencyID, t.Price) ,
                    t.PriceD = t.Price / s.ExchangeRate ,
                    t.PriceLL = ( t.Price / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( t.Price / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.PriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.PriceWithTax) ,
                    t.PriceWithTaxD = t.PriceWithTax / s.ExchangeRate ,
                    t.PriceWithTaxLL = ( t.PriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceWithTaxEuro = ( t.PriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceF = Currencys.f_Format(s.CurrencyID, t.WholesalePrice) ,
                    t.WholesalePriceD = t.WholesalePrice / s.ExchangeRate ,
                    t.WholesalePriceLL = ( t.WholesalePrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceEuro = ( t.WholesalePrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.WholesalePriceWithTax) ,
                    t.WholesalePriceWithTaxD = t.WholesalePriceWithTax / s.ExchangeRate ,
                    t.WholesalePriceWithTaxLL = ( t.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceWithTaxEuro = ( t.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceF = Currencys.f_Format(s.CurrencyID, t.DistributionPrice) ,
                    t.DistributionPriceD = t.DistributionPrice / s.ExchangeRate ,
                    t.DistributionPriceLL = ( t.DistributionPrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceEuro = ( t.DistributionPrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.DistributionPriceWithTax) ,
                    t.DistributionPriceWithTaxD = t.DistributionPriceWithTax / s.ExchangeRate ,
                    t.DistributionPriceWithTaxLL = ( t.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceWithTaxEuro = ( t.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ID = t_UnityItem.ID );

    END;

    BEGIN --Update t_ItemShared

      DELETE FROM @Items_
        WHERE PrimaryIs = 0;

      WITH  o AS ( SELECT ROW_NUMBER() OVER ( PARTITION BY s.ItemSharedID ORDER BY ( SELECT 0
                                                                                   ) ) AS RowCountIs
                    FROM @Items_ AS s
                 )
        DELETE FROM o
          WHERE o.RowCountIs > 1;

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.SellCurrencyID = s.CurrencyID ,
                    t.SellCurrency = s.Currency ,
                    t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.Sell = s.Price ,
                    t.SellWithTax = s.PriceWithTax;

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.WholesalePriceF = Currencys.f_Format(s.CurrencyID, t.WholesalePrice) ,
                    t.WholesalePriceD = t.WholesalePrice / s.ExchangeRate ,
                    t.WholesalePriceLL = ( t.WholesalePrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceEuro = ( t.WholesalePrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.WholesalePriceWithTax) ,
                    t.WholesalePriceWithTaxD = t.WholesalePriceWithTax / s.ExchangeRate ,
                    t.WholesalePriceWithTaxLL = ( t.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceWithTaxEuro = ( t.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceF = Currencys.f_Format(s.CurrencyID, t.DistributionPrice) ,
                    t.DistributionPriceD = t.DistributionPrice / s.ExchangeRate ,
                    t.DistributionPriceLL = ( t.DistributionPrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceEuro = ( t.DistributionPrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceWithTaxF = Currencys.f_Format(s.CurrencyID, t.DistributionPriceWithTax) ,
                    t.DistributionPriceWithTaxD = t.DistributionPriceWithTax / s.ExchangeRate ,
                    t.DistributionPriceWithTaxLL = ( t.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceWithTaxEuro = ( t.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.SellF = Currencys.f_Format(s.CurrencyID, t.Sell) ,
                    t.SellD = t.Sell / s.ExchangeRate ,
                    t.SellLL = ( t.Sell / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellEuro = ( t.Sell / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.SellWithTaxF = Currencys.f_Format(s.CurrencyID, t.SellWithTax) ,
                    t.SellWithTaxD = t.SellWithTax / s.ExchangeRate ,
                    t.SellWithTaxLL = ( t.SellWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellWithTaxEuro = ( t.SellWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            TotalWholesalePrice = WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
            TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            TotalDistributionPrice = DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            SellTotal = Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL) ,
			LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

    END;
	
    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @ItemSharedIDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ItemSharedID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Items AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
