      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceF = Currencys.f_Format(s.CurrencyID, s.WholesalePrice) ,
                    t.WholesalePriceD = s.WholesalePrice / s.ExchangeRate ,
                    t.WholesalePriceLL = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceEuro = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.WholesalePriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.WholesalePriceWithTax) ,
                    t.WholesalePriceWithTaxD = s.WholesalePriceWithTax / s.ExchangeRate ,
                    t.WholesalePriceWithTaxLL = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceWithTaxEuro = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceF = Currencys.f_Format(s.CurrencyID, s.DistributionPrice) ,
