CREATE PROCEDURE [Items].[s_ItemSharedUpdateSaleByRateBySubCategory] @IncreaseRate DECIMAL(5, 2) ,
  @SubCategoryID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;
	
    BEGIN --Declare

      DECLARE @Items_ AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
          PrimaryIs BIT NOT NULL ,
          Price FLOAT NOT NULL ,
          PriceWithTax FLOAT NOT NULL ,
          DistributionPrice FLOAT NOT NULL ,
          DistributionPriceWithTax FLOAT NOT NULL ,
          WholesalePrice FLOAT NOT NULL ,
          WholesalePriceWithTax FLOAT NOT NULL ,
          CurrencyID UNIQUEIDENTIFIER NOT NULL ,
          ExchangeRate FLOAT NOT NULL
        );

      DECLARE @ItemSharedIDs Alls.tt_Guid ,
        @Return INT = 0 ,
        @ExchangeRateLL FLOAT ,
        @ExchangeRateEuro FLOAT;

    END;
  
    BEGIN --Set info

      INSERT INTO @Items_
          ( ID ,
            ItemSharedID ,
            PrimaryIs ,
            Price ,
            PriceWithTax ,
            DistributionPrice ,
            DistributionPriceWithTax ,
            WholesalePrice ,
            WholesalePriceWithTax ,
            CurrencyID ,
            ExchangeRate
          )
        SELECT s.ID ,
            s.SharedID ,
            s.PrimaryIs ,
            Calculation.Rate(s.Price, @IncreaseRate) ,
            Calculation.Rate(Calculation.Rate(s.Price, @IncreaseRate), s2.TaxRate) ,
            Calculation.Rate(s.DistributionPrice, @IncreaseRate) ,
            Calculation.Rate(Calculation.Rate(s.DistributionPrice, @IncreaseRate), s2.TaxRate) ,
            Calculation.Rate(s.WholesalePrice, @IncreaseRate) ,
            Calculation.Rate(Calculation.Rate(s.WholesalePrice, @IncreaseRate), s2.TaxRate) ,
            s.CurrencyID ,
            s1.ExchangeRate
          FROM Items.t_UnityItem AS s
          INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
          INNER JOIN Items.t_ItemShared AS s2 ON s2.ID = s.SharedID
          WHERE s2.SubCategoryID = @SubCategoryID;

      SET @ExchangeRateLL = Currencys.f_CurrencyGetExchangeRateLL();
      SET @ExchangeRateEuro = Currencys.f_CurrencyGetExchangeRateEuro();

      INSERT INTO @ItemSharedIDs
          ( ID
          )
        SELECT s.ItemSharedID
          FROM @Items_ AS s;

    END;

    BEGIN --Update t_UnityItem

      MERGE Items.t_UnityItem AS t
      USING @Items_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(s.CurrencyID, s.Price) ,
                    t.PriceD = s.Price / s.ExchangeRate ,
                    t.PriceLL = ( s.Price / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( s.Price / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.PriceWithTax = s.PriceWithTax ,
                    t.PriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.PriceWithTax) ,
                    t.PriceWithTaxD = s.PriceWithTax / s.ExchangeRate ,
                    t.PriceWithTaxLL = ( s.PriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceWithTaxEuro = ( s.PriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceF = Currencys.f_Format(s.CurrencyID, s.DistributionPrice) ,
                    t.DistributionPriceD = s.DistributionPrice / s.ExchangeRate ,
                    t.DistributionPriceLL = ( s.DistributionPrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceEuro = ( s.DistributionPrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.DistributionPriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.DistributionPriceWithTax) ,
                    t.DistributionPriceWithTaxD = s.DistributionPriceWithTax / s.ExchangeRate ,
                    t.DistributionPriceWithTaxLL = ( s.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceWithTaxEuro = ( s.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceF = Currencys.f_Format(s.CurrencyID, s.WholesalePrice) ,
                    t.WholesalePriceD = s.WholesalePrice / s.ExchangeRate ,
                    t.WholesalePriceLL = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceEuro = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.WholesalePriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.WholesalePriceWithTax) ,
                    t.WholesalePriceWithTaxD = s.WholesalePriceWithTax / s.ExchangeRate ,
                    t.WholesalePriceWithTaxLL = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceWithTaxEuro = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ID = t_UnityItem.ID );

    END;

    BEGIN --Update t_ItemShared

      DELETE FROM @Items_
        WHERE PrimaryIs = 0;

      WITH  o AS ( SELECT ROW_NUMBER() OVER ( PARTITION BY s.ItemSharedID ORDER BY ( SELECT 0
                                                                                   ) ) AS RowCountIs
                    FROM @Items_ AS s
                 )
        DELETE FROM o
          WHERE o.RowCountIs > 1;

      MERGE Items.t_ItemShared AS t
      USING @Items_ AS s
      ON s.ItemSharedID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceF = Currencys.f_Format(s.CurrencyID, s.WholesalePrice) ,
                    t.WholesalePriceD = s.WholesalePrice / s.ExchangeRate ,
                    t.WholesalePriceLL = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceEuro = ( s.WholesalePrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.WholesalePriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.WholesalePriceWithTax) ,
                    t.WholesalePriceWithTaxD = s.WholesalePriceWithTax / s.ExchangeRate ,
                    t.WholesalePriceWithTaxLL = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.WholesalePriceWithTaxEuro = ( s.WholesalePriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceF = Currencys.f_Format(s.CurrencyID, s.DistributionPrice) ,
                    t.DistributionPriceD = s.DistributionPrice / s.ExchangeRate ,
                    t.DistributionPriceLL = ( s.DistributionPrice / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceEuro = ( s.DistributionPrice / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.DistributionPriceWithTaxF = Currencys.f_Format(s.CurrencyID, s.DistributionPriceWithTax) ,
                    t.DistributionPriceWithTaxD = s.DistributionPriceWithTax / s.ExchangeRate ,
                    t.DistributionPriceWithTaxLL = ( s.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.DistributionPriceWithTaxEuro = ( s.DistributionPriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.Sell = s.Price ,
                    t.SellF = Currencys.f_Format(s.CurrencyID, s.Price) ,
                    t.SellD = s.Price / s.ExchangeRate ,
                    t.SellLL = ( s.Price / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellEuro = ( s.Price / s.ExchangeRate ) * @ExchangeRateEuro ,
                    t.SellWithTax = s.PriceWithTax ,
                    t.SellWithTaxF = Currencys.f_Format(s.CurrencyID, s.PriceWithTax) ,
                    t.SellWithTaxD = s.PriceWithTax / s.ExchangeRate ,
                    t.SellWithTaxLL = ( s.PriceWithTax / s.ExchangeRate ) * @ExchangeRateLL ,
                    t.SellWithTaxEuro = ( s.PriceWithTax / s.ExchangeRate ) * @ExchangeRateEuro;

    END;

    BEGIN --Rebuilding statistics

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            TotalWholesalePrice = WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
            TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            TotalDistributionPrice = DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            SellTotal = Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL) ,
			LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Items_ AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

    END;
	
    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @ItemSharedIDs;
	
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;

GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdateSaleToCurrency]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdateSaleToCurrency] @CurrencyID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemSharedIDs Alls.tt_Guid ,
        @Return INT ,
        @Currency NVARCHAR(MAX) ,
        @CurrencyTypeIs INT ,
        @ExchangeRate FLOAT ,
        @ExchangeRateLL FLOAT ,
        @ExchangeRateEuro FLOAT;

    END;

    BEGIN --Set info
			    
      SELECT TOP ( 1 ) @Currency = s.Name ,
          @ExchangeRate = s.ExchangeRate ,
          @CurrencyTypeIs = s.TypeIs
        FROM Currencys.t_Currency AS s
        WHERE s.ID = @CurrencyID
        ORDER BY s.ID;

      SET @ExchangeRateLL = Currencys.f_CurrencyGetExchangeRateLL();
      SET @ExchangeRateEuro = Currencys.f_CurrencyGetExchangeRateEuro();
  
      INSERT INTO @ItemSharedIDs
          ( ID )
        SELECT s.ID
          FROM @IDs AS s;

    END;

    BEGIN --Update t_UnityItem

      SET @Return = 0;

      IF ( @CurrencyTypeIs = 0 )
      BEGIN
				                     
        UPDATE Items.t_UnityItem
          SET CurrencyID = @CurrencyID ,
              Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
              Price = PriceD ,
              PriceWithTax = PriceWithTaxD ,
              DistributionPrice = DistributionPriceD ,
              DistributionPriceWithTax = DistributionPriceWithTaxD ,
              WholesalePrice = WholesalePriceD ,
              WholesalePriceWithTax = WholesalePriceWithTaxD
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_UnityItem.SharedID );

      END;
      ELSE
        IF ( @CurrencyTypeIs = 1 )
        BEGIN
				                     
          UPDATE Items.t_UnityItem
            SET CurrencyID = @CurrencyID ,
                Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
                Price = PriceLL ,
                PriceWithTax = PriceWithTaxLL ,
                DistributionPrice = DistributionPriceLL ,
                DistributionPriceWithTax = DistributionPriceWithTaxLL ,
                WholesalePrice = WholesalePriceLL ,
                WholesalePriceWithTax = WholesalePriceWithTaxLL
            WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                            FROM @IDs AS s
                            WHERE s.ID = t_UnityItem.SharedID );

        END;
        ELSE
          IF ( @CurrencyTypeIs = 2 )
          BEGIN
				                     
            UPDATE Items.t_UnityItem
              SET CurrencyID = @CurrencyID ,
                  Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
                  Price = PriceEuro ,
                  PriceWithTax = PriceWithTaxEuro ,
                  DistributionPrice = DistributionPriceEuro ,
                  DistributionPriceWithTax = DistributionPriceWithTaxEuro ,
                  WholesalePrice = WholesalePriceEuro ,
                  WholesalePriceWithTax = WholesalePriceWithTaxEuro
              WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                              FROM @IDs AS s
                              WHERE s.ID = t_UnityItem.SharedID );

          END;

      UPDATE Items.t_UnityItem
        SET PriceF = Currencys.f_Format(CurrencyID, Price) ,
            PriceD = Price / @ExchangeRate ,
            PriceLL = ( Price / @ExchangeRate ) * @ExchangeRateLL ,
            PriceEuro = ( Price / @ExchangeRate ) * @ExchangeRateEuro ,
            PriceWithTaxF = Currencys.f_Format(CurrencyID, PriceWithTax) ,
            PriceWithTaxD = PriceWithTax / @ExchangeRate ,
            PriceWithTaxLL = ( PriceWithTax / @ExchangeRate ) * @ExchangeRateLL ,
            PriceWithTaxEuro = ( PriceWithTax / @ExchangeRate ) * @ExchangeRateEuro ,
            DistributionPriceF = Currencys.f_Format(CurrencyID, DistributionPrice) ,
            DistributionPriceD = DistributionPrice / @ExchangeRate ,
            DistributionPriceLL = ( DistributionPrice / @ExchangeRate ) * @ExchangeRateLL ,
            DistributionPriceEuro = ( DistributionPrice / @ExchangeRate ) * @ExchangeRateEuro ,
            DistributionPriceWithTaxF = Currencys.f_Format(CurrencyID, DistributionPriceWithTax) ,
            DistributionPriceWithTaxD = DistributionPriceWithTax / @ExchangeRate ,
            DistributionPriceWithTaxLL = ( DistributionPriceWithTax / @ExchangeRate ) * @ExchangeRateLL ,
            DistributionPriceWithTaxEuro = ( DistributionPriceWithTax / @ExchangeRate ) * @ExchangeRateEuro ,
            WholesalePriceF = Currencys.f_Format(CurrencyID, WholesalePrice) ,
            WholesalePriceD = WholesalePrice / @ExchangeRate ,
            WholesalePriceLL = ( WholesalePrice / @ExchangeRate ) * @ExchangeRateLL ,
            WholesalePriceEuro = ( WholesalePrice / @ExchangeRate ) * @ExchangeRateEuro ,
            WholesalePriceWithTaxF = Currencys.f_Format(CurrencyID, WholesalePriceWithTax) ,
            WholesalePriceWithTaxD = WholesalePriceWithTax / @ExchangeRate ,
            WholesalePriceWithTaxLL = ( WholesalePriceWithTax / @ExchangeRate ) * @ExchangeRateLL ,
            WholesalePriceWithTaxEuro = ( WholesalePriceWithTax / @ExchangeRate ) * @ExchangeRateEuro
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_UnityItem.SharedID );

    END;

    BEGIN --Update t_ItemShared

      WITH  o AS ( SELECT s.CurrencyID AS SellCurrencyID_ ,
                      s.Currency AS SellCurrency_ ,
                      s1.SellCurrencyID ,
                      s1.SellCurrency ,
                      s.WholesalePrice AS WholesalePrice_ ,
                      s.WholesalePriceF AS WholesalePriceF_ ,
                      s.WholesalePriceD AS WholesalePriceD_ ,
                      s.WholesalePriceLL AS WholesalePriceLL_ ,
                      s.WholesalePriceEuro AS WholesalePriceEuro_ ,
                      s.WholesalePriceWithTax AS WholesalePriceWithTax_ ,
                      s.WholesalePriceWithTaxF AS WholesalePriceWithTaxF_ ,
                      s.WholesalePriceWithTaxD AS WholesalePriceWithTaxD_ ,
                      s.WholesalePriceWithTaxLL AS WholesalePriceWithTaxLL_ ,
                      s.WholesalePriceWithTaxEuro AS WholesalePriceWithTaxEuro_ ,
                      s.DistributionPrice AS DistributionPrice_ ,
                      s.DistributionPriceF AS DistributionPriceF_ ,
                      s.DistributionPriceD AS DistributionPriceD_ ,
                      s.DistributionPriceLL AS DistributionPriceLL_ ,
                      s.DistributionPriceEuro AS DistributionPriceEuro_ ,
                      s.DistributionPriceWithTax AS DistributionPriceWithTax_ ,
                      s.DistributionPriceWithTaxF AS DistributionPriceWithTaxF_ ,
                      s.DistributionPriceWithTaxD AS DistributionPriceWithTaxD_ ,
                      s.DistributionPriceWithTaxLL AS DistributionPriceWithTaxLL_ ,
                      s.DistributionPriceWithTaxEuro AS DistributionPriceWithTaxEuro_ ,
                      s.Price AS Price_ ,
                      s.PriceF AS PriceF_ ,
                      s.PriceD AS PriceD_ ,
                      s.PriceLL AS PriceLL_ ,
                      s.PriceEuro AS PriceEuro_ ,
                      s.PriceWithTax AS PriceWithTax_ ,
                      s.PriceWithTaxF AS PriceWithTaxF_ ,
                      s.PriceWithTaxD AS PriceWithTaxD_ ,
                      s.PriceWithTaxLL AS PriceWithTaxLL_ ,
                      s.PriceWithTaxEuro AS PriceWithTaxEuro_ ,
                      s1.WholesalePrice ,
                      s1.WholesalePriceF ,
                      s1.WholesalePriceD ,
                      s1.WholesalePriceLL ,
                      s1.WholesalePriceEuro ,
                      s1.WholesalePriceWithTax ,
                      s1.WholesalePriceWithTaxF ,
                      s1.WholesalePriceWithTaxD ,
                      s1.WholesalePriceWithTaxLL ,
                      s1.WholesalePriceWithTaxEuro ,
                      s1.DistributionPrice ,
                      s1.DistributionPriceF ,
                      s1.DistributionPriceD ,
                      s1.DistributionPriceLL ,
                      s1.DistributionPriceEuro ,
                      s1.DistributionPriceWithTax ,
                      s1.DistributionPriceWithTaxF ,
                      s1.DistributionPriceWithTaxD ,
                      s1.DistributionPriceWithTaxLL ,
                      s1.DistributionPriceWithTaxEuro ,
                      s1.Sell ,
                      s1.SellF ,
                      s1.SellD ,
                      s1.SellLL ,
                      s1.SellEuro ,
                      s1.SellWithTax ,
                      s1.SellWithTaxF ,
                      s1.SellWithTaxD ,
                      s1.SellWithTaxLL ,
                      s1.SellWithTaxEuro
                    FROM Items.t_UnityItem AS s
                    INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
                    WHERE s.PrimaryIs = 1 AND s.Qty = 1 AND EXISTS ( SELECT TOP ( 1 ) ss.ID
                                                                      FROM @IDs AS ss
                                                                      WHERE ss.ID = s.SharedID )
                 )
        UPDATE o
          SET o.SellCurrencyID = o.SellCurrencyID_ ,
              o.SellCurrency = o.SellCurrency_ ,
              o.WholesalePrice = o.WholesalePrice_ ,
              o.WholesalePriceF = o.WholesalePriceF_ ,
              o.WholesalePriceD = o.WholesalePriceD_ ,
              o.WholesalePriceLL = o.WholesalePriceLL_ ,
              o.WholesalePriceEuro = o.WholesalePriceEuro_ ,
              o.WholesalePriceWithTax = o.WholesalePriceWithTax_ ,
              o.WholesalePriceWithTaxF = o.WholesalePriceWithTaxF_ ,
              o.WholesalePriceWithTaxD = o.WholesalePriceWithTaxD_ ,
              o.WholesalePriceWithTaxLL = o.WholesalePriceWithTaxLL_ ,
              o.WholesalePriceWithTaxEuro = o.WholesalePriceWithTaxEuro_ ,
              o.DistributionPrice = o.DistributionPrice_ ,
              o.DistributionPriceF = o.DistributionPriceF_ ,
              o.DistributionPriceD = o.DistributionPriceD_ ,
              o.DistributionPriceLL = o.DistributionPriceLL_ ,
              o.DistributionPriceEuro = o.DistributionPriceEuro_ ,
              o.DistributionPriceWithTax = o.DistributionPriceWithTax_ ,
              o.DistributionPriceWithTaxF = o.DistributionPriceWithTaxF_ ,
              o.DistributionPriceWithTaxD = o.DistributionPriceWithTaxD_ ,
              o.DistributionPriceWithTaxLL = o.DistributionPriceWithTaxLL_ ,
              o.DistributionPriceWithTaxEuro = o.DistributionPriceWithTaxEuro_ ,
              o.Sell = o.Price_ ,
              o.SellF = o.PriceF_ ,
              o.SellD = o.PriceD_ ,
              o.SellLL = o.PriceLL_ ,
              o.SellEuro = o.PriceEuro_ ,
              o.SellWithTax = o.PriceWithTax_ ,
              o.SellWithTaxF = o.PriceWithTaxF_ ,
              o.SellWithTaxD = o.PriceWithTaxD_ ,
              o.SellWithTaxLL = o.PriceWithTaxLL_ ,
              o.SellWithTaxEuro = o.PriceWithTaxEuro_;

    END;

    BEGIN --Rebuilding statistics
			
      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            TotalWholesalePrice = WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(SellCurrencyID, WholesalePrice * QtyCurrent) ,
            TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(SellCurrencyID, WholesalePriceWithTax * QtyCurrent) ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            TotalDistributionPrice = DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(SellCurrencyID, DistributionPrice * QtyCurrent) ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(SellCurrencyID, DistributionPriceWithTax * QtyCurrent) ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            SellTotal = Sell * QtyCurrent ,
            SellTotalF = Currencys.f_Format(SellCurrencyID, Sell * QtyCurrent) ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(SellCurrencyID, SellWithTax * QtyCurrent) ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent ,
			LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

    EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @ItemSharedIDs;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            REPLACE(@Event, '{0}', s1.Name) ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s
          LEFT JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ID;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatesAlfaMtcShowImageSaleBoard]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
