CREATE PROCEDURE [Items].[s_ItemSharedUpdatesAllPrices] @Prices Items.tt_ItemSharedPrices READONLY ,
  @UnityItems Items.tt_UnityItem READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventIs NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Prices_ Items.tt_ItemSharedPrices ,
        @UnityItems_ Items.tt_UnityItem ,
        @Return INT = 0;

    END;

    BEGIN --Set info
	
      INSERT INTO @Prices_
          ( ID ,
            Name ,
            Barcode ,
            CurrencyID ,
            Currency ,
            Purchase ,
            PurchaseF ,
            PurchaseD ,
            PurchaseLL ,
            PurchaseEuro ,
            PurchaseWithTax ,
            PurchaseWithTaxF ,
            PurchaseWithTaxD ,
            PurchaseWithTaxLL ,
            PurchaseWithTaxEuro ,
            SellCurrencyID ,
            SellCurrency ,
            WholesalePrice ,
            WholesalePriceF ,
            WholesalePriceD ,
            WholesalePriceLL ,
            WholesalePriceEuro ,
            WholesalePriceWithTax ,
            WholesalePriceWithTaxF ,
            WholesalePriceWithTaxD ,
            WholesalePriceWithTaxLL ,
            WholesalePriceWithTaxEuro ,
            WholesalePriceProfitRatio ,
            DistributionPrice ,
            DistributionPriceF ,
            DistributionPriceD ,
            DistributionPriceLL ,
            DistributionPriceEuro ,
            DistributionPriceWithTax ,
            DistributionPriceWithTaxF ,
            DistributionPriceWithTaxD ,
            DistributionPriceWithTaxLL ,
            DistributionPriceWithTaxEuro ,
            DistributionPriceProfitRatio ,
            Sell ,
            SellF ,
            SellD ,
            SellLL ,
            SellEuro ,
            SellWithTax ,
            SellWithTaxF ,
            SellWithTaxD ,
            SellWithTaxLL ,
            SellWithTaxEuro ,
            ProfitRatio ,
            Discount ,
            DiscountF ,
            TaxRate ,
            LegalWithTax
	      )
        SELECT s1.ID ,
            s.Name ,
            s.Barcode ,
            s.CurrencyID ,
            s.Currency ,
            s.Purchase ,
            s.PurchaseF ,
            s.PurchaseD ,
            s.PurchaseLL ,
            s.PurchaseEuro ,
            s.PurchaseWithTax ,
            s.PurchaseWithTaxF ,
            s.PurchaseWithTaxD ,
            s.PurchaseWithTaxLL ,
            s.PurchaseWithTaxEuro ,
            s.SellCurrencyID ,
            s.SellCurrency ,
            s.WholesalePrice ,
            s.WholesalePriceF ,
            s.WholesalePriceD ,
            s.WholesalePriceLL ,
            s.WholesalePriceEuro ,
            s.WholesalePriceWithTax ,
            s.WholesalePriceWithTaxF ,
            s.WholesalePriceWithTaxD ,
            s.WholesalePriceWithTaxLL ,
            s.WholesalePriceWithTaxEuro ,
            s.WholesalePriceProfitRatio ,
            s.DistributionPrice ,
            s.DistributionPriceF ,
            s.DistributionPriceD ,
            s.DistributionPriceLL ,
            s.DistributionPriceEuro ,
            s.DistributionPriceWithTax ,
            s.DistributionPriceWithTaxF ,
            s.DistributionPriceWithTaxD ,
            s.DistributionPriceWithTaxLL ,
            s.DistributionPriceWithTaxEuro ,
            s.DistributionPriceProfitRatio ,
            s.Sell ,
            s.SellF ,
            s.SellD ,
            s.SellLL ,
            s.SellEuro ,
            s.SellWithTax ,
            s.SellWithTaxF ,
            s.SellWithTaxD ,
            s.SellWithTaxLL ,
            s.SellWithTaxEuro ,
            s.ProfitRatio ,
            s.Discount ,
            s.DiscountF ,
            s.TaxRate ,
            s.LegalWithTax
          FROM @Prices AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.Barcode = s.Barcode;

      INSERT @UnityItems_
          ( ID ,
            UnityID ,
            Unity ,
            SharedID ,
            BarCode ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            PriceWithTax ,
            PriceWithTaxF ,
            PriceWithTaxD ,
            PriceWithTaxLL ,
            PriceWithTaxEuro ,
            DistributionPrice ,
            DistributionPriceF ,
            DistributionPriceD ,
            DistributionPriceLL ,
            DistributionPriceEuro ,
            DistributionPriceWithTax ,
            DistributionPriceWithTaxF ,
            DistributionPriceWithTaxD ,
            DistributionPriceWithTaxLL ,
            DistributionPriceWithTaxEuro ,
            DistributionPriceProfitRatio ,
            WholesalePrice ,
            WholesalePriceF ,
            WholesalePriceD ,
            WholesalePriceLL ,
            WholesalePriceEuro ,
            WholesalePriceWithTax ,
            WholesalePriceWithTaxF ,
            WholesalePriceWithTaxD ,
            WholesalePriceWithTaxLL ,
            WholesalePriceWithTaxEuro ,
            WholesalePriceProfitRatio ,
            LowestPrice ,
            LowestPriceF ,
            LowestPriceD ,
            CurrencyIDCost ,
            CurrencyCost ,
            Cost ,
            CostF ,
            CostD ,
            CostLL ,
            CostEuro ,
            CostWithTax ,
            CostWithTaxF ,
            CostWithTaxD ,
            CostWithTaxLL ,
            CostWithTaxEuro ,
            ProfitRatio
          )
        SELECT s3.ID ,
            s3.UnityID ,
            s.Unity ,
            s3.SharedID ,
            s.BarCode ,
            s.CurrencyID ,
            s.Currency ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            s.PriceWithTax ,
            s.PriceWithTaxF ,
            s.PriceWithTaxD ,
            s.PriceWithTaxLL ,
            s.PriceWithTaxEuro ,
            s.DistributionPrice ,
            s.DistributionPriceF ,
            s.DistributionPriceD ,
            s.DistributionPriceLL ,
            s.DistributionPriceEuro ,
            s.DistributionPriceWithTax ,
            s.DistributionPriceWithTaxF ,
            s.DistributionPriceWithTaxD ,
            s.DistributionPriceWithTaxLL ,
            s.DistributionPriceWithTaxEuro ,
            s.DistributionPriceProfitRatio ,
            s.WholesalePrice ,
            s.WholesalePriceF ,
            s.WholesalePriceD ,
            s.WholesalePriceLL ,
            s.WholesalePriceEuro ,
            s.WholesalePriceWithTax ,
            s.WholesalePriceWithTaxF ,
            s.WholesalePriceWithTaxD ,
            s.WholesalePriceWithTaxLL ,
            s.WholesalePriceWithTaxEuro ,
            s.WholesalePriceProfitRatio ,
            s.LowestPrice ,
            s.LowestPriceF ,
            s.LowestPriceD ,
            s.CurrencyIDCost ,
            s.CurrencyCost ,
            s.Cost ,
            s.CostF ,
            s.CostD ,
            s.CostLL ,
            s.CostEuro ,
            s.CostWithTax ,
            s.CostWithTaxF ,
            s.CostWithTaxD ,
            s.CostWithTaxLL ,
            s.CostWithTaxEuro ,
            s.ProfitRatio
          FROM @UnityItems AS s
          INNER JOIN @Prices AS s1 ON s1.ID = s.SharedID
          INNER JOIN @Prices_ AS s2 ON s2.Barcode = s1.Barcode
          INNER JOIN Items.t_UnityItem AS s3 ON s3.SharedID = s2.ID AND s3.Unity = s.Unity;

    END;

    BEGIN --Update t_ItemShared

      MERGE Items.t_ItemShared AS t
      USING @Prices_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Currency = s.Currency ,
                    t.Purchase = s.Purchase ,
                    t.PurchaseF = s.PurchaseF ,
                    t.PurchaseD = s.PurchaseD ,
                    t.PurchaseLL = s.PurchaseLL ,
                    t.PurchaseEuro = s.PurchaseEuro ,
                    t.PurchaseTotal = s.Purchase * t.QtyCurrent ,
                    t.PurchaseTotalF = Currencys.f_Format(s.CurrencyID, s.Purchase * t.QtyCurrent) ,
                    t.PurchaseTotalD = s.PurchaseD * t.QtyCurrent ,
                    t.PurchaseTotalLL = s.PurchaseLL * t.QtyCurrent ,
                    t.PurchaseTotalEuro = s.PurchaseEuro * t.QtyCurrent ,
                    t.PurchaseWithTax = s.PurchaseWithTax ,
                    t.PurchaseWithTaxF = s.PurchaseWithTaxF ,
                    t.PurchaseWithTaxD = s.PurchaseWithTaxD ,
                    t.PurchaseWithTaxLL = s.PurchaseWithTaxLL ,
                    t.PurchaseWithTaxEuro = s.PurchaseWithTaxEuro ,
                    t.PurchaseTotalWithTax = s.PurchaseWithTax * t.QtyCurrent ,
                    t.PurchaseTotalWithTaxF = Currencys.f_Format(s.CurrencyID, s.PurchaseWithTax * t.QtyCurrent) ,
                    t.PurchaseTotalWithTaxD = s.PurchaseWithTaxD * t.QtyCurrent ,
                    t.PurchaseTotalWithTaxLL = s.PurchaseWithTaxLL * t.QtyCurrent ,
                    t.PurchaseTotalWithTaxEuro = s.PurchaseWithTaxEuro * t.QtyCurrent ,
                    t.SellCurrencyID = s.SellCurrencyID ,
                    t.SellCurrency = s.SellCurrency ,
                    t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceF = s.WholesalePriceF ,
                    t.WholesalePriceD = s.WholesalePriceD ,
                    t.WholesalePriceLL = s.WholesalePriceLL ,
                    t.WholesalePriceEuro = s.WholesalePriceEuro ,
                    t.TotalWholesalePrice = s.WholesalePrice * t.QtyCurrent ,
                    t.TotalWholesalePriceF = Currencys.f_Format(s.SellCurrencyID, s.WholesalePrice * t.QtyCurrent) ,
                    t.TotalWholesalePriceD = s.WholesalePriceD * t.QtyCurrent ,
                    t.TotalWholesalePriceLL = s.WholesalePriceLL * t.QtyCurrent ,
                    t.TotalWholesalePriceEuro = s.WholesalePriceEuro * t.QtyCurrent ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.WholesalePriceWithTaxF = s.WholesalePriceWithTaxF ,
                    t.WholesalePriceWithTaxD = s.WholesalePriceWithTaxD ,
                    t.WholesalePriceWithTaxLL = s.WholesalePriceWithTaxLL ,
                    t.WholesalePriceWithTaxEuro = s.WholesalePriceWithTaxEuro ,
                    t.TotalWholesalePriceWithTax = s.WholesalePriceWithTax * t.QtyCurrent ,
                    t.TotalWholesalePriceWithTaxF = Currencys.f_Format(s.SellCurrencyID, s.WholesalePriceWithTax * t.QtyCurrent) ,
                    t.TotalWholesalePriceWithTaxD = s.WholesalePriceWithTaxD * t.QtyCurrent ,
                    t.TotalWholesalePriceWithTaxLL = s.WholesalePriceWithTaxLL * t.QtyCurrent ,
                    t.TotalWholesalePriceWithTaxEuro = s.WholesalePriceWithTaxEuro * t.QtyCurrent ,
                    t.WholesalePriceProfitRatio = s.WholesalePriceProfitRatio ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceF = s.DistributionPriceF ,
                    t.DistributionPriceD = s.DistributionPriceD ,
                    t.DistributionPriceLL = s.DistributionPriceLL ,
                    t.DistributionPriceEuro = s.DistributionPriceEuro ,
                    t.TotalDistributionPrice = s.DistributionPrice * t.QtyCurrent ,
                    t.TotalDistributionPriceF = Currencys.f_Format(s.SellCurrencyID, s.DistributionPrice * t.QtyCurrent) ,
                    t.TotalDistributionPriceD = s.DistributionPriceD * t.QtyCurrent ,
                    t.TotalDistributionPriceLL = s.DistributionPriceLL * t.QtyCurrent ,
                    t.TotalDistributionPriceEuro = s.DistributionPriceEuro * t.QtyCurrent ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.DistributionPriceWithTaxF = s.DistributionPriceWithTaxF ,
                    t.DistributionPriceWithTaxD = s.DistributionPriceWithTaxD ,
                    t.DistributionPriceWithTaxLL = s.DistributionPriceWithTaxLL ,
                    t.DistributionPriceWithTaxEuro = s.DistributionPriceWithTaxEuro ,
                    t.TotalDistributionPriceWithTax = s.DistributionPriceWithTax * t.QtyCurrent ,
                    t.TotalDistributionPriceWithTaxF = Currencys.f_Format(s.SellCurrencyID, s.DistributionPriceWithTax * t.QtyCurrent) ,
                    t.TotalDistributionPriceWithTaxD = s.DistributionPriceWithTaxD * t.QtyCurrent ,
                    t.TotalDistributionPriceWithTaxLL = s.DistributionPriceWithTaxLL * t.QtyCurrent ,
                    t.TotalDistributionPriceWithTaxEuro = s.DistributionPriceWithTaxEuro * t.QtyCurrent ,
                    t.DistributionPriceProfitRatio = s.DistributionPriceProfitRatio ,
                    t.Sell = s.Sell ,
                    t.SellF = s.SellF ,
                    t.SellD = s.SellD ,
                    t.SellLL = s.SellLL ,
                    t.SellEuro = s.SellEuro ,
                    t.SellTotal = s.Sell * t.QtyCurrent ,
                    t.SellTotalF = Currencys.f_Format(s.SellCurrencyID, s.Sell * t.QtyCurrent) ,
                    t.SellTotalD = s.SellD * t.QtyCurrent ,
                    t.SellTotalLL = s.SellLL * t.QtyCurrent ,
                    t.SellTotalEuro = s.SellEuro * t.QtyCurrent ,
                    t.SellWithTax = s.SellWithTax ,
                    t.SellWithTaxF = s.SellWithTaxF ,
                    t.SellWithTaxD = s.SellWithTaxD ,
                    t.SellWithTaxLL = s.SellWithTaxLL ,
                    t.SellWithTaxEuro = s.SellWithTaxEuro ,
                    t.SellTotalWithTax = s.SellWithTax * t.QtyCurrent ,
                    t.SellTotalWithTaxF = Currencys.f_Format(s.SellCurrencyID, s.SellWithTax * t.QtyCurrent) ,
                    t.SellTotalWithTaxD = s.SellWithTaxD * t.QtyCurrent ,
                    t.SellTotalWithTaxLL = s.SellWithTaxLL * t.QtyCurrent ,
                    t.SellTotalWithTaxEuro = s.SellWithTaxEuro * t.QtyCurrent ,
                    t.ProfitRatio = s.ProfitRatio ,
                    t.Discount = s.Discount ,
                    t.DiscountF = s.DiscountF ,
                    t.FinalPrice = Calculation.Discount(s.Sell, s.Discount) ,
                    t.FinalPriceF = Currencys.f_Format(s.SellCurrencyID, Calculation.Discount(s.Sell, s.Discount)) ,
                    t.FinalPriceD = Calculation.Discount(s.SellD, s.Discount) ,
                    t.FinalPriceLL = Calculation.Discount(s.SellLL, s.Discount) ,
                    t.FinalPriceEuro = Calculation.Discount(s.SellEuro, s.Discount) ,
                    t.TaxRate = s.TaxRate ,
                    t.LegalWithTax = s.LegalWithTax;

    END;

    IF EXISTS ( SELECT TOP ( 1 ) --Update t_ItemSharedMaterial
                    s.ID
                  FROM Items.t_ItemSharedMaterial AS s
                  WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                  FROM @Prices_ AS ss
                                  WHERE ss.ID = s.ItemSharedID ) )
    BEGIN
		  
      DECLARE @MaterialItemSharedFatherIDs AS Alls.tt_Guid;

      INSERT @MaterialItemSharedFatherIDs
          ( ID
          )
        SELECT s.ItemSharedFatherID
          FROM Items.t_ItemSharedMaterial AS s
          WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                          FROM @Prices_ AS ss
                          WHERE ss.ID = s.ItemSharedID );

      EXECUTE Items.s_ItemSharedFixProductionCostPARTs @MaterialItemSharedFatherIDs;

    END;

    DISABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    BEGIN --Update t_UnityItem

      MERGE Items.t_UnityItem AS t
      USING @UnityItems_ AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = s.CurrencyID ,
                    t.Currency = s.Currency ,
                    t.Price = s.Price ,
                    t.PriceF = s.PriceF ,
                    t.PriceD = s.PriceD ,
                    t.PriceLL = s.PriceLL ,
                    t.PriceEuro = s.PriceEuro ,
                    t.PriceWithTax = s.PriceWithTax ,
                    t.PriceWithTaxF = s.PriceWithTaxF ,
                    t.PriceWithTaxD = s.PriceWithTaxD ,
                    t.PriceWithTaxLL = s.PriceWithTaxLL ,
                    t.PriceWithTaxEuro = s.PriceWithTaxEuro ,
                    t.DistributionPrice = s.DistributionPrice ,
                    t.DistributionPriceF = s.DistributionPriceF ,
                    t.DistributionPriceD = s.DistributionPriceD ,
                    t.DistributionPriceLL = s.DistributionPriceLL ,
                    t.DistributionPriceEuro = s.DistributionPriceEuro ,
                    t.DistributionPriceWithTax = s.DistributionPriceWithTax ,
                    t.DistributionPriceWithTaxF = s.DistributionPriceWithTaxF ,
                    t.DistributionPriceWithTaxD = s.DistributionPriceWithTaxD ,
                    t.DistributionPriceWithTaxLL = s.DistributionPriceWithTaxLL ,
                    t.DistributionPriceWithTaxEuro = s.DistributionPriceWithTaxEuro ,
                    t.DistributionPriceProfitRatio = s.DistributionPriceProfitRatio ,
                    t.WholesalePrice = s.WholesalePrice ,
                    t.WholesalePriceF = s.WholesalePriceF ,
                    t.WholesalePriceD = s.WholesalePriceD ,
                    t.WholesalePriceLL = s.WholesalePriceLL ,
                    t.WholesalePriceEuro = s.WholesalePriceEuro ,
                    t.WholesalePriceWithTax = s.WholesalePriceWithTax ,
                    t.WholesalePriceWithTaxF = s.WholesalePriceWithTaxF ,
                    t.WholesalePriceWithTaxD = s.WholesalePriceWithTaxD ,
                    t.WholesalePriceWithTaxLL = s.WholesalePriceWithTaxLL ,
                    t.WholesalePriceWithTaxEuro = s.WholesalePriceWithTaxEuro ,
                    t.WholesalePriceProfitRatio = s.WholesalePriceProfitRatio ,
                    t.LowestPrice = s.LowestPrice ,
                    t.LowestPriceF = s.LowestPriceF ,
                    t.LowestPriceD = s.LowestPriceD ,
                    t.CurrencyIDCost = s.CurrencyIDCost ,
                    t.CurrencyCost = s.CurrencyCost ,
                    t.Cost = s.Cost ,
                    t.CostF = s.CostF ,
                    t.CostD = s.CostD ,
                    t.CostLL = s.CostLL ,
                    t.CostEuro = s.CostEuro ,
                    t.CostWithTax = s.CostWithTax ,
                    t.CostWithTaxF = s.CostWithTaxF ,
                    t.CostWithTaxD = s.CostWithTaxD ,
                    t.CostWithTaxLL = s.CostWithTaxLL ,
                    t.CostWithTaxEuro = s.CostWithTaxEuro ,
                    t.ProfitRatio = s.ProfitRatio;
  
    END;

    ENABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;
	
    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            Alls.f_GetEmptyGuid() ,
            @EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    ENABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    SELECT @Return;

  END CATCH;

END;










