GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdatesAutoPurchaseFull] @t Items.tt_ItemSharedAutoPurchase READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    MERGE Items.t_ItemShared AS t
    USING @t AS s
    ON t.ID = s.ID
    WHEN MATCHED THEN
      UPDATE SET t.AutoPurchase = s.AutoPurchase ,
                  t.AutoPurchaseAccountID = s.AutoPurchaseAccountID ,
                  t.AutoPurchaseCurrencyID = s.AutoPurchaseCurrencyID ,
				  t.LastModifiedDate = GETDATE();
	     
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT -1;

  END CATCH;

END;










