/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatesMainCategory]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemSharedUpdatesMainCategory] @MainCategoryID UNIQUEIDENTIFIER ,
  @SubCategoryID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_IDAndEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @MainCategories AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @return INT = 0;

    END;

    BEGIN --Set Info
    
      INSERT INTO @MainCategories
          ( ID
          )
        SELECT DISTINCT t.MainCategoryID
          FROM Items.t_ItemShared AS t
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.ID );

      INSERT INTO @MainCategories
          ( ID )
        VALUES ( @MainCategoryID );

    END;

    BEGIN --Update item shared

      UPDATE Items.t_ItemShared
        SET MainCategoryID = @MainCategoryID ,
            MainCategory = Items.f_MainCategoryGetName(@MainCategoryID) ,
            SubCategoryID = @SubCategoryID ,
            SubCategory = Items.f_SubCategoryGetName(@SubCategoryID) ,
            LastModifiedDate = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_ItemShared.ID );

    END;

    BEGIN --Insert t_ItemSharedMoving

      SET @return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;

    BEGIN --Update t_MainCategory

      UPDATE Items.t_MainCategory
        SET ItemC = ( SELECT COUNT(*) AS Total
                        FROM Items.t_ItemShared AS t
                        WHERE t.MainCategoryID = t_MainCategory.ID
                    ) ,
            ItemInListCount = ( SELECT COUNT(*) AS Total
                                  FROM Items.t_ItemShared AS t
                                  WHERE t.MainCategoryID = t_MainCategory.ID AND t.InList = 1
                              )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @MainCategories AS s
                        WHERE s.ID = t_MainCategory.ID );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;


GO
