CREATE PROCEDURE [Items].[s_ItemSharedUpdatesQtyCurrentLegal] @t Items.tt_ItemSharedQtyCurrentLegal READONLY
AS
BEGIN;

  DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    MERGE Items.t_ItemShared AS t
    USING @t AS s
    ON t.ID = s.ID
    WHEN MATCHED THEN
      UPDATE SET t.QtyCurrentLegal = s.QtyCurrentLegal ,
                  t.QtyCurrentByUnitLegal = Items.f_GetQtyCurrentByUnit(t.ID, s.QtyCurrentLegal),
				  t.LastModifiedDate = GETDATE();

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT -1;

  END CATCH;

  ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;

END;

