CREATE PROCEDURE [Items].[s_ItemSharedUpdatesQtyToReorderPercentage] @IDs Alls.tt_Guid READONLY ,
  @Percentage FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @EventIs NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @return INT = 0;

    END;

    BEGIN --Update t_ItemShared

      UPDATE Items.t_ItemShared
        SET QtyToReorder = CEILING(Calculation.Division(QtyCurrent, 100) * @Percentage) ,
			LastModifiedDate = GETDATE()
        WHERE QtyCurrent >= 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                            FROM @IDs AS s
                                            WHERE s.ID = t_ItemShared.ID );

    END;
  
    BEGIN --Update t_Item

      UPDATE Items.t_Item
        SET QtyToReorder = CEILING(Calculation.Division(QtyCurrent, 100) * @Percentage)
        WHERE QtyCurrent >= 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                            FROM @IDs AS s
                                            WHERE s.ID = t_Item.SharedID );

    END;

    BEGIN --Insert t_ItemSharedMoving

      SET @return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            Alls.f_GetEmptyGuid() ,
            @EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










