/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatesRecalculateAverageCost]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemSharedUpdatesRecalculateAverageCost] @ItemSharedIDs Alls.tt_Guid READONLY ,
  @CalculatingFreeQuantities BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set Info
	    
      INSERT INTO @ItemShared
          ( ID ,
            CurrencyID ,
            OldCost ,
            Cost ,
            EventIs
          )
        SELECT s.ID ,
            s1.CurrencyID ,
            s1.Purchase ,
            Items.f_ItemSharedGetAverageCost(s.ID, @CalculatingFreeQuantities) ,
            @EventBase + s1.PurchaseF
          FROM @ItemSharedIDs AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ID
          WHERE s1.MaterialsCounts <= 0;
    
      INSERT INTO @ItemShared
          ( ID ,
            CurrencyID ,
            OldCost ,
            Cost ,
            EventIs
          )
        SELECT s.ID ,
            s1.CurrencyID ,
            s1.Purchase ,
            Items.f_ItemSharedMaterial_GetCost(s.ID) ,
            N''
          FROM @ItemSharedIDs AS s
          INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ID
          WHERE s1.MaterialsCounts > 0;

      UPDATE @ItemShared
        SET EventIs = @EventBase + Currencys.f_Format(CurrencyID, Cost)
        WHERE EventIs = N'';

      DELETE FROM @ItemShared
        WHERE OldCost = Cost;

      UPDATE @ItemShared
        SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

    END;

    EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @EventBase, @ComputerIP, @Computer, @ComputerAccount;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Items].[s_ItemSharedUpdatesRecalculateCostPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared AS Items.tt_ItemSharedRecalculateCost READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @EventBase NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  BEGIN --Declare

    DECLARE @ItemSharedIDs Alls.tt_Guid;

  END;

  BEGIN --Set Info
	    
    INSERT INTO @ItemSharedIDs
        ( ID )
      SELECT s.ID
        FROM @ItemShared AS s;

  END;

  BEGIN --Update 

    MERGE Items.t_ItemShared AS t
    USING @ItemShared AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.Purchase = s.Cost ,
                  t.PurchaseF = Currencys.f_Format(t.CurrencyID, s.Cost) ,
                  t.PurchaseTotal = t.QtyCurrent * s.Cost ,
                  t.PurchaseTotalF = Currencys.f_Format(t.CurrencyID, t.QtyCurrent * s.Cost) ,
                  t.PurchaseWithTax = Calculation.Rate(s.Cost, t.TaxRate) ,
                  t.PurchaseWithTaxF = Currencys.f_Format(t.CurrencyID, Calculation.Rate(s.Cost, t.TaxRate)) ,
                  t.PurchaseTotalWithTax = t.QtyCurrent * Calculation.Rate(s.Cost, t.TaxRate) ,
                  t.PurchaseTotalWithTaxF = Currencys.f_Format(t.CurrencyID, t.QtyCurrent * Calculation.Rate(s.Cost, t.TaxRate));

    WITH  o AS ( SELECT s.CurrencyID ,
                    s.Purchase ,
                    s.PurchaseD ,
                    s.PurchaseLL ,
                    s.PurchaseEuro ,
                    s.PurchaseWithTax ,
                    s.PurchaseWithTaxD ,
                    s.PurchaseWithTaxLL ,
                    s.PurchaseWithTaxEuro ,
                    s1.ExchangeRate
                  FROM Items.t_ItemShared AS s
                  INNER JOIN Currencys.t_Currency AS s1 ON s1.ID = s.CurrencyID
                  WHERE EXISTS ( SELECT TOP ( 1 ) s2.ID
                                  FROM @ItemShared AS s2
                                  WHERE s2.ID = s.ID )
               )
      UPDATE o
        SET o.PurchaseD = o.Purchase / o.ExchangeRate ,
            o.PurchaseLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
            o.PurchaseEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.Purchase, o.Purchase / o.ExchangeRate) ,
            o.PurchaseWithTaxD = o.PurchaseWithTax / o.ExchangeRate ,
            o.PurchaseWithTaxLL = Currencys.f_ExchangeToLL(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate) ,
            o.PurchaseWithTaxEuro = Currencys.f_ExchangeToEuro(o.CurrencyID, o.PurchaseWithTax, o.PurchaseWithTax / o.ExchangeRate);

    UPDATE Items.t_ItemShared
      SET PurchaseTotalD = PurchaseD * QtyCurrent ,
          PurchaseTotalLL = PurchaseLL * QtyCurrent ,
          PurchaseTotalEuro = PurchaseEuro * QtyCurrent ,
          PurchaseTotalWithTaxD = PurchaseWithTaxD * QtyCurrent ,
          PurchaseTotalWithTaxLL = PurchaseWithTaxLL * QtyCurrent ,
          PurchaseTotalWithTaxEuro = PurchaseWithTaxEuro * QtyCurrent ,
          LastModifiedDate = GETDATE()
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @ItemShared AS s
                      WHERE s.ID = t_ItemShared.ID );

  END;

  IF EXISTS ( SELECT TOP ( 1 ) --t_ItemSharedMaterial
                  s.ID
                FROM Items.t_ItemSharedMaterial AS s
                WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                FROM @ItemShared AS ss
                                WHERE ss.ID = s.ItemSharedID ) )
  BEGIN
		  
    DECLARE @MaterialItemSharedFatherIDs AS Alls.tt_Guid;

    INSERT @MaterialItemSharedFatherIDs
        ( ID
        )
      SELECT s.ItemSharedFatherID
        FROM Items.t_ItemSharedMaterial AS s
        WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                        FROM @ItemShared AS ss
                        WHERE ss.ID = s.ItemSharedID );

      EXECUTE Items.s_ItemSharedFixProductionCostPARTs @MaterialItemSharedFatherIDs;

  END;

  EXECUTE Items.s_ItemSharedKeepProfitRatioFixPART @ItemSharedIDs;
	
  EXECUTE Items.s_ItemFixesPurchaseAndSaleTotalByShared @ItemSharedIDs;
	
  BEGIN --Insert event

    INSERT INTO Items.t_ItemSharedMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      SELECT @UserID ,
          s.ID ,
          s.EventIs ,
          1 ,
          @ComputerIP ,
          @Computer ,
          @ComputerAccount
        FROM @ItemShared AS s;

  END;

END;




GO
