  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'itemsPackage' );
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            1 ,
            'itemsPackageDetails'
          FROM Items.t_ItemsPackageDetails AS t
          WHERE t.ItemsPackageID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Items.t_ItemsPackageDetails
        WHERE ItemsPackageID = @ID;

      DELETE FROM Items.t_ItemsPackage
        WHERE ID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Items.s_ItemsPackageMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Items.s_ItemsPackageLiveVersion;
    EXECUTE Items.s_ItemsPackageDetailsLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






