AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @OrderBy BIGINT ,
        @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @Return INT  = 0;

    END;

    BEGIN --Set
	    
      SELECT @OrderBy = ISNULL(MAX(s.OrderBy), 0) + 1
        FROM Items.t_ItemsPackage AS s;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemsPackage
          ( ID ,
            Name ,
            Barcode ,
            BarcodeNumber ,
            ColorIs ,
            ColorInt ,
            ImageIs ,
            ImagePath ,
            TargetType ,
            TargetGeneralQuantity ,
            CurrencyID ,
