            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            OrderBy ,
            ShowImage ,
            FlowBreak ,
            DescriptionIs ,
            IsActive ,
            CreatedByUserID ,
            ItemsQtys ,
            ItemsCount ,
            ItemsNames ,
            IsSyncImage
          )
        VALUES
          ( @ID ,
            @Name ,
            @Barcode ,
			@BarcodeNumber ,
            @ColorIs ,
            @ColorInt ,
            @ImageIs ,
            @ImagePath ,
            @TargetType ,
            @TargetGeneralQuantity ,
            @CurrencyID ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @TotalCost ,
            @TotalCostF ,
            @TotalCostD ,
            @TotalCostLL ,
            @TotalCostEuro ,
            @Subtotal ,
            @SubtotalF ,
            @SubtotalD ,
            @SubtotalLL ,
            @SubtotalEuro ,
            @NontaxableAmount ,
