            @NontaxableAmountLL ,
            @NontaxableAmountEuro ,
            @TaxableAmount ,
            @TaxableAmountF ,
            @TaxableAmountD ,
            @TaxableAmountLL ,
            @TaxableAmountEuro ,
            @Taxes ,
            @TaxesF ,
            @TaxesD ,
            @TaxesLL ,
            @TaxesEuro ,
            @TaxesRate ,
            @TaxesRateF ,
            @Total ,
            @TotalF ,
            @TotalD ,
