            @ShowImage ,
            @FlowBreak ,
            @DescriptionIs ,
            @IsActive ,
            @CreatedByUserID ,
            @ItemsQtys ,
            @ItemsCount ,
            @ItemsNames ,
            IIF(@ImagePath = '', 0, 1)
          );

    END;

    EXECUTE Items.s_ItemsPackageUpdateReorderPART 1;

    BEGIN --Insert t_ItemsPackageDetail

      INSERT INTO Items.t_ItemsPackageDetails
          ( ID ,
            ItemsPackageID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            Qty ,
            QtyWithUnit ,
            Qtys ,
            UnitCost ,
            UnitCostF ,
            UnitCostD ,
            UnitCostLL ,
            UnitCostEuro ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            SalePrice ,
            SalePriceF ,
            SalePriceD ,
            SalePriceLL ,
            SalePriceEuro ,
            DiscountRate ,
            DiscountRateF ,
            Discount ,
            DiscountF ,
            DiscountD ,
            DiscountLL ,
            DiscountEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            TaxesRate ,
            TaxesRateF ,
            Taxes ,
            TaxesF ,
            TaxesD ,
            TaxesLL ,
            TaxesEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            Profit ,
            ProfitF ,
            ProfitD ,
            ProfitLL ,
            ProfitEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            ProfitRate ,
            ProfitRateF ,
            OrderBy ,
            DescriptionIs
          )
        SELECT t.ID ,
            t.ItemsPackageID ,
            t.ItemSharedID ,
            t.ItemID ,
            t.WarehouseID ,
            t.ItemUnitID ,
            t.Qty ,
            t.QtyWithUnit ,
            t.Qtys ,
            t.UnitCost ,
            t.UnitCostF ,
            t.UnitCostD ,
            t.UnitCostLL ,
            t.UnitCostEuro ,
            t.TotalCost ,
            t.TotalCostF ,
            t.TotalCostD ,
            t.TotalCostLL ,
            t.TotalCostEuro ,
            t.SalePrice ,
            t.SalePriceF ,
            t.SalePriceD ,
            t.SalePriceLL ,
            t.SalePriceEuro ,
            t.DiscountRate ,
            t.DiscountRateF ,
            t.Discount ,
            t.DiscountF ,
            t.DiscountD ,
            t.DiscountLL ,
            t.DiscountEuro ,
            t.SubTotal ,
            t.SubTotalF ,
            t.SubTotalD ,
            t.SubTotalLL ,
            t.SubTotalEuro ,
            t.TaxesRate ,
            t.TaxesRateF ,
            t.Taxes ,
            t.TaxesF ,
            t.TaxesD ,
            t.TaxesLL ,
            t.TaxesEuro ,
            t.Total ,
            t.TotalF ,
            t.TotalD ,
            t.TotalLL ,
            t.TotalEuro ,
            t.Profit ,
            t.ProfitF ,
            t.ProfitD ,
            t.ProfitLL ,
            t.ProfitEuro ,
            t.TotalProfit ,
            t.TotalProfitF ,
            t.TotalProfitD ,
            t.TotalProfitLL ,
            t.TotalProfitEuro ,
            t.ProfitRate ,
            t.ProfitRateF ,
            t.OrderBy ,
            t.DescriptionIs
          FROM @ItemsPackageDetails AS t;

    END;

    SET @Return = -1;
    EXECUTE Items.s_ItemsPackageMovingInsertPART @ID, @CreatedByUserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Items.s_ItemsPackageLiveVersion;
    EXECUTE Items.s_ItemsPackageDetailsLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
