/****** Object:  StoredProcedure [Items].[s_ItemsPackageRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemsPackageRebuildingStatistics] @RebuildColumn NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuilding Statistics

      IF @RebuildColumn = 'All'
      BEGIN

        UPDATE Items.t_ItemsPackage
          SET TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalAR = Currencys.f_ToWordAR(Total, CurrencyID, 1) ,
              TotalEN = Currencys.f_ToWordEN(Total, CurrencyID, 1) ,
              TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              ItemsQtys = Items.f_ItemsPackageGetItemsQtysX(ID) ,
              ItemsCount = Items.f_ItemsPackageGetItemsCountX(ID) ,
              ItemsNames = Items.f_ItemsPackageGetItemsNamesX(ID) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_ItemsPackage.ID );

        EXECUTE Items.s_ItemsPackageUpdateReorderPART 0;

      END;

      IF @RebuildColumn = 'Currency'
      BEGIN

        UPDATE Items.t_ItemsPackage
          SET TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
              SubtotalF = Currencys.f_Format(CurrencyID, Subtotal) ,
              NontaxableAmountF = Currencys.f_Format(CurrencyID, NontaxableAmount) ,
              TaxableAmountF = Currencys.f_Format(CurrencyID, TaxableAmount) ,
              TaxesF = Currencys.f_Format(CurrencyID, Taxes) ,
              TaxesRateF = Currencys.f_FormatRate(TaxesRate) ,
              TotalF = Currencys.f_Format(CurrencyID, Total) ,
              TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
              ProfitRateF = Currencys.f_FormatRate(ProfitRate) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_ItemsPackage.ID );

      END;

      IF @RebuildColumn = 'Total Text'
      BEGIN

        UPDATE Items.t_ItemsPackage
          SET TotalAR = Currencys.f_ToWordAR(Total, CurrencyID, 1) ,
              TotalEN = Currencys.f_ToWordEN(Total, CurrencyID, 1) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_ItemsPackage.ID );

      END;

      IF @RebuildColumn = 'Items Informations'
      BEGIN

        UPDATE Items.t_ItemsPackage
          SET ItemsQtys = Items.f_ItemsPackageGetItemsQtysX(ID) ,
              ItemsCount = Items.f_ItemsPackageGetItemsCountX(ID) ,
              ItemsNames = Items.f_ItemsPackageGetItemsNamesX(ID) ,
              IsSync = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t_ItemsPackage.ID );

      END;

      IF @RebuildColumn = 'Order by'
      BEGIN

        EXECUTE Items.s_ItemsPackageUpdateReorderPART 0;

      END;

    END;

    BEGIN --Insert t_ItemsPackageMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemsPackageMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;
 
    EXECUTE Items.[s_ItemsPackageLiveVersion];

    COMMIT TRAN;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;











