CREATE PROCEDURE [Items].[s_ItemsPackageUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(450) ,
  @Barcode NVARCHAR(450) ,
  @BarcodeNumber BIGINT ,
  @ColorIs NVARCHAR(MAX) ,
  @ColorInt INT ,
  @ImageIs IMAGE ,
  @ImagePath NVARCHAR(MAX) ,
  @TargetType INT ,
  @TargetGeneralQuantity FLOAT ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TotalCost FLOAT ,
  @TotalCostF NVARCHAR(MAX) ,
  @TotalCostD FLOAT ,
