  @TotalCostEuro FLOAT ,
  @Subtotal FLOAT ,
  @SubtotalF NVARCHAR(MAX) ,
  @SubtotalD FLOAT ,
  @SubtotalLL FLOAT ,
  @SubtotalEuro FLOAT ,
  @NontaxableAmount FLOAT ,
