  @TotalEuro FLOAT ,
  @TotalProfit FLOAT ,
  @TotalProfitF NVARCHAR(MAX) ,
  @TotalProfitD FLOAT ,
  @TotalProfitLL FLOAT ,
  @TotalProfitEuro FLOAT ,
  @ProfitRate FLOAT ,
  @ProfitRateF NVARCHAR(MAX) ,
  @ShowImage BIT ,
  @FlowBreak BIT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @IsActive BIT ,
  @ItemsQtys FLOAT ,
  @ItemsCount INT ,
  @ItemsNames NVARCHAR(MAX) ,
  @ItemsPackageDetails Items.tt_ItemsPackageDetails READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @Return INT  = 0;

    END;

    BEGIN --Insert

      UPDATE Items.t_ItemsPackage
        SET Name = @Name ,
            Barcode = @Barcode ,
            BarcodeNumber = @BarcodeNumber ,
            ColorIs = @ColorIs ,
            ColorInt = @ColorInt ,
            ImageIs = @ImageIs ,
            ImagePath = @ImagePath ,
            TargetType = @TargetType ,
            TargetGeneralQuantity = @TargetGeneralQuantity ,
            CurrencyID = @CurrencyID ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
