            TaxableAmountD = @TaxableAmountD ,
            TaxableAmountLL = @TaxableAmountLL ,
            TaxableAmountEuro = @TaxableAmountEuro ,
            Taxes = @Taxes ,
            TaxesF = @TaxesF ,
            TaxesD = @TaxesD ,
            TaxesLL = @TaxesLL ,
            TaxesEuro = @TaxesEuro ,
            TaxesRate = @TaxesRate ,
            TaxesRateF = @TaxesRateF ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            TotalAR = @TotalAR ,
            TotalEN = @TotalEN ,
            TotalProfit = @TotalProfit ,
            TotalProfitF = @TotalProfitF ,
            TotalProfitD = @TotalProfitD ,
            TotalProfitLL = @TotalProfitLL ,
            TotalProfitEuro = @TotalProfitEuro ,
            ProfitRate = @ProfitRate ,
            ProfitRateF = @ProfitRateF ,
            ShowImage = @ShowImage ,
            FlowBreak = @FlowBreak ,
            DescriptionIs = @DescriptionIs ,
            IsActive = @IsActive ,
            ItemsQtys = @ItemsQtys ,
            ItemsCount = @ItemsCount ,
            ItemsNames = @ItemsNames ,
            IsSync = 0 ,
            IsSyncImage = IIF(@ImagePath = '', 0, 1)
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            1 ,
            'itemsPackageDetail'
          FROM Items.t_ItemsPackageDetails AS t
          WHERE t.ItemsPackageID = @ID
        EXCEPT
        SELECT t.ID ,
            1 ,
            'itemsPackageDetail'
          FROM @ItemsPackageDetails AS t;

    END;

    BEGIN --Delete t_ItemsPackageDetails

      DELETE FROM Items.t_ItemsPackageDetails
        WHERE ItemsPackageID = @ID;

    END;

    BEGIN --Insert t_ItemsPackageDetail

      INSERT INTO Items.t_ItemsPackageDetails
          ( ID ,
            ItemsPackageID ,
            ItemSharedID ,
            ItemID ,
            WarehouseID ,
            ItemUnitID ,
            Qty ,
            QtyWithUnit ,
            Qtys ,
            UnitCost ,
