/****** Object:  StoredProcedure [Items].[s_ItemsPackageUpdateOrderBy]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemsPackageUpdateOrderBy] @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDOrderByEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update 

      MERGE Items.t_ItemsPackage AS t
      USING @IDAndEvent AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.OrderBy = s.OrderBy ,
                    t.IsSync = 0;

      EXECUTE Items.s_ItemsPackageUpdateReorderPART 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemsPackageMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDAndEvent AS s;

    END;
	
    EXECUTE Items.s_ItemsPackageLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;














