AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDOld UNIQUEIDENTIFIER ,
        @OrderByOld BIGINT ,
        @OrderByNew BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OrderByOld = s.OrderBy
        FROM Items.t_ItemsPackage AS s
        WHERE s.ID = @ID;

      SELECT TOP ( 1 ) @OrderByNew = MAX(s.OrderBy)
        FROM Items.t_ItemsPackage AS s;
  
      IF @OrderByNew IS NULL
      BEGIN
                             
        RETURN 1;

      END;

      IF @OrderByOld = @OrderByNew
      BEGIN
                             
        RETURN 1;

      END;

      SELECT TOP ( 1 ) @IDOld = s.ID
        FROM Items.t_ItemsPackage AS s
        WHERE s.OrderBy = @OrderByNew;

    END;

    BEGIN --Update

      UPDATE Items.t_ItemsPackage
        SET OrderBy = @OrderByNew ,
            IsSync = 0
        WHERE ID = @ID;
 
      UPDATE Items.t_ItemsPackage
        SET OrderBy = @OrderByOld ,
            IsSync = 0
        WHERE ID = @IDOld;
		
      EXECUTE Items.s_ItemsPackageUpdateReorderPART 1;

    END;

    BEGIN --Insert t_ItemsPackageMoving

      DECLARE @Event2 NVARCHAR(MAX) = @Event;

      SET @Event = REPLACE(@Event, @OrderByOld, @OrderByNew);
      SET @Event2 = REPLACE(@Event2, @OrderByNew, @OrderByOld);

      SET @Return = -1;
      EXECUTE Items.s_ItemsPackageMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
      EXECUTE Items.s_ItemsPackageMovingInsertPART @IDOld, @UserID, @Event2, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
 
    END;

    EXECUTE Items.s_ItemsPackageLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





