/****** Object:  StoredProcedure [Items].[s_ItemsPackageUpdateReorderPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemsPackageUpdateReorderPART] @IsSync BIT
AS
BEGIN

  WITH  o AS ( SELECT s.OrderBy ,
                  ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy ,
                  s.IsSync
                FROM Items.t_ItemsPackage AS s
             )
    UPDATE o
      SET o.OrderBy = o.NewOrderBy ,
          o.IsSync = IIF(@IsSync = 0, 0, o.IsSync);
	
END;



