/****** Object:  StoredProcedure [Items].[s_ItemSubtabRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemSubtabRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild

      UPDATE Items.t_ItemSubtab
        SET ItemsCount = ( SELECT COUNT(*) AS Total
                            FROM Items.t_ItemSubtabDetail AS s
                            WHERE ( s.ItemSubtabID = t_ItemSubtab.ID )
                         ) ,
            IsSync = 0;
 
      WITH  o AS ( SELECT s.OrderBy ,
                      s.IsSync ,
                      ROW_NUMBER() OVER ( PARTITION BY s.ItemSubtabID ORDER BY s.OrderBy ) AS OrderBy_
                    FROM Items.t_ItemSubtabDetail AS s
                 )
        UPDATE o
          SET o.OrderBy = o.OrderBy_ ,
              o.IsSync = 1;

    END;

    BEGIN --Insert t_ItemSubtabMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSubtabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    EXECUTE Items.s_ItemSubtabLiveVersion;
    EXECUTE Items.s_ItemSubtabDetailLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




