            'itemSubtabDetail'
          FROM Items.t_ItemSubtabDetail AS t
          WHERE t.ItemSubtabID = @ID
        EXCEPT
        SELECT t.ID ,
            1 ,
            'itemSubtabDetail'
          FROM @ItemSubtabDetail AS t;

    END;

    BEGIN --Delete t_ItemSubtabDetail

      DELETE FROM Items.t_ItemSubtabDetail
        WHERE ItemSubtabID = @ID;

    END;

    BEGIN --Insert t_ItemSubtabDetail

      INSERT INTO Items.t_ItemSubtabDetail
