  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'itemTab' );
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            1 ,
            'itemTabDetail'
          FROM Items.t_ItemTabDetail AS t
          WHERE t.ItemTabID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Items.t_ItemTabDetail
        WHERE ItemTabID = @ID;

      DELETE FROM Items.t_ItemTab
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_ItemTabMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemTabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Items.s_ItemTabLiveVersion;
    EXECUTE Items.s_ItemTabDetailLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





