/****** Object:  StoredProcedure [Items].[s_ItemTabDeleteBySubtabPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemTabDeleteBySubtabPART] @Subtab UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @IDs AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

  END;

  BEGIN --Set Info
	  
    INSERT INTO @IDs
        ( ID
        )
      SELECT DISTINCT s.ItemTabID
        FROM Items.t_ItemTabDetail AS s
        WHERE s.TabTypeID = @Subtab;

  END;

  BEGIN --Update t_ItemTabDetail

    DELETE Items.t_ItemTabDetail
      WHERE TabTypeID = @Subtab AND TabType = 1;

  END;

  BEGIN --Rebuild Statistics

    UPDATE Items.t_ItemTab
      SET ItemsCount = ( SELECT COUNT(*) AS Total
                          FROM Items.t_ItemTabDetail AS s
                          WHERE ( ItemTabID = t_ItemTab.ID )
                       ) ,
          IsSync = 0
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_ItemTab.ID );
 
    DELETE FROM Items.t_ItemTab
      WHERE ItemsCount <= 0 AND EXISTS ( SELECT TOP ( 1 ) s.ID
                                          FROM @IDs AS s
                                          WHERE s.ID = t_ItemTab.ID );

  END;

  EXECUTE Items.s_ItemTabLiveVersion;
  EXECUTE Items.s_ItemTabDetailLiveVersion;
 
  EXECUTE Items.s_ItemSubtabLiveVersion;
  EXECUTE Items.s_ItemSubtabDetailLiveVersion;

END;



GO
