/****** Object:  StoredProcedure [Items].[s_ItemTabDetailLiveVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemTabDetailLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, ItemTabDetail, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;






