    END;

    BEGIN --Insert

      INSERT INTO Items.t_ItemTab
          ( ID ,
            Name ,
            ImageIs ,
            ImagePath ,
            DescriptionIs ,
            ItemsCount ,
            IsActive ,
            IsSyncImage
          )
        VALUES
          ( @ID ,
            @Name ,
            @ImageIs ,
            @ImagePath ,
            @DescriptionIs ,
            @ItemsCount ,
            @IsActive ,
            IIF(@ImagePath = '', 0, 1)
          );

    END;

    BEGIN --Insert t_ItemTabDetail

      INSERT INTO Items.t_ItemTabDetail
          ( ID ,
            ItemTabID ,
            TabType ,
            TabTypeID ,
            ItemUnityID ,
            Qty ,
            OrderBy ,
            ShowImage ,
            NameWithImage ,
            WithSalePrice ,
            WithWholesalePrice ,
            FlowBreak ,
            IsActive ,
            CreatedByUserID
          )
        SELECT t.ID ,
            t.ItemTabID ,
            t.TabType ,
            t.TabTypeID ,
            t.ItemUnityID ,
            t.Qty ,
            t.OrderBy ,
            t.ShowImage ,
            t.NameWithImage ,
            t.WithSalePrice ,
            t.WithWholesalePrice ,
            t.FlowBreak ,
            t.IsActive ,
            t.CreatedByUserID
          FROM @ItemTabDetail AS t;

    END;

    BEGIN --Insert t_ItemTabMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemTabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

