/****** Object:  StoredProcedure [Items].[s_ItemTabRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_ItemTabRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Items.t_ItemTab
        SET ItemsCount = ( SELECT COUNT(*) AS Total
                            FROM Items.t_ItemTabDetail AS s
                            WHERE ( ItemTabID = t_ItemTab.ID )
                         );

      WITH  o AS ( SELECT s.OrderBy ,
                      s.IsSync ,
                      ROW_NUMBER() OVER ( ORDER BY s.OrderBy, s.Name ) AS OrderBy_
                    FROM Items.t_ItemTab AS s
                 )
        UPDATE o
          SET o.OrderBy = o.OrderBy_ ,
              o.IsSync = 1;

      WITH  o AS ( SELECT s.OrderBy ,
                      s.IsSync ,
                      ROW_NUMBER() OVER ( PARTITION BY s.ItemTabID ORDER BY s.OrderBy, s.ID ) AS OrderBy_
                    FROM Items.t_ItemTabDetail AS s
                 )
        UPDATE o
          SET o.OrderBy = o.OrderBy_ ,
              o.IsSync = 1;
  
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemTabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;
	
    EXECUTE Items.s_ItemTabLiveVersion;
    EXECUTE Items.s_ItemTabDetailLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Items].[s_ItemTabUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemTabUpdate] @ID UNIQUEIDENTIFIER ,
  @Name NVARCHAR(MAX) ,
  @ImageIs IMAGE ,
  @ImagePath NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @IsActive BIT ,
  @ItemTabDetail Items.tt_ItemTabDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;

    BEGIN --Update

      UPDATE Items.t_ItemTab
        SET Name = @Name ,
            ImageIs = @ImageIs ,
            ImagePath = @ImagePath ,
            DescriptionIs = @DescriptionIs ,
            ItemsCount = @ItemsCount ,
            IsActive = @IsActive ,
            IsSync = 0 ,
            IsSyncImage = IIF(@ImagePath = '', 0, 1)
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete
  
      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT t.ID ,
            1 ,
            'itemTabDetail'
          FROM Items.t_ItemSubtabDetail AS t
          WHERE t.ItemSubtabID = @ID
        EXCEPT
        SELECT t.ID ,
            1 ,
            'itemTabDetail'
          FROM @ItemTabDetail AS t;

    END;

    BEGIN --Delete t_ItemTabDetail

      DELETE FROM Items.t_ItemTabDetail
        WHERE ItemTabID = @ID;

    END;

    BEGIN --Insert t_ItemTabDetail

      INSERT INTO Items.t_ItemTabDetail
          ( ID ,
            ItemTabID ,
            TabType ,
            TabTypeID ,
            ItemUnityID ,
            Qty ,
            OrderBy ,
            ShowImage ,
            NameWithImage ,
            WithSalePrice ,
            WithWholesalePrice ,
            FlowBreak ,
            IsActive ,
            CreatedByUserID
          )
        SELECT t.ID ,
            t.ItemTabID ,
            t.TabType ,
            t.TabTypeID ,
            t.ItemUnityID ,
            t.Qty ,
            t.OrderBy ,
            t.ShowImage ,
            t.NameWithImage ,
            t.WithSalePrice ,
            t.WithWholesalePrice ,
            t.FlowBreak ,
            t.IsActive ,
            t.CreatedByUserID
          FROM @ItemTabDetail AS t;

    END;

    BEGIN --Insert t_ItemTabMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemTabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Items.s_ItemTabLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;











