/****** Object:  StoredProcedure [Items].[s_ItemTabUpdateAddItemPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemTabUpdateAddItemPART] @ID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemUnitID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @OrderBy BIGINT;

  END;

  BEGIN --Set
	    
    SELECT TOP ( 1 ) @OrderBy = ISNULL(s.OrderBy, 1)
      FROM Items.t_ItemTabDetail AS s
      WHERE s.ItemTabID = @ID
      ORDER BY s.OrderBy DESC;

  END;

  BEGIN --Update t_ItemTab

    UPDATE Items.t_ItemTab
      SET ItemsCount += 1
      WHERE ID = @ID;

  END;

  BEGIN --Insert t_ItemTabDetail

    INSERT INTO Items.t_ItemTabDetail
        ( ItemTabID ,
          TabTypeID ,
          ItemUnityID ,
          OrderBy ,
          CreatedByUserID
        )
      VALUES
        ( @ID ,
          @ItemSharedID ,
          @ItemUnitID ,
          @OrderBy ,
          @UserID
        );

  END;

  EXECUTE Items.s_ItemTabLiveVersion;
  EXECUTE Items.s_ItemTabDetailLiveVersion;

END;
