/****** Object:  StoredProcedure [Items].[s_ItemTabUpdateOrderBy]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_ItemTabUpdateOrderBy] @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDOrderByEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Update 

      MERGE Items.t_ItemTab AS t
      USING @IDAndEvent AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.OrderBy = s.OrderBy ,
                    t.IsSync = 0;

      WITH  o AS ( SELECT s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy ,
                      s.IsSync
                    FROM Items.t_ItemTab AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy ,
              o.IsSync = 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemTabMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDAndEvent AS s;

    END;
	
    EXECUTE Items.s_ItemTabLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;













GO
/****** Object:  StoredProcedure [Items].[s_ItemTabUpdateOrderByDown]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Items].[s_ItemTabUpdateOrderByDown] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDOld UNIQUEIDENTIFIER ,
        @OrderByOld BIGINT ,
        @OrderByNew BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @OrderByOld = s.OrderBy
        FROM Items.t_ItemTab AS s
        WHERE s.ID = @ID;

      SELECT TOP ( 1 ) @IDOld = s.ID ,
          @OrderByNew = s.OrderBy
        FROM Items.t_ItemTab AS s
        WHERE s.OrderBy > @OrderByOld
        ORDER BY s.OrderBy;

      IF @OrderByNew IS NULL
      BEGIN
                             
        RETURN 1;

      END;

    END;

    BEGIN --Update

      UPDATE Items.t_ItemTab
        SET OrderBy = @OrderByNew ,
            IsSync = 0
        WHERE ID = @ID;
 
      UPDATE Items.t_ItemTab
        SET OrderBy = @OrderByOld ,
            IsSync = 0
        WHERE ID = @IDOld;

      WITH  o AS ( SELECT s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy
                    FROM Items.t_ItemTab AS s
                 )
        UPDATE o
          SET o.OrderBy = o.NewOrderBy;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      DECLARE @Event2 NVARCHAR(MAX) = @Event;

      SET @Event = REPLACE(@Event, @OrderByOld, @OrderByNew);
      SET @Event2 = REPLACE(@Event2, @OrderByNew, @OrderByOld);

      INSERT INTO Items.t_ItemTabMoving
          ( UserID, SectionID, EventIs, EventType, ComputerIP, Computer, ComputerAccount )
        VALUES  ( @UserID, @ID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount ),
                ( @UserID, @IDOld, @Event2, @EventType, @ComputerIP, @Computer, @ComputerAccount );
 
    END;

    EXECUTE Items.s_ItemTabLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



GO
