/****** Object:  StoredProcedure [Items].[s_ItemUpdateIsSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemUpdateIsSync]
    @IsSync BIT,
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

		DISABLE TRIGGER Items.tr_Item ON Items.t_Item;

        BEGIN --Insert

            UPDATE Items.t_Item
            SET IsSync = @IsSync
            WHERE ID = @ID;

        END;

		ENABLE TRIGGER Items.tr_Item ON Items.t_Item;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;











