/****** Object:  StoredProcedure [Items].[s_ItemUpdatesPlace]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_ItemUpdatesPlace] @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @Places Items.tt_ItemPlace READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge t_Item

      MERGE Items.t_Item AS t
      USING @Places AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.PlaceID = s.PlaceID ,
                    t.Place = Company.f_PlaceGetName(s.PlaceID);

    END;

    BEGIN --Update t_Item

      UPDATE Items.t_ItemShared
        SET PlacesNames = Alls.f_FixXML(( SELECT N', ' + t.Place AS [text()]
                                            FROM Items.t_Item AS t
                                            WHERE t.SharedID = t_ItemShared.ID
                                        FOR
                                          XML PATH('')
                                        ))
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @Places AS s
                        WHERE s.ItemSharedID = t_ItemShared.ID );

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ItemSharedID ,
            s.EventIs ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Places AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;

