/****** Object:  StoredProcedure [Items].[s_MainCategory_Updates_Printer]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_MainCategory_Updates_Printer] @IDs Alls.tt_IDOrderByEvent READONLY ,
  @Printer NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY
    
    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;
	
    BEGIN --Merge

      MERGE Items.t_MainCategory AS t
      USING @IDs AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET Printer = @Printer;

    END;

    SET @Return = -1;
    EXECUTE Items.s_MainCategoryMovingInsertsPART @IDs, @UserID, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    COMMIT TRANSACTION;

    SELECT 1;
	
  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    SELECT @Return;

  END CATCH;

END;




