/****** Object:  StoredProcedure [Items].[s_MainCategoryImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_MainCategoryImport] @WithImage BIT ,
  @drs Items.tt_MainCategory READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Items.t_MainCategory AS t
      USING @drs AS s
      ON s.Name = t.Name
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( Name ,
                 DescriptionIs ,
                 Printer ,
                 ProductionWhenSale ,
                 CRMEnabled ,
                 CRMFirstDatePeriod ,
                 CRMSecondDatePeriod ,
                 CRMThirdDatePeriod ,
                 ReportHeaderFooterID
               )
        VALUES ( Name ,
                 DescriptionIs ,
                 Printer ,
                 ProductionWhenSale ,
                 CRMEnabled ,
                 CRMFirstDatePeriod ,
                 CRMSecondDatePeriod ,
                 CRMThirdDatePeriod ,
                 ReportHeaderFooterID
               )
      WHEN MATCHED THEN
        UPDATE SET t.DescriptionIs = s.DescriptionIs ,
                    t.Printer = s.Printer ,
                    t.ProductionWhenSale = s.ProductionWhenSale ,
                    t.CRMEnabled = s.CRMEnabled ,
                    t.CRMFirstDatePeriod = s.CRMFirstDatePeriod ,
                    t.CRMSecondDatePeriod = s.CRMSecondDatePeriod ,
                    t.CRMThirdDatePeriod = s.CRMThirdDatePeriod ,
                    t.ReportHeaderFooterID = s.ReportHeaderFooterID;

    END;

    IF @WithImage = 1 --Merge Images
    BEGIN
                   
      MERGE Items.t_MainCategory AS t
      USING @drs AS s
      ON s.Name = t.Name
      WHEN MATCHED THEN
        UPDATE SET t.ImageIs = s.ImageIs ,
                    t.ImagePath = N'' ,
                    t.IsSyncImage = 0;

    END;

    BEGIN --Rebuild

      WITH  o AS ( SELECT s.SubCategoryC ,
                      ( SELECT COUNT(*) AS Total
                          FROM Items.t_SubCategory AS t
                          WHERE t.MainCategoryID = s.ID
                      ) AS SubCategoryC_ ,
                      s.OrderBy ,
                      ROW_NUMBER() OVER ( ORDER BY OrderBy , Name ) AS NewOrderBy
                    FROM Items.t_MainCategory AS s
                 )
        UPDATE o
          SET o.SubCategoryC = o.SubCategoryC_ ,
              o.OrderBy = o.NewOrderBy;

    END;

    BEGIN --Insert t_SubCategory

      INSERT INTO Items.t_SubCategory
          ( Name ,
            MainCategoryID
          )
        SELECT N'-' ,
            s.ID
          FROM Items.t_MainCategory AS s
          WHERE s.SubCategoryC = 0;

    END;

    BEGIN --Update t_MainCategory

      UPDATE Items.t_MainCategory
        SET SubCategoryC = 1
        WHERE SubCategoryC = 0;

    END;

    SET @Return = -1;
    EXECUTE Items.s_MainCategoryMovingInsertPART N'00000000-0000-0000-0000-000000000000', @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Items].[s_MainCategoryInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_MainCategoryInsert] @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ImageIs IMAGE ,
  @ImagePath NVARCHAR(MAX) ,
  @Printer NVARCHAR(MAX) ,
  @ProductionWhenSale BIT ,
  @ItemDiscountRateLevel1 FLOAT ,
  @ItemDiscountRateLevel2 FLOAT ,
  @ItemDiscountRateLevel3 FLOAT ,
  @ItemDiscountRateLevel4 FLOAT ,
  @ItemDiscountRateLevel5 FLOAT ,
  @ItemDiscountRateLevel6 FLOAT  ,
  @ItemDiscountRateLevel7  FLOAT ,
  @ItemDiscountRateLevel8  FLOAT ,
  @ItemDiscountRateLevel9  FLOAT ,
  @ItemDiscountRateLevel10  FLOAT ,
  @SubCategoryList NVARCHAR(MAX) ,
  @SubCategoryEvent NVARCHAR(MAX) ,
  @CRMEnabled BIT ,
  @CRMFirstDatePeriod INT ,
  @CRMSecondDatePeriod INT ,
  @CRMThirdDatePeriod INT ,
  @ReportHeaderFooterID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @SubCategory TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          Name NVARCHAR(MAX) NOT NULL
        );

      DECLARE @OrderBy INT ,
        @Return INT;

    END;

    BEGIN --Set Info
    
      SELECT @OrderBy = ISNULL(SUM(s.OrderBy), 0) + 1
        FROM Items.t_MainCategory AS s;

    END;

    BEGIN --Insert

      SET @Return = 0;

      INSERT INTO Items.t_MainCategory
          ( ID ,
            Name ,
            DescriptionIs ,
            ImageIs ,
            ImagePath ,
            IsSyncImage ,
            Printer ,
            ProductionWhenSale ,
            ItemDiscountRateLevel1 ,
            ItemDiscountRateLevel2 ,
            ItemDiscountRateLevel3 ,
            ItemDiscountRateLevel4 ,
            ItemDiscountRateLevel5 ,
            ItemDiscountRateLevel6 ,
            ItemDiscountRateLevel7 ,
            ItemDiscountRateLevel8 ,
            ItemDiscountRateLevel9 ,
            ItemDiscountRateLevel10 ,
            CRMEnabled ,
            CRMFirstDatePeriod ,
            CRMSecondDatePeriod ,
            CRMThirdDatePeriod ,
            ReportHeaderFooterID ,
            OrderBy
          )
        VALUES
          ( @ID ,
            @Name ,
            @DescriptionIs ,
            @ImageIs ,
            @ImagePath ,
            IIF(@ImagePath = N'', 0, 1) ,
            @Printer ,
            @ProductionWhenSale ,
            @ItemDiscountRateLevel1 ,
            @ItemDiscountRateLevel2 ,
            @ItemDiscountRateLevel3 ,
            @ItemDiscountRateLevel4 ,
            @ItemDiscountRateLevel5 ,
            @ItemDiscountRateLevel6 ,
            @ItemDiscountRateLevel7 ,
            @ItemDiscountRateLevel8 ,
            @ItemDiscountRateLevel9 ,
            @ItemDiscountRateLevel10 ,
            @CRMEnabled ,
            @CRMFirstDatePeriod ,
            @CRMSecondDatePeriod ,
            @CRMThirdDatePeriod ,
            @ReportHeaderFooterID ,
            @OrderBy
          );

    END;

    BEGIN --Insert t_SubCategory

      SET @SubCategoryList = [Alls].[f_GetOneAtLess](@SubCategoryList);

      INSERT INTO Items.t_SubCategory
          ( Name ,
            MainCategoryID 
          )
        OUTPUT Inserted.ID ,
          Inserted.Name
          INTO @SubCategory ( ID, Name )
        SELECT s.Name ,
            @ID
          FROM Alls.CastArrayToListString(@SubCategoryList) AS s;

    END;

    BEGIN --Rebuild t_MainCategory
    
      UPDATE Items.t_MainCategory
        SET SubCategoryC = ( SELECT COUNT(*) AS Total
                              FROM Items.t_SubCategory AS s
                              WHERE s.MainCategoryID = t_MainCategory.ID
                           )
        WHERE t_MainCategory.ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_MainCategoryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Insert Event t_SubCategory

      INSERT INTO Items.t_SubCategoryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @SubCategoryEvent + s.Name ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @SubCategory AS s;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
