SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_MainCategoryUpdate] @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ImageIs IMAGE ,
  @ImagePath NVARCHAR(MAX) ,
  @Printer NVARCHAR(MAX) ,
  @ProductionWhenSale BIT ,
  @ItemDiscountRateLevel1 FLOAT ,
  @ItemDiscountRateLevel2 FLOAT ,
  @ItemDiscountRateLevel3 FLOAT ,
  @ItemDiscountRateLevel4 FLOAT ,
  @ItemDiscountRateLevel5 FLOAT ,
  @ItemDiscountRateLevel6 FLOAT ,
  @ItemDiscountRateLevel7 FLOAT ,
  @ItemDiscountRateLevel8 FLOAT ,
  @ItemDiscountRateLevel9 FLOAT ,
  @ItemDiscountRateLevel10 FLOAT ,
  @CRMEnabled BIT ,
  @CRMFirstDatePeriod INT ,
  @CRMSecondDatePeriod INT ,
  @CRMThirdDatePeriod INT ,
  @ReportHeaderFooterID UNIQUEIDENTIFIER ,
  @IsSyncImage BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0 ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Items.t_MainCategory AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      UPDATE Items.t_MainCategory
        SET Name = @Name ,
            DescriptionIs = @DescriptionIs ,
            ImageIs = @ImageIs ,
            ImagePath = @ImagePath ,
            IsSyncImage = @IsSyncImage ,
            Printer = @Printer ,
            ProductionWhenSale = @ProductionWhenSale ,
            ItemDiscountRateLevel1 = @ItemDiscountRateLevel1 ,
            ItemDiscountRateLevel2 = @ItemDiscountRateLevel2 ,
            ItemDiscountRateLevel3 = @ItemDiscountRateLevel3 ,
            ItemDiscountRateLevel4 = @ItemDiscountRateLevel4 ,
            ItemDiscountRateLevel5 = @ItemDiscountRateLevel5 ,
            ItemDiscountRateLevel6 = @ItemDiscountRateLevel6 ,
            ItemDiscountRateLevel7 = @ItemDiscountRateLevel7 ,
            ItemDiscountRateLevel8 = @ItemDiscountRateLevel8 ,
            ItemDiscountRateLevel9 = @ItemDiscountRateLevel9 ,
            ItemDiscountRateLevel10 = @ItemDiscountRateLevel10 ,
            CRMEnabled = @CRMEnabled ,
            CRMFirstDatePeriod = @CRMFirstDatePeriod ,
            CRMSecondDatePeriod = @CRMSecondDatePeriod ,
            CRMThirdDatePeriod = @CRMThirdDatePeriod ,
            ReportHeaderFooterID = @ReportHeaderFooterID
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_MainCategoryMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Fix ItemShared

        UPDATE Items.t_ItemShared
          SET MainCategory = @Name
          WHERE MainCategoryID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



