/****** Object:  StoredProcedure [Items].[s_MainCategoryUpdateOrderBy]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_MainCategoryUpdateOrderBy]
  @UserID UNIQUEIDENTIFIER ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @IDAndEvent Alls.tt_IDOrderByEvent READONLY
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Update 

      SET @Return = 0;

      MERGE Items.t_MainCategory AS t
      USING @IDAndEvent AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET
               t.OrderBy = s.OrderBy;

      WITH  o AS ( SELECT s.OrderBy ,
                          ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy
                   FROM   Items.t_MainCategory AS s
                 )
        UPDATE  o
        SET     o.OrderBy = o.NewOrderBy;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Items.t_MainCategoryMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      SELECT  @UserID ,
              s.ID ,
              s.EventIs ,
              @EventType ,
              @ComputerIP ,
              @Computer ,
              @ComputerAccount
      FROM    @IDAndEvent AS s;

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  @Return;

  END CATCH;

END;











