/****** Object:  StoredProcedure [Items].[s_MainCategoryUpdateOrderByDown]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_MainCategoryUpdateOrderByDown]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDOld UNIQUEIDENTIFIER ,
        @OrderByOld BIGINT ,
        @OrderByNew BIGINT ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 )
              @OrderByOld = s.OrderBy
      FROM    Items.t_MainCategory AS s
      WHERE   s.ID = @ID;

      SELECT TOP ( 1 )
              @IDOld = s.ID ,
              @OrderByNew = s.OrderBy
      FROM    Items.t_MainCategory AS s
      WHERE   s.OrderBy > @OrderByOld
      ORDER BY s.OrderBy;

      IF @OrderByNew IS NULL
      BEGIN
                             
        RETURN 1;

      END;

    END;

    BEGIN --Update

      UPDATE  Items.t_MainCategory
      SET     OrderBy = @OrderByNew
      WHERE   ID = @ID;
 
      UPDATE  Items.t_MainCategory
      SET     OrderBy = @OrderByOld
      WHERE   ID = @IDOld;

      WITH  o AS ( SELECT s.OrderBy ,
                          ROW_NUMBER() OVER ( ORDER BY s.OrderBy ) AS NewOrderBy
                   FROM   Items.t_MainCategory AS s
                 )
        UPDATE  o
        SET     o.OrderBy = o.NewOrderBy;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      DECLARE @Event2 NVARCHAR(MAX) = @Event;

      SET @Event = REPLACE(@Event, @OrderByOld, @OrderByNew);
      SET @Event2 = REPLACE(@Event2, @OrderByNew, @OrderByOld);

      INSERT  INTO Items.t_MainCategoryMoving
              ( UserID, SectionID, EventIs, EventType, ComputerIP, Computer, ComputerAccount )
      VALUES  ( @UserID, @ID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount ),
              ( @UserID, @IDOld, @Event2, @EventType, @ComputerIP, @Computer, @ComputerAccount );
 
    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;

