/****** Object:  StoredProcedure [Items].[s_StockAdjustmentDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockAdjustmentDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @LinkType INT ,
        @LinkID UNIQUEIDENTIFIER ,
        @LinkRefF NVARCHAR(MAX) ,
        @Return INT = 0;

    END;

    BEGIN --Set
    
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_StockAdjustmentDetail AS s
          WHERE s.StockAdjustmentID = @ID;

      SELECT TOP ( 1 ) @LinkType = t.LinkType ,
          @LinkID = t.LinkID ,
          @LinkRefF = t.LinkRefF
        FROM Items.t_StockAdjustment AS t
        WHERE t.ID = @ID;

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID ,
            HasImage ,
            TableName
          )
        SELECT @ID ,
            0 ,
            'stockAdjustment'
        UNION ALL
        SELECT s.ID ,
            0 ,
            'stockAdjustmentDetail'
          FROM Items.t_StockAdjustmentDetail AS s
          WHERE s.StockAdjustmentID = @ID
        UNION ALL
        SELECT s.ID ,
            0 ,
            'stockAdjustmentDetailSerial'
          FROM Items.t_StockAdjustmentDetailSerial AS s
          WHERE s.StockAdjustmentID = @ID;

    END;

    EXECUTE Items.s_StockAdjustmentDetailExpirationDateDeletePART @ID;
	
    BEGIN --Delete

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Items.t_StockAdjustmentDetailSerial AS s
                        WHERE s.SerialID = t_ItemSerial.ID );

      DELETE FROM Items.t_StockAdjustmentDetailSerial
        WHERE StockAdjustmentID = @ID;

      DELETE FROM Items.t_ItemSerial
        WHERE SectionType = 7 AND LinkID = @ID;

      DELETE FROM Items.t_StockAdjustmentDetail
        WHERE StockAdjustmentID = @ID;

      DELETE FROM Items.t_StockAdjustment
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_StockAdjustmentMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

    EXECUTE Items.s_StockAdjustmentLiveVersion;
	
    --Delete t_Sold
    IF @LinkType = 1
    BEGIN

      EXECUTE Invoices.s_SoldDelete @UserID, --
        @LinkRefF, -- @Event
        @EventType, --
        @ComputerIP, -- 
        @Computer, -- 
        @ComputerAccount, --
        @ID = @LinkID; -- @ID
						 
    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













GO
/****** Object:  StoredProcedure [Items].[s_StockAdjustmentDetailExpirationDateDeletePART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockAdjustmentDetailExpirationDateDeletePART] @ID UNIQUEIDENTIFIER
AS
BEGIN

  BEGIN --Declare

    DECLARE @t_In AS  TABLE
      (
        Ref BIGINT NOT NULL ,
        RefF NVARCHAR(MAX) NOT NULL ,
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );
     
    DECLARE @t_Out AS  TABLE
      (
        ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
        ItemID UNIQUEIDENTIFIER NOT NULL ,
        WareHouseID UNIQUEIDENTIFIER NOT NULL ,
        PlaceID UNIQUEIDENTIFIER NOT NULL ,
        Barcode NVARCHAR(MAX) NOT NULL ,
        Qtys FLOAT NOT NULL ,
        ProductionDate DATE NOT NULL ,
        ExpirationDate DATE NOT NULL ,
        NotifyMeDaysBefore INT NOT NULL ,
        NotificationDate DATE NOT NULL ,
        CurrencyID UNIQUEIDENTIFIER NOT NULL ,
        Price FLOAT NOT NULL ,
        BatchNumber NVARCHAR(MAX) NOT NULL ,
        DescriptionIs NVARCHAR(MAX) NOT NULL
      );
 
    DECLARE @Ref BIGINT = Items.f_ItemExpirationDateGetNewRef() - 1;

  END;

  BEGIN --Set In
   
    INSERT INTO @t_In
        ( Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT @Ref + ROW_NUMBER() OVER ( ORDER BY ( SELECT 1
                                                 ) ) ,
          N'' ,
          t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(0 - t.Qtys), 0) ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Items.t_StockAdjustmentDetailExpirationDate AS t
        WHERE t.StockAdjustmentID = @ID AND t.Qtys < 0
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

    UPDATE @t_In
      SET RefF = FORMAT(Ref, '#');

  END;  
  
  BEGIN --Set Out
   
    INSERT INTO @t_Out
        ( ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
          NotificationDate ,
          CurrencyID ,
          Price ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          ISNULL(SUM(0 - t.Qtys), 0) ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs
        FROM Items.t_StockAdjustmentDetailExpirationDate AS t
        WHERE t.StockAdjustmentID = @ID AND t.Qtys > 0
        GROUP BY t.ItemSharedID ,
          t.ItemID ,
          t.WareHouseID ,
          t.PlaceID ,
          t.Barcode ,
          t.ProductionDate ,
          t.ExpirationDate ,
          t.NotifyMeDaysBefore ,
          t.NotificationDate ,
          t.CurrencyID ,
          t.Price ,
          t.BatchNumber ,
          t.DescriptionIs; 

  END;  

  BEGIN --Delete t_StockAdjustmentDetailExpirationDate

    DELETE FROM Items.t_StockAdjustmentDetailExpirationDate
      WHERE StockAdjustmentID = @ID;

  END;
  
  BEGIN --Merge t_ItemExpirationDate In
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t_In AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( Ref ,
               RefF ,
               ItemSharedID ,
               ItemID ,
               WareHouseID ,
               WareHouse ,
               PlaceID ,
               Place ,
               SectionIs ,
               SectionID ,
               Barcode ,
               Qtys ,
               ProductionDate ,
               ExpirationDate ,
               NotifyMeDaysBefore ,
               NotificationDate ,
               CurrencyID ,
               Currency ,
               Price ,
               PriceF ,
               PriceD ,
               PriceLL ,
               PriceEuro ,
               BatchNumber ,
               DescriptionIs
             )
      VALUES ( s.Ref ,
               s.RefF ,
               s.ItemSharedID ,
               s.ItemID ,
               s.WareHouseID ,
               Company.f_WareHouseGetName(s.WareHouseID) ,
               s.PlaceID ,
               Company.f_PlaceGetName(s.PlaceID) ,
               158 ,
               @ID ,
               s.Barcode ,
               s.Qtys ,
               s.ProductionDate ,
               s.ExpirationDate ,
               s.NotifyMeDaysBefore ,
               s.NotificationDate ,
               s.CurrencyID ,
               Currencys.f_CurrencyGetName(s.CurrencyID) ,
               s.Price ,
               Currencys.f_Format(s.CurrencyID, s.Price) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateLL() ,
               s.Price / Currencys.f_CurrencyGetExchangeRate(s.CurrencyID) * Currencys.f_CurrencyGetExchangeRateEuro() ,
               s.BatchNumber ,
               s.DescriptionIs
             )
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  BEGIN --Merge t_ItemExpirationDate Out
    
    MERGE Items.t_ItemExpirationDate AS t
    USING @t_Out AS s
    ON s.ItemSharedID = t.ItemSharedID AND s.ItemID = t.ItemID AND s.PlaceID = t.PlaceID AND s.Barcode = t.Barcode AND s.ProductionDate = t.ProductionDate AND s.ExpirationDate = t.ExpirationDate AND s.NotifyMeDaysBefore = t.NotifyMeDaysBefore AND s.NotificationDate = t.NotificationDate AND s.CurrencyID = t.CurrencyID AND s.Price = t.Price AND s.BatchNumber = t.BatchNumber AND s.DescriptionIs = t.DescriptionIs
    WHEN MATCHED THEN
      UPDATE SET t.Qtys += s.Qtys;

  END;

  EXECUTE Items.s_ItemExpirationDateCleanPART;	
  	
END;



GO
