  BEGIN --Delete Old
    
    DELETE FROM Items.t_StockAdjustmentDetailExpirationDate
      WHERE StockAdjustmentID = @ID;

  END;

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @ItemExpirationDate AS s )
  BEGIN
   
    RETURN;

  END;

  BEGIN --Declare

    DECLARE @t_In AS  TABLE
      (
        Ref BIGINT NOT NULL ,
