          PriceD ,
          PriceLL ,
          PriceEuro ,
          BatchNumber ,
          DescriptionIs
        )
      SELECT s.ID ,
          s.ID ,
          s.FatherID1 ,
          s.FatherID2 ,
          s.ItemSharedID ,
          s.ItemID ,
          s.WareHouseID ,
          s.PlaceID ,
          158 ,
          @ID ,
          s.Barcode ,
          s.Qtys ,
          s.ProductionDate ,
