          s.PriceLL ,
          s.PriceEuro ,
          s.BatchNumber ,
          s.DescriptionIs
        FROM @ItemExpirationDate AS s;

  END;
  
  BEGIN --Set In
   
    INSERT INTO @t_In
        ( Ref ,
          RefF ,
          ItemSharedID ,
          ItemID ,
          WareHouseID ,
          PlaceID ,
          Barcode ,
          Qtys ,
          ProductionDate ,
          ExpirationDate ,
          NotifyMeDaysBefore ,
