CREATE PROCEDURE [Items].[s_StockAdjustmentInsertPART] @ID UNIQUEIDENTIFIER ,
  @LinkType INT ,
  @LinkID UNIQUEIDENTIFIER ,
  @LinkRef BIGINT ,
  @LinkRefF NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @ReasonStockAdjustmentID UNIQUEIDENTIFIER ,
  @ReasonStockAdjustment NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @TotalQtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @Warehouses NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @DetailIs Items.[tt_StockAdjustmentDetail] READONLY ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @DetailIs AS s )
  BEGIN
   
    RETURN 1;

  END;

  BEGIN --Declare
	
    DECLARE @ItemQtys AS Items.ItemAppendQtys;

    DECLARE @Ref BIGINT ,
      @RefF NVARCHAR(MAX) ,
      @DM DATE = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
      @DY DATE = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
      @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
      @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
      @return INT = 0;

  END;

  BEGIN --Set info

    SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
      FROM Items.t_StockAdjustment AS s;

    SET @RefF = FORMAT(@Ref, '#');

    INSERT INTO @ItemQtys
        ( ID ,
          SharedID ,
          Qty
        )
      SELECT s.ItemID ,
          s.ItemSharedID ,
          s.Qtys
        FROM @DetailIs AS s;

  END;

  BEGIN --Insert

    INSERT INTO Items.t_StockAdjustment
        ( ID ,
          Ref ,
          RefF ,
          LinkType ,
          LinkID ,
          LinkRef ,
          LinkRefF ,
          DateIs ,
          DateOnly ,
          DateMonthly ,
          DateYearly ,
          ReasonStockAdjustmentID ,
          ReasonStockAdjustment ,
          UserID ,
          UserIs ,
          CurrencyID ,
          Currency ,
          CurrencyType ,
          ExchangeRateLL ,
          ExchangeRateEuro ,
          Total ,
          TotalF ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          TotalAR ,
          TotalEN ,
          TotalQtys ,
          DescriptionIs ,
          Warehouses ,
          ItemsNames
        )
      VALUES
        ( @ID ,
          @Ref ,
          @RefF ,
          @LinkType ,
          @LinkID ,
          @LinkRef ,
          @LinkRefF ,
          @DateIs ,
          @DateIs ,
          @DM ,
          @DY ,
          @ReasonStockAdjustmentID ,
          @ReasonStockAdjustment ,
          @UserID ,
          @UserIs ,
          @CurrencyID ,
          @Currency ,
          @CurrencyType ,
          @ExchangeRateLL ,
          @ExchangeRateEuro ,
          @Total ,
          @TotalF ,
          @TotalD ,
          @TotalLL ,
          @TotalEuro ,
          @TotalAR ,
          @TotalEN ,
          @TotalQtys ,
          @DescriptionIs ,
          @Warehouses ,
          @ItemsNames
        );

  END;

  BEGIN --Insert t_StockAdjustmentDetail

    INSERT INTO Items.t_StockAdjustmentDetail
        ( ID ,
          StockAdjustmentID ,
          ItemSharedID ,
          ItemID ,
          ItemUnityID ,
          Qty ,
          QtyWithUnity ,
          Qtys ,
          Cost ,
          CostF ,
          CostD ,
          CostLL ,
          CostEuro ,
          Total ,
          TotalF ,
          TotalD ,
          TotalLL ,
          TotalEuro ,
          DescriptionIs ,
          SortAt
        )
      SELECT s.ID ,
          @ID ,
          s.ItemSharedID ,
          s.ItemID ,
          s.ItemUnityID ,
          s.Qty ,
          s.QtyWithUnity ,
          s.Qtys ,
          s.Cost ,
          s.CostF ,
          s.CostD ,
          s.CostLL ,
          s.CostEuro ,
          s.Total ,
          s.TotalF ,
          s.TotalD ,
          s.TotalLL ,
          s.TotalEuro ,
          s.DescriptionIs ,
          s.SortAt
        FROM @DetailIs AS s;

  END;

  BEGIN --Insert t_StockAdjustmentMoving

    SET @return = -1;

    INSERT INTO Items.t_StockAdjustmentMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      VALUES
        ( @UserID ,
          @ID ,
          @Event + N': ' + @RefF ,
          @EventType ,
          @ComputerIP ,
          @Computer ,
          @ComputerAccount
        );

  END;

	--Fix Item Qty
  EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;

  EXECUTE Items.s_StockAdjustmentLiveVersion;

END;






