/****** Object:  StoredProcedure [Items].[s_StockAdjustmentRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockAdjustmentRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild statistics

      UPDATE Items.t_StockAdjustment
        SET RefF = FORMAT(Ref, '#') ,
            ReasonStockAdjustment = Items.f_ReasonStockAdjustmentGetName(ReasonStockAdjustmentID) ,
            UserIs = Users.f_UserGetName(UserID) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            TotalAR = Currencys.f_ToWordAR(Total, CurrencyID, 1) ,
            TotalEN = Currencys.f_ToWordEN(Total, CurrencyID, 1) ,
            Warehouses = Alls.f_FixXML(( SELECT DISTINCT ', ' + t2.Name AS [text()]
                                          FROM Items.t_StockAdjustmentDetail AS t
                                          INNER JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                          INNER JOIN Company.t_WareHouse AS t2 ON t2.ID = t1.WareHouseID
                                          WHERE t.StockAdjustmentID = t_StockAdjustment.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_StockAdjustmentDetail AS t
                                          INNER JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.StockAdjustmentID = t_StockAdjustment.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            IsSync = 0;

      WITH  o AS ( SELECT s.Cost ,
                      s.CostF ,
                      s.Total ,
                      s.TotalF ,
                      s1.CurrencyID ,
                      s.Qty ,
                      s.Qtys ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity ,
                      s.IsSync
                    FROM Items.t_StockAdjustmentDetail AS s
                    INNER JOIN Items.t_StockAdjustment AS s1 ON s1.ID = s.StockAdjustmentID
                    INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    INNER JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE o
          SET o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost) ,
              o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
              o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity ,
              IsSync = 0;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_StockAdjustmentMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Items.s_StockAdjustmentLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;







GO
/****** Object:  StoredProcedure [Items].[s_StockAdjustmentUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
