GO


CREATE PROCEDURE [Items].[s_StockAdjustmentUpdate] @DateIs DATETIME ,
  @ReasonStockAdjustmentID UNIQUEIDENTIFIER ,
  @ReasonStockAdjustment NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @CurrencyType TINYINT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @TotalQtys DECIMAL(18, 6) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @Warehouses NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @DetailIs Items.[tt_StockAdjustmentDetail] READONLY ,
  @SerialIsIn Items.tt_ItemSerial READONLY ,
  @SerialIsOut Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @AutomaticallyUpdateCostAfterSave TINYINT ,
  @UpdateCostEventBase NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @DM DATE = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
        @DY DATE = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
        @ExchangeRate FLOAT = CASE @CurrencyType
                                WHEN 0 THEN 1
                                WHEN 1 THEN @ExchangeRateLL
                                ELSE @ExchangeRateEuro
                              END ,
        @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @return INT = 0;

    END;

    BEGIN --Set

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_StockAdjustmentDetail AS s
          WHERE s.StockAdjustmentID = @ID
        UNION ALL
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qtys
          FROM @DetailIs AS s;

    END;

    BEGIN --Update

      UPDATE Items.t_StockAdjustment
        SET DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = @DM ,
            DateYearly = @DY ,
            ReasonStockAdjustmentID = @ReasonStockAdjustmentID ,
            ReasonStockAdjustment = @ReasonStockAdjustment ,
            UserID = @UserID ,
            UserIs = @UserIs ,
            CurrencyID = @CurrencyID ,
            Currency = @Currency ,
            CurrencyType = @CurrencyType ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            TotalAR = @TotalAR ,
            TotalEN = @TotalEN ,
            TotalQtys = @TotalQtys ,
            DescriptionIs = @DescriptionIs ,
            Warehouses = @Warehouses ,
            ItemsNames = @ItemsNames
        WHERE ID = @ID;

    END;

    EXECUTE Items.s_StockAdjustmentDetailExpirationDateDeletePART @ID;

    BEGIN --Merge t_StockAdjustmentDetail

      MERGE Items.t_StockAdjustmentDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 StockAdjustmentID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 Cost ,
                 CostF ,
                 CostD ,
                 CostLL ,
                 CostEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.Qty ,
                 s.QtyWithUnity ,
                 s.Qtys ,
                 s.Cost ,
                 s.CostF ,
                 s.CostD ,
                 s.CostLL ,
                 s.CostEuro ,
                 s.Total ,
                 s.TotalF ,
                 s.TotalD ,
                 s.TotalLL ,
                 s.TotalEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemID = s.ItemID ,
                    t.ItemUnityID = s.ItemUnityID ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = s.QtyWithUnity ,
                    t.Qtys = s.Qtys ,
                    t.Cost = s.Cost ,
                    t.CostF = s.CostF ,
                    t.CostD = s.CostD ,
                    t.CostLL = s.CostLL ,
                    t.CostEuro = s.CostEuro ,
                    t.Total = s.Total ,
                    t.TotalF = s.TotalF ,
                    t.TotalD = s.TotalD ,
                    t.TotalLL = s.TotalLL ,
                    t.TotalEuro = s.TotalEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.StockAdjustmentID = @ID THEN
        DELETE;

    END;

    BEGIN --Insert t_ItemSerial

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            7 ,
            @ID
          FROM @SerialIsIn AS s;

    END;

    BEGIN --Insert t_StockAdjustmentDetailSerial

      INSERT INTO Items.t_StockAdjustmentDetailSerial
          ( StockAdjustmentID ,
            StockAdjustmentDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsIn AS s
        UNION ALL
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsOut AS s;

    END;

    BEGIN --Update t_ItemSerial

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIsOut AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
		
    EXECUTE Items.s_StockAdjustmentDetailUpdateSerialNamesPART @SerialIsIn;
    EXECUTE Items.s_StockAdjustmentDetailUpdateSerialNamesPART @SerialIsOut;

    EXECUTE Items.s_StockAdjustmentDetailExpirationDateInsertPART @ItemExpirationDate, @ID;
	
    BEGIN --Insert t_StockAdjustmentMoving

      SET @return = -1;

      INSERT INTO Items.t_StockAdjustmentMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--Fix Item Qty
    EXECUTE Items.s_ItemAppendQtysPART @ItemQtys;
	
    IF @AutomaticallyUpdateCostAfterSave > 0 --Update t_ItemShared (Items Cost)
    BEGIN 

      BEGIN --Declare

        DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;
    
      END;

      BEGIN --Set Info

        INSERT INTO @ItemShared
            ( ID ,
              CurrencyID ,
              OldCost ,
              Cost ,
              EventIs
            )
          SELECT s.ItemSharedID ,
              s1.CurrencyID ,
              s1.Purchase ,
              CASE s2.TypeIs
                WHEN 0 THEN ( s.Cost / s3.Qty ) / @ExchangeRate
                WHEN 1 THEN ( ( s.Cost / s3.Qty ) / @ExchangeRate ) * @ExchangeRateLL
                ELSE ( ( s.Cost / s3.Qty ) / @ExchangeRate ) * @ExchangeRateEuro
              END ,
              @UpdateCostEventBase + s1.PurchaseF
            FROM @DetailIs AS s
            INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
            INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
            INNER JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
            WHERE s.Cost > 0;

        DELETE FROM @ItemShared
          WHERE OldCost = Cost;
  
        DELETE FROM @ItemShared
          WHERE OldCost > 0 AND @AutomaticallyUpdateCostAfterSave = 1;

        UPDATE @ItemShared
          SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

      END;
  
      EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @UpdateCostEventBase, @ComputerIP, @Computer, @ComputerAccount;

    END;

    EXECUTE Items.s_StockAdjustmentLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;











