    BEGIN --Update

      UPDATE Items.t_StockAdjustment
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_StockAdjustment.ID );
 
      UPDATE Items.t_StockAdjustmentDetail
        SET IsSync = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
