/****** Object:  StoredProcedure [Items].[s_StockTakeDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_StockTakeDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
	      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      DECLARE @Return INT = 0;

    END;

    EXECUTE Items.s_StockTakeDetailExpirationDateDeletePART @ID;

    BEGIN --Delete

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 1
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM Items.t_StockTakeDetailSerial AS s
                        WHERE s.SerialID = t_ItemSerial.ID );

      DELETE FROM Items.t_StockTakeDetailSerial
        WHERE StockTakeID = @ID;

      DELETE FROM Items.t_ItemSerial
        WHERE SectionType = 101 AND LinkID = @ID;

      DELETE FROM Items.t_StockTakeDetail
        OUTPUT Deleted.ItemID ,
          Deleted.ItemSharedID ,
          0 - Deleted.Qtys
          INTO @ItemQtys
        WHERE StockTakeID = @ID;

      DELETE FROM Items.t_StockTake
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_StockTakeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;















