/****** Object:  StoredProcedure [Items].[s_StockTakeInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockTakeInsert] @DateIs DATETIME ,
  @TypeIs TINYINT ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @ReasonStockAdjustmentID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Items.[tt_StockTakeDetail] READONLY ,
  @SerialIsIn Items.tt_ItemSerial READONLY ,
  @SerialIsOut Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @AutomaticallyUpdateCostAfterSave TINYINT ,
  @UpdateCostEventBase NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Item AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          SharedID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL ,
          Total FLOAT NOT NULL ,
          TotalD FLOAT NOT NULL ,
          TotalLL FLOAT NOT NULL ,
          TotalEuro FLOAT NOT NULL
        );

      DECLARE @ItemQtyNet AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL
        );

      DECLARE @Ref BIGINT = Items.f_StockTakeGetNewRef();

      DECLARE @RefF NVARCHAR(MAX) = FORMAT(@Ref, '#') ,
        @DateOnly DATE = @DateIs ,
        @return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_StockTake
          ( ID ,
            Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            WarehouseID ,
            Warehouse ,
            ReasonStockAdjustmentID ,
            ReasonStockAdjustment ,
            UserID ,
            UserIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            DescriptionIs
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @TypeIs ,
            @DateIs ,
            @DateOnly ,
            DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            @WarehouseID ,
            Company.f_WareHouseGetName(@WarehouseID) ,
            @ReasonStockAdjustmentID ,
            Items.f_ReasonStockAdjustmentGetName(@ReasonStockAdjustmentID) ,
            @UserID ,
            Users.f_UserGetName(@UserID) ,
            @CurrencyID ,
            Currencys.f_CurrencyGetName(@CurrencyID) ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @DescriptionIs
          );

    END;

    BEGIN --Insert detail

      INSERT INTO Items.t_StockTakeDetail
          ( ID ,
            StockTakeID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            QtyCurrent ,
            QtyOnHand ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DescriptionIs ,
            SortAt
          )
        OUTPUT Inserted.ItemID ,
          Inserted.ItemSharedID ,
          Inserted.Qtys ,
          Inserted.Total ,
          Inserted.TotalD ,
          Inserted.TotalLL ,
          Inserted.TotalEuro
          INTO @Item
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.QtyCurrent ,
            s.QtyOnHand ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qty * s1.Qty ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

	--Insert t_ItemSerial in
    IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @SerialIsIn AS s )
    BEGIN 

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            101 ,
            @ID
          FROM @SerialIsIn AS s;

    END;
		
    BEGIN  --Insert t_StockTakeDetailSerial serial

      INSERT INTO Items.t_StockTakeDetailSerial
          ( StockTakeID ,
            StockTakeDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsIn AS s
        UNION ALL
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsOut AS s;

    END;

	--Update t_ItemSerial
    IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @SerialIsOut AS s )
    BEGIN 

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIsOut AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
		
    EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsIn;
    EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsOut;

    EXECUTE Items.s_StockTakeDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Rebuild statistics

      UPDATE Items.t_StockTake
        SET NetIs = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM @Item AS s
                    ) ,
            NetIsD = ( SELECT COALESCE(SUM(s.TotalD), 0)
                        FROM @Item AS s
                     ) ,
            NetIsLL = ( SELECT COALESCE(SUM(s.TotalLL), 0)
                          FROM @Item AS s
                      ) ,
            NetIsEuro = ( SELECT COALESCE(SUM(s.TotalEuro), 0)
                            FROM @Item AS s
                        ) ,
            Qtys = ( SELECT COALESCE(SUM(s.Qty), 0)
                      FROM @Item AS s
                   )
        WHERE ID = @ID;

      UPDATE Items.t_StockTake
        SET NetIsF = Currencys.f_Format(@CurrencyID, NetIs) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_StockTakeDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.StockTakeID = t_StockTake.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @ID;

    END;

    BEGIN--Item Qtys
   
      DECLARE @ItemQtys AS Items.ItemAppendQtys;

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ID ,
            s.SharedID ,
            s.Qty
          FROM @Item AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;


      BEGIN --Update t_Item LastStockTake
         
		  INSERT INTO @ItemQtyNet
          ( ID ,
            Qty
          )
        SELECT o.ID ,
            0
          FROM @ItemQtys AS o
          GROUP BY o.ID;

        MERGE Items.t_Item AS t
        USING @ItemQtyNet AS s
        ON s.ID = t.ID AND t.LastStockTakeDate < @DateOnly
        WHEN MATCHED THEN
          UPDATE SET t.LastStockTakeID = @ID ,
                      t.LastStockTakeRef = @Ref ,
                      t.LastStockTakeRefF = FORMAT(@Ref, '#') ,
                      t.LastStockTakeDate = @DateOnly ,
                      t.StockTakeEveryNotificationDate = CASE t.StockTakeEveryType
                                                           WHEN 2 THEN DATEADD(DAY, t.StockTakeEvery, @DateOnly)
                                                           WHEN 1 THEN DATEADD(MONTH, t.StockTakeEvery, @DateOnly)
                                                           ELSE DATEADD(YEAR, t.StockTakeEvery, @DateOnly)
                                                         END;

      END;


   -- IF @AutomaticallyUpdateCostAfterSave > 0 --Update t_ItemShared (Items Cost)
   -- BEGIN 

   --   BEGIN --Declare

   --     DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;
    
   --   END;

   --   BEGIN --Set Info

   --     INSERT INTO @ItemShared
   --         ( ID ,
   --           CurrencyID ,
   --           OldCost ,
   --           Cost ,
   --           EventIs
   --         )
   --       SELECT s.ItemSharedID ,
   --           s1.CurrencyID ,
   --           s1.Purchase ,
   --           CASE s2.TypeIs
   --             WHEN 0 THEN ( s.Price / s3.Qty ) / @ExchangeRate
   --             WHEN 1 THEN ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateLL
   --             ELSE ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateEuro
   --           END ,
   --           @UpdateCostEventBase + s1.PurchaseF
   --         FROM @DetailIs AS s
   --         INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
   --         INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
   --         INNER JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
			--WHERE s.Price > 0;

   --     DELETE FROM @ItemShared
   --       WHERE OldCost = Cost;
  
   --     DELETE FROM @ItemShared
   --       WHERE OldCost > 0 AND @AutomaticallyUpdateCostAfterSave = 1;

   --     UPDATE @ItemShared
   --       SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

   --   END;
  
   --   EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @UpdateCostEventBase, @ComputerIP, @Computer, @ComputerAccount;

   -- END;
      
    SET @return = -1;
    SET @Event += N': ' + @RefF;
    EXECUTE Items.s_StockTakeMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;


GO
/****** Object:  StoredProcedure [Items].[s_StockTakeInsert1]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockTakeInsert1] @ID UNIQUEIDENTIFIER ,
  @TypeIs TINYINT ,
  @DateIs DATETIME ,
  @DateOnly DATE ,
  @DateMonthly DATE ,
  @DateYearly DATE ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @Warehouse NVARCHAR(MAX) ,
  @ReasonStockAdjustmentID UNIQUEIDENTIFIER ,
  @ReasonStockAdjustment NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @TotalQtys FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @DetailIs Items.[tt_StockTakeDetail] READONLY ,
  @SerialIsIn Items.tt_ItemSerial READONLY ,
  @SerialIsOut Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @ItemQtys Items.tt_ItemQtys READONLY ,
  @ItemSharedQtys Items.tt_ItemSharedQtys READONLY ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Ref BIGINT = Items.f_StockTakeGetNewRef();

      DECLARE @RefF NVARCHAR(MAX) = FORMAT(@Ref, '#') ,
        @TotalAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@Total, @CurrencyID, 1) ,
        @TotalEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@Total, @CurrencyID, 1) ,
        @return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Items.t_StockTake
          ( ID ,
            Ref ,
            RefF ,
            TypeIs ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            WarehouseID ,
            Warehouse ,
            ReasonStockAdjustmentID ,
            ReasonStockAdjustment ,
            UserID ,
            UserIs ,
            CurrencyID ,
            Currency ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            Qtys ,
            DescriptionIs ,
            ItemsNames
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @TypeIs ,
            @DateIs ,
            @DateOnly ,
            @DateMonthly ,
            @DateYearly ,
            @WarehouseID ,
            @Warehouse ,
            @ReasonStockAdjustmentID ,
            @ReasonStockAdjustment ,
            @UserID ,
            @UserIs ,
            @CurrencyID ,
            @Currency ,
            @ExchangeRate ,
            @ExchangeRateLL ,
            @ExchangeRateEuro ,
            @Total ,
            @TotalF ,
            @TotalD ,
            @TotalLL ,
            @TotalEuro ,
            @TotalAR ,
            @TotalEuro ,
            @TotalQtys ,
            @DescriptionIs ,
            @ItemsNames
          );

    END;

    BEGIN --Insert t_StockTakeDetail

      INSERT INTO Items.t_StockTakeDetail
          ( ID ,
            StockTakeID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            QtyCurrent ,
            QtyOnHand ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            @ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.QtyCurrent ,
            s.QtyOnHand ,
            s.Qty ,
            Items.f_FormatQty(s.Qty) + ' ' + s2.Name ,
            s.Qty * s1.Qty ,
            s.Price ,
            Currencys.f_Format(@CurrencyID, s.Price) ,
            s.Price / @ExchangeRate ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
            s.Total ,
            Currencys.f_Format(@CurrencyID, s.Total) ,
            s.Total / @ExchangeRate ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
            ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s
          LEFT JOIN Items.t_UnityItem AS s1 ON s1.ID = s.ItemUnityID
          LEFT JOIN Items.t_Unity AS s2 ON s2.ID = s1.UnityID;

    END;

    BEGIN --Serials

	--Insert t_ItemSerial in
      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIsIn AS s )
      BEGIN 

        INSERT INTO Items.t_ItemSerial
            ( ID ,
              ItemSharedID ,
              ItemID ,
              SerialText ,
              SectionType ,
              LinkID
            )
          SELECT s.ID ,
              s.ItemSharedID ,
              s.ItemID ,
              s.SerialText ,
              101 ,
              @ID
            FROM @SerialIsIn AS s;

      END;
		
      BEGIN  --Insert t_StockTakeDetailSerial serial

        INSERT INTO Items.t_StockTakeDetailSerial
            ( StockTakeID ,
              StockTakeDetailID ,
              SerialID
            )
          SELECT @ID ,
              s.FatherID ,
              s.ID
            FROM @SerialIsIn AS s
          UNION ALL
          SELECT @ID ,
              s.FatherID ,
              s.ID
            FROM @SerialIsOut AS s;

      END;

	--Update t_ItemSerial
      IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIsOut AS s )
      BEGIN 

        UPDATE Items.t_ItemSerial
          SET IsAvailable = 0
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @SerialIsOut AS s
                          WHERE s.ID = t_ItemSerial.ID );

      END;
		
      EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsIn;
      EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsOut;

    END;

    EXECUTE Items.s_StockTakeDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Update t_Item LastStockTake
    
      MERGE Items.t_Item AS t
      USING @ItemQtys AS s
      ON s.ID = t.ID AND t.LastStockTakeDate < @DateOnly
      WHEN MATCHED THEN
        UPDATE SET t.LastStockTakeID = @ID ,
                    t.LastStockTakeRef = @Ref ,
                    t.LastStockTakeRefF = @RefF ,
                    t.LastStockTakeDate = @DateOnly ,
                    t.StockTakeEveryNotificationDate = CASE t.StockTakeEveryType
                                                         WHEN 2 THEN DATEADD(DAY, t.StockTakeEvery, @DateOnly)
                                                         WHEN 1 THEN DATEADD(MONTH, t.StockTakeEvery, @DateOnly)
                                                         ELSE DATEADD(YEAR, t.StockTakeEvery, @DateOnly)
                                                       END;

    END;

  	--Item Qtys
    EXECUTE Items.s_ItemAppendQtysPART2 @ItemQtys, @ItemSharedQtys;
     
    SET @return = -1;
    SET @Event += N': ' + @RefF;
    EXECUTE Items.s_StockTakeMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    SELECT @return;

  END CATCH;

END;


GO
/****** Object:  StoredProcedure [Items].[s_StockTakeLiveVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_StockTakeLiveVersion]
AS
BEGIN

  UPDATE Alls.t_LiveVersion
    SET VersionLive = STUFF(VersionLive, StockTake, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
        SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;



GO
/****** Object:  StoredProcedure [Items].[s_StockTakeMovingInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_StockTakeMovingInsert]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = -1;

    END;

    BEGIN --Insert event

      INSERT  INTO Items.t_StockTakeMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                3 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, StockTake, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

