/****** Object:  StoredProcedure [Items].[s_StockTakeRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockTakeRebuildingStatistics]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE  Items.t_StockTake
      SET     RefF = FORMAT(Ref, '#') ,
              Warehouse = Company.f_WareHouseGetName(WarehouseID) ,
              ReasonStockAdjustment = Items.f_ReasonStockAdjustmentGetName(ReasonStockAdjustmentID) ,
              UserIs = Users.f_UserGetName(UserID) ,
              Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
              NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
              NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
              NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
              ItemsNames = Alls.f_FixXML(( SELECT DISTINCT
                                                  ', ' + t1.Name AS [text()]
                                           FROM   Items.t_StockTakeDetail AS t
                                           LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                           WHERE  t.StockTakeID = t_StockTake.ID
                                         FOR
                                           XML PATH('')
                                         ));

      WITH  o AS ( SELECT s.Price ,
                          s.PriceF ,
                          s.Total ,
                          s.TotalF ,
                          s1.CurrencyID ,
                          s.Qty ,
                          s.Qtys ,
                          s.QtyWithUnity ,
                          s3.Name AS Unity
                   FROM   Items.t_StockTakeDetail AS s
                   LEFT JOIN Items.t_StockTake AS s1 ON s1.ID = s.StockTakeID
                   LEFT JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                   LEFT JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE  o
        SET     o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
                o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
                o.QtyWithUnity = Items.f_FormatQty(o.Qty) + ' ' + o.Unity;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Items.t_StockTakeMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                '00000000-0000-0000-0000-000000000000' ,
                @Event ,
                6 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, StockTake, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








