/****** Object:  StoredProcedure [Items].[s_StockTakeUnsavedMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_StockTakeUnsavedMerge] @ID UNIQUEIDENTIFIER ,
  @PCName NVARCHAR(MAX) ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @Warehouse NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @TotalCost FLOAT ,
  @TotalCostF NVARCHAR(MAX) ,
  @ItemsCount INT ,
  @Detail Items.tt_StockTakeUnsavedDetail READONLY
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Merge

      MERGE Items.t_StockTakeUnsaved AS t
      USING
        ( SELECT @ID AS ID
        ) AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 PCName ,
                 WarehouseID ,
                 Warehouse ,
                 UserID ,
                 UserIs ,
                 CurrencyID ,
                 Currency ,
                 ExchangeRate ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 TotalCost ,
                 TotalCostF ,
                 ItemsCount
               )
        VALUES ( @ID ,
                 @PCName ,
                 @WarehouseID ,
                 @Warehouse ,
                 @UserID ,
                 @UserIs ,
                 @CurrencyID ,
                 @Currency ,
                 @ExchangeRate ,
                 @ExchangeRateLL ,
                 @ExchangeRateEuro ,
                 @TotalCost ,
                 @TotalCostF ,
                 @ItemsCount
          
               )
      WHEN MATCHED THEN
        UPDATE SET t.PCName = @PCName ,
                    t.DateIs = GETDATE() ,
                    t.WarehouseID = @WarehouseID ,
                    t.Warehouse = @Warehouse ,
                    t.UserID = @UserID ,
                    t.UserIs = @UserIs ,
                    t.CurrencyID = @CurrencyID ,
                    t.Currency = @Currency ,
                    t.ExchangeRate = @ExchangeRate ,
                    t.ExchangeRateLL = @ExchangeRateLL ,
                    t.ExchangeRateEuro = @ExchangeRateEuro ,
                    t.TotalCost = @TotalCost ,
                    t.TotalCostF = @TotalCostF ,
                    t.ItemsCount = @ItemsCount;

    END;

    BEGIN --Reinsert t_StockTakeUnsavedDetail
	
      DELETE FROM Items.t_StockTakeUnsavedDetail
        WHERE StockTakeUnsavedID = @ID;

      INSERT Items.t_StockTakeUnsavedDetail
          ( ID ,
            StockTakeUnsavedID ,
            ItemSharedID ,
            ItemID ,
            ItemUnityID ,
            QtyOnHand ,
            UnitCost ,
            UnitCostF ,
            TotalCost ,
            TotalCostF ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            s.StockTakeUnsavedID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.ItemUnityID ,
            s.QtyOnHand ,
            s.UnitCost ,
            s.UnitCostF ,
            s.TotalCost ,
            s.TotalCostF ,
            s.DescriptionIs ,
            s.SortAt
          FROM @Detail AS s;

    END;

    EXECUTE Items.s_StockTakeUnsavedLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Items].[s_StockTakeUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_StockTakeUpdate] @DateIs DATETIME ,
  @TypeIs TINYINT ,
  @WarehouseID UNIQUEIDENTIFIER ,
  @ReasonStockAdjustmentID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DetailIs Items.[tt_StockTakeDetail] READONLY ,
  @SerialIsIn Items.tt_ItemSerial READONLY ,
  @SerialIsOut Items.tt_ItemSerial READONLY ,
  @ItemExpirationDate [Items].tt_ItemExpirationDate READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @AutomaticallyUpdateCostAfterSave TINYINT ,
  @UpdateCostEventBase NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Item AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          SharedID UNIQUEIDENTIFIER NOT NULL ,
          ItemID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL ,
          Total FLOAT NOT NULL ,
          TotalD FLOAT NOT NULL ,
          TotalLL FLOAT NOT NULL ,
          TotalEuro FLOAT NOT NULL
        );

      DECLARE @ItemQtys AS Items.ItemAppendQtys;
     
      DECLARE @ItemQtyNet AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @DateOnly DATE = @DateIs ,
        @return INT;

    END;

    BEGIN --Set info

      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            0 - s.Qtys
          FROM Items.t_StockTakeDetail AS s
          WHERE s.StockTakeID = @ID;

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @RefF = s.RefF
        FROM Items.t_StockTake AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      SET @return = 0;

      UPDATE Items.t_StockTake
        SET TypeIs = @TypeIs ,
            DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            WarehouseID = @WarehouseID ,
            Warehouse = Company.f_WareHouseGetName(@WarehouseID) ,
            ReasonStockAdjustmentID = @ReasonStockAdjustmentID ,
            ReasonStockAdjustment = Items.f_ReasonStockAdjustmentGetName(@ReasonStockAdjustmentID) ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    EXECUTE Items.s_StockTakeDetailExpirationDateDeletePART @ID;

    BEGIN --Insert detail

      MERGE Items.t_StockTakeDetail AS t
      USING @DetailIs AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 StockTakeID ,
                 ItemSharedID ,
                 ItemID ,
                 ItemUnityID ,
                 QtyCurrent ,
                 QtyOnHand ,
                 Qty ,
                 QtyWithUnity ,
                 Qtys ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 PriceLL ,
                 PriceEuro ,
                 Total ,
                 TotalF ,
                 TotalD ,
                 TotalLL ,
                 TotalEuro ,
                 DescriptionIs ,
                 SortAt
               )
        VALUES ( s.ID ,
                 @ID ,
                 s.ItemSharedID ,
                 s.ItemID ,
                 s.ItemUnityID ,
                 s.QtyCurrent ,
                 s.QtyOnHand ,
                 s.Qty ,
                 Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                 s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.Total ,
                 Currencys.f_Format(@CurrencyID, s.Total) ,
                 s.Total / @ExchangeRate ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                 ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                 s.DescriptionIs ,
                 s.SortAt
               )
      WHEN MATCHED THEN
        UPDATE SET t.ItemID = s.ItemID ,
                    t.ItemUnityID = s.ItemUnityID ,
                    t.QtyCurrent = s.QtyCurrent ,
                    t.QtyOnHand = s.QtyOnHand ,
                    t.Qty = s.Qty ,
                    t.QtyWithUnity = Items.f_FormatQty(s.Qty) + ' ' + Items.f_UnityItemGetName(s.ItemUnityID) ,
                    t.Qtys = s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID) ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.PriceLL = ( s.Price / @ExchangeRate ) * @ExchangeRateLL ,
                    t.PriceEuro = ( s.Price / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.Total = s.Total ,
                    t.TotalF = Currencys.f_Format(@CurrencyID, s.Total) ,
                    t.TotalD = s.Total / @ExchangeRate ,
                    t.TotalLL = ( s.Total / @ExchangeRate ) * @ExchangeRateLL ,
                    t.TotalEuro = ( s.Total / @ExchangeRate ) * @ExchangeRateEuro ,
                    t.DescriptionIs = s.DescriptionIs ,
                    t.SortAt = s.SortAt
      WHEN NOT MATCHED BY SOURCE AND t.StockTakeID = @ID THEN
        DELETE;

      INSERT INTO @Item
          ( ID ,
            SharedID ,
            ItemID ,
            Qty ,
            Total ,
            TotalD ,
            TotalLL ,
            TotalEuro
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.Qtys ,
            s.Total ,
            s.TotalD ,
            s.TotalLL ,
            s.TotalEuro
          FROM Items.t_StockTakeDetail AS s
          WHERE s.StockTakeID = @ID;

    END;

    BEGIN --Insert serial in

      INSERT INTO Items.t_ItemSerial
          ( ID ,
            ItemSharedID ,
            ItemID ,
            SerialText ,
            SectionType ,
            LinkID
          )
        SELECT s.ID ,
            s.ItemSharedID ,
            s.ItemID ,
            s.SerialText ,
            101 ,
            @ID
          FROM @SerialIsIn AS s;

    END;

    BEGIN --Insert detial serial

      INSERT INTO Items.t_StockTakeDetailSerial
          ( StockTakeID ,
            StockTakeDetailID ,
            SerialID
          )
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsIn AS s
        UNION ALL
        SELECT @ID ,
            s.FatherID ,
            s.ID
          FROM @SerialIsOut AS s;

    END;

    BEGIN --Update item serial out

      UPDATE Items.t_ItemSerial
        SET IsAvailable = 0
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @SerialIsOut AS s
                        WHERE s.ID = t_ItemSerial.ID );

    END;
		
    EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsIn;
    EXECUTE Items.s_StockTakeDetailUpdateSerialNamesPART @SerialIsOut;
  
    EXECUTE Items.s_StockTakeDetailExpirationDateInsertPART @ItemExpirationDate, @ID;

    BEGIN --Rebuild statistics

      UPDATE Items.t_StockTake
        SET NetIs = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM @Item AS s
                    ) ,
            NetIsD = ( SELECT COALESCE(SUM(s.TotalD), 0)
                        FROM @Item AS s
                     ) ,
            NetIsLL = ( SELECT COALESCE(SUM(s.TotalLL), 0)
                          FROM @Item AS s
                      ) ,
            NetIsEuro = ( SELECT COALESCE(SUM(s.TotalEuro), 0)
                            FROM @Item AS s
                        ) ,
            Qtys = ( SELECT COALESCE(SUM(s.Qty), 0)
                      FROM @Item AS s
                   )
        WHERE ID = @ID;

      UPDATE Items.t_StockTake
        SET NetIsF = Currencys.f_Format(@CurrencyID, NetIs) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Items.t_StockTakeDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.StockTakeID = t_StockTake.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @ID;

    END;
	
    BEGIN--Item Qtys
   
      INSERT INTO @ItemQtys
          ( ID ,
            SharedID ,
            Qty
          )
        SELECT s.ItemID ,
            s.ItemSharedID ,
            s.Qty * Items.f_UnityItemGetQty(s.ItemUnityID)
          FROM @DetailIs AS s;

      EXECUTE Items.s_ItemAppendQtysPART3 @ItemQtys;

    END;

    BEGIN --Update t_Item LastStockTake
   
      INSERT INTO @ItemQtyNet
          ( ID ,
            Qty
          )
        SELECT o.ID ,
            0
          FROM @ItemQtys AS o
          GROUP BY o.ID;
 
      MERGE Items.t_Item AS t
      USING @ItemQtyNet AS s
      ON s.ID = t.ID AND t.LastStockTakeDate < @DateOnly
      WHEN MATCHED THEN
        UPDATE SET t.LastStockTakeID = @ID ,
                    t.LastStockTakeRef = @Ref ,
                    t.LastStockTakeRefF = FORMAT(@Ref, '#') ,
                    t.LastStockTakeDate = @DateOnly ,
                    t.StockTakeEveryNotificationDate = CASE t.StockTakeEveryType
                                                         WHEN 2 THEN DATEADD(DAY, t.StockTakeEvery, @DateOnly)
                                                         WHEN 1 THEN DATEADD(MONTH, t.StockTakeEvery, @DateOnly)
                                                         ELSE DATEADD(YEAR, t.StockTakeEvery, @DateOnly)
                                                       END;

    END;

   -- IF @AutomaticallyUpdateCostAfterSave > 0 --Update t_ItemShared (Items Cost)
   -- BEGIN 

   --   BEGIN --Declare

   --     DECLARE @ItemShared AS Items.tt_ItemSharedRecalculateCost;
    
   --   END;

   --   BEGIN --Set Info

   --     INSERT INTO @ItemShared
   --         ( ID ,
   --           CurrencyID ,
   --           OldCost ,
   --           Cost ,
   --           EventIs
   --         )
   --       SELECT s.ItemSharedID ,
   --           s1.CurrencyID ,
   --           s1.Purchase ,
   --           CASE s2.TypeIs
   --             WHEN 0 THEN ( s.Price / s3.Qty ) / @ExchangeRate
   --             WHEN 1 THEN ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateLL
   --             ELSE ( ( s.Price / s3.Qty ) / @ExchangeRate ) * @ExchangeRateEuro
   --           END ,
   --           @UpdateCostEventBase + s1.PurchaseF
   --         FROM @DetailIs AS s
   --         INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.ItemSharedID
   --         INNER JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.CurrencyID
   --         INNER JOIN Items.t_UnityItem AS s3 ON s3.ID = s.ItemUnityID
			--WHERE s.Price > 0;

   --     DELETE FROM @ItemShared
   --       WHERE OldCost = Cost;
  
   --     DELETE FROM @ItemShared
   --       WHERE OldCost > 0 AND @AutomaticallyUpdateCostAfterSave = 1;

   --     UPDATE @ItemShared
   --       SET EventIs += ' = ' + Currencys.f_Format(CurrencyID, Cost);

   --   END;
  
   --   EXECUTE [Items].[s_ItemSharedUpdatesRecalculateCostPART] @ItemShared, @UserID, @UpdateCostEventBase, @ComputerIP, @Computer, @ComputerAccount;

   -- END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Items.t_StockTakeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;












