/****** Object:  StoredProcedure [Items].[s_StockTakeUpdateCostToTodayCost]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_StockTakeUpdateCostToTodayCost] @IDs Alls.tt_Guid READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @DetailIs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL ,
          StockTakeID UNIQUEIDENTIFIER NOT NULL ,
          Qty DECIMAL(18, 6) NOT NULL ,
          CurrencyID UNIQUEIDENTIFIER NOT NULL ,
          Price FLOAT NOT NULL ,
          PriceF NVARCHAR(MAX) NOT NULL ,
          PriceD FLOAT NOT NULL ,
          PriceLL FLOAT NOT NULL ,
          PriceEuro FLOAT NOT NULL ,
          Total FLOAT NOT NULL ,
          TotalF NVARCHAR(MAX) NOT NULL ,
          TotalD FLOAT NOT NULL ,
          TotalLL FLOAT NOT NULL ,
          TotalEuro FLOAT NOT NULL
        );

      DECLARE @Return INT = 0;

    END;

    BEGIN --Set info

      INSERT @DetailIs
          ( ID ,
            StockTakeID ,
            Qty ,
            CurrencyID ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro
          )
        SELECT t.ID ,
            t.StockTakeID ,
            t.Qty ,
            t1.CurrencyID ,
            0 ,
            '' ,
            t2.PurchaseD * t3.Qty ,
            t2.PurchaseLL * t3.Qty ,
            t2.PurchaseEuro * t3.Qty ,
            0 ,
            '' ,
            0 ,
            0 ,
            0
          FROM Items.t_StockTakeDetail AS t
          INNER JOIN Items.t_StockTake AS t1 ON t1.ID = t.StockTakeID
          INNER JOIN Items.t_ItemShared AS t2 ON t2.ID = t.ItemSharedID
          INNER JOIN Items.t_UnityItem AS t3 ON t3.ID = t.ItemUnityID
          WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                          FROM @IDs AS s
                          WHERE s.ID = t.StockTakeID );

      UPDATE @DetailIs
        SET Price = Currencys.f_ChooseValue(CurrencyID, PriceD, PriceEuro, PriceEuro);

      UPDATE @DetailIs
        SET PriceF = Currencys.f_Format(CurrencyID, Price) ,
            Total = Price * Qty ,
            TotalF = Currencys.f_Format(CurrencyID, Price * Qty) ,
            TotalD = PriceD * Qty ,
            TotalLL = PriceLL * Qty ,
            TotalEuro = PriceEuro * Qty;

    END;

    BEGIN --Update t_StockTakeDetail

      MERGE Items.t_StockTakeDetail AS t
      USING @DetailIs AS s
      ON t.ID = s.ID
      WHEN MATCHED THEN
        UPDATE SET t.Price = s.Price ,
                    t.PriceF = s.PriceF ,
                    t.PriceD = s.PriceD ,
                    t.PriceLL = s.PriceLL ,
                    t.PriceEuro = s.PriceEuro ,
                    t.Total = s.Total ,
                    t.TotalF = s.TotalF ,
                    t.TotalD = s.TotalD ,
                    t.TotalLL = s.TotalLL ,
                    t.TotalEuro = s.TotalEuro;

    END;

    BEGIN --Update t_StockTake

      UPDATE Items.t_StockTake
        SET NetIs = ( SELECT COALESCE(SUM(s.Total), 0)
                        FROM @DetailIs AS s
                        WHERE s.StockTakeID = t_StockTake.ID
                    ) ,
            NetIsD = ( SELECT COALESCE(SUM(s.TotalD), 0)
                        FROM @DetailIs AS s
                        WHERE s.StockTakeID = t_StockTake.ID
                     ) ,
            NetIsLL = ( SELECT COALESCE(SUM(s.TotalLL), 0)
                          FROM @DetailIs AS s
                        WHERE s.StockTakeID = t_StockTake.ID
                      ) ,
            NetIsEuro = ( SELECT COALESCE(SUM(s.TotalEuro), 0)
                            FROM @DetailIs AS s
                        WHERE s.StockTakeID = t_StockTake.ID
                        )
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_StockTake.ID );

      UPDATE Items.t_StockTake
        SET NetIsF = Currencys.f_Format(CurrencyID, NetIs)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDs AS s
                        WHERE s.ID = t_StockTake.ID );

    END;

    BEGIN --Insert t_StockTakeMoving

      SET @Return = -1;

      INSERT INTO Items.t_StockTakeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @IDs AS s;

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;













