CREATE PROCEDURE [Items].[s_StockTakeUpdateNotSync]
  @IDs Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Items.tr_StockTake ON Items.t_StockTake;
    DISABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;
    DISABLE TRIGGER Items.tr_StockTakeDetailSerial ON Items.t_StockTakeDetailSerial;

    BEGIN --Update

      UPDATE  Items.t_StockTake
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = t_StockTake.ID );
 
      UPDATE  Items.t_StockTakeDetail
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_StockTakeDetail.StockTakeID );
 
      UPDATE  Items.t_StockTakeDetailSerial
      SET     IsSync = 0
      WHERE   EXISTS ( SELECT TOP ( 1 )
                              s.ID
                       FROM   @IDs AS s
                       WHERE  s.ID = Items.t_StockTakeDetailSerial.StockTakeID );

    END;

    ENABLE TRIGGER Items.tr_StockTake ON Items.t_StockTake;
    ENABLE TRIGGER Items.tr_StockTakeDetail ON Items.t_StockTakeDetail;
    ENABLE TRIGGER Items.tr_StockTakeDetailSerial ON Items.t_StockTakeDetailSerial;
	  
    BEGIN --Live

      UPDATE  Alls.t_LiveVersion
      SET     VersionLive = STUFF(VersionLive, StockTake, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
              SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT  1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT  0;

  END CATCH;

END;






