/****** Object:  StoredProcedure [Items].[s_SubCategoryImport]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Items].[s_SubCategoryImport] @drs Items.tt_SubCategory READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare
	
      DECLARE @Drs2 AS Items.tt_SubCategory;

      DECLARE @Return INT = 0;

    END;

    BEGIN

      INSERT INTO @Drs2
          ( ID ,
            Name ,
            MainCategoryID ,
            MainCategory ,
            DescriptionIs ,
            IsSync
	      )
        SELECT s.ID ,
            s.Name ,
            s1.ID ,
            s1.Name ,
            s.DescriptionIs ,
            s.IsSync
          FROM @drs AS s
          INNER JOIN Items.t_MainCategory AS s1 ON s1.Name = s.MainCategory;

    END;

    BEGIN --Merge

      MERGE Items.t_SubCategory AS t
      USING @Drs2 AS s
      ON s.MainCategoryID = t.MainCategoryID AND s.Name = t.Name
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( Name ,
                 MainCategoryID ,
                 DescriptionIs
               )
        VALUES ( Name ,
                 MainCategoryID ,
                 DescriptionIs
               )
      WHEN MATCHED THEN
        UPDATE SET t.DescriptionIs = s.DescriptionIs;

    END;
	
    BEGIN --Rebuild t_MainCategory
    
      UPDATE Items.t_MainCategory
        SET SubCategoryC = ( SELECT COUNT(*) AS Total
                              FROM Items.t_SubCategory AS s
                              WHERE s.MainCategoryID = t_MainCategory.ID
                           );

    END;

    SET @Return = -1;
    EXECUTE Items.s_SubCategoryMovingInsertPART N'00000000-0000-0000-0000-000000000000', @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 
  
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;







GO
