/****** Object:  StoredProcedure [Items].[s_SubCategoryRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_SubCategoryRebuildingStatistics]
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE  Items.t_SubCategory
      SET     ItemC = ( SELECT  COUNT(*) AS Total
                        FROM    Items.t_ItemShared AS t
                        WHERE   t.SubCategoryID = t_SubCategory.ID
                      ) ,
              PurchaseC = ( SELECT  COUNT(*) AS Total
                            FROM    Invoices.t_PurchasingDetail AS t
                            LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                            LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                            WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                          ) ,
              PurchaseQty = ( SELECT  ISNULL(SUM(t.Qtys), 0) AS Total
                              FROM    Invoices.t_PurchasingDetail AS t
                              LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                              LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                              WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                            ) ,
              PurchaseReturnC = ( SELECT  COUNT(*) AS Total
                                  FROM    Invoices.t_PurchasingReturnDetail AS t
                                  LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                  LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                                  WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                                ) ,
              PurchaseReturnQty = ( SELECT  ISNULL(SUM(t.Qtys), 0) AS Total
                                    FROM    Invoices.t_PurchasingReturnDetail AS t
                                    LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                    LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                                    WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                                  ) ,
              QuotationC = ( SELECT COUNT(*) AS Total
                             FROM   Quotations.t_QuotationDetail AS t
                             LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                             WHERE  ( t1.SubCategoryID = t_SubCategory.ID )
                           ) + ( SELECT COUNT(*) AS Total
                                 FROM   Quotations.t_QuotationDetail AS t
                                 LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                 WHERE  ( t1.SubCategoryID = t_SubCategory.ID )
                               ) ,
              QuotationQty = ( SELECT ISNULL(SUM(t.Qtys), 0) AS Total
                               FROM   Quotations.t_QuotationHistoryDetail AS t
                               LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                               WHERE  ( t1.SubCategoryID = t_SubCategory.ID )
                             ) + ( SELECT ISNULL(SUM(t.Qtys), 0) AS Total
                                   FROM   Quotations.t_QuotationHistoryDetail AS t
                                   LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                   WHERE  ( t1.SubCategoryID = t_SubCategory.ID )
                                 ) ,
              SellC = ( SELECT  COUNT(*) AS Total
                        FROM    Invoices.t_SoldDetail AS t
                        LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                        LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                        WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                      ) ,
              SellQty = ( SELECT  ISNULL(SUM(t.Qtys), 0) AS Total
                          FROM    Invoices.t_SoldDetail AS t
                          LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                          LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                          WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                        ) ,
              SellReturnC = ( SELECT  COUNT(*) AS Total
                              FROM    Invoices.t_SoldReturnDetail AS t
                              LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                              LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                              WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                            ) ,
              SellReturnQty = ( SELECT  ISNULL(SUM(t.Qtys), 0) AS Total
                                FROM    Invoices.t_SoldReturnDetail AS t
                                LEFT JOIN Items.t_Item AS t1 ON t1.ID = t.ItemID
                                LEFT JOIN Items.t_ItemShared AS t2 ON t2.ID = t1.SharedID
                                WHERE   ( t2.SubCategoryID = t_SubCategory.ID )
                              );

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Items.t_SubCategoryMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                '00000000-0000-0000-0000-000000000000' ,
                @Event ,
                6 ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;





GO
/****** Object:  StoredProcedure [Items].[s_SubCategoryUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_SubCategoryUpdate]
  @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 )
              @NameOld = s.Name
      FROM    Items.t_SubCategory AS s
      WHERE   s.ID = @ID
      ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE  Items.t_SubCategory
      SET     Name = @Name ,
              DescriptionIs = @DescriptionIs
      WHERE   ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Items.t_SubCategoryMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Fix ItemShared

        UPDATE  Items.t_ItemShared
        SET     SubCategory = @Name
        WHERE   SubCategoryID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;










