/****** Object:  StoredProcedure [Items].[s_UnityItem_TransferToBaseUnit]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItem_TransferToBaseUnit] @ItemSharedID UNIQUEIDENTIFIER ,
  @ItemUnitID_Old UNIQUEIDENTIFIER ,
  @ItemUnitID_New UNIQUEIDENTIFIER ,
  @Unit NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Company

      BEGIN --t_AccountItemPrice

        WITH  o AS ( SELECT s.ItemUnityID ,
                        s.CurrencyID ,
                        s.Price ,
                        s.PriceF ,
                        s.PriceD ,
                        s2.Qty AS UnitQty
                      FROM Company.t_AccountItemPrice AS s
                      INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                      WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnityID = @ItemUnitID_Old
                   )
          UPDATE o
            SET o.ItemUnityID = @ItemUnitID_New ,
                o.Price = o.Price / o.UnitQty ,
                o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price / o.UnitQty) ,
                o.PriceD = o.PriceD / o.UnitQty;

      END;

    END;

    BEGIN --Customers

      BEGIN --t_FrameJobOrder
   
        BEGIN --t_FrameJobOrderDetail

          WITH  o AS ( SELECT s.ItemUnityID ,
                          s.Qty ,
                          s.QtyWithUnity ,
                          s.Qtys ,
                          s.Sale ,
                          s.SaleF ,
                          s.SaleD ,
                          s.SaleLL ,
                          s.SaleEuro ,
                          s.Cost ,
                          s.CostF ,
                          s.CostD ,
                          s.CostLL ,
                          s.CostEuro ,
                          s.Profit ,
                          s.ProfitF ,
                          s.ProfitD ,
                          s.ProfitLL ,
                          s.ProfitEuro ,
                          s1.CurrencyID ,
                          s2.Qty AS UnitQty
                        FROM Customers.t_FrameJobOrderDetail AS s
                        INNER JOIN Customers.t_FrameJobOrder AS s1 ON s1.ID = s.FrameJobOrderID
                        INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                        WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnityID = @ItemUnitID_Old
                     )
            UPDATE o
              SET o.ItemUnityID = @ItemUnitID_New ,
                  o.Qty = o.Qtys ,
                  o.QtyWithUnity = FORMAT(o.Qtys, N'0.######') + N' ' + @Unit ,
                  o.Sale = o.Sale / o.UnitQty ,
                  o.SaleF = Currencys.f_Format(o.CurrencyID, o.Sale / o.UnitQty) ,
                  o.SaleD = o.SaleD / o.UnitQty ,
                  o.SaleLL = o.SaleLL / o.UnitQty ,
                  o.SaleEuro = o.SaleEuro / o.UnitQty ,
                  o.Cost = o.Cost / o.UnitQty ,
                  o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost / o.UnitQty) ,
                  o.CostD = o.CostD / o.UnitQty ,
                  o.CostLL = o.CostLL / o.UnitQty ,
                  o.CostEuro = o.CostEuro / o.UnitQty ,
                  o.Profit = o.Profit / o.UnitQty ,
                  o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit / o.UnitQty) ,
                  o.ProfitD = o.ProfitD / o.UnitQty ,
                  o.ProfitLL = o.ProfitLL / o.UnitQty ,
                  o.ProfitEuro = o.ProfitEuro / o.UnitQty;

        END;

        BEGIN --t_FrameJobOrderHistoryDetail

          WITH  o AS ( SELECT s.ItemUnityID ,
                          s.Qty ,
                          s.QtyWithUnity ,
                          s.Qtys ,
                          s.Sale ,
                          s.SaleF ,
                          s.SaleD ,
                          s.SaleLL ,
                          s.SaleEuro ,
                          s.Cost ,
                          s.CostF ,
                          s.CostD ,
                          s.CostLL ,
                          s.CostEuro ,
                          s.Profit ,
                          s.ProfitF ,
                          s.ProfitD ,
                          s.ProfitLL ,
                          s.ProfitEuro ,
                          s1.CurrencyID ,
                          s2.Qty AS UnitQty
                        FROM Customers.t_FrameJobOrderHistoryDetail AS s
                        INNER JOIN Customers.t_FrameJobOrderHistory AS s1 ON s1.ID = s.FrameJobOrderHistoryID
                        INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                        WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnityID = @ItemUnitID_Old
                     )
            UPDATE o
              SET o.ItemUnityID = @ItemUnitID_New ,
                  o.Qty = o.Qtys ,
                  o.QtyWithUnity = FORMAT(o.Qtys, N'0.######') + N' ' + @Unit ,
                  o.Sale = o.Sale / o.UnitQty ,
                  o.SaleF = Currencys.f_Format(o.CurrencyID, o.Sale / o.UnitQty) ,
                  o.SaleD = o.SaleD / o.UnitQty ,
                  o.SaleLL = o.SaleLL / o.UnitQty ,
                  o.SaleEuro = o.SaleEuro / o.UnitQty ,
                  o.Cost = o.Cost / o.UnitQty ,
                  o.CostF = Currencys.f_Format(o.CurrencyID, o.Cost / o.UnitQty) ,
                  o.CostD = o.CostD / o.UnitQty ,
                  o.CostLL = o.CostLL / o.UnitQty ,
                  o.CostEuro = o.CostEuro / o.UnitQty ,
                  o.Profit = o.Profit / o.UnitQty ,
                  o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit / o.UnitQty) ,
                  o.ProfitD = o.ProfitD / o.UnitQty ,
                  o.ProfitLL = o.ProfitLL / o.UnitQty ,
                  o.ProfitEuro = o.ProfitEuro / o.UnitQty;

        END;

      END;

    END;

    BEGIN --Invoices

      BEGIN --t_PurchaseOrder
   
        BEGIN --t_PurchaseOrderDetail

          WITH  o AS ( SELECT s.ItemUnitID ,
                          s.Qty ,
                          s.QtyWithUnit ,
                          s.Qtys ,
                          s.UnitCost ,
                          s.UnitCostF ,
                          s.UnitCostD ,
                          s.UnitCostLL ,
                          s.UnitCostEuro ,
                          s.SalePrice ,
                          s.SalePriceF ,
                          s.SalePriceD ,
                          s.SalePriceLL ,
                          s.SalePriceEuro ,
                          s.Profit ,
                          s.ProfitF ,
                          s.ProfitD ,
                          s.ProfitLL ,
                          s.ProfitEuro ,
                          s1.CurrencyID ,
                          s2.Qty AS UnitQty
                        FROM Invoices.t_PurchaseOrderDetail AS s
                        INNER JOIN Invoices.t_PurchaseOrder AS s1 ON s1.ID = s.PurchaseOrderID
                        INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnitID
                        WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnitID = @ItemUnitID_Old
                     )
            UPDATE o
              SET o.ItemUnitID = @ItemUnitID_New ,
                  o.Qty = o.Qtys ,
                  o.QtyWithUnit = FORMAT(o.Qtys, N'0.######') + N' ' + @Unit ,
                  o.UnitCost = o.UnitCost / o.UnitQty ,
                  o.UnitCostF = Currencys.f_Format(o.CurrencyID, o.UnitCost / o.UnitQty) ,
                  o.UnitCostD = o.UnitCostD / o.UnitQty ,
                  o.UnitCostLL = o.UnitCostLL / o.UnitQty ,
                  o.UnitCostEuro = o.UnitCostEuro / o.UnitQty ,
                  o.SalePrice = o.SalePrice / o.UnitQty ,
                  o.SalePriceF = Currencys.f_Format(o.CurrencyID, o.SalePrice / o.UnitQty) ,
                  o.SalePriceD = o.SalePriceD / o.UnitQty ,
                  o.SalePriceLL = o.SalePriceLL / o.UnitQty ,
                  o.SalePriceEuro = o.SalePriceEuro / o.UnitQty ,
                  o.Profit = o.Profit / o.UnitQty ,
                  o.ProfitF = Currencys.f_Format(o.CurrencyID, o.Profit / o.UnitQty) ,
                  o.ProfitD = o.ProfitD / o.UnitQty ,
                  o.ProfitLL = o.ProfitLL / o.UnitQty ,
                  o.ProfitEuro = o.ProfitEuro / o.UnitQty;

        END;

        BEGIN --t_PurchaseOrderArchiveDetail

          WITH  o AS ( SELECT s.ItemUnitID ,
                          s.Qty ,
                          s.QtyWithUnit ,
                          s.Qtys ,
                          s.UnitCost ,
                          s.UnitCostF ,
                          s.UnitCostD ,
                          s.UnitCostLL ,
                          s.UnitCostEuro ,
                          s.SalePrice ,
                          s.SalePriceF ,
                          s.SalePriceD ,
                          s.SalePriceLL ,
                          s.SalePriceEuro ,
                          s.Profit ,
                          s.ProfitF ,
                          s.ProfitD ,
                          s.ProfitLL ,
                          s.ProfitEuro ,
                          s1.CurrencyID ,
                          s2.Qty AS UnitQty
                        FROM Invoices.t_PurchaseOrderArchiveDetail AS s
                        INNER JOIN Invoices.t_PurchaseOrderArchive AS s1 ON s1.ID = s.PurchaseOrderArchiveID
                        INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnitID
                        WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnitID = @ItemUnitID_Old
                     )
            UPDATE o
