                o.UnitCostWithTaxD = o.UnitCostWithTaxD / o.UnitQty ,
                o.UnitCostWithTaxLL = o.UnitCostWithTaxLL / o.UnitQty ,
                o.UnitCostWithTaxEuro = o.UnitCostWithTaxEuro / o.UnitQty ,
                o.UnitProfit = o.UnitProfit / o.UnitQty ,
                o.UnitProfitF = Currencys.f_Format(o.CurrencyID, o.UnitProfit / o.UnitQty) ,
                o.UnitProfitD = o.UnitProfitD / o.UnitQty ,
                o.UnitProfitLL = o.UnitProfitLL / o.UnitQty ,
                o.UnitProfitEuro = o.UnitProfitEuro / o.UnitQty ,
                o.UnitProfitWithTax = o.UnitProfitWithTax / o.UnitQty ,
                o.UnitProfitWithTaxF = Currencys.f_Format(o.CurrencyID, o.UnitProfitWithTax / o.UnitQty) ,
                o.UnitProfitWithTaxD = o.UnitProfitWithTaxD / o.UnitQty ,
                o.UnitProfitWithTaxLL = o.UnitProfitWithTaxLL / o.UnitQty ,
                o.UnitProfitWithTaxEuro = o.UnitProfitWithTaxEuro / o.UnitQty;

      END;

      BEGIN --t_QuotationHistory

        WITH  o AS ( SELECT s.ItemUnityID ,
                        s.Qty ,
                        s.QtyWithUnity ,
                        s.Qtys ,
                        s.Price ,
                        s.PriceF ,
                        s.PriceD ,
                        s.PriceLL ,
                        s.PriceEuro ,
                        s.UnitCost ,
                        s.UnitCostF ,
                        s.UnitCostD ,
                        s.UnitCostLL ,
                        s.UnitCostEuro ,
                        s.UnitCostWithTax ,
                        s.UnitCostWithTaxF ,
                        s.UnitCostWithTaxD ,
                        s.UnitCostWithTaxLL ,
                        s.UnitCostWithTaxEuro ,
                        s.UnitProfit ,
                        s.UnitProfitF ,
                        s.UnitProfitD ,
                        s.UnitProfitLL ,
                        s.UnitProfitEuro ,
                        s.UnitProfitWithTax ,
                        s.UnitProfitWithTaxF ,
                        s.UnitProfitWithTaxD ,
                        s.UnitProfitWithTaxLL ,
                        s.UnitProfitWithTaxEuro ,
                        s1.CurrencyID ,
                        s2.Qty AS UnitQty
                      FROM Quotations.t_QuotationHistoryDetail AS s
                      INNER JOIN Quotations.t_QuotationHistory AS s1 ON s1.ID = s.QuotationHistoryID
                      INNER JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                      WHERE s.ItemSharedID = @ItemSharedID AND s.ItemUnityID = @ItemUnitID_Old
                   )
          UPDATE o
            SET o.ItemUnityID = @ItemUnitID_New ,
                o.Qty = o.Qtys ,
                o.QtyWithUnity = FORMAT(o.Qtys, N'0.######') + N' ' + @Unit ,
                o.Price = o.Price / o.UnitQty ,
                o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price / o.UnitQty) ,
                o.PriceD = o.PriceD / o.UnitQty ,
                o.PriceLL = o.PriceLL / o.UnitQty ,
                o.PriceEuro = o.PriceEuro / o.UnitQty ,
                o.UnitCost = o.UnitCost / o.UnitQty ,
                o.UnitCostF = Currencys.f_Format(o.CurrencyID, o.UnitCost / o.UnitQty) ,
                o.UnitCostD = o.UnitCostD / o.UnitQty ,
                o.UnitCostLL = o.UnitCostLL / o.UnitQty ,
                o.UnitCostEuro = o.UnitCostEuro / o.UnitQty ,
                o.UnitCostWithTax = o.UnitCostWithTax / o.UnitQty ,
                o.UnitCostWithTaxF = Currencys.f_Format(o.CurrencyID, o.UnitCostWithTax / o.UnitQty) ,
                o.UnitCostWithTaxD = o.UnitCostWithTaxD / o.UnitQty ,
                o.UnitCostWithTaxLL = o.UnitCostWithTaxLL / o.UnitQty ,
                o.UnitCostWithTaxEuro = o.UnitCostWithTaxEuro / o.UnitQty ,
                o.UnitProfit = o.UnitProfit / o.UnitQty ,
                o.UnitProfitF = Currencys.f_Format(o.CurrencyID, o.UnitProfit / o.UnitQty) ,
                o.UnitProfitD = o.UnitProfitD / o.UnitQty ,
                o.UnitProfitLL = o.UnitProfitLL / o.UnitQty ,
                o.UnitProfitEuro = o.UnitProfitEuro / o.UnitQty ,
                o.UnitProfitWithTax = o.UnitProfitWithTax / o.UnitQty ,
                o.UnitProfitWithTaxF = Currencys.f_Format(o.CurrencyID, o.UnitProfitWithTax / o.UnitQty) ,
                o.UnitProfitWithTaxD = o.UnitProfitWithTaxD / o.UnitQty ,
                o.UnitProfitWithTaxLL = o.UnitProfitWithTaxLL / o.UnitQty ,
                o.UnitProfitWithTaxEuro = o.UnitProfitWithTaxEuro / o.UnitQty;

      END;

    END;
	
    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ItemSharedID; 
  
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    RETURN @Return;

  END CATCH;

END;


