/****** Object:  StoredProcedure [Items].[s_UnityItemChangeUnit]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItemChangeUnit] @OldUnitID UNIQUEIDENTIFIER ,
  @NewUnitID UNIQUEIDENTIFIER ,
  @NewUnit NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    EXECUTE Items.s_UnityItemChangeUnitAccountItemPricePART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitBeginningInventoryQuantityDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitDaysPackageDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitDeliveryPermissionDeleteDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitDeliveryPermissionDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitDeliveryPermissionHistoryDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitFrameJobOrderDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitFrameJobOrderHistoryDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitItemProductionPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitItemProductionMaterialPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitItemSharedMaterialPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitItemsPackageDetailsPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitPurchaseOrderUnsavedDetailPART @OldUnitID, @NewUnitID, @NewUnit;
    EXECUTE Items.s_UnityItemChangeUnitPurchasingDeletedDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitPurchasingDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitPurchasingReturnDeletedDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitPurchasingReturnDetailPART @OldUnitID, @NewUnitID, @NewUnit; 
    EXECUTE Items.s_UnityItemChangeUnitPurchasingUnsavedDetailPART @OldUnitID, @NewUnitID, @NewUnit; 

    BEGIN --Update t_Item
	
      UPDATE Items.t_Item
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent);

    END;
 
    BEGIN --Update t_ItemShared

      UPDATE Items.t_ItemShared
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID);

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;


