GO
CREATE PROCEDURE [Items].[s_UnityItemChangeUnitAccountItemPricePART] @OldUnitID UNIQUEIDENTIFIER ,
  @NewUnitID UNIQUEIDENTIFIER ,
  @NewUnit NVARCHAR(MAX)
AS
BEGIN;

  DISABLE TRIGGER Company.tr_AccountItemPrice ON Company.t_AccountItemPrice;

  WITH  o AS ( SELECT t.ItemUnityID ,
                  t.Unity ,
                  t.CurrencyID ,
                  t.Price ,
                  t.PriceF ,
                  t.PriceD ,
                  t1.Qty AS UnitQty
                FROM Company.t_AccountItemPrice AS t
                INNER JOIN Items.t_UnityItem AS t1 ON t1.ID = t.ItemUnityID
                WHERE t.ItemUnityID = @OldUnitID
             )
    UPDATE o
      SET o.ItemUnityID = @NewUnitID ,
          o.Unity = @NewUnit ,
          o.Price /= o.UnitQty ,
          o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price / o.UnitQty) ,
          o.PriceD /= o.UnitQty;
	
  ENABLE TRIGGER Company.tr_AccountItemPrice ON Company.t_AccountItemPrice;
  
END



