/****** Object:  StoredProcedure [Items].[s_UnityItemDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItemDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @ItemSharedID UNIQUEIDENTIFIER ,
        @Barcode NVARCHAR(450) ,
        @Purchasing BIT ,
        @Sold BIT ,
        @Inventory BIT ,
        @UseInTransfer BIT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ItemSharedID = s.SharedID ,
          @Barcode = s.BarCode ,
          @Purchasing = s.Purchasing ,
          @Sold = s.Sold ,
          @Inventory = s.Inventory ,
          @UseInTransfer = s.UseInTransfer
        FROM Items.t_UnityItem AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Delete t_TrackDeletedItemsFromInvoices

      DELETE FROM Invoices.t_TrackDeletedItemsFromInvoices
        WHERE ItemUnitID = @ID;

    END;

    BEGIN --Delete Barcode

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ItemSharedID AND TypeIs = 2 AND BarCode = @Barcode;

    END;

    BEGIN --Delete

      SET @Return = 0;

      DELETE FROM Company.t_AccountItemPrice
        WHERE ItemUnityID = @ID;

      DELETE FROM Items.t_UnityItem
        WHERE ID = @ID;

    END;

    BEGIN --Fix data

      UPDATE Items.t_UnityItem
        SET Purchasing = CASE @Purchasing
                           WHEN 1 THEN @Purchasing
                           ELSE Purchasing
                         END ,
            Sold = CASE @Sold
                     WHEN 1 THEN @Sold
                     ELSE Sold
                   END ,
            Inventory = CASE @Inventory
                          WHEN 1 THEN @Inventory
                          ELSE Inventory
                        END ,
            UseInTransfer = CASE @UseInTransfer
                              WHEN 1 THEN @UseInTransfer
                              ELSE UseInTransfer
                            END
        WHERE SharedID = @ItemSharedID AND PrimaryIs = 1;

    END;

    BEGIN --Rebuilding statistics
	
      UPDATE Items.t_Item
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent)
        WHERE t_Item.SharedID = @ItemSharedID;

      UPDATE Items.t_ItemShared
        SET Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            UnityC -= 1 ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID)
        WHERE ID = @ItemSharedID;

    END;

    SET @Return = -1;
    EXECUTE Items.s_ItemSharedMovingInsertPART @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount, @ItemSharedID; 
  
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    RETURN @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Items].[s_UnityItemInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItemInsert] @UnityID UNIQUEIDENTIFIER ,
  @SharedID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 6) ,
  @Purchasing BIT ,
  @Sold BIT ,
  @Inventory BIT ,
  @UseInTransfer BIT ,
  @BarCode NVARCHAR(450) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Price FLOAT ,
  @DistributionPrice FLOAT ,
  @WholesalePrice FLOAT ,
  @LowestPrice FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ExchangeRate FLOAT ,
        @TaxRate DECIMAL(4, 2) ,
        @Return INT;

    END;

    BEGIN --Set info

      SET @ExchangeRate = Currencys.f_CurrencyGetExchangeRate(@CurrencyID);

      SELECT TOP ( 1 ) @TaxRate = s.TaxRate
        FROM Items.t_ItemShared AS s
        WHERE s.ID = @SharedID
        ORDER BY s.ID;

    END;

    IF @BarCode <> N''
    BEGIN --Insert barcodes

      SET @Return = -3;

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        VALUES
          ( @SharedID ,
            @BarCode ,
            Alls.f_ToBigint(@BarCode) ,
            2
          );

    END;

    BEGIN --Insert

      SET @Return = 0;

      INSERT INTO Items.t_UnityItem
          ( ID ,
            UnityID ,
            Unity ,
            SharedID ,
            Qty ,
            PrimaryIs ,
            Purchasing ,
            Sold ,
            Inventory ,
            UseInTransfer ,
            BarCode ,
            CurrencyID ,
            Currency ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            PriceWithTax ,
            DistributionPrice ,
            DistributionPriceF ,
            DistributionPriceD ,
            DistributionPriceLL ,
            DistributionPriceEuro ,
            DistributionPriceWithTax ,
            WholesalePrice ,
            WholesalePriceF ,
            WholesalePriceD ,
            WholesalePriceLL ,
            WholesalePriceEuro ,
            WholesalePriceWithTax ,
            LowestPrice ,
            LowestPriceF ,
            LowestPriceD
          )
        SELECT TOP ( 1 ) @ID ,
            @UnityID ,
            Items.f_UnityGetName(@UnityID) ,
            @SharedID ,
            @Qty ,
            0 ,
            @Purchasing ,
            @Sold ,
            @Inventory ,
            @UseInTransfer ,
            @BarCode ,
            @CurrencyID ,
            s.Name ,
            @Price ,
            Currencys.f_Format(@CurrencyID, @Price) ,
            @Price / s.ExchangeRate ,
            Currencys.f_ExchangeToLL(@CurrencyID, @Price, @Price / s.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @Price / s.ExchangeRate) ,
            Calculation.Rate(@Price, @TaxRate) ,
            @DistributionPrice ,
            Currencys.f_Format(@CurrencyID, @DistributionPrice) ,
            @DistributionPrice / s.ExchangeRate ,
            Currencys.f_ExchangeToLL(@CurrencyID, @DistributionPrice, @DistributionPrice / s.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @DistributionPrice, @DistributionPrice / s.ExchangeRate) ,
            Calculation.Rate(@DistributionPrice, @TaxRate) ,
            @WholesalePrice ,
            Currencys.f_Format(@CurrencyID, @WholesalePrice) ,
            @WholesalePrice / s.ExchangeRate ,
            Currencys.f_ExchangeToLL(@CurrencyID, @WholesalePrice, @WholesalePrice / s.ExchangeRate) ,
            Currencys.f_ExchangeToEuro(@CurrencyID, @WholesalePrice, @WholesalePrice / s.ExchangeRate) ,
            Calculation.Rate(@WholesalePrice, @TaxRate) ,
            @LowestPrice ,
            Currencys.f_Format(@CurrencyID, @LowestPrice) ,
            @LowestPrice / s.ExchangeRate
          FROM Currencys.t_Currency AS s
          WHERE s.ID = @CurrencyID
          ORDER BY s.ID;

    END;

    BEGIN --Fix data

      UPDATE Items.t_UnityItem
        SET Purchasing = CASE @Purchasing
                           WHEN 1 THEN 0
                           ELSE Purchasing
                         END ,
            Sold = CASE @Sold
                     WHEN 1 THEN 0
                     ELSE Sold
                   END ,
            Inventory = CASE @Inventory
                          WHEN 1 THEN 0
                          ELSE Inventory
                        END ,
            UseInTransfer = CASE @UseInTransfer
                              WHEN 1 THEN 0
                              ELSE UseInTransfer
                            END
        WHERE SharedID = @SharedID AND ID <> @ID;



      WITH  o AS ( SELECT s.Qty ,
                      s.CurrencyIDCost ,
                      s.CurrencyCost ,
                      s.Cost ,
                      s.CostF ,
                      s.CostD ,
                      s.CostLL ,
                      s.CostEuro ,
                      s.CostWithTax ,
                      s.CostWithTaxF ,
                      s.CostWithTaxD ,
                      s.CostWithTaxLL ,
                      s.CostWithTaxEuro ,
                      s1.CurrencyID AS CurrencyIDCost_ ,
                      s1.Currency AS CurrencyCost_ ,
                      s1.Purchase AS Cost_ ,
                      s1.PurchaseD AS CostD_ ,
                      s1.PurchaseLL AS CostLL_ ,
                      s1.PurchaseEuro AS CostEuro_ ,
                      s1.PurchaseWithTax AS CostWithTax_ ,
                      s1.PurchaseWithTaxD AS CostWithTaxD_ ,
                      s1.PurchaseWithTaxLL AS CostWithTaxLL_ ,
                      s1.PurchaseWithTaxEuro AS CostWithTaxEuro_ ,
                      s.QtyCurrent ,
                      s1.QtyCurrent AS QtyCurrent_
                    FROM Items.t_UnityItem AS s
                    INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
                    WHERE s.ID = @ID
                 )
        UPDATE o
          SET o.CurrencyIDCost = o.CurrencyIDCost_ ,
              o.CurrencyCost = o.CurrencyCost_ ,
              o.Cost = o.Cost_ * o.Qty ,
              o.CostF = Currencys.f_Format(o.CurrencyIDCost_, o.Cost_ * o.Qty) ,
              o.CostD = o.CostD_ * o.Qty ,
              o.CostLL = o.CostLL_ * o.Qty ,
              o.CostEuro = o.CostEuro_ * o.Qty ,
              o.CostWithTax = o.CostWithTax_ * o.Qty ,
              o.CostWithTaxF = Currencys.f_Format(o.CurrencyIDCost_, o.CostWithTax_ * o.Qty) ,
              o.CostWithTaxD = o.CostWithTaxD_ * o.Qty ,
              o.CostWithTaxLL = o.CostWithTaxLL_ * o.Qty ,
              o.CostWithTaxEuro = o.CostWithTaxEuro_ * o.Qty ,
              o.QtyCurrent = o.QtyCurrent_ / o.Qty;

      UPDATE Items.t_UnityItem
        SET PriceWithTaxF = Currencys.f_Format(CurrencyID, PriceWithTax) ,
            PriceWithTaxD = PriceWithTax / @ExchangeRate ,
            PriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, PriceWithTax, PriceWithTax / @ExchangeRate) ,
            PriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, PriceWithTax, PriceWithTax / @ExchangeRate) ,
            DistributionPriceWithTaxF = Currencys.f_Format(CurrencyID, DistributionPriceWithTax) ,
            DistributionPriceWithTaxD = DistributionPriceWithTax / @ExchangeRate ,
            DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            WholesalePriceWithTaxF = Currencys.f_Format(CurrencyID, WholesalePriceWithTax) ,
            WholesalePriceWithTaxD = WholesalePriceWithTax / @ExchangeRate ,
            WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate) ,
            WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate)
        WHERE ID = @ID;
	  
      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE ID = @ID;

    END;

    BEGIN --Rebuilding statistics
	
      UPDATE Items.t_Item
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent)
        WHERE t_Item.SharedID = @SharedID;

      UPDATE Items.t_ItemShared
        SET Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID) ,
            QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            UnityC += 1 ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE ID = @SharedID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @SharedID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Items].[s_UnityItemUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Items].[s_UnityItemUpdate] @UnityID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 6) ,
  @Purchasing BIT ,
  @Sold BIT ,
  @Inventory BIT ,
  @UseInTransfer BIT ,
  @BarCode NVARCHAR(450) ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Price FLOAT ,
  @DistributionPrice FLOAT ,
  @WholesalePrice FLOAT ,
  @LowestPrice FLOAT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

	--DISABLE TRIGGER Items.tr_Item ON Items.t_Item;
	--DISABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
	--DISABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    BEGIN --Declare

      DECLARE @Return INT ,
        @ItemSharedID UNIQUEIDENTIFIER ,
        @UnityIDOld UNIQUEIDENTIFIER ,
        @QtyOld DECIMAL(18, 6) ,
        @Unity NVARCHAR(MAX) ,
        @BarcodeOld NVARCHAR(450) ,
        @ExchangeRate FLOAT ,
        @PrimaryIs BIT ,
        @PurchasingOld BIT ,
        @SoldOld BIT ,
        @InventoryOld BIT ,
        @UseInTransferOld BIT ,
        @UnityC INT ,
        @TaxRate DECIMAL(4, 2);

    END;

    BEGIN --Set info

      SET @ExchangeRate = Currencys.f_CurrencyGetExchangeRate(@CurrencyID);

      SET @Unity = Items.f_UnityGetName(@UnityID);

      SELECT TOP ( 1 ) @ItemSharedID = s.SharedID ,
          @UnityIDOld = s.UnityID ,
          @QtyOld = s.Qty ,
          @BarcodeOld = s.BarCode ,
          @PrimaryIs = s.PrimaryIs ,
          @PurchasingOld = s.Purchasing ,
          @SoldOld = s.Sold ,
          @InventoryOld = s.Inventory ,
          @UseInTransferOld = s.UseInTransfer ,
          @TaxRate = s1.TaxRate
        FROM Items.t_UnityItem AS s
        INNER JOIN Items.t_ItemShared AS s1 ON s1.ID = s.SharedID
        WHERE s.ID = @ID
        ORDER BY s.ID;

      SELECT @UnityC = COUNT(*)
        FROM Items.t_UnityItem AS s
        WHERE s.SharedID = @ItemSharedID;

    END;

    BEGIN --Delete old barcode

      SET @Return = -3;

      DELETE FROM Items.t_ItemSharedBarCode
        WHERE SharedID = @ItemSharedID AND TypeIs = 2 AND BarCode = @BarcodeOld;

    END;

    IF @BarCode <> N''
    BEGIN --Insert barcodes

      INSERT INTO Items.t_ItemSharedBarCode
          ( SharedID ,
            BarCode ,
            BarcodeNumber ,
            TypeIs
          )
        VALUES
          ( @ItemSharedID ,
            @BarCode ,
            Alls.f_ToBigint(@BarCode) ,
            2
          );

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Items.t_UnityItem
        SET Purchasing = IIF(@Purchasing = 1, 0, Purchasing) ,
            Sold = IIF(@Sold = 1, 0, Sold) ,
            Inventory = IIF(@Inventory = 1, 0, Inventory) ,
            UseInTransfer = IIF(@UseInTransfer = 1, 0, UseInTransfer)
        WHERE SharedID = @ItemSharedID;

      UPDATE Items.t_UnityItem
        SET UnityID = @UnityID ,
            Unity = @Unity ,
            Qty = @Qty ,
            Purchasing = @Purchasing ,
            Sold = @Sold ,
            Inventory = @Inventory ,
            UseInTransfer = @UseInTransfer ,
            BarCode = @BarCode ,
            CurrencyID = @CurrencyID ,
            Currency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            Price = @Price ,
            PriceF = Currencys.f_Format(@CurrencyID, @Price) ,
            PriceD = @Price / @ExchangeRate ,
            PriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @Price, @Price / @ExchangeRate) ,
            PriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @Price / @ExchangeRate) ,
            PriceWithTax = Calculation.Rate(@Price, @TaxRate) ,
            DistributionPrice = @DistributionPrice ,
            DistributionPriceF = Currencys.f_Format(@CurrencyID, @DistributionPrice) ,
            DistributionPriceD = @DistributionPrice / @ExchangeRate ,
            DistributionPriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @DistributionPrice, @DistributionPrice / @ExchangeRate) ,
            DistributionPriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @DistributionPrice, @DistributionPrice / @ExchangeRate) ,
            DistributionPriceWithTax = Calculation.Rate(@DistributionPrice, @TaxRate) ,
            WholesalePrice = @WholesalePrice ,
            WholesalePriceF = Currencys.f_Format(@CurrencyID, @WholesalePrice) ,
            WholesalePriceD = @WholesalePrice / @ExchangeRate ,
            WholesalePriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @WholesalePrice, @WholesalePrice / @ExchangeRate) ,
            WholesalePriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @WholesalePrice, @WholesalePrice / @ExchangeRate) ,
            WholesalePriceWithTax = Calculation.Rate(@WholesalePrice, @TaxRate) ,
            LowestPrice = @LowestPrice ,
            LowestPriceF = Currencys.f_Format(@CurrencyID, @LowestPrice) ,
            LowestPriceD = @LowestPrice / @ExchangeRate
        WHERE ID = @ID;

      UPDATE Items.t_UnityItem
        SET PriceWithTaxF = Currencys.f_Format(CurrencyID, PriceWithTax) ,
            PriceWithTaxD = PriceWithTax / @ExchangeRate ,
            PriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, PriceWithTax, PriceWithTax / @ExchangeRate) ,
            PriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, PriceWithTax, PriceWithTax / @ExchangeRate) ,
            DistributionPriceWithTaxF = Currencys.f_Format(CurrencyID, DistributionPriceWithTax) ,
            DistributionPriceWithTaxD = DistributionPriceWithTax / @ExchangeRate ,
            DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            WholesalePriceWithTaxF = Currencys.f_Format(CurrencyID, WholesalePriceWithTax) ,
            WholesalePriceWithTaxD = WholesalePriceWithTax / @ExchangeRate ,
            WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate) ,
            WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate)
        WHERE ID = @ID;

    END;

    BEGIN --Fix data

      IF @UnityC = 1
      BEGIN

        UPDATE Items.t_UnityItem
          SET Purchasing = 1 ,
              Sold = 1 ,
              Inventory = 1 ,
              UseInTransfer = 1
          WHERE SharedID = @ItemSharedID;

      END;

      IF @UnityC = 2
      BEGIN

        UPDATE Items.t_UnityItem
          SET Purchasing = ~@Purchasing ,
              Sold = ~@Sold ,
              Inventory = ~@Inventory ,
              UseInTransfer = ~@UseInTransfer
          WHERE SharedID = @ItemSharedID AND ID <> @ID;

      END;

      IF @UnityC > 2
      BEGIN

        DECLARE @ID2 UNIQUEIDENTIFIER;

        SELECT TOP ( 1 ) @ID2 = s.ID
          FROM Items.t_UnityItem AS s
          WHERE s.SharedID = @ItemSharedID AND s.ID <> @ID
          ORDER BY s.DateCreate;

        UPDATE Items.t_UnityItem
          SET Purchasing = IIF(@Purchasing = 0 AND @PurchasingOld = 1, 1, Purchasing) ,
              Sold = IIF(@Sold = 0 AND @SoldOld = 1, 1, Sold) ,
              Inventory = IIF(@Inventory = 0 AND @InventoryOld = 1, 1, Inventory) ,
              UseInTransfer = IIF(@UseInTransfer = 0 AND @UseInTransferOld = 1, 1, UseInTransfer)
          WHERE ID = @ID2;

      END;

    END;

    IF @PrimaryIs = 1
    BEGIN --Update item

      UPDATE Items.t_ItemShared
        SET SellCurrencyID = @CurrencyID ,
            SellCurrency = Currencys.f_CurrencyGetName(@CurrencyID) ,
            WholesalePrice = @WholesalePrice ,
            WholesalePriceF = Currencys.f_Format(@CurrencyID, @WholesalePrice) ,
            WholesalePriceD = @WholesalePrice / @ExchangeRate ,
            WholesalePriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @WholesalePrice, @WholesalePrice / @ExchangeRate) ,
            WholesalePriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @WholesalePrice, @WholesalePrice / @ExchangeRate) ,
            WholesalePriceWithTax = Calculation.Rate(@WholesalePrice, TaxRate) ,
            DistributionPrice = @DistributionPrice ,
            DistributionPriceF = Currencys.f_Format(@CurrencyID, @DistributionPrice) ,
            DistributionPriceD = @DistributionPrice / @ExchangeRate ,
            DistributionPriceLL = Currencys.f_ExchangeToLL(@CurrencyID, @DistributionPrice, @DistributionPrice / @ExchangeRate) ,
            DistributionPriceEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @DistributionPrice, @DistributionPrice / @ExchangeRate) ,
            DistributionPriceWithTax = Calculation.Rate(@DistributionPrice, TaxRate) ,
            Sell = @Price ,
            SellF = Currencys.f_Format(@CurrencyID, @Price) ,
            SellD = @Price / @ExchangeRate ,
            SellLL = Currencys.f_ExchangeToLL(@CurrencyID, @Price, @Price / @ExchangeRate) ,
            SellEuro = Currencys.f_ExchangeToEuro(@CurrencyID, @Price, @Price / @ExchangeRate) ,
            SellWithTax = Calculation.Rate(@Price, TaxRate)
        WHERE ID = @ItemSharedID;

      UPDATE Items.t_ItemShared
        SET FinalPrice = Calculation.Discount(Sell, Discount) ,
            FinalPriceF = Currencys.f_Format(SellCurrencyID, Calculation.Discount(Sell, Discount)) ,
            FinalPriceD = Calculation.Discount(SellD, Discount) ,
            FinalPriceLL = Calculation.Discount(SellLL, Discount) ,
            FinalPriceEuro = Calculation.Discount(SellEuro, Discount) ,
            TotalWholesalePrice = @WholesalePrice * QtyCurrent ,
            TotalWholesalePriceF = Currencys.f_Format(@CurrencyID, @WholesalePrice * QtyCurrent) ,
            WholesalePriceWithTaxF = Currencys.f_Format(@CurrencyID, WholesalePriceWithTax) ,
            WholesalePriceWithTaxD = WholesalePriceWithTax / @ExchangeRate ,
            WholesalePriceWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate) ,
            WholesalePriceWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyID, WholesalePriceWithTax, WholesalePriceWithTax / @ExchangeRate) ,
            TotalWholesalePriceWithTax = WholesalePriceWithTax * QtyCurrent ,
            TotalWholesalePriceWithTaxF = Currencys.f_Format(@CurrencyID, WholesalePriceWithTax * QtyCurrent) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - PurchaseLL, PurchaseLL) ,
            TotalDistributionPrice = @DistributionPrice * QtyCurrent ,
            TotalDistributionPriceF = Currencys.f_Format(@CurrencyID, @DistributionPrice * QtyCurrent) ,
            DistributionPriceWithTaxF = Currencys.f_Format(@CurrencyID, DistributionPriceWithTax) ,
            DistributionPriceWithTaxD = DistributionPriceWithTax / @ExchangeRate ,
            DistributionPriceWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            DistributionPriceWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyID, DistributionPriceWithTax, DistributionPriceWithTax / @ExchangeRate) ,
            TotalDistributionPriceWithTax = DistributionPriceWithTax * QtyCurrent ,
            TotalDistributionPriceWithTaxF = Currencys.f_Format(@CurrencyID, DistributionPriceWithTax * QtyCurrent) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - PurchaseLL, PurchaseLL) ,
            SellTotal = @Price * QtyCurrent ,
            SellTotalF = Currencys.f_Format(@CurrencyID, @Price * QtyCurrent) ,
            SellWithTaxF = Currencys.f_Format(@CurrencyID, SellWithTax) ,
            SellWithTaxD = SellWithTax / @ExchangeRate ,
            SellWithTaxLL = Currencys.f_ExchangeToLL(@CurrencyID, SellWithTax, SellWithTax / @ExchangeRate) ,
            SellWithTaxEuro = Currencys.f_ExchangeToEuro(@CurrencyID, SellWithTax, SellWithTax / @ExchangeRate) ,
            SellTotalWithTax = SellWithTax * QtyCurrent ,
            SellTotalWithTaxF = Currencys.f_Format(@CurrencyID, SellWithTax * QtyCurrent) ,
            ProfitRatio = Calculation.GetRate(SellLL - PurchaseLL, PurchaseLL)
        WHERE ID = @ItemSharedID;

      UPDATE Items.t_ItemShared
        SET TotalWholesalePriceD = WholesalePriceD * QtyCurrent ,
            TotalWholesalePriceLL = WholesalePriceLL * QtyCurrent ,
            TotalWholesalePriceEuro = WholesalePriceEuro * QtyCurrent ,
            TotalWholesalePriceWithTaxD = WholesalePriceWithTaxD * QtyCurrent ,
            TotalWholesalePriceWithTaxLL = WholesalePriceWithTaxLL * QtyCurrent ,
            TotalWholesalePriceWithTaxEuro = WholesalePriceWithTaxEuro * QtyCurrent ,
            TotalDistributionPriceD = DistributionPriceD * QtyCurrent ,
            TotalDistributionPriceLL = DistributionPriceLL * QtyCurrent ,
            TotalDistributionPriceEuro = DistributionPriceEuro * QtyCurrent ,
            TotalDistributionPriceWithTaxD = DistributionPriceWithTaxD * QtyCurrent ,
            TotalDistributionPriceWithTaxLL = DistributionPriceWithTaxLL * QtyCurrent ,
            TotalDistributionPriceWithTaxEuro = DistributionPriceWithTaxEuro * QtyCurrent ,
            SellTotalD = SellD * QtyCurrent ,
            SellTotalLL = SellLL * QtyCurrent ,
            SellTotalEuro = SellEuro * QtyCurrent ,
            SellTotalWithTaxD = SellWithTaxD * QtyCurrent ,
            SellTotalWithTaxLL = SellWithTaxLL * QtyCurrent ,
            SellTotalWithTaxEuro = SellWithTaxEuro * QtyCurrent
        WHERE ID = @ItemSharedID;

    END;

    BEGIN --Rebuilding statistics
	
      UPDATE Items.t_Item
        SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent)
        WHERE t_Item.SharedID = @ItemSharedID;

      UPDATE Items.t_ItemShared
        SET Barcodes = Items.f_ItemShared_GetLive_Barcodes(ID) ,
            QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent) ,
            UnityNames = Alls.f_FixXML(( SELECT N', ' + t.Unity AS [text()]
                                          FROM Items.t_UnityItem AS t
                                          WHERE t.SharedID = t_ItemShared.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            UnitsDetails = Items.f_ItemShared_Get_UnitsDetails_LIVE(ID)
        WHERE ID = @ItemSharedID;

      IF @UnityID <> @UnityIDOld
      BEGIN

        UPDATE Invoices.t_PurchasingDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_PurchasingDeletedDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_PurchasingReturnDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_PurchasingReturnDeletedDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_SoldDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_SoldDeletedDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_SoldReturnDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_SoldReturnDeletedDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Company.t_AccountItemPrice
          SET Unity = @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_TransferDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Invoices.t_TransferAwaitedDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Items.t_BeginningInventoryQuantityDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Items.t_ItemProduction
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Items.t_ItemProductionMaterial
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Items.t_ItemSharedMaterial
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;
 
        UPDATE Items.t_ItemsPackageDetails
          SET QtyWithUnit = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnitID = @ID;

        UPDATE Items.t_StockAdjustmentDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Items.t_StockTakeDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Quotations.t_QuotationDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

        UPDATE Quotations.t_QuotationHistoryDetail
          SET QtyWithUnity = Items.f_FormatQty(Qty) + ' ' + @Unity
          WHERE ItemUnityID = @ID;

      END;
   	  
      UPDATE Items.t_UnityItem
        SET ProfitRatio = Calculation.GetRate(PriceLL - CostLL, CostLL) ,
            DistributionPriceProfitRatio = Calculation.GetRate(DistributionPriceLL - CostLL, CostLL) ,
            WholesalePriceProfitRatio = Calculation.GetRate(WholesalePriceLL - CostLL, CostLL)
        WHERE ID = @ID;

    END;

    EXECUTE Items.s_UnityItemUpdateQtyPART @ID, @ItemSharedID, @Qty, @QtyOld;
  
    BEGIN --Insert t_ItemSharedMoving

      SET @Return = -1;

      INSERT INTO Items.t_ItemSharedMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ItemSharedID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

	--ENABLE TRIGGER Items.tr_Item ON Items.t_Item;
	--ENABLE TRIGGER Items.tr_ItemShared ON Items.t_ItemShared;
	--ENABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Items].[s_UnityItemUpdateIsSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItemUpdateIsSync]
  @IsSync BIT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    BEGIN --Insert

      UPDATE  Items.t_UnityItem
      SET     IsSync = @IsSync
      WHERE   ID = @ID;

    END;

    ENABLE TRIGGER Items.tr_UnityItem ON Items.t_UnityItem;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



