/****** Object:  StoredProcedure [Items].[s_UnityItemUpdateQtyPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Items].[s_UnityItemUpdateQtyPART] @ID UNIQUEIDENTIFIER ,
  @ItemSharedID UNIQUEIDENTIFIER ,
  @Qty DECIMAL(18, 2) ,
  @QtyOld DECIMAL(18, 2)
AS
BEGIN

  IF @Qty = @QtyOld
  BEGIN

    RETURN 1;

  END;

  BEGIN --Invoices
    
    UPDATE Invoices.t_PurchasingDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_PurchasingDeletedDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_PurchasingReturnDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_PurchasingReturnDeletedDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_SoldDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_SoldDeletedDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_SoldReturnDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_SoldReturnDeletedDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_TransferDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Invoices.t_TransferAwaitedDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

  END;

  BEGIN --Items
    
    UPDATE Items.t_BeginningInventoryQuantityDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;
 
    UPDATE Items.t_DeliveryPermissionDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;
 
    UPDATE Items.t_DeliveryPermissionHistoryDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;
  
    UPDATE Items.t_DeliveryPermissionDeleteDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Items.t_ItemProduction
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Items.t_ItemProductionMaterial
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Items.t_ItemSharedMaterial
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;
  
    UPDATE Items.t_ItemsPackageDetails
      SET Qtys = Qty * @Qty
      WHERE ItemUnitID = @ID;

    UPDATE Items.t_StockAdjustmentDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Items.t_StockTakeDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

  END;

  BEGIN --Quotations
    
    UPDATE Quotations.t_QuotationDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

    UPDATE Quotations.t_QuotationHistoryDetail
      SET Qtys = Qty * @Qty
      WHERE ItemUnityID = @ID;

  END;
  
  UPDATE Items.t_Item
    SET QtyCurrent = Items.f_ItemGetQty(ID)
    WHERE SharedID = @ItemSharedID;

  UPDATE Items.t_Item
    SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(@ItemSharedID, QtyCurrent)
    WHERE SharedID = @ItemSharedID;

  UPDATE Items.t_ItemShared
    SET QtyCurrent = ( SELECT COALESCE(SUM(s.QtyCurrent), 0)
                        FROM Items.t_Item AS s
                        WHERE s.SharedID = t_ItemShared.ID
                     )
    WHERE ID = @ItemSharedID;

  UPDATE Items.t_ItemShared
    SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(ID, QtyCurrent)
    WHERE ID = @ItemSharedID;

END;




