/****** Object:  StoredProcedure [Location].[s_RegionDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Location].[s_RegionDelete]
    @EventBase NVARCHAR(MAX),
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @EventType TINYINT,
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Street AS TABLE
            (
                ID UNIQUEIDENTIFIER NOT NULL,
                Name NVARCHAR(MAX) NOT NULL
            );

            DECLARE @StatesID UNIQUEIDENTIFIER,
                    @RegionCount INT,
                    @Return INT;

        END;

        BEGIN --Set

            SELECT TOP (1)
                   @StatesID = s.StatesID
            FROM Location.t_Region AS s
            WHERE s.ID = @ID
            ORDER BY s.DateCreate;

            SELECT @RegionCount = COUNT(*)
            FROM Location.t_Region AS s
            WHERE s.StatesID = @StatesID;

        END;

        BEGIN --Check

            IF @RegionCount <= 1
            BEGIN

                ROLLBACK;

                RETURN 0;

            END;

        END;

        BEGIN --Delete street

            SET @Return = 0;

            INSERT @Street
            (
                ID,
                Name
            )
            SELECT s.ID,
                   s.Name
            FROM Location.t_Street AS s
            WHERE s.RegionID = @ID;

            DELETE FROM Location.t_Street
            WHERE RegionID = @ID;

        END;

        BEGIN --Delete

            DELETE FROM Location.t_Region
            WHERE ID = @ID;

        END;

        BEGIN --Insert event

            SET @Return = -1;

