    BEGIN --Insert

      SET @Return = 0;

      INSERT  INTO Location.t_States
              ( ID ,
                Name ,
                DescriptionIs ,
                RegionC ,
                StreetC
              )
      VALUES  ( @ID ,
                @Name ,
                @DescriptionIs ,
                1 ,
                1
              );

    END;

    BEGIN --Insert Region

      INSERT  INTO Location.t_Region
              ( ID, Name, StatesID, StatesIs )
      VALUES  ( @RegionID, @RegionIs, @ID, @Name );
	  
    END;

    BEGIN --Insert Street

      INSERT  INTO Location.t_Street
              ( ID ,
                Name ,
                StatesID ,
                StatesIs ,
                RegionID ,
                RegionIs
              )
      VALUES  ( @StreetID ,
                @Street ,
                @ID ,
                @Name ,
                @RegionID ,
                @RegionIs
              );
  
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT  INTO Location.t_StatesMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    BEGIN --Insert event Region

      INSERT  INTO Location.t_RegionMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @RegionID ,
                @EventBase + @RegionIs ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    BEGIN --Insert event Street

      INSERT  INTO Location.t_StreetMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @StreetID ,
                @EventBase + @Street ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






