GO


CREATE PROCEDURE [Location].[s_StatesInsertDefaultData]
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Check

            IF EXISTS (SELECT TOP (1) ID FROM Location.t_States)
            BEGIN
			
