/****** Object:  StoredProcedure [Location].[s_StatesUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Location].[s_StatesUpdate] @Name NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Location.t_States AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Location.t_States
        SET Name = @Name ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Location.t_StatesMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix

      BEGIN --Fix Address

        UPDATE Location.t_Address
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Bank

        UPDATE Company.t_Bank
          SET StatesIs = @Name
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Contact

        UPDATE Company.t_Contact
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Customer

        UPDATE Customers.t_Customer
          SET StatesIs = @Name ,
              BirthPlaceStates = @Name ,
              DrivingLicenseStates = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-') ,
              BirthPlace = Location.f_ConcetFullAddress(@Name, BirthPlaceRegion, BirthPlaceStreet, '-', '-', '-', '-', ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Employee

        UPDATE Employees.t_Employee
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix SalesPerson

        UPDATE Employees.t_SalesPerson
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Vendor

        UPDATE Vendors.t_Vendor
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix Warehouse

        UPDATE Company.t_WareHouse
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix t_Doctor

        UPDATE Company.t_Doctor
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix t_FrameJobOrder

        UPDATE Customers.t_FrameJobOrder
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, N'', N'', N'', N'', N' - ', N'-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix t_FrameJobOrderHistory

        UPDATE Customers.t_FrameJobOrderHistory
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, N'', N'', N'', N'', N' - ', N'-')
          WHERE StatesID = @ID;

      END;

      BEGIN --Fix t_CarDriver

        UPDATE Cars.t_CarDriver
          SET StatesIs = @Name ,
              AddressIs = Location.f_ConcetFullAddress(@Name, RegionIs, Street, Building, FloorIs, PostalCode, AddressNote, ' - ', '-')
          WHERE StatesID = @ID;
 
        UPDATE Cars.t_CarDriver
          SET DrivingLicenseStates = @Name
          WHERE DrivingLicenseStatesID = @ID;
 
        UPDATE Cars.t_CarDriver
          SET BirthdayStates = @Name
          WHERE BirthdayStatesID = @ID;

      END;

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













