/****** Object:  StoredProcedure [Options].[s_WorldFoodProgrammeUpDate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Options].[s_WorldFoodProgrammeUpDate] @ShopID NVARCHAR(MAX) ,
  @BranchID NVARCHAR(MAX) ,
  @DestinationPath NVARCHAR(MAX) ,
  @FileNamePrefix NVARCHAR(MAX) ,
  @FileNameDateTimeFormat NVARCHAR(MAX) ,
  @FileNameSuffix NVARCHAR(MAX) ,
  @AutoGenerateReport TINYINT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @ShopIDOld NVARCHAR(MAX) ,
        @BranchIDOld NVARCHAR(MAX) ,
        @Return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @ShopIDOld = s.ShopID ,
          @BranchIDOld = s.BranchID
        FROM Options.t_WorldFoodProgramme AS s
        ORDER BY s.ID;

    END;

    BEGIN --Update

      SET @Return = 0;

      UPDATE Options.t_WorldFoodProgramme
        SET ShopID = @ShopID ,
            BranchID = @BranchID ,
            DestinationPath = @DestinationPath ,
            FileNamePrefix = @FileNamePrefix ,
            FileNameDateTimeFormat = @FileNameDateTimeFormat ,
            FileNameSuffix = @FileNameSuffix ,
            AutoGenerateReport = @AutoGenerateReport
        WHERE ID = @ID;

    END;

    IF @ShopID <> @ShopIDOld OR @BranchID <> @BranchIDOld
    BEGIN --Fix Invoices.t_Sold
		
      UPDATE Invoices.t_Sold
        SET WFPShopID = @ShopID ,
            WFPBranchID = @BranchID ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE WFPFrom = 1;
						
    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Options.t_WorldFoodProgrammeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




GO
/****** Object:  StoredProcedure [Quotations].[s_QuotationDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Quotations].[s_QuotationDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @AccountID UNIQUEIDENTIFIER ,
        @WarrantyID UNIQUEIDENTIFIER ,
        @TypeID UNIQUEIDENTIFIER ,
        @Return INT = 0;

    END;

    BEGIN --Set info
	    
      SELECT TOP ( 1 ) @AccountID = s.AccountID ,
          @WarrantyID = s.WarrantyID ,
          @TypeID = s.TypeID
        FROM Quotations.t_Quotation AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Delete

      DELETE FROM Quotations.t_QuotationNoteLink
        WHERE QuotationID = @ID;

      DELETE FROM Quotations.t_QuotationDetail
        WHERE QuotationID = @ID;

      DELETE FROM Quotations.t_Quotation
        WHERE ID = @ID;

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET QuotationC -= 1 ,
            QuotationTotal = Quotations.[f_QuotationGetTotalByAccountID](ID) ,
            QuotationProfit = Quotations.[f_QuotationGetProfitByAccountID](ID) ,
            QuotationLast = Quotations.f_QuotationGetLastDateByAccountID(ID)
        WHERE ID = @AccountID;

      UPDATE Company.t_Account
        SET QuotationTotalF = Currencys.f_Format(CurrencyID, QuotationTotal) ,
            QuotationProfitF = Currencys.f_Format(CurrencyID, QuotationProfit)
        WHERE ID = @AccountID;
		  
    END;
   
    BEGIN --Update t_Sold

      UPDATE Invoices.t_Sold
        SET SaveFromSection = 0 ,
            LinkID = '00000000-0000-0000-0000-000000000000' ,
            LinkRef = 0 ,
            LinkRefF = '' ,
            RowVersionID = [DateTimes].[f_GetRowVersionID]()
        WHERE SaveFromSection = 1 AND LinkID = @ID;

      UPDATE Invoices.t_SoldDeleted
        SET SaveFromSection = 0 ,
            LinkID = '00000000-0000-0000-0000-000000000000' ,
            LinkRef = 0 ,
            LinkRefF = ''
        WHERE SaveFromSection = 1 AND LinkID = @ID;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Quotations.t_QuotationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 0, 'quotation' );

    END;
	
    EXECUTE Quotations.s_QuotationLiveVersion; 

    EXECUTE Quotations.s_QuotationWarrantyAddQuotationC -1, 0, @WarrantyID; 

    EXECUTE Quotations.s_QuotationTypeAddQuotationC -1, 0, @TypeID; 

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;















GO
