/****** Object:  StoredProcedure [Quotations].[s_QuotationHistoryRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Quotations].[s_QuotationHistoryRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    DISABLE TRIGGER Quotations.tr_QuotationHistory ON Quotations.t_QuotationHistory;

    BEGIN --Rebuild statistics

      SET @Return = 0;

      UPDATE Quotations.t_QuotationHistory
        SET RefF = FORMAT(Ref, '#') ,
            CommissionRateF = FORMAT(CommissionRate, '0.##') + N' %' ,
            CommissionValueF = Currencys.f_Format(CurrencyID, CommissionValue) ,
            TotalF = Currencys.f_Format(CurrencyID, Total) ,
            DiscountIsF = Currencys.f_Format(CurrencyID, DiscountIs) ,
            TaxValueF = Currencys.f_Format(CurrencyID, TaxValue) ,
            NetIsF = Currencys.f_Format(CurrencyID, NetIs) ,
            NetIsAR = Currencys.f_ToWordAR(NetIs, CurrencyID, 1) ,
            NetIsEN = Currencys.f_ToWordEN(NetIs, CurrencyID, 1) ,
            TotalCostF = Currencys.f_Format(CurrencyID, TotalCost) ,
            TotalCostWithTaxF = Currencys.f_Format(CurrencyID, TotalCostWithTax) ,
            TotalProfitF = Currencys.f_Format(CurrencyID, TotalProfit) ,
            TotalProfitWithTaxF = Currencys.f_Format(CurrencyID, TotalProfitWithTax) ,
            ItemsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                          FROM Quotations.t_QuotationHistoryDetail AS t
                                          LEFT JOIN Items.t_ItemShared AS t1 ON t1.ID = t.ItemSharedID
                                          WHERE t.QuotationHistoryID = t_QuotationHistory.ID
                                       FOR
                                         XML PATH('')
                                       )) ,
            ItemHaveDiscount = CASE ( SELECT COALESCE(SUM(s.DiscountIsValue), 0)
                                        FROM Quotations.t_QuotationHistoryDetail AS s
                                        WHERE s.QuotationHistoryID = t_QuotationHistory.ID
                                    )
                                 WHEN 0 THEN 0
                                 ELSE 1
                               END;

      UPDATE Quotations.t_QuotationHistory
        SET TaxRateF = FORMAT(( TaxValue / ( NetIs - TaxValue ) ) * 100.0, '0.##') + N' %'
        WHERE NetIs > 0;

      WITH  o AS ( SELECT s.Price ,
                      s.PriceF ,
                      s.DiscountIs ,
                      s.DiscountIsF ,
                      s.DiscountIsValue ,
                      s.DiscountIsValueF ,
                      s.SubTotal ,
                      s.SubTotalF ,
                      s.DiscountQuotation ,
                      s.DiscountQuotationF ,
                      s.TaxRate ,
                      s.TaxRateF ,
                      s.TaxValue ,
                      s.Total ,
                      s.TotalF ,
                      s.UnitCost ,
                      s.UnitCostF ,
                      s.UnitCostWithTax ,
                      s.UnitCostWithTaxF ,
                      s.TotalCost ,
                      s.TotalCostF ,
                      s.TotalCostWithTax ,
                      s.TotalCostWithTaxF ,
                      s.UnitProfit ,
                      s.UnitProfitF ,
                      s.UnitProfitWithTax ,
                      s.UnitProfitWithTaxF ,
                      s.TotalProfit ,
                      s.TotalProfitF ,
                      s.TotalProfitWithTax ,
                      s.TotalProfitWithTaxF ,
                      s1.CurrencyID ,
                      s.Qty ,
                      s.Qtys ,
                      s.QtyWithUnity ,
                      s3.Name AS Unity
                    FROM Quotations.t_QuotationHistoryDetail AS s
                    LEFT JOIN Quotations.t_QuotationHistory AS s1 ON s1.ID = s.QuotationHistoryID
                    LEFT JOIN Items.t_UnityItem AS s2 ON s2.ID = s.ItemUnityID
                    LEFT JOIN Items.t_Unity AS s3 ON s3.ID = s2.UnityID
                 )
        UPDATE o
          SET o.PriceF = Currencys.f_Format(o.CurrencyID, o.Price) ,
              o.DiscountIsF = Currencys.f_FormatRate(o.DiscountIs) ,
              o.DiscountIsValueF = Currencys.f_Format(o.CurrencyID, o.DiscountIsValue) ,
              o.SubTotalF = Currencys.f_Format(o.CurrencyID, o.SubTotal) ,
              o.DiscountQuotationF = Currencys.f_Format(o.CurrencyID, o.DiscountQuotation) ,
              o.TaxRateF = Currencys.f_FormatRate(o.TaxRate) ,
              o.TotalF = Currencys.f_Format(o.CurrencyID, o.Total) ,
              o.UnitCostF = Currencys.f_Format(o.CurrencyID, o.UnitCost) ,
              o.UnitCostWithTaxF = Currencys.f_Format(o.CurrencyID, o.UnitCostWithTax) ,
              o.TotalCostF = Currencys.f_Format(o.CurrencyID, o.TotalCost) ,
              o.TotalCostWithTaxF = Currencys.f_Format(o.CurrencyID, o.TotalCostWithTax) ,
              o.UnitProfitF = Currencys.f_Format(o.CurrencyID, o.UnitProfit) ,
              o.UnitProfitWithTaxF = Currencys.f_Format(o.CurrencyID, o.UnitProfitWithTax) ,
              o.TotalProfitF = Currencys.f_Format(o.CurrencyID, o.TotalProfit) ,
              o.TotalProfitWithTaxF = Currencys.f_Format(o.CurrencyID, o.TotalProfitWithTax) ,
              o.QtyWithUnity = FORMAT(o.Qty, '#,##0.##') + ' ' + o.Unity;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Quotations.t_QuotationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, Quotation, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaQuotation, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    ENABLE TRIGGER Quotations.tr_QuotationHistory ON Quotations.t_QuotationHistory;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;






GO
/****** Object:  StoredProcedure [Quotations].[s_QuotationInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Quotations].[s_QuotationInsert] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @SourceID UNIQUEIDENTIFIER ,
  @SourceRef BIGINT ,
  @SourceRefF NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @CommissionRate DECIMAL(18, 2) ,
  @CommissionRateF NVARCHAR(MAX) ,
  @CommissionRateType TINYINT ,
  @CommissionValue FLOAT ,
  @CommissionValueF NVARCHAR(MAX) ,
  @CommissionValueD FLOAT ,
  @CommissionValueLL FLOAT ,
  @CommissionValueEuro FLOAT ,
  @AttentionTo NVARCHAR(MAX) ,
  @SubjectIs NVARCHAR(MAX) ,
  @WarrantyID UNIQUEIDENTIFIER ,
  @TypeID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @DiscountIs FLOAT ,
  @DiscountIsF NVARCHAR(MAX) ,
  @DiscountIsD FLOAT ,
  @DiscountIsLL FLOAT ,
  @DiscountIsEuro FLOAT ,
  @TaxRate DECIMAL(5, 2) ,
  @TaxRateF NVARCHAR(MAX) ,
  @TaxValue FLOAT ,
  @TaxValueF NVARCHAR(MAX) ,
  @TaxValueD FLOAT ,
  @TaxValueLL FLOAT ,
  @TaxValueEuro FLOAT ,
  @NetIs FLOAT ,
  @NetIsF NVARCHAR(MAX) ,
  @NetIsD FLOAT ,
  @NetIsLL FLOAT ,
  @NetIsEuro FLOAT ,
  @TotalCost FLOAT ,
  @TotalCostF NVARCHAR(MAX) ,
  @TotalCostD FLOAT ,
  @TotalCostLL FLOAT ,
  @TotalCostEuro FLOAT ,
  @TotalCostWithTax FLOAT ,
  @TotalCostWithTaxF NVARCHAR(MAX) ,
  @TotalCostWithTaxD FLOAT ,
  @TotalCostWithTaxLL FLOAT ,
  @TotalCostWithTaxEuro FLOAT ,
  @TotalProfit FLOAT ,
  @TotalProfitF NVARCHAR(MAX) ,
  @TotalProfitD FLOAT ,
  @TotalProfitLL FLOAT ,
  @TotalProfitEuro FLOAT ,
  @TotalProfitWithTax FLOAT ,
  @TotalProfitWithTaxF NVARCHAR(MAX) ,
  @TotalProfitWithTaxD FLOAT ,
  @TotalProfitWithTaxLL FLOAT ,
  @TotalProfitWithTaxEuro FLOAT ,
  @GhanaSystem BIT ,
  @GS_Covid19Rate FLOAT ,
  @GS_NHILRate FLOAT ,
  @GS_GetfundLevyRate FLOAT ,
  @GS_TaxRate FLOAT ,
  @GS_Reverse FLOAT ,
  @Qtys DECIMAL(18, 2) ,
  @StatusIs TINYINT ,
  @NotificationAfterDays TINYINT ,
  @NotificationDate DATE ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @ItemHaveDiscount BIT ,
  @DetailIs Quotations.[tt_QuotationDetail] READONLY ,
  @Notes [Quotations].[tt_QuotationNoteLink] READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @NetIsAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
        @NetIsEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@NetIs, @CurrencyID, 1) ,
        @Return INT = 0;

    END;

    BEGIN --Set info

      SELECT @Ref = COALESCE(MAX(o.Ref), 0) + 1
        FROM ( SELECT s.Ref
                FROM Quotations.t_Quotation AS s
               UNION ALL
               SELECT s.Ref
                FROM Quotations.t_QuotationHistory AS s
             ) AS o;

      SET @RefF = FORMAT(@Ref, '#');

    END;

    BEGIN --Insert

      INSERT INTO Quotations.t_Quotation
          ( ID ,
            Ref ,
            RefF ,
            RefPaper ,
            SourceType ,
            SourceID ,
            SourceRef ,
            SourceRefF ,
            DateIs ,
            DateOnly ,
            DateMonthly ,
            DateYearly ,
            AccountID ,
            SalespersonID ,
            CommissionRate ,
            CommissionRateF ,
            CommissionRateType ,
            CommissionValue ,
            CommissionValueF ,
            CommissionValueD ,
            CommissionValueLL ,
            CommissionValueEuro ,
            AttentionTo ,
            SubjectIs ,
            WarrantyID ,
            TypeID ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsD ,
            DiscountIsLL ,
            DiscountIsEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            NetIs ,
            NetIsF ,
            NetIsD ,
            NetIsLL ,
            NetIsEuro ,
            NetIsAR ,
            NetIsEN ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            TotalCostWithTax ,
            TotalCostWithTaxF ,
            TotalCostWithTaxD ,
            TotalCostWithTaxLL ,
            TotalCostWithTaxEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            TotalProfitWithTax ,
            TotalProfitWithTaxF ,
            TotalProfitWithTaxD ,
            TotalProfitWithTaxLL ,
            TotalProfitWithTaxEuro ,
            GhanaSystem ,
            GS_Covid19Rate ,
            GS_NHILRate ,
            GS_GetfundLevyRate ,
            GS_TaxRate ,
            GS_Reverse ,
            Qtys ,
            StatusIs ,
            WhyThisStatus ,
            IsConfirm ,
            NotificationAfterDays ,
            NotificationDate ,
            NotificationStop ,
            NotificationTextAR ,
