/****** Object:  StoredProcedure [Quotations].[s_QuotationTypeRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Quotations].[s_QuotationTypeRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Rebuild statistics

      UPDATE Quotations.t_QuotationType
        SET QuotationActiveC = ( SELECT COUNT(*) AS Total
                                  FROM Quotations.t_QuotationHistory AS s
                                  WHERE ( s.TypeID = t_QuotationType.ID )
                               ) ,
            QuotationArchivedC = ( SELECT COUNT(*) AS Total
                                    FROM Quotations.t_QuotationHistory AS s
                                    WHERE ( s.TypeID = t_QuotationType.ID )
                                 ) ,
            IsSync = 0;

      UPDATE Quotations.t_QuotationType
        SET QuotationC = QuotationActiveC + QuotationArchivedC;

    END;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Quotations.t_QuotationTypeMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Quotations.s_QuotationTypeLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;




