CREATE PROCEDURE [Quotations].[s_QuotationUpdate] @ID UNIQUEIDENTIFIER ,
  @RefPaper NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @SourceID UNIQUEIDENTIFIER ,
  @SourceRef BIGINT ,
  @SourceRefF NVARCHAR(MAX) ,
  @DateIs DATETIME ,
  @AccountID UNIQUEIDENTIFIER ,
  @SalespersonID UNIQUEIDENTIFIER ,
  @CommissionRate DECIMAL(18, 2) ,
  @CommissionRateF NVARCHAR(MAX) ,
  @CommissionRateType TINYINT ,
  @CommissionValue FLOAT ,
  @CommissionValueF NVARCHAR(MAX) ,
  @CommissionValueD FLOAT ,
  @CommissionValueLL FLOAT ,
  @CommissionValueEuro FLOAT ,
  @AttentionTo NVARCHAR(MAX) ,
  @SubjectIs NVARCHAR(MAX) ,
  @WarrantyID UNIQUEIDENTIFIER ,
  @TypeID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @Currency NVARCHAR(MAX) ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Total FLOAT ,
  @TotalF NVARCHAR(MAX) ,
  @TotalD FLOAT ,
  @TotalLL FLOAT ,
  @TotalEuro FLOAT ,
  @DiscountIs FLOAT ,
  @DiscountIsF NVARCHAR(MAX) ,
  @DiscountIsD FLOAT ,
  @DiscountIsLL FLOAT ,
  @DiscountIsEuro FLOAT ,
  @TaxRate DECIMAL(5, 2) ,
  @TaxRateF NVARCHAR(MAX) ,
  @TaxValue FLOAT ,
  @TaxValueF NVARCHAR(MAX) ,
  @TaxValueD FLOAT ,
  @TaxValueLL FLOAT ,
  @TaxValueEuro FLOAT ,
  @NetIs FLOAT ,
  @NetIsF NVARCHAR(MAX) ,
  @NetIsD FLOAT ,
  @NetIsLL FLOAT ,
  @NetIsEuro FLOAT ,
  @TotalCost FLOAT ,
  @TotalCostF NVARCHAR(MAX) ,
  @TotalCostD FLOAT ,
  @TotalCostLL FLOAT ,
  @TotalCostEuro FLOAT ,
  @TotalCostWithTax FLOAT ,
  @TotalCostWithTaxF NVARCHAR(MAX) ,
  @TotalCostWithTaxD FLOAT ,
  @TotalCostWithTaxLL FLOAT ,
  @TotalCostWithTaxEuro FLOAT ,
  @TotalProfit FLOAT ,
  @TotalProfitF NVARCHAR(MAX) ,
  @TotalProfitD FLOAT ,
  @TotalProfitLL FLOAT ,
  @TotalProfitEuro FLOAT ,
  @TotalProfitWithTax FLOAT ,
  @TotalProfitWithTaxF NVARCHAR(MAX) ,
  @TotalProfitWithTaxD FLOAT ,
  @TotalProfitWithTaxLL FLOAT ,
  @TotalProfitWithTaxEuro FLOAT ,
  @GhanaSystem BIT ,
  @GS_Covid19Rate FLOAT ,
  @GS_NHILRate FLOAT ,
  @GS_GetfundLevyRate FLOAT ,
  @GS_TaxRate FLOAT ,
  @GS_Reverse FLOAT ,
  @Qtys DECIMAL(18, 2) ,
  @StatusIs TINYINT ,
  @NotificationAfterDays TINYINT ,
  @NotificationDate DATE ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @ItemsNames NVARCHAR(MAX) ,
  @ItemHaveDiscount BIT ,
  @DetailIs Quotations.[tt_QuotationDetail] READONLY ,
  @Notes [Quotations].[tt_QuotationNoteLink] READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @AccountID_Old UNIQUEIDENTIFIER ,
        @NetIsAR NVARCHAR(MAX) = Currencys.f_ToWordAR(@NetIs, @CurrencyID, 1) ,
        @NetIsEN NVARCHAR(MAX) = Currencys.f_ToWordEN(@NetIs, @CurrencyID, 1) ,
        @Return INT  = 0;

    END;

    BEGIN --Set info
	 
      SELECT TOP ( 1 ) @AccountID_Old = s.AccountID
        FROM Quotations.t_Quotation AS s
        WHERE s.ID = @ID;

    END;

    BEGIN --Update

      UPDATE Quotations.t_Quotation
        SET RefPaper = @RefPaper ,
            SourceType = @SourceType ,
            SourceID = @SourceID ,
            SourceRef = @SourceRef ,
            SourceRefF = @SourceRefF ,
            DateIs = @DateIs ,
            DateOnly = @DateIs ,
            DateMonthly = DATEFROMPARTS(YEAR(@DateIs), MONTH(@DateIs), 1) ,
            DateYearly = DATEFROMPARTS(YEAR(@DateIs), 1, 1) ,
            AccountID = @AccountID ,
            SalespersonID = @SalespersonID ,
            CommissionRate = @CommissionRate ,
            CommissionRateF = @CommissionRateF ,
            CommissionRateType = @CommissionRateType ,
            CommissionValue = @CommissionValue ,
            CommissionValueF = @CommissionValueF ,
            CommissionValueD = @CommissionValueD ,
            CommissionValueLL = @CommissionValueLL ,
            CommissionValueEuro = @CommissionValueEuro ,
            AttentionTo = @AttentionTo ,
            SubjectIs = @SubjectIs ,
            WarrantyID = @WarrantyID ,
            TypeID = @TypeID ,
            CurrencyID = @CurrencyID ,
            ExchangeRate = @ExchangeRate ,
            ExchangeRateLL = @ExchangeRateLL ,
            ExchangeRateEuro = @ExchangeRateEuro ,
            Total = @Total ,
            TotalF = @TotalF ,
            TotalD = @TotalD ,
            TotalLL = @TotalLL ,
            TotalEuro = @TotalEuro ,
            DiscountIs = @DiscountIs ,
            DiscountIsF = @DiscountIsF ,
            DiscountIsD = @DiscountIsD ,
            DiscountIsLL = @DiscountIsLL ,
            DiscountIsEuro = @DiscountIsEuro ,
            TaxRate = @TaxRate ,
            TaxRateF = @TaxRateF ,
            TaxValue = @TaxValue ,
            TaxValueF = @TaxValueF ,
            TaxValueD = @TaxValueD ,
            TaxValueLL = @TaxValueLL ,
            TaxValueEuro = @TaxValueEuro ,
            NetIs = @NetIs ,
            NetIsF = @NetIsF ,
            NetIsD = @NetIsD ,
            NetIsLL = @NetIsLL ,
            NetIsEuro = @NetIsEuro ,
            NetIsAR = @NetIsAR ,
            NetIsEN = @NetIsEN ,
            TotalCost = @TotalCost ,
            TotalCostF = @TotalCostF ,
            TotalCostD = @TotalCostD ,
            TotalCostLL = @TotalCostLL ,
            TotalCostEuro = @TotalCostEuro ,
            TotalCostWithTax = @TotalCostWithTax ,
            TotalCostWithTaxF = @TotalCostWithTaxF ,
            TotalCostWithTaxD = @TotalCostWithTaxD ,
            TotalCostWithTaxLL = @TotalCostWithTaxLL ,
            TotalCostWithTaxEuro = @TotalCostWithTaxEuro ,
            TotalProfit = @TotalProfit ,
            TotalProfitF = @TotalProfitF ,
            TotalProfitD = @TotalProfitD ,
            TotalProfitLL = @TotalProfitLL ,
            TotalProfitEuro = @TotalProfitEuro ,
            TotalProfitWithTax = @TotalProfitWithTax ,
            TotalProfitWithTaxF = @TotalProfitWithTaxF ,
            TotalProfitWithTaxD = @TotalProfitWithTaxD ,
            TotalProfitWithTaxLL = @TotalProfitWithTaxLL ,
            TotalProfitWithTaxEuro = @TotalProfitWithTaxEuro ,
            GhanaSystem = @GhanaSystem ,
            GS_Covid19Rate = @GS_Covid19Rate ,
            GS_NHILRate = @GS_NHILRate ,
            GS_GetfundLevyRate = @GS_GetfundLevyRate ,
            GS_TaxRate = @GS_TaxRate ,
            GS_Reverse = @GS_Reverse ,
            Qtys = @Qtys ,
            StatusIs = @StatusIs ,
            IsConfirm = 0 ,
            NotificationAfterDays = @NotificationAfterDays ,
            NotificationDate = @NotificationDate ,
            NotificationStop = 0 ,
            NotificationTextAR = @NotificationTextAR ,
            NotificationTextEN = @NotificationTextEN ,
            DescriptionIs = @DescriptionIs ,
            ItemsNames = @ItemsNames ,
            ItemHaveDiscount = @ItemHaveDiscount
        WHERE ID = @ID;

    END;

    BEGIN --Delete t_QuotationDetail

      DELETE FROM Quotations.t_QuotationDetail
        WHERE QuotationID = @ID;

    END;

    BEGIN --Insert t_QuotationDetail

      INSERT INTO Quotations.t_QuotationDetail
          ( ID ,
            QuotationID ,
            ItemSharedID ,
            ItemUnityID ,
            PackUnitID ,
            PackUnitQty ,
            PackQtys ,
            Qty ,
            QtyWithUnity ,
            Qtys ,
            Price ,
            PriceF ,
            PriceD ,
            PriceLL ,
            PriceEuro ,
            DiscountIs ,
            DiscountIsF ,
            DiscountIsValue ,
            DiscountIsValueF ,
            DiscountIsValueD ,
            DiscountIsValueLL ,
            DiscountIsValueEuro ,
            SubTotal ,
            SubTotalF ,
            SubTotalD ,
            SubTotalLL ,
            SubTotalEuro ,
            DiscountQuotation ,
            DiscountQuotationF ,
            DiscountQuotationD ,
            DiscountQuotationLL ,
            DiscountQuotationEuro ,
            TaxRate ,
            TaxRateF ,
            TaxValue ,
            TaxValueF ,
            TaxValueD ,
            TaxValueLL ,
            TaxValueEuro ,
            Total ,
            TotalF ,
            TotalD ,
            TotalLL ,
            TotalEuro ,
            UnitCost ,
            UnitCostF ,
            UnitCostD ,
            UnitCostLL ,
            UnitCostEuro ,
            UnitCostWithTax ,
            UnitCostWithTaxF ,
            UnitCostWithTaxD ,
            UnitCostWithTaxLL ,
            UnitCostWithTaxEuro ,
            TotalCost ,
            TotalCostF ,
            TotalCostD ,
            TotalCostLL ,
            TotalCostEuro ,
            TotalCostWithTax ,
            TotalCostWithTaxF ,
            TotalCostWithTaxD ,
            TotalCostWithTaxLL ,
            TotalCostWithTaxEuro ,
            UnitProfit ,
            UnitProfitF ,
            UnitProfitD ,
            UnitProfitLL ,
            UnitProfitEuro ,
            UnitProfitWithTax ,
            UnitProfitWithTaxF ,
            UnitProfitWithTaxD ,
            UnitProfitWithTaxLL ,
            UnitProfitWithTaxEuro ,
            TotalProfit ,
            TotalProfitF ,
            TotalProfitD ,
            TotalProfitLL ,
            TotalProfitEuro ,
            TotalProfitWithTax ,
            TotalProfitWithTaxF ,
            TotalProfitWithTaxD ,
            TotalProfitWithTaxLL ,
            TotalProfitWithTaxEuro ,
            DescriptionIs ,
            SortAt
          )
        SELECT s.ID ,
            s.QuotationID ,
            s.ItemSharedID ,
            s.ItemUnityID ,
            s.PackUnitID ,
            s.PackUnitQty ,
            s.PackQtys ,
            s.Qty ,
            s.QtyWithUnity ,
            s.Qtys ,
            s.Price ,
            s.PriceF ,
            s.PriceD ,
            s.PriceLL ,
            s.PriceEuro ,
            s.DiscountIs ,
            s.DiscountIsF ,
            s.DiscountIsValue ,
            s.DiscountIsValueF ,
            s.DiscountIsValueD ,
            s.DiscountIsValueLL ,
            s.DiscountIsValueEuro ,
            s.SubTotal ,
            s.SubTotalF ,
            s.SubTotalD ,
            s.SubTotalLL ,
            s.SubTotalEuro ,
            s.DiscountQuotation ,
            s.DiscountQuotationF ,
            s.DiscountQuotationD ,
            s.DiscountQuotationLL ,
            s.DiscountQuotationEuro ,
            s.TaxRate ,
            s.TaxRateF ,
            s.TaxValue ,
            s.TaxValueF ,
            s.TaxValueD ,
            s.TaxValueLL ,
            s.TaxValueEuro ,
            s.Total ,
            s.TotalF ,
            s.TotalD ,
            s.TotalLL ,
            s.TotalEuro ,
            s.UnitCost ,
            s.UnitCostF ,
            s.UnitCostD ,
            s.UnitCostLL ,
            s.UnitCostEuro ,
            s.UnitCostWithTax ,
            s.UnitCostWithTaxF ,
            s.UnitCostWithTaxD ,
            s.UnitCostWithTaxLL ,
            s.UnitCostWithTaxEuro ,
            s.TotalCost ,
            s.TotalCostF ,
            s.TotalCostD ,
            s.TotalCostLL ,
            s.TotalCostEuro ,
            s.TotalCostWithTax ,
            s.TotalCostWithTaxF ,
            s.TotalCostWithTaxD ,
            s.TotalCostWithTaxLL ,
            s.TotalCostWithTaxEuro ,
            s.UnitProfit ,
            s.UnitProfitF ,
            s.UnitProfitD ,
            s.UnitProfitLL ,
            s.UnitProfitEuro ,
            s.UnitProfitWithTax ,
            s.UnitProfitWithTaxF ,
            s.UnitProfitWithTaxD ,
            s.UnitProfitWithTaxLL ,
            s.UnitProfitWithTaxEuro ,
            s.TotalProfit ,
            s.TotalProfitF ,
            s.TotalProfitD ,
            s.TotalProfitLL ,
            s.TotalProfitEuro ,
            s.TotalProfitWithTax ,
            s.TotalProfitWithTaxF ,
            s.TotalProfitWithTaxD ,
            s.TotalProfitWithTaxLL ,
            s.TotalProfitWithTaxEuro ,
            s.DescriptionIs ,
            s.SortAt
          FROM @DetailIs AS s;

    END;

    BEGIN --Insert t_QuotationNoteLink

      DELETE FROM Quotations.t_QuotationNoteLink
        WHERE QuotationID = @ID;

      INSERT INTO Quotations.t_QuotationNoteLink
          ( QuotationID ,
            NoteID ,
            SortAt
          )
        SELECT @ID ,
            s.NoteID ,
            s.SortAt
          FROM @Notes AS s;

    END;

    DECLARE @NumberIs BIGINT = Company.f_AccountGetNumber(@AccountID);
    IF @NumberIs <> 4010100001 AND @NumberIs <> 4110100001
    BEGIN --Insert last price

      DECLARE @DetailIsDistinct AS TABLE
        (
          ItemSharedID UNIQUEIDENTIFIER NOT NULL ,
          ItemUnityID UNIQUEIDENTIFIER NOT NULL ,
          Price FLOAT NOT NULL ,
          DiscountIs DECIMAL(5, 2) NOT NULL
        );

      DECLARE @DistinctIDs AS TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      INSERT INTO @DistinctIDs
          ( ID
          )
        SELECT MIN(s.ID)
          FROM @DetailIs AS s
          WHERE s.Price <> 0
          GROUP BY s.ItemUnityID;

      INSERT INTO @DetailIsDistinct
          ( ItemSharedID ,
            ItemUnityID ,
            Price ,
            DiscountIs
          )
        SELECT o1.ItemSharedID ,
            o1.ItemUnityID ,
            o1.Price ,
            o1.DiscountIs
          FROM @DistinctIDs AS o
          INNER JOIN @DetailIs AS o1 ON o1.ID = o.ID;

      MERGE Company.t_AccountItemPrice AS t
      USING @DetailIsDistinct AS s
      ON s.ItemUnityID = t.ItemUnityID AND t.AccountID = @AccountID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( AccountID ,
                 ItemSharedID ,
                 ItemUnityID ,
                 Unity ,
                 CurrencyID ,
                 Currency ,
                 Price ,
                 PriceF ,
                 PriceD ,
                 DiscountIs ,
                 DiscountIsF ,
                 SectionIs
               )
        VALUES ( @AccountID ,
                 s.ItemSharedID ,
                 s.ItemUnityID ,
                 Items.f_UnityItemGetName(s.ItemUnityID) ,
                 @CurrencyID ,
                 @Currency ,
                 s.Price ,
                 Currencys.f_Format(@CurrencyID, s.Price) ,
                 s.Price / @ExchangeRate ,
                 s.DiscountIs ,
                 Currencys.f_FormatRate(s.DiscountIs) ,
                 2
               )
      WHEN MATCHED THEN
        UPDATE SET t.CurrencyID = @CurrencyID ,
                    t.Currency = @Currency ,
                    t.Price = s.Price ,
                    t.PriceF = Currencys.f_Format(@CurrencyID, s.Price) ,
                    t.PriceD = s.Price / @ExchangeRate ,
                    t.DiscountIs = s.DiscountIs ,
                    t.DiscountIsF = Currencys.f_FormatRate(s.DiscountIs);

    END;

    BEGIN --Fix t_Account

      UPDATE Company.t_Account
        SET QuotationTotal = Quotations.f_QuotationGetTotalByAccountID(ID) ,
            QuotationProfit = Quotations.f_QuotationGetProfitByAccountID(ID) ,
            QuotationLast = Quotations.f_QuotationGetLastDateByAccountID(ID)
        WHERE ID = @AccountID OR ID = @AccountID_Old;

      UPDATE Company.t_Account
        SET QuotationTotalF = Currencys.f_Format(CurrencyID, QuotationTotal) ,
            QuotationProfitF = Currencys.f_Format(CurrencyID, QuotationProfit)
        WHERE ID = @AccountID OR ID = @AccountID_Old;
		  
    END;

    BEGIN --Insert t_QuotationMoving

      SET @Return = -1;

      INSERT INTO Quotations.t_QuotationMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Quotations.s_QuotationWarrantyAddQuotationC -1, 0, @WarrantyID; 
    EXECUTE Quotations.s_QuotationWarrantyAddQuotationC 1, 0, @WarrantyID; 

    EXECUTE Quotations.s_QuotationTypeAddQuotationC -1, 0, @TypeID; 
    EXECUTE Quotations.s_QuotationTypeAddQuotationC 1, 0, @TypeID; 

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Quotations].[s_QuotationUpdateIsConfirm]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [Quotations].[s_QuotationUpdateIsConfirm]
    @IsConfirm bit,
    @UserID UNIQUEIDENTIFIER,
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @IDAndEvent Alls.tt_IDAndEvent READONLY
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        BEGIN --Update 

            SET @Return = 0;

            UPDATE Quotations.t_Quotation
            SET IsConfirm = @IsConfirm
            WHERE EXISTS
            (
                SELECT TOP (1) s.ID FROM @IDAndEvent AS s WHERE s.ID = t_Quotation.ID
            );

        END;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Quotations.t_QuotationMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            SELECT @UserID,
                   s.ID,
                   s.EventIs,
                   1,
                   @ComputerIP,
                   @Computer,
                   @ComputerAccount
            FROM @IDAndEvent AS s;

        END;

        COMMIT TRANSACTION;

        SELECT 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        SELECT @Return;

    END CATCH;

END;











