GO

CREATE PROCEDURE [Quotations].[s_QuotationUpdateTransmission] @ID UNIQUEIDENTIFIER ,
  @TransmissionType TINYINT ,
  @TransmissionID UNIQUEIDENTIFIER ,
  @TransmissionRef BIGINT ,
  @TransmissionRefF NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0;

    END;

    BEGIN --Update

      UPDATE Quotations.t_Quotation
        SET TransmissionType = @TransmissionType ,
            TransmissionID = @TransmissionID ,
            TransmissionRef = @TransmissionRef ,
            TransmissionRefF = @TransmissionRefF
        WHERE ID = @ID;

    END;
	
    SET @Return = -1;
    EXECUTE Quotations.s_QuotationMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    EXECUTE Quotations.s_QuotationLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;








