/****** Object:  StoredProcedure [Quotations].[s_QuotationWarrantyAddQuotationC]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Quotations].[s_QuotationWarrantyAddQuotationC] @QuotationActiveC BIGINT ,
  @QuotationArchivedC BIGINT ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN

  DECLARE @QuotationC BIGINT = @QuotationActiveC + @QuotationArchivedC;

  UPDATE Quotations.t_QuotationWarranty
    SET QuotationC = QuotationActiveC + QuotationArchivedC + @QuotationC ,
        QuotationActiveC += @QuotationActiveC ,
        QuotationArchivedC += @QuotationArchivedC ,
        IsSync = 0
    WHERE ID = @ID;

  EXECUTE Quotations.s_QuotationWarrantyLiveVersion;

END;



