/****** Object:  StoredProcedure [Transactions].[s_TransactionDetailUpdateNotSyncImage]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Transactions].[s_TransactionDetailUpdateNotSyncImage] @IDAndEvent Alls.tt_Guid READONLY
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

    BEGIN --Update

      UPDATE Transactions.t_TransactionDetail
        SET IsSyncImage = IIF(TypeIs = 1, 0, 1)
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @IDAndEvent AS s
                        WHERE s.ID = t_TransactionDetail.ID );

    END;

    ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;
		  
    BEGIN --Live

      UPDATE Alls.t_LiveVersion
        SET VersionLive = STUFF(VersionLive, TransactionIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
            SchemasIs = STUFF(SchemasIs, SchemaTransaction, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

    END;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT 0;

  END CATCH;

END;











