CREATE PROCEDURE [Transactions].[s_TransactionInsert] @PaperRef NVARCHAR(MAX) ,
  @TypeIs NVARCHAR(225) ,
  @DateIs DATETIME ,
  @BalanceType TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @SourceID UNIQUEIDENTIFIER ,
  @SourceRef BIGINT ,
  @SourceRefF NVARCHAR(MAX) ,
  @DetailIs Transactions.dt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @DetailsCount INT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
        FROM Transactions.t_Transaction AS s
        WHERE s.TypeIs = @TypeIs;

      SELECT @DetailsCount = COUNT(*)
        FROM @DetailIs AS s;
            
    END;

    BEGIN --Insert transaction

      SET @return = 0;

      INSERT INTO Transactions.t_Transaction
          ( ID ,
            Ref ,
            PaperRef ,
            TypeIs ,
            BalanceType ,
            DateIs ,
            DescriptionIs ,
            UserID ,
            SourceType ,
            SourceID ,
            SourceRef ,
            SourceRefF ,
            DetailsCount
          )
        VALUES
          ( @ID ,
            @Ref ,
            @PaperRef ,
            @TypeIs ,
            @BalanceType ,
            @DateIs ,
            @DescriptionIs ,
            @UserID ,
            @SourceType ,
            @SourceID ,
            @SourceRef ,
            @SourceRefF ,
            @DetailsCount
          );

    END;

    BEGIN --Insert detail

      INSERT INTO Transactions.t_TransactionDetail
          ( ID ,
            RowNumber ,
            TransactionID ,
            AccountID ,
            DateIs ,
            CurrencyID ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            BalanceType ,
            Balance ,
            BalanceD ,
            BalanceLL ,
            BalanceEuro ,
            StatementIs ,
            TypeIs ,
            ChequeNumber ,
            ChequeImage ,
            ChequeImagePath ,
            ChequeNote ,
            ChequeDateGet ,
            ChequeStopNotificationGet ,
            NotificationTextAR ,
            NotificationTextEN 
          )
        SELECT t.ID ,
            t.RowNumber ,
            @ID ,
            t.AccountID ,
            t.DateIs ,
            t.CurrencyID ,
            t.ExchangeRate ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            @BalanceType ,
            t.Balance ,
            t.BalanceD ,
            t.BalanceLL ,
            t.BalanceEuro ,
            t.StatementIs ,
            t.TypeIs ,
            t.ChequeNumber ,
            t.ChequeImage ,
            t.ChequeImagePath ,
            t.ChequeNote ,
            t.ChequeDateGet ,
            t.ChequeStopNotificationGet ,
            t.NotificationTextAR ,
            t.NotificationTextEN
          FROM @DetailIs AS t
          ORDER BY t.RowNumber;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @DetailIs AS s
                        WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

    END;
	
    BEGIN --Fix t_Transaction

      EXECUTE Transactions.s_TransactionFixPart @ID;

    END;

    SET @return = -1;
    SET @Event += FORMAT(@Ref, '#');
    EXECUTE Transactions.s_TransactionMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;
	
    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;









GO
