CREATE PROCEDURE [Transactions].[s_TransactionInsert2] @ID UNIQUEIDENTIFIER ,
  @PaperRef NVARCHAR(MAX) ,
  @TypeIs NVARCHAR(225) ,
  @BalanceType TINYINT ,
  @DateIs DATETIME ,
  @DateOnly DATE ,
  @DateFirstDayInMonth DATE ,
  @DateFirstDayInYear DATE ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @SourceType TINYINT,
  @SourceID UNIQUEIDENTIFIER,
  @SourceRef BIGINT,
  @SourceRefF NVARCHAR(MAX) ,
  @DescriptionIs NVARCHAR(MAX) ,
  @LinkType INT ,
  @LinkTypeSub TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @SubLinkID UNIQUEIDENTIFIER ,
  @AccountsNames NVARCHAR(MAX) ,
  @DetailsCount INT ,
  @DetailIs Transactions.dt_TransactionDetailFull READONLY ,
  @EventIs NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @RefF NVARCHAR(MAX) ,
        @Return INT= 0;

    END;

    BEGIN --Set Info

      SET @Ref = Transactions.f_TransactionGetNewRef(@TypeIs);
      SET @RefF = FORMAT(@Ref, '#');

    END;

    BEGIN --Insert t_Transaction

      INSERT INTO Transactions.t_Transaction
          ( ID ,
            Ref ,
            RefF ,
            PaperRef ,
            TypeIs ,
            BalanceType ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            SourceType ,
            SourceID ,
            SourceRef ,
            SourceRefF ,
            LinkType ,
            LinkTypeSub ,
            LinkID ,
            SubLinkID ,
            AccountsNames ,
            DetailsCount 
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @PaperRef ,
            @TypeIs ,
            @BalanceType ,
            @DateIs ,
            @DateOnly ,
            @DateFirstDayInMonth ,
            @DateFirstDayInYear ,
            @UserID ,
            @UserIs ,
            @DescriptionIs ,
            @SourceType ,
            @SourceID ,
            @SourceRef ,
            @SourceRefF ,
            @LinkType ,
            @LinkTypeSub ,
            @LinkID ,
            @SubLinkID ,
            @AccountsNames ,
            @DetailsCount 
          );

    END;

    BEGIN --Insert t_TransactionDetail

      INSERT INTO Transactions.t_TransactionDetail
          ( ID ,
            RowNumber ,
            TransactionID ,
            AccountID ,
            Account ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            CurrencyID ,
            Currency ,
            CurrencyTypeIs ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            BalanceType ,
            Balance ,
            BalanceF ,
            BalanceD ,
            BalanceLL ,
            BalanceEuro ,
            BalanceAR ,
            BalanceEN ,
            Credit ,
            CreditD ,
            CreditLL ,
            CreditEuro ,
            Debit ,
            DebitD ,
            DebitLL ,
            DebitEuro ,
            StatementIs ,
            TypeIs ,
            ChequeNumber ,
            ChequeImage ,
            ChequeImagePath ,
            ChequeNote ,
            ChequeDateGet ,
            ChequeStopNotificationGet ,
            NotificationTextAR ,
            NotificationTextEN
          )
        SELECT t.ID ,
            t.RowNumber ,
            t.TransactionID ,
            t.AccountID ,
            t.Account ,
            t.DateIs ,
            t.DateOnly ,
            t.DateFirstDayInMonth ,
            t.DateFirstDayInYear ,
            t.CurrencyID ,
            t.Currency ,
            t.CurrencyTypeIs ,
            t.ExchangeRate ,
            t.ExchangeRateLL ,
            t.ExchangeRateEuro ,
            t.BalanceType ,
            t.Balance ,
            t.BalanceF ,
            t.BalanceD ,
            t.BalanceLL ,
            t.BalanceEuro ,
            t.BalanceAR ,
            t.BalanceEN ,
            t.Credit ,
            t.CreditD ,
            t.CreditLL ,
            t.CreditEuro ,
            t.Debit ,
            t.DebitD ,
            t.DebitLL ,
            t.DebitEuro ,
            t.StatementIs ,
            t.TypeIs ,
            t.ChequeNumber ,
            t.ChequeImage ,
            t.ChequeImagePath ,
            t.ChequeNote ,
            t.ChequeDateGet ,
            t.ChequeStopNotificationGet ,
            t.NotificationTextAR ,
            t.NotificationTextEN
          FROM @DetailIs AS t
          ORDER BY t.RowNumber;

    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @DetailIs AS s
                        WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

    END;
	
    --BEGIN --Fix t_Transaction

    --  EXECUTE Transactions.s_TransactionFixPart @ID;

    --END;

	--Insert t_TransactionMoving
    SET @Return = -1;
    SET @EventIs += @RefF;
    EXECUTE Transactions.s_TransactionMovingInsertPART @UserID, @ID, @EventIs, @EventType, @ComputerIP, @Computer, @ComputerAccount; 

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;










