/****** Object:  StoredProcedure [Transactions].[s_TransactionInsertPart]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Transactions].[s_TransactionInsertPart] @ID UNIQUEIDENTIFIER ,
  @TypeIs NVARCHAR(MAX) ,
  @BalanceType TINYINT ,
  @DateIs DATETIME ,
  @UserID UNIQUEIDENTIFIER ,
  @DescriptionIs NVARCHAR(MAX) ,
  @LinkType INT ,
  @LinkTypeSub TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @SubLinkID UNIQUEIDENTIFIER ,
  @TransactionDetail Transactions.dt_TransactionDetail READONLY ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  BEGIN --Declare

    DECLARE @Ref BIGINT ,
      @LinkRefF NVARCHAR(MAX) = Alls.f_GetAnyRefF(@LinkID, @LinkType) ,
      @DetailsCount INT ,
      @return INT = 0;

  END;

  BEGIN --Set info

    SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
      FROM Transactions.t_Transaction AS s
      WHERE s.TypeIs = @TypeIs;

    SELECT @DetailsCount = COUNT(s.ID)
      FROM @TransactionDetail AS s;
          
  END;

  BEGIN --Insert t_Transaction

    INSERT INTO Transactions.t_Transaction
        ( ID ,
          Ref ,
          TypeIs ,
          BalanceType ,
          DateIs ,
          UserID ,
          DescriptionIs ,
          LinkType ,
          LinkTypeSub ,
          LinkID ,
          SubLinkID ,
          DetailsCount
        )
      VALUES
        ( @ID ,
          @Ref ,
          @TypeIs ,
          @BalanceType ,
          @DateIs ,
          @UserID ,
          REPLACE(@DescriptionIs, N'{0}', @LinkRefF) ,
          @LinkType ,
          @LinkTypeSub ,
          @LinkID ,
          @SubLinkID ,
          @DetailsCount
        );

  END;

  BEGIN --Insert t_TransactionDetail

    INSERT INTO Transactions.t_TransactionDetail
        ( ID ,
          RowNumber ,
          TransactionID ,
          AccountID ,
          DateIs ,
          CurrencyID ,
          ExchangeRate ,
          ExchangeRateLL ,
          ExchangeRateEuro ,
          BalanceType ,
          Balance ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro ,
          StatementIs ,
          TypeIs ,
          ChequeNumber ,
          ChequeImage ,
          ChequeImagePath ,
          ChequeNote ,
          ChequeDateGet ,
          ChequeStopNotificationGet ,
          NotificationTextAR ,
          NotificationTextEN ,
          IsSyncImage
        )
      SELECT t.ID ,
          t.RowNumber ,
          @ID ,
          t.AccountID ,
          t.DateIs ,
          t.CurrencyID ,
          t.ExchangeRate ,
          t.ExchangeRateLL ,
          t.ExchangeRateEuro ,
          @BalanceType ,
          t.Balance ,
          t.BalanceD ,
          t.BalanceLL ,
          t.BalanceEuro ,
          REPLACE(t.StatementIs, N'{0}', @LinkRefF) ,
          t.TypeIs ,
          t.ChequeNumber ,
          t.ChequeImage ,
          t.ChequeImagePath ,
          t.ChequeNote ,
          t.ChequeDateGet ,
          t.ChequeStopNotificationGet ,
          t.NotificationTextAR ,
          t.NotificationTextEN ,
          IIF(t.ChequeImagePath = '', 1, 0)
        FROM @TransactionDetail AS t
        ORDER BY t.RowNumber;

  END;

  BEGIN --Update t_Account

    UPDATE Company.t_Account
      SET StatusIs = 0 ,
          LastAction = GETDATE()
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @TransactionDetail AS s
                      WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

  END;
	
  BEGIN --Update t_Transaction

    EXECUTE Transactions.s_TransactionFixPart @ID;

  END;

  BEGIN --Insert t_TransactionMoving

    SET @return = -1;

    INSERT INTO Transactions.t_TransactionMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      VALUES
        ( @UserID ,
          @ID ,
          @Event + FORMAT(@Ref, '#') ,
          @EventType ,
          @ComputerIP ,
          @Computer ,
          @ComputerAccount
        );

  END;

  RETURN 1;

END;








