/****** Object:  StoredProcedure [Transactions].[s_TransactionInsertSimple]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Transactions].[s_TransactionInsertSimple]
  @PaperRef NVARCHAR(MAX) ,
  @TypeIs NVARCHAR(225) ,
  @DateIs DATETIME ,
  @DescriptionIs NVARCHAR(MAX) ,
  @LinkType INT ,
  @LinkTypeSub TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @DebitID UNIQUEIDENTIFIER ,
  @CreditID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Amount FLOAT ,
  @DetailTypeIs TINYINT ,
  @ChequeNumber NVARCHAR(MAX) ,
  @ChequeImage IMAGE ,
  @ChequeNote NVARCHAR(MAX) ,
  @ChequeDateGet DATE ,
  @ChequeStopNotificationGet BIT ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @Debit NVARCHAR(MAX) ,
        @Credit NVARCHAR(MAX) ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT  @Ref = ISNULL(MAX(s.Ref), 0) + 1
      FROM    Transactions.t_Transaction AS s
      WHERE   s.TypeIs = @TypeIs;

      SET @Debit = Company.f_AccountGetName(@DebitID);
      SET @Credit = Company.f_AccountGetName(@CreditID);

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;
      SET @V = @Amount;
      SET @VD = @Amount / @E;

    END;

    BEGIN --Insert transaction

      SET @return = 0;

      INSERT  INTO Transactions.t_Transaction
              ( ID ,
                Ref ,
                PaperRef ,
                TypeIs ,
                DateIs ,
                DescriptionIs ,
                LinkType ,
                LinkTypeSub ,
                LinkID ,
                UserID ,
                DetailsCount
              )
      VALUES  ( @ID ,
                @Ref ,
                @PaperRef ,
                @TypeIs ,
                @DateIs ,
                @DescriptionIs ,
                @LinkType ,
                @LinkTypeSub ,
                @LinkID ,
                @UserID ,
                2
              );

    END;

    BEGIN --Insert detail

      INSERT  INTO Transactions.t_TransactionDetail
              ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD,
                DebitLL, DebitEuro, StatementIs, TypeIs, ChequeNumber, ChequeImage, ChequeNote, ChequeDateGet, ChequeStopNotificationGet, NotificationTextAR,
                NotificationTextEN, CurrencyID, ExchangeRate, ExchangeRateLL, ExchangeRateEuro )
      VALUES  ( 1, @ID, @DebitID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, @DescriptionIs + ' \ ' + @Credit,
                @DetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN,
                @CID, @E, @ELL, @EEuro ),
              ( 2, @ID, @CreditID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0,
                @DescriptionIs + ' \ ' + @Debit, @DetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet,
                @NotificationTextAR, @NotificationTextEN, @CID, @E, @ELL, @EEuro );

    END;

    BEGIN --Fix data

      UPDATE  Company.t_Account
      SET     StatusIs = 0 ,
              LastAction = GETDATE()
      WHERE   ID IN ( @DebitID, @CreditID )
              AND StatusIs = 1;

      EXECUTE Transactions.s_TransactionFixPart @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT  INTO Transactions.t_TransactionMoving
              ( UserID ,
                SectionID ,
                EventIs ,
                EventType ,
                ComputerIP ,
                Computer ,
                ComputerAccount
              )
      VALUES  ( @UserID ,
                @ID ,
                @Event + FORMAT(@Ref, '#') ,
                @EventType ,
                @ComputerIP ,
                @Computer ,
                @ComputerAccount
              );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;



GO
/****** Object:  StoredProcedure [Transactions].[s_TransactionInsertSimple2]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Transactions].[s_TransactionInsertSimple2] @ID UNIQUEIDENTIFIER ,
  @PaperRef NVARCHAR(MAX) ,
  @TypeIs NVARCHAR(225) ,
  @BalanceType TINYINT ,
  @DateIs DATETIME ,
  @DateOnly DATE ,
  @DateFirstDayInMonth DATE ,
  @DateFirstDayInYear DATE ,
  @DescriptionIs NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @SourceID UNIQUEIDENTIFIER ,
  @SourceRef BIGINT ,
  @SourceRefF NVARCHAR(MAX) ,
  @LegalID UNIQUEIDENTIFIER ,
  @LegalRef BIGINT ,
  @LegalRefF NVARCHAR(MAX) ,
  @LinkType INT ,
  @LinkTypeSub TINYINT ,
  @LinkID UNIQUEIDENTIFIER ,
  @SubLinkID UNIQUEIDENTIFIER ,
  @AccountsNames NVARCHAR(MAX) ,
  @DetailsCount INT ,
  @Details Transactions.dt_TransactionDetailFull READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @UserIs NVARCHAR(MAX) ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT = Transactions.f_TransactionGetNewRef(@TypeIs) ,
        @RefF NVARCHAR(MAX) ,
        @AccountsIDs Alls.tt_Guid ,
        @return INT = 0;

    END;

    BEGIN --Set
    
      SET @RefF = FORMAT(@Ref, '#');

      INSERT INTO @AccountsIDs
          ( ID
          )
        SELECT DISTINCT s.AccountID
          FROM @Details AS s;

    END;

    BEGIN --Insert

      INSERT INTO Transactions.t_Transaction
          ( ID ,
            Ref ,
            RefF ,
            PaperRef ,
            TypeIs ,
            BalanceType ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            UserID ,
            UserIs ,
            DescriptionIs ,
            SourceType ,
            SourceID ,
            SourceRef ,
            SourceRefF ,
            LegalID ,
            LegalRef ,
            LegalRefF ,
            LinkType ,
            LinkTypeSub ,
            LinkID ,
            SubLinkID ,
            AccountsNames ,
            DetailsCount
          )
        VALUES
          ( @ID ,
            @Ref ,
            @RefF ,
            @PaperRef ,
            @TypeIs ,
            @BalanceType ,
            @DateIs ,
            @DateOnly ,
            @DateFirstDayInMonth ,
            @DateFirstDayInYear ,
            @UserID ,
            @UserIs ,
            @DescriptionIs ,
            @SourceType ,
            @SourceID ,
            @SourceRef ,
            @SourceRefF ,
            @LegalID ,
            @LegalRef ,
            @LegalRefF ,
            @LinkType ,
            @LinkTypeSub ,
            @LinkID ,
            @SubLinkID ,
            @AccountsNames ,
            @DetailsCount
          );

    END;

    BEGIN --Insert t_TransactionDetail

      INSERT INTO Transactions.t_TransactionDetail
          ( ID ,
            RowNumber ,
            TransactionID ,
            AccountID ,
            Account ,
            DateIs ,
            DateOnly ,
            DateFirstDayInMonth ,
            DateFirstDayInYear ,
            CurrencyID ,
            Currency ,
            CurrencyTypeIs ,
            ExchangeRate ,
            ExchangeRateLL ,
            ExchangeRateEuro ,
            BalanceType ,
            Balance ,
            BalanceF ,
            BalanceD ,
            BalanceLL ,
            BalanceEuro ,
            BalanceAR ,
            BalanceEN ,
            Credit ,
            CreditD ,
            CreditLL ,
            CreditEuro ,
            Debit ,
            DebitD ,
            DebitLL ,
            DebitEuro ,
            StatementIs ,
            TypeIs ,
            ChequeNumber ,
            ChequeImage ,
            ChequeImagePath ,
            ChequeNote ,
            ChequeDateGet ,
            ChequeStopNotificationGet ,
            NotificationTextAR ,
            NotificationTextEN
          )
        SELECT s.ID ,
            s.RowNumber ,
            s.TransactionID ,
            s.AccountID ,
            s.Account ,
            s.DateIs ,
            s.DateOnly ,
            s.DateFirstDayInMonth ,
            s.DateFirstDayInYear ,
            s.CurrencyID ,
            s.Currency ,
            s.CurrencyTypeIs ,
            s.ExchangeRate ,
            s.ExchangeRateLL ,
            s.ExchangeRateEuro ,
            s.BalanceType ,
            s.Balance ,
            s.BalanceF ,
            s.BalanceD ,
            s.BalanceLL ,
            s.BalanceEuro ,
            Currencys.f_ToWordAR(s.Balance, s.CurrencyID, 1) ,
            Currencys.f_ToWordEN(s.Balance, s.CurrencyID, 1) ,
            s.Credit ,
            s.CreditD ,
            s.CreditLL ,
            s.CreditEuro ,
            s.Debit ,
            s.DebitD ,
            s.DebitLL ,
            s.DebitEuro ,
            s.StatementIs ,
            s.TypeIs ,
            s.ChequeNumber ,
            s.ChequeImage ,
            s.ChequeImagePath ,
            s.ChequeNote ,
            s.ChequeDateGet ,
            s.ChequeStopNotificationGet ,
            s.NotificationTextAR ,
            s.NotificationTextEN
          FROM @Details AS s;
	 
    END;

    BEGIN --Update t_Account

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @AccountsIDs AS s
                        WHERE s.ID = t_Account.ID ) AND StatusIs = 1;

    END;

    SET @return = -1;
    SET @Event += @RefF;
    EXECUTE Transactions.s_TransactionMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    SELECT @return;

  END CATCH;

END;



