/****** Object:  StoredProcedure [Transactions].[s_TransactionInsertsPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Transactions].[s_TransactionInsertsPART] @Transaction Transactions.tt_Transaction READONLY ,
  @TransactionDetail Transactions.tt_TransactionDetail READONLY
AS
BEGIN

  IF NOT EXISTS ( SELECT TOP ( 1 ) s.ID
                    FROM @Transaction AS s )
  BEGIN
    
    RETURN 0;

  END;

  BEGIN --Declare

    DECLARE @Transaction_ Transactions.tt_Transaction ,
      @TypeIsJV NVARCHAR(MAX) = N'JV' ,
      @TypeIsRV NVARCHAR(MAX) = N'RV' ,
      @TypeIsPV NVARCHAR(MAX) = N'PV' ,
      @RefJV BIGINT ,
      @RefRV BIGINT ,
      @RefPV BIGINT;

  END;

  BEGIN --Set Info

    SELECT @RefJV = ISNULL(MAX(s.Ref), 0)
      FROM Transactions.t_Transaction AS s
      WHERE s.TypeIs = @TypeIsJV;
    
    SELECT @RefRV = ISNULL(MAX(s.Ref), 0) + 1
      FROM Transactions.t_Transaction AS s
      WHERE s.TypeIs = @TypeIsRV;
   	  
    SELECT @RefPV = ISNULL(MAX(s.Ref), 0) + 1
      FROM Transactions.t_Transaction AS s
      WHERE s.TypeIs = @TypeIsPV;
     
    INSERT INTO @Transaction_
        ( ID ,
          Ref ,
          RefF ,
          PaperRef ,
          TypeIs ,
          BalanceType ,
          DateIs ,
          DateOnly ,
          DateFirstDayInMonth ,
          DateFirstDayInYear ,
          UserID ,
          UserIs ,
          DescriptionIs ,
          LinkType ,
          LinkTypeSub ,
          LinkID ,
          SubLinkID ,
          AccountsNames ,
          DetailsCount ,
          IsSync ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
	    )
      SELECT s.ID ,
          @RefJV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ) ,
          FORMAT(@RefJV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ), '#') ,
          s.PaperRef ,
          s.TypeIs ,
          s.BalanceType ,
          s.DateIs ,
          s.DateOnly ,
          s.DateFirstDayInMonth ,
          s.DateFirstDayInYear ,
          s.UserID ,
          s.UserIs ,
          s.DescriptionIs ,
          s.LinkType ,
          s.LinkTypeSub ,
          s.LinkID ,
          s.SubLinkID ,
          s.AccountsNames ,
          s.DetailsCount ,
          s.IsSync ,
          s.EventIs ,
          s.EventType ,
          s.ComputerIP ,
          s.Computer ,
          s.ComputerAccount
        FROM @Transaction AS s
        WHERE s.TypeIs = @TypeIsJV
      UNION ALL
      SELECT s.ID ,
          @RefRV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ) ,
          FORMAT(@RefRV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ), '#') ,
          s.PaperRef ,
          s.TypeIs ,
          s.BalanceType ,
          s.DateIs ,
          s.DateOnly ,
          s.DateFirstDayInMonth ,
          s.DateFirstDayInYear ,
          s.UserID ,
          s.UserIs ,
          s.DescriptionIs ,
          s.LinkType ,
          s.LinkTypeSub ,
          s.LinkID ,
          s.SubLinkID ,
          s.AccountsNames ,
          s.DetailsCount ,
          s.IsSync ,
          s.EventIs ,
          s.EventType ,
          s.ComputerIP ,
          s.Computer ,
          s.ComputerAccount
        FROM @Transaction AS s
        WHERE s.TypeIs = @TypeIsRV
      UNION ALL
      SELECT s.ID ,
          @RefPV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ) ,
          FORMAT(@RefPV + ROW_NUMBER() OVER ( ORDER BY s.TypeIs ), '#') ,
          s.PaperRef ,
          s.TypeIs ,
          s.BalanceType ,
          s.DateIs ,
          s.DateOnly ,
          s.DateFirstDayInMonth ,
          s.DateFirstDayInYear ,
          s.UserID ,
          s.UserIs ,
          s.DescriptionIs ,
          s.LinkType ,
          s.LinkTypeSub ,
          s.LinkID ,
          s.SubLinkID ,
          s.AccountsNames ,
          s.DetailsCount ,
          s.IsSync ,
          s.EventIs ,
          s.EventType ,
          s.ComputerIP ,
          s.Computer ,
          s.ComputerAccount
        FROM @Transaction AS s
        WHERE s.TypeIs = @TypeIsPV;

  END;

  BEGIN --Insert t_Transaction

    INSERT INTO Transactions.t_Transaction
        ( ID ,
          Ref ,
          RefF ,
          PaperRef ,
          TypeIs ,
          BalanceType ,
          DateIs ,
          DateOnly ,
          DateFirstDayInMonth ,
          DateFirstDayInYear ,
          UserID ,
          UserIs ,
          DescriptionIs ,
          LinkType ,
          LinkTypeSub ,
          LinkID ,
          SubLinkID ,
          AccountsNames ,
          DetailsCount ,
          IsSync 
        )
      SELECT s.ID ,
          s.Ref ,
          s.RefF ,
          s.PaperRef ,
          s.TypeIs ,
          s.BalanceType ,
          s.DateIs ,
          s.DateOnly ,
          s.DateFirstDayInMonth ,
          s.DateFirstDayInYear ,
          s.UserID ,
          s.UserIs ,
          s.DescriptionIs ,
          s.LinkType ,
          s.LinkTypeSub ,
          s.LinkID ,
          s.SubLinkID ,
          s.AccountsNames ,
          s.DetailsCount ,
          s.IsSync
        FROM @Transaction_ AS s;

  END;

  BEGIN --Insert t_TransactionDetail

    INSERT INTO Transactions.t_TransactionDetail
        ( ID ,
          RowNumber ,
          TransactionID ,
          AccountID ,
          Account ,
          DateIs ,
          DateOnly ,
          DateFirstDayInMonth ,
          DateFirstDayInYear ,
          CurrencyID ,
          Currency ,
          CurrencyTypeIs ,
          ExchangeRate ,
          ExchangeRateLL ,
          ExchangeRateEuro ,
          BalanceType ,
          Balance ,
          BalanceF ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro ,
          BalanceAR ,
          BalanceEN ,
          Credit ,
          CreditD ,
          CreditLL ,
          CreditEuro ,
          Debit ,
          DebitD ,
          DebitLL ,
          DebitEuro ,
          StatementIs ,
          TypeIs ,
          ChequeNumber ,
          ChequeImage ,
          ChequeImagePath ,
          ChequeNote ,
          ChequeDateGet ,
          ChequeStopNotificationGet ,
          NotificationTextAR ,
          NotificationTextEN ,
          IsSync ,
          IsSyncImage 
        )
      SELECT s.ID ,
          s.RowNumber ,
          s.TransactionID ,
          s.AccountID ,
          s.Account ,
          s.DateIs ,
          s.DateOnly ,
          s.DateFirstDayInMonth ,
          s.DateFirstDayInYear ,
          s.CurrencyID ,
          s.Currency ,
          s.CurrencyTypeIs ,
          s.ExchangeRate ,
          s.ExchangeRateLL ,
          s.ExchangeRateEuro ,
          s.BalanceType ,
          s.Balance ,
          s.BalanceF ,
          s.BalanceD ,
          s.BalanceLL ,
          s.BalanceEuro ,
          Currencys.f_ToWordAR(s.Balance, s.CurrencyID, 1) ,
          Currencys.f_ToWordEN(s.Balance, s.CurrencyID, 1) ,
          s.Credit ,
          s.CreditD ,
          s.CreditLL ,
          s.CreditEuro ,
          s.Debit ,
          s.DebitD ,
          s.DebitLL ,
          s.DebitEuro ,
          s.StatementIs ,
          s.TypeIs ,
          s.ChequeNumber ,
          s.ChequeImage ,
          s.ChequeImagePath ,
          s.ChequeNote ,
          s.ChequeDateGet ,
          s.ChequeStopNotificationGet ,
          s.NotificationTextAR ,
          s.NotificationTextEN ,
          s.IsSync ,
          s.IsSyncImage
        FROM @TransactionDetail AS s;

  END;

  BEGIN --Update t_Account

    UPDATE Company.t_Account
      SET StatusIs = 0 ,
          LastAction = GETDATE()
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @TransactionDetail AS s
                      WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

  END;
	
  BEGIN --Insert t_TransactionMoving

    INSERT INTO Transactions.t_TransactionMoving
        ( UserID ,
          SectionID ,
          EventIs ,
          EventType ,
          ComputerIP ,
          Computer ,
          ComputerAccount
        )
      SELECT s.UserID ,
          s.ID ,
          s.EventIs + s.RefF ,
          s.EventType ,
          s.ComputerIP ,
          s.Computer ,
          s.ComputerAccount
        FROM @Transaction_ AS s;

  END;

END;






