/****** Object:  StoredProcedure [Transactions].[s_TransactionLiveVersion]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Transactions].[s_TransactionLiveVersion]
AS
BEGIN

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, TransactionIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaTransaction, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

END;





