/****** Object:  StoredProcedure [Transactions].[s_TransactionRebuildingStatistics]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Transactions].[s_TransactionRebuildingStatistics] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT;

    END;

    BEGIN; --Rebuilding statistics

      DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
      DISABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

      UPDATE Transactions.t_TransactionDetail
        SET Account = Company.f_AccountGetName(AccountID) ,
            BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
            BalanceAR = Currencys.f_ToWordAR(Balance, CurrencyID, 1) ,
            BalanceEN = Currencys.f_ToWordEN(Balance, CurrencyID, 1) ,
            Currency = Currencys.f_CurrencyGetName(CurrencyID) ,
            CurrencyTypeIs = Currencys.f_CurrencyGetTypeIs(CurrencyID);

      UPDATE Transactions.t_Transaction
        SET RefF = FORMAT(Ref, '#') ,
            UserIs = Users.f_UserGetName(UserID) ,
            AccountsNames = Alls.f_FixXML(( SELECT DISTINCT ', ' + t1.Name AS [text()]
                                              FROM Transactions.t_TransactionDetail AS t
                                              LEFT JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
                                              WHERE t.TransactionID = t_Transaction.ID
                                          FOR
                                            XML PATH('')
                                          )) ,
            DetailsCount = ( SELECT COUNT(*)
                              FROM Transactions.t_TransactionDetail AS s
                              WHERE s.TransactionID = t_Transaction.ID
                           );

      ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
      ENABLE TRIGGER Transactions.tr_TransactionDetail ON Transactions.t_TransactionDetail;

    END;

    EXECUTE Transactions.s_TransactionDetailByDaysReinsertPART;

    BEGIN --Insert event

      SET @Return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            '00000000-0000-0000-0000-000000000000' ,
            @Event ,
            6 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











