/****** Object:  StoredProcedure [Transactions].[s_TransactionUpDate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [Transactions].[s_TransactionUpDate] @PaperRef NVARCHAR(MAX) ,
  @TypeIs NVARCHAR(225) ,
  @DateIs DATETIME ,
  @BalanceType TINYINT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @SourceType TINYINT ,
  @SourceID UNIQUEIDENTIFIER ,
  @SourceRef BIGINT ,
  @SourceRefF NVARCHAR(MAX) ,
  @DetailIs Transactions.dt_TransactionDetail READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Ref BIGINT ,
        @DetailsCount INT ,
        @TypeIsOld NVARCHAR(225) ,
        @return INT = 0;

    END;
 
    BEGIN --Set info

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @TypeIsOld = s.TypeIs
        FROM Transactions.t_Transaction AS s
        WHERE s.ID = @ID;

      IF @TypeIs <> @TypeIsOld
      BEGIN
    
        SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = @TypeIs;

      END;

      SELECT @DetailsCount = COUNT(*)
        FROM @DetailIs AS s;

    END;

    BEGIN --Update transaction

      UPDATE Transactions.t_Transaction
        SET Ref = @Ref ,
            PaperRef = @PaperRef ,
            TypeIs = @TypeIs ,
            BalanceType = @BalanceType ,
            DateIs = @DateIs ,
            DescriptionIs = @DescriptionIs ,
            DetailsCount = @DetailsCount ,
            SourceType = @SourceType ,
            SourceID = @SourceID ,
            SourceRef = @SourceRef ,
            SourceRefF = @SourceRefF
        WHERE ID = @ID;

    END;

    BEGIN --Merge t_TransactionDetail
	
      MERGE Transactions.t_TransactionDetail AS t
      USING @DetailIs AS s
      ON t.ID = s.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( ID ,
                 RowNumber ,
                 TransactionID ,
                 AccountID ,
                 DateIs ,
                 CurrencyID ,
                 ExchangeRate ,
                 ExchangeRateLL ,
                 ExchangeRateEuro ,
                 BalanceType ,
                 Balance ,
                 BalanceD ,
                 BalanceLL ,
                 BalanceEuro ,
                 StatementIs ,
                 TypeIs ,
                 ChequeNumber ,
                 ChequeImage ,
                 ChequeImagePath ,
                 ChequeNote ,
                 ChequeDateGet ,
                 ChequeStopNotificationGet ,
                 NotificationTextAR ,
                 NotificationTextEN ,
                 IsSyncImage
               )
        VALUES ( s.ID ,
                 s.RowNumber ,
                 @ID ,
                 s.AccountID ,
                 s.DateIs ,
                 s.CurrencyID ,
                 s.ExchangeRate ,
                 s.ExchangeRateLL ,
                 s.ExchangeRateEuro ,
                 @BalanceType ,
                 s.Balance ,
                 s.BalanceD ,
                 s.BalanceLL ,
                 s.BalanceEuro ,
                 s.StatementIs ,
                 s.TypeIs ,
                 s.ChequeNumber ,
                 s.ChequeImage ,
                 s.ChequeImagePath ,
                 s.ChequeNote ,
                 s.ChequeDateGet ,
                 s.ChequeStopNotificationGet ,
                 s.NotificationTextAR ,
                 s.NotificationTextEN ,
                 IIF(s.ChequeImagePath = '', 0, 1)
               )
      WHEN MATCHED THEN
        UPDATE SET t.RowNumber = s.RowNumber ,
                    t.AccountID = s.AccountID ,
                    t.DateIs = s.DateIs ,
                    t.CurrencyID = s.CurrencyID ,
                    t.ExchangeRate = s.ExchangeRate ,
                    t.ExchangeRateLL = s.ExchangeRateLL ,
                    t.ExchangeRateEuro = s.ExchangeRateEuro ,
                    t.BalanceType = @BalanceType ,
                    t.Balance = s.Balance ,
                    t.BalanceD = s.BalanceD ,
                    t.BalanceLL = s.BalanceLL ,
                    t.BalanceEuro = s.BalanceEuro ,
                    t.StatementIs = s.StatementIs ,
                    t.TypeIs = s.TypeIs ,
                    t.ChequeNumber = s.ChequeNumber ,
                    t.ChequeImage = s.ChequeImage ,
                    t.ChequeImagePath = s.ChequeImagePath ,
                    t.ChequeNote = s.ChequeNote ,
                    t.ChequeDateGet = s.ChequeDateGet ,
                    t.ChequeStopNotificationGet = s.ChequeStopNotificationGet ,
                    t.NotificationTextAR = s.NotificationTextAR ,
                    t.NotificationTextEN = s.NotificationTextEN ,
                    t.IsSync = 0 ,
                    t.IsSyncImage = IIF(s.ChequeImagePath = '', 0, 1)
      WHEN NOT MATCHED BY SOURCE AND t.TransactionID = @ID THEN
        DELETE;

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @DetailIs AS s
                        WHERE s.AccountID = t_Account.ID ) AND StatusIs = 1;

    END;

    BEGIN --Fix data

      EXECUTE Transactions.s_TransactionFixPart @ID;

    END;

    SET @return = -1;
    EXECUTE Transactions.s_TransactionMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @return;

  END CATCH;

END;










GO
