/****** Object:  StoredProcedure [Transactions].[s_TransactionUpdateResetRefs]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Transactions].[s_TransactionUpdateResetRefs] @StartRef BIGINT ,
  @TypeIs NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY

    SET ANSI_WARNINGS OFF;

    BEGIN TRANSACTION;

    DISABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;

    BEGIN --Update
 
      WITH  o AS ( SELECT t.Ref ,
                      t.RefF ,
                      t.DateIs ,
                      t.DateCreate ,
                      ROW_NUMBER() OVER ( PARTITION BY t.TypeIs ORDER BY t.DateIs ) + @StartRef AS Ref_
                    FROM Transactions.t_Transaction AS t
                    WHERE t.TypeIs = @TypeIs
                 )
        UPDATE o
          SET o.Ref = o.Ref_ ,
              o.RefF = FORMAT(o.Ref_, '#') ,
              o.DateCreate = o.DateIs;

    END;
	     
    ENABLE TRIGGER Transactions.tr_Transaction ON Transactions.t_Transaction;
	
    EXECUTE Transactions.s_TransactionLiveVersion;

    COMMIT TRANSACTION;

    RETURN  1;

  END TRY
