/****** Object:  StoredProcedure [Transactions].[s_TransactionUpDateSimple]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Transactions].[s_TransactionUpDateSimple] @PaperRef NVARCHAR(MAX), @TypeIs NVARCHAR(225) ,
  @DateIs DATETIME ,
  @DescriptionIs NVARCHAR(MAX) ,
  @DebitID UNIQUEIDENTIFIER ,
  @CreditID UNIQUEIDENTIFIER ,
  @CurrencyID UNIQUEIDENTIFIER ,
  @ExchangeRate FLOAT ,
  @ExchangeRateLL FLOAT ,
  @ExchangeRateEuro FLOAT ,
  @Amount FLOAT ,
  @DetailTypeIs TINYINT ,
  @ChequeNumber NVARCHAR(MAX) ,
  @ChequeImage IMAGE ,
  @ChequeNote NVARCHAR(MAX) ,
  @ChequeDateGet DATE ,
  @ChequeStopNotificationGet BIT ,
  @NotificationTextAR NVARCHAR(MAX) ,
  @NotificationTextEN NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY

    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @IDs TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

      DECLARE @Ref BIGINT ,
        @TypeIsOld NVARCHAR(225) ,
        @Debit NVARCHAR(MAX) ,
        @Credit NVARCHAR(MAX) ,
        @CID UNIQUEIDENTIFIER ,
        @E FLOAT ,
        @ELL FLOAT ,
        @EEuro FLOAT ,
        @V FLOAT ,
        @VD FLOAT ,
        @return INT;

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @Ref = s.Ref ,
          @TypeIsOld = s.TypeIs
        FROM Transactions.t_Transaction AS s
        WHERE s.ID = @ID;

      IF @TypeIs <> @TypeIsOld
      BEGIN
    
        SELECT @Ref = ISNULL(MAX(s.Ref), 0) + 1
          FROM Transactions.t_Transaction AS s
          WHERE s.TypeIs = @TypeIs;

      END;

      SET @Debit = Company.f_AccountGetName(@DebitID);
      SET @Credit = Company.f_AccountGetName(@CreditID);

      SET @CID = @CurrencyID;
      SET @E = @ExchangeRate;
      SET @ELL = @ExchangeRateLL;
      SET @EEuro = @ExchangeRateEuro;
      SET @V = @Amount;
      SET @VD = @Amount / @E;

    END;

    BEGIN --Update transaction

      SET @return = 0;

      UPDATE Transactions.t_Transaction
        SET Ref = @Ref ,
		    PaperRef = @PaperRef ,
            TypeIs = @TypeIs ,
            DateIs = @DateIs ,
            DescriptionIs = @DescriptionIs ,
            UserID = @UserID
        WHERE ID = @ID;

    END;

    BEGIN --Reinsert Detail

      DELETE FROM Transactions.t_TransactionDetail
        WHERE TransactionID = @ID;

      INSERT INTO Transactions.t_TransactionDetail
          ( RowNumber, TransactionID, AccountID, DateIs, Balance, BalanceD, BalanceLL, BalanceEuro, Credit, CreditD, CreditLL, CreditEuro, Debit, DebitD, DebitLL, DebitEuro, StatementIs, TypeIs, ChequeNumber, ChequeImage, ChequeNote, ChequeDateGet, ChequeStopNotificationGet, NotificationTextAR, NotificationTextEN, CurrencyID, ExchangeRate , ExchangeRateLL , ExchangeRateEuro )
        VALUES  ( 1, @ID, @DebitID, @DateIs, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @V, @VD, @VD * @ELL, @VD * @EEuro, @DescriptionIs + ' \ ' + @Credit, @DetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN, @CID, @E, @ELL , @EEuro ),
                ( 2, @ID, @CreditID, @DateIs, 0 - @V, 0 - @VD, ( 0 - @VD ) * @ELL, ( 0 - @VD ) * @EEuro, @V, @VD, @VD * @ELL, @VD * @EEuro, 0, 0, 0, 0, @DescriptionIs + ' \ ' + @Debit, @DetailTypeIs, @ChequeNumber, @ChequeImage, @ChequeNote, @ChequeDateGet, @ChequeStopNotificationGet, @NotificationTextAR, @NotificationTextEN, @CID, @E , @ELL , @EEuro );

    END;

    BEGIN --Fix data

      UPDATE Company.t_Account
        SET StatusIs = 0 ,
            LastAction = GETDATE()
        WHERE ID IN ( @DebitID, @CreditID ) AND StatusIs = 1;
     
      EXECUTE Transactions.s_TransactionFixPart @ID;

    END;

    BEGIN --Insert event

      SET @return = -1;

      INSERT INTO Transactions.t_TransactionMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @return;

  END CATCH;

END;




