/****** Object:  StoredProcedure [Users].[s_PermissionAccountStatementMerge]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionAccountStatementMerge] @PermissionID UNIQUEIDENTIFIER ,
  @t Users.tt_PermissionAccountStatement READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ErrorMessage NVARCHAR(MAX) OUTPUT
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Users.t_PermissionAccountStatement AS t
      USING @t AS s
      ON s.ID = t.ID
      WHEN NOT MATCHED BY TARGET THEN
        INSERT ( PermissionID ,
                 RangeType ,
                 FromNumber ,
                 ToNumber ,
                 CreatedByUserID
               )
        VALUES ( s.PermissionID ,
                 s.RangeType ,
                 s.FromNumber ,
                 s.ToNumber ,
                 s.CreatedByUserID
               )
      WHEN MATCHED THEN
        UPDATE SET t.RangeType = s.RangeType ,
                    t.FromNumber = s.FromNumber ,
                    t.ToNumber = s.ToNumber
      WHEN NOT MATCHED BY SOURCE AND t.PermissionID = @PermissionID THEN
        DELETE;

    END;

    SET @Return = -1;
    EXECUTE Users.s_PermissionMovingInsertPART @PermissionID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Users.s_PermissionLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SET @ErrorMessage = ERROR_MESSAGE();

    SELECT @Return;

  END CATCH;

END;

