/****** Object:  StoredProcedure [Users].[s_PermissionMovingInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionMovingInsert] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    EXECUTE Users.s_PermissionMovingInsertPART @ID, @UserID, @Event, 3, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Users.s_PermissionLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN -1;

  END CATCH;

END;

