/****** Object:  StoredProcedure [Users].[s_PermissionMovingInsertPART]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Users].[s_PermissionMovingInsertPART] @ID UNIQUEIDENTIFIER ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN

  INSERT INTO Users.t_PermissionMoving
      ( UserID ,
        SectionID ,
        EventIs ,
        EventType ,
        ComputerIP ,
        Computer ,
        ComputerAccount
      )
    VALUES
      ( @UserID ,
        @ID ,
        @Event ,
        @EventType ,
        @ComputerIP ,
        @Computer ,
        @ComputerAccount
      );

END;








