/****** Object:  StoredProcedure [Users].[s_PermissionMovingTruncate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionMovingTruncate] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Delete

      TRUNCATE TABLE Users.t_PermissionMoving;

    END;

    SET @Return = -1;
    EXECUTE Users.s_PermissionMovingInsertPART '00000000-0000-0000-0000-000000000000', @UserID, @Event, 4, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Users.s_PermissionLiveVersion;
	
    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;













