/****** Object:  StoredProcedure [Users].[s_PermissionUpdate]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionUpdate] @Name NVARCHAR(MAX) ,
  @SaleInvoiceMaximumDiscount FLOAT ,
  @ViewPurchaseInvoicesFromAPeriodOfDays INT ,
  @ViewSalesInvoicesFromAPeriodOfDays INT ,
  @DescriptionIs NVARCHAR(MAX) ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT  = 0 ,
        @NameOld NVARCHAR(450);

    END;

    BEGIN --Set info

      SELECT TOP ( 1 ) @NameOld = s.Name
        FROM Users.t_Permission AS s
        WHERE s.ID = @ID
        ORDER BY s.ID;

    END;

    BEGIN --Update

      UPDATE Users.t_Permission
        SET Name = @Name ,
            SaleInvoiceMaximumDiscount = @SaleInvoiceMaximumDiscount ,
            ViewPurchaseInvoicesFromAPeriodOfDays = @ViewPurchaseInvoicesFromAPeriodOfDays ,
            ViewSalesInvoicesFromAPeriodOfDays = @ViewSalesInvoicesFromAPeriodOfDays ,
            DescriptionIs = @DescriptionIs
        WHERE ID = @ID;

    END;

    IF @NameOld COLLATE Arabic_CS_AS <> @Name COLLATE Arabic_CS_AS
    BEGIN --Fix Name

      UPDATE Users.t_User
        SET PermissionIs = @Name
        WHERE PermissionID = @ID;

    END;

    SET @Return = -1;
    EXECUTE Users.s_PermissionMovingInsertPART @ID, @UserID, @Event, @EventType, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Users.s_PermissionLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
