/****** Object:  StoredProcedure [Users].[s_PermissionUpdateColumn]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionUpdateColumn] @ColumnName NVARCHAR(MAX) ,
  @HavePermission BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0,
        @SceripIs NVARCHAR(MAX);

    END;

    BEGIN --Update

      SET @SceripIs = 'update users.t_Permission set ' 
	  + @ColumnName + ' = ' 
	  + CONVERT(NVARCHAR(MAX), @HavePermission) 
	  + ' where ID = ''' 
	  + CONVERT(NVARCHAR(MAX), @ID) + '''';

      EXECUTE (@SceripIs);

    END;

    SET @Return = -1;
    EXECUTE Users.s_PermissionMovingInsertPART @ID, @UserID, @Event, 1, @ComputerIP, @Computer, @ComputerAccount;

    EXECUTE Users.s_PermissionLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;











GO
/****** Object:  StoredProcedure [Users].[s_PermissionUpdateIsSync]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_PermissionUpdateIsSync]
    @IsSync BIT,
    @UserID UNIQUEIDENTIFIER,
    @Event NVARCHAR(MAX),
    @ComputerIP NVARCHAR(MAX),
    @Computer NVARCHAR(MAX),
    @ComputerAccount NVARCHAR(MAX),
    @ID UNIQUEIDENTIFIER
AS
BEGIN
    BEGIN TRY
        BEGIN TRANSACTION;

        BEGIN --Declare

            DECLARE @Return INT;

        END;

        DISABLE TRIGGER Users.tr_Permission ON Users.t_Permission;

        BEGIN --Insert

            UPDATE Users.t_Permission
            SET IsSync = @IsSync
            WHERE ID = @ID;

        END;

        ENABLE TRIGGER Users.tr_Permission ON Users.t_Permission;

        BEGIN --Insert event

            SET @Return = -1;

            INSERT INTO Users.t_PermissionMoving
            (
                UserID,
                SectionID,
                EventIs,
                EventType,
                ComputerIP,
                Computer,
                ComputerAccount
            )
            VALUES
            (@UserID, @ID, @Event, 7, @ComputerIP, @Computer, @ComputerAccount);

        END;

        COMMIT TRANSACTION;

        RETURN 1;

    END TRY
    BEGIN CATCH

        ROLLBACK;

        RETURN @Return;

    END CATCH;

END;


