            MainPanelHeaderFont = @MainPanelHeaderFont ,
            MainPanelItemFont = @MainPanelItemFont ,
            MainPanelWidth = @MainPanelWidth ,
            MainPanelDetailsHeight = @MainPanelDetailsHeight ,
            LastModifiedDate = GETDATE()
        WHERE ID = @ID;	  

