/****** Object:  StoredProcedure [Users].[s_UserDelete]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_UserDelete] @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;
      DECLARE @AccountUserBlocked TABLE
        (
          ID UNIQUEIDENTIFIER NOT NULL
        );

    END;

    BEGIN --Delete t_TrackDeletedItemsFromInvoices

      DELETE FROM Invoices.t_TrackDeletedItemsFromInvoices
        WHERE UserID = @ID;

    END;
	
    BEGIN --Delete t_WarehouseUser

      DELETE FROM Company.t_WarehouseUser
        WHERE UserID = @ID;
		  
    END;
	
    BEGIN --Update t_WareHouse

      UPDATE Company.t_WareHouse
        SET UserC = ( SELECT COUNT(*)
                        FROM Company.t_WarehouseUser AS s
                        WHERE s.WarehouseID = t_WareHouse.ID
                    ) ,
            UsersNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                          FROM Company.t_WarehouseUser AS t
                                          LEFT JOIN Users.t_User AS t1 ON t1.ID = t.UserID
                                          WHERE t.WarehouseID = t_WareHouse.ID
                                       FOR
                                         XML PATH('')
                                       ));

    END;
      
    BEGIN --

      INSERT INTO @AccountUserBlocked
          ( ID
          )
        SELECT DISTINCT AccountID
          FROM Company.t_AccountUserBlocked
          WHERE UserID = @ID;
		  
    END;
	  
    BEGIN --Delete t_AccountUserBlocked

      DELETE FROM Company.t_AccountUserBlocked
        WHERE UserID = @ID;
		  
    END;
	
    BEGIN --Update Account

      UPDATE Company.t_Account
        SET UserBlockedC = ( SELECT COUNT(*)
                              FROM Company.t_AccountUserBlocked AS s
                              WHERE s.AccountID = t_Account.ID
                           ) ,
            UsersNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                          FROM Company.t_AccountUserBlocked AS t
                                          LEFT JOIN Users.t_User AS t1 ON t1.ID = t.UserID
                                          WHERE t.AccountID = t_Account.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                        FROM @AccountUserBlocked AS s
                        WHERE s.ID = t_Account.ID );

    END;
	 
    BEGIN --Delete

      DELETE FROM Users.t_User
        WHERE ID = @ID;

    END;

    BEGIN --Insert t_FireStoreRowsForDelete

      INSERT INTO Alls.t_FireStoreRowsForDelete
          ( DocumentID, HasImage, TableName )
        VALUES ( @ID, 1, 'user' );

    END;
	
    BEGIN --Insert t_UserMoving

      SET @Return = -1;

      INSERT INTO Users.t_UserMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Users.s_UserLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;



