/****** Object:  StoredProcedure [Users].[s_UserInsert]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [Users].[s_UserInsert] @Name NVARCHAR(450) ,
  @PasswordIs NVARCHAR(MAX) ,
  @ChangePasswordOnLogin BIT ,
  @PermissionID UNIQUEIDENTIFIER ,
  @UserInterfaceType TINYINT ,
  @AccountBoxID UNIQUEIDENTIFIER ,
  @AccountBoxLLID UNIQUEIDENTIFIER ,
  @AccountBoxEuroID UNIQUEIDENTIFIER ,
  @WorkFullTime BIT ,
  @BeginWork TIME(7) ,
  @EndWork TIME(7) ,
  @TemporaryUse BIT ,
  @TemporaryDate DATE ,
  @ImageIs IMAGE ,
  @ImagePath NVARCHAR(MAX) ,
  @Spying BIT ,
  @SpyingEverySec INT ,
  @MandatoryPricingType TINYINT ,
  @CalculatingTheOpeningBalance BIT ,
  @SetAutomaticBoxClosingBalance BIT ,
  @PrintSoldQuantityReportAfterClosingTheBox BIT ,
  @UserID UNIQUEIDENTIFIER ,
  @Event NVARCHAR(MAX) ,
  @EventType TINYINT ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX) ,
  @ID UNIQUEIDENTIFIER
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Insert

      INSERT INTO Users.t_User
          ( ID ,
            Name ,
            IsAdmin ,
            PasswordIs ,
            ChangePasswordOnLogin ,
            PermissionID ,
            PermissionIs ,
            UserInterfaceType ,
            AccountBoxID ,
            AccountBoxName ,
            AccountBoxNumberF ,
            AccountBoxLLID ,
            AccountBoxLLName ,
            AccountBoxLLNumberF ,
            AccountBoxEuroID ,
            AccountBoxEuroName ,
            AccountBoxEuroNumberF ,
            WorkFullTime ,
            BeginWork ,
            BeginWorkF ,
            EndWork ,
            EndWorkF ,
            TemporaryUse ,
            TemporaryDate ,
            ImageIs ,
            ImagePath ,
            IsSyncImage ,
            Spying ,
            SpyingEverySec ,
            MandatoryPricingType ,
            CalculatingTheOpeningBalance ,
            SetAutomaticBoxClosingBalance ,
            PrintSoldQuantityReportAfterClosingTheBox
          )
        VALUES
          ( @ID ,
            @Name ,
            0 ,
            @PasswordIs ,
            @ChangePasswordOnLogin ,
            @PermissionID ,
            Users.f_PermissionGetName(@PermissionID) ,
            @UserInterfaceType ,
            @AccountBoxID ,
            Company.f_AccountGetName(@AccountBoxID) ,
            Company.f_AccountGetNumberF(@AccountBoxID) ,
            @AccountBoxLLID ,
            Company.f_AccountGetName(@AccountBoxLLID) ,
            Company.f_AccountGetNumberF(@AccountBoxLLID) ,
            @AccountBoxEuroID ,
            Company.f_AccountGetName(@AccountBoxEuroID) ,
            Company.f_AccountGetNumberF(@AccountBoxEuroID) ,
            @WorkFullTime ,
            @BeginWork ,
            FORMAT(CAST(@BeginWork AS DATETIME), 'hh:mm tt', 'ar-lb') ,
            @EndWork ,
            FORMAT(CAST(@EndWork AS DATETIME), 'hh:mm tt', 'ar-lb') ,
            @TemporaryUse ,
            @TemporaryDate ,
            @ImageIs ,
            @ImagePath ,
            IIF(@ImagePath = N'', 0, 1) ,
            @Spying ,
            @SpyingEverySec ,
            @MandatoryPricingType ,
			@CalculatingTheOpeningBalance ,
            @SetAutomaticBoxClosingBalance ,
            @PrintSoldQuantityReportAfterClosingTheBox
          );

    END;
     
    BEGIN --Insert t_WarehouseUser

      INSERT INTO Company.t_WarehouseUser
          ( WarehouseID ,
            Warehouse ,
            UserID ,
            UserIs 
          )
        SELECT t.ID ,
            t.Name ,
            @ID ,
            @Name
          FROM Company.t_WareHouse AS t;

    END;

    BEGIN --Rebuilding Statistics t_WareHouse

      UPDATE Company.t_WareHouse
        SET UserC = ( SELECT COUNT(*)
                        FROM Company.t_WarehouseUser AS s
                        WHERE s.WarehouseID = t_WareHouse.ID
                    ) ,
            UsersNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                          FROM Company.t_WarehouseUser AS t
                                          LEFT JOIN Users.t_User AS t1 ON t1.ID = t.UserID
                                          WHERE t.WarehouseID = t_WareHouse.ID
                                       FOR
                                         XML PATH('')
                                       ));

    END;
        
    BEGIN --Insert t_AccountUserBlocked

      INSERT INTO Company.t_AccountUserBlocked
          ( AccountID ,
            Account ,
            UserID ,
            UserIs ,
            CanUse 
          )
        SELECT t.ID ,
            t.Name ,
            @ID ,
            @Name ,
            0
          FROM Company.t_Account AS t
          WHERE t.NumberIs BETWEEN 5310100000 AND 5310199999 AND t.ID <> @AccountBoxID AND t.ID <> @AccountBoxLLID AND t.ID <> @AccountBoxEuroID;

    END;

    BEGIN --Rebuilding Statistics Account

      UPDATE Company.t_Account
        SET UserBlockedC = ( SELECT COUNT(*)
                              FROM Company.t_AccountUserBlocked AS s
                              WHERE s.AccountID = t_Account.ID
                           ) ,
            UsersNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                          FROM Company.t_AccountUserBlocked AS t
                                          LEFT JOIN Users.t_User AS t1 ON t1.ID = t.UserID
                                          WHERE t.AccountID = t_Account.ID
                                       FOR
                                         XML PATH('')
                                       ))
        WHERE NumberIs BETWEEN 5310100000 AND 5310199999 AND ID <> @AccountBoxID AND ID <> @AccountBoxLLID AND ID <> @AccountBoxEuroID;

    END;

    BEGIN --Rebuilding Statistics t_User

      UPDATE Users.t_User
        SET AccountBlockedC = ( SELECT COUNT(*)
                                  FROM Company.t_AccountUserBlocked AS s
                                  WHERE s.UserID = t_User.ID
                              ) ,
            AccountNames = Alls.f_FixXML(( SELECT ', ' + t1.Name AS [text()]
                                            FROM Company.t_AccountUserBlocked AS t
                                            LEFT JOIN Company.t_Account AS t1 ON t1.ID = t.AccountID
                                            WHERE t.UserID = t_User.ID
                                         FOR
                                           XML PATH('')
                                         ))
        WHERE ID = @UserID;

    END;

    BEGIN --Insert t_UserMoving

      SET @Return = -1;

      INSERT INTO Users.t_UserMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        VALUES
          ( @UserID ,
            @ID ,
            @Event ,
            @EventType ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          );

    END;

    EXECUTE Users.s_UserLiveVersion;

    COMMIT TRANSACTION;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN @Return;

  END CATCH;

END;

GO
/****** Object:  StoredProcedure [Users].[s_UserInsertDefaultData]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [Users].[s_UserInsertDefaultData]
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Check

      IF EXISTS ( SELECT TOP ( 1 ) ID
                    FROM Users.t_User )
      BEGIN
			
        COMMIT TRAN;

        RETURN 1;

      END;

    END;

    BEGIN --Insert

      EXECUTE Users.s_PermissionInsertDefaultData;
     
      INSERT INTO Users.t_User
          ( ID, Name, IsAdmin, PermissionID, PermissionIs )
        VALUES  ( NEWID(), 'Admin', 1, Users.f_PermissionGetID(N'Admin'), N'Admin' ),
                ( NEWID(), 'User', 0, Users.f_PermissionGetID(N'User'), N'User' );

      UPDATE Users.t_User
        SET AccountBoxID = Company.f_AccountGetIDByNumber(N'5310100003') ,
            AccountBoxName = N'Admin Box $' ,
            AccountBoxNumberF = N'5310100003' ,
            AccountBoxLLID = Company.f_AccountGetIDByNumber(N'5310100004') ,
            AccountBoxLLName = N'Admin Box LL' ,
            AccountBoxLLNumberF = N'5310100004' ,
            AccountBoxEuroID = Company.f_AccountGetIDByNumber(N'5310100003') ,
            AccountBoxEuroName = N'Admin Box $' ,
            AccountBoxEuroNumberF = N'5310100003'
        WHERE IsAdmin = 1;

      UPDATE Users.t_User
        SET UserInterfaceType = 2 ,
            AccountBoxID = Company.f_AccountGetIDByNumber(N'5310100005') ,
            AccountBoxName = N'User Box $' ,
            AccountBoxNumberF = N'5310100005' ,
            AccountBoxLLID = Company.f_AccountGetIDByNumber(N'5310100006') ,
            AccountBoxLLName = N'User Box LL' ,
            AccountBoxLLNumberF = N'5310100006' ,
            AccountBoxEuroID = Company.f_AccountGetIDByNumber(N'5310100005') ,
            AccountBoxEuroName = N'User Box $' ,
            AccountBoxEuroNumberF = N'5310100005'
        WHERE IsAdmin = 0;

    END;

    COMMIT TRAN;

    RETURN 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    RETURN 0;

  END CATCH;

END;










