/****** Object:  StoredProcedure [Users].[s_UserUpdatesIsEnable]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [Users].[s_UserUpdatesIsEnable] @Users Users.tt_UserUpdatesIsEnable READONLY ,
  @UserID UNIQUEIDENTIFIER ,
  @ComputerIP NVARCHAR(MAX) ,
  @Computer NVARCHAR(MAX) ,
  @ComputerAccount NVARCHAR(MAX)
AS
BEGIN
  BEGIN TRY
    BEGIN TRANSACTION;

    BEGIN --Declare

      DECLARE @Return INT = 0;

    END;

    BEGIN --Merge

      MERGE Users.t_User AS t
      USING @Users AS s
      ON s.ID = t.ID
      WHEN MATCHED THEN
        UPDATE SET t.IsEnable = s.IsEnable ,
                    t.IsSync = 0;

    END;

    BEGIN --Insert t_UserMoving

      INSERT INTO Users.t_UserMoving
          ( UserID ,
            SectionID ,
            EventIs ,
            EventType ,
            ComputerIP ,
            Computer ,
            ComputerAccount
          )
        SELECT @UserID ,
            s.ID ,
            s.EventIs ,
            1 ,
            @ComputerIP ,
            @Computer ,
            @ComputerAccount
          FROM @Users AS s;

    END;
    
    EXECUTE Users.s_UserLiveVersion;

    COMMIT TRANSACTION;

    SELECT 1;

  END TRY
  BEGIN CATCH

    ROLLBACK;

    SELECT @Return;

  END CATCH;

END;









