/****** Object:  Trigger [Company].[tr_Account]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Company].[tr_Account] ON [Company].[t_Account]
  AFTER INSERT, UPDATE, DELETE
AS
BEGIN

  IF NOT UPDATE(IsSync)
  BEGIN 

    UPDATE Company.t_Account
      SET IsSync = 0
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM Inserted AS s
                      WHERE s.ID = t_Account.ID );

  END;

  BEGIN --Declare

    DECLARE @IDs AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL
      );

    DECLARE @AccountLevel3 TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        BalanceD FLOAT NOT NULL ,
        BalanceLL FLOAT NOT NULL ,
        BalanceEuro FLOAT NOT NULL
      );

  END;

  BEGIN --Set info

    INSERT @IDs
        ( ID )
      SELECT s.ID
        FROM Inserted AS s;

    INSERT INTO @AccountLevel3
        ( ID ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro
        )
      SELECT o.Level3ID ,
          ISNULL(SUM(o.BalanceD), 0) ,
          ISNULL(SUM(o.BalanceLL), 0) ,
          ISNULL(SUM(o.BalanceEuro), 0)
        FROM ( SELECT t.Level3ID ,
                  t.BalanceD ,
                  t.BalanceLL ,
                  t.BalanceEuro
                FROM Inserted AS t
               UNION ALL
               SELECT t.Level3ID ,
                  0 - t.BalanceD ,
                  0 - t.BalanceLL ,
                  0 - t.BalanceEuro
                FROM Deleted AS t
             ) AS o
        GROUP BY o.Level3ID;

  END;

  BEGIN --Format

    WITH  o AS ( SELECT s1.CurrencyID ,
                    s1.Balance ,
                    s1.BalanceF ,
                    s1.BalanceD ,
                    s1.BalanceLL ,
                    s1.BalanceEuro ,
                    s1.SubaccountsBalance ,
                    s1.SubaccountsBalanceF ,
                    s1.SubaccountsBalanceD ,
                    s1.SubaccountsBalanceLL ,
                    s1.SubaccountsBalanceEuro ,
                    s1.TotalBalance ,
                    s1.TotalBalanceF ,
                    s1.TotalBalanceD ,
                    s1.TotalBalanceLL ,
                    s1.TotalBalanceEuro ,
                    Company.f_SubAccountsGetBalanceX(s.MainAccountID) AS SubaccountsBalance_ ,
                    Company.f_SubAccountsGetBalanceDX(s.MainAccountID) AS SubaccountsBalanceD_ ,
                    Company.f_SubAccountsGetBalanceLLX(s.MainAccountID) AS SubaccountsBalanceLL_ ,
                    Company.f_SubAccountsGetBalanceEuroX(s.MainAccountID) AS SubaccountsBalanceEuro_
                  FROM Company.t_SubAccounts AS s
                  INNER JOIN Company.t_Account AS s1 ON s1.ID = s.MainAccountID
                  WHERE EXISTS ( SELECT TOP ( 1 ) ss.ID
                                  FROM @IDs AS ss
                                  WHERE ss.ID = s.SubAccountID )
               )
      UPDATE o
        SET o.SubaccountsBalance = o.SubaccountsBalance_ ,
            o.SubaccountsBalanceF = Currencys.f_Format(o.CurrencyID, o.SubaccountsBalance_) ,
            o.SubaccountsBalanceD = o.SubaccountsBalanceD_ ,
            o.SubaccountsBalanceLL = o.SubaccountsBalanceLL_ ,
            o.SubaccountsBalanceEuro = o.SubaccountsBalanceEuro_ ,
            o.TotalBalance = o.Balance + o.SubaccountsBalance_ ,
            o.TotalBalanceF = Currencys.f_Format(o.CurrencyID, o.Balance + o.SubaccountsBalance_) ,
            o.TotalBalanceD = o.BalanceD + o.SubaccountsBalanceD_ ,
            o.TotalBalanceLL = o.BalanceLL + o.SubaccountsBalanceLL_ ,
            o.TotalBalanceEuro = o.BalanceEuro + o.SubaccountsBalanceEuro_;

    UPDATE Company.t_Account
      SET BalanceF = Currencys.f_Format(CurrencyID, Balance) ,
          TotalBalance = Balance + SubaccountsBalance ,
          TotalBalanceF = Currencys.f_Format(CurrencyID, Balance + SubaccountsBalance) ,
          TotalBalanceD = BalanceD + SubaccountsBalanceD ,
          TotalBalanceLL = BalanceLL + SubaccountsBalanceLL ,
    TotalBalanceEuro = BalanceEuro + SubaccountsBalanceEuro,
		  LastDateTransactionDetail = Transactions.f_TransactionDetailGetLastDateByAccount(ID)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_Account.ID );

  END;

  BEGIN --Fix AccountLevel3

    MERGE Company.t_AccountLevel3 AS t
    USING @AccountLevel3 AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.BalanceD += s.BalanceD ,
                  t.BalanceLL += s.BalanceLL ,
                  t.BalanceEuro += s.BalanceEuro;

  END;

  BEGIN --For delete

    INSERT INTO Alls.t_FireStoreRowsForDelete
        ( DocumentID ,
          HasImage ,
          TableName
        )
      SELECT s.ID ,
          0 ,
          'account'
        FROM Deleted AS s
      EXCEPT
      SELECT s.ID ,
          0 ,
          'account'
        FROM Inserted AS s;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, Account, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaCompany, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

END;

