/****** Object:  Trigger [Employees].[tr_Bonus]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Employees].[tr_Bonus] ON [Employees].[t_Bonus]
  AFTER INSERT, UPDATE, DELETE
AS
BEGIN

  BEGIN --Declare

    DECLARE @Employee TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        BonusAvailable FLOAT NOT NULL
      );

    DECLARE @BonusType TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        BonusTotalD FLOAT NOT NULL ,
        BonusTotalLL FLOAT NOT NULL ,
        BonusTotalEuro FLOAT NOT NULL ,
        BonusC BIGINT NOT NULL
      );

  END;

  BEGIN --Set info

    INSERT INTO @Employee
        ( ID ,
          BonusAvailable
        )
      SELECT o.EmployeeID ,
          COALESCE(SUM(o.BonusAvailable), 0)
        FROM ( SELECT s.EmployeeID ,
                  CASE s2.TypeIs
                    WHEN 0 THEN s.ValueIsD
                    WHEN 1 THEN s.ValueIsLL
                    ELSE s.ValueIsEuro
                  END AS BonusAvailable
                FROM Inserted AS s
                LEFT JOIN Employees.t_Employee AS s1 ON s1.ID = s.EmployeeID
                LEFT JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.FirstSalaryCurrencyID
                WHERE s.StatusIs = 0
               UNION ALL
               SELECT s.EmployeeID ,
                  0 - CASE s2.TypeIs
                        WHEN 0 THEN s.ValueIsD
                        WHEN 1 THEN s.ValueIsLL
                        ELSE s.ValueIsEuro
                      END AS BonusAvailable
                FROM Deleted AS s
                LEFT JOIN Employees.t_Employee AS s1 ON s1.ID = s.EmployeeID
                LEFT JOIN Currencys.t_Currency AS s2 ON s2.ID = s1.FirstSalaryCurrencyID
                WHERE s.StatusIs = 0
             ) AS o
        GROUP BY o.EmployeeID;

    INSERT INTO @BonusType
        ( ID ,
          BonusTotalD ,
          BonusTotalLL ,
          BonusTotalEuro ,
          BonusC
        )
      SELECT o.TypeID ,
          COALESCE(SUM(o.BonusTotalD), 0) ,
          COALESCE(SUM(o.BonusTotalLL), 0) ,
          COALESCE(SUM(o.BonusTotalEuro), 0) ,
          COALESCE(SUM(o.BonusC), 0)
        FROM ( SELECT s.TypeID ,
                  s.ValueIsD AS BonusTotalD ,
                  s.ValueIsLL AS BonusTotalLL ,
                  s.ValueIsEuro AS BonusTotalEuro ,
                  1 AS BonusC
                FROM Inserted AS s
               UNION ALL
               SELECT s.TypeID ,
                  0 - s.ValueIsD AS BonusTotalD ,
                  0 - s.ValueIsLL AS BonusTotalLL ,
                  0 - s.ValueIsEuro AS BonusTotalEuro ,
                  -1 AS BonusC
                FROM Deleted AS s
             ) AS o
        GROUP BY o.TypeID;

  END;

  BEGIN --Fix t_Employee

    MERGE Employees.t_Employee AS t
    USING @Employee AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.BonusAvailable += s.BonusAvailable ,
                  t.BonusAvailableF = Currencys.f_Format(t.FirstSalaryCurrencyID, t.BonusAvailable + s.BonusAvailable);

  END;

  BEGIN --Fix t_BonusType

    MERGE Employees.t_BonusType AS t
    USING @BonusType AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.BonusTotalD += s.BonusTotalD ,
                  t.BonusTotalLL += s.BonusTotalLL ,
                  t.BonusTotalEuro += s.BonusTotalEuro ,
                  t.BonusC += s.BonusC;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, EmployeeBonus, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaEmployee, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

END;


GO
