/****** Object:  Trigger [Items].[tr_Item]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Items].[tr_Item] ON [Items].[t_Item]
  AFTER INSERT, UPDATE, DELETE
AS
BEGIN

  IF NOT UPDATE(RowVersionID)
  BEGIN 

    UPDATE Items.t_Item
      SET RowVersionID = [DateTimes].[f_GetRowVersionID]()
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM Inserted AS s
                      WHERE s.ID = t_Item.ID );
  
  END;
   
  IF UPDATE(QtyCurrent) --Update QtyCurrent
  BEGIN

    UPDATE Items.t_Item
      SET QtyCurrentByUnit = Items.f_GetQtyCurrentByUnit(SharedID, QtyCurrent) ,
          IsUsed = 1
      WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                      FROM Inserted AS t
                      WHERE t.ID = t_Item.ID );

  END;

  IF UPDATE(LastStockTakeDate) OR UPDATE(StockTakeEvery) --Update StockTakeEvery
  BEGIN

    UPDATE Items.t_Item
      SET StockTakeEveryARF = FORMAT(StockTakeEvery, '0') + CASE StockTakeEveryType
                                                              WHEN 2 THEN N' أيام'
                                                              WHEN 1 THEN N' شهور'
                                                              ELSE N' سنوات'
                                                            END ,
          StockTakeEveryENF = FORMAT(StockTakeEvery, '0') + CASE StockTakeEveryType
                                                              WHEN 2 THEN N' Days'
                                                              WHEN 1 THEN N' Months'
                                                              ELSE N' Years'
                                                            END ,
          StockTakeEveryNotificationDate = CASE StockTakeEveryType
                                             WHEN 2 THEN DATEADD(DAY, StockTakeEvery, LastStockTakeDate)
                                             WHEN 1 THEN DATEADD(MONTH, StockTakeEvery, LastStockTakeDate)
                                             ELSE DATEADD(YEAR, StockTakeEvery, LastStockTakeDate)
                                           END
      WHERE EXISTS ( SELECT TOP ( 1 ) t.ID
                      FROM Inserted AS t
                      WHERE t.ID = t_Item.ID );

  END;

  BEGIN --For delete

    INSERT INTO Alls.t_FireStoreRowsForDelete
        ( DocumentID ,
          HasImage ,
          TableName
        )
      SELECT s.ID ,
          0 ,
          'item'
        FROM Deleted AS s
      EXCEPT
      SELECT s.ID ,
          0 ,
          'item'
        FROM Inserted AS s;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, Item, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

END;

