GO
CREATE TRIGGER [Items].[tr_ItemExpirationDate] ON [Items].[t_ItemExpirationDate]
  AFTER INSERT, UPDATE, DELETE
AS
BEGIN

  IF NOT UPDATE(IsSync)
  BEGIN 

    UPDATE Items.t_ItemExpirationDate
      SET IsSync = 0
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM Inserted AS s
                      WHERE s.ID = t_ItemExpirationDate.ID );

  END;
  
  BEGIN 

    DECLARE @IDs AS TABLE ( ID UNIQUEIDENTIFIER );
  
    INSERT INTO @IDs
        ( ID
        )
      SELECT DISTINCT t.ItemSharedID
        FROM Inserted AS t
        WHERE t.BatchNumber <> N''
      UNION
      SELECT DISTINCT t.ItemSharedID
        FROM Deleted AS t
        WHERE t.BatchNumber <> N'';

    UPDATE Items.t_ItemShared
      SET BatchNumbers = Items.f_ItemExpirationDateGetBatchNumbers(ID)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM @IDs AS s
                      WHERE s.ID = t_ItemShared.ID );

  END;
 
  BEGIN --For delete

    INSERT INTO Alls.t_FireStoreRowsForDelete
        ( DocumentID ,
          HasImage ,
          TableName
        )
      SELECT s.ID ,
          0 ,
          'itemExpirationDate'
        FROM Deleted AS s
      EXCEPT
      SELECT s.ID ,
          0 ,
          'itemExpirationDate'
        FROM Inserted AS s;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, ItemExpirationDate, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaItem, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

END;

