/****** Object:  Trigger [Transactions].[tr_TransactionDetail]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Transactions].[tr_TransactionDetail] ON [Transactions].[t_TransactionDetail]
  AFTER INSERT, UPDATE, DELETE
AS
BEGIN

  IF NOT UPDATE(IsSync)
  BEGIN 

    UPDATE Transactions.t_TransactionDetail
      SET IsSync = 0 ,
          IsSyncImage = IIF(TypeIs = 1, IsSyncImage, 1)
      WHERE EXISTS ( SELECT TOP ( 1 ) s.ID
                      FROM Inserted AS s
                      WHERE s.ID = t_TransactionDetail.ID );

  END;

  BEGIN --DECLARE

    DECLARE @TransactionDetailDay AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        DateOnly DATE NOT NULL ,
        BalanceD FLOAT NOT NULL ,
        BalanceLL FLOAT NOT NULL ,
        BalanceEuro FLOAT NOT NULL ,
        CreditD FLOAT NOT NULL ,
        CreditLL FLOAT NOT NULL ,
        CreditEuro FLOAT NOT NULL ,
        DebitD FLOAT NOT NULL ,
        DebitLL FLOAT NOT NULL ,
        DebitEuro FLOAT NOT NULL
      );

    DECLARE @Account AS TABLE
      (
        ID UNIQUEIDENTIFIER NOT NULL ,
        BalanceD FLOAT NOT NULL ,
        BalanceLL FLOAT NOT NULL ,
        BalanceEuro FLOAT NOT NULL
      );

  END;

  BEGIN --Set info

    INSERT @TransactionDetailDay
        ( ID ,
          DateOnly ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro ,
          CreditD ,
          CreditLL ,
          CreditEuro ,
          DebitD ,
          DebitLL ,
          DebitEuro
        )
      SELECT o.AccountID ,
          o.DateOnly ,
          ISNULL(SUM(o.BalanceD), 0) AS BalanceD ,
          ISNULL(SUM(o.BalanceLL), 0) AS BalanceLL ,
          ISNULL(SUM(o.BalanceEuro), 0) AS BalanceEuro ,
          ISNULL(SUM(o.CreditD), 0) AS CreditD ,
          ISNULL(SUM(o.CreditLL), 0) AS CreditLL ,
          ISNULL(SUM(o.CreditEuro), 0) AS CreditEuro ,
          ISNULL(SUM(o.DebitD), 0) AS DebitD ,
          ISNULL(SUM(o.DebitLL), 0) AS DebitLL ,
          ISNULL(SUM(o.DebitEuro), 0) AS DebitEuro
        FROM ( SELECT s.AccountID ,
                  Alls.f_Company_RestDate(s.DateIs) AS DateOnly ,
                  s.BalanceD ,
                  s.BalanceLL ,
                  s.BalanceEuro ,
                  s.CreditD ,
                  s.CreditLL ,
                  s.CreditEuro ,
                  s.DebitD ,
                  s.DebitLL ,
                  s.DebitEuro
                FROM Inserted AS s
               UNION ALL
               SELECT s.AccountID ,
                  Alls.f_Company_RestDate(s.DateIs) ,
                  0 - s.BalanceD ,
                  0 - s.BalanceLL ,
                  0 - s.BalanceEuro ,
                  0 - s.CreditD ,
                  0 - s.CreditLL ,
                  0 - s.CreditEuro ,
                  0 - s.DebitD ,
                  0 - s.DebitLL ,
                  0 - s.DebitEuro
                FROM Deleted AS s
             ) AS o
        GROUP BY o.DateOnly ,
          o.AccountID;

    INSERT @Account
        ( ID ,
          BalanceD ,
          BalanceLL ,
          BalanceEuro
        )
      SELECT o.ID ,
          ISNULL(SUM(o.BalanceD), 0) AS BalanceD ,
          ISNULL(SUM(o.BalanceLL), 0) AS BalanceLL ,
          ISNULL(SUM(o.BalanceEuro), 0) AS BalanceEuro
        FROM @TransactionDetailDay AS o
        GROUP BY o.ID;

  END;

  BEGIN --Fix Account Balance

    MERGE Company.t_Account AS t
    USING @Account AS s
    ON s.ID = t.ID
    WHEN MATCHED THEN
      UPDATE SET t.Balance += CASE t.CurrencyTypeIs
                                WHEN 0 THEN s.BalanceD
                                WHEN 1 THEN s.BalanceLL
                                WHEN 2 THEN s.BalanceEuro
                                ELSE 0
                              END ,
                  t.BalanceD += s.BalanceD ,
                  t.BalanceLL += s.BalanceLL ,
                  t.BalanceEuro += s.BalanceEuro;

  END;

  BEGIN --Merge Transaction Detail Day

    MERGE Transactions.t_TransactionDetailByDay AS t
    USING @TransactionDetailDay AS s
    ON s.ID = t.AccountID AND s.DateOnly = t.DateOnly
    WHEN NOT MATCHED BY TARGET THEN
      INSERT ( AccountID ,
               Account ,
               DateOnly ,
               BalanceD ,
               BalanceLL ,
               BalanceEuro ,
               CreditD ,
               CreditLL ,
               CreditEuro ,
               DebitD ,
               DebitLL ,
               DebitEuro
             )
      VALUES ( s.ID ,
               Company.f_AccountGetName(s.ID) ,
               s.DateOnly ,
               s.BalanceD ,
               s.BalanceLL ,
               s.BalanceEuro ,
               s.CreditD ,
               s.CreditLL ,
               s.CreditEuro ,
               s.DebitD ,
               s.DebitLL ,
               s.DebitEuro
             )
    WHEN MATCHED THEN
      UPDATE SET t.BalanceD += s.BalanceD ,
                  t.BalanceLL += s.BalanceLL ,
                  t.BalanceEuro += s.BalanceEuro ,
                  t.CreditD += s.CreditD ,
                  t.CreditLL += s.CreditLL ,
                  t.CreditEuro += s.CreditEuro ,
                  t.DebitD += s.DebitD ,
                  t.DebitLL += s.DebitLL ,
                  t.DebitEuro += s.DebitEuro;

  END;
  
  BEGIN --For delete

    INSERT INTO Alls.t_FireStoreRowsForDelete
        ( DocumentID ,
          HasImage ,
          TableName
        )
      SELECT s.ID ,
          1 ,
          'transactionDetail'
        FROM Deleted AS s
      EXCEPT
      SELECT s.ID ,
          1 ,
          'transactionDetail'
        FROM Inserted AS s;

  END;

  BEGIN --Live

    UPDATE Alls.t_LiveVersion
      SET VersionLive = STUFF(VersionLive, TransactionIs, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000')) ,
          SchemasIs = STUFF(SchemasIs, SchemaTransaction, 3, FORMAT(DATEPART(MILLISECOND, GETDATE()), '000'));

  END;

END;


GO
/****** Object:  Trigger [Transactions].[tr_TransactionDetailByDay]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Transactions].[tr_TransactionDetailByDay]
ON [Transactions].[t_TransactionDetailByDay]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN

    BEGIN --DECLARE

        DECLARE @TransactionDetailMonth AS TABLE
        (
            ID UNIQUEIDENTIFIER NOT NULL,
            Name NVARCHAR(MAX) NOT NULL,
            DateOnly DATE NOT NULL,
            BalanceD FLOAT NOT NULL,
            BalanceLL FLOAT NOT NULL,
            BalanceEuro FLOAT NOT NULL,
            CreditD FLOAT NOT NULL,
            CreditLL FLOAT NOT NULL,
            CreditEuro FLOAT NOT NULL,
            DebitD FLOAT NOT NULL,
            DebitLL FLOAT NOT NULL,
            DebitEuro FLOAT NOT NULL
        );

    END;

    BEGIN --Set info

        INSERT @TransactionDetailMonth
        (
            ID,
            Name,
            DateOnly,
            BalanceD,
            BalanceLL,
            BalanceEuro,
            CreditD,
            CreditLL,
            CreditEuro,
            DebitD,
            DebitLL,
            DebitEuro
        )
        SELECT o.AccountID,
               MIN(o.Account) AS Account,
               o.DateOnly,
               ISNULL(SUM(o.BalanceD), 0) AS BalanceD,
               ISNULL(SUM(o.BalanceLL), 0) AS BalanceLL,
               ISNULL(SUM(o.BalanceEuro), 0) AS BalanceEuro,
               ISNULL(SUM(o.CreditD), 0) AS CreditD,
               ISNULL(SUM(o.CreditLL), 0) AS CreditLL,
               ISNULL(SUM(o.CreditEuro), 0) AS CreditEuro,
               ISNULL(SUM(o.DebitD), 0) AS DebitD,
               ISNULL(SUM(o.DebitLL), 0) AS DebitLL,
               ISNULL(SUM(o.DebitEuro), 0) AS DebitEuro
        FROM
        (
            SELECT s.AccountID,
                   s.Account,
                   DATEFROMPARTS(YEAR(s.DateOnly), MONTH(s.DateOnly), 1) AS DateOnly,
                   s.BalanceD,
                   s.BalanceLL,
                   s.BalanceEuro,
                   s.CreditD,
                   s.CreditLL,
                   s.CreditEuro,
                   s.DebitD,
                   s.DebitLL,
                   s.DebitEuro
            FROM Inserted AS s
            UNION ALL
            SELECT s.AccountID,
                   s.Account,
                   DATEFROMPARTS(YEAR(s.DateOnly), MONTH(s.DateOnly), 1) AS DateOnly,
                   0 - s.BalanceD,
                   0 - s.BalanceLL,
                   0 - s.BalanceEuro,
                   0 - s.CreditD,
                   0 - s.CreditLL,
                   0 - s.CreditEuro,
                   0 - s.DebitD,
                   0 - s.DebitLL,
                   0 - s.DebitEuro
            FROM Deleted AS s
        ) AS o
        GROUP BY o.DateOnly,
                 o.AccountID;

    END;

    BEGIN --Merge Transaction Detail Month

        MERGE Transactions.t_TransactionDetailByMonth AS t
        USING @TransactionDetailMonth AS s
        ON s.ID = t.AccountID
           AND s.DateOnly = t.DateOnly
        WHEN NOT MATCHED BY TARGET THEN
            INSERT
            (
                AccountID,
                Account,
                DateOnly,
                BalanceD,
                BalanceLL,
                BalanceEuro,
                CreditD,
                CreditLL,
                CreditEuro,
                DebitD,
                DebitLL,
                DebitEuro
            )
            VALUES
            (s.ID, s.Name, s.DateOnly, s.BalanceD, s.BalanceLL, s.BalanceEuro, s.CreditD, s.CreditLL, s.CreditEuro,
             s.DebitD, s.DebitLL, s.DebitEuro)
        WHEN MATCHED THEN
            UPDATE SET t.BalanceD += s.BalanceD,
                       t.BalanceLL += s.BalanceLL,
                       t.BalanceEuro += s.BalanceEuro,
                       t.CreditD += s.CreditD,
                       t.CreditLL += s.CreditLL,
                       t.CreditEuro += s.CreditEuro,
                       t.DebitD += s.DebitD,
                       t.DebitLL += s.DebitLL,
                       t.DebitEuro += s.DebitEuro;

    END;

END;


GO
