/****** Object:  Trigger [Users].[tr_UserLoginHistory]    Script Date: 28-03-2026 08:37:02 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE TRIGGER [Users].[tr_UserLoginHistory]
ON [Users].[t_UserLoginHistory]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN

    BEGIN --DECLARE

        DECLARE @User AS TABLE
        (
            ID UNIQUEIDENTIFIER NOT NULL,
            HoursIs FLOAT NOT NULL,
            LoginC BIGINT NOT NULL
        );

    END;

    BEGIN --Set info

        INSERT INTO @User
        (
            ID,
            HoursIs,
            LoginC
        )
        SELECT o.UserID,
               ISNULL(SUM(o.HoursIs), 0),
               ISNULL(SUM(o.LoginC), 0)
        FROM
        (
            SELECT s.UserID,
                   s.HoursIs,
                   1 AS LoginC
            FROM Inserted AS s
            UNION ALL
            SELECT s.UserID,
                   0 - s.HoursIs,
                   -1 AS LoginC
            FROM Deleted AS s
        ) AS o
        GROUP BY o.UserID;

    END;

    BEGIN --Fix user

        MERGE Users.t_User AS t
        USING @User AS s
        ON s.ID = t.ID
        WHEN MATCHED THEN
            UPDATE SET t.HoursIs += s.HoursIs,
                       t.WorkTime = DateTimes.f_DateTimeDiff(
                                                                GETDATE(),
                                                                GETDATE() + ((t.HoursIs + s.HoursIs) / 24),
                                                                N'y',
                                                                1,
                                                                '',
                                                                ''
                                                            ),
                       t.LoginC += s.LoginC;

    END;

END;

GO
